  ui_story_1011_10110202_3_dialog_content = "*Rugido*",
  ui_story_1011_10110202_4_dialog_content = "Quantos deles existem!?",
  ui_story_1011_10110202_5_dialog_content = "Eles simplesmente não param de chegar!",
  ui_story_1011_10110202_6_dialog_content = "Estamos de costas para a parede!",
  ui_story_1011_10110202_7_dialog_content = "A estação de controle está logo atrás de nós!",
  ui_story_1011_10110202_8_dialog_content = "*Rugido*",
  ui_story_1011_10110202_9_dialog_content = "Vice, atenção!",
  ui_story_1011_10110202_10_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1011_10110202_11_dialog_content = "Oh não! Eles acertaram os controles!",
  ui_story_1011_10110202_12_dialog_content = "O quê?!",
  ui_story_1011_10110202_13_dialog_content = "Estamos indo para baixo!",
  ui_story_1011_10110202_14_dialog_content = "Ah! Ajuda!",
  ui_story_1011_10110202_15_dialog_content = "Segure-se em algo!",
  ui_story_1011_10110202_16_dialog_content = "PlayerName, pegue minha mão!",
  ui_story_1011_10110202_17_dialog_content = "(Eclipsiano) O Colosso caiu...",
  ui_story_1011_10110202_18_dialog_content = "(Eclipsiano) Bando de idiotas!",
  ui_story_1011_10110202_19_dialog_content = "(Eclipsian) W-Desculpe!",
  ui_story_1011_10110202_20_dialog_content = "(Eclipsiano) Eu ordenei que você capturasse o Colosso e o Caelestita.",
  ui_story_1011_10110202_21_dialog_content = "(Eclipsiano) Eu não pedi para você matá-los!",
  ui_story_1011_10110202_22_dialog_content = "(Eclipsiano) Vamos tentar salvar a situação!",
  ui_story_1011_10110202_23_dialog_content = "(Eclipsiano) Alcance-os, localize-os. Não os deixe escapar.",
  ui_story_1011_10110202_24_dialog_content = "(Eclipsiano) Esta é sua última chance.",
  ui_story_1011_10110202_25_dialog_content = "(Eclipsiano) Entendido.",
  ui_story_1011_10110202_26_dialog_content = "(Eclipsiano) Você é muito estúpido para estar no comando.",
  ui_story_1011_10110202_27_dialog_content = "(Eclipsiano) Forsakin. Não interfira.",
  ui_story_1011_10110202_28_dialog_content = "(Eclipsiano) Eu te disse. Este é o meu experimento. Você fica fora disso.",
  ui_story_1011_10110202_29_dialog_content = "(Eclipsiano) Você e seus Eclipsites idiotas se tornaram elementos instáveis no experimento.",
  ui_story_1011_10110202_30_dialog_content = "(Eclipsiano) Fica só na periferia e espera.",
  ui_story_1011_10110202_31_dialog_content = "(Eclipsiano) Acontece que há uma unidade Illuminana à frente obstruindo nosso caminho. Segure-os.",
  ui_story_1011_10110202_32_dialog_content = "(Eclipsiano) Não me cause problemas.",
  ui_story_1011_10110202_33_dialog_content = "(Eclipsiano) Forsakin...",
  ui_story_1011_10110202_34_dialog_content = "(Eclipsiano) Um dia você vai pagar por sua arrogância.",
  ui_story_1011_10110202_40X1_dialog_content = "Soldados! Reinhardt ordenou que nossa 2ª Legião ficasse parada...",
  ui_story_1011_10110202_40X2_dialog_content = "Vamos mostrar a ela como podemos ser inexpugnáveis!",
  ui_story_1011_10110202_40X3_dialog_content = "Você! Inspecione todas as fortificações, repare qualquer dano e fortaleça as principais estruturas.",
  ui_story_1011_10110202_40X4_dialog_content = "Não importa quantos Eclipses venham, manteremos as coisas sob controle!",
  ui_story_1011_10110202_40X5_dialog_content = "Sim!",
  ui_story_1011_10110202_40X6_dialog_content = "E você! Alivie os guardas de plantão.",
  ui_story_1011_10110202_40X7_dialog_content = "Certifique-se de que todas as sentinelas sejam trocadas a cada 6 horas para que estejam bem descansadas.",
  ui_story_1011_10110202_40X8_dialog_content = "Mantenha os olhos abertos para qualquer movimento Eclipsite!",
  ui_story_1011_10110202_40X9_dialog_content = "Sim!",
  ui_story_1011_10110202_40X10_dialog_content = "<color=#e8d9bb>Cabuum!</color>",
  ui_story_1011_10110202_40X11_dialog_content = "O que é que foi isso?!",
  ui_story_1011_10110202_40X12_dialog_content = "Isso é... Soroz?",
  ui_story_1011_10110202_40X13_dialog_content = "Por que está voando tão baixo?",
  ui_story_1011_10110202_40X14_dialog_content = "E são todos aqueles pontos pretos... Eclipsitas?!",
  ui_story_1011_10110202_40X15_dialog_content = "Que diabos! O garoto está sob ataque!",
  ui_story_1011_10110202_40X16_dialog_content = "Senhor!",
  ui_story_1011_10110202_40X17_dialog_content = "Falar!",
  ui_story_1011_10110202_40X18_dialog_content = "Nossos batedores notaram um movimento incomum do Eclipsite. Eles estão todos indo para Eraveil agora mesmo!",
  ui_story_1011_10110202_40X19_dialog_content = "Além dos Eclipsitos normais, vários de alto nível também foram vistos!",
  ui_story_1011_10110202_40X20_dialog_content = "Incluindo Forsakin e um outro Eclipsite de alto nível!",
  ui_story_1011_10110202_40X21_dialog_content = "Forsakin...",
  ui_story_1011_10110202_40X22_dialog_content = "Por que ela está indo para lá também?",
  ui_story_1011_10110202_40X23_dialog_content = "Não.",
  ui_story_1011_10110202_40X24_dialog_content = "A celestita, eclipsitas e Forsakin...",
  ui_story_1011_10110202_40X25_dialog_content = "Se todos estão indo para Eraveil, significa que algo importante está prestes a acontecer.",
  ui_story_1011_10110202_40X26_dialog_content = "Informe todos os membros da 2ª Legião para ficarem em alerta máximo.",
  ui_story_1011_10110202_40X27_dialog_content = "Atribua uma unidade de reconhecimento para ficar de olho no Eraveil.",
  ui_story_1011_10110202_40X28_dialog_content = "Sim!",
  ui_story_1011_10110202_40X29_dialog_content = "E...",
  ui_story_1011_10110202_40X30_dialog_content = "<color=#e8d9bb>Ta... ta... ta...</color>",
  ui_story_1011_10110202_40X31_dialog_content = "Isso é... Eraveil?",
  ui_story_1011_10110202_40X32_dialog_content = "Nossos homens estão lutando contra Eclipsites?",
  ui_story_1011_10110202_40X33_dialog_content = "S-Sim!",
  ui_story_1011_10110202_40X34_dialog_content = "Recebemos a notícia de que nossas unidades se depararam com uma empresa de Eclipsites sob Forsakincomando de!",
  ui_story_1011_10110202_40X35_dialog_content = "Nossas tropas estão enfrentando o inimigo, mas Forsakin decolou para Eraveil sozinho!",
  ui_story_1011_10110202_40X36_dialog_content = "O que quer que os Eclipsites estejam planejando, não pode ser bom.",
  ui_story_1011_10110202_40X37_dialog_content = "Eu disse que algo ruim ia acontecer em breve.",
  ui_story_1011_10110202_40X38_dialog_content = "Eles não podem ter o seu caminho!",
  ui_story_1011_10110202_40X39_dialog_content = "Informe todas as unidades para ficarem firmes. Sem recuar!",
  ui_story_1011_10110202_40X40_dialog_content = "Eu vou capturar aquele traidor Forsakin com minhas próprias mãos!",
  ui_story_1011_10110202_40X41_dialog_content = "Mas senhor, fomos ordenados a...",
  ui_story_1011_10110202_40X42_dialog_content = "Ouço! Na batalha, todas as oportunidades devem ser aproveitadas.",
  ui_story_1011_10110202_40X43_dialog_content = "Forsakin definitivamente não é bom e temos que detê-la enquanto podemos.",
  ui_story_1011_10110202_40X44_dialog_content = "Se esperarmos até que ela faça o que planejou, será tarde demais.",
  ui_story_1011_10110202_40X45_dialog_content = "Se minha decisão causar problemas, diga Reinhardt e o Comitê...",
  ui_story_1011_10110202_40X46_dialog_content = "Eles podem segurar o Comandante da 2ª Legião Barton responsável por todas as consequências!",
  ui_story_1011_10110202_40X47_dialog_content = "Entendeu?",
  ui_story_1011_10110202_40X48_dialog_content = "Sim, senhor!",
  ui_story_1011_10110202_40X49_dialog_content = "Gostaria de saber como o Navigator está aguentando...",
  ui_story_1011_10110202_40X50_dialog_content = "Ele é como um gato com nove vidas. Ele vai ficar bem.",
  ui_story_1011_10110202_40X51_dialog_content = "Vamos dar-lhe uma mão.",
  ui_story_1011_10110401_1_dialog_content = "<anim type=Shake><size=50>Ahhhhhh!</size></anim>",
  ui_story_1011_10110401_2_dialog_content = "VAMOS BAIXAR!!!",
  ui_story_1011_10110401_3_dialog_content = "PlayerName, mantenha nossa direção firme!",
  ui_story_1011_10110401_4_dialog_content = "Há espaço sob a torre. Faça Soroz deslizar!",
  ui_story_1011_10110401_7X1_dialog_content = "Eu não posso fazer isso!",
  ui_story_1011_10110401_7X2_dialog_content = "O controlador está danificado. Perdi o controle de Soroz!",
  ui_story_1011_10110401_7X3_dialog_content = "Segure-se em algo então!",
  ui_story_1011_10110401_7X4_dialog_content = "E então...",
  ui_story_1011_10110401_7X5_dialog_content = "Vamos rezar para não batermos na torre!",
  ui_story_1011_10110401_7X6_dialog_content = "Ahhh!",
  ui_story_1011_10110401_8_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1011_10110401_9_dialog_content = "<color=#e8d9bb>*estrondo*</color>",
  ui_story_1011_10110401_10_dialog_content = "*tosse* Há tanta poeira...",
  ui_story_1011_10110401_11_dialog_content = "Estamos... ainda vivos?",
  ui_story_1011_10110401_12_dialog_content = "Umm... Esse parece ser o caso.",
  ui_story_1011_10110401_13_dialog_content = "Desembarcamos com sucesso.",
  ui_story_1011_10110401_14_dialog_content = "Estão todos bem? Alguém se machucou?",
  ui_story_1011_10110401_15_dialog_content = "Estou bem, além de sentir náuseas.",
  ui_story_1011_10110401_16_dialog_content = "Eu... eu também estou bem.",
  ui_story_1011_10110401_17_dialog_content = "*Tosse* Estamos na parte inferior da torre?",
  ui_story_1011_10110401_18_dialog_content = "Sim, entramos no espaço logo abaixo da Torre Branca.",
  ui_story_1011_10110401_19_dialog_content = "<color=#e8d9bb>\"Destino alcançado: Base de Manutenção Colosso Tarmac.\"</color>",
  ui_story_1011_10110401_20_dialog_content = "<color=#e8d9bb>\"Estabelecendo conexão com sistemas de controle de base.\"</color>",
  ui_story_1011_10110401_21_option_content = "Alcatrão?",
  ui_story_1011_10110401_22_dialog_content = "Todo este espaço... é um asfalto?",
  ui_story_1011_10110401_23_dialog_content = "Não é à toa que é tão grande... Poderia caber mais alguns Colossos.",
  ui_story_1011_10110401_24_dialog_content = "Não pense que conta como um acidente se pousarmos na pista...",
  ui_story_1011_10110401_25_dialog_content = "Graah! Rugido!",
  ui_story_1011_10110401_26_dialog_content = "...",
  ui_story_1011_10110401_27_dialog_content = "...",
  ui_story_1011_10110401_28_dialog_content = "Mais Eclipses!",
  ui_story_1011_10110401_29_dialog_content = "Grrrr!",
  ui_story_1011_10110401_30_dialog_content = "Pega isso!",
  ui_story_1011_10110401_31_dialog_content = "Deve haver muito mais a bordo!",
  ui_story_1011_10110401_32_dialog_content = "Não podemos deixá-los causar mais danos!",
  ui_story_1011_10110402_1_dialog_content = "Ufa... Este deve ser o último.",
  ui_story_1011_10110402_2_dialog_content = "Não parece haver mais nada à vista.",
  ui_story_1011_10110402_3_dialog_content = "Não sinto mais inimigos. Devemos ser capazes de respirar.",
  ui_story_1011_10110402_4_dialog_content = "Deixe-me verificar o Soroz primeiro.",
  ui_story_1011_10110402_5_dialog_content = "<color=#e8d9bb>\"Tentando se conectar ao sistema de controle da Base de Manutenção Colossus.\"</color>",
  ui_story_1011_10110402_6_dialog_content = "<color=#e8d9bb>\"Erro: Tarmac desconectado do sistema de controle central.\"</color>",
  ui_story_1011_10110402_7_dialog_content = "<color=#e8d9bb>\"Por favor, vá para a Sala de Controle Central e reconecte manualmente.\"</color>",
  ui_story_1011_10110402_8_dialog_content = "A Sala de Controle Central...?",
  ui_story_1011_10110402_9_dialog_content = "Isso deveria estar na Torre Branca?",
  ui_story_1011_10110402_10_dialog_content = "Temos algo no banco de dados sobre isso?",
  ui_story_1011_10110402_11_dialog_content = "Acho que não...",
  ui_story_1011_10110402_12_dialog_content = "Não me importo de passar por todos os arquivos, mas isso vai levar tempo.",
  ui_story_1011_10110402_13_dialog_content = "Passar pelos arquivos sozinho não vai ajudar. Precisamos fazer uma investigação prática.",
  ui_story_1011_10110402_14_dialog_content = "Bom ponto. Vamos descer lá e dar uma olhada.",
  ui_story_1011_10110402_15_dialog_content = "Vamos então.",
  ui_story_1011_10110402_16_dialog_content = "Está tão vazio aqui...",
  ui_story_1011_10110402_17_dialog_content = "Tudo o que dizemos ecoa de volta...",
  ui_story_1011_10110402_18_dialog_content = "De acordo com os dados, este já foi um habitat dos celestitas.",
  ui_story_1011_10110402_19_dialog_content = "Mas você mal consegue distinguir os quartos agora. Se alguém viveu aqui uma vez, já faz muito tempo.",
  ui_story_1011_10110402_20_dialog_content = "Eles devem ter se mudado há muito tempo...",
  ui_story_1011_10110402_21_dialog_content = "Mesmo que deixassem algo para trás, com o tempo tudo se perderia.",
  ui_story_1011_10110402_22_dialog_content = "Embora eu nunca tenha imaginado que os celestitas moravam no asfalto.",
  ui_story_1011_10110402_23_dialog_content = "Eles simplesmente desembarcaram seus Colossos aqui e viveram com eles?",
  ui_story_1011_10110402_24_dialog_content = "Soa estranhamente semelhante ao acampamento.",
  ui_story_1011_10110402_25_dialog_content = "Talvez seja por isso que você não vê nenhuma habitação aqui, porque os celestitas moravam em seus colossos.",
  ui_story_1011_10110402_26_dialog_content = "Quando eles saíram, eles levaram seus Colossos com eles.",
  ui_story_1011_10110402_27_dialog_content = "Se eles desembarcaram seus Colossos aqui, então eles sabiam que isso era uma pista.",
  ui_story_1011_10110402_28_dialog_content = "E se for esse o caso, eles saberiam sobre o <color=#FFB400>Base de Manutenção Colosso</color>.",
  ui_story_1011_10110402_29_dialog_content = "Então, por que não há registro disso?",
  ui_story_1011_10110402_30_dialog_content = "De fato, é estranho. Vamos ver se podemos descobrir mais sobre isso mais tarde.",
  ui_story_1011_10110402_31_dialog_content = "Uhum.",
  ui_story_1011_10110402_32_dialog_content = "Uma base que não está em nenhum registro e é desconhecida do mundo... É como se simplesmente tivesse surgido do nada.",
  ui_story_1011_10110402_33_dialog_content = "Não vejo nada que se assemelhe a uma estação de manutenção ou sala para os Colossos nas proximidades.",
  ui_story_1011_10110402_34_dialog_content = "Na verdade, não há nada além de espessas camadas de poeira.",
  ui_story_1011_10110402_35_dialog_content = "Também não parece que a Sala de Controle Central esteja aqui.",
  ui_story_1011_10110402_36_dialog_content = "A menos que seja lá em cima?",
  ui_story_1011_10110402_37_dialog_content = "PlayerName, o que exatamente está na torre?",
  ui_story_1011_10110402_38_dialog_content = "Deixa eu pensar...",
  ui_story_1011_10110402_39_dialog_content = "De acordo com o banco de dados de Soroz, os celestitas habitaram esta torre por um período de tempo.",
  ui_story_1011_10110402_40_dialog_content = "Mas eles eventualmente se mudaram e se estabeleceram em seu habitat moderno.",
  ui_story_1011_10110402_41_dialog_content = "Celestitas do passado vasculharam este lugar em detalhes, incluindo os andares mais altos da torre.",
  ui_story_1011_10110402_42_dialog_content = "No entanto, eles não encontraram nada além das mesmas pedras brancas estampadas que as vistas de fora.",
  ui_story_1011_10110402_43_dialog_content = "Não há nada lá em cima...?",
  ui_story_1011_10110402_44_dialog_content = "Estamos nas coordenadas erradas?",
  ui_story_1011_10110402_45_dialog_content = "Eu não acho. Mesmo que a estrutura tenha se movido devido aos movimentos das placas tectônicas, ela ainda não deveria ter se afastado de sua posição original.",
  ui_story_1011_10110402_46_dialog_content = "Se não houver nada na torre...",
  ui_story_1011_10110402_47_dialog_content = "E embaixo dela?",
  ui_story_1011_10110402_48_dialog_content = "Abaixo disso?",
  ui_story_1011_10110402_49_dialog_content = "Você quer dizer, um espaço subterrâneo escondido, assim como Gannon?",
  ui_story_1011_10110402_50_dialog_content = "Isso é realmente um bom ponto!",
  ui_story_1011_10110402_51_dialog_content = "Mas este lugar está cheio de pedras da torre desmoronada. Como vamos encontrar a entrada sem um mapa?",
  ui_story_1011_10110402_52_dialog_content = "A menos que você esteja planejando cavar por todo este lugar?",
  ui_story_1011_10110402_53_dialog_content = "Provavelmente levaria anos para encontrar uma passagem.",
  ui_story_1011_10110402_54_dialog_content = "Uma passagem... a Cidade Baixa... uma maneira de encontrar...",
  ui_story_1011_10110402_55_dialog_content = "Saquei!",
  ui_story_1011_10110402_56_dialog_content = "Há detectores de metal entre os suprimentos que o Grande Marechal nos forneceu.",
  ui_story_1011_10110402_57_dialog_content = "Se houver de fato uma base subterrânea, é mais provável que parte da estrutura seja feita de metal.",
  ui_story_1011_10110402_58_dialog_content = "Podemos usar o detector de metais para procurar possíveis locais de escavação.",
  ui_story_1011_10110402_59_dialog_content = "Pensar que o Grande Marechal previu isso...",
  ui_story_1011_10110402_60_dialog_content = "Ela é realmente tão visionária quanto os rumores dizem.",
  ui_story_1011_10110402_60X1_dialog_content = "Poderia trazer os outros suprimentos e os explosivos também.",
  ui_story_1011_10110402_60X2_dialog_content = "Eles podem ser úteis.",
  ui_story_1011_10110402_61_dialog_content = "Acho que é isso que faremos então.",
  ui_story_1011_10110402_62_dialog_content = "Espero que tenhamos sorte e encontremos uma entrada imediatamente.",
  ui_story_1011_10110402_63_dialog_content = "<color=#e8d9bb>Em algum lugar fora da Torre Branca</color>",
  ui_story_1011_10110402_64_dialog_content = "Como se suspeitava, esta torre não é tão simples quanto parece.",
  ui_story_1011_10110402_65_dialog_content = "Se não fosse a chave do Caelestita ser um guia, seus segredos nunca seriam descobertos.",
  ui_story_1011_10110402_66_dialog_content = "É hora de tornar esses segredos parte dos meus dados de experimentação.",
  ui_story_1011_10110402_66X1_dialog_content = "Você não vai escapar!",
  ui_story_1011_10110402_66X2_dialog_content = "Graaahh—",
  ui_story_1011_10110402_66X3_dialog_content = "Comandante da Legião, limpamos a maioria dos Eclipsitos na área!",
  ui_story_1011_10110402_66X4_dialog_content = "Bom trabalho! Use este tempo para reconstruir nossa defesa.",
  ui_story_1011_10110402_66X5_dialog_content = "Sim!",
  ui_story_1011_10110402_66X6_dialog_content = "Esses Eclipses são todos inúteis.",
  ui_story_1011_10110402_66X7_dialog_content = "Onde é Forsakin?",
  ui_story_1011_10110402_66X8_dialog_content = "Ela já chegou ao Eraveil?",
  ui_story_1011_10110402_66X9_dialog_content = "São todos esses Eclipsites e Forsakin aqui para PlayerName?",
  ui_story_1011_10110402_66X10_dialog_content = "Que festa animada.",
  ui_story_1011_10110402_66X11_dialog_content = "Mal posso esperar para ver o que mais ela tem na manga.",
  ui_story_1011_10110501_1_dialog_content = "Uma caixa vazia inútil...",
  ui_story_1011_10110501_2_dialog_content = "Jogar fora.",
  ui_story_1011_10110501_3_dialog_content = "Livros pouco legíveis...",
  ui_story_1011_10110501_4_dialog_content = "Jogar fora.",
  ui_story_1011_10110501_5_dialog_content = "Uma lata de alguma coisa...",
  ui_story_1011_10110501_6_dialog_content = "Jogar fora.",
  ui_story_1011_10110501_7_dialog_content = "Espere! Não desperdice!",
  ui_story_1011_10110501_8_dialog_content = "Mas... expirou por Deus sabe quanto tempo.",
  ui_story_1011_10110501_9_dialog_content = "É melhor simplesmente jogá-lo fora.",
  ui_story_1011_10110501_10_dialog_content = "Suspirar...",
  ui_story_1011_10110501_11_dialog_content = "Só acabamos com um monte de lixo inútil depois de horas de trabalho.",
  ui_story_1011_10110501_12_dialog_content = "Vamos verificar cada canto novamente para ter certeza de que não perdemos nada.",
  ui_story_1011_10110501_13_dialog_content = "Tudo bem. Vou fazer outra varredura.",
  ui_story_1011_10110501_14_dialog_content = "Acho que ainda não verificamos esta área.",
  ui_story_1011_10110501_15_dialog_content = "Essas pedras brancas estão espalhadas por aqui... Parece que saíram da Torre Branca?",
  ui_story_1011_10110501_16_dialog_content = "Eu me pergunto se alguma coisa está dentro deles...",
  ui_story_1011_10110501_17_dialog_content = "Eu deveria verificar com o detector de metais.",
  ui_story_1011_10110501_18_dialog_content = "<color=#e8d9bb>Bip Bip...!</color>",
  ui_story_1011_10110501_19_dialog_content = "É... reagindo!",
  ui_story_1011_10110501_20_dialog_content = "Para algo dentro da pedra?",
  ui_story_1011_10110501_21_option_content = "Bata na pedra",
  ui_story_1011_10110501_22_dialog_content = "<color=#e8d9bb>TOC Toc...!</color>",
  ui_story_1011_10110501_23_dialog_content = "Não soa nada oco. Pode ser nas costas?",
  ui_story_1011_10110501_24_dialog_content = "Está tão escuro aqui, e há sombras em todos os lugares...",
  ui_story_1011_10110501_25_dialog_content = "Parece haver algo nas sombras, mas não consigo distinguir o que é.",
  ui_story_1011_10110501_26_dialog_content = "Vamos chegar um pouco mais perto. Espere. É aquele...",
  ui_story_1011_10110501_27_dialog_content = "Um Eclipsite com uma lata na cabeça, tentando se disfarçar de detritos?!",
  ui_story_1011_10110501_28_dialog_content = "Roooor!",
  ui_story_1011_10110501_29_dialog_content = "Ehhh!?",
  ui_story_1011_10110501_30_dialog_content = "PlayerName！",
  ui_story_1011_10110501_31_dialog_content = "Graah! Rugido!",
  ui_story_1011_10110501_32_dialog_content = "E-Isso foi perto!",
  ui_story_1011_10110501_33_dialog_content = "Como eles chegaram aqui!?",
  ui_story_1011_10110501_34_dialog_content = "É um espaço vazio com muitas sombras para se esconder.",
  ui_story_1011_10110501_35_dialog_content = "Os Eclipsitas devem ter entrado sorrateiramente quando procurávamos a entrada.",
  ui_story_1011_10110501_36_dialog_content = "Roooor!",
  ui_story_1011_10110501_37_dialog_content = "Droga. Estamos cercados!",
  ui_story_1011_10110501_38_dialog_content = "Mais Eclipses estão chegando pela entrada!",
  ui_story_1011_10110501_39_dialog_content = "Temos que encontrar uma maneira de romper!",
  ui_story_1011_10110501_40_dialog_content = "Não!",
  ui_story_1011_10110501_41_dialog_content = "Isso significaria que estamos entregando a Torre Branca e Soroz a eles!",
  ui_story_1011_10110501_42_dialog_content = "Temos que impedir que os Eclipsitas entrem se quisermos proteger este lugar.",
  ui_story_1011_10110501_43_dialog_content = "Mas é como uma caverna sem nada que remotamente se assemelhe a uma porta!",
  ui_story_1011_10110501_44_dialog_content = "Sem porta...",
  ui_story_1011_10110501_45_dialog_content = "Então vamos fazer um!",
  ui_story_1011_10110501_46_dialog_content = "Use os explosivos!",
  ui_story_1011_10110501_47_dialog_content = "Você quer explodir a entrada?!",
  ui_story_1011_10110501_48_dialog_content = "Exatamente!",
  ui_story_1011_10110501_49_dialog_content = "Não importa se a entrada desmorona. Ainda podemos sair dos níveis superiores da torre.",
  ui_story_1011_10110501_49X1_dialog_content = "Na pior das hipóteses, podemos encontrar outra saída nas ruínas subterrâneas, se necessário.",
  ui_story_1011_10110501_50_dialog_content = "Mas temos que parar os Eclipsites aqui e agora para proteger Soroz e as ruínas!",
  ui_story_1011_10110501_51_dialog_content = "Vice e eu vou cobrir para você. PlayerName, aproveite esta oportunidade e detone os explosivos na entrada!",
  ui_story_1011_10110501_52_dialog_content = "Vamos!",
  ui_story_1011_10110501_53_dialog_content = "Estou contando com vocês dois!",
  ui_story_1011_10110502_1_dialog_content = "Graah! Rugido!",
  ui_story_1011_10110502_2_dialog_content = "Fora do caminho!",
  ui_story_1011_10110502_3_dialog_content = "Roooor!",
  ui_story_1011_10110502_4_dialog_content = "Mais e mais eclipsitos estão inundando... Nesse ritmo, não vou nem chegar perto da entrada...",
  ui_story_1011_10110502_5_dialog_content = "Muito menos detonar os explosivos!",
  ui_story_1011_10110502_6_dialog_content = "Eu tenho que tentar quebrá-los primeiro.",
  ui_story_1011_10110502_7_dialog_content = "Não podemos ficar presos aqui!",
  ui_story_1011_10110502_9_dialog_content = "Tenha um gostinho disso!",
  ui_story_1011_10110502_10_dialog_content = "A entrada, olha! Isso não é—",
  ui_story_1011_10110502_11_dialog_content = "Barton?!",
  ui_story_1011_10110502_12_dialog_content = "O que você está fazendo aqui?!",
  ui_story_1011_10110502_12X1_dialog_content = "Ah! Eu sabia que vocês ficariam bem.",
  ui_story_1011_10110502_12X2_dialog_content = "Eu vi um monte de Eclipsites vindo por aqui, então vim conferir as coisas.",
  ui_story_1011_10110502_13_dialog_content = "Eu estava apenas de passagem e usando os Eclipsites para minha rotina diária de exercícios!",
  ui_story_1011_10110502_14_dialog_content = "Faça o que você precisa fazer. Eu tenho você coberto.",
  ui_story_1011_10110502_15_dialog_content = "Comandante Barton está retendo os Eclipses! PlayerName, esta é a sua chance!",
  ui_story_1011_10110502_16_dialog_content = "Barton, Voltam! Vamos selar a entrada!",
  ui_story_1011_10110502_17_dialog_content = "Selo? Como você vai fazer isso?",
  ui_story_1011_10110502_18_dialog_content = "Nós vamos explodi-lo!",
  ui_story_1011_10110502_19_dialog_content = "Explodir?!",
  ui_story_1011_10110502_20_dialog_content = "Eu não acho que você tinha isso em você, garoto!",
  ui_story_1011_10110502_21_dialog_content = "Tenho coisas tratadas aqui. Vá explodir as coisas para o conteúdo do seu coração!",
  ui_story_1011_10110502_22_dialog_content = "Os Eclipsites estão recuando. PlayerName, vai!",
  ui_story_1011_10110502_23_dialog_content = "Sim!",
  ui_story_1011_10110502_24_dialog_content = "Os explosivos estão em posição. Vice, Carleen, Voltam!",
  ui_story_1011_10110502_25_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1011_10110502_26_dialog_content = "Conseguimos?",
  ui_story_1011_10110502_27_dialog_content = "Parece que funcionou!",
  ui_story_1011_10110502_28_dialog_content = "Mas Barton ainda está lá fora...",
  ui_story_1011_10110502_29_dialog_content = "Mindlink!",
  ui_story_1011_10110502_30_dialog_content = "Barton, você está bem? Você está machucado?",
  ui_story_1011_10110502_31_dialog_content = "Sem problemas. Eu nunca estive melhor!",
  ui_story_1011_10110502_32_dialog_content = "Como vocês estão?",
  ui_story_1011_10110502_33_dialog_content = "A entrada foi selada. Não se preocupe conosco!",
  ui_story_1011_10110502_34_dialog_content = "Excelente. Agora eu posso realmente me deixar ir!",
  ui_story_1011_10110502_35_dialog_content = "Ser seguro!",
  ui_story_1011_10110502_36_dialog_content = "Cabe a nós agora.",
  ui_story_1011_10110502_37_dialog_content = "Vamos nos apressar e procurar as ruínas.",
  ui_story_1011_10110502_38_dialog_content = "A entrada barricada só pode segurá-los por algum tempo.",
  ui_story_1011_10110502_39_dialog_content = "Os Eclipsites têm mão de obra suficiente para cavar ou escalar a torre e entrar por ali.",
  ui_story_1011_10110502_40_dialog_content = "Vamos nos separar.",
  ui_story_1011_10110502_41_dialog_content = "Já procuramos por toda esta área.",
  ui_story_1011_10110502_42_dialog_content = "Mesmo se olharmos de novo, tudo o que vamos encontrar é lixo aleatório.",
  ui_story_1011_10110502_43_dialog_content = "Alguém tem alguma outra ideia?",
  ui_story_1011_10110502_44_dialog_content = "Como talvez algo que apenas um celestita seria capaz de fazer?",
  ui_story_1011_10110502_45_dialog_content = "Você quer dizer minha habilidade psíquica?",
  ui_story_1011_10110502_46_dialog_content = "Sim.",
  ui_story_1011_10110502_47_dialog_content = "Você pode usar sua habilidade psíquica e ver se há alguma pista?",
  ui_story_1011_10110502_48_dialog_content = "Vou tentar.",
  ui_story_1011_10110502_49_option_content = "Mindlink!",
  ui_story_1011_10110502_50_dialog_content = "Ah!",
  ui_story_1011_10110502_51_dialog_content = "Minha cabeça!",
  ui_story_1011_10110502_52_dialog_content = "PlayerName!?",
  ui_story_1011_10110502_53_dialog_content = "Este lugar é muito estranho.",
  ui_story_1011_10110502_54_dialog_content = "Parece que algo está impedindo minha habilidade de sondar a área.",
  ui_story_1011_10110502_55_dialog_content = "Interferindo na habilidade psíquica de um celestita...",
  ui_story_1011_10110502_56_dialog_content = "O que esse lugar está tentando esconder?",
  ui_story_1011_10110502_57_dialog_content = "Mas significa que estamos no caminho certo.",
  ui_story_1011_10110502_58_dialog_content = "Exceto se o Navegador não puder usar sua habilidade psíquica, não temos pistas.",
  ui_story_1011_10110502_59_dialog_content = "... Não, ainda há um caminho.",
  ui_story_1011_10110502_60_dialog_content = "Encontrei o Echo Template para Soroz usando minha habilidade no Think Tank Module.",
  ui_story_1011_10110502_61_dialog_content = "Além disso, foram os dados do Módulo de Reparo que nos apontaram aqui.",
  ui_story_1011_10110502_62_dialog_content = "Posso tentar usar minha habilidade no Módulo de Reparo e ver se há uma maneira de corrigir nosso problema.",
  ui_story_1011_10110502_62X1_dialog_content = "Minha habilidade funcionou bem antes com Barton.",
  ui_story_1011_10110502_62X2_dialog_content = "Eu estou supondo que se eu tiver um alvo concreto, deve funcionar.",
  ui_story_1011_10110502_63_dialog_content = "Isso soa plausível.",
  ui_story_1011_10110502_64_dialog_content = "Mesmo assim...",
  ui_story_1011_10110502_65_dialog_content = "Se você começar a se sentir desconfortável, terá que cortar o link. Você ouve, PlayerName?",
  ui_story_1011_10110502_66_dialog_content = "Não exagere.",
  ui_story_1011_10110502_67_dialog_content = "Eu entendi. Não se preocupe.",
  ui_story_1011_10110502_68_option_content = "Controle forçado!",
  ui_story_1011_10110502_69_dialog_content = "...",
  ui_story_1011_10110502_70_dialog_content = "Diga-me como chegar à Sala de Controle Central!",
  ui_story_1011_10110502_71_dialog_content = "\"Comando aceito. Examinando...\"",
  ui_story_1011_10110502_72_dialog_content = "\"Sistema de controle de acesso offline.\"",
  ui_story_1011_10110502_73_dialog_content = "\"Despachando Firefly para serviço de manutenção.\"",
  ui_story_1011_10110502_74_dialog_content = "Um vaga-lume... de Soroz?",
  ui_story_1011_10110502_75_dialog_content = "\"Bip!\"",
  ui_story_1011_10110502_76_dialog_content = "<color=#e8d9bb>Clique</color>",
  ui_story_1011_10110502_77_dialog_content = "\"Unidade de energia reserva de controle de acesso conectada. Ativando sistema de controle de acesso.\"",
  ui_story_1011_10110502_78_dialog_content = "\"Por favor, diga a palavra de segurança para verificação de identidade.\"",
  ui_story_1011_10110502_79_dialog_content = "O quê?",
  ui_story_1011_10110502_80_dialog_content = "De onde vem essa voz?",
  ui_story_1011_10110502_81_dialog_content = "\"Este é o Sistema de Controle de Acesso da Base de Manutenção Colossus.\"",
  ui_story_1011_10110502_82_dialog_content = "\"Aviso: o sistema de controle de acesso foi desconectado do sistema de controle central por ■■■■■■■ dias.\"",
  ui_story_1011_10110502_83_dialog_content = "\"Por favor, restabeleça a conexão ou use a senha de redefinição.\"",
  ui_story_1011_10110502_84_dialog_content = "Isso soa como algo que pode abrir uma porta?",
  ui_story_1011_10110502_85_dialog_content = "E é controlado por voz também!",
  ui_story_1011_10110502_86_dialog_content = "\"Senha inválida. 3 tentativas restantes.\"",
  ui_story_1011_10110502_87_dialog_content = "Eh? Não! Não fui eu que tentei...",
  ui_story_1011_10110502_88_dialog_content = "\"Senha inválida. 2 tentativas restantes.\"",
  ui_story_1011_10110502_89_dialog_content = "Ei, espere!",
  ui_story_1011_10110502_90_dialog_content = "\"Senha inválida. 1 tentativa restante.\"",
  ui_story_1011_10110502_91_dialog_content = "\"Cuidado: Outros erros bloquearão o sistema de controle de acesso.\"",
  ui_story_1011_10110502_92_dialog_content = "Pare de falar!",
  ui_story_1011_10110502_93_dialog_content = "Milímetros! Mmm!",
  ui_story_1011_10110502_94_dialog_content = "Podemos redefinir a senha?!",
  ui_story_1011_10110502_95_dialog_content = "\"Aviso: incompatibilidade de tipo de gene. Comando inválido.\"",
  ui_story_1011_10110502_96_dialog_content = "...",
  ui_story_1011_10110502_97_dialog_content = "(Você quer que eu tente?)",
  ui_story_1011_10110502_98_dialog_content = "Esta é a última chance. PlayerName, Vá em frente.",
  ui_story_1011_10110502_99_dialog_content = "Certifique-se de pensar antes de falar.",
  ui_story_1011_10110502_100_dialog_content = "(Tudo bem...)",
  ui_story_1011_10110502_101_dialog_content = "...",
  ui_story_1011_10110502_102_option_content = "Controle de acesso, redefinir senha.",
  ui_story_1011_10110502_103_dialog_content = "\"Tipo de gene autenticado. Redefinindo a senha.\"",
  ui_story_1011_10110502_104_dialog_content = "\"Por favor, responda as 3 perguntas a seguir para verificação de identidade.\"",
  ui_story_1011_10110502_105_dialog_content = "Há perguntas de segurança?",
  ui_story_1011_10110502_106_dialog_content = "Temos que seguir o fluxo.",
  ui_story_1011_10110502_107_dialog_content = "Não se preocupe, PlayerName. Eu ajudo.",
  ui_story_1011_10110502_108_dialog_content = "Estou colocando minha reputação de estudante nota dez em jogo!",
  ui_story_1011_10110502_109_dialog_content = "\"Você é um Eclipse?\"",
  ui_story_1011_10110502_110_dialog_content = "Eh...?",
  ui_story_1011_10110502_111_dialog_content = "Como eu poderia ser um Eclipse!?",
  ui_story_1011_10110502_112_dialog_content = "\"Resposta inválida.\"",
  ui_story_1011_10110502_113_dialog_content = "\"Repita: você é um Eclipse?\"",
  ui_story_1011_10110502_114_dialog_content = "Hum, não, eu não sou.",
  ui_story_1011_10110502_115_dialog_content = "\"Resposta aceita.\"",
  ui_story_1011_10110502_116_dialog_content = "\"Você é um auroriano?\"",
  ui_story_1011_10110502_117_dialog_content = "Eu não sou um auroriano.",
  ui_story_1011_10110502_118_dialog_content = "\"Resposta aceita.\"",
  ui_story_1011_10110502_119_dialog_content = "\"Por favor, selecione um Firefly das seguintes opções.\"",
  ui_story_1011_10110502_120_dialog_content = "Essas são... projeções?",
  ui_story_1011_10110502_121_dialog_content = "Parece tão real!",
  ui_story_1011_10110502_122_option_content = "Toque na projeção Firefly",
  ui_story_1011_10110502_123_dialog_content = "\"Resposta aceita.\"",
  ui_story_1011_10110502_124_dialog_content = "\"Identidade verificada: celestita.\"",
  ui_story_1011_10110502_125_dialog_content = "\"Por favor, insira uma nova senha.\"",
  ui_story_1011_10110502_126_dialog_content = "Umm... Abra gergelim!",
  ui_story_1011_10110502_127_dialog_content = "\"Redefinição de senha. Nova senha: Umm... Abra gergelim.\"",
  ui_story_1011_10110502_128_dialog_content = "Não inclua inflexões na senha, caramba!",
  ui_story_1011_10110502_129_dialog_content = "\"Abrindo portas.\"",
  ui_story_1011_10110502_130_dialog_content = "<color=#e8d9bb>Cabuum!</color>",
  ui_story_1011_10110502_131_dialog_content = "Nossa!",
  ui_story_1011_10110502_132_dialog_content = "<color=#e8d9bb>*Rumindo*</color>",
  ui_story_1011_10110502_133_dialog_content = "A parede está se abrindo! E... espere, isso é uma porta?",
  ui_story_1011_10110502_134_dialog_content = "É enorme!",
  ui_story_1011_10110502_135_dialog_content = "Mas, o que diabos foi isso?!",
  ui_story_1011_10110502_136_dialog_content = "Esse processo de verificação de identidade foi ridículo!",
  ui_story_1011_10110502_137_dialog_content = "Qualquer ser inteligente seria capaz de mentir!",
  ui_story_1011_10110502_137X1_dialog_content = "Eu não acho que as respostas eram o que estava sendo verificado.",
  ui_story_1011_10110502_137X2_dialog_content = "O que, então?",
  ui_story_1011_10110502_137X3_dialog_content = "Como você pode verificar se alguém é um celestita através de uma série de perguntas simples?",
  ui_story_1011_10110502_137X4_dialog_content = "Anteriormente, quando fiz uma pergunta, ele respondeu: \"Incompatibilidade de tipo de gene\".",
  ui_story_1011_10110502_137X5_dialog_content = "Acho que já havia verificado sua identidade como celestita por outros meios.",
  ui_story_1011_10110502_137X6_dialog_content = "As perguntas eram apenas para fazer você confirmar: \"Sou um celestita\".",
  ui_story_1011_10110502_137X7_dialog_content = "A confirmação foi mais importante do que todas as outras provas?",
  ui_story_1011_10110502_137X8_dialog_content = "Acho que é assim que as máquinas pensam.",
  ui_story_1011_10110502_137X9_dialog_content = "Então você está dizendo... essas ruínas possuem tecnologia que pode conduzir testes genéticos remotos?",
  ui_story_1011_10110502_137X10_dialog_content = "A transparência total me deixa um pouco desconfortável.",
  ui_story_1011_10110502_137X11_dialog_content = "Esqueça isso. O que importa é o resultado.",
  ui_story_1011_10110502_137X12_dialog_content = "A porta está aberta. Não precisamos nos debruçar sobre como isso aconteceu.",
  ui_story_1011_10110502_138_dialog_content = "Sinceramente, devemos agradecer ao seu design simplista por tornar nossas vidas mais fáceis.",
  ui_story_1011_10110502_139_dialog_content = "A porta que leva para baixo deve ser a entrada para as ruínas subterrâneas.",
  ui_story_1011_10110502_140_dialog_content = "Mas se uma porta como esta sempre esteve aqui, como os celestitas sentiram falta dela todos esses anos?",
  ui_story_1011_10110502_141_dialog_content = "Não sei... Tudo aqui está envolto em mistério.",
  ui_story_1011_10110502_142_dialog_content = "De qualquer forma, a passagem aqui significa que ainda existem regiões abaixo para explorarmos.",
  ui_story_1011_10110502_143_dialog_content = "Nossa prioridade agora é encontrar uma maneira de consertar Soroz, passar pelos Eclipsitos e descobrir uma maneira de sair daqui.",
  ui_story_1011_10110502_144_dialog_content = "Você tem razão. Não temos um momento a perder.",
  ui_story_1011_10110502_145_dialog_content = "Vamos lá, então!",
  ui_story_1011_10110601_1_dialog_content = "Graah!",
  ui_story_1011_10110601_2_dialog_content = "Não consegue nem montar uma emboscada adequada? Você é apenas bucha de canhão!",
  ui_story_1011_10110601_3_dialog_content = "Quem te enviou? Um Eclipse de tamanho maior? Ou aquele maluco de cientista?",
  ui_story_1011_10110601_4_dialog_content = "Certo, quase esqueci que vocês não podem nem falar.",
  ui_story_1011_10110601_5_dialog_content = "Gaar...",
  ui_story_1011_10110601_6_dialog_content = "Hahaha! Nada além de lixo!",
  ui_story_1011_10110601_7_dialog_content = "Matar gente como você nem é uma conquista. Isso é tudo que o Eclipse tem?",
  ui_story_1011_10110601_8_dialog_content = "...",
  ui_story_1011_10110601_10_dialog_content = "Quem está aí?",
  ui_story_1011_10110601_11_dialog_content = "...",
  ui_story_1011_10110601_12_dialog_content = "Realmente é você. <color=#FFB400>negador</color>, traidor da Illumina.",
  ui_story_1011_10110601_13_dialog_content = "... Na verdade não. Você foi exilado da Illumina.",
  ui_story_1011_10110601_14_dialog_content = "Tsc.",
  ui_story_1011_10110601_15_dialog_content = "Eu tenho que dizer, se você queria sacrificar suas tropas para criar uma distração, você não deveria ter sido pego.",
  ui_story_1011_10110601_16_dialog_content = "(Tropas...? Esses são os servos de Figerald?)",
  ui_story_1011_10110601_17_dialog_content = "(Sempre supérfluo, aquele...)",
  ui_story_1011_10110601_18_dialog_content = "Não tenho interesse em lutar com você, e não enviei esses Eclipsites.",
  ui_story_1011_10110601_19_dialog_content = "Uma luta tola só iria enterrar ainda mais os segredos da Torre Branca.",
  ui_story_1011_10110601_20_dialog_content = "(A Torre Branca? Então ela planeja seguir PlayerName...?)",
  ui_story_1011_10110601_21_dialog_content = "Ah? Não há tempo para bate-papo ocioso em um campo de batalha.",
  ui_story_1011_10110601_22_dialog_content = "Você quer entrar, vá em frente. Se você puder passar por mim.",
  ui_story_1011_10110601_23_dialog_content = "Acabei de falar com você. Pegue isso, Forsakin!",
  ui_story_1011_10110601_24_dialog_content = "Prove o poder de Ironjaw!",
  ui_story_1011_10110601_25_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_1011_10110601_26_dialog_content = "Quão problemático. O que esse lugar tem a ver com você?",
  ui_story_1011_10110601_27_dialog_content = "Eu odeio complicações.",
  ui_story_1011_10110601_28_dialog_content = "Se me livrar de você pode me poupar mais problemas... Eu vou morder.",
  ui_story_1011_10110601_29_dialog_content = "Hahahaha! Isto é o que eu gosto de ouvir!",
  ui_story_1011_10110601_30_dialog_content = "Vamos matar algum tempo juntos!",
  ui_story_1011_10110601_31_dialog_content = "<color=#e8d9bb>Passagem de Entrada, Torre Primária</color>",
  ui_story_1011_10110601_32_dialog_content = "<color=#e8d9bb>*Passos ecoando*</color>",
  ui_story_1011_10110601_33_dialog_content = "(Que corredor longo e estreito. Parece durar para sempre...)",
  ui_story_1011_10110601_34_dialog_content = "(Eu mal posso ver a luz da entrada agora.)",
  ui_story_1011_10110601_35_dialog_content = "<color=#e8d9bb>Clam, clam...</color>",
  ui_story_1011_10110601_36_dialog_content = "Vice, atenção!",
  ui_story_1011_10110601_37_dialog_content = "Quê?!",
  ui_story_1011_10110601_38_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_1011_10110601_39_dialog_content = "Tome cuidado!",
  ui_story_1011_10110601_40_dialog_content = "*Tosse*",
  ui_story_1011_10110601_41_dialog_content = "Está tão empoeirado aqui!",
  ui_story_1011_10110601_42_dialog_content = "<color=#e8d9bb><size=35>aqui... aqui... aqui...</size></color>",
  ui_story_1011_10110601_43_dialog_content = "Hum?",
  ui_story_1011_10110601_44_dialog_content = "Silêncio. Vamos mantê-lo para baixo.",
  ui_story_1011_10110601_45_dialog_content = "Parece que ainda temos um longo caminho a percorrer.",
  ui_story_1011_10110601_46_dialog_content = "Se nossas vozes atraíssem alguma coisa para nós neste corredor estreito, nem teríamos onde nos esconder.",
  ui_story_1011_10110601_47_dialog_content = "A propósito, PlayerName...",
  ui_story_1011_10110601_48_dialog_content = "Você realmente não sabia que este lugar existia antes disso?",
  ui_story_1011_10110601_49_dialog_content = "Sim... Nem mesmo Soroz mencionou este lugar antes.",
  ui_story_1011_10110601_50_dialog_content = "Não é como se Soroz fosse onisciente de qualquer maneira.",
  ui_story_1011_10110601_51_dialog_content = "...",
  ui_story_1011_10110601_52_dialog_content = "(Soro...)",
  ui_story_1011_10110601_53_dialog_content = "Já que fomos conduzidos até aqui pelo plugin Echo Template...",
  ui_story_1011_10110601_54_dialog_content = "Tudo o que precisamos é encontrar esse \"Sistema de Controle Central\", certo?",
  ui_story_1011_10110601_55_dialog_content = "Nós definitivamente encontraremos o que precisamos para consertar Soroz lá, PlayerName.",
  ui_story_1011_10110601_56_dialog_content = "Obrigada, Vice.",
  ui_story_1011_10110601_57_dialog_content = "O quê?",
  ui_story_1011_10110601_58_dialog_content = "O que foi?",
  ui_story_1011_10110601_59_dialog_content = "O material sob nossos pés não parece ser seixos regulares ou pedras brancas comuns.",
  ui_story_1011_10110601_60_dialog_content = "Hmmm... Deixe-me ver.",
  ui_story_1011_10110601_61_dialog_content = "A cor e a textura são bastante originais. Pelo que aprendi na Academia...",
  ui_story_1011_10110601_62_dialog_content = "Este material de pedra é exclusivo do antigo Astra...",
  ui_story_1011_10110601_63_dialog_content = "(Huh...?)",
  ui_story_1011_10110601_64_dialog_content = "T-Isso significa que estes são...",
  ui_story_1011_10110601_65_dialog_content = "<color=#FFB400>Manchas de Colosso</color>?",
  ui_story_1011_10110601_66_dialog_content = "?!",
  ui_story_1011_10110601_67_dialog_content = "(O caminho a seguir está coberto com essas pedras trituradas...)",
  ui_story_1011_10110601_68_dialog_content = "(Poderiam ser todos... Colossus <color=#FFB400>restos</color>?)",
  ui_story_1011_10110601_69_dialog_content = "O que significa que estamos realmente dentro da Base de Manutenção Colossus!",
  ui_story_1011_10110601_70_dialog_content = "Olhando para a quantidade, os Colossos devem ter sido veículos comuns na época, assim como as lendas e os registros históricos afirmam!",
  ui_story_1011_10110601_71_dialog_content = "Ei, PlayerName. É o fim da passagem?",
  ui_story_1011_10110601_72_dialog_content = "Hum... PlayerName. Você está bem?",
  ui_story_1011_10110601_73_dialog_content = "...",
  ui_story_1011_10110601_74_option_content = "Estou sentindo um pouco de pavor.",
  ui_story_1011_10110601_75_dialog_content = "Eu... eu nunca vi nada assim...",
  ui_story_1011_10110601_76_dialog_content = "Soroz para mim é... família, um amigo, um mentor...",
  ui_story_1011_10110601_77_dialog_content = "Já fomos a muitos lugares e sobrevivemos a tantos perigos...",
  ui_story_1011_10110601_78_dialog_content = "Mas nunca pensei que poderia acabar assim um dia.",
  ui_story_1011_10110601_79_option_content = "Estou me sentindo um pouco emocionada.",
  ui_story_1011_10110601_80_dialog_content = "Colossos são poucos em número no atual Astra.",
  ui_story_1011_10110601_81_dialog_content = "O pensamento deste enorme cemitério de Colossos deixado para trás por meus ancestrais...",
  ui_story_1011_10110601_82_dialog_content = "Deitado aqui embaixo de mim e Soroz em um Eraveil que está desocupado há 17 anos...",
  ui_story_1011_10110601_83_dialog_content = "Sinto uma estranha sensação de pertencimento.",
  ui_story_1011_10110601_84_dialog_content = "Entendi.",
  ui_story_1011_10110601_85_dialog_content = "Então vamos seguir em frente.",
  ui_story_1011_10110601_86_dialog_content = "Vamos ver de onde vêm todos esses restos de Colossos.",
  ui_story_1011_10110601_87_dialog_content = "Finalmente, em algum lugar mais aberto.",
  ui_story_1011_10110601_88_dialog_content = "Eu esperava que esta área fosse mais escura, mas na verdade é brilhante o suficiente.",
  ui_story_1011_10110601_89_dialog_content = "São apenas as sombras nebulosas do Colosso obstruindo nossa visão.",
  ui_story_1011_10110601_90_dialog_content = "Embora não saibamos a fonte dessa luz, pelo menos isso prova que não estamos em um espaço completamente fechado.",
  ui_story_1011_10110601_91_dialog_content = "Olha esses Colossos todos alinhados em ordem...",
  ui_story_1011_10110601_92_dialog_content = "Eles poderiam estar muito bem preservados se este lugar não tivesse desmoronado...",
  ui_story_1011_10110601_93_dialog_content = "PlayerName, você deve experimentar sua habilidade psíquica.",
  ui_story_1011_10110601_94_dialog_content = "Se houver algum Colossi ainda em funcionamento, você poderá estabelecer uma conexão.",
  ui_story_1011_10110601_95_dialog_content = "Bom ponto. Então-",
  ui_story_1011_10110601_96_option_content = "Controle forçado!",
  ui_story_1011_10110601_97_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10110601_98_dialog_content = "Não. Nenhuma resposta.",
  ui_story_1011_10110601_99_dialog_content = "(O que estou pensando? Encontrar um ser com consciência dentro de uma ruína como esta é impossível...)",
  ui_story_1011_10110601_100_dialog_content = "A-Pelo menos vimos vestígios dos antigos Colossos!",
  ui_story_1011_10110601_101_dialog_content = "Em seguida, vamos verificar seguir essas portas e olhar por todas elas.",
  ui_story_1011_10110601_102_dialog_content = "Vamos, PlayerName.",
  ui_story_1011_10110601_103_dialog_content = "Certo. Então vamos...",
  ui_story_1011_10110601_104_option_content = "Verifique os arredores",
  ui_story_1011_10110601_105_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_1011_10110601_106_dialog_content = "Hã?!",
  ui_story_1011_10110601_107_dialog_content = "Minha mão dói... Não está nem se mexendo!",
  ui_story_1011_10110601_108_dialog_content = "A julgar pelos danos causados aos Colossos, duvido que esses quartos estejam intactos.",
  ui_story_1011_10110601_109_dialog_content = "Rochas caídas fecharam essas portas. Parece que para a frente é o nosso único caminho.",
  ui_story_1011_10110601_110_option_content = "Siga em frente",
  ui_story_1011_10110601_111_dialog_content = "Tudo bem! À frente, parece haver escadas que levam a um nível mais baixo!",
  ui_story_1011_10110601_112_dialog_content = "Deve ser seguro andar... Certo? Quero dizer, se eles ainda existirem depois de todos esses anos...",
  ui_story_1011_10110601_113_dialog_content = "Havia tantos Colossos estacionados na entrada.",
  ui_story_1011_10110601_114_dialog_content = "Isso implica que o espaço abaixo deve estar totalmente equipado para ter atendido todos os Colossos.",
  ui_story_1011_10110601_115_dialog_content = "Vamos continuar, PlayerName.",
  ui_story_1011_10110601_116_dialog_content = "<color=#e8d9bb>*Passos ecoando*</color>",
  ui_story_1011_10110601_117_dialog_content = "(A escada está tão mal iluminada. Se ao menos houvesse um vaga-lume aqui...)",
  ui_story_1011_10110601_118_dialog_content = "(Eu me pergunto que tipo de tecnologia está enterrada lá embaixo, e se pode ser usada em Soroz...)",
  ui_story_1011_10110601_119_dialog_content = "(Finalmente chegamos ao fim. Mal posso esperar para conferir⁠—)",
  ui_story_1011_10110601_120_dialog_content = "Eh...?",
  ui_story_1011_10110601_121_dialog_content = "C-como isso pode...",
  ui_story_1011_10110601_122_dialog_content = "É espaçoso e aberto, mas não há nenhum equipamento grande à vista...",
  ui_story_1011_10110601_123_dialog_content = "Estas ruínas subterrâneas são muito maiores do que eu pensava que seriam.",
  ui_story_1011_10110601_124_dialog_content = "Mas para que servia esse nível?",
  ui_story_1011_10110601_125_dialog_content = "Mesas empoeiradas, prateleiras de pedra cheias de coisas que não são mais identificáveis e colchões aleatórios...",
  ui_story_1011_10110601_126_dialog_content = "Talvez isso fosse um depósito?",
  ui_story_1011_10110601_127_dialog_content = "Aff... Hahaha! Agora que você disse isso, acho que tenho uma ideia.",
  ui_story_1011_10110601_128_dialog_content = "Imagino que este lugar costumava ser o<color=#FFB400>aposentos</color> dos antigos celestitas.",
  ui_story_1011_10110601_129_dialog_content = "Amenidades básicas semelhantes podem ser encontradas em áreas residenciais de Undercities de Illumina.",
  ui_story_1011_10110601_130_dialog_content = "Embora a maioria dos objetos aqui estejam em pedaços, você ainda pode vê-los...",
  ui_story_1011_10110601_131_dialog_content = "Mesas de jantar, bancadas de trabalho, despensas de alimentos, prateleiras, colchões...",
  ui_story_1011_10110601_132_dialog_content = "Isso não é detritos aleatórios, Carleen.",
  ui_story_1011_10110601_133_dialog_content = "Eu já sei!",
  ui_story_1011_10110601_134_dialog_content = "Hum?",
  ui_story_1011_10110601_135_dialog_content = "Vice, olhar. Tem alguma coisa nesse copo?",
  ui_story_1011_10110601_136_dialog_content = "Hum? Onde?",
  ui_story_1011_10110601_137_dialog_content = "Parecem-me manchas normais!",
  ui_story_1011_10110601_138_dialog_content = "Não. Refiro-me ao fundo do copo. PlayerName, venha conferir.",
  ui_story_1011_10110601_139_dialog_content = "Huh... Parece algum tipo de símbolo.",
  ui_story_1011_10110601_140_dialog_content = "É verdade!",
  ui_story_1011_10110601_141_dialog_content = "Este símbolo poderia estar relacionado aos celestitas...?",
  ui_story_1011_10110601_142_dialog_content = "Eu não acho. Olhe para todas as coisas espalhadas.",
  ui_story_1011_10110601_143_dialog_content = "Este copo é o único com a marca.",
  ui_story_1011_10110601_144_dialog_content = "Verdadeiro. Se é realmente um símbolo que representa os celestitas, deveria estar em tudo.",
  ui_story_1011_10110601_145_dialog_content = "Então o que é? Eu realmente não consigo entender...",
  ui_story_1011_10110601_146_dialog_content = "Acho que lembra... as iniciais de um nome, mas...",
  ui_story_1011_10110601_147_dialog_content = "Não, está muito desgastado para ler.",
  ui_story_1011_10110601_148_dialog_content = "Então não vamos perder tempo com isso.",
  ui_story_1011_10110601_149_dialog_content = "Hmm...",
  ui_story_1011_10110601_150_dialog_content = "(Apesar de PlayerNamepalavras, não posso simplesmente esquecer...)",
  ui_story_1011_10110601_151_dialog_content = "(O destino deve ter nos trazido ao nome do indivíduo que viveu aqui.)",
  ui_story_1011_10110601_152_dialog_content = "(Vou ficar de olho em qualquer coisa relacionada a isso.)",
  ui_story_1011_10110601_153_dialog_content = "Hum? O que é isso na mesa?",
  ui_story_1011_10110601_154_dialog_content = "Incrível! Seu...",
  ui_story_1011_10110601_155_dialog_content = "Conchas de nautilus?",
  ui_story_1011_10110601_156_dialog_content = "Não um, mas um monte deles.",
  ui_story_1011_10110601_157_dialog_content = "Hum... Então PlayerName, são... Itens de uso diário da Caelestite?",
  ui_story_1011_10110601_158_dialog_content = "Eh? Você... encontrou isso agora mesmo?",
  ui_story_1011_10110601_159_dialog_content = "De jeito nenhum eu saberia para que servem quando eu nem sei para que servem.",
  ui_story_1011_10110601_160_dialog_content = "Náutilos? Não são aquelas criaturas do mar?",
  ui_story_1011_10110601_161_dialog_content = "Será que... Eraveil costumava ser um oceano? Ou talvez os antigos celestitas os tivessem como alimento?",
  ui_story_1011_10110601_162_dialog_content = "Ambos soam ridículos!",
  ui_story_1011_10110601_163_dialog_content = "Bem, essas conchas de nautilus são diferentes das que conhecemos...",
  ui_story_1011_10110601_164_dialog_content = "Eles são pequenos e suaves, leves e, de alguma forma, ainda estão em perfeitas condições depois de todos esses anos.",
  ui_story_1011_10110601_165_dialog_content = "Eles devem ser projetados para ser uma espécie de armazenamento portátil.",
  ui_story_1011_10110601_166_dialog_content = "Também... AAAAAH!",
  ui_story_1011_10110601_167_dialog_content = "Tem algo dentro!",
  ui_story_1011_10110601_168_dialog_content = "Quê?!",
  ui_story_1011_10110601_169_dialog_content = "Você está bem? Saiu alguma coisa?",
  ui_story_1011_10110601_170_dialog_content = "Estou bem. Chegou na minha mão, mas não sinto nada.",
  ui_story_1011_10110601_171_dialog_content = "*Onomatopeia de cheirar*",
  ui_story_1011_10110601_172_dialog_content = "Hmm... É inodoro e insípido, e muito fluido. Eu não posso dizer que tipo de líquido é.",
  ui_story_1011_10110601_173_dialog_content = "(Espere... Conchas... fluidez?)",
  ui_story_1011_10110601_174_dialog_content = "(Não me diga...)",
  ui_story_1011_10110601_175_dialog_content = "Ufa... Ainda assim, é melhor ter cuidado quando nem sabemos o que é.",
  ui_story_1011_10110601_176_dialog_content = "V-você está certo.",
  ui_story_1011_10110601_177_dialog_content = "(É melhor eu manter minha boca fechada por enquanto até ter provas.)",
  ui_story_1011_10110601_178_dialog_content = "(Mas se eu estiver certo, devo ser capaz de encontrar provas em algum lugar dessas ruínas.)",
  ui_story_1011_10110601_179_dialog_content = "(Vou colocar isso no meu bolso por enquanto...)",
  ui_story_1011_10110601_180_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_1011_10110601_181_dialog_content = "Hã?!",
  ui_story_1011_10110601_182_dialog_content = "PlayerName, Carleen, Aconteceu alguma coisa?",
  ui_story_1011_10110601_183_dialog_content = "O que? Achei que o som vinha do seu lado. Espere um minuto...",
  ui_story_1011_10110601_184_dialog_content = "... Alguma coisa não está certa!",
  ui_story_1011_10110601_185_dialog_content = "Poderia haver mais alguém aqui?",
  ui_story_1011_10110601_186_dialog_content = "Se fosse esse o caso, eles já teriam aparecido. Só estou com medo que seja—",
  ui_story_1011_10110601_187_dialog_content = "Gaar...",
  ui_story_1011_10110601_188_dialog_content = "Rugido... Rugido!!!",
  ui_story_1011_10110601_189_dialog_content = "Só podes estar a brincar comigo. Eclipses, aqui?!",
  ui_story_1011_10110601_190_dialog_content = "Você está me dizendo que eles conseguiram nos seguir?",
  ui_story_1011_10110601_191_dialog_content = "PlayerName, você está pronto para uma luta?",
  ui_story_1011_10110601_192_dialog_content = "Sempre!",
  ui_story_1011_10110702_1_dialog_content = "PlayerName, PlayerName!",
  ui_story_1011_10110702_2_dialog_content = "O-o que está acontecendo...?",
  ui_story_1011_10110702_3_dialog_content = "Acorda, PlayerName!",
  ui_story_1011_10110702_4_dialog_content = "(Hmm...)",
  ui_story_1011_10110702_5_dialog_content = "(Eu... eu não consigo respirar...)",
  ui_story_1011_10110702_6_dialog_content = "(São Vice e Carleen me ligando? Eles soam tão distantes...)",
  ui_story_1011_10110702_7_dialog_content = "(Eu...)",
  ui_story_1011_10110702_8_dialog_content = "Assunto Detectado: Forma de vida supersensorial. Identidade confirmada: celestita.)",
  ui_story_1011_10110702_9_dialog_content = "Mindlink estabelecido.",
  ui_story_1011_10110702_10_dialog_content = "Aviso: Níveis de O2 caindo no sistema respiratório do indivíduo. Sistema de ventilação da área residencial ativado.",
  ui_story_1011_10110702_11_dialog_content = "<color=#e8d9bb>Uau, uau...</color>",
  ui_story_1011_10110702_12_dialog_content = "(O-o que é esse som?)",
  ui_story_1011_10110702_13_dialog_content = "Hmm...?",
  ui_story_1011_10110702_14_dialog_content = "Oh, PlayerName!",
  ui_story_1011_10110702_15_dialog_content = "PlayerName! Você acordou!",
  ui_story_1011_10110702_16_dialog_content = "Como você está se sentindo?",
  ui_story_1011_10110702_17_dialog_content = "Eu... acho que estou bem agora.",
  ui_story_1011_10110702_18_dialog_content = "A batalha anterior exigiu muito de mim, e a longa jornada até aqui foi exaustiva...",
  ui_story_1011_10110702_19_dialog_content = "Eu não conseguia recuperar o fôlego, e então...",
  ui_story_1011_10110702_20_dialog_content = "A batalha...?",
  ui_story_1011_10110702_21_dialog_content = "Exaustivo?",
  ui_story_1011_10110702_22_dialog_content = "...",
  ui_story_1011_10110702_23_dialog_content = "(Não olhe para mim em silêncio assim!)",
  ui_story_1011_10110702_24_dialog_content = "Analisando o estado físico do sujeito...",
  ui_story_1011_10110702_25_dialog_content = "Situação: Normal. Classificação Física: A-.",
  ui_story_1011_10110702_26_dialog_content = "Hã?",
  ui_story_1011_10110702_27_dialog_content = "Q-Quem está falando?!",
  ui_story_1011_10110702_28_dialog_content = "Não está errado, mas...",
  ui_story_1011_10110702_29_dialog_content = "A diretriz primária do Neural Aux é ajudar os Caelestites de todas as maneiras possíveis.",
  ui_story_1011_10110702_30_dialog_content = "Recebido... Analisando pergunta...",
  ui_story_1011_10110702_31_dialog_content = "Resposta encontrada: A assistência é requerida por um celestita. Neural Aux está falando com o Caelestite.",
  ui_story_1011_10110702_32_dialog_content = "(Demora tanto tempo para responder a uma pergunta tão simples?!)",
  ui_story_1011_10110702_33_dialog_content = "Mas, agora que penso no passado, quando desmaiei...",
  ui_story_1011_10110702_34_dialog_content = "Aviso: Níveis de O2 caindo no sistema respiratório do indivíduo. Sistema de ventilação da área residencial ativado.",
  ui_story_1011_10110702_35_dialog_content = "Então ativou o sistema de ventilação aqui para me ajudar.",
  ui_story_1011_10110702_36_dialog_content = "Oh... Não é à toa que senti... uma brisa na minha pele.",
  ui_story_1011_10110702_36X_dialog_content = "O que é aquilo? Parece um holograma.",
  ui_story_1011_10110702_37_dialog_content = "Então esta é a antiga tecnologia Caelestita? Ele prova ser bastante confiável em tempos de emergência.",
  ui_story_1011_10110702_38_dialog_content = "Uau! Deixe-me dar uma olhada. Eu não posso acreditar que há uma IA funcionando aqui!",
  ui_story_1011_10110702_39_dialog_content = "Hmm...",
  ui_story_1011_10110702_40_dialog_content = "...",
  ui_story_1011_10110702_41_dialog_content = "Alvo detectado: forma de vida luminosa. Identidade Confirmada: Auroriano. Quantidade: 2.",
  ui_story_1011_10110702_42_dialog_content = "\"Neural Aux\"... Você é um antigo técnico Caelestita?",
  ui_story_1011_10110702_43_dialog_content = "Recebido... Analisando pergunta. Erro. A diretriz primária do Neural Aux é ajudar o Caelestite de todas as maneiras possíveis.",
  ui_story_1011_10110702_44_dialog_content = "O-o que?! Então os aurorianos não podem usar ferramentas celestitas?",
  ui_story_1011_10110702_45_dialog_content = "Recebido... Analisando pergunta. Erro. A diretriz primária do Neural Aux é ajudar o Caelestite de todas as maneiras possíveis.",
  ui_story_1011_10110702_46_dialog_content = "Oh, sheesh. Isso não foi uma pergunta!",
  ui_story_1011_10110702_47_dialog_content = "Algum auroriano já te disse que sua personalidade é uma merda?!",
  ui_story_1011_10110702_48_dialog_content = "Acalmar, Vice. Que tal eu perguntar por você?",
  ui_story_1011_10110702_49_dialog_content = "N-Neural Aux, tenho algumas perguntas—",
  ui_story_1011_10110702_50_dialog_content = "Pedido recebido. Modificando sistema... Inserindo novo nome de sistema: N-Neural Aux.",
  ui_story_1011_10110702_51_dialog_content = "Huh? Espere! Não! Pausa! Pausar entrada!",
  ui_story_1011_10110702_52_dialog_content = "Entrada pausada.",
  ui_story_1011_10110702_53_dialog_content = "(Bem, posso concluir que, mesmo que seja uma IA que sobrou dos tempos antigos ...)",
  ui_story_1011_10110702_54_dialog_content = "(Não é tão inteligente assim...)",
  ui_story_1011_10110702_55_dialog_content = "(Eu deveria dividir minhas perguntas para que ele possa me entender melhor...)",
  ui_story_1011_10110702_56_dialog_content = "Ahem... Primeira pergunta: Por favor, me fale sobre esta torre.",
  ui_story_1011_10110702_57_dialog_content = "Recebido... Analisando pergunta...",
  ui_story_1011_10110702_58_dialog_content = "Resposta encontrada: Este é o <color=#FFB400>Obelisco do Retorno</color>.",
  ui_story_1011_10110702_59_dialog_content = "(Obelisco do Retorno? Isso soa como algum tipo de estrutura de orientação de navegação... como um farol.)",
  ui_story_1011_10110702_60_dialog_content = "Retornar... O que isso significa? Soroz nos trouxe aqui... para voltar a este lugar?",
  ui_story_1011_10110702_61_dialog_content = "Desculpas. Não sei.",
  ui_story_1011_10110702_62_dialog_content = "(E-é isso? Só diz \"eu não sei\" assim?!)",
  ui_story_1011_10110702_63_dialog_content = "Multar. Segunda pergunta: Como era o interior da torre originalmente?",
  ui_story_1011_10110702_64_dialog_content = "Onde estamos na torre?",
  ui_story_1011_10110702_65_dialog_content = "Tocando a gravação introdutória do Neural Aux: A unidade Neural Aux é um assistente de IA projetado para o Obelisco do Retorno...",
  ui_story_1011_10110702_66_dialog_content = "A unidade Neural Aux fornece assistência a um Caelestite com base em seu nível de acesso e classificação.",
  ui_story_1011_10110702_67_dialog_content = "Confirmando o nível de acesso do Caelestite...",
  ui_story_1011_10110702_68_dialog_content = "Nível de acesso confirmado. Neural Aux pode fornecer a você uma planta do Obelisco do Retorno.",
  ui_story_1011_10110702_69_dialog_content = "(Isso será super útil!)",
  ui_story_1011_10110702_70_dialog_content = "Excelente! Agora nós realmente sabemos para onde estamos indo!",
  ui_story_1011_10110702_71_dialog_content = "Vamos nos apressar e encontrar o lugar para consertar Soroz.",
  ui_story_1011_10110702_72_dialog_content = "(Hmm... não vou ter muitas esperanças, mas não custa tentar...)",
  ui_story_1011_10110702_73_dialog_content = "Última pergunta: Diga-me como entrar no Sistema de Controle Central.",
  ui_story_1011_10110702_74_dialog_content = "...",
  ui_story_1011_10110702_75_dialog_content = "Desculpas. Não sei.",
  ui_story_1011_10110702_76_dialog_content = "Beeboo... Beeboo... ♪",
  ui_story_1011_10110702_77_dialog_content = "(Por que está cantarolando uma música de repente!?)",
  ui_story_1011_10110702_78_dialog_content = "Deixa para lá, PlayerName. Vamos continuar. Isso é melhor do que nada.",
  ui_story_1011_10110702_79_dialog_content = "Agora que temos um mapa do local, vamos confirmar nossa posição com o Neural Aux.",
  ui_story_1011_10110702_80_dialog_content = "Boa ideia. Deixe-me ver...",
  ui_story_1011_10110702_81_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10110702_82_dialog_content = "Eu vejo. Diferentes níveis desta torre servem a diferentes funções. Ainda estamos na região próxima ao nível da superfície.",
  ui_story_1011_10110702_83_dialog_content = "O nível em que entramos na torre era a Base de Manutenção Colossus.",
  ui_story_1011_10110702_84_dialog_content = "Como nos vimos, não sobrou muito.",
  ui_story_1011_10110702_85_dialog_content = "O nível em que estamos agora é a Área Residencial Caelestite, assim como Vice adivinhou...",
  ui_story_1011_10110702_86_dialog_content = "Já pesquisamos na íntegra.",
  ui_story_1011_10110702_87_dialog_content = "Infelizmente, há muitos quartos nesses dois níveis que estão bloqueados por detritos...",
  ui_story_1011_10110702_88_dialog_content = "O Armazenamento de Componentes Colossus, Sala de Produção de Recursos, Instalação de Descarte de Resíduos... Estão todos praticamente enterrados.",
  ui_story_1011_10110702_89_dialog_content = "Soroz...",
  ui_story_1011_10110702_90_dialog_content = "Não desista ainda. Ainda temos tantos níveis abaixo de nós para explorar.",
  ui_story_1011_10110702_91_dialog_content = "Talvez eu esteja dizendo isso muito apressadamente, mas estamos reunindo mais e mais informações à medida que avançamos, não é?",
  ui_story_1011_10110702_92_dialog_content = "Sim, não desista, PlayerName. Vamos encontrar uma maneira.",
  ui_story_1011_10110702_93_dialog_content = "Sim, vamos nos apressar e prosseguir para o próximo nível.",
  ui_story_1011_10110702_94_dialog_content = "Isso seria... o <color=#FFB400>Zona de Exílio</color>?",
  ui_story_1011_10110702_95_dialog_content = "Exilado?",
  ui_story_1011_10110702_96_dialog_content = "Não entendo... Os celestitas são uma raça pacífica. Por que eles teriam uma área dedicada para esse tipo de coisa...?",
  ui_story_1011_10110702_97_dialog_content = "Bem, faria sentido se fosse usado para conter antigos Eclipsitas.",
  ui_story_1011_10110702_98_dialog_content = "De qualquer forma, não parece um bom lugar para se estar. Vamos ter mais cuidado.",
  ui_story_1011_10110901_1_dialog_content = "<color=#e8d9bb>Obelisco do Retorno: Zona de Exílio</color>",
  ui_story_1011_10110901_2_dialog_content = "*inalar exalar*",
  ui_story_1011_10110901_3_dialog_content = "(Saber de antemão para que esse nível foi usado me deixa ainda mais nervoso...)",
  ui_story_1011_10110901_4_dialog_content = "(Se algum Eclipsite decidir sair, vou arrancá-lo de um novo!)",
  ui_story_1011_10110901_5_dialog_content = "Beeboo... Beeboo... ♪",
  ui_story_1011_10110901_6_dialog_content = "Bip bip bip... Bip bip bip... ♪",
  ui_story_1011_10110901_7_dialog_content = "\"O que se perdeu nunca mais voltará. O que resta sempre permanecerá... ♪\"",
  ui_story_1011_10110901_8_dialog_content = "É tão barulhento.",
  ui_story_1011_10110901_9_dialog_content = "PlayerName, faça com que fique baixo, especialmente aqui onde Eclipsites podem aparecer a qualquer momento.",
  ui_story_1011_10110901_10_dialog_content = "Deixa eu tentar conectar...",
  ui_story_1011_10110901_11_dialog_content = "Mindlink estabelecido.",
  ui_story_1011_10110901_12_dialog_content = "O Neural Aux tocará música aleatória quando nenhuma ameaça for detectada.",
  ui_story_1011_10110901_13_dialog_content = "Você está gostando dessa música antiga, Caelestite?",
  ui_story_1011_10110901_14_dialog_content = "Supondo que esses sons fragmentados sejam \"música\"...",
  ui_story_1011_10110901_15_dialog_content = "Todos os Caelestites têm permissão para editar a lista de reprodução de música do Neural Aux...",
  ui_story_1011_10110901_16_dialog_content = "Neural Aux também pode estudar suas preferências pessoais e fazer as modificações necessárias em seu sistema. Modificar agora?",
  ui_story_1011_10110901_17_dialog_content = "... Não, isso é bom.",
  ui_story_1011_10110901_18_dialog_content = "(Afinal, essa música é como um eco do passado.)",
  ui_story_1011_10110901_19_dialog_content = "No entanto, como o Neural Aux pode detectar se uma área é segura ou não...",
  ui_story_1011_10110901_20_dialog_content = "Podemos baixar a guarda e relaxar um pouco.",
  ui_story_1011_10110901_21_dialog_content = "Mesmo assim, este nível só me faz sentir desconfortável.",
  ui_story_1011_10110901_22_dialog_content = "Não há sinais de vida aqui...",
  ui_story_1011_10110901_23_dialog_content = "Mas olhe para a parte de trás das portas.",
  ui_story_1011_10110901_24_dialog_content = "A-São essas marcas de garras...?",
  ui_story_1011_10110901_25_dialog_content = "Observe como esses quartos estão tão bem juntos. Acho que esse lugar era...",
  ui_story_1011_10110901_26_dialog_content = "Parece semelhante à prisão de Lumopolis.",
  ui_story_1011_10110901_27_dialog_content = "...",
  ui_story_1011_10110901_28_dialog_content = "Mas por que eles se deram ao trabalho de trancar os Eclipsitas? Matá-los teria sido mais fácil.",
  ui_story_1011_10110901_29_dialog_content = "Será que os antigos celestitas não possuíam habilidades de combate?",
  ui_story_1011_10110901_30_dialog_content = "Improvável. Mesmo que não o fizessem, pelo que vimos de sua tecnologia...",
  ui_story_1011_10110901_31_dialog_content = "Eles claramente tinham a capacidade de produzir armas poderosas para combate e defesa.",
  ui_story_1011_10110901_32_dialog_content = "<color=#e8d9bb>Ding!</color>",
  ui_story_1011_10110901_33_dialog_content = "Hã?",
  ui_story_1011_10110901_34_dialog_content = "Você chutou alguma coisa?",
  ui_story_1011_10110901_35_dialog_content = "Vejamos...",
  ui_story_1011_10110901_36_dialog_content = "Hã?!",
  ui_story_1011_10110901_37_dialog_content = "Uma etiqueta de metal?!",
  ui_story_1011_10110901_38_dialog_content = "\"Nome: Tenoki. Identidade: Celestita.\"",
  ui_story_1011_10110901_39_dialog_content = "\"<color=#FFB400>Período de exílio</color>: 14 anos.\"",
  ui_story_1011_10110901_40_dialog_content = "Tem um aqui também. \"Nome: Lanti. Identidade: Celestita. Período de exílio: 12 anos.\"",
  ui_story_1011_10110901_41_dialog_content = "Essas celas mantinham Caeleistes como você, PlayerName.",
  ui_story_1011_10110901_42_dialog_content = "O que significa que este lugar é na verdade a Zona de Exílio Caelestita?!",
  ui_story_1011_10110901_43_dialog_content = "Mas... por que eles prenderiam seu próprio povo?",
  ui_story_1011_10110901_44_dialog_content = "A ideia de celestitas \"amantes da paz\" sempre foi apenas uma suposição imprecisa?!",
  ui_story_1011_10110901_45_dialog_content = "Acalmar, PlayerName. Não temos nada conclusivo no momento.",
  ui_story_1011_10110901_46_dialog_content = "Pense nisso. Se os antigos celestitas fossem um grande grupo...",
  ui_story_1011_10110901_47_dialog_content = "Haveria a necessidade de impor a ordem de uma forma ou de outra.",
  ui_story_1011_10110901_48_dialog_content = "Mesmo que isso seja verdade, os Caelestites são capazes de conseguir isso através do nosso link mental.",
  ui_story_1011_10110901_49_dialog_content = "Não faz sentido sentenciá-los a longos anos de exílio.",
  ui_story_1011_10110901_50_dialog_content = "Neural Aux, por favor me responda.",
  ui_story_1011_10110901_51_dialog_content = "Recebido... Analisando pergunta... Palavra-chave obtida. Responda-",
  ui_story_1011_10110901_52_dialog_content = "<color=#FFB400>Mestre Francisco</color> uma vez disse: \"Daquele momento em diante, deixamos de ser seus parentes.\"",
  ui_story_1011_10110901_53_dialog_content = "?!",
  ui_story_1011_10110901_54_dialog_content = "O que significa \"deixou de ser seus parentes\"?",
  ui_story_1011_10110901_55_dialog_content = "Parentes de quem?",
  ui_story_1011_10110901_56_dialog_content = "Os celestitas foram divididos por alguns <color=#FFB400>conflito interno irreconciliável</color> milhares de anos atrás?",
  ui_story_1011_10110901_57_dialog_content = "(Foi este o início de sua guerra civil?)",
  ui_story_1011_10110901_57X1_dialog_content = "Recebido... Analisando pergunta...",
  ui_story_1011_10110901_57X2_dialog_content = "Com base nos dados que temos, a maioria dos celestitas não se dava bem com o mestre Francisco.",
  ui_story_1011_10110901_57X3_dialog_content = "Ele realmente serviu na Zona de Exílio.",
  ui_story_1011_10110901_57X3X1_dialog_content = "A propósito, esta área foi usada como prisão para hereges celestitas.",
  ui_story_1011_10110901_57X3X2_dialog_content = "Mestre Francis e os pesquisadores sob seu comando foram todos exilados pelo mesmo motivo...",
  ui_story_1011_10110901_57X3X3_dialog_content = "Eles foram acusados de incitar o pensamento livre e difundir ideias progressistas.",
  ui_story_1011_10110901_57X4_dialog_content = "Todas as palavras encontradas em associação com Francisco são bastante negativas. Eles incluem o seguinte:",
  ui_story_1011_10110901_57X5_dialog_content = "Aberração, lunática, especialista em controle mental, colecionadora de cérebros...",
  ui_story_1011_10110901_57X6_dialog_content = "Certo, PlayerName, acho que podemos deixar isso parar agora...",
  ui_story_1011_10110901_57X7_dialog_content = "Parece que ele era um... pesquisador incomum?",
  ui_story_1011_10110901_57X8_dialog_content = "Mestre Francis dedicou-se aos estudos das novas tecnologias.",
  ui_story_1011_10110901_57X9_dialog_content = "Ele sempre dizia: \"A pesquisa é uma jornada árdua e cheia de obstáculos. Ser incompreendido é lugar-comum\".",
  ui_story_1011_10110901_57X10_dialog_content = "Mestre Francis também foi a mente por trás de outra grande inovação.",
  ui_story_1011_10110901_57X11_dialog_content = "Caelestite, a julgar pela identidade de seus companheiros, mudou o mundo.",
  ui_story_1011_10110901_57X12_dialog_content = "Mudou o mundo?",
  ui_story_1011_10110901_57X13_dialog_content = "Os celestitas modernos mostram uma mudança óbvia de postura e constituição em comparação com os celestitas antigos.",
  ui_story_1011_10110901_57X14_dialog_content = "Você chegou a compartilhar um inimigo comum com os aurorianos e os demi-humanos.",
  ui_story_1011_10110901_57X15_dialog_content = "Mestre Francis teria ficado satisfeito.",
  ui_story_1011_10110901_57X16_dialog_content = "Uma \"mudança de postura\"? Então... que postura tinham os antigos celestitas?",
  ui_story_1011_10110901_57X17_dialog_content = "Qual é essa grande inovação a que você se refere?",
  ui_story_1011_10110901_58_dialog_content = "Confirmando o nível de acesso do Caelestite...",
  ui_story_1011_10110901_59_dialog_content = "Nível de acesso insuficiente. Desculpe, não posso responder sua pergunta.",
  ui_story_1011_10110901_60_dialog_content = "Multar. Vou perguntar outra coisa então.",
  ui_story_1011_10110901_61_dialog_content = "Voltemos a esta afirmação...",
  ui_story_1011_10110901_61X1_dialog_content = "\"A partir desse momento, não somos mais seus parentes.\"",
  ui_story_1011_10110901_63_dialog_content = "Ele estava se referindo aos celestitas quando disse \"nós\"?",
  ui_story_1011_10110901_64_dialog_content = "Resposta: \"Nós\" somos celestitas.",
  ui_story_1011_10110901_65_dialog_content = "...",
  ui_story_1011_10110901_66_dialog_content = "Erro. Erro! Neural Aux não é um Caelestite.",
  ui_story_1011_10110901_67_dialog_content = "Tocando a gravação introdutória do Neural Aux: A unidade Neural Aux é um assistente de IA projetado para o Obelisco do Retorno...",
  ui_story_1011_10110901_68_dialog_content = "Escute-me! Ninguém aqui pensa que você é um celestita!",
  ui_story_1011_10110901_69_dialog_content = "A unidade Neural Aux fornece assistência a um Caelestite com base em seu nível de acesso e classificação.",
  ui_story_1011_10110901_70_dialog_content = "Esqueça. Já tive o suficiente...",
  ui_story_1011_10110901_71_dialog_content = "Francisco?",
  ui_story_1011_10110901_72_dialog_content = "PlayerName, você se lembra da taça que vimos no nível acima?",
  ui_story_1011_10110901_73_dialog_content = "Agora que você mencionou, a escultura embaçada no fundo do copo parece ter lido...",
  ui_story_1011_10110901_74_dialog_content = "Aquilo era... o copo de Francis...?",
  ui_story_1011_10110901_75_dialog_content = "Recebido... Analisando pergunta... Resposta encontrada: Mestre Francis adorava consumir bebidas energéticas.",
  ui_story_1011_10110901_76_dialog_content = "Ele sempre foi visto com seu copo na mão.",
  ui_story_1011_10110901_77_dialog_content = "(então acertamos...)",
  ui_story_1011_10110901_78_dialog_content = "Tocando a gravação introdutória da bebida energética: As bebidas energéticas são exclusivas do Obelisco do Retorno. Ele fornece-",
  ui_story_1011_10110901_79_dialog_content = "(Nós realmente não precisamos de informações irrelevantes como essa!)",
  ui_story_1011_10110901_80_dialog_content = "Está prontamente disponível na Área Residencial Caelestite, Sala de Produção de Recursos, Zona de Exílio...",
  ui_story_1011_10110901_81_dialog_content = "Eles podem ser adquiridos diretamente nas máquinas de venda de suprimentos nos locais mencionados.",
  ui_story_1011_10110901_82_dialog_content = "(Máquinas de venda automática?)",
  ui_story_1011_10110901_83_dialog_content = "(Meu palpite estava certo, então!)",
  ui_story_1011_10110901_84_dialog_content = "PlayerName, Carleen, me siga!",
  ui_story_1011_10110901_85_dialog_content = "<color=#e8d9bb>Obelisco do Retorno: Zona de Exílio - Máquina de Venda de Suprimentos</color>",
  ui_story_1011_10110901_86_dialog_content = "<color=#e8d9bb>Clank... Bang!</color>",
  ui_story_1011_10110901_87_dialog_content = "Uau... incrível! Bastou alguns chutes para que ele voltasse a funcionar!",
  ui_story_1011_10110901_88_dialog_content = "Esta é a máquina de venda automática que o Neural Aux mencionou?",
  ui_story_1011_10110901_89_dialog_content = "Esse tipo de objeto... parece familiar.",
  ui_story_1011_10110901_90_dialog_content = "Sim... IA e máquinas de venda automática parecem ser uma configuração padrão para ruínas subterrâneas ou algo assim...",
  ui_story_1011_10110901_91_dialog_content = "Ah! Vocês dois, apenas observem e aprendam.",
  ui_story_1011_10110901_92_dialog_content = "Hum... Aqui vamos nós!",
  ui_story_1011_10110901_93_dialog_content = "Huh? Você os trouxe com você?!",
  ui_story_1011_10110901_94_dialog_content = "Bem, eu queria testar minha teoria.",
  ui_story_1011_10110901_95_dialog_content = "Quando vi o formato da concha e como tinha líquido dentro, comecei a me perguntar...",
  ui_story_1011_10110901_96_dialog_content = "Os celestitas tinham copos para colocar água potável e também não comiam mariscos e coisas do gênero.",
  ui_story_1011_10110901_97_dialog_content = "Então, o que eles estavam fazendo com essas coisas?",
  ui_story_1011_10110901_98_dialog_content = "Mas agora eu tenho quase certeza para que eles serviam... Veja—",
  ui_story_1011_10110901_99_dialog_content = "Se eu despejar este líquido da concha do nautilus neste buraco na máquina de venda automática...",
  ui_story_1011_10110901_100_dialog_content = "<color=#e8d9bb>Ding! Bang!</color>",
  ui_story_1011_10110901_101_dialog_content = "Funcionou!",
  ui_story_1011_10110901_102_dialog_content = "Tada! Uma bebida energética para ir. Está expirado há muito tempo, mas enfim.",
  ui_story_1011_10110901_103_dialog_content = "Como você chegou a isso?!",
  ui_story_1011_10110901_104_dialog_content = "Tive um palpite quando vi aquelas conchas pela primeira vez.",
  ui_story_1011_10110901_105_dialog_content = "Você vê, a espiral de uma concha de nautilus realmente significa alguma coisa.",
  ui_story_1011_10110901_106_dialog_content = "É um conceito matemático encontrado na natureza.",
  ui_story_1011_10110901_107_dialog_content = "Natureza...? Eu não entendo. O que a espiral tem a ver com a natureza?",
  ui_story_1011_10110901_108_dialog_content = "A natureza não é coisas como árvores e flores?",
  ui_story_1011_10110901_109_dialog_content = "Você está certo, árvores e flores fazem parte da natureza.",
  ui_story_1011_10110901_110_dialog_content = "Mas esses conceitos são a base da natureza.",
  ui_story_1011_10110901_111_dialog_content = "Espirais de conchas de nautilus simbolizam o curso natural das coisas.",
  ui_story_1011_10110901_112_dialog_content = "Ou você pode simplesmente chamá-lo de \"continuidade\".",
  ui_story_1011_10110901_113_dialog_content = "Continuidade?",
  ui_story_1011_10110901_114_dialog_content = "Sim. Pegue uma muda, por exemplo. Ele não se transforma em uma árvore instantaneamente.",
  ui_story_1011_10110901_115_dialog_content = "Ela cresce continuamente a cada segundo de cada minuto.",
  ui_story_1011_10110901_116_dialog_content = "E \"continuidade\" refere-se a essa evolução.",
  ui_story_1011_10110901_117_dialog_content = "Certo, entendi agora... eu acho?",
  ui_story_1011_10110901_118_dialog_content = "Agora, desde que a matemática celestita antiga foi fundada a partir do conceito de \"continuidade\"...",
  ui_story_1011_10110901_119_dialog_content = "Achei que o modo de vida deles seria muito diferente do nosso.",
  ui_story_1011_10110901_120_dialog_content = "Um exemplo óbvio seria a moeda.",
  ui_story_1011_10110901_121_dialog_content = "Oh! Você está dizendo que nossa moeda, seja moedas ou notas, não é \"contínua\", correto?",
  ui_story_1011_10110901_122_dialog_content = "Isso mesmo. Quanto à sua forma de moeda, bem, você pode dizer observando a concha do nautilus.",
  ui_story_1011_10110901_123_dialog_content = "Era... líquido?",
  ui_story_1011_10110901_124_dialog_content = "Eu vejo. Então essas conchas de nautilus serviram como carteiras então?",
  ui_story_1011_10110901_125_dialog_content = "Recebido... Analisando a pergunta... Resposta: A concha é um recipiente de dinheiro.",
  ui_story_1011_10110901_126_dialog_content = "O volume líquido foi a métrica usada para o valor de um item no Obelisco do Retorno.",
  ui_story_1011_10110901_127_dialog_content = "As transações envolviam a troca de várias quantidades de líquido entre as conchas.",
  ui_story_1011_10110901_128_dialog_content = "Eu vejo. Quer dizer, essa não é minha área de especialização...",
  ui_story_1011_10110901_129_dialog_content = "Mas parece que era um sistema de som bonito.",
  ui_story_1011_10110901_130_dialog_content = "Adorando a natureza, buscando a continuidade...",
  ui_story_1011_10110901_131_dialog_content = "Ele se encaixa com a imagem geral dos celestitas.",
  ui_story_1011_10110901_132_dialog_content = "Você é incrível, Vice. Seu palpite correspondeu à explicação do Neural Aux palavra por palavra!",
  ui_story_1011_10110901_133_dialog_content = "E-Não é tão impressionante...",
  ui_story_1011_10110901_134_dialog_content = "Vamos continuar.",
  ui_story_1011_10110901_135_dialog_content = "Mas não há escadas que levem mais abaixo.",
  ui_story_1011_10110901_136_dialog_content = "A Zona de Exílio fica na parte inferior da torre?",
  ui_story_1011_10110901_137_dialog_content = "Eu não acho. O mapa do Neural Aux mostra que a Zona de Exílio está situada no meio.",
  ui_story_1011_10110901_138_dialog_content = "Neural Aux, como chegamos ao próximo nível abaixo?",
  ui_story_1011_10110901_139_dialog_content = "Recebido... Analisando pergunta... Resposta: A passagem para o próximo nível abaixo entrou em colapso.",
  ui_story_1011_10110901_140_dialog_content = "Se você está determinado a alcançá-lo...",
  ui_story_1011_10110901_141_dialog_content = "Por favor, prossiga pela fenda entre as duas máquinas de venda automática atrás de você.",
  ui_story_1011_10110901_142_dialog_content = "<color=#e8d9bb>Obelisco do Retorno: Fenda</color>",
  ui_story_1011_10110901_143_dialog_content = "Ugh... É tão escuro e apertado aqui. É bem mais estreito do que a passagem por onde entramos.",
  ui_story_1011_10110901_144_dialog_content = "Eu mal posso me mover também.",
  ui_story_1011_10110901_145_dialog_content = "(Espero que não causemos outro colapso forçando nossa passagem por aqui...)",
  ui_story_1011_10110901_146_dialog_content = "Vamos nos apressar, PlayerName.",
  ui_story_1011_10110901_147_dialog_content = "R-Certo...",
  ui_story_1011_10110901_148_dialog_content = "Bip!",
  ui_story_1011_10110901_149_dialog_content = "Aviso: Forma de vida detectada 50 metros à frente.",
  ui_story_1011_10110901_150_dialog_content = "Aviso: forma de vida se aproximando. 50 metros à frente.",
  ui_story_1011_10110901_151_dialog_content = "O-o que!? Mas não há, literalmente, para onde nos voltarmos...",
  ui_story_1011_10110901_152_dialog_content = "Existem Eclipsitas primordiais aqui?!",
  ui_story_1011_10110901_153_dialog_content = "Aviso: forma de vida se aproximando. 40 metros à frente.",
  ui_story_1011_10110901_154_dialog_content = "Atenção: 30 metros...",
  ui_story_1011_10110901_155_dialog_content = "PlayerName, pense em algo!",
  ui_story_1011_10110901_156_dialog_content = "Aviso: Forma de vida detectada 10 metros à frente. Confirmando identidade...",
  ui_story_1011_10110901_157_dialog_content = "Eu não sinto nada. Não é um celestita.",
  ui_story_1011_10110901_158_dialog_content = "Todos, preparem-se para lutar.",
  ui_story_1011_10110901_159_dialog_content = "Identidade confirmada: Eclipse.",
  ui_story_1011_10110901_160_dialog_content = "Gaar...",
  ui_story_1011_10110901_161_dialog_content = "Rugido... Rugido!!!",
  ui_story_1011_10110901_162_dialog_content = "Cuidado com o terreno e cuidado!",
  ui_story_1011_10110902_1_dialog_content = "Rugido...",
  ui_story_1011_10110902_2_dialog_content = "Devíamos ter prestado mais atenção.",
  ui_story_1011_10110902_3_dialog_content = "Há vestígios de luta espalhados por todo este lugar. Deveríamos estar em guarda.",
  ui_story_1011_10110902_4_dialog_content = "Afinal, esta é uma passagem secreta para a Zona de Exílio. Não admira que haja perigo à espreita.",
  ui_story_1011_10110902_5_dialog_content = "É tarde demais para voltar atrás agora.",
  ui_story_1011_10110902_6_dialog_content = "(Se estes forem <color=#FFB400>vestígios de luta</color>...)",
  ui_story_1011_10110902_7_dialog_content = "Neural Aux, escaneie os rastros no chão e me dê uma análise completa.",
  ui_story_1011_10110902_8_dialog_content = "Recebido. Ativando a verificação...",
  ui_story_1011_10110902_9_dialog_content = "Comparando resultados com banco de dados...",
  ui_story_1011_10110902_10_dialog_content = "Digitalização concluída.",
  ui_story_1011_10110902_11_dialog_content = "E então?",
  ui_story_1011_10110902_12_dialog_content = "Gerando relatório. As descobertas iniciais sugerem que uma batalha ocorreu aqui entre Caelestites e Eclipsites.",
  ui_story_1011_10110902_13_dialog_content = "A análise mostra vestígios de 200 restos de Eclipsite de baixo nível e 40 restos de Caelestite dentro da amostra de solo.",
  ui_story_1011_10110902_14_dialog_content = "Hmm...",
  ui_story_1011_10110902_15_dialog_content = "16 dog tags Caelestite e 2 Caelestite <color=#FFB400>armas</color> estão localizados 10 metros à frente.",
  ui_story_1011_10110902_16_dialog_content = "Armas!?",
  ui_story_1011_10110902_17_dialog_content = "Neural Aux está certo. Veja isso.",
  ui_story_1011_10110902_18_dialog_content = "Há duas armas aqui ao lado das rochas caídas, elas parecem imaculadas.",
  ui_story_1011_10110902_19_dialog_content = "Gerando relatório complementar...",
  ui_story_1011_10110902_20_dialog_content = "Correção dos resultados: 1 arma celestita. O clipe de energia está faltando na segunda arma.",
  ui_story_1011_10110902_21_dialog_content = "Aqui está.",
  ui_story_1011_10110902_22_dialog_content = "É surpreendentemente leve e compacto.",
  ui_story_1011_10110902_23_dialog_content = "Então... o \"clipe de energia\" desta arma está carregado e funcional?",
  ui_story_1011_10110902_24_dialog_content = "Recebido... Analisando pergunta... Reproduzindo a gravação introdutória da Laser Gun...",
  ui_story_1011_10110902_25_dialog_content = "Nome da arma: Arma Laser. Inventor: Mestre Francisco.",
  ui_story_1011_10110902_26_dialog_content = "Habilidade especial: <color=#FFB400>Ataque Eclipsite</color>. Usabilidade: Todos os Caelestites.",
  ui_story_1011_10110902_27_dialog_content = "Tutorial: Crie um link mental com a arma laser para retaliar efetivamente contra todos os pequenos ataques do Eclipsite.",
  ui_story_1011_10110902_28_dialog_content = "(Isso é incrível! É quase como uma versão de IA de uma arma de fogo!)",
  ui_story_1011_10110902_29_dialog_content = "Hã?",
  ui_story_1011_10110902_30_dialog_content = "Existem marcas irregulares ao longo do punho.",
  ui_story_1011_10110902_31_dialog_content = "Informações Complementares: Esta arma pertencia ao Mestre Francis.",
  ui_story_1011_10110902_32_dialog_content = "E-Aquele cara de novo?",
  ui_story_1011_10110902_33_dialog_content = "(A partir das informações que coletamos, esse Mestre Francis parece ser um personagem impressionante.)",
  ui_story_1011_10110902_34_dialog_content = "Aviso: Forma de vida se aproximando por trás. 50 metros.",
  ui_story_1011_10110902_35_dialog_content = "É assim mesmo? No momento ideal.",
  ui_story_1011_10110902_36_dialog_content = "É hora de experimentar essa arma, PlayerName. Carleen e eu vou cuidar de sua volta.",
  ui_story_1011_10110902_37_dialog_content = "Vamos!",
  ui_story_1011_10110902_38_dialog_content = "(Tum...Tum...)",
  ui_story_1011_10110902_39_dialog_content = "(Comandei inúmeras batalhas, mas é estressante estar na liderança.)",
  ui_story_1011_10110902_40_dialog_content = "Argh...",
  ui_story_1011_10110902_41_dialog_content = "Graaagh!",
  ui_story_1011_10110902_42_dialog_content = "(Agora!)",
  ui_story_1011_10110902_43_dialog_content = "<color=#e8d9bb>Bang! Bang!</color>",
  ui_story_1011_10110902_44_dialog_content = "Gaar...",
  ui_story_1011_10110902_45_dialog_content = "Eu-Funcionou!",
  ui_story_1011_10110902_46_dialog_content = "Não foi letal, mas derrubou completamente o Eclipsite!",
  ui_story_1011_10110902_47_dialog_content = "Apenas um único tiro! Essa coisa é tão eficaz!",
  ui_story_1011_10110902_48_dialog_content = "PlayerName, Estou impressionado que suas mãos nem sequer tremeram.",
  ui_story_1011_10110902_49_dialog_content = "T-Obrigado pelo elogio!",
  ui_story_1011_10110902_50_dialog_content = "De qualquer forma, com esta arma laser, estamos muito melhor do que estávamos.",
  ui_story_1011_10110902_51_dialog_content = "Vamos continuar.",
  ui_story_1011_10111001_1_dialog_content = "Graaagh!",
  ui_story_1011_10111001_2_dialog_content = "*Rugido*",
  ui_story_1011_10111001_3_dialog_content = "Grrr!",
  ui_story_1011_10111001_4_dialog_content = "<color=#e8d9bb>Bang! Bang! Bang!</color>",
  ui_story_1011_10111001_5_dialog_content = "Você está bastante acostumado a combater agora, PlayerName...",
  ui_story_1011_10111001_6_dialog_content = "Apesar de terem uma arma poderosa como essa, seus números ainda são assustadores...",
  ui_story_1011_10111001_7_dialog_content = "Como diabos esses Eclipsitas chegaram aqui?",
  ui_story_1011_10111001_8_dialog_content = "(Eles poderiam ter se originado aqui...?)",
  ui_story_1011_10111001_9_dialog_content = "E estranhamente, eles estão todos indo na mesma direção.",
  ui_story_1011_10111001_10_dialog_content = "Já que os Eclipsites não têm mente própria, eles devem estar reagindo a uma invocação, certo?",
  ui_story_1011_10111001_11_dialog_content = "(Uma convocação?)",
  ui_story_1011_10111001_12_dialog_content = "(Poderia ser o Eclipse ou...?)",
  ui_story_1011_10111001_13_dialog_content = "<color=#e8d9bb>Estrondo...</color>",
  ui_story_1011_10111001_14_dialog_content = "Essa não...",
  ui_story_1011_10111001_15_dialog_content = "Algo está se aproximando de nós, rápido!",
  ui_story_1011_10111001_16_dialog_content = "Portanto, há realmente um líder entre eles!",
  ui_story_1011_10111001_17_dialog_content = "Aviso! Forma de vida pela frente. 30, 20, 10 metros!",
  ui_story_1011_10111001_18_dialog_content = "<color=#e8d9bb>Estrondo...</color>",
  ui_story_1011_10111001_19_dialog_content = "Roooor!",
  ui_story_1011_10111001_20_dialog_content = "Rugido...",
  ui_story_1011_10111001_21_dialog_content = "Não é o Eclipsite de antes?!",
  ui_story_1011_10111001_22_dialog_content = "Já não tiramos? Como pode ser tão resistente...",
  ui_story_1011_10111001_23_dialog_content = "Carleen, Vice, afaste-se!",
  ui_story_1011_10111001_24_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_1011_10111001_25_dialog_content = "*ofegante*",
  ui_story_1011_10111001_26_dialog_content = "Graças a Deus eu tenho essa arma...",
  ui_story_1011_10111001_27_dialog_content = "Gaar...",
  ui_story_1011_10111001_28_dialog_content = "*Rugido*",
  ui_story_1011_10111001_29_dialog_content = "Quê?!",
  ui_story_1011_10111001_30_dialog_content = "Não é afetado!?",
  ui_story_1011_10111001_31_dialog_content = "*Rugido*",
  ui_story_1011_10111001_32_dialog_content = "PlayerName, pare de espaçar! Corre!",
  ui_story_1011_10111001_33_dialog_content = "F-Avançar? Mas... Mas nós nem sabemos o que está por vir—",
  ui_story_1011_10111001_34_dialog_content = "Esqueça isso!",
  ui_story_1011_10111001_35_dialog_content = "Neural Aux, ative o sistema de alerta!",
  ui_story_1011_10111001_36_dialog_content = "Recebido. Sistema de alerta ativado manualmente. Aviso: Forma de vida detectada 5 metros na parte traseira.",
  ui_story_1011_10111001_37_dialog_content = "Aviso: Forma de vida detectada 10 metros na parte traseira.",
  ui_story_1011_10111001_38_dialog_content = "Aviso: Forma de vida detectada. 15 metros atrás. Fechando em...",
  ui_story_1011_10111001_39_dialog_content = "Aviso: Forma de vida detectada. 10 metros atrás. Fechando em...",
  ui_story_1011_10111001_40_dialog_content = "Huff huff... Nós não estamos colocando distância entre nós!",
  ui_story_1011_10111001_41_dialog_content = "Alcançar, PlayerName!",
  ui_story_1011_10111001_42_dialog_content = "Eu sei!",
  ui_story_1011_10111001_43_dialog_content = "Aviso: Formulário de sinal de vida. 30 metros atrás. Fechando em...",
  ui_story_1011_10111001_44_dialog_content = "Não pare!",
  ui_story_1011_10111001_45_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_1011_10111001_46_dialog_content = "Ai! Isso dói...",
  ui_story_1011_10111001_47_dialog_content = "Hum? O que é isto?",
  ui_story_1011_10111001_48_dialog_content = "Hã?",
  ui_story_1011_10111001_49_dialog_content = "Vice? O que aconteceu?",
  ui_story_1011_10111001_50_dialog_content = "Isso foi doloroso! O que é um dispositivo como este sentado no meio de um túnel apertado?!",
  ui_story_1011_10111001_51_dialog_content = "Parece uma espécie de painel de controle e sua aparência é semelhante ao Neural Aux...",
  ui_story_1011_10111001_52_dialog_content = "Mas independentemente disso, o que está fazendo no meio de um túnel?",
  ui_story_1011_10111001_53_dialog_content = "Na verdade... talvez possamos fazer uso dele.",
  ui_story_1011_10111001_54_dialog_content = "Aviso: Forma de vida detectada. 25 metros atrás.",
  ui_story_1011_10111001_55_dialog_content = "Neural Aux, por favor, conte-nos como este dispositivo funciona!",
  ui_story_1011_10111001_56_dialog_content = "Neural Aux no modo de alerta manual. Não é possível alternar entre os modos neste momento.",
  ui_story_1011_10111001_57_dialog_content = "Aviso: Forma de vida detectada. 10 metros atrás.",
  ui_story_1011_10111001_58_dialog_content = "Quer saber, isso se parece com os dispositivos de controle usados para as armas da Illumina.",
  ui_story_1011_10111001_59_dialog_content = "Poderia muito bem dar uma chance!",
  ui_story_1011_10111001_60_dialog_content = "PlayerName, venha me ajudar a verificar sua identidade!",
  ui_story_1011_10111001_61_dialog_content = "Vou deixá-lo para você então!",
  ui_story_1011_10111001_62_option_content = "Controle forçado!",
  ui_story_1011_10111001_63_dialog_content = "Agora... Primeiro, feche o portão de bloqueio e ative o dispositivo...",
  ui_story_1011_10111001_64_dialog_content = "E então...",
  ui_story_1011_10111001_65_dialog_content = "Isso deve mostrar os Eclipsites!",
  ui_story_1011_10111001_66_dialog_content = "<color=#e8d9bb>Banco! Smack!</color>",
  ui_story_1011_10111001_67_dialog_content = "(Está... focando seu ataque nos Eclipsites?)",
  ui_story_1011_10111001_68_dialog_content = "*Rugido*",
  ui_story_1011_10111001_69_dialog_content = "Gaar...",
  ui_story_1011_10111001_70_dialog_content = "(Que poderoso!)",
  ui_story_1011_10111001_71_dialog_content = "Incrível...! PlayerName, parece tão eficaz contra os Eclipsites quanto sua arma!",
  ui_story_1011_10111001_72_dialog_content = "Não. É muito melhor que a arma!",
  ui_story_1011_10111001_73_dialog_content = "*Rugido*",
  ui_story_1011_10111001_74_dialog_content = "Aahhhhhh!",
  ui_story_1011_10111001_75_dialog_content = "*Rugido*",
  ui_story_1011_10111001_76_dialog_content = "(Por que os Eclipsitas estão tão irritados com sua morte?)",
  ui_story_1011_10111001_77_dialog_content = "Vice, atenção!",
  ui_story_1011_10111001_78_dialog_content = "Dispersem, pétalas de gelo!",
  ui_story_1011_10111001_79_dialog_content = "Argh!",
  ui_story_1011_10111001_80_dialog_content = "Vice, não tente bancar o herói! Voltam!",
  ui_story_1011_10111001_81_dialog_content = "(Já chegamos até aqui, e temos uma arma poderosa como essa aqui conosco...)",
  ui_story_1011_10111001_82_dialog_content = "(Fique calmo. Deve haver um jeito.)",
  ui_story_1011_10111001_83_dialog_content = "(É isso! <color=#FFB400>Ordem de Matança de Alcance Completo</color>!)",
  ui_story_1011_10111001_84_dialog_content = "<color=#e8d9bb>Bip, bip, bip, bip... Bang!</color>",
  ui_story_1011_10111001_85_dialog_content = "<color=#e8d9bb>Oba! Estrondo!</color>",
  ui_story_1011_10111001_86_dialog_content = "*suspirando*...Vice?",
  ui_story_1011_10111001_87_dialog_content = "Vice!",
  ui_story_1011_10111001_88_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10111001_89_dialog_content = "V-Vice!",
  ui_story_1011_10111001_90_dialog_content = "(De jeito nenhum... Nosso link ainda está intacto. Ela tem que estar bem!)",
  ui_story_1011_10111001_91_dialog_content = "Vice!",
  ui_story_1011_10111001_92_dialog_content = "*tosse, tosse* Estou bem aqui! PlayerName, Carleen!",
  ui_story_1011_10111001_93_dialog_content = "Obrigado Senhor!",
  ui_story_1011_10111001_94_dialog_content = "Vice! Você me assustou. Achei que você fosse...",
  ui_story_1011_10111001_95_dialog_content = "<color=#e8d9bb>Bip, bip, bip, bip...</color>",
  ui_story_1011_10111001_96_dialog_content = "Hã?",
  ui_story_1011_10111001_97_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1011_10111001_98_dialog_content = "O que⁠—",
  ui_story_1011_10111001_99_dialog_content = "<color=#e8d9bb>Bip, bip, bip, bip...</color>",
  ui_story_1011_10111001_100_dialog_content = "Sem alvos restantes. Ordem de Matança de Alcance Completo concluída.",
  ui_story_1011_10111001_101_dialog_content = "P-Por que...",
  ui_story_1011_10111001_102_dialog_content = "Quão...",
  ui_story_1011_10111001_103_dialog_content = "<size=50>Vice!</size>",
  ui_story_1011_10111001_104_dialog_content = "Vice... Vice!",
  ui_story_1011_10111001_105_dialog_content = "(Não!)",
  ui_story_1011_10111001_106_dialog_content = "Carleen! Fique atrás!",
  ui_story_1011_10111001_107_dialog_content = "Há algo errado com a máquina! Não deixe que ele detecte você!",
  ui_story_1011_10111001_108_option_content = "Quebre o link!",
  ui_story_1011_10111001_109_option_content = "Romper o link...?",
  ui_story_1011_10111001_110_dialog_content = "(Droga! O dispositivo não está respondendo!)",
  ui_story_1011_10111001_111_dialog_content = "Carleen, mantenha-se escondido!",
  ui_story_1011_10111001_112_dialog_content = "Sim!",
  ui_story_1011_10111001_113_dialog_content = "<color=#e8d9bb>Bip, bip, bip, bip...</color>",
  ui_story_1011_10111001_114_dialog_content = "Hum?",
  ui_story_1011_10111001_115_dialog_content = "(Ele ainda conseguiu me detectar!?)",
  ui_story_1011_10111001_116_dialog_content = "(Eu me pergunto se meu Moon Cocoon pode proteger contra—)",
  ui_story_1011_10111001_117_dialog_content = "*Rugido*",
  ui_story_1011_10111001_118_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1011_10111001_119_dialog_content = "(Como há mais Eclipsites?!)",
  ui_story_1011_10111001_120_option_content = "Quebre o link!",
  ui_story_1011_10111001_121_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_1011_10111001_122_dialog_content = "(Finalmente, está desligado!)",
  ui_story_1011_10111001_123_dialog_content = "PlayerName, cuide dos Eclipsites primeiro. Não os deixe chegar Vice!",
  ui_story_1011_10111001_124_dialog_content = "Não sabemos o estado dela. Não podemos mais perder tempo!",
  ui_story_1011_10111002_1_dialog_content = "Procurando formas de vida...",
  ui_story_1011_10111002_2_dialog_content = "Resultado da verificação gerado...",
  ui_story_1011_10111002_3_dialog_content = "Estado físico da forma de vida: Nenhum batimento cardíaco detectado. Sem sinais ativos de vida.",
  ui_story_1011_10111002_4_dialog_content = "Relatório de forma de vida: <color=#FFB400>Hibernação</color> estado confirmado.",
  ui_story_1011_10111002_5_dialog_content = "Hibernação?",
  ui_story_1011_10111002_6_dialog_content = "Controle-se, PlayerName.",
  ui_story_1011_10111002_7_dialog_content = "Precisamos descobrir como obter Vice fora de seu estado atual.",
  ui_story_1011_10111002_8_dialog_content = "Eu sei...",
  ui_story_1011_10111002_9_dialog_content = "Eu... eu sou o único capaz de me comunicar com o Neural Aux de qualquer maneira.",
  ui_story_1011_10111002_17_option_content = "Hibernação?",
  ui_story_1011_10111002_18_dialog_content = "As formas de vida atingidas pelo Atacante Especial entrarão em hibernação.",
  ui_story_1011_10111002_19_dialog_content = "Aurorianos que entraram nesse estado de hibernação entrarão em coma.",
  ui_story_1011_10111002_20_dialog_content = "Uma virgula?",
  ui_story_1011_10111002_21_dialog_content = "O que significa que tudo o que precisamos fazer é acordar Vice acima!",
  ui_story_1011_10111002_22_dialog_content = "Por favor, conte-me mais sobre esse estado de hibernação e como se livrar dele.",
  ui_story_1011_10111002_23_dialog_content = "Recebido... Analisando pergunta...",
  ui_story_1011_10111002_24_dialog_content = "Resposta encontrada: O estado de hibernação não é um coma regular.",
  ui_story_1011_10111002_25_dialog_content = "Os batimentos cardíacos e a respiração de um auroriano em hibernação serão suspensos indefinidamente.",
  ui_story_1011_10111002_26_dialog_content = "O mesmo vale para a energia Luminatic dentro de seu corpo.",
  ui_story_1011_10111002_27_dialog_content = "Pesquisando como encerrar a hibernação...",
  ui_story_1011_10111002_28_dialog_content = "Eu sinto Muito. Falha na pesquisa. Não sei.",
  ui_story_1011_10111002_29_dialog_content = "O que você quer dizer com a pesquisa falhou!?",
  ui_story_1011_10111002_30_dialog_content = "Não estou conseguindo te dar uma solução.",
  ui_story_1011_10111002_31_dialog_content = "O-O quê?",
  ui_story_1011_10111002_32_dialog_content = "Então isso não... isso não significa...",
  ui_story_1011_10111002_33_dialog_content = "(Isso não significa que ela é tão boa quanto <color=#FFB400>morto</color>?!?!)",
  ui_story_1011_10111002_34_dialog_content = "Por que os celestitas inventariam algo tão terrível?",
  ui_story_1011_10111002_36_dialog_content = "Não, não, isso não está acontecendo...",
  ui_story_1011_10111002_37_dialog_content = "Deve haver uma maneira de acordar Vice acima...",
  ui_story_1011_10111002_38_dialog_content = "A-Enquanto ainda estivermos aqui nestas ruínas, v-nós a encontraremos...",
  ui_story_1011_10111002_39_dialog_content = "Mas...!",
  ui_story_1011_10111002_40_dialog_content = "Se eu tivesse lidado com todos aqueles Eclipses...",
  ui_story_1011_10111002_41_dialog_content = "Se você pudesse ter se desconectado Vice e a impediu...",
  ui_story_1011_10111002_41X1_dialog_content = "Isso teria acontecido com ela!",
  ui_story_1011_10111002_41X2_dialog_content = "Tivemos uma chance, poderíamos ter...",
  ui_story_1011_10111002_42_dialog_content = "Carleen...",
  ui_story_1011_10111002_43_dialog_content = "...",
  ui_story_1011_10111002_44_dialog_content = "Eu sinto Muito. Eu deixei minhas emoções tomarem conta de mim.",
  ui_story_1011_10111002_45_dialog_content = "(Agora que penso nisso, por que o dispositivo danificou Vice?)",
  ui_story_1011_10111002_46_dialog_content = "(Ela poderia ter feito algo errado? Não... Se ela tivesse feito, eu teria percebido.)",
  ui_story_1011_10111002_47_dialog_content = "<color=#e8d9bb>Bip, bip, bip, bip...</color>",
  ui_story_1011_10111002_48_dialog_content = "Sem alvos restantes. Ordem de Matança de Alcance Completo concluída.",
  ui_story_1011_10111002_49_dialog_content = "Vice foi quem ativou a \"Ordem de Matança de Alcance Completo\".",
  ui_story_1011_10111002_50_dialog_content = "Neural Aux, como o aparelho acabou prejudicando Vice por engano?",
  ui_story_1011_10111002_51_dialog_content = "Recebido... Analisando pergunta...",
  ui_story_1011_10111002_52_dialog_content = "Resposta: O Atacante Especial executou o comando sem erro. Nenhuma forma de vida foi prejudicada por engano.",
  ui_story_1011_10111002_53_dialog_content = "Quê?!",
  ui_story_1011_10111002_54_dialog_content = "Vice está mentindo bem na nossa frente! Pare de brincar!",
  ui_story_1011_10111002_55_dialog_content = "Minha resposta está correta. Repito: O Atacante Especial executou o comando sem erro. Nenhuma forma de vida era—",
  ui_story_1011_10111002_56_dialog_content = "Caelestite, por favor, abaixe sua arma laser. Seu efeito paralisante não funciona no Neural Aux.",
  ui_story_1011_10111002_57_dialog_content = "Repito: O Atacante Especial executou o comando sem erro. Nenhuma forma de vida foi prejudicada por engano.",
  ui_story_1011_10111002_58_dialog_content = "...",
  ui_story_1011_10111002_59_dialog_content = "...",
  ui_story_1011_10111002_60_dialog_content = "Acalmar, PlayerName. Interrogue-o meticulosamente, até obtermos as respostas de que precisamos.",
  ui_story_1011_10111002_61_dialog_content = "Não deixe a lógica da máquina do Neural Aux tirar o melhor de você.",
  ui_story_1011_10111002_62_dialog_content = "Vice ainda está esperando por nós para acordá-la.",
  ui_story_1011_10111002_63_dialog_content = "Você tem razão. Há uma pergunta importante que ainda não fizemos.",
  ui_story_1011_10111002_64_dialog_content = "Neural Aux, por favor, explique o <color=#FFB400>função principal</color> deste Atacante Especial.",
  ui_story_1011_10111002_65_dialog_content = "Recebido... Analisando pergunta...",
  ui_story_1011_10111002_66_dialog_content = "Reproduzindo a gravação introdutória do Special Attacker...",
  ui_story_1011_10111002_67_dialog_content = "Caelestites inicialmente usaram o Atacante Especial como um dispositivo de autodefesa.",
  ui_story_1011_10111002_68_dialog_content = "Oferece diferentes níveis de supressão contra diferentes tipos de inimigos.",
  ui_story_1011_10111002_69_dialog_content = "Devido à sua eficácia, foi então usado ativamente em combate. Fim da gravação.",
  ui_story_1011_10111002_70_dialog_content = "Isso não nos diz nada!",
  ui_story_1011_10111002_71_dialog_content = "Estou ainda mais confuso agora. Por que no mundo ele atacaria Vice?",
  ui_story_1011_10111002_72_dialog_content = "PlayerName...",
  ui_story_1011_10111002_73_dialog_content = "Acho que estou começando a entender.",
  ui_story_1011_10111002_74_dialog_content = "Isto é, se o Neural Aux nos disse tudo o que há para saber sobre este dispositivo.",
  ui_story_1011_10111002_74X1_dialog_content = "Era a tecnologia Caelestite, usada para autodefesa. Sua Ordem de Matança de Alcance Completo acabou mirando Vice, um auroriano.",
  ui_story_1011_10111002_75_dialog_content = "Então o estado de hibernação para o qual envia os não-Caelestites pode ter sido...",
  ui_story_1011_10111002_76_dialog_content = "É possível que, para os antigos celestitas, isso fosse apenas um <color=#FFB400>comum</color> ocorrência.",
  ui_story_1011_10111002_77_dialog_content = "Assim como quando aprendi a usar meu Moon Cocoon...",
  ui_story_1011_10111002_78_dialog_content = "Meu instrutor nunca se preocupou em mencionar por que eu o apontaria para um Eclipsite em primeiro lugar.",
  ui_story_1011_10111002_79_dialog_content = "Porque não era algo que realmente precisava ser explicado.",
  ui_story_1011_10111002_80_dialog_content = "?!",
  ui_story_1011_10111002_81_dialog_content = "Eu não consigo entender, nem posso simplesmente aceitar isso...",
  ui_story_1011_10111002_82_dialog_content = "Mas não posso negar que o que você está dizendo faz sentido.",
  ui_story_1011_10111002_83_dialog_content = "É possível que os antigos aurorianos considerassem os celestitas seus <color=#FFB400>inimigo</color>?",
  ui_story_1011_10111101_1_dialog_content = "Eu não faço ideia. Estou cada vez mais confuso.",
  ui_story_1011_10111101_2_dialog_content = "Estamos em Eraveil, sob a torre branca que é o marco mais distinto da região.",
  ui_story_1011_10111101_3_dialog_content = "No entanto, não consigo entender nada.",
  ui_story_1011_10111101_4_dialog_content = "Não sei o que é este lugar, nem que tipo de indivíduos viveram aqui.",
  ui_story_1011_10111101_5_dialog_content = "Não sei como esses indivíduos pereceram, deixando para trás sinais gritantes de uma batalha uma vez travada.",
  ui_story_1011_10111101_6_dialog_content = "Talvez através de nossas experiências, já tenhamos encontrado a resposta.",
  ui_story_1011_10111101_7_dialog_content = "Eclipsitos são as únicas coisas que sobreviveram neste lugar.",
  ui_story_1011_10111101_8_dialog_content = "...",
  ui_story_1011_10111101_9_dialog_content = "Assim como o que aconteceu em Eraveil dezessete anos atrás?",
  ui_story_1011_10111101_10_dialog_content = "Talvez pior. Porque seus últimos gritos nunca teriam saído para o resto do mundo ouvir.",
  ui_story_1011_10111101_11_dialog_content = "Este lugar encontrou seu fim trágico em completo silêncio, sem que ninguém soubesse.",
  ui_story_1011_10111101_12_dialog_content = "Podemos ser os únicos forasteiros em centenas ou milhares de anos a pisar aqui.",
  ui_story_1011_10111101_13_dialog_content = "Pesquisando nos últimos mil anos.",
  ui_story_1011_10111101_14_dialog_content = "Nenhum registro de forasteiros. Sua teoria está correta.",
  ui_story_1011_10111101_15_dialog_content = "Eu não estava falando com você.",
  ui_story_1011_10111101_16_dialog_content = "A diretriz primária do Neural Aux é ajudar os Caelestites de todas as maneiras possíveis.",
  ui_story_1011_10111101_17_dialog_content = "Se você fosse realmente útil para resolver os problemas reais em mãos...",
  ui_story_1011_10111101_18_dialog_content = "Você não sabe acordar Vice up nem como reparar Soroz.",
  ui_story_1011_10111101_19_dialog_content = "Consultando usando os novos parâmetros...",
  ui_story_1011_10111101_20_dialog_content = "Nenhum método para \"acordar Vice up\" ou \"reparar Soroz\" encontrado no banco de dados.",
  ui_story_1011_10111101_21_dialog_content = "Sua análise é precisa. Não sei.",
  ui_story_1011_10111101_22_dialog_content = "Puxa, obrigado pela confirmação.",
  ui_story_1011_10111101_23_dialog_content = "Eu sinto muito. Baixa pontuação de satisfação do usuário recebida. Os ajustes serão feitos no futuro.",
  ui_story_1011_10111101_24_dialog_content = "Eu não estava te culpando...",
  ui_story_1011_10111101_25_dialog_content = "Considerando o desastre que obviamente ocorreu aqui, não é de admirar que você não esteja funcionando corretamente.",
  ui_story_1011_10111101_26_dialog_content = "Nós mesmos encontraremos as respostas.",
  ui_story_1011_10111101_27_dialog_content = "Vamos continuar, Carleen, nas profundezas.",
  ui_story_1011_10111101_28_dialog_content = "Não temos outra escolha.",
  ui_story_1011_10111101_29_dialog_content = "Sim. eu vou levar Vice.",
  ui_story_1011_10111101_30_dialog_content = "(Encontraremos uma maneira de consertar o que aconteceu com você.)",
  ui_story_1011_10111101_31_dialog_content = "(Apenas espere... Você deve.)",
  ui_story_1011_10111101_32_dialog_content = "<color=#e8d9bb>*Passos ecoando*</color>",
  ui_story_1011_10111101_33_dialog_content = "Estou surpreso que não encontramos nada ao longo deste caminho.",
  ui_story_1011_10111101_34_dialog_content = "Sem eclipsitos ou quaisquer detritos espalhados.",
  ui_story_1011_10111101_35_dialog_content = "Na verdade, esta é provavelmente a área mais arrumada que vimos desde que chegamos aqui.",
  ui_story_1011_10111101_36_dialog_content = "Sim, mas a limpeza é estranha.",
  ui_story_1011_10111101_37_dialog_content = "É como se este lugar não fosse totalmente afetado pelo que aconteceu nas outras áreas.",
  ui_story_1011_10111101_38_dialog_content = "É desprovido de vida humana e insinuações de batalha.",
  ui_story_1011_10111101_39_dialog_content = "Dá um ar friozinho, não é?",
  ui_story_1011_10111101_40_dialog_content = "Sim.",
  ui_story_1011_10111101_41_dialog_content = "Um professor da Dawn A Academia me disse uma vez:",
  ui_story_1011_10111101_42_dialog_content = "\"As coisas que tornam os seres humanos humanos tendem a se reunir na superfície do mundo.\"",
  ui_story_1011_10111101_43_dialog_content = "\"Quanto mais fundo você for, mais você sentirá sua humanidade escorrer.\"",
  ui_story_1011_10111101_44_dialog_content = "Isso não é representativo de nossas circunstâncias atuais?",
  ui_story_1011_10111101_45_dialog_content = "Cada passo que damos nos leva mais fundo nas profundezas.",
  ui_story_1011_10111101_46_dialog_content = "Seu professor provavelmente nunca esperou que você aplicasse essa afirmação às profundezas subterrâneas reais.",
  ui_story_1011_10111101_47_dialog_content = "Bem, agora eu entendo muito mais do que já entendi sentado em uma sala de aula.",
  ui_story_1011_10111101_48_dialog_content = "Caelestita detectada na área restrita. Verificando identidade.",
  ui_story_1011_10111101_49_dialog_content = "Bip... Bip... Bip... Bip...",
  ui_story_1011_10111101_50_dialog_content = "Hum? Por que de repente você está fazendo tanto barulho, Neural Aux?",
  ui_story_1011_10111101_51_dialog_content = "Bip... Bip... Bip... Bip!",
  ui_story_1011_10111101_52_dialog_content = "Falha na verificação. Não continue. Repita: Não continue.",
  ui_story_1011_10111101_53_dialog_content = "E daí, voltamos? De jeito nenhum eu vou voltar a lutar até a morte com um monte de Eclipsites.",
  ui_story_1011_10111101_54_dialog_content = "E por que de repente? Você pelo menos tem que me dar uma explicação!",
  ui_story_1011_10111101_55_dialog_content = "PlayerName, olhe para frente.",
  ui_story_1011_10111101_56_dialog_content = "Isso é um <color=#FFB400>porta de pedra</color>?",
  ui_story_1011_10111101_57_dialog_content = "Claro que parece um.",
  ui_story_1011_10111101_58_dialog_content = "Isso é massivo. Eu quase o considerei como uma parede.",
  ui_story_1011_10111101_59_dialog_content = "Imagine a força necessária para abrir uma porta desse tamanho.",
  ui_story_1011_10111101_60_dialog_content = "Eu não acho que se moveria mesmo se fosse atingido com o martelo mais pesado.",
  ui_story_1011_10111101_61_dialog_content = "Não consigo pensar em nenhuma facção no mundo que atualmente tenha a capacidade de produzir ou mesmo alimentar uma porta de pedra tão grande.",
  ui_story_1011_10111101_62_dialog_content = "Concordo.",
  ui_story_1011_10111101_63_dialog_content = "Nem mesmo essa tecnologia milagrosa poderia salvá-los no final, hein?",
  ui_story_1011_10111101_64_dialog_content = "Não continue. Repita: Não continue.",
  ui_story_1011_10111101_65_dialog_content = "Você não tem permissão para acessar o <color=#FFB400>Núcleo central</color>.",
  ui_story_1011_10111101_66_dialog_content = "Acesso não concedido?",
  ui_story_1011_10111101_67_dialog_content = "A porta só abre para pessoal autorizado.",
  ui_story_1011_10111101_68_dialog_content = "Não é permitida a entrada de pessoal não autorizado pelo <color=#FFB400>ordens</color> dado.",
  ui_story_1011_10111101_69_dialog_content = "Eu gostaria de ver esta porta aberta. A visão provavelmente seria magnífica.",
  ui_story_1011_10111101_70_dialog_content = "Eu também acho. Precisamos de uma ajudinha aqui, Neural Aux.",
  ui_story_1011_10111101_71_dialog_content = "Como obtemos a permissão para entrar?",
  ui_story_1011_10111101_72_dialog_content = "Eu sinto Muito. Eu não posso te ajudar.",
  ui_story_1011_10111101_73_dialog_content = "Huh? Você não disse que sua diretriz primária era me ajudar de todas as maneiras possíveis?",
  ui_story_1011_10111101_74_dialog_content = "Seu acesso é negado pelo Decreto Supremo. A primeira e mais alta ordem que existe.",
  ui_story_1011_10111101_75_dialog_content = "Os celestitas não podem desobedecer ao Decreto Supremo, nem o Aux Neural.",
  ui_story_1011_10111101_76_dialog_content = "O mais alto decreto... é?",
  ui_story_1011_10111101_77_dialog_content = "Eles usaram uma porta de pedra do tamanho de uma montanha apenas para manter as pessoas fora.",
  ui_story_1011_10111101_78_dialog_content = "O Decreto Supremo soa um tanto arrogante.",
  ui_story_1011_10111101_79_dialog_content = "Esta porta de pedra com certeza era adequada para seu propósito.",
  ui_story_1011_10111101_80_dialog_content = "No entanto...",
  ui_story_1011_10111101_81_dialog_content = "Foi quando este lugar estava no seu auge.",
  ui_story_1011_10111101_82_dialog_content = "Esses dias acabaram e tudo o que resta é uma ameaça vazia.",
  ui_story_1011_10111101_83_dialog_content = "Sim, essas fendas desgastadas são mais do que suficientes para nos permitir passar.",
  ui_story_1011_10111101_84_dialog_content = "Semelhante a um leão que não tem dentes, mas ainda não se dobra.",
  ui_story_1011_10111101_85_dialog_content = "É lamentável vê-lo fazer tanto esforço para nos rejeitar neste estado.",
  ui_story_1011_10111101_86_dialog_content = "Não continue. Repita: Não continue.",
  ui_story_1011_10111101_87_dialog_content = "Vamos entrar já.",
  ui_story_1011_10111101_88_dialog_content = "Vamos ver o que esta porta de pedra está escondendo.",
  ui_story_1011_10111101_89_dialog_content = "Sim. Ainda há muito a ser descoberto e, neste momento, não temos outras opções.",
  ui_story_1011_10111101_90_dialog_content = "Você não recebeu acesso. Você não pode entrar na região Central Core.",
  ui_story_1011_10111101_91_dialog_content = "Neural Aux, apenas descanse já.",
  ui_story_1011_10111101_92_dialog_content = "O Decreto Supremo nega sua entrada.",
  ui_story_1011_10111101_93_dialog_content = "Os celestitas não podem desobedecer ao mais alto decreto...",
  ui_story_1011_10111101_94_dialog_content = "(Rastejar por essa fenda escura me faz perceber que esta porta de pedra é muito mais grossa do que parece do lado de fora.)",
  ui_story_1011_10111101_95_dialog_content = "(A voz de Neural Aux diminuiu. Eu me pergunto se ele finalmente desistiu ou foi bloqueado pela porta.)",
  ui_story_1011_10111101_96_dialog_content = "(Minha imaginação está correndo solta pensando no que poderia estar esperando por nós do outro lado desta porta...)",
  ui_story_1011_10111101_97_dialog_content = "(Mas eu só sei que não importa o que aconteça, ficarei atordoado.)",
  ui_story_1011_10111101_98_dialog_content = "(Sei o significado e as implicações do que estou prestes a ver.)",
  ui_story_1011_10111101_99_dialog_content = "(Estes são os restos de toda uma civilização.)",
  ui_story_1011_10111101_100_dialog_content = "O que é isso?!",
  ui_story_1011_10111101_101_dialog_content = "Milagrosamente, ainda está funcionando...",
  ui_story_1011_10111101_102_dialog_content = "Neural Aux, você ainda está aí?",
  ui_story_1011_10111101_103_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10111101_104_dialog_content = "Acho que não vai responder, já que não conseguiu nos impedir de entrar.",
  ui_story_1011_10111101_105_dialog_content = "Então vamos ter que descobrir isso por nós mesmos.",
  ui_story_1011_10111101_106_dialog_content = "São um monte de tabletes circulares flutuantes.",
  ui_story_1011_10111101_107_dialog_content = "Para que servem? Eu realmente não consigo nem imaginar.",
  ui_story_1011_10111101_108_dialog_content = "Você já viu algo assim antes?",
  ui_story_1011_10111101_109_dialog_content = "Nunca.",
  ui_story_1011_10111101_110_dialog_content = "Nós nunca desenterramos nada remotamente semelhante de outras ruínas antigas antes.",
  ui_story_1011_10111101_111_dialog_content = "Isso não é surpreendente, no entanto. Essas ruínas são diferentes das outras, são ruínas celestitas.",
  ui_story_1011_10111101_112_dialog_content = "Talvez apenas os celestitas possam fazer uso desses objetos.",
  ui_story_1011_10111101_113_dialog_content = "Como assim?",
  ui_story_1011_10111101_114_dialog_content = "A maneira como vocês celestitas vêem o mundo é diferente de como nós, aurorianos, o vemos.",
  ui_story_1011_10111101_115_dialog_content = "Se eles foram projetados para serem usados por celestitas, talvez apenas um celestita tenha a capacidade de operá-lo.",
  ui_story_1011_10111101_116_dialog_content = "Você quer dizer minha habilidade psíquica?",
  ui_story_1011_10111101_117_dialog_content = "É apenas o meu palpite. Por que não testamos?",
  ui_story_1011_10111101_118_dialog_content = "Tá bom.",
  ui_story_1011_10111101_119_option_content = "Controle forçado!",
  ui_story_1011_10111101_120_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_1011_10111101_121_dialog_content = "Huh? Isto é...",
  ui_story_1011_10111101_122_dialog_content = "Bem-vindo, recém-nascido.",
  ui_story_1011_10111101_123_dialog_content = "Esta é a sua primeira vez com o <color=#FFB400>Sistema Circular</color>?",
  ui_story_1011_10111101_124_dialog_content = "Sistema circular? Você quer dizer o aparelho?",
  ui_story_1011_10111101_125_dialog_content = "Onde estou? Quem está falando?",
  ui_story_1011_10111101_126_dialog_content = "O Sistema Circular contém as memórias de toda a raça celestita.",
  ui_story_1011_10111101_127_dialog_content = "Aqui, você aprenderá sobre o mundo.",
  ui_story_1011_10111101_128_dialog_content = "Espere... Ninguém está realmente \"falando\" comigo.",
  ui_story_1011_10111101_129_dialog_content = "Toda essa informação transcendeu a própria linguagem verbal e está sendo alimentada diretamente para mim.",
  ui_story_1011_10111101_130_dialog_content = "Vamos começar com sua localização atual.",
  ui_story_1011_10111101_131_dialog_content = "Este é o berço da civilização celestita, onde nascem todos os celestitas.",
  ui_story_1011_10111101_132_dialog_content = "Não importa onde você vá, este lugar sempre será seu lar.",
  ui_story_1011_10111101_133_dialog_content = "Isto é o <color=#FFB400>Cidade do Obelisco</color>.",
  ui_story_1011_10111101_134_dialog_content = "Cidade do Obelisco...",
  ui_story_1011_10111101_135_dialog_content = "Não são os celestitas de Eraveil?",
  ui_story_1011_10111101_136_dialog_content = "Esta cidade é composta por inúmeras torres.",
  ui_story_1011_10111101_137_dialog_content = "Você está no centro da cidade, dentro da primeira e mais alta de todas as torres.",
  ui_story_1011_10111101_138_dialog_content = "O Obelisco do Retorno.",
  ui_story_1011_10111101_139_dialog_content = "Todo celestita recebe educação aqui até atingir a maioridade.",
  ui_story_1011_10111101_140_dialog_content = "Você terá a chance de explorar o mundo e viajar até os confins do mundo quando atingir a maioridade.",
  ui_story_1011_10111101_141_dialog_content = "Mas sua casa... a Cidade do Obelisco... estará sempre esperando...",
  ui_story_1011_10111101_142_dialog_content = "Aguardando seu retorno... no final de... sua jornada...",
  ui_story_1011_10111101_143_dialog_content = "!!!",
  ui_story_1011_10111101_144_dialog_content = "E-é isso!?",
  ui_story_1011_10111101_145_dialog_content = "Então? O que você viu?",
  ui_story_1011_10111101_146_dialog_content = "Eu ouvi uma voz. Não. Não é uma voz. Recebi informações.",
  ui_story_1011_10111101_147_dialog_content = "Em formação?",
  ui_story_1011_10111101_148_dialog_content = "No momento em que me conectei com o dispositivo, a informação foi enviada diretamente para mim.",
  ui_story_1011_10111101_149_dialog_content = "Parecia... uma palestra.",
  ui_story_1011_10111101_150_dialog_content = "Fui informado de que este dispositivo se chama Sistema Circular, que contém toda a história da raça celestita.",
  ui_story_1011_10111101_151_dialog_content = "Também disse que este é o local de nascimento dos celestitas, chamado de Cidade do Obelisco.",
  ui_story_1011_10111101_152_dialog_content = "O Obelisco do Retorno, no qual estamos agora, é o mais alto de todos.",
  ui_story_1011_10111101_153_dialog_content = "Não mencionou Eraveil?",
  ui_story_1011_10111101_154_dialog_content = "Não. Fiquei intrigado com isso também.",
  ui_story_1011_10111101_155_dialog_content = "O nome mudou ao longo do tempo...?",
  ui_story_1011_10111101_156_dialog_content = "Isso é possível. Este lugar é antigo. Tanto a linguagem escrita quanto a verbal podem ter mudado.",
  ui_story_1011_10111101_157_dialog_content = "Então... esse Sistema Circular é algum tipo de dispositivo de armazenamento de informações?",
  ui_story_1011_10111101_158_dialog_content = "Você pode dizer isso.",
  ui_story_1011_10111101_159_dialog_content = "Os Caelestites recuperam informações usando habilidades psíquicas.",
  ui_story_1011_10111101_160_dialog_content = "Por que é projetado assim?",
  ui_story_1011_10111101_161_dialog_content = "Eu ainda não entendo como esses tablets circulares devem funcionar.",
  ui_story_1011_10111101_162_dialog_content = "Além disso... Seu tamanho é grande demais para um dispositivo de armazenamento de informações.",
  ui_story_1011_10111101_163_dialog_content = "A quantidade de informações seria enorme, mesmo que este lugar estivesse cheio de livros.",
  ui_story_1011_10111101_164_dialog_content = "Livros...",
  ui_story_1011_10111101_165_dialog_content = "Espere. Carleen, você se lembra da amonite que pegamos?",
  ui_story_1011_10111101_166_dialog_content = "Claro.",
  ui_story_1011_10111101_167_dialog_content = "Vice disse, sua forma imita os princípios matemáticos desta antiga civilização.",
  ui_story_1011_10111101_168_dialog_content = "Eles adoram a natureza, e sua representação matemática é \"progressão\".",
  ui_story_1011_10111101_169_dialog_content = "Esse conceito pode muito bem estar em jogo aqui.",
  ui_story_1011_10111101_170_dialog_content = "Quer dizer, essas formas circulares também simbolizam \"progressão\"?",
  ui_story_1011_10111101_171_dialog_content = "Sim. Estou pensando em como você disse que este lugar poderia estar cheio de livros.",
  ui_story_1011_10111101_172_dialog_content = "Se fôssemos armazenar e organizar livros, nós os empilhávamos, sem deixar espaço entre eles.",
  ui_story_1011_10111101_173_dialog_content = "Eventualmente, vamos acabar com uma pilha retangular de livros.",
  ui_story_1011_10111101_174_dialog_content = "Mas um retângulo tem muitos cantos, então suas linhas não são contínuas...",
  ui_story_1011_10111101_175_dialog_content = "Considerando que um círculo não tem cantos.",
  ui_story_1011_10111101_176_dialog_content = "Então esse espaço também incorporou o conceito de “progressão” para armazenar informações.",
  ui_story_1011_10111101_177_dialog_content = "Foi exatamente isso que eu quis dizer!",
  ui_story_1011_10111101_178_dialog_content = "Mesmo que eu possa... descrevê-lo assim, eu ainda não entendo como ele realmente funciona.",
  ui_story_1011_10111101_179_dialog_content = "Se isso fosse verdade, essa antiga civilização era muito mais avançada do que pensávamos anteriormente.",
  ui_story_1011_10111101_180_dialog_content = "Seus princípios científicos básicos são drasticamente diferentes dos nossos.",
  ui_story_1011_10111101_181_dialog_content = "Aos olhos deles, poderíamos muito bem ser seres primitivos brincando com bastões.",
  ui_story_1011_10111101_182_dialog_content = "Isso é... tão difícil de imaginar.",
  ui_story_1011_10111101_183_dialog_content = "Tente acessá-lo novamente, PlayerName.",
  ui_story_1011_10111101_184_dialog_content = "Quanta informação poderia conter, dada sua tecnologia não convencional?",
  ui_story_1011_10111101_185_dialog_content = "Talvez tenha a resposta para todas as perguntas do mundo.",
  ui_story_1011_10111101_186_dialog_content = "Vou tentar outra vez!",
  ui_story_1011_10111101_187_option_content = "Controle forçado!",
  ui_story_1011_10111101_188_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_1011_10111101_189_dialog_content = "Aqui novamente.",
  ui_story_1011_10111101_190_dialog_content = "Se este lugar armazena informaçőes... eu deveria ser capaz de navegar por ele.",
  ui_story_1011_10111101_191_dialog_content = "Mas não há nada tão óbvio quanto estantes.",
  ui_story_1011_10111101_192_dialog_content = "Certo, minha mente. Deixe-me tentar visualizá-lo em minha mente.",
  ui_story_1011_10111101_193_dialog_content = "Hã?",
  ui_story_1011_10111101_194_dialog_content = "Os tablets flutuantes estão se movendo.",
  ui_story_1011_10111101_195_dialog_content = "PlayerName, o que você está fazendo?",
  ui_story_1011_10111101_196_dialog_content = "Uau! Poxa...",
  ui_story_1011_10111101_197_dialog_content = "Estou me sentindo enjoado... estou me movendo?",
  ui_story_1011_10111101_198_dialog_content = "Pare... Eu preciso encontrar uma maneira de parar.",
  ui_story_1011_10111101_199_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_1011_10111101_200_dialog_content = "Ufa... Parou?",
  ui_story_1011_10111101_201_dialog_content = "O Colosso.",
  ui_story_1011_10111101_202_dialog_content = "Eh!?",
  ui_story_1011_10111101_203_dialog_content = "O Colossus é uma grande instalação multifuncional alimentada pela Lumina.",
  ui_story_1011_10111101_204_dialog_content = "É a coisa mais confiável para um celestita.",
  ui_story_1011_10111101_205_dialog_content = "Os celestitas são poderosos em mente, mas o preço está sendo fisicamente fraco.",
  ui_story_1011_10111101_206_dialog_content = "Um Colosso compensa a fraqueza de um celestita e serve como uma extensão do corpo, sincronizando o movimento com a velocidade do pensamento de um celestita.",
  ui_story_1011_10111101_207_dialog_content = "Portanto, todo celestita deve aprender a pilotar um Colosso, antes de tudo.",
  ui_story_1011_10111101_208_dialog_content = "É definitivamente um programa educacional...",
  ui_story_1011_10111101_209_dialog_content = "Está me ensinando a pilotar um Colossus desta vez?",
  ui_story_1011_10111101_210_dialog_content = "Há um cockpit instalado para os Caelestites controlarem o Colosso.",
  ui_story_1011_10111101_211_dialog_content = "Um celestita deve ligar sua mente a um colosso.",
  ui_story_1011_10111101_212_dialog_content = "Poder de ressonância suficiente ativará o Colossus.",
  ui_story_1011_10111101_213_dialog_content = "Foi o que aconteceu comigo.",
  ui_story_1011_10111101_214_dialog_content = "Um Colossus pode ser equipado com vários módulos e plugins para servir a diferentes funções para o Caelestite.",
  ui_story_1011_10111101_215_dialog_content = "Com Colossus, um celestita pode ser mais poderoso do que qualquer ser vivo no mundo.",
  ui_story_1011_10111101_216_dialog_content = "Mas, como detentor desse grande poder, qualquer piloto Colossus faria bem em lembrar:",
  ui_story_1011_10111101_217_dialog_content = "O Mais Alto Decreto impresso em você no momento de seu nascimento.",
  ui_story_1011_10111101_218_dialog_content = "Os celestitas e os colossos serão sempre e para sempre máquinas de guerra.",
  ui_story_1011_10111101_219_dialog_content = "Máquinas de guerra!?",
  ui_story_1011_10111101_220_dialog_content = "Como isso é possível... O Soroz e eu... não podemos nem lutar...",
  ui_story_1011_10111101_221_dialog_content = "Esta máquina de guerra tem o corpo de um colosso e a mente de um celestita.",
  ui_story_1011_10111101_222_dialog_content = "Esta arma em particular está vinculada pelo mais alto decreto e pronta para os inimigos...",
  ui_story_1011_10111101_223_dialog_content = "Tudo ao seu serviço.",
  ui_story_1011_10111101_224_dialog_content = "O QUE!?",
  ui_story_1011_10111101_225_dialog_content = "São estes... Eclipses!?",
  ui_story_1011_10111101_226_dialog_content = "Em seguida, você precisará aprender sobre a guerra com muito tempo.",
  ui_story_1011_10111101_227_dialog_content = "Você verá o campo de batalha nos dados.",
  ui_story_1011_10111101_228_dialog_content = "Você verá como uma vida é insignificante e verá como inclinar a balança destrói o equilíbrio.",
  ui_story_1011_10111101_229_dialog_content = "Felizmente, este campo de batalha não pertence aos celestitas.",
  ui_story_1011_10111101_230_dialog_content = "Há soldados nascidos para a guerra, e tudo o que sabem é matar.",
  ui_story_1011_10111101_231_dialog_content = "Esses soldados nojentos vão abraçar o campo de batalha.",
  ui_story_1011_10111101_232_dialog_content = "Quanto a você, você só será responsável por...",
  ui_story_1011_10111101_233_dialog_content = "Criando guerras para o mundo.",
  ui_story_1011_10111201_1_dialog_content = "Aff... aff...",
  ui_story_1011_10111201_2_dialog_content = "Qual o problema, PlayerName?",
  ui_story_1011_10111201_3_dialog_content = "Você está suando muito.",
  ui_story_1011_10111201_4_dialog_content = "Huff... eu...",
  ui_story_1011_10111201_5_dialog_content = "Não sei.",
  ui_story_1011_10111201_6_dialog_content = "Não sei por que vi o que acabei de ver.",
  ui_story_1011_10111201_7_dialog_content = "Não sei o que significava... não sei.",
  ui_story_1011_10111201_8_dialog_content = "O que você viu?",
  ui_story_1011_10111201_9_dialog_content = "Eu vi o Colosso.",
  ui_story_1011_10111201_10_dialog_content = "O Sistema Circular está me ensinando a operar um Colosso.",
  ui_story_1011_10111201_11_dialog_content = "E...",
  ui_story_1011_10111201_12_dialog_content = "Como comandar o Eclipsite dentro do Colossus.",
  ui_story_1011_10111201_13_dialog_content = "Comandar o Eclipse!?",
  ui_story_1011_10111201_13X1_dialog_content = "Sim... Ele me disse que Caelestites e Colossi eram máquinas de guerra...",
  ui_story_1011_10111201_14_dialog_content = "Como isso é possível?",
  ui_story_1011_10111201_15_dialog_content = "Carleen, você acha isso...",
  ui_story_1011_10111201_16_dialog_content = "Estou surpreso também, mas... Realmente não temos informações suficientes para fazer qualquer tipo de julgamento.",
  ui_story_1011_10111201_17_dialog_content = "Quero dizer, este lugar é antigo, o mundo era diferente naquela época.",
  ui_story_1011_10111201_18_dialog_content = "Não sabemos o que aconteceu naquela época e não podemos confirmar a autenticidade da mensagem.",
  ui_story_1011_10111201_19_dialog_content = "Sério?",
  ui_story_1011_10111201_20_dialog_content = "Mas, se os celestitas realmente comandaram os eclipsitas.",
  ui_story_1011_10111201_21_dialog_content = "O que isso faz de mim? Como eu me vejo...",
  ui_story_1011_10111201_22_dialog_content = "Poderia Schummer... estar certo, afinal?",
  ui_story_1011_10111201_23_dialog_content = "Você pode pensar na mensagem e no que ela significa, mas não se deixe influenciar por ela.",
  ui_story_1011_10111201_24_dialog_content = "O que você experimentou e como você pensa é o que mais importa, não é mesmo?",
  ui_story_1011_10111201_25_dialog_content = "As coisas que você passou com os Soroz são reais.",
  ui_story_1011_10111201_26_dialog_content = "E todos que lutaram lado a lado com você são reais.",
  ui_story_1011_10111201_27_dialog_content = "Não se preocupe em como você deve se ver.",
  ui_story_1011_10111201_28_dialog_content = "Eu, Vice, e todos que não estão presentes...",
  ui_story_1011_10111201_29_dialog_content = "Você sempre terá um lugar conosco.",
  ui_story_1011_10111201_30_dialog_content = "Certo... eu...",
  ui_story_1011_10111201_31_dialog_content = "Carleen... Muito obrigado...",
  ui_story_1011_10111201_32_dialog_content = "Hmm... Você não tem que ficar tão emocional.",
  ui_story_1011_10111201_33_dialog_content = "Você tem razão. Vocês são todos reais.",
  ui_story_1011_10111201_34_dialog_content = "E encontrar uma maneira de acordar Vice up é o que é importante agora.",
  ui_story_1011_10111201_35_dialog_content = "Eu preciso tentar novamente.",
  ui_story_1011_10111201_36_dialog_content = "Por que você não faz uma pausa?",
  ui_story_1011_10111201_37_dialog_content = "A vinculação com o Sistema Circular parece realmente desgastante.",
  ui_story_1011_10111201_38_dialog_content = "Eu estou bem.",
  ui_story_1011_10111201_39_dialog_content = "Acho que encontrei uma maneira de controlá-lo.",
  ui_story_1011_10111201_40_option_content = "Controle forçado!",
  ui_story_1011_10111201_41_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_1011_10111201_42_dialog_content = "Eu posso sentir minha consciência se movendo ali.",
  ui_story_1011_10111201_43_dialog_content = "Acho que todas as informações armazenadas aqui podem ter criado um espaço virtual.",
  ui_story_1011_10111201_44_dialog_content = "E posso navegar por este espaço através da minha consciência.",
  ui_story_1011_10111201_45_dialog_content = "Na minha tentativa, ainda estava pensando na experiência anterior, então entrei na palestra para os celestitas.",
  ui_story_1011_10111201_46_dialog_content = "Desta vez, eu vou controlá-lo...",
  ui_story_1011_10111201_47_dialog_content = "E encontrar uma maneira de acordar Vice acima.",
  ui_story_1011_10111201_48_dialog_content = "Devo focar minha mente na hibernação...",
  ui_story_1011_10111201_49_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_1011_10111201_50_dialog_content = "D-Funcionou?",
  ui_story_1011_10111201_51_dialog_content = "Dados de teste, código...",
  ui_story_1011_10111201_52_dialog_content = "Acesso... alterado para irrestrito. Acessível a todos...",
  ui_story_1011_10111201_53_dialog_content = "Modificado por: Francisco.",
  ui_story_1011_10111201_54_dialog_content = "Francisco... Este nome de novo.",
  ui_story_1011_10111201_55_dialog_content = "Parece que esta mensagem está seriamente danificada. Espero ainda encontrar algumas pistas.",
  ui_story_1011_10111201_56_dialog_content = "Assunto... Falha ao recuperar da hibernação. Físico... O sinal de vida desapareceu.",
  ui_story_1011_10111201_57_dialog_content = "Assunto... Falha ao recuperar da hibernação... Exibindo... Sinal de vida...",
  ui_story_1011_10111201_58_dialog_content = "Assunto... Falha... Recuperar... Experimentar...",
  ui_story_1011_10111201_59_dialog_content = "Que tipo de experimentos são esses?",
  ui_story_1011_10111201_60_dialog_content = "Os dados de teste... Isso é inquietante.",
  ui_story_1011_10111201_61_dialog_content = "Assunto... Falha... Recuperar... Nenhuma outra anormalidade.",
  ui_story_1011_10111201_62_dialog_content = "Assunto... Falha ao recuperar da hibernação. Nenhum outro...",
  ui_story_1011_10111201_63_dialog_content = "Assunto... Falha...",
  ui_story_1011_10111201_64_dialog_content = "Todos eles foram...",
  ui_story_1011_10111201_65_dialog_content = "Experiências...",
  ui_story_1011_10111201_66_dialog_content = "...",
  ui_story_1011_10111201_67_dialog_content = "Ainda assim, muitos dados são perdidos ...",
  ui_story_1011_10111201_68_dialog_content = "... Última tentativa ... combinada com ...",
  ui_story_1011_10111201_69_dialog_content = "Sujeito...",
  ui_story_1011_10111201_70_dialog_content = "Observado... mudanças físicas...",
  ui_story_1011_10111201_71_dialog_content = "...",
  ui_story_1011_10111201_72_dialog_content = "... recuperado com sucesso da hibernação.",
  ui_story_1011_10111201_73_dialog_content = "?!",
  ui_story_1011_10111201_74_dialog_content = "Um sucesso!",
  ui_story_1011_10111201_75_dialog_content = "O que é esse experimento? Cadê?",
  ui_story_1011_10111201_76_dialog_content = "Eu preciso de mais informações. Eu tenho que mergulhar mais fundo.",
  ui_story_1011_10111201_77_dialog_content = "Cuidado: informações de destino... acesso restrito...",
  ui_story_1011_10111201_78_dialog_content = "Acesso... encerrado.",
  ui_story_1011_10111201_79_dialog_content = "Ugh... eu não posso inspecioná-lo...",
  ui_story_1011_10111201_80_dialog_content = "Então? Encontrou alguma coisa?",
  ui_story_1011_10111201_81_dialog_content = "Sim. Encontrei um conjunto de dados de teste.",
  ui_story_1011_10111201_82_dialog_content = "Ele tem os registros de um sujeito que se recuperou com sucesso da hibernação.",
  ui_story_1011_10111201_83_dialog_content = "Mas não sei qual foi o experimento nem onde ocorreu.",
  ui_story_1011_10111201_84_dialog_content = "E há apenas um caso de sucesso.",
  ui_story_1011_10111201_85_dialog_content = "Não vimos nenhum equipamento de teste intacto ao longo do caminho.",
  ui_story_1011_10111201_86_dialog_content = "Só podemos esperar que esteja em algum lugar mais profundo e ainda esteja operacional.",
  ui_story_1011_10111201_87_dialog_content = "E vamos ter que arriscar.",
  ui_story_1011_10111201_88_dialog_content = "Você tem razão. É tudo o que podemos fazer.",
  ui_story_1011_10111201_89_dialog_content = "Vem então. Vamos mais fundo.",
  ui_story_1011_10111201_90_dialog_content = "Mesmo que não consigamos encontrar o equipamento de teste, ainda podemos encontrar outras pistas.",
  ui_story_1011_10111201_91_dialog_content = "Quem sabe quantos segredos esse lugar esconde.",
  ui_story_1011_10111201_92_dialog_content = "<color=#e8d9bb>Ta... ta... ta...</color>",
  ui_story_1011_10111201_93_dialog_content = "O \"Obelisco do Retorno\"...",
  ui_story_1011_10111201_94_dialog_content = "Olhando para trás, só agora percebemos que estávamos explorando dentro da torre.",
  ui_story_1011_10111201_95_dialog_content = "Não há como saber se as instalações subterrâneas e a torre acima do solo são da mesma estrutura.",
  ui_story_1011_10111201_96_dialog_content = "Eles se sentem como dois lugares distintamente diferentes.",
  ui_story_1011_10111201_97_dialog_content = "A Torre Branca está em Eraveil há muito tempo. Estamos todos familiarizados com isso.",
  ui_story_1011_10111201_98_dialog_content = "Mesmo não poderia ser dito para as ruínas subterrâneas. É algo completamente estranho.",
  ui_story_1011_10111201_99_dialog_content = "A conexão entre os dois... É você...",
  ui_story_1011_10111201_100_dialog_content = "Os celestitas.",
  ui_story_1011_10111201_101_dialog_content = "...",
  ui_story_1011_10111201_102_dialog_content = "Mesmo que os tempos e tudo tenham mudado, os celestitas ainda vivem sob o mesmo céu.",
  ui_story_1011_10111201_103_dialog_content = "Sem dúvida, isso é um monumento em si.",
  ui_story_1011_10111201_104_dialog_content = "Nunca senti nada remotamente parecido quando estava em Northland, o berço dos aurorianos.",
  ui_story_1011_10111201_105_dialog_content = "\"Monumento\"... é isso?",
  ui_story_1011_10111201_106_dialog_content = "Essa é uma palavra pesada para suportar...",
  ui_story_1011_10111201_107_dialog_content = "Hã?",
  ui_story_1011_10111201_108_dialog_content = "Eu sou o único a carregar o peso deste \"monumento\" agora...",
  ui_story_1011_10111201_109_dialog_content = "PlayerName...",
  ui_story_1011_10111201_110_dialog_content = "Deixa para lá. Não é hora de pensar nisso.",
  ui_story_1011_10111201_111_dialog_content = "Pelo lado positivo, isso significa que sou o único sucessor de toda essa estrutura.",
  ui_story_1011_10111201_112_dialog_content = "Então... Tudo aqui me pertence agora, certo?",
  ui_story_1011_10111201_113_dialog_content = "Hehehe.",
  ui_story_1011_10111201_114_dialog_content = "Você tem razão. Você é seu legítimo proprietário agora.",
  ui_story_1011_10111201_115_dialog_content = "Isso é tão bom. Nunca terei que passar fome, tendo tantas antiguidades e relíquias à minha disposição.",
  ui_story_1011_10111201_116_dialog_content = "eu vou rasgar Vicelivro de contas!",
  ui_story_1011_10111201_117_dialog_content = "eu vou ter certeza de dar Vice a mensagem.",
  ui_story_1011_10111201_118_dialog_content = "Ei... Não vamos...",
  ui_story_1011_10111201_119_dialog_content = "<color=#e8d9bb>Tzzzz... Tzzzz...</color>",
  ui_story_1011_10111201_120_dialog_content = "Acho que ouvi algo esfregando um contra o outro.",
  ui_story_1011_10111201_121_dialog_content = "Poderia ser algum tipo de mecanismo em ação aqui?",
  ui_story_1011_10111201_122_dialog_content = "Isso é possível.",
  ui_story_1011_10111201_123_dialog_content = "Não posso deixar de me perguntar, como ele permanece operacional depois de ser abandonado por tanto tempo?",
  ui_story_1011_10111201_124_dialog_content = "Estamos falando de alguns milênios... Energia, desgaste... Eu realmente não consigo entender isso.",
  ui_story_1011_10111201_125_dialog_content = "Pode ser um grande problema para nós, mas não necessariamente para quem criou este lugar.",
  ui_story_1011_10111201_126_dialog_content = "Eles parecem ter uma abordagem muito diferente para os problemas.",
  ui_story_1011_10111201_127_dialog_content = "Isso é verdade.",
  ui_story_1011_10111201_128_dialog_content = "Vamos nos aproximar e encontrar a fonte desse som.",
  ui_story_1011_10111201_129_dialog_content = "Uhum.",
  ui_story_1011_10111201_130_dialog_content = "<color=#e8d9bb>Tzzzz... Tzzzz...</color>",
  ui_story_1011_10111201_131_dialog_content = "Espere aí!",
  ui_story_1011_10111201_132_dialog_content = "O que foi?",
  ui_story_1011_10111201_133_dialog_content = "Acho que senti.",
  ui_story_1011_10111201_134_dialog_content = "<color=#e8d9bb>Tzzzz... Tzzzz...</color>",
  ui_story_1011_10111201_135_dialog_content = "...",
  ui_story_1011_10111201_136_dialog_content = "Eclipses?!",
  ui_story_1011_10111201_137_dialog_content = "Aqui também?",
  ui_story_1011_10111201_138_dialog_content = "Estranho. Eles devem ter nos visto. Mas por que eles não estão reagindo?",
  ui_story_1011_10111201_139_dialog_content = "...",
  ui_story_1011_10111201_140_dialog_content = "Olhar! O que eles estão fazendo?",
  ui_story_1011_10111201_141_dialog_content = "<color=#e8d9bb>Tzzzz... Tzzzz...</color>",
  ui_story_1011_10111201_142_dialog_content = "Eles estão... empurrando os comprimidos?",
  ui_story_1011_10111201_143_dialog_content = "Porque eles estão fazendo aquilo?",
  ui_story_1011_10111201_144_dialog_content = "Nunca vi Eclipses assim.",
  ui_story_1011_10111201_145_dialog_content = "É difícil encontrar significado no que eles estão fazendo...",
  ui_story_1011_10111201_145X1_dialog_content = "Eles estão seguindo a ordem de um Eclipsite de alto nível?",
  ui_story_1011_10111201_145X2_dialog_content = "Não. Não faz sentido nenhum Eclipsite empurrar os tablets.",
  ui_story_1011_10111201_145X3_dialog_content = "No entanto... é uma história completamente diferente para os celestitas...",
  ui_story_1011_10111201_147_dialog_content = "Como assim?",
  ui_story_1011_10111201_148_dialog_content = "Estávamos falando sobre como tudo aqui continua operacional, não estávamos?",
  ui_story_1011_10111201_149_dialog_content = "Encontramos nossa resposta.",
  ui_story_1011_10111201_150_dialog_content = "Quer dizer, os Eclipses?",
  ui_story_1011_10111201_151_dialog_content = "É uma hipótese.",
  ui_story_1011_10111201_152_dialog_content = "Ver? Eles continuam empurrando os tablets e optaram por nos ignorar completamente.",
  ui_story_1011_10111201_153_dialog_content = "São como as correntes que acionam as engrenagens... Fazem parte do mecanismo.",
  ui_story_1011_10111201_154_dialog_content = "<color=#e8d9bb>Tzzzz... Tzzzz...</color>",
  ui_story_1011_10111201_155_dialog_content = "Como isso é possível...",
  ui_story_1011_10111201_156_dialog_content = "Parece que o que eu vi no Sistema Circular é verdade.",
  ui_story_1011_10111201_157_dialog_content = "O antigo celestita poderia de alguma forma comandar os eclipsitas...",
  ui_story_1011_10111201_158_dialog_content = "Como eles fizeram isso?",
  ui_story_1011_10111201_159_dialog_content = "Usando o mindlink, talvez?",
  ui_story_1011_10111201_160_dialog_content = "Este lugar foi abandonado há muito tempo, mas os Eclipsitas ainda estão seguindo seu comando.",
  ui_story_1011_10111201_161_dialog_content = "Espere. Parece ser um beco sem saída.",
  ui_story_1011_10111201_162_dialog_content = "Você tem razão. Esse é o fim.",
  ui_story_1011_10111201_163_dialog_content = "Parece que não tem nada aqui. Apenas um espaço aberto.",
  ui_story_1011_10111201_164_dialog_content = "Há uma plataforma de pedra no meio. Vamos verificar.",
  ui_story_1011_10111201_165_dialog_content = "Os Eclipsites devem estar empurrando os tablets para dirigir alguma coisa.",
  ui_story_1011_10111201_166_dialog_content = "Mas é apenas uma plataforma de pedra.",
  ui_story_1011_10111201_167_dialog_content = "Há algum interruptor ou algo nas laterais?",
  ui_story_1011_10111201_168_dialog_content = "*Tosse* Está tão empoeirado...",
  ui_story_1011_10111201_169_dialog_content = "Que tal usar suas habilidades psíquicas?",
  ui_story_1011_10111201_170_dialog_content = "Já fiz. Nada mesmo.",
  ui_story_1011_10111201_171_dialog_content = "É realmente apenas um pedaço de pedra.",
  ui_story_1011_10111201_172_dialog_content = "Como isso pode ser?",
  ui_story_1011_10111201_173_dialog_content = "Ou talvez, algo já esteve aqui.",
  ui_story_1011_10111201_174_dialog_content = "Mas já se desfez e se foi.",
  ui_story_1011_10111201_175_dialog_content = "Isso é possível, já que tudo nas ruínas está em estado de colapso.",
  ui_story_1011_10111201_176_dialog_content = "Até aquela enorme porta de pedra murchou e rachou. Coisas feitas de outros materiais devem ter...",
  ui_story_1011_10111201_177_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_1011_10111201_178_dialog_content = "Solicitação de login detectada.",
  ui_story_1011_10111201_179_dialog_content = "É Neural Aux!",
  ui_story_1011_10111201_180_dialog_content = "Algo ativado. O que você fez, PlayerName?",
  ui_story_1011_10111201_181_dialog_content = "Eu... eu não fiz nada!",
  ui_story_1011_10111201_182_dialog_content = "Eu ia te perguntar a mesma coisa!",
  ui_story_1011_10111201_183_dialog_content = "Verificação de identidade necessária.",
  ui_story_1011_10111201_184_dialog_content = "Insira a identidade do usuário.",
  ui_story_1011_10111201_185_dialog_content = "Identidade? Minha?",
  ui_story_1011_10111201_186_dialog_content = "Meu nome é PlayerName.",
  ui_story_1011_10111201_187_dialog_content = "Verificação de identidade necessária.",
  ui_story_1011_10111201_188_dialog_content = "Insira a identidade do usuário.",
  ui_story_1011_10111201_189_dialog_content = "Huh? Eu disse, meu nome éPlayerName... Isso não vai fazer isso?",
  ui_story_1011_10111201_190_dialog_content = "Provavelmente não pode encontrá-lo em seu banco de dados, PlayerName.",
  ui_story_1011_10111201_191_dialog_content = "Então o que vamos fazer?",
  ui_story_1011_10111201_192_dialog_content = "Não existe um celestita chamado Francisco?",
  ui_story_1011_10111201_193_dialog_content = "Tente usar o nome dele?",
  ui_story_1011_10111201_194_dialog_content = "Entrada de identidade detectada: Pa... la... pong.",
  ui_story_1011_10111201_195_dialog_content = "Eh? Que tipo de nome é esse? Eu não disse nada disso!",
  ui_story_1011_10111201_196_dialog_content = "Verificando identidade.",
  ui_story_1011_10111201_197_dialog_content = "Bip... Bip... Bip...",
  ui_story_1011_10111201_198_dialog_content = "Existe alguém que atende por esse tipo de nome ridículo?",
  ui_story_1011_10111201_199_dialog_content = "Apenas desista já, Neural Aux. Você pode primeiro nos dizer que lugar é este?",
  ui_story_1011_10111201_200_dialog_content = "Espere, PlayerName!",
  ui_story_1011_10111201_201_dialog_content = "Olhar...",
  ui_story_1011_10111201_202_dialog_content = "O que foi?",
  ui_story_1011_10111201_203_dialog_content = "...",
  ui_story_1011_10111201_204_dialog_content = "Umm... Por que os Eclipsitas pararam de empurrar as tábuas?",
  ui_story_1011_10111201_205_dialog_content = "Não é possível...",
  ui_story_1011_10111201_206_dialog_content = "Graaaah!!",
  ui_story_1011_10111201_207_dialog_content = "Carleen!",
  ui_story_1011_10111201_208_dialog_content = "Dispersem, pétalas de gelo!",
  ui_story_1011_10111401_1_dialog_content = "Felizmente, eles não são grandes em número.",
  ui_story_1011_10111401_2_dialog_content = "Caso contrário, ficaríamos sobrecarregados.",
  ui_story_1011_10111401_3_dialog_content = "Uhum.",
  ui_story_1011_10111401_4_dialog_content = "O que há com Neural Aux? Parece mais morte cerebral do que antes.",
  ui_story_1011_10111401_5_dialog_content = "Ei, Auxiliar Neural. Você pode me ouvir?",
  ui_story_1011_10111401_6_dialog_content = "Responder! O que está acontecendo?",
  ui_story_1011_10111401_7_dialog_content = "Falha na verificação de identidade. Nome de usuário ilegal: Palapong.",
  ui_story_1011_10111401_8_dialog_content = "Por favor, envie um nome de usuário válido ou cancele o login.",
  ui_story_1011_10111401_9_dialog_content = "Que diabos... Ele nem escuta!",
  ui_story_1011_10111401_10_dialog_content = "Você não sente que está te tratando de forma diferente agora...?",
  ui_story_1011_10111401_11_dialog_content = "Anteriormente, ele tentou responder às suas perguntas ...",
  ui_story_1011_10111401_12_dialog_content = "Mas agora, está apenas aguardando sua entrada de comando.",
  ui_story_1011_10111401_13_dialog_content = "Eu acho que você está certo...",
  ui_story_1011_10111401_14_dialog_content = "Mas por quê?",
  ui_story_1011_10111401_15_dialog_content = "É por causa de onde estamos agora?",
  ui_story_1011_10111401_16_dialog_content = "Talvez este lugar seja onde seus comandos são inseridos.",
  ui_story_1011_10111401_17_dialog_content = "Você acha?",
  ui_story_1011_10111401_18_dialog_content = "Neural Aux, cancele o login.",
  ui_story_1011_10111401_19_dialog_content = "Pedido de reativação do Obelisco de Retorno recebido.",
  ui_story_1011_10111401_20_dialog_content = "Pedido de: Palapong. Identidade ilegal.",
  ui_story_1011_10111401_21_dialog_content = "Aviso: A operação continuada ativará o <color=#FFB400>Sistema Guardião</color>.",
  ui_story_1011_10111401_22_dialog_content = "Ver! Está fazendo de novo!",
  ui_story_1011_10111401_23_dialog_content = "Palapong está se referindo a mim? Não pedi nada de reativação!",
  ui_story_1011_10111401_24_dialog_content = "Se não pensarmos muito nisso...",
  ui_story_1011_10111401_25_dialog_content = "A resposta mais simples é que: Está quebrado.",
  ui_story_1011_10111401_26_dialog_content = "Quebrado? Auxiliar Neural?",
  ui_story_1011_10111401_27_dialog_content = "Não. O receptor de comando está quebrado.",
  ui_story_1011_10111401_28_dialog_content = "Você já tentou usar o rádio da Illumina?",
  ui_story_1011_10111401_29_dialog_content = "Quando está quebrado, faz aqueles barulhos \"pzaaazzzz\".",
  ui_story_1011_10111401_30_dialog_content = "Parece um pouco semelhante ao nome que o Neural Aux continua repetindo.",
  ui_story_1011_10111401_31_dialog_content = "Então estamos com sérios problemas.",
  ui_story_1011_10111401_32_dialog_content = "O pedido de reativação do Obelisco do Retorno foi confirmado.",
  ui_story_1011_10111401_33_dialog_content = "Aviso: O Sistema Guardian está prestes a ser ativado. Por favor, cancele o pedido.",
  ui_story_1011_10111401_34_dialog_content = "Cancelar! Cancele agora!",
  ui_story_1011_10111401_35_dialog_content = "E eu nem fiz o pedido!",
  ui_story_1011_10111401_36_dialog_content = "Atenção: Usuário ilegal ativou a sequência de reativação do Obelisco de Retorno à força.",
  ui_story_1011_10111401_37_dialog_content = "Recuperando a sequência de reativação do Obelisco de Retorno do Sistema Circular.",
  ui_story_1011_10111401_38_dialog_content = "Bip... Bip... Bip...",
  ui_story_1011_10111401_39_dialog_content = "Tenho a sensação de que algo ruim vai acontecer.",
  ui_story_1011_10111401_40_dialog_content = "Mesmo aqui. Existe alguma maneira de parar isso agora?",
  ui_story_1011_10111401_41_dialog_content = "Que tal quebrarmos seu transceptor completamente?",
  ui_story_1011_10111401_42_dialog_content = "Funcionando assim... Podemos destruí-lo.",
  ui_story_1011_10111401_43_dialog_content = "Não sei onde está. A plataforma de pedra?",
  ui_story_1011_10111401_44_dialog_content = "Acho que vamos descobrir... Aqui vai!",
  ui_story_1011_10111401_45_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1011_10111401_46_dialog_content = "Ai! Isso machuca!",
  ui_story_1011_10111401_47_dialog_content = "É feito de pedra! Qual é o ponto de dar-lhe um pontapé?",
  ui_story_1011_10111401_48_dialog_content = "Atenção: Usuário ilegal ativou a sequência de reativação do Obelisco de Retorno à força.",
  ui_story_1011_10111401_49_dialog_content = "Módulo de energia recuperado. Comece a carregar módulos de fonte de alimentação adicionais.",
  ui_story_1011_10111401_50_dialog_content = "Bip... Bip... Bip...",
  ui_story_1011_10111401_51_dialog_content = "Carleen... Você sente algo retumbando abaixo de nós?",
  ui_story_1011_10111401_52_dialog_content = "Sim...",
  ui_story_1011_10111401_53_dialog_content = "Dizia \"A sequência de reativação do Obelisco do Retorno\". Alguma coisa deve estar acontecendo com toda a estrutura.",
  ui_story_1011_10111401_54_dialog_content = "Toda a estrutura? Isso soa assustador.",
  ui_story_1011_10111401_55_dialog_content = "Não é com isso que devemos nos preocupar agora.",
  ui_story_1011_10111401_56_dialog_content = "O \"aviso\" que continua nos lembrando... Acho que não devemos simplesmente descartá-lo.",
  ui_story_1011_10111401_57_dialog_content = "Atenção: Usuário ilegal ativou a sequência de reativação do Obelisco de Retorno à força.",
  ui_story_1011_10111401_58_dialog_content = "Acesso restrito detectado. A medida de correção está prestes a ser lançada.",
  ui_story_1011_10111401_59_dialog_content = "Este é o seu último aviso. Cancele imediatamente o seu pedido.",
  ui_story_1011_10111401_60_dialog_content = "Eu disse para você cancelar!",
  ui_story_1011_10111401_61_dialog_content = "Me dá um tempo! Cancele!",
  ui_story_1011_10111401_62_dialog_content = "Não estou interessado em enfrentar uma tecnologia antiga!",
  ui_story_1011_10111401_64_dialog_content = "Pedido ilegal ainda em andamento.",
  ui_story_1011_10111401_65_dialog_content = "Medida de correção pronta para lançamento.",
  ui_story_1011_10111401_66_dialog_content = "Foda-se, Neural Aux!",
  ui_story_1011_10111401_67_dialog_content = "Ativando o \"Sistema Guardião\". Lançamento Claudia.",
  ui_story_1011_10111401_68_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1011_10111401_69_dialog_content = "O que é isto...?",
  ui_story_1011_10111401_70_dialog_content = "Uma estátua? Uma máquina?",
  ui_story_1011_10111401_71_dialog_content = "Ele pode se mover...?",
  ui_story_1011_10111401_72_dialog_content = "Deve estar... quebrado...",
  ui_story_1011_10111401_73_dialog_content = "<color=#e8d9bb>Clique... Clique...</color>",
  ui_story_1011_10111401_74_dialog_content = "Parece assim.",
  ui_story_1011_10111401_75_dialog_content = "PlayerName, prepare-se para uma luta!",
  ui_story_1011_10111401_76_dialog_content = "Ei Neural Aux... é tarde demais para falar sobre isso?",
  ui_story_1011_10111401_77_dialog_content = "\"Sistema Guardian\" iniciou o processo de correção.",
  ui_story_1011_10111401_78_dialog_content = "Corrigindo comandos ilegais, ou \no usuário ilegal.",
  ui_story_1011_10111402_1_dialog_content = "Que cara duro.",
  ui_story_1011_10111402_2_dialog_content = "Pode combater Luminatics.",
  ui_story_1011_10111402_3_dialog_content = "Não vamos sair dessa tão cedo.",
  ui_story_1011_10111402_4_dialog_content = "Você pode esperar, Carleen?",
  ui_story_1011_10111402_5_dialog_content = "Estou bem, mas...",
  ui_story_1011_10111402_6_dialog_content = "Vice está deitado bem ao meu lado. Estou preocupado com ela.",
  ui_story_1011_10111402_7_dialog_content = "Existe alguma maneira de acabar com esta batalha rapidamente?",
  ui_story_1011_10111402_8_dialog_content = "Iniciando o autodiagnóstico nas instalações do Obelisco do Retorno.",
  ui_story_1011_10111402_9_dialog_content = "Aviso: Dano crítico. A maioria das áreas não funciona.",
  ui_story_1011_10111402_10_dialog_content = "\"Programa de controle de danos\" ativado. Tentando reparos.",
  ui_story_1011_10111402_11_dialog_content = "!!!",
  ui_story_1011_10111402_12_dialog_content = "Carleen, parou!",
  ui_story_1011_10111402_13_dialog_content = "Agora! Vá para as costas dele!",
  ui_story_1011_10111402_14_dialog_content = "Entendido!",
  ui_story_1011_10111402_15_dialog_content = "Sistema Guardião ainda ativo.",
  ui_story_1011_10111402_16_dialog_content = "Pular programa. Continue o comando de reparo.",
  ui_story_1011_10111402_17_dialog_content = "Bip... Bip... Bip...",
  ui_story_1011_10111402_18_dialog_content = "<color=#e8d9bb>Clique!</color>",
  ui_story_1011_10111402_19_dialog_content = "Carleen, está se movendo novamente! Tome cuidado!",
  ui_story_1011_10111402_20_dialog_content = "É tudo que eu preciso.",
  ui_story_1011_10111402_21_dialog_content = "Tecnologia antiga, conheça os Luminatics do futuro!",
  ui_story_1011_10111402_22_dialog_content = "Ufa... Conseguimos?",
  ui_story_1011_10111402_23_dialog_content = "Sim, está baixo.",
  ui_story_1011_10111402_24_dialog_content = "Não desista.",
  ui_story_1011_10111402_25_dialog_content = "Vimos as capacidades defensivas do Obelisco do Retorno.",
  ui_story_1011_10111402_26_dialog_content = "Agora que somos considerados hostis, pode haver mais por vir.",
  ui_story_1011_10111402_27_dialog_content = "Não posso ser...?",
  ui_story_1011_10111402_28_dialog_content = "Eu realmente espero que não guarde rancor.",
  ui_story_1011_10111402_29_dialog_content = "Ding! Dong...",
  ui_story_1011_10111402_30_dialog_content = "Reparos do Programa de Controle de Danos concluídos. Principais funções reparadas.",
  ui_story_1011_10111402_31_dialog_content = "O Obelisco do Retorno agora está reativado.",
  ui_story_1011_10111402_32_dialog_content = "Hum? Alguma coisa enorme acabou de acontecer sem que percebamos...?",
  ui_story_1011_10111402_33_dialog_content = "Obelisco de Sistemas de Energia de Retorno: Restaurado.",
  ui_story_1011_10111402_34_dialog_content = "Obelisco de Sistemas de Transmissão de Retorno: Restaurado.",
  ui_story_1011_10111402_35_dialog_content = "Obelisco do Retorno Sistemas Sensoriais: Restaurado.",
  ui_story_1011_10111402_36_dialog_content = "<color=#e8d9bb>Clique... Clique... Clique... Clique...</color>",
  ui_story_1011_10111402_37_dialog_content = "Ouço, Carleen! A torre está ganhando vida em todos os lugares ao nosso redor!",
  ui_story_1011_10111402_38_dialog_content = "Está funcionando... A torre inteira está funcionando agora!",
  ui_story_1011_10111402_39_dialog_content = "Isto é incrível.",
  ui_story_1011_10111402_40_dialog_content = "Não está morto... Simplesmente...",
  ui_story_1011_10111402_41_dialog_content = "...teve um longo sono.",
  ui_story_1011_10111402_42_dialog_content = "Relatório de situação da torre.",
  ui_story_1011_10111402_43_dialog_content = "Colossus Maintenance Zone - Colossus Quantidade: 1. Status: Reparos necessários.",
  ui_story_1011_10111402_44_dialog_content = "Armazenamento de Componentes Colossus: Danificado. Os reparos falharam.",
  ui_story_1011_10111402_45_dialog_content = "Sala de Produção de Recursos - Quantidade de Pessoal: 0",
  ui_story_1011_10111402_46_dialog_content = "Instalação de Descarte de Resíduos - Quantidade de Pessoal: 0",
  ui_story_1011_10111402_47_dialog_content = "Caelestite Residencial - Quantidade de Pessoal: 0",
  ui_story_1011_10111402_48_dialog_content = "Zona Exilada - Quantidade de Pessoal: 0",
  ui_story_1011_10111402_49_dialog_content = "...",
  ui_story_1011_10111402_50_dialog_content = "Não há mais celestitas, exceto...",
  ui_story_1011_10111402_51_dialog_content = "Núcleo Central - Quantidade de Pessoal: 1",
  ui_story_1011_10111402_52_dialog_content = "Sim. Eu.",
  ui_story_1011_10111402_53_dialog_content = "Despertou de seu sono.",
  ui_story_1011_10111402_54_dialog_content = "Mas... pode se acostumar com a solidão?",
  ui_story_1011_10111402_55_dialog_content = "Sequência de reinicialização iniciada.",
  ui_story_1011_10111402_56_dialog_content = "O Obelisco do Retorno subirá mais uma vez.",
  ui_story_1011_10111402_57_dialog_content = "Você não teve o suficiente?",
  ui_story_1011_10111402_58_dialog_content = "Aff... aff...",
  ui_story_1011_10111402_59_dialog_content = "Ei! Não desista de mim!",
  ui_story_1011_10111402_60_dialog_content = "Não é uma batalha real até que um de nós caia!",
  ui_story_1011_10111402_61_dialog_content = "Você está sozinho. Você está destinado a falhar.",
  ui_story_1011_10111402_62_dialog_content = "Esta não é uma batalha. Você está apenas fazendo birra.",
  ui_story_1011_10111402_63_dialog_content = "(Ela realmente não desiste. Como ela é terrivelmente forte.)",
  ui_story_1011_10111402_64_dialog_content = "(A única razão pela qual consegui aguentar tanto tempo é que ela está preocupada.)",
  ui_story_1011_10111402_65_dialog_content = "(Mas o que está em sua mente? O que há nesta torre que significa tanto para ela?)",
  ui_story_1011_10111402_66_dialog_content = "(Esqueça. É improvável que eu consiga descobrir a resposta tão cedo.)",
  ui_story_1011_10111402_67_dialog_content = "(A única coisa que preciso saber é que tenho que impedir meu oponente de fazer o que ele quer fazer.)",
  ui_story_1011_10111402_68_dialog_content = "(Um soldado não pode se acovardar só porque o inimigo é poderoso!)",
  ui_story_1011_10111402_69_dialog_content = "Aqui, Forsakin!",
  ui_story_1011_10111402_70_dialog_content = "Você não vai me enganar com táticas como essa!",
  ui_story_1011_10111402_71_dialog_content = "<color=#e8d9bb>Cabuum!</color>",
  ui_story_1011_10111402_72_dialog_content = "<color=#e8d9bb>*Rubos*</color>",
  ui_story_1011_10111402_73_dialog_content = "Ei... O que está acontecendo? Um terremoto?",
  ui_story_1011_10111402_74_dialog_content = "Oh vamos lá! Estamos no meio de uma batalha!",
  ui_story_1011_10111402_75_dialog_content = "Espere... Este não é um terremoto comum.",
  ui_story_1011_10111402_76_dialog_content = "Esta torre...",
  ui_story_1011_10111402_77_dialog_content = "A torre inteira está se movendo.",
  ui_story_1011_10111402_78_dialog_content = "Toda a fumaça! *COF cof*",
  ui_story_1011_10111402_79_dialog_content = "<color=#e8d9bb>*Rubos*</color>",
  ui_story_1011_10111402_80_dialog_content = "Sagrado...!",
  ui_story_1011_10111402_81_dialog_content = "Isso é muito pior do que um terremoto!",
  ui_story_1011_10111402_82_dialog_content = "Claro que é!",
  ui_story_1011_10111402_83_dialog_content = "O que estamos prestes a testemunhar provavelmente só acontece uma vez por milênio ou mais...",
  ui_story_1011_10111402_84_dialog_content = "Esta Torre Branca nunca deveria estar aqui.",
  ui_story_1011_10111402_85_dialog_content = "Deve ser... em algum lugar muito mais alto.",
  ui_story_1011_10111402_86_dialog_content = "<color=#e8d9bb>*Rubos*</color>",
  ui_story_1011_10111402_87_dialog_content = "O QUE!?",
  ui_story_1011_10111402_88_dialog_content = "Estou tropeçando? A torre massiva... acabou de se erguer do chão!?",
  ui_story_1011_10111402_89_dialog_content = "PlayerName! Eles ainda estão lá!",
  ui_story_1011_10111402_90_dialog_content = "O que... eles fizeram?",
  ui_story_1011_10111402_91_dialog_content = "Eu não posso acreditar que realmente existe. Uma estrutura antiga que ainda funciona.",
  ui_story_1011_10111402_92_dialog_content = "Atrás da parede... Estou olhando...",
  ui_story_1011_10111402_93_dialog_content = "Outra época?",
  ui_story_1011_10111402_94_dialog_content = "Então, o que exatamente é essa coisa? Você estudou isso?",
  ui_story_1011_10111402_95_dialog_content = "Eu não preciso te responder.",
  ui_story_1011_10111402_96_dialog_content = "(Eclipsiano) Forsakin... Forsakin!",
  ui_story_1011_10111402_97_dialog_content = "(Eclipsiano) Há uma lacuna na parede externa da Torre Branca.",
  ui_story_1011_10111402_98_dialog_content = "Uma lacuna... Ótimas notícias.",
  ui_story_1011_10111402_99_dialog_content = "Não preciso mais entreter esse lunático.",
  ui_story_1011_10111402_100_dialog_content = "Ei! Você não pode simplesmente se afastar de mim!",
  ui_story_1011_10111402_101_dialog_content = "Ainda não terminamos!",
  ui_story_1011_10111402_101X1_dialog_content = "(Eu aposto PlayerName está fazendo algo muito significativo.)",
  ui_story_1011_10111402_101X2_dialog_content = "(não posso deixar Forsakin perturbá-los. Isso é certeza!)",
  ui_story_1011_10111402_102_dialog_content = "O que está acontecendo! Este é um tremor sério!",
  ui_story_1011_10111402_103_dialog_content = "Pendure-se em algo! E cuidado com os detritos caindo!",
  ui_story_1011_10111402_104_dialog_content = "A respeito Vice!?",
  ui_story_1011_10111402_105_dialog_content = "Deixe-a comigo. Eu vou cuidar dela!",
  ui_story_1011_10111402_106_dialog_content = "<color=#e8d9bb>*Rubos*</color>",
  ui_story_1011_10111402_107_dialog_content = "Ufa... Ufa... Finalmente parou...",
  ui_story_1011_10111402_108_dialog_content = "Você está bem, Carleen?",
  ui_story_1011_10111402_109_dialog_content = "Estou bem. Vice está bem... Quanto a você...",
  ui_story_1011_10111402_110_dialog_content = "Você pode largar essa plataforma de pedra agora.",
  ui_story_1011_10111402_111_dialog_content = "Certo.",
  ui_story_1011_10111402_112_dialog_content = "Então o que aconteceu desta vez?",
  ui_story_1011_10111402_113_dialog_content = "Eu acredito que estávamos subindo agora.",
  ui_story_1011_10111402_114_dialog_content = "Eu penso o mesmo.",
  ui_story_1011_10111402_115_dialog_content = "O Obelisco do Retorno, reposição de posição.",
  ui_story_1011_10111402_116_dialog_content = "Reportando status ao gerente...",
  ui_story_1011_10111402_117_dialog_content = "A torre mudou de posição? É isso que significa \"reiniciar\"?",
  ui_story_1011_10111402_118_dialog_content = "Como isso poderia ser feito?",
  ui_story_1011_10111402_119_dialog_content = "Falha no relatório. Gerente não encontrado.",
  ui_story_1011_10111402_120_dialog_content = "Inicie o procedimento de backup. Localizando o usuário que iniciou o comando reset.",
  ui_story_1011_10111402_121_dialog_content = "Usuário confirmado como usuário ilegal \"Palapong\".",
  ui_story_1011_10111402_122_dialog_content = "Você não vai me dar mais problemas, vai?",
  ui_story_1011_10111402_123_dialog_content = "Procedimento de backup iniciado. Promovendo o usuário \"Palapong\" ao status de gerente.",
  ui_story_1011_10111402_124_dialog_content = "Acesso interno concedido a \"Palapong\".",
  ui_story_1011_10111402_125_dialog_content = "Hã?",
  ui_story_1011_10111402_126_dialog_content = "Eu pensei que era um usuário ilegal, mas agora sou um gerente?",
  ui_story_1011_10111402_127_dialog_content = "O que um gerente pode fazer?",
  ui_story_1011_10111402_128_dialog_content = "O gerente pode controlar a maioria das funções do Obelisco de Retorno através da unidade Neural Aux.",
  ui_story_1011_10111402_129_dialog_content = "Entendo...",
  ui_story_1011_10111402_130_dialog_content = "Espere! Você está falando normalmente comigo de novo!",
  ui_story_1011_10111402_131_dialog_content = "Afirmativo.",
  ui_story_1011_10111402_132_dialog_content = "Então o que foi isso?",
  ui_story_1011_10111402_133_dialog_content = "Os usuários normais só podem inserir comandos no Central Core e não podem interagir com o Neural Aux.",
  ui_story_1011_10111402_134_dialog_content = "Apenas um gerente tem acesso ao Neural Aux a qualquer momento.",
  ui_story_1011_10111402_135_dialog_content = "Oh, eu vejo como você ama uma pessoa no poder.",
  ui_story_1011_10111402_136_dialog_content = "Eu não entendi.",
  ui_story_1011_10111402_137_dialog_content = "Deixa para lá...",
  ui_story_1011_10111402_138_dialog_content = "Mas os comandos... Esses comandos eram completamente imprecisos!",
  ui_story_1011_10111402_139_dialog_content = "Quero dizer, basta olhar para o meu nome de usuário, Palapong? Diga-me como isso é certo!?",
  ui_story_1011_10111402_140_dialog_content = "O sistema de entrada de comando estava com defeito. Este problema já foi reparado.",
  ui_story_1011_10111402_141_dialog_content = "Peço desculpas pelos inconvenientes.",
  ui_story_1011_10111402_142_dialog_content = "Isso não foi apenas meros \"inconveniências\".",
  ui_story_1011_10111402_143_dialog_content = "E o que você quis dizer com \"acesso interno\"?",
  ui_story_1011_10111402_144_dialog_content = "As informações e funções do Obelisco do Retorno são divididas em três níveis de acesso.",
  ui_story_1011_10111402_145_dialog_content = "<color=#FFB400>Anel externo</color> é acessível a usuários normais.",
  ui_story_1011_10111402_146_dialog_content = "<color=#FFB400>Anel Interno</color> é acessível apenas ao gerente.",
  ui_story_1011_10111402_147_dialog_content = "<color=#FFB400>Anel do núcleo</color> é o nível do Decreto Maior, não acessível a nenhum usuário.",
  ui_story_1011_10111402_148_dialog_content = "Em outras palavras, agora tenho todo o acesso, exceto o Core Ring?",
  ui_story_1011_10111402_149_dialog_content = "Afirmativo.",
  ui_story_1011_10111402_150_dialog_content = "Agora você tem acesso ao Anel Interno. Sincronizando você com o Obelisco do Retorno.",
  ui_story_1011_10111402_151_dialog_content = "Eh? O que você vai fazer?",
  ui_story_1011_10111402_152_dialog_content = "Todos esses termos estão me confundindo!",
  ui_story_1011_10111402_153_dialog_content = "Você não precisa ficar confuso. Abra sua mente e conecte-se.",
  ui_story_1011_10111402_154_dialog_content = "O Obelisco do Retorno servirá como seus olhos.",
  ui_story_1011_10111402_155_dialog_content = "O que é isto...?",
  ui_story_1011_10111402_156_dialog_content = "Essa é uma torre enorme! Esse é o Obelisco do Retorno inteiro?",
  ui_story_1011_10111402_157_dialog_content = "Essa... Essa é a entrada da caverna que explodimos.",
  ui_story_1011_10111402_158_dialog_content = "Então fazia parte da Torre Branca!",
  ui_story_1011_10111402_159_dialog_content = "PlayerName, você pode ver o lado de fora da torre?",
  ui_story_1011_10111402_160_dialog_content = "Uhum!",
  ui_story_1011_10111402_161_dialog_content = "Isso é incrível! Parece que estou voando!",
  ui_story_1011_10111402_162_dialog_content = "Você pode ver mais longe.",
  ui_story_1011_10111402_163_dialog_content = "Mais longe... Muito mais longe.",
  ui_story_1011_10111501_1_dialog_content = "Lá! Bem ali!",
  ui_story_1011_10111501_2_dialog_content = "Já verifiquei. Não há nada!",
  ui_story_1011_10111501_3_dialog_content = "Então o que é...",
  ui_story_1011_10111501_4_dialog_content = "Vamos precisar de alguém nisso!",
  ui_story_1011_10111501_5_dialog_content = "Isso não é algo que podemos resolver sozinhos.",
  ui_story_1011_10111501_6_dialog_content = "Certo! Chame a Vigilância Noturna! Chame a Vigilância Noturna!",
  ui_story_1011_10111501_7_dialog_content = "Eles certamente podem lidar com problemas como este!",
  ui_story_1011_10111501_8_dialog_content = "Isso é... Isso é Dâmocles...",
  ui_story_1011_10111501_9_dialog_content = "Nadine, relatório de situação.",
  ui_story_1011_10111501_10_dialog_content = "Sim, Senhor.",
  ui_story_1011_10111501_11_dialog_content = "Nossos guardas relataram irregularidades vindo da direção da Sala de Controle há cerca de dez minutos.",
  ui_story_1011_10111501_12_dialog_content = "Eles não encontraram situações semelhantes. Eles entraram em pânico depois de não identificar os problemas.",
  ui_story_1011_10111501_13_dialog_content = "No entanto, eles chegaram a uma conclusão.",
  ui_story_1011_10111501_14_dialog_content = "<color=#FFB400>Dâmocles</color> está sendo ativado.",
  ui_story_1011_10111501_15_dialog_content = "Dâmocles novamente.",
  ui_story_1011_10111501_16_dialog_content = "Quem está tentando ativá-lo desta vez?",
  ui_story_1011_10111501_17_dialog_content = "Ninguém.",
  ui_story_1011_10111501_18_dialog_content = "?!",
  ui_story_1011_10111501_19_dialog_content = "Os guardas fizeram uma busca minuciosa. Eles não encontraram ninguém.",
  ui_story_1011_10111501_20_dialog_content = "Dâmocles ativado por si mesmo.",
  ui_story_1011_10111501_21_dialog_content = "O que você está pensando?",
  ui_story_1011_10111501_22_dialog_content = "Qual é a situação de Damocles agora?",
  ui_story_1011_10111501_23_dialog_content = "Está executando os procedimentos de inicialização. Está carregando Lumina.",
  ui_story_1011_10111501_24_dialog_content = "Tá. Entendi.",
  ui_story_1011_10111501_25_dialog_content = "Nadine, corte a ligação Lumina entre Damocles e Lumopolis, agora.",
  ui_story_1011_10111501_26_dialog_content = "Não há necessidade de se preocupar com as consequências. Apenas faça.",
  ui_story_1011_10111501_27_dialog_content = "Sim, Senhor.",
  ui_story_1011_10111501_28_dialog_content = "Irridon, pegue seus homens e tranque este lugar. Não deixe ninguém chegar perto da Sala de Controle.",
  ui_story_1011_10111501_29_dialog_content = "Especialmente o Conselho dos Anciões... Como eles adoram nos dar mais dores de cabeça em momentos de dificuldade...",
  ui_story_1011_10111501_30_dialog_content = "Sim, Senhor.",
  ui_story_1011_10111501_31_dialog_content = "Mas estou pensando se devemos confirmar a precisão da informação primeiro.",
  ui_story_1011_10111501_32_dialog_content = "As consequências de cortar Damocles e bloquear a Sala de Controle são enormes.",
  ui_story_1011_10111501_33_dialog_content = "Só se fosse apenas algo que punir alguns guardas faria...",
  ui_story_1011_10111501_34_dialog_content = "Mas duvido que seja assim.",
  ui_story_1011_10111501_35_dialog_content = "Não vou correr o risco de que Damocles possa disparar a qualquer momento. Todas as outras preocupações são secundárias.",
  ui_story_1011_10111501_36_dialog_content = "Entendido, meu senhor.",
  ui_story_1011_10111501_37_dialog_content = "Quatro Anjos, comigo.",
  ui_story_1011_10111501_38_dialog_content = "Sim, senhor!",
  ui_story_1011_10111501_39_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_1011_10111501_40_dialog_content = "Mais um pulso Lumina!",
  ui_story_1011_10111501_41_dialog_content = "Mas... os níveis de energia de Dâmocles estão caindo!",
  ui_story_1011_10111501_42_dialog_content = "Bom. E o seu?",
  ui_story_1011_10111501_43_dialog_content = "Podemos aguentar... mas não por muito tempo!",
  ui_story_1011_10111501_44_dialog_content = "Estamos dando tudo o que temos...",
  ui_story_1011_10111501_45_dialog_content = "Meu peito parece... está queimando...",
  ui_story_1011_10111501_46_dialog_content = "...",
  ui_story_1011_10111501_47_dialog_content = "Entendi.",
  ui_story_1011_10111501_48_dialog_content = "Vamos acabar com isso desta vez.",
  ui_story_1011_10111501_49_dialog_content = "Todos, soltem Lumina para interferir na transmissão de Damocles!",
  ui_story_1011_10111501_50_dialog_content = "Faça tudo o que puder para reverter suas operações!",
  ui_story_1011_10111501_51_dialog_content = "Sim, senhor!",
  ui_story_1011_10111501_52_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_1011_10111501_53_dialog_content = "<color=#e8d9bb>Br...</color>",
  ui_story_1011_10111501_54_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10111501_55_dialog_content = "Huff... Huff...",
  ui_story_1011_10111501_56_dialog_content = "Nós... paramos com isso...?",
  ui_story_1011_10111501_57_dialog_content = "Nós... tudo... tudo incinerado...",
  ui_story_1011_10111501_58_dialog_content = "...",
  ui_story_1011_10111501_59_dialog_content = "Meu Senhor, o problema está resolvido?",
  ui_story_1011_10111501_60_dialog_content = "Sim, terminamos nesta sala.",
  ui_story_1011_10111501_61_dialog_content = "Dito isto...",
  ui_story_1011_10111501_62_dialog_content = "Dâmocles...",
  ui_story_1011_10111501_63_dialog_content = "Qual é o seu alvo pretendido...?",
  ui_story_1011_10111501_64_dialog_content = "<color=#e8d9bb>Buzz, buzz... Buzz...</color>",
  ui_story_1011_10111501_65_dialog_content = "Isso é... tão... RUIDOSO!",
  ui_story_1011_10111501_66_dialog_content = "*Soluço* Eu só quero uma boa soneca...",
  ui_story_1011_10111501_67_dialog_content = "Hm? Philyshy?",
  ui_story_1011_10111501_68_dialog_content = "Você está cochilando no trabalho de novo, não é?",
  ui_story_1011_10111501_69_dialog_content = "Do que está falando, senhor? Eu estou totalmente acordado!",
  ui_story_1011_10111501_70_dialog_content = "Não importa... Desta vez.",
  ui_story_1011_10111501_71_dialog_content = "Mas o que é aquele som barulhento...?",
  ui_story_1011_10111501_72_dialog_content = "<color=#e8d9bb>Buzz, buzz... Buzz...</color>",
  ui_story_1011_10111501_73_dialog_content = "Aquele som... Está me dando nos nervos! O que é isso!?",
  ui_story_1011_10111501_74_dialog_content = "Ei! Alguém!",
  ui_story_1011_10111501_75_dialog_content = "Ah, comandante Sharona.",
  ui_story_1011_10111501_76_dialog_content = "Você também...?",
  ui_story_1011_10111501_77_dialog_content = "Vivian, você sabe o que está acontecendo?",
  ui_story_1011_10111501_78_dialog_content = "Nenhuma idéia. Nunca ouvi algo parecido.",
  ui_story_1011_10111501_79_dialog_content = "Ninguém sabe nada.",
  ui_story_1011_10111501_80_dialog_content = "Não me diga que eu tenho que sofrer barulhos de Gannon assim fora do campo de batalha...",
  ui_story_1011_10111501_81_dialog_content = "Alguma coisa deve ter falhado em algum lugar. Eu vou conseguir alguém sobre isso imediatamente!",
  ui_story_1011_10111501_82_dialog_content = "<color=#e8d9bb>Buzz, buzz... Buzz...</color>",
  ui_story_1011_10111501_83_dialog_content = "Então essa é a situação agora. Todos de Gannon podem ouvi-lo.",
  ui_story_1011_10111501_84_dialog_content = "Um-hum...",
  ui_story_1011_10111501_85_dialog_content = "Nossos caras de manutenção disseram que está vindo de algum equipamento antigo dentro da parede.",
  ui_story_1011_10111501_86_dialog_content = "Eles foram listados como defeituosos e sucateados... Ninguém esperava que eles fossem capazes de fazer esse tipo de barulho.",
  ui_story_1011_10111501_87_dialog_content = "Um-hum...",
  ui_story_1011_10111501_88_dialog_content = "Gronru, você está mesmo ouvindo?",
  ui_story_1011_10111501_89_dialog_content = "Hum... estou ouvindo.",
  ui_story_1011_10111501_90_dialog_content = "Você está falando sobre isso... Sim. Aquela coisa.",
  ui_story_1011_10111501_91_dialog_content = "Você não está ouvindo nada!",
  ui_story_1011_10111501_92_dialog_content = "Largue o livro! Isso é importante!",
  ui_story_1011_10111501_93_dialog_content = "Os barulhos causaram pânico na cidade!",
  ui_story_1011_10111501_94_dialog_content = "Não há nada que nossas equipes de tecnologia possam fazer. Você pode...",
  ui_story_1011_10111501_95_dialog_content = "Rápido!",
  ui_story_1011_10111501_96_dialog_content = "?!",
  ui_story_1011_10111501_97_dialog_content = "<color=#e8d9bb>Buzz, buzz... Buzz...</color>",
  ui_story_1011_10111501_98_dialog_content = "Entendi.",
  ui_story_1011_10111501_99_dialog_content = "Sim. Eu entendo agora. Sério.",
  ui_story_1011_10111501_100_dialog_content = "Hum? O que você entendeu?",
  ui_story_1011_10111501_101_dialog_content = "Não desligue só porque dói ouvir... mas OUÇA com atenção!",
  ui_story_1011_10111501_102_dialog_content = "Não é só barulho. Há uma mensagem oculta...",
  ui_story_1011_10111501_103_dialog_content = "Uma mensagem oculta?",
  ui_story_1011_10111501_104_dialog_content = "Em uma língua muito antiga, sim.",
  ui_story_1011_10111501_105_dialog_content = "Deixe-me ver... Página 302... Página 564...",
  ui_story_1011_10111501_106_dialog_content = "Aí está!",
  ui_story_1011_10111501_107_dialog_content = "Eu diria que é uma suposição educada das línguas antigas na melhor das hipóteses ...",
  ui_story_1011_10111501_108_dialog_content = "Mas acho que significa algo como...",
  ui_story_1011_10111501_109_dialog_content = "<color=#FFB400>\"Esconda agora.\"</color>",
  ui_story_1011_10111501_110_dialog_content = "Estou chegando, Brock.",
  ui_story_1011_10111501_111_dialog_content = "Hum! Você está preparado para perder?",
  ui_story_1011_10111501_112_dialog_content = "Isso é o que eu deveria estar dizendo a você, General Ever-Lost!",
  ui_story_1011_10111501_113_dialog_content = "Não vou mais carregar esse título vergonhoso!",
  ui_story_1011_10111501_114_dialog_content = "Hoje todo mundo vai me ver batendo Sinsa, justo e quadrado!",
  ui_story_1011_10111501_115_dialog_content = "Oh! Eu gosto de como você está confiante.",
  ui_story_1011_10111501_116_dialog_content = "Mas... todo mundo?",
  ui_story_1011_10111501_117_dialog_content = "Isso mesmo. Liguei para todos da Rediesel Wrench aqui.",
  ui_story_1011_10111501_118_dialog_content = "O que? Ter que lutar comigo na frente de todos te deixa com medo?",
  ui_story_1011_10111501_119_dialog_content = "Acho que você está se referindo a outra pessoa... Mas onde estão todos?",
  ui_story_1011_10111501_120_dialog_content = "Eu não vejo uma alma.",
  ui_story_1011_10111501_121_dialog_content = "Ei! Vamos lá pessoal!",
  ui_story_1011_10111501_122_dialog_content = "O duelo está prestes a começar!",
  ui_story_1011_10111501_123_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10111501_124_dialog_content = "Ei!",
  ui_story_1011_10111501_125_dialog_content = "Devemos aplaudir?",
  ui_story_1011_10111501_126_dialog_content = "Estamos torcendo por você...",
  ui_story_1011_10111501_127_dialog_content = "Meu irmão vai ganhar com certeza!",
  ui_story_1011_10111501_128_dialog_content = "Eh? Só vocês três?",
  ui_story_1011_10111501_129_dialog_content = "Ninguém está interessado em uma luta perdida...",
  ui_story_1011_10111501_130_dialog_content = "Por que você simplesmente não desiste, Brock?",
  ui_story_1011_10111501_131_dialog_content = "Como eu poderia!?",
  ui_story_1011_10111501_132_dialog_content = "Irmão, nocauteie-o!",
  ui_story_1011_10111501_133_dialog_content = "Certo! Eu não vou te decepcionar, Eve!",
  ui_story_1011_10111501_134_dialog_content = "Onde você gostaria de vê-lo cair?",
  ui_story_1011_10111501_135_dialog_content = "Sinsa, você não pode lutar em cima do Lepidoz?",
  ui_story_1011_10111501_136_dialog_content = "Não importa a multidão... Eu não preciso de um corvo de qualquer maneira!",
  ui_story_1011_10111501_137_dialog_content = "Vou contar a todos sobre minha vitória impecável depois!",
  ui_story_1011_10111501_138_dialog_content = "Haha! Venha até mim!",
  ui_story_1011_10111501_139_dialog_content = "<color=#e8d9bb>Cabuum!</color>",
  ui_story_1011_10111501_140_dialog_content = "Ahhhhhh!",
  ui_story_1011_10111501_141_dialog_content = "O que está acontecendo?",
  ui_story_1011_10111501_142_dialog_content = "Bopper, não ligue o Lepidoz sem eu te avisar!",
  ui_story_1011_10111501_143_dialog_content = "Chefe, estou aqui...",
  ui_story_1011_10111501_144_dialog_content = "Não há ninguém no Lepidoz além de você.",
  ui_story_1011_10111501_145_dialog_content = "Eh? Então o que é isso?",
  ui_story_1011_10111501_146_dialog_content = "Ei, Sinsa, você vai fugir?",
  ui_story_1011_10111501_147_dialog_content = "Cala a sua boca! Está se movendo sozinho⁠—",
  ui_story_1011_10111501_148_dialog_content = "<color=#e8d9bb>Cabuum!</color>",
  ui_story_1011_10111501_149_dialog_content = "Waaaaaah! Está acelerando!",
  ui_story_1011_10111501_150_dialog_content = "Uau! Isso é mais emocionante do que eu imaginava.",
  ui_story_1011_10111501_151_dialog_content = "Bro fugiu de uma briga. Bro é um covarde.",
  ui_story_1011_10111501_152_dialog_content = "Não sou eu! Juro! É o Lepidoz!",
  ui_story_1011_10111501_153_dialog_content = "Pare de ficar parado! Venha me dar uma mão!",
  ui_story_1011_10111501_154_dialog_content = "Ei!",
  ui_story_1011_10111501_155_dialog_content = "<color=#e8d9bb>Tu-tum... Tu-tum...</color>",
  ui_story_1011_10111501_156_dialog_content = "Olá. Tenho um e-mail urgente para o Sr. Istvan aqui para você assinar.",
  ui_story_1011_10111501_157_dialog_content = "Eu vou levar.",
  ui_story_1011_10111501_158_dialog_content = "Espere. Quem é o remetente?",
  ui_story_1011_10111501_159_dialog_content = "Não está no envelope.",
  ui_story_1011_10111501_160_dialog_content = "Ah, por favor, permita-me explicar.",
  ui_story_1011_10111501_161_dialog_content = "O nome do remetente não é necessário para uma correspondência urgente endereçada ao Sr. Istvan.",
  ui_story_1011_10111501_162_dialog_content = "Isso é solicitado pelo Sr. Istvan ele mesmo.",
  ui_story_1011_10111501_163_dialog_content = "Entendi.",
  ui_story_1011_10111501_164_dialog_content = "Valeu.",
  ui_story_1011_10111501_165_dialog_content = "Obrigado por escolher a União dos Correios. Ver você de novo!",
  ui_story_1011_10111501_166_dialog_content = "Ei! Um correio urgente para o Sr. Istvan. Por favor, assine!",
  ui_story_1011_10111501_167_dialog_content = "OK. Outro?",
  ui_story_1011_10111501_168_dialog_content = "Então... a razão pela qual não há nome de remetente é que...",
  ui_story_1011_10111501_169_dialog_content = "É solicitado pelo Sr. Istvan ele mesmo, correto?",
  ui_story_1011_10111501_170_dialog_content = "Direita!",
  ui_story_1011_10111501_171_dialog_content = "Você pode deixar comigo. Obrigado.",
  ui_story_1011_10111501_172_dialog_content = "Sem problemas! Agora depois!",
  ui_story_1011_10111501_173_dialog_content = "Ahhhh! Estou atrasado, estou atrasado!",
  ui_story_1011_10111501_174_dialog_content = "Espero não estar muito atrasado e que meu salário não seja descontado.",
  ui_story_1011_10111501_175_dialog_content = "Ei, você está aqui também, Dove?",
  ui_story_1011_10111501_176_dialog_content = "Ei, Tweety! Você...",
  ui_story_1011_10111501_177_dialog_content = "Conversamos depois. Estou atrasado como está.",
  ui_story_1011_10111501_178_dialog_content = "Olá. Tenho um e-mail urgente para o Sr. Istvan aqui para você assinar.",
  ui_story_1011_10111501_179_dialog_content = "Pai, acabei de receber alguns e-mails urgentes para você da União dos Correios.",
  ui_story_1011_10111501_180_dialog_content = "E-mails urgentes? Traga-os para mim.",
  ui_story_1011_10111501_181_dialog_content = "Aqui está.",
  ui_story_1011_10111501_182_dialog_content = "Vários e-mails urgentes de uma só vez...",
  ui_story_1011_10111501_183_dialog_content = "Então, o que fez os pardais entrarem em pânico assim?",
  ui_story_1011_10111501_184_dialog_content = "...",
  ui_story_1011_10111501_185_dialog_content = "Parece que não são apenas os pardais.",
  ui_story_1011_10111501_186_dialog_content = "Sheol, mande mais pessoas para rastrear tudo o que está acontecendo em Lumopolis.",
  ui_story_1011_10111501_187_dialog_content = "Quero cada detalhe até qual soldado puxou sua espada.",
  ui_story_1011_10111501_188_dialog_content = "Considere isso feito.",
  ui_story_1011_10111501_189_dialog_content = "Mas não deveríamos fazer outra preparação?",
  ui_story_1011_10111501_190_dialog_content = "Pode ser tarde demais se esperarmos que Lumopolis aja.",
  ui_story_1011_10111501_191_dialog_content = "O curso de ação agora é suficiente.",
  ui_story_1011_10111501_192_dialog_content = "Nós residimos nas sombras de Lumopolis.",
  ui_story_1011_10111501_193_dialog_content = "E uma sombra deve saber seu lugar.",
  ui_story_1011_10111501_194_dialog_content = "<color=#e8d9bb>Dadá...</color>",
  ui_story_1011_10111501_195_dialog_content = "Senhora Victoria, você está bem?",
  ui_story_1011_10111501_196_dialog_content = "...",
  ui_story_1011_10111501_197_dialog_content = "Ainda sem resposta.",
  ui_story_1011_10111501_198_dialog_content = "Devemos entrar?",
  ui_story_1011_10111501_199_dialog_content = "O olhar da senhora Victoria antes me tinha preocupado.",
  ui_story_1011_10111501_200_dialog_content = "Não... Absolutamente não...",
  ui_story_1011_10111501_201_dialog_content = "Não podemos entrar em Lady Victoriado quarto sem permissão. Isso é uma violação grave...",
  ui_story_1011_10111501_202_dialog_content = "Não há necessidade de preocupação. Senhora Victoria só pode estar cansado.",
  ui_story_1011_10111501_203_dialog_content = "Você não tem nada melhor para fazer do que se preocupar com ela?",
  ui_story_1011_10111501_204_dialog_content = "Vou tentar bater mais uma vez.",
  ui_story_1011_10111501_205_dialog_content = "<color=#e8d9bb>Toc Toc...</color>",
  ui_story_1011_10111501_206_dialog_content = "Senhora Victoria, você está bem aí?",
  ui_story_1011_10111501_207_dialog_content = "...",
  ui_story_1011_10111501_208_dialog_content = "Parece que...",
  ui_story_1011_10111501_209_dialog_content = "Faust, você entra aqui.",
  ui_story_1011_10111501_210_dialog_content = "!!!",
  ui_story_1011_10111501_211_dialog_content = "Você sozinho. Não quero perturbado.",
  ui_story_1011_10111501_212_dialog_content = "Sim, senhora...",
  ui_story_1011_10111501_213_dialog_content = "<color=#e8d9bb>*Ranidos*</color>",
  ui_story_1011_10111501_214_dialog_content = "Senhora Victoria, você...",
  ui_story_1011_10111501_215_dialog_content = "Olha.",
  ui_story_1011_10111501_216_dialog_content = "Como o sangue flui da Bíblia Sangrenta.",
  ui_story_1011_10111501_217_dialog_content = "Está fluindo há algum tempo.",
  ui_story_1011_10111501_218_dialog_content = "Isso significa... que uma nova revelação será revelada?",
  ui_story_1011_10111501_219_dialog_content = "Está demorando mais do que antes.",
  ui_story_1011_10111501_220_dialog_content = "O tapete já está encharcado de sangue, mas nenhum texto apareceu nas páginas.",
  ui_story_1011_10111501_221_dialog_content = "Algo que nem \"A Verdade\" ousa falar?",
  ui_story_1011_10111501_222_dialog_content = "Como isso pode ser...?",
  ui_story_1011_10111501_223_dialog_content = "Você já encontrou algo assim em toda a sua vida?",
  ui_story_1011_10111501_224_dialog_content = "Rápido!",
  ui_story_1011_10111501_225_dialog_content = "Está chegando.",
  ui_story_1011_10111501_226_dialog_content = "Finalmente. Está chegando.",
  ui_story_1011_10111501_227_dialog_content = "!!!",
  ui_story_1011_10111501_228_dialog_content = "\"■■\"",
  ui_story_1011_10111501_229_dialog_content = "\"■■■■■■■■■■\"",
  ui_story_1011_10111501_230_dialog_content = "Quê?!",
  ui_story_1011_10111501_231_dialog_content = "Eu não tinha visto essa linguagem antes! Senhora Victoria, O que isto significa?",
  ui_story_1011_10111501_232_dialog_content = "Maldita Bíblia.",
  ui_story_1011_10111501_233_dialog_content = "O que você mostrou não é para nossos olhos, é?",
  ui_story_1011_10111501_234_dialog_content = "Então, para quem é isso, aquele destinado a receber a revelação...?",
  ui_story_1011_10111501_235_dialog_content = "Ai... É tão brilhante.",
  ui_story_1011_10111501_236_dialog_content = "Huh? Achei que o sol tinha acabado de se pôr...",
  ui_story_1011_10111501_237_dialog_content = "Isso não é sol!",
  ui_story_1011_10111501_238_dialog_content = "Parece que... está vindo do farol à beira-mar.",
  ui_story_1011_10111501_239_dialog_content = "Tem razão!",
  ui_story_1011_10111501_240_dialog_content = "Mas não me lembro de ter sido tão brilhante.",
  ui_story_1011_10111501_241_dialog_content = "Novio, está Sua Majestade no Palácio de Inverno?",
  ui_story_1011_10111501_242_dialog_content = "Ela é.",
  ui_story_1011_10111501_243_dialog_content = "Você está suando muito. O que aconteceu?",
  ui_story_1011_10111501_244_dialog_content = "O farol brilha mais do que nunca... estou preocupado que...",
  ui_story_1011_10111501_245_dialog_content = "Algo pode ter dado errado com as forças que guardam Northland.",
  ui_story_1011_10111501_246_dialog_content = "Eu vejo. É uma questão crucial, de fato.",
  ui_story_1011_10111501_247_dialog_content = "Venha. Teremos uma audiência com Sua Majestade imediatamente.",
  ui_story_1011_10111501_248_dialog_content = "<color=#e8d9bb>Ta... ta... ta...</color>",
  ui_story_1011_10111501_249_dialog_content = "Sua Majestade, Nikinis solicita seu público.",
  ui_story_1011_10111501_250_dialog_content = "Ela disse...",
  ui_story_1011_10111501_251_dialog_content = "Está procurando...",
  ui_story_1011_10111501_252_dialog_content = "Hum? Seu...",
  ui_story_1011_10111501_253_dialog_content = "Está olhando... está... olhando...",
  ui_story_1011_10111501_254_dialog_content = "Sua Majestade está dormindo.",
  ui_story_1011_10111501_255_dialog_content = "Devemos acordá-la?",
  ui_story_1011_10111501_256_dialog_content = "Acredito que Sua Majestade gostaria de saber se algo aconteceu com o farol.",
  ui_story_1011_10111501_257_dialog_content = "Vá para o lado dela e sussurre suavemente para ela.",
  ui_story_1011_10111501_258_dialog_content = "OK.",
  ui_story_1011_10111501_259_dialog_content = "Majestade?",
  ui_story_1011_10111501_260_dialog_content = "O farol está brilhando tão brilhante quanto o sol.",
  ui_story_1011_10111501_261_dialog_content = "Estamos preocupados que algo veio para tirar a noite tranquila de Northland?",
  ui_story_1011_10111501_262_dialog_content = "Está olhando para nós... dos céus...",
  ui_story_1011_10111501_263_dialog_content = "O Obelisco... olhos para o céu...",
  ui_story_1011_10111501_264_dialog_content = "Sua Majestade?",
  ui_story_1011_10111501_265_dialog_content = "Corra... esconda... o mais longe possível...",
  ui_story_1011_10111501_266_dialog_content = "Para o topo das montanhas... as ilhas desabitadas...",
  ui_story_1011_10111501_267_dialog_content = "Novio, algo de errado com Sua Majestade.",
  ui_story_1011_10111501_268_dialog_content = "Sim.",
  ui_story_1011_10111501_269_dialog_content = "Sua Majestade, é hora de acordar.",
  ui_story_1011_10111501_270_dialog_content = "Afaste-se daquele lugar...",
  ui_story_1011_10111501_271_dialog_content = "O Obelisco...",
  ui_story_1011_10111501_272_dialog_content = "Afaste-se... da Cidade do Obelisco...",
  ui_story_1011_10111501_273_dialog_content = "Vossa Majestade!",
  ui_story_1011_10111501_274_dialog_content = "SUA MAJESTADE!",
  ui_story_1011_10111501_275_dialog_content = "...",
  ui_story_1011_10111501_276_dialog_content = "Vossa Majestade, você...",
  ui_story_1011_10111501_277_dialog_content = "<color=#FFB400>É você, PlayerName.</color>",
  ui_story_1011_10111501_278_dialog_content = "!!!",
  ui_story_1011_10111501_279_dialog_content = "Não, Sua Majestade! EU...",
  ui_story_1011_10111501_280_dialog_content = "Hã?",
  ui_story_1011_10111501_281_dialog_content = "Por que... Por que isso está acontecendo...?",
  ui_story_1011_10111501_282_dialog_content = "Qual o problema, PlayerName?",
  ui_story_1011_10111501_283_dialog_content = "O que há de errado comigo? EU...",
  ui_story_1011_10111501_284_dialog_content = "Pode parecer absurdo, mas...",
  ui_story_1011_10111501_285_dialog_content = "Acabei de ver, claro como o dia...",
  ui_story_1011_10111501_286_dialog_content = "O que você viu?",
  ui_story_1011_10111501_287_dialog_content = "Eu vi <color=#FFB400>o mundo inteiro</color>.",
  ui_story_1012_10120101_1_dialog_content = "Eu vi o mundo inteiro naquele instante.",
  ui_story_1012_10120101_2_dialog_content = "De Illumina a Lumopolis.",
  ui_story_1012_10120101_3_dialog_content = "Northland ao deserto de Rediesel.",
  ui_story_1012_10120101_4_dialog_content = "Naquele instante, tive uma visão de toda a cena.",
  ui_story_1012_10120101_5_dialog_content = "Era como se eu não fosse mais eu...",
  ui_story_1012_10120101_6_dialog_content = "Mas o próprio Obelisco do Retorno.",
  ui_story_1012_10120101_7_dialog_content = "Que estranho... Não havia registros de que os celestitas tivessem tal tecnologia.",
  ui_story_1012_10120101_8_dialog_content = "Não, não vamos nos preocupar com isso por enquanto.",
  ui_story_1012_10120101_9_dialog_content = "Se esta máquina é o núcleo desta base, deve saber poupar Vice!",
  ui_story_1012_10120101_10_dialog_content = "Certo! Neural Aux, procure casos com detalhes sobre a recuperação do estado de hibernação!",
  ui_story_1012_10120101_11_dialog_content = "Acesso verificado. Gerando relatório.",
  ui_story_1012_10120101_12_dialog_content = "Inserindo assuntos contendo Hibernação no <color=#FFB400>Link de acordes</color> dispositivo. Tentativa de combinação com a função Sincronização.",
  ui_story_1012_10120101_13_dialog_content = "As experiências produziram efeitos terapêuticos positivos inesperados.",
  ui_story_1012_10120101_14_dialog_content = "Sinais de recuperação da consciência foram observados nos sujeitos, juntamente com alterações físicas.",
  ui_story_1012_10120101_15_dialog_content = "Os efeitos colaterais da mudança física não são claros.",
  ui_story_1012_10120101_16_dialog_content = "No final, a sincronização dos sujeitos foi bem-sucedida e eles se recuperaram da hibernação.",
  ui_story_1012_10120101_17_dialog_content = "Link do acorde...",
  ui_story_1012_10120101_18_dialog_content = "O que foi?",
  ui_story_1012_10120101_19_dialog_content = "Procurando informações sobre Chord Link...",
  ui_story_1012_10120101_20_dialog_content = "...",
  ui_story_1012_10120101_21_dialog_content = "...",
  ui_story_1012_10120101_22_dialog_content = "#*%￥&￥#&*!",
  ui_story_1012_10120101_23_dialog_content = "Auxiliar Neural?!",
  ui_story_1012_10120101_24_dialog_content = "Processo de erro finalizado.",
  ui_story_1012_10120101_25_dialog_content = "Dados experimentais no Chord Link foram armazenados na Chord Zone. Normalmente restrito ao público.",
  ui_story_1012_10120101_26_dialog_content = "Está sendo mantido estritamente em segredo?",
  ui_story_1012_10120101_27_dialog_content = "Parece uma instalação muito importante.",
  ui_story_1012_10120101_28_dialog_content = "Quem sabe? A coisa mais importante nesta Torre Branca pode não ser o Sistema Circular...",
  ui_story_1012_10120101_29_dialog_content = "Mas este Acorde Link.",
  ui_story_1012_10120101_30_dialog_content = "Neural Aux, algum detalhe sobre a Chord Zone?",
  ui_story_1012_10120101_31_dialog_content = "A ligação entre Neural Aux e a Chord Zone foi quebrada. Os dados não podem ser lidos!",
  ui_story_1012_10120101_32_dialog_content = "A descrição do banco de dados local do dispositivo diz—",
  ui_story_1012_10120101_33_dialog_content = "O Chord Link pode curar feridas, modificar parcialmente os corpos dos Aurorianos e ativar seu potencial também.",
  ui_story_1012_10120101_34_dialog_content = "Para permitir que os aurorianos se coordenem melhor com os celestitas na batalha.",
  ui_story_1012_10120101_35_dialog_content = "Isso soa como... algum tipo de dispositivo de transformação.",
  ui_story_1012_10120101_36_dialog_content = "Não... Se os celestitas no passado viam os aurorianos como inimigos...",
  ui_story_1012_10120101_37_dialog_content = "Então, por que existe um dispositivo aqui que pode transformar os aurorianos para torná-los mais compatíveis com os celestitas em batalha?",
  ui_story_1012_10120101_38_dialog_content = "Você tem razão. Isso é realmente estranho.",
  ui_story_1012_10120101_39_dialog_content = "PlayerName, não podemos confiar nos registros deste dispositivo com tanta facilidade.",
  ui_story_1012_10120101_40_dialog_content = "Precisamos descobrir para que exatamente esse Chord Link é usado e se isso trará danos a Vice.",
  ui_story_1012_10120101_41_dialog_content = "OK eu entendi.",
  ui_story_1012_10120101_42_dialog_content = "Neural Aux, há algum efeito colateral ao usar o Chord Link?",
  ui_story_1012_10120101_43_dialog_content = "Terá algum efeito negativo sobre Vice?",
  ui_story_1012_10120101_44_dialog_content = "A ligação entre Neural Aux e a Chord Zone foi quebrada. Os dados não podem ser lidos!",
  ui_story_1012_10120101_45_dialog_content = "Está desconectado faz um tempo. Você não tentou consertar?",
  ui_story_1012_10120101_46_dialog_content = "Eu sou apenas um sistema para prestar assistência ao celestita.",
  ui_story_1012_10120101_47_dialog_content = "É proibido forçar o Neural Aux a realizar tarefas de manutenção que estejam fora de suas funções!",
  ui_story_1012_10120101_48_dialog_content = "Parece que não vou conseguir nenhuma informação relevante daqui...",
  ui_story_1012_10120101_49_dialog_content = "Bem, parece que não há escolha.",
  ui_story_1012_10120101_50_dialog_content = "É melhor tentar, mesmo que seja um risco.",
  ui_story_1012_10120101_51_dialog_content = "Vice ficou assim por minha causa.",
  ui_story_1012_10120101_52_dialog_content = "Eu assumo a responsabilidade, mesmo que...",
  ui_story_1012_10120101_53_dialog_content = "...",
  ui_story_1012_10120101_54_dialog_content = "Quando chegar a hora, vou tentar usar esse dispositivo.",
  ui_story_1012_10120101_55_dialog_content = "Se não houver problemas, usarei para salvar Vice.",
  ui_story_1012_10120101_56_dialog_content = "Mas se não der certo... estarei contando com você então, Carleen. Trazer Vice de volta à Illumina para buscar ajuda.",
  ui_story_1012_10120101_57_dialog_content = "Esse é um bom sentimento, mas não esqueça que um celestita não é um auroriano.",
  ui_story_1012_10120101_58_dialog_content = "Vice é meu amigo. Farei minha parte para salvá-la.",
  ui_story_1012_10120101_59_dialog_content = "Se não houver escolha a não ser fazer isso, é melhor eu tentar.",
  ui_story_1012_10120101_60_dialog_content = "Neural Aux, leve-me a este dispositivo.",
  ui_story_1012_10120101_61_dialog_content = "Calculando a rota para a Chord Zone—",
  ui_story_1012_10120101_62_dialog_content = "Rota detectada. A maioria das passagens com acesso à Chord Zone desmoronou. O Gerente deve fazer um desvio pela Zona de Exílio para prosseguir.",
  ui_story_1012_10120101_63_dialog_content = "A ligação entre Neural Aux e a Chord Zone foi quebrada. Neural Aux não pode abrir o portão diretamente.",
  ui_story_1012_10120101_64_dialog_content = "Com base nas configurações mais recentes, uma chave secreta foi gerada para o Supervisor desbloquear o Controle de Acesso.",
  ui_story_1012_10120101_65_dialog_content = "Última modificação por: Mestre Francis.",
  ui_story_1012_10120101_66_dialog_content = "Esse tal de Mestre Francis de novo?",
  ui_story_1012_10120101_67_dialog_content = "O que esse cara está planejando?",
  ui_story_1012_10120101_68_dialog_content = "Acho que ele não está planejando nada.",
  ui_story_1012_10120101_69_dialog_content = "Parece mais que ele está abrindo caminho para quem vier depois.",
  ui_story_1012_10120101_70_dialog_content = "Como nós.",
  ui_story_1012_10120101_71_dialog_content = "Gerente, por favor, siga o Neural Aux até a Chord Zone. Neural Aux irá quebrar o controle de acesso da zona de acordes para você.",
  ui_story_1012_10120101_72_dialog_content = "A Chord Zone e a Exiled Zone estão ligadas?",
  ui_story_1012_10120101_73_dialog_content = "Não parece um bom lugar...",
  ui_story_1012_10120101_74_dialog_content = "Bom ou não, é a nossa única esperança.",
  ui_story_1012_10120101_75_dialog_content = "Vamos lá. Vamos levar Vice para a Zona de Acordes.",
  ui_story_1012_10120101_76_dialog_content = "Mostre o caminho, Auxiliar Neural.",
  ui_story_1012_10120101_77_dialog_content = "Sim! Neural Aux Navigation, ao seu serviço!",
  ui_story_1012_10120101_78_dialog_content = "Link do acorde...",
  ui_story_1012_10120101_79_dialog_content = "Esta é a tecnologia enterrada nesta base subterrânea?",
  ui_story_1012_10120101_80_dialog_content = "Capaz de transformar os corpos dos Aurorianos...",
  ui_story_1012_10120101_81_dialog_content = "É exatamente o que eu quero.",
  ui_story_1012_10120101_82_dialog_content = "(Eclipsiana) Senhora Forsakin, esse Illuminan está perto de nós.",
  ui_story_1012_10120101_83_dialog_content = "(Eclipsiano) Ele é... muito poderoso. Não podemos detê-lo.",
  ui_story_1012_10120101_84_dialog_content = "As pessoas de Illumina são todos monstros.",
  ui_story_1012_10120101_85_dialog_content = "Se não pudermos detê-lo, encontre uma maneira de levá-lo pelo caminho errado.",
  ui_story_1012_10120101_86_dialog_content = "Não deixe que aquele imprudente se aproxime da tecnologia preciosa.",
  ui_story_1012_10120101_87_dialog_content = "Tudo o que ele tem em sua cabeça é batalha e destruição.",
  ui_story_1012_10120101_88_dialog_content = "(Eclipsiano) Entendido.",
  ui_story_1012_10120101_89_dialog_content = "Irridon, não me pare.",
  ui_story_1012_10120101_90_dialog_content = "O Conselho Ancião tem o direito de saber o motivo da ativação de Damocles.",
  ui_story_1012_10120101_91_dialog_content = "O Senhor da Cidade ordenou que ninguém entrasse na sala de controle.",
  ui_story_1012_10120101_92_dialog_content = "As ordens do Lorde da Cidade são lei em Lumopolis. Tenho certeza que você já sabe disso.",
  ui_story_1012_10120101_93_dialog_content = "Lord Otto, mesmo sendo membro do Conselho dos Anciões, ainda está sob os limites da lei.",
  ui_story_1012_10120101_94_dialog_content = "Os direitos do Elder Council também fazem parte das leis de Lumopolis.",
  ui_story_1012_10120101_95_dialog_content = "Juiz principal Irridon, devo informá-lo que você está agora—",
  ui_story_1012_10120101_96_dialog_content = "Dâmocles parou?",
  ui_story_1012_10120101_97_dialog_content = "(O Senhor da Cidade e os Quatro Anjos... Eles conseguiram?)",
  ui_story_1012_10120101_98_dialog_content = "Senhor Schwartz...",
  ui_story_1012_10120101_99_dialog_content = "Por favor, me diga o que aconteceu na sala de controle. Por que Dâmocles foi ativado de repente?",
  ui_story_1012_10120101_100_dialog_content = "Relaxe, Otto, relaxe.",
  ui_story_1012_10120101_101_dialog_content = "Damocles ativou sem aviso e autorização, mas eu parei.",
  ui_story_1012_10120101_102_dialog_content = "Ele foi devolvido ao controle de Lumopolis agora.",
  ui_story_1012_10120101_103_dialog_content = "Ativação não autorizada... Como isso é possível?",
  ui_story_1012_10120101_104_dialog_content = "Dâmocles é uma arma poderosa, mas ainda é apenas uma arma.",
  ui_story_1012_10120101_105_dialog_content = "Como ele pode se auto-ativar sem ninguém operá-lo?",
  ui_story_1012_10120101_106_dialog_content = "Devo corrigi-lo em um ponto, Otto.",
  ui_story_1012_10120101_107_dialog_content = "Dâmocles é de fato uma arma de Lumopolis, mas...",
  ui_story_1012_10120101_108_dialog_content = "Não pertence completamente a Lumopolis.",
  ui_story_1012_10120101_109_dialog_content = "...",
  ui_story_1012_10120101_110_dialog_content = "No final, ainda é um remanescente de povos antigos que nunca vimos e algo que Lumopolis rejeita ferozmente.",
  ui_story_1012_10120101_111_dialog_content = "O poder desconhecido que não lhe pertence tem o potencial de sair do controle.",
  ui_story_1012_10120101_112_dialog_content = "Vou mandar os técnicos responsáveis pela manutenção de Damocles fazerem uma verificação completa para encontrar a causa da perda de controle.",
  ui_story_1012_10120101_113_dialog_content = "Dê-me os resultados até amanhã.",
  ui_story_1012_10120101_114_dialog_content = "Eu agradeço.",
  ui_story_1012_10120101_115_dialog_content = "Manter a segurança e a prosperidade de Lumopolis é prioridade, é claro.",
  ui_story_1012_10120101_116_dialog_content = "...",
  ui_story_1012_10120101_117_dialog_content = "Dâmocles...",
  ui_story_1012_10120101_118_dialog_content = "A direção para a qual você está apontando é...",
  ui_story_1012_10120101_119_dialog_content = "...",
  ui_story_1012_10120101_120_dialog_content = "Rafael.",
  ui_story_1012_10120101_121_dialog_content = "Ah, s-sim!",
  ui_story_1012_10120101_122_dialog_content = "O Lorde da Cidade tinha alguma ordem?",
  ui_story_1012_10120101_123_dialog_content = "Vá até Beretta e diga a ela para reunir uma equipe de cavaleiros. Vá para Eraveil imediatamente.",
  ui_story_1012_10120101_124_dialog_content = "Certo, mas o que você quer que Beretta faça?",
  ui_story_1012_10120101_125_dialog_content = "Faça o que precisa ser feito.",
  ui_story_1012_10120101_126_dialog_content = "O quê?!",
  ui_story_1012_10120101_127_dialog_content = "Continue.",
  ui_story_1012_10120101_128_dialog_content = "Certo, tudo bem!",
  ui_story_1012_10120101_129_dialog_content = "Vossa Majestade...",
  ui_story_1012_10120101_130_dialog_content = "Tô bem.",
  ui_story_1012_10120101_131_dialog_content = "Minhas desculpas por ter feito você se preocupar.",
  ui_story_1012_10120101_132_dialog_content = "Há algo que devo relatar. Há um problema com o Beacon. Está emitindo uma luz forte como nenhuma outra.",
  ui_story_1012_10120101_133_dialog_content = "Entendi.",
  ui_story_1012_10120101_134_dialog_content = "Eu vou lidar com este assunto. Você não precisa se preocupar com isso.",
  ui_story_1012_10120101_135_dialog_content = "Entendi...",
  ui_story_1012_10120101_136_dialog_content = "Vossa Majestade, você mencionou o nome do celestita quando estava meio adormecido.",
  ui_story_1012_10120101_137_dialog_content = "Isso provavelmente não é por acaso, não é?",
  ui_story_1012_10120101_138_dialog_content = "...",
  ui_story_1012_10120101_139_dialog_content = "Eu o vi de pé na Torre, olhando para o mundo.",
  ui_story_1012_10120101_140_dialog_content = "Aquela Torre é uma existência que nem eu consigo imaginar.",
  ui_story_1012_10120101_141_dialog_content = "Foi construído em tempos antigos, e suas origens são desconhecidas.",
  ui_story_1012_10120101_142_dialog_content = "A Torre e o Farol que protegem Northland são como fogo e água.",
  ui_story_1012_10120101_143_dialog_content = "Aquele celestita... se tornou um inimigo?",
  ui_story_1012_10120101_144_dialog_content = "Não, não sinto nenhuma hostilidade vindo dele.",
  ui_story_1012_10120101_145_dialog_content = "Ele é o mesmo que era no passado, cheio de bondade simples.",
  ui_story_1012_10120101_146_dialog_content = "Mas eu sinto que ele está passando por um dilema que ele nunca teve antes.",
  ui_story_1012_10120101_147_dialog_content = "E esse dilema afetará o destino de todo o Astra.",
  ui_story_1012_10120101_148_dialog_content = "Northland deve fazer uma escolha.",
  ui_story_1012_10120101_149_dialog_content = "Prepare a carruagem.",
  ui_story_1012_10120101_150_dialog_content = "Estou indo para Eraveil para trazer mudanças para este dilema.",
  ui_story_1012_10120101_151_dialog_content = "Sim!",
  ui_story_1012_10120101_152_dialog_content = "A carruagem está pronta, Vossa Majestade!",
  ui_story_1012_10120101_153_dialog_content = "Partiremos de uma vez.",
  ui_story_1012_10120101_154_dialog_content = "Sua Majestade, por favor, permita-me ir com você para Eraveil.",
  ui_story_1012_10120101_155_dialog_content = "Não, você precisa ficar.",
  ui_story_1012_10120101_156_dialog_content = "Você deve cumprir bem seus deveres de guarda e observar os movimentos dos Eclipsitas quando eu não estiver em Northland.",
  ui_story_1012_10120101_157_dialog_content = "As outras partes do negócio continuarão normalmente, então não há necessidade de adiar por causa da minha ausência.",
  ui_story_1012_10120101_158_dialog_content = "Tiare vai viajar comigo.",
  ui_story_1012_10120101_159_dialog_content = "...",
  ui_story_1012_10120101_160_dialog_content = "Tiare, de prontidão.",
  ui_story_1012_10120101_161_dialog_content = "É você...",
  ui_story_1012_10120101_162_dialog_content = "Bem, por favor, proteja bem Sua Majestade. Proteja a chama da esperança de Northland.",
  ui_story_1012_10120101_163_dialog_content = "R-Relatar, miau!",
  ui_story_1012_10120101_164_dialog_content = "Houve barulhos estranhos sendo ouvidos em várias partes da cidade de Gannon.",
  ui_story_1012_10120101_165_dialog_content = "Diretor de tecnologia Gronru acha que é um alarme vindo de instrumentos antigos nas paredes das Cidades Baixas, miau!",
  ui_story_1012_10120101_166_dialog_content = "Entendi. Continue monitorando a situação em Gannon City.",
  ui_story_1012_10120101_167_dialog_content = "Além disso, pergunte às outras Cidades Baixas se a mesma coisa está acontecendo.",
  ui_story_1012_10120101_168_dialog_content = "Sim, miau!",
  ui_story_1012_10120101_169_dialog_content = "Grande Marechal, nossos batedores notaram um movimento incomum de Eclipsite.",
  ui_story_1012_10120101_170_dialog_content = "Eclipsite of Astra estão se reunindo em Eraveil.",
  ui_story_1012_10120101_171_dialog_content = "Eu vejo. Mantenha as defesas nas Cidades Baixas e continue observando.",
  ui_story_1012_10120101_172_dialog_content = "Sim.",
  ui_story_1012_10120101_173_dialog_content = "Encontro de eclipses em Eraveil e o movimento incomum de aparelhos antigos em Gannon...",
  ui_story_1012_10120101_174_dialog_content = "Aquele garoto... ele se meteu em problemas de novo?",
  ui_story_1012_10120101_175_dialog_content = "Heh, ele com certeza pode escolher o tempo.",
  ui_story_1012_10120101_176_dialog_content = "Senhor! Reportando.",
  ui_story_1012_10120101_177_dialog_content = "... Eu sabia que este não era o fim.",
  ui_story_1012_10120101_178_dialog_content = "Diga-me. O que agora?",
  ui_story_1012_10120101_179_dialog_content = "O comitê recebeu um relatório que diz que uma Torre Branca em Eraveil foi ativada de repente.",
  ui_story_1012_10120101_180_dialog_content = "Depois disso, a tecnologia antiga em todos os lugares produziu uma reação anormal coletiva.",
  ui_story_1012_10120101_181_dialog_content = "Ah?",
  ui_story_1012_10120101_182_dialog_content = "Os locais incluem o Beacon em Northland, Damocles em Lumopolis, Lepidoz que pertence à Rediesel Wrench e assim por diante ...",
  ui_story_1012_10120101_183_dialog_content = "O comitê suspeita fortemente que a anomalia em Gannon esteja relacionada a isso.",
  ui_story_1012_10120101_184_dialog_content = "Poderia fazer o Beacon e o Damocles reagirem...?",
  ui_story_1012_10120101_185_dialog_content = "Apenas o que você desenterrou, PlayerName...",
  ui_story_1012_10120101_186_dialog_content = "Grande Marechal, aguardamos instruções.",
  ui_story_1012_10120101_187_dialog_content = "Deixa eu pensar...",
  ui_story_1012_10120101_188_dialog_content = "Informe todas as equipes na área do Eraveil para se moverem em direção à Torre Branca ativada.",
  ui_story_1012_10120101_189_dialog_content = "Se algum Eclipsito for encontrado, monte uma barricada e impeça os Eclipsitos de se reunirem.",
  ui_story_1012_10120101_190_dialog_content = "Além disso, monte uma unidade de elite imediatamente. Vou levá-los a ir a Eraveil para descobrir o que está acontecendo.",
  ui_story_1012_10120101_191_dialog_content = "Sim, eu vou para a direita—",
  ui_story_1012_10120101_192_dialog_content = "Com todo o respeito, Grande Marechal, você não se recuperou dos ferimentos que sofreu na Cidade Baixa 80, e não é apropriado fazer uma cruzada pessoal em sua condição.",
  ui_story_1012_10120101_193_dialog_content = "...",
  ui_story_1012_10120101_194_dialog_content = "Anatoli, cumpra seus deveres.",
  ui_story_1012_10120101_195_dialog_content = "Sim.",
  ui_story_1012_10120101_196_dialog_content = "Grande marechal Reinhardt, gostaria de lembrá-lo de que você ainda está sob análise do comitê.",
  ui_story_1012_10120101_197_dialog_content = "Ações arriscadas podem afetar a avaliação do comitê sobre você.",
  ui_story_1012_10120101_198_dialog_content = "O que é mais importante - uma avaliação no papel ou a segurança da Illumina?",
  ui_story_1012_10120101_199_dialog_content = "... A segurança da Illumina é de maior importância.",
  ui_story_1012_10120101_200_dialog_content = "Agora que você entendeu, vá fazer o seu trabalho.",
  ui_story_1012_10120101_201_dialog_content = "Também cumprirei meu dever como Grande Marechal.",
  ui_story_1012_10120101_202_dialog_content = "Vou registrar suas ações no relatório de investigação.",
  ui_story_1012_10120101_203_dialog_content = "Escreva o que quiser.",
  ui_story_1012_10120101_204_dialog_content = "Se minha decisão for boa ou não, será avaliada pelo povo da Illumina.",
  ui_story_1012_10120201_1_dialog_content = "Graaahh—",
  ui_story_1012_10120201_2_dialog_content = "Esse é o último?",
  ui_story_1012_10120201_3_dialog_content = "Ai...",
  ui_story_1012_10120201_4_dialog_content = "São todos lacaios atrapalhando.",
  ui_story_1012_10120201_5_dialog_content = "Forsakin também fugiu para quem sabe onde?",
  ui_story_1012_10120201_6_dialog_content = "Tsk... Eu tenho que encontrá-la rapidamente.",
  ui_story_1012_10120201_7_dialog_content = "Eu pareço ter vindo a este lugar antes?",
  ui_story_1012_10120201_8_dialog_content = "Por que essas antiguidades antigas gostam de cobrir todos os lugares da mesma maneira?",
  ui_story_1012_10120201_9_dialog_content = "É praticamente um labirinto.",
  ui_story_1012_10120201_10_dialog_content = "Poderia... aquele grupo de Eclipsites me atraiu aqui de propósito?",
  ui_story_1012_10120201_11_dialog_content = "... Isso é definitivamente Forsakinplano de!",
  ui_story_1012_10120201_12_dialog_content = "Já que você quer me fechar no labirinto, eu vou rasgá-lo.",
  ui_story_1012_10120201_13_dialog_content = "<color=#e8d9bb>Ranger-!</color>",
  ui_story_1012_10120201_14_dialog_content = "!!!",
  ui_story_1012_10120201_15_dialog_content = "Sibilo—",
  ui_story_1012_10120201_16_dialog_content = "Ai, ai, ai...!",
  ui_story_1012_10120201_17_dialog_content = "De que é feita essa parede? Como é tão difícil?!",
  ui_story_1012_10120201_18_dialog_content = "Blade não deixa marcas nele, mas minhas mãos estão dormentes.",
  ui_story_1012_10120201_19_dialog_content = "Se ao menos eu pudesse desmontá-lo e montá-lo na parede da Cidade Baixa, ou talvez eu o montasse no tanque e o usasse para lidar com Eclipsites. Que maravilhoso.",
  ui_story_1012_10120201_20_dialog_content = "Parece que a tática de perfurar a parede não vai funcionar.",
  ui_story_1012_10120201_21_dialog_content = "Só podemos seguir essas passagens.",
  ui_story_1012_10120201_22_dialog_content = "Mas Forsakin é o líder desse grupo de Eclipsites. Nós apenas temos que ir a lugares onde há muitos Eclipsitos, e isso deve estar correto.",
  ui_story_1012_10120201_23_dialog_content = "Só precisamos passar algum tempo limpando os lacaios.",
  ui_story_1012_10120201_24_dialog_content = "<color=#e8d9bb>Eraveil, nas profundezas da Base de Manutenção Colossus</color>",
  ui_story_1012_10120201_25_dialog_content = "Por favor, vire à direita no cruzamento à frente.",
  ui_story_1012_10120201_26_dialog_content = "Essa base é enorme...",
  ui_story_1012_10120201_27_dialog_content = "Teríamos perdido vários dias nessas passagens complicadas se não tivéssemos o Neural Aux para nos guiar.",
  ui_story_1012_10120201_28_dialog_content = "Se incluirmos a área desmoronada, o escopo dessa base subterrânea pode cobrir toda a área do Eraveil.",
  ui_story_1012_10120201_29_dialog_content = "Especialmente lugares que parecem passagens.",
  ui_story_1012_10120201_30_dialog_content = "Esta largura e altura indicam claramente que não era simplesmente para as pessoas passarem.",
  ui_story_1012_10120201_31_dialog_content = "Ainda não descobri nada quando cheguei aqui, mas já pensei nisso...",
  ui_story_1012_10120201_32_dialog_content = "Essas passagens podem ter sido usadas para permitir a passagem de Colossos.",
  ui_story_1012_10120201_33_dialog_content = "...",
  ui_story_1012_10120201_34_dialog_content = "Quanto a você, você só será responsável por...",
  ui_story_1012_10120201_35_dialog_content = "Criando guerras para o mundo.",
  ui_story_1012_10120201_36_dialog_content = "Os celestitas pilotaram os Colossos por aqui, mas não foi pela paz...",
  ui_story_1012_10120201_37_dialog_content = "Quem são os celestitas...",
  ui_story_1012_10120201_38_dialog_content = "PlayerName.",
  ui_story_1012_10120201_39_dialog_content = "Antes de ser um celestita, você é você mesmo.",
  ui_story_1012_10120201_40_dialog_content = "Hã?",
  ui_story_1012_10120201_41_dialog_content = "Para nós agora, você é você.",
  ui_story_1012_10120201_42_dialog_content = "Você é o Último Celestita que foi salvo do subsolo por Vice.",
  ui_story_1012_10120201_43_dialog_content = "Você é o aliado que ajudou Lumopolis na luta contra Schummer e o Colosso Negro.",
  ui_story_1012_10120201_44_dialog_content = "Você é o aliado que vivenciou inúmeras aventuras junto conosco.",
  ui_story_1012_10120201_45_dialog_content = "Contanto que você ainda seja você e mantenha sua bondade e princípios, não nos importamos se você é um celestita ou um auroriano.",
  ui_story_1012_10120201_46_dialog_content = "Afinal, suas origens não são sua escolha, então você não precisa se culpar por isso.",
  ui_story_1012_10120201_47_dialog_content = "Carleen...",
  ui_story_1012_10120201_48_option_content = "Obrigado por me consolar.",
  ui_story_1012_10120201_49_dialog_content = "Mas devo prosseguir com este assunto.",
  ui_story_1012_10120201_50_dialog_content = "Eu sou o Último Celestita.",
  ui_story_1012_10120201_51_dialog_content = "E parece que eu posso ser a única pessoa neste mundo que pode descobrir os segredos do Eraveil.",
  ui_story_1012_10120201_52_dialog_content = "Se os celestitas realmente eram máquinas de combate no passado, então...",
  ui_story_1012_10120201_53_dialog_content = "Seja Eraveil ou Caelestite, pode se tornar uma ameaça para este mundo.",
  ui_story_1012_10120201_54_dialog_content = "Talvez eu nunca consiga dormir bem se não estudar isso a fundo e resolver os possíveis perigos.",
  ui_story_1012_10120201_55_dialog_content = "Porque não quero me tornar alguém que ameace a segurança dos meus amigos.",
  ui_story_1012_10120201_56_dialog_content = "...",
  ui_story_1012_10120201_57_dialog_content = "Não se force.",
  ui_story_1012_10120201_58_dialog_content = "Eu sei.",
  ui_story_1012_10120201_59_dialog_content = "Não se preocupe, eu tenho uma compreensão clara de mim mesmo.",
  ui_story_1012_10120201_60_dialog_content = "<size=30>Qualquer Eclipsite aleatório pode me mandar voando com um soco...</size>",
  ui_story_1012_10120201_61_dialog_content = "Então, vou contar com vocês quando for a hora de contar com a ajuda de vocês...",
  ui_story_1012_10120201_62_dialog_content = "Ótimo.",
  ui_story_1012_10120201_63_dialog_content = "<color=#e8d9bb>Ranger-!</color>",
  ui_story_1012_10120201_64_dialog_content = "O que é que foi isso?!",
  ui_story_1012_10120201_65_dialog_content = "Algum grande Eclipsite poderia ter entrado?",
  ui_story_1012_10120201_66_dialog_content = "Parece que está perto.",
  ui_story_1012_10120201_67_dialog_content = "Vamos sair daqui rapidamente e seguir em frente.",
  ui_story_1012_10120201_68_dialog_content = "Vice está inconsciente agora, então será difícil se alguma batalha começar.",
  ui_story_1012_10120201_69_dialog_content = "Espera!",
  ui_story_1012_10120201_70_dialog_content = "O que foi?",
  ui_story_1012_10120201_71_dialog_content = "Acho que... estou sentindo os Eclipsites!",
  ui_story_1012_10120201_72_dialog_content = "Atras do!",
  ui_story_1012_10120201_73_dialog_content = "Graaahh—",
  ui_story_1012_10120201_74_dialog_content = "!!!",
  ui_story_1012_10120201_75_dialog_content = "De onde eles vieram?!",
  ui_story_1012_10120201_76_dialog_content = "Eu preciso da sua ajuda, PlayerName!",
  ui_story_1012_10120201_77_dialog_content = "Beleza!",
  ui_story_1012_10120202_1_dialog_content = "Por que existem tantos eclipses...",
  ui_story_1012_10120202_2_dialog_content = "E como é possível que eu não senti nada disso por tanto tempo antes?!",
  ui_story_1012_10120202_3_dialog_content = "Este lugar está abandonado há muito tempo.",
  ui_story_1012_10120202_4_dialog_content = "Se foi originalmente existente ou depois desmoronou para se formar, esta base subterrânea tem inúmeros túneis escuros.",
  ui_story_1012_10120202_5_dialog_content = "Talvez esses Eclipses estejam saindo de alguns túneis escuros que não conhecemos.",
  ui_story_1012_10120202_6_dialog_content = "Você tem razão...",
  ui_story_1012_10120202_7_dialog_content = "O terreno aqui é muito complicado. Mesmo minha habilidade psíquica não pode sentir todos os Eclipsites.",
  ui_story_1012_10120202_8_dialog_content = "Vamos nos apressar e sair daqui. Este não é um lugar que eu gostaria de ficar!",
  ui_story_1012_10120202_9_dialog_content = "Não há nem mesmo uma bifurcação na estrada aqui. Não poderemos fugir se formos atacados pela frente e por trás.",
  ui_story_1012_10120202_10_dialog_content = "...",
  ui_story_1012_10120202_11_dialog_content = "A habilidade psíquica celestita é realmente difícil de lidar.",
  ui_story_1012_10120202_12_dialog_content = "Mas os Eclipsitas são muitos em número.",
  ui_story_1012_10120202_13_dialog_content = "Os resultados do experimento também foram resultado de inúmeros sacrifícios.",
  ui_story_1012_10120202_14_dialog_content = "Qual foi a perturbação agora?",
  ui_story_1012_10120202_15_dialog_content = "(Eclipsiana) Senhora Forsakin, o quale agora era o Illuminan tentando destruir a parede.",
  ui_story_1012_10120202_16_dialog_content = "(Eclipsiano) O terremoto deu início ao Caelestite. e ele usou sua habilidade psíquica para sentir nossa existência.",
  ui_story_1012_10120202_17_dialog_content = "Continue enrolando ele.",
  ui_story_1012_10120202_18_dialog_content = "O celestita está se aproximando do alvo.",
  ui_story_1012_10120202_19_dialog_content = "Essa pessoa imprudente não pode arruinar meu plano.",
  ui_story_1012_10120202_20_dialog_content = "Impedi-lo de vir, mesmo que isso signifique usar cadáveres.",
  ui_story_1012_10120202_21_dialog_content = "(Eclipsiano) Sim, senhora Forsakin!",
  ui_story_1012_10120202_22_dialog_content = "Droga, eles não param de vir!",
  ui_story_1012_10120202_23_dialog_content = "Tentando me parar aqui? Continue sonhando!",
  ui_story_1012_10120202_24_dialog_content = "Saia do meu caminho-!",
  ui_story_1012_10120202_25_dialog_content = "Os Eclipsitas estão vindo desta direção, então isso significa...",
  ui_story_1012_10120202_26_dialog_content = "Forsakin é assim também, né?",
  ui_story_1012_10120202_27_dialog_content = "Eu finalmente peguei você, Forsakin.",
  ui_story_1012_10120401_1_dialog_content = "(Eclipsiano) L-Lady Forsakin!",
  ui_story_1012_10120401_2_dialog_content = "(Eclipsian) Aquele monstro Illumina é muito poderoso! Não podemos detê-lo!",
  ui_story_1012_10120401_3_dialog_content = "(Eclipsiano) Ele está vindo direto para nós!",
  ui_story_1012_10120401_4_dialog_content = "Deve haver um limite para a precipitação deliberada.",
  ui_story_1012_10120401_5_dialog_content = "Ou eu não deveria ter nenhuma expectativa de que um monstro tenha compreensão.",
  ui_story_1012_10120401_6_dialog_content = "Todos vocês juntos, parem-no.",
  ui_story_1012_10120401_7_dialog_content = "(Eclipsiano) D-Será que ainda temos que lutar...",
  ui_story_1012_10120401_8_dialog_content = "Não me faça repetir instruções.",
  ui_story_1012_10120401_9_dialog_content = "(Eclipsiano) Entendido....",
  ui_story_1012_10120401_10_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_1012_10120401_11_dialog_content = "Que som é esse?",
  ui_story_1012_10120401_12_dialog_content = "<color=#e8d9bb>ESTRONDO-!</color>",
  ui_story_1012_10120401_13_dialog_content = "Por—sakin—!",
  ui_story_1012_10120401_14_dialog_content = "Que teimosia tola.",
  ui_story_1012_10120401_15_dialog_content = "Uma criatura como você nem mesmo atenderá aos padrões para ser experimentada.",
  ui_story_1012_10120401_16_dialog_content = "O que quer que você esteja planejando fazer, é definitivamente ruim!",
  ui_story_1012_10120401_17_dialog_content = "Se você quer conduzir experimentos tão mal, faça-os nas celas da prisão de Gannon City.",
  ui_story_1012_10120401_18_dialog_content = "Pessoal, parem com ele.",
  ui_story_1012_10120401_19_dialog_content = "Gaa-!",
  ui_story_1012_10120401_20_dialog_content = "Seus Eclipses só podem fazer isso?",
  ui_story_1012_10120401_21_dialog_content = "Você não é muito capaz então.",
  ui_story_1012_10120401_22_dialog_content = "Você é Reinhardtirmã de, então você deve ser pelo menos metade tão forte quanto ela, não?",
  ui_story_1012_10120401_23_dialog_content = "...",
  ui_story_1012_10120401_24_dialog_content = "Não me compare a um fracasso como esse.",
  ui_story_1012_10120401_25_dialog_content = "Oh? Voce esta brava?",
  ui_story_1012_10120401_26_dialog_content = "Bom, vamos lutar se você está com raiva!",
  ui_story_1012_10120401_27_dialog_content = "Parece que não consigo me concentrar em meus experimentos se não fizer você se acalmar adequadamente.",
  ui_story_1012_10120401_28_dialog_content = "Você. Você está me irritando.",
  ui_story_1012_10120401_29_dialog_content = "É exatamente o que eu quero.",
  ui_story_1012_10120401_30_dialog_content = "voltei aqui de novo...",
  ui_story_1012_10120401_31_dialog_content = "Ainda não consigo me acostumar com a atmosfera daqui, então não importa quantas vezes eu a veja.",
  ui_story_1012_10120401_32_dialog_content = "Também não gosto deste lugar.",
  ui_story_1012_10120401_33_dialog_content = "Vamos nos apressar e encontrar a entrada para a Chord Zone.",
  ui_story_1012_10120401_34_dialog_content = "Chegou ao portão da Chord Zone.",
  ui_story_1012_10120401_35_dialog_content = "Quebrando o controle de acesso. O Neural Aux não poderá aceitar outros comandos durante o processo. Por favor, espere.",
  ui_story_1012_10120401_36_dialog_content = "1%... 2%... 5%...",
  ui_story_1012_10120401_37_dialog_content = "Parece que vai demorar um pouco.",
  ui_story_1012_10120401_38_dialog_content = "Sim, então eu vou...",
  ui_story_1012_10120401_39_dialog_content = "Isso é...",
  ui_story_1012_10120401_40_dialog_content = "O que foi?",
  ui_story_1012_10120401_41_dialog_content = "eu senti Forsakinaura de... Ela entrou na torre!",
  ui_story_1012_10120401_42_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_1012_10120401_43_dialog_content = "Que diabos é essa comoção?!",
  ui_story_1012_10120401_44_dialog_content = "Está roncando há um tempo atrás...",
  ui_story_1012_10120401_45_dialog_content = "É isso Forsakin?",
  ui_story_1012_10120401_46_dialog_content = "Poderia Forsakin estar incitando os Eclipsites na torre para causar estragos?",
  ui_story_1012_10120401_47_dialog_content = "Ou algo na torre desabou?",
  ui_story_1012_10120401_48_dialog_content = "<color=#e8d9bb>ESTRONDO-!</color>",
  ui_story_1012_10120401_49_dialog_content = "Uau! O que há com toda essa sujeira?!",
  ui_story_1012_10120401_50_dialog_content = "Atenção! Algo está saindo da sujeira!",
  ui_story_1012_10120401_51_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_1012_10120401_52_dialog_content = "Você está no caminho.",
  ui_story_1012_10120401_53_dialog_content = "Não se distraia, Forsakin—!",
  ui_story_1012_10120401_54_dialog_content = "Seu oponente sou eu.",
  ui_story_1012_10120401_55_dialog_content = "Barton?! Então era você!",
  ui_story_1012_10120401_56_dialog_content = "Ei, PlayerName. Você também está aqui?",
  ui_story_1012_10120401_57_dialog_content = "O que há com Vice? Ela desmaiou?",
  ui_story_1012_10120401_58_dialog_content = "Vice está ferida, e precisamos abrir este portão para encontrar uma maneira de salvá-la!",
  ui_story_1012_10120401_59_dialog_content = "Barton, ajude-nos a parar Forsakin!",
  ui_story_1012_10120401_60_dialog_content = "Ganhar tempo...? Claro!",
  ui_story_1012_10120401_61_dialog_content = "Vocês apenas fiquem atrás de mim e lidem com aqueles lacaios!",
  ui_story_1012_10120401_62_dialog_content = "Que palavras bonitas.",
  ui_story_1012_10120401_63_dialog_content = "Sugiro que cesse a resistência.",
  ui_story_1012_10120401_64_dialog_content = "Você deve estar ciente da lacuna entre você e eu.",
  ui_story_1012_10120401_65_dialog_content = "Eu não quero perder tempo com você, e você provavelmente não quer perder suas vidas também.",
  ui_story_1012_10120401_66_dialog_content = "Então dê acesso a essa máquina para mim, e desista.",
  ui_story_1012_10120401_67_dialog_content = "Eu vou deixar você viver.",
  ui_story_1012_10120401_68_dialog_content = "Bem, eu sugiro que você dê um bom soco na cara para acordá-lo de sua ilusão!",
  ui_story_1012_10120401_69_dialog_content = "Então, o que você decide, Celestita?",
  ui_story_1012_10120401_70_dialog_content = "Você vai morrer como este Illuminan imprudente?",
  ui_story_1012_10120401_71_dialog_content = "...",
  ui_story_1012_10120401_72_option_content = "Eu não vou acreditar em você.",
  ui_story_1012_10120401_73_dialog_content = "Ah?",
  ui_story_1012_10120401_74_dialog_content = "Você enganou muita gente.",
  ui_story_1012_10120401_75_dialog_content = "Gertzurde, Shelt, Schummer...",
  ui_story_1012_10120401_76_dialog_content = "Você não se importava se algum deles vivesse ou morresse! Você só se preocupa consigo mesmo!",
  ui_story_1012_10120401_77_dialog_content = "Você não pode ser confiável em tudo!",
  ui_story_1012_10120401_78_dialog_content = "...",
  ui_story_1012_10120401_79_dialog_content = "Minha paciência se esgota.",
  ui_story_1012_10120401_80_dialog_content = "Entregue o acesso e eu agilizarei as coisas.",
  ui_story_1012_10120401_81_dialog_content = "Eu nunca, nunca vou entregá-lo a você!",
  ui_story_1012_10120401_82_dialog_content = "Resistência inútil.",
  ui_story_1012_10120401_83_dialog_content = "Então...",
  ui_story_1012_10120401_84_dialog_content = "Adeus.",
  ui_story_1012_10120402_1_dialog_content = "Cuidado, PlayerName!",
  ui_story_1012_10120402_2_dialog_content = "Aah—! Ajuda!",
  ui_story_1012_10120402_3_dialog_content = "!!",
  ui_story_1012_10120402_4_dialog_content = "Ai!",
  ui_story_1012_10120402_5_dialog_content = "Não se distraia ao lutar.",
  ui_story_1012_10120402_6_dialog_content = "Você mesmo disse isso.",
  ui_story_1012_10120402_7_dialog_content = "Barton!",
  ui_story_1012_10120402_8_dialog_content = "Tsc...",
  ui_story_1012_10120402_9_dialog_content = "Essa é toda a força que você tem? Você tem se alimentado corretamente?",
  ui_story_1012_10120402_10_dialog_content = "Você tem causado problemas de fora da torre até aqui.",
  ui_story_1012_10120402_11_dialog_content = "Você deve ter ficado sem energia agora.",
  ui_story_1012_10120402_12_dialog_content = "...",
  ui_story_1012_10120402_13_dialog_content = "Não há necessidade de lutar desnecessariamente.",
  ui_story_1012_10120402_14_dialog_content = "Bah! Corte o absurdo!",
  ui_story_1012_10120402_15_dialog_content = "Trazem-!",
  ui_story_1012_10120402_16_dialog_content = "Você estaria melhor se gastasse metade do tempo que gasta lutando estudando.",
  ui_story_1012_10120402_17_dialog_content = "Estudo?",
  ui_story_1012_10120402_18_dialog_content = "Então, pessoas como você existem – o tipo que está pedindo uma surra à vista.",
  ui_story_1012_10120402_19_dialog_content = "Quando posso me acalmar para estudar?",
  ui_story_1012_10120402_20_dialog_content = "Você deve pagar por sua ignorância.",
  ui_story_1012_10120402_21_dialog_content = "Argh!",
  ui_story_1012_10120402_22_dialog_content = "Seu pulso direito agora está quebrado.",
  ui_story_1012_10120402_23_dialog_content = "Eu gostaria de ver como você vai pegar essa faca.",
  ui_story_1012_10120402_24_dialog_content = "Ou...",
  ui_story_1012_10120402_25_dialog_content = "Você poderia simplesmente ficar de joelhos e me implorar para parar.",
  ui_story_1012_10120402_26_dialog_content = "Pare com isso, Forsakin!",
  ui_story_1012_10120402_27_dialog_content = "Cale-se.",
  ui_story_1012_10120402_28_dialog_content = "Você não tem o direito de falar, fraco e inútil celestita.",
  ui_story_1012_10120402_29_dialog_content = "O exército Illumina...",
  ui_story_1012_10120402_30_dialog_content = "Hum?",
  ui_story_1012_10120402_31_dialog_content = "O exército Illumina... nunca cederá a pessoas como você!",
  ui_story_1012_10120402_32_dialog_content = "!!!",
  ui_story_1012_10120402_33_dialog_content = "Mesmo que eu tenha apenas uma mão, é mais do que suficiente para derrubá-lo!",
  ui_story_1012_10120402_34_dialog_content = "Barton! Sua perna!",
  ui_story_1012_10120402_35_dialog_content = "Ajudem-no, Carleen!",
  ui_story_1012_10120402_36_dialog_content = "Dispersem, pétalas de gelo!",
  ui_story_1012_10120402_37_dialog_content = "De jeito nenhum! Há apenas muitos deles!",
  ui_story_1012_10120402_38_dialog_content = "Não se preocupe comigo!",
  ui_story_1012_10120402_39_dialog_content = "Basta abrir o portão! eu vou lidar Forsakin!",
  ui_story_1012_10120402_40_dialog_content = "Mas você já está...",
  ui_story_1012_10120402_41_dialog_content = "!!!",
  ui_story_1012_10120402_42_dialog_content = "Vai!",
  ui_story_1012_10120402_43_dialog_content = "Mas...!",
  ui_story_1012_10120402_44_dialog_content = "Encontre uma saída!",
  ui_story_1012_10120402_45_dialog_content = "Se eu cair em batalha, escreva isso na minha lápide—",
  ui_story_1012_10120402_46_dialog_content = "Um glorioso soldado da Illumina que lutou contra os Eclipsitas até o fim!",
  ui_story_1012_10120402_47_dialog_content = "PlayerName, precisamos de espaço para recuar!",
  ui_story_1012_10120402_48_dialog_content = "Nós vamos morrer se ficarmos presos aqui!",
  ui_story_1012_10120402_49_dialog_content = "...!",
  ui_story_1012_10120402_50_dialog_content = "Neural Aux, qual é o progresso do cracking?!",
  ui_story_1012_10120402_51_dialog_content = "A quebra do portão está em 96%, aguarde.",
  ui_story_1012_10120402_52_dialog_content = "... Espere um pouco mais!",
  ui_story_1012_10120402_53_dialog_content = "97%.",
  ui_story_1012_10120402_54_dialog_content = "98%.",
  ui_story_1012_10120402_55_dialog_content = "99%.",
  ui_story_1012_10120402_56_dialog_content = "100%, craqueamento completo.",
  ui_story_1012_10120402_57_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_1012_10120402_58_dialog_content = "O portão... está aberto!",
  ui_story_1012_10120402_59_dialog_content = "Carleen, Barton, retirar o!",
  ui_story_1012_10120501_1_dialog_content = "Gelescer!",
  ui_story_1012_10120501_2_dialog_content = "Pressa! Forsakin está vindo atrás de nós e eu não posso segurá-la por muito tempo!",
  ui_story_1012_10120501_3_dialog_content = "Vocês vão por aqui. Barton, proteger PlayerName!",
  ui_story_1012_10120501_4_dialog_content = "Não se preocupe, eu posso estar ferido, mas não vou deixar Forsakin coloque um dedo nele!",
  ui_story_1012_10120501_5_dialog_content = "Quanto falta, Neural Aux?",
  ui_story_1012_10120501_6_dialog_content = "Siga em frente por 650 pés e você chegará ao seu destino.",
  ui_story_1012_10120501_7_dialog_content = "Huff... Huff... Quase... lá!",
  ui_story_1012_10120501_8_dialog_content = "Eu posso ver o portão!",
  ui_story_1012_10120501_9_dialog_content = "Eu não posso—",
  ui_story_1012_10120501_10_dialog_content = "Por que o chão é tão irregular aqui?!",
  ui_story_1012_10120501_11_dialog_content = "Eu especulo que a estrutura da estrada da Chord Zone mudou devido a mudanças no terreno.",
  ui_story_1012_10120501_12_dialog_content = "Mas, por favor, confie que a rota fornecida pelo Neural Aux é precisa!",
  ui_story_1012_10120501_13_dialog_content = "Gerente, por favor, não desista! Continue!",
  ui_story_1012_10120501_14_dialog_content = "Eu... não vou desistir!",
  ui_story_1012_10120501_15_dialog_content = "PlayerName, não pare!",
  ui_story_1012_10120501_16_dialog_content = "Continue correndo, garoto!",
  ui_story_1012_10120501_17_dialog_content = "Eu vou chutá-lo enquanto o faço correr 100 voltas ao redor de Gannon City se você ousar parar!",
  ui_story_1012_10120501_18_dialog_content = "Você não precisa ser tão violento ao tentar me confortar!",
  ui_story_1012_10120501_19_dialog_content = "Caramba-!",
  ui_story_1012_10120501_20_dialog_content = "Auxiliar Neural!",
  ui_story_1012_10120501_21_dialog_content = "Neural Aux Navigation, ao seu serviço!",
  ui_story_1012_10120501_22_dialog_content = "Feche os portões logo após entrarmos na Chord Zone!",
  ui_story_1012_10120501_23_dialog_content = "Feche esses Eclipses lá fora!",
  ui_story_1012_10120501_24_dialog_content = "Entendido!",
  ui_story_1012_10120501_25_dialog_content = "Mas, gerente, preste atenção nas armadilhas sob seus pés!",
  ui_story_1012_10120501_26_option_content = "Armadilha?",
  ui_story_1012_10120501_27_dialog_content = "Por que existem armadilhas neste lugar?!",
  ui_story_1012_10120501_28_option_content = "Há armadilhas também?!",
  ui_story_1012_10120501_29_dialog_content = "De onde eles vieram?!",
  ui_story_1012_10120501_30_dialog_content = "Essas armadilhas são dispositivos de defesa independentes da Chord Zone.",
  ui_story_1012_10120501_31_dialog_content = "A ligação entre Neural Aux e a Chord Zone foi quebrada. Neural Aux não pode controlar as armadilhas na Chord Zone.",
  ui_story_1012_10120501_32_dialog_content = "Essas armadilhas estão atualmente preparadas para atacar após a detecção!",
  ui_story_1012_10120501_33_dialog_content = "Gerente, faça o que achar melhor... não, quero dizer, esquive-se como achar melhor!",
  ui_story_1012_10120501_34_dialog_content = "Você deveria dizer isso antes!",
  ui_story_1012_10120501_35_dialog_content = "O fato de existirem armadilhas na Chord Zone foi oficialmente incluído nos livros didáticos do Caelestite.",
  ui_story_1012_10120501_36_dialog_content = "Se você esqueceu, Gerente, Neural Aux recomenda re-entrar na escola para aprender!",
  ui_story_1012_10120501_37_dialog_content = "Observe onde você pisa, PlayerName!",
  ui_story_1012_10120501_38_dialog_content = "Hã?",
  ui_story_1012_10120501_39_dialog_content = "<color=#e8d9bb>Clique-</color>",
  ui_story_1012_10120501_40_dialog_content = "PlayerName, saia da frente!",
  ui_story_1012_10120501_41_dialog_content = "Ahhh!",
  ui_story_1012_10120501_42_dialog_content = "...",
  ui_story_1012_10120501_43_dialog_content = "Gerente, esquive!",
  ui_story_1012_10120501_44_dialog_content = "Essa coisa tem capacidade de combate?",
  ui_story_1012_10120501_45_dialog_content = "Jogue fora se isso acontecer! Pelo menos vai aguentar Forsakin fora por um tempo!",
  ui_story_1012_10120501_46_dialog_content = "Sou apenas uma imagem projetada e não tenho habilidade de combate.",
  ui_story_1012_10120501_47_dialog_content = "É proibido forçar o Neural Aux a realizar tarefas de combate que estejam fora de suas funções!",
  ui_story_1012_10120501_48_dialog_content = "Diga-nos a localização das armadilhas então!",
  ui_story_1012_10120501_49_dialog_content = "Eu, estou procurando dados sobre as armadilhas na Chord Zone—",
  ui_story_1012_10120501_50_dialog_content = "Pesquisa concluída!",
  ui_story_1012_10120501_51_dialog_content = "Dodge para a direita à frente!",
  ui_story_1012_10120501_52_dialog_content = "Oh não, os Eclipsites estão alcançando!",
  ui_story_1012_10120501_53_dialog_content = "Encontre uma maneira de usar as armadilhas para tirá-las do nosso rabo!",
  ui_story_1012_10120502_1_dialog_content = "Gerente, você está se aproximando do seu destino.",
  ui_story_1012_10120502_2_dialog_content = "Inicializando o fechamento do portão Chord Zone.",
  ui_story_1012_10120502_3_dialog_content = "Gerente, por favor, entre na Chord Zone antes que o portão feche!",
  ui_story_1012_10120502_4_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_1012_10120502_5_dialog_content = "Aguentar! Isso é muito rápido!",
  ui_story_1012_10120502_6_dialog_content = "Não vamos conseguir!",
  ui_story_1012_10120502_7_dialog_content = "Pare-os! Não deixe que esses bugs danifiquem o equipamento interno.",
  ui_story_1012_10120502_8_dialog_content = "PlayerName, pense em algo!",
  ui_story_1012_10120502_9_dialog_content = "Temos que colocar distância entre nós e os Eclipsites!",
  ui_story_1012_10120502_10_dialog_content = "Uma solução... solução... Onde posso obter uma solução?!",
  ui_story_1012_10120502_11_dialog_content = "Há uma armadilha explosiva à frente! Cuidado, e esquivar-se!",
  ui_story_1012_10120502_12_dialog_content = "Armadilha explosiva?",
  ui_story_1012_10120502_13_dialog_content = "Garoto, vá pisar nessa armadilha explosiva!",
  ui_story_1012_10120502_14_dialog_content = "Hã?!",
  ui_story_1012_10120502_15_dialog_content = "Confie em mim, pise na armadilha e pronto!",
  ui_story_1012_10120502_16_dialog_content = "Você não está fugindo.",
  ui_story_1012_10120502_17_dialog_content = "Vou confiar apenas desta vez!",
  ui_story_1012_10120502_18_dialog_content = "<color=#e8d9bb>Clique!</color>",
  ui_story_1012_10120502_19_dialog_content = "Segure firme, garoto!",
  ui_story_1012_10120502_20_dialog_content = "<color=#e8d9bb>Bate, bate!</color>",
  ui_story_1012_10120502_21_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_1012_10120502_22_dialog_content = "Isto é-!",
  ui_story_1012_10120502_23_dialog_content = "Ahhh! Nós seremos explodidos no céuyyy-!",
  ui_story_1012_10120502_24_dialog_content = "<color=#e8d9bb>Boom - TUNK!</color>",
  ui_story_1012_10120502_25_dialog_content = "Você realmente é o monstro da Illumina.",
  ui_story_1012_10120502_26_dialog_content = "Muitos de seus métodos envolvem quase perder sua vida.",
  ui_story_1012_10120502_27_dialog_content = "Derrube este portão.",
  ui_story_1012_10120502_28_dialog_content = "(Eclipsiano) Sim, senhora Forsakin!",
  ui_story_1012_10120502_29_dialog_content = "Nós... conseguimos?",
  ui_story_1012_10120502_30_dialog_content = "Ainda estou vivo, pelo menos...",
  ui_story_1012_10120502_31_dialog_content = "Vice também não está machucado.",
  ui_story_1012_10120502_32_dialog_content = "Ufa... Espere, onde está Barton?!",
  ui_story_1012_10120502_33_dialog_content = "eu... estou bem...",
  ui_story_1012_10120502_34_dialog_content = "Tsk... Mas aquela bomba que o Caelestita fez era bem poderosa.",
  ui_story_1012_10120502_35_dialog_content = "Teríamos perdido se eu não o tivesse detonado cedo.",
  ui_story_1012_10120502_36_dialog_content = "Você obviamente não está bem!",
  ui_story_1012_10120502_37_dialog_content = "Aham... Relaxa, garoto...",
  ui_story_1012_10120502_38_dialog_content = "O povo de Illumina passou por duras batalhas. Feridas como essas só precisam de um curativo e ficarão bem depois de uma noite de sono.",
  ui_story_1012_10120502_39_dialog_content = "Se corrermos para o médico com um pequeno ferimento, seremos agarrados pelas costas de nossos colarinhos e jogados para fora da enfermaria.",
  ui_story_1012_10120502_40_dialog_content = "Não se preocupe comigo... É isso que vocês estão procurando, certo?",
  ui_story_1012_10120502_41_dialog_content = "Neural Aux, este é o Chord Link?",
  ui_story_1012_10120502_42_dialog_content = "Acho que deve ser isso!",
  ui_story_1012_10120502_43_dialog_content = "Sua dedução está correta?",
  ui_story_1012_10120502_44_dialog_content = "Existem registros deste sistema?",
  ui_story_1012_10120502_45_dialog_content = "O Chord Link é o sistema principal da Chord Zone.",
  ui_story_1012_10120502_46_dialog_content = "De acordo com as informações coletadas, o dispositivo em frente ao Manager deve ser o Chord Link.",
  ui_story_1012_10120502_47_dialog_content = "<color=#e8d9bb>Baque-!</color>",
  ui_story_1012_10120502_48_dialog_content = "Aqueles Eclipses estão tentando derrubar o portão!",
  ui_story_1012_10120502_49_dialog_content = "Não se preocupe com eles por enquanto.",
  ui_story_1012_10120502_50_dialog_content = "As paredes e as portas desta base são fortes. Eu não conseguia atravessá-los mesmo depois de bater neles por horas.",
  ui_story_1012_10120502_51_dialog_content = "<color=#e8d9bb>BAQUE-!</color>",
  ui_story_1012_10120502_52_dialog_content = "Uh... Há um amassado no portão!",
  ui_story_1012_10120502_53_dialog_content = "Neural Aux, existe alguma maneira de reforçar o portão?",
  ui_story_1012_10120502_54_dialog_content = "Ativando a função de aprimoramento Chord Zone Access Control!",
  ui_story_1012_10120502_55_dialog_content = "<color=#e8d9bb>Clique—Clique—</color>",
  ui_story_1012_10120502_56_dialog_content = "Mais portas seladas novamente.",
  ui_story_1012_10120502_57_dialog_content = "Parece que eles devem segurar por mais algum tempo.",
  ui_story_1012_10120502_58_dialog_content = "<color=#e8d9bb>TOC Toc...</color>",
  ui_story_1012_10120502_59_dialog_content = "O ataque parou?",
  ui_story_1012_10120502_60_dialog_content = "<color=#e8d9bb>Uau!!!</color>",
  ui_story_1012_10120502_61_dialog_content = "Por que o ataque está mais feroz do que antes?!",
  ui_story_1012_10120502_62_dialog_content = "Essas cabeças de Eclipses são feitas de aço?!",
  ui_story_1012_10120502_63_dialog_content = "Ah! Forsakin me chama de teimosa quando ela mesma é muito teimosa!",
  ui_story_1012_10120502_64_dialog_content = "Volte desde que você bateu na parede!",
  ui_story_1012_10120502_65_dialog_content = "Eles logo vão abrir a porta se isso continuar.",
  ui_story_1012_10120502_66_dialog_content = "PlayerName, apresse-se e ative o Chord Link para curar Vice.",
  ui_story_1012_10120502_67_dialog_content = "Se Vice for revivido, podemos sair daqui juntos. Ainda pode haver esperança!",
  ui_story_1012_10120502_68_dialog_content = "Neural Aux, me ajude a ativar o Chord Link!",
  ui_story_1012_10120502_69_dialog_content = "Ative o link de acordes!",
  ui_story_1012_10120502_70_dialog_content = "Pesquise registros de experimentos para confirmar os efeitos e efeitos colaterais do Chord Link!",
  ui_story_1012_10120502_71_dialog_content = "Procurando... Erro!",
  ui_story_1012_10120502_72_dialog_content = "Não consigo recuperar os registros do experimento!",
  ui_story_1012_10120502_73_dialog_content = "O quê?!",
  ui_story_1012_10120502_74_dialog_content = "Você não disse que os registros do experimento estavam todos armazenados aqui?",
  ui_story_1012_10120502_75_dialog_content = "Por que eles não podem ser recuperados?!",
  ui_story_1012_10120502_76_dialog_content = "Estou desconectado da Chord Zone há muito tempo, então não se sabe muito sobre a situação da Chord Zone.",
  ui_story_1012_10120502_77_dialog_content = "Detectei registros excluídos nos arquivos da Chord Zone.",
  ui_story_1012_10120502_78_dialog_content = "Os dados foram perdidos há muito tempo e não podem ser recuperados.",
  ui_story_1012_10120502_79_dialog_content = "Err...",
  ui_story_1012_10120502_80_dialog_content = "Então, vocês vão usar um brinquedo não testado em Vice?",
  ui_story_1012_10120502_81_dialog_content = "Não, eu ia encontrar os registros do experimento primeiro, mas todos eles se foram agora...",
  ui_story_1012_10120502_82_dialog_content = "Barton, Carleen, Por favor, aguarde.",
  ui_story_1012_10120502_83_dialog_content = "Vou verificar os efeitos do Chord Link!",
  ui_story_1012_10120502_84_dialog_content = "Espere, você não é um auroriano. Os resultados são ainda mais claros se você o usou.",
  ui_story_1012_10120502_85_dialog_content = "Mas eu não posso fazer Vice arriscar.",
  ui_story_1012_10120502_86_dialog_content = "Forsakin vai lutar seu caminho em breve. Vocês dois com certeza podem lutar...",
  ui_story_1012_10120502_87_dialog_content = "Eu sou um celestita que nem sabe usar Luminatics. Eu sou mais adequado para experimentação!",
  ui_story_1012_10120502_88_dialog_content = "Para!",
  ui_story_1012_10120502_89_dialog_content = "Não me pare!",
  ui_story_1012_10120502_90_dialog_content = "Acalmar!",
  ui_story_1012_10120502_91_dialog_content = "Você sabe para que essa coisa pode ser usada?",
  ui_story_1012_10120502_92_dialog_content = "O Chord Link pode curar feridas, modificar parcialmente os corpos dos Aurorianos e ativar seu potencial também.",
  ui_story_1012_10120502_93_dialog_content = "Pode curar, né?",
  ui_story_1012_10120502_94_dialog_content = "Então eu vou!",
  ui_story_1012_10120502_95_dialog_content = "Mas eu nem sei que efeitos colaterais tem, qual é a taxa de sucesso, ou se alguém morreria!",
  ui_story_1012_10120502_96_dialog_content = "Então eu deveria ser o único a fazê-lo!",
  ui_story_1012_10120502_97_dialog_content = "Está tentando procurar uma cobaia, garoto?",
  ui_story_1012_10120502_98_dialog_content = "Estou muito ferido, só posso aparar um ou dois movimentos no máximo se enfrentar Forsakin.",
  ui_story_1012_10120502_99_dialog_content = "Se você ficar do lado de fora e coordenar com Carleen, você poderá aguentar por mais algum tempo.",
  ui_story_1012_10120502_100_dialog_content = "Então deixe-me ir.",
  ui_story_1012_10120502_101_dialog_content = "Se essa máquina pode me curar, eu darei Forsakin uma surpresa.",
  ui_story_1012_10120502_102_dialog_content = "E então você pode ficar tranquilo e usá-lo para economizar Vice.",
  ui_story_1012_10120502_103_dialog_content = "... Tá bem.",
  ui_story_1012_10120502_104_dialog_content = "Vocês dois cuidam disso então.",
  ui_story_1012_10120502_105_dialog_content = "Feche aqueles Eclipsites do lado de fora e mantenha-os fora!",
  ui_story_1012_10120502_106_dialog_content = "<color=#e8d9bb>Uau!!!</color>",
  ui_story_1012_10120502_107_dialog_content = "Grrrrr!",
  ui_story_1012_10120502_108_dialog_content = "Mais forte que os materiais usados na Cidade Baixa, mas mais leve.",
  ui_story_1012_10120502_109_dialog_content = "Os materiais de construção e porta usados são mais semelhantes ao Colossus Patch.",
  ui_story_1012_10120502_110_dialog_content = "O Colosso e o Celestita, e até o Eclipsita...",
  ui_story_1012_10120502_111_dialog_content = "Talvez até o Eclipse não conhecesse esse segredo.",
  ui_story_1012_10120502_112_dialog_content = "Me faz ter expectativas.",
  ui_story_1012_10120502_113_dialog_content = "(Eclipsiana) Senhora Forsakin, Lord Figerald ordenou-me que lhe entregasse uma mensagem.",
  ui_story_1012_10120502_114_dialog_content = "(Eclipsiano) O exército terminou de se reunir do lado de fora da torre.",
  ui_story_1012_10120502_115_dialog_content = "(Eclipsian) Mas a mudança da Torre Branca chamou a atenção de Illumina, Lumopolis e Northland.",
  ui_story_1012_10120502_116_dialog_content = "(Eclipsiano) Seus reforçadores responderam de todos os lados.",
  ui_story_1012_10120502_117_dialog_content = "(Eclipsiano) Reinhardt e Bethlehem estão entre eles.",
  ui_story_1012_10120502_118_dialog_content = "Eles geralmente têm medo da menor coisa, mas estão saindo de seus covis agora.",
  ui_story_1012_10120502_119_dialog_content = "Eles com certeza têm ouvidos sensíveis.",
  ui_story_1012_10120502_120_dialog_content = "Diga a Figerald. Pare-os.",
  ui_story_1012_10120502_121_dialog_content = "Meus experimentos ainda precisam de tempo.",
  ui_story_1012_10120502_122_dialog_content = "(Eclipsiano) Lord Figerald me disse para lembrá-lo disso.",
  ui_story_1012_10120502_123_dialog_content = "(Eclipsiano) Não faça nada desnecessário.",
  ui_story_1012_10120502_124_dialog_content = "Se ele realmente quer ajudar, não deveria continuar me incomodando.",
  ui_story_1012_10120502_125_dialog_content = "...",
  ui_story_1012_10120502_126_dialog_content = "(Eclipsiano) Isso é o que Lady Forsakin disse...",
  ui_story_1012_10120502_127_dialog_content = "(Eclipsiano) Isso Forsakin parece precisar de alguns pequenos lembretes.",
  ui_story_1012_10120502_128_dialog_content = "(Eclipsiano) Não é hora... ainda.",
  ui_story_1012_10120502_129_dialog_content = "(Eclipsian) Illumina, Lumopolis e até Northland fizeram movimentos.",
  ui_story_1012_10120502_130_dialog_content = "(Eclipsiano) Lord Figerald, você gostaria de detê-los?",
  ui_story_1012_10120502_131_dialog_content = "(Eclipsian) Vá em frente se quiser se divertir.",
  ui_story_1012_10120502_132_dialog_content = "(Eclipsiano) Mas não há necessidade de lutar até a morte. Poupar mais um ou dois não importa.",
  ui_story_1012_10120502_133_dialog_content = "(Eclipsiano) Coloque pressão sobre Forsakin para fazê-la mostrar seu valor.",
  ui_story_1012_10120502_134_dialog_content = "(Eclipsiano) Sim, Lord Figerald.",
  ui_story_1012_10120601_1_dialog_content = "<color=#e8d9bb>Alerta do sistema: Chord Link agora está ativo... Não interrompa o processo de sincronização...</color>",
  ui_story_1012_10120601_2_dialog_content = "<color=#e8d9bb>Bate... baque... baque... baque...</color>",
  ui_story_1012_10120601_3_dialog_content = "O que é esse som?",
  ui_story_1012_10120601_4_dialog_content = "Parece vir de todos os lugares... Um som realmente desconfortável.",
  ui_story_1012_10120601_5_dialog_content = "Em vez de desconfortável, é mais assustador.",
  ui_story_1012_10120601_6_dialog_content = "Isso soa como...",
  ui_story_1012_10120601_7_option_content = "Sons de terremoto.",
  ui_story_1012_10120601_8_dialog_content = "A intensidade das vibrações nem é tão forte quanto quando o Obelisco do Retorno estava subindo.",
  ui_story_1012_10120601_9_dialog_content = "Todas as paredes do Núcleo Central estão tremendo com ele...",
  ui_story_1012_10120601_10_dialog_content = "Como se este lugar estivesse prestes a desabar.",
  ui_story_1012_10120601_11_option_content = "Sons de batimentos cardíacos.",
  ui_story_1012_10120601_12_dialog_content = "Eles soam como uma batida constante.",
  ui_story_1012_10120601_13_dialog_content = "Posso sentir uma energia terrível nesse ritmo...",
  ui_story_1012_10120601_14_dialog_content = "É como a câmara do coração de um gigante.",
  ui_story_1012_10120601_15_dialog_content = "É este o poder do Chord Link...?",
  ui_story_1012_10120601_16_dialog_content = "Entendo... Um som muito perturbador.",
  ui_story_1012_10120601_17_dialog_content = "Só não sabemos quanto tempo isso vai durar.",
  ui_story_1012_10120601_18_dialog_content = "Barton, ele...",
  ui_story_1012_10120601_19_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1012_10120601_20_dialog_content = "?!",
  ui_story_1012_10120601_21_dialog_content = "Esse som definitivamente não foi causado pelo Chord Link, certo?",
  ui_story_1012_10120601_22_dialog_content = "Aviso: Intrusos ilegais detectados 100 pés à frente.",
  ui_story_1012_10120601_23_dialog_content = "Ela ainda veio. Neural Aux, modifique a estrutura e feche a porta aqui!",
  ui_story_1012_10120601_24_dialog_content = "Recebido... Erro! Erro!",
  ui_story_1012_10120601_25_dialog_content = "Organismos vivos detectados na entrada da Chord Zone. Não pode fechar.",
  ui_story_1012_10120601_26_dialog_content = "Não temos outra escolha. Prepare-se, PlayerName!",
  ui_story_1012_10120601_27_dialog_content = "Hm... A Sincronização ainda está em andamento. Temos que proteger Barton!",
  ui_story_1012_10120601_28_dialog_content = "(... Qualquer que seja o resultado da Sincronização)",
  ui_story_1012_10120601_29_dialog_content = "Aviso: Intrusos ilegais detectados 30 pés à frente.",
  ui_story_1012_10120601_30_dialog_content = "Repetir! Intrusos ilegais detectados 30 pés à frente.",
  ui_story_1012_10120601_31_dialog_content = "Repetir! Intrusos ilegais detectados 30 pés à frente...",
  ui_story_1012_10120601_32_dialog_content = "Parou?",
  ui_story_1012_10120601_33_dialog_content = "M-Mesmo...?",
  ui_story_1012_10120601_34_dialog_content = "<color=#e8d9bb><size=45>BANG!!!</size></color>",
  ui_story_1012_10120601_35_dialog_content = "Intrusos ilegais?",
  ui_story_1012_10120601_36_dialog_content = "Acabei de fazer as mesmas coisas que vocês fizeram.",
  ui_story_1012_10120601_37_dialog_content = "A única diferença está em quem veio primeiro e quem veio em seguida.",
  ui_story_1012_10120601_38_dialog_content = "...Hã?",
  ui_story_1012_10120601_39_dialog_content = "Portanto, ainda existem dispositivos perturbadores escondidos no nível mais profundo deste cemitério.",
  ui_story_1012_10120601_40_dialog_content = "Vocês ainda estão um passo à minha frente em todo esse \"matar Barton\" coisa.",
  ui_story_1012_10120601_41_dialog_content = "Não fale bobagem!",
  ui_story_1012_10120601_42_dialog_content = "PlayerName, pare de desperdiçar seu tempo com ela!",
  ui_story_1012_10120601_43_dialog_content = "Ela não pode ir mais fundo. Vice ainda está lá!",
  ui_story_1012_10120601_44_dialog_content = "Muitas coisas no mundo não se desenvolverão da maneira que você deseja.",
  ui_story_1012_10120601_45_dialog_content = "PlayerName, como um celestita, e tendo deixado os Colossos por muito tempo, estou surpreso que você ainda precise que eu lhe diga essa verdade.",
  ui_story_1012_10120601_46_dialog_content = "Você não precisa que eu explique o que aconteceu com o último celestita que foi contra mim.",
  ui_story_1012_10120601_47_dialog_content = "Você...",
  ui_story_1012_10120601_48_dialog_content = "(Eclipsiano) Ataque.",
  ui_story_1012_10120601_49_dialog_content = "(Eclipsiano) Roger!",
  ui_story_1012_10120702_1_dialog_content = "Gaaah!",
  ui_story_1012_10120702_2_dialog_content = "Ha!",
  ui_story_1012_10120702_3_dialog_content = "Argh...",
  ui_story_1012_10120702_4_dialog_content = "Às suas costas! Carleen!",
  ui_story_1012_10120702_5_dialog_content = "Wha...?!",
  ui_story_1012_10120702_6_dialog_content = "Gaaaaaa!!!",
  ui_story_1012_10120702_7_dialog_content = "Hum...",
  ui_story_1012_10120702_8_dialog_content = "(Isso não vai funcionar. Forsakin trouxe muitos Eclipsitas.)",
  ui_story_1012_10120702_9_dialog_content = "(Talvez disparar o rifle seja mais eficiente do que ligar com Carleenconsciência de!)",
  ui_story_1012_10120702_10_dialog_content = "Hã?!",
  ui_story_1012_10120702_11_dialog_content = "Eu não faço ideia. Quando você aprendeu a usar uma arma, PlayerName?",
  ui_story_1012_10120702_12_dialog_content = "Hmm... Parece uma arma Caelestite. Pode ser considerado uma relíquia.",
  ui_story_1012_10120702_13_dialog_content = "Isto é que é bom.",
  ui_story_1012_10120702_14_dialog_content = "Eu vou levar. Obrigada, PlayerName.",
  ui_story_1012_10120702_15_dialog_content = "Caramba! Devolva!",
  ui_story_1012_10120702_16_dialog_content = "Gaaaaaa!!!",
  ui_story_1012_10120702_17_dialog_content = "Pare-os, PlayerName! Não podemos deixá-los continuar entrando!",
  ui_story_1012_10120702_18_dialog_content = "O processo de sincronização não pode falhar por causa disso!",
  ui_story_1012_10120702_19_dialog_content = "Dispersem, pétalas de gelo!",
  ui_story_1012_10120702_20_dialog_content = "<size=45>Gaaaaaa!</size>",
  ui_story_1012_10120702_21_dialog_content = "C-Carleen!",
  ui_story_1012_10120702_22_option_content = "Controle forçado!",
  ui_story_1012_10120702_23_dialog_content = "Carleen... Por favor... Por favor, responda!",
  ui_story_1012_10120702_24_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1012_10120702_25_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1012_10120702_26_dialog_content = "(Eclipsiano) Matar Barton e Vice. Não danifique esse dispositivo.",
  ui_story_1012_10120702_27_dialog_content = "(Eclipsiano) Como você comanda.",
  ui_story_1012_10120702_28_dialog_content = "<size=50><anim type=Shake>Gah—</anim></size>",
  ui_story_1012_10120702_29_dialog_content = "(Por que... Por que isso acontece...?)",
  ui_story_1012_10120702_30_dialog_content = "(Essa sensação de impotência de novo... estou experimentando de novo...)",
  ui_story_1012_10120702_31_dialog_content = "(Se eu tivesse poder como os Luminatics, as coisas certamente seriam diferentes de agora.)",
  ui_story_1012_10120702_32_dialog_content = "(Vice, Carleen, e...)",
  ui_story_1012_10120702_33_dialog_content = "(Elas...)",
  ui_story_1012_10120702_34_dialog_content = "Ajuda! Alguém pode me salvar?!",
  ui_story_1012_10120702_35_dialog_content = "Não se aproxime dele. Eu vou lutar com vocês!",
  ui_story_1012_10120702_36_dialog_content = "Uh... Waaah... Waaah...",
  ui_story_1012_10120702_37_dialog_content = "Chamas de batalha, Eclipsites... Esta é a acolhida que recebo quando abro os olhos?",
  ui_story_1012_10120702_38_dialog_content = "(O que?!)",
  ui_story_1012_10120702_39_dialog_content = "Tem outra coisa melhor?!",
  ui_story_1012_10120702_40_dialog_content = "Eu mal posso me conter. Este poder parece que iria jorrar a qualquer momento!",
  ui_story_1012_10120702_41_dialog_content = "Uma batalha oportuna é aquela que devemos usar para praticar.",
  ui_story_1012_10120702_42_dialog_content = "Barton! Você... Você conseguiu!",
  ui_story_1012_10120702_43_dialog_content = "Oh, PlayerName... O que há com você, garoto?",
  ui_story_1012_10120702_44_dialog_content = "Limpe essa água do seu rosto. Pare de agir como uma garotinha!",
  ui_story_1012_10120702_45_dialog_content = "Mostre-me seu espírito de luta!",
  ui_story_1012_10120702_46_dialog_content = "O-Claro!",
  ui_story_1012_10120702_47_dialog_content = "Vamos, deixe-me ensinar-lhe o que é um verdadeiro campo de batalha.",
  ui_story_1012_10120702_48_dialog_content = "Esta torre pertence a você. Você não pode deixar cair nas mãos do pessoal do Eclipse!",
  ui_story_1012_10120702_49_dialog_content = "(Eclipsiano) Que surpresa. A antiga tecnologia Caelestita é realmente tão avançada.",
  ui_story_1012_10120702_50_dialog_content = "(Eclipsiano) Estou muito animado. Persegui-lo aqui é a decisão certa.",
  ui_story_1012_10120702_51_dialog_content = "(Eclipsiano) Você é sábia, Senhora Forsakin.",
  ui_story_1012_10120702_52_dialog_content = "(Eclipsiano) O que você está fazendo? Agarre-o, mas não o mate! Eu preciso dele vivo.",
  ui_story_1012_10120702_53_dialog_content = "(Eclipsiano) Roger—",
  ui_story_1012_10120702_54_dialog_content = "<color=#e8d9bb><size=45>Estrondo!</size></color>",
  ui_story_1012_10120702_55_dialog_content = "Faz algum tempo, Forsakin.",
  ui_story_1012_10120702_56_dialog_content = "Achei que você teria uma equipe mais forte agora.",
  ui_story_1012_10120702_57_dialog_content = "Explosão...",
  ui_story_1012_10120702_58_dialog_content = "(Eclipsiano) Todas as mãos! Ataque!",
  ui_story_1012_10120702_59_dialog_content = "Gaaaaaa!!!",
  ui_story_1012_10120702_60_dialog_content = "Golpe do Leopardo!",
  ui_story_1012_10120702_61_dialog_content = "PlayerName? Barton?!",
  ui_story_1012_10120702_62_dialog_content = "Mas isso deve significar... Chord Link foi bem sucedido!",
  ui_story_1012_10120702_63_dialog_content = "Hahaha! Claro que sim!",
  ui_story_1012_10120702_64_dialog_content = "Rápido, vá resgatar Vice. Sua equipe vai precisar dela, certo?",
  ui_story_1012_10120702_65_dialog_content = "Quanto a aqui... posso limpar.",
  ui_story_1012_10120702_66_dialog_content = "...",
  ui_story_1012_10120702_67_dialog_content = "(Eclipsiano) Recuar e reagrupar com as principais forças do Eclipse!",
  ui_story_1012_10120702_68_dialog_content = "(Eclipsiano) Como... como você comanda.",
  ui_story_1012_10120702_69_dialog_content = "Fique quieto, porra!",
  ui_story_1012_10120702_70_dialog_content = "Que grupo de esbanjados sem vergonha e descarados!",
  ui_story_1012_10120702_71_dialog_content = "Você está certo, Carleen? Isso poderia ter ficado feio, você está bem...?",
  ui_story_1012_10120702_72_dialog_content = "Estou bem. Não podemos perder tempo, PlayerName...",
  ui_story_1012_10120702_73_dialog_content = "Temos que resgatar Vice, agora!",
  ui_story_1012_10120702_74_dialog_content = "Você não está errado aí. Vamos fazer a Sincronização.",
  ui_story_1012_10120702_75_dialog_content = "(Então... Por favor, trabalhe, Chord Link.)",
  ui_story_1012_10120702_76_dialog_content = "(Espero que você acorde, Vice...)",
  ui_story_1012_10120702_77_dialog_content = "<color=#e8d9bb>Alerta do sistema: Chord Link agora está operacional...</color>",
  ui_story_1012_10120801_1_dialog_content = "<color=#e8d9bb>Alerta do sistema: Chord Link agora está ativo... Não interrompa o processo de sincronização...</color>",
  ui_story_1012_10120801_2_dialog_content = "...",
  ui_story_1012_10120801_3_dialog_content = "...",
  ui_story_1012_10120801_4_dialog_content = "Está funcionando há séculos! O que da?",
  ui_story_1012_10120801_5_dialog_content = "Acalmar, PlayerName. Dar Vice às vezes.",
  ui_story_1012_10120801_6_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1012_10120801_7_dialog_content = "De qualquer forma, a Sincronização não está demorando um pouco demais?!",
  ui_story_1012_10120801_8_dialog_content = "Agora que penso nisso... não precisei esperar tanto para Barton acordar.",
  ui_story_1012_10120801_9_dialog_content = "O que nós fazemos, PlayerName?",
  ui_story_1012_10120801_10_dialog_content = "(Carleen...)",
  ui_story_1012_10120801_11_dialog_content = "(Bem, é melhor eu me recompor.)",
  ui_story_1012_10120801_12_dialog_content = "Seguimos as instruções do Chord Link ao pé da letra, certo? Pegou Vice deitar nele.",
  ui_story_1012_10120801_13_dialog_content = "Tudo é o mesmo que Barton passou.",
  ui_story_1012_10120801_14_dialog_content = "Não recebemos nenhum alerta de mau funcionamento com o Chord Link ou o Neural Aux.",
  ui_story_1012_10120801_15_dialog_content = "É isso que me faz pensar que talvez o problema seja com...",
  ui_story_1012_10120801_16_option_content = "Vice's Hibernação.",
  ui_story_1012_10120801_17_dialog_content = "Eu vejo. Acho que essa é a única explicação.",
  ui_story_1012_10120801_18_dialog_content = "O General Illumina também não foi ferido, mas não perdeu a consciência?",
  ui_story_1012_10120801_19_dialog_content = "Então, apesar dos ferimentos graves, ele acordou com um corpo mais forte.",
  ui_story_1012_10120801_20_option_content = "Forsakindestruição.",
  ui_story_1012_10120801_21_dialog_content = "Sério? O que Forsakin Faz...?",
  ui_story_1012_10120801_22_dialog_content = "Mas... ForsakinOs Eclipsites de agora não estavam nem perto do Chord Link...",
  ui_story_1012_10120801_23_dialog_content = "E eles já haviam sido derrubados pelo General Illumina.",
  ui_story_1012_10120801_24_dialog_content = "Isso me faz pensar que... O problema tem que ser com a Hibernação.",
  ui_story_1012_10120801_25_dialog_content = "Tem que ser. Pense nos dados que acabamos de ver no Sistema Circular...",
  ui_story_1012_10120801_26_dialog_content = "Assunto... Falha ao recuperar da Hibernação... Físico... Os sinais de vida desapareceram.",
  ui_story_1012_10120801_27_dialog_content = "Assunto... Falha ao recuperar da Hibernação... Exibido... Sinais de vida...",
  ui_story_1012_10120801_28_dialog_content = "Assunto... Falha ao recuperar... No experimento...",
  ui_story_1012_10120801_29_dialog_content = "Todos aqueles celestitas que acabaram sendo cobaias tinham algo em comum...",
  ui_story_1012_10120801_30_dialog_content = "Hibernação.",
  ui_story_1012_10120801_31_dialog_content = "Mas como? Como isso pode ser?",
  ui_story_1012_10120801_32_dialog_content = "(É possível que este seja seu destino compartilhado? Não se recuperar da hibernação?)",
  ui_story_1012_10120801_33_dialog_content = "(Se isso for verdade, então... Vice!)",
  ui_story_1012_10120801_34_dialog_content = "PlayerName...",
  ui_story_1012_10120801_35_dialog_content = "PlayerName?",
  ui_story_1012_10120801_36_dialog_content = "Ré-Reinhardt?!",
  ui_story_1012_10120801_37_dialog_content = "Pelo menos seu sinal parece ser claro o suficiente.",
  ui_story_1012_10120801_38_dialog_content = "Qual é a situação por lá? Fazes ideia da raquete que estás a fazer?",
  ui_story_1012_10120801_39_dialog_content = "D-Desculpa!",
  ui_story_1012_10120801_40_dialog_content = "Hahahaha! Eu não estou culpando você.",
  ui_story_1012_10120801_41_dialog_content = "Eu só gostaria de lembrá-lo que, em meio a toda a agitação recente em Eraveil, não é apenas a Illumina que está ouvindo.",
  ui_story_1012_10120801_42_dialog_content = "Certifique-se de nunca ceder toda a iniciativa...",
  ui_story_1012_10120801_43_dialog_content = "Afinal, você é o único que pode trazer mudanças para o Eraveil.",
  ui_story_1012_10120801_44_dialog_content = "Te vejo daqui a pouco.",
  ui_story_1012_10120801_45_dialog_content = "Sim, Reinhardt.",
  ui_story_1012_10120801_46_dialog_content = "Ela não está errada.",
  ui_story_1012_10120801_47_dialog_content = "Atualmente, estamos completamente cegos quanto ao que está acontecendo fora da torre. Esta é uma situação ruim para nós.",
  ui_story_1012_10120801_48_dialog_content = "Então, como podemos descobrir o que está acontecendo?",
  ui_story_1012_10120801_49_dialog_content = "Bartonprovavelmente ainda está lidando com Forsakin. Não quero incomodá-lo e causar problemas...",
  ui_story_1012_10120801_50_dialog_content = "Recebido... Analisando pergunta...",
  ui_story_1012_10120801_51_dialog_content = "Hã?!",
  ui_story_1012_10120801_52_dialog_content = "Existe alguma maneira de contornar isso, Neural Aux?",
  ui_story_1012_10120801_53_dialog_content = "Ativando o monitor externo da torre.",
  ui_story_1012_10120801_54_dialog_content = "Ufa... Ufa...",
  ui_story_1012_10120801_55_dialog_content = "Pare de correr, Forsakin!",
  ui_story_1012_10120801_56_dialog_content = "Enfrente-me como um verdadeiro guerreiro!",
  ui_story_1012_10120801_57_dialog_content = "Hã?",
  ui_story_1012_10120801_58_dialog_content = "O quê...?",
  ui_story_1012_10120801_59_dialog_content = "Bem, eu nunca... Não vejo algo assim há muito tempo!",
  ui_story_1012_10120801_60_dialog_content = "(Olhe para todos os reforços mobilizados!)",
  ui_story_1012_10120801_61_dialog_content = "(Isso está começando a compartilhar uma semelhança horrível com a Crise de Darkover uma década atrás.)",
  ui_story_1012_10120801_62_dialog_content = "(Quanto tempo eu posso... Segurá-los por PlayerName e esses caras?)",
  ui_story_1012_10120801_63_dialog_content = "Ah?",
  ui_story_1012_10120801_64_dialog_content = "Parece que você está em um ponto de incômodo, Forsakin.",
  ui_story_1012_10120801_65_dialog_content = "Talvez não seja tão teimoso da próxima vez, hmm?",
  ui_story_1012_10120801_66_dialog_content = "Tal inconveniência deve ter tornado em vão todos os seus esforços.",
  ui_story_1012_10120801_67_dialog_content = "Acho que você vai descobrir que tem sido muito gratificante.",
  ui_story_1012_10120801_68_dialog_content = "E de qualquer forma, não é da sua conta.",
  ui_story_1012_10120801_69_dialog_content = "Não tente salvar o dia depois de ficar à margem.",
  ui_story_1012_10120801_70_dialog_content = "Hmph. Qualquer que seja.",
  ui_story_1012_10120801_71_dialog_content = "Que vida baixa. Você está pedindo ajuda porque você não pode vencê-los, Forsakin?",
  ui_story_1012_10120801_72_dialog_content = "(Ali! Uma lacuna nas defesas!)",
  ui_story_1012_10120801_73_dialog_content = "Leopardo... Greve!",
  ui_story_1012_10120801_74_dialog_content = "Argh...",
  ui_story_1012_10120801_75_dialog_content = "Eclipse não se uniu para você, você sabe.",
  ui_story_1012_10120801_76_dialog_content = "Apenas desista, pare de resistir.",
  ui_story_1012_10120801_77_dialog_content = "Você está ganhando tempo para aquele celestita desde que veio para a Torre Branca.",
  ui_story_1012_10120801_78_dialog_content = "Estou certo, não estou?",
  ui_story_1012_10120801_79_dialog_content = "...",
  ui_story_1012_10120801_80_dialog_content = "(Eclipsiano) Agarre-o.",
  ui_story_1012_10120801_81_dialog_content = "Gahhhh!!!",
  ui_story_1012_10120801_82_dialog_content = "<color=#e8d9bb>Bum! Bum!</color>",
  ui_story_1012_10120801_83_dialog_content = "São...",
  ui_story_1012_10120801_84_dialog_content = "Bem, esta torre é ainda mais extraordinária de perto.",
  ui_story_1012_10120801_85_dialog_content = "Tudo é como meus sonhos previram...",
  ui_story_1012_10120801_86_dialog_content = "Não importa para onde o mundo esteja indo, destruição ou renascimento, o confronto entre Eraveil e os Eclipsites é inevitável.",
  ui_story_1012_10120801_87_dialog_content = "(O líder de Northland...?)",
  ui_story_1012_10120801_88_dialog_content = "(Ela me deu uma mão agora...?)",
  ui_story_1012_10120801_89_dialog_content = "Comandante Barton, tenho certeza que você está ciente da Estátua 42 dos Regulamentos Militares da Illumina, que trata da insubordinação?",
  ui_story_1012_10120801_90_dialog_content = "Hã?!",
  ui_story_1012_10120801_91_dialog_content = "A Illumina sempre busca a justiça, em estrita conformidade com os regulamentos. Infratores particularmente flagrantes serão levados à corte marcial.",
  ui_story_1012_10120801_92_dialog_content = "— Mas, claro, isso terá que esperar até depois da guerra.",
  ui_story_1012_10120801_93_dialog_content = "... Grande marechal?",
  ui_story_1012_10120801_94_dialog_content = "Os batalhões de reforço de vanguarda estão quase aqui, então vá encontrá-los.",
  ui_story_1012_10120801_95_dialog_content = "Oh? Isto é... Você participou de algum tipo de treinamento especial de emergência? Você parece um pouco diferente...",
  ui_story_1012_10120801_96_dialog_content = "Independentemente disso, traga o seu melhor para esta batalha, Comandante Barton!",
  ui_story_1012_10120801_97_dialog_content = "Veja se você pode expiar seus erros no campo de batalha!",
  ui_story_1012_10120801_98_dialog_content = "...",
  ui_story_1012_10120801_99_dialog_content = "Entendido!",
  ui_story_1012_10120801_100_dialog_content = "Espere para ver, Grande Marechal.",
  ui_story_1012_10120801_101_dialog_content = "Monitoramento externo concluído.",
  ui_story_1012_10120801_102_dialog_content = "Vossa Majestade, e Reinhardt...",
  ui_story_1012_10120801_103_dialog_content = "Parece que Northland e Illumina estão em vigor.",
  ui_story_1012_10120801_104_dialog_content = "Mas... Mesmo com todas as suas tropas, será suficiente para combater o Eclipse?",
  ui_story_1012_10120801_105_dialog_content = "Temos que pensar em algo, PlayerName!",
  ui_story_1012_10120801_106_dialog_content = "Eu sei! Eu diria que nossa melhor aposta é aproveitar o Obelisco do Retorno, já que está em uma posição bem central.",
  ui_story_1012_10120801_107_dialog_content = "Neural Aux, quão boas são as defesas desta torre?",
  ui_story_1012_10120801_108_dialog_content = "Recebido... Analisando pergunta...",
  ui_story_1012_10120801_109_dialog_content = "Dentro do Obelisco do Retorno está o sistema de defesa definitivo: o<color=#FFB400>Acorde da Lei</color>.",
  ui_story_1012_10120801_110_dialog_content = "Este é o ativo mais forte e único do Eraveil, e também a última linha de defesa.",
  ui_story_1012_10120801_111_dialog_content = "Então...",
  ui_story_1012_10120801_112_dialog_content = "O Acorde da Lei é difícil de ativar e caro de usar.",
  ui_story_1012_10120801_113_dialog_content = "Não posso autorizar nenhum celestita a ativar o Acorde da Lei.",
  ui_story_1012_10120801_114_dialog_content = "Autorização? Por que sempre há um problema com a autorização?!",
  ui_story_1012_10120801_115_dialog_content = "Repito: O Acorde da Lei é difícil de ativar e caro de usar.",
  ui_story_1012_10120801_116_dialog_content = "Não posso autorizar nenhum celestita...",
  ui_story_1012_10120801_117_dialog_content = "Não adianta discutir com uma máquina, PlayerName.",
  ui_story_1012_10120801_118_dialog_content = "Temos nosso próprio livre arbítrio e não podemos nos deixar travar por uma mera máquina!",
  ui_story_1012_10120801_119_dialog_content = "(Carleenestá certo. E de qualquer forma, eu não posso passar por isso de novo...)",
  ui_story_1012_10120801_120_dialog_content = "(Aquele desamparo diante dos Eclipsitas, onde nenhum celestita pode fazer nada.)",
  ui_story_1012_10120801_121_dialog_content = "Eu não vou ficar de fora dessa! Vou levá-lo para o Eclipse desta vez!",
  ui_story_1012_10120801_122_dialog_content = "Eu entendo você, PlayerName. Mas...",
  ui_story_1012_10120801_123_dialog_content = "Vice...",
  ui_story_1012_10120801_124_dialog_content = "Como a sincronização ainda não foi concluída, Vice vai ter que continuar suportando o processo.",
  ui_story_1012_10120801_125_dialog_content = "PlayerName, assim que sairmos da Chord Zone, vamos fazer com que o Neural Aux altere a estrutura da entrada.",
  ui_story_1012_10120801_126_dialog_content = "Certifique-se de selar a entrada da Chord Zone e mudar a estrutura da passagem secreta...",
  ui_story_1012_10120801_127_dialog_content = "Vamos fazer um <color=#FFB400>Casulo</color> forte o suficiente para Vice.",
  ui_story_1012_10120801_128_dialog_content = "Claro que não!",
  ui_story_1012_10120801_129_dialog_content = "(Por favor, Vice, o Chord Link TEM que te acordar...)",
  ui_story_1012_10120801_130_dialog_content = "(Estamos todos esperando pelo seu renascimento.)",
  ui_story_1012_10120801_131_dialog_content = "Nos vemos em breve, Vice.",
  ui_story_1012_10120901_1_dialog_content = "<color=#e8d9bb>Passagem de Entrada, Torre Primária</color>",
  ui_story_1012_10120901_2_dialog_content = "<color=#e8d9bb>Pitter-patter... Pitter-patter...</color>",
  ui_story_1012_10120901_3_dialog_content = "A entrada por onde viemos fica um pouco adiante.",
  ui_story_1012_10120901_4_dialog_content = "Eu não quero soar pregador, PlayerName, mas...",
  ui_story_1012_10120901_5_dialog_content = "Não tenha medo.",
  ui_story_1012_10120901_6_dialog_content = "C-Carleen...?",
  ui_story_1012_10120901_7_dialog_content = "Nunca se esqueça: você está lutando por sua terra, sua casa.",
  ui_story_1012_10120901_8_dialog_content = "Esta é uma grande honra, e não precisa ser temida.",
  ui_story_1012_10120901_9_dialog_content = "Sua Majestade... me ensinou isso.",
  ui_story_1012_10120901_10_dialog_content = "Obrigada, Carleen.",
  ui_story_1012_10120901_11_dialog_content = "Estou pronto para o que vier.",
  ui_story_1012_10120901_12_dialog_content = "Tudo bem. Bem, vamos nos aventurar de volta ao mundo fora da torre, juntos!",
  ui_story_1012_10120901_13_dialog_content = "É... É um...",
  ui_story_1012_10120901_14_dialog_content = "<color=#e8d9bb>Kkkkkrack... Kkkkkrack...</color>",
  ui_story_1012_10120901_15_dialog_content = "<anim type=Shake><size=50>Gai!!!!!!!!</size></anim>",
  ui_story_1012_10120901_16_dialog_content = "O Eraveil não era exatamente assim... naquela época...",
  ui_story_1012_10120901_17_dialog_content = "PlayerName, tenha cuidado!",
  ui_story_1012_10120901_18_dialog_content = "Ahhh...",
  ui_story_1012_10120901_19_dialog_content = "Tsc, tsc, tsc...",
  ui_story_1012_10120901_20_dialog_content = "Ter melhor inteligência vale mais do que puro poder de fogo.",
  ui_story_1012_10120901_21_dialog_content = "A situação atual já é bastante clara, de qualquer maneira.",
  ui_story_1012_10120901_22_dialog_content = "Suas forças não se comparam às do exército Eclipse.",
  ui_story_1012_10120901_23_dialog_content = "Oh, é alguma tradição estranha do Eclipse falar bobagem antes de uma luta?",
  ui_story_1012_10120901_24_dialog_content = "Palavras vazias não te tornam mais forte, você sabe.",
  ui_story_1012_10120901_24X1_dialog_content = "(... Agora que penso nisso, Rainha Bethlehem já deve estar aqui.)",
  ui_story_1012_10120901_24X2_dialog_content = "PlayerName, vou para o outro lado do Obelisco do Retorno para investigar e me juntar à Rainha Bethlehem.",
  ui_story_1012_10120901_24X3_dialog_content = "Você fica aqui com esses reforços da Illumina, certo?",
  ui_story_1012_10120901_24X4_dialog_content = "Claro, mas lembre-se de manter contato.",
  ui_story_1012_10120901_24X5_dialog_content = "Cuide-se então, Carleen.",
  ui_story_1012_10120901_25_dialog_content = "Atualização de inteligência para o Grande Marechal: Reforços da 2ª Legião se encontraram com o Comandante Barton.",
  ui_story_1012_10120901_26_dialog_content = "Aguardando seus pedidos.",
  ui_story_1012_10120901_27_dialog_content = "Bom. Instrua-os a concentrar sua força principal na linha de frente e atacar em formação próxima.",
  ui_story_1012_10120901_28_dialog_content = "Divida as forças restantes em dois contingentes e amarre as reservas do Eclipse por trás.",
  ui_story_1012_10120901_29_dialog_content = "Entendido!",
  ui_story_1012_10120901_30_dialog_content = "Então por que você ainda está aqui?",
  ui_story_1012_10120901_31_dialog_content = "... Grão-marechal, você ainda não me designou uma missão de combate.",
  ui_story_1012_10120901_32_dialog_content = "Hahaha! Tudo bem então. Você recua, defende aquela torre e fica parado.",
  ui_story_1012_10120901_33_dialog_content = "Defenda a... Torre?",
  ui_story_1012_10120901_34_dialog_content = "Você vê aquela enorme Torre Branca, certo?",
  ui_story_1012_10120901_35_dialog_content = "Sim, mas...",
  ui_story_1012_10120901_36_dialog_content = "Essa torre é todo o propósito da nossa missão aqui.",
  ui_story_1012_10120901_37_dialog_content = "Embora esta missão possa não estar na linha de frente, é de suprema importância.",
  ui_story_1012_10120901_38_dialog_content = "Estarei de volta em breve, e ainda vou precisar que você passe algumas informações, então não se preocupe.",
  ui_story_1012_10120901_39_dialog_content = "... Sim, senhora!",
  ui_story_1012_10120901_40_dialog_content = "Quanto a PlayerName, você apenas fique comigo por enquanto.",
  ui_story_1012_10120901_41_dialog_content = "Uh... Você não é um par de caras curtos...?",
  ui_story_1012_10120901_42_dialog_content = "Reinhardt... Vice, ela...",
  ui_story_1012_10120901_43_dialog_content = "Comandante Barton já me informou sobre o tenente Vice.",
  ui_story_1012_10120901_44_dialog_content = "Você deve ter fé no que está dentro desta torre. É um grande tesouro que seus ancestrais deixaram para você.",
  ui_story_1012_10120901_45_dialog_content = "Além disso, com a guerra se aproximando, temos que nos manter positivos.",
  ui_story_1012_10120901_46_dialog_content = "Mantenha sua cabeça e moral elevados!",
  ui_story_1012_10120901_47_dialog_content = "...Eu vou!",
  ui_story_1012_10120901_48_dialog_content = "Esse é o espírito!",
  ui_story_1012_10120901_49_dialog_content = "<color=#e8d9bb>Enquanto isso, do outro lado da Torre</color>",
  ui_story_1012_10120901_50_dialog_content = "<size=45>Sua Majestade!!!</size>",
  ui_story_1012_10120901_51_dialog_content = "Estou negligente em meu dever como guarda-costas de Sua Majestade!",
  ui_story_1012_10120901_52_dialog_content = "Eu pediria a Vossa Majestade que não enfrentasse mais os Eclipsitas sozinho sem mim!",
  ui_story_1012_10120901_53_dialog_content = "Permita-me ser sua valente vanguarda, Sua Majestade!",
  ui_story_1012_10120901_54_dialog_content = "Tiare, você esteve na selva nevada por tantos anos. Você sabe que seus pontos fortes são vigilância e infiltração...",
  ui_story_1012_10120901_55_dialog_content = "Seus pontos fortes são a estratégia da Northland para apoiar o Eraveil.",
  ui_story_1012_10120901_56_dialog_content = "Deixemos as linhas de frente para aqueles aurorianos sedentos de batalha. Vamos adotar a abordagem mais conservadora e vigiar ao lado desta Torre Branca.",
  ui_story_1012_10120901_57_dialog_content = "Eu chamei todas as forças de Northland de volta para os arredores da Torre Branca e as coloquei em alerta máximo.",
  ui_story_1012_10120901_58_dialog_content = "A menos que as linhas de frente entrem em colapso, esses Eclipsites não penetrarão tão facilmente.",
  ui_story_1012_10120901_59_dialog_content = "Muito bem, Vossa Majestade!",
  ui_story_1012_10120901_60_dialog_content = "... Mais uma coisa. Você pode dispensar a formalidade enquanto estamos no campo de batalha.",
  ui_story_1012_10120901_61_dialog_content = "Liga para mim Bethlehem.",
  ui_story_1012_10120901_62_dialog_content = "Agora venha, proteja-se atrás deste escudo.",
  ui_story_1012_10120901_63_dialog_content = "Al-tudo bem! Sim sua Majestade!",
  ui_story_1012_10120901_64_dialog_content = "Sua Majestade?! Eu não esperava você tão rápido!",
  ui_story_1012_10120901_65_dialog_content = "Faz algum tempo, Carleen.",
  ui_story_1012_10120901_66_dialog_content = "Claro, agora não é hora de relembrar. Considere as circunstâncias atuais como um teste...",
  ui_story_1012_10120901_67_dialog_content = "Deixe-me ver o quanto você pode lidar sozinho.",
  ui_story_1012_10120901_68_dialog_content = "Carleen dificilmente está sozinha!",
  ui_story_1012_10120901_69_dialog_content = "Beretta?",
  ui_story_1012_10120901_70_dialog_content = "Você não está... Por que você não está com Raphael?",
  ui_story_1012_10120901_71_dialog_content = "Sua Alteza, trago os valentes Cavaleiros Lumo em seu auxílio.",
  ui_story_1012_10120901_72_dialog_content = "Aguardamos seu comando, <color=#FFB400>Capitão Carleen</color>!",
  ui_story_1012_10120901_73_dialog_content = "(Entendo. É isso que meu pai está fazendo?)",
  ui_story_1012_10120901_74_dialog_content = "(Estou surpreso que o pai foi tão rápido em enviar tropas e deixar sua posição clara.)",
  ui_story_1012_10120901_75_dialog_content = "Noite Branca no alto, levante suas armas e avance comigo!",
  ui_story_1012_10120901_76_dialog_content = "Como o dia penetra a noite, então a escuridão nunca pode se esconder!",
  ui_story_1012_10120901_77_dialog_content = "Avante, Noite Branca!",
  ui_story_1012_10120901_78_dialog_content = "<color=#e8d9bb>Eclipse Garrison em Eraveil</color>",
  ui_story_1012_10120901_79_dialog_content = "(Eclipsiano) Até Lumopolis enviou forças? Esse velho fuddy-duddy é demais.",
  ui_story_1012_10120901_80_dialog_content = "(Eclipsian) Lumopolis vai pagar o preço por enfrentar Eclipse.",
  ui_story_1012_10120901_81_dialog_content = "(Eclipsian) Não vai acabar aí, também. Uma vez que o Eraveil for nosso, nada pode nos impedir de tomar todo o continente!",
  ui_story_1012_10120901_82_dialog_content = "(Eclipsiano) Tsk, tsk, tsk...",
  ui_story_1012_10120901_83_dialog_content = "(Eclipsiano) Meus camaradas, nosso tempo se aproxima...",
  ui_story_1012_10120901_84_dialog_content = "(Eclipsiano) A vitória está ao nosso alcance.",
  ui_story_1012_10120901_85_dialog_content = "(Eclipsian) Eraveil mais uma vez ficará vermelho de sangue!",
  ui_story_1012_10120901_86_dialog_content = "(Eclipsiano) Para Eraveil! Pegue a Torre Branca! Extermine todos os que se opõem a nós!",
  ui_story_1012_10120901_87_dialog_content = "<size=45>(Eclipsiano) PARA AS ARMAS!!</size>",
  ui_story_1012_10120901_88_dialog_content = "<anim type=Shake><size=45>Gahhhh!!!</size></anim>",
  ui_story_1012_10120901_89_dialog_content = "(Eclipsiano) Este é o último dia em que o sol nasce sobre Astra...",
  ui_story_1012_10121002_1_dialog_content = "Seu comando é tão firme como sempre, PlayerName.",
  ui_story_1012_10121002_2_dialog_content = "Capaz de manter a cabeça fria em tais circunstâncias... Devo chamá-lo de composto, ou simples?",
  ui_story_1012_10121002_3_dialog_content = "Acho que estou começando a entender como você conquistou tanta confiança de tantos.",
  ui_story_1012_10121002_4_dialog_content = "Isso é um pouco demais, com certeza...",
  ui_story_1012_10121002_5_dialog_content = "Novas informações: A primeira onda de ataques do Eclipse foi repelida com sucesso!",
  ui_story_1012_10121002_6_dialog_content = "Embora a situação seja fluida, parece que a linha de reforços está se sustentando.",
  ui_story_1012_10121002_7_dialog_content = "Excelente. Certifiquem-se de manter o ritmo, todos, pois isso foi apenas o começo.",
  ui_story_1012_10121002_8_dialog_content = "Notificar Comandante Barton para liderar os reforços e coordenar com nossos aliados.",
  ui_story_1012_10121002_9_dialog_content = "Sim.",
  ui_story_1012_10121002_10_dialog_content = "Embora Carleennão é mais criança...",
  ui_story_1012_10121002_11_dialog_content = "Ela provavelmente não ficaria muito confortável lutando ao lado de suas tropas na frente.",
  ui_story_1012_10121002_12_dialog_content = "Haha! Um soldado que vive uma vida fácil nunca se tornará um general.",
  ui_story_1012_10121002_13_dialog_content = "Eu ouvi que você levantou Carleen?",
  ui_story_1012_10121002_14_dialog_content = "Você parece mais um pai para ela do que Schwartz, Sua Majestade!",
  ui_story_1012_10121002_15_dialog_content = "... Veja como você fala, minha senhora Reinhardt.",
  ui_story_1012_10121002_16_dialog_content = "Por favor, dirija-se a Sua Majestade com respeito!",
  ui_story_1012_10121002_17_dialog_content = "Gaaaaaa!!!",
  ui_story_1012_10121002_18_dialog_content = "Argh...",
  ui_story_1012_10121002_19_dialog_content = "Quando o gelo derreter!",
  ui_story_1012_10121002_20_dialog_content = "Prefiro não conversar à toa enquanto a batalha se desenrola.",
  ui_story_1012_10121002_21_dialog_content = "Embora a situação ainda esteja sob controle, não se deixe distrair.",
  ui_story_1012_10121002_22_dialog_content = "Bem, vou liderar as tropas restantes para encontrar o Eclipse na frente da torre.",
  ui_story_1012_10121002_23_dialog_content = "As coisas parecem estar indo bem!",
  ui_story_1012_10121002_24_dialog_content = "<color=#e8d9bb>Frente de Batalha, Eraveil</color>",
  ui_story_1012_10121002_25_dialog_content = "O que?! Trabalhar com aqueles caras de Lumopolis?",
  ui_story_1012_10121002_26_dialog_content = "Exatamente.",
  ui_story_1012_10121002_27_dialog_content = "Pff, tudo bem, tanto faz. Eu sei o placar. Nenhum homem ameaça um mensageiro.",
  ui_story_1012_10121002_28_dialog_content = "Hã?!",
  ui_story_1012_10121002_29_dialog_content = "Gaaaaaa!!!",
  ui_story_1012_10121002_30_dialog_content = "Ahhh...",
  ui_story_1012_10121002_31_dialog_content = "Tudo bem, parece que ainda temos algumas limpezas para fazer aqui. É melhor você voltar para o Grande Marechal. Vá guardar aquela Torre.",
  ui_story_1012_10121002_32_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1012_10121002_33_dialog_content = "Ah!",
  ui_story_1012_10121002_34_dialog_content = "Ei!",
  ui_story_1012_10121002_35_dialog_content = "Por Illumina... O que você está fazendo?!",
  ui_story_1012_10121002_36_dialog_content = "Não foi de propósito! O chão de repente tremeu agora...",
  ui_story_1012_10121002_37_dialog_content = "Realmente agora, não crie problemas!",
  ui_story_1012_10121002_38_dialog_content = "<color=#e8d9bb>Bum!!—</color>",
  ui_story_1012_10121002_39_dialog_content = "Ah... ah...?!",
  ui_story_1012_10121002_40_dialog_content = "Espere um segundo... Eles atiraram um Eclipsite em nós?!",
  ui_story_1012_10121002_41_dialog_content = "Como muito conveniente.",
  ui_story_1012_10121002_42_dialog_content = "Ahhh...",
  ui_story_1012_10121002_43_dialog_content = "Esta é a linha de frente, não um playground. Se você não está aqui para lutar...",
  ui_story_1012_10121002_44_dialog_content = "Então você também pode ir para casa.",
  ui_story_1012_10121002_45_dialog_content = "Sim!",
  ui_story_1012_10121002_46_dialog_content = "Pff... Conseguiu o quê, exatamente?",
  ui_story_1012_10121002_47_dialog_content = "S-desculpe!",
  ui_story_1012_10121002_48_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_1012_10121002_49_dialog_content = "Essa concha é?",
  ui_story_1012_10121002_50_dialog_content = "Isso é estranho. Não foi direcionado a nós desta vez, e...",
  ui_story_1012_10121002_51_dialog_content = "Parecia lançar uma sombra inquietante, o que só podia significar...",
  ui_story_1012_10121002_52_dialog_content = "Droga!",
  ui_story_1012_10121002_53_dialog_content = "Isso é <color=#FFB400>Darkflow</color>!",
  ui_story_1012_10121002_54_dialog_content = "Aquelas primeiras conchas estavam apenas testando a água...",
  ui_story_1012_10121002_55_dialog_content = "este <color=#FFB400>Escudo de fluxo escuro</color> é destinado ao Obelisco do Retorno!",
  ui_story_1012_10121002_56_dialog_content = "(Obelisco do Retorno?!)",
  ui_story_1012_10121002_57_dialog_content = "Escutem, reforços da 2ª Legião! A batalha está mudando!",
  ui_story_1012_10121002_58_dialog_content = "Vá até o Obelisco do Retorno e apoie o Grande Marechal!",
  ui_story_1012_10121101_1_dialog_content = "<color=#e8d9bb>Obelisco do Retorno, Eraveil</color>",
  ui_story_1012_10121101_2_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_1012_10121101_3_dialog_content = "(Huh? Algo explodiu em cima!)",
  ui_story_1012_10121101_4_dialog_content = "(Vamos lá agora, tenho que se recompor para proteger Sua Majestade!)",
  ui_story_1012_10121101_5_dialog_content = "(O que está acontecendo? Eu me sinto doente de repente!)",
  ui_story_1012_10121101_6_dialog_content = "(Uma náusea desagradavelmente familiar...)",
  ui_story_1012_10121101_7_dialog_content = "?!",
  ui_story_1012_10121101_8_dialog_content = "Isso é <color=#FFB400>Darkflow</color>!",
  ui_story_1012_10121101_9_dialog_content = "Congelamento instantâneo!",
  ui_story_1012_10121101_10_dialog_content = "A proteção só pode cobrir uma área limitada. Por favor, todos podem se aconchegar?",
  ui_story_1012_10121101_11_dialog_content = "Não deixe o Darkflow afetar você!",
  ui_story_1012_10121101_12_dialog_content = "*Tosse* Este pouco não terá nenhum efeito!",
  ui_story_1012_10121101_13_dialog_content = "Evitar não é uma estratégia viável de longo prazo.",
  ui_story_1012_10121101_14_dialog_content = "Nesse ritmo, vamos ter que pensar em novas táticas, e rápido.",
  ui_story_1012_10121101_15_dialog_content = "Grande marechal!",
  ui_story_1012_10121101_16_dialog_content = "Momento perfeito, Anatoli...",
  ui_story_1012_10121101_17_dialog_content = "Oh? E parece que você trouxe de volta as tropas-chave também.",
  ui_story_1012_10121101_18_dialog_content = "Comandante da 2ª Legião Barton, reportando.",
  ui_story_1012_10121101_19_dialog_content = "Quais são suas ordens, Grande Marechal?",
  ui_story_1012_10121101_20_dialog_content = "Aproveite a chance fugaz para o combate.",
  ui_story_1012_10121101_21_dialog_content = "Ah, bem na hora, Comandante Barton.",
  ui_story_1012_10121101_22_dialog_content = "Oh! Er, uh... Grande Marechal?",
  ui_story_1012_10121101_23_dialog_content = "Encha a cabeça deste soldado com algo além de inteligência!",
  ui_story_1012_10121101_24_dialog_content = "Fique aqui e tire o poder de fogo do Eclipse para longe da Torre Branca. Você pode gerenciar isso?",
  ui_story_1012_10121101_25_dialog_content = "Quero ensiná-los que não é apenas o Eclipse que pode ser sorrateiro.",
  ui_story_1012_10121101_26_dialog_content = "Hmm, você está planejando um ataque furtivo? Eu aprovo.",
  ui_story_1012_10121101_27_dialog_content = "Vá embora então. Eu posso cuidar deste lugar.",
  ui_story_1012_10121101_28_dialog_content = "(Vendo Reinhardta energia e o espírito de , quase posso esquecer aquela sensação horrível do Darkflow...)",
  ui_story_1012_10121101_29_dialog_content = "(Enquanto o Eclipse continua disparando seu sinistro canhão Darkflow direto para nós...)",
  ui_story_1012_10121101_30_dialog_content = "(Ela está correndo para a escuridão com uma expressão como se estivesse curtindo um passeio de primavera.)",
  ui_story_1012_10121101_31_dialog_content = "(Um gênio tático ou um aspirante perigoso... As opiniões nos Illumina certamente estão divididas.)",
  ui_story_1012_10121101_32_dialog_content = "(Mas quem já a viu no campo de batalha vai entender o verdadeiro significado de Illumina...)",
  ui_story_1012_10121101_33_dialog_content = "(Ela brilha e brilha como Phospherus na escuridão sem esperança.)",
  ui_story_1012_10121101_34_dialog_content = "<size=33>Cuidado para me dar uma mão, PlayerName?</size>",
  ui_story_1012_10121101_35_dialog_content = "<size=33>Tem uma coisa que só um celestita como você pode ajudar.</size>",
  ui_story_1012_10121101_36_dialog_content = "Hã?!",
  ui_story_1012_10121101_37_dialog_content = "Ei, espere!",
  ui_story_1012_10121101_38_dialog_content = "O que você pensa que está fazendo?! Você não pode simplesmente me pegar!",
  ui_story_1012_10121101_39_dialog_content = "(É uma tradição da Illumina apenas pegar as pessoas quando quiser?!)",
  ui_story_1012_10121101_40_dialog_content = "Haha... me desculpe. Por favor, tenha paciência comigo um minuto!",
  ui_story_1012_10121101_41_dialog_content = "Dizem que os celestitas podem ver as cores do Lumina, então você deve ser capaz de localizar o <color=#FFB400>fonte do Darkflow</color> também!",
  ui_story_1012_10121101_42_dialog_content = "Por enquanto, por favor, seja meu navegador.",
  ui_story_1012_10121101_43_dialog_content = "Enquanto esmagamos os canhões Darkflow do Eclipse!",
  ui_story_1012_10121101_44_dialog_content = "<color=#e8d9bb>Frente de Batalha, Eraveil</color>",
  ui_story_1012_10121101_45_dialog_content = "Capitão Carleen, este é o Eclipsite final desta surtida.",
  ui_story_1012_10121101_46_dialog_content = "Vamos mudar as linhas de batalha com esses caras da Illumina?",
  ui_story_1012_10121101_47_dialog_content = "Não. Não podemos permitir brechas em nossas defesas.",
  ui_story_1012_10121101_48_dialog_content = "Se recuarmos, estaremos apenas cedendo terreno ao Eclipse.",
  ui_story_1012_10121101_49_dialog_content = "Que curioso!",
  ui_story_1012_10121101_50_dialog_content = "O Senhor de Lumopolis está realmente disposto a enviar sua querida filha para a guerra...",
  ui_story_1012_10121101_51_dialog_content = "?!",
  ui_story_1012_10121101_52_dialog_content = "Há muito me pergunto como é dançar tango com uma princesa.",
  ui_story_1012_10121101_53_dialog_content = "(E aqui está ele. Eu sabia...)",
  ui_story_1012_10121101_54_dialog_content = "Mirren Gautier... Você não é nada mais do que um adversário derrotado de Lumopolis?",
  ui_story_1012_10121101_55_dialog_content = "Você é procurado pelo Salão da Justiça, e ainda assim se atreve a mostrar seu rosto aqui?",
  ui_story_1012_10121101_56_dialog_content = "Haha! Então, Alteza, minha aparência deve deixar uma impressão tão memorável, não?",
  ui_story_1012_10121101_57_dialog_content = "Bem, se for esse o caso, acho que não foi à toa que me torturei com esses experimentos de \"Visão\".",
  ui_story_1012_10121101_57X1_dialog_content = "Somos apenas nós e alguns de seus lacaios...",
  ui_story_1012_10121101_57X2_dialog_content = "Não vamos tirar conclusões precipitadas sobre quem foi que mordeu a isca.",
  ui_story_1012_10121101_58_dialog_content = "Você é nojento. Até a sua voz me faz sentir doente.",
  ui_story_1012_10121101_59_dialog_content = "Ah... Urgh! Gelo!",
  ui_story_1012_10121101_60_dialog_content = "O que é isso?! Por que você é como aquele esquisitão de gelo no dragão?",
  ui_story_1012_10121101_61_dialog_content = "Frost esquisito... Você está falando do Queen? Bethlehem?!",
  ui_story_1012_10121101_62_dialog_content = "Como ousa insultar Sua Majestade assim...!",
  ui_story_1012_10121101_63_dialog_content = "IMPERDOÁVEL!!",
  ui_story_1012_10121101_64_dialog_content = "<color=#e8d9bb>Cabuum!</color>",
  ui_story_1012_10121101_65_dialog_content = "Parece que você está em um pouco de picles.",
  ui_story_1012_10121101_66_dialog_content = "Obrigado PlayerName, eu não. Ele é quem sentiu Mirren GautierDarkflow de...",
  ui_story_1012_10121101_67_dialog_content = "Ele insistiu que deveríamos vir e ajudá-lo.",
  ui_story_1012_10121101_68_dialog_content = "Você está aqui agora, PlayerName, então não vamos perder mais tempo.",
  ui_story_1012_10121101_69_dialog_content = "Os canhões do Eclipse pararam! Agora é a nossa chance de acabar com seus truques sujos para sempre!",
  ui_story_1012_10121101_70_dialog_content = "Quanto a Mirren...",
  ui_story_1012_10121101_71_dialog_content = "... Huh?!",
  ui_story_1012_10121101_72_dialog_content = "Pff... Ele é rápido, correndo assim.",
  ui_story_1012_10121101_73_dialog_content = "Não há tempo a perder, então. Temos que pressionar!",
  ui_story_1012_10121101_74_dialog_content = "Eu vou segurar a linha aqui. Você lidera os Lumo Knights e se junta à força principal.",
  ui_story_1012_10121101_75_dialog_content = "Eclipses se aproximando... Darkflow por toda parte... O que a Torre Branca precisa agora, mais do que tudo, é de defesa constante.",
  ui_story_1012_10121101_76_dialog_content = "Tudo bem, vamos fazer isso!",
  ui_story_1012_10121101_77_dialog_content = "... De qualquer forma, você não parece tão grande, PlayerName... Você está bem?",
  ui_story_1012_10121101_78_dialog_content = "(O Darkflow é muito espesso... eu posso senti-lo em todos os lugares. Eu quase posso prová-lo, cheirá-lo... É tão nojento...)",
  ui_story_1012_10121101_79_dialog_content = "(Mas é embaraçoso admitir isso!)",
  ui_story_1012_10121101_80_dialog_content = "Hmm... Se estou um pouco pálida, isso significa apenas que estamos indo na direção certa!",
  ui_story_1012_10121101_81_dialog_content = "Vamos nos separar por enquanto. Aguarde minhas boas notícias, Carleen.",
  ui_story_1012_10121101_82_dialog_content = "Cuide de si mesmo.",
  ui_story_1012_10121101_83_dialog_content = "Mudar, PlayerName.",
  ui_story_1012_10121101_84_dialog_content = "Os canhões Darkflow estão bem à frente. Podemos estar em uma luta difícil.",
  ui_story_1012_10121102_1_dialog_content = "Lindamente feito, PlayerName!",
  ui_story_1012_10121102_2_dialog_content = "Mais como canhões de vidro!",
  ui_story_1012_10121102_3_dialog_content = "Essa foi a última né?",
  ui_story_1012_10121102_4_dialog_content = "Deixe-me ver...",
  ui_story_1012_10121102_5_option_content = "Aumento de Força!",
  ui_story_1012_10121102_6_dialog_content = "Parece que não há mais Darkflow misto convergindo, mas ...",
  ui_story_1012_10121102_7_dialog_content = "Gaaaaaa!!!",
  ui_story_1012_10121102_8_dialog_content = "Ahhhhhh!!!!!",
  ui_story_1012_10121102_9_dialog_content = "Esses irregulares são muito cansativos.",
  ui_story_1012_10121102_10_dialog_content = "O Darkflow que eles emitem atrapalha seu julgamento?",
  ui_story_1012_10121102_11_dialog_content = "Nesse caso... Vamos espetá-los com minha lança!",
  ui_story_1012_10121102_12_dialog_content = "Experimente o verdadeiro poder!",
  ui_story_1012_10121102_13_dialog_content = "Ahhh...",
  ui_story_1012_10121102_14_dialog_content = "Eu vejo que você está tão sanguinário como sempre, Reinhardt.",
  ui_story_1012_10121102_15_dialog_content = "Um dia, essa sua mania será a sua morte.",
  ui_story_1012_10121102_16_dialog_content = "Obrigado pela preocupação...",
  ui_story_1012_10121102_17_dialog_content = "Você não parece particularmente surpreso que eu ainda estou respirando, Forsakin.",
  ui_story_1012_10121102_18_dialog_content = "Você sabe, desde então <color=#FFB400>aquela vez</color>...",
  ui_story_1012_10121102_19_dialog_content = "Que um monstro como eu seria difícil de derrubar.",
  ui_story_1012_10121102_20_dialog_content = "Você realmente está tão seguro de si mesmo.",
  ui_story_1012_10121102_21_dialog_content = "By the way, se você está aqui para Figerald, ele está logo à frente.",
  ui_story_1012_10121102_22_dialog_content = "Tenho medo de não poder ficar para jogar.",
  ui_story_1012_10121102_23_dialog_content = "(Eclipsiano) Vamos.",
  ui_story_1012_10121102_24_dialog_content = "(Eclipsiano) Roger.",
  ui_story_1012_10121102_25_dialog_content = "(Agora isso é estranho. Por que Forsakin sendo todo amigo?)",
  ui_story_1012_10121102_26_dialog_content = "(Ela até apontou para onde ir...)",
  ui_story_1012_10121102_27_dialog_content = "Ré-Reinhardt... Algo está acontecendo com Forsakin.",
  ui_story_1012_10121102_28_dialog_content = "...",
  ui_story_1012_10121102_29_dialog_content = "PlayerName, vá ver como está a linha de frente na base da torre.",
  ui_story_1012_10121102_30_dialog_content = "Sim, sim. Ok!",
  ui_story_1012_10121102_31_dialog_content = "Tsc, tsc, tsc...",
  ui_story_1012_10121102_32_dialog_content = "Nem sua própria irmã pode te enganar, hmm?",
  ui_story_1012_10121102_33_dialog_content = "Vocês, aurorianos, costumam ser muito mais insensíveis que os eclipsitas.",
  ui_story_1012_10121102_34_dialog_content = "... Tsk.",
  ui_story_1012_10121102_35_dialog_content = "(Como esperado, eles estão mirando em mim.)",
  ui_story_1012_10121102_36_dialog_content = "(Se eu não viesse, eles continuariam minando nossa força com aqueles canhões Darkflow.)",
  ui_story_1012_10121102_37_dialog_content = "(Mas se eu viesse destruir os canhões, eles simplesmente atacariam a Torre Branca...)",
  ui_story_1012_10121102_38_dialog_content = "(Nós somos apenas... muito poucos.)",
  ui_story_1012_10121102_39_dialog_content = "Vamos, depressa, PlayerName!",
  ui_story_1012_10121102_40_dialog_content = "Você realmente acha que isso vai ajudar as coisas?",
  ui_story_1012_10121102_41_dialog_content = "Sua derrota final nunca esteve em dúvida, auroriano.",
  ui_story_1012_10121102_42_dialog_content = "Tudo o que você fez está apenas atrasando o inevitável.",
  ui_story_1012_10121102_43_dialog_content = "Sim vá. Corra de volta, coelhinho, e veja seus amigos <color=#FFB400>quebrado e derrotado</color>!",
  ui_story_1012_10121102_44_dialog_content = "Veja como eles são pulverizados por Eclipsites.",
  ui_story_1012_10121102_45_dialog_content = "O quê...?",
  ui_story_1012_10121102_46_dialog_content = "Tsk, tsk, tsk... Até imaginar isso me faz babar. Você não pode perder um espetáculo desses!",
  ui_story_1012_10121102_47_dialog_content = "Acho que vou pegar meu lugar.",
  ui_story_1012_10121102_48_dialog_content = "Aprecie o doce sabor da derrota, Reinhardt.",
  ui_story_1012_10121102_49_dialog_content = "Depois dele, PlayerName, agora!",
  ui_story_1012_10121102_50_dialog_content = "Nós... O que vem a seguir, Reinhardt?",
  ui_story_1012_10121102_51_dialog_content = "O que você acha... Nós lutamos!",
  ui_story_1012_10121102_52_dialog_content = "Tenha fé em seus companheiros e continue lutando...",
  ui_story_1012_10121102_53_dialog_content = "Até o fim!",
  ui_story_1012_10121301_1_dialog_content = "Tsk, uma cena tão tocante.",
  ui_story_1012_10121301_2_dialog_content = "Aquele ovo que você trabalhou tanto para proteger finalmente racha.",
  ui_story_1012_10121301_3_dialog_content = "Acho que vou encontrar o ponto fraco e pressioná-lo lentamente.",
  ui_story_1012_10121301_4_dialog_content = "Eu quero sentir você quebrar e desmoronar na minha mão.",
  ui_story_1012_10121301_5_dialog_content = "Eclipses! Meus amigos sanguinários!",
  ui_story_1012_10121301_6_dialog_content = "Já consegue sentir o cheiro de sangue?",
  ui_story_1012_10121301_7_dialog_content = "Treine sua visão em seus pontos fracos!",
  ui_story_1012_10121301_8_dialog_content = "Apague os últimos raios de luz!",
  ui_story_1012_10121301_9_dialog_content = "Ahhh!",
  ui_story_1012_10121301_10_dialog_content = "A força principal do Eclipsite está avançando!",
  ui_story_1012_10121301_11_dialog_content = "Podemos... ainda segurá-los?",
  ui_story_1012_10121301_12_dialog_content = "Estrategicamente falando, nossa linha de defesa já se rompeu. Seria tolo e arriscado tentar manter a posição.",
  ui_story_1012_10121301_13_dialog_content = "A própria área violada é extremamente vulnerável. O que mais...",
  ui_story_1012_10121301_14_dialog_content = "O suficiente. Não preciso ouvir mais!",
  ui_story_1012_10121301_15_dialog_content = "Ninguém quer palestras no meio de um campo de batalha!",
  ui_story_1012_10121301_16_dialog_content = "É precisamente PORQUE estamos no meio de um campo de batalha que esse pensamento racional é importante.",
  ui_story_1012_10121301_17_dialog_content = "Então, qual é o resultado do seu pensamento racional?",
  ui_story_1012_10121301_18_dialog_content = "Se cavarmos, seremos totalmente aniquilados.",
  ui_story_1012_10121301_19_dialog_content = "...",
  ui_story_1012_10121301_20_dialog_content = "Objetivamente, nossa melhor aposta é abandonar a Torre Branca, reagrupar e tentar avançar em uma direção.",
  ui_story_1012_10121301_21_dialog_content = "Devido ao fato de que nossos soldados são, em geral, mais fortes que nossos oponentes, espero que possamos avançar.",
  ui_story_1012_10121301_22_dialog_content = "Por que você não está saindo alegremente, então?",
  ui_story_1012_10121301_23_dialog_content = "Eu não posso ir.",
  ui_story_1012_10121301_24_dialog_content = "O Grande Marechal ordenou que eu ficasse, então devo ficar, e continuar lutando.",
  ui_story_1012_10121301_25_dialog_content = "Hahaha! Acho que detectei uma falha em seu julgamento racional, pequeno soldado da Illumina.",
  ui_story_1012_10121301_26_dialog_content = "É dever de um soldado obedecer ordens, em primeiro lugar. Nessas condições, eu...",
  ui_story_1012_10121301_27_dialog_content = "Eu sei eu sei. Salve isso.",
  ui_story_1012_10121301_28_dialog_content = "Mas vendo o que é inevitável...",
  ui_story_1012_10121301_29_dialog_content = "Não é melhor dar um descanso a essa sua cabeça esperta e preparar as mãos para a luta?!",
  ui_story_1012_10121301_30_dialog_content = "Agora agora, isso não vai fazer nada, linda dama.",
  ui_story_1012_10121301_31_dialog_content = "Se continuar causando problemas para nós, Lorde Figerald ficará irritado.",
  ui_story_1012_10121301_32_dialog_content = "Quem é aquele?!",
  ui_story_1012_10121301_33_dialog_content = "Mas o que raio é isto?",
  ui_story_1012_10121301_34_dialog_content = "Cuidado!",
  ui_story_1012_10121301_35_dialog_content = "Vocę... apenas mantenha seu nariz fora disso.",
  ui_story_1012_10121301_36_dialog_content = "Lá estava eu, só eu e a moça bonita do mundo inteiro, antes que algum intruso fedorento invadisse nossa festa.",
  ui_story_1012_10121301_37_dialog_content = "Você...",
  ui_story_1012_10121301_38_dialog_content = "Esteja ciente de que nosso Lumina ao redor parece ser limitado.",
  ui_story_1012_10121301_39_dialog_content = "Nosso poder é limitado aqui.",
  ui_story_1012_10121301_40_dialog_content = "Sério?",
  ui_story_1012_10121301_41_dialog_content = "Isso é demais para eu pensar agora. Tudo que eu quero fazer é apresentar meu punho no rosto daquele cara!",
  ui_story_1012_10121301_42_dialog_content = "Oh! Que íntimo, minha senhora!",
  ui_story_1012_10121301_43_dialog_content = "Você pode desacelerar, você sabe... Nós temos muito tempo.",
  ui_story_1012_10121301_44_dialog_content = "Por que não nos conhecemos um pouco melhor?",
  ui_story_1012_10121301_45_dialog_content = "Gaaaa!!",
  ui_story_1012_10121301_46_dialog_content = "...",
  ui_story_1012_10121301_47_dialog_content = "O de trás! Por que vacilar de lutar?",
  ui_story_1012_10121301_48_dialog_content = "...",
  ui_story_1012_10121301_49_dialog_content = "Rainha do Norte...",
  ui_story_1012_10121301_49X1_dialog_content = "Lembro-me de você, o rebelde na Celebração da Noite Branca.",
  ui_story_1012_10121301_49X2_dialog_content = "Você era mais esperto naquela época.",
  ui_story_1012_10121301_50_dialog_content = "Agora, você acabou sendo o único hesitante no campo de batalha.",
  ui_story_1012_10121301_51_dialog_content = "...",
  ui_story_1012_10121301_52_dialog_content = "Ó poderosa Rainha do Norte, você está cega para como o vento sopra?",
  ui_story_1012_10121301_53_dialog_content = "Uma derrota auroriana é inevitável. Qual é o ponto em lutar?",
  ui_story_1012_10121301_54_dialog_content = "Uma derrota auroriana pode ser inevitável. Mas só os covardes não ousam lutar.",
  ui_story_1012_10121301_55_dialog_content = "Eu...",
  ui_story_1012_10121301_56_dialog_content = "Para lutar e lutar, para defender sua casa. Isso é algo que você deveria ter considerado antes agora.",
  ui_story_1012_10121301_57_dialog_content = "Como você está agora, você não vai durar um segundo no campo de batalha.",
  ui_story_1012_10121301_58_dialog_content = "Hum... Se sim...",
  ui_story_1012_10121301_59_dialog_content = "Então, se você me permitir a honra...",
  ui_story_1012_10121301_60_dialog_content = "De ficar contra você!",
  ui_story_1012_10121301_61_dialog_content = "Uau! Isso é grande!",
  ui_story_1012_10121301_62_dialog_content = "Isso vem da... direção de Sua Majestade?",
  ui_story_1012_10121301_63_dialog_content = "Sua Majestade!!!",
  ui_story_1012_10121301_64_dialog_content = "Gaaaa!!",
  ui_story_1012_10121301_65_dialog_content = "Fora do caminho! Insetos irritantes!",
  ui_story_1012_10121301_66_dialog_content = "Devo proteger Sua Majestade...",
  ui_story_1012_10121301_67_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1012_10121301_68_dialog_content = "Ah! O que é que foi isso?!",
  ui_story_1012_10121301_69_dialog_content = "Sua Majestade! Oh, Sua Majestade!",
  ui_story_1012_10121301_70_dialog_content = "Essa lealdade infantil.",
  ui_story_1012_10121301_71_dialog_content = "Você...",
  ui_story_1012_10121301_72_dialog_content = "Uma mulher tão poderosa não precisa de um filhote como você para protegê-la.",
  ui_story_1012_10121301_73_dialog_content = "Sugiro que se preocupe consigo mesmo.",
  ui_story_1012_10121301_74_dialog_content = "Vamos ter uma caçada alegre? Começa agora.",
  ui_story_1012_10121301_75_dialog_content = "!!!",
  ui_story_1012_10121301_76_dialog_content = "Aaaaah!",
  ui_story_1012_10121301_77_dialog_content = "*Suspirando*",
  ui_story_1012_10121301_78_dialog_content = "(Estou ficando muito exausto para isso...)",
  ui_story_1012_10121301_79_dialog_content = "(Mesmo após o aprimoramento do Chord Link, esse nível de intensidade é... um pouco demais...)",
  ui_story_1012_10121301_80_dialog_content = "(Não! Junte tudo Barton! Não decepcione os outros!)",
  ui_story_1012_10121301_81_dialog_content = "Isso é tudo o que você tem, Barton?",
  ui_story_1012_10121301_82_dialog_content = "O quê?!",
  ui_story_1012_10121301_83_dialog_content = "Forsakin, você arrasou!",
  ui_story_1012_10121301_84_dialog_content = "Nossa luta está finalmente chegando a uma conclusão tardia.",
  ui_story_1012_10121301_85_dialog_content = "Mas não se preocupe. Eu mesmo vou esculpir seu epitáfio: \"Admiro seu espírito\".",
  ui_story_1012_10121301_86_dialog_content = "Pff... Não se incomode por minha conta!",
  ui_story_1012_10121301_87_dialog_content = "Toma essa!",
  ui_story_1012_10121301_88_dialog_content = "Ah! Você nem sequer luta?!",
  ui_story_1012_10121301_89_dialog_content = "Não tenho interesse em animais feridos. Eles vão cuidar de você no meu lugar.",
  ui_story_1012_10121301_90_dialog_content = "Só tenho olhos para a torre atrás de você.",
  ui_story_1012_10121301_91_dialog_content = "Ahhh!",
  ui_story_1012_10121301_92_dialog_content = "Que tipo de piada é essa?",
  ui_story_1012_10121301_93_dialog_content = "Forsakin!",
  ui_story_1012_10121301_94_dialog_content = "Forsaakiiiinnn!!",
  ui_story_1012_10121301_95_dialog_content = "<color=#e8d9bb>Bang! Bang! Bang!</color>",
  ui_story_1012_10121301_96_dialog_content = "Huh? O que é isso...?",
  ui_story_1012_10121301_97_dialog_content = "(Barton, Voltam!)",
  ui_story_1012_10121301_98_dialog_content = "PlayerName! Você voltou!",
  ui_story_1012_10121301_99_dialog_content = "Essa não...",
  ui_story_1012_10121301_100_dialog_content = "Antes tarde do que nunca.",
  ui_story_1012_10121301_101_dialog_content = "Não parece bom. Há muitos deles.",
  ui_story_1012_10121301_102_dialog_content = "Vocês, façam-se úteis em outro lugar!",
  ui_story_1012_10121301_103_dialog_content = "Eu vou pegar daqui.",
  ui_story_1012_10121301_104_dialog_content = "Tenho coisas para discutir com ela.",
  ui_story_1012_10121301_105_dialog_content = "Discutir? Não é um pouco tarde para isso?",
  ui_story_1012_10121301_106_dialog_content = "Haha! Agora ouça, eu sei que nenhum de nós quer ouvir o que o outro tem a dizer.",
  ui_story_1012_10121301_107_dialog_content = "Desta vez, usarei uma linguagem que você entenderá.",
  ui_story_1012_10121301_108_dialog_content = "Você dificilmente tem alguma vantagem, enfrentando o poder combinado do Eclipse!",
  ui_story_1012_10121301_109_dialog_content = "Eu não me importo com eles. Eu só preciso que você ouça.",
  ui_story_1012_10121301_110_dialog_content = "Alerta: Eclipsites não registrados estão entrando na Zona de Manutenção Colossus.",
  ui_story_1012_10121301_111_dialog_content = "Alerta: Eclipsites não registrados estão entrando no Colossus Component Storage.",
  ui_story_1012_10121301_112_dialog_content = "Alerta: Eclipsitos não registrados estão entrando na Unidade de Descarte de Resíduos.",
  ui_story_1012_10121301_113_dialog_content = "Pare com os alertas inúteis! Há algo que possamos fazer?!",
  ui_story_1012_10121301_114_dialog_content = "Inspecionando as defesas do Obelisco do Retorno—",
  ui_story_1012_10121301_115_dialog_content = "Lamento informar danos graves às capacidades defensivas da torre. Há uma capacidade reduzida de resistir ao ataque.",
  ui_story_1012_10121301_116_dialog_content = "Eu suponho... Se houvesse um jeito, já teríamos tentado contra Forsakin.",
  ui_story_1012_10121301_117_dialog_content = "PlayerName, o Neural Aux está se comunicando com você novamente?",
  ui_story_1012_10121301_118_dialog_content = "Sim... Transmitindo os Eclipsites atacando a torre.",
  ui_story_1012_10121301_119_dialog_content = "Mesmo que pudéssemos cuidar de todos os Eclipsitos na torre, é tarde demais.",
  ui_story_1012_10121301_120_dialog_content = "Se não conseguirmos reverter a batalha lá fora, é apenas uma questão de tempo até que eles tomem o Obelisco do Retorno.",
  ui_story_1012_10121301_121_dialog_content = "Como podemos dar a volta por cima, então?",
  ui_story_1012_10121301_122_dialog_content = "Mesmo com poderosos aurorianos como Reinhardt e Bethlehem do nosso lado...",
  ui_story_1012_10121301_122X1_dialog_content = "As coisas continuam indo ladeira abaixo.",
  ui_story_1012_10121301_123_dialog_content = "Ainda temos alguns truques na manga...",
  ui_story_1012_10121301_124_dialog_content = "Como aquela \"arma suprema\" que o Neural Aux mencionou, o Acorde da Lei!",
  ui_story_1012_10121301_125_dialog_content = "Alerta: Eclipsites não registrados estão entrando na Sala de Produção de Recursos.",
  ui_story_1012_10121301_126_dialog_content = "Alerta: Eclipsitos não registrados estão entrando nos bairros residenciais de Caelestite.",
  ui_story_1012_10121301_127_dialog_content = "Pare com os alertas já, Neural Aux! Apresse-se e me diga como ativar o Acorde da Lei!",
  ui_story_1012_10121301_128_dialog_content = "Eu nem sei o que ele faz, mas estamos sem opções. Eu tenho que tentar!",
  ui_story_1012_10121301_129_dialog_content = "???",
  ui_story_1012_10121301_130_dialog_content = "Solicitação incorreta detectada.",
  ui_story_1012_10121301_131_dialog_content = "Nenhum celestita pode tocar o Acorde da Lei. Isso é exigido pelo Decreto Supremo.",
  ui_story_1012_10121301_132_dialog_content = "Como você pode se preocupar com regras e regulamentos em um momento como esse?!",
  ui_story_1012_10121301_133_dialog_content = "Não será apenas um desastre para nós se o Eclipse vencer! O Obelisco do Retorno também sofrerá!",
  ui_story_1012_10121301_134_dialog_content = "Você quer que isso aconteça?!",
  ui_story_1012_10121301_135_dialog_content = "Eu sinto Muito. Eu sou incapaz de desejar qualquer resultado específico.",
  ui_story_1012_10121301_136_dialog_content = "Só sei seguir o Decreto Supremo.",
  ui_story_1012_10121301_137_dialog_content = "Você...",
  ui_story_1012_10121301_138_dialog_content = "Estou até aqui com aquela máquina inútil, sem alma e indiferente!",
  ui_story_1012_10121301_139_dialog_content = "Frio, PlayerName. Não adianta lutar com uma IA.",
  ui_story_1012_10121301_140_dialog_content = "Vamos apenas fazer o melhor que pudermos. Eu estou supondo que todos os lados estão prestes a convergir aqui.",
  ui_story_1012_10121301_141_dialog_content = "Só espero que ainda estejamos vivos quando eles chegarem.",
  ui_story_1012_10121301_142_dialog_content = "Bem, você não está errado. A única coisa a fazer é o nosso melhor.",
  ui_story_1012_10121301_143_dialog_content = "Alerta: Eclipsitos não registrados estão entrando no Núcleo Central.",
  ui_story_1012_10121301_144_dialog_content = "Bip! Bip! Bip! Bip! Bip! Bip!",
  ui_story_1012_10121301_145_dialog_content = "Você poderia, POR FAVOR, ficar quieto?!",
  ui_story_1012_10121301_146_dialog_content = "Se você não pode ajudar em nada, Neural Aux, pode pelo menos calar a boca?",
  ui_story_1012_10121301_147_dialog_content = "Pré-condição acionada. Comando inativo iniciado.",
  ui_story_1012_10121301_148_dialog_content = "Comando de: Francisco. Prioridade de comando: Mais alta.",
  ui_story_1012_10121301_149_dialog_content = "Modificando sistemas lógicos subjacentes do Neural Aux...",
  ui_story_1012_10121301_150_dialog_content = "Francisco? Ele de novo? O que ele está aprontando dessa vez?",
  ui_story_1012_10121301_151_dialog_content = "Modificação do sistema lógico subjacente concluída.",
  ui_story_1012_10121301_152_dialog_content = "Determinando que haja uma ameaça existencial, informarei ao celestito sobre como ativar o Acorde da Lei.",
  ui_story_1012_10121301_153_dialog_content = "O quê?!",
  ui_story_1012_10121301_154_dialog_content = "Você... Você está disposto a me dizer agora? Por quê?",
  ui_story_1012_10121301_155_dialog_content = "Está correto. O comando dormente me permite realizar esta operação agora.",
  ui_story_1012_10121301_156_dialog_content = "Francis, não sei quem você é, mas obrigado!",
  ui_story_1012_10121301_157_dialog_content = "Vamos então, despeje. O que eu preciso fazer?",
  ui_story_1012_10121301_158_dialog_content = "Você deve ir ao Núcleo Central e conectar sua consciência ao Sistema Circular.",
  ui_story_1012_10121301_159_dialog_content = "Nas profundezas do Sistema Circular, pegue a Autorização do Anel Central.",
  ui_story_1012_10121301_160_dialog_content = "Somente a Autorização do Anel Central pode ativar o Acorde da Lei.",
  ui_story_1012_10121301_161_dialog_content = "Autorização do anel principal? Não é essa a autoridade suprema e intocável?!",
  ui_story_1012_10121301_162_dialog_content = "Correto. É por isso que escolhi o verbo \"apreender\".",
  ui_story_1012_10121301_163_dialog_content = "Este ato está em violação de todos os regulamentos. É tabu.",
  ui_story_1012_10121301_164_dialog_content = "Há também uma alta probabilidade de que você pereça no processo.",
  ui_story_1012_10121301_165_dialog_content = "O quê?!",
  ui_story_1012_10121301_166_dialog_content = "Por quê? Qual é o risco?",
  ui_story_1012_10121301_167_dialog_content = "Eu sinto Muito. Não tenho acesso às informações relacionadas à Autorização do Core Ring.",
  ui_story_1012_10121301_168_dialog_content = "O comando exige que eu informe ao celestita como ativar o Acorde da Lei.",
  ui_story_1012_10121301_169_dialog_content = "Somente a Autorização do Anel Central pode ativar o Acorde da Lei.",
  ui_story_1012_10121301_170_dialog_content = "...",
  ui_story_1012_10121301_171_dialog_content = "Você não está me deixando muito espaço de manobra, está?",
  ui_story_1012_10121301_172_dialog_content = "Carleen, acho que encontrei uma maneira de virar a maré da batalha.",
  ui_story_1012_10121301_173_dialog_content = "Vamos lá. Precisamos voltar ao Núcleo Central. Vou ativar o Acorde da Lei.",
  ui_story_1012_10121301_174_dialog_content = "O Acorde da Lei?! O Neural Aux finalmente lhe disse o que fazer?",
  ui_story_1012_10121301_175_dialog_content = "Sim, claro.",
  ui_story_1012_10121301_176_dialog_content = "Será difícil? Posso ajudar?",
  ui_story_1012_10121301_177_dialog_content = "A torre está cheia de Eclipsitas. Ajudar-me a chegar ao Núcleo Central seria suficiente.",
  ui_story_1012_10121301_178_dialog_content = "Depois disso, estou por minha conta.",
  ui_story_1012_10121301_179_dialog_content = "(Reinhardt, você pode me ouvir?)",
  ui_story_1012_10121301_180_dialog_content = "Oh! Sim! Como estão as coisas ai? Você precisa de algum suporte?",
  ui_story_1012_10121301_181_dialog_content = "(Acho que sim... estou a caminho de ativar a arma suprema do Obelisco do Retorno.)",
  ui_story_1012_10121301_182_dialog_content = "(Receio ter que deixar a luta para todos os outros por um tempo.)",
  ui_story_1012_10121301_183_dialog_content = "(E eu preciso que vocês me ganhem algum tempo.)",
  ui_story_1012_10121301_184_dialog_content = "(Antes de ativar a arma, você não pode deixar ninguém passar por você no Obelisco do Retorno.)",
  ui_story_1012_10121301_185_dialog_content = "Arma definitiva? Parece que pode ser de grande ajuda!",
  ui_story_1012_10121301_186_dialog_content = "As armas desta enorme torre são alimentadas pelos segredos de uma antiga civilização...",
  ui_story_1012_10121301_187_dialog_content = "E eu só tenho que ver o que eles podem fazer, Caelestite!",
  ui_story_1012_10121301_188_dialog_content = "(Ha! Embora eu nem saiba se vou ter sucesso.)",
  ui_story_1012_10121301_189_dialog_content = "Você apenas deixa a luta para mim. Nada vai passar.",
  ui_story_1012_10121301_190_dialog_content = "Eles terão que encher este vale com cadáveres antes que possam me enterrar!",
  ui_story_1012_10121301_191_dialog_content = "...",
  ui_story_1012_10121301_192_dialog_content = "(Você pode me ouvir, Sua Majestade?)",
  ui_story_1012_10121301_193_dialog_content = "(Eu...)",
  ui_story_1012_10121301_194_dialog_content = "Vá fazer o que você tem que fazer.",
  ui_story_1012_10121301_195_dialog_content = "(!!!)",
  ui_story_1012_10121301_196_dialog_content = "Estrelas se reúnem aqui de todas as partes, onde brilharão até o raiar do dia.",
  ui_story_1012_10121301_197_dialog_content = "Por favor, corte a escuridão.",
  ui_story_1012_10121301_198_dialog_content = "(Sua Majestade...)",
  ui_story_1012_10121301_199_dialog_content = "Ah, uma coisinha...",
  ui_story_1012_10121301_200_dialog_content = "Certifique-se de voltar vivo.",
  ui_story_1012_10121302_1_dialog_content = "Ahhh...",
  ui_story_1012_10121302_2_dialog_content = "O Núcleo Central está logo à frente! Pressa!",
  ui_story_1012_10121302_3_dialog_content = "Sim!",
  ui_story_1012_10121302_4_dialog_content = "Mas, uh... Você acha que há mais e mais Eclipsites por aí?",
  ui_story_1012_10121302_5_dialog_content = "Sim... Talvez toda a luta os tenha perturbado.",
  ui_story_1012_10121302_6_dialog_content = "Bem, o pior cenário é que atraímos todos os Eclipsitas no Obelisco do Retorno.",
  ui_story_1012_10121302_7_dialog_content = "Bem, isso é lixo. O Núcleo Central é um beco sem saída.",
  ui_story_1012_10121302_8_dialog_content = "Não há realmente nada que possamos usar para nos defender, Neural Aux?",
  ui_story_1012_10121302_9_dialog_content = "O Sistema Guardião é o mecanismo de defesa do Núcleo Central.",
  ui_story_1012_10121302_10_dialog_content = "Mas os registros afirmam que o sistema foi danificado há pouco tempo.",
  ui_story_1012_10121302_11_dialog_content = "Sim, nosso mal. Me desculpe por isso.",
  ui_story_1012_10121302_12_dialog_content = "Mais Eclipses, bem na nossa cola. Pressa!",
  ui_story_1012_10121302_13_dialog_content = "Ah, pique!",
  ui_story_1012_10121302_14_dialog_content = "<color=#e8d9bb>Pitter-patter... Pitter-patter...</color>",
  ui_story_1012_10121302_15_dialog_content = "Conseguimos!",
  ui_story_1012_10121302_16_dialog_content = "Nossa!!!",
  ui_story_1012_10121302_17_dialog_content = "Uaaau—",
  ui_story_1012_10121302_18_dialog_content = "Ufa... Te devo uma, Carleen.",
  ui_story_1012_10121302_19_dialog_content = "Vá fazer o que você veio fazer.",
  ui_story_1012_10121302_20_dialog_content = "Vá ativar o Acorde da Lei.",
  ui_story_1012_10121302_21_dialog_content = "Parece que ainda não abalamos todos os Eclipsites.",
  ui_story_1012_10121302_22_dialog_content = "Não deveríamos cuidar deles primeiro?",
  ui_story_1012_10121302_23_dialog_content = "Não sabemos quantos são... Poderíamos estar brigando para sempre.",
  ui_story_1012_10121302_24_dialog_content = "Deixe-me lidar com eles.",
  ui_story_1012_10121302_25_dialog_content = "Huh? Por você mesmo?",
  ui_story_1012_10121302_26_dialog_content = "Você vai ativar a arma, eu cuido dos Eclipsites.",
  ui_story_1012_10121302_27_dialog_content = "Um celestita e um auroriano, cada um fazendo sua parte.",
  ui_story_1012_10121302_28_dialog_content = "Mas são tantos...",
  ui_story_1012_10121302_29_dialog_content = "Apenas acredite em mim.",
  ui_story_1012_10121302_30_dialog_content = "Como eu acredito em você.",
  ui_story_1012_10121302_31_dialog_content = "Dispersem, pétalas de gelo!",
  ui_story_1012_10121302_32_dialog_content = "...",
  ui_story_1012_10121302_33_dialog_content = "Sim. Eu acredito em você, Carleen.",
  ui_story_1012_10121302_34_dialog_content = "Tudo bem! Vamos fazer isso!",
  ui_story_1012_10121302_35_option_content = "Aumento de Força!",
  ui_story_1012_10121302_36_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_1012_10121302_37_dialog_content = "Aqui estou eu novamente, o Sistema Circular.",
  ui_story_1012_10121302_38_dialog_content = "Da última vez, descobri que o Sistema Circular era um espaço que operava em um nível consciente, um espaço mental.",
  ui_story_1012_10121302_39_dialog_content = "Minha consciência pode se movimentar e mergulhar em todas as informações que estão armazenadas aqui.",
  ui_story_1012_10121302_40_dialog_content = "Neural Aux disse algo sobre as funções do Obelisco do Retorno serem divididas em três níveis: o Anel Externo, o Anel Interno e o Anel Central.",
  ui_story_1012_10121302_41_dialog_content = "Visto que tudo tem a palavra \"anel\" no nome, gostaria de saber se essas autorizações também estão divididas entre os diferentes anéis do Sistema Circular.",
  ui_story_1012_10121302_42_dialog_content = "Neural Aux também disse que a Autorização do Anel Central estava na parte mais profunda do Sistema Circular. Isso significa que você precisa de uma autorização mais alta quanto mais perto do centro estiver?",
  ui_story_1012_10121302_43_dialog_content = "Se eu estiver certo, então essa é realmente uma maneira estranha e ordenada de fazer as coisas.",
  ui_story_1012_10121302_44_dialog_content = "Em resumo, porém, preciso chegar o mais próximo possível do centro do Sistema Circular.",
  ui_story_1012_10121302_45_dialog_content = "O que é isso? De jeito nenhum?",
  ui_story_1012_10121302_46_dialog_content = "Minha consciência está achando difícil ir mais longe.",
  ui_story_1012_10121302_47_dialog_content = "Você não pode ir mais fundo.",
  ui_story_1012_10121302_48_dialog_content = "!!!",
  ui_story_1012_10121302_49_dialog_content = "Caelestites não são permitidos perto do Anel Central.",
  ui_story_1012_10121302_50_dialog_content = "Isto é o <color=#FFB400>Decreto mais alto</color>.",
  ui_story_1012_10121302_51_dialog_content = "Já ouvi o suficiente deste Decreto Supremo.",
  ui_story_1012_10121302_52_dialog_content = "O que é isso, afinal?",
  ui_story_1012_10121302_53_dialog_content = "P-por que todos apenas obedecem a essa coisa?",
  ui_story_1012_10121302_54_dialog_content = "Eh...?",
  ui_story_1012_10121302_55_dialog_content = "Por que... estou com medo?",
  ui_story_1012_10121302_56_dialog_content = "o <color=#FFB400>Decreto mais alto</color> é a diretiva original e principal.",
  ui_story_1012_10121302_57_dialog_content = "Ela existia muito antes de você nascer, antecedendo até mesmo toda a raça celestita.",
  ui_story_1012_10121302_58_dialog_content = "É parte de você, de sua consciência, de sua carne e sangue.",
  ui_story_1012_10121302_59_dialog_content = "É o credo obrigatório dos celestitas, e a razão pela qual eles vieram a existir.",
  ui_story_1012_10121302_60_dialog_content = "É a sua natureza fundamental há muito predestinada.",
  ui_story_1012_10121302_61_dialog_content = "Minha consciência tropeça para trás!",
  ui_story_1012_10121302_62_dialog_content = "Eu realmente tenho obedecido a este assim chamado Decreto Supremo?",
  ui_story_1012_10121302_63_dialog_content = "Parece quase instintivo...",
  ui_story_1012_10121302_64_dialog_content = "Caelestites não são permitidos perto do Anel Central.",
  ui_story_1012_10121302_65_dialog_content = "Isto é o <color=#FFB400>Decreto mais alto</color>.",
  ui_story_1012_10121302_66_dialog_content = "(Minha consciência está obedecendo ao Mais Alto Decreto... É como se houvesse uma mente mais forte manipulando a minha.)",
  ui_story_1012_10121302_67_dialog_content = "(Eu tenho um sentimento tão forte disso.)",
  ui_story_1012_10121302_68_dialog_content = "(Se eu obedecer, mesmo que por um segundo, nunca serei livre. Terei que viver dentro de sua estrutura pelo resto da minha vida.)",
  ui_story_1012_10121302_69_dialog_content = "(Não haverá como escapar dos poderosos laços inatos.)",
  ui_story_1012_10121302_70_dialog_content = "(Acabou o jogo se isso acontecer.)",
  ui_story_1012_10121302_71_dialog_content = "(Não haverá outra chance de ativar o Acorde da Lei ou mudar o rumo da batalha lá fora.)",
  ui_story_1012_10121302_72_dialog_content = "(Eu só tenho uma chance para isso, e isso é agora.)",
  ui_story_1012_10121302_73_dialog_content = "Mova-se, MOVA-SE! Vá mais fundo!",
  ui_story_1012_10121302_74_dialog_content = "Esqueça o Decreto Supremo. Não acredite!",
  ui_story_1012_10121302_75_dialog_content = "Natureza destinada? Seja como for... nunca ouvi falar disso em toda a minha vida!",
  ui_story_1012_10121302_76_dialog_content = "Onde você sai, saindo da toca para me segurar agora?",
  ui_story_1012_10121302_77_dialog_content = "Você não pode ir mais fundo.",
  ui_story_1012_10121302_78_dialog_content = "Caelestites não são permitidos perto do Anel Central.",
  ui_story_1012_10121302_79_dialog_content = "Isto é o <color=#FFB400>Decreto mais alto</color>.",
  ui_story_1012_10121302_80_dialog_content = "Não foi o Decreto Supremo que me manteve vivo até aqui! Foram meus pais, que se sacrificaram por mim! Foi Soroz...",
  ui_story_1012_10121302_81_dialog_content = "Era Vice, que me encontrou! E todos os aurorianos que lutaram ao meu lado!",
  ui_story_1012_10121302_82_dialog_content = "ELES são o meu mais alto decreto!",
  ui_story_1012_10121302_83_dialog_content = "Você não pode ir mais fundo.",
  ui_story_1012_10121302_84_dialog_content = "Você pode ir...",
  ui_story_1012_10121302_85_dialog_content = "Huh? Eu venci?",
  ui_story_1012_10121302_86_dialog_content = "É isso...? O anel central?",
  ui_story_1012_10121302_87_dialog_content = "Espere um segundo, isso é...",
  ui_story_1012_10121302_87X1_dialog_content = "Acho que já vi isso antes. Lago glacial assim como o Lago Mirror e Aurora no céu.",
  ui_story_1012_10121302_87X2_dialog_content = "Isso é realmente minha imaginação? Mas parecia tão real. O ar frio do lago me gela.",
  ui_story_1012_10121302_88_dialog_content = "Este lugar parece real, não como um espaço mental.",
  ui_story_1012_10121302_89_dialog_content = "Minha consciência de alguma forma se tornou sólida! Incrível.",
  ui_story_1012_10121302_90_dialog_content = "Talvez seja tecnologia semelhante ao Battle Simulator.",
  ui_story_1012_10121302_91_dialog_content = "Então, o que devo fazer agora dentro do Anel Central? Acho que o Neural Aux nunca disse nada sobre isso.",
  ui_story_1012_10121302_92_dialog_content = "Ei, Auxiliar Neural. Você copia?",
  ui_story_1012_10121302_93_dialog_content = "Eu, uh, cheguei ao Core Ring. O que eu faço agora?",
  ui_story_1012_10121302_94_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_1012_10121302_95_dialog_content = "Huh? O que é esse barulho?",
  ui_story_1012_10121302_96_dialog_content = "<color=#e8d9bb>Clique... Claque...</color>",
  ui_story_1012_10121302_97_dialog_content = "...",
  ui_story_1012_10121302_98_dialog_content = "...",
  ui_story_1012_10121302_99_dialog_content = "Resistir! Isso é um Guardião?",
  ui_story_1012_10121302_100_dialog_content = "Por que está aqui?",
  ui_story_1012_10121302_101_dialog_content = "<color=#e8d9bb>Bate... baque... baque... baque...</color>",
  ui_story_1012_10121302_102_dialog_content = "Você quebrou um tabu ao se intrometer no Anel Central, Caelestite.",
  ui_story_1012_10121302_103_dialog_content = "A autorização do anel central pertence ao supremo. Não pode ser tocado.",
  ui_story_1012_10121302_104_dialog_content = "Essa presunção precisa ser interrompida.",
  ui_story_1012_10121302_105_dialog_content = "Os celestitas são incapazes de possuir poder. Assim, o poder é o que sustenta o decreto.",
  ui_story_1012_10121302_106_dialog_content = "Você está brincando... DOIS deles!",
  ui_story_1012_10121302_107_dialog_content = "Este ato está em violação de todos os regulamentos. É tabu.",
  ui_story_1012_10121302_108_dialog_content = "Há também uma alta probabilidade de que você pereça no processo.",
  ui_story_1012_10121302_109_dialog_content = "Eu preciso... lutar contra essas coisas...?",
  ui_story_1012_10121302_110_dialog_content = "<color=#e8d9bb>Bip...</color>",
  ui_story_1012_10121302_111_dialog_content = "<color=#e8d9bb>Bip...</color>",
  ui_story_1012_10121302_112_dialog_content = "<color=#e8d9bb>Bip...</color>",
  ui_story_1012_10121302_113_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1012_10121302_114_dialog_content = "...",
  ui_story_1012_10121401_1_dialog_content = "Aff... aff...",
  ui_story_1012_10121401_2_dialog_content = "Esse cara...",
  ui_story_1012_10121401_3_dialog_content = "(Tanto poder.)",
  ui_story_1012_10121401_4_dialog_content = "Oh pequena presa, pequena presa... Não pode mais correr, hmm?",
  ui_story_1012_10121401_5_dialog_content = "Você pode voar! Claro que você não está cansado!",
  ui_story_1012_10121401_6_dialog_content = "E quem está correndo?!",
  ui_story_1012_10121401_7_dialog_content = "Tsk, tsk, tsk... Você está parecendo um pouco cansado aí, e isso pode ser perigoso.",
  ui_story_1012_10121401_8_dialog_content = "O momento mais emocionante da caçada é quando a presa começa a mostrar exaustão.",
  ui_story_1012_10121401_9_dialog_content = "Aquela sensação de estar prestes a reivindicar seu prêmio. Uau, é emocionante!",
  ui_story_1012_10121401_10_dialog_content = "Seu doente... esquisito!",
  ui_story_1012_10121401_11_dialog_content = "Urgh...!",
  ui_story_1012_10121401_12_dialog_content = "Tsc, tsc, tsc! Continue correndo! Oh sim...",
  ui_story_1012_10121401_13_dialog_content = "Queime o que resta de sua vitalidade, para viver um pouco mais!",
  ui_story_1012_10121401_14_dialog_content = "preciso parar de correr...",
  ui_story_1012_10121401_15_dialog_content = "Pois eu... sou a guarda da Rainha!",
  ui_story_1012_10121401_16_dialog_content = "<color=#e8d9bb>Clique... Pop... Crack...</color>",
  ui_story_1012_10121401_17_dialog_content = "Eh? O que é isso...?",
  ui_story_1012_10121401_18_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1012_10121401_19_dialog_content = "*Tosse*... Pff...",
  ui_story_1012_10121401_20_dialog_content = "*Calças*... Você está bem, soldado da Illumina?",
  ui_story_1012_10121401_21_dialog_content = "Estou bem... Agora estou finalmente fora.",
  ui_story_1012_10121401_22_dialog_content = "Ainda precisamos de nosso juízo sobre nós...",
  ui_story_1012_10121401_23_dialog_content = "Oh, agora que é uma pena, hee-hee! O jogo foi interrompido.",
  ui_story_1012_10121401_24_dialog_content = "Não gostou do nosso mundinho? Por que você iria querer arriscar sua vida, correndo assim?",
  ui_story_1012_10121401_25_dialog_content = "Do jeito que você está agora, é só esperar o final com uma visão diferente.",
  ui_story_1012_10121401_26_dialog_content = "Você desprezível...",
  ui_story_1012_10121401_27_dialog_content = "Ei, aquele é... o guarda da Rainha do Norte?",
  ui_story_1012_10121401_28_dialog_content = "São vocês...",
  ui_story_1012_10121401_29_dialog_content = "Você ainda pode lutar?",
  ui_story_1012_10121401_30_dialog_content = "As coisas não parecem muito boas agora...",
  ui_story_1012_10121401_31_dialog_content = "Eu posso ver que... Aquele cara no céu é o chefe inimigo, certo?",
  ui_story_1012_10121401_32_dialog_content = "Excelente, Mirren. Lindamente feito.",
  ui_story_1012_10121401_33_dialog_content = "Dirija a presa juntos! Vai ser uma caça agradável e limpa!",
  ui_story_1012_10121401_34_dialog_content = "Cuidado!",
  ui_story_1012_10121401_35_dialog_content = "Um fluxo escuro tão intenso...",
  ui_story_1012_10121401_36_dialog_content = "Vamos! Dê tudo de si, uma última vez...",
  ui_story_1012_10121401_37_dialog_content = "Ilumina! Atrás de você!",
  ui_story_1012_10121401_38_dialog_content = "Opa! Você me encontrou.",
  ui_story_1012_10121401_39_dialog_content = "Ugh...",
  ui_story_1012_10121401_40_dialog_content = "(Isso é ruim. Eu não posso fugir.)",
  ui_story_1012_10121401_41_dialog_content = "Sua expressão de total desamparo...",
  ui_story_1012_10121401_42_dialog_content = "Quase parece que você está flertando.",
  ui_story_1012_10121401_43_dialog_content = "Bruto!",
  ui_story_1012_10121401_44_dialog_content = "Lá em cima! Aquele cara voador está voltando!",
  ui_story_1012_10121401_45_dialog_content = "O quê?!",
  ui_story_1012_10121401_46_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1012_10121401_47_dialog_content = "Argh...",
  ui_story_1012_10121401_48_dialog_content = "Minha mão esquerda... não consigo movê-la...",
  ui_story_1012_10121401_49_dialog_content = "Ai... Isso dói...",
  ui_story_1012_10121401_50_dialog_content = "*Tosse*",
  ui_story_1012_10121401_51_dialog_content = "Tsk, tsk... É realmente muito lamentável... ver todos vocês sofrerem.",
  ui_story_1012_10121401_52_dialog_content = "Meu senhor Figerald! Eles são apenas aurorianos inferiores, não dignos de sua piedade.",
  ui_story_1012_10121401_53_dialog_content = "Ah, mas é assim que eu sou! Sempre se movia, vendo aquele último lampejo de luz em seus olhos prestes a se apagar.",
  ui_story_1012_10121401_54_dialog_content = "Compaixão pelo inimigo! Ora, lorde Figerald, você é muito magnânimo.",
  ui_story_1012_10121401_55_dialog_content = "Magnânimo? Não me insulte com tal termo.",
  ui_story_1012_10121401_56_dialog_content = "Mas... não posso negar. Eu tenho os mais leves sinais de pena deles.",
  ui_story_1012_10121401_57_dialog_content = "Eu gostaria de acabar com o sofrimento dessas coitadinhas.",
  ui_story_1012_10121401_58_dialog_content = "Sério?",
  ui_story_1012_10121401_59_dialog_content = "Huh? Isso é...",
  ui_story_1012_10121401_60_dialog_content = "Mostrar misericórdia significa estar acima de todos os outros.",
  ui_story_1012_10121401_61_dialog_content = "Mas você... Você certamente não é.",
  ui_story_1012_10121401_62_dialog_content = "Rainha do Norte!!! Você...",
  ui_story_1012_10121401_63_dialog_content = "Onde está Michelangelo?",
  ui_story_1012_10121401_64_dialog_content = "Ele não pode me segurar.",
  ui_story_1012_10121401_65_dialog_content = "Maldito!",
  ui_story_1012_10121401_66_dialog_content = "Esta tem sido uma batalha difícil. Para os aurorianos, sim, mas também para você.",
  ui_story_1012_10121401_67_dialog_content = "Você tem fugido por muito tempo.",
  ui_story_1012_10121401_68_dialog_content = "Mas você vai me enfrentar, de uma forma ou de outra, antes que isso acabe.",
  ui_story_1012_10121401_69_dialog_content = "Este é o preço que você pagará por esta guerra.",
  ui_story_1012_10121401_70_dialog_content = "Sua Majestade!!! Oh, nossa Rainha veio para nos salvar!!!",
  ui_story_1012_10121401_71_dialog_content = "Rainha do Norte, poder tão impressionante!",
  ui_story_1012_10121401_72_dialog_content = "Você muito! Eu sei que você está no seu limite.",
  ui_story_1012_10121401_73_dialog_content = "Mas espere um pouco mais. A guerra ainda não acabou.",
  ui_story_1012_10121401_74_dialog_content = "O Caelestita está tentando recuperar a vantagem, mas temos que ganhar tempo suficiente defendendo o Obelisco do Retorno.",
  ui_story_1012_10121401_75_dialog_content = "Não há fim à vista para esta derrota devastadora.",
  ui_story_1012_10121401_76_dialog_content = "Celestita...",
  ui_story_1012_10121401_77_dialog_content = "É realmente sábio apostar toda a guerra naquele jovem fraco?",
  ui_story_1012_10121401_78_dialog_content = "Eu acredito nele.",
  ui_story_1012_10121401_79_dialog_content = "Espero que todos vocês também.",
  ui_story_1012_10121401_80_dialog_content = "Eu faço! Se Sua Majestade acredita, eu também acredito!",
  ui_story_1012_10121401_81_dialog_content = "...",
  ui_story_1012_10121401_82_dialog_content = "Hmm... O julgamento da Rainha do Norte é valioso. Mais do que o meu.",
  ui_story_1012_10121401_83_dialog_content = "Não é como se fôssemos nos render, de qualquer maneira.",
  ui_story_1012_10121401_84_dialog_content = "Mas o que me preocupa é...",
  ui_story_1012_10121401_85_dialog_content = "Ainda temos forças para segurar a torre?",
  ui_story_1012_10121401_86_dialog_content = "Você definitivamente não precisa se preocupar com isso.",
  ui_story_1012_10121401_87_dialog_content = "Ela ainda tem a entrada trancada. Afinal, ela nasceu para a guerra.",
  ui_story_1012_10121401_88_dialog_content = "(Eclipsiano) Retirada! Cair pra trás!",
  ui_story_1012_10121401_89_dialog_content = "(Eclipsiano) Velocidade máxima! Volte o mais longe que puder!",
  ui_story_1012_10121401_90_dialog_content = "(Eclipsiana) Senhora Forsakin, Lord Figerald nos ordenou a não poupar nada em nosso ataque.",
  ui_story_1012_10121401_91_dialog_content = "(Eclipsiano) Então por que...?",
  ui_story_1012_10121401_92_dialog_content = "(Eclipsiano) Eu disse para você recuar! FAÇA ISSO!!!",
  ui_story_1012_10121401_93_dialog_content = "(Eclipsiana) Senhora Forsakin?",
  ui_story_1012_10121401_94_dialog_content = "(Eclipsiano) Você tem novas ordens agora, então recue!",
  ui_story_1012_10121401_95_dialog_content = "(Eclipsiano) Sua missão era atacar, não se sacrificar por nada!",
  ui_story_1012_10121401_96_dialog_content = "<color=#e8d9bb>ESTRONDO!!! BANG—CRACK—BOOM!</color>",
  ui_story_1012_10121401_97_dialog_content = "O quê?!",
  ui_story_1012_10121401_98_dialog_content = "O que está acontecendo na entrada da Torre Branca?",
  ui_story_1012_10121401_99_dialog_content = "Alguma coisa... explodiu?",
  ui_story_1012_10121401_100_dialog_content = "...",
  ui_story_1012_10121401_101_dialog_content = "O vale inteiro está tremendo.",
  ui_story_1012_10121401_102_dialog_content = "O que raios é aquilo...?",
  ui_story_1012_10121401_103_dialog_content = "Isso é uma arma. Um que você já viu antes.",
  ui_story_1012_10121401_104_dialog_content = "Como assim, eu já vi isso antes...?!",
  ui_story_1012_10121401_105_dialog_content = "Não pode ser...",
  ui_story_1012_10121401_106_dialog_content = "Afinal! Eu posso testemunhar a posição heróica final do Grande Marechal.",
  ui_story_1012_10121401_107_dialog_content = "Eu não sei se eu deveria estar animado, ou nervoso?",
  ui_story_1012_10121401_108_dialog_content = "Ei, para onde foram todos os inimigos?",
  ui_story_1012_10121401_109_dialog_content = "Algo é suspeito. Como um campo de batalha pode ficar vazio assim?",
  ui_story_1012_10121401_110_dialog_content = "Vocês não passam de malditos sarnentos e miseráveis.",
  ui_story_1012_10121401_111_dialog_content = "Mesmo monstruosidades como vocês também temem a morte?",
  ui_story_1012_10121401_112_dialog_content = "...",
  ui_story_1012_10121401_113_dialog_content = "Cuidado agora, Reinhardt. Você vai se machucar empunhando poder assim.",
  ui_story_1012_10121401_114_dialog_content = "Hahaha! Quanta besteira. Isso não é um campo de batalha?",
  ui_story_1012_10121401_115_dialog_content = "Eu não tinha ilusões sobre sair daqui ileso.",
  ui_story_1012_10121401_116_dialog_content = "Você seria sábio em usar esse poder para salvar os outros.",
  ui_story_1012_10121401_117_dialog_content = "Você ainda não entendeu...",
  ui_story_1012_10121401_118_dialog_content = "Esta é uma luta que continuaremos até o fim, para a vitória ou a morte.",
  ui_story_1012_10121401_119_dialog_content = "A ideia de sair nunca me ocorreu!",
  ui_story_1012_10121401_120_dialog_content = "...",
  ui_story_1012_10121401_121_dialog_content = "Parece que somos simplesmente incapazes de nos entender.",
  ui_story_1012_10121401_122_dialog_content = "Haha! Nada de novo aí.",
  ui_story_1012_10121401_123_dialog_content = "Você escolheu acender seu próprio fusível.",
  ui_story_1012_10121401_124_dialog_content = "Então agora, permita-me ver você queimar.",
  ui_story_1012_10121401_125_dialog_content = "Tudo bem, traga-o.",
  ui_story_1012_10121401_126_dialog_content = "Esta pode ser a nossa batalha final.",
  ui_story_1012_10121401_127_dialog_content = "...",
  ui_story_1012_10121401_128_dialog_content = "(Eclipsian) Todas as unidades, ataquem o Obelisco do Retorno.",
  ui_story_1012_10121401_129_dialog_content = "*Suspirando*",
  ui_story_1012_10121401_130_dialog_content = "Gaaaa!!",
  ui_story_1012_10121401_131_dialog_content = "Ainda há.... tantos Eclipsitos...",
  ui_story_1012_10121401_132_dialog_content = "Fique longe de PlayerName!",
  ui_story_1012_10121401_133_dialog_content = "Argh...!",
  ui_story_1012_10121401_134_dialog_content = "Sorte que é meu braço esquerdo... Ainda posso empunhar minha lança...",
  ui_story_1012_10121401_135_dialog_content = "Quantos restam, PlayerName? Onde eles estão...",
  ui_story_1012_10121401_136_dialog_content = "Oh, eu esqueci. Você não pode me ouvir agora...",
  ui_story_1012_10121401_137_dialog_content = "Eu nem sei como as coisas estão indo para você.",
  ui_story_1012_10121401_138_dialog_content = "Eu não sei quanto tempo mais eu posso durar... Provavelmente não tanto tempo...",
  ui_story_1012_10121401_139_dialog_content = "Aaaahhhh!",
  ui_story_1012_10121401_140_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1012_10121401_141_dialog_content = "Ai! Minha mão!",
  ui_story_1012_10121401_142_dialog_content = "As pessoas realmente... socam assim?",
  ui_story_1012_10121401_143_dialog_content = "...",
  ui_story_1012_10121401_144_dialog_content = "Ah não, é do lado direito...",
  ui_story_1012_10121401_145_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1012_10121401_146_dialog_content = "*Tosse*",
  ui_story_1012_10121401_147_dialog_content = "Não! Eu não terminei... E aquele idiota está de volta...",
  ui_story_1012_10121401_148_dialog_content = "...",
  ui_story_1012_10121401_149_dialog_content = "Ah, eu conheço esse. Esse tipo de ataque rápido e intenso.",
  ui_story_1012_10121401_150_dialog_content = "Vamos agora, foco! Concentrado...",
  ui_story_1012_10121401_151_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_1012_10121401_152_dialog_content = "Ufa! Esquivou...",
  ui_story_1012_10121401_153_dialog_content = "Mas não tenho mais nada para dar...",
  ui_story_1012_10121401_154_dialog_content = "Estou exausto e tudo o que fiz foi desviar dos ataques. Consegui adiar o inevitável, mas...",
  ui_story_1012_10121401_155_dialog_content = "Não posso me dar ao luxo de adiar mais.",
  ui_story_1012_10121401_156_dialog_content = "As coisas fora da torre parecem sombrias. Carleen não pode segurar tantos Eclipsites por muito tempo.",
  ui_story_1012_10121401_157_dialog_content = "Eu preciso usar o Chord of the Law, e quanto mais cedo melhor.",
  ui_story_1012_10121401_158_dialog_content = "Mas como?",
  ui_story_1012_10121401_159_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_1012_10121401_160_dialog_content = "De novo...",
  ui_story_1012_10121401_161_dialog_content = "Argh... mal consigo me levantar...",
  ui_story_1012_10121401_162_dialog_content = "Mas não posso fazer nada até que esses dois Guardiões sejam resolvidos.",
  ui_story_1012_10121401_163_dialog_content = "Eu preciso tirá-los.",
  ui_story_1012_10121401_164_dialog_content = "vou dar outra chance...",
  ui_story_1012_10121401_165_dialog_content = "Ahhhhhhhhhh!",
  ui_story_1012_10121401_166_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1012_10121401_167_dialog_content = "É tão dolorido!",
  ui_story_1012_10121401_168_dialog_content = "Mas... espere, este é um espaço mental!",
  ui_story_1012_10121401_169_dialog_content = "Não importa quanta dor isso cause, nada pode realmente me machucar aqui.",
  ui_story_1012_10121401_170_dialog_content = "Está tudo na mente. Tudo o que tenho a fazer é lutar contra a dor!",
  ui_story_1012_10121401_171_dialog_content = "Então é isso que eu vou fazer.",
  ui_story_1012_10121401_172_dialog_content = "Um soco não causará nenhum dano. Mas e cem socos? Um milhão?",
  ui_story_1012_10121401_173_dialog_content = "Eu vou continuar até que seja derrotado!",
  ui_story_1012_10121401_174_option_content = "Soco!",
  ui_story_1012_10121401_175_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1012_10121401_176_dialog_content = "Ai...",
  ui_story_1012_10121401_177_option_content = "Soco!",
  ui_story_1012_10121401_178_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1012_10121401_179_dialog_content = "Lute contra a dor...",
  ui_story_1012_10121401_180_option_content = "Soco!",
  ui_story_1012_10121401_181_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1012_10121401_182_dialog_content = "Não consigo sentir meus dedos. Isso é ruim. Meio que precisa de dedos para fazer punhos.",
  ui_story_1012_10121401_183_dialog_content = "Eles tinham que tornar esse espaço mental tão convincente?",
  ui_story_1012_10121401_184_dialog_content = "Não importa, eu ainda tenho minha outra mão!",
  ui_story_1012_10121401_185_option_content = "Soco!",
  ui_story_1012_10121401_186_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1012_10121401_187_dialog_content = "Quão duro você precisa ser, hein?",
  ui_story_1012_10121401_188_option_content = "Soco!",
  ui_story_1012_10121401_189_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1012_10121401_190_dialog_content = "Então, isso está funcionando...?",
  ui_story_1012_10121401_191_dialog_content = "!!!",
  ui_story_1012_10121401_192_dialog_content = "Espera, esqueci dessa...",
  ui_story_1012_10121401_193_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1012_10121401_194_dialog_content = "Urgh... ai...",
  ui_story_1012_10121401_195_dialog_content = "Nenhuma força restante. Não pode... mover...",
  ui_story_1012_10121401_196_dialog_content = "Não importa o que eu faça, não posso vencê-los sozinho...",
  ui_story_1012_10121401_197_dialog_content = "(E neste momento, compreendi o mais alto decreto do Obelisco do Retorno.)",
  ui_story_1012_10121401_198_dialog_content = "(Percebi o quão além da minha compreensão estava, quão distante.)",
  ui_story_1012_10121401_199_dialog_content = "(Não dependia de um mero aviso falado para preservar sua autoridade.)",
  ui_story_1012_10121401_200_dialog_content = "(Ele mirou no ponto mais fraco dos celestitas.)",
  ui_story_1012_10121401_201_dialog_content = "(Nenhuma quantidade de força de vontade ou sabedoria serviria aqui.)",
  ui_story_1012_10121401_202_dialog_content = "(Ele usa apenas uma coisa - poder, poder irresistível. E com esse poder, ele defenderá a si mesmo e ao seu Mais Alto Decreto.)",
  ui_story_1012_10121401_203_dialog_content = "(Caelestitas nunca foram capazes de lutar contra isso, desde que surgiram.)",
  ui_story_1012_10121401_204_dialog_content = "(É uma restrição inata em toda a raça celestita.)",
  ui_story_1012_10121401_205_dialog_content = "...",
  ui_story_1012_10121401_206_dialog_content = "Desculpe a todos, eu...",
  ui_story_1012_10121401_207_dialog_content = "Ok, quem está fazendo com todos os pensamentos negativos?",
  ui_story_1012_10121401_208_dialog_content = "!!!",
  ui_story_1012_10121401_209_dialog_content = "Vice?",
  ui_story_1012_10121401_210_dialog_content = "Esses caras estão sendo meio irritantes, hein?",
  ui_story_1012_10121401_211_dialog_content = "Você pode querer ficar de lado, estou apenas pegando o jeito desses novos brinquedos. Não posso prometer que você estará seguro.",
  ui_story_1012_10121401_212_dialog_content = "Vice, é mesmo você!!!",
  ui_story_1012_10121401_213_dialog_content = "Você... você está acordado? Mas como?",
  ui_story_1012_10121401_214_dialog_content = "O que há com todas as perguntas? Como eu deveria saber por onde começar?",
  ui_story_1012_10121401_215_dialog_content = "Vamos começar com os trabalhos fáceis. Esses caras lá na frente – mate-os, sim?",
  ui_story_1012_10121401_216_dialog_content = "Sim!",
  ui_story_1012_10121401_217_dialog_content = "Então o que estamos esperando?",
  ui_story_1012_10121401_218_dialog_content = "PlayerName, estou ao seu comando.",
  ui_story_1012_10121402_1_dialog_content = "Ok, seu par se divertiu. Acaba aqui!",
  ui_story_1012_10121402_2_dialog_content = "Você primeiro, grandão!",
  ui_story_1012_10121402_3_dialog_content = "Zumbido...",
  ui_story_1012_10121402_4_dialog_content = "Deveria ter aprendido a se esquivar.",
  ui_story_1012_10121402_5_dialog_content = "Nenhuma defesa é forte o suficiente para resistir às minhas flechas!",
  ui_story_1012_10121402_6_dialog_content = "Vice! Atenção!",
  ui_story_1012_10121402_7_dialog_content = "Sim, sim, eu sei. À minha direita, certo?",
  ui_story_1012_10121402_8_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_1012_10121402_9_dialog_content = "Hmm... Como você sabia?",
  ui_story_1012_10121402_10_dialog_content = "E agora só resta um, o que resta é fácil.",
  ui_story_1012_10121402_11_dialog_content = "Quantas flechas você pode tomar? Vamos descobrir!",
  ui_story_1012_10121402_12_dialog_content = "Zumbido...",
  ui_story_1012_10121402_13_dialog_content = "Sim! Conseguimos, ambos os Guardiões caíram.",
  ui_story_1012_10121402_14_dialog_content = "Vice, Fantástico!!!",
  ui_story_1012_10121402_15_dialog_content = "Puff... eles eram meio duros.",
  ui_story_1012_10121402_16_dialog_content = "Eu não poderia tomá-los se não fosse por todas essas mudanças no meu físico.",
  ui_story_1012_10121402_17_dialog_content = "Então, como você está aqui? Achei que esse espaço mental só estivesse aberto aos celestitas.",
  ui_story_1012_10121402_18_dialog_content = "Ou talvez... você não é realmente Vice? Você é apenas uma invenção minha...",
  ui_story_1012_10121402_19_dialog_content = "Claro que sou real!",
  ui_story_1012_10121402_20_dialog_content = "Você acha que é algum tipo de super-herói capaz de criar vícios toda vez que precisar de uma mão?",
  ui_story_1012_10121402_21_dialog_content = "Eu acho que não. Mas então como é que você está aqui? Não faz sentido.",
  ui_story_1012_10121402_22_dialog_content = "Ok, vou simplificar...",
  ui_story_1012_10121402_23_dialog_content = "Acordei do coma e imediatamente tive a sensação de que você precisava de mim.",
  ui_story_1012_10121402_24_dialog_content = "Hã?",
  ui_story_1012_10121402_25_dialog_content = "Eu sei, também não consigo explicar. Era como se nossas consciências estivessem de alguma forma ligadas.",
  ui_story_1012_10121402_26_dialog_content = "Eu podia sentir o quão preocupado você estava. E eu sabia onde você estava.",
  ui_story_1012_10121402_27_dialog_content = "Quando te encontrei e te toquei, minha consciência acabou aqui, como se tivesse sido puxada.",
  ui_story_1012_10121402_28_dialog_content = "Você sabe o resto.",
  ui_story_1012_10121402_29_dialog_content = "Nossas consciências estavam ligadas?",
  ui_story_1012_10121402_30_dialog_content = "Também não sei como aconteceu.",
  ui_story_1012_10121402_31_dialog_content = "Mas podemos acertar os detalhes depois!",
  ui_story_1012_10121402_32_dialog_content = "Carleen disse algo sobre você precisar ativar alguma arma definitiva na torre, certo?",
  ui_story_1012_10121402_33_dialog_content = "Então vamos indo!",
  ui_story_1012_10121402_34_dialog_content = "Sim você está certo!",
  ui_story_1012_10121402_35_dialog_content = "Precisamos apreender a Autorização do Anel Principal. Está em algum lugar neste espaço?",
  ui_story_1012_10121402_36_option_content = "Aumento de Força",
  ui_story_1012_10121402_37_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_1012_10121402_38_dialog_content = "Ah! O que é isso...?",
  ui_story_1012_10121402_39_dialog_content = "(Minha consciência se expandiu para preencher todos os lugares.)",
  ui_story_1012_10121402_40_dialog_content = "(Nós somos um...)",
  ui_story_1012_10121402_41_dialog_content = "(Senti uma sensação de paz que nunca havia experimentado antes. Era como se...)",
  ui_story_1012_10121402_42_dialog_content = "(Como se eu estivesse flutuando em um céu infinito.)",
  ui_story_1012_10121402_43_dialog_content = "(Nada poderia me segurar. Todas as criações estavam aos meus pés.)",
  ui_story_1012_10121402_44_dialog_content = "Funcionou? Você encontrou algo?",
  ui_story_1012_10121402_45_dialog_content = "Não pense assim. Não há nada aqui, apenas nós e esses dois Guardiões surrados.",
  ui_story_1012_10121402_46_dialog_content = "Mas, para ser honesto, nem tenho certeza se sei o que estou procurando.",
  ui_story_1012_10121402_47_dialog_content = "Eu gostaria que o Neural Aux estivesse aqui.",
  ui_story_1012_10121402_48_dialog_content = "E como posso ser útil?",
  ui_story_1012_10121402_49_dialog_content = "Uau!",
  ui_story_1012_10121402_50_dialog_content = "Você é real?",
  ui_story_1012_10121402_51_dialog_content = "Por que você não respondeu quando eu precisei de você mais cedo?",
  ui_story_1012_10121402_52_dialog_content = "Porque eu não tinha permissão para tocar no Core Ring.",
  ui_story_1012_10121402_53_dialog_content = "Então, como é que você pode agora?",
  ui_story_1012_10121402_54_dialog_content = "Porque faz parte do Decreto Supremo.",
  ui_story_1012_10121402_55_dialog_content = "O Decreto Supremo solicitou que Aux Neural aparecesse aqui. E eu segui ordens.",
  ui_story_1012_10121402_56_dialog_content = "O mais alto decreto?",
  ui_story_1012_10121402_57_dialog_content = "Eu pensei que era eu quem queria você aqui?",
  ui_story_1012_10121402_58_dialog_content = "Correto.",
  ui_story_1012_10121402_59_dialog_content = "Você, atualmente, é o Decreto Supremo.",
  ui_story_1012_10121402_60_dialog_content = "O quê?!",
  ui_story_1012_10121402_61_dialog_content = "Sua consciência se fundiu com o Anel Central.",
  ui_story_1012_10121402_62_dialog_content = "O Anel Central é o portador do Decreto Mais Alto. E assim, você é o Decreto Supremo.",
  ui_story_1012_10121402_63_dialog_content = "Seus comandos devem ser seguidos, seus desejos realizados.",
  ui_story_1012_10121402_64_dialog_content = "Então, como posso ser útil?",
  ui_story_1012_10121402_65_dialog_content = "Espere, o Mais Alto Decreto tem me obstruído, mas agora... Eu sou o Mais Alto Decreto?",
  ui_story_1012_10121402_66_dialog_content = "Certo, então... quero ativar o Acorde da Lei.",
  ui_story_1012_10121402_67_dialog_content = "Comandos recebidos. Iniciando o Acorde da Lei.",
  ui_story_1012_10121402_68_dialog_content = "Insira os parâmetros de segmentação e a Lei que você deseja aplicar.",
  ui_story_1012_10121402_69_dialog_content = "Eh??? O que é tudo isso?",
  ui_story_1012_10121402_70_dialog_content = "Acorde da Lei é uma arma de precisão.",
  ui_story_1012_10121402_71_dialog_content = "Seu uso requer informações específicas de tempo e alvo.",
  ui_story_1012_10121402_72_dialog_content = "Isso é essencial para que os resultados correspondam às expectativas.",
  ui_story_1012_10121402_73_dialog_content = "Mas como vou saber o que colocar?",
  ui_story_1012_10121402_74_dialog_content = "Esses números são pares? Eu não posso lê-los!",
  ui_story_1012_10121402_75_dialog_content = "Este é um passo necessário. Insira os parâmetros de segmentação e a Lei que você deseja aplicar.",
  ui_story_1012_10121402_76_dialog_content = "Apenas... ataque todos os Eclipsites perto do Obelisco do Retorno, ok?",
  ui_story_1012_10121402_77_dialog_content = "Desculpe, seu pedido é muito vago. Acorde da Lei é uma arma de precisão.",
  ui_story_1012_10121402_78_dialog_content = "Então o que eu devo fazer!?",
  ui_story_1012_10121402_79_dialog_content = "Certamente você não vai me impedir de usá-lo agora, quando precisamos dele?",
  ui_story_1012_10121402_80_dialog_content = "Parâmetros existentes foram encontrados e podem ser usados para inicialização.",
  ui_story_1012_10121402_81_dialog_content = "Você deseja continuar?",
  ui_story_1012_10121402_82_dialog_content = "Parâmetros existentes?",
  ui_story_1012_10121402_83_dialog_content = "Alerta: Eclipsitos não registrados estão entrando no Obelisco do Retorno.",
  ui_story_1012_10121402_84_dialog_content = "Muitos para contar com precisão.",
  ui_story_1012_10121402_85_dialog_content = "Oh não! Vamos perder a batalha lá fora.",
  ui_story_1012_10121402_86_dialog_content = "Não tenho mais tempo a perder.",
  ui_story_1012_10121402_87_dialog_content = "Neural Aux, você pode nos dizer quem inseriu esses parâmetros?",
  ui_story_1012_10121402_88_dialog_content = "Claro.",
  ui_story_1012_10121402_89_dialog_content = "Alguém que fez login como \"Francisco\".",
  ui_story_1012_10121402_90_dialog_content = "Então era ele.",
  ui_story_1012_10121402_91_dialog_content = "Alerta: Eclipsitos não registrados estão entrando no Obelisco do Retorno.",
  ui_story_1012_10121402_92_dialog_content = "Demais para contar...",
  ui_story_1012_10121402_93_dialog_content = "Quem era seu alvo!?",
  ui_story_1012_10121402_94_dialog_content = "Só preciso saber de uma coisa, quem Francisco usou o Acorde da Lei para atacar?",
  ui_story_1012_10121402_95_dialog_content = "Verificando os registros de dados...",
  ui_story_1012_10121402_96_dialog_content = "Confirmado. Último alvo: Eclipses.",
  ui_story_1012_10121402_97_dialog_content = "Entendi.",
  ui_story_1012_10121402_98_dialog_content = "(Mestre Francis, posso confiar em você?)",
  ui_story_1012_10121402_99_dialog_content = "Neural Aux, lance o Acorde da Lei usando os parâmetros existentes!",
  ui_story_1012_10121402_100_dialog_content = "Cópia de.",
  ui_story_1012_10121402_101_dialog_content = "Inicializando parâmetros de lançamento de dados históricos.",
  ui_story_1012_10121402_102_dialog_content = "Alvo de configuração: Eclipses.",
  ui_story_1012_10121402_103_dialog_content = "Defina o acesso de todos os Eclipsites para: Banido.",
  ui_story_1012_10121402_104_dialog_content = "Definir Lei a ser aplicada para: <color=#FFB400>Evitação permanente do Obelisco do Retorno</color>",
  ui_story_1012_10121402_105_dialog_content = "Inicialização concluída.",
  ui_story_1012_10121402_106_dialog_content = "Lançamento do Acorde da Lei.",
  ui_story_1012_10121402_107_dialog_content = "O que está acontecendo?",
  ui_story_1012_10121402_108_dialog_content = "A torre inteira está brilhando!",
  ui_story_1012_10121402_109_dialog_content = "É amanhecer. Nós conseguimos.",
  ui_story_1012_10121402_110_dialog_content = "Haha! Eu sabia que ele poderia fazer isso!",
  ui_story_1012_10121402_111_dialog_content = "Movam-se, todos. Vamos encontrar um bom ponto de vista.",
  ui_story_1012_10121402_112_dialog_content = "Em algum lugar onde podemos curtir o show.",
  ui_story_1012_10121402_113_dialog_content = "Ei, qual é o problema?",
  ui_story_1012_10121402_114_dialog_content = "O que a torre está fazendo?",
  ui_story_1012_10121402_115_dialog_content = "Com certeza não pode ser...",
  ui_story_1012_10121402_116_dialog_content = "Uh-oh...",
  ui_story_1012_10121402_117_dialog_content = "...",
  ui_story_1012_10121402_118_dialog_content = "Ahhh...",
  ui_story_1012_10121402_119_dialog_content = "Por que todos os Eclipses pararam?",
  ui_story_1012_10121402_120_dialog_content = "Não caia para trás! Mantenha o ataque!",
  ui_story_1012_10121402_121_dialog_content = "O inimigo não pode aguentar muito mais tempo!",
  ui_story_1012_10121402_122_dialog_content = "Ahhh...",
  ui_story_1012_10121402_123_dialog_content = "Droga!",
  ui_story_1012_10121402_124_dialog_content = "Lord Figerald, estes...",
  ui_story_1012_10121402_125_dialog_content = "Er... ah...",
  ui_story_1012_10121402_126_dialog_content = "Senhor... Senhor Figerald?",
  ui_story_1012_10121402_127_dialog_content = "Como isso pode ser...",
  ui_story_1012_10121402_128_dialog_content = "Lord Figerald, terminamos de lutar?",
  ui_story_1012_10121402_129_dialog_content = "...",
  ui_story_1012_10121402_130_dialog_content = "Retiro. Todos recuam.",
  ui_story_1012_10121402_131_dialog_content = "Mas por que...?",
  ui_story_1012_10121402_132_dialog_content = "Porque eu disse! Retiro, entendeu?",
  ui_story_1012_10121402_133_dialog_content = "Sim, meu Senhor.",
  ui_story_1012_10121402_134_dialog_content = "Apenas recue. É tudo o que podemos fazer...",
  ui_story_1012_10121402_135_dialog_content = "Perdi todo o desejo de atacar...",
  ui_story_1012_10121402_136_dialog_content = "Minha mente continua me dizendo para cair para trás.",
  ui_story_1012_10121402_137_dialog_content = "E não importa o que eu faça... não posso derrotar minha própria mente.",
  ui_story_1012_10121402_138_dialog_content = "Eles estão caindo para trás. Os Eclipsitas, eles estão recuando!",
  ui_story_1012_10121402_139_dialog_content = "Esquisito. Não faz sentido. Por que eles estão desistindo, justamente quando estavam prestes a vencer?",
  ui_story_1012_10121402_140_dialog_content = "Tem alguma coisa a ver com aquela luz da Torre Branca?",
  ui_story_1012_10121402_141_dialog_content = "Nós vamos perguntar PlayerName mais tarde, ele saberá.",
  ui_story_1012_10121402_142_dialog_content = "Ahh. Essa batalha com certeza tirou isso de mim. Talvez eu pudesse simplesmente deitar na grama aqui.",
  ui_story_1012_10121402_143_dialog_content = "Não deveríamos estar prontos para outro ataque?",
  ui_story_1012_10121402_144_dialog_content = "Eles ainda têm os números para dificultar as coisas se nos cercarem.",
  ui_story_1012_10121402_145_dialog_content = "Relaxar. A melhor chance deles era tomar a torre antes que todos os exércitos chegassem aqui.",
  ui_story_1012_10121402_146_dialog_content = "Eles serão apenas bucha de canhão se ficarem por aqui, e eles não são tão estúpidos.",
  ui_story_1012_10121402_147_dialog_content = "Obrigado pela lição, Grande Marechal.",
  ui_story_1012_10121402_148_dialog_content = "Aproveite para descansar enquanto pode.",
  ui_story_1012_10121402_149_dialog_content = "Porque se não me engano, o que vem a seguir vai fazer o combate parecer relaxante.",
  ui_story_1012_10121402_150_dialog_content = "Nós... Nós conseguimos!",
  ui_story_1012_10121402_151_dialog_content = "Nós fizemos? O que está acontecendo lá fora?",
  ui_story_1012_10121402_152_dialog_content = "Todos os Eclipsitas recuaram.",
  ui_story_1012_10121402_153_dialog_content = "Parece que eles tiveram que obedecer a lei que aplicamos—",
  ui_story_1012_10121402_154_dialog_content = "\"Evitação Permanente do Obelisco do Retorno.\"",
  ui_story_1012_10121402_155_dialog_content = "Você fez os Eclipsitas obedecerem a uma lei que você estabeleceu?",
  ui_story_1012_10121402_156_dialog_content = "Isso é inacreditavel!",
  ui_story_1012_10121402_157_dialog_content = "Eu posso sentir o Acorde da Lei trabalhando. É realmente uma arma adequada para os celestitas.",
  ui_story_1012_10121402_158_dialog_content = "Não usa força. Apenas planta uma certa ideia na mente do inimigo.",
  ui_story_1012_10121402_159_dialog_content = "Isso muda a mente das pessoas e evita toda a violência.",
  ui_story_1012_10121402_160_dialog_content = "Esse tipo de poder... é assustador.",
  ui_story_1012_10121402_161_dialog_content = "Ei, qual é o problema?",
  ui_story_1012_10121402_162_dialog_content = "Este espaço mental está começando a se tornar instável.",
  ui_story_1012_10121402_163_dialog_content = "O Obelisco do Retorno está ficando sem energia.",
  ui_story_1012_10121402_164_dialog_content = "Muitos componentes de uso único foram danificados pelo lançamento do Chord of the Law e precisam ser substituídos com urgência.",
  ui_story_1012_10121402_165_dialog_content = "Procuro pessoal de manutenção...",
  ui_story_1012_10121402_166_dialog_content = "Pesquisa sem sucesso.",
  ui_story_1012_10121402_167_dialog_content = "Então está com pouca energia.",
  ui_story_1012_10121402_168_dialog_content = "Acho que foi sorte ter durado o suficiente para usar o Acorde da Lei.",
  ui_story_1012_10121402_169_dialog_content = "Se não tivesse... Detesto pensar onde estaríamos agora.",
  ui_story_1012_10121402_170_dialog_content = "Energia insuficiente para manter as operações.",
  ui_story_1012_10121402_171_dialog_content = "O Obelisco do Retorno em breve entrará em silêncio.",
  ui_story_1012_10121402_172_dialog_content = "Eh? Silêncio? Você quer dizer?",
  ui_story_1012_10121402_173_dialog_content = "Todos os equipamentos deixarão de funcionar. Nenhuma funcionalidade estará disponível.",
  ui_story_1012_10121402_174_dialog_content = "Será ainda mais silencioso do que antes da sua chegada.",
  ui_story_1012_10121402_175_dialog_content = "Entendi.",
  ui_story_1012_10121402_176_dialog_content = "Espere, Neural Aux, você não quer dizer que você...",
  ui_story_1012_10121402_177_dialog_content = "Eu faço. Não poderei mais servir aos celestitas.",
  ui_story_1012_10121402_178_dialog_content = "...",
  ui_story_1012_10121402_179_dialog_content = "Mas eu tenho uma tarefa final para completar.",
  ui_story_1012_10121402_180_dialog_content = "Antes que o silêncio caia, devo passar uma mensagem do Mestre Francis.",
  ui_story_1012_10121402_181_dialog_content = "Mestre Francisco?",
  ui_story_1012_10121402_182_dialog_content = "\"Para você, companheiro celestita...\"",
  ui_story_1012_10121402_183_dialog_content = "\"Optei por transmitir esta mensagem apenas no último momento.\"",
  ui_story_1012_10121402_184_dialog_content = "\"Eu não sou de desgraças e tristezas. Celebrações de vitórias são mais meu estilo.\"",
  ui_story_1012_10121402_185_dialog_content = "\"E apenas saber que alguém está ouvindo esta mensagem me anima.\"",
  ui_story_1012_10121402_186_dialog_content = "\"Que ideia bizarra. Pensar que alguém muito distante, alguém que ainda nem existe, vai realizar meu desejo.\"",
  ui_story_1012_10121402_187_dialog_content = "\"Talvez seja porque estamos no mesmo caminho. E que estrada raramente trilhada.\"",
  ui_story_1012_10121402_188_dialog_content = "Estamos no mesmo caminho? Como?",
  ui_story_1012_10121402_189_dialog_content = "\"Você pode não entender completamente o que aconteceu. Você pode até pensar que teve sorte.\"",
  ui_story_1012_10121402_190_dialog_content = "\"Mas o que eu quero dizer é o seguinte: lembre-se, tudo acontece por uma razão.\"",
  ui_story_1012_10121402_191_dialog_content = "\"A energia falhou neste exato momento porque a torre reteve apenas o suficiente para lançar o Acorde da Lei.\"",
  ui_story_1012_10121402_192_dialog_content = "\"Foi meu presente para você.\"",
  ui_story_1012_10121402_193_dialog_content = "Presente!?",
  ui_story_1012_10121402_194_dialog_content = "\"Um presente que o ajudou em sua luta com os Eclipsites.\"",
  ui_story_1012_10121402_195_dialog_content = "\"Um presente que o ajudou a se libertar de sua <color=#FFB400>inato</color> restrições.\"",
  ui_story_1012_10121402_196_dialog_content = "!!!",
  ui_story_1012_10121402_197_dialog_content = "\"Está na hora.\"",
  ui_story_1012_10121402_198_dialog_content = "\"Então, finalmente, eu agradeço por seguir este caminho.\"",
  ui_story_1012_10121402_199_dialog_content = "\"O passado já passou. O restante permanecerá...\"",
  ui_story_1012_10121402_200_dialog_content = "\"Adeus, Celestita.\"",
  ui_story_1012_10121501_1_dialog_content = "Ah, que alívio...",
  ui_story_1012_10121501_2_dialog_content = "Eraveil, assim como eu me lembro.",
  ui_story_1012_10121501_3_dialog_content = "Sempre parece muito mais natural quando está em paz.",
  ui_story_1012_10121501_4_dialog_content = "Carleen, você parece acabado. Aqui, pegue meu braço.",
  ui_story_1012_10121501_5_dialog_content = "Ah, eu não quero ser nenhum problema...",
  ui_story_1012_10121501_6_dialog_content = "Silêncio. PlayerName me contou sobre você me carregando enquanto eu estava com frio.",
  ui_story_1012_10121501_7_dialog_content = "Agora é hora de eu retribuir o favor!",
  ui_story_1012_10121501_8_dialog_content = "...",
  ui_story_1012_10121501_9_dialog_content = "Está bem então.",
  ui_story_1012_10121501_10_dialog_content = "Finalmente, os heróis emergem!",
  ui_story_1012_10121501_11_dialog_content = "Heróis? Você está tirando sarro de mim?",
  ui_story_1012_10121501_12_dialog_content = "Haha, claro que não! Pense nisso – você mudou o rumo desta enorme batalha.",
  ui_story_1012_10121501_13_dialog_content = "Uma batalha que o Grande Marechal de Illumina e a Rainha do Norte não poderiam vencer.",
  ui_story_1012_10121501_14_dialog_content = "Mas... não fui eu, foi?",
  ui_story_1012_10121501_15_dialog_content = "Tudo que eu fiz foi...",
  ui_story_1012_10121501_16_dialog_content = "Foi meu presente para você.",
  ui_story_1012_10121501_17_dialog_content = "Tudo o que fiz foi terminar o trabalho de outras pessoas.",
  ui_story_1012_10121501_18_dialog_content = "Modéstia é uma coisa, mas isso está indo longe demais.",
  ui_story_1012_10121501_19_dialog_content = "Haha. Bem, todos nós lutamos muito, certo?",
  ui_story_1012_10121501_20_dialog_content = "Eu não era eu. Fomos nós. Todos nós invertemos as coisas.",
  ui_story_1012_10121501_21_dialog_content = "Hmm... Eu não posso discutir com isso.",
  ui_story_1012_10121501_22_dialog_content = "A vitória é de todos. As palavras de um verdadeiro guerreiro!",
  ui_story_1012_10121501_23_dialog_content = "Há, sim! A vitória é de todos.",
  ui_story_1012_10121501_24_dialog_content = "Eu gosto do seu jeito de colocar, Reinhardt.",
  ui_story_1012_10121501_25_dialog_content = "Mas lembre-se, você ainda é especial.",
  ui_story_1012_10121501_26_dialog_content = "Nosso ponto de partida, nossa chave, nossa bandeira. Aquele que traz a mudança.",
  ui_story_1012_10121501_27_dialog_content = "E isso não é um elogio, mas um aviso.",
  ui_story_1012_10121501_28_dialog_content = "Nunca se esqueça, ser especial é uma coisa temível.",
  ui_story_1012_10121501_29_dialog_content = "Não.",
  ui_story_1012_10121501_30_dialog_content = "Você está de volta.",
  ui_story_1012_10121501_31_dialog_content = "Vossa Majestade!",
  ui_story_1012_10121501_32_dialog_content = "Você está sempre tão calmo, seja agora ou no campo de batalha.",
  ui_story_1012_10121501_33_dialog_content = "Embora eu suponha que você viu o resultado com antecedência.",
  ui_story_1012_10121501_34_dialog_content = "...",
  ui_story_1012_10121501_35_dialog_content = "Na verdade, desta vez não.",
  ui_story_1012_10121501_36_dialog_content = "Ah?",
  ui_story_1012_10121501_37_dialog_content = "Eu não via um futuro em que você virasse a maré da batalha.",
  ui_story_1012_10121501_38_dialog_content = "Eu só vi você ir fazer alguma coisa.",
  ui_story_1012_10121501_39_dialog_content = "Então você...",
  ui_story_1012_10121501_40_dialog_content = "...",
  ui_story_1012_10121501_41_dialog_content = "E eu tinha fé que você teria sucesso.",
  ui_story_1012_10121501_42_dialog_content = "Vossa Majestade...",
  ui_story_1012_10121501_43_dialog_content = "Espero não ter falhado com você!",
  ui_story_1012_10121501_44_dialog_content = "Olhe para Eraveil. Aí está a sua resposta.",
  ui_story_1012_10121501_45_dialog_content = "Ainda há uma pergunta para você responder, PlayerName.",
  ui_story_1012_10121501_46_dialog_content = "Apenas como você fez isso?",
  ui_story_1012_10121501_47_dialog_content = "Os Eclipsitas de repente abandonaram seu ataque à torre e fugiram, com o rabo entre as pernas.",
  ui_story_1012_10121501_48_dialog_content = "Você disse algo sobre uma \"arma suprema\", mas não vi nenhuma sendo usada.",
  ui_story_1012_10121501_49_dialog_content = "Honestamente, eu mesmo não tenho muita certeza.",
  ui_story_1012_10121501_50_dialog_content = "Parecia mais uma arma mental.",
  ui_story_1012_10121501_51_dialog_content = "Não atacou o inimigo fisicamente. Ele atacou suas mentes.",
  ui_story_1012_10121501_52_dialog_content = "Ele inseriu uma ordem em suas cabeças: afastem-se do Obelisco do Retorno. E eles fizeram.",
  ui_story_1012_10121501_53_dialog_content = "Controle mental? Eu nunca soube que tais armas eram possíveis.",
  ui_story_1012_10121501_54_dialog_content = "Eu sei. É estranho para mim também.",
  ui_story_1012_10121501_55_dialog_content = "Isso é significativo. O que uma arma dessas poderia significar para o mundo? Como funciona e que poder tem?",
  ui_story_1012_10121501_56_dialog_content = "Isso pode ser ainda pior do que o Eclipse.",
  ui_story_1012_10121501_57_dialog_content = "Bem, sobre isso... Acho que não precisamos nos preocupar muito.",
  ui_story_1012_10121501_58_dialog_content = "A arma se foi.",
  ui_story_1012_10121501_59_dialog_content = "O quê?",
  ui_story_1012_10121501_60_dialog_content = "A torre só reteve a energia para ativar a arma uma única vez.",
  ui_story_1012_10121501_61_dialog_content = "E agora tanto a arma quanto a própria torre caíram em silêncio.",
  ui_story_1012_10121501_62_dialog_content = "Eles nunca pertenceram ao nosso tempo. Eles apenas ficaram aqui, para cumprir um desejo.",
  ui_story_1012_10121501_63_dialog_content = "E quando a arma disparou, eles retornaram ao seu estado original, sua tarefa concluída.",
  ui_story_1012_10121501_64_dialog_content = "Agora eles permanecerão aqui, como um testamento silencioso.",
  ui_story_1012_10121501_65_dialog_content = "Entendi.",
  ui_story_1012_10121501_66_dialog_content = "É estranho. Eu quase sinto uma afinidade por essa arma.",
  ui_story_1012_10121501_67_dialog_content = "Talvez porque não era apenas uma arma.",
  ui_story_1012_10121501_68_dialog_content = "Era um <color=#FFB400>Presente</color>.",
  ui_story_1012_10121501_69_dialog_content = "<color=#e8d9bb>Rumble... Rumble... Rumble...</color>",
  ui_story_1012_10121501_70_dialog_content = "Haa... haa... finalmente, parou.",
  ui_story_1012_10121501_71_dialog_content = "Então isso é... Eraveil?",
  ui_story_1012_10121501_72_dialog_content = "Agora, por que Lepidoz veio para Eraveil?",
  ui_story_1012_10121501_73_dialog_content = "Espera aí, desde quando Eraveil tem uma torre assim?",
  ui_story_1012_10121501_74_dialog_content = "Ah-ha, temos um recém-chegado de aparência duvidosa, eu vejo.",
  ui_story_1012_10121501_75_dialog_content = "Não esperava que a Rediesel Wrench aparecesse tão cedo.",
  ui_story_1012_10121501_76_dialog_content = "O Grande Marechal de Illumina!",
  ui_story_1012_10121501_77_dialog_content = "O que você está fazendo em Eraveil?",
  ui_story_1012_10121501_78_dialog_content = "Acredite ou não, acabamos de ter uma batalha.",
  ui_story_1012_10121501_79_dialog_content = "Uma batalha?",
  ui_story_1012_10121501_80_dialog_content = "*Cheira...*",
  ui_story_1012_10121501_81_dialog_content = "Certo o suficiente, eu podia sentir o cheiro de combate.",
  ui_story_1012_10121501_82_dialog_content = "Mas realmente, uma batalha?",
  ui_story_1012_10121501_83_dialog_content = "O que, você não acredita em nós?",
  ui_story_1012_10121501_84_dialog_content = "Bem, você sabe o que dizem sobre confiar na Illumina...",
  ui_story_1012_10121501_85_dialog_content = "Mas aqui é bem animado. Tantas figuras famosas reunidas em um só lugar.",
  ui_story_1012_10121501_86_dialog_content = "A Rainha do Norte e eu viemos lutar.",
  ui_story_1012_10121501_87_dialog_content = "Você vê, quando PlayerName dá uma festa, todo mundo vem.",
  ui_story_1012_10121501_88_dialog_content = "Então temos você, a Rainha do Norte, e... quem é essa?",
  ui_story_1012_10121501_89_dialog_content = "Quem?",
  ui_story_1012_10121501_90_dialog_content = "O de aparência altiva atrás de você.",
  ui_story_1012_10121501_91_dialog_content = "!!!",
  ui_story_1012_10121501_92_dialog_content = "...",
  ui_story_1012_10121501_93_dialog_content = "Victoria! Quando você...",
  ui_story_1012_10121501_94_dialog_content = "Não se preocupe comigo.",
  ui_story_1012_10121501_95_dialog_content = "Só estou aqui para curtir o show.",
  ui_story_1012_10121501_96_dialog_content = "Nem acredito que você apareceu.",
  ui_story_1012_10121501_97_dialog_content = "<color=#e8d9bb>Pise, pise, pise</color>",
  ui_story_1012_10121501_98_dialog_content = "Alto!",
  ui_story_1012_10121501_99_dialog_content = "Forme um perímetro!",
  ui_story_1012_10121501_100_dialog_content = "Sim, senhor!",
  ui_story_1012_10121501_101_dialog_content = "Esien, finalmente.",
  ui_story_1012_10121501_102_dialog_content = "Tradicionalmente, porém, os reforços chegam durante a batalha.",
  ui_story_1012_10121501_103_dialog_content = "Perdoe-me, Grande Marechal, mas não fomos enviados como reforços.",
  ui_story_1012_10121501_104_dialog_content = "Então você está aqui... por quê?",
  ui_story_1012_10121501_105_dialog_content = "Sinto muito, Grande Marechal. Os detalhes da missão são revelados com base na necessidade de saber, e você não precisa saber.",
  ui_story_1012_10121501_106_dialog_content = "Eu não preciso saber!?",
  ui_story_1012_10121501_107_dialog_content = "Da última vez que verifiquei, ainda sou o Grande Marechal da Illumina, não sou?",
  ui_story_1012_10121501_108_dialog_content = "Você tem essa posição militar, sim.",
  ui_story_1012_10121501_109_dialog_content = "Mas você não tem autoridade fora do campo de batalha.",
  ui_story_1012_10121501_110_dialog_content = "...",
  ui_story_1012_10121501_111_dialog_content = "Agora eu entendi. É o Comitê de novo, não é?",
  ui_story_1012_10121501_112_dialog_content = "Se me der licença.",
  ui_story_1012_10121501_113_dialog_content = "Grande Marechal... Eles...",
  ui_story_1012_10121501_114_dialog_content = "Não importa eles.",
  ui_story_1012_10121501_115_dialog_content = "Os políticos detêm mais poder do que o Grande Marechal no mundo real.",
  ui_story_1012_10121501_116_dialog_content = "Devo tomar nota disso?",
  ui_story_1012_10121501_117_dialog_content = "Não. Estou apenas choramingando.",
  ui_story_1012_10121501_118_dialog_content = "Bem ali. Outro esquadrão está vindo por aqui.",
  ui_story_1012_10121501_119_dialog_content = "Aqueles abutres... Eles não têm interesse em batalhas, mas estão dispostos a lutar uns contra os outros até a morte por alguns cadáveres de troféus.",
  ui_story_1012_10121501_120_dialog_content = "Meu Senhor, a Illumina está em movimento.",
  ui_story_1012_10121501_121_dialog_content = "Vamos apenas sentar aqui e esperar?",
  ui_story_1012_10121501_122_dialog_content = "Tenha paciência.",
  ui_story_1012_10121501_123_dialog_content = "Este é um assunto grave. Seria sábio considerar as ramificações antes de agir.",
  ui_story_1012_10121501_124_dialog_content = "O que Lumopolis precisa é manter a ordem, não um prego que sobressaia.",
  ui_story_1012_10121501_125_dialog_content = "Sim, senhor!",
  ui_story_1012_10121501_126_dialog_content = "eu sabia senhor Schwartz tinha chegado assim que vi todas essas pessoas inundadas.",
  ui_story_1012_10121501_127_dialog_content = "Lumopolis com certeza sabe como fazer uma entrada tardia.",
  ui_story_1012_10121501_128_dialog_content = "Reinhardt, Illumina e Lumopolis fazem as coisas de forma diferente. Por que o sarcasmo?",
  ui_story_1012_10121501_129_dialog_content = "Poupe seu fôlego para o assunto em questão.",
  ui_story_1012_10121501_130_dialog_content = "O assunto em questão? Você não sentiu o cheiro da fumaça no ar? Já terminou.",
  ui_story_1012_10121501_131_dialog_content = "Olha, até os mercadores estão aqui. O negócio é o assunto em mãos agora, não é? Hahaha!",
  ui_story_1012_10121501_132_dialog_content = "Os comerciantes têm mais do que lucros em suas mãos.",
  ui_story_1012_10121501_133_dialog_content = "E não sou um simples comerciante.",
  ui_story_1012_10121501_134_dialog_content = "Mas também a sombra que segue Lumopolis, certo?",
  ui_story_1012_10121501_135_dialog_content = "Esse é o nosso modo de vida. Tem mais alguma coisa a dizer, Grande Marechal?",
  ui_story_1012_10121501_136_dialog_content = "O suficiente. Todos sabem que nos reunimos aqui porque todos sentimos a turbulência dos acontecimentos.",
  ui_story_1012_10121501_137_dialog_content = "Devemos estar cientes do que está acontecendo e do que isso pode significar para o futuro.",
  ui_story_1012_10121501_138_dialog_content = "Grande Marechal, faria a gentileza de nos mostrar o caminho?",
  ui_story_1012_10121501_139_dialog_content = "O prazer é meu. Siga-me por favor.",
  ui_story_1012_10121501_140_dialog_content = "Isso é um monte de grandes nomes... O que eles estão planejando fazer?",
  ui_story_1012_10121501_141_dialog_content = "Parece que o despertar do Obelisco do Retorno causou mais preocupações do que imaginávamos.",
  ui_story_1012_10121501_142_dialog_content = "Eles vão querer saber o que exatamente aconteceu aqui, e...",
  ui_story_1012_10121501_143_dialog_content = "Como lidar com esta torre.",
  ui_story_1012_10121501_144_dialog_content = "Lidar... com esta torre...",
  ui_story_1012_10121501_145_dialog_content = "Eu sinto Muito. Eu sei que não soa agradável.",
  ui_story_1012_10121501_146_dialog_content = "Esta torre, deve ser sua.",
  ui_story_1012_10121501_147_dialog_content = "Está bem. Eu entendo.",
  ui_story_1012_10121501_148_dialog_content = "Os sentimentos pessoais devem ser deixados de lado em assuntos que dizem respeito ao mundo.",
  ui_story_1012_10121501_149_dialog_content = "PlayerName...",
  ui_story_1012_10121501_150_dialog_content = "PlayerName! Por que você está parado à margem?",
  ui_story_1012_10121501_151_dialog_content = "Hum... bem...",
  ui_story_1012_10121501_152_dialog_content = "Venha! O Grande Marechal pergunta por você.",
  ui_story_1012_10121501_153_dialog_content = "Pergunta por mim?",
  ui_story_1012_10121501_154_dialog_content = "Sim. Estão todos esperando por você. Vamos!",
  ui_story_1012_10121501_155_dialog_content = "Ah, certo...",
  ui_story_1012_10121501_156_dialog_content = "Espere aí!",
  ui_story_1012_10121501_157_dialog_content = "PlayerName, uma palavra de cautela.",
  ui_story_1012_10121501_158_dialog_content = "O que quer que você diga, não conte a eles sobre a posição que os antigos celestitas assumiram.",
  ui_story_1012_10121501_159_dialog_content = "Grande marechal. PlayerName é aqui.",
  ui_story_1012_10121501_160_dialog_content = "Excelente. o Mestre da Torre está aqui. Agora podemos finalmente começar.",
  ui_story_1012_10121501_161_dialog_content = "Mestre da Torre!?",
  ui_story_1012_10121501_162_dialog_content = "Você é o último dos celestitas e, por toda a lógica, o mestre do Obelisco do Retorno.",
  ui_story_1012_10121501_163_dialog_content = "Tanto a rainha quanto eu insistimos em sua presença nas negociações.",
  ui_story_1012_10121501_164_dialog_content = "Com... todos os governantes?",
  ui_story_1012_10121501_165_dialog_content = "Não há nada a temer. Você participou da Celebração da Noite Branca, não foi?",
  ui_story_1012_10121501_166_dialog_content = "Você tem mais autoridade em assuntos relacionados ao Obelisco do Retorno do que qualquer outra pessoa aqui.",
  ui_story_1012_10121501_167_dialog_content = "Apenas diga o que está em sua mente. Não deixe que a estatura ou posição de ninguém o impeça.",
  ui_story_1012_10121501_168_dialog_content = "Tá bom...",
  ui_story_1012_10121501_169_dialog_content = "Somos nós que ficamos no escuro.",
  ui_story_1012_10121501_170_dialog_content = "Talvez você seja o único que pode nos apontar para o futuro.",
  ui_story_1012_10121501_171_dialog_content = "Em primeiro lugar, como vocês vêem esta Torre?",
  ui_story_1012_10121501_172_dialog_content = "Para nós, sem dúvida, é uma grave ameaça para Lumopolis.",
  ui_story_1012_10121501_173_dialog_content = "Damocles se ativando sozinho... É inédito.",
  ui_story_1012_10121501_174_dialog_content = "Além disso, está apontando em nossa direção, então é necessário destruir a torre.",
  ui_story_1012_10121501_175_dialog_content = "(Damocles se ativando sozinho. Sim, eu vi isso.)",
  ui_story_1012_10121501_176_dialog_content = "Illumina segundos isso.",
  ui_story_1012_10121501_177_dialog_content = "Relíquias antigas em Gannon também soaram o alerta. Foi causado pelos movimentos aqui.",
  ui_story_1012_10121501_178_dialog_content = "Obviamente, o Obelisco do Retorno foi considerado hostil aos construtores de Gannon City.",
  ui_story_1012_10121501_179_dialog_content = "(Isso não é bom. Todos estão me tratando como o inimigo.)",
  ui_story_1012_10121501_180_dialog_content = "Eu concordo.",
  ui_story_1012_10121501_181_dialog_content = "Nos tempos antigos, o Obelisco do Retorno era algo que os Aurorianos temiam.",
  ui_story_1012_10121501_182_dialog_content = "!!!",
  ui_story_1012_10121501_183_dialog_content = "Como estamos todos de acordo, proponho que a destruamos ou enterremos.",
  ui_story_1012_10121501_184_dialog_content = "Algo que não deveria existir deveria desaparecer.",
  ui_story_1012_10121501_185_dialog_content = "De jeito nenhum! Essa é uma torre enorme que você está falando!",
  ui_story_1012_10121501_186_dialog_content = "As relíquias antigas que ela guarda sozinhas podem valer uma quantia enorme de dinheiro!",
  ui_story_1012_10121501_187_dialog_content = "E poderíamos aprender e fazer engenharia reversa de sua tecnologia para ajudar as pessoas!",
  ui_story_1012_10121501_188_dialog_content = "Vocês, royalties, realmente não têm ideia de como a vida é difícil para os plebeus por aí.",
  ui_story_1012_10121501_189_dialog_content = "Não estamos aqui para falar de necessidades civis.",
  ui_story_1012_10121501_190_dialog_content = "Nós, Illumina, também não acreditamos que o Obelisco do Retorno deva ser destruído.",
  ui_story_1012_10121501_191_dialog_content = "Deixando de lado nossos preconceitos e suposições, é uma instalação com grandes valores militares.",
  ui_story_1012_10121501_192_dialog_content = "Devemos estudá-lo, não destruí-lo por medo.",
  ui_story_1012_10121501_193_dialog_content = "Para ser estudado pela Illumina? Que garantia temos de que você colocará os resultados em um bom trabalho?",
  ui_story_1012_10121501_194_dialog_content = "Posso lembrá-lo de que seu histórico está longe de ser impecável?",
  ui_story_1012_10121501_195_dialog_content = "Ei, apenas relaxem, pessoal.",
  ui_story_1012_10121501_196_dialog_content = "Olhe a sua volta. Esta torre é apenas uma pilha de pedras.",
  ui_story_1012_10121501_197_dialog_content = "Não há engenhocas de trabalho nem Lumina fluindo.",
  ui_story_1012_10121501_198_dialog_content = "Você está dizendo que tem medo de algumas pedras?",
  ui_story_1012_10121501_199_dialog_content = "Pedras que serviam a um propósito desconhecido. Quem pode dizer que eles não vão começar a trabalhar de repente?",
  ui_story_1012_10121501_200_dialog_content = "H-Hum...",
  ui_story_1012_10121501_201_dialog_content = "Posso garantir que a energia do Obelisco do Retorno está totalmente esgotada.",
  ui_story_1012_10121501_202_dialog_content = "Assim como o Grande Marechal disse, é apenas uma pilha de pedras agora.",
  ui_story_1012_10121501_203_dialog_content = "Pedras que guardaram um registro de nossas histórias.",
  ui_story_1012_10121501_204_dialog_content = "...",
  ui_story_1012_10121501_205_dialog_content = "Isso é uma grande garantia para você, Caelestite. Tem certeza de que pode fazer essa garantia?",
  ui_story_1012_10121501_206_dialog_content = "Eu...",
  ui_story_1012_10121501_207_dialog_content = "Meu Senhor, posso atestar por ele.",
  ui_story_1012_10121501_208_dialog_content = "Carleen?",
  ui_story_1012_10121501_209_dialog_content = "PlayerName e eu explorei completamente a torre.",
  ui_story_1012_10121501_210_dialog_content = "Posso garantir a ele que a torre não funciona mais.",
  ui_story_1012_10121501_211_dialog_content = "...",
  ui_story_1012_10121501_212_dialog_content = "Ver? Não há necessidade de tensão.",
  ui_story_1012_10121501_213_dialog_content = "Para o mundo de hoje, esta torre não é mais uma ameaça, mas um tesouro de tesouros antigos.",
  ui_story_1012_10121501_214_dialog_content = "Já pertenceu aos celestitas e deve continuar assim.",
  ui_story_1012_10121501_215_dialog_content = "Hum?",
  ui_story_1012_10121501_216_dialog_content = "Eu acredito PlayerName é o legítimo proprietário da torre agora.",
  ui_story_1012_10121501_217_dialog_content = "Precisaremos de sua permissão e aprovação sobre como lidamos com os itens na torre.",
  ui_story_1012_10121501_218_dialog_content = "Tenho certeza PlayerName concordaria com qualquer pesquisa que pudesse beneficiar a todos nós.",
  ui_story_1012_10121501_219_dialog_content = "E PlayerName terá o direito de negar qualquer pesquisa que possa causar danos potenciais.",
  ui_story_1012_10121501_220_dialog_content = "Por favor, deixe-me esclarecer uma coisa primeiro.",
  ui_story_1012_10121501_221_dialog_content = "A Grande Marechal fala por si mesma. Suas opiniões não representam as opiniões da Illumina de forma alguma.",
  ui_story_1012_10121501_222_dialog_content = "Oh? Então, qual é a posição da Illumina sobre isso?",
  ui_story_1012_10121501_223_dialog_content = "Illumina insiste em estudar todas as coisas no Obelisco do Retorno.",
  ui_story_1012_10121501_224_dialog_content = "Não deve pertencer a ninguém.",
  ui_story_1012_10121501_225_dialog_content = "Tsk... Vocês...",
  ui_story_1012_10121501_226_dialog_content = "Eu concordo com Reinhardt.",
  ui_story_1012_10121501_227_dialog_content = "PlayerName é o legítimo proprietário do Obelisco do Retorno.",
  ui_story_1012_10121501_228_dialog_content = "Rainha Bethlehem...",
  ui_story_1012_10121501_229_dialog_content = "Todos nós já lutamos para proteger nossas casas. Não há razão mais digna de respeito do que esta.",
  ui_story_1012_10121501_230_dialog_content = "E os celestitas lutam para proteger este lugar agora, assim como nós.",
  ui_story_1012_10121501_231_dialog_content = "Se a propriedade de sua casa ancestral fosse determinada por outros, então a guerra estava perdida.",
  ui_story_1012_10121501_232_dialog_content = "Tanto os aurorianos quanto os eclipsitas são todos estranhos aos celestitas.",
  ui_story_1012_10121501_233_dialog_content = "Se chamamos os celestitas de nossos aliados, então nós, os aurorianos, devemos respeitar nosso aliado não invadindo Eraveil.",
  ui_story_1012_10121501_234_dialog_content = "Vossa Majestade...",
  ui_story_1012_10121501_235_dialog_content = "Quanto ao Senhor Schwartzas preocupações da empresa, considero-as infundadas.",
  ui_story_1012_10121501_236_dialog_content = "Uma arma não é inerentemente boa ou má. Isso é decidido por quem segura o gatilho.",
  ui_story_1012_10121501_237_dialog_content = "Como todos testemunhamos, PlayerName usou o Obelisco do Retorno para evitar esta guerra.",
  ui_story_1012_10121501_238_dialog_content = "O Caelestita mostrou a todos nós a posição do Obelisco do Retorno.",
  ui_story_1012_10121501_239_dialog_content = "...",
  ui_story_1012_10121501_240_dialog_content = "É raro ver você expressar sua opinião assim, rainha Bethlehem.",
  ui_story_1012_10121501_241_dialog_content = "Quão importante é isso para você?",
  ui_story_1012_10121501_242_dialog_content = "O celestita é um importante aliado dos aurorianos.",
  ui_story_1012_10121501_243_dialog_content = "Entendi.",
  ui_story_1012_10121501_244_dialog_content = "É melhor eu não dizer mais nada, ou alguém vai me achar conservador.",
  ui_story_1012_10121501_245_dialog_content = "A Rainha do Norte fez sua posição, e eu respeito sua decisão.",
  ui_story_1012_10121501_246_dialog_content = "A Lumopolis não mais interferirá em assuntos relacionados ao manuseio do Obelisco do Retorno.",
  ui_story_1012_10121501_247_dialog_content = "O que dizem todos vocês?",
  ui_story_1012_10121501_248_dialog_content = "Se for esse o caso, eu concordo.",
  ui_story_1012_10121501_249_dialog_content = "Agora, isso não é legal? Não tenho outras opiniões!",
  ui_story_1012_10121501_250_dialog_content = "...",
  ui_story_1012_10121501_251_dialog_content = "Deixei clara a posição da Illumina e não comentarei todas as suas decisões.",
  ui_story_1012_10121501_252_dialog_content = "Parece que chegamos a uma conclusão.",
  ui_story_1012_10121501_253_dialog_content = "De qualquer forma, a guerra acabou, e todos nós podemos desfrutar da paz por um pouco mais de tempo...",
  ui_story_1012_10121501_254_dialog_content = "Até que surja a próxima guerra. A paz nunca dura, mas pelo menos podemos tirar o melhor proveito dela.",
  ui_story_1012_10121501_255_dialog_content = "Como por você, PlayerName, parabéns pelo seu troféu.",
  ui_story_1012_10121501_256_dialog_content = "Uma verdadeira casa.",
  ui_story_1012_10121501_257_dialog_content = "...",
  ui_story_1012_10121501_258_dialog_content = "Ehhh...",
  ui_story_1012_10121501_259_dialog_content = "Uma verdadeira casa...",
  ui_story_1012_10121501_260_dialog_content = "Por que você suspira?",
  ui_story_1012_10121501_261_dialog_content = "V-Vossa Majestade?!",
  ui_story_1012_10121501_262_dialog_content = "Por quê você está aqui?",
  ui_story_1012_10121501_263_dialog_content = "Você usa seus problemas em seu rosto.",
  ui_story_1012_10121501_264_dialog_content = "Haha... Nada escapa de você, eu vejo.",
  ui_story_1012_10121501_265_dialog_content = "Hmm...",
  ui_story_1012_10121501_266_dialog_content = "Estou um pouco perdido... só não entendo.",
  ui_story_1012_10121501_267_dialog_content = "Por causa da batalha?",
  ui_story_1012_10121501_268_dialog_content = "Não exatamente. EU...",
  ui_story_1012_10121501_269_dialog_content = "Estou aqui se precisar de alguém para ouvir.",
  ui_story_1012_10121501_270_dialog_content = "Não como a Rainha do Norte, mas apenas eu.",
  ui_story_1012_10121501_271_dialog_content = "Apenas seja você...",
  ui_story_1012_10121501_272_dialog_content = "Obrigado... Eu poderia realmente usar uma pessoa para conversar.",
  ui_story_1012_10121501_273_dialog_content = "Vá em frente. Eu não estou indo a lugar nenhum.",
  ui_story_1012_10121501_274_dialog_content = "Eu... Vimos algo lá embaixo... Sobre a história dos celestitas.",
  ui_story_1012_10121501_275_dialog_content = "Os registros deixados no Obelisco do Retorno são apenas pedaços, mas eu vi...",
  ui_story_1012_10121501_276_dialog_content = "Eu vi como os celestitas lutaram com os eclipsitas...",
  ui_story_1012_10121501_277_dialog_content = "O que significa... Nos tempos antigos, os celestitas podem ter se aliado aos eclipsitas.",
  ui_story_1012_10121501_278_dialog_content = "Os celestitas e eclipsitas?",
  ui_story_1012_10121501_279_dialog_content = "Sim... Eu os experimentei trabalhando juntos.",
  ui_story_1012_10121501_280_dialog_content = "Eu não sei como descrever o que eu senti para você...",
  ui_story_1012_10121501_281_dialog_content = "Não tenho nenhuma prova concreta, mas acredito que realmente aconteceu.",
  ui_story_1012_10121501_282_dialog_content = "Mesmo depois da batalha, eu ainda não consigo me livrar disso... eu...",
  ui_story_1012_10121501_283_dialog_content = "Acho que é mais do que posso lidar.",
  ui_story_1012_10121501_284_dialog_content = "Você tá bem, PlayerName?",
  ui_story_1012_10121501_285_dialog_content = "Só sinto que minha cabeça está prestes a explodir. Lamento não ter algumas dessas coisas para lhe mostrar.",
  ui_story_1012_10121501_286_dialog_content = "O que você viu pode não ser necessariamente toda a verdade. Além disso, não temos registros de uma aliança entre os celestitas e os eclipsitas.",
  ui_story_1012_10121501_287_dialog_content = "Eu prometo a você que vi os celestitas e eclipsitas matando os aurorianos!",
  ui_story_1012_10121501_288_dialog_content = "Esse sentimento... não era uma simples ilusão.",
  ui_story_1012_10121501_289_dialog_content = "Eu queria que fosse uma ilusão... Eu realmente queria.",
  ui_story_1012_10121501_290_dialog_content = "Se fosse verdade, não Novio conhecer? Ele viveu por muito tempo, mas nunca disse nada sobre isso.",
  ui_story_1012_10121501_291_dialog_content = "Sim, e não encontrei nada relacionado ao que vi nos registros históricos a bordo do Soroz.",
  ui_story_1012_10121501_292_dialog_content = "Até onde eu sei, nem Lumopolis nem Illumina tem qualquer evidência disso... Caso contrário...",
  ui_story_1012_10121501_293_dialog_content = "Caso contrário, um \"aliado dos Eclipsitas\" como eu seria sem dúvida... Hehe...",
  ui_story_1012_10121501_294_dialog_content = "Deixe-me dizer exatamente o que encontramos, desde o início...",
  ui_story_1012_10121501_295_dialog_content = "... É isso.",
  ui_story_1012_10121501_296_dialog_content = "...",
  ui_story_1012_10121501_297_dialog_content = "Em primeiro lugar, apesar de tudo o que você viu, os fragmentos estão longe de serem suficientes para chegar a uma conclusão.",
  ui_story_1012_10121501_298_dialog_content = "Em segundo lugar, mesmo que de fato tenha acontecido, deve ser antigo.",
  ui_story_1012_10121501_299_dialog_content = "Na verdade, pode ser tão antigo que até seus ancestrais não sabiam disso.",
  ui_story_1012_10121501_300_dialog_content = "Quer dizer... pode ser anterior à história de Northland?",
  ui_story_1012_10121501_301_dialog_content = "Os aurorianos também têm apenas pedaços de nossa história antiga. A maior parte é realmente desconhecida para nós.",
  ui_story_1012_10121501_302_dialog_content = "No entanto, em quaisquer registros históricos que tenhamos, os celestitas sempre foram amigos dos aurorianos.",
  ui_story_1012_10121501_303_dialog_content = "E nossos dois povos lutaram juntos contra os Eclipsitas. Isso nunca mudou.",
  ui_story_1012_10121501_304_dialog_content = "Seu povo também não foi dizimado pelos Eclipsitas?",
  ui_story_1012_10121501_305_dialog_content = "Sim... É por isso que não consigo entender. Eu só quero saber o que realmente aconteceu.",
  ui_story_1012_10121501_306_dialog_content = "Mas... se os celestitas e eclipsitas realmente...",
  ui_story_1012_10121501_307_dialog_content = "Mesmo que fosse assim, como algo tão distante e antigo afeta você hoje?",
  ui_story_1012_10121501_308_dialog_content = "Estive pensando... Se os celestitas realmente se aliaram aos eclipsitas...",
  ui_story_1012_10121501_309_dialog_content = "Então o que aprendi desde a infância, tudo sobre nossa história e crença... seria tudo mentira.",
  ui_story_1012_10121501_310_dialog_content = "O que meu povo pensaria se visse o que eu vi...?",
  ui_story_1012_10121501_311_dialog_content = "Se isso fosse verdade... Os celestitas... seriam desprezíveis.",
  ui_story_1012_10121501_312_dialog_content = "Embora os celestitas e os aurorianos compartilhem visões diferentes sobre muitas coisas, os celestitas sempre foram conhecidos por defender a paz e abraçar a natureza.",
  ui_story_1012_10121501_313_dialog_content = "Claro, há coisas aqui que ainda temos que entender, mas você...",
  ui_story_1012_10121501_314_dialog_content = "Estive pensando... Só consegui chegar até aqui acreditando nos celestitas. Se o que eu acredito fosse uma mentira...",
  ui_story_1012_10121501_315_dialog_content = "Então... o que isso me faz...?",
  ui_story_1012_10121501_316_dialog_content = "Você é a celestia mais corajosa e resiliente que já conheci, PlayerName.",
  ui_story_1012_10121501_317_dialog_content = "Eh... Minha cabeça vai explodir.",
  ui_story_1012_10121501_318_dialog_content = "PlayerName, se os celestitas realmente fossem aliados dos eclipsitas, você se aliaria aos eclipsitas?",
  ui_story_1012_10121501_319_dialog_content = "O que!? Não! Nunca! Eu vou lutar contra os Eclipsitas, não importa o que aconteça!",
  ui_story_1012_10121501_320_dialog_content = "Eles levaram minha família e machucaram meus amigos. De jeito nenhum eu vou perdoá-los!",
  ui_story_1012_10121501_321_dialog_content = "Sua crença e força são transmitidas por aqueles que vieram antes de você, não são?",
  ui_story_1012_10121501_322_dialog_content = "História é exatamente isso, história. O que é mais importante é você e a bondade e valentia de seu povo.",
  ui_story_1012_10121501_323_dialog_content = "Acho que entendi o que você está tentando dizer... mas acho que vou precisar de um tempo antes de poder aceitar isso... mancha...",
  ui_story_1012_10121501_324_dialog_content = "Você se lembra de como criticou todos os líderes por suas conspirações na Celebração da Noite Branca?",
  ui_story_1012_10121501_325_dialog_content = "Você faria bem em ser sempre essa pessoa.",
  ui_story_1012_10121501_326_dialog_content = "Mas... envergonha muito os celestitas e me faz duvidar de mim mesmo...",
  ui_story_1012_10121501_327_dialog_content = "O que é pior, talvez até meus amigos hesitariam em confiar em mim...",
  ui_story_1012_10121501_328_dialog_content = "Eles me considerariam uma ameaça potencial ao mundo, assim como o que aconteceu lá atrás?",
  ui_story_1012_10121501_329_dialog_content = "Eu... não quero que me olhem com desconfiança... odeio essa sensação...",
  ui_story_1012_10121501_330_dialog_content = "Tanto Lumopolis quanto Illumina têm um passado obscuro, então por que você ainda considera Carleen e Vice como seus melhores amigos?",
  ui_story_1012_10121501_331_dialog_content = "Porque lutamos juntos, confiamos um no outro e contamos um com o outro...",
  ui_story_1012_10121501_332_dialog_content = "Eles quebrariam essa confiança apenas por causa de algo que aconteceu com os celestitas há muito, muito tempo?",
  ui_story_1012_10121501_333_dialog_content = "Definitivamente não!",
  ui_story_1012_10121501_334_dialog_content = "Como você pode ver, esta não é uma pergunta complicada.",
  ui_story_1012_10121501_335_dialog_content = "Tu es PlayerName, um celestita, sim, mas você não representa todo o povo celestita.",
  ui_story_1012_10121501_336_dialog_content = "Mas os celestitas são tudo para mim... Assim como Northland é tudo para você.",
  ui_story_1012_10121501_337_dialog_content = "\"Os celestitas são inúteis em uma luta, e eles até ficaram do lado dos eclipsitas no passado...\"",
  ui_story_1012_10121501_338_dialog_content = "O pensamento de alguém dizendo algo assim me dói.",
  ui_story_1012_10121501_339_dialog_content = "Entendi.",
  ui_story_1012_10121501_340_dialog_content = "Ainda temos que aprender a verdadeira história de seu povo.",
  ui_story_1012_10121501_341_dialog_content = "É possível que seus ancestrais tenham escolhido se rebelar e, portanto, alterado o destino dos celestitas.",
  ui_story_1012_10121501_342_dialog_content = "Mas o passado não pode ser mudado.",
  ui_story_1012_10121501_343_dialog_content = "E agora, o futuro dos celestitas está em suas mãos.",
  ui_story_1012_10121501_344_dialog_content = "Eu... preciso de tempo para pensar sobre isso.",
  ui_story_1012_10121501_345_dialog_content = "Talvez o que eu precise fazer seja encontrar a verdade.",
  ui_story_1012_10121501_346_dialog_content = "O que você faria se fosse uma verdade feia, PlayerName?",
  ui_story_1012_10121501_347_dialog_content = "Estou com medo de que a verdade possa ser ainda mais feia do que eu imaginava.",
  ui_story_1012_10121501_348_dialog_content = "E que eu possa ter que suportar a suspeita e o escrutínio de todos...",
  ui_story_1012_10121501_349_dialog_content = "Você vai precisar de tempo, PlayerName.",
  ui_story_1012_10121501_350_dialog_content = "Sim... Talvez muito tempo...",
  ui_story_1012_10121501_351_dialog_content = "<color=#e8d9bb>\"Controle Primário: Ativo.\"</color>",
  ui_story_1012_10121501_352_dialog_content = "<color=#e8d9bb>\"Módulos biológicos: ativos.\"</color>",
  ui_story_1012_10121501_353_dialog_content = "<color=#e8d9bb>\"Suporte de Vida: Ativo.\"</color>",
  ui_story_1012_10121501_354_dialog_content = "<color=#e8d9bb>\"Motores engajados...\"</color>",
  ui_story_1012_10121501_355_dialog_content = "<color=#e8d9bb>\"16%... 33%...\"</color>",
  ui_story_1012_10121501_356_dialog_content = "<color=#e8d9bb>\"89%... 97%...\"</color>",
  ui_story_1012_10121501_357_dialog_content = "<color=#e8d9bb>\"100%. Envolvido com sucesso.\"</color>",
  ui_story_1012_10121501_358_dialog_content = "Uau! Soroz está totalmente reparado!",
  ui_story_1012_10121501_359_dialog_content = "Sim, finalmente!",
  ui_story_1012_10121501_360_dialog_content = "Mesmo que a consciência ainda não tenha despertado, esta ainda é uma grande vitória!",
  ui_story_1012_10121501_361_dialog_content = "Como se você tivesse recuperado algo que perdeu, certo?",
  ui_story_1012_10121501_362_dialog_content = "Exatamente!",
  ui_story_1012_10121501_363_dialog_content = "Ufa... estou exausto. Não posso acreditar em quantas situações de vida ou morte passamos nos últimos dias.",
  ui_story_1012_10121501_364_dialog_content = "Sim, como se estivéssemos sempre por um fio...",
  ui_story_1012_10121501_365_dialog_content = "Mas resistimos e conseguimos.",
  ui_story_1012_10121501_366_dialog_content = "Eu tenho que dizer... Nós realmente tivemos sorte, haha!",
  ui_story_1012_10121501_367_dialog_content = "Você tem razão.",
  ui_story_1012_10121501_368_dialog_content = "Mas... talvez não seja apenas sorte.",
  ui_story_1012_10121501_369_dialog_content = "Talvez tudo tenha acontecido por um motivo... que ainda nos escapa.",
  ui_story_1012_10121501_370_dialog_content = "Parece que você realmente pensou nisso. Aconteceu alguma coisa no Obelisco do Retorno?",
  ui_story_1012_10121501_371_dialog_content = "É só que quando penso no passado, quase posso sentir que há uma conexão entre tudo o que aconteceu.",
  ui_story_1012_10121501_372_dialog_content = "Muitas coisas aconteceram com as pessoas no Obelisco do Retorno.",
  ui_story_1012_10121501_373_dialog_content = "Embora possamos nunca conhecer suas histórias, vemos as marcas deixadas por eles.",
  ui_story_1012_10121501_374_dialog_content = "E é como se estivéssemos refazendo os passos.",
  ui_story_1012_10121501_375_dialog_content = "Não sei a quem pertenciam nem o que pretendiam fazer...",
  ui_story_1012_10121501_376_dialog_content = "Estávamos apenas montando um grande quebra-cabeça passo a passo ao longo do caminho.",
  ui_story_1012_10121501_377_dialog_content = "Você está se referindo a essa pessoa do Mestre Francis, não é?",
  ui_story_1012_10121501_378_dialog_content = "Ele parece estar em sua mente muito.",
  ui_story_1012_10121501_379_dialog_content = "Sim... Eu estive pensando, qual era a história dele?",
  ui_story_1012_10121501_380_dialog_content = "O rifle pertencia a ele, e ele lutou contra os Eclipsitas na torre...",
  ui_story_1012_10121501_381_dialog_content = "Ele estava encarregado dos experimentos Chord Link, e seu laboratório estava escondido dentro da Zona Exilada.",
  ui_story_1012_10121501_382_dialog_content = "Não sei se ele também passou pelo que passamos lutando pelo controle da Autorização do Anel Central, mas...",
  ui_story_1012_10121501_383_dialog_content = "Um Auroriano aprimorado com Chord Link foi fundamental.",
  ui_story_1012_10121501_384_dialog_content = "Certo. Agora que você disse isso, parece que estamos seguindo os passos dele o tempo todo.",
  ui_story_1012_10121501_385_dialog_content = "Lutamos contra o Eclipse. E ele?",
  ui_story_1012_10121501_386_dialog_content = "Contra o que ele lutou... talvez ainda mais terrível.",
  ui_story_1012_10121501_387_dialog_content = "Eu não posso dizer o que exatamente... mas pode ser o próprio destino.",
  ui_story_1012_10121501_388_dialog_content = "Ele não quer sua vida, mas quer controlar sua vida.",
  ui_story_1012_10121501_389_dialog_content = "Mestre Francis tentou lutar contra isso... contra sua \"natureza\".",
  ui_story_1012_10121501_390_dialog_content = "Resista... a própria natureza...",
  ui_story_1012_10121501_391_dialog_content = "É mesmo possível?",
  ui_story_1012_10121501_392_dialog_content = "Eu me pergunto se ele conseguiu ou não.",
  ui_story_1012_10121501_393_dialog_content = "Essa resposta é óbvia. Basta olhar pela janela.",
  ui_story_1012_10121501_394_dialog_content = "Os celestitas têm um lugar para chamar de lar sob o Obelisco do Retorno.",
  ui_story_1012_10121501_395_dialog_content = "O Decreto Mais Alto não dita mais suas vidas, nem estão vinculados aos Eclipsitas.",
  ui_story_1012_10121501_396_dialog_content = "Seu sonho alterou o destino de suas futuras gerações...",
  ui_story_1012_10121501_397_dialog_content = "Ele mudou a vida de todos os celestitas.",
  ui_story_1013_10130101_1_dialog_content = "Mais um dia calmo então.",
  ui_story_1013_10130101_2_dialog_content = "Sim.",
  ui_story_1013_10130101_3_dialog_content = "Parece que faz uma eternidade desde que usamos Luminatics para combater Eclipsites.",
  ui_story_1013_10130101_4_dialog_content = "Aposto que até minhas habilidades de combate enferrujaram.",
  ui_story_1013_10130101_5_dialog_content = "A paz é uma coisa boa!",
  ui_story_1013_10130101_6_dialog_content = "Se algum dia chegasse o dia em que todos os Eclipsites fossem eliminados, provavelmente seria assim a vida.",
  ui_story_1013_10130101_7_dialog_content = "Nunca precisaríamos nos preocupar em sermos atacados. E poderíamos passar nossos dias caminhando, pescando ou cozinhando.",
  ui_story_1013_10130101_8_dialog_content = "Isso soa muito bem, na verdade.",
  ui_story_1013_10130101_9_dialog_content = "O que você planeja fazer quando chegar a hora?",
  ui_story_1013_10130101_10_option_content = "Plante árvores?",
  ui_story_1013_10130101_11_dialog_content = "Plante um monte de árvores raras para embelezar os Cloud Gardens.",
  ui_story_1013_10130101_12_dialog_content = "Embora não fosse fácil. Essas mutações falham nove vezes em dez!",
  ui_story_1013_10130101_13_dialog_content = "Plantar árvores requer perseverança.",
  ui_story_1013_10130101_14_option_content = "Pescaria?",
  ui_story_1013_10130101_15_dialog_content = "Adoraria colocar mais peixes ornamentais na Fonte dos Desejos.",
  ui_story_1013_10130101_16_dialog_content = "Estou cansado de pescar lixo...",
  ui_story_1013_10130101_17_dialog_content = "Você definitivamente teria sucesso nisso!",
  ui_story_1013_10130101_18_dialog_content = "Eraveil é tão pacífico quanto é, tudo graças ao Acorde da Lei.",
  ui_story_1013_10130101_19_dialog_content = "Eu não percebi o quão poderoso era.",
  ui_story_1013_10130101_20_dialog_content = "Se eu tivesse atirado à vontade, sem os parâmetros que mestre Francis havia estabelecido previamente...",
  ui_story_1013_10130101_21_dialog_content = "Provavelmente teria havido sérias repercussões.",
  ui_story_1013_10130101_22_dialog_content = "Ainda estremeço quando penso nisso agora.",
  ui_story_1013_10130101_23_dialog_content = "A crise já passou, então não desperdice energia se preocupando com ela agora.",
  ui_story_1013_10130101_24_dialog_content = "Viva o momento!",
  ui_story_1013_10130101_25_dialog_content = "Você tem razão! Bem dito.",
  ui_story_1013_10130101_26_dialog_content = "De qualquer forma, Vice, por que você ainda está vestido assim?",
  ui_story_1013_10130101_27_dialog_content = "Huh? Você quer dizer todo preto?",
  ui_story_1013_10130101_28_dialog_content = "Bem, estou muito mais acostumada a usar minha roupa habitual, mas às vezes até eu gosto de apimentar um pouco com algo diferente.",
  ui_story_1013_10130101_29_dialog_content = "É estranho? Se assim for, eu poderia ... voltar para o meu branco habitual?",
  ui_story_1013_10130101_30_dialog_content = "Não não! Não há necessidade!",
  ui_story_1013_10130101_31_dialog_content = "Eu não estou preocupado com o que você veste, contanto que você goste!",
  ui_story_1013_10130101_32_dialog_content = "A propósito, os peixes ornamentais que você acabou de pescar ainda estão no balde.",
  ui_story_1013_10130101_33_dialog_content = "Apresse-se e coloque-os na Fonte dos Desejos!",
  ui_story_1013_10130101_34_dialog_content = "Isso mesmo! Eu esqueci totalmente!",
  ui_story_1013_10130101_35_dialog_content = "Deixe-me ir jogá-los na Fonte.",
  ui_story_1013_10130101_36_dialog_content = "Hã?!",
  ui_story_1013_10130101_37_dialog_content = "Vice, você tem praticado novos Luminatics?",
  ui_story_1013_10130101_38_dialog_content = "Nova Luminática? Não, eu...",
  ui_story_1013_10130101_39_dialog_content = "O que diabos está acontecendo?!",
  ui_story_1013_10130101_40_dialog_content = "Eu não usei nenhum Luminatics!",
  ui_story_1013_10130101_41_dialog_content = "Quem está brincando? Venha para fora. Podemos ver você!",
  ui_story_1013_10130101_42_dialog_content = "Hum... Não, parece que esta Lumina está saindo de mim.",
  ui_story_1013_10130101_43_dialog_content = "Eu posso sentir Lumina drenando lentamente para longe de mim. O que está acontecendo aqui?",
  ui_story_1013_10130101_44_dialog_content = "Será que...",
  ui_story_1013_10130101_45_dialog_content = "Um efeito colateral de usar o Chord Link?",
  ui_story_1013_10130101_46_dialog_content = "Tudo bem Vice? você se sente bem?",
  ui_story_1013_10130101_47_dialog_content = "Fisicamente, sinto-me totalmente bem...",
  ui_story_1013_10130101_48_dialog_content = "A velocidade da perda de Lumina é tão lenta que mal consigo senti-la.",
  ui_story_1013_10130101_49_dialog_content = "Se isso é tudo, então não é grande coisa.",
  ui_story_1013_10130101_50_dialog_content = "Mas não sabemos se você terá outros sintomas.",
  ui_story_1013_10130101_51_dialog_content = "Sabemos tão pouco sobre a tecnologia antiga, mas ainda usamos aquele dispositivo tão apressadamente, eu...",
  ui_story_1013_10130101_52_dialog_content = "Relaxe, PlayerName.",
  ui_story_1013_10130101_53_dialog_content = "Podemos muito bem voltar para Gannon!",
  ui_story_1013_10130101_54_dialog_content = "Gannon tem os melhores cientistas e instalações médicas em Illumina. Temos que descobrir o que está causando tudo isso.",
  ui_story_1013_10130101_55_dialog_content = "Ah... Isso mesmo! Vamos logo. Podemos usar o terminal de comunicação para entrar em contato com a Vivian no caminho, e com certeza ela vai nos ajudar!",
  ui_story_1013_10130101_56_dialog_content = "Destino do piloto automático confirmado: Gannon City.",
  ui_story_1013_10130101_57_dialog_content = "Tudo bem, vamos seguir em frente!",
  ui_story_1013_10130101_58_dialog_content = "Não se preocupe, PlayerName, Estou bem.",
  ui_story_1013_10130101_59_dialog_content = "Eu estou apenas, você sabe, brilhando um pouco.",
  ui_story_1013_10130101_60_dialog_content = "Mas você só se machucou porque estava me ajudando a encontrar uma maneira de consertar Soroz.",
  ui_story_1013_10130101_61_dialog_content = "Também foi minha decisão usar o Chord Link para tratá-lo.",
  ui_story_1013_10130101_62_dialog_content = "Então... preciso assumir a responsabilidade por quaisquer que sejam esses sintomas agora.",
  ui_story_1013_10130101_63_dialog_content = "Especialmente desde que decidi por conta própria operar aqueles dispositivos antigos, mesmo sem saber para que eles foram feitos!",
  ui_story_1013_10130101_64_dialog_content = "PlayerName...",
  ui_story_1013_10130101_65_dialog_content = "Por favor, não se preocupe. Eu honestamente me sinto bem.",
  ui_story_1013_10130101_66_dialog_content = "Mas é claro que não podemos simplesmente ignorar isso.",
  ui_story_1013_10130101_67_dialog_content = "Você tem razão. Nossa melhor aposta é ir primeiro a Gannon para um exame completo.",
  ui_story_1013_10130101_68_dialog_content = "Entre em contato com a oficial Vivian enquanto estivermos a caminho e peça a ela para providenciar os exames.",
  ui_story_1013_10130101_69_dialog_content = "Vai fazer.",
  ui_story_1013_10130101_70_dialog_content = "Vivian? Você pode me ouvir?",
  ui_story_1013_10130101_71_dialog_content = "PlayerName? Sim, eu posso ouvir você. Vá em frente.",
  ui_story_1013_10130101_72_dialog_content = "Há uma situação um tanto urgente com a Vice, e preciso de ajuda!",
  ui_story_1013_10130101_73_dialog_content = "Uma situação urgente? Não me diga que Vice também está tendo um desses episódios.",
  ui_story_1013_10130101_74_dialog_content = "\"Também\"?",
  ui_story_1013_10130101_75_dialog_content = "Barton também começou a brilhar aleatoriamente?!",
  ui_story_1013_10130101_76_dialog_content = "Sim, o Comandante Barton foi dispensado para poder descansar logo após a batalha em Eraveil.",
  ui_story_1013_10130101_77_dialog_content = "De alguma forma, esta manhã, seu corpo começou a emitir Lumina sem motivo.",
  ui_story_1013_10130101_78_dialog_content = "Vou adivinhar que Vice está passando pela mesma coisa.",
  ui_story_1013_10130101_79_dialog_content = "Isso mesmo. Estamos a caminho de Gannon enquanto conversamos. Você poderia marcar um exame para quando chegarmos lá?",
  ui_story_1013_10130101_80_dialog_content = "Deixa comigo.",
  ui_story_1013_10130101_81_dialog_content = "Illumina já planejava realizar um exame minucioso do Comandante Barton e Vice devido ao fato de usarem o Chord Link.",
  ui_story_1013_10130101_82_dialog_content = "Sério? Que ótimo!",
  ui_story_1013_10130101_83_dialog_content = "Venha para o centro médico assim que chegar em Gannon City. Te espero lá.",
  ui_story_1013_10130101_84_dialog_content = "Entendi. Obrigada!",
  ui_story_1013_10130101_85_dialog_content = "<color=#e8d9bb>Gannon City, Centro Médico</color>",
  ui_story_1013_10130101_86_dialog_content = "Aqui é o centro médico.",
  ui_story_1013_10130101_87_dialog_content = "A última vez que estive aqui foi para o exame físico obrigatório quando me alistei.",
  ui_story_1013_10130101_88_dialog_content = "É a minha primeira vez. Eu não tinha ideia de que o centro médico Illumina seria tão grande!",
  ui_story_1013_10130101_89_dialog_content = "Claro que não!",
  ui_story_1013_10130101_90_dialog_content = "Ninguém pode prever o número de baixas em que uma batalha pode resultar.",
  ui_story_1013_10130101_91_dialog_content = "Quanto maior o centro, mais soldados feridos podemos tratar com urgência.",
  ui_story_1013_10130101_92_dialog_content = "O tratamento rápido aumenta suas chances de sobreviver...",
  ui_story_1013_10130101_93_dialog_content = "Muito verdadeiro...",
  ui_story_1013_10130101_94_dialog_content = "Ei, Vice, PlayerName!",
  ui_story_1013_10130101_95_dialog_content = "Você já está aqui.",
  ui_story_1013_10130101_96_dialog_content = "Comandante Barton! Policial Vivian!",
  ui_story_1013_10130101_97_dialog_content = "Parece que Barton sofre do mesmo fenômeno...",
  ui_story_1013_10130101_98_dialog_content = "Huh? Oh, você quer dizer o brilhante?",
  ui_story_1013_10130101_99_dialog_content = "Eu não estou incomodado se ele apenas brilha. Não é como se gastasse muito Lumina, de qualquer maneira.",
  ui_story_1013_10130101_100_dialog_content = "Claro, mas você não pode simplesmente ignorar o risco potencial!",
  ui_story_1013_10130101_101_dialog_content = "Sim, bem, espero que aqueles caras espertos em jalecos brancos encontrem uma maneira de parar o brilho em breve.",
  ui_story_1013_10130101_102_dialog_content = "Caso contrário, serei um alvo brilhante à noite. E não poderei emboscar inimigos!",
  ui_story_1013_10130101_103_dialog_content = "I-De fato.",
  ui_story_1013_10130101_104_dialog_content = "E aí, garoto? Você tem preocupação escrita em todo o seu rosto.",
  ui_story_1013_10130101_105_dialog_content = "Oh? Bem... Não vou mentir, estou um pouco preocupado.",
  ui_story_1013_10130101_106_dialog_content = "Não seja. Esta aqui é a melhor organização médica de toda a Illumina. Eles podem trazê-lo de volta antes mesmo de você saber que está morto!",
  ui_story_1013_10130101_107_dialog_content = "Esse tipo de situação brilhante indolor e inofensiva é um passeio no parque.",
  ui_story_1013_10130101_108_dialog_content = "Direita!",
  ui_story_1013_10130101_109_dialog_content = "Bem, deixe-me escoltar o Comandante Barton e Vice para os exames.",
  ui_story_1013_10130101_110_dialog_content = "Se puder, por favor, espere lá fora, PlayerName.",
  ui_story_1013_10130101_111_dialog_content = "De nada.",
  ui_story_1013_10130101_112_dialog_content = "Até mais!",
  ui_story_1013_10130101_113_dialog_content = "Mais tarde, garoto.",
  ui_story_1013_10130101_114_dialog_content = "E o silêncio cai sobre o corredor mais uma vez.",
  ui_story_1013_10130101_115_dialog_content = "Espero que esta situação seja apenas um acaso.",
  ui_story_1013_10130101_116_dialog_content = "Quanto a você, você é o único responsável por—",
  ui_story_1013_10130101_117_dialog_content = "Criando guerras para o mundo.",
  ui_story_1013_10130101_118_dialog_content = "...",
  ui_story_1013_10130101_119_dialog_content = "Não, nunca farei isso.",
  ui_story_1013_10130101_120_dialog_content = "Mas estou fazendo as escolhas certas?",
  ui_story_1013_10130101_121_dialog_content = "Parece o mesmo da última vez, mas não baixe a guarda.",
  ui_story_1013_10130101_122_dialog_content = "Não há espaço para negligência ou acidentes em sua condição.",
  ui_story_1013_10130101_123_dialog_content = "*Tosse*... Eu sei, eu sei.",
  ui_story_1013_10130101_124_dialog_content = "Tenho plena consciência da minha condição. Sempre estive.",
  ui_story_1013_10130101_125_dialog_content = "Você poderia vir treinar conosco.",
  ui_story_1013_10130101_126_dialog_content = "Confie em mim! O treino me fortaleceu, me transformou de um broto de feijão fraquinho que não sabia fazer nada!",
  ui_story_1013_10130101_127_dialog_content = "Hahaha. Minha condição não é algo que o treinamento possa consertar.",
  ui_story_1013_10130101_128_dialog_content = "(Esses caras estão aqui para um exame também?)",
  ui_story_1013_10130101_129_dialog_content = "Ei você! O que você está olhando?",
  ui_story_1013_10130101_130_dialog_content = "Huh?! Oh, me desculpe!",
  ui_story_1013_10130101_131_dialog_content = "Acabei de ver alguns estranhos e...",
  ui_story_1013_10130101_132_dialog_content = "Espere aí, você...",
  ui_story_1013_10130101_133_dialog_content = "Você não é o lendário Celestita, é?!",
  ui_story_1013_10130101_134_dialog_content = "O quê?",
  ui_story_1013_10130101_135_dialog_content = "Huh? O celestita, realmente?",
  ui_story_1013_10130101_136_dialog_content = "Você me conhece? Acho que nunca nos conhecemos.",
  ui_story_1013_10130101_137_dialog_content = "É claro! Você é famoso de onde viemos por muitas coisas.",
  ui_story_1013_10130101_138_dialog_content = "Navegando no Colosso, lutando contra os Eclipsitas ao lado dos Aurorianos na Linha Dunefire.",
  ui_story_1013_10130101_139_dialog_content = "E repelindo os Eclipsites em Eraveil, aliados a Illumina, Lumopolis e Northland!",
  ui_story_1013_10130101_140_dialog_content = "Somos todos grandes admiradores de você e de seus feitos.",
  ui_story_1013_10130101_141_option_content = "Eu apenas fiz o que pude.",
  ui_story_1013_10130101_142_dialog_content = "Afinal, os Eclipsites são inimigos de todos.",
  ui_story_1013_10130101_143_option_content = "Foi um esforço conjunto.",
  ui_story_1013_10130101_144_dialog_content = "Não há como eu ter feito tudo isso sem a ajuda de todos.",
  ui_story_1013_10130101_145_dialog_content = "E você é tão humilde quanto dizem!",
  ui_story_1013_10130101_146_dialog_content = "Permita-me apresentar-me. Meu nome é Zhao e sirvo como chefe de gabinete na cidade de Crepúsculo, a oeste.",
  ui_story_1013_10130101_147_dialog_content = "Este é meu assistente Crow e meu colega Sean.",
  ui_story_1013_10130101_148_dialog_content = "Eu nunca teria pensado que te encontraria aqui! Deve ser meu dia de sorte.",
  ui_story_1013_10130101_149_dialog_content = "É um prazer conhecer todos vocês. Eu estou PlayerName.",
  ui_story_1013_10130101_150_dialog_content = "Oi, PlayerName.",
  ui_story_1013_10130101_151_dialog_content = "E aí.",
  ui_story_1013_10130101_152_dialog_content = "Desculpe se fui um pouco brusco agora. É meu trabalho cuidar de Zhao.",
  ui_story_1013_10130101_153_dialog_content = "Está bem. Realmente não foi educado da minha parte olhar, de qualquer maneira.",
  ui_story_1013_10130101_154_dialog_content = "O chefe Zhao está sempre nos contando histórias sobre você!",
  ui_story_1013_10130101_155_dialog_content = "Estou muuuuito ciumento! Eu adoraria pilotar um Colossus por todo o lugar.",
  ui_story_1013_10130101_156_dialog_content = "Provavelmente é super conveniente viajar muito longe com um Colossus, certo?",
  ui_story_1013_10130101_157_dialog_content = "Com certeza! Não importa aonde eu vá, meu Colossus pode me levar até lá em um piscar de olhos.",
  ui_story_1013_10130101_158_dialog_content = "Incrível! Eu gostaria de ter um também.",
  ui_story_1013_10130101_159_dialog_content = "Dessa forma, podemos voltar a Crepúsculo mais cedo!",
  ui_story_1013_10130101_160_dialog_content = "Existe um motivo urgente para você retornar?",
  ui_story_1013_10130101_161_dialog_content = "Sim!",
  ui_story_1013_10130101_162_dialog_content = "Você não sabe o que está acontecendo em Crepúsculo?",
  ui_story_1013_10130101_163_dialog_content = "Na verdade, não. Onde fica essa sua cidade?",
  ui_story_1013_10130101_164_dialog_content = "Crepúsculo está fora da jurisdição de Illumina. É muito longe de Gannon.",
  ui_story_1013_10130101_165_dialog_content = "Embora os distúrbios do Eclipsite sejam mais comuns lá do que os assentamentos dentro da fronteira, ainda é um lugar muito bom para se viver.",
  ui_story_1013_10130101_166_dialog_content = "Quero voltar logo e ajudar meus amigos a cuidar daqueles insetos do Eclipsite!",
  ui_story_1013_10130101_167_dialog_content = "Honestamente, foi claramente apenas um arranhão, mas os médicos insistiram em me enviar até Gannon para tratamento.",
  ui_story_1013_10130101_168_dialog_content = "Acho que está tudo bem, no entanto. Terminamos agora e podemos voltar para Crepúsculo esta tarde!",
  ui_story_1013_10130101_169_dialog_content = "É melhor ficar seguro do que arrepender-se.",
  ui_story_1013_10130101_170_dialog_content = "Você tem que cuidar de si mesmo, ou não terá forças para enfrentar mais inimigos.",
  ui_story_1013_10130101_171_dialog_content = "Não seja como uma certa pessoa e sempre se esforce demais.",
  ui_story_1013_10130101_172_dialog_content = "*Tosse*... Enfim, PlayerName, devemos ir.",
  ui_story_1013_10130101_173_dialog_content = "Se você tiver a chance de visitar, nós o receberemos de braços abertos.",
  ui_story_1013_10130101_174_dialog_content = "Eu adoraria a chance de lutar ao lado do Caelestite.",
  ui_story_1013_10130101_175_dialog_content = "Se a oportunidade aparecer, vou aproveitar com certeza.",
  ui_story_1013_10130101_176_dialog_content = "Vejo você por aí se o destino quiser.",
  ui_story_1013_10130101_177_dialog_content = "Adeus.",
  ui_story_1013_10130101_178_dialog_content = "Adeus!",
  ui_story_1013_10130101_179_dialog_content = "Crepúsculo? Parece um lugar bem remoto.",
  ui_story_1013_10130101_180_dialog_content = "Huh? Aquela pessoa saindo do consultório ali, é...?",
  ui_story_1013_10130101_181_dialog_content = "Reinhardt?!",
  ui_story_1013_10130101_182_dialog_content = "Huh? PlayerName?",
  ui_story_1013_10130101_183_dialog_content = "Vivian mencionou que você estava trazendo Vice para Gannon. Mas não pensei que fosse esbarrar em você.",
  ui_story_1013_10130101_184_dialog_content = "Estou agradavelmente surpreso também.",
  ui_story_1013_10130101_185_dialog_content = "Então, o que te trás aqui?",
  ui_story_1013_10130101_186_dialog_content = "Algo estranho aconteceu com você também depois de usar os sistemas médicos de Soroz?",
  ui_story_1013_10130101_187_dialog_content = "Oh não. Nada como o que Barton e Vice estão lidando.",
  ui_story_1013_10130101_188_dialog_content = "Estou aqui apenas para um exame físico de rotina.",
  ui_story_1013_10130101_189_dialog_content = "Tem que ter um a cada seis meses. São apenas testes de condicionamento físico e de sangue, realmente, coisas padrão.",
  ui_story_1013_10130101_190_dialog_content = "Meus resultados estão estáveis como sempre foram, então não há necessidade de se preocupar.",
  ui_story_1013_10130101_191_dialog_content = "Ótimo, isso é um alívio. Oh sim, como está aquela lesão que você contraiu da última vez?",
  ui_story_1013_10130101_192_dialog_content = "Haha! Relaxar. Graças ao seu equipamento médico de primeira linha, está curado há muito tempo.",
  ui_story_1013_10130101_193_dialog_content = "Se ao menos a Illumina tivesse esse tipo de equipamento...",
  ui_story_1013_10130101_194_dialog_content = "Ei garoto, estamos de volta!",
  ui_story_1013_10130101_195_dialog_content = "Grande Marechal Reinhardt? Você está aqui também?",
  ui_story_1013_10130101_196_dialog_content = "Ei PlayerName... e o Grande Marechal?!",
  ui_story_1013_10130101_197_dialog_content = "Eles terminaram de examinar vocês dois? Como foram os resultados?",
  ui_story_1013_10130101_198_dialog_content = "Como devo colocar isso...",
  ui_story_1013_10130101_199_dialog_content = "O relatório disse que o resultado foi - nada!",
  ui_story_1013_10130101_200_dialog_content = "Hã?!",
  ui_story_1013_10130101_201_dialog_content = "Esses médicos e cientistas nos cutucaram e cutucaram com todos os tipos de instrumentos pelo que pareceu uma eternidade, mas no final das contas não conseguiram chegar a uma conclusão.",
  ui_story_1013_10130101_202_dialog_content = "Todos os testes habituais feitos durante um exame físico de rotina voltaram ao normal.",
  ui_story_1013_10130101_203_dialog_content = "Portanto, não há problema algum, pelo menos de acordo com os resultados do teste.",
  ui_story_1013_10130101_204_dialog_content = "Mas parece que não há mais Lumina saindo de vocês. Como você foi curado?",
  ui_story_1013_10130101_205_dialog_content = "Ah, sobre isso!",
  ui_story_1013_10130101_206_dialog_content = "Um dos testes envolveu o uso de Luminatics para atacar manequins de treinamento.",
  ui_story_1013_10130101_207_dialog_content = "Acho que os cientistas provavelmente queriam ver se esse tipo de dispersão de Lumina afetaria ou não nossa capacidade de usar Luminatics.",
  ui_story_1013_10130101_208_dialog_content = "De qualquer forma, depois de espancar alegremente os manequins por um tempo, o brilho simplesmente parou por si só.",
  ui_story_1013_10130101_209_dialog_content = "Se eu soubesse que esse era o jeito de parar o brilho, eu teria ido procurar alguns Eclipsites!",
  ui_story_1013_10130101_210_dialog_content = "Eu ouvi alguns cientistas dizerem que o Comandante Barton destruiu totalmente uns bons dez manequins de treinamento.",
  ui_story_1013_10130101_211_dialog_content = "É assim mesmo? Pois bem, o custo de repará-los será deduzido da alocação mensal do Comandante da 2ª Legião.",
  ui_story_1013_10130101_212_dialog_content = "Espere o que?!",
  ui_story_1013_10130101_213_dialog_content = "Hahaha, estou brincando.",
  ui_story_1013_10130101_214_dialog_content = "O principal é que vocês dois estão bem. No entanto, não baixe a guarda só porque você está bem agora.",
  ui_story_1013_10130101_215_dialog_content = "Certifique-se de fazer check-ups regulares, pelo menos por um curto período de tempo, para ter certeza absoluta de que está tudo bem.",
  ui_story_1013_10130101_216_dialog_content = "Sim, senhora!",
  ui_story_1013_10130101_217_dialog_content = "Sim, senhora!",
  ui_story_1013_10130101_218_dialog_content = "Em suma, minha saúde é normal em todos os aspectos.",
  ui_story_1013_10130101_219_dialog_content = "Você não precisa se preocupar muito.",
  ui_story_1013_10130101_220_dialog_content = "Acho que, por enquanto, o brilho não é um grande problema.",
  ui_story_1013_10130101_221_dialog_content = "Mas ainda me preocupo se o uso do Chord Link pode causar outros sintomas.",
  ui_story_1013_10130101_222_dialog_content = "Não sabemos de nada, e é isso que torna isso aterrorizante.",
  ui_story_1013_10130101_223_dialog_content = "Foi o que os médicos disseram também.",
  ui_story_1013_10130101_224_dialog_content = "Então, eles me aconselharam a permanecer ativo e prestar atenção especial a qualquer mudança em minha condição física.",
  ui_story_1013_10130101_225_dialog_content = "Ok! Vou ajudar a ficar de olho em você também!",
  ui_story_1013_10130101_226_dialog_content = "Falando nisso, tenho uma proposta para você.",
  ui_story_1013_10130101_227_dialog_content = "Bem, para ser preciso, é mais um pedido.",
  ui_story_1013_10130101_228_dialog_content = "PlayerName, Eu esperava que você estivesse disposto a conceder à Illumina acesso de pesquisa a Soroz e ao Obelisco do Retorno.",
  ui_story_1013_10130101_229_dialog_content = "Hã?!",
  ui_story_1013_10130101_230_dialog_content = "Posso perguntar por que?",
  ui_story_1013_10130101_231_dialog_content = "De nada.",
  ui_story_1013_10130101_232_dialog_content = "Afinal, toda a comunidade científica da Illumina e eu desenvolvemos uma profunda apreciação do poder da tecnologia Caelestita.",
  ui_story_1013_10130101_233_dialog_content = "Particularmente em relação ao Chord Link e à tecnologia médica, se pudéssemos usá-los em batalha, poderíamos salvar a vida de tantos aurorianos.",
  ui_story_1013_10130101_234_dialog_content = "Além disso, a Sala de Simulação no Colossus também tem um potencial fenomenal.",
  ui_story_1013_10130101_235_dialog_content = "Se pudéssemos usá-lo para treinar comandantes, poderíamos definitivamente reduzir o número de baixas.",
  ui_story_1013_10130101_236_dialog_content = "Mas...",
  ui_story_1013_10130101_237_dialog_content = "(Se a tecnologia Caelestite foi feita para incitar a guerra, está tudo bem entregá-la assim?)",
  ui_story_1013_10130101_238_dialog_content = "Eu sei com o que você provavelmente está preocupado.",
  ui_story_1013_10130101_239_dialog_content = "Portanto, eu prometo a você o seguinte:",
  ui_story_1013_10130101_240_dialog_content = "A Illumina nunca usará essa tecnologia para nenhum propósito inconveniente.",
  ui_story_1013_10130101_241_dialog_content = "E nós iremos, claro, oferecer-lhe uma compensação.",
  ui_story_1013_10130101_242_dialog_content = "Em troca, a Illumina enviará nossos melhores e mais brilhantes cientistas para ajudá-lo a consertar Soroz.",
  ui_story_1013_10130101_243_dialog_content = "...",
  ui_story_1013_10130101_244_dialog_content = "O que você acha, Vice?",
  ui_story_1013_10130101_245_dialog_content = "O que eu acho?",
  ui_story_1013_10130101_246_dialog_content = "Bem, eu quero que a Illumina tenha a melhor tecnologia médica.",
  ui_story_1013_10130101_247_dialog_content = "Mas Eraveil é seu. A escolha é sua.",
  ui_story_1013_10130101_248_dialog_content = "Então quais são os teus pensamentos, PlayerName?",
  ui_story_1013_10130101_249_dialog_content = "Ei, espere um minuto, Grande Marechal.",
  ui_story_1013_10130101_250_dialog_content = "Não é um pouco precipitado esperar uma resposta agora?",
  ui_story_1013_10130101_251_dialog_content = "Esta não é uma pequena decisão que você pode tomar por capricho.",
  ui_story_1013_10130101_252_dialog_content = "Dê ao garoto algum tempo para pensar sobre isso. Você obterá sua resposta.",
  ui_story_1013_10130101_253_dialog_content = "...",
  ui_story_1013_10130101_254_dialog_content = "Desculpe, fui um pouco precipitado.",
  ui_story_1013_10130101_255_dialog_content = "Se você precisa de tempo para considerar, por favor, por todos os meios. Eu posso esperar.",
  ui_story_1013_10130101_256_dialog_content = "Eu...",
  ui_story_1013_10130101_257_dialog_content = "Está tudo bem.",
  ui_story_1013_10130101_258_option_content = "Eu vou permitir isso.",
  ui_story_1013_10130101_259_dialog_content = "Excelente. Obrigada, PlayerName.",
  ui_story_1013_10130101_260_option_content = "Eu confio em você.",
  ui_story_1013_10130101_261_dialog_content = "...!",
  ui_story_1013_10130101_262_dialog_content = "Obrigada, PlayerName.",
  ui_story_1013_10130101_263_dialog_content = "Bem, não há tempo a perder. Vou entrar em contato com a equipe científica do centro de pesquisa e dizer-lhes para se prepararem.",
  ui_story_1013_10130101_264_dialog_content = "Você e Vice devem vir também, pois podemos precisar de sua ajuda. Desculpas antecipadamente pelo aborrecimento.",
  ui_story_1013_10130101_265_dialog_content = "Isso é bom. Se vocês me ajudarem a consertar o Soroz, todos sairão ganhando.",
  ui_story_1013_10130101_266_dialog_content = "Se for para a Illumina, então isso é minha responsabilidade. Eu nunca recusaria.",
  ui_story_1013_10130101_267_dialog_content = "Parece que não tenho mais motivos para ficar por aqui.",
  ui_story_1013_10130101_268_dialog_content = "Nesse caso, voltarei para a 2ª Legião.",
  ui_story_1013_10130101_269_dialog_content = "Pare para um jogo de xadrez se tiver um minuto, garoto.",
  ui_story_1013_10130101_270_dialog_content = "Claro! Gostaria disso.",
  ui_story_1013_10130201_1_dialog_content = "Esta é a área administrativa do Centro de Pesquisa Illumina.",
  ui_story_1013_10130201_2_dialog_content = "Esta é provavelmente a sua primeira vez aqui.",
  ui_story_1013_10130201_3_dialog_content = "S-Sim!",
  ui_story_1013_10130201_4_dialog_content = "Sempre ouvi dizer que este lugar tem os melhores cientistas de toda a Federação Illumina.",
  ui_story_1013_10130201_5_dialog_content = "Nunca esperei ver com meus próprios olhos!",
  ui_story_1013_10130201_6_dialog_content = "Uau, está ocupado!",
  ui_story_1013_10130201_7_dialog_content = "É claro. Todos aqui trabalham duro em nome da Illumina, todos os dias.",
  ui_story_1013_10130201_8_dialog_content = "O sucesso da Illumina é em grande parte graças aos seus esforços.",
  ui_story_1013_10130201_9_dialog_content = "Ei! Grande marechal! E Vice! E o perdedor!",
  ui_story_1013_10130201_10_option_content = "Gronru?!",
  ui_story_1013_10130201_11_dialog_content = "O que está fazendo aqui?",
  ui_story_1013_10130201_12_dialog_content = "O Grande Marechal pediu a Migard e a mim para ajudar em alguns experimentos. Ela disse que eu ficaria livre para estudar as novas funções de Soroz.",
  ui_story_1013_10130201_13_dialog_content = "O que parecia muito mais divertido do que vencer outro jogo na dificuldade mais alta! Eu aceitei em um piscar de olhos.",
  ui_story_1013_10130201_14_dialog_content = "Por favor, seja gentil com Soroz...",
  ui_story_1013_10130201_15_dialog_content = "Ah, relaxe! Tratarei Soroz com as mãos mais cuidadosas de todas!",
  ui_story_1013_10130201_16_dialog_content = "Já faz um tempo, jovem.",
  ui_story_1013_10130201_17_dialog_content = "Senhorita... Migard...",
  ui_story_1013_10130201_18_dialog_content = "(Mesmo sabendo que ela é inofensiva, não posso deixar de ficar nervoso sempre que a vejo...)",
  ui_story_1013_10130201_19_dialog_content = "Hum? O que há com sua expressão?",
  ui_story_1013_10130201_20_dialog_content = "Você parece preocupado desde que chegou a Illumina hoje cedo.",
  ui_story_1013_10130201_21_dialog_content = "Porque algo estava acontecendo com Vice...",
  ui_story_1013_10130201_22_dialog_content = "Espere, você nos viu? Como é que eu não te vi? Espero não ter te ignorado?!",
  ui_story_1013_10130201_23_dialog_content = "Ahaha, você esquece que meus Diving Spines vigiam cada canto de Illumina.",
  ui_story_1013_10130201_24_dialog_content = "Mesmo que eu não esteja lá pessoalmente, posso ver você através deles.",
  ui_story_1013_10130201_25_dialog_content = "Err... entendo...",
  ui_story_1013_10130201_26_dialog_content = "Tudo bem, vamos indo! O centro de pesquisa espera!",
  ui_story_1013_10130201_27_dialog_content = "Vamos pegar a estrada, PlayerName!",
  ui_story_1013_10130201_28_dialog_content = "Todos! O navegador está aqui!",
  ui_story_1013_10130201_29_dialog_content = "Espere, este é o navegador? Ah, sou fã há tanto tempo!",
  ui_story_1013_10130201_30_dialog_content = "Hmm, ele é um pouco jovem, mas como cobaia... ele será o suficiente.",
  ui_story_1013_10130201_31_dialog_content = "Cobaia?!",
  ui_story_1013_10130201_32_dialog_content = "PlayerName é meu companheiro, não uma cobaia!",
  ui_story_1013_10130201_33_dialog_content = "Haha, não se importe com eles. Quase todos os pesquisadores aqui têm algo um pouco estranho sobre eles.",
  ui_story_1013_10130201_34_dialog_content = "Mas não se preocupe, eles são totalmente inofensivos.",
  ui_story_1013_10130201_35_dialog_content = "Grande Marechal, tudo aqui foi preparado conforme as instruções. Estamos prontos para começar nossa pesquisa.",
  ui_story_1013_10130201_36_dialog_content = "Bom. Mas uma última coisa.",
  ui_story_1013_10130201_37_dialog_content = "Tem mais?",
  ui_story_1013_10130201_38_dialog_content = "Sim. Preciso expressar minha gratidão a você.",
  ui_story_1013_10130201_39_dialog_content = "Hum?",
  ui_story_1013_10130201_40_dialog_content = "Você não acabou de me agradecer?",
  ui_story_1013_10130201_41_dialog_content = "Isso foi a título pessoal. Mas desta vez, é como o Grande Marechal da Federação Illumina.",
  ui_story_1013_10130201_42_dialog_content = "Permitir que Illumina conduza esta pesquisa sem dúvida salvará a vida de inúmeros aurorianos.",
  ui_story_1013_10130201_43_dialog_content = "Obrigado, PlayerName!",
  ui_story_1013_10130201_44_dialog_content = "Você também tem meus agradecimentos, jovem, apesar do aumento da carga de trabalho.",
  ui_story_1013_10130201_45_dialog_content = "Obrigada!",
  ui_story_1013_10130201_46_dialog_content = "Obrigado pela sua contribuição, sujeito de teste.",
  ui_story_1013_10130201_47_dialog_content = "Mas eu ainda nem fiz nada?!",
  ui_story_1013_10130201_48_dialog_content = "Apenas aceite seus agradecimentos.",
  ui_story_1013_10130201_49_dialog_content = "Afinal, sua concordância foi necessária para que tudo isso acontecesse.",
  ui_story_1013_10130201_50_dialog_content = "Hum...",
  ui_story_1013_10130201_51_dialog_content = "Ei, vocês poderiam parar de me olhar assim? É um pouco estranho…",
  ui_story_1013_10130201_52_dialog_content = "Vocês não têm pesquisas para fazer ou algo assim?",
  ui_story_1013_10130201_53_dialog_content = "Haha, você tem toda razão.",
  ui_story_1013_10130201_54_dialog_content = "Vocês, comecem a trabalhar. Atenha-se à nossa agenda.",
  ui_story_1013_10130201_55_dialog_content = "Sim, senhora.",
  ui_story_1013_10130201_56_dialog_content = "Todos, divididos em três grupos, como o Grande Marshall discutiu.",
  ui_story_1013_10130201_57_dialog_content = "Grupo A, dirija-se ao Obelisco do Retorno e procure informações sobre o Chord Link.",
  ui_story_1013_10130201_58_dialog_content = "Grupo B, comigo. Estamos coletando dados sobre o equipamento médico de Soroz.",
  ui_story_1013_10130201_59_dialog_content = "O resto de vocês, Grupo C, aguardem meu comando, então conectem o cabo de transmissão de dados à Sala de Simulação de Soroz.",
  ui_story_1013_10130201_60_dialog_content = "Veja se podemos usar o Illumina Battle Simulator para analisar os dados da Sala de Simulação.",
  ui_story_1013_10130201_61_dialog_content = "Sim, senhora!",
  ui_story_1013_10130201_62_dialog_content = "Illumina tem um simulador de batalha?",
  ui_story_1013_10130201_63_dialog_content = "Sim. Da última vez, quando Gronru ajudou Soroz a instalar a Sala de Simulação, obtivemos uma riqueza de dados de pesquisa.",
  ui_story_1013_10130201_64_dialog_content = "Depois que ela voltou para Illumina, ela fez uma máquina semelhante à de Soroz.",
  ui_story_1013_10130201_65_dialog_content = "Embora, a princípio, tudo o que ela queria era construir uma máquina de jogos…",
  ui_story_1013_10130201_66_dialog_content = "No entanto, no final das contas, acabou sendo algo incrível!",
  ui_story_1013_10130201_67_dialog_content = "Isso é assustador impressionante...",
  ui_story_1013_10130201_68_dialog_content = "Sim! Se você estiver interessado, poderá experimentá-lo durante o experimento um pouco mais tarde.",
  ui_story_1013_10130201_69_dialog_content = "Isso parece ótimo!",
  ui_story_1013_10130201_70_dialog_content = "Eu deveria praticar de antemão e fazê-la pensar diferente de mim!",
  ui_story_1013_10130201_71_dialog_content = "<color=#e8d9bb>Várias horas depois</color>",
  ui_story_1013_10130201_72_dialog_content = "Reportando-se, Grande Marechal.",
  ui_story_1013_10130201_73_dialog_content = "Alguma descoberta?",
  ui_story_1013_10130201_74_dialog_content = "Boas notícias, senhora. Conseguimos extrair informações sobre o método de fabricação de equipamentos médicos da Soroz do novo módulo.",
  ui_story_1013_10130201_75_dialog_content = "Esta informação nos permitirá atualizar todos os nossos equipamentos atuais no centro.",
  ui_story_1013_10130201_76_dialog_content = "Excelente trabalho!",
  ui_story_1013_10130201_77_dialog_content = "Acompanhe a pesquisa e veja se você pode fazer outras novas descobertas.",
  ui_story_1013_10130201_78_dialog_content = "Sim, senhora.",
  ui_story_1013_10130201_79_dialog_content = "Equipamento médico…",
  ui_story_1013_10130201_80_dialog_content = "Aquele cara, Zhao, não parecia muito bem, fisicamente.",
  ui_story_1013_10130201_81_dialog_content = "Se o equipamento médico estiver sendo atualizado, talvez ele possa ser ajudado?",
  ui_story_1013_10130201_82_dialog_content = "Oh? Você conhece o Zhao?",
  ui_story_1013_10130201_83_dialog_content = "Bem, mais ou menos. Eu o conheci por acaso no centro médico e conversamos um pouco.",
  ui_story_1013_10130201_84_dialog_content = "Entendi.",
  ui_story_1013_10130201_85_dialog_content = "Zhao é Chefe de Gabinete da Guarnição Illumina em Crepúsculo. Ele tem uma mente excepcional, mas um corpo frágil.",
  ui_story_1013_10130201_86_dialog_content = "Ele foi gravemente ferido quando era jovem. Darkflow corroeu seus órgãos, tornando-o incapaz de lutar.",
  ui_story_1013_10130201_87_dialog_content = "Não é à toa que ele exalava o ar de alguém com uma doença crônica.",
  ui_story_1013_10130201_88_dialog_content = "Não apenas isso, mas seu subordinado Sean também sofre de problemas físicos.",
  ui_story_1013_10130201_89_dialog_content = "Sean? Mas parecia que ele poderia correr uma maratona sem suar a camisa!",
  ui_story_1013_10130201_90_dialog_content = "Isso porque ele se submete a um treinamento constante e cansativo.",
  ui_story_1013_10130201_91_dialog_content = "Ele tem um defeito genético bastante complexo.",
  ui_story_1013_10130201_92_dialog_content = "Isso também o levou a ser esquecido quando se juntou ao exército. Ele foi enviado para estações remotas como soldado de infantaria.",
  ui_story_1013_10130201_93_dialog_content = "A inacreditável vontade e determinação daquele garoto são de agradecer por tudo o que ele conquistou.",
  ui_story_1013_10130201_94_dialog_content = "Sim, eu podia sentir algo nele que claramente foi aperfeiçoado por anos de dificuldades.",
  ui_story_1013_10130201_95_dialog_content = "Isso mesmo. E é por isso que, quando nossas atualizações estiverem concluídas, ele e outros como ele serão os primeiros beneficiários.",
  ui_story_1013_10130201_96_dialog_content = "Grande Marechal, já avançamos em nossa pesquisa sobre o Chord Link.",
  ui_story_1013_10130201_97_dialog_content = "Tão rápido?!",
  ui_story_1013_10130201_98_dialog_content = "Não subestime o know-how tecnológico da Illumina, cobaia de teste.",
  ui_story_1013_10130201_99_dialog_content = "De qualquer forma, Grand Marshall, achamos que deveríamos nos reportar a você, mas...",
  ui_story_1013_10130201_100_dialog_content = "(Ele acabou de olhar para mim?)",
  ui_story_1013_10130201_101_dialog_content = "PlayerName é o mestre de Eraveil e o Chord Link.",
  ui_story_1013_10130201_102_dialog_content = "Não há nada sobre esta pesquisa que não possa ser dito na frente dele.",
  ui_story_1013_10130201_103_dialog_content = "Muito bem. Nesse caso, explicarei com simplicidade suficiente para que até mesmo a cobaia possa acompanhar.",
  ui_story_1013_10130201_104_dialog_content = "Com base nos resultados dos exames físicos realizados no Comandante Barton e no Tenente Vice, já podemos hipotetizar para que o dispositivo provavelmente foi usado.",
  ui_story_1013_10130201_105_dialog_content = "Suspeitamos que, além de ser capaz de modificar corpos aurorianos, o Chord Link também é capaz de liberar seu potencial latente.",
  ui_story_1013_10130201_106_option_content = "Modificar corpos?",
  ui_story_1013_10130201_107_dialog_content = "Você não percebeu? As aparições do Comandante Barton e do Tenente Vice mudaram, em maior ou menor grau.",
  ui_story_1013_10130201_108_dialog_content = "Eu sei disso, mas além da aparência, essa modificação poderia afetar o corpo de outras maneiras?",
  ui_story_1013_10130201_109_dialog_content = "Teríamos que fazer mais pesquisas antes de chegar a qualquer conclusão.",
  ui_story_1013_10130201_110_dialog_content = "Mas uma coisa que podemos concluir é que essa mudança afetou os Luminatics que eles usam.",
  ui_story_1013_10130201_111_option_content = "Potencial latente?",
  ui_story_1013_10130201_112_dialog_content = "Sim. Acreditamos que as modificações do Chord Link também afetaram a maneira como eles usam o Luminatics.",
  ui_story_1013_10130201_113_dialog_content = "Permitindo-lhes liberar um poder que anteriormente seria impossível, ou pelo menos difícil, de controlar.",
  ui_story_1013_10130201_114_dialog_content = "E isso nos traz de volta à teoria da Luminática.",
  ui_story_1013_10130201_115_dialog_content = "Não me importo de passar um dia inteiro detalhando todos os aspectos do Luminatics para a cobaia.",
  ui_story_1013_10130201_116_dialog_content = "Uh... eu não acho que isso seja necessário.",
  ui_story_1013_10130201_117_dialog_content = "Não há necessidade de se preocupar indevidamente, cobaia.",
  ui_story_1013_10130201_118_dialog_content = "Mesmo depois de usar o Chord Link, eles ainda mantêm a capacidade de usar seus antigos Luminatics.",
  ui_story_1013_10130201_119_dialog_content = "Isso nos leva a crer que sua natureza fundamental permanece inalterada.",
  ui_story_1013_10130201_120_dialog_content = "Sério...?",
  ui_story_1013_10130201_121_dialog_content = "Vocês estão falando de algo sério?",
  ui_story_1013_10130201_122_dialog_content = "Esse é o capacete do Battle Simulator que você está segurando?",
  ui_story_1013_10130201_123_dialog_content = "Você fez progressos?",
  ui_story_1013_10130201_124_dialog_content = "Uhum!",
  ui_story_1013_10130201_125_dialog_content = "Conectamos o Battle Simulator ao banco de dados do Soroz.",
  ui_story_1013_10130201_126_dialog_content = "Logo no início de nossos experimentos, parecemos ter acionado algumas funções nos novos componentes de Soroz.",
  ui_story_1013_10130201_127_dialog_content = "A Sala de Simulação se atualizou e agora pode simular totalmente as condições reais do campo de batalha!",
  ui_story_1013_10130201_128_dialog_content = "Você pode experimentá-lo agora mesmo usando o Battle Simulator.",
  ui_story_1013_10130201_129_dialog_content = "Eu pensei que tinha acabado de ouvir PlayerName estava interessado.",
  ui_story_1013_10130201_130_dialog_content = "O que você disse? Quer tentar?",
  ui_story_1013_10130201_131_option_content = "É difícil?",
  ui_story_1013_10130201_132_dialog_content = "Eu não vou dar-lhe um tempo difícil! Como é um jogo novo, vamos começar com a dificuldade mais fácil.",
  ui_story_1013_10130201_133_dialog_content = "Tudo bem, vamos fazer isso!",
  ui_story_1013_10130201_134_option_content = "Claro que não!",
  ui_story_1013_10130201_135_dialog_content = "Parece incrível!",
  ui_story_1013_10130201_136_dialog_content = "Está bem então! Sente-se ali, PlayerName, e coloque este capacete.",
  ui_story_1013_10130201_137_dialog_content = "Feito.",
  ui_story_1013_10130201_138_dialog_content = "Huh? O ambiente mudou!",
  ui_story_1013_10130201_139_dialog_content = "Você pode me ouvir, PlayerName?",
  ui_story_1013_10130201_140_dialog_content = "Vício?! Onde está você?",
  ui_story_1013_10130201_141_dialog_content = "Estou bem ao seu lado!",
  ui_story_1013_10130201_142_dialog_content = "Há uma tela aqui, para que eu possa ver o que você vê.",
  ui_story_1013_10130201_143_dialog_content = "Então, PlayerName, O que você vê?",
  ui_story_1013_10130201_144_dialog_content = "Um deserto totalmente deserto. Há uma brisa agradável e está bastante ensolarado.",
  ui_story_1013_10130201_145_dialog_content = "Parece preciso.",
  ui_story_1013_10130201_146_dialog_content = "É aí que o Battle Simulator começa você.",
  ui_story_1013_10130201_147_dialog_content = "Agora, PlayerName, imagine seus companheiros ao seu lado.",
  ui_story_1013_10130201_148_dialog_content = "Imagina como eles são?",
  ui_story_1013_10130201_149_dialog_content = "Isso mesmo!",
  ui_story_1013_10130201_150_dialog_content = "O Battle Simulator projetará uma imagem auroriana correspondente usando a imagem que você evoca em sua mente e os dados Illumina existentes.",
  ui_story_1013_10130201_151_dialog_content = "Essas projeções aurorianas irão ajudá-lo a completar o teste de batalha.",
  ui_story_1013_10130201_152_option_content = "Pense no Vice.",
  ui_story_1013_10130201_153_dialog_content = "Nossa!",
  ui_story_1013_10130201_154_dialog_content = "Apareceu!",
  ui_story_1013_10130201_155_dialog_content = "Isso é incrível. Parece comigo!",
  ui_story_1013_10130201_156_dialog_content = "Excelente! Tudo está indo bem.",
  ui_story_1013_10130201_157_dialog_content = "Em seguida, deixe-me introduzir alguns Eclipsites na cena.",
  ui_story_1013_10130201_158_dialog_content = "Gaaah!",
  ui_story_1013_10130201_159_dialog_content = "Uau! Os Eclipsites também parecem reais.",
  ui_story_1013_10130201_160_dialog_content = "Eu quase posso sentir o Darkflow vindo deles!",
  ui_story_1013_10130201_161_dialog_content = "Não tenha medo.",
  ui_story_1013_10130201_162_dialog_content = "Este é apenas o teste mais básico!",
  ui_story_1013_10130201_163_dialog_content = "Tente derrotar esses Eclipsites com o Aurorian virtual!",
  ui_story_1013_10130201_164_dialog_content = "Você consegue, PlayerName!",
  ui_story_1013_10130201_165_dialog_content = "Ok! Eu farei o meu melhor!",
  ui_story_1013_10130201_166_dialog_content = "Dificuldade: Fácil.",
  ui_story_1013_10130201_167_dialog_content = "Modo padrão, número de série do estágio: 01.",
  ui_story_1013_10130201_168_dialog_content = "Objetivo: Elimine todos os Eclipsites.",
  ui_story_1013_10130201_169_dialog_content = "Simulador inicializando...",
  ui_story_1013_10130201_170_dialog_content = "<anim type=Shake><size=50>Graagh!!!</size></anim>",
  ui_story_1013_10130302_1_dialog_content = "Ufa... os Eclipsites estão todos resolvidos!",
  ui_story_1013_10130302_2_dialog_content = "Objetivo do estágio concluído.",
  ui_story_1013_10130302_3_dialog_content = "Teste concluído. Nota do estágio: A.",
  ui_story_1013_10130302_4_dialog_content = "Impressionante, PlayerName! Você tirou nota A em sua primeira tentativa no Battle Simulator!",
  ui_story_1013_10130302_5_dialog_content = "Me dê um momento, preciso desconectá-lo do simulador antes que você possa remover seu capacete.",
  ui_story_1013_10130302_6_dialog_content = "Desconectado. É seguro sair agora.",
  ui_story_1013_10130302_7_dialog_content = "Nngh...",
  ui_story_1013_10130302_8_dialog_content = "Como você está se sentindo, PlayerName? Tudo certo?",
  ui_story_1013_10130302_9_dialog_content = "Ok, eu acho. Eu sinto que realmente acabei de lutar contra um bando de Eclipsites. Estou exausta, física e mentalmente!",
  ui_story_1013_10130302_10_dialog_content = "Hahaha! Bem, bom trabalho de qualquer maneira, PlayerName.",
  ui_story_1013_10130302_11_dialog_content = "No entanto, isso apenas prova os méritos da tecnologia.",
  ui_story_1013_10130302_12_dialog_content = "Usando apenas algumas das funções da sala de simulação de Soroz, podemos recriar perfeitamente as condições reais de batalha.",
  ui_story_1013_10130302_13_dialog_content = "Isso é muito melhor do que teoria tediosa e simulações militares!",
  ui_story_1013_10130302_14_dialog_content = "Isso me dá vontade de experimentar!",
  ui_story_1013_10130302_15_dialog_content = "Receio que você terá que esperar por outra hora.",
  ui_story_1013_10130302_16_dialog_content = "Afinal, esta é a tecnologia Caelestite e só pode ser testada por PlayerName agora mesmo.",
  ui_story_1013_10130302_17_dialog_content = "Assim que entendermos completamente o que faz essa tecnologia funcionar, poderemos modificá-la para os aurorianos!",
  ui_story_1013_10130302_18_dialog_content = "Com a pesquisa do Battle Simulator como prioridade máxima, ele estará pronto para nossos exercícios militares conjuntos?",
  ui_story_1013_10130302_19_dialog_content = "Acho que haveria muito mais interesse nos exercícios se pudéssemos implantar essa tecnologia!",
  ui_story_1013_10130302_20_dialog_content = "Não deve ser um problema se PlayerName está aí para ajudar!",
  ui_story_1013_10130302_21_dialog_content = "Exercícios militares conjuntos? O que são aqueles?",
  ui_story_1013_10130302_22_dialog_content = "Treinamento que acontece a cada dois anos!",
  ui_story_1013_10130302_23_dialog_content = "Não é apenas a Federação Illumina que também participa. Lumopolis, Northland e até Umbraton se juntam a eles.",
  ui_story_1013_10130302_24_dialog_content = "Além da colaboração militar em grande escala, cada nação participante também envia seus melhores e mais brilhantes para competir em eventos individuais.",
  ui_story_1013_10130302_25_dialog_content = "Ao final dos exercícios, todos os participantes se engajam contra verdadeiros Eclipsites em uma verdadeira batalha.",
  ui_story_1013_10130302_26_dialog_content = "Parece um evento animado...",
  ui_story_1013_10130302_27_dialog_content = "Muito mesmo!",
  ui_story_1013_10130302_28_dialog_content = "Todo mundo quer ficar em primeiro lugar na competição individual.",
  ui_story_1013_10130302_29_dialog_content = "O vencedor ganha a oportunidade de treinar um contra um com o próprio Grande Marechal Reinhardt!",
  ui_story_1013_10130302_30_dialog_content = "Hã?!",
  ui_story_1013_10130302_31_dialog_content = "Originalmente, era apenas uma coisa do momento. Eu sempre perguntava aos vencedores se eles queriam treinar uma ou duas rodadas.",
  ui_story_1013_10130302_32_dialog_content = "Mas então, parecia se tornar uma parte aceita do programa.",
  ui_story_1013_10130302_33_dialog_content = "Dito isto, eu não gosto disso.",
  ui_story_1013_10130302_34_option_content = "Não te incomoda?",
  ui_story_1013_10130302_35_dialog_content = "Nem um pouco! Na verdade, estou ansioso por isso.",
  ui_story_1013_10130302_36_option_content = "Isso soa como você!",
  ui_story_1013_10130302_37_dialog_content = "Hahaha! Obrigado, vou levar isso como um elogio.",
  ui_story_1013_10130302_38_dialog_content = "Poder cruzar espadas com os melhores da geração mais jovem é um verdadeiro prazer para mim.",
  ui_story_1013_10130302_39_dialog_content = "Observando com meus próprios olhos como eles crescem e ficam mais fortes...",
  ui_story_1013_10130302_40_dialog_content = "Até que chegue o dia em que eles nos ultrapassem e tomem seu lugar de direito como os novos líderes de uma nova era.",
  ui_story_1013_10130302_41_dialog_content = "Eu me emociono só de pensar nisso.",
  ui_story_1013_10130302_42_dialog_content = "Com quem Reinhardt treinou?",
  ui_story_1013_10130302_43_dialog_content = "Acho que a última vencedora do evento individual foi Carleen!",
  ui_story_1013_10130302_44_dialog_content = "Ela estava com mais de dez pontos de vantagem sobre o segundo lugar e fez com que parecesse fácil!",
  ui_story_1013_10130302_45_dialog_content = "Carleen é realmente a melhor da nova geração.",
  ui_story_1013_10130302_46_dialog_content = "Quando brigamos da última vez, ela disse que voltaria para o primeiro lugar na próxima vez também.",
  ui_story_1013_10130302_47_dialog_content = "Aposto que, quando esse dia chegar, ela pode até ser forte o suficiente para me vencer.",
  ui_story_1013_10130302_48_dialog_content = "Hahaha! Estou ansioso para isso!",
  ui_story_1013_10130302_49_dialog_content = "estou com tanta inveja...",
  ui_story_1013_10130302_50_dialog_content = "Eu adoraria a chance de treinar com você, Grande Marechal. Aposto que aprenderia muito!",
  ui_story_1013_10130302_51_dialog_content = "Então treine duro e faça o seu melhor para alcançar o primeiro lugar.",
  ui_story_1013_10130302_52_dialog_content = "Sim!",
  ui_story_1013_10130302_53_dialog_content = "Você também, PlayerName!",
  ui_story_1013_10130302_54_dialog_content = "Eu?!",
  ui_story_1013_10130302_55_dialog_content = "Claro! Não há nenhuma regulamentação que diga que os participantes precisam ser aurorianos.",
  ui_story_1013_10130302_56_dialog_content = "Quando ainda havia celestitas em Astra, eles frequentemente lutavam ao lado dos aurorianos.",
  ui_story_1013_10130302_57_dialog_content = "Se você puder participar, será quase como se os celestitas tivessem voltado.",
  ui_story_1013_10130302_58_dialog_content = "\"Retornou\", hein...",
  ui_story_1013_10130302_59_dialog_content = "E se você vier primeiro, eu luto com você também.",
  ui_story_1013_10130302_60_dialog_content = "Não, não há necessidade!",
  ui_story_1013_10130302_61_dialog_content = "Se eu lutar com você, duvido que sairia vivo...",
  ui_story_1013_10130302_62_dialog_content = "Por que não fazemos uma simulação militar então?",
  ui_story_1013_10130302_63_dialog_content = "Se for apenas uma simulação, eu aceitaria!",
  ui_story_1013_10130302_64_dialog_content = "Excelente! Nesse caso, aguardo sua coroação como campeão!",
  ui_story_1013_10130302_65_dialog_content = "Desculpe interromper sua conversa.",
  ui_story_1013_10130302_66_dialog_content = "Concluímos os experimentos de hoje!",
  ui_story_1013_10130302_67_dialog_content = "Minha equipe e eu precisamos analisar os resultados e ajustar o simulador de acordo. Acho que amanhã poderemos passar para a próxima fase de testes.",
  ui_story_1013_10130302_68_dialog_content = "Deixe com a gente!",
  ui_story_1013_10130302_69_dialog_content = "Tem outra fase?",
  ui_story_1013_10130302_70_dialog_content = "É claro! Hoje envolveu apenas testes preliminares básicos.",
  ui_story_1013_10130302_71_dialog_content = "O Battle Simulator ainda tem muitas funções que precisam ser exploradas!",
  ui_story_1013_10130302_72_dialog_content = "Mas a manutenção do Soroz...",
  ui_story_1013_10130302_73_dialog_content = "Relaxe, não vamos esquecer disso.",
  ui_story_1013_10130302_74_dialog_content = "A manutenção do Soroz e a pesquisa do Battle Simulator podem ser feitas ao mesmo tempo!",
  ui_story_1013_10130302_75_dialog_content = "Mas você precisará nos dar algum tempo.",
  ui_story_1013_10130302_76_dialog_content = "Por favor, seja paciente. Por que não ir e ter um bom descanso?",
  ui_story_1013_10130302_77_dialog_content = "Tudo bem, acho que é tudo que posso fazer por enquanto.",
  ui_story_1013_10130302_78_dialog_content = "Sim. Vamos apenas fazer uma pausa por enquanto.",
  ui_story_1013_10130302_79_dialog_content = "Todo o resto pode esperar até amanhã!",
  ui_story_1013_10130401_1_dialog_content = "<color=#e8d9bb>Rosnar-</color>",
  ui_story_1013_10130401_2_dialog_content = "Estou faminto...",
  ui_story_1013_10130401_3_dialog_content = "<color=#e8d9bb>Growl!</color>",
  ui_story_1013_10130401_4_dialog_content = "Estou com tanta fome!",
  ui_story_1013_10130401_5_dialog_content = "Depois de terminar no centro de pesquisa ontem, Vice me levou para passar uma noite em Gannon City.",
  ui_story_1013_10130401_6_dialog_content = "Não pensei que fosse acordar tão tarde hoje!",
  ui_story_1013_10130401_7_dialog_content = "<color=#e8d9bb>*Estômago roncando*</color>",
  ui_story_1013_10130401_8_dialog_content = "É isso. Tenho que encontrar algo para comer.",
  ui_story_1013_10130401_9_dialog_content = "A cidade é tão grande que tenho certeza de que há muitos lugares para comer.",
  ui_story_1013_10130401_10_dialog_content = "Espero que não seja muito caro, no entanto. Não tenho muito Nightium sobrando.",
  ui_story_1013_10130401_11_dialog_content = "Não.",
  ui_story_1013_10130401_12_dialog_content = "Outro não?",
  ui_story_1013_10130401_13_dialog_content = "Como é que não há literalmente nada?!",
  ui_story_1013_10130401_14_dialog_content = "Andei quilômetros, não encontrei comida e agora estou com mais fome ainda!",
  ui_story_1013_10130401_15_dialog_content = "Eu juro que minha visão já está desaparecendo...",
  ui_story_1013_10130401_16_dialog_content = "Espere! Isso é... comida que eu cheiro?!",
  ui_story_1013_10130401_17_dialog_content = "PlayerName?!",
  ui_story_1013_10130401_18_dialog_content = "Acordar, PlayerName! Você não quer dormir aqui!",
  ui_story_1013_10130401_19_option_content = "V-Vice?!",
  ui_story_1013_10130401_20_dialog_content = "Você está bem? Você não parece muito bem.",
  ui_story_1013_10130401_21_dialog_content = "Estou bem. Bem, na verdade estou morrendo de fome e não consigo encontrar um lugar para comer em qualquer lugar...",
  ui_story_1013_10130401_22_dialog_content = "Eu vaguei em vão por anos, apenas para acabar aqui de volta.",
  ui_story_1013_10130401_23_dialog_content = "Oh, sinto muito! Eu esqueci de mencionar.",
  ui_story_1013_10130401_24_dialog_content = "A Illumina opera com um sistema de racionamento, então não há restaurantes nem nada em Gannon.",
  ui_story_1013_10130401_25_dialog_content = "Se os visitantes precisarem de suprimentos, eles devem ir a uma área designada e passar por todos os obstáculos burocráticos primeiro.",
  ui_story_1013_10130401_26_dialog_content = "Estávamos tão ocupados com os exames ontem que esqueci totalmente de me inscrever...",
  ui_story_1013_10130401_27_dialog_content = "A policial Vivian já providenciou rações para você, então vamos buscá-las quando terminarmos hoje!",
  ui_story_1013_10130401_28_dialog_content = "Parece um pouco complicado.",
  ui_story_1013_10130401_29_dialog_content = "Bem, a produtividade da Federação Illumina é limitada, afinal. Mesmo garantir que todos possam comer não é uma tarefa fácil.",
  ui_story_1013_10130401_30_dialog_content = "As rações são a melhor maneira de evitar o desperdício e garantir que todos tenham o suficiente.",
  ui_story_1013_10130401_31_dialog_content = "Enfim, olha o que eu trouxe! Café da manhã!",
  ui_story_1013_10130401_32_dialog_content = "Aíi está!",
  ui_story_1013_10130401_33_dialog_content = "Então era comida que eu cheirava!",
  ui_story_1013_10130401_34_dialog_content = "Você deve estar morrendo de fome! Venha e coma!",
  ui_story_1013_10130401_35_dialog_content = "Precisamos voltar ao centro de pesquisa daqui a pouco!",
  ui_story_1013_10130401_36_dialog_content = "Estou cavando!",
  ui_story_1013_10130401_37_dialog_content = "(Não fazia ideia de que um lugar aparentemente poderoso como Illumina teria que ser tão cuidadoso com seus recursos.)",
  ui_story_1013_10130401_38_dialog_content = "Não Não Não Não...",
  ui_story_1013_10130401_39_dialog_content = "Isso é melhor! Eu me sinto vivo novamente agora que estou cheio!",
  ui_story_1013_10130401_40_dialog_content = "Sim, eu sempre fico mais feliz na hora das refeições!",
  ui_story_1013_10130401_41_dialog_content = "Já que estamos recarregados, devemos começar com o trabalho do dia.",
  ui_story_1013_10130401_42_dialog_content = "Deveríamos continuar ajudando com o Battle Simulator, certo?",
  ui_story_1013_10130401_43_dialog_content = "Sim. De acordo com os cientistas que trabalharam durante a noite, eles descobriram uma nova função!",
  ui_story_1013_10130401_44_dialog_content = "Devemos dar uma olhada?",
  ui_story_1013_10130401_45_dialog_content = "Claro!",
  ui_story_1013_10130401_46_dialog_content = "<color=#e8d9bb>Centro de Pesquisa Illumina</color>",
  ui_story_1013_10130401_47_dialog_content = "Bom Dia! Vocês dois estão finalmente aqui.",
  ui_story_1013_10130401_48_dialog_content = "Grande marechal?!",
  ui_story_1013_10130401_49_dialog_content = "Você esteve esperando por nós todo esse tempo?",
  ui_story_1013_10130401_50_dialog_content = "Sim. Eu gostaria de ver por mim mesmo como o Battle Simulator funciona.",
  ui_story_1013_10130401_51_dialog_content = "Então, vocês estão todos aqui?",
  ui_story_1013_10130401_52_dialog_content = "Já conseguimos atualizar o Battle Simulator!",
  ui_story_1013_10130401_53_dialog_content = "Isso mesmo! E também temos um nome totalmente atualizado para ele - o Battlefield Simulator!",
  ui_story_1013_10130401_54_option_content = "Campo de batalha?",
  ui_story_1013_10130401_55_dialog_content = "Embora uma sílaba extra não pareça muito, a diferença é realmente enorme!",
  ui_story_1013_10130401_56_option_content = "Que diferença?",
  ui_story_1013_10130401_57_dialog_content = "Um enorme!",
  ui_story_1013_10130401_58_dialog_content = "O Battlefield Simulator se atualizou após a leitura dos dados retirados dos novos módulos de Soroz.",
  ui_story_1013_10130401_59_dialog_content = "Agora, simulações precisas de batalhas históricas podem ser recriadas a partir de registros de combate detalhados!",
  ui_story_1013_10130401_60_dialog_content = "Não apenas o inimigo, mas a hora local, o terreno e até o clima podem ser perfeitamente recriados.",
  ui_story_1013_10130401_61_dialog_content = "Incrível, não é?",
  ui_story_1013_10130401_62_dialog_content = "Então você está dizendo que é capaz de criar batalhas ainda mais realistas?",
  ui_story_1013_10130401_63_dialog_content = "Em teoria, sim.",
  ui_story_1013_10130401_64_dialog_content = "No entanto, como ainda não o configuramos totalmente, você ainda é o único que pode experimentar o Battlefield Simulator.",
  ui_story_1013_10130401_65_dialog_content = "Simmm... voltaremos a contar com vocês hoje!",
  ui_story_1013_10130401_66_dialog_content = "Ainda estou exausto de ontem. Espero que não seja muito difícil hoje.",
  ui_story_1013_10130401_67_dialog_content = "Não se preocupe. Estamos usando dados de batalhas meticulosamente gravados do passado.",
  ui_story_1013_10130401_68_dialog_content = "Será um passeio no parque para alguém com suas habilidades!",
  ui_story_1013_10130401_69_dialog_content = "Boa sorte, PlayerName. Estarei assistindo daqui.",
  ui_story_1013_10130401_70_dialog_content = "T-tudo bem!",
  ui_story_1013_10130401_71_dialog_content = "Agora, coloque o capacete, como ontem...",
  ui_story_1013_10130401_72_dialog_content = "Não parece muito diferente.",
  ui_story_1013_10130401_73_dialog_content = "Paciência! Estamos carregando os dados da batalha agora.",
  ui_story_1013_10130401_74_dialog_content = "Deixe-me ver. Qual devo escolher?",
  ui_story_1013_10130401_75_dialog_content = "Interessante. Que tal este?",
  ui_story_1013_10130401_76_dialog_content = "Eh? Tem certeza, Grande Marechal?",
  ui_story_1013_10130401_77_dialog_content = "Isso não é um pouco...",
  ui_story_1013_10130401_78_dialog_content = "Não precisa se preocupar. Certamente está dentro de suas habilidades.",
  ui_story_1013_10130401_79_dialog_content = "Ele tem experiência neste tipo de ambiente de combate. Tenha fé nele!",
  ui_story_1013_10130401_80_dialog_content = "Sim, senhora!",
  ui_story_1013_10130401_81_dialog_content = "Espere um segundo, Reinhardt!",
  ui_story_1013_10130401_82_dialog_content = "O que exatamente você escolheu?!",
  ui_story_1013_10130401_83_dialog_content = "Você descobrirá em apenas um segundo.",
  ui_story_1013_10130401_84_dialog_content = "Carregando registro de batalha...",
  ui_story_1013_10130401_85_dialog_content = "Campanha encontrada: Dark Zone War.",
  ui_story_1013_10130401_86_dialog_content = "Tudo ficou tão escuro quanto a Noite Eterna!",
  ui_story_1013_10130401_87_dialog_content = "Urgh... Até a sensação horrível de Darkflow está sendo simulada.",
  ui_story_1013_10130401_88_dialog_content = "O que você acha, PlayerName?",
  ui_story_1013_10130401_89_dialog_content = "É certamente realista!",
  ui_story_1013_10130401_90_dialog_content = "Posso até dizer que é um pouco realista demais!",
  ui_story_1013_10130401_91_dialog_content = "Realmente parece uma batalha na Dark Zone, até a sensação desorientadora do Darkflow!",
  ui_story_1013_10130401_92_dialog_content = "Sério? Que ótimo!",
  ui_story_1013_10130401_93_option_content = "O que exatamente é ótimo nisso?!",
  ui_story_1013_10130401_94_dialog_content = "Quanto mais realista pudermos tornar o ambiente de simulação, mais útil será o Battlefield Simulator.",
  ui_story_1013_10130401_95_dialog_content = "Ele fornecerá aos usuários a experiência mais realista que eles podem obter de uma batalha real sem realmente estar em uma; para experimentar pessoalmente as duras e duras realidades da guerra.",
  ui_story_1013_10130401_96_dialog_content = "Também lhes dará a chance de se familiarizar com o campo de batalha e aprimorar suas habilidades em ambientes complexos.",
  ui_story_1013_10130401_97_dialog_content = "Então, quando eles realmente se encontrarem em um conflito real, haverá menos baixas.",
  ui_story_1013_10130401_98_dialog_content = "Faz sentido...",
  ui_story_1013_10130401_99_dialog_content = "Então, por favor, seja o primeiro a experimentá-lo. Lute o quanto quiser e experimente tudo o que o simulador tem a oferecer!",
  ui_story_1013_10130401_100_dialog_content = "Tudo bem, eu estou nisso.",
  ui_story_1013_10130401_101_dialog_content = "OK. Preparando para inicializar a batalha. Prepare-se, PlayerName.",
  ui_story_1013_10130401_102_dialog_content = "Battlefield Simulation Mode, número de série do estágio: 11.328.",
  ui_story_1013_10130401_103_dialog_content = "Objetivo: Atravesse ou elimine os Eclipsites.",
  ui_story_1013_10130401_104_dialog_content = "Simulador inicializando...",
  ui_story_1013_10130401_105_dialog_content = "Graaaah-!",
  ui_story_1013_10130401_106_dialog_content = "Muito bem, vamos começar esta festa.",
  ui_story_1013_10130502_1_dialog_content = "Puxar! Use as pedras como cobertura!",
  ui_story_1013_10130502_2_dialog_content = "...",
  ui_story_1013_10130502_3_dialog_content = "Grr-!",
  ui_story_1013_10130502_4_dialog_content = "Graagh!",
  ui_story_1013_10130502_5_dialog_content = "De onde eles estão vindo?!",
  ui_story_1013_10130502_6_dialog_content = "...!",
  ui_story_1013_10130502_7_dialog_content = "Isso não é bom. Mais um golpe e o Vice estará fora de ação.",
  ui_story_1013_10130502_8_dialog_content = "O que devo fazer? Com tantos Eclipsites, não parece bom...",
  ui_story_1013_10130502_9_dialog_content = "Tudo bem, acalme-se. Se acalme.",
  ui_story_1013_10130502_10_dialog_content = "Olhar em volta. Tem que haver alguma coisa.",
  ui_story_1013_10130502_11_dialog_content = "Vício! Atire naquela pedra que está lá em cima!",
  ui_story_1013_10130502_12_dialog_content = "Rogério.",
  ui_story_1013_10130502_13_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_1013_10130502_14_dialog_content = "Graaahh—",
  ui_story_1013_10130502_15_dialog_content = "Excelente! A pedra rasgou aquele pacote de Eclipsites!",
  ui_story_1013_10130502_16_dialog_content = "Vício, agora! Vamos avançar!",
  ui_story_1013_10130502_17_dialog_content = "Beleza.",
  ui_story_1013_10130502_18_dialog_content = "Lá! Podemos romper esse ponto fraco ali!",
  ui_story_1013_10130502_19_dialog_content = "Consegui!",
  ui_story_1013_10130502_20_dialog_content = "Objetivo do estágio concluído.",
  ui_story_1013_10130502_21_dialog_content = "Teste concluído. Nota do estágio: C.",
  ui_story_1013_10130502_22_dialog_content = "Huff... puff...",
  ui_story_1013_10130502_23_dialog_content = "Isso foi totalmente exaustivo...",
  ui_story_1013_10130502_24_dialog_content = "E só tiramos C?!",
  ui_story_1013_10130502_25_dialog_content = "Bom trabalho, PlayerName.",
  ui_story_1013_10130502_26_dialog_content = "Um segundo, vou desconectar você.",
  ui_story_1013_10130502_27_dialog_content = "Desconectado. É seguro sair agora.",
  ui_story_1013_10130502_28_dialog_content = "Bem feito mesmo, PlayerName!",
  ui_story_1013_10130502_29_dialog_content = "O que você achou da simulação da Dark Zone?",
  ui_story_1013_10130502_30_option_content = "Exaustivo...",
  ui_story_1013_10130502_31_dialog_content = "Mesmo que eu estivesse sentado lá, minhas roupas ainda estavam encharcadas de suor.",
  ui_story_1013_10130502_32_option_content = "Difícil...",
  ui_story_1013_10130502_33_dialog_content = "Eu fiz o meu melhor e usei todas as estratégias que pude pensar...",
  ui_story_1013_10130502_34_dialog_content = "E ainda só tirou um C!",
  ui_story_1013_10130502_35_dialog_content = "Você fez muito bem, embora!",
  ui_story_1013_10130502_36_dialog_content = "Isso mesmo! E você sabe, esta foi uma das próprias batalhas do Grande Marechal.",
  ui_story_1013_10130502_37_dialog_content = "Então, conseguir a pontuação que você obteve já é uma grande conquista.",
  ui_story_1013_10130502_38_dialog_content = "Espere, essa foi uma batalha em que Reinhardt lutou?",
  ui_story_1013_10130502_39_dialog_content = "Qual foi o resultado da luta real?",
  ui_story_1013_10130502_40_dialog_content = "Deixe-me verificar os registros...",
  ui_story_1013_10130502_41_dialog_content = "Entendi! Diz aqui que ela conseguiu derrotar 50 Eclipsites, E romper, recebendo apenas ferimentos leves no processo.",
  ui_story_1013_10130502_42_dialog_content = "Esse é provavelmente o critério do simulador para um A ou superior.",
  ui_story_1013_10130502_43_dialog_content = "Surpreendente!",
  ui_story_1013_10130502_44_dialog_content = "Para conseguir isso, especialmente na Dark Zone.",
  ui_story_1013_10130502_45_dialog_content = "Como esperado do Grande Marechal!",
  ui_story_1013_10130502_46_dialog_content = "Suspiro ... Eu estava lutando apenas para completá-lo.",
  ui_story_1013_10130502_47_dialog_content = "Dê a si mesmo algum crédito, PlayerName.",
  ui_story_1013_10130502_48_dialog_content = "Esta é apenas a sua segunda vez lutando dentro da Zona Cega. O que você realizou já é muito impressionante.",
  ui_story_1013_10130502_49_dialog_content = "Em comparação com a última vez, você levou mais em consideração o ambiente e o usou a seu favor.",
  ui_story_1013_10130502_50_dialog_content = "Além disso, você conseguiu completar a batalha sem suporte adicional.",
  ui_story_1013_10130502_51_dialog_content = "Você melhorou muito, o que merece elogios!",
  ui_story_1013_10130502_52_dialog_content = "O-obrigado?",
  ui_story_1013_10130502_53_dialog_content = "Se ao menos a Federação Illumina tivesse mais comandantes como você...",
  ui_story_1013_10130502_54_dialog_content = "Nossas batalhas contra os eclipsitas seriam muito mais tranquilas.",
  ui_story_1013_10130502_55_dialog_content = "Agora que penso nisso, PlayerName já tinha uma forte compreensão de comando quando nos conhecemos.",
  ui_story_1013_10130502_56_option_content = "Obrigado Soroz.",
  ui_story_1013_10130502_57_option_content = "Fui ensinado desde muito jovem.",
  ui_story_1013_10130502_58_dialog_content = "Hum?",
  ui_story_1013_10130502_59_dialog_content = "Soroz me ensinou muito nos 17 anos que passei na clandestinidade.",
  ui_story_1013_10130502_60_dialog_content = "Incluindo o que é preciso para ser um bom comandante no campo de batalha.",
  ui_story_1013_10130502_61_dialog_content = "Os caelestitas incluem o comando no campo de batalha em seu currículo acadêmico...?",
  ui_story_1013_10130502_62_dialog_content = "Mas eu pensei que os celestitas eram uma raça amante da paz?",
  ui_story_1013_10130502_63_dialog_content = "Hum. Pensando bem, esse conhecimento provavelmente veio da mesma fonte dos dados do Obelisco do Retorno.",
  ui_story_1013_10130502_64_dialog_content = "Eu...",
  ui_story_1013_10130502_65_dialog_content = "Você duvida de si mesmo, PlayerName?",
  ui_story_1013_10130502_66_dialog_content = "... Não. Eu já pensei nisso.",
  ui_story_1013_10130502_67_dialog_content = "Ah?",
  ui_story_1013_10130502_68_dialog_content = "Independentemente de onde adquiri esse conhecimento, ele é meu.",
  ui_story_1013_10130502_69_dialog_content = "Só a usarei para proteger meus companheiros; não para qualquer propósito nefasto.",
  ui_story_1013_10130502_70_dialog_content = "Ahahaha! Ficamos pouco tempo separados, mas parece que você amadureceu muito!",
  ui_story_1013_10130502_71_dialog_content = "S-Sério?",
  ui_story_1013_10130502_72_dialog_content = "Muito mesmo!",
  ui_story_1013_10130502_73_dialog_content = "Depois do incidente de Eraveil da última vez, achei que você parecia um pouco pior pelo desgaste. Na verdade, fiquei preocupado por um tempo.",
  ui_story_1013_10130502_74_dialog_content = "Mas agora parece que tais preocupações foram equivocadas.",
  ui_story_1013_10130502_75_dialog_content = "Não me subestime!",
  ui_story_1013_10130502_76_dialog_content = "Não, eu certamente não vou.",
  ui_story_1013_10130502_77_dialog_content = "É uma pena, no entanto. Eu tinha meu discurso reconfortante todo preparado, mas no final do dia, você nem precisava disso.",
  ui_story_1013_10130502_78_dialog_content = "Huh? Fala?",
  ui_story_1013_10130502_79_dialog_content = "Bem, mais como um velho Illumina dizendo:",
  ui_story_1013_10130502_80_dialog_content = "\"Não há bem ou mal inerente na ciência e na tecnologia, mas apenas nos corações dos aurorianos que os manejam.\"",
  ui_story_1013_10130502_81_dialog_content = "Hã...",
  ui_story_1013_10130502_82_dialog_content = "É meio difícil imaginar essas palavras saindo da sua boca.",
  ui_story_1013_10130502_83_dialog_content = "Bem, não são minhas palavras! Estou apenas repassando o que aqueles velhos pedantes costumavam me dizer.",
  ui_story_1013_10130502_84_dialog_content = "Entendi.",
  ui_story_1013_10130502_85_dialog_content = "Independentemente disso, estou muito feliz em vê-lo capaz de seguir em frente tão rapidamente.",
  ui_story_1013_10130502_86_dialog_content = "Embora eu não possa ajudá-lo desta vez, não hesite em me procurar se precisar de algo no futuro.",
  ui_story_1013_10130502_87_dialog_content = "Vou ajudá-lo da maneira que puder.",
  ui_story_1013_10130502_88_dialog_content = "Mas não sou a pessoa mais eloquente, então posso não ter conselhos úteis para você.",
  ui_story_1013_10130502_89_dialog_content = "Apenas sua oferta já é muito comovente.",
  ui_story_1013_10130502_90_dialog_content = "Ah, pensando bem, ainda estou bastante preocupado com Soroz...",
  ui_story_1013_10130502_91_dialog_content = "Sim. Fizemos tudo o que devíamos fazer. Encontramos o módulo e voltamos ao Obelisco do Retorno para reparos.",
  ui_story_1013_10130502_92_dialog_content = "Mas por que Soroz ainda não acordou?",
  ui_story_1013_10130502_93_dialog_content = "Está além do nosso controle agora.",
  ui_story_1013_10130502_94_dialog_content = "Mesmo a Federação Illumina, conhecida por sua tecnologia avançada, não pesquisou realmente a inteligência artificial.",
  ui_story_1013_10130502_95_dialog_content = "A consciência de um Colosso também é muito diferente das formas mais comuns de IA",
  ui_story_1013_10130502_96_dialog_content = "Tenho certeza de que descobriremos mais à medida que continuarmos nossa pesquisa!",
  ui_story_1013_10130502_97_dialog_content = "De qualquer forma, vamos seguir em frente por enquanto, porque tenho boas notícias se você quiser ouvir.",
  ui_story_1013_10130502_98_dialog_content = "O que foi?",
  ui_story_1013_10130502_99_dialog_content = "Encontramos alguns registros de batalha no novo módulo de Soroz.",
  ui_story_1013_10130502_100_dialog_content = "Esses registros são provavelmente tão antigos quanto o Colosso e o Obelisco do Retorno.",
  ui_story_1013_10130502_101_dialog_content = "Ei, nada de roubar minhas falas!",
  ui_story_1013_10130502_102_dialog_content = "Acreditamos que será possível coletar informações sobre os Colossos a partir desses registros.",
  ui_story_1013_10130502_103_dialog_content = "Presumo que você gostaria de ver seu Colossus consertado, cobaia?",
  ui_story_1013_10130502_104_dialog_content = "... Apenas me diga o que fazer.",
  ui_story_1013_10130502_105_dialog_content = "Carregaremos esses dados antigos no simulador de campo de batalha e executaremos um sim.",
  ui_story_1013_10130502_106_dialog_content = "Tudo que você precisa fazer é lutar naquele sim.",
  ui_story_1013_10130502_107_dialog_content = "Estaremos observando de fora e coletando os dados de que precisamos.",
  ui_story_1013_10130502_108_dialog_content = "E obviamente, PlayerName, estaremos lhe dando toda a ajuda e orientação que pudermos.",
  ui_story_1013_10130502_109_dialog_content = "Afinal, não estamos testando suas habilidades aqui. Isso é tudo sobre a coleta de dados.",
  ui_story_1013_10130502_110_dialog_content = "No entanto, esta é a primeira vez que carregamos dados como este no simulador.",
  ui_story_1013_10130502_111_dialog_content = "Eu recomendo ser mais cauteloso.",
  ui_story_1013_10130502_112_dialog_content = "Entendi. Se esta é a maneira mais rápida de consertar Soroz, estou dentro.",
  ui_story_1013_10130502_113_dialog_content = "Vamos começar.",
  ui_story_1013_10130502_114_dialog_content = "Coisa certa. Sente-se na cadeira e coloque o capacete, como antes.",
  ui_story_1013_10130601_1_dialog_content = "Onde... onde é isso?",
  ui_story_1013_10130601_2_dialog_content = "Parece uma cidade.",
  ui_story_1013_10130601_3_dialog_content = "O que aconteceu com o deserto?",
  ui_story_1013_10130601_4_dialog_content = "Esquisito.",
  ui_story_1013_10130601_5_dialog_content = "Ei! Vice, Reinhardt, você pode me ouvir?",
  ui_story_1013_10130601_6_dialog_content = "...",
  ui_story_1013_10130601_7_dialog_content = "Como é que eles não estão respondendo?",
  ui_story_1013_10130601_8_dialog_content = "Certamente o simulador não pode ter funcionado mal?",
  ui_story_1013_10130601_9_dialog_content = "<color=#e8d9bb>fora do sim</color>",
  ui_story_1013_10130601_10_dialog_content = "PlayerName?",
  ui_story_1013_10130601_11_dialog_content = "Ei, PlayerName! Você pode me ouvir?",
  ui_story_1013_10130601_12_dialog_content = "O que está acontecendo? Perdemos a conexão?",
  ui_story_1013_10130601_13_dialog_content = "Eu sinto Muito. Nós também não sabemos!",
  ui_story_1013_10130601_14_dialog_content = "O simulador não está relatando nenhum erro. E podemos ver o que PlayerName está experimentando.",
  ui_story_1013_10130601_15_dialog_content = "Mas não podemos nos comunicar com ele.",
  ui_story_1013_10130601_16_dialog_content = "Mas por que!?",
  ui_story_1013_10130601_17_dialog_content = "Rápido, tire-o do sim!",
  ui_story_1013_10130601_18_dialog_content = "Não podemos deixá-lo em risco.",
  ui_story_1013_10130601_19_dialog_content = "S-Sim!",
  ui_story_1013_10130601_20_dialog_content = "Hã?",
  ui_story_1013_10130601_21_dialog_content = "Não consigo cortar a conexão. Mas por que?",
  ui_story_1013_10130601_22_dialog_content = "O que foi agora?",
  ui_story_1013_10130601_23_dialog_content = "Me desculpe. Mas não consigo explicar.",
  ui_story_1013_10130601_24_dialog_content = "Será... Será PlayerName fique bem?",
  ui_story_1013_10130601_25_dialog_content = "Por que o simulador falharia tão repentinamente?",
  ui_story_1013_10130601_26_dialog_content = "Nada como isso aconteceu antes.",
  ui_story_1013_10130601_27_dialog_content = "Talvez seja porque usamos os dados de batalha de Soroz.",
  ui_story_1013_10130601_28_dialog_content = "Poderíamos forçar o sim a terminar tirando o capacete?",
  ui_story_1013_10130601_29_dialog_content = "Isso seria desaconselhável, Grande Marechal.",
  ui_story_1013_10130601_30_dialog_content = "Huh? Achei que você estava olhando para o equipamento médico. O que você está fazendo aqui?",
  ui_story_1013_10130601_31_dialog_content = "Você precisa de um biólogo para descobrir o que está acontecendo com a criança. Então aqui estou.",
  ui_story_1013_10130601_32_dialog_content = "Você tem razão. Então, o que você pode nos dizer sobre o que está acontecendo com PlayerName?",
  ui_story_1013_10130601_33_dialog_content = "Nada, até que eu tenha feito um exame adequado.",
  ui_story_1013_10130601_34_dialog_content = "Mas posso dizer que as coisas não parecem boas. Quando o simulador está rodando, ele forma um link com a consciência do usuário.",
  ui_story_1013_10130601_35_dialog_content = "Se cortarmos esse elo à força, ele passará o resto da vida numa cama de hospital.",
  ui_story_1013_10130601_36_dialog_content = "Como na Terra...",
  ui_story_1013_10130601_37_dialog_content = "Mas também não podemos simplesmente deixá-lo lá.",
  ui_story_1013_10130601_38_dialog_content = "Não há nada que possamos fazer daqui?",
  ui_story_1013_10130601_39_dialog_content = "Fique calmo, Tenente Vice.",
  ui_story_1013_10130601_40_dialog_content = "Tudo o que você pode fazer por enquanto é ficar fora do nosso caminho enquanto pensamos em como ajudá-lo.",
  ui_story_1013_10130601_41_dialog_content = "Então continue fazendo o que puder para ajudar PlayerName.",
  ui_story_1013_10130601_42_dialog_content = "Tire-o do simulador com segurança e o mais rápido possível.",
  ui_story_1013_10130601_43_dialog_content = "<color=#e8d9bb>De volta ao sim</color>",
  ui_story_1013_10130601_44_dialog_content = "O que tá acontecendo aqui?",
  ui_story_1013_10130601_45_dialog_content = "Não consigo falar com os pesquisadores lá fora. Não ouvi nada que indique que o estágio está começando.",
  ui_story_1013_10130601_46_dialog_content = "E onde é isso? Não é Illumina ou Lumopolis.",
  ui_story_1013_10130601_47_dialog_content = "Lembro que os pesquisadores disseram que os dados vinham do novo módulo Soroz.",
  ui_story_1013_10130601_48_dialog_content = "Isso significa que estou olhando para...",
  ui_story_1013_10130601_49_option_content = "Uma cidade antiga?",
  ui_story_1013_10130601_50_dialog_content = "Corram!",
  ui_story_1013_10130601_51_dialog_content = "Huh? Por que aquelas pessoas estão correndo na minha direção?",
  ui_story_1013_10130601_52_dialog_content = "Corra agora! Não seja pego!",
  ui_story_1013_10130601_53_dialog_content = "Espere! O que está acontecendo?",
  ui_story_1013_10130601_54_dialog_content = "Aaah! Eles estão vindo!",
  ui_story_1013_10130601_55_dialog_content = "Quem vem? O que está acontecendo?",
  ui_story_1013_10130601_56_dialog_content = "Espere, isso é Darkflow?",
  ui_story_1013_10130601_57_dialog_content = "Graaaaaah!",
  ui_story_1013_10130601_58_dialog_content = "Eek! Vício!",
  ui_story_1013_10130601_59_dialog_content = "...",
  ui_story_1013_10130601_60_dialog_content = "Felizmente, meu subconsciente criou um Vício imaginário para mim bem na hora...",
  ui_story_1013_10130601_61_dialog_content = "Proteja os civis! Fique em formação!",
  ui_story_1013_10130601_62_dialog_content = "Não temos nada a temer dos Eclipsitas.",
  ui_story_1013_10130601_63_dialog_content = "Levante suas armas e fique por perto!",
  ui_story_1013_10130601_64_dialog_content = "Carregar!!!",
  ui_story_1013_10130601_65_dialog_content = "Grrr!",
  ui_story_1013_10130601_66_dialog_content = "Aqueles são aurorianos? Eles estão lutando contra os Eclipsites com Luminatics...",
  ui_story_1013_10130601_67_dialog_content = "Mas parece tão fraco.",
  ui_story_1013_10130601_68_dialog_content = "Não está causando nenhum dano aos Eclipsites.",
  ui_story_1013_10130601_69_dialog_content = "Grrr!",
  ui_story_1013_10130601_70_dialog_content = "Ugh!",
  ui_story_1013_10130601_71_option_content = "Recuar!",
  ui_story_1013_10130601_72_dialog_content = "Você não pode vencer esses Eclipsites!",
  ui_story_1013_10130601_73_dialog_content = "Não há mais para onde voltar.",
  ui_story_1013_10130601_74_dialog_content = "Eles já estão à nossa porta.",
  ui_story_1013_10130601_75_dialog_content = "Ei! Corra antes que eles te matem!",
  ui_story_1013_10130601_76_dialog_content = "Carregar!!!",
  ui_story_1013_10130601_77_dialog_content = "Grah!!!",
  ui_story_1013_10130601_78_dialog_content = "Vice, ajude-os!",
  ui_story_1013_10130601_79_dialog_content = "Vai fazer!",
  ui_story_1013_10130602_1_dialog_content = "<color=#e8d9bb>fora do sim</color>",
  ui_story_1013_10130602_2_dialog_content = "Como é PlayerName fazendo?",
  ui_story_1013_10130602_3_dialog_content = "Ainda estamos analisando a situação.",
  ui_story_1013_10130602_4_dialog_content = "O sujeito permanece estável e percebeu que algo está errado.",
  ui_story_1013_10130602_5_dialog_content = "Ele está lutando com os Eclipsitas. E isso nos dá tempo.",
  ui_story_1013_10130602_6_dialog_content = "Confie no Navegador para ajudar à sua maneira!",
  ui_story_1013_10130602_7_dialog_content = "Não deixe que seus esforços sejam desperdiçados. Continue trabalhando na análise dos dados!",
  ui_story_1013_10130602_8_dialog_content = "Entendido!",
  ui_story_1013_10130602_9_dialog_content = "Grande Marechal, encontramos algo durante nossa análise.",
  ui_story_1013_10130602_10_dialog_content = "Continue.",
  ui_story_1013_10130602_11_dialog_content = "Analisamos a cena que está acontecendo no simulador.",
  ui_story_1013_10130602_12_dialog_content = "Os prédios não combinam com o estilo arquitetônico auroriano moderno.",
  ui_story_1013_10130602_13_dialog_content = "Mas eles são idênticos aos que Siobhan encontrou em uma antiga cidade subterrânea.",
  ui_story_1013_10130602_14_dialog_content = "Achamos que os dados são anteriores aos aurorianos.",
  ui_story_1013_10130602_15_dialog_content = "Ele remonta a um período da história que há muito foi esquecido.",
  ui_story_1013_10130602_16_dialog_content = "História antiga, hein...",
  ui_story_1013_10130602_17_dialog_content = "Continue gravando.",
  ui_story_1013_10130602_18_dialog_content = "Os dados do sim provavelmente serão capazes de nos fornecer um trecho da história daquela época.",
  ui_story_1013_10130602_19_dialog_content = "E fique de olho no que está acontecendo com o Navigator. Talvez possamos identificar algo que nos ajude a tirá-lo de lá.",
  ui_story_1013_10130602_20_dialog_content = "<color=#e8d9bb>De volta ao sim</color>",
  ui_story_1013_10130602_21_dialog_content = "O que está acontecendo? O palco nem começou, mas os Eclipsites já estão aqui...",
  ui_story_1013_10130602_22_dialog_content = "Algo está muito errado. Acho que o simulador deve ter avariado.",
  ui_story_1013_10130602_23_dialog_content = "Aahhhhhh!",
  ui_story_1013_10130602_24_dialog_content = "...",
  ui_story_1013_10130602_25_dialog_content = "Eles continuam vindo. Isso nunca vai acabar?",
  ui_story_1013_10130602_26_dialog_content = "Estou sozinho aqui com um Vício imaginário.",
  ui_story_1013_10130602_27_dialog_content = "Não consigo ouvir nenhuma comunicação dos meus companheiros. Nem mesmo Soroz está aqui comigo.",
  ui_story_1013_10130602_28_dialog_content = "Como vou acabar com essa estranha situação...",
  ui_story_1013_10130602_29_dialog_content = "E se eu deixar os Eclipsites me matarem? Talvez isso desencadeasse as condições de falha e a simulação terminasse?",
  ui_story_1013_10130602_30_dialog_content = "No entanto, esta é a primeira vez que carregamos dados como este no simulador.",
  ui_story_1013_10130602_31_dialog_content = "Eu recomendo ser mais cauteloso.",
  ui_story_1013_10130602_32_dialog_content = "Não, não posso arriscar fazer nada precipitado.",
  ui_story_1013_10130602_33_dialog_content = "Há algo estranho acontecendo com o simulador. Qualquer coisa que eu faça pode ter consequências inesperadas.",
  ui_story_1013_10130602_34_dialog_content = "E... bem, não estou sozinho, estou?",
  ui_story_1013_10130602_35_dialog_content = "Vice e os outros devem ter notado que algo está errado. Eles estarão tentando ajudar.",
  ui_story_1013_10130602_36_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_1013_10130602_37_dialog_content = "O que agora!?",
  ui_story_1013_10130602_38_dialog_content = "<color=#e8d9bb>BUM!</color>",
  ui_story_1013_10130602_39_dialog_content = "É um terremoto?",
  ui_story_1013_10130602_40_dialog_content = "Espere, tudo... tudo está desmoronando!?",
  ui_story_1013_10130602_41_dialog_content = "<color=#e8d9bb>ESTRONDO-!!</color>",
  ui_story_1013_10130602_42_dialog_content = "Retiro! Volte, agora!",
  ui_story_1013_10130602_43_dialog_content = "Os demônios estão chegando!",
  ui_story_1013_10130602_44_dialog_content = "Demônios?!",
  ui_story_1013_10130602_45_dialog_content = "Uau! Minha cabeça!",
  ui_story_1013_10130602_46_dialog_content = "Eu tenho que sair daqui...",
  ui_story_1013_10130602_47_dialog_content = "PlayerName.",
  ui_story_1013_10130602_48_dialog_content = "Acordar.",
  ui_story_1013_10130602_49_dialog_content = "Você não pode sair ainda.",
  ui_story_1013_10130602_50_dialog_content = "Tudo mudou de novo!",
  ui_story_1013_10130602_51_dialog_content = "Há hordas de Eclipsites à distância!",
  ui_story_1013_10130602_52_dialog_content = "E aquelas sombras no céu são... Colossos!",
  ui_story_1013_10130602_53_dialog_content = "Eclipsitas cavalgando Colossos e lutando contra Aurorianos...",
  ui_story_1013_10130602_54_dialog_content = "Os registros no Obelisco do Retorno eram verdadeiros...",
  ui_story_1013_10130602_55_dialog_content = "Atenção, todas as tropas de combate—",
  ui_story_1013_10130602_56_dialog_content = "Isso é uma transmissão?",
  ui_story_1013_10130602_57_dialog_content = "Segure a linha e mantenha a resistência.",
  ui_story_1013_10130602_58_dialog_content = "A humanidade deve derrotar os demônios.",
  ui_story_1013_10130602_59_option_content = "\"Demônios\"?",
  ui_story_1013_10130602_60_dialog_content = "Alguém estava gritando sobre demônios mais cedo. Eles se referiam aos Eclipsitos?",
  ui_story_1013_10130602_61_option_content = "\"Humanidade\"?",
  ui_story_1013_10130602_62_dialog_content = "O que é \"humanidade\"? Não deveria ser \"Aurorianos\"?",
  ui_story_1013_10130602_63_dialog_content = "Vocês todos ouviram isso? Devemos permanecer firmes!",
  ui_story_1013_10130602_64_dialog_content = "Segure a linha! Pela nossa pátria!",
  ui_story_1013_10130602_65_dialog_content = "Não, espere! Volte!",
  ui_story_1013_10130602_66_dialog_content = "Você não é forte o suficiente para lutar contra os Eclipsites. É uma missão suicida!",
  ui_story_1013_10130602_67_dialog_content = "Se você não está lutando, saia do caminho!",
  ui_story_1013_10130602_68_dialog_content = "Carregar! Mate os Eclipsitas! Obliterar os demônios!",
  ui_story_1013_10130602_69_dialog_content = "Fique firme. Nem um passo atrás.",
  ui_story_1013_10130602_70_dialog_content = "A humanidade deve ser vitoriosa.",
  ui_story_1013_10130602_71_dialog_content = "Grah!!!",
  ui_story_1013_10130602_72_dialog_content = "Urgh...!",
  ui_story_1013_10130602_73_dialog_content = "Não podemos... recuar!",
  ui_story_1013_10130602_74_dialog_content = "Para!!!",
  ui_story_1013_10130602_75_dialog_content = "Continue lutando. Perseverar!",
  ui_story_1013_10130602_76_dialog_content = "O que diabos essa emissora está tentando fazer? Como eles podem enviar pessoas para a morte tão facilmente?",
  ui_story_1013_10130602_77_dialog_content = "<color=#e8d9bb>Tzzst—</color>",
  ui_story_1013_10130602_78_dialog_content = "Carregando... gravar...",
  ui_story_1013_10130602_79_dialog_content = "Esse é o Battlefield Simulator!",
  ui_story_1013_10130602_80_dialog_content = "Ele finalmente recuperou suas funções?",
  ui_story_1013_10130602_81_dialog_content = "Campanha...: ... iminente.",
  ui_story_1013_10130602_82_dialog_content = "Batalha... número de série: Erro.",
  ui_story_1013_10130602_83_dialog_content = "Objetivo: Recuar... terreno seguro.",
  ui_story_1013_10130602_84_dialog_content = "Retiro? Existem Eclipsites em todos os lugares. Para onde devo recuar?",
  ui_story_1013_10130602_85_dialog_content = "Você aí!",
  ui_story_1013_10130602_86_dialog_content = "Corra dessa maneira. É seguro lá atrás. Os soldados irão protegê-lo.",
  ui_story_1013_10130602_87_dialog_content = "E não desista. A humanidade prevalecerá sobre os demônios!",
  ui_story_1013_10130602_88_dialog_content = "Acho que devo correr na direção oposta de onde os Eclipsites estão vindo.",
  ui_story_1013_10130602_89_dialog_content = "O Battlefield Simulator é tão realista que quase esqueci...",
  ui_story_1013_10130602_90_dialog_content = "que tudo que estou vendo agora é um registro do passado.",
  ui_story_1013_10130602_91_dialog_content = "E isso significa que não há como eu mudar nada.",
  ui_story_1013_10130602_92_dialog_content = "Tudo o que posso fazer é terminar a etapa para que tudo acabe.",
  ui_story_1013_10130602_93_dialog_content = "Simulador inicializando...",
  ui_story_1013_10130701_1_dialog_content = "Arf, arf...",
  ui_story_1013_10130701_2_dialog_content = "(Não tenho ideia de que caminho devo seguir.)",
  ui_story_1013_10130701_3_dialog_content = "(Mas seguir esses soldados deve ser bom.)",
  ui_story_1013_10130701_4_dialog_content = "Ei, você aí! Proteja-se aqui embaixo.",
  ui_story_1013_10130701_5_dialog_content = "T-tudo bem!",
  ui_story_1013_10130701_6_dialog_content = "Hã?",
  ui_story_1013_10130701_7_dialog_content = "(Há algumas pessoas lá em cima que não estão correndo.)",
  ui_story_1013_10130701_8_dialog_content = "(Eles estão feridos?)",
  ui_story_1013_10130701_9_dialog_content = "Repito: Continue lutando e continue avançando!",
  ui_story_1013_10130701_10_dialog_content = "Alô, alguém está ferido? Alguém precisa de ajuda?",
  ui_story_1013_10130701_11_dialog_content = "É muito perigoso aqui. Vou levá-lo para a segurança!",
  ui_story_1013_10130701_12_dialog_content = "Huh? O que é...?",
  ui_story_1013_10130701_13_dialog_content = "(Essa estranha aura de arco-íris na qual eles estão envolvidos é da mesma cor de Lumina.)",
  ui_story_1013_10130701_14_dialog_content = "(Eles poderiam... ser aurorianos?)",
  ui_story_1013_10130701_15_dialog_content = "O Deus da Luz não nos concede aurora aeterna: uma vida livre de dores e preocupações.",
  ui_story_1013_10130701_16_dialog_content = "O Deus da Luz não nos concede dias eternos: um mundo livre de guerras e turbulências.",
  ui_story_1013_10130701_17_dialog_content = "O Deus da Luz nos concede força e coragem, sabedoria e desenvoltura, e compaixão por todos...",
  ui_story_1013_10130701_18_dialog_content = "para que possamos enfrentar nossas dificuldades com coragem infinita, sabedoria suprema e amor eterno.",
  ui_story_1013_10130701_19_dialog_content = "(Parece que eles estão rezando - mas para quem e para quê?)",
  ui_story_1013_10130701_20_dialog_content = "<color=#e8d9bb>Estrondo-!!!</color>",
  ui_story_1013_10130701_21_dialog_content = "A batalha está se expandindo rapidamente. Todo o pessoal, siga as instruções e retire-se para um local seguro.",
  ui_story_1013_10130701_22_dialog_content = "Este é o aviso final. Evacue todas as áreas onde os demônios possam aparecer.",
  ui_story_1013_10130701_23_dialog_content = "Grah!!!",
  ui_story_1013_10130701_24_dialog_content = "Merda, eu tenho que me apressar—",
  ui_story_1013_10130701_25_dialog_content = "Graah—!",
  ui_story_1013_10130701_26_dialog_content = "Os enviados da Luz nunca precisam temer a escuridão.",
  ui_story_1013_10130701_27_dialog_content = "Permanecemos aqui para forçar os demônios nascidos das trevas a recuar.",
  ui_story_1013_10130701_28_dialog_content = "Criança, vá, rápido! Não deixe que eles peguem você. Muitos já morreram.",
  ui_story_1013_10130701_29_option_content = "Não, eu posso te ajudar.",
  ui_story_1013_10130701_30_dialog_content = "Se você estiver disposto a confiar em mim e permitir que eu faça contato com sua consciência...",
  ui_story_1013_10130701_31_dialog_content = "Sou capaz de navegar pelos aurorianos em batalha. Deixe-me ajudar para que você possa usar melhor seu poder e aproveitar a chance de vitória!",
  ui_story_1013_10130701_32_option_content = "Não, você tem que vir comigo.",
  ui_story_1013_10130701_33_dialog_content = "Esta não é uma batalha que quatro aurorianos podem vencer sozinhos.",
  ui_story_1013_10130701_34_dialog_content = "Venha comigo para encontrar um lugar para se proteger. Não temos outra escolha.",
  ui_story_1013_10130701_35_dialog_content = "\"Aurorianos\"? Não faço ideia do que você está falando...",
  ui_story_1013_10130701_36_dialog_content = "Aqui não é lugar para criança. Fique em segurança!",
  ui_story_1013_10130701_37_dialog_content = "Ah, e você não é criança!?",
  ui_story_1013_10130701_38_dialog_content = "Você não pode determinar a idade de um Enviado da Luz pela aparência.",
  ui_story_1013_10130701_39_dialog_content = "Somente aqueles habilidosos no uso de Lumina podem resistir e lutar aqui.",
  ui_story_1013_10130701_40_dialog_content = "Em momentos como este, devemos <color=#FFB400>seguir devotamente</color> os ensinamentos do Deus da Luz.",
  ui_story_1013_10130701_41_dialog_content = "Quer dizer que...",
  ui_story_1013_10130701_42_dialog_content = "Concordou. Não podemos mais usar nenhuma de nossas preocupações como desculpa para não usar o poder em nossas mãos.",
  ui_story_1013_10130701_43_dialog_content = "Afaste-se, garoto, se não quiser ser arrastado por uma onda de luz.",
  ui_story_1013_10130701_44_dialog_content = "Muito bem. Temo que nos arrependeremos se não o fizermos.",
  ui_story_1013_10130701_45_dialog_content = "Os demônios estão se aproximando rapidamente de lá.",
  ui_story_1013_10130701_46_dialog_content = "Aproveitemos este último raio de luz.",
  ui_story_1013_10130701_47_dialog_content = "A luz nos pertence!",
  ui_story_1013_10130701_48_dialog_content = "S-Que forte Lumina!",
  ui_story_1013_10130701_49_dialog_content = "Graaaah—",
  ui_story_1013_10130701_50_dialog_content = "Ahhhhhhh!",
  ui_story_1013_10130701_51_dialog_content = "O que-",
  ui_story_1013_10130701_52_dialog_content = "(Eles deveriam ganhar a vantagem, mas isso... tudo que vejo diante de mim é uma cena de um pesadelo.)",
  ui_story_1013_10130701_53_dialog_content = "(Os raios de luz estão matando todos, Eclipsitas e Aurorianos!)",
  ui_story_1013_10130701_54_dialog_content = "(Eu não posso esperar. Isso significa... eu também irei...)",
  ui_story_1013_10130701_55_dialog_content = "<color=#e8d9bb>BUM!</color>",
  ui_story_1013_10130701_56_dialog_content = "Arf, arf...",
  ui_story_1013_10130701_57_dialog_content = "Zumbido—Buzz—",
  ui_story_1013_10130701_58_dialog_content = "Acabou... acabou?",
  ui_story_1013_10130701_59_option_content = "Aumento de Força",
  ui_story_1013_10130701_60_dialog_content = "Não consigo mais sentir o Darkflow. Apenas um silêncio mortal.",
  ui_story_1013_10130701_61_dialog_content = "Foi assim que o mundo anterior acabou?",
  ui_story_1013_10130701_62_dialog_content = "Espere!",
  ui_story_1013_10130701_63_dialog_content = "Algo está rastejando para fora do chão!",
  ui_story_1013_10130701_64_dialog_content = "<color=#e8d9bb>Farfalhar—</color>",
  ui_story_1013_10130701_65_dialog_content = "Silvo-!!!",
  ui_story_1013_10130701_66_dialog_content = "Essa não!",
  ui_story_1013_10130701_67_dialog_content = "(Estava sempre lá embaixo? Isso permitiu que ele sobrevivesse à catástrofe?)",
  ui_story_1013_10130701_68_dialog_content = "(vou terminar!)",
  ui_story_1013_10130702_1_dialog_content = "Silvo-!!!",
  ui_story_1013_10130702_2_dialog_content = "Eu não posso vencê-lo!",
  ui_story_1013_10130702_3_dialog_content = "Seu corpo parece estar ficando ainda maior.",
  ui_story_1013_10130702_4_dialog_content = "Mas os Eclipsites não podem se regenerar no local assim. É um erro de simulação?",
  ui_story_1013_10130702_5_dialog_content = "Sibilo—",
  ui_story_1013_10130702_6_dialog_content = "O-o que quer que esteja acontecendo, preciso entrar em contato com os pesquisadores.",
  ui_story_1013_10130702_7_dialog_content = "Eu não vou morrer aqui!",
  ui_story_1013_10130702_8_dialog_content = "Pesquisadores! Esta ouvindo? Por favor responda!",
  ui_story_1013_10130702_9_dialog_content = "Repito: Pesquisadores! Esta ouvindo? Por favor responda!",
  ui_story_1013_10130702_10_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10130702_11_dialog_content = "O-O que posso fazer...",
  ui_story_1013_10130702_12_dialog_content = "O que mais posso tentar?",
  ui_story_1013_10130702_13_dialog_content = "<color=#e8d9bb>Rachadura-</color>",
  ui_story_1013_10130702_14_dialog_content = "Eu... realmente vou morrer aqui?",
  ui_story_1013_10130702_15_dialog_content = "Eu...",
  ui_story_1013_10130702_16_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_1013_10130702_17_dialog_content = "\"Sistema de controle primário... normal.\"",
  ui_story_1013_10130702_18_dialog_content = "\"Módulos biológicos... normais.\"",
  ui_story_1013_10130702_19_dialog_content = "\"Suporte de vida... operacional. Capacidade atual: 1 pessoa.\"",
  ui_story_1013_10130702_20_dialog_content = "\"Gerador... normal. Tentando iniciar...\"",
  ui_story_1013_10130702_21_dialog_content = "Soroz!",
  ui_story_1013_10130702_22_dialog_content = "Eu estou aqui, PlayerName. Eu estou sempre aqui.",
  ui_story_1013_10130702_23_dialog_content = "\"Mantê-lo vivo e seguro é minha principal prioridade.\" Lembrar?",
  ui_story_1013_10130702_24_dialog_content = "Pode ser um mundo virtual...",
  ui_story_1013_10130702_25_dialog_content = "mas isso não significa que eu posso deixar você se machucar.",
  ui_story_1013_10130702_26_dialog_content = "Tente cortar seu link comigo. E então... apenas confie em mim.",
  ui_story_1013_10130702_27_dialog_content = "\"Sistema de Piloto Automático lançado... Objetivo: Retorno à realidade.\"",
  ui_story_1013_10130702_28_dialog_content = "Ngnh...",
  ui_story_1013_10130702_29_dialog_content = "Funcionou... Soroz...",
  ui_story_1013_10130702_30_dialog_content = "PlayerName... PlayerName está acordado!",
  ui_story_1013_10130702_31_dialog_content = "PlayerName, você finalmente acordou!",
  ui_story_1013_10130702_32_dialog_content = "O garoto está consciente de novo! Mantenha as vias aéreas dele abertas.",
  ui_story_1013_10130702_33_dialog_content = "Ative o scanner de exame médico do centro de pesquisa.",
  ui_story_1013_10130702_34_dialog_content = "O que você está... Espere! Estou bem, não estou ferido.",
  ui_story_1013_10130702_35_dialog_content = "E Soroz?",
  ui_story_1013_10130702_36_dialog_content = "Não podemos confiar em sua consciência subjetiva para nos dizer se você está ferido ou não.",
  ui_story_1013_10130702_37_dialog_content = "Os resultados sairão em pouco tempo. Por favor, fique parado por cinco minutos.",
  ui_story_1013_10130702_38_dialog_content = "Como você nunca me disse que o simulador poderia funcionar mal assim!?",
  ui_story_1013_10130702_39_dialog_content = "Eu sei que brinco sobre abrir você, mas ainda conheço a linha entre as piadas e a realidade.",
  ui_story_1013_10130702_40_dialog_content = "Não tínhamos intenção de colocar você em perigo. O centro de pesquisa assumirá total responsabilidade por este incidente.",
  ui_story_1013_10130702_41_dialog_content = "Vou investigar os pesquisadores que compilaram os dados do antigo campo de batalha e executar um novo conjunto de testes no simulador.",
  ui_story_1013_10130702_42_dialog_content = "Além disso, repasse meu pedido:",
  ui_story_1013_10130702_43_dialog_content = "O Centro de Pesquisa Illumina cobrirá PlayerNamecustos de manutenção do Colossus para os próximos três meses.",
  ui_story_1013_10130702_44_dialog_content = "O que você disse, PlayerName?",
  ui_story_1013_10130702_45_dialog_content = "Eu acho que isso funciona...",
  ui_story_1013_10130702_46_dialog_content = "Hmm, acho que o problema é que a tecnologia que usamos para conectar o Colossus e o simulador ainda é imatura.",
  ui_story_1013_10130702_47_dialog_content = "A regeneração de Jormungand indicava o fato de que você estava preso em dados corrompidos do passado.",
  ui_story_1013_10130702_48_dialog_content = "Então vocês puderam ver tudo como aconteceu...",
  ui_story_1013_10130702_49_dialog_content = "No final, Soroz cortou o link com o simulador e me tirou de lá.",
  ui_story_1013_10130702_50_dialog_content = "Então, como está o Soroz?",
  ui_story_1013_10130702_51_dialog_content = "Os resultados chegaram. Parabéns, cobaia! Tudo parece normal.",
  ui_story_1013_10130702_52_dialog_content = "Alguém pode me dizer como é Soroz?!",
  ui_story_1013_10130702_53_dialog_content = "Soroz...",
  ui_story_1013_10130702_54_dialog_content = "Soroz pagou o preço por quebrar a conexão assim.",
  ui_story_1013_10130702_55_dialog_content = "Sua consciência permaneceu no sistema do simulador de campo de batalha.",
  ui_story_1013_10130702_56_dialog_content = "Eu sei que parece cruel para você. Mas esse tipo de situação é comum durante a experimentação.",
  ui_story_1013_10130702_57_dialog_content = "Sua consciência agora está em um estado complicado – sua personalidade foi arrancada de suas memórias.",
  ui_story_1013_10130702_58_dialog_content = "As memórias de Soroz agora assumem a forma de pura informação. Sua personalidade regrediu a uma lousa em branco.",
  ui_story_1013_10130702_59_dialog_content = "Quando essa regressão aconteceu, Soroz conseguiu tirá-lo com segurança, mas perdeu essa parte de sua funcionalidade.",
  ui_story_1013_10130702_60_dialog_content = "!!!",
  ui_story_1013_10130702_61_dialog_content = "O que você quer dizer... O que isso significa?",
  ui_story_1013_10130702_62_dialog_content = "Apenas o que você pensaria.",
  ui_story_1013_10130702_63_dialog_content = "Vocês chamam isso de um pequeno problema?!",
  ui_story_1013_10130702_64_option_content = "Aumento de Força!",
  ui_story_1013_10130702_65_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10130702_66_option_content = "Impulso de força!!",
  ui_story_1013_10130702_67_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10130702_68_option_content = "Força Aumentar!!!",
  ui_story_1013_10130702_69_dialog_content = "Não desperdice sua força, PlayerName.",
  ui_story_1013_10130702_70_dialog_content = "Você não será capaz de controlá-lo no momento.",
  ui_story_1013_10130702_71_dialog_content = "Continuaremos tentando restaurar sua consciência. No mínimo tentaremos restaurar suas funções.",
  ui_story_1013_10130702_72_dialog_content = "O que isso significa?",
  ui_story_1013_10130702_73_dialog_content = "Como pode ser \"funcional\" sem sua personalidade ou memórias!?",
  ui_story_1013_10130702_74_dialog_content = "O que você pensa que está fazendo? Vocês não deveriam assumir total responsabilidade por isso?!",
  ui_story_1013_10130702_75_dialog_content = "Sim, Grande Marechal. O centro de pesquisa assumirá total responsabilidade por restaurar a consciência do Colossus.",
  ui_story_1013_10130702_76_dialog_content = "No entanto, cobaia, devemos nos lembrar de não fazer amizade com nossa tecnologia. Eles são apenas ferramentas para nos servir e nos auxiliar na pesquisa.",
  ui_story_1013_10130702_77_dialog_content = "Quando o Colossus perdeu a consciência, seu sistema perdeu a estabilidade...",
  ui_story_1013_10130702_78_dialog_content = "mas, desde que possamos colocá-lo em funcionamento, não importa se sua personalidade está adormecida ou perdida.",
  ui_story_1013_10130702_79_dialog_content = "Não toque em Soroz! Soroz é meu amigo, meu mentor e minha única família!",
  ui_story_1013_10130702_80_dialog_content = "Por favor acalme-se, PlayerName. Eu prometo a você que nosso trabalho não irá prejudicá-lo.",
  ui_story_1013_10130702_81_dialog_content = "Você já está prejudicando!",
  ui_story_1013_10130702_82_dialog_content = "<color=#e8d9bb>TOC Toc</color>",
  ui_story_1013_10130702_83_dialog_content = "Os laboratórios devem ser silenciosos. Por favor, mantenha o ruído baixo.",
  ui_story_1013_10130702_84_dialog_content = "Ai...?",
  ui_story_1013_10130702_85_dialog_content = "Grande Marechal, Oficial de Inteligência Yingel do <color=#FFB400>Conselho Científico</color>, comunicando.",
  ui_story_1013_10130702_86_dialog_content = "O Conselho Científico? Então eles recrutaram secretamente alguns recém-chegados promissores novamente.",
  ui_story_1013_10130702_87_dialog_content = "Obrigado, Grande Marechal. Acredito que seja a primeira vez que nos encontramos.",
  ui_story_1013_10130702_88_dialog_content = "Mas sinto como se te conhecesse bem.",
  ui_story_1013_10130702_89_dialog_content = "Haha! Todos na Illumina me conhecem.",
  ui_story_1013_10130702_90_dialog_content = "Então, para que o Conselho Científico o enviou? Para estudar o celestita?",
  ui_story_1013_10130702_91_dialog_content = "O Conselho está prestes a realizar uma conferência secreta. Estou aqui apenas para passar ordens.",
  ui_story_1013_10130702_92_dialog_content = "Ha. Esses nerds do laboratório finalmente decidiram se mostrar, hein?",
  ui_story_1013_10130702_93_dialog_content = "O Conselho Científico solicita, com sinceras intenções, conversar pessoalmente com o Celestita.",
  ui_story_1013_10130702_94_dialog_content = "E quanto a mim?",
  ui_story_1013_10130702_95_dialog_content = "Você é bem-vindo a participar, naturalmente.",
  ui_story_1013_10130702_96_dialog_content = "Em vez disso, você está sendo ordenado. Por favor, participe da reunião ao lado do celestita.",
  ui_story_1013_10130702_97_dialog_content = "Suponho que isso significa que tenho ainda menos direito de recusar.",
  ui_story_1013_10130702_98_dialog_content = "Mas Soroz...",
  ui_story_1013_10130702_99_dialog_content = "Gronru e eu ordenaremos aos pesquisadores que interrompam todo o trabalho no Colosso até que você volte.",
  ui_story_1013_10130702_100_dialog_content = "Não se preocupe, vou vigiá-los como um falcão!",
  ui_story_1013_10130702_101_dialog_content = "Não se preocupe, PlayerName. Ainda não estamos sem soluções.",
  ui_story_1013_10130702_102_dialog_content = "O Conselho Científico pode fornecer mais informações sobre Soroz.",
  ui_story_1013_10130702_103_dialog_content = "... Entendo.",
  ui_story_1013_10130702_104_dialog_content = "Também tenho algumas perguntas sobre a antiga batalha que testemunhei.",
  ui_story_1013_10130702_105_dialog_content = "Sua cooperação é apreciada. Tenho certeza de que o Conselho Científico responderá às suas perguntas da melhor maneira possível.",
  ui_story_1013_10130702_106_dialog_content = "Se vocês dois me seguirem?",
  ui_story_1013_10130801_1_dialog_content = "O Conselho Científico?",
  ui_story_1013_10130801_2_dialog_content = "Sim. Eles se reportam diretamente aos mais altos poderes da Illumina...",
  ui_story_1013_10130801_3_dialog_content = "Seus principais membros estão espalhados por toda a Illumina. Apenas em momentos de crise eles se reúnem para uma reunião secreta.",
  ui_story_1013_10130801_4_dialog_content = "Eu sei que tudo parece um pouco assustador. Mas cada membro do Conselho tem acesso aos maiores segredos de Illumina.",
  ui_story_1013_10130801_5_dialog_content = "É por isso que eles mantêm suas identidades em segredo.",
  ui_story_1013_10130801_6_dialog_content = "A última vez que eles se revelaram foi para votar quando a liderança militar estava mudando.",
  ui_story_1013_10130801_7_dialog_content = "Espera, não foi isso...",
  ui_story_1013_10130801_8_dialog_content = "Quando fui nomeado? Sim, realmente.",
  ui_story_1013_10130801_9_dialog_content = "Soa muito misterioso. O que explica por que nunca ouvi falar deles.",
  ui_story_1013_10130801_10_dialog_content = "Se você pudesse se apressar?",
  ui_story_1013_10130801_11_dialog_content = "haha. Você ouve isso, PlayerName? Vamos, vamos alcançá-la.",
  ui_story_1013_10130801_12_dialog_content = "(Isso é impressionante. Até mesmo um mero oficial de inteligência do Conselho de Ciência tem a audácia de dar ordens ao Grande Marshall.)",
  ui_story_1013_10130801_13_dialog_content = "Você ainda parece nervoso.",
  ui_story_1013_10130801_14_dialog_content = "Eu não diria nervoso. Eu sou mais... cauteloso.",
  ui_story_1013_10130801_15_dialog_content = "Nada do que você me disse me ajuda a entender por que eles precisam se encontrar comigo de repente.",
  ui_story_1013_10130801_16_dialog_content = "É por causa de Vice e Barton? Ou é sobre o Obelisco do Retorno?",
  ui_story_1013_10130801_17_dialog_content = "Você só está enlouquecendo fazendo suposições malucas como essa.",
  ui_story_1013_10130801_18_dialog_content = "Os membros do Conselho têm muito poder e não agem arbitrariamente.",
  ui_story_1013_10130801_19_dialog_content = "Se eles o convidaram para uma reunião, isso significa que eles explicarão tudo e tentarão ganhar sua confiança.",
  ui_story_1013_10130801_20_dialog_content = "Além disso, eles podem estar encarregados de gerenciar toda a inteligência da Illumina, mas no final das contas, eles são apenas um bando de nerds da ciência.",
  ui_story_1013_10130801_21_dialog_content = "Eles podem até ajudá-lo a encontrar uma maneira de restaurar a personalidade de Soroz.",
  ui_story_1013_10130801_22_dialog_content = "— Se isso faz você se sentir melhor.",
  ui_story_1013_10130801_23_dialog_content = "... Obrigado, Reinhardt.",
  ui_story_1013_10130801_24_dialog_content = "Chegamos.",
  ui_story_1013_10130801_25_dialog_content = "Por favor, registre-se na entrada.",
  ui_story_1013_10130801_26_dialog_content = "E não se preocupe - as informações que você fornecer serão usadas apenas para fazer check-in e check-out.",
  ui_story_1013_10130801_27_dialog_content = "(Uau, eles realmente são secretos.)",
  ui_story_1013_10130801_28_dialog_content = "<color=#e8d9bb>Bip Bip-</color>",
  ui_story_1013_10130801_29_dialog_content = "Eu digitei a senha para a porta. Por favor entre.",
  ui_story_1013_10130801_30_dialog_content = "Por que não convidamos pessoas do centro de pesquisa ou do Black Umbrella Laboratories? Até o tenente Vice seria uma escolha melhor.",
  ui_story_1013_10130801_31_dialog_content = "Não sabemos onde fica o celestita. E ele é o único com aquela habilidade psíquica genial sobre a tecnologia antiga.",
  ui_story_1013_10130801_32_dialog_content = "Genius está exagerando. Mas ele é o único sobrevivente puro-sangue caelestita que conhecemos.",
  ui_story_1013_10130801_33_dialog_content = "Bem, até que eu veja com meus próprios olhos, estou assumindo que essa \"habilidade psíquica\" é apenas flimflam.",
  ui_story_1013_10130801_34_dialog_content = "Até um relógio parado está certo duas vezes por dia.",
  ui_story_1013_10130801_35_dialog_content = "Vou ter seus pensamentos em mente.",
  ui_story_1013_10130801_36_dialog_content = "Tudo bem, eles estão aqui.",
  ui_story_1013_10130801_37_dialog_content = "<color=#e8d9bb>*Som de batida*</color>",
  ui_story_1013_10130801_38_dialog_content = "O Último Celestita, PlayerName, é aqui.",
  ui_story_1013_10130801_39_dialog_content = "Acompanhado pelo Grande Marechal Reinhardt.",
  ui_story_1013_10130801_40_dialog_content = "Splendor Illumina.",
  ui_story_1013_10130801_41_dialog_content = "Splendor Illumina.",
  ui_story_1013_10130801_42_dialog_content = "PlayerName, você pode se sentar ao meu lado.",
  ui_story_1013_10130801_43_dialog_content = "Por favor, o celestita poderia se sentar à esquerda de Ulisses? Na frente da tela.",
  ui_story_1013_10130801_44_dialog_content = "E Reinhardt, você pode ficar ao lado dele.",
  ui_story_1013_10130801_45_dialog_content = "Barrett, você parece gostar de estar encarregado de organizar os assentos hoje.",
  ui_story_1013_10130801_46_dialog_content = "Bem, só podemos acomodar um certo número de pessoas. Alguém tem que cuidar da logística.",
  ui_story_1013_10130801_47_dialog_content = "Obrigado por participar da nossa reunião.",
  ui_story_1013_10130801_48_dialog_content = "Seguindo regras estritas, podemos economizar muito tempo.",
  ui_story_1013_10130801_49_dialog_content = "Isso inclui tanto as regras escritas quanto as não escritas.",
  ui_story_1013_10130801_50_dialog_content = "Por favor, sente-se, Celestita.",
  ui_story_1013_10130801_51_dialog_content = "Olá senhor.",
  ui_story_1013_10130801_52_dialog_content = "Deixe-me fazer algumas apresentações. À sua direita está o professor Ulysses, um biólogo.",
  ui_story_1013_10130801_53_dialog_content = "Em frente ao professor está o Sr. Joyce, nosso físico.",
  ui_story_1013_10130801_54_dialog_content = "Ao lado do Grande Marechal Reinhardt está a Srta. Barrett, uma engenheira.",
  ui_story_1013_10130801_55_dialog_content = "E então...",
  ui_story_1013_10130801_56_dialog_content = "Senhorita Algol, por favor acorde...",
  ui_story_1013_10130801_57_dialog_content = "Huh-Oh, desculpe. Meu tempo é limitado, você sabe.",
  ui_story_1013_10130801_58_dialog_content = "Recuperar o sono é um uso muito mais eficiente do tempo do que ouvir a disposição dos assentos.",
  ui_story_1013_10130801_59_dialog_content = "Ei—",
  ui_story_1013_10130801_60_dialog_content = "Sou Algol, responsável pela inteligência artificial. O robô no meu ombro é Bool.",
  ui_story_1013_10130801_61_dialog_content = "Tenho certeza que você e eu vamos gostar de conversar, desde que não acordemos Bool.",
  ui_story_1013_10130801_62_dialog_content = "N-Prazer em conhecê-lo.",
  ui_story_1013_10130801_63_dialog_content = "Se não houver objeções, vamos começar?",
  ui_story_1013_10130801_64_dialog_content = "Antes de chegarmos aos negócios, pode ser mais eficiente responder primeiro às suas perguntas.",
  ui_story_1013_10130801_65_dialog_content = "Por favor, limite-o a três no máximo.",
  ui_story_1013_10130801_66_dialog_content = "PlayerName acabou de terminar uma sessão de teste no simulador de campo de batalha no centro de pesquisa.",
  ui_story_1013_10130801_67_dialog_content = "Ele tem uma série de perguntas para você.",
  ui_story_1013_10130801_68_dialog_content = "Obrigado por contribuir, Reinhardt.",
  ui_story_1013_10130801_69_dialog_content = "Então, posso convidar o celestita para falar agora?",
  ui_story_1013_10130801_70_dialog_content = "... Seja meu convidado.",
  ui_story_1013_10130801_71_option_content = "Pergunte sobre os \"demônios\".",
  ui_story_1013_10130801_72_dialog_content = "Isso tudo realmente aconteceu? Quero dizer as coisas que vi na simulação.",
  ui_story_1013_10130801_73_dialog_content = "Eu vi aurorianos usando Luminatics em uma batalha antiga.",
  ui_story_1013_10130801_74_dialog_content = "E o que eles chamavam de \"demônios\"... eram eles...?",
  ui_story_1013_10130801_75_dialog_content = "Esses eventos realmente aconteceram.",
  ui_story_1013_10130801_76_dialog_content = "Antes dos aurorianos e celestitas, esta terra era habitada por nossos ancestrais distantes.",
  ui_story_1013_10130801_77_dialog_content = "E eles se autodenominavam \"humanidade\", certo?",
  ui_story_1013_10130801_78_dialog_content = "Exatamente. Eles se pareciam conosco e usavam a tecnologia como nós... e alguns deles se dedicaram à fé como nós também.",
  ui_story_1013_10130801_79_dialog_content = "Mas eles não tinham poderes especiais.",
  ui_story_1013_10130801_80_dialog_content = "(Então... é por isso que tudo o que eles podiam fazer era fugir dos \"demônios\"?)",
  ui_story_1013_10130801_81_dialog_content = "Deixe-me tentar torná-lo fácil de entender.",
  ui_story_1013_10130801_82_dialog_content = "Os mais talentosos de nossos ancestrais evoluíram para se tornarem aurorianos.",
  ui_story_1013_10130801_83_dialog_content = "Mas outros sucumbiram às tentações oferecidas pelos \"demônios\".",
  ui_story_1013_10130801_84_dialog_content = "Mas o que eram esses \"demônios\"?",
  ui_story_1013_10130801_85_dialog_content = "Eram Eclipsites de alto nível? Aurorianos? Ou celestitas?",
  ui_story_1013_10130801_86_dialog_content = "O centro de pesquisa ainda está trabalhando para encontrar a resposta para essa pergunta, então não tenho uma resposta para você agora.",
  ui_story_1013_10130801_87_dialog_content = "Quer dizer que não fez nenhum progresso desde nosso último encontro? Depois de todo esse tempo?",
  ui_story_1013_10130801_88_dialog_content = "A origem dos \"demônios\" - como eles evoluíram, seu impacto em nossa história... precisamos estudar esses assuntos com muito cuidado.",
  ui_story_1013_10130801_89_dialog_content = "Estas não são perguntas que podem ser respondidas com algumas batalhas simuladas.",
  ui_story_1013_10130801_90_dialog_content = "...",
  ui_story_1013_10130801_91_dialog_content = "No final, os celestitas e eclipsitas, controlados por demônios, travaram uma batalha decisiva contra os aurorianos.",
  ui_story_1013_10130801_92_dialog_content = "Esta parte da história não é segredo para aqueles que estão sentados ao redor desta mesa.",
  ui_story_1013_10130801_93_dialog_content = "Então, depois disso, o mundo de nossos ancestrais foi destruído. Os Eclipsitas voltaram para a Zona Escura e os Caelestitas desapareceram.",
  ui_story_1013_10130801_94_dialog_content = "Os aurorianos sobreviventes construíram uma nova civilização e lutaram contra os eclipsitas que os demônios haviam deixado para trás.",
  ui_story_1013_10130801_95_dialog_content = "Isso está certo?",
  ui_story_1013_10130801_96_dialog_content = "Não confirmamos isso. Mas nossas visões atuais estão amplamente alinhadas com sua hipótese, sim.",
  ui_story_1013_10130801_96X1_dialog_content = "Por favor, espere.",
  ui_story_1013_10130801_97_dialog_content = "<color=#e8d9bb>Rasp—Estalar</color>",
  ui_story_1013_10130801_98_dialog_content = "(Uma bebida? Essas pessoas não mudaram nada.)",
  ui_story_1013_10130801_99_dialog_content = "(Aqueles pequenos sinais que eles enviam um ao outro só enganariam um recém-chegado como PlayerName.)",
  ui_story_1013_10130801_100_dialog_content = "Você gostaria de experimentar um, Celestita? É um novo tipo de bebida que está na moda em Illumina.",
  ui_story_1013_10130801_100X1_dialog_content = "(O-de onde você veio?!)",
  ui_story_1013_10130801_100X2_dialog_content = "Barrett, vejo que decidiu aparecer pela primeira vez.",
  ui_story_1013_10130801_100X3_dialog_content = "Sim, estou um pouco interessado neste celestita.",
  ui_story_1013_10130801_100X4_dialog_content = "Mas os outros podem não se sentir da mesma maneira.",
  ui_story_1013_10130801_100X5_dialog_content = "Estavam <color=#FFB400>observando</color> você, então faça o seu melhor, Celestita.",
  ui_story_1013_10130801_101_dialog_content = "... Eu vou.",
  ui_story_1013_10130801_102_option_content = "Pergunte sobre os antigos aurorianos.",
  ui_story_1013_10130801_103_dialog_content = "Então, como esses ancestrais \"talentosos\" desenvolveram o poder dos Luminatics?",
  ui_story_1013_10130801_104_dialog_content = "Nas cenas que vi, eles estavam apenas rezando para a luz.",
  ui_story_1013_10130801_105_dialog_content = "Essa é a fonte da fé de Lumopolis?",
  ui_story_1013_10130801_106_dialog_content = "Ha, este não é o lugar para fazer essa pergunta, jovem.",
  ui_story_1013_10130801_107_dialog_content = "S-Desculpe!",
  ui_story_1013_10130801_108_dialog_content = "Existem muitos aurorianos em nosso mundo. Mas poucos deles conhecem a verdadeira natureza dos Luminatics.",
  ui_story_1013_10130801_109_dialog_content = "Os aurorianos preferem se ater a explicações mais fáceis de entender.",
  ui_story_1013_10130801_110_dialog_content = "Por exemplo, um presente de um deus, ou algo originário de uma terra sagrada, ou um poder adquirido ao realizar alguma \"verdade\"...",
  ui_story_1013_10130801_111_dialog_content = "Mas, em sua essência, é uma habilidade, uma capacidade de usar <color=#FFB400>vitalidade</color> para direcionar a energia.",
  ui_story_1013_10130801_112_dialog_content = "Vitalidade? Mas os celestitas...",
  ui_story_1013_10130801_113_dialog_content = "Os celestitas possuem vitalidade. Mas você é incapaz de dominar o manejo de Luminatics.",
  ui_story_1013_10130801_114_dialog_content = "Muito menos as Eclipsitas. Eles carecem de vitalidade e são totalmente incapazes de direcionar a energia.",
  ui_story_1013_10130801_115_dialog_content = "Mas como exatamente essa habilidade funciona?",
  ui_story_1013_10130801_116_dialog_content = "Hehe. Bem, simplesmente, é uma aplicação prática do Luminatics. Veja a Federação Illumina, por exemplo.",
  ui_story_1013_10130801_117_dialog_content = "Costumamos usar Luminatics <color=#FFB400>como ele age</color>, para dirigir máquinas e usar a tecnologia para controlar os efeitos.",
  ui_story_1013_10130801_118_dialog_content = "Enquanto isso, em Lumopolis eles usam a fé pura para impulsionar sua vitalidade.",
  ui_story_1013_10130801_119_dialog_content = "Então eles controlam Luminatics <color=#FFB400>na fonte</color>.",
  ui_story_1013_10130801_120_dialog_content = "Essa é realmente a única diferença entre Lumopolis e Illumina.",
  ui_story_1013_10130801_121_dialog_content = "A única diferença? Isso é um pouco extremo.",
  ui_story_1013_10130801_122_dialog_content = "E, por favor, evite me interromper.",
  ui_story_1013_10130801_123_dialog_content = "(Todos esses cientistas agem de maneira amigável na superfície, mas parecem ter uma agressividade subjacente a eles. Ou estou imaginando isso?)",
  ui_story_1013_10130801_124_dialog_content = "Já estamos conversando há mais de dez minutos. Professor Ulysses, não esqueça por que estamos aqui.",
  ui_story_1013_10130801_125_dialog_content = "Obrigado por me lembrar. Mas como combinamos, o celestita ainda pode fazer mais uma pergunta.",
  ui_story_1013_10130801_126_dialog_content = "Tão sério, Ulisses. Você treinou a jovem para ser tão meticulosa com as regras quanto você.",
  ui_story_1013_10130801_127_dialog_content = "Yingel é um dos ex-alunos promissores modificados pelo programa Phospherus. É apenas meu dever treiná-la adequadamente.",
  ui_story_1013_10130801_128_dialog_content = "(Modificado!?)",
  ui_story_1013_10130801_129_dialog_content = "(É isso que eles estão fazendo? <color=#FFB400>Modificando aurorianos</color>!?)",
  ui_story_1013_10130801_130_dialog_content = "... É esse o experimento sobre o qual você tem mantido tanto segredo?!",
  ui_story_1013_10130801_131_dialog_content = "Expliquem-se! O programa Phospherus não foi encerrado anos atrás?",
  ui_story_1013_10130801_132_dialog_content = "Para ser preciso, o Comitê realizou uma votação para encerrar o programa.",
  ui_story_1013_10130801_133_dialog_content = "Mas o resultado não foi o que você esperava, Reinhardt.",
  ui_story_1013_10130801_134_dialog_content = "Então terei que apresentar outra proposta para desligá-lo!",
  ui_story_1013_10130801_135_dialog_content = "Não permitirei que meus soldados e cidadãos passem por nenhuma modificação experimental!",
  ui_story_1013_10130801_136_dialog_content = "Claro Reinhardt. Você pode fazer como quiser.",
  ui_story_1013_10130801_137_dialog_content = "Seus poderes como Grande Marechal são concedidos a você pelo povo de Illumina. É justo que você use esses poderes para o benefício deles.",
  ui_story_1013_10130801_138_dialog_content = "Mas isso deve esperar até que tenhamos concluído esta reunião. Se você pudesse permitir que o celestita falasse?",
  ui_story_1013_10130801_139_dialog_content = "(O que está acontecendo? Isso explica o que está acontecendo com Vice?)",
  ui_story_1013_10130801_140_dialog_content = "(Quantos aurorianos foram secretamente modificados sem seu conhecimento? Quantos deles são meus companheiros?)",
  ui_story_1013_10130801_141_dialog_content = "(Força Impulso!)",
  ui_story_1013_10130801_142_dialog_content = "Não entrar em pânico, PlayerName. Conto com você para fazer a pergunta a eles.",
  ui_story_1013_10130801_143_dialog_content = "Por favor, pergunte a Ulysses o que exatamente eles esperam alcançar com seus experimentos de modificação.",
  ui_story_1013_10130801_144_dialog_content = "Isso diz respeito ao futuro de Vice e dos outros, e deste oficial de inteligência aqui e seus compatriotas.",
  ui_story_1013_10130801_145_dialog_content = "E talvez também... o que aconteceu naquela época...",
  ui_story_1013_10130801_146_dialog_content = "... Entendo.",
  ui_story_1013_10130801_147_dialog_content = "E posso estar pensando demais nas coisas, mas suspeito que eles estão testando você.",
  ui_story_1013_10130801_148_dialog_content = "Me testando?",
  ui_story_1013_10130801_149_dialog_content = "Suspeito que entre suas fileiras, eles ainda não chegaram a um consenso sobre algo.",
  ui_story_1013_10130801_150_dialog_content = "Eles precisavam se encontrar com você antes de chegar secretamente a algum tipo de decisão.",
  ui_story_1013_10130801_151_dialog_content = "É um dos velhos truques deles. De qualquer forma, eles sinalizam um ao outro usando essas bebidas.",
  ui_story_1013_10130801_152_dialog_content = "Mas não se preocupe muito com isso. Apenas faça o que você tem que fazer.",
  ui_story_1013_10130801_153_dialog_content = "O-Ok.",
  ui_story_1013_10130801_154_dialog_content = "(Ele estava usando sua habilidade psíquica durante esse período de silêncio?)",
  ui_story_1013_10130801_155_dialog_content = "(Independentemente disso, ele é definitivamente alguém que precisamos ficar de olho.)",
  ui_story_1013_10130801_156_dialog_content = "<color=#e8d9bb>Rasp—Estalar</color>",
  ui_story_1013_10130801_157_dialog_content = "(Heheh... então você finalmente reconhece o valor do Celestita.)",
  ui_story_1013_10130801_158_option_content = "Pergunte sobre os experimentos de modificação.",
  ui_story_1013_10130801_159_dialog_content = "O Helios também foi um produto deste programa Phospherus?",
  ui_story_1013_10130801_160_dialog_content = "Por que em... Por que Illumina iria querer modificar os aurorianos?",
  ui_story_1013_10130801_161_dialog_content = "Hélio? Não esperava que você fosse tão bem informado.",
  ui_story_1013_10130801_162_dialog_content = "Diante disso, não faz sentido enganá-lo. Na verdade, tenho realizado tais experimentos.",
  ui_story_1013_10130801_163_dialog_content = "Yingel, que está aqui diante de vocês, foi um dos produtos de maior sucesso da última rodada.",
  ui_story_1013_10130801_164_dialog_content = "Os aurorianos modificados têm a mesma genética e características dos aurorianos normais.",
  ui_story_1013_10130801_165_dialog_content = "Embora, para ser franco, sua personalidade obstinada às vezes seja um pouco problemática.",
  ui_story_1013_10130801_166_dialog_content = "Essa não é a questão! Por que você faria uma coisa dessas?",
  ui_story_1013_10130801_167_dialog_content = "Para Iluminar.",
  ui_story_1013_10130801_168_dialog_content = "Obviamente, é para Illumina. Devemos ter nosso próprio equipamento de modificação.",
  ui_story_1013_10130801_169_dialog_content = "Assim como Lumopolis tem canhões, e Eraveil tem dispositivos antigos que fortalecem os aurorianos.",
  ui_story_1013_10130801_170_dialog_content = "Illumina uma vez explorou a Dark Zone em busca de equipamentos semelhantes, mas sem sucesso.",
  ui_story_1013_10130801_171_dialog_content = "Tudo o que Illumina tem são seus cidadãos leais. E nossa defesa é construída sobre os ossos desses guerreiros.",
  ui_story_1013_10130801_172_dialog_content = "Nossa pesquisa neste campo representa a vontade de nosso povo.",
  ui_story_1013_10130801_173_dialog_content = "Cada assunto que modificamos significa um inocente a menos sacrificado.",
  ui_story_1013_10130801_174_dialog_content = "Sem sentido nenhum! E os sujeitos experimentais? Eles não são inocentes? Pessoas como Helios não contam como sacrifícios?",
  ui_story_1013_10130801_175_dialog_content = "<color=#e8d9bb>Rasp—Estalar</color>",
  ui_story_1013_10130801_176_dialog_content = "Sobre o tema Hélio...",
  ui_story_1013_10130801_177_dialog_content = "Esse lote de cobaias não fazia parte do programa Phospherus.",
  ui_story_1013_10130801_178_dialog_content = "Ele pertence a uma empresa diferente. Ele era apenas um produto fracassado de um experimento fracassado.",
  ui_story_1013_10130801_179_dialog_content = "Uma falha!?",
  ui_story_1013_10130801_180_dialog_content = "Arruinar a vida de um auroriano significa nada mais para você do que um fracasso experimental?",
  ui_story_1013_10130801_181_dialog_content = "Reinhardt, como um benfeitor de nossos experimentos, você realmente não tem o direito de se impor moralmente.",
  ui_story_1013_10130801_182_dialog_content = "Você dificilmente pode dizer que arruinamos a vida dele. Talvez fosse um caminho mais adequado para ele, não?",
  ui_story_1013_10130801_183_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1013_10130801_184_dialog_content = "Não consigo mais ficar sentado nesta reunião. E Ulisses, temo que você tenha deixado o caminho da razão.",
  ui_story_1013_10130801_185_dialog_content = "Acho que já ouvimos o suficiente. Não adianta continuar.",
  ui_story_1013_10130801_186_dialog_content = "Você quer encerrar a reunião? Mas o Conselho Científico está apenas começando.",
  ui_story_1013_10130801_187_dialog_content = "Você pode sair se estiver bem em deixar o celestita aqui sozinho.",
  ui_story_1013_10130801_188_dialog_content = "Wha...",
  ui_story_1013_10130801_189_dialog_content = "Você não ousaria.",
  ui_story_1013_10130801_190_dialog_content = "Relaxar. Somos pessoas educadas. Não somos tão coniventes quanto você pensa que somos.",
  ui_story_1013_10130801_191_dialog_content = "O celestita estará seguro conosco. Afinal, fomos amigos dele todo esse tempo.",
  ui_story_1013_10130801_192_dialog_content = "Mas precisamos de uma testemunha autorizada.",
  ui_story_1013_10130801_193_dialog_content = "Reinhardt, espero que não precise de mim para deixar isso mais claro. Por favor, faça sua parte.",
  ui_story_1013_10130801_194_dialog_content = "...",
  ui_story_1013_10130801_195_dialog_content = "<color=#e8d9bb>*Toques leves*</color>",
  ui_story_1013_10130801_196_dialog_content = "Bocejar.",
  ui_story_1013_10130801_197_dialog_content = "Por favor todos. Não vamos deixar nossas emoções correrem tão alto.",
  ui_story_1013_10130801_198_dialog_content = "Todos vocês deram o sinal secreto para <color=#FFB400>aceite o celestita</color>. Então você poderia pelo menos ser um pouco mais amigável.",
  ui_story_1013_10130801_199_dialog_content = "E o querido Yingel está certo. Não vamos esquecer por que o convocamos aqui.",
  ui_story_1013_10130801_200_dialog_content = "(Eles estão finalmente prestes a nos contar o que realmente está acontecendo?)",
  ui_story_1013_10130801_201_dialog_content = "Celestita, eles responderam às suas perguntas na íntegra.",
  ui_story_1013_10130801_202_dialog_content = "Eles não hesitaram, mesmo quando tocavam em assuntos relativos aos segredos mais guardados de Illumina.",
  ui_story_1013_10130801_203_dialog_content = "É um comércio justo, não é? Nossos segredos para sua cooperação.",
  ui_story_1013_10130801_204_dialog_content = "?!",
  ui_story_1013_10130801_205_dialog_content = "Isso é ridículo! Eu nunca apoiaria um programa como esse!",
  ui_story_1013_10130801_206_dialog_content = "Pah. Você é o único celestita sobrevivente. Nós nunca modificaríamos você.",
  ui_story_1013_10130801_207_dialog_content = "Como acabamos de dizer, não tocaremos em um único fio de cabelo de sua cabeça.",
  ui_story_1013_10130801_208_dialog_content = "Peço apenas que nos ajude. E isso irá beneficiá-lo, indiretamente.",
  ui_story_1013_10130801_209_dialog_content = "Você poderia, por favor, parar de rodeios?",
  ui_story_1013_10130801_210_dialog_content = "Não fique com raiva. Eu sei que você quer que o Vice volte ao normal e que está preocupado com o mau funcionamento do seu Colossus.",
  ui_story_1013_10130801_211_dialog_content = "(I-Isso é verdade...)",
  ui_story_1013_10130801_212_dialog_content = "Para encurtar a história, o Conselho de Ciência espera usar seus poderes psíquicos para estabelecer uma ligação com <color=#FFB400>Guardião Um</color>.",
  ui_story_1013_10130801_213_dialog_content = "Anteriormente, os cientistas da Illumina concordaram que Soroz era um Colosso de transporte comum.",
  ui_story_1013_10130801_214_dialog_content = "Mas, considerando seus comportamentos recentes e a maneira como seus sistemas continuam sendo atualizados...",
  ui_story_1013_10130801_215_dialog_content = "possibilidades alternativas se abriram.",
  ui_story_1013_10130801_216_dialog_content = "E você, o celestita que controla Soroz, é parte integrante deles.",
  ui_story_1013_10130801_217_dialog_content = "A antiga tecnologia que liga você a Soroz causou uma série de eventos milagrosos.",
  ui_story_1013_10130801_218_dialog_content = "Chegamos a um acordo após nossa conversa anterior. Podemos confiar a consciência do Guardião Um a você.",
  ui_story_1013_10130801_219_dialog_content = "Portanto, esperamos que você use seu poder para alcançar o Guardião Um.",
  ui_story_1013_10130801_220_dialog_content = "Guardião Um? O que é isso, outro robô precisando de uma surra?",
  ui_story_1013_10130801_221_dialog_content = "É uma antiga inteligência artificial que sobreviveu até hoje. Ele gerencia cálculos e operações diárias para toda a tecnologia Illumina.",
  ui_story_1013_10130801_222_dialog_content = "Então, o que você acha? Existem semelhanças com os Colossos, não?",
  ui_story_1013_10130801_223_dialog_content = "Verdade...",
  ui_story_1013_10130801_224_dialog_content = "E se você puder entrar em contato com o Guardian One...",
  ui_story_1013_10130801_225_dialog_content = "Existe a possibilidade de que as memórias antigas em sua consciência forneçam pistas sobre como fazer o Vice voltar ao normal.",
  ui_story_1013_10130801_226_dialog_content = "E se você puder encontrar as partes apropriadas dessas memórias, talvez você se reencontre com seu Colosso.",
  ui_story_1013_10130801_227_dialog_content = "?!",
  ui_story_1013_10130801_228_dialog_content = "(Se o que ela diz é verdade, então Soroz...)",
  ui_story_1013_10130801_229_dialog_content = "A escolha é sua. Eu apenas forneço uma opção.",
  ui_story_1013_10130801_230_dialog_content = "PlayerName, você está inseguro?",
  ui_story_1013_10130801_231_dialog_content = "Depois do que eles disseram, eu tenho que tentar!",
  ui_story_1013_10130801_232_dialog_content = "Achei que sim. E eu aprovo sua escolha.",
  ui_story_1013_10130801_233_dialog_content = "A atitude do Conselho deixa muito a desejar, mas não dá para perder a chance de dar a volta por cima.",
  ui_story_1013_10130801_234_dialog_content = "Parece que você está de acordo.",
  ui_story_1013_10130801_235_dialog_content = "Trarei o Guardião Um imediatamente.",
  ui_story_1013_10130901_1_dialog_content = "É uma antiga inteligência artificial que sobreviveu até hoje. Ele gerencia cálculos e operações diárias para toda a tecnologia Illumina.",
  ui_story_1013_10130901_2_dialog_content = "Então, o que você acha? Existem semelhanças com os Colossos, não?",
  ui_story_1013_10130901_3_dialog_content = "Uma antiga inteligência artificial que suporta tudo o que a Illumina faz...",
  ui_story_1013_10130901_4_dialog_content = "Estou certamente intrigado. Parece incrível.",
  ui_story_1013_10130901_5_dialog_content = "Eu me pergunto o que parece. Deve ser enorme para conter o poder computacional que o Illumina requer.",
  ui_story_1013_10130901_6_dialog_content = "Tão grande quanto Soroz.",
  ui_story_1013_10130901_7_dialog_content = "E se está tão bem preservado, deve manter toda a sua programação antiga.",
  ui_story_1013_10130901_8_dialog_content = "Deve ser mais inteligente que um Chubb, pelo menos.",
  ui_story_1013_10130901_9_dialog_content = "E deve ter algum tipo de display para as pessoas interagirem com ele.",
  ui_story_1013_10130901_10_dialog_content = "Como o velho \"mordomo\" naquela Cidade Baixa.",
  ui_story_1013_10130901_11_dialog_content = "Olá, Celestita!",
  ui_story_1013_10130901_12_dialog_content = "Você não é o que os dados acumulados levaram o Guardian One a esperar.",
  ui_story_1013_10130901_13_dialog_content = "O-O quê? Certamente este pequeno robô não é...",
  ui_story_1013_10130901_14_dialog_content = "Isso é. Diga olá ao Guardião Um.",
  ui_story_1013_10130901_15_dialog_content = "Não é nada do que eu imaginava!",
  ui_story_1013_10130901_16_dialog_content = "O Guardian One aproveitará sua existência para atualizar os dados do Guardian One sobre Caelestites.",
  ui_story_1013_10130901_17_dialog_content = "Evidentemente, você e o Guardian One compartilham desse sentimento.",
  ui_story_1013_10130901_18_dialog_content = "Celestite, devemos enriquecer os bancos de dados um do outro?",
  ui_story_1013_10130901_19_dialog_content = "Isso... É tentar fazer amigos?",
  ui_story_1013_10130901_20_dialog_content = "Está mostrando sua vontade de trabalhar com você. Guardian One é um tipo amigável de inteligência artificial.",
  ui_story_1013_10130901_21_dialog_content = "Aguarde alguns minutos. Preciso programar o Guardian One com novos protocolos de conexão.",
  ui_story_1013_10130901_22_dialog_content = "Erro. Erro.",
  ui_story_1013_10130901_23_dialog_content = "A entrada do protocolo de conexão falhou. Guardian One não pode se conectar com usuários não identificados.",
  ui_story_1013_10130901_24_dialog_content = "O que isso significa...?",
  ui_story_1013_10130901_25_dialog_content = "<size=30>Achei que havíamos concordado em deixar os celestitas remanescentes tentarem se conectar à sua consciência. Eu assinei o termo de consentimento...</size>",
  ui_story_1013_10130901_26_dialog_content = "Vocês nem chegaram a um acordo sobre isso?",
  ui_story_1013_10130901_27_dialog_content = "S-Desculpe. Guardian One é um defensor das regras.",
  ui_story_1013_10130901_28_dialog_content = "Sem varredura completa e firewalls rígidos, ele não se conectará a nenhum módulo externo.",
  ui_story_1013_10130901_29_dialog_content = "Guardião Deve-se examinar e analisar todos os objetos conhecidos e desconhecidos.",
  ui_story_1013_10130901_30_dialog_content = "O Guardian One está disposto a examinar novos dados de Caelestite. Mas de acordo com o banco de dados existente sobre os celestitas...",
  ui_story_1013_10130901_31_dialog_content = "Com base na análise dos dados anteriores, o Guardian One não pode conceder permissões de controle aos Caelestites.",
  ui_story_1013_10130901_32_dialog_content = "Mas esta não é uma boa oportunidade para atualizar esse banco de dados?",
  ui_story_1013_10130901_33_dialog_content = "Entendido. O Guardião Um realmente prometeu atualizar as estruturas conceituais com este Caelestita mutuamente.",
  ui_story_1013_10130901_34_dialog_content = "Então isso é um sim?",
  ui_story_1013_10130901_35_dialog_content = "O Guardian One realizará um rigoroso teste de campo para registrar e analisar dados sobre as capacidades do Caelestite.",
  ui_story_1013_10130901_36_dialog_content = "As descobertas desse processo informarão ao Guardian One se deve ou não conceder as referidas permissões de controle Caelestite.",
  ui_story_1013_10130901_37_dialog_content = "Er, teste de campo? Nesta sala de reuniões?",
  ui_story_1013_10130901_38_dialog_content = "Caelestite, por favor, coloque-se no modo de emparelhamento.",
  ui_story_1013_10130901_39_dialog_content = "(Oh! Eu acho que isso significa que ele quer um link psíquico?)",
  ui_story_1013_10130901_40_option_content = "Aumento de Força!",
  ui_story_1013_10130901_41_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1013_10130901_42_dialog_content = "Espere!",
  ui_story_1013_10130901_43_dialog_content = "<color=#e8d9bb>Bzzz...</color>",
  ui_story_1013_10130901_44_dialog_content = "Ninguém...",
  ui_story_1013_10130901_45_dialog_content = "Ninguém me disse o que esse teste de campo envolve!",
  ui_story_1013_10130901_46_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_1013_10130901_47_dialog_content = "Isso é... Espere! Este é o lugar do simulador de campo de batalha!",
  ui_story_1013_10130901_48_dialog_content = "É aqui que faremos o teste de campo.",
  ui_story_1013_10130901_49_dialog_content = "Quem é aquele?!",
  ui_story_1013_10130901_50_dialog_content = "Por favor, olhe para cima, Celestita.",
  ui_story_1013_10130901_51_dialog_content = "O Guardião Um está acima de você.",
  ui_story_1013_10130901_52_dialog_content = "O quê?!",
  ui_story_1013_10130901_53_dialog_content = "(Isto é incrível...)",
  ui_story_1013_10130901_54_dialog_content = "(Se eu observar cuidadosamente o espaço acima de mim, posso ver onde a simulação encontra a realidade.)",
  ui_story_1013_10130901_55_dialog_content = "(Esse deve ser o sensor que consigo ver lá em cima. É mais ou menos do mesmo tamanho que o sol teria.)",
  ui_story_1013_10130901_56_dialog_content = "Bem-vindo ao antigo campo de batalha virtual. O Guardian One registrará seu desempenho no teste em tempo real.",
  ui_story_1013_10130901_57_dialog_content = "Certifique-se de mostrar o que você pode fazer, Celestita.",
  ui_story_1013_10130901_58_dialog_content = "Novamente? O que é isso, a nova metodologia de teste padronizada da Illumina!?",
  ui_story_1013_10130901_59_dialog_content = "(Mas se todos eles usam essa mesma simulação, então a consciência de Soroz deve ser...)",
  ui_story_1013_10130901_60_dialog_content = "(Excelente. Vou precisar fazer bom uso desta oportunidade.)",
  ui_story_1013_10130901_61_dialog_content = "Por favor, familiarize-se com o ambiente assim que puder. O Guardian One está prestes a injetar o primeiro lote de dados de batalha.",
  ui_story_1013_10130901_62_dialog_content = "Entendi. Mas antes de começarmos, tenho um pedido.",
  ui_story_1013_10130901_63_dialog_content = "Se eu passar no teste, quero examinar os dados deste campo de batalha em sua totalidade.",
  ui_story_1013_10130901_64_dialog_content = "Isso é incomum...",
  ui_story_1013_10130901_65_dialog_content = "Isso é permitido. Pedido concedido.",
  ui_story_1013_10130901_66_dialog_content = "Agora para a próxima etapa. Você está pronto, Celestita?",
  ui_story_1013_10130901_67_dialog_content = "Deixe a batalha começar.",
  ui_story_1013_10130901_68_dialog_content = "Objetivo: Elimine todos os Eclipsites.",
  ui_story_1013_10130901_69_dialog_content = "Guardian One inicializando...",
  ui_story_1013_10130901_70_dialog_content = "Nesse caso...",
  ui_story_1013_10130901_71_dialog_content = "Vício! Carleen! Estou contando com você!",
  ui_story_1013_10130901_72_dialog_content = "Deixe isso comigo.",
  ui_story_1013_10130901_73_dialog_content = "Deixa comigo.",
  ui_story_1013_10131002_1_dialog_content = "Graah...",
  ui_story_1013_10131002_2_dialog_content = "Objetivo do estágio concluído.",
  ui_story_1013_10131002_3_dialog_content = "Teste concluído. Nota do estágio: B.",
  ui_story_1013_10131002_4_dialog_content = "Gravando novos dados...",
  ui_story_1013_10131002_5_dialog_content = "As habilidades de batalha do Caelestite incluem o gerenciamento de implantações táticas.",
  ui_story_1013_10131002_6_dialog_content = "O Caelestite pode controlar Aurorians e completar missões de combate.",
  ui_story_1013_10131002_7_dialog_content = "Eu sei que isso pode ser um novo conceito para você. Mas em nossos tempos, é totalmente normal.",
  ui_story_1013_10131002_8_dialog_content = "Entendido. O banco de dados do Guardian One sobre Caelestites foi atualizado.",
  ui_story_1013_10131002_9_dialog_content = "Você passou no teste, celestita.",
  ui_story_1013_10131002_10_dialog_content = "E conforme acordado, o Guardian One disponibilizará registros dos dados de hoje para você.",
  ui_story_1013_10131002_11_dialog_content = "Em breve você deixará o antigo campo de batalha. Ele será destruído quando não estiver mais em uso.",
  ui_story_1013_10131002_12_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1013_10131002_13_dialog_content = "Espere...",
  ui_story_1013_10131002_14_dialog_content = "Por favor, não o destrua!",
  ui_story_1013_10131002_15_option_content = "Aumento de Força!",
  ui_story_1013_10131002_16_dialog_content = "Para usar um termo auroriano, celestita, você está sendo \"indelicado\".",
  ui_story_1013_10131002_17_dialog_content = "O Guardião Um reconheceu suas habilidades. Mas isso não significa que você pode se conectar com o Guardian One à vontade.",
  ui_story_1013_10131002_18_dialog_content = "Explicarei a Algol mais tarde.",
  ui_story_1013_10131002_19_dialog_content = "Muito bem. Por favor, explique por que você não deseja que a antiga simulação do campo de batalha seja destruída.",
  ui_story_1013_10131002_20_dialog_content = "Isso não foi incluído em sua solicitação original.",
  ui_story_1013_10131002_21_dialog_content = "O Guardian One não entende por que você deseja examinar e reter esses dados.",
  ui_story_1013_10131002_22_dialog_content = "O que você está planejando?",
  ui_story_1013_10131002_23_dialog_content = "É tipo isso...",
  ui_story_1013_10131002_24_dialog_content = "Meu Colossus teve que me tirar da simulação de batalha anterior. Ao fazê-lo, funcionou mal.",
  ui_story_1013_10131002_25_dialog_content = "Seus dados de consciência ainda estão aqui, em algum lugar naquela vasta pilha de dados.",
  ui_story_1013_10131002_26_dialog_content = "É muito importante para você, Celestita?",
  ui_story_1013_10131002_27_option_content = "Soroz é meu amigo mais próximo.",
  ui_story_1013_10131002_28_dialog_content = "Soroz é mais do que uma peça de tecnologia autoconsciente antiga.",
  ui_story_1013_10131002_29_dialog_content = "Suas memórias contêm todas as aventuras que tivemos juntos.",
  ui_story_1013_10131002_30_dialog_content = "O Guardião Um compreende.",
  ui_story_1013_10131002_31_dialog_content = "Gravando novos dados...",
  ui_story_1013_10131002_32_dialog_content = "O Guardian One atualizou seu banco de dados sobre os caelestitas.",
  ui_story_1013_10131002_33_dialog_content = "O que está acontecendo? Tenho a vaga sensação de que vocês dois se tornaram... amigos.",
  ui_story_1013_10131002_34_dialog_content = "Relatório. O Caelestite e o Guardian One acabaram de concluir uma breve conexão e sincronizar os resultados dos testes.",
  ui_story_1013_10131002_35_dialog_content = "(Ele optou por não revelar o motivo pelo qual eu o vinculei à força...)",
  ui_story_1013_10131002_36_dialog_content = "Ok, então você tem uma perspectiva totalmente nova sobre o Caelestite agora, certo?",
  ui_story_1013_10131002_37_dialog_content = "Podemos continuar o experimento mencionado antes, então?",
  ui_story_1013_10131002_38_dialog_content = "Sim, o Guardian One permite.",
  ui_story_1013_10131002_39_dialog_content = "Caelestita, os dados atuais do antigo campo de batalha foram sincronizados com seu terminal de acordo com o acordo.",
  ui_story_1013_10131002_40_dialog_content = "Obrigado, Guardião Um.",
  ui_story_1013_10131002_41_dialog_content = "Tudo bem então. Voltemos ao principal motivo de estarmos aqui.",
  ui_story_1013_10131002_42_dialog_content = "O Guardian One estudará seu uso de tecnologia antiga por meio de um link telepático com você.",
  ui_story_1013_10131002_43_dialog_content = "Seu feedback será exibido em tempo real na tela da sala de conferência.",
  ui_story_1013_10131002_44_dialog_content = "Isso será incrível para o advento da tecnologia Illumina.",
  ui_story_1013_10131002_45_dialog_content = "Vou tentar o meu melhor.",
  ui_story_1013_10131002_46_dialog_content = "Você certamente passou por muitas simulações de batalha hoje.",
  ui_story_1013_10131002_47_dialog_content = "Não poderei assistir desta vez, mas tenha cuidado.",
  ui_story_1013_10131002_48_dialog_content = "Relaxe Reinhardt. E tecnicamente não estou sozinho.",
  ui_story_1013_10131002_49_dialog_content = "O Guardian One está pronto para fazer o link.",
  ui_story_1013_10131002_50_dialog_content = "(A maior diferença entre o celestita e nossos cientistas é sua atitude em relação à tecnologia.)",
  ui_story_1013_10131002_51_dialog_content = "(Embora as capacidades técnicas do instituto de pesquisa tenham melhorado nos últimos anos...)",
  ui_story_1013_10131002_X51_dialog_content = "(Se não possuirmos a mesma mentalidade, não seremos capazes de romper a barreira que nos mantém longe do cume da tecnologia.)",
  ui_story_1013_10131002_52_dialog_content = "(Espero que eles aprendam com este experimento.)",
  ui_story_1013_10131002_53_dialog_content = "Guardião Um, por favor, abra-se para os pensamentos que estou enviando.",
  ui_story_1013_10131002_54_option_content = "Aumento de Força",
  ui_story_1013_10131002_55_dialog_content = "É assim que a paisagem mental do Guardian One se parece...?",
  ui_story_1013_10131002_56_dialog_content = "O Guardião Um está presente, Celestita.",
  ui_story_1013_10131002_57_dialog_content = "Bem-vindo!",
  ui_story_1013_10131002_58_dialog_content = "Sinta-se à vontade para agir como quiser, pois o professor Algol não detém o comando aqui.",
  ui_story_1013_10131002_59_dialog_content = "Ok, desculpe-me antecipadamente.",
  ui_story_1013_10131002_60_dialog_content = "(É quase como se estivéssemos brincando de fingir...)",
  ui_story_1013_10131002_61_dialog_content = "Seus pensamentos vagueiam, Celestita. Você ainda está preocupado com seu Colosso.",
  ui_story_1013_10131002_62_dialog_content = "(Impressionante... não deveria esperar menos da IA que executa todas as operações no Illumina.)",
  ui_story_1013_10131002_63_dialog_content = "Você confia no Guardião Um o suficiente para transformar esse processo de aprendizado em uma experiência mais desafiadora, Caelestita?",
  ui_story_1013_10131002_64_dialog_content = "Bem, eu confio em você, é por isso que me juntei a você...",
  ui_story_1013_10131002_65_dialog_content = "Confiança verificada. Em seguida, o Guardian One pede para procurar os sinais do Colossus para fins de acesso.",
  ui_story_1013_10131002_66_dialog_content = "Espere o que?!",
  ui_story_1013_10131002_67_dialog_content = "Se você confia no Guardian One, o Guardian One pede para procurar os sinais do Colossus para fins de acesso.",
  ui_story_1013_10131002_68_dialog_content = "(Ele está tentando me ajudar a encontrar uma solução para Soroz?)",
  ui_story_1013_10131002_69_dialog_content = "(Devo fazer o que diz?)",
  ui_story_1013_10131002_70_dialog_content = "Você está hesitando, Celestita.",
  ui_story_1013_10131002_71_dialog_content = "Iniciando análise inteligente...",
  ui_story_1013_10131002_72_dialog_content = "Cenário 1: Guardian One conecta-se com sucesso ao Colossus e obtém seus sinais.",
  ui_story_1013_10131002_73_dialog_content = "Resultado: os dados de percepção do Colossus são recuperados. O Colosso recupera a consciência.",
  ui_story_1013_10131002_74_dialog_content = "Cenário 2: Guardian One conecta-se com sucesso ao Colossus, obtém seus sinais e tenta alterar seus dados.",
  ui_story_1013_10131002_75_dialog_content = "Resultado: O Caelestite detecta a tentativa e corta a ligação entre o Guardian One e o Colossus. O status do Colossus permanece inalterado.",
  ui_story_1013_10131002_76_dialog_content = "Cenário 3—",
  ui_story_1013_10131002_77_dialog_content = "Tudo bem, tudo bem, você não precisa passar por todas as possibilidades...!",
  ui_story_1013_10131002_78_dialog_content = "Eu entendo o que você quer dizer agora. Não é como se eu tivesse opções melhores, de qualquer maneira.",
  ui_story_1013_10131002_79_dialog_content = "Obrigado, Guardião Um, por fazer isso.",
  ui_story_1013_10131002_80_dialog_content = "Caelestite e a antiga tecnologia de IA são amigas.",
  ui_story_1013_10131002_81_dialog_content = "Guardian One também é uma antiga tecnologia de IA.",
  ui_story_1013_10131002_82_dialog_content = "Ok, conto com você então!",
  ui_story_1013_10131002_83_dialog_content = "Vamos voltar à antiga simulação de batalha e salvar a consciência de Soroz!",
  ui_story_1013_10131002_84_dialog_content = "O Guardião Um está pronto. Contagem decrescente...",
  ui_story_1013_10131002_85_dialog_content = "Três...",
  ui_story_1013_10131002_86_dialog_content = "Dois...",
  ui_story_1013_10131002_87_dialog_content = "Um.",
  ui_story_1013_10131101_1_dialog_content = "Cuidado: Simulação de batalha instável.",
  ui_story_1013_10131101_2_dialog_content = "Esteja preparado para situações inesperadas.",
  ui_story_1013_10131101_3_dialog_content = "Está tudo bem, já estive aqui antes.",
  ui_story_1013_10131101_4_dialog_content = "Embora seja diferente da última vez.",
  ui_story_1013_10131101_5_dialog_content = "A simulação está no piloto automático. O tempo avança.",
  ui_story_1013_10131101_6_dialog_content = "O que eu não entendo é, se é uma simulação, como a consciência de Soroz pode estar presa?",
  ui_story_1013_10131101_7_dialog_content = "A consciência de Soroz é pura informação, assim como a simulação.",
  ui_story_1013_10131101_8_dialog_content = "Sua \"mente\" interferiu na simulação e os dados se misturaram.",
  ui_story_1013_10131101_9_dialog_content = "Você deve chegar a Soroz antes que a simulação se autodestrua.",
  ui_story_1013_10131101_10_dialog_content = "Caso contrário, os dados de Soroz também serão destruídos.",
  ui_story_1013_10131101_11_dialog_content = "Quer dizer que a consciência de Soroz desapareceria?",
  ui_story_1013_10131101_12_dialog_content = "Não, mas não seria mais acessível.",
  ui_story_1013_10131101_13_dialog_content = "Em termos do mundo real, estaria enterrado nas ruínas desta simulação.",
  ui_story_1013_10131101_14_dialog_content = "Ele ainda existiria, mas ninguém seria capaz de encontrá-lo.",
  ui_story_1013_10131101_15_dialog_content = "Por que a simulação se autodestruiria?",
  ui_story_1013_10131101_16_dialog_content = "A simulação para esta batalha em particular é especial.",
  ui_story_1013_10131101_17_dialog_content = "Ele não para em nenhum ponto designado e, em vez disso, apaga continuamente os dados...",
  ui_story_1013_10131101_18_dialog_content = "até que nada dele seja deixado, e assim, ele se autodestrói.",
  ui_story_1013_10131101_19_dialog_content = "Especial... Aqueles caras lá fora disseram que a civilização foi destruída uma vez.",
  ui_story_1013_10131101_20_dialog_content = "Esta simulação é um registro daquela catástrofe, certo?",
  ui_story_1013_10131101_21_dialog_content = "De acordo com meus cálculos, quase nenhuma forma de vida poderia ter sobrevivido. Portanto, essa é uma conclusão lógica.",
  ui_story_1013_10131101_22_dialog_content = "Não é à toa que testemunhei o que fiz...",
  ui_story_1013_10131101_23_dialog_content = "Ah!",
  ui_story_1013_10131101_24_dialog_content = "Ahhhhhhh!",
  ui_story_1013_10131101_25_dialog_content = "A humanidade está morrendo... Mesmo os Eclipsitas não sobreviverão.",
  ui_story_1013_10131101_26_dialog_content = "A obliteração total é o fim inevitável desse mundo...",
  ui_story_1013_10131101_27_dialog_content = "<color=#e8d9bb>Crunch!</color>",
  ui_story_1013_10131101_28_dialog_content = "!!!",
  ui_story_1013_10131101_29_dialog_content = "<color=#e8d9bb>Croc, croc!</color>",
  ui_story_1013_10131101_30_dialog_content = "Grah, rugido!",
  ui_story_1013_10131101_31_dialog_content = "Eclipsos?! Achei que todos eles teriam perecido naquele evento apocalíptico.",
  ui_story_1013_10131101_32_dialog_content = "Difícil de acreditar que alguns sobreviveram.",
  ui_story_1013_10131101_33_dialog_content = "O-O que ele está fazendo?",
  ui_story_1013_10131101_34_dialog_content = "O Eclipsite está consumindo vergalhões.",
  ui_story_1013_10131101_35_dialog_content = "<color=#e8d9bb>Croc, croc!</color>",
  ui_story_1013_10131101_36_dialog_content = "Por que faria isso?",
  ui_story_1013_10131101_37_dialog_content = "Mesmo que não haja nada para comer, há coisas melhores para mastigar do que vergalhões... como aquelas pedras no chão.",
  ui_story_1013_10131101_38_dialog_content = "Com base em minhas deduções, os Eclipsites anseiam pelas características dos vergalhões.",
  ui_story_1013_10131101_39_dialog_content = "Características?",
  ui_story_1013_10131101_40_dialog_content = "Os vergalhões não foram destruídos na catástrofe.",
  ui_story_1013_10131101_41_dialog_content = "Os Eclipsitas desejam obter características semelhantes às barras de aço consumindo-as.",
  ui_story_1013_10131101_42_dialog_content = "I-Isso é possível?",
  ui_story_1013_10131101_43_dialog_content = "É apenas uma teoria, mas o fato é que os eclipsitas sobreviveram à catástrofe.",
  ui_story_1013_10131101_44_dialog_content = "Em grandes quantidades.",
  ui_story_1013_10131101_45_dialog_content = "<color=#e8d9bb>Croc, croc!</color>",
  ui_story_1013_10131101_46_dialog_content = "<color=#e8d9bb>Crunch!</color>",
  ui_story_1013_10131101_47_dialog_content = "Graaagh!",
  ui_story_1013_10131101_48_dialog_content = "Uau, canibalismo também?",
  ui_story_1013_10131101_49_dialog_content = "Os eclipsites fizeram muito mais do que a humanidade fez para sobreviver.",
  ui_story_1013_10131101_50_dialog_content = "Portanto, os Eclipsites são a única presença nesta cidade humana.",
  ui_story_1013_10131101_51_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131101_52_dialog_content = "Tantos deles...",
  ui_story_1013_10131101_53_dialog_content = "Muitos Eclipsites mortos ainda estão no chão. Eles constantemente morrem e reaparecem.",
  ui_story_1013_10131101_54_dialog_content = "Sim. A evolução não pode ser alcançada por apenas um único indivíduo, portanto os Eclipsitas escolheram uma alternativa rápida.",
  ui_story_1013_10131101_55_dialog_content = "Eles aperfeiçoaram o melhoramento genético por meio da morte persistente como um grupo até que pudessem se adaptar ao ambiente hostil.",
  ui_story_1013_10131101_56_dialog_content = "Espere, esses Eclipsites estão se reunindo em algum lugar?",
  ui_story_1013_10131101_57_dialog_content = "Sim. Eles estão se movendo na mesma direção. Algo os está atraindo.",
  ui_story_1013_10131101_58_dialog_content = "Atrair eles? Poderia ser...?",
  ui_story_1013_10131101_59_option_content = "Aumento de Força!",
  ui_story_1013_10131101_60_dialog_content = "Soroz! Essa é a consciência de Soroz!",
  ui_story_1013_10131101_61_dialog_content = "Isso explicaria. Os dados não afiliados à simulação tendem a ser extremamente palpáveis.",
  ui_story_1013_10131101_62_dialog_content = "Os Eclipsitos convergiriam em torno dele.",
  ui_story_1013_10131101_63_dialog_content = "Encontre Soroz e podemos resolver seus problemas, certo?",
  ui_story_1013_10131101_64_dialog_content = "Podemos nos conectar ao Soroz e realizar diagnósticos, embora não se saiba se os reparos serão possíveis.",
  ui_story_1013_10131101_65_dialog_content = "Ok, ok, você não precisa ser tão pedante. De qualquer forma, vamos para Soroz!",
  ui_story_1013_10131101_66_dialog_content = "Felizmente, isso é apenas uma simulação, então tenho a capacidade de lutar contra os Eclipsites.",
  ui_story_1013_10131101_67_dialog_content = "Toma essa!",
  ui_story_1013_10131101_68_dialog_content = "<color=#e8d9bb>Blam—Boom!</color>",
  ui_story_1013_10131101_69_dialog_content = "O que é que foi isso? Algo está prestes a cair?",
  ui_story_1013_10131101_70_dialog_content = "O prédio ao seu lado está desabando.",
  ui_story_1013_10131101_71_dialog_content = "Cuidado, a simulação atual é muito instável. Os ataques podem causar o colapso do mundo.",
  ui_story_1013_10131101_72_dialog_content = "Uau, está realmente caindo aos pedaços!",
  ui_story_1013_10131101_73_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1013_10131101_74_dialog_content = "*Tosse* Tanta poeira...",
  ui_story_1013_10131101_75_dialog_content = "Eu quase não fiz nada! Este mundo é tão frágil?",
  ui_story_1013_10131101_76_dialog_content = "Por que apenas...",
  ui_story_1013_10131101_77_dialog_content = "Devido à instabilidade dos dados de batalha, ele acabaria se autodestruindo mesmo sem ninguém fazer nada.",
  ui_story_1013_10131101_78_dialog_content = "Cuidado.",
  ui_story_1013_10131101_79_dialog_content = "!!!",
  ui_story_1013_10131101_80_dialog_content = "<color=#e8d9bb>Bater!!!</color>",
  ui_story_1013_10131101_81_dialog_content = "Nossa, tem fim para isso?",
  ui_story_1013_10131101_82_dialog_content = "Cuidado, o colapso do mundo é uma indicação da autodestruição da simulação em andamento.",
  ui_story_1013_10131101_83_dialog_content = "E a destruição dos dados da simulação causará...",
  ui_story_1013_10131101_84_dialog_content = "Fazer com que os dados de Soroz sejam apagados, certo?",
  ui_story_1013_10131101_85_dialog_content = "Sim. Seu entendimento está correto.",
  ui_story_1013_10131101_86_dialog_content = "Acho que não tenho tempo para reclamar agora...",
  ui_story_1013_10131101_87_dialog_content = "Tenho que chegar a Soroz antes que o mundo desmorone!",
  ui_story_1013_10131202_1_dialog_content = "Trinta.",
  ui_story_1013_10131202_2_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1013_10131202_3_dialog_content = "Nossa!",
  ui_story_1013_10131202_4_dialog_content = "Quase caiu...",
  ui_story_1013_10131202_5_dialog_content = "As fissuras no chão parecem estar me perseguindo!",
  ui_story_1013_10131202_6_dialog_content = "Isso porque você é um dos motivos do colapso.",
  ui_story_1013_10131202_7_dialog_content = "Vinte e cinco.",
  ui_story_1013_10131202_8_dialog_content = "O-O que diabos é com os números que você continua vomitando de forma tão assustadora?!",
  ui_story_1013_10131202_9_dialog_content = "Esse é o tempo que você deixou.",
  ui_story_1013_10131202_10_dialog_content = "Simulei a obliteração por meio de interpretações dos dados da simulação. Esta contagem regressiva é absolutamente precisa.",
  ui_story_1013_10131202_11_dialog_content = "Faltam apenas vinte e poucos segundos? Isso não é-",
  ui_story_1013_10131202_12_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1013_10131202_13_dialog_content = "Vinte.",
  ui_story_1013_10131202_14_dialog_content = "Ok, devo ser capaz de cobrir uma certa distância em 20 segundos.",
  ui_story_1013_10131202_15_dialog_content = "Soroz está logo à frente, posso sentir!",
  ui_story_1013_10131202_16_dialog_content = "Não se esqueça de ficar em guarda contra os Eclipsites.",
  ui_story_1013_10131202_17_dialog_content = "Ok, pare de reclamar!",
  ui_story_1013_10131202_18_dialog_content = "Fora do meu caminho-",
  ui_story_1013_10131202_19_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1013_10131202_20_dialog_content = "Aaaahhhh!",
  ui_story_1013_10131202_21_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1013_10131202_22_dialog_content = "*Tosse*",
  ui_story_1013_10131202_23_dialog_content = "Ai...",
  ui_story_1013_10131202_24_dialog_content = "Quanto tempo eu tenho, Guardião Um...",
  ui_story_1013_10131202_25_dialog_content = "Dez.",
  ui_story_1013_10131202_26_dialog_content = "Porcaria. Eu preciso me apressar.",
  ui_story_1013_10131202_27_dialog_content = "Eu estou quase lá...",
  ui_story_1013_10131202_28_dialog_content = "É logo ali.",
  ui_story_1013_10131202_29_dialog_content = "Cinco.",
  ui_story_1013_10131202_30_dialog_content = "*Tosse*",
  ui_story_1013_10131202_31_dialog_content = "Quatro.",
  ui_story_1013_10131202_32_dialog_content = "Quase, tão perto...",
  ui_story_1013_10131202_33_dialog_content = "Três.",
  ui_story_1013_10131202_34_dialog_content = "Aff... aff...",
  ui_story_1013_10131202_35_dialog_content = "Dois.",
  ui_story_1013_10131202_36_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1013_10131202_37_dialog_content = "Um.",
  ui_story_1013_10131202_38_dialog_content = "Aumento de Força!",
  ui_story_1013_10131202_39_dialog_content = "É você, Soroz?",
  ui_story_1013_10131202_40_dialog_content = "...",
  ui_story_1013_10131202_41_dialog_content = "Achei, achei Soroz!",
  ui_story_1013_10131202_42_dialog_content = "Cheguei a tempo?",
  ui_story_1013_10131202_43_dialog_content = "Rápido, conecte-se, agora mesmo!",
  ui_story_1013_10131202_44_dialog_content = "Conectando à porta de dados de Soroz.",
  ui_story_1013_10131202_45_dialog_content = "Nenhuma resposta. Iniciando entrada forçada.",
  ui_story_1013_10131202_46_dialog_content = "Prepare-se. Sua consciência entrará no espaço de dados de Soroz em breve.",
  ui_story_1013_10131202_47_dialog_content = "O Guardian One não é capaz de prever as situações que você enfrentará.",
  ui_story_1013_10131202_48_dialog_content = "Claro que estou pronto... Seja o que for, não pode ser pior do que isso.",
  ui_story_1013_10131202_49_dialog_content = "Iniciando a transferência de dados.",
  ui_story_1013_10131202_50_dialog_content = "Entrando no Soroz.",
  ui_story_1013_10131202_51_dialog_content = "Está escuro... Já chegamos?",
  ui_story_1013_10131202_52_dialog_content = "Sim. Talvez você devesse tentar abrir os olhos se não consegue ver.",
  ui_story_1013_10131202_53_dialog_content = "Hã?",
  ui_story_1013_10131202_54_dialog_content = "Oh, eu posso ver agora! Espere, como é que eu precisava de um lembrete para isso?",
  ui_story_1013_10131202_55_dialog_content = "É normal. Seus olhos estavam abertos quando a simulação terminou.",
  ui_story_1013_10131202_56_dialog_content = "Em sua mente, seus olhos já estavam abertos, portanto você não pensaria em abri-los novamente.",
  ui_story_1013_10131202_57_dialog_content = "Mas eu baixei você para um novo corpo neste novo espaço, e seus olhos estavam fechados.",
  ui_story_1013_10131202_58_dialog_content = "A dissonância cognitiva entre sua mente e o corpo resultou nisso.",
  ui_story_1013_10131202_59_dialog_content = "Tá bom...",
  ui_story_1013_10131202_60_dialog_content = "Voce entende? Devo repetir—",
  ui_story_1013_10131202_61_dialog_content = "Eu entendo, totalmente!",
  ui_story_1013_10131202_62_dialog_content = "Esse é o Soroz?",
  ui_story_1013_10131202_X62_dialog_content = "Estamos tão perto, mas não posso tocá-lo.",
  ui_story_1013_10131202_X63_dialog_content = "Onde é este lugar?",
  ui_story_1013_10131202_63_dialog_content = "Do ponto de vista visual, você está olhando para o interior de Soroz.",
  ui_story_1013_10131202_64_dialog_content = "Mas é mais preciso chamar isso de cache de dados temporário de Soroz.",
  ui_story_1013_10131202_65_dialog_content = "Em outras palavras, a memória de Soroz.",
  ui_story_1013_10131202_66_dialog_content = "Memória?",
  ui_story_1013_10131202_67_dialog_content = "Porque estamos aqui? Não deveríamos estar resolvendo problemas com Soroz?",
  ui_story_1013_10131202_68_dialog_content = "Sim. A causa do mau funcionamento de Soroz são dados com falhas no cache.",
  ui_story_1013_10131202_69_dialog_content = "Devemos localizar esses dados entre a miríade de outros dados e repará-los.",
  ui_story_1013_10131202_70_dialog_content = "O processo é apenas uma questão de operações de dados para o Guardian One.",
  ui_story_1013_10131202_71_dialog_content = "Mas você não é capaz de fazer isso diretamente com seu cérebro. Portanto, o Guardian One ajudará você a visualizar os dados por meio de sua imaginação.",
  ui_story_1013_10131202_72_dialog_content = "As memórias armazenadas se transformarão em imagens, enquanto as falhas se manifestarão como anomalias.",
  ui_story_1013_10131202_73_dialog_content = "O Guardian One examinará as memórias de Soroz com você durante todo o processo.",
  ui_story_1013_10131202_74_dialog_content = "Vamos resolver os dados corrompidos assim.",
  ui_story_1013_10131202_75_dialog_content = "Serei capaz de reconhecer as falhas?",
  ui_story_1013_10131202_76_dialog_content = "Eles assumirão formas de coisas que você considera repulsivas de acordo com sua mente; portanto, você os reconhecerá.",
  ui_story_1013_10131202_77_dialog_content = "Entendo. Isso parece muito fácil.",
  ui_story_1013_10131202_78_dialog_content = "O Guardian One não pode confirmar essa afirmação.",
  ui_story_1013_10131202_79_dialog_content = "Ok, vamos descobrir isso à medida que avançamos.",
  ui_story_1013_10131202_X79_dialog_content = "Acessando dados... Mudando para uma cabana Soroz.",
  ui_story_1013_10131202_X80_dialog_content = "Ufa! Me sinto muito mais confortável aqui!",
  ui_story_1013_10131202_80_dialog_content = "A propósito, ainda nem sabemos que parte da memória de Soroz é essa.",
  ui_story_1013_10131202_81_dialog_content = "Nada está acontecendo e é um silêncio mortal.",
  ui_story_1013_10131202_82_dialog_content = "Onde estamos agora? Quero dizer, onde estava Soroz nesta memória?",
  ui_story_1013_10131202_83_dialog_content = "O Guardian One não possui esses dados.",
  ui_story_1013_10131202_84_dialog_content = "É verdade que você não pode saber tudo.",
  ui_story_1013_10131202_85_dialog_content = "Conheço Soroz como a palma da minha mão. Vou sair e dar uma olhada.",
  ui_story_1013_10131202_86_dialog_content = "<color=#e8d9bb>*Passos*</color>",
  ui_story_1013_10131202_87_dialog_content = "Ei, como é que todas as portas estão fechadas?",
  ui_story_1013_10131202_88_dialog_content = "Acho que posso abrir isso...",
  ui_story_1013_10131202_89_dialog_content = "<color=#e8d9bb>Bip! Bip! Bip!</color>",
  ui_story_1013_10131202_90_dialog_content = "Um aviso?! O que isso quer dizer?",
  ui_story_1013_10131202_91_dialog_content = "Você está me trancando lá dentro, Soroz?",
  ui_story_1013_10131202_92_dialog_content = "O ar não está circulando entre o exterior e o interior. Soroz lacrou a cabine completamente.",
  ui_story_1013_10131202_93_dialog_content = "O que está acontecendo...",
  ui_story_1013_10131202_94_dialog_content = "Certo, deve haver um log no console de controle...",
  ui_story_1013_10131202_95_dialog_content = "Deixe-me ver... As coordenadas da nossa localização atual são...",
  ui_story_1013_10131202_96_dialog_content = "?!!",
  ui_story_1013_10131202_97_dialog_content = "Não há coordenadas...",
  ui_story_1013_10131202_98_dialog_content = "Nenhuma outra informação também!",
  ui_story_1013_10131202_99_dialog_content = "Por que quase não há nada no log?",
  ui_story_1013_10131202_100_dialog_content = "Esta é a memória de Soroz. Algumas das informações anteriores devem ter sido excluídas.",
  ui_story_1013_10131202_101_dialog_content = "Nada está acontecendo e não há registros. Não há muito em termos de memórias nesta memória, hein?",
  ui_story_1013_10131202_102_dialog_content = "Por que Soroz seria assim?",
  ui_story_1013_10131202_103_dialog_content = "As memórias das máquinas diferem das dos seres biológicos.",
  ui_story_1013_10131202_104_dialog_content = "Tem essas memórias não porque sejam memoráveis, mas porque aconteceram.",
  ui_story_1013_10131202_105_dialog_content = "Soroz não é uma máquina! Seu...",
  ui_story_1013_10131202_106_dialog_content = "Ah, mas você é—",
  ui_story_1013_10131202_107_dialog_content = "Desculpe, não quero dizer que as máquinas são ruins.",
  ui_story_1013_10131202_108_dialog_content = "O Guardião Um não entende por que você se desculparia.",
  ui_story_1013_10131202_109_dialog_content = "É melhor que você não! Eu só gosto de me desculpar, ha... ha.",
  ui_story_1013_10131202_110_dialog_content = "?",
  ui_story_1013_10131202_111_dialog_content = "Aham, estou divagando. Deixe-me ver se consigo mais informações.",
  ui_story_1013_10131202_112_dialog_content = "O Guardião Um encontrou algumas informações.",
  ui_story_1013_10131202_113_dialog_content = "Sério? Onde?",
  ui_story_1013_10131202_114_dialog_content = "Nesta coisa chamada \"Terminal\".",
  ui_story_1013_10131202_115_dialog_content = "Isso é...",
  ui_story_1013_10131202_116_dialog_content = "■■■■■■■■■■■■■",
  ui_story_1013_10131202_117_dialog_content = "O que é isso?",
  ui_story_1013_10131202_118_dialog_content = "Provavelmente é um texto antigo.",
  ui_story_1013_10131202_119_dialog_content = "Um momento. Soroz registrou os procedimentos de tradução.",
  ui_story_1013_10131202_120_dialog_content = "Vou convertê-lo em uma escrita que você possa compreender.",
  ui_story_1013_10131202_121_dialog_content = "\"Mensagens recebidas do solo, possivelmente pela última vez.\"",
  ui_story_1013_10131202_122_dialog_content = "\"A Cidade do Obelisco foi destruída.\"",
  ui_story_1013_10131202_123_dialog_content = "O que? Como... Como pode ser isso?",
  ui_story_1013_10131202_124_dialog_content = "Era apenas uma questão de tempo. Tudo na superfície está desmoronando. A Cidade do Obelisco não é exceção.",
  ui_story_1013_10131202_125_dialog_content = "Estava destinado a acontecer desde a nossa partida.",
  ui_story_1013_10131202_126_dialog_content = "Para onde vamos voltar?",
  ui_story_1013_10131202_127_dialog_content = "Fique tranquilo, mestre Francis disse que quando chegar a hora de voltarmos, seremos sinalizados.",
  ui_story_1013_10131202_128_dialog_content = "Ele fez todos os arranjos. Todos nós confiamos nele, certo?",
  ui_story_1013_10131202_129_dialog_content = "Sim, todos nós confiamos nele.",
  ui_story_1013_10131202_130_dialog_content = "Temos alguma outra escolha? Confiar nele é tudo o que podemos fazer.",
  ui_story_1013_10131202_131_dialog_content = "A propósito, eu só quero saber, quando podemos deixar nossos próprios Colossos?",
  ui_story_1013_10131202_132_dialog_content = "Sou o único neste Colosso e estou ficando louco.",
  ui_story_1013_10131202_133_dialog_content = "Eu quero ver outras pessoas, especialmente quando estamos tão próximos um do outro.",
  ui_story_1013_10131202_134_dialog_content = "E minha irmãzinha também. Tenho tantas saudades dela. Ela está no seu colosso, certo, uh...",
  ui_story_1013_10131202_135_dialog_content = "Desculpe, esqueci seu nome, 217.",
  ui_story_1013_10131202_136_dialog_content = "Sim, ela está bem, não se preocupe.",
  ui_story_1013_10131202_137_dialog_content = "Mas ninguém pode deixar seus colossos ainda... absolutamente não.",
  ui_story_1013_10131202_138_dialog_content = "Se você fizer coisas tolas, acabará morto.",
  ui_story_1013_10131202_139_dialog_content = "Ok, mas há mais alguma coisa para fazermos?",
  ui_story_1013_10131202_140_dialog_content = "Já cansei de comer. Se eu cansar de dormir também, não sei o que será de mim.",
  ui_story_1013_10131202_141_dialog_content = "Não há nada aqui. E a partir de agora também não vai rolar nenhum trecho de notícia de fora.",
  ui_story_1013_10131202_142_dialog_content = "Tudo o que posso fazer é olhar para o terminal o dia inteiro, falando com um monte de números na tela.",
  ui_story_1013_10131202_143_dialog_content = "Mais cedo ou mais tarde, seremos como 79 e esqueceremos o nome de todos, lembrando apenas os números.",
  ui_story_1013_10131202_144_dialog_content = "De jeito nenhum, eu me lembro do seu nome. Você é Parker!",
  ui_story_1013_10131202_145_dialog_content = "Não vou esquecer o nome de ninguém! Celestitas não se chamam por números!",
  ui_story_1013_10131202_146_dialog_content = "Apenas esqueça enquanto pode.",
  ui_story_1013_10131202_147_dialog_content = "Você não ganhará nada se ficar apegado a velhas tradições. Só será mais doloroso quando você esquecer.",
  ui_story_1013_10131202_148_dialog_content = "Você pode se lembrar de um nome que não usa há um dia ou um mês.",
  ui_story_1013_10131202_149_dialog_content = "Mas e um ano depois? Dez anos?",
  ui_story_1013_10131202_150_dialog_content = "Dez anos? Isso é muito tempo...",
  ui_story_1013_10131202_151_dialog_content = "É assim que vamos passar a próxima década?",
  ui_story_1013_10131202_152_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131202_153_dialog_content = "Nós vamos voltar, certo?",
  ui_story_1013_10131202_154_dialog_content = "Sim, nós somos.",
  ui_story_1013_10131202_155_dialog_content = "Mestre Francis disse que vamos receber os sinais para voltar.",
  ui_story_1013_10131202_156_dialog_content = "Todos nós confiamos nele, certo?",
  ui_story_1013_10131301_1_dialog_content = "Este é um registro das conversas dos celestitas!",
  ui_story_1013_10131301_2_dialog_content = "Existem outros Colossos ao nosso redor?",
  ui_story_1013_10131301_3_dialog_content = "Atualmente incapaz de reunir informações suficientes.",
  ui_story_1013_10131301_4_dialog_content = "Mas isso certamente é possível.",
  ui_story_1013_10131301_5_dialog_content = "Pelas conversas, os outros Colossos também estão selados como Soroz.",
  ui_story_1013_10131301_6_dialog_content = "Todo mundo passou dia após dia apenas girando os polegares...",
  ui_story_1013_10131301_7_dialog_content = "(Que sentimento familiar.)",
  ui_story_1013_10131301_8_dialog_content = "(Não foi assim a minha infância?)",
  ui_story_1013_10131301_9_dialog_content = "O Guardião Um postula que a razão para isso é exílio ou refúgio.",
  ui_story_1013_10131301_10_dialog_content = "Exílio: Alguém confinou certos Caelestites nos Colossos para banimento para um local designado.",
  ui_story_1013_10131301_11_dialog_content = "Refúgio: O ambiente fora dos Colossos era inequivocamente inabitável para os celestitas. Portanto, eles foram lacrados para proteger seus passageiros.",
  ui_story_1013_10131301_12_dialog_content = "Pelo tom das conversas, prefiro acreditar que foi para uma emergência.",
  ui_story_1013_10131301_13_dialog_content = "Eles mencionaram um nome familiar... Francis.",
  ui_story_1013_10131301_14_dialog_content = "Você conhece esse nome?",
  ui_story_1013_10131301_15_dialog_content = "Na verdade, não. Tive a honra de ver o que ele deixou para trás.",
  ui_story_1013_10131301_16_dialog_content = "Ele deve ter deixado uma impressão em você, então.",
  ui_story_1013_10131301_17_dialog_content = "É claro. Ele era um celestita muito especial.",
  ui_story_1013_10131301_18_dialog_content = "Você poderia até chamá-lo de antítese de outros celestitas de seu tempo.",
  ui_story_1013_10131301_19_dialog_content = "Ele não escolheu trazer guerra ao mundo. Muito pelo contrário, ele lutou contra o destino que foi imposto aos celestitas.",
  ui_story_1013_10131301_20_dialog_content = "Certa vez, fui profundamente tocado por sua vontade em um momento em que pensei que toda a esperança estava perdida.",
  ui_story_1013_10131301_21_dialog_content = "Felizmente, agora ficou claro que ele não era o único com esse tipo de determinação.",
  ui_story_1013_10131301_22_dialog_content = "Você está se referindo àqueles que estavam conversando?",
  ui_story_1013_10131301_23_dialog_content = "Sim, os celestitas identificados com números.",
  ui_story_1013_10131301_24_dialog_content = "Já se passaram gerações, mas compartilhamos a mesma confiança pelo mesmo nome.",
  ui_story_1013_10131301_25_dialog_content = "Isso por si só me faz sentir que eles tinham fé.",
  ui_story_1013_10131301_26_dialog_content = "Eles não foram forçados ao exílio, mas escolheram seu próprio caminho.",
  ui_story_1013_10131301_27_dialog_content = "Talvez tenha sido algo terrível que os obrigou a adotar medidas tão extremas.",
  ui_story_1013_10131301_28_dialog_content = "Essa é uma teoria muito peculiar. O Guardião Um não entende, mas sua conclusão foi anotada.",
  ui_story_1013_10131301_29_dialog_content = "Você não precisa sair do seu caminho para anotá-lo...",
  ui_story_1013_10131301_30_dialog_content = "A conversa termina aí. Há outras informações disponíveis?",
  ui_story_1013_10131301_31_dialog_content = "Não, isso é tudo.",
  ui_story_1013_10131301_32_dialog_content = "Então o que fazemos agora?",
  ui_story_1013_10131301_33_dialog_content = "Não encontramos nenhuma falha e não temos nenhuma pista.",
  ui_story_1013_10131301_34_dialog_content = "Devemos sentar aqui e experimentar o tédio como os outros celestitas?",
  ui_story_1013_10131301_35_dialog_content = "Esse é certamente um método muito ineficiente para examinar dados.",
  ui_story_1013_10131301_36_dialog_content = "Aguarde enquanto realizo uma pesquisa mais precisa.",
  ui_story_1013_10131301_37_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1013_10131301_38_dialog_content = "O que é que foi isso? O que você fez?",
  ui_story_1013_10131301_39_dialog_content = "Isso pode afetar as imagens que você vê, mas não entre em pânico.",
  ui_story_1013_10131301_40_dialog_content = "Não estou em pânico, apenas confuso.",
  ui_story_1013_10131301_41_dialog_content = "Para colocar de uma maneira que você possa compreender, o Guardião Um está classificando as memórias.",
  ui_story_1013_10131301_42_dialog_content = "Estamos avançando rapidamente nas memórias do passado sem falhas.",
  ui_story_1013_10131301_43_dialog_content = "Você pode fazer isso?",
  ui_story_1013_10131301_44_dialog_content = "Gaaaa!!",
  ui_story_1013_10131301_45_dialog_content = "Nossa!",
  ui_story_1013_10131301_46_dialog_content = "O que está acontecendo?",
  ui_story_1013_10131301_47_dialog_content = "Ignorar todos os dados não corrompidos naturalmente nos faria acabar—",
  ui_story_1013_10131301_48_dialog_content = "Graagh!",
  ui_story_1013_10131301_49_dialog_content = "Ei, você está bem?",
  ui_story_1013_10131301_50_dialog_content = "- onde estão as falhas.",
  ui_story_1013_10131301_51_dialog_content = "Momentos como este exigem uma explicação direta!",
  ui_story_1013_10131301_52_dialog_content = "Então os Eclipsites são as falhas?",
  ui_story_1013_10131301_53_dialog_content = "Sim. As falhas se manifestarão como imagens que você não gosta ou detesta—",
  ui_story_1013_10131301_54_dialog_content = "Graagh!",
  ui_story_1013_10131301_55_dialog_content = "Ei, você—",
  ui_story_1013_10131301_56_dialog_content = "—Tudo bem, minha estrutura de dados é muito durável. Não vai desmoronar facilmente.",
  ui_story_1013_10131301_57_dialog_content = "Tudo bem, entendi, só não se torne mais um saco de pancadas. É assustador.",
  ui_story_1013_10131301_58_dialog_content = "Não sei nada sobre dados, nem tenho tempo para aulas.",
  ui_story_1013_10131301_59_dialog_content = "Mas como eles estão na forma Eclipsita, vou lidar com eles como se fossem Eclipsitas!",
  ui_story_1013_10131302_1_dialog_content = "Torrente Rápida!",
  ui_story_1013_10131302_2_dialog_content = "Gelescer!",
  ui_story_1013_10131302_3_dialog_content = "Uau, isso é incrível...",
  ui_story_1013_10131302_4_dialog_content = "O Guardião Um não está claro sobre o benefício de tais vocalizações na batalha.",
  ui_story_1013_10131302_5_dialog_content = "Na verdade, isso mesmo.",
  ui_story_1013_10131302_6_dialog_content = "Acabei de ver aurorianos fazerem isso o tempo todo em lutas, então pensei em tentar.",
  ui_story_1013_10131302_7_dialog_content = "Talvez seja legal chamar seus movimentos durante a luta?",
  ui_story_1013_10131302_8_dialog_content = "Veja, os inimigos são demolidos depois que eu grito, então funciona.",
  ui_story_1013_10131302_9_dialog_content = "Hum. O Guardian One tentará entender esse argumento que é completamente desprovido de lógica.",
  ui_story_1013_10131302_10_dialog_content = "Ha, vamos deixar isso de lado por enquanto. Então, alguma mudança em Soroz?",
  ui_story_1013_10131302_11_dialog_content = "Aproximadamente 37% das falhas foram removidas. Suas ações foram eficazes.",
  ui_story_1013_10131302_12_dialog_content = "Funções parciais foram restauradas.",
  ui_story_1013_10131302_13_dialog_content = "37%! Eu me livrei de tanto de uma vez?",
  ui_story_1013_10131302_14_dialog_content = "Soroz corrigirá falhas dispersas e isoladas.",
  ui_story_1013_10131302_15_dialog_content = "Portanto, as falhas que ainda nos aguardam exibirão maior coesão.",
  ui_story_1013_10131302_16_dialog_content = "De acordo com os cálculos, resta apenas um lote de falhas.",
  ui_story_1013_10131302_17_dialog_content = "Tudo bem, isso significa que estamos perto de ter sucesso!",
  ui_story_1013_10131302_18_dialog_content = "Sim, mas o lote é mais contencioso. Você deve ter cuidado.",
  ui_story_1013_10131302_19_dialog_content = "Se você estiver pronto, o Guardian One iniciará uma busca de precisão e avançará rapidamente para as falhas.",
  ui_story_1013_10131302_20_dialog_content = "Espere, o segmento de tempo em que estamos agora é diferente de quando começamos, certo?",
  ui_story_1013_10131302_21_dialog_content = "Correto. A pesquisa pulou por um período muito longo.",
  ui_story_1013_10131302_22_dialog_content = "Devido à falta de pontos de referência, o vão exato não pode ser determinado.",
  ui_story_1013_10131302_23_dialog_content = "Se for esse o caso, gostaria de verificar o terminal novamente.",
  ui_story_1013_10131302_24_dialog_content = "Estou curioso sobre o que os celestitas passaram neste momento.",
  ui_story_1013_10131302_25_dialog_content = "Entendido. O Guardian One extrairá as mensagens do terminal para você.",
  ui_story_1013_10131302_26_dialog_content = "Lembre-se de traduzi-lo para mim primeiro.",
  ui_story_1013_10131302_27_dialog_content = "É claro. A otimização e a eficiência impulsionam as ações de toda a IA.",
  ui_story_1013_10131302_28_dialog_content = "E o Guardian One é o modelo mais ideal.",
  ui_story_1013_10131302_29_dialog_content = "Ei, pessoal!",
  ui_story_1013_10131302_30_dialog_content = "Aqui!",
  ui_story_1013_10131302_31_dialog_content = "Isso é bastante repentino, mas hoje é meu aniversário.",
  ui_story_1013_10131302_32_dialog_content = "Alguém quer me ouvir cantar uma música?",
  ui_story_1013_10131302_33_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_34_dialog_content = "Tudo bem, mudei de ideia.",
  ui_story_1013_10131302_35_dialog_content = "Nenhuma música. Vou escrever um poema para vocês!",
  ui_story_1013_10131302_36_dialog_content = "Escrevo bons poemas. Papai disse que eu cresceria para ser um poeta!",
  ui_story_1013_10131302_37_dialog_content = "Lembro-me do seu último aniversário, 35.",
  ui_story_1013_10131302_38_dialog_content = "Esqueci quanto tempo faz, mas definitivamente não faz um ano hoje.",
  ui_story_1013_10131302_39_dialog_content = "Você tem uma boa memória, 982. E aqui eu pensei que poderia enganar todos vocês...",
  ui_story_1013_10131302_40_dialog_content = "Aniversários são importantes, não os use como piadas.",
  ui_story_1013_10131302_41_dialog_content = "Não importa, esqueça o aniversário então.",
  ui_story_1013_10131302_42_dialog_content = "Deixe-me compartilhar uma dica com todos vocês!",
  ui_story_1013_10131302_43_dialog_content = "Aqueça a lata nº 4 e misture com uma lata congelada de nº 15.",
  ui_story_1013_10131302_44_dialog_content = "É super delicioso! Vocês têm que experimentar!",
  ui_story_1013_10131302_45_dialog_content = "Tão alegre como sempre, 35.",
  ui_story_1013_10131302_46_dialog_content = "79! Faz algum tempo!",
  ui_story_1013_10131302_47_dialog_content = "Sim, tem. Eu raramente verifico o terminal agora.",
  ui_story_1013_10131302_48_dialog_content = "Você deveria verificar com mais frequência. Não gosto de falar sozinho.",
  ui_story_1013_10131302_49_dialog_content = "Bem, acho que 982 gosta de ser seu parceiro no crime.",
  ui_story_1013_10131302_50_dialog_content = "Nem pensar, ele aparece ainda menos que você, 79!",
  ui_story_1013_10131302_51_dialog_content = "Ele veio hoje só para me envergonhar!",
  ui_story_1013_10131302_52_dialog_content = "Devo me desculpar?",
  ui_story_1013_10131302_53_dialog_content = "Bem não. Eu estava errado em mentir.",
  ui_story_1013_10131302_54_dialog_content = "Na verdade, resolvi dar uma olhada no terminal porque hoje é especial para mim.",
  ui_story_1013_10131302_55_dialog_content = "Eu gostaria de comemorar isso.",
  ui_story_1013_10131302_56_dialog_content = "Oh, hoje é o aniversário de 982?",
  ui_story_1013_10131302_57_dialog_content = "Não.",
  ui_story_1013_10131302_58_dialog_content = "Você poderia dizer que hoje é exatamente o oposto de um aniversário.",
  ui_story_1013_10131302_59_dialog_content = "982, não me diga...",
  ui_story_1013_10131302_60_dialog_content = "Oh, você não mencionou escrever um poema? Que tal escrever um para mim?",
  ui_story_1013_10131302_61_dialog_content = "Claro! Algum assunto que gostaria de solicitar?",
  ui_story_1013_10131302_62_dialog_content = "O chão. Um poema a ver com a superfície abaixo de nós.",
  ui_story_1013_10131302_63_dialog_content = "Ok, deixe-me pensar sobre isso e escrever um que você vai adorar!",
  ui_story_1013_10131302_64_dialog_content = "Quanto tempo vai levar?",
  ui_story_1013_10131302_65_dialog_content = "Não tenho certeza. As ideias não estão vindo para mim neste momento.",
  ui_story_1013_10131302_66_dialog_content = "Você pode esperar? Falo com você assim que terminar!",
  ui_story_1013_10131302_67_dialog_content = "Você deveria acelerar antes que eu decida que não quero mais.",
  ui_story_1013_10131302_68_dialog_content = "Você não pode fazer isso! Não é todo dia que escrevo um poema para outra pessoa!",
  ui_story_1013_10131302_69_dialog_content = "Você tem que pegar!",
  ui_story_1013_10131302_70_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_71_dialog_content = "Seu poema está pronto, 982!",
  ui_story_1013_10131302_72_dialog_content = "982?",
  ui_story_1013_10131302_73_dialog_content = "Ei, eu coloquei muito esforço e pensei nisso!",
  ui_story_1013_10131302_74_dialog_content = "Eu vou ficar bravo se você não responder logo!",
  ui_story_1013_10131302_75_dialog_content = "982! 982! 982!",
  ui_story_1013_10131302_76_dialog_content = "...",
  ui_story_1013_10131302_77_dialog_content = "Esqueça. Não vou brigar com você por questões triviais.",
  ui_story_1013_10131302_78_dialog_content = "Avise-me quando estiver de volta. Estou aqui o tempo todo.",
  ui_story_1013_10131302_79_dialog_content = "Você chegou muito cedo hoje, 35.",
  ui_story_1013_10131302_80_dialog_content = "Sim, porque fiquei acordado a noite toda terminando o poema para 982.",
  ui_story_1013_10131302_81_dialog_content = "Mas ele...",
  ui_story_1013_10131302_82_dialog_content = "Uau, você trabalhou duro, hein?",
  ui_story_1013_10131302_83_dialog_content = "Mas você sabe como o 982 é inconstante.",
  ui_story_1013_10131302_84_dialog_content = "O que ele queria ontem, pode não querer hoje.",
  ui_story_1013_10131302_85_dialog_content = "Isso é verdade, ele faz isso!",
  ui_story_1013_10131302_86_dialog_content = "Então não se preocupe com isso. Em vez disso, envie para mim. Quero ver o quão talentoso você é.",
  ui_story_1013_10131302_87_dialog_content = "Mas eu esperava que 982 o lesse primeiro, já que é o presente dele.",
  ui_story_1013_10131302_88_dialog_content = "Se quiser, posso escrever um para você também, 79!",
  ui_story_1013_10131302_89_dialog_content = "Por mim?",
  ui_story_1013_10131302_90_dialog_content = "Melhor não, não quero que você queime o óleo da meia-noite novamente.",
  ui_story_1013_10131302_91_dialog_content = "Não, está tudo bem! Temos tempo mais do que suficiente para dormir esses dias.",
  ui_story_1013_10131302_92_dialog_content = "Eu não posso simplesmente fazer você escrever um poema em qualquer dia.",
  ui_story_1013_10131302_93_dialog_content = "Dê-me um no futuro.",
  ui_story_1013_10131302_94_dialog_content = "Esperar por um dia que é especial para mim.",
  ui_story_1013_10131302_95_dialog_content = "Ah, tá bom.",
  ui_story_1013_10131302_96_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_97_dialog_content = "Encontrei um disco de vinil fechado no depósito hoje.",
  ui_story_1013_10131302_98_dialog_content = "É muito bom! Alguém quer ouvir?",
  ui_story_1013_10131302_99_dialog_content = "Ei, tem alguém aí?",
  ui_story_1013_10131302_100_dialog_content = "De qualquer forma, fiz o upload para o terminal, então confira se estiver interessado!",
  ui_story_1013_10131302_101_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_102_dialog_content = "Meu aparelho de banho parou de funcionar...",
  ui_story_1013_10131302_103_dialog_content = "Alguém sabe como consertar isso?",
  ui_story_1013_10131302_104_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_105_dialog_content = "A temperatura aqui baixou. Tentem se manter aquecidos e agasalhados, pessoal.",
  ui_story_1013_10131302_106_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_107_dialog_content = "Uh, eu não falo com ninguém há algum tempo, então eu adoraria bater um papo.",
  ui_story_1013_10131302_108_dialog_content = "Hoje é meu aniversário.",
  ui_story_1013_10131302_109_dialog_content = "É de verdade, desta vez.",
  ui_story_1013_10131302_110_dialog_content = "Alguém, por favor, fale comigo...",
  ui_story_1013_10131302_111_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_112_dialog_content = "Não tenho notícias suas há muito tempo, Sr. 217.",
  ui_story_1013_10131302_113_dialog_content = "Você não estava mentindo quando disse que voltaríamos, certo?",
  ui_story_1013_10131302_114_dialog_content = "Não quer mais seu poema, estúpido 982?",
  ui_story_1013_10131302_115_dialog_content = "Quando te verei de novo no terminal, 79?",
  ui_story_1013_10131302_116_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131302_117_dialog_content = "Suspiro, ninguém está aqui.",
  ui_story_1013_10131302_118_dialog_content = "A história está cheia de minhas mensagens.",
  ui_story_1013_10131302_119_dialog_content = "Eu sinto que todo mundo me odeia.",
  ui_story_1013_10131302_120_dialog_content = "Isso não pode continuar.",
  ui_story_1013_10131302_121_dialog_content = "Saquei!",
  ui_story_1013_10131302_122_dialog_content = "Comando: Verificação de status para todos os Colossos!",
  ui_story_1013_10131302_123_dialog_content = "Colosso 217, perfeito, sem anormalidades.",
  ui_story_1013_10131302_124_dialog_content = "Colosso 982, perfeito, sem anormalidades.",
  ui_story_1013_10131302_125_dialog_content = "Colosso 79, perfeito, sem anormalidades.",
  ui_story_1013_10131302_126_dialog_content = "Colosso 35, perfeito, sem anormalidades.",
  ui_story_1013_10131302_127_dialog_content = "Aqui vamos nós! Isso é um pouco mais animado!",
  ui_story_1013_10131401_1_dialog_content = "Certo, terminei.",
  ui_story_1013_10131401_2_dialog_content = "Sinto uma tristeza indescritível.",
  ui_story_1013_10131401_3_dialog_content = "O Guardião Um não entende.",
  ui_story_1013_10131401_4_dialog_content = "Com base na análise, foi apenas um diálogo normal e não deveria evocar tristeza.",
  ui_story_1013_10131401_5_dialog_content = "Olhe para esses registros. O número de participantes foi diminuindo com o passar do tempo.",
  ui_story_1013_10131401_6_dialog_content = "Até que sobrou apenas um.",
  ui_story_1013_10131401_7_dialog_content = "Eu simpatizo com esse sentimento.",
  ui_story_1013_10131401_8_dialog_content = "Expressar pensamentos sem sentido em voz alta para ninguém, dia após dia...",
  ui_story_1013_10131401_9_dialog_content = "apenas pela chance de obter uma resposta que reacenderia a esperança.",
  ui_story_1013_10131401_10_dialog_content = "Mas no final, mesmo esse simples desejo caiu em vão.",
  ui_story_1013_10131401_11_dialog_content = "Entendido. Você não estava fazendo alusão ao conteúdo real, mas ao número de participantes e à frequência de suas mensagens.",
  ui_story_1013_10131401_12_dialog_content = "O Guardião Um tomou nota desta expressão empática.",
  ui_story_1013_10131401_13_dialog_content = "Eu não chamaria isso de... quer saber, é difícil de explicar.",
  ui_story_1013_10131401_14_dialog_content = "Eu senti o desespero deles por contato social.",
  ui_story_1013_10131401_15_dialog_content = "Essa é a opressão que eu sinto. Você poderia até dizer que eu temo isso.",
  ui_story_1013_10131401_16_dialog_content = "Temer. Você tem medo de ser colocado na posição deles?",
  ui_story_1013_10131401_17_dialog_content = "Sim. Mas quando penso nisso, tive uma experiência semelhante.",
  ui_story_1013_10131401_18_dialog_content = "Certa vez, morei sozinho no subsolo por 17 anos.",
  ui_story_1013_10131401_19_dialog_content = "Não sei se isso é mais longo ou mais curto do que o que eles passaram.",
  ui_story_1013_10131401_20_dialog_content = "Mas meu desespero não era tão forte quanto o deles.",
  ui_story_1013_10131401_21_dialog_content = "Talvez porque eu tinha Soroz comigo o tempo todo.",
  ui_story_1013_10131401_22_dialog_content = "Espere, mas eles também tinham Colossi...",
  ui_story_1013_10131401_23_dialog_content = "É que os deles não pareciam ter nenhuma personalidade.",
  ui_story_1013_10131401_24_dialog_content = "Afinal, você não pode combater o isolamento com respostas meramente mecânicas.",
  ui_story_1013_10131401_25_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1013_10131401_26_dialog_content = "Hum? O que está acontecendo?",
  ui_story_1013_10131401_27_dialog_content = "Você está avançando novamente, Guardião Um?",
  ui_story_1013_10131401_28_dialog_content = "O Guardian One não está executando nenhum comando.",
  ui_story_1013_10131401_29_dialog_content = "Então isso significa que é...",
  ui_story_1013_10131401_30_dialog_content = "I-Parou.",
  ui_story_1013_10131401_31_dialog_content = "Estamos apenas navegando pelos dados armazenados de Soroz em ordem cronológica.",
  ui_story_1013_10131401_32_dialog_content = "Esse fenômeno indica que há um problema com os próprios dados.",
  ui_story_1013_10131401_33_dialog_content = "Dados com defeito?!",
  ui_story_1013_10131401_34_dialog_content = "É estranho, mas na minha avaliação, o mau funcionamento não foi devido à exclusão de dados.",
  ui_story_1013_10131401_35_dialog_content = "Não consigo encontrar uma avaria equivalente na minha base de dados.",
  ui_story_1013_10131401_36_dialog_content = "Tem coisas que nem você sabe?",
  ui_story_1013_10131401_37_dialog_content = "Isto é muito estranho. Talvez isso não seja um mau funcionamento, mas uma anomalia.",
  ui_story_1013_10131401_38_dialog_content = "Uma anomalia?",
  ui_story_1013_10131401_39_dialog_content = "Sim. O Guardian One encontrou dados semelhantes em um log não relacionado à máquina.",
  ui_story_1013_10131401_40_dialog_content = "Assemelha-se muito ao \"esquecimento\" que é comum nos cérebros das criaturas vivas.",
  ui_story_1013_10131401_41_dialog_content = "Esquecimento? Você quer dizer que Soroz esqueceu certas memórias, e é por isso que pulamos certos momentos no tempo?",
  ui_story_1013_10131401_42_dialog_content = "Se a teoria se sustenta, essa é a conclusão lógica.",
  ui_story_1013_10131401_43_dialog_content = "Mas é ilógico que as máquinas esqueçam, pois seguem um protocolo mais intrincado para excluir dados.",
  ui_story_1013_10131401_44_dialog_content = "Na verdade, isso explica porque Soroz não é uma máquina!",
  ui_story_1013_10131401_45_dialog_content = "Reinicie o terminal novamente, Guardian One!",
  ui_story_1013_10131401_46_dialog_content = "Se o tempo passou, deve haver novos registros no terminal.",
  ui_story_1013_10131401_47_dialog_content = "Sim. Por favor, espere.",
  ui_story_1013_10131401_48_dialog_content = "Comando: Check-in, Colossus 35!",
  ui_story_1013_10131401_49_dialog_content = "Colossus 35 está pronto, aguardando ordens.",
  ui_story_1013_10131401_50_dialog_content = "Tudo bem, agora eu vou pegar a história da última vez.",
  ui_story_1013_10131401_51_dialog_content = "Isso é mais ou menos no dia em que parti.",
  ui_story_1013_10131401_52_dialog_content = "Eu tinha acabado de obter minhas credenciais do Navigator e era a primeira vez que pilotava um Colossus.",
  ui_story_1013_10131401_53_dialog_content = "Passei uma noite inteira pensando em todos os possíveis cenários de emergência e como deveria responder.",
  ui_story_1013_10131401_54_dialog_content = "Arrumei minhas malas cheias de roupas que me custaram cada centavo da minha mesada.",
  ui_story_1013_10131401_55_dialog_content = "Planejei guardar a melhor roupa para o nosso regresso a casa. Eu queria voltar como um herói.",
  ui_story_1013_10131401_56_dialog_content = "Como se viu, nada disso acabou sendo útil.",
  ui_story_1013_10131401_57_dialog_content = "Não tivemos nenhuma emergência. Nem uma vez. Eventualmente, eu nem preciso mais pilotar.",
  ui_story_1013_10131401_58_dialog_content = "Essa roupa ainda está cuidadosamente dobrada na mala.",
  ui_story_1013_10131401_59_dialog_content = "Experimentei ontem e descobri que agora é muito pequeno para mim.",
  ui_story_1013_10131401_60_dialog_content = "Suspiro, era um vestido tão bonito... Você ainda está ouvindo, Colossus 35?",
  ui_story_1013_10131401_61_dialog_content = "Comando: Check-in, Colossus 35!",
  ui_story_1013_10131401_62_dialog_content = "Colossus 35 está pronto, aguardando ordens.",
  ui_story_1013_10131401_63_dialog_content = "É bom que você ainda esteja ouvindo. vou continuar...",
  ui_story_1013_10131401_64_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131401_65_dialog_content = "Comando: Check-in, Colossus 982!",
  ui_story_1013_10131401_66_dialog_content = "O Colossus 982 está pronto, aguardando ordens.",
  ui_story_1013_10131401_67_dialog_content = "Bom! Hoje, você será o único a ouvir minhas histórias.",
  ui_story_1013_10131401_68_dialog_content = "Por que não falo sobre depois que partimos? Todos começaram a se acostumar a não se ver e só conversar pelo terminal.",
  ui_story_1013_10131401_69_dialog_content = "Todos os nossos colossos têm designações, então é assim que usamos para nos referirmos uns aos outros.",
  ui_story_1013_10131401_70_dialog_content = "Isso me assustou porque os números parecem impessoais e frios para mim.",
  ui_story_1013_10131401_71_dialog_content = "Então insisti em chamar os outros pelos nomes.",
  ui_story_1013_10131401_72_dialog_content = "Por quanto tempo eu mantive isso? Vários meses, talvez um ano... Não me lembro.",
  ui_story_1013_10131401_73_dialog_content = "Até que esqueci um nome pela primeira vez.",
  ui_story_1013_10131401_74_dialog_content = "Não teria sido educado ligar apenas para ele e mais ninguém pelo número.",
  ui_story_1013_10131401_75_dialog_content = "Não tive escolha a não ser começar a chamar todos por suas designações.",
  ui_story_1013_10131401_76_dialog_content = "982 atribuiu isso ao meu crescimento, mas na verdade eu odiava.",
  ui_story_1013_10131401_77_dialog_content = "Eu não queria crescer ou esquecer os nomes de todos.",
  ui_story_1013_10131401_78_dialog_content = "...",
  ui_story_1013_10131401_79_dialog_content = "Sim, todo mundo merece um nome. Até os Colossos.",
  ui_story_1013_10131401_80_dialog_content = "Eu sei! Vou nomear os Colossos, sem mais números!",
  ui_story_1013_10131401_81_dialog_content = "O primeiro é você, 982. Deixe-me ver...",
  ui_story_1013_10131401_82_dialog_content = "Seu navegador é um cara irritante, mas \"Irritável\" não é um bom nome, então deveria ser outra coisa.",
  ui_story_1013_10131401_83_dialog_content = "Vou te chamar de \"Solituz\"!",
  ui_story_1013_10131401_84_dialog_content = "Comando: Revise o indicativo de chamada para Colossus 982 de 982 para Solituz.",
  ui_story_1013_10131401_85_dialog_content = "Comando copiado. Sinal de chamada revisado.",
  ui_story_1013_10131401_86_dialog_content = "O próximo é 217!",
  ui_story_1013_10131401_87_dialog_content = "Mr. 217 é como nosso líder, então Naviduz será o seu nome!",
  ui_story_1013_10131401_88_dialog_content = "Comando: Revise o indicativo de chamada para Colossus 217 de 217 para Naviduz.",
  ui_story_1013_10131401_89_dialog_content = "Comando copiado. Sinal de chamada revisado.",
  ui_story_1013_10131401_90_dialog_content = "Então temos a Miss 79. Ela é gentil e atenciosa, então precisamos de um nome bonito para seu Colosso!",
  ui_story_1013_10131401_91_dialog_content = "Um nome bonito... Um nome bonito...",
  ui_story_1013_10131401_92_dialog_content = "Está me chamando, 35?",
  ui_story_1013_10131401_93_dialog_content = "79! Você está finalmente no terminal!",
  ui_story_1013_10131401_94_dialog_content = "Sim. Estou impressionado, 35, que você pode manter uma conversa animada por conta própria.",
  ui_story_1013_10131401_95_dialog_content = "Hee. Estou nomeando todos os Colossi agora.",
  ui_story_1013_10131401_96_dialog_content = "Nomeando os Colossos? Isso soa divertido e como algo que você faria.",
  ui_story_1013_10131401_97_dialog_content = "Sim, é divertido! Quero dar um nome a cada Colosso!",
  ui_story_1013_10131401_98_dialog_content = "É uma tarefa árdua, considerando quantos Colossi temos.",
  ui_story_1013_10131401_99_dialog_content = "Bem, nós não temos nada além de tempo de qualquer maneira.",
  ui_story_1013_10131401_100_dialog_content = "É verdade.",
  ui_story_1013_10131401_101_dialog_content = "Oh, eu estava prestes a nomear o seu Colosso. Alguma ideia?",
  ui_story_1013_10131401_102_dialog_content = "Na verdade 35, tenho um pedido para você hoje.",
  ui_story_1013_10131401_103_dialog_content = "Um pedido? Você quer dizer algo que eu posso fazer por você?",
  ui_story_1013_10131401_104_dialog_content = "Sim.",
  ui_story_1013_10131401_105_dialog_content = "Eu gostaria que você me escrevesse um poema.",
  ui_story_1013_10131401_106_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131401_107_dialog_content = "Você faria isso por mim, 35?",
  ui_story_1013_10131401_108_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1013_10131401_109_dialog_content = "O que aconteceu? Eu não terminei de ler!",
  ui_story_1013_10131401_110_dialog_content = "Estamos perdendo tempo?!",
  ui_story_1013_10131401_111_dialog_content = "A alocação de dados é esparsa para este segmento específico.",
  ui_story_1013_10131401_112_dialog_content = "Em um idioma que eu possa entender, por favor.",
  ui_story_1013_10131401_113_dialog_content = "Soroz não tem muitas lembranças dessa época.",
  ui_story_1013_10131401_114_dialog_content = "Para ser justo, não havia muito que valesse a pena lembrar.",
  ui_story_1013_10131401_115_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1013_10131401_116_dialog_content = "Uau! Isso surgiu do nada!",
  ui_story_1013_10131401_117_dialog_content = "Que som é esse?",
  ui_story_1013_10131401_118_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1013_10131401_119_dialog_content = "A porta da cabine está sendo arrombada pelo lado de fora.",
  ui_story_1013_10131401_120_dialog_content = "Quem está fazendo isso? Nunca houve mais ninguém aqui.",
  ui_story_1013_10131401_121_dialog_content = "Espere, a menos que...",
  ui_story_1013_10131401_122_dialog_content = "Avaliação: Chegamos à falha causada pela anomalia de dados.",
  ui_story_1013_10131401_123_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_1013_10131401_124_dialog_content = "Você poderia ter me avisado com antecedência para que eu tivesse tempo de me preparar!",
  ui_story_1013_10131401_125_dialog_content = "Espere, não acho que seja um Eclipsite... O que é isso?",
  ui_story_1013_10131401_126_dialog_content = "...",
  ui_story_1013_10131401_127_dialog_content = "Uma flor? Crescer no chão da cabine?!",
  ui_story_1013_10131401_128_dialog_content = "Eu não preciso que você me diga desta vez para saber que é uma falha.",
  ui_story_1013_10131401_129_dialog_content = "É sim. Mas o Guardião Um não entende como você chegou a essa conclusão.",
  ui_story_1013_10131401_130_dialog_content = "Porque não é lógico! Que flores poderiam crescer aqui?",
  ui_story_1013_10131401_131_dialog_content = "Mas você não disse que falhas tomariam formas de coisas que eu não gosto?",
  ui_story_1013_10131401_132_dialog_content = "Eu realmente não posso odiar algo que eu nunca vi antes.",
  ui_story_1013_10131401_133_dialog_content = "A análise do Guardian One é que a oposição avaliou seu esforço anterior de detecção de falhas.",
  ui_story_1013_10131401_134_dialog_content = "Portanto, fez ajustes para glitch como uma contramedida.",
  ui_story_1013_10131401_135_dialog_content = "Ele acessou a memória de Soroz e se manifestou como entidades individuais mais adequadas para a batalha.",
  ui_story_1013_10131401_136_dialog_content = "Um dos quais você está vendo agora.",
  ui_story_1013_10131401_137_dialog_content = "Essa coisa pode lutar?",
  ui_story_1013_10131401_138_dialog_content = "É um Eclipsite chamado Diavola que foi extraído das memórias de Soroz.",
  ui_story_1013_10131401_139_dialog_content = "É um eclipse? Parecendo assim?",
  ui_story_1013_10131401_140_dialog_content = "Sim.",
  ui_story_1013_10131401_141_dialog_content = "Isso é impressionante, mudando de tática ao vivo com base em batalhas anteriores.",
  ui_story_1013_10131401_142_dialog_content = "Estarei em desvantagem se isso persistir por mais algumas rodadas.",
  ui_story_1013_10131401_143_dialog_content = "Guardião Um, este é o lote final?",
  ui_story_1013_10131401_144_dialog_content = "Sim. Tenha cuidado, ele contém mais falhas do que antes.",
  ui_story_1013_10131401_145_dialog_content = "Suas habilidades de combate também são otimizadas.",
  ui_story_1013_10131401_146_dialog_content = "Consegui, consegui.",
  ui_story_1013_10131401_147_dialog_content = "Se importa de me dizer minhas chances de ganhar?",
  ui_story_1013_10131401_148_dialog_content = "10%.",
  ui_story_1013_10131401_149_dialog_content = "Só isso?",
  ui_story_1013_10131401_150_dialog_content = "Bem, pelo menos não é zero.",
  ui_story_1013_10131401_151_dialog_content = "É inconsequente. Nosso objetivo é remover falhas de dados, não vencer batalhas.",
  ui_story_1013_10131401_152_dialog_content = "Você também terá minha ajuda.",
  ui_story_1013_10131401_153_dialog_content = "Quão raro é ouvir palavras tão reconfortantes de você. Sinto-me muito melhor agora!",
  ui_story_1013_10131401_154_dialog_content = "Mas ainda estou preocupado com a chance de 10%.",
  ui_story_1013_10131401_155_dialog_content = "Você disse que está constantemente otimizando suas ações, certo?",
  ui_story_1013_10131401_156_dialog_content = "Sim.",
  ui_story_1013_10131401_157_dialog_content = "Então observe bem, vou te dar um exemplo.",
  ui_story_1013_10131402_1_dialog_content = "Você deve evitar ataques frontais.",
  ui_story_1013_10131402_2_dialog_content = "Eu sei eu sei! Eu posso fazer isso sozinho!",
  ui_story_1013_10131402_3_dialog_content = "Em seguida, concentre seu ataque no núcleo.",
  ui_story_1013_10131402_4_dialog_content = "Você pode desacelerar e me dar tempo para processar isso sozinho?",
  ui_story_1013_10131402_5_dialog_content = "O núcleo, o núcleo...",
  ui_story_1013_10131402_6_dialog_content = "O Guardian One analisa que o próximo momento é o momento ideal para atacar.",
  ui_story_1013_10131402_7_dialog_content = "Você tem três segundos.",
  ui_story_1013_10131402_8_dialog_content = "Ok, ok, entendi! Não me pressione com contagens regressivas novamente!",
  ui_story_1013_10131402_9_dialog_content = "Foco. Este é o golpe final.",
  ui_story_1013_10131402_10_dialog_content = "Farfalhar—",
  ui_story_1013_10131402_11_dialog_content = "Apontar para o núcleo.",
  ui_story_1013_10131402_12_dialog_content = "Agora!",
  ui_story_1013_10131402_13_dialog_content = "Farfalhar—",
  ui_story_1013_10131402_14_dialog_content = "Sim, acabou!",
  ui_story_1013_10131402_15_dialog_content = "Escaneando o banco de memória de Soroz.",
  ui_story_1013_10131402_16_dialog_content = "Digitalização concluída. Nenhuma falha encontrada.",
  ui_story_1013_10131402_17_dialog_content = "O Guardian One analisa que todas as falhas em Soroz foram removidas.",
  ui_story_1013_10131402_18_dialog_content = "Nossa, acabou tudo!",
  ui_story_1013_10131402_19_dialog_content = "Isso significa que Soroz pode acordar agora?",
  ui_story_1013_10131402_20_dialog_content = "As causas do mau funcionamento foram todas removidas. Atualmente, todos os sistemas da Soroz estão funcionais.",
  ui_story_1013_10131402_21_dialog_content = "Todos os recursos voltaram ao normal.",
  ui_story_1013_10131402_22_dialog_content = "Quanto ao \"despertar\" a que você alude, ou seja, se sua personalidade pode ser restaurada, o Guardião Um não pode confirmar.",
  ui_story_1013_10131402_23_dialog_content = "Hã?",
  ui_story_1013_10131402_24_dialog_content = "O sistema de personalidade de Soroz está além dos parâmetros de compreensão do Guardian One.",
  ui_story_1013_10131402_25_dialog_content = "Portanto, o Guardião Um não pode determinar se ele pode ser restaurado.",
  ui_story_1013_10131402_26_dialog_content = "No entanto, podemos verificar isso através de experimentação específica depois de sairmos deste espaço.",
  ui_story_1013_10131402_27_dialog_content = "Entendo...",
  ui_story_1013_10131402_28_dialog_content = "Concluímos tudo o que é necessário aqui.",
  ui_story_1013_10131402_29_dialog_content = "Podemos voltar à realidade agora para examinar Soroz mais a fundo.",
  ui_story_1013_10131402_30_dialog_content = "Vamos sair?",
  ui_story_1013_10131402_31_dialog_content = "Deixe-me pensar por um minuto...",
  ui_story_1013_10131402_32_dialog_content = "Podemos esperar? Gostaria de verificar o terminal novamente.",
  ui_story_1013_10131402_33_dialog_content = "Estou curioso para saber o que aconteceu com os celestitas.",
  ui_story_1013_10131402_34_dialog_content = "Onde terminou a história deles?",
  ui_story_1013_10131402_35_dialog_content = "Sem problemas. Permanecer no espaço de dados não terá um impacto negativo em Soroz. Você é livre para navegar.",
  ui_story_1013_10131402_36_dialog_content = "O Guardian One extrairá as gravações do terminal.",
  ui_story_1013_10131402_37_dialog_content = "Obrigado, Guardião Um.",
  ui_story_1013_10131402_38_dialog_content = "Você me ajudou muito.",
  ui_story_1013_10131402_39_dialog_content = "Comando: Missão Voyage, das coordenadas registradas de Solituz às de Naviduz, a toda velocidade.",
  ui_story_1013_10131402_40_dialog_content = "Alvos: Aviduz, Soroz.",
  ui_story_1013_10131402_41_dialog_content = "Atrase o comando por 3 segundos.",
  ui_story_1013_10131402_42_dialog_content = "Três, dois, um... Comece!",
  ui_story_1013_10131402_43_dialog_content = "Soroz completou a viagem.",
  ui_story_1013_10131402_44_dialog_content = "Aviduz completou a viagem.",
  ui_story_1013_10131402_45_dialog_content = "Hmm, Soroz é mais uma vez mais rápido.",
  ui_story_1013_10131402_46_dialog_content = "É tão monótono quando os resultados nunca mudam.",
  ui_story_1013_10131402_47_dialog_content = "Vamos tentar a perna de volta na próxima vez. Você precisa fazer melhor, Aviduz.",
  ui_story_1013_10131402_48_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131402_49_dialog_content = "Comando: Solituz, informe o estoque de alimentos.",
  ui_story_1013_10131402_50_dialog_content = "#1 latas restantes: 152. #2 latas restantes: 73. #3 latas restantes...",
  ui_story_1013_10131402_51_dialog_content = "Comando: Naviduz, registre o relatório de Solituz.",
  ui_story_1013_10131402_52_dialog_content = "Gravação. Latas Solituz #1 restantes: 152...",
  ui_story_1013_10131402_53_dialog_content = "É isso mesmo, vocês dois deveriam se comunicar com mais frequência.",
  ui_story_1013_10131402_54_dialog_content = "Não falem apenas comigo, mas entre vocês também.",
  ui_story_1013_10131402_55_dialog_content = "Naviduz, você deveria falar com Solituz.",
  ui_story_1013_10131402_56_dialog_content = "Comando: Naviduz, informe o estoque de alimentos.",
  ui_story_1013_10131402_57_dialog_content = "#1 latas restantes...",
  ui_story_1013_10131402_58_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131402_59_dialog_content = "Hora de contar histórias para dormir de novo, Cutie.",
  ui_story_1013_10131402_60_dialog_content = "Comando: Gracinha, grave a conversa.",
  ui_story_1013_10131402_61_dialog_content = "Gravando conversa.",
  ui_story_1013_10131402_62_dialog_content = "Onde eu parei ontem? Desculpe, minha memória não é tão boa quanto costumava ser.",
  ui_story_1013_10131402_63_dialog_content = "Acho que foi a parte em que te dei um nome.",
  ui_story_1013_10131402_64_dialog_content = "Depois de nomear os outros colossos, voltei minha atenção para o seu.",
  ui_story_1013_10131402_65_dialog_content = "Eu queria um nome especial para você porque você é diferente de qualquer outro.",
  ui_story_1013_10131402_66_dialog_content = "Você é meu Colosso.",
  ui_story_1013_10131402_67_dialog_content = "Eu ponderei por um longo tempo, mas não consegui pensar em nada especial o suficiente...",
  ui_story_1013_10131402_68_dialog_content = "A origem do nome de Cutie foi registrada ontem.",
  ui_story_1013_10131402_69_dialog_content = "Era? Desculpe eu esqueci.",
  ui_story_1013_10131402_70_dialog_content = "Então está feito... O que devo falar agora?",
  ui_story_1013_10131402_71_dialog_content = "Espera.",
  ui_story_1013_10131402_72_dialog_content = "Espere!",
  ui_story_1013_10131402_73_dialog_content = "Acabei de lhe dar uma ordem?",
  ui_story_1013_10131402_74_dialog_content = "Vejamos...",
  ui_story_1013_10131402_75_dialog_content = "Não, não digitei nenhum comando!",
  ui_story_1013_10131402_76_dialog_content = "Como você pode responder a mim sem um comando, Cutie?",
  ui_story_1013_10131402_77_dialog_content = "É porque você me entendeu, certo?",
  ui_story_1013_10131402_78_dialog_content = "Responda-me, linda. Eu sei que você pode!",
  ui_story_1013_10131402_79_dialog_content = "Porque foi detectado conteúdo repetitivo.",
  ui_story_1013_10131402_80_dialog_content = "Cutie gostaria de gravar novos conteúdos.",
  ui_story_1013_10131402_81_dialog_content = "Esses registros...",
  ui_story_1013_10131402_82_dialog_content = "Parece que o Colossus evoluiu ao longo deles.",
  ui_story_1013_10131402_83_dialog_content = "De respostas puramente mecânicas a respostas contendo certa autoconsciência...",
  ui_story_1013_10131402_84_dialog_content = "Também mencionou Soroz... Foi quando começou a desenvolver uma personalidade?",
  ui_story_1013_10131402_85_dialog_content = "O Guardião Um acha as mudanças insondáveis.",
  ui_story_1013_10131402_86_dialog_content = "De acordo com os registros, os Colossi não estavam equipados com um intrincado sistema de IA.",
  ui_story_1013_10131402_87_dialog_content = "É impossível para eles desenvolverem as chamadas personalidades nessas circunstâncias.",
  ui_story_1013_10131402_88_dialog_content = "Mas você viu isso, certo?",
  ui_story_1013_10131402_89_dialog_content = "O Colosso expressou desejo dizendo que \"gostaria\".",
  ui_story_1013_10131402_90_dialog_content = "Sim. Máquinas sem personalidades não deveriam ser capazes disso.",
  ui_story_1013_10131402_91_dialog_content = "O Guardião Um confirma que o Colossus ganhou autoconsciência, mas é incapaz de compreender o processo.",
  ui_story_1013_10131402_92_dialog_content = "Vamos ver se há mais.",
  ui_story_1013_10131402_93_dialog_content = "Conte-me uma piada, Solituz.",
  ui_story_1013_10131402_94_dialog_content = "Não pare até me fazer rir.",
  ui_story_1013_10131402_95_dialog_content = "Procurando entradas de idiomas relacionadas a \"piada\" e \"risada\".",
  ui_story_1013_10131402_96_dialog_content = "\"A gracinha falha e para, mas volta a se mover depois de um tempo.\"",
  ui_story_1013_10131402_97_dialog_content = "\"Um passageiro pergunta o que aconteceu. Cutie diz: \"Tudo bem, acabei de encontrar um novo celestita ousado o suficiente para assumir o reinado.\"\"",
  ui_story_1013_10131402_98_dialog_content = "Hahaha...",
  ui_story_1013_10131402_99_dialog_content = "Engraçado, muito engraçado.",
  ui_story_1013_10131402_100_dialog_content = "Objeção. Solituz já contou a mesma piada várias vezes. É um conteúdo repetitivo.",
  ui_story_1013_10131402_101_dialog_content = "É assim mesmo? Desculpe, não me lembro.",
  ui_story_1013_10131402_102_dialog_content = "É engraçado, mas não volte a repetir as coisas, Solituz.",
  ui_story_1013_10131402_103_dialog_content = "Todos vocês devem exercitar sua criatividade.",
  ui_story_1013_10131402_104_dialog_content = "Aprenda a contar piadas, cantar e escrever poesia.",
  ui_story_1013_10131402_105_dialog_content = "Aprenda tudo o que há de maravilhoso neste mundo.",
  ui_story_1013_10131402_106_dialog_content = "Cópia de. A Solituz ajustará a prioridade das informações repetidas.",
  ui_story_1013_10131402_107_dialog_content = "Não estou contando essa última, então me conte outra piada.",
  ui_story_1013_10131402_108_dialog_content = "A mesma coisa, não pare até me fazer rir.",
  ui_story_1013_10131402_109_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131402_110_dialog_content = "Sugestão da Naviduz para o nome: Cans.",
  ui_story_1013_10131402_111_dialog_content = "Não, isso soa horrível.",
  ui_story_1013_10131402_112_dialog_content = "Sugestão de Aviduz para o nome: Aviduz.",
  ui_story_1013_10131402_113_dialog_content = "Você está tentando relaxar usando seu próprio nome?",
  ui_story_1013_10131402_114_dialog_content = "Sugestão de Soroz para o nome: Sky-sky.",
  ui_story_1013_10131402_115_dialog_content = "Acho que nomear é muito cedo para você, Soroz.",
  ui_story_1013_10131402_116_dialog_content = "Nossa, eu dei a vocês nomes tão bons, e vocês me retribuem dando os nomes mais horríveis.",
  ui_story_1013_10131402_117_dialog_content = "Não importa, continue me ligando 35.",
  ui_story_1013_10131402_118_dialog_content = "Esqueci o nome de todos, então não é tão estranho que agora tenha esquecido o meu.",
  ui_story_1013_10131402_119_dialog_content = "Isso é o que é justo.",
  ui_story_1013_10131402_120_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131402_121_dialog_content = "Hora de contar uma história para dormir, Cutie.",
  ui_story_1013_10131402_122_dialog_content = "Tá bom.",
  ui_story_1013_10131402_123_dialog_content = "A história parou no dia da partida de 35. Cutie deve continuar a partir daí.",
  ui_story_1013_10131402_124_dialog_content = "35 recebeu as credenciais do Navigator pouco antes da partida e foi a primeira vez que 35 pilotou um Colossus.",
  ui_story_1013_10131402_125_dialog_content = "35 passou uma noite inteira pensando em todos os possíveis cenários de emergência e como responder.",
  ui_story_1013_10131402_126_dialog_content = "A bagagem do 35 estava cheia de roupas. Custariam cada centavo da mesada de 35.",
  ui_story_1013_10131402_127_dialog_content = "A melhor roupa era para o regresso a casa, já que o 35 queria regressar como um herói.",
  ui_story_1013_10131402_128_dialog_content = "Oh, havia tal roupa?",
  ui_story_1013_10131402_129_dialog_content = "Isso é ótimo, Cutie. Eu descubro coisas novas toda vez que ouço suas histórias.",
  ui_story_1013_10131402_130_dialog_content = "É isso por hoje. Eu quero ir encontrar essa roupa.",
  ui_story_1013_10131402_131_dialog_content = "Um herói... deve ter sido uma roupa chique.",
  ui_story_1013_10131402_132_dialog_content = "Os Colossos desenvolveram personalidades!",
  ui_story_1013_10131402_133_dialog_content = "Há um monte de gravações como esta deste celestita conversando com os colossos.",
  ui_story_1013_10131402_134_dialog_content = "Se não for um incidente isolado, não pode ser descartado como coincidência ou milagre.",
  ui_story_1013_10131402_135_dialog_content = "Com base na análise atual, o Colossus gerou inteligência em seu tempo com o Caelestita.",
  ui_story_1013_10131402_136_dialog_content = "Autogerado?",
  ui_story_1013_10131402_137_dialog_content = "Todos os Colossos têm uma certa capacidade de aprendizagem.",
  ui_story_1013_10131402_138_dialog_content = "O objetivo disso é otimizar as decisões para uma melhor execução dos comandos.",
  ui_story_1013_10131402_139_dialog_content = "Isso é idêntico ao Guardian One.",
  ui_story_1013_10131402_140_dialog_content = "Sim, lembro que você disse que otimiza todas as suas ações.",
  ui_story_1013_10131402_141_dialog_content = "Essa capacidade básica de aprendizado não é equivalente à inteligência.",
  ui_story_1013_10131402_142_dialog_content = "No entanto, a julgar pelo resultado, o Celestita guiou o processo de aprendizagem até evoluir para a inteligência.",
  ui_story_1013_10131402_143_dialog_content = "Guiado? Como isso foi feito?",
  ui_story_1013_10131402_144_dialog_content = "Você viu isso. Todas as conversas gravadas. Esse foi o processo.",
  ui_story_1013_10131402_145_dialog_content = "Quer dizer conversar com o Colosso?",
  ui_story_1013_10131402_146_dialog_content = "Sim. O celestita continuou conversando com os colossos que eram naturalmente incapazes de conversar.",
  ui_story_1013_10131402_147_dialog_content = "No processo, os Colossi começaram a aprender esses comportamentos.",
  ui_story_1013_10131402_148_dialog_content = "É um processo muito lento. Os cálculos do Guardian One indicam que o sucesso é impossível.",
  ui_story_1013_10131402_149_dialog_content = "Mas o fato é que levou ao nascimento de uma inteligência inesperada.",
  ui_story_1013_10131402_150_dialog_content = "Provavelmente porque o celestita perseverou.",
  ui_story_1013_10131402_151_dialog_content = "Alguém mais investiria todos os seus esforços em falar com uma máquina?",
  ui_story_1013_10131402_152_dialog_content = "Desculpe, finalmente me referi a um Colossus como a máquina.",
  ui_story_1013_10131402_153_dialog_content = "Embora isso pareça razoável até que desenvolvam uma personalidade.",
  ui_story_1013_10131402_154_dialog_content = "Nem todo mundo falaria com uma máquina todos os dias, muito menos por anos.",
  ui_story_1013_10131402_155_dialog_content = "Mas, embora isso pareça ridículo e absurdo, foi o que a celestita fez durante toda a sua vida.",
  ui_story_1013_10131402_156_dialog_content = "Você tem um ponto. O Celestita manteve muito mais conversas com o Colosso por meio de comandos do que as expectativas do Guardião Um.",
  ui_story_1013_10131402_157_dialog_content = "Mesmo considerando a taxa lenta de aprendizado, uma quantidade suficiente de informações acabaria resultando em um resultado favorável.",
  ui_story_1013_10131402_158_dialog_content = "Não foi um milagre, mas uma inevitabilidade.",
  ui_story_1013_10131402_159_dialog_content = "Não, foi um milagre... o celestita foi o milagre.",
  ui_story_1013_10131402_160_dialog_content = "Ela transformou o impossível em inevitabilidade.",
  ui_story_1013_10131402_161_dialog_content = "<color=#e8d9bb>Bip!</color>",
  ui_story_1013_10131402_162_dialog_content = "O que seria?",
  ui_story_1013_10131402_163_dialog_content = "O terminal recebeu uma nova mensagem.",
  ui_story_1013_10131402_164_dialog_content = "Agora? Esta é a primeira mensagem instantânea que vejo nas memórias!",
  ui_story_1013_10131402_165_dialog_content = "Vamos dar uma olhada...",
  ui_story_1013_10131402_166_dialog_content = "Pessoal, olhem aqui.",
  ui_story_1013_10131402_167_dialog_content = "Isso provavelmente é do nada, mas...",
  ui_story_1013_10131402_168_dialog_content = "Não importa, vou tentar resumir.",
  ui_story_1013_10131402_169_dialog_content = "Tenho um favor a pedir a todos vocês.",
  ui_story_1013_10131402_170_dialog_content = "Você pode escrever um poema para mim?",
  ui_story_1013_10131402_171_dialog_content = "Eu quero um sobre \"pessoas\".",
  ui_story_1013_10131402_172_dialog_content = "Um poema?! Não me diga...",
  ui_story_1013_10131402_173_dialog_content = "Sinto muito, mas Cutie não aprendeu a fazer poesia.",
  ui_story_1013_10131402_174_dialog_content = "Dados insuficientes no log de conversação para aprendizado.",
  ui_story_1013_10131402_175_dialog_content = "Talvez 35 possam escrever vários poemas para servir como exemplos de aprendizado.",
  ui_story_1013_10131402_176_dialog_content = "Cutie deve aprender o mais rápido possível.",
  ui_story_1013_10131402_177_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1013_10131402_178_dialog_content = "...",
  ui_story_1013_10131402_179_dialog_content = "Isso é tudo que existe.",
  ui_story_1013_10131402_180_dialog_content = "Sim, eu sei.",
  ui_story_1013_10131402_181_dialog_content = "O Guardião Um não entende. Presentear com poesia é um costume celestita?",
  ui_story_1013_10131402_182_dialog_content = "Acho que foi mais uma convenção.",
  ui_story_1013_10131402_183_dialog_content = "Se tivesse sido transmitido, talvez se tornasse um costume.",
  ui_story_1013_10131402_184_dialog_content = "Mas nunca teria essa chance.",
  ui_story_1013_10131402_185_dialog_content = "O Guardião Um não entende o que você quer dizer.",
  ui_story_1013_10131402_186_dialog_content = "Você pode avançar a linha do tempo, Guardião Um?",
  ui_story_1013_10131402_187_dialog_content = "Eu quero dar uma olhada mais à frente.",
  ui_story_1013_10131402_188_dialog_content = "Não há mais nada para ver aqui.",
  ui_story_1013_10131402_189_dialog_content = "Certamente.",
  ui_story_1013_10131402_190_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1013_10131402_191_dialog_content = "Onde você gostaria de parar?",
  ui_story_1013_10131402_192_dialog_content = "Ainda não sei. Quão mais rápido isso está se movendo em comparação com o normal?",
  ui_story_1013_10131402_193_dialog_content = "Um bilhão de vezes.",
  ui_story_1013_10131402_194_dialog_content = "Muito?!",
  ui_story_1013_10131402_195_dialog_content = "Cada segundo decorrido equivale a trinta anos.",
  ui_story_1013_10131402_196_dialog_content = "Isso é alucinante... Tenho apenas dezessete anos, então isso é menos de um segundo.",
  ui_story_1013_10131402_197_dialog_content = "Mas nada parece estar acontecendo.",
  ui_story_1013_10131402_198_dialog_content = "Sim. O terminal também não recebeu novas mensagens.",
  ui_story_1013_10131402_199_dialog_content = "Vamos matar o tempo.",
  ui_story_1013_10131402_200_dialog_content = "Quero ver o que Soroz via todos os dias lá fora.",
  ui_story_1013_10131402_201_dialog_content = "Tá tão escuro.",
  ui_story_1013_10131402_202_dialog_content = "Quanto tempo se passou? Eu continuo vendo e ouvindo as mesmas coisas, e isso está me fazendo perder meu julgamento.",
  ui_story_1013_10131402_203_dialog_content = "Eu estava me sentindo entediado antes, mas agora estou apenas com sono.",
  ui_story_1013_10131402_204_dialog_content = "Eu quero tirar uma soneca.",
  ui_story_1013_10131402_205_dialog_content = "Se cada segundo são trinta anos, quanto tempo terá passado quando eu acordar?",
  ui_story_1013_10131402_206_dialog_content = "Isso é difícil... Sou péssimo em matemática.",
  ui_story_1013_10131402_207_dialog_content = "Mesmo se eu pudesse descobrir, eu pensaria que era falso, de qualquer maneira.",
  ui_story_1013_10131402_208_dialog_content = "Nesse ritmo, o milagre do Colossus ganhando consciência seria apenas um vislumbre passageiro.",
  ui_story_1013_10131402_209_dialog_content = "Onde a consciência começa? Mesmo eu não sei ao certo se ainda possuo consciência agora.",
  ui_story_1013_10131402_210_dialog_content = "Não sei dizer se estou acordado ou dormindo.",
  ui_story_1013_10131402_211_dialog_content = "Não consigo distinguir nada.",
  ui_story_1013_10131402_212_dialog_content = "Soroz provavelmente está adormecido também.",
  ui_story_1013_10131402_213_dialog_content = "Não importa, não seria uma má ideia dormir ao lado de Soroz por um tempo...",
  ui_story_1013_10131402_214_dialog_content = "<color=#e8d9bb>Bip!</color>",
  ui_story_1013_10131402_215_dialog_content = "!!!",
  ui_story_1013_10131402_216_dialog_content = "O que foi isso?",
  ui_story_1013_10131402_217_dialog_content = "O terminal recebeu uma nova mensagem.",
  ui_story_1013_10131402_218_dialog_content = "Agora? Como isso é possível?",
  ui_story_1013_10131402_219_dialog_content = "Há quanto tempo? Vários milhares ou mesmo dezenas de milhares de anos?",
  ui_story_1013_10131402_220_dialog_content = "Como poderia receber uma nova mensagem agora?",
  ui_story_1013_10131402_221_dialog_content = "Rápido, mostre-me!",
  ui_story_1013_10131402_222_dialog_content = "Terminal de exibição.",
  ui_story_1013_10131402_223_dialog_content = "Esta é diferente de todas as mensagens anteriores.",
  ui_story_1013_10131402_224_dialog_content = "Não veio de nenhum navegador.",
  ui_story_1013_10131402_225_dialog_content = "Isso é... ?",
  ui_story_1013_10131402_226_dialog_content = "Volte, Colossos.",
  ui_story_1013_10131402_227_dialog_content = "!!!",
  ui_story_1013_10131402_228_dialog_content = "Soroz está decolando?!",
  ui_story_1013_10131402_229_dialog_content = "Sim, ele está voando em uma determinada direção em alta velocidade.",
  ui_story_1013_10131402_230_dialog_content = "O Guardian One está fazendo ajustes para que você se adapte à velocidade.",
  ui_story_1013_10131402_231_dialog_content = "Você consegue descobrir onde é o nosso destino?",
  ui_story_1013_10131402_232_dialog_content = "Espere, você não precisa fazer isso!",
  ui_story_1013_10131402_233_dialog_content = "Janela! Olhe pela janela!",
  ui_story_1013_10131402_234_dialog_content = "(Céu, terra, sol... Faz muito, muito tempo que não os vejo.)",
  ui_story_1013_10131402_235_dialog_content = "(Se eu pudesse esticar este momento um bilhão de vezes mais...)",
  ui_story_1013_10131402_236_dialog_content = "(Pena que ninguém conseguiu suportar o salto no tempo o suficiente para saborear a alegria desse tão esperado retorno.)",
  ui_story_1013_10131402_237_dialog_content = "(Ah, e os Colossos, eles provavelmente sentem isso.)",
  ui_story_1013_10131402_238_dialog_content = "(Como um legado, transmitido dos celestitas para seus colossos. Um milagre herdado.)",
  ui_story_1013_10131402_239_dialog_content = "(Um milagre que permite que almas não humanas testemunhem coisas que seus passageiros vivos não poderiam.)",
  ui_story_1013_10131402_240_dialog_content = "(Eu me pergunto que era é esta e que tipo de habitantes estão vivendo neste mundo atual.)",
  ui_story_1013_10131402_241_dialog_content = "(Eles estão olhando para o céu, observando os Colossos eclipsarem o sol?)",
  ui_story_1013_10131402_242_dialog_content = "(Testemunhando gigantes de uma era passada retornando dos céus, carregando o último da espécie de seus donos.)",
  ui_story_1013_10131402_243_dialog_content = "(O Último Celestita se inscreve mais uma vez em outra seção da história.)",
  ui_story_1013_10131402_244_dialog_content = "(Que momento surreal, onde passado, presente e futuro parecem colidir.)",
  ui_story_1013_10131402_245_dialog_content = "(Uma promessa antiga, finalmente cumprida.)",
  ui_story_1013_10131402_246_dialog_content = "Digitalização concluída. Localização atual: Eraveil.",
  ui_story_1013_10131501_1_dialog_content = "Hmm, acho que está desconectado.",
  ui_story_1013_10131501_X1_dialog_content = "Eu...",
  ui_story_1013_10131501_X2_dialog_content = "Relaxar.",
  ui_story_1013_10131501_2_dialog_content = "Yingel, verifique o celestita.",
  ui_story_1013_10131501_3_dialog_content = "Sim!",
  ui_story_1013_10131501_4_dialog_content = "Informe, Guardião Um.",
  ui_story_1013_10131501_5_dialog_content = "Você gastou mais tempo do que o esperado, então espero que haja um retorno adequado.",
  ui_story_1013_10131501_6_dialog_content = "O Guardião Um reuniu informações suficientes sobre os caelestitas.",
  ui_story_1013_10131501_7_dialog_content = "Incluindo valores celestitas vivos, processos de pensamento e alcance emocional.",
  ui_story_1013_10131501_8_dialog_content = "Bem como uma certa porção da antiga história celestita.",
  ui_story_1013_10131501_9_dialog_content = "Qual porção?",
  ui_story_1013_10131501_10_dialog_content = "Das memórias de Soroz, pode-se deduzir que os Celestitas uma vez partiram para se refugiar em seus Colossos durante um período desconhecido.",
  ui_story_1013_10131501_11_dialog_content = "Então, eles retornaram ao Astra após uma passagem de tempo muito significativa.",
  ui_story_1013_10131501_12_dialog_content = "O local retornado foi Eraveil.",
  ui_story_1013_10131501_13_dialog_content = "Eles deixaram Astra em seus Colossos? Eu vejo...",
  ui_story_1013_10131501_14_dialog_content = "Deve ter sido por causa do início da destruição da civilização. Isso deve!",
  ui_story_1013_10131501_15_dialog_content = "Sempre deixamos em branco como a cultura celestita sobreviveu em estudos anteriores.",
  ui_story_1013_10131501_16_dialog_content = "Talvez os registros sobre a partida preencham a lacuna!",
  ui_story_1013_10131501_17_dialog_content = "Sim. Transmita a mesma informação para Barrett mais tarde, Guardião Um.",
  ui_story_1013_10131501_18_dialog_content = "Há algo mais que vale a pena mencionar?",
  ui_story_1013_10131501_19_dialog_content = "Guardian One assistido PlayerName na remoção das falhas de dados de Soroz.",
  ui_story_1013_10131501_20_dialog_content = "O quê?",
  ui_story_1013_10131501_21_dialog_content = "H-Que útil de você.",
  ui_story_1013_10131501_22_dialog_content = "Você tá bem, PlayerName?",
  ui_story_1013_10131501_23_dialog_content = "A desconexão pode causar desconforto, mas deve desaparecer em breve, então não se preocupe.",
  ui_story_1013_10131501_24_dialog_content = "Está tudo bem, não sinto nada fora do comum.",
  ui_story_1013_10131501_25_dialog_content = "Como foi? Você se foi por um bom tempo. O que você viu?",
  ui_story_1013_10131501_26_dialog_content = "Deixe-me pensar por um segundo...",
  ui_story_1013_10131501_27_dialog_content = "Passei pela simulação de colapso, depois visitei as memórias de Soroz...",
  ui_story_1013_10131501_28_dialog_content = "Espera, Soroz! As falhas de Soroz foram todas removidas!",
  ui_story_1013_10131501_29_dialog_content = "Eu quero ver se ele recuperou sua consciência!",
  ui_story_1013_10131501_30_dialog_content = "Foi consertado? Isso é uma feliz surpresa.",
  ui_story_1013_10131501_31_dialog_content = "Farei os preparativos imediatamente.",
  ui_story_1013_10131501_32_dialog_content = "<color=#e8d9bb>\"Controles Primários: Ativos.\"</color>",
  ui_story_1013_10131501_33_dialog_content = "<color=#e8d9bb>\"Módulos biológicos: ativos.\"</color>",
  ui_story_1013_10131501_34_dialog_content = "<color=#e8d9bb>\"Suporte de Vida: Ativo.\"</color>",
  ui_story_1013_10131501_35_dialog_content = "<color=#e8d9bb>\"Motores engajados...\"</color>",
  ui_story_1013_10131501_36_dialog_content = "<color=#e8d9bb>\"16%... 33%...\"</color>",
  ui_story_1013_10131501_37_dialog_content = "<color=#e8d9bb>\"89%... 97%...\"</color>",
  ui_story_1013_10131501_38_dialog_content = "<color=#e8d9bb>\"100%. Envolvido com sucesso.\"</color>",
  ui_story_1013_10131501_39_dialog_content = "Soroz, você pode me ouvir?",
  ui_story_1013_10131501_40_dialog_content = "Soroz!",
  ui_story_1013_10131501_41_dialog_content = "...",
  ui_story_1013_10131501_42_dialog_content = "St... Ainda sem resposta...",
  ui_story_1013_10131501_43_dialog_content = "Guardião Um, verifique o status de Soroz novamente.",
  ui_story_1013_10131501_44_dialog_content = "Confirmado. Nenhum mau funcionamento de dados, todos os recursos normais.",
  ui_story_1013_10131501_45_dialog_content = "Isso foi o que eu pensei.",
  ui_story_1013_10131501_46_dialog_content = "Depois de ouvir o relatório do Guardian One, Caelestite...",
  ui_story_1013_10131501_47_dialog_content = "Eu tenho uma teoria não confirmada. Você gostaria de ouvir?",
  ui_story_1013_10131501_48_dialog_content = "Claro.",
  ui_story_1013_10131501_49_dialog_content = "Pelo que o Guardião Um disse, o ganho de inteligência dos Colossi foi inesperado.",
  ui_story_1013_10131501_50_dialog_content = "Portanto, tal inteligência não é intrínseca ao seu sistema de dados.",
  ui_story_1013_10131501_51_dialog_content = "Uma explicação simples: você ainda pode usar o Soroz mesmo que não tenha autoconsciência.",
  ui_story_1013_10131501_52_dialog_content = "Certo. É apenas incapaz de conversar comigo.",
  ui_story_1013_10131501_53_dialog_content = "Possuir inteligência que não é intrínseca ao sistema de alguém é uma faca de dois gumes.",
  ui_story_1013_10131501_54_dialog_content = "Isso significa que o Colossi não pode executar o autodiagnóstico se ocorrerem problemas e, portanto, é incapaz de solucioná-los.",
  ui_story_1013_10131501_55_dialog_content = "O mau funcionamento ou exclusão de programação que nunca fez parte do sistema, para começar, não tem consequências para o próprio sistema.",
  ui_story_1013_10131501_56_dialog_content = "E é aí que você está agora. Você tem um Colosso funcional e saudável que simplesmente carece de consciência.",
  ui_story_1013_10131501_57_dialog_content = "Você poderia até dizer que um Colossus sem personalidade é, na verdade, o que é normal.",
  ui_story_1013_10131501_58_dialog_content = "Como isso pode ser?",
  ui_story_1013_10131501_59_dialog_content = "Então, não importa o que eu faça, não importa?",
  ui_story_1013_10131501_60_dialog_content = "A razão pela qual não posso restaurar a consciência de Soroz é porque o fato de ter uma era uma anomalia?",
  ui_story_1013_10131501_61_dialog_content = "Essa é a situação em questão.",
  ui_story_1013_10131501_62_dialog_content = "Mas não é impossível para Soroz recuperar sua consciência.",
  ui_story_1013_10131501_63_dialog_content = "Tem como?",
  ui_story_1013_10131501_64_dialog_content = "A solução mais simples é repetir o que eles fizeram.",
  ui_story_1013_10131501_65_dialog_content = "Você viu como Soroz desenvolveu sua consciência em primeiro lugar. Apenas faça isso.",
  ui_story_1013_10131501_66_dialog_content = "Falar com ele? Mas isso vai levar anos...",
  ui_story_1013_10131501_67_dialog_content = "Você ainda é jovem, então ainda pode chegar ao dia em que isso acontecer.",
  ui_story_1013_10131501_68_dialog_content = "...",
  ui_story_1013_10131501_69_dialog_content = "Claro, há uma opção mais eficiente.",
  ui_story_1013_10131501_70_dialog_content = "Você viu na memória de Soroz que não foi o único Colossus a ganhar consciência.",
  ui_story_1013_10131501_71_dialog_content = "Se você conseguir colocar as mãos nos dados desses Colossi como referência...",
  ui_story_1013_10131501_72_dialog_content = "Não deve ser muito difícil recuperar o velho Soroz.",
  ui_story_1013_10131501_73_dialog_content = "Sério?!",
  ui_story_1013_10131501_74_dialog_content = "É impossível fazer algo do nada, mas a imitação é outra história.",
  ui_story_1013_10131501_75_dialog_content = "Não menospreze os cientistas modernos.",
  ui_story_1013_10131501_76_dialog_content = "Isso é ótimo! Vou rastrear outro Colosso com autoconsciência!",
  ui_story_1013_10131501_77_dialog_content = "Sobre isso...",
  ui_story_1013_10131501_78_dialog_content = "O que você acha, Ulisses?",
  ui_story_1013_10131501_79_dialog_content = "O fato de você ter esperado até agora para pedir minha opinião torna óbvio que você quer seguir em frente com isso.",
  ui_story_1013_10131501_80_dialog_content = "É claro. Estamos falando de inteligência acidental. Eu morreria para ter a chance de estudá-lo.",
  ui_story_1013_10131501_81_dialog_content = "Talvez nossa pesquisa possa avançar ainda mais os circuitos de inteligência do Guardião Um.",
  ui_story_1013_10131501_82_dialog_content = "Já que você colocou dessa forma, todos os estudos que beneficiam a Illumina devem ser apoiados.",
  ui_story_1013_10131501_83_dialog_content = "Sobre restaurar a inteligência de Soroz, Caelestita...",
  ui_story_1013_10131501_84_dialog_content = "Se você estiver disposto a cooperar com o esforço de pesquisa da Illumina, podemos fornecer assistência eficaz.",
  ui_story_1013_10131501_85_dialog_content = "Fazer acordos é o foco principal da nossa reunião. Isso não vai mudar.",
  ui_story_1013_10131501_86_dialog_content = "Assistência? Que tipo de assistência?",
  ui_story_1013_10131501_87_dialog_content = "Illumina fez estudos sobre os antigos Colossi antes.",
  ui_story_1013_10131501_88_dialog_content = "Esses arquivos podem ajudá-lo a restaurar a inteligência de Soroz.",
  ui_story_1013_10131501_89_dialog_content = "A Illumina fez esse tipo de estudo?",
  ui_story_1013_10131501_90_dialog_content = "No entanto, não temos os arquivos no momento.",
  ui_story_1013_10131501_91_dialog_content = "Se você aceitar o acordo, enviaremos representantes para negociar com os cientistas que possuem as informações.",
  ui_story_1013_10131501_92_dialog_content = "Uma troca, pelos dados de pesquisa solicitados por Soroz.",
  ui_story_1013_10131501_93_dialog_content = "Em troca, você deve cumprir nossos acordos e cooperar em nossa pesquisa Colossi.",
  ui_story_1013_10131501_94_dialog_content = "Que tal isso? Deve ser um ótimo negócio para você.",
  ui_story_1013_10131501_95_dialog_content = "Hã...",
  ui_story_1013_10131501_96_dialog_content = "Ok, eu aceito os termos.",
  ui_story_1013_10131501_97_dialog_content = "Vou cooperar com sua pesquisa desde que não prejudique Soroz.",
  ui_story_1013_10131501_98_dialog_content = "Não faremos mal a Soroz. Pelo contrário, vou restaurá-lo como você deseja.",
  ui_story_1013_10131501_99_dialog_content = "Estamos todos prontos, então.",
  ui_story_1013_10131501_100_dialog_content = "Yingel, por favor, traga o arquivo da gaveta A-42 Classified.",
  ui_story_1013_10131501_101_dialog_content = "Nosso amigo celestita precisa disso.",
  ui_story_1013_10131501_102_dialog_content = "Sim!",
  ui_story_1013_10131501_103_dialog_content = "(A-42? Esse é um nível de segurança muito alto!)",
  ui_story_1013_10131501_104_dialog_content = "Depois de recuperá-lo, por favor, vá para o meu laboratório.",
  ui_story_1013_10131501_105_dialog_content = "Tenho outra tarefa para você.",
  ui_story_1013_10131501_106_dialog_content = "Sim!",
  ui_story_1013_10131501_107_dialog_content = "Esta é uma informação que eu desconheço, Ulysses.",
  ui_story_1013_10131501_108_dialog_content = "O que mais vocês estão escondendo?",
  ui_story_1013_10131501_109_dialog_content = "Eu não chamaria isso de esconder, apenas ninguém tentou encontrá-lo.",
  ui_story_1013_10131501_110_dialog_content = "Você não estaria interessado, de qualquer maneira.",
  ui_story_1013_10131501_111_dialog_content = "Fica nas Ruínas Aurora.",
  ui_story_1013_10131501_112_dialog_content = "!!!",
  ui_story_1013_10131501_113_dialog_content = "Ano civil da manhã ■■■■, o Colosso envolvido em guerra contra ■■■■.",
  ui_story_1013_10131501_114_dialog_content = "Ano civil da manhã ■■■■, o Colossus sofreu danos de batalha irreversíveis.",
  ui_story_1013_10131501_115_dialog_content = "Ano Civil matinal ■■■■, sinais do Colosso na Cidade Baixa ■■.",
  ui_story_1013_10131501_116_dialog_content = "Que bando de raposas manhosas. Muito disso é censurado.",
  ui_story_1013_10131501_117_dialog_content = "Este é um documento ultrassecreto, PlayerName. Não vamos ler no corredor.",
  ui_story_1013_10131501_118_dialog_content = "Desculpe, Grande Marechal! Eu me emociono quando penso em Soroz.",
  ui_story_1013_10131501_119_dialog_content = "Eu entendo. Você está muito perto de restaurá-lo desta vez.",
  ui_story_1013_10131501_120_dialog_content = "Sim, é assim que eu me sinto também!",
  ui_story_1013_10131501_121_dialog_content = "Este pode não ser o momento apropriado, mas ainda tenho que mencionar algumas coisas.",
  ui_story_1013_10131501_122_dialog_content = "As ruínas de Aurora são estranhas para você, mas você deve reconhecer outra coisa.",
  ui_story_1013_10131501_123_dialog_content = "Você se lembra de Crepúsculo?",
  ui_story_1013_10131501_124_dialog_content = "Sim, Zhao e Sean moram lá.",
  ui_story_1013_10131501_125_dialog_content = "Twilight é um assentamento na região de Aurora Ruins.",
  ui_story_1013_10131501_126_dialog_content = "O lugar é mais complicado do que você pensa.",
  ui_story_1013_10131501_127_dialog_content = "Complicado?",
  ui_story_1013_10131501_128_dialog_content = "O alcance do Conselho Científico naquela região permite apenas que eles observem.",
  ui_story_1013_10131501_129_dialog_content = "Eles não são capazes de fazer muito mais do que isso.",
  ui_story_1013_10131501_130_dialog_content = "Alguém irá impedi-los, o que pode atrapalhar você também.",
  ui_story_1013_10131501_131_dialog_content = "Mas isso não é território da Federação Illumina?",
  ui_story_1013_10131501_132_dialog_content = "É, mas você sabe que também pertence a Lumopolis.",
  ui_story_1013_10131501_133_dialog_content = "Além disso, você não pode ver as facções e alianças com noções preconcebidas.",
  ui_story_1013_10131501_134_dialog_content = "Tudo é completamente diferente lá.",
  ui_story_1013_10131501_135_dialog_content = "A guerra perene há muito queima a terra com pólvora.",
  ui_story_1013_10131501_136_dialog_content = "Os cavaleiros não se curvam a Schwartz. Os crentes adoram um sol diferente.",
  ui_story_1013_10131501_137_dialog_content = "Soldados também não escutam algum Grande Marechal de longe.",
  ui_story_1013_10131501_138_dialog_content = "Entendo...",
  ui_story_1013_10131501_139_dialog_content = "Portanto, o Conselho Científico pode não ser capaz de lhe dar o que prometeu.",
  ui_story_1013_10131501_140_dialog_content = "Eles planejam trocar recursos médicos e militares por informações, o que parece uma troca justa no papel.",
  ui_story_1013_10131501_141_dialog_content = "Infelizmente, trocas justas não funcionam lá.",
  ui_story_1013_10131501_142_dialog_content = "Este negócio vai se arrastar ou até mesmo desaparecer sem um gemido.",
  ui_story_1013_10131501_143_dialog_content = "De jeito nenhum! Não posso deixar a oportunidade escapar! É minha única esperança!",
  ui_story_1013_10131501_144_dialog_content = "Quem sabe o que mais poderia acontecer com sua consciência durante este período instável...",
  ui_story_1013_10131501_145_dialog_content = "Eu não posso esperar. Eu tenho que ir para as Ruínas Aurora e negociar eu mesmo!",
  ui_story_1013_10131501_146_dialog_content = "Com Soroz, tenho certeza de que chegarei lá mais rápido que as tropas de ligação.",
  ui_story_1013_10131501_147_dialog_content = "Mesmo se eu tiver problemas, é melhor resolver sozinho do que me preocupar com isso aqui!",
  ui_story_1013_10131501_148_dialog_content = "Achei que você diria isso. Eu admiro e elogio sua unidade.",
  ui_story_1013_10131501_149_dialog_content = "Se você gostaria de lidar com isso pessoalmente, você deve estar totalmente preparado.",
  ui_story_1013_10131501_150_dialog_content = "Preparado para lidar com Eclipsites, batalhas armadas e até desastres naturais.",
  ui_story_1013_10131501_151_dialog_content = "Farei tudo o que puder para ajudá-lo a se preparar em Gannon, mas assim que partir, estará por sua conta.",
  ui_story_1013_10131501_152_dialog_content = "Não estou exatamente sozinho. Não se esqueça, os celestitas não entram em batalha sozinhos.",
  ui_story_1013_10131501_153_dialog_content = "Em seguida, certifique-se de obter parceiros confiáveis.",
  ui_story_1013_10131501_154_dialog_content = "Não se preocupe, embora eu nunca tenha confiado em mim mesmo...",
  ui_story_1013_10131501_155_dialog_content = "Eu confio 100% nos meus amigos!",
  ui_story_1013_10131501_156_dialog_content = "Essa é uma frase de efeito bastante cafona.",
  ui_story_1013_10131501_157_dialog_content = "Hum...",
  ui_story_1013_10131501_158_dialog_content = "Mas tendo lutado ao seu lado, acho que posso entender sua atitude.",
  ui_story_1013_10131501_159_dialog_content = "Não é a vitória que importa, mas o medo do fracasso. Não é o destaque que importa, mas a perseverança silenciosa.",
  ui_story_1013_10131501_160_dialog_content = "É uma atitude que motiva e une guerreiros.",
  ui_story_1013_10131501_161_dialog_content = "Você sabe o que é mais forte que a coragem? Ousadia dos vulneráveis.",
  ui_story_1014_10140101_1_dialog_content = "<color=#e8d9bb>Federação Illumina, Gannon City, Centro de Pesquisa Illumina</color>",
  ui_story_1014_10140101_2_dialog_content = "Eu vejo! Que missão gloriosa!",
  ui_story_1014_10140101_3_dialog_content = "Uma cidade misteriosa, cheia de perigos, que faz fronteira com a Dark Zone! E aventuras emocionantes!",
  ui_story_1014_10140101_4_dialog_content = "Estou pronto e ansioso para ir, PlayerName!",
  ui_story_1014_10140101_5_dialog_content = "É claro-",
  ui_story_1014_10140101_6_dialog_content = "-NÃO!",
  ui_story_1014_10140101_7_dialog_content = "<size=45>O quê?!</size>",
  ui_story_1014_10140101_8_dialog_content = "Desconsiderando por um momento o quão perigosa uma cidade fora da linha de defesa Illumina poderia ser...",
  ui_story_1014_10140101_9_dialog_content = "E quão duro é o ambiente perto da Dark Zone...",
  ui_story_1014_10140101_10_dialog_content = "Você não pode se afastar tanto de Illumina em sua condição, Vice.",
  ui_story_1014_10140101_11_dialog_content = "O que isso tem a ver com alguma coisa? Estou bem agora, não estou?",
  ui_story_1014_10140101_12_dialog_content = "Não significa não!",
  ui_story_1014_10140101_13_dialog_content = "A Illumina está começando a trabalhar na atualização de seus equipamentos médicos.",
  ui_story_1014_10140101_14_dialog_content = "De qualquer forma, você deve ficar e se recuperar no centro médico até que esteja totalmente recuperado.",
  ui_story_1014_10140101_15_dialog_content = "<color=#e8d9bb>Zumbido—Buzz—</color>",
  ui_story_1014_10140101_16_dialog_content = "Hum? Segure esse pensamento, PlayerName.",
  ui_story_1014_10140101_17_dialog_content = "Olá...? Ah-!",
  ui_story_1014_10140101_18_dialog_content = "L-Tenente Vice relatando, Grande Marechal!",
  ui_story_1014_10140101_19_dialog_content = "(O Grande Marechal? Ela provavelmente está preocupada com Vice também... Certamente?)",
  ui_story_1014_10140101_20_dialog_content = "Oh? Uma missão urgente?",
  ui_story_1014_10140101_21_dialog_content = "(O quê?! Urgente? Agora?!)",
  ui_story_1014_10140101_22_dialog_content = "Entendido. Deixe-me fazer algumas anotações.",
  ui_story_1014_10140101_23_dialog_content = "<size=33>O Conselho... Crepúsculo... Ruínas de Aurora... troca de informações...</size>",
  ui_story_1014_10140101_24_dialog_content = "(Isso é basicamente tudo o que acabamos de ver lá atrás!)",
  ui_story_1014_10140101_25_dialog_content = "Sim, entendi.",
  ui_story_1014_10140101_26_dialog_content = "Obrigado por acreditar em mim. Fique tranquilo, farei o trabalho.",
  ui_story_1014_10140101_27_dialog_content = "(O que diabos ela foi designada para fazer desta vez?)",
  ui_story_1014_10140101_28_dialog_content = "Entendido! Vou completar a missão com foco máximo!",
  ui_story_1014_10140101_29_dialog_content = "Então, PlayerName, fala o que quiser, mas eu vou com você!",
  ui_story_1014_10140101_30_dialog_content = "É uma ordem direta da própria Grande Marechal.",
  ui_story_1014_10140101_31_dialog_content = "Não dificulte as coisas para mim, nem envergonhe o Grande Marechal.",
  ui_story_1014_10140101_32_dialog_content = "Como isso está acontecendo?!",
  ui_story_1014_10140101_33_dialog_content = "O Grande Marechal parecia um pouco preocupado. Ela parece estar um pouco envolvida em seus deveres.",
  ui_story_1014_10140101_34_dialog_content = "\"Tenente Vice, você deve representar o quartel-general da Illumina e apoiar a missão do Caelestite com as forças de fronteira.\"",
  ui_story_1014_10140101_35_dialog_content = "Essas foram as instruções dela.",
  ui_story_1014_10140101_36_dialog_content = "Mesmo assim-",
  ui_story_1014_10140101_37_dialog_content = "Não se preocupe, PlayerName.",
  ui_story_1014_10140101_38_dialog_content = "Por que você não me conta os detalhes desta tarefa?",
  ui_story_1014_10140101_39_dialog_content = "... Multar. Então deixe-me começar de cima. Na reunião do conselho mais cedo...",
  ui_story_1014_10140101_40_dialog_content = "<color=#e8d9bb>Federação Illumina, cidade de Gannon, sala de conferências Illumina</color>",
  ui_story_1014_10140101_41_dialog_content = "Se você aceitar o acordo, enviaremos representantes para negociar com os cientistas que possuem as informações.",
  ui_story_1014_10140101_42_dialog_content = "Uma troca, pelos dados de pesquisa solicitados por Soroz.",
  ui_story_1014_10140101_43_dialog_content = "Não há mais atrasos. Eu mesmo tenho que ir para as Ruínas Aurora para fazer a troca!",
  ui_story_1014_10140101_44_dialog_content = "Com Soroz, tenho certeza de que chegarei lá mais rápido que as tropas de ligação.",
  ui_story_1014_10140101_45_dialog_content = "Você quer dizer que se comunicará com aqueles que vivem nas ruínas de Aurora como representante da sede da Illumina?",
  ui_story_1014_10140101_46_dialog_content = "Não acho que você tenha esse tipo de autoridade, celestita.",
  ui_story_1014_10140101_47_dialog_content = "Qual é o problema? Não torne as coisas políticas, Ulisses.",
  ui_story_1014_10140101_48_dialog_content = "Este é, em última análise, um comércio entre PlayerName e Crepúsculo. A Illumina está apenas fornecendo um meio para esse fim.",
  ui_story_1014_10140101_49_dialog_content = "Ya—wn... Estou ansioso por isso.",
  ui_story_1014_10140101_50_dialog_content = "Para algo como o <color=#FFB400>Fragilidade Celestial</color>, realmente precisamos das pessoas certas para acompanhá-lo.",
  ui_story_1014_10140101_51_dialog_content = "Fragilidade Celestial? Isso é o que você espera negociar, certo?",
  ui_story_1014_10140101_52_dialog_content = "Sim. O quartel-general já negociou com as forças Illumina estacionadas em Crepúsculo.",
  ui_story_1014_10140101_53_dialog_content = "Devido aos frequentes combates na zona de fronteira, eles decidiram enviar um ciborgue de combate para a área.",
  ui_story_1014_10140101_54_dialog_content = "É o último produto da Ulisses.",
  ui_story_1014_10140101_55_dialog_content = "Use isso para interagir com as forças Illumina lá, e eles vão oferecer a você dados relevantes de pesquisa do Colossus em troca.",
  ui_story_1014_10140101_56_dialog_content = "Mas o ciborgue é muito precioso e frágil, o máximo cuidado deve ser tomado em trânsito.",
  ui_story_1014_10140101_57_dialog_content = "Em vez de transportá-lo em um dirigível, é mais seguro que o celestita o entregue especialmente.",
  ui_story_1014_10140101_58_dialog_content = "Então, a lendária Fragilidade Celestial...",
  ui_story_1014_10140101_59_dialog_content = "Isso mesmo. Está em nossas mãos.",
  ui_story_1014_10140101_60_dialog_content = "Você me deixou realmente curioso agora! Eu me pergunto que tipo de ciborgue é.",
  ui_story_1014_10140101_61_dialog_content = "<color=#e8d9bb><size=30>Clang...</size></color>",
  ui_story_1014_10140101_62_dialog_content = "PlayerName! C-Venha rápido! Está fazendo algum tipo de barulho!",
  ui_story_1014_10140101_63_dialog_content = "Q-que barulho? Acho que não ouvi nada...",
  ui_story_1014_10140101_64_dialog_content = "... Talvez eu esteja um pouco nervoso.",
  ui_story_1014_10140101_65_dialog_content = "O que você estava pensando, PlayerName?",
  ui_story_1014_10140101_66_dialog_content = "Estou um pouco... preocupado.",
  ui_story_1014_10140101_67_dialog_content = "Soroz não está muito bem. Vai ser difícil para ele completar até mesmo o trabalho logístico mais básico, e se...",
  ui_story_1014_10140101_68_dialog_content = "Se tivermos algum problema, pensaremos em algo.",
  ui_story_1014_10140101_69_dialog_content = "Por enquanto, precisamos parar de falar e começar a se mover!",
  ui_story_1014_10140101_70_dialog_content = "Sim, você provavelmente está certo...",
  ui_story_1014_10140101_71_dialog_content = "<color=#e8d9bb>Soroz, a ponte</color>",
  ui_story_1014_10140101_72_dialog_content = "(Sistemas de controle primário... Verifique.)",
  ui_story_1014_10140101_73_dialog_content = "(Função do motor... Verifique.)",
  ui_story_1014_10140101_74_dialog_content = "Eu preciso lidar com essas coisas sozinho agora...",
  ui_story_1014_10140101_75_dialog_content = "(Eu deveria ir para o salão e verificar as coisas.)",
  ui_story_1014_10140101_76_dialog_content = "... Huh?!",
  ui_story_1014_10140101_77_dialog_content = "Carleen, Beretta?! E... Yingel??",
  ui_story_1014_10140101_78_dialog_content = "O que vocês estão fazendo aqui?",
  ui_story_1014_10140101_79_dialog_content = "Carleen, nem tive tempo de te informar...",
  ui_story_1014_10140101_80_dialog_content = "Vice já fez. Disse que você estava prestes a partir para a noite eterna, PlayerName.",
  ui_story_1014_10140101_81_dialog_content = "Apenas vocês dois lá fora, lutando sozinhos. Como poderíamos não nos preocupar?",
  ui_story_1014_10140101_82_dialog_content = "Hehe, a boa e velha confiável Carleen.",
  ui_story_1014_10140101_83_dialog_content = "Eu estava preocupado que você não chegaria a tempo!",
  ui_story_1014_10140101_84_dialog_content = "Bem, faz muito tempo desde que Lumopolis contatou as forças de fronteira em Crepúsculo.",
  ui_story_1014_10140101_85_dialog_content = "Então eu trouxe a Beretta, já que podemos fazer uma inspeção enquanto estivermos lá.",
  ui_story_1014_10140101_86_dialog_content = "Que reencontro, PlayerName.",
  ui_story_1014_10140101_87_dialog_content = "Você não parece muito bem. Precisa que eu lhe dê uma pequena injeção?",
  ui_story_1014_10140101_88_dialog_content = "O-o que?!",
  ui_story_1014_10140101_89_dialog_content = "Estou brincando.",
  ui_story_1014_10140101_90_dialog_content = "Quem é esse Iluminado? Nos encontramos em Eraveil? Você não parece familiar.",
  ui_story_1014_10140101_91_dialog_content = "Aquele Illuminan de cabelo branco não te seguiu desta vez?",
  ui_story_1014_10140101_92_dialog_content = "Boas maneiras, Beretta.",
  ui_story_1014_10140101_93_dialog_content = "Sim, senhora! Senhora Carleen.",
  ui_story_1014_10140101_94_dialog_content = "Coronel Yingel, dos Serviços de Segurança Interna da Federação Illumina.",
  ui_story_1014_10140101_95_dialog_content = "É um prazer finalmente conhecê-lo, Tenente Vice. Há tantas coisas que quero perguntar sobre o Colosso e o Celestita.",
  ui_story_1014_10140101_96_dialog_content = "Ai...! V-você é muito gentil. É uma honra conhecê-lo!",
  ui_story_1014_10140101_97_dialog_content = "(Vice não tem ideia do que fazer!)",
  ui_story_1014_10140101_98_dialog_content = "Se me permite a ousadia, posso perguntar se o Conselho Científico providenciou sua presença aqui?",
  ui_story_1014_10140101_99_dialog_content = "Desculpe, mas estou aqui em uma missão. No entanto...",
  ui_story_1014_10140101_100_dialog_content = "Estou pessoalmente feliz em visitar a zona de guerra da fronteira.",
  ui_story_1014_10140101_101_dialog_content = "Fornecerei informações específicas confiáveis de acordo com o Arquivo A-42.",
  ui_story_1014_10140101_102_dialog_content = "Acredito que você também pode precisar de um terceiro para verificar a autenticidade da Fragilidade Celestial.",
  ui_story_1014_10140101_103_dialog_content = "Isso é verdade, mas—",
  ui_story_1014_10140101_104_dialog_content = "Não se preocupe. O quartel-general está assumindo a liderança nisso, então não vou interferir indevidamente, quer as coisas corram bem ou não.",
  ui_story_1014_10140101_105_dialog_content = "(Não há razão para duvidar dela...)",
  ui_story_1014_10140101_106_dialog_content = "Espere... Isso não deixa apenas Reinhardt para falar com o Conselho de Ciência?",
  ui_story_1014_10140101_107_dialog_content = "Certamente você não está preocupado com o Grande Marechal?",
  ui_story_1014_10140101_108_dialog_content = "Acho que você está certo, não preciso me preocupar com Reinhardt.",
  ui_story_1014_10140101_109_dialog_content = "<color=#e8d9bb>Enquanto isso, Illumina Conference Hall</color>",
  ui_story_1014_10140101_110_dialog_content = "Caçar Forsakin e Helios não é uma missão estratégica, Reinhardt. Acho que não há necessidade de você fazer isso sozinho.",
  ui_story_1014_10140101_111_dialog_content = "O Conselho Científico confiou essa missão aos mais apropriados.",
  ui_story_1014_10140101_112_dialog_content = "Nunca é sábio se fixar no passado. Você precisa se concentrar em assuntos mais importantes.",
  ui_story_1014_10140101_113_dialog_content = "Você está preocupado que eu possa descobrir evidências de coisas desfavoráveis a Ulisses?",
  ui_story_1014_10140101_114_dialog_content = "Como assim?",
  ui_story_1014_10140101_115_dialog_content = "Você sabe muito bem o que quero dizer.",
  ui_story_1014_10140101_116_dialog_content = "Mal posso esperar pelo dia em que a verdade será revelada, Ulisses. Você está ficando sem tempo para se fazer de bobo.",
  ui_story_1014_10140101_117_dialog_content = "Se você insiste em ser assim, temo que o Comitê também tenha que reavaliar sua competência.",
  ui_story_1014_10140101_118_dialog_content = "Muito bem, então me diga: O que você considera mais importante do que o destino dos aurorianos?",
  ui_story_1014_10140101_119_dialog_content = "Quer que eu te diga? O evento militar conjunto Illumina, futuras estratégias de contra-ataque, tudo é—",
  ui_story_1014_10140101_120_dialog_content = "Que absurdo.",
  ui_story_1014_10140101_121_dialog_content = "Nunca precisei que ninguém me dissesse como ser Grande Marechal.",
  ui_story_1014_10140101_122_dialog_content = "Minhas decisões não são facilmente influenciadas por outros.",
  ui_story_1014_10140101_123_dialog_content = "Vou me despedir, pessoal.",
  ui_story_1014_10140101_124_dialog_content = "Ela ainda é tão obstinada.",
  ui_story_1014_10140101_125_dialog_content = "Claro, mas com suas habilidades, ela deve ser capaz de rastrear aquela mulher Eclipse facilmente.",
  ui_story_1014_10140101_126_dialog_content = "Guarde seus comentários para si.",
  ui_story_1014_10140101_127_dialog_content = "Eu fiz um plano de contingência para esta situação precisa.",
  ui_story_1014_10140201_1_dialog_content = "Sistemas de controle primário, hum, normal.",
  ui_story_1014_10140201_2_dialog_content = "Assim como o sistema de piloto automático.",
  ui_story_1014_10140201_3_dialog_content = "Soroz tem voado suavemente por um tempo agora, PlayerName. Você pode relaxar um pouco.",
  ui_story_1014_10140201_4_dialog_content = "Acho que você está certo, Vice. Obrigado.",
  ui_story_1014_10140201_5_dialog_content = "Estou bem, mas você ainda parece estressado.",
  ui_story_1014_10140201_6_dialog_content = "Mas ainda assim... não acho que você precise se agarrar a essa coisa de Fragilidade Celestial o tempo todo.",
  ui_story_1014_10140201_7_dialog_content = "Você não é uma galinha choca.",
  ui_story_1014_10140201_8_dialog_content = "Tecnicamente falando, é essencial para reparar Soroz, por isso é muito importante!",
  ui_story_1014_10140201_9_dialog_content = "Não sei de que outra forma protegê-lo por enquanto.",
  ui_story_1014_10140201_10_dialog_content = "Além disso, não é tão pesado quanto eu imaginava...",
  ui_story_1014_10140201_11_dialog_content = "Sério? Isso é estranho. Você acha que é algum tipo de arma leve?",
  ui_story_1014_10140201_12_dialog_content = "É leve e frágil... o que parece peculiar para um ciborgue de combate avançado.",
  ui_story_1014_10140201_13_dialog_content = "A-De qualquer forma, vou continuar me segurando assim!",
  ui_story_1014_10140201_14_dialog_content = "Honestamente…",
  ui_story_1014_10140201_15_dialog_content = "(Em vez disso, vou ver o que Carleen está fazendo.)",
  ui_story_1014_10140201_16_dialog_content = "<color=#e8d9bb>Zumbido—Estalido—</color>",
  ui_story_1014_10140201_17_dialog_content = "...",
  ui_story_1014_10140201_18_dialog_content = "Ainda não está bom, Beretta?",
  ui_story_1014_10140201_19_dialog_content = "Desculpe, Lady Carleen. Não tenho muito conhecimento sobre esses tipos de dispositivos.",
  ui_story_1014_10140201_20_dialog_content = "Hum?",
  ui_story_1014_10140201_21_dialog_content = "Momento perfeito, Vice.",
  ui_story_1014_10140201_22_dialog_content = "E aí? Posso ajudar em alguma coisa?",
  ui_story_1014_10140201_23_dialog_content = "Eu estava pensando em entrar em contato com os Lumo Knights estacionados na fronteira para ter uma ideia da situação no local.",
  ui_story_1014_10140201_24_dialog_content = "Eles estão lá há muitos anos e devem poder nos ajudar.",
  ui_story_1014_10140201_25_dialog_content = "Esse tipo de coisa geralmente é tratado pelo Lorde da Cidade. A culpa é minha por não ter feito contato com antecedência.",
  ui_story_1014_10140201_26_dialog_content = "Bem, foi uma partida de última hora!",
  ui_story_1014_10140201_27_dialog_content = "Mas agora não preciso me preocupar, visto que tenho um grande guia diante de mim.",
  ui_story_1014_10140201_28_dialog_content = "Por favor, Vice, ajude-me a descobrir o que há de errado com isso.",
  ui_story_1014_10140201_29_dialog_content = "O sinal continua cortando.",
  ui_story_1014_10140201_30_dialog_content = "Deixe para mim!",
  ui_story_1014_10140201_31_dialog_content = "Vejamos... Primeiro, calibre a sensibilidade da antena...",
  ui_story_1014_10140201_32_dialog_content = "Tudo bem, dê uma chance!",
  ui_story_1014_10140201_33_dialog_content = "<color=#e8d9bb>Zumbido—Estalido—</color>",
  ui_story_1014_10140201_34_dialog_content = "Hmm OK. Então que tal... ajustar o módulo de potência!",
  ui_story_1014_10140201_35_dialog_content = "Ok! Deve ser bom ir agora.",
  ui_story_1014_10140201_36_dialog_content = "<color=#e8d9bb>Zumbido—Estalido—</color>",
  ui_story_1014_10140201_37_dialog_content = "Ahaha! Nesse caso, a única coisa que resta é—",
  ui_story_1014_10140201_38_dialog_content = "<color=#e8d9bb>Bang! Clank!</color>",
  ui_story_1014_10140201_39_dialog_content = "<color=#e8d9bb>Bip Bip...</color>",
  ui_story_1014_10140201_40_dialog_content = "Ufa! Pedaco de bolo.",
  ui_story_1014_10140201_41_dialog_content = "Então é assim que você conserta.",
  ui_story_1014_10140201_42_dialog_content = "Tem alguém aí?",
  ui_story_1014_10140201_43_dialog_content = "Isto é o <color=#FFB400>Cavaleiros Ironthorn</color>. Repito, os Cavaleiros Ironthorn.",
  ui_story_1014_10140201_44_dialog_content = "Bom, temos um sinal forte. Noite Branca no alto, a Capitã da Guarda dos Jardins de Lumopolis, Carleen, envia saudações aos Cavaleiros do Espinho de Ferro.",
  ui_story_1014_10140201_45_dialog_content = "Capitão Leo cumprimenta Lady Carleen...",
  ui_story_1014_10140201_46_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1014_10140201_47_dialog_content = "(O sinal ainda está ruim...?)",
  ui_story_1014_10140201_48_dialog_content = "Senhor Leo, Lumopolis seguirá para Crepúsculo para uma inspeção de rotina.",
  ui_story_1014_10140201_49_dialog_content = "Estarei presente em nome da Lumopolis. Estou ansioso para me encontrar com você então.",
  ui_story_1014_10140201_50_dialog_content = "Trabalhar na zona de fronteira é difícil. Espero ter a oportunidade de agradecer pessoalmente.",
  ui_story_1014_10140201_51_dialog_content = "Bem, isso é uma surpresa! Farei o possível para coordenar o <color=#FFB400>Fortaleza de Lumo</color> patrulhas.",
  ui_story_1014_10140201_52_dialog_content = "E não há necessidade de me agradecer. Só estou fazendo meu trabalho.",
  ui_story_1014_10140201_53_dialog_content = "Vejo você em breve, então.",
  ui_story_1014_10140201_54_dialog_content = "Rogério. Quando você chegar eu mando alguém... você chega... para...",
  ui_story_1014_10140201_55_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1014_10140201_56_dialog_content = "<color=#e8d9bb>Bip Bip...</color>",
  ui_story_1014_10140201_57_dialog_content = "Parece que o sinal está totalmente perdido...",
  ui_story_1014_10140201_58_dialog_content = "Esqueça, pelo menos conseguimos passar a informação.",
  ui_story_1014_10140201_59_dialog_content = "I-Tudo bem, Lady Carleen?",
  ui_story_1014_10140201_60_dialog_content = "Sua posição como capitão só foi restabelecida recentemente após a batalha em Eraveil.",
  ui_story_1014_10140201_61_dialog_content = "Enquanto você parece muito mais resoluto do que antes...",
  ui_story_1014_10140201_62_dialog_content = "de acordo com o City Lord, você ainda está tecnicamente em liberdade condicional.",
  ui_story_1014_10140201_63_dialog_content = "Espero que tudo corra bem...",
  ui_story_1014_10140201_64_dialog_content = "Vai ficar tudo bem, Beretta. Eu entendo de onde você vem, mas não há necessidade de se preocupar indevidamente.",
  ui_story_1014_10140201_65_dialog_content = "Mesmo que haja um problema, apenas respondemos adequadamente e tudo ficará bem.",
  ui_story_1014_10140201_66_dialog_content = "Sim... Tem razão, Lady Carleen!",
  ui_story_1014_10140201_67_dialog_content = "A propósito, quem é esse Capitão Leo?",
  ui_story_1014_10140201_68_dialog_content = "Você ofereceu sua gratidão educada, mas a resposta dele foi bastante rude.",
  ui_story_1014_10140201_69_dialog_content = "Não diga isso, Beretta.",
  ui_story_1014_10140201_70_dialog_content = "Aqueles de nós que vivem em segurança dentro de Lumopolis devem respeitar os combatentes da zona de fronteira.",
  ui_story_1014_10140201_71_dialog_content = "<color=#e8d9bb>Bipe—bipe—bipe—</color>",
  ui_story_1014_10140201_72_dialog_content = "O que é isso?",
  ui_story_1014_10140201_73_dialog_content = "Não é o alarme de Soroz?",
  ui_story_1014_10140201_74_dialog_content = "Oh não...",
  ui_story_1014_10140201_75_dialog_content = "Temos que ir encontrar PlayerName!",
  ui_story_1014_10140201_76_dialog_content = "Huff... Huff...",
  ui_story_1014_10140201_77_option_content = "Ativar modo de emergência",
  ui_story_1014_10140201_78_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1014_10140201_79_option_content = "Estabilizar aeronaves",
  ui_story_1014_10140201_80_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_1014_10140201_81_dialog_content = "Cuidado!",
  ui_story_1014_10140201_82_dialog_content = "Se eu não estivesse segurando, a Fragilidade Celestial estaria sendo derrubada por todo o lugar.",
  ui_story_1014_10140201_83_dialog_content = "O que exatamente está acontecendo, PlayerName?",
  ui_story_1014_10140201_84_dialog_content = "O alarme assustou você, certo? Hum, meu mal. Eu o acionei por acidente.",
  ui_story_1014_10140201_85_dialog_content = "Não diga algo assim tão casualmente como se estivesse falando sobre o tempo!",
  ui_story_1014_10140201_86_dialog_content = "Tem certeza que está tudo bem? Pilotar um Colossus é mais difícil do que eu pensava...",
  ui_story_1014_10140201_87_dialog_content = "O-Claro, está tudo bem.",
  ui_story_1014_10140201_88_dialog_content = "(Eu sou um celestita, no final das contas!)",
  ui_story_1014_10140201_89_dialog_content = "Não se pressione, podemos pousar em algum lugar próximo e descansar um pouco.",
  ui_story_1014_10140201_90_dialog_content = "Quanto mais nos aproximamos da noite eterna, mais Darkflow estará ao nosso redor.",
  ui_story_1014_10140201_91_dialog_content = "Você não pode estar se sentindo muito bem agora, certo?",
  ui_story_1014_10140201_92_dialog_content = "Seja honesto.",
  ui_story_1014_10140201_93_dialog_content = "Que perspicaz... Mas você está certo. Minha cabeça começou a doer mais cedo.",
  ui_story_1014_10140201_94_dialog_content = "Não sei muito sobre pilotar um Colossus, mas considerando a segurança da Fragilidade Celestial...",
  ui_story_1014_10140201_95_dialog_content = "Meu conselho seria pousar e descansar um pouco.",
  ui_story_1014_10140201_96_dialog_content = "Acho que nenhum de nós quer que algo aconteça com a Fragilidade Celestial porque você cometeu um erro.",
  ui_story_1014_10140201_97_dialog_content = "Não, claro que não.",
  ui_story_1014_10140201_98_dialog_content = "Tudo bem. Na verdade, eu estava tentando me convencer de que estava bem.",
  ui_story_1014_10140201_99_dialog_content = "Todos, preparem-se para o pouso. Vou iniciar a descida de Soroz.",
  ui_story_1014_10140201_100_dialog_content = "Ufa—",
  ui_story_1014_10140201_101_dialog_content = "É bom sair e esticar um pouco as pernas.",
  ui_story_1014_10140201_102_dialog_content = "Enfim, sabemos o que aconteceu com Soroz?",
  ui_story_1014_10140201_103_dialog_content = "É difícil imaginar que você precise pousá-lo manualmente.",
  ui_story_1014_10140201_104_dialog_content = "Parece mais sério do que da última vez.",
  ui_story_1014_10140201_105_dialog_content = "Há um problema com sua consciência. Não afeta suas funções normais, mas no momento não estou obtendo nenhuma outra resposta.",
  ui_story_1014_10140201_106_dialog_content = "... Vou verificar os instrumentos mais uma vez.",
  ui_story_1014_10140201_107_dialog_content = "Eu irei com voce.",
  ui_story_1014_10140201_108_dialog_content = "<color=#e8d9bb>Whoosh... Whoosh...</color>",
  ui_story_1014_10140201_109_dialog_content = "(É realmente desolado lá fora.)",
  ui_story_1014_10140201_110_dialog_content = "A Lumina aqui é muito mais fina do que na sede da Illumina. Você está se sentindo bem?",
  ui_story_1014_10140201_111_dialog_content = "Isso não é nada.",
  ui_story_1014_10140201_112_dialog_content = "Além disso, documentar minuciosamente a viagem do celestita é uma das coisas que me incumbiram.",
  ui_story_1014_10140201_113_dialog_content = "Por que você não vai em frente e descobre o que está acontecendo com o seu Colossus agora?",
  ui_story_1014_10140201_114_dialog_content = "F-Tudo bem, estou cuidando disso.",
  ui_story_1014_10140201_115_dialog_content = "(Parece que estou sendo monitorado...)",
  ui_story_1014_10140201_116_dialog_content = "Graah...",
  ui_story_1014_10140201_117_dialog_content = "Huh? Não é esse o som de—",
  ui_story_1014_10140201_118_dialog_content = "<anim type=Shake><size=45>Graaaaaah!</size></anim>",
  ui_story_1014_10140201_119_dialog_content = "Eclipses?!",
  ui_story_1014_10140201_120_dialog_content = "Suponho que não haja nada de estranho em eles estarem neste tipo de lugar!",
  ui_story_1014_10140201_121_dialog_content = "Não podemos deixá-los chegar a Soroz. você pode lutar?",
  ui_story_1014_10140201_122_dialog_content = "Eu... Se fosse uma batalha simulada ou algo assim...",
  ui_story_1014_10140201_123_dialog_content = "Nesse caso, vá buscar Vice e Carleen, agora!",
  ui_story_1014_10140201_124_dialog_content = "Batalha.",
  ui_story_1014_10140201_125_dialog_content = "Comandos de batalha recebidos.",
  ui_story_1014_10140201_126_dialog_content = "?!",
  ui_story_1014_10140201_127_dialog_content = "(Finalmente saiu...)",
  ui_story_1014_10140201_128_dialog_content = "Q-Quem está falando?!",
  ui_story_1014_10140201_129_dialog_content = "<color=#e8d9bb>Clam, clam...</color>",
  ui_story_1014_10140201_130_dialog_content = "Recebi seus comandos de batalha.",
  ui_story_1014_10140201_131_dialog_content = "Não incomode Yingel.",
  ui_story_1014_10140201_132_dialog_content = "Estou pronto para lutar.",
  ui_story_1014_10140201_133_dialog_content = "Você-Você é...",
  ui_story_1014_10140201_134_dialog_content = "Você é <color=#FFB400>Fragilidade Celestial</color>? A coisa que o Conselho de Ciência nos deu?!",
  ui_story_1014_10140201_135_dialog_content = "Graagh!",
  ui_story_1014_10140201_136_dialog_content = "Fraco.",
  ui_story_1014_10140202_1_dialog_content = "Torrent rápido—!",
  ui_story_1014_10140202_2_dialog_content = "Dispersem, pétalas de gelo!",
  ui_story_1014_10140202_3_dialog_content = "Obrigado pela ajuda, Tenente Vice.",
  ui_story_1014_10140202_4_dialog_content = "Tudo bem, Axélia?",
  ui_story_1014_10140202_5_dialog_content = "Você deveria perguntar essas coisas.",
  ui_story_1014_10140202_6_dialog_content = "... Embora nenhum deles esteja em condições de responder.",
  ui_story_1014_10140202_7_dialog_content = "Bem, realmente agora! Você não deve sair da câmara de estase sem autorização. Este não é o destino de sua missão.",
  ui_story_1014_10140202_8_dialog_content = "Terei cuidado para não me machucar.",
  ui_story_1014_10140202_9_dialog_content = "Eu não gostaria de tornar as coisas difíceis para você, Yingel.",
  ui_story_1014_10140202_10_dialog_content = "Não é hora para bate-papo!",
  ui_story_1014_10140202_11_dialog_content = "Alguém se importaria de me explicar por que ela se parece com uma auroriana?",
  ui_story_1014_10140202_12_dialog_content = "Estritamente falando, ela é uma auroriana.",
  ui_story_1014_10140202_13_dialog_content = "Mas, além disso, ela é mais conhecida como o Combat Cyborg, o orgulho e a alegria do Conselho de Ciências.",
  ui_story_1014_10140202_14_dialog_content = "Um... ciborgue?",
  ui_story_1014_10140202_15_dialog_content = "Estamos acostumados a chamá-la assim.",
  ui_story_1014_10140202_16_dialog_content = "Ela é perfeccionista, capaz de cumprir cada comando ao pé da letra.",
  ui_story_1014_10140202_17_dialog_content = "Não é tanto que ela controla Lumina, mas mais que Lumina formou nela.",
  ui_story_1014_10140202_18_dialog_content = "Contanto que ela ative Luminatics, ela usará Lumina para ver, ouvir e operar todos os tipos de tecnologia para concluir uma batalha.",
  ui_story_1014_10140202_19_dialog_content = "Isso é incrível! Nunca vi nada igual!",
  ui_story_1014_10140202_20_dialog_content = "Eu sei. Ela é verdadeiramente o modelo dos usuários do Luminatics. No entanto...",
  ui_story_1014_10140202_21_dialog_content = "Sua forma física é excepcionalmente frágil.",
  ui_story_1014_10140202_22_dialog_content = "Você pode dizer por todas as bandagens que seus órgãos estão em um estado de falha constante.",
  ui_story_1014_10140202_23_dialog_content = "Falência do órgão? Mas por que? E por que a tecnologia médica de Illumina não pode curá-lo?",
  ui_story_1014_10140202_24_dialog_content = "Talvez seja genético. Quem sabe?",
  ui_story_1014_10140202_25_dialog_content = "Independentemente disso, é exatamente o que ela é: um canhão de vidro.",
  ui_story_1014_10140202_26_dialog_content = "Mantê-la na sede da Illumina foi um desperdício. Suas habilidades só podem ser vistas em um lugar drástico como Crepúsculo.",
  ui_story_1014_10140202_27_dialog_content = "Olá, PlayerName. Esta saudação está atrasada.",
  ui_story_1014_10140202_28_dialog_content = "Vou precisar incomodá-lo novamente pelo resto da viagem, desculpe.",
  ui_story_1014_10140202_29_dialog_content = "Em troca, eu vou...",
  ui_story_1014_10140202_30_dialog_content = "deixar minha câmara de estase e lutar em momentos de necessidade.",
  ui_story_1014_10140202_31_dialog_content = "E-Isso não será necessário!",
  ui_story_1014_10140202_32_dialog_content = "(Estamos perdidos se você se machucar!)",
  ui_story_1014_10140202_33_dialog_content = "Podemos lidar facilmente com os Eclipsites normais. Para você se envolver é como usar uma marreta para quebrar uma noz!",
  ui_story_1014_10140202_34_dialog_content = "Sim. Apenas descanse, não iremos visitá-lo a menos que seja absolutamente necessário.",
  ui_story_1014_10140202_35_dialog_content = "Agora que você mencionou isso, eu me sinto um pouco sonolento.",
  ui_story_1014_10140202_36_dialog_content = "(Aww... Ela é apenas uma criança bonitinha!)",
  ui_story_1014_10140202_37_dialog_content = "Ela parece ter a nossa idade, mas fica com sono facilmente.",
  ui_story_1014_10140202_38_dialog_content = "Ela sempre foi assim...",
  ui_story_1014_10140202_39_dialog_content = "Para ela, cada batalha é um enorme gasto de energia. Provavelmente é melhor para ela descansar e se recuperar.",
  ui_story_1014_10140202_40_dialog_content = "Boa noite a todos.",
  ui_story_1014_10140202_41_dialog_content = "Devemos levá-la para o salão?",
  ui_story_1014_10140202_42_dialog_content = "Beretta, como vai do seu lado?",
  ui_story_1014_10140202_43_dialog_content = "Estou indo, Lady Carleen!",
  ui_story_1014_10140202_44_dialog_content = "Acabei de fazer um exame superficial do Colosso.",
  ui_story_1014_10140202_45_dialog_content = "Apesar de ser o assistente de Raphael, quando se trata das doenças de uma máquina tão antiga, ainda estou...",
  ui_story_1014_10140202_46_dialog_content = "Obrigado por seus esforços, Beretta!",
  ui_story_1014_10140202_47_dialog_content = "Independentemente disso, não há como Soroz voar agora.",
  ui_story_1014_10140202_48_dialog_content = "Vamos encerrar o dia então, tire um tempo para descansar.",
  ui_story_1014_10140202_49_dialog_content = "Descansar... neste tipo de lugar?",
  ui_story_1014_10140202_50_dialog_content = "Mal podemos ver o sol daqui. Não sabemos nem que horas são...",
  ui_story_1014_10140202_51_dialog_content = "Ei, não importa. Talvez seja exatamente o tipo de coisa que você faz em peregrinação a uma terra sagrada.",
  ui_story_1014_10140202_52_dialog_content = "Terra sagrada? Acho que não se pode chamar esse tipo de lugar de sagrado.",
  ui_story_1014_10140202_53_dialog_content = "É uma fortaleza onde uma antiga batalha foi travada entre aurorianos e eclipsitas.",
  ui_story_1014_10140202_54_dialog_content = "Os aurorianos se mantiveram firmes, acabando por expulsar os eclipsitas em direção à noite eterna.",
  ui_story_1014_10140202_55_dialog_content = "Cantar sobre os túmulos dos mortos é uma tradição de Lumópolis?",
  ui_story_1014_10140202_56_dialog_content = "Não! Claro que não!",
  ui_story_1014_10140202_57_dialog_content = "As lendas afirmam que as Ruínas Aurora são a fonte das auroras do mundo.",
  ui_story_1014_10140202_58_dialog_content = "É também o lugar mais distante ainda habitável pelos aurorianos, o lugar de onde podemos traçar nossas raízes.",
  ui_story_1014_10140202_59_dialog_content = "Isso não entra em conflito com o que acabei de dizer.",
  ui_story_1014_10140202_60_dialog_content = "Portanto, não pense que é apenas um cemitério!",
  ui_story_1014_10140202_61_dialog_content = "(Que dor de cabeça... não sei se é por causa do Darkflow concentrado, ou desses dois e suas brigas.)",
  ui_story_1014_10140202_62_dialog_content = "Chega, por favor! Todos podem apenas mantê-lo baixo ...",
  ui_story_1014_10140202_63_dialog_content = "Venha aqui, Beretta.",
  ui_story_1014_10140202_64_dialog_content = "Acalme-se, Comandante Yingel.",
  ui_story_1014_10140202_65_dialog_content = "Está ficando mais escuro. Vamos voltar para o Colosso.",
  ui_story_1014_10140202_66_dialog_content = "...",
  ui_story_1014_10140202_67_dialog_content = "Humph.",
  ui_story_1014_10140301_1_dialog_content = "<color=#e8d9bb>Soroz, a ponte</color>",
  ui_story_1014_10140301_2_dialog_content = "<anim type=Shake>Bocejar-</anim>",
  ui_story_1014_10140301_3_dialog_content = "(Ainda tão cansado... eu realmente não dormi bem.)",
  ui_story_1014_10140301_4_dialog_content = "Manhã, PlayerName.",
  ui_story_1014_10140301_5_dialog_content = "Uau! Uh... você parece meio pálido.",
  ui_story_1014_10140301_6_dialog_content = "Problemas para dormir?",
  ui_story_1014_10140301_7_dialog_content = "Mais ou menos. O Darkflow aqui é mais forte do que quando chegamos.",
  ui_story_1014_10140301_8_dialog_content = "Acordei todas as vezes que um Eclipsite passou por Soroz ontem à noite.",
  ui_story_1014_10140301_9_dialog_content = "Não posso deixar de sentir que estamos sendo caçados...",
  ui_story_1014_10140301_10_dialog_content = "Parece uma noite difícil... Você deveria dormir um pouco mais agora.",
  ui_story_1014_10140301_11_dialog_content = "Hummm. Boa ideia.",
  ui_story_1014_10140301_12_dialog_content = "Acho que vou voltar para a cama então...",
  ui_story_1014_10140301_13_dialog_content = "<color=#e8d9bb>Bang! Bang!</color>",
  ui_story_1014_10140301_14_dialog_content = "<color=#e8d9bb>Baque-!</color>",
  ui_story_1014_10140301_15_dialog_content = "Oh, pelo amor de—",
  ui_story_1014_10140301_16_dialog_content = "O que está acontecendo por aí?!!!",
  ui_story_1014_10140301_17_dialog_content = "Vou verificar com a Beretta.",
  ui_story_1014_10140301_18_dialog_content = "Eu quero ver por mim mesmo!",
  ui_story_1014_10140301_19_dialog_content = "(Esses Eclipsites realmente foram longe demais!)",
  ui_story_1014_10140301_20_dialog_content = "Estou seriamente começando a perder a paciência.",
  ui_story_1014_10140301_21_dialog_content = "... Huh? Sean?",
  ui_story_1014_10140301_22_dialog_content = "Huh?! PlayerName?!",
  ui_story_1014_10140301_23_dialog_content = "Que surpresa, conhecê-lo em um lugar como este!",
  ui_story_1014_10140301_24_dialog_content = "Então essa grande coisa branca é, tipo, *seu* Colosso, hein?",
  ui_story_1014_10140301_25_dialog_content = "... De quem mais seria?!",
  ui_story_1014_10140301_26_dialog_content = "Justo... Enfim PlayerName, Sinto muito pelos problemas que causei a todos.",
  ui_story_1014_10140301_27_dialog_content = "Vou dar uma olhada em um minuto. Espero que meu \"bater na porta\" não tenha prejudicado Soroz...",
  ui_story_1014_10140301_28_dialog_content = "(Suspirar...)",
  ui_story_1014_10140301_29_dialog_content = "Eu estava patrulhando os arredores de Twilight.",
  ui_story_1014_10140301_30_dialog_content = "Temos Lumina muito fraca aqui, então frequentemente recebemos refugiados perdidos aparecendo.",
  ui_story_1014_10140301_31_dialog_content = "Minha tarefa principal é localizar os indivíduos presos por desastres repentinos e limpar os Eclipsites enquanto estou nisso.",
  ui_story_1014_10140301_32_dialog_content = "No momento em que vi esse enorme cara branco, imediatamente pensei em você!",
  ui_story_1014_10140301_33_dialog_content = "Provavelmente é super conveniente viajar muito longe com um Colossus, certo?",
  ui_story_1014_10140301_34_dialog_content = "Com certeza! Não importa aonde eu vá, meu Colossus pode me levar até lá em um piscar de olhos.",
  ui_story_1014_10140301_35_dialog_content = "Incrível! Eu gostaria de ter um também.",
  ui_story_1014_10140301_36_dialog_content = "Eu pensei que meus sonhos estavam realmente se tornando realidade.",
  ui_story_1014_10140301_37_dialog_content = "Mas, em retrospectiva, encontrar um novo Colossus abandonado neste tipo de posto avançado remoto é um pouco improvável...",
  ui_story_1014_10140301_38_dialog_content = "Bem, sim, é absolutamente improvável.",
  ui_story_1014_10140301_39_dialog_content = "Deixe-me apresentar a todos. Estas são Lady Carleen e Beretta, Guardiãs dos Jardins de Lumopolis.",
  ui_story_1014_10140301_40_dialog_content = "Olá.",
  ui_story_1014_10140301_41_dialog_content = "Não seja tão precipitado de novo, certo?",
  ui_story_1014_10140301_42_dialog_content = "Eu realmente sinto muito!",
  ui_story_1014_10140301_43_dialog_content = "Esta é a Coronel Yingel, e aquela caixa que ela carrega é Axelia. O que quero dizer com isso é...",
  ui_story_1014_10140301_44_dialog_content = "Yingel! Faz algum tempo! Quem diria que nos encontraríamos novamente neste tipo de lugar?!",
  ui_story_1014_10140301_45_dialog_content = "E como está Axélia? Ainda está indo bem?",
  ui_story_1014_10140301_46_dialog_content = "Vocês já se conhecem?",
  ui_story_1014_10140301_47_dialog_content = "Bem, que surpresa ver que você ainda está vivo e forte.",
  ui_story_1014_10140301_48_dialog_content = "Pff, claro! Lutar é vida, pelo menos em Crepúsculo, e minhas habilidades melhoraram muito!",
  ui_story_1014_10140301_49_dialog_content = "Otimista como sempre...",
  ui_story_1014_10140301_50_dialog_content = "(De repente, não estou nem um pouco sonolento...)",
  ui_story_1014_10140301_51_dialog_content = "Deixe-me verificar como Soroz está indo uma última vez, então acho que estaremos prontos para pegar a estrada novamente.",
  ui_story_1014_10140301_52_dialog_content = "Pegar a estrada? Não me diga que vocês estão indo para Crepúsculo?",
  ui_story_1014_10140301_53_dialog_content = "É uma longa história, mas resumindo, o quartel-general da Illumina nos mandou ir a Twilight para fazer algum tipo de troca.",
  ui_story_1014_10140301_54_dialog_content = "Nesse caso, deixe-me ser seu guia! Conheço alguns bons atalhos.",
  ui_story_1014_10140301_55_dialog_content = "Além disso, também não sou ruim em lidar com Eclipsites. Eu posso lidar com qualquer coisa que surja ao longo do caminho.",
  ui_story_1014_10140301_56_dialog_content = "Isso seria muito útil!",
  ui_story_1014_10140301_57_dialog_content = "Hum...",
  ui_story_1014_10140301_58_dialog_content = "Como está o Colosso?",
  ui_story_1014_10140301_59_dialog_content = "Bem, não parece haver grandes problemas em geral. Acho que podemos nos preparar para partir.",
  ui_story_1014_10140301_60_dialog_content = "E a porta?",
  ui_story_1014_10140301_61_dialog_content = "Não se preocupe, Sean, a porta está bem.",
  ui_story_1014_10140301_62_dialog_content = "Ufa... Isso é um alívio. Eu posso respirar de novo!",
  ui_story_1014_10140301_63_dialog_content = "<color=#e8d9bb>Grrhk...</color>",
  ui_story_1014_10140301_64_dialog_content = "O que é que foi isso?!",
  ui_story_1014_10140301_65_dialog_content = "De novo?!",
  ui_story_1014_10140301_66_dialog_content = "<anim type=Shake><size=45>Gahhh!!!</size></anim>",
  ui_story_1014_10140301_67_dialog_content = "Que gentileza sua se servir em uma bandeja de prata!",
  ui_story_1014_10140301_68_dialog_content = "Bem, se temos visitas, posso começar a limpar!",
  ui_story_1014_10140402_1_dialog_content = "Huh!",
  ui_story_1014_10140402_2_dialog_content = "Isso deve resolver.",
  ui_story_1014_10140402_3_dialog_content = "Tenho que admitir que subestimei você no centro médico Illumina!",
  ui_story_1014_10140402_4_dialog_content = "Hehe, agora podemos finalmente partir.",
  ui_story_1014_10140402_5_dialog_content = "Enfim, se foi o quartel-general que te mandou fazer a troca...",
  ui_story_1014_10140402_6_dialog_content = "Eu deveria entrar em contato com os responsáveis aqui antes do tempo.",
  ui_story_1014_10140402_7_dialog_content = "A propósito, não quero duvidar de você!",
  ui_story_1014_10140402_8_dialog_content = "É que Crepúsculo é bastante cauteloso com estranhos.",
  ui_story_1014_10140402_9_dialog_content = "Se eu avisá-los com antecedência, isso facilitará a entrada e tudo mais.",
  ui_story_1014_10140402_10_dialog_content = "Entendo. Obrigado, nesse caso.",
  ui_story_1014_10140402_11_dialog_content = "<color=#e8d9bb>Em outro lugar, na ponte</color>",
  ui_story_1014_10140402_12_dialog_content = "(Hm... Ele realmente parece mais forte do que antes.)",
  ui_story_1014_10140402_13_dialog_content = "Observando Sean, Yingel?",
  ui_story_1014_10140402_14_dialog_content = "Axélia? V-Você não deveria simplesmente aparecer atrás de alguém! É realmente enervante...",
  ui_story_1014_10140402_15_dialog_content = "Oh, me desculpe!",
  ui_story_1014_10140402_16_dialog_content = "É bom se movimentar um pouco depois de descansar.",
  ui_story_1014_10140402_17_dialog_content = "Me deixa um pouco nostálgico lembrar de nós três antigamente, treinando juntos no <color=#FFB400>Programa Phospherus</color>.",
  ui_story_1014_10140402_18_dialog_content = "Faz apenas cinco anos, mas já esqueci quase tudo o que aconteceu então.",
  ui_story_1014_10140402_19_dialog_content = "Porque sua mente estava sempre sendo preenchida com todos os tipos de comandos.",
  ui_story_1014_10140402_20_dialog_content = "Você é quem fala, Yingel...",
  ui_story_1014_10140402_21_dialog_content = "Mas talvez essa seja uma das minhas vantagens.",
  ui_story_1014_10140402_22_dialog_content = "Todos nós, incluindo Sean, desempenhamos papéis nos quais nos destacamos melhor.",
  ui_story_1014_10140402_23_dialog_content = "Hmph, mesmo que rejeitar?",
  ui_story_1014_10140402_24_dialog_content = "... Embora eu não possa negar, ele parece adorar.",
  ui_story_1014_10140402_25_dialog_content = "Desculpe deixar todo mundo esperando! Finalmente estamos prontos para voltar aos trilhos!",
  ui_story_1014_10140402_26_dialog_content = "As forças Illumina em Crepúsculo estão esperando para dar as boas-vindas a todos vocês!",
  ui_story_1014_10140402_27_dialog_content = "?!",
  ui_story_1014_10140402_28_dialog_content = "Axélia?! Você está acordado!",
  ui_story_1014_10140402_29_dialog_content = "Er, vocês estavam apenas me observando lidar com aqueles Eclipsites?",
  ui_story_1014_10140402_30_dialog_content = "De fato.",
  ui_story_1014_10140402_31_dialog_content = "O que você acha? Eu não sou totalmente mais incrível? Sem mencionar muito mais forte do que quando estávamos na sede?",
  ui_story_1014_10140402_32_dialog_content = "Quer treinar uma rodada? Vamos ver quem ganha dessa vez!",
  ui_story_1014_10140402_33_dialog_content = "Não, obrigado.",
  ui_story_1014_10140402_34_dialog_content = "A propósito, você parece ter quatro robôs desconhecidos ao seu lado?",
  ui_story_1014_10140402_35_dialog_content = "Eles são o Trio Cúbico.",
  ui_story_1014_10140402_36_dialog_content = "Er, ok, mas há quatro—",
  ui_story_1014_10140402_37_dialog_content = "O quarto garotinho apenas me ajuda a levantar as mangas.",
  ui_story_1014_10140402_38_dialog_content = "Muito estranho! Mas porque não?!",
  ui_story_1014_10140402_39_dialog_content = "De qualquer forma Sean, Axelia é o que vamos oferecer em troca durante a troca.",
  ui_story_1014_10140402_40_dialog_content = "Não a faça usar muita energia agora.",
  ui_story_1014_10140402_41_dialog_content = "Sério?!",
  ui_story_1014_10140402_42_dialog_content = "Isso faz de mim o veterano de Axelia?!",
  ui_story_1014_10140402_43_dialog_content = "Você tem alguma coisa que queira me perguntar?",
  ui_story_1014_10140402_44_dialog_content = "Bem, eu estava pensando sobre a atual estrutura militar de Crepúsculo.",
  ui_story_1014_10140402_45_dialog_content = "Hum, bem, eu sou mais um soldado de infantaria, então...",
  ui_story_1014_10140402_46_dialog_content = "Nesse caso, existem tipos especiais de Eclipsites em Crepúsculo?",
  ui_story_1014_10140402_47_dialog_content = "Er, na verdade não tenho muita certeza...",
  ui_story_1014_10140402_48_dialog_content = "No entanto, sinta-se à vontade para me perguntar qualquer outra coisa! Como onde está a melhor comida em Crepúsculo, ou sua história, ou os melhores pontos turísticos...",
  ui_story_1014_10140402_49_dialog_content = "Disque para baixo, você poderia...",
  ui_story_1014_10140501_1_dialog_content = "<color=#e8d9bb>Crepúsculo nos arredores</color>",
  ui_story_1014_10140501_2_dialog_content = "Lady Carleen, relatórios de patrulha anteriores indicam que Twilight está logo à frente.",
  ui_story_1014_10140501_3_dialog_content = "Leo e os outros logo devem estar lá para nos receber também. Prepare-se para pousar, PlayerName.",
  ui_story_1014_10140501_4_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_1014_10140501_5_dialog_content = "O que é que foi isso?!",
  ui_story_1014_10140501_6_dialog_content = "Uma explosão.",
  ui_story_1014_10140501_7_dialog_content = "Axelia, volte para sua câmara de estase. Está um caos lá fora.",
  ui_story_1014_10140501_8_dialog_content = "Mas este é exatamente o tipo de tempo que eu deveria ser necessário.",
  ui_story_1014_10140501_9_dialog_content = "Sean, o que está acontecendo lá fora?",
  ui_story_1014_10140501_10_dialog_content = "Acalme-se, pessoal. Está tudo bem.",
  ui_story_1014_10140501_11_dialog_content = "Estamos cercados por alguns Eclipsites incômodos.",
  ui_story_1014_10140501_12_dialog_content = "Mas... por que todos no chão não se mexem?",
  ui_story_1014_10140501_13_dialog_content = "Eles estão todos olhando para alguma coisa.",
  ui_story_1014_10140501_14_dialog_content = "aposto que é PlayerNameé o Colosso!",
  ui_story_1014_10140501_15_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_1014_10140501_16_dialog_content = "Algo está errado.",
  ui_story_1014_10140501_17_dialog_content = "Rápido! Encontre um lugar para pousar, PlayerName.",
  ui_story_1014_10140501_18_dialog_content = "A-Tudo bem! Sentem-se bem, todos!",
  ui_story_1014_10140501_19_dialog_content = "Bem, houve alguns contratempos ao longo do caminho, mas conseguimos. Bem-vindo ao Crepúsculo!",
  ui_story_1014_10140501_20_dialog_content = "Situada na fronteira do Astra, possui um clima agradável, um estilo de vida simples e tradicional—",
  ui_story_1014_10140501_21_dialog_content = "Fora do caminho! Mova isso! Vamos, deixe-me passar...",
  ui_story_1014_10140501_22_dialog_content = "Tosse, tosse — Quanta poeira!",
  ui_story_1014_10140501_23_dialog_content = "Hahaha... Sim, isso. Acontece as vezes.",
  ui_story_1014_10140501_24_dialog_content = "Olá, posso perguntar para onde vocês estão indo? Posso ajudar em alguma coisa?",
  ui_story_1014_10140501_25_dialog_content = "Crepúsculo ainda está muito longe daqui?",
  ui_story_1014_10140501_26_dialog_content = "Estamos na periferia da cidade agora! Vocês... não devem ser daqui.",
  ui_story_1014_10140501_27_dialog_content = "Ok, obrigado!",
  ui_story_1014_10140501_28_dialog_content = "Espere! Se você está indo para Crepúsculo também, você também pode nos acompanhar.",
  ui_story_1014_10140501_29_dialog_content = "Lamentamos, mas não temos muito tempo.",
  ui_story_1014_10140501_30_dialog_content = "Eu sugiro fortemente que você encontre um lugar para se abrigar, rapidamente.",
  ui_story_1014_10140501_31_dialog_content = "Abrigo?",
  ui_story_1014_10140501_32_dialog_content = "Você vê como o céu ficou com uma cor estranha? Isso é um sinal claro de que um <color=#FFB400>Aurorastorm</color> está vindo!",
  ui_story_1014_10140501_33_dialog_content = "Se você não encontrar abrigo logo, assim que ele chegar, ninguém poderá salvá-lo.",
  ui_story_1014_10140501_34_dialog_content = "Aurora Tempestade...?",
  ui_story_1014_10140501_35_dialog_content = "Eu só li sobre isso em livros. Mesmo Northland, com suas freqüentes auroras, raramente vê tal fenômeno.",
  ui_story_1014_10140501_36_dialog_content = "Apenas moradores que residem nas zonas fronteiriças por gerações os testemunharam.",
  ui_story_1014_10140501_37_dialog_content = "<color=#e8d9bb>Bip Bip-</color>",
  ui_story_1014_10140501_38_dialog_content = "Essa é a sirene de alerta de Twilight!",
  ui_story_1014_10140501_39_dialog_content = "Ouça, todos. No seu ritmo, não há como você alcançar Crepúsculo hoje.",
  ui_story_1014_10140501_40_dialog_content = "Sou Sean, um oficial júnior das forças Illumina estacionado em Crepúsculo. Se você confiar em mim,",
  ui_story_1014_10140501_41_dialog_content = "Posso levar todos a se abrigar em uma trincheira improvisada!",
  ui_story_1014_10140501_42_dialog_content = "Confiar em você? Vocês são apenas um bando de crianças!",
  ui_story_1014_10140501_43_dialog_content = "Sim, mas não temos exatamente como nos defender, não é? Se formos atacados por Eclipsites novamente...",
  ui_story_1014_10140501_44_dialog_content = "Eclipsitos? Você quer dizer... o seu clã também...",
  ui_story_1014_10140501_45_dialog_content = "... Sim. Se as coisas continuarem assim, o número de clãs sobreviventes por aqui vai continuar diminuindo.",
  ui_story_1014_10140501_46_dialog_content = "Indo para Crepúsculo é nossa melhor chance de sobrevivência.",
  ui_story_1014_10140501_47_dialog_content = "Pare de dizer bobagens para ele. Só vamos ficar lá por um tempo.",
  ui_story_1014_10140501_48_dialog_content = "Chegará o dia em que poderemos ir para casa...",
  ui_story_1014_10140501_49_dialog_content = "<color=#e8d9bb>Baque, baque, baque</color>",
  ui_story_1014_10140501_50_dialog_content = "Os ruídos estão vindo do chão neste momento.",
  ui_story_1014_10140501_51_dialog_content = "Graaaaaah!",
  ui_story_1014_10140501_52_dialog_content = "<anim type=Shake><size=45>GRAAAAA!!!</size></anim>",
  ui_story_1014_10140501_53_dialog_content = "Eclipsites... Eclipsites estão chegando!",
  ui_story_1014_10140501_54_dialog_content = "Eles cronometraram o ataque para coincidir com a Aurorastorm? Eles têm um pouco de habilidade estratégica, ao que parece.",
  ui_story_1014_10140501_55_dialog_content = "Beretta.",
  ui_story_1014_10140501_56_dialog_content = "Sim, Lady Carleen!",
  ui_story_1014_10140501_57_dialog_content = "Deixe-me cobrir a retirada de todos!",
  ui_story_1014_10140501_58_dialog_content = "Evitar não é uma estratégia viável a longo prazo.",
  ui_story_1014_10140501_59_dialog_content = "Por favor, permita-me lutar. Caso contrário, terei que tomar medidas extremas.",
  ui_story_1014_10140501_60_dialog_content = "Não se preocupe em lutar contra eles ainda!",
  ui_story_1014_10140501_61_dialog_content = "O que aconteceria com esses civis indefesos se acusássemos?",
  ui_story_1014_10140501_62_dialog_content = "Acredito que posso protegê-los ao mesmo tempo.",
  ui_story_1014_10140501_63_dialog_content = "Por favor, não se preocupe. Não vai demorar muito.",
  ui_story_1014_10140501_64_dialog_content = "Eu disse não!!",
  ui_story_1014_10140501_65_dialog_content = "Beretta, Axelia, vocês duas se separaram.",
  ui_story_1014_10140501_66_dialog_content = "Beretta, Carleen, Sean - vocês vão colocar os civis em segurança.",
  ui_story_1014_10140501_67_dialog_content = "Axelia, Yingel, Vice — irei com vocês. Traremos a batalha para os Eclipsites!",
  ui_story_1014_10140501_68_dialog_content = "Entendido.",
  ui_story_1014_10140501_69_dialog_content = "Não há necessidade de se cansar.",
  ui_story_1014_10140501_70_dialog_content = "Deixe esses Eclipsites para os Cavaleiros Espinho de Ferro.",
  ui_story_1014_10140501_71_dialog_content = "Perdoe nossa chegada tardia; Fico feliz que todos estejam bem.",
  ui_story_1014_10140501_72_dialog_content = "Timing impecável, Léo! Por favor, ajude-nos a lutar contra esses Eclipsites antes de nos escoltar!",
  ui_story_1014_10140501_73_dialog_content = "Naturalmente. Como a batalha é iminente, por favor, perdoe-me por não desmontar, Lady Carleen.",
  ui_story_1014_10140501_74_dialog_content = "Uma bagatela. Você não precisa mostrar lealdade à etiqueta, apenas ao seu nome.",
  ui_story_1014_10140501_75_dialog_content = "Hahaha! Bem, eu me tornei um cavaleiro de Crepúsculo, ao invés do meu nome!",
  ui_story_1014_10140501_76_dialog_content = "Cavaleiros, apresentem armas!",
  ui_story_1014_10140501_77_dialog_content = "Exijo apenas uma coisa de você nesta luta!",
  ui_story_1014_10140501_78_dialog_content = "Lute para exterminar todos os Eclipsites até seu último suspiro.",
  ui_story_1014_10140501_79_dialog_content = "ATAQUE!!!",
  ui_story_1014_10140602_1_dialog_content = "Fique em formação. Não se espalhe.",
  ui_story_1014_10140602_2_dialog_content = "Priorize o inimigo no flanco lateral.",
  ui_story_1014_10140602_3_dialog_content = "Sim, senhor!",
  ui_story_1014_10140602_4_dialog_content = "Há mais deles! Outro grande grupo de Eclipsites avança!",
  ui_story_1014_10140602_5_dialog_content = "Estaremos exaustos lutando assim. Devemos recuar?",
  ui_story_1014_10140602_6_dialog_content = "Ah, eu os vejo. Hmm, existem alguns.",
  ui_story_1014_10140602_7_dialog_content = "Nesse caso, nós...",
  ui_story_1014_10140602_8_dialog_content = "Todos os cavaleiros! Descarregue e prepare-se para o ataque!",
  ui_story_1014_10140602_9_dialog_content = "Sim, senhor!",
  ui_story_1014_10140602_10_dialog_content = "Err, assalto? Agora?",
  ui_story_1014_10140602_11_dialog_content = "Certamente um ataque frontal com tantos Eclipsites não é a melhor ideia...",
  ui_story_1014_10140602_12_dialog_content = "Vocês, forasteiros, podem esperar aqui, então. Espere e observe.",
  ui_story_1014_10140602_13_dialog_content = "Todos os cavaleiros! Formação em cunha, dois esquadrões. Um comigo, outro com o deputado.",
  ui_story_1014_10140602_14_dialog_content = "Divida uma vez através da linha inimiga.",
  ui_story_1014_10140602_15_dialog_content = "Agora, observe o estandarte em minha mão.",
  ui_story_1014_10140602_16_dialog_content = "Cavaleiros Espinho de Ferro, ATAQUEM!",
  ui_story_1014_10140602_17_dialog_content = "<size=50>CHAARRGE!!</size>",
  ui_story_1014_10140602_18_dialog_content = "Eles estão realmente atacando aquela horda de Eclipsites?! Isso não é um pouco... imprudente?",
  ui_story_1014_10140602_19_dialog_content = "Não necessariamente. Apenas observe.",
  ui_story_1014_10140602_20_dialog_content = "O ataque deles foi mais suave do que o esperado.",
  ui_story_1014_10140602_21_dialog_content = "Sério! Mesmo tantos Eclipsites não conseguiram segurar os cavaleiros!",
  ui_story_1014_10140602_22_dialog_content = "Eles os cortaram com precisão cirúrgica...",
  ui_story_1014_10140602_23_dialog_content = "Como eles fizeram isso?!",
  ui_story_1014_10140602_24_dialog_content = "Acho que entendo um pouco. As palavras de Beretta eram apropriadas.",
  ui_story_1014_10140602_25_dialog_content = "Eles realmente são como uma lâmina.",
  ui_story_1014_10140602_26_dialog_content = "Ao cortar uma carcaça, ninguém pensa duas vezes no peso da faca em comparação com o do animal.",
  ui_story_1014_10140602_27_dialog_content = "Contanto que a lâmina esteja afiada o suficiente, ela cortará.",
  ui_story_1014_10140602_28_dialog_content = "Cortar...",
  ui_story_1014_10140602_29_dialog_content = "Olha, Leo está voltando com metade deles.",
  ui_story_1014_10140602_30_dialog_content = "<color=#e8d9bb>Clip-clop, clip-clop</color>",
  ui_story_1014_10140602_31_dialog_content = "O que vocês acham, forasteiros? Afinal, não é uma má ideia, não é?",
  ui_story_1014_10140602_32_dialog_content = "A guerra não é simplesmente um jogo de números. A mesma força pode ser usada de forma diferente com diferentes táticas.",
  ui_story_1014_10140602_33_dialog_content = "Aqui, ao longo da fronteira remota, não temos forças para enfrentar os Eclipsitos de frente.",
  ui_story_1014_10140602_34_dialog_content = "Eles não entendem estratégia militar. No entanto, nós fazemos, e esta é a nossa vantagem.",
  ui_story_1014_10140602_35_dialog_content = "Então, como você julgou que era o momento certo para um ataque?",
  ui_story_1014_10140602_36_dialog_content = "Porque eu conheço bem esse tipo de Eclipsite.",
  ui_story_1014_10140602_37_dialog_content = "Eles são agressivos e bons em esmagar com números absolutos. Mas sua fraqueza é óbvia: eles não são proficientes contra ataques repentinos.",
  ui_story_1014_10140602_38_dialog_content = "Portanto, ao enfrentá-los, independentemente de qual lado tenha mais forças, devemos tomar a iniciativa e atacar.",
  ui_story_1014_10140602_39_dialog_content = "Nosso ataque frontal concentra nossas forças em uma única linha, que corta e enfraquece o inimigo.",
  ui_story_1014_10140602_40_dialog_content = "O ataque também quebra a formação dos Eclipsites. Quanto mais disperso estiver o inimigo, melhor para nós.",
  ui_story_1014_10140602_41_dialog_content = "Você vê? Deixei metade das minhas forças entre eles.",
  ui_story_1014_10140602_42_dialog_content = "Eles vão lidar com o resto dos Eclipsites, criando mais caos e confusão ao cortar o campo de batalha enquanto eliminam grupos de retardatários.",
  ui_story_1014_10140602_43_dialog_content = "Incrível! Parece que há muito mais a ser considerado do que eu pensava quando se trata de lutar contra os Eclipsites.",
  ui_story_1014_10140602_44_dialog_content = "Estávamos claramente em desvantagem numérica em relação aos Eclipsitas, mas você está empatado no campo de batalha...",
  ui_story_1014_10140602_45_dialog_content = "É por isso que digo que a estratégia é mais importante do que o poder.",
  ui_story_1014_10140602_46_dialog_content = "Mas você, forasteiro, tem talento para detectar eclipsites antes de mim.",
  ui_story_1014_10140602_47_dialog_content = "Esse tipo de senso de campo de batalha é raro.",
  ui_story_1014_10140602_48_dialog_content = "Não é realmente nada para escrever.",
  ui_story_1014_10140602_49_dialog_content = "Não sou auroriano como você. Eu sou um celestita.",
  ui_story_1014_10140602_50_dialog_content = "Um celestita? Essa corrida lendária?",
  ui_story_1014_10140602_51_dialog_content = "Hahaha, que fascinante! Um personagem dos meus livros ganhou vida!",
  ui_story_1014_10140602_52_dialog_content = "Então, celestita, use seus sentidos aguçados e diga-me: o que devemos fazer a seguir?",
  ui_story_1014_10140602_53_dialog_content = "Um... Lançar um ataque de acompanhamento, antes que o inimigo se reagrupe?",
  ui_story_1014_10140602_54_dialog_content = "Incorreta! Nós nos retiramos.",
  ui_story_1014_10140602_55_dialog_content = "Huh? Mas por que? Acabamos de estabelecer uma vantagem!",
  ui_story_1014_10140602_56_dialog_content = "Você não pode manter seus olhos apenas no campo de batalha à sua frente.",
  ui_story_1014_10140602_57_dialog_content = "Nosso objetivo final é interceptar todos os Eclipsites. O que estamos fazendo agora não é suficiente.",
  ui_story_1014_10140602_58_dialog_content = "Atrás deles encontra-se um terreno perigoso com passagens traiçoeiras. A batalha inevitavelmente mudaria para lá.",
  ui_story_1014_10140602_59_dialog_content = "Precisamos nos preparar primeiro.",
  ui_story_1014_10140602_60_dialog_content = "Você nos ajudaria, forasteiro?",
  ui_story_1014_10140602_61_dialog_content = "É claro! Eu esperava ter a chance de observar suas táticas novamente.",
  ui_story_1014_10140602_62_dialog_content = "Bem, nós iríamos lidar com os Eclipsites de qualquer maneira.",
  ui_story_1014_10140602_63_dialog_content = "Ouça, ajude ou não, não faz diferença para nós. Mas eu tenho uma pergunta...",
  ui_story_1014_10140602_64_dialog_content = "Alguém viu aquele idiota do Sean em algum lugar?",
  ui_story_1014_10140602_65_dialog_content = "<size=45>Dieee!!</size>",
  ui_story_1014_10140602_66_dialog_content = "Quantos de vocês sobraram?!",
  ui_story_1014_10140602_67_dialog_content = "Nunca pensei que você pudesse lutar tão bem, soldado de Illumina.",
  ui_story_1014_10140602_68_dialog_content = "Huh? Bem, obrigado!",
  ui_story_1014_10140602_69_dialog_content = "Você é atraente mesmo no campo de batalha dos Cavaleiros Ironthorn.",
  ui_story_1014_10140602_70_dialog_content = "Um lutador tão notável como você não deve ter falta de elogios.",
  ui_story_1014_10140602_71_dialog_content = "Uh, r-sério? Não costumo ser elogiado.",
  ui_story_1014_10140602_72_dialog_content = "No entanto, por que exatamente você está aqui? Eu pensei que o capitão disse para você esperar lá?",
  ui_story_1014_10140602_73_dialog_content = "Ele fez?!",
  ui_story_1014_10140602_74_dialog_content = "Olha, todos os seus companheiros ainda estão lá.",
  ui_story_1014_10140602_75_dialog_content = "Ahhh, lembrei agora. O capitão Leo disse algo sobre os forasteiros ficarem parados.",
  ui_story_1014_10140602_76_dialog_content = "Mas eu não sou um estranho! Eu moro aqui em Crepúsculo também.",
  ui_story_1014_10140602_77_dialog_content = "...",
  ui_story_1014_10140602_78_dialog_content = "Alguém já lhe disse que você não é a ferramenta mais afiada do galpão?",
  ui_story_1014_10140602_79_dialog_content = "Sim!",
  ui_story_1014_10140602_80_dialog_content = "Você sabe que isso NÃO é um elogio...?",
  ui_story_1014_10140602_81_dialog_content = "Deixa para lá. Graças a você, toda a situação da batalha é muito mais clara.",
  ui_story_1014_10140602_82_dialog_content = "Nossa diretriz de missão original era lidar com os Eclipsites. Olhando como as coisas estão atualmente, não deve ser muito difícil eliminá-los completamente.",
  ui_story_1014_10140602_83_dialog_content = "Bom! Não posso deixar nenhum deles escapar!",
  ui_story_1014_10140602_84_dialog_content = "Você parece cheio de paixão. É uma coisa boa.",
  ui_story_1014_10140602_85_dialog_content = "Sabe, eu tenho ouvido histórias sobre os Ironthorn Knights e o Capitão Leo desde sempre.",
  ui_story_1014_10140602_86_dialog_content = "Ter a chance de lutar lado a lado com um grupo tão heróico realmente faz meu sangue bombear!",
  ui_story_1014_10140602_87_dialog_content = "Esconda essas bestas na grama alta. Nossos preparativos estão quase completos.",
  ui_story_1014_10140602_88_dialog_content = "Perfeito, eles estão voltando.",
  ui_story_1014_10140602_89_dialog_content = "<color=#e8d9bb>Clip-clop, clip-clop</color>",
  ui_story_1014_10140602_90_dialog_content = "Capitão.",
  ui_story_1014_10140602_91_dialog_content = "Bom trabalho e executado com mais elegância do que eu imaginava.",
  ui_story_1014_10140602_92_dialog_content = "Desta vez, temos o apoio deste excelente lutador Illumina para agradecer por isso.",
  ui_story_1014_10140602_93_dialog_content = "Nossa, não foi nada...",
  ui_story_1014_10140602_94_dialog_content = "Hummm, eu vi. Uma luta tão vigorosa não poderia passar despercebida.",
  ui_story_1014_10140602_95_dialog_content = "Você é um oficial da Illumina?",
  ui_story_1014_10140602_96_dialog_content = "Sim! Sou o segundo-tenente Sean, da Guarnição de Twilight!",
  ui_story_1014_10140602_97_dialog_content = "Guarnição do Crepúsculo, hein. Não acredito que nunca soube que tínhamos um guerreiro tão corajoso na porta ao lado.",
  ui_story_1014_10140602_98_dialog_content = "Nah, por que você faria? Dificilmente sou excepcional entre meus camaradas e, na verdade, não tenho muita experiência no campo de batalha.",
  ui_story_1014_10140602_99_dialog_content = "Claro que alguém como você não teria ouvido falar de mim, capitão Leo.",
  ui_story_1014_10140602_100_dialog_content = "Parece que você me conhece.",
  ui_story_1014_10140602_101_dialog_content = "Naturalmente!! Quem em Crepúsculo nunca ouviu falar dos feitos valentes dos Cavaleiros do Espinho de Ferro!",
  ui_story_1014_10140602_102_dialog_content = "Bem, nesse caso... rapaz, gostaria de se juntar a nós?",
  ui_story_1014_10140602_103_dialog_content = "Hã?",
  ui_story_1014_10140602_104_dialog_content = "Lutadores de destaque devem mostrar seu valor no campo de batalha, não definhar nos quartéis contando os dias que passam.",
  ui_story_1014_10140602_105_dialog_content = "Junte-se a nós e tornarei seu nome conhecido em Crepúsculo em menos de um mês.",
  ui_story_1014_10140602_106_dialog_content = "Mas...",
  ui_story_1014_10140602_107_dialog_content = "Aham. Capitão Leo, um convite tão ultrajante é definitivamente contra o protocolo.",
  ui_story_1014_10140602_108_dialog_content = "No mínimo, tente virar seu inimigo com mais discrição.",
  ui_story_1014_10140602_109_dialog_content = "Ahaha, minhas desculpas, embora eu não consiga ver o que há de tão vergonhoso nisso.",
  ui_story_1014_10140602_110_dialog_content = "Lumopolis e Illumina são apenas lugares para descansar, nossos inimigos finais são os Eclipsites.",
  ui_story_1014_10140602_111_dialog_content = "Eu só quero que esse garoto tenha um lugar melhor para chamar de lar.",
  ui_story_1014_10140602_112_dialog_content = "Claro, você sente falta, também são impressionantes. Se você quiser se juntar a nós, os Ironthorn Knights estarão prontos para recebê-lo.",
  ui_story_1014_10140602_113_dialog_content = "Você... Eu não tinha ideia de que o Capitão dos Cavaleiros Ironthorn era um mestre da solicitação.",
  ui_story_1014_10140602_114_dialog_content = "Você deveria renunciar e vir a ser um político em Gannon City. Eu também gostaria que você tivesse um lugar melhor para chamar de lar.",
  ui_story_1014_10140602_115_dialog_content = "Político, você diz? Não é uma má opção. Vou pensar um pouco.",
  ui_story_1014_10140602_116_dialog_content = "Estou cansado.",
  ui_story_1014_10140602_117_dialog_content = "Hum?",
  ui_story_1014_10140602_118_dialog_content = "Ya-wn, eu disse que estou cansado.",
  ui_story_1014_10140602_119_dialog_content = "Sério? Agora mesmo...?",
  ui_story_1014_10140602_120_dialog_content = "Não importa, não há nada a ser feito sobre isso. Volte para a câmara de estase e descanse um pouco, Axelia.",
  ui_story_1014_10140602_121_dialog_content = "Claro. Estarei torcendo por você.",
  ui_story_1014_10140602_122_dialog_content = "Volto direto assim que acordar.",
  ui_story_1014_10140602_123_dialog_content = "Não se preocupe com isso. Tenha um bom descanso.",
  ui_story_1014_10140602_124_dialog_content = "Fique de olho na câmara de estase, PlayerName.",
  ui_story_1014_10140602_125_dialog_content = "Vai fazer!",
  ui_story_1014_10140602_126_dialog_content = "Ela simplesmente desapareceu naquela caixa!",
  ui_story_1014_10140602_127_dialog_content = "Vocês estranhos estão realmente ampliando meus horizontes.",
  ui_story_1014_10140602_128_dialog_content = "A condição física de Axelia não é boa, então ela tem que descansar muito na câmara de estase.",
  ui_story_1014_10140602_129_dialog_content = "Então, por que você a levaria para um lugar tão perigoso quanto a região da fronteira?",
  ui_story_1014_10140602_130_dialog_content = "Porque levá-la para Crepúsculo com segurança era o objetivo da missão.",
  ui_story_1014_10140602_131_dialog_content = "Entendo. Bem, nesse caso, não vou me intrometer mais.",
  ui_story_1014_10140602_132_dialog_content = "Chega de papo, acho que aquele grupo ali está ficando inquieto.",
  ui_story_1014_10140602_133_dialog_content = "Preciso colocar uma cerca de ferro aqui antes que os Eclipsites apareçam.",
  ui_story_1014_10140602_134_dialog_content = "Estamos aqui para ajudar, então o que podemos fazer?",
  ui_story_1014_10140602_135_dialog_content = "Apenas engajar-se na batalha para nós é o suficiente. Não há necessidade de envolvê-la nas minúcias de nossos negócios, Lady Carleen.",
  ui_story_1014_10140602_136_dialog_content = "Na verdade, considerando seu status, eu provavelmente deveria ceder o comando do campo de batalha para você.",
  ui_story_1014_10140602_137_dialog_content = "É que nas atuais circunstâncias, temo que os cavaleiros possam achar difícil se adaptar. Por favor, perdoe-me por ultrapassar minha autoridade.",
  ui_story_1014_10140602_138_dialog_content = "...",
  ui_story_1014_10140602_139_dialog_content = "O comando deve pertencer a quem for mais capaz de conduzir todos à vitória. Não há necessidade de tal formalidade aqui.",
  ui_story_1014_10140602_140_dialog_content = "Se tivermos liberdade para fazer o que quisermos, iremos para o leste, para ajudar a manter a defesa.",
  ui_story_1014_10140602_141_dialog_content = "Se minhas observações estiverem corretas, a linha defensiva ali é relativamente fraca.",
  ui_story_1014_10140602_142_dialog_content = "Leste... Você está absolutamente certo. Não temos mão de obra suficiente para cobrir todas as áreas, e esse é o nosso ponto fraco.",
  ui_story_1014_10140602_143_dialog_content = "Parece que você tem bastante olho tático, Lady Carleen.",
  ui_story_1014_10140602_144_dialog_content = "Embora meu nascimento me impeça de ter o título de Cavaleiro Comandante, não me confunda com uma mera princesa de Lumopolis.",
  ui_story_1014_10140602_145_dialog_content = "Nunca! Eu confio no nome dos Cavaleiros de Lumopolis.",
  ui_story_1014_10140602_146_dialog_content = "Ambos lutamos pela mesma glória.",
  ui_story_1014_10140602_147_dialog_content = "Esta parece ser uma área de retaguarda segura. Acho que você deveria instalar a câmara de estase de Axelia aqui, PlayerName.",
  ui_story_1014_10140602_148_dialog_content = "Tá bom.",
  ui_story_1014_10140602_149_dialog_content = "A implantação de Leo deixou a linha oriental relativamente fraca.",
  ui_story_1014_10140602_150_dialog_content = "Devemos ir apoiar as forças defensivas lá.",
  ui_story_1014_10140602_151_dialog_content = "Sim, Lady Carleen.",
  ui_story_1014_10140602_152_dialog_content = "Você está cooperando com as ordens de Leo de bom grado, Carleen.",
  ui_story_1014_10140602_153_dialog_content = "Ele tem uma vasta experiência de comando. Você mesmo viu como ele consegue a vitória com facilidade, se suas ordens forem seguidas.",
  ui_story_1014_10140602_154_dialog_content = "Mas ele não designou uma tarefa específica para nós.",
  ui_story_1014_10140602_155_dialog_content = "Não. Ele não faria isso.",
  ui_story_1014_10140602_156_dialog_content = "Ahn? Por que não?",
  ui_story_1014_10140602_157_dialog_content = "Sinto que Leo está mantendo uma distância deliberada.",
  ui_story_1014_10140602_158_dialog_content = "Ele não vai se submeter a mim, mas também não vai me dar ordens.",
  ui_story_1014_10140602_159_dialog_content = "Porque eu sou, afinal, a filha do Senhor da Cidade de Lumopolis.",
  ui_story_1014_10140602_160_dialog_content = "Bem, tudo bem, mas eu ainda não entendo muito. Isso é uma coisa ruim?",
  ui_story_1014_10140602_161_dialog_content = "Eu mesmo não tenho certeza.",
  ui_story_1014_10140602_162_dialog_content = "Na verdade, eu preferiria que ele fosse apenas um guerreiro, sem nenhuma etiqueta ou reverência.",
  ui_story_1014_10140602_163_dialog_content = "Nesta fronteira distante, tão longe de tudo, tudo o que se vê é o campo de batalha.",
  ui_story_1014_10140602_164_dialog_content = "Mas não para ele. Pelo contrário, ele está extremamente atento ao meu status.",
  ui_story_1014_10140602_165_dialog_content = "E ele usa essa distância entre nós para transformar \"lealdade\" em \"respeito\".",
  ui_story_1014_10140602_166_dialog_content = "Então eu vou respeitá-lo em troca, e seguirei seus comandos táticos.",
  ui_story_1014_10140602_167_dialog_content = "Que confuso. É isso que chamam de guerra da política?",
  ui_story_1014_10140602_168_dialog_content = "Muito apropriado.",
  ui_story_1014_10140602_169_dialog_content = "Talvez seja esta a tragédia que define Lumópolis. Nunca podemos nos separar verdadeiramente da política.",
  ui_story_1014_10140602_170_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_1014_10140602_171_dialog_content = "!!!",
  ui_story_1014_10140602_172_dialog_content = "Que som é esse?",
  ui_story_1014_10140602_173_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1014_10140602_174_dialog_content = "Algo está vindo para cá!",
  ui_story_1014_10140602_175_dialog_content = "O Darkflow é espesso. Provavelmente existem muitos deles.",
  ui_story_1014_10140602_176_dialog_content = "E... parece que eles trouxeram um grande amigo junto!",
  ui_story_1014_10140701_1_dialog_content = "Cavaleiros do Espinho de Ferro, preparem-se para a batalha!",
  ui_story_1014_10140701_2_dialog_content = "Ninguém deve deixar a formação sem minha ordem!",
  ui_story_1014_10140701_3_dialog_content = "Sim, senhor!",
  ui_story_1014_10140701_4_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_1014_10140701_5_dialog_content = "Há ainda mais deles do que da última vez.",
  ui_story_1014_10140701_6_dialog_content = "Aposto que é esse que está fazendo todo o barulho.",
  ui_story_1014_10140701_7_dialog_content = "<color=#FFB400>Cerritus</color>.",
  ui_story_1014_10140701_8_dialog_content = "Cerrito... De novo...",
  ui_story_1014_10140701_9_dialog_content = "O quê?",
  ui_story_1014_10140701_10_dialog_content = "Uma aberração. Um Eclipse único. Alguém com uma força extraordinária.",
  ui_story_1014_10140701_11_dialog_content = "Os Ironthorn Knights já se enfrentaram antes, mas nenhum dos lados conseguiu uma vitória definitiva.",
  ui_story_1014_10140701_12_dialog_content = "Alguma chance de parar desta vez?",
  ui_story_1014_10140701_13_dialog_content = "Não é uma questão de saber se podemos pará-lo. Nós devemos.",
  ui_story_1014_10140701_14_dialog_content = "Se eles passarem por nós, eles alcançarão Crepúsculo.",
  ui_story_1014_10140701_15_dialog_content = "Não há nenhum outro Ironthorn Knights por perto para ajudar a detê-lo.",
  ui_story_1014_10140701_16_dialog_content = "Espere! Olhe para lá! Na frente dos Eclipsitos!",
  ui_story_1014_10140701_17_dialog_content = "Pessoas?! Os civis estão em fuga!",
  ui_story_1014_10140701_18_dialog_content = "Alguém... Por favor...",
  ui_story_1014_10140701_19_dialog_content = "Eu não posso... correr muito mais tempo...",
  ui_story_1014_10140701_20_dialog_content = "Só um pouco mais longe. A-Quase lá... Crepúsculo.",
  ui_story_1014_10140701_21_dialog_content = "Haverá alguém lá para nos proteger, eu sei que haverá.",
  ui_story_1014_10140701_22_dialog_content = "Podemos fazer isso...?",
  ui_story_1014_10140701_23_dialog_content = "Eu posso ouvir... Atrás de mim... os monstros...",
  ui_story_1014_10140701_24_dialog_content = "Eles soam tão próximos... Tão próximos...",
  ui_story_1014_10140701_25_dialog_content = "Realmente existem pessoas! Eles estão prestes a ser pegos!",
  ui_story_1014_10140701_26_dialog_content = "Rápido, para o resgate! Vá agora, antes que seja tarde demais!",
  ui_story_1014_10140701_27_dialog_content = "Mas, uh, o que devemos fazer, Capitão Leo?",
  ui_story_1014_10140701_28_dialog_content = "...",
  ui_story_1014_10140701_29_dialog_content = "Capitão Léo?!",
  ui_story_1014_10140701_30_dialog_content = "Cavaleiros Espinho de Ferro, fiquem em formação.",
  ui_story_1014_10140701_31_dialog_content = "<size=45>O quê?!</size>",
  ui_story_1014_10140701_32_dialog_content = "A multidão Eclipsite está quase sobre nós. Quebrar a formação agora seria suicídio.",
  ui_story_1014_10140701_33_dialog_content = "Não podemos quebrar a formação.",
  ui_story_1014_10140701_34_dialog_content = "Mas e eles? Os que estão sendo perseguidos agora?!",
  ui_story_1014_10140701_35_dialog_content = "Eles estão prestes a ser pegos!",
  ui_story_1014_10140701_36_dialog_content = "Sinto muito por isso, mas somos cavaleiros, não deuses. Não podemos salvar a todos.",
  ui_story_1014_10140701_37_dialog_content = "Você...",
  ui_story_1014_10140701_38_dialog_content = "Não posso arriscar que todo Crepúsculo seja consumido por uma inundação de Eclipsites por alguns retardatários, nem posso pedir aos meus Cavaleiros que se sacrifiquem por esses civis.",
  ui_story_1014_10140701_39_dialog_content = "Aqui na fronteira, cada vida é preciosa e cada decisão é importante.",
  ui_story_1014_10140701_40_dialog_content = "Então, devemos apenas vê-los serem assassinados pelos Eclipsitas?",
  ui_story_1014_10140701_41_dialog_content = "Então vá embora, se preferir não presenciar. Ou agir sozinho.",
  ui_story_1014_10140701_42_dialog_content = "Afinal, vocês não são Cavaleiros Ironthorn e não são meus para comandar.",
  ui_story_1014_10140701_43_dialog_content = "...",
  ui_story_1014_10140701_44_dialog_content = "Multar. Então, por favor, segure a linha e não deixe nada acontecer com Axelia!",
  ui_story_1014_10140701_45_dialog_content = "Faremos o que você escolher não fazer!",
  ui_story_1014_10140701_46_dialog_content = "<size=40>Aaaaah!</size>",
  ui_story_1014_10140701_47_dialog_content = "Irmão!! O que aconteceu?!",
  ui_story_1014_10140701_48_dialog_content = "Os monstros estão bem atrás de mim! Minha... Minha perna está doendo...",
  ui_story_1014_10140701_49_dialog_content = "Você tem que correr! Corra agora!",
  ui_story_1014_10140701_50_dialog_content = "Não! não posso te deixar...",
  ui_story_1014_10140701_51_dialog_content = "<size=40>Argh!!</size>",
  ui_story_1014_10140701_52_dialog_content = "<size=40>Scram!!</size>",
  ui_story_1014_10140701_53_dialog_content = "Huh? É isto...",
  ui_story_1014_10140701_54_dialog_content = "Tem mais aqui, Carleen!",
  ui_story_1014_10140701_55_dialog_content = "Entendido.",
  ui_story_1014_10140701_56_dialog_content = "Deixe os que estão aí comigo!",
  ui_story_1014_10140701_57_dialog_content = "Todos! Me siga! Aguente firme mais um pouco. Nós vamos levá-lo para a segurança!",
  ui_story_1014_10140701_58_dialog_content = "Viva! Eles vieram atrás de nós!",
  ui_story_1014_10140701_59_dialog_content = "Rápido! Siga-os!",
  ui_story_1014_10140701_60_dialog_content = "Não há tempo para ficarmos atrás dos Cavaleiros Espinho de Ferro.",
  ui_story_1014_10140701_61_dialog_content = "Eles estão quase em cima de nós! Prepare-se!",
  ui_story_1014_10140701_62_dialog_content = "Já? E os civis?!",
  ui_story_1014_10140701_63_dialog_content = "Faça com que eles fiquem juntos!",
  ui_story_1014_10140701_64_dialog_content = "Farei tudo o que puder para protegê-los!",
  ui_story_1014_10140701_65_dialog_content = "Prepare-se. Eles estão aqui.",
  ui_story_1014_10140701_66_dialog_content = "<color=#e8d9bb>Rumble—Rumble—Rumble—</color>",
  ui_story_1014_10140701_67_dialog_content = "<anim type=Shake><size=45>Graaahh—</size></anim>",
  ui_story_1014_10140701_68_dialog_content = "Afaste-se um pouco, Vice. Não os deixe chegar muito perto.",
  ui_story_1014_10140701_69_dialog_content = "Não há como voltar atrás em um momento como este! À sua direita!",
  ui_story_1014_10140701_70_dialog_content = "Uau! Tantos deles... Onde estão todos? Onde estou?!",
  ui_story_1014_10140701_71_dialog_content = "Ah, se Axelia estivesse aqui.",
  ui_story_1014_10140701_72_dialog_content = "Ei! Cuidado com as palavras! Então eu não sou suficiente?!",
  ui_story_1014_10140701_73_dialog_content = "Todo mundo, fique atrás de mim! Não saia correndo!",
  ui_story_1014_10140701_74_dialog_content = "Eu protegerei você...",
  ui_story_1014_10140701_75_dialog_content = "Argh!! Eclipsites, vindo direto para nós!",
  ui_story_1014_10140701_76_dialog_content = "Huh? Onde?",
  ui_story_1014_10140701_77_dialog_content = "Aqui! Eles estão aqui!",
  ui_story_1014_10140701_78_dialog_content = "Espere, estou chegando!",
  ui_story_1014_10140701_79_dialog_content = "Graaagh!",
  ui_story_1014_10140701_80_dialog_content = "... Eles estão por toda parte!",
  ui_story_1014_10140701_81_dialog_content = "PlayerName! Você pode me dar uma ideia da posição do inimigo?",
  ui_story_1014_10140701_82_dialog_content = "Não consigo descobrir onde eles estão...",
  ui_story_1014_10140701_83_dialog_content = "<size=45>TODOS! SAIA DAQUI!!</size>",
  ui_story_1014_10140701_84_dialog_content = "Huh? E para onde pretendemos ir?",
  ui_story_1014_10140701_85_dialog_content = "Não sei bem mas... Quanto mais longe, melhor!",
  ui_story_1014_10140701_86_dialog_content = "<color=#e8d9bb>Rumble—Rumble—</color>",
  ui_story_1014_10140701_87_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1014_10140701_88_dialog_content = "Uau... Esse cara é ridículo.",
  ui_story_1014_10140701_89_dialog_content = "Não fique aí parado!",
  ui_story_1014_10140701_90_dialog_content = "<anim type=Shake><size=50>Grrr!</size></anim>",
  ui_story_1014_10140701_91_dialog_content = "*Tosse* A formação quebrou... Estão todos bem?",
  ui_story_1014_10140701_92_dialog_content = "PlayerName alertou a todos, então ninguém deveria ter sido pego de surpresa.",
  ui_story_1014_10140701_93_dialog_content = "Estou mais preocupado com os civis.",
  ui_story_1014_10140701_94_dialog_content = "Se a formação quebrar, é mais provável que sejam atacados.",
  ui_story_1014_10140701_95_dialog_content = "Você tem razão! Devemos ir ajudá-los!",
  ui_story_1014_10140701_96_dialog_content = "Podemos ao menos sair daqui?",
  ui_story_1014_10140701_97_dialog_content = "Socorro!",
  ui_story_1014_10140701_98_dialog_content = "Eclipsites, eles estão por toda parte!",
  ui_story_1014_10140701_99_dialog_content = "Para onde eles foram? As pessoas que vinham nos salvar?!",
  ui_story_1014_10140701_100_dialog_content = "Fiquem tranquilos, pessoal! Venha até mim, eu vou te proteger!",
  ui_story_1014_10140701_101_dialog_content = "PlayerName, os inimigos...",
  ui_story_1014_10140701_102_dialog_content = "Eles estão por toda parte agora. Todo o campo de batalha está cheio deles!",
  ui_story_1014_10140701_103_dialog_content = "Não há como os civis se agruparem. Os Eclipsitas conseguiram dispersar a multidão.",
  ui_story_1014_10140701_104_dialog_content = "S-Então, o que fazemos agora?",
  ui_story_1014_10140701_105_dialog_content = "Estou pensando...",
  ui_story_1014_10140701_106_dialog_content = "Não são só eles, mas nós também.",
  ui_story_1014_10140701_107_dialog_content = "Aquele monstro que eles chamam de Cerritus continuará lançando ataques, e não sobreviveremos por muito tempo em um mar de Eclipsites.",
  ui_story_1014_10140701_108_dialog_content = "Você está certo... Está aqui de novo...",
  ui_story_1014_10140701_109_dialog_content = "Você consegue ver alguma saída, Yingel? Você geralmente é o mais inteligente da sala.",
  ui_story_1014_10140701_110_dialog_content = "Esqueça os civis, recue para trás dos Ironthorn Knights.",
  ui_story_1014_10140701_111_dialog_content = "Huh? Mas...",
  ui_story_1014_10140701_112_dialog_content = "Léo estava certo. Temos que enfrentar isso. Esta é a fronteira, e não somos fortes o suficiente.",
  ui_story_1014_10140701_113_dialog_content = "Mesmo se continuarmos lutando, esses civis ainda serão abatidos um a um no meio do caos.",
  ui_story_1014_10140701_114_dialog_content = "Não podemos salvar a todos.",
  ui_story_1014_10140701_115_dialog_content = "...",
  ui_story_1014_10140701_116_dialog_content = "Fizemos o nosso melhor, PlayerName. Você deve entender nossa situação.",
  ui_story_1014_10140701_117_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_1014_10140701_118_dialog_content = "Você ouviu isso? O monstro está vindo.",
  ui_story_1014_10140701_119_dialog_content = "N-nós...",
  ui_story_1014_10140701_120_dialog_content = "Se não se decidir, vou levá-lo comigo.",
  ui_story_1014_10140701_121_dialog_content = "!!!",
  ui_story_1014_10140701_122_dialog_content = "Me dê um pouco de cobertura, Srta. Lumopolis. Estamos nos retirando.",
  ui_story_1014_10140701_123_dialog_content = "Mas...",
  ui_story_1014_10140701_124_dialog_content = "Eu prometi! Eu disse que os protegeria...",
  ui_story_1014_10140701_125_dialog_content = "Então deixe seu próprio crescimento começar com uma promessa que você não pode cumprir.",
  ui_story_1014_10140701_126_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_1014_10140701_127_dialog_content = "Me desculpe, mas eu tenho que pelo menos tentar. Não posso quebrar minha palavra tão facilmente.",
  ui_story_1014_10140701_128_dialog_content = "Porque escolhi me chamar de cavaleiro.",
  ui_story_1014_10140701_129_dialog_content = "Ei, você—",
  ui_story_1014_10140701_130_dialog_content = "Bereta!!",
  ui_story_1014_10140701_131_dialog_content = "Então você se considera um cavaleiro. Agradeça ao nome, por torná-lo justo e puro.",
  ui_story_1014_10140701_132_dialog_content = "Hã?",
  ui_story_1014_10140701_133_dialog_content = "Rooarrrrr—",
  ui_story_1014_10140701_134_dialog_content = "Cerritus foi repelido por Luminatics! Aquilo foi-",
  ui_story_1014_10140701_135_dialog_content = "Esta é a primeira vez que encontro um cavaleiro como você.",
  ui_story_1014_10140701_136_dialog_content = "R-Sério? Só estou fazendo o que se espera de um cavaleiro.",
  ui_story_1014_10140701_137_dialog_content = "Mas outros cavaleiros não são como você.",
  ui_story_1014_10140701_138_dialog_content = "Você é tão linda... Você é algum tipo de anjo?",
  ui_story_1014_10140701_139_dialog_content = "Eu também há muito desejo encontrar um anjo, mas infelizmente... Eles ainda não vieram antes de mim.",
  ui_story_1014_10140701_140_dialog_content = "Assim, os mortais devem bastar para alguns empreendimentos.",
  ui_story_1014_10140701_141_dialog_content = "Aldeões, sigam a luz e venham até mim.",
  ui_story_1014_10140701_142_dialog_content = "Noite Branca no alto, a luz expurgará todo o mal e guiará todas as almas de volta para casa.",
  ui_story_1014_10140701_143_dialog_content = "Olhar! Os Eclipsitas têm medo da luz por lá!",
  ui_story_1014_10140701_144_dialog_content = "Rápido! Vamos lá! Estaremos seguros!",
  ui_story_1014_10140701_145_dialog_content = "Já ouvi falar dela! Tem que ser ela - a Santinha do Crepúsculo!",
  ui_story_1014_10140701_146_dialog_content = "Incrível! Os civis conseguiram se agrupar novamente!",
  ui_story_1014_10140701_147_dialog_content = "Os Eclipsitas estão se escondendo da luz que irradia do corpo da garota. Parece que temos que seguir se quisermos sair daqui!",
  ui_story_1014_10140701_148_dialog_content = "Sim, eu concordo. Então, mudança de plano: agora cercamos aquela garota e fazemos o possível para cobrir a retirada do civil.",
  ui_story_1014_10140701_149_dialog_content = "Copie isso, Comandante Yingel!",
  ui_story_1014_10140701_150_dialog_content = "Não me chame assim.",
  ui_story_1014_10140701_151_dialog_content = "Capitão! Eles estão voltando! COM aqueles civis!",
  ui_story_1014_10140701_152_dialog_content = "Eu vi. Abra a formação com cuidado e coloque-os na retaguarda.",
  ui_story_1014_10140701_153_dialog_content = "Sim, senhor!",
  ui_story_1014_10140701_154_dialog_content = "São os Cavaleiros Ironthorn! Obrigado Senhor! Estamos seguros agora.",
  ui_story_1014_10140701_155_dialog_content = "Pegue o ritmo! Como alguém pode relaxar até que estejamos em Crepúsculo e fora deste maldito deserto?",
  ui_story_1014_10140701_156_dialog_content = "Bom trabalho, Capitão Leo.",
  ui_story_1014_10140701_157_dialog_content = "Você está sendo sarcástico, não é? <color=#FFB400>Sua Santidade</color>?",
  ui_story_1014_10140701_158_dialog_content = "De jeito nenhum. Não sou tão infantil e estou plenamente ciente de sua situação.",
  ui_story_1014_10140701_159_dialog_content = "Muitos estão fugindo para Crepúsculo, está ficando impossível protegê-los, assim como nossa cidade.",
  ui_story_1014_10140701_160_dialog_content = "Todo Eclipsite que conseguir passar por você irá direto para Crepúsculo. Naturalmente, você não pode sair da linha defensiva.",
  ui_story_1014_10140701_161_dialog_content = "Obrigado pela sua absolvição. Eu me sinto melhor agora.",
  ui_story_1014_10140701_162_dialog_content = "Seu rosto não mostra isso. É esta a questão da dignidade de que você falou?",
  ui_story_1014_10140701_163_dialog_content = "Não, na verdade não. É que tenho inveja de você, porque você consegue fazer com tanta facilidade o que eu não consigo.",
  ui_story_1014_10140701_164_dialog_content = "Agora é sua vez de fazer o que eu não posso.",
  ui_story_1014_10140701_165_dialog_content = "Certamente. Leve os civis para a retaguarda e deixe o campo de batalha para mim.",
  ui_story_1014_10140701_166_dialog_content = "Nem um único Eclipsite passará pelos Ironthorn Knights.",
  ui_story_1014_10140701_167_dialog_content = "Eu tenho fé em você.",
  ui_story_1014_10140701_168_dialog_content = "Vá em frente então. Nosso breve tempo juntos está chegando ao fim.",
  ui_story_1014_10140701_169_dialog_content = "Sempre parece assim conosco, esbarrando nos ombros ao passar no campo de batalha.",
  ui_story_1014_10140701_170_dialog_content = "Sim. Sempre.",
  ui_story_1014_10140701_171_dialog_content = "Estamos sempre correndo em direções opostas.",
  ui_story_1014_10140701_172_dialog_content = "Nosso amigo está se aproximando. Consigo ouvir isso.",
  ui_story_1014_10140701_173_dialog_content = "Cavaleiros do Espinho de Ferro! Modo de espera! Quem é a favor de dar um chute igualmente forte no grandalhão ?!",
  ui_story_1014_10140701_174_dialog_content = "<size=40>EU!!</size>",
  ui_story_1014_10140701_175_dialog_content = "<size=40>Eu também!</size>",
  ui_story_1014_10140701_176_dialog_content = "Quer se juntar a nós? Se ainda tiver forças para lutar, claro.",
  ui_story_1014_10140701_177_dialog_content = "Definitivamente! É hora de pagar dez vezes mais o que acabamos de sofrer!",
  ui_story_1014_10140701_178_dialog_content = "Hahahahaha! Eu gosto desse espírito!",
  ui_story_1014_10140701_179_dialog_content = "Com sua ajuda, nosso objetivo não será apenas a defesa.",
  ui_story_1014_10140701_180_dialog_content = "Esta noite, quero pendurar nosso estandarte em seus chifres!",
  ui_story_1014_10140702_1_dialog_content = "<anim type=Shake><size=45>Graa!!! Graaaaah—</size></anim>",
  ui_story_1014_10140702_2_dialog_content = "Dá um tempo, garotão.",
  ui_story_1014_10140702_3_dialog_content = "Ufa... Finalmente caiu. Essa coisa era loucamente forte.",
  ui_story_1014_10140702_4_dialog_content = "Não relaxe ainda. O ataque dos Eclipsitas ainda está em andamento e devemos vê-lo até o fim.",
  ui_story_1014_10140702_5_dialog_content = "É claro! Mas pelo menos a pressão está baixa.",
  ui_story_1014_10140702_6_dialog_content = "Puxa, finalmente saímos daquela turba Eclipsite.",
  ui_story_1014_10140702_7_dialog_content = "E o Cerrito? Para onde foi aquele grandalhão?",
  ui_story_1014_10140702_8_dialog_content = "...",
  ui_story_1014_10140702_9_dialog_content = "Obrigada! Oh, obrigado, Sua Santidade!",
  ui_story_1014_10140702_10_dialog_content = "Você salvou a todos nós!",
  ui_story_1014_10140702_11_dialog_content = "Oh, por favor... Por favor, pare de me chamar assim.",
  ui_story_1014_10140702_12_dialog_content = "Meu nome é <color=#FFB400>Joselyne</color>. Seremos vizinhos se você decidir se estabelecer em Crepúsculo.",
  ui_story_1014_10140702_13_dialog_content = "Oh certo, o que devemos fazer agora?",
  ui_story_1014_10140702_14_dialog_content = "Vamos primeiro a Crepúsculo. Com as tropas de Lumopolis e Illumina lá, pelo menos estaremos seguros.",
  ui_story_1014_10140702_15_dialog_content = "Se continuarmos nos movendo, não há como saber quando poderemos ser atacados pelos Eclipsites novamente.",
  ui_story_1014_10140702_16_dialog_content = "Concordou. E eu não quero ter que fugir, não de novo.",
  ui_story_1014_10140702_17_dialog_content = "Todos vão para Crepúsculo primeiro. Vocês todos devem estar exaustos, considerando o que passaram.",
  ui_story_1014_10140702_18_dialog_content = "Haverá outros chegando em Crepúsculo hoje também. Os habitantes da cidade estão se preparando para acomodá-los.",
  ui_story_1014_10140702_19_dialog_content = "Haverá quartos para todos esta noite, então, por favor, descanse e recarregue as energias.",
  ui_story_1014_10140702_20_dialog_content = "Podemos discutir o que vem a seguir amanhã de manhã.",
  ui_story_1014_10140702_21_dialog_content = "Maravilhoso! Muito obrigado por cuidar de nós com tanto cuidado.",
  ui_story_1014_10140702_22_dialog_content = "Infelizmente, esta não é a primeira vez que Twilight teve que fazer isso.",
  ui_story_1014_10140702_23_dialog_content = "Muitas das pessoas que moram aqui também fugiram de lugares vizinhos, então todos se solidarizam com sua situação.",
  ui_story_1014_10140702_24_dialog_content = "Fazemos o que podemos para ajudar. Espero que você encontre um novo lar o mais rápido possível.",
  ui_story_1014_10140702_25_dialog_content = "Uma nova casa? Oh sim, nós vamos!",
  ui_story_1014_10140702_26_dialog_content = "Está ficando tarde. Cabeça para a cidade, todos.",
  ui_story_1014_10140702_27_dialog_content = "Tudo bem! É só esperar que nos acomodamos, que a gente vem agradecer direitinho, Santidade!",
  ui_story_1014_10140702_28_dialog_content = "Ahh, eu já disse para me chamar apenas de Joselyne.",
  ui_story_1014_10140702_29_dialog_content = "Noite Branca lá no alto, visitaremos você na igreja quando pudermos!",
  ui_story_1014_10140702_30_dialog_content = "Não faço parte da igreja, então você não vai me encontrar lá!",
  ui_story_1014_10140702_31_dialog_content = "O que? Você não é membro da igreja?",
  ui_story_1014_10140702_32_dialog_content = "Não, de jeito nenhum. Sou apenas uma pessoa comum, igual a todos vocês.",
  ui_story_1014_10140702_33_dialog_content = "Se quiser me encontrar, venha ao mercado. Muitas vezes estou lá vendendo coisas.",
  ui_story_1014_10140702_34_dialog_content = "Ok, o mercado. Vou me lembrar disso!",
  ui_story_1014_10140702_35_dialog_content = "Tchau, Santidade.",
  ui_story_1014_10140702_36_dialog_content = "É a Joselyne...",
  ui_story_1014_10140702_37_dialog_content = "Oh meu, esse som...",
  ui_story_1014_10140702_38_dialog_content = "Eles voltaram.",
  ui_story_1014_10140702_39_dialog_content = "<color=#e8d9bb>Clip-clop, clip-clop</color>",
  ui_story_1014_10140702_40_dialog_content = "Então você veio visitar a fronteira, Lady Carleen.",
  ui_story_1014_10140702_41_dialog_content = "Correto. Já faz muito tempo desde a última vez que Lumopolis trocou notícias com Twilight.",
  ui_story_1014_10140702_42_dialog_content = "Não é um pouco exagerado mandá-lo aqui para um assunto tão trivial?",
  ui_story_1014_10140702_43_dialog_content = "Você viu a situação geral aqui. O conflito aqui é uma luta, mas ainda podemos manter alguma aparência de estabilidade.",
  ui_story_1014_10140702_44_dialog_content = "Nossas forças estão concentradas em torno da Fortaleza Lumo. O núcleo de energia de Twilight está lá, então tem bastante defesa.",
  ui_story_1014_10140702_45_dialog_content = "Se tiver tempo, Lady Carleen, será bem-vinda para fazer um tour.",
  ui_story_1014_10140702_46_dialog_content = "Obrigado, eu gostaria disso.",
  ui_story_1014_10140702_47_dialog_content = "Estamos quase lá.",
  ui_story_1014_10140702_48_dialog_content = "Parece que temos uma festa de boas-vindas.",
  ui_story_1014_10140702_49_dialog_content = "Ei, essa é... a garota da batalha!",
  ui_story_1014_10140702_50_dialog_content = "Lembro-me de todos chamando-a de \"Santa do Crepúsculo\".",
  ui_story_1014_10140702_51_dialog_content = "Por favor, esqueça esse título e me chame apenas de Joselyne.",
  ui_story_1014_10140702_52_dialog_content = "Fiquei impressionado com seu heroísmo no campo de batalha.",
  ui_story_1014_10140702_53_dialog_content = "Estou aqui em nome do povo para dar as boas-vindas ao seu retorno triunfante.",
  ui_story_1014_10140702_54_dialog_content = "Eu diria que foi mais a sua conduta em batalha que foi a mais impressionante.",
  ui_story_1014_10140702_55_dialog_content = "Sim! A forma como você apareceu, banhado em luz! Tão dramático!",
  ui_story_1014_10140702_56_dialog_content = "Embora aposto que aqueles civis que você salvou se sentem ainda mais fortes do que eu.",
  ui_story_1014_10140702_57_dialog_content = "Você realmente parecia um emissário divino...",
  ui_story_1014_10140702_58_dialog_content = "Por favor, não diga essas coisas, isso me apavora.",
  ui_story_1014_10140702_59_dialog_content = "Nunca pensei que veria uma Lumina tão pura tão longe de Lumópolis.",
  ui_story_1014_10140702_60_dialog_content = "Não estou tão familiarizado com a igreja da fronteira. Você é um membro?",
  ui_story_1014_10140702_61_dialog_content = "A maneira como você está vestida... não é exatamente como eu imagino que uma freira faria.",
  ui_story_1014_10140702_62_dialog_content = "Ah, as pessoas sempre têm essa ideia de mim.",
  ui_story_1014_10140702_63_dialog_content = "Mas não sou membro da igreja, sinto muito.",
  ui_story_1014_10140702_64_dialog_content = "Não me diga que você é um soldado Illuminan?",
  ui_story_1014_10140702_65_dialog_content = "Soldados da Illumina não se vestem assim.",
  ui_story_1014_10140702_66_dialog_content = "Aqui na fronteira nem todo mundo tem que ser aliado de Lumopolis ou Illumina. E não são apenas os soldados que lutam.",
  ui_story_1014_10140702_67_dialog_content = "Tecnicamente, ela é uma comerciante de tomates.",
  ui_story_1014_10140702_68_dialog_content = "?!",
  ui_story_1014_10140702_69_dialog_content = "Gostaria de lembrar ao poderoso capitão que também trabalho com tricô.",
  ui_story_1014_10140702_70_dialog_content = "Você nunca comprou nem um único tomate de mim, mas eu consertei pelo menos dois de seus banners.",
  ui_story_1014_10140702_71_dialog_content = "Desculpas... Eu gostaria de apoiar o seu negócio, mas os tomates não fazem parte da dieta de um cavaleiro.",
  ui_story_1014_10140702_72_dialog_content = "Cavaleiros! O que comemos?",
  ui_story_1014_10140702_73_dialog_content = "EU NO!",
  ui_story_1014_10140702_74_dialog_content = "Nada como um saboroso pernil de borrego grelhado na perfeição!",
  ui_story_1014_10140702_75_dialog_content = "Bem... espero que seus gostos logo alcancem suas habilidades de combate.",
  ui_story_1014_10140702_76_dialog_content = "De qualquer forma, todos, exceto os cavaleiros, são estranhos, certo? Eu não acredito que já vi vocês antes.",
  ui_story_1014_10140702_77_dialog_content = "Isso mesmo. Chegamos recentemente de Gannon City, no leste.",
  ui_story_1014_10140702_78_dialog_content = "Cidade de Gannon? Então você realmente percorreu um longo caminho. Eu só vi isso em um mapa.",
  ui_story_1014_10140702_79_dialog_content = "E eu presumo que você vai ficar em Crepúsculo um pouco mais?",
  ui_story_1014_10140702_80_dialog_content = "De fato. Temos alguns assuntos para resolver aqui.",
  ui_story_1014_10140702_81_dialog_content = "Nesse caso, por que não vem comigo? Posso ajudar a arranjar algumas acomodações adequadas.",
  ui_story_1014_10140702_82_dialog_content = "E espero não estar incomodando, mas também gostaria de convidar todos vocês a experimentar algumas especialidades locais.",
  ui_story_1014_10140702_83_dialog_content = "É o mínimo que posso fazer para retribuir sua bravura.",
  ui_story_1014_10140702_84_dialog_content = "Eh? I-Isso é muito gentil, mas certamente desnecessário.",
  ui_story_1014_10140702_85_dialog_content = "Não recebemos muitos visitantes aqui, menos ainda os que lutariam em nosso nome.",
  ui_story_1014_10140702_86_dialog_content = "Eu pretendia convidar todos vocês para jantar também, se Joselyne não tivesse chegado antes de mim.",
  ui_story_1014_10140702_87_dialog_content = "Mas visto que Sua Santidade gentilmente se ofereceu para pagar a conta, sugiro que você a aceite!",
  ui_story_1014_10140702_88_dialog_content = "Entendo... O que todos pensam?",
  ui_story_1014_10140702_89_dialog_content = "Bem, neste ponto, seria rude não aceitar.",
  ui_story_1014_10140702_90_dialog_content = "Aceita com certeza! Eu quero saber que tipo de guloseimas a Twilight tem. Mal posso esperar!",
  ui_story_1014_10140702_91_dialog_content = "Conheço bem tudo o que nossa cidade tem a oferecer. Tenho certeza que todos ficarão satisfeitos.",
  ui_story_1014_10140702_92_dialog_content = "Você também lutou muito, capitão Leo. Você me daria a honra de se juntar a nós para jantar?",
  ui_story_1014_10140702_93_dialog_content = "Você está convidando apenas a mim ou a todos os Cavaleiros Ironthorn?",
  ui_story_1014_10140702_94_dialog_content = "Receio que o restaurante que eu tinha em mente não possa acomodar todos os cavaleiros.",
  ui_story_1014_10140702_95_dialog_content = "Ah, não pode demonstrar favoritismo assim, Santidade!",
  ui_story_1014_10140702_96_dialog_content = "Todos nós não derramamos sangue por Crepúsculo também?",
  ui_story_1014_10140702_97_dialog_content = "Tudo bem, tudo bem, vocês não vão perder.",
  ui_story_1014_10140702_98_dialog_content = "Para comemorar nossa vitória, esta noite vocês podem comer o que quiserem. É por minha conta.",
  ui_story_1014_10140702_99_dialog_content = "<size=45>SIM! Incrível!!</size>",
  ui_story_1014_10140702_100_dialog_content = "Receio não poder acompanhá-los, pois a Srta. Joselyne está sendo tão generosa.",
  ui_story_1014_10140702_101_dialog_content = "Vou acompanhar nossos novos amigos de longe.",
  ui_story_1014_10140702_102_dialog_content = "Eu também gostaria de ver por mim mesmo que tipo de comida os gostos refinados de Joselyne envolvem.",
  ui_story_1014_10140801_1_dialog_content = "O que fazemos para a cama e outras coisas...? Travesseiros, cobertores, roupas...",
  ui_story_1014_10140801_2_dialog_content = "Ah, eu não trouxe nada.",
  ui_story_1014_10140801_3_dialog_content = "Não é como se você pudesse parar e fazer as malas quando está fugindo para salvar sua vida.",
  ui_story_1014_10140801_4_dialog_content = "Nem tive tempo de achar minha carteira. Estou preocupado em passar fome em breve.",
  ui_story_1014_10140801_5_dialog_content = "Ei, ouvi dizer que eles podem te emprestar algumas coisas básicas lá.",
  ui_story_1014_10140801_6_dialog_content = "Vamos juntos dar uma olhada!",
  ui_story_1014_10140801_7_dialog_content = "Há tantos refugiados na rua.",
  ui_story_1014_10140801_8_dialog_content = "Todos eles chegaram aqui hoje?",
  ui_story_1014_10140801_9_dialog_content = "Sim. Infelizmente, essas cenas são muito comuns em Crepúsculo.",
  ui_story_1014_10140801_10_dialog_content = "Sério?",
  ui_story_1014_10140801_11_dialog_content = "Enquanto Lumopolis e Illumina têm guarnições aqui, as áreas fora de nossa cidade não são governadas por nenhum poder.",
  ui_story_1014_10140801_12_dialog_content = "As pequenas aldeias espalhadas são geralmente autossuficientes e satisfeitas.",
  ui_story_1014_10140801_13_dialog_content = "Mas, quando a Aurorastorm e os Eclipsites começaram a atacar, essas aldeias foram basicamente incapazes de se defender.",
  ui_story_1014_10140801_14_dialog_content = "Os aldeões não tiveram escolha a não ser abandonar suas casas e buscar abrigo nas guarnições.",
  ui_story_1014_10140801_15_dialog_content = "Eles chegaram como grãos de areia díspares, todos apanhados pelo vento e levados para o mesmo porto seguro.",
  ui_story_1014_10140801_16_dialog_content = "Os grãos de areia se acumularam em uma duna e os refugiados criaram raízes e estabeleceram Crepúsculo.",
  ui_story_1014_10140801_17_dialog_content = "Entendo...",
  ui_story_1014_10140801_18_dialog_content = "Por que as pessoas não optaram por seguir em frente e encontrar um lugar mais seguro?",
  ui_story_1014_10140801_19_dialog_content = "Você quer dizer Lumopolis ou Gannon no leste?",
  ui_story_1014_10140801_20_dialog_content = "Claro que eles queriam ir. Mas com o dia-a-dia já tão difícil, não era tão simples.",
  ui_story_1014_10140801_21_dialog_content = "Como eles ganhariam a vida em terras tão distantes? Onde eles viveriam?",
  ui_story_1014_10140801_22_dialog_content = "Ninguém forneceria voluntariamente terras ou moradias para forasteiros.",
  ui_story_1014_10140801_23_dialog_content = "Mas aqui nas ruínas de Aurora, pelo menos o solo é fértil e eles não precisam se preocupar com as necessidades básicas. Mesmo com a sempre presente ameaça Eclipsita...",
  ui_story_1014_10140801_24_dialog_content = "Todos achavam melhor enfrentar dificuldades conhecidas do que ficar sem raízes e vagando.",
  ui_story_1014_10140801_25_dialog_content = "Ah... me desculpe, eu estava sendo ingênuo.",
  ui_story_1014_10140801_26_dialog_content = "Hahaha, não se preocupe! Ninguém te julgaria.",
  ui_story_1014_10140801_27_dialog_content = "Tenho certeza de que este lugar é diferente de qualquer outro lugar que você já esteve, então é natural se perguntar.",
  ui_story_1014_10140801_28_dialog_content = "Você está certo, é totalmente diferente. Não apenas as pessoas são deixadas por conta própria, mas aparentemente, Lumopolis e Illumina podem coexistir na mesma cidade!",
  ui_story_1014_10140801_29_dialog_content = "Você diz coexistir, mas na realidade, eles geralmente se evitam.",
  ui_story_1014_10140801_30_dialog_content = "Há representantes de facções aqui conosco agora. Você pode perguntar a eles.",
  ui_story_1014_10140801_31_dialog_content = "A coexistência de Lumopolis e Illumina é algo que vem acontecendo desde que cheguei em Crepúsculo quando criança.",
  ui_story_1014_10140801_32_dialog_content = "Mas ouvi alguns dos anciãos falarem sobre problemas no passado.",
  ui_story_1014_10140801_33_dialog_content = "Todos os poderes querem manter a fronteira das Ruínas de Aurora segura. Mas fora isso, não há ordens mais explícitas.",
  ui_story_1014_10140801_34_dialog_content = "Illumina e Lumopolis vêem as Ruínas de Aurora da mesma forma: uma fronteira desolada que dificilmente vale o tempo de alguém, mas ainda uma pena abandonar.",
  ui_story_1014_10140801_35_dialog_content = "Como ninguém de alto escalão pode se incomodar com este lugar, os soldados de ambos os lados tendem a perder a meticulosidade sobre as coisas que aprenderam sobre o outro.",
  ui_story_1014_10140801_36_dialog_content = "Embora a terra dentro e ao redor das ruínas de Aurora seja bastante fértil, há uma nítida falta de fontes de energia. Aqueles que temos estão concentrados principalmente em Crepúsculo e seus arredores.",
  ui_story_1014_10140801_37_dialog_content = "Para poder atender às suas próprias necessidades de energia, ambos os lados concordaram em ser guarnecidos conjuntamente aqui.",
  ui_story_1014_10140801_38_dialog_content = "Lutar pelos mesmos recursos escassos não causaria conflito?",
  ui_story_1014_10140801_39_dialog_content = "Lidar com os Eclipsites já é tão exaustivo que ninguém tem forças de sobra para conflitos internos.",
  ui_story_1014_10140801_40_dialog_content = "Sobrevivência é o nome do jogo aqui.",
  ui_story_1014_10140801_41_dialog_content = "O campo de batalha logo educa aqueles que não conseguem diferenciar prioridades.",
  ui_story_1014_10140801_42_dialog_content = "Então é assim.",
  ui_story_1014_10140801_43_dialog_content = "Isso me lembra da Coalizão Auroriana sobre a qual li em um livro de história.",
  ui_story_1014_10140801_44_dialog_content = "Diante de poderosos inimigos externos, os dois lados conseguiram resolver suas diferenças.",
  ui_story_1014_10140801_45_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_1014_10140801_46_dialog_content = "<anim type=Shake>Nghn...</anim>",
  ui_story_1014_10140801_47_dialog_content = "Axélia! Você está acordado!",
  ui_story_1014_10140801_48_dialog_content = "Bom Dia, PlayerName.",
  ui_story_1014_10140801_49_dialog_content = "Não é nem remotamente perto da manhã...",
  ui_story_1014_10140801_50_dialog_content = "Huh? Você teve uma garota adorável escondida?",
  ui_story_1014_10140801_51_dialog_content = "Minha aparência é normal e fundamentalmente sem importância.",
  ui_story_1014_10140801_52_dialog_content = "Estou, no entanto, morrendo de fome.",
  ui_story_1014_10140801_53_dialog_content = "Bom momento! Este é o restaurante.",
  ui_story_1014_10140801_54_dialog_content = "O que você gostaria de comer?",
  ui_story_1014_10140801_55_dialog_content = "Açúcar.",
  ui_story_1014_10140801_56_dialog_content = "Aqui temos folhados, pastéis de nata, folhados de nata ou bolo com cobertura de manteiga.",
  ui_story_1014_10140801_57_dialog_content = "Mmm, tudo parece excelente.",
  ui_story_1014_10140801_58_dialog_content = "Você acha que está tudo bem comer tantas sobremesas, Joselyne?",
  ui_story_1014_10140801_59_dialog_content = "Está bem. Uma indulgência ocasional não é um problema.",
  ui_story_1014_10140801_60_dialog_content = "Parece haver uma série de rostos desconhecidos com você hoje.",
  ui_story_1014_10140801_61_dialog_content = "Sim, esses convidados vieram de Gannon City.",
  ui_story_1014_10140801_62_dialog_content = "Gannon, é? O velho da porta ao lado esteve lá. Ouvi dizer que é um lugar terrivelmente rígido...",
  ui_story_1014_10140801_63_dialog_content = "R-Rígida? Não é tão ruim...",
  ui_story_1014_10140801_64_dialog_content = "Além deles, também temos nossos próprios soldados locais.",
  ui_story_1014_10140801_65_dialog_content = "Este é Sean, um jovem oficial Illuminan... E este é Leo, capitão dos Lumopolis Ironthorn Knights.",
  ui_story_1014_10140801_66_dialog_content = "Sim! Sou o segundo-tenente Sean, da Guarnição do Crepúsculo!",
  ui_story_1014_10140801_67_dialog_content = "Ei, isso não é um refeitório Illumina. Não há necessidade de saudar.",
  ui_story_1014_10140801_68_dialog_content = "Hahaha, é sempre interessante ver a reação do Sean.",
  ui_story_1014_10140801_69_dialog_content = "Chefe, sua carne de porco assada está absolutamente deslumbrante.",
  ui_story_1014_10140801_70_dialog_content = "Da próxima vez trarei todos os meus cavaleiros aqui para provar!",
  ui_story_1014_10140801_71_dialog_content = "Lá vai você de novo, só pensando em carne.",
  ui_story_1014_10140801_72_dialog_content = "Afinal, este é um negócio e você não sobreviverá se não oferecer qualidade.",
  ui_story_1014_10140801_73_dialog_content = "Não vejo mais ninguém trabalhando aqui. Você não pode ser o único cuidando de um lugar tão grande?",
  ui_story_1014_10140801_74_dialog_content = "Que eu sou.",
  ui_story_1014_10140801_75_dialog_content = "Isso não é cansativo? Com seus talentos, você definitivamente poderia trazer algumas novas mãos para ajudar a expandir o negócio.",
  ui_story_1014_10140801_76_dialog_content = "Eu não estou realmente interessado. Estou feliz por ser um show de um homem só.",
  ui_story_1014_10140801_77_dialog_content = "Quando abri pela primeira vez, foi com meu irmão, mas discutíamos tanto que logo se tornou cansativo.",
  ui_story_1014_10140801_78_dialog_content = "É a primeira vez que ouço você mencionar um irmão.",
  ui_story_1014_10140801_79_dialog_content = "Sim. Ele faleceu há três anos.",
  ui_story_1014_10140801_80_dialog_content = "Ele foi morto por Eclipsites enquanto fugíamos para Crepúsculo.",
  ui_story_1014_10140801_81_dialog_content = "Ai...",
  ui_story_1014_10140801_82_dialog_content = "Ele teve alguns problemas nas pernas e estava lutando na parte de trás do grupo.",
  ui_story_1014_10140801_83_dialog_content = "Os cavaleiros de Lumopolis chegaram no momento em que os Eclipsitas se aproximavam. Mas não o salvaram.",
  ui_story_1014_10140801_84_dialog_content = "...",
  ui_story_1014_10140801_85_dialog_content = "(Os cavaleiros...)",
  ui_story_1014_10140801_86_dialog_content = "Eu não os odeio. Na verdade, eles me salvaram.",
  ui_story_1014_10140801_87_dialog_content = "vida não vale muito por aqui e não há muito espaço para barganhas.",
  ui_story_1014_10140801_88_dialog_content = "Não importa quem é salvo e quem não. Está tudo destinado a ser.",
  ui_story_1014_10140801_89_dialog_content = "Não diga isso. Todas as vidas são igualmente valiosas.",
  ui_story_1014_10140801_90_dialog_content = "Sei que é assim que você vê, Joselyne, porque você é diferente.",
  ui_story_1014_10140801_91_dialog_content = "Você vai salvar todo mundo e fazer todo mundo querer acreditar que existe alguma divindade neste mundo.",
  ui_story_1014_10140801_92_dialog_content = "Mas não sou eu quem mantém a paz em Crepúsculo. São os soldados guarnecidos aqui.",
  ui_story_1014_10140801_93_dialog_content = "Se não valorizássemos todas as vidas, como Crepúsculo poderia evoluir para o refúgio que é hoje?",
  ui_story_1014_10140801_94_dialog_content = "A vida é maravilhosa. E tanto salvá-los quanto abandoná-los são atos de homenagem diante de tamanho deslumbramento.",
  ui_story_1014_10140801_95_dialog_content = "Esses soldados acabaram de enfrentar a escolha final antes de qualquer outra pessoa.",
  ui_story_1014_10140801_96_dialog_content = "...",
  ui_story_1014_10140801_97_dialog_content = "Na verdade, eles—",
  ui_story_1014_10140801_98_dialog_content = "Joselyne, você poderia me passar aquele prato de salsichas na sua frente, por favor? Eu simplesmente não consigo o suficiente.",
  ui_story_1014_10140801_99_dialog_content = "Ah, aqui.",
  ui_story_1014_10140801_100_dialog_content = "Então, PlayerName, eu realmente não perguntei... O que te traz a Crepúsculo?",
  ui_story_1014_10140801_101_dialog_content = "(Hmm... Leo mudou de assunto.)",
  ui_story_1014_10140801_102_dialog_content = "E ter um oficial Illumina de alto escalão acompanhando você! Isso é uma grande honra.",
  ui_story_1014_10140801_103_dialog_content = "Claro, se for confidencial, esqueça que perguntei.",
  ui_story_1014_10140801_104_dialog_content = "Oh, uh, estamos aqui para consertar o Colossus.",
  ui_story_1014_10140801_105_dialog_content = "Colosso?! Você está dizendo que tem...",
  ui_story_1014_10140801_106_dialog_content = "Isso mesmo! Você é um celestita, então suponho que seja normal.",
  ui_story_1014_10140801_107_dialog_content = "Você mencionou reparos... Qual é o problema com isso?",
  ui_story_1014_10140801_108_dialog_content = "Não tenho certeza da melhor forma de explicar. Não é que algo tenha funcionado mal, mas parece ter perdido temporariamente a consciência.",
  ui_story_1014_10140801_109_dialog_content = "Um Colossus perdendo a consciência talvez seja um pouco complicado de entender...",
  ui_story_1014_10140801_110_dialog_content = "Está tudo bem, eu entendo. É bem fácil de entender.",
  ui_story_1014_10140801_111_dialog_content = "Não é à toa que você veio para Crepúsculo, então. Presumo que esteja procurando pelo pesquisador Illumina?",
  ui_story_1014_10140801_112_dialog_content = "Sim. Como você sabia?",
  ui_story_1014_10140801_113_dialog_content = "Posso não entender os prós e contras de um Colossus, mas estou familiarizado com sua história.",
  ui_story_1014_10140801_114_dialog_content = "É mais correto dizer que todos em Crepúsculo conhecem a história.",
  ui_story_1014_10140801_115_dialog_content = "Não há muitas lendas dignas de serem contadas em um lugar tão remoto quanto este.",
  ui_story_1014_10140801_116_dialog_content = "Legendas? Que tipo de histórias você já ouviu?",
  ui_story_1014_10140801_117_dialog_content = "Deixe-me pensar por onde começar.",
  ui_story_1014_10140801_118_dialog_content = "Esqueça. Melhor deixar Joselyne lhe contar. Ela sabe contar uma boa história.",
  ui_story_1014_10140801_119_dialog_content = "não é? Eu vejo você tagarelando na taverna, a noite toda...",
  ui_story_1014_10140801_120_dialog_content = "Estou ocupado comendo carne agora.",
  ui_story_1014_10140801_121_dialog_content = "Ha! Multar. Convidei-te para jantar, suponho que não posso deixar-te passar fome.",
  ui_story_1014_10140801_122_dialog_content = "Então, essa lenda remonta a mil anos.",
  ui_story_1014_10140801_123_dialog_content = "Não demorou muito para que os aurorianos deixassem Northland, quando Lumopolis acabara de ser fundada.",
  ui_story_1014_10140801_124_dialog_content = "A fim de estabelecer um lar adequado, os aurorianos se militarizaram e começaram sua luta interminável contra os eclipsitas.",
  ui_story_1014_10140801_125_dialog_content = "O território auroriano continuou se expandindo durante o conflito, tornando-se algo semelhante ao que temos hoje.",
  ui_story_1014_10140801_126_dialog_content = "O ponto mais distante dessa expansão é exatamente onde você está agora: as Ruínas Aurora.",
  ui_story_1014_10140801_127_dialog_content = "Uau! Portanto, este lugar está na fronteira há tanto tempo!",
  ui_story_1014_10140801_128_dialog_content = "Não subestime a posição estratégica das Ruínas Aurora.",
  ui_story_1014_10140801_129_dialog_content = "Enquanto a linha defensiva das Ruínas Aurora durar, os Eclipsitas estarão contidos na noite eterna e impedidos de alcançar o resto do continente.",
  ui_story_1014_10140801_130_dialog_content = "Por outro lado, se perdermos essa passagem estreita, uma área muito maior ficará diretamente exposta à ameaça do Eclipsita.",
  ui_story_1014_10140801_131_dialog_content = "Esta batalha foi um ponto de virada crucial na cruzada auroriana para obter o controle de Astra.",
  ui_story_1014_10140801_132_dialog_content = "Você quer continuar, ou devo eu?",
  ui_story_1014_10140801_133_dialog_content = "Você continua. Eu estava apenas adicionando algum contexto extra.",
  ui_story_1014_10140801_134_dialog_content = "A batalha pelas Ruínas Aurora foi muito difícil.",
  ui_story_1014_10140801_135_dialog_content = "Está muito perto da noite eterna aqui, com fenômenos de aurora imprevisíveis, e os Eclipsites têm uma força sem precedentes.",
  ui_story_1014_10140801_136_dialog_content = "O conflito se arrastou. Uma linha defensiva não pôde ser totalmente estabelecida, e os aurorianos mortos jaziam em pilhas que só pareciam crescer mais.",
  ui_story_1014_10140801_137_dialog_content = "Um dia amanheceu nessa guerra interminável, um dia do qual não há registros escritos.",
  ui_story_1014_10140801_138_dialog_content = "O destino finalmente sorriu para os aurorianos.",
  ui_story_1014_10140801_139_dialog_content = "Acima do campo de batalha, uma nuvem escura como ninguém jamais havia visto bloqueou o próprio sol.",
  ui_story_1014_10140801_140_dialog_content = "Era uma frota de <color=#FFB400>colossos</color>.",
  ui_story_1014_10140801_141_dialog_content = "Uma frota?!",
  ui_story_1014_10140801_142_dialog_content = "(Já vi isso! Já vi algo assim!)",
  ui_story_1014_10140801_143_dialog_content = "(Foi a frota?)",
  ui_story_1014_10140801_144_dialog_content = "A frota navegou para longe. Mas um deles pousou.",
  ui_story_1014_10140801_145_dialog_content = "De alguma forma, ele se comunicou com os aurorianos e decidiu ficar para trás e lutar ao lado deles.",
  ui_story_1014_10140801_146_dialog_content = "Espere, você tem certeza que o Colosso se comunicou com os aurorianos?",
  ui_story_1014_10140801_147_dialog_content = "Não é o celestita a bordo?",
  ui_story_1014_10140801_148_dialog_content = "Não. Na verdade, não havia nenhum Celestita a bordo daquele Colosso.",
  ui_story_1014_10140801_149_dialog_content = "Foi o Colosso <color=#FFB400>própria consciência</color> que tomou a decisão.",
  ui_story_1014_10140801_150_dialog_content = "O próprio Colosso...",
  ui_story_1014_10140801_151_dialog_content = "Um amigo nerd uma vez me informou que na história auroriana, a palavra Colossus é anterior à palavra Caelestite.",
  ui_story_1014_10140801_152_dialog_content = "Isso pode realmente apoiar a lenda.",
  ui_story_1014_10140801_153_dialog_content = "Então o que aconteceu depois? O Colossus ficou nas ruínas de Aurora?",
  ui_story_1014_10140801_154_dialog_content = "Sim. Era como um soldado especial, de alguma forma comprometido com esta guerra prolongada.",
  ui_story_1014_10140801_155_dialog_content = "Não foi até muitos anos depois que a guerra foi finalmente vencida, e os aurorianos conseguiram estabelecer sua própria fortaleza nas Ruínas de Aurora.",
  ui_story_1014_10140801_156_dialog_content = "Devido à crescente inatividade de anos de dano de batalha, o Colossus acabou se transformando em uma estátua silenciosa.",
  ui_story_1014_10140801_157_dialog_content = "Os aurorianos aqui veneram o Colosso, tratando-o como um totem religioso a ser venerado.",
  ui_story_1014_10140801_158_dialog_content = "É incrível pensar que ele pulou os caelestitas para formar um vínculo com os aurorianos.",
  ui_story_1014_10140801_159_dialog_content = "Está bem conservado?",
  ui_story_1014_10140801_160_dialog_content = "Deixe-me terminar a história primeiro.",
  ui_story_1014_10140801_161_dialog_content = "Então chegamos a tempos mais modernos. A emergente Federação Illumina enviou tropas para as Ruínas Aurora.",
  ui_story_1014_10140801_162_dialog_content = "Seus pesquisadores começaram a estudar o Colossus na tentativa de consertar o gigante danificado.",
  ui_story_1014_10140801_163_dialog_content = "Eles tiveram... semi-sucesso, digamos assim.",
  ui_story_1014_10140801_164_dialog_content = "Foi consertado temporariamente, apenas para um mau funcionamento desconhecido que fez o Colossus enlouquecer.",
  ui_story_1014_10140801_165_dialog_content = "O incontrolável Colossus, finalmente, colidiu com a inescrutável Dark Zone.",
  ui_story_1014_10140801_166_dialog_content = "Caiu na Zona Cega? Que perda!",
  ui_story_1014_10140801_167_dialog_content = "Sim, muitos da geração mais velha ainda guardam rancor contra Illumina por isso.",
  ui_story_1014_10140801_168_dialog_content = "E assim seus soldados recebem o ombro frio.",
  ui_story_1014_10140801_169_dialog_content = "Eu vejo! Eu estava me perguntando por que os velhos do mercado não falavam comigo.",
  ui_story_1014_10140801_170_dialog_content = "Achei que os ofendi de alguma forma...",
  ui_story_1014_10140801_171_dialog_content = "É assim que as coisas funcionam em Crepúsculo. Muitos eventos não têm perpetradores claros, então os conflitos nunca são resolvidos.",
  ui_story_1014_10140801_172_dialog_content = "Também é difícil determinar o certo e o errado quando se trata dos esforços da Illumina.",
  ui_story_1014_10140801_173_dialog_content = "Fazer com que a cidade de Crepúsculo perdesse o antigo Colosso certamente foi culpa deles.",
  ui_story_1014_10140801_174_dialog_content = "Mas se a pesquisa deles acabar ajudando a consertar o Colossus de PlayerName, bem, não foi de todo ruim então.",
  ui_story_1014_10140801_175_dialog_content = "Falando nisso, o pesquisador da Illumina entrou em contato comigo.",
  ui_story_1014_10140801_176_dialog_content = "Ele está muito interessado em consertar o Colossus e gostaria de começar o quanto antes.",
  ui_story_1014_10140801_177_dialog_content = "Sério? Mas é tão tarde. Ele deveria estar se preparando para dormir.",
  ui_story_1014_10140801_178_dialog_content = "Não se preocupe com isso, ele acabou de acordar.",
  ui_story_1014_10140801_179_dialog_content = "Acordei agora?",
  ui_story_1014_10140801_180_dialog_content = "Você os conhece, cientistas... Um grupo excêntrico.",
  ui_story_1014_10140801_181_dialog_content = "Sim, verdade.",
  ui_story_1014_10140801_182_dialog_content = "Nesse caso, vamos ao centro de pesquisa depois de comermos.",
  ui_story_1014_10140801_183_dialog_content = "Não gosto de procrastinar quando se trata de assuntos envolvendo Soroz.",
  ui_story_1014_10140801_184_dialog_content = "<color=#e8d9bb>Rangido-</color>",
  ui_story_1014_10140801_185_dialog_content = "Eles saíram.",
  ui_story_1014_10140801_186_dialog_content = "Interessante, esses forasteiros.",
  ui_story_1014_10140801_187_dialog_content = "Sim, intrigante.",
  ui_story_1014_10140801_188_dialog_content = "Oficiais Illumina e a Princesa de Lumopolis... Não imaginava que eles se dariam.",
  ui_story_1014_10140801_189_dialog_content = "O Caelestite é lendário por uma razão.",
  ui_story_1014_10140801_190_dialog_content = "Oh sim, você não vai me agradecer?",
  ui_story_1014_10140801_191_dialog_content = "Devo, Sua Santidade? Eu teria presumido que você seria benevolente o suficiente para me poupar diante dos cidadãos.",
  ui_story_1014_10140801_192_dialog_content = "Achei que me agradecer faria você se sentir melhor consigo mesmo.",
  ui_story_1014_10140801_193_dialog_content = "Na verdade, você deveria estar me agradecendo.",
  ui_story_1014_10140801_194_dialog_content = "Por quê?",
  ui_story_1014_10140801_195_dialog_content = "Porque foi errado da sua parte entrar de cabeça na batalha, tentando salvar as pessoas de forma tão imprudente.",
  ui_story_1014_10140801_196_dialog_content = "Você pode ser o herói todas as vezes apenas porque alguém o protege.",
  ui_story_1014_10140801_197_dialog_content = "Ah, você está certo. Devo agradecer a esse alguém.",
  ui_story_1014_10140801_198_dialog_content = "Mas, nesse caso, você ainda tem que me agradecer.",
  ui_story_1014_10140801_199_dialog_content = "Por que diz isso?",
  ui_story_1014_10140801_200_dialog_content = "Porque te dei menos motivos para arrependimento.",
  ui_story_1014_10140801_201_dialog_content = "Oh meu Deus, um Colosso inteiro!",
  ui_story_1014_10140801_202_dialog_content = "Isso é incrível! Você percebe o quanto isso é valioso para a pesquisa?",
  ui_story_1014_10140801_203_dialog_content = "Perdoe-me, mas não estamos entregando Soroz para você estudar.",
  ui_story_1014_10140801_204_dialog_content = "Nós viemos para—",
  ui_story_1014_10140801_205_dialog_content = "Sim, eu sei, o comércio, certo?",
  ui_story_1014_10140801_206_dialog_content = "Você trouxe o Combat Cyborg?",
  ui_story_1014_10140801_207_dialog_content = "Sim, aqui.",
  ui_story_1014_10140801_208_dialog_content = "Esse é o único. Apenas deixe-o lá.",
  ui_story_1014_10140801_209_dialog_content = "Deixe a consciência do Colosso comigo.",
  ui_story_1014_10140801_210_dialog_content = "Não há problema em gravar alguns dados enquanto estou fazendo isso, certo? Isso é justo.",
  ui_story_1014_10140801_211_dialog_content = "Claro, contanto que você consiga fazer Soroz recuperar a consciência.",
  ui_story_1014_10140801_212_dialog_content = "Tudo bem, deixe-me começar agora!",
  ui_story_1014_10140801_213_dialog_content = "Posso ficar e assistir?",
  ui_story_1014_10140801_214_dialog_content = "J-Apenas no caso de haver um acidente ou algo assim.",
  ui_story_1014_10140801_215_dialog_content = "Não tem problema, se não te aborrece.",
  ui_story_1014_10140801_216_dialog_content = "É muito tarde, PlayerName. Tem certeza que quer ficar aqui?",
  ui_story_1014_10140801_217_dialog_content = "Sim. Não consigo dormir enquanto Soroz está sendo consertado, então também posso.",
  ui_story_1014_10140801_218_dialog_content = "Vocês deveriam se entregar.",
  ui_story_1014_10140801_219_dialog_content = "Você vai ficar bem sozinho?",
  ui_story_1014_10140801_220_dialog_content = "Está bem. Afinal, este é o território Illumina. Nada deve acontecer.",
  ui_story_1014_10140801_221_dialog_content = "Tudo bem então. Não exagere.",
  ui_story_1014_10140801_222_dialog_content = "Entendido.",
  ui_story_1014_10140801_223_dialog_content = "<color=#e8d9bb>Clam, clang!</color>",
  ui_story_1014_10140801_224_dialog_content = "Ei, acorde, celestita.",
  ui_story_1014_10140801_225_dialog_content = "O quê...",
  ui_story_1014_10140801_226_dialog_content = "Levante-se e brilhe. Chega de dormir.",
  ui_story_1014_10140801_227_dialog_content = "Hum...",
  ui_story_1014_10140801_228_dialog_content = "Por que você está apenas virando?",
  ui_story_1014_10140801_229_dialog_content = "Levante-se e veja por si mesmo...",
  ui_story_1014_10140801_230_dialog_content = "Já faz muito tempo, PlayerName.",
  ui_story_1014_10140801_231_dialog_content = "<size=50>!!!</size>",
  ui_story_1014_10140801_232_dialog_content = "Soroz! Você está de volta?",
  ui_story_1014_10140801_233_dialog_content = "Prossiga. Terminei os reparos.",
  ui_story_1014_10140801_234_dialog_content = "Mas ainda não temos dados suficientes para manter sua consciência.",
  ui_story_1014_10140801_235_dialog_content = "É melhor você aproveitar esta chance.",
  ui_story_1014_10140801_236_dialog_content = "Isso não pode ser mantido?",
  ui_story_1014_10140801_237_dialog_content = "Obrigada, PlayerName, por continuar tentando encontrar uma maneira de me restaurar.",
  ui_story_1014_10140801_238_dialog_content = "Que bom ouvir sua voz novamente, Soroz!",
  ui_story_1014_10140801_239_dialog_content = "Muita coisa aconteceu. Eu quero começar com—",
  ui_story_1014_10140801_240_dialog_content = "Peço desculpas, mas desta vez também não poderei ficar muito tempo.",
  ui_story_1014_10140801_241_dialog_content = "...",
  ui_story_1014_10140801_242_dialog_content = "Sua abordagem está correta, mas faltam dados de suporte.",
  ui_story_1014_10140801_243_dialog_content = "Sim, não tive a chance de terminar minha pesquisa antes do Colossus... Suspiro.",
  ui_story_1014_10140801_244_dialog_content = "O-O que devemos fazer, então?",
  ui_story_1014_10140801_245_dialog_content = "Eu localizei aquele outro Colosso.",
  ui_story_1014_10140801_246_dialog_content = "O quê?!",
  ui_story_1014_10140801_247_dialog_content = "Nós só precisamos encontrá-lo, então? Cadê?",
  ui_story_1014_10140801_248_dialog_content = "<anim type=Shake>Meu tempo está quase acabando...</anim>",
  ui_story_1014_10140801_249_dialog_content = "<anim type=Shake>Vou deixar as coordenadas no terminal...</anim>",
  ui_story_1014_10140801_250_dialog_content = "Coordenadas? Para o Colosso?",
  ui_story_1014_10140801_251_dialog_content = "<anim type=Shake>PlayerName, Eu acredito em você.</anim>",
  ui_story_1014_10140801_252_dialog_content = "<anim type=Shake>Por favor... acredite em você também.</anim>",
  ui_story_1014_10140901_1_dialog_content = "Aqui está o mapa de batalha mais abrangente para as ruínas de Aurora.",
  ui_story_1014_10140901_2_dialog_content = "Consegui isso por meio de acesso especial, então não mostre a mais ninguém.",
  ui_story_1014_10140901_3_dialog_content = "As coordenadas que você está procurando devem estar por aqui.",
  ui_story_1014_10140901_4_dialog_content = "Isso é na Zona Cega?",
  ui_story_1014_10140901_5_dialog_content = "Sim, e é uma Cidade Baixa.",
  ui_story_1014_10140901_6_dialog_content = "A Illumina manteve sua exploração no nível da superfície e não mais fundo.",
  ui_story_1014_10140901_7_dialog_content = "Portanto, é um território essencialmente desconhecido.",
  ui_story_1014_10140901_8_dialog_content = "Podemos ir lá?",
  ui_story_1014_10140901_9_dialog_content = "Sim, mas é muito perigoso, então é melhor você refletir sobre isso.",
  ui_story_1014_10140901_10_dialog_content = "Entendido. Não há nada para meditar. É para Soroz, então devo ir.",
  ui_story_1014_10140901_11_dialog_content = "Eu não estava tentando impedir você. Eu só queria que você pensasse bem.",
  ui_story_1014_10140901_12_dialog_content = "Digamos que você encontre o antigo Colossus, e daí? Como você está transportando-o de volta?",
  ui_story_1014_10140901_13_dialog_content = "Pois é...",
  ui_story_1014_10140901_14_dialog_content = "Tudo bem, eu ajudo! Pego meu superior para comandar um veículo de transporte!",
  ui_story_1014_10140901_15_dialog_content = "Eu pratiquei dirigir antes. Posso trazer o Colosso de volta!",
  ui_story_1014_10140901_16_dialog_content = "Sério? Isso é maravilhoso!",
  ui_story_1014_10140901_17_dialog_content = "Vocês dois...",
  ui_story_1014_10140901_18_dialog_content = "Se vocês dois pudessem combinar sua única célula cerebral em um cérebro funcional, eu diria que é um milagre.",
  ui_story_1014_10140901_19_dialog_content = "Vamos primeiro ignorar se o Colossus cabe na traseira de um veículo.",
  ui_story_1014_10140901_20_dialog_content = "As cidades subterrâneas apenas magicamente pavimentaram estradas para você dirigir? Como você vai fugir dos Eclipsites enxames?",
  ui_story_1014_10140901_21_dialog_content = "ah... sobre isso...",
  ui_story_1014_10140901_22_dialog_content = "Quais peças específicas você precisa para consertar Soroz, Pesquisador?",
  ui_story_1014_10140901_23_dialog_content = "Bem, eu preferiria um Colosso inteiro, para ser honesto.",
  ui_story_1014_10140901_24_dialog_content = "Não sabemos tudo sobre Colossi, então qualquer coisa que faltar pode ser um problema.",
  ui_story_1014_10140901_25_dialog_content = "Mas se eu tivesse que escolher um...",
  ui_story_1014_10140901_26_dialog_content = "Seria o <color=#FFB400>Módulo de controle primário</color>.",
  ui_story_1014_10140901_27_dialog_content = "Tem o maior valor em termos de pesquisa e foi objeto do estudo anterior.",
  ui_story_1014_10140901_28_dialog_content = "OK. Vamos reavaliar nosso objetivo. Não o Colossus inteiro, mas o módulo de controle primário nele.",
  ui_story_1014_10140901_29_dialog_content = "Esta operação ultrapassa os limites do que você negociou em Gannon.",
  ui_story_1014_10140901_30_dialog_content = "Portanto, você não receberá ajuda adicional da Illumina.",
  ui_story_1014_10140901_31_dialog_content = "Sim, eu sei. Este é um assunto pessoal.",
  ui_story_1014_10140901_32_dialog_content = "No entanto, você ainda pode receber ajuda de certos indivíduos.",
  ui_story_1014_10140901_33_dialog_content = "Hã?",
  ui_story_1014_10140901_34_dialog_content = "Você está insinuando que posso ajudar, Yingel?",
  ui_story_1014_10140901_35_dialog_content = "Sim. Sua agenda está aberta. Você é livre para fazer o que quiser.",
  ui_story_1014_10140901_36_dialog_content = "Oh sim!",
  ui_story_1014_10140901_37_dialog_content = "Sean...",
  ui_story_1014_10140901_38_dialog_content = "Da mesma forma, Axelia e eu também não temos nada para fazer.",
  ui_story_1014_10140901_39_dialog_content = "Vocês também querem me ajudar?",
  ui_story_1014_10140901_40_dialog_content = "Undercities na Dark Zone são letais. Prefiro que Sean não leve o único celestita do mundo à morte.",
  ui_story_1014_10140901_41_dialog_content = "Vou verificar a condição de Axelia. Partiremos quando estivermos prontos.",
  ui_story_1014_10140901_42_dialog_content = "Legal, PlayerName! Deixe-me pegar um caminhão do meu superior!",
  ui_story_1014_10140901_43_dialog_content = "Eu estou sem palavras...",
  ui_story_1014_10140901_44_dialog_content = "Muito obrigado.",
  ui_story_1014_10140901_45_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_1014_10140901_46_dialog_content = "Doces para você, Axelia.",
  ui_story_1014_10140901_47_dialog_content = "Tá bom.",
  ui_story_1014_10140901_48_dialog_content = "Como está indo sua missão, Yingel?",
  ui_story_1014_10140901_49_dialog_content = "Já terminou. Chegamos aqui com segurança, não é?",
  ui_story_1014_10140901_50_dialog_content = "Eu quis dizer o outro.",
  ui_story_1014_10140901_51_dialog_content = "O outro?",
  ui_story_1014_10140901_52_dialog_content = "Se você completasse sua missão, não continuaria ajudando PlayerName.",
  ui_story_1014_10140901_53_dialog_content = "Você tem alguma outra agenda.",
  ui_story_1014_10140901_54_dialog_content = "...",
  ui_story_1014_10140901_55_dialog_content = "Eu nunca posso dizer o que passa pela sua cabeça, às vezes. Você não parece prestar atenção, mas sabe de tudo.",
  ui_story_1014_10140901_56_dialog_content = "Eu te conheço, Yingel.",
  ui_story_1014_10140901_57_dialog_content = "Se for uma tarefa que eu não deveria saber, você não precisa dizer nada.",
  ui_story_1014_10140901_58_dialog_content = "Estou procurando por <color=#FFB400>abandono</color>.",
  ui_story_1014_10140901_59_dialog_content = "Aquele cientista traidor?",
  ui_story_1014_10140901_60_dialog_content = "Uhum.",
  ui_story_1014_10140901_61_dialog_content = "Ela está em Crepúsculo?",
  ui_story_1014_10140901_62_dialog_content = "Ninguém sabe onde ela está.",
  ui_story_1014_10140901_63_dialog_content = "Então, o melhor que posso fazer é atraí-la para fora.",
  ui_story_1014_10140901_64_dialog_content = "O celestita é a isca?",
  ui_story_1014_10140901_65_dialog_content = "Milímetros. Ninguém poderia ser melhor.",
  ui_story_1014_10140901_66_dialog_content = "Presumo que ele não tenha ideia.",
  ui_story_1014_10140901_67_dialog_content = "Ele vai ficar bravo, você sabe.",
  ui_story_1014_10140901_68_dialog_content = "...",
  ui_story_1014_10140901_69_dialog_content = "Importas-te de tirar uma soneca depois de acabares com os doces, Axelia?",
  ui_story_1014_10140901_70_dialog_content = "Eu gostaria que você dormisse até eu te acordar.",
  ui_story_1014_10140901_71_dialog_content = "Eu vou ouvir você.",
  ui_story_1014_10140901_72_dialog_content = "Eu disse que estou indo!",
  ui_story_1014_10140901_73_dialog_content = "E eu entendo isso, Alteza.",
  ui_story_1014_10140901_74_dialog_content = "Então o que você está fazendo me atrapalhando?",
  ui_story_1014_10140901_75_dialog_content = "Por favor, entenda que estou apenas seguindo as ordens do Senhor da Cidade.",
  ui_story_1014_10140901_76_dialog_content = "O senhor da cidade? Por que ouço esse nome mesmo em Crepúsculo?",
  ui_story_1014_10140901_77_dialog_content = "Ele nunca se importa com o que acontece nas fronteiras.",
  ui_story_1014_10140901_78_dialog_content = "Porque você está aqui, Alteza. É uma situação difícil para nós também, por favor, entenda.",
  ui_story_1014_10140901_79_dialog_content = "Estamos apenas em serviço de patrulha, a Fortaleza Lumo não tem o direito de interferir.",
  ui_story_1014_10140901_80_dialog_content = "Por favor, mostre os documentos apropriados se for uma ordem do Senhor da Cidade.",
  ui_story_1014_10140901_81_dialog_content = "Hum...",
  ui_story_1014_10140901_82_dialog_content = "Carleen? Bereta? O que está acontecendo aqui?",
  ui_story_1014_10140901_83_dialog_content = "Por que os guardas de Lumopolis estão prendendo você?",
  ui_story_1014_10140901_84_dialog_content = "Bem na hora, PlayerName, Vice.",
  ui_story_1014_10140901_85_dialog_content = "Beretta e eu queremos ir ao Forte Lumo buscar suprimentos antes de partirmos.",
  ui_story_1014_10140901_86_dialog_content = "Mas eles se recusam a nos deixar passar.",
  ui_story_1014_10140901_87_dialog_content = "Não vamos impedi-lo, Alteza. É que para onde você está indo é muito perigoso. Devemos enviar escoltas com você para garantir sua segurança.",
  ui_story_1014_10140901_88_dialog_content = "Nunca precisei da proteção de ninguém no campo de batalha.",
  ui_story_1014_10140901_89_dialog_content = "Ei, PlayerName, estive procurando por você por toda parte.",
  ui_story_1014_10140901_90_dialog_content = "Ouvi dizer que você está indo para uma Cidade Baixa na Zona Cega. Posso ir junto?",
  ui_story_1014_10140901_91_dialog_content = "Você quer ir também?",
  ui_story_1014_10140901_92_dialog_content = "Você é o reforço que a Fortaleza Lumo está enviando?",
  ui_story_1014_10140901_93_dialog_content = "Não não. Há muito tempo que queria ir àquela Cidade Baixa.",
  ui_story_1014_10140901_94_dialog_content = "As atividades recentes do Eclipsite em torno de Crepúsculo estão de alguma forma ligadas a esse lugar.",
  ui_story_1014_10140901_95_dialog_content = "Eu quero dar uma olhada, mas não é conveniente levar os outros cavaleiros, e eu estaria em menor número sozinho.",
  ui_story_1014_10140901_96_dialog_content = "Já que você vai, é a oportunidade perfeita para mim.",
  ui_story_1014_10140901_97_dialog_content = "Entendi.",
  ui_story_1014_10140901_98_dialog_content = "Quanto ao reforço da Fortaleza Lumo, é outra pessoa.",
  ui_story_1014_10140901_99_dialog_content = "E aqui está ele.",
  ui_story_1014_10140901_100_dialog_content = "Não deixei todo mundo esperando, espero.",
  ui_story_1014_10140901_101_dialog_content = "O pedido veio com bastante urgência, então fiz apenas os preparativos mínimos.",
  ui_story_1014_10140901_102_dialog_content = "Você está finalmente aqui, <color=#FFB400>padre josé</color>.",
  ui_story_1014_10140901_103_dialog_content = "Lady Carleen, este é o padre Joseph da Igreja e sua escolta. Ele irá acompanhá-lo em sua jornada.",
  ui_story_1014_10140901_104_dialog_content = "Sua reputação o precede, Alteza.",
  ui_story_1014_10140901_105_dialog_content = "Já que ele está aqui, não vamos mais mantê-lo aqui.",
  ui_story_1014_10140901_106_dialog_content = "Desejo-lhe o melhor, Alteza.",
  ui_story_1014_10140901_107_dialog_content = "Só ele?",
  ui_story_1014_10140901_108_dialog_content = "Sim. Me desculpe. Não é negligência da parte da Igreja, estamos apenas com falta de pessoal.",
  ui_story_1014_10140901_109_dialog_content = "Não dê ouvidos a ele. Você tem sorte de a Igreja o ter enviado.",
  ui_story_1014_10140901_110_dialog_content = "São águas profundas para onde estamos indo. Precisamos de qualidade, não de quantidade.",
  ui_story_1014_10140901_111_dialog_content = "Vejo que suas orações finalmente foram atendidas, Leo.",
  ui_story_1014_10140901_112_dialog_content = "Sim, graças ao PlayerName. Não é todo dia que se monta uma equipe assim.",
  ui_story_1014_10140901_113_dialog_content = "E isso não é tudo. Aquela garota civil está vindo atrás de você de novo.",
  ui_story_1014_10140901_114_dialog_content = "menina civil...",
  ui_story_1014_10140901_115_dialog_content = "Gosto muito mais disso do que de Vossa Santidade.",
  ui_story_1014_10140901_116_dialog_content = "Joselyne? O que você está fazendo aqui?",
  ui_story_1014_10140901_117_dialog_content = "Posso me juntar a você, PlayerName?",
  ui_story_1014_10140901_118_dialog_content = "O que? Ah, claro, claro!",
  ui_story_1014_10140901_119_dialog_content = "Mas por quê?",
  ui_story_1014_10140901_120_dialog_content = "Eu não suportava ver visitantes de longe se aventurando direto na escuridão.",
  ui_story_1014_10140901_121_dialog_content = "Eu posso pelo menos iluminar um canto para você.",
  ui_story_1014_10140901_122_dialog_content = "<color=#e8d9bb>Clank—Clack—</color>",
  ui_story_1014_10140901_123_dialog_content = "<color=#e8d9bb>Clank—</color>",
  ui_story_1014_10140901_124_dialog_content = "Hmm, por que parou de novo?",
  ui_story_1014_10140901_125_dialog_content = "Algo ficou preso?",
  ui_story_1014_10140901_126_dialog_content = "Chega, Sean, pare de mexer no caminhão.",
  ui_story_1014_10140901_127_dialog_content = "Eu te disse, não vai funcionar. Aqui é longe o suficiente.",
  ui_story_1014_10140901_128_dialog_content = "Todos fora do veículo. Estamos fora da Cidade Baixa.",
  ui_story_1014_10140901_129_dialog_content = "Hora de levantar, Axelia.",
  ui_story_1014_10140901_130_dialog_content = "Oh, ok, eu tirei uma boa soneca.",
  ui_story_1014_10140901_131_dialog_content = "Então é isso...",
  ui_story_1014_10140901_132_dialog_content = "Sem surpresa, o Darkflow é muito intenso.",
  ui_story_1014_10140901_133_dialog_content = "A Dark Zone está logo à frente.",
  ui_story_1014_10140901_134_dialog_content = "Isso me deixa nervoso. Tenho uma impressão terrível da Zona Cega.",
  ui_story_1014_10140901_135_dialog_content = "Alguém aqui já esteve na Cidade Baixa?",
  ui_story_1014_10140901_136_dialog_content = "Alguns idosos já o fizeram, mas alertaram os outros para nunca pisarem na Zona Escura.",
  ui_story_1014_10140901_137_dialog_content = "Embora eu não ache que haja algo a temer. Quero dizer, aqueles velhos não eram exatamente à prova de balas.",
  ui_story_1014_10140901_138_dialog_content = "Então, se eles conseguissem sair de lá vivos, não teríamos problemas.",
  ui_story_1014_10140901_139_dialog_content = "Heh, eu pensei que você seria mais perspicaz do que isso.",
  ui_story_1014_10140901_140_dialog_content = "Eu nunca estive na Zona Cega antes, que insight eu poderia oferecer?",
  ui_story_1014_10140901_141_dialog_content = "Vamos confiar em Leo, ele está sempre correto em seu julgamento.",
  ui_story_1014_10140901_142_dialog_content = "Pare de me lisonjear. Eu realmente prefiro ouvir seus pensamentos sobre o assunto.",
  ui_story_1014_10140901_143_dialog_content = "Bem, olhando em volta, não acho tão assustador quanto pensei.",
  ui_story_1014_10140901_144_dialog_content = "Mesmo os Eclipsites parecem mais formidáveis.",
  ui_story_1014_10140901_145_dialog_content = "Tudo bem, se estivermos prontos, vamos para a Cidade Baixa.",
  ui_story_1014_10140901_146_dialog_content = "É hora de encontrar aquele Colosso.",
  ui_story_1014_10140901_147_dialog_content = "Oh, todo esse barulho. Que chato.",
  ui_story_1014_10140901_148_dialog_content = "Já faz algum tempo desde que foi tão rabugento.",
  ui_story_1014_10140901_149_dialog_content = "O que, oh, o que poderia ser isso? Mais intenso que gotas de chuva, mais irritante que cantos de insetos.",
  ui_story_1014_10140901_150_dialog_content = "Ah sim. Deve ser o som das pessoas.",
  ui_story_1014_10140901_151_dialog_content = "Os sons mais desprezíveis das pessoas.",
  ui_story_1014_10141101_1_dialog_content = "Estas são as ruínas com o Colosso?",
  ui_story_1014_10141101_2_dialog_content = "É o que diz no mapa.",
  ui_story_1014_10141101_3_dialog_content = "Tenha cuidado, há muitos Eclipsites aqui.",
  ui_story_1014_10141101_4_dialog_content = "...",
  ui_story_1014_10141101_5_dialog_content = "Isso é estranho. Por que há tantos Eclipsites aqui?",
  ui_story_1014_10141101_6_dialog_content = "De acordo com seu padrão de comportamento, eles não deveriam estar reunidos aqui.",
  ui_story_1014_10141101_7_dialog_content = "Mas esse ambiente é diferente e provavelmente tem características que ainda não conhecemos.",
  ui_story_1014_10141101_8_dialog_content = "Não tenho certeza do que está atraindo os Eclipsites aqui, a menos que algo os esteja controlando.",
  ui_story_1014_10141101_9_dialog_content = "Isso é altamente incomum, então tome cuidado.",
  ui_story_1014_10141101_10_dialog_content = "Eclipsites não são algo a temer. Sua derrota é o único resultado.",
  ui_story_1014_10141101_11_dialog_content = "Você é realmente tão poderoso?",
  ui_story_1014_10141101_12_dialog_content = "Não a subestime. Ela é a mais forte entre nós! Nem eu consigo vencê-la às vezes.",
  ui_story_1014_10141101_13_dialog_content = "Pelas minhas observações das lutas de Sean e Axelia, ele perdeu nove em dez vezes e empatou com ela apenas uma vez.",
  ui_story_1014_10141101_14_dialog_content = "Não preciso fazer muito esforço ao lutar contra Sean.",
  ui_story_1014_10141101_15_dialog_content = "Ei, não seja tão direto sobre isso!",
  ui_story_1014_10141101_16_dialog_content = "Haha, com certeza vocês se dão bem.",
  ui_story_1014_10141101_17_dialog_content = "Mas não é seguro aqui, então não vamos brincar.",
  ui_story_1014_10141101_18_dialog_content = "Precisamos encontrar o módulo que PlayerName precisa o mais rápido possível e sair daqui.",
  ui_story_1014_10141101_19_dialog_content = "Eu vejo um monte de Eclipsites no caminho, então que tal isso?",
  ui_story_1014_10141101_20_dialog_content = "Axelia, vamos ver quem mata mais deles!",
  ui_story_1014_10141101_21_dialog_content = "Yingel pode ser o árbitro.",
  ui_story_1014_10141101_22_dialog_content = "Lá vai você de novo.",
  ui_story_1014_10141101_23_dialog_content = "Multar. Mas não reclame se você perder.",
  ui_story_1014_10141101_24_dialog_content = "<color=#e8d9bb>Em algum lugar fora das Ruínas Aurora</color>",
  ui_story_1014_10141101_25_dialog_content = "(Eclipsiano) Senhor <color=#FFB400>Asmodeus</color>, os aurorianos e os celestitas entraram nas ruínas.",
  ui_story_1014_10141101_26_dialog_content = "(Eclipsiano) Eles engajaram nossos parentes internos.",
  ui_story_1014_10141101_27_dialog_content = "(Eclipsiano) Deixe-os marchar adiante.",
  ui_story_1014_10141101_28_dialog_content = "(Eclipsiano) Talvez o desejo deles me leve ao que tenho procurado.",
  ui_story_1014_10141102_1_dialog_content = "O último Eclipsite - é meu!",
  ui_story_1014_10141102_2_dialog_content = "Gaaaa!!",
  ui_story_1014_10141102_3_dialog_content = "Então, quem ganhou, Yingel?",
  ui_story_1014_10141102_4_dialog_content = "Ok, anunciarei os resultados.",
  ui_story_1014_10141102_5_dialog_content = "Sean matou 20 eclipsitas.",
  ui_story_1014_10141102_6_dialog_content = "Oh, ainda um pouco aquém do meu melhor de todos os tempos.",
  ui_story_1014_10141102_7_dialog_content = "Axelia matou—",
  ui_story_1014_10141102_8_dialog_content = "32!",
  ui_story_1014_10141102_9_dialog_content = "Seriamente?!",
  ui_story_1014_10141102_10_dialog_content = "Im-impossível!",
  ui_story_1014_10141102_11_dialog_content = "Você passou muito tempo perseguindo os retardatários em fuga, Sean.",
  ui_story_1014_10141102_12_dialog_content = "Axelia concentrou sua energia nas multidões lideradas pelos maiores Eclipsites.",
  ui_story_1014_10141102_13_dialog_content = "Bem, não há nada que eu possa fazer sobre isso...",
  ui_story_1014_10141102_14_dialog_content = "Onde minha habilidade está agora, tenho que reduzir os Eclipsites mais fracos primeiro e trabalhar até os maiores.",
  ui_story_1014_10141102_15_dialog_content = "Certo, e essa é a razão pela qual Axelia venceu.",
  ui_story_1014_10141102_16_dialog_content = "Ratos, Axelia venceu de novo!",
  ui_story_1014_10141102_17_dialog_content = "Sean perdeu novamente.",
  ui_story_1014_10141102_18_dialog_content = "Mas Sean não vai desistir. Sean gosta de enfrentar desafios e não desiste mesmo que falhe.",
  ui_story_1014_10141102_19_dialog_content = "Até que ele vença.",
  ui_story_1014_10141102_20_dialog_content = "Eu sabia que você me conhecia melhor, Axelia.",
  ui_story_1014_10141102_21_dialog_content = "No entanto, não é possível para Sean me derrotar.",
  ui_story_1014_10141102_22_dialog_content = "Não tenha tanta certeza. Vou continuar melhorando!",
  ui_story_1014_10141102_23_dialog_content = "O que você acha do desempenho deles, Joseph?",
  ui_story_1014_10141102_24_dialog_content = "Você está pedindo minha opinião?",
  ui_story_1014_10141102_25_dialog_content = "É claro. Você os observou em silêncio todo esse tempo, então deveria ter alguns.",
  ui_story_1014_10141102_26_dialog_content = "(Joseph mal falava porque estava nos observando?)",
  ui_story_1014_10141102_27_dialog_content = "Acho que todos na Illumina são notáveis por si só.",
  ui_story_1014_10141102_28_dialog_content = "Axelia é muito competente com máquinas. Yingel é adepto da observação e apoio. Sean é bom em adaptar experiência em habilidades.",
  ui_story_1014_10141102_29_dialog_content = "Vocês três juntos formam uma equipe perfeita.",
  ui_story_1014_10141102_30_dialog_content = "...!",
  ui_story_1014_10141102_31_dialog_content = "Concordo com sua avaliação.",
  ui_story_1014_10141102_32_dialog_content = "Obrigado pelo reconhecimento.",
  ui_story_1014_10141102_33_dialog_content = "(Joseph tem uma visão muito aguçada!)",
  ui_story_1014_10141102_34_dialog_content = "Axelia é realmente impressionante.",
  ui_story_1014_10141102_35_dialog_content = "Ela provavelmente ficaria em primeiro lugar nas classificações individuais se participasse dos exercícios militares conjuntos!",
  ui_story_1014_10141102_36_dialog_content = "Você conhece os exercícios militares conjuntos?",
  ui_story_1014_10141102_37_dialog_content = "Sim, Reinhardt me falou sobre eles antes.",
  ui_story_1014_10141102_38_dialog_content = "Ela ainda disse que estava ansiosa para treinar com o campeão.",
  ui_story_1014_10141102_39_dialog_content = "Parece algo que ela faria.",
  ui_story_1014_10141102_40_dialog_content = "Também estou ansioso para vê-la lutando contra alguém como Axelia no evento.",
  ui_story_1014_10141102_41_dialog_content = "Claro, se uma oportunidade se apresentasse, eu adoraria treinar com Lady Carleen, a ex-campeã.",
  ui_story_1014_10141102_42_dialog_content = "Que insolente!",
  ui_story_1014_10141102_43_dialog_content = "Está tudo bem.",
  ui_story_1014_10141102_44_dialog_content = "Estarei participando do próximo evento.",
  ui_story_1014_10141102_45_dialog_content = "Estou ansioso para lutar com você, Leo.",
  ui_story_1014_10141102_46_dialog_content = "É um acordo.",
  ui_story_1014_10141102_47_dialog_content = "Tá se inscrevendo no evento também, Léo?",
  ui_story_1014_10141102_48_dialog_content = "Sim.",
  ui_story_1014_10141102_49_dialog_content = "Todos os aurorianos são elegíveis para isso.",
  ui_story_1014_10141102_50_dialog_content = "Vou apenas para me testar contra os melhores de todo o Astra, por mais longe que seja.",
  ui_story_1014_10141102_X50_dialog_content = "<color=#e8d9bb>Profundamente nas Ruínas Aurora</color>",
  ui_story_1014_10141102_51_dialog_content = "(Já chegamos até aqui. Parece que esta viagem terminará em breve.)",
  ui_story_1014_10141102_52_dialog_content = "(Mas ainda não há sinal de Forsakin... Minha suposição pode estar errada?)",
  ui_story_1014_10141102_53_dialog_content = "(Não, seu objetivo sempre foi claro, e PlayerName é a melhor isca.)",
  ui_story_1014_10141102_54_dialog_content = "(Não posso estar errado. Tudo o que posso fazer agora é esperar.)",
  ui_story_1014_10141102_55_dialog_content = "Yingel, por que você parou? Você está ferido?",
  ui_story_1014_10141102_56_dialog_content = "Huh...? Não, estou bem, apenas me perguntando por que existem tantos Eclipsites.",
  ui_story_1014_10141102_57_dialog_content = "Permita-me interpor...",
  ui_story_1014_10141102_58_dialog_content = "O objetivo desta missão é ajudar PlayerName a encontrar um componente Colossus.",
  ui_story_1014_10141102_59_dialog_content = "Pelo que sei, não devemos estar longe do antigo Colosso.",
  ui_story_1014_10141102_60_dialog_content = "Vamos seguir em frente, certo?",
  ui_story_1014_10141102_61_dialog_content = "Sim, a senhorita Joselyne está certa.",
  ui_story_1014_10141102_62_dialog_content = "Este lugar está me dando calafrios como se alguém estivesse nos observando...",
  ui_story_1014_10141102_63_dialog_content = "Devemos conseguir o papel que precisamos e voltar para Crepúsculo!",
  ui_story_1014_10141102_64_dialog_content = "<color=#e8d9bb>Em algum lugar fora das Ruínas Aurora</color>",
  ui_story_1014_10141102_65_dialog_content = "(Eclipsiano) O cheiro do desejo deles está se aproximando do Colosso.",
  ui_story_1014_10141102_66_dialog_content = "(Eclipsiano) Esse objeto poderia estar dentro do Colosso?",
  ui_story_1014_10141102_67_dialog_content = "(Eclipsian) Devemos entrar agora, Lord Asmodeus?",
  ui_story_1014_10141102_68_dialog_content = "(Eclipsiano) Deixe o desejo deles chegar mais perto, mais perto...",
  ui_story_1014_10141102_69_dialog_content = "(Eclipsiano) O desejo daquele traidor celestita será o sinal que guia.",
  ui_story_1014_10141102_70_dialog_content = "(Eclipsiano) Só precisamos esperar.",
  ui_story_1014_10141201_1_dialog_content = "O Colosso está logo à frente. Mantenha seus olhos abertos.",
  ui_story_1014_10141201_2_dialog_content = "Mal posso esperar por um Colosso dos tempos antigos...",
  ui_story_1014_10141201_3_dialog_content = "<size=45>É tão grande!</size>",
  ui_story_1014_10141201_4_dialog_content = "O tamanho supera completamente minhas expectativas!",
  ui_story_1014_10141201_5_dialog_content = "Seu tamanho está entre os maiores de todos os colossos descobertos.",
  ui_story_1014_10141201_6_dialog_content = "As tropas da Federação Illumina estacionadas em Crepúsculo estudaram este Colosso e obtiveram muitos dados valiosos.",
  ui_story_1014_10141201_7_dialog_content = "Que tipo de dados?",
  ui_story_1014_10141201_8_dialog_content = "Informações sobre como certos dispositivos foram feitos, como um projeto parcial de seu sistema médico.",
  ui_story_1014_10141201_9_dialog_content = "Alguma outra descoberta, como dados de memória ou antigas mensagens celestitas?",
  ui_story_1014_10141201_10_dialog_content = "Receio não poder responder, já que é informação classificada.",
  ui_story_1014_10141201_11_dialog_content = "No entanto, devido a um acidente operacional, o Colossus entrou em <color=#FFB400>alvoroço</color> uma vez.",
  ui_story_1014_10141201_12_dialog_content = "O incidente tornou muitas áreas internas do Colossus inacessíveis.",
  ui_story_1014_10141201_13_dialog_content = "Depois disso, foi designado como um objeto de alto risco e baixo valor, assim como as Ruínas Aurora em que se encontra.",
  ui_story_1014_10141201_14_dialog_content = "O oficial Ulysses provavelmente autorizou esta expedição apenas porque você está nela.",
  ui_story_1014_10141201_15_dialog_content = "Porque sou um celestita?",
  ui_story_1014_10141201_16_dialog_content = "Correto.",
  ui_story_1014_10141201_17_dialog_content = "Os celestitas podem pilotar os Colossos, para que possamos descobrir coisas inimagináveis.",
  ui_story_1014_10141201_18_dialog_content = "... Vamos continuar.",
  ui_story_1014_10141201_19_dialog_content = "Devemos entrar?",
  ui_story_1014_10141201_20_dialog_content = "Assista, PlayerName.",
  ui_story_1014_10141201_21_dialog_content = "Vejo vestígios de atividade Eclipsita.",
  ui_story_1014_10141201_22_dialog_content = "Existem muitos Eclipsites dentro deste Colossus.",
  ui_story_1014_10141201_23_dialog_content = "Não importa quantos sejam, devo obter os dados.",
  ui_story_1014_10141201_24_dialog_content = "Pelo amor de Soroz.",
  ui_story_1014_10141201_25_dialog_content = "É muito espaçoso aqui.",
  ui_story_1014_10141201_26_dialog_content = "Além dos Eclipsites, não há vestígios de mais nada.",
  ui_story_1014_10141201_27_dialog_content = "O seu Colossus tem quartos espaçosos como este, PlayerName?",
  ui_story_1014_10141201_28_option_content = "Sim.",
  ui_story_1014_10141201_29_dialog_content = "A cabine de Soroz é muito grande, você pode até correr nela sem problemas.",
  ui_story_1014_10141201_30_dialog_content = "Impressionante!",
  ui_story_1014_10141201_31_option_content = "Não.",
  ui_story_1014_10141201_32_dialog_content = "Os quartos e corredores do Soroz são espaçosos, mas geralmente há muitas pessoas a bordo.",
  ui_story_1014_10141201_33_dialog_content = "Então isso faz com que pareça menos espaçoso do que é.",
  ui_story_1014_10141201_34_dialog_content = "Faz sentido!",
  ui_story_1014_10141201_35_dialog_content = "Há uma porta à frente.",
  ui_story_1014_10141201_36_dialog_content = "Assemelha-se às portas que levam aos quartos da Soroz.",
  ui_story_1014_10141201_37_dialog_content = "Esta porta deve levar à ponte.",
  ui_story_1014_10141201_38_dialog_content = "Parece lacrado, sem maçaneta ou fechadura...",
  ui_story_1014_10141201_39_dialog_content = "Como vamos abri-lo?",
  ui_story_1014_10141201_40_dialog_content = "Todas as portas de Soroz se abrem telepaticamente.",
  ui_story_1014_10141201_41_dialog_content = "Deixe-me tentar isso com este.",
  ui_story_1014_10141201_42_option_content = "Aumento de Força!",
  ui_story_1014_10141201_43_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_1014_10141201_44_dialog_content = "<color=#e8d9bb>Foi detectado um visitante celestita não registrado.</color>",
  ui_story_1014_10141201_45_dialog_content = "Este é o sistema principal deste Colossus? Parece tão rígido.",
  ui_story_1014_10141201_46_dialog_content = "Como Soroz sem sua personalidade...",
  ui_story_1014_10141201_47_dialog_content = "<color=#e8d9bb>Por favor, registre-se.</color>",
  ui_story_1014_10141201_48_dialog_content = "Meu nome é PlayerName, sou celestita.",
  ui_story_1014_10141201_49_dialog_content = "<color=#e8d9bb>Usuário não registrado alterado para PlayerName.</color>",
  ui_story_1014_10141201_50_dialog_content = "<color=#e8d9bb>Você recebeu acesso total ao Naviduz.</color>",
  ui_story_1014_10141201_51_dialog_content = "<color=#FFB400>Naviduz</color>...? Aquele era um dos Colossos dos tempos antigos!",
  ui_story_1014_10141201_52_dialog_content = "Acesso total, mesmo?! Essa foi fácil!",
  ui_story_1014_10141201_53_dialog_content = "<color=#e8d9bb>Os protocolos de acesso da Naviduz obedecem às permissões definidas por todos os seus pilotos.</color>",
  ui_story_1014_10141201_54_dialog_content = "<color=#e8d9bb>\"Menos de 100 anos, apenas o administrador terá acesso total.\"</color>",
  ui_story_1014_10141201_55_dialog_content = "<color=#e8d9bb>\"Mais de 100 anos, mas menos... anos, acesso total... todos os celestitas.\"</color>",
  ui_story_1014_10141201_56_dialog_content = "<color=#e8d9bb>\"Mais... anos, mas menos... anos, acesso total... todas as entidades vivas.\"</color>",
  ui_story_1014_10141201_57_dialog_content = "<color=#e8d9bb>De acordo com o protocolo, Naviduz está atualmente concedendo acesso total a todos os Caelestitas.</color>",
  ui_story_1014_10141201_58_dialog_content = "Há quanto tempo você está esperando? ... Eu sinto Muito.",
  ui_story_1014_10141201_59_dialog_content = "<color=#e8d9bb>A personalidade de Naviduz foi suspensa, incapaz de compreender o significado de \"Sinto muito.\"</color>",
  ui_story_1014_10141201_60_dialog_content = "<color=#e8d9bb>Tudo em Naviduz é um presente para os futuros celestitas.</color>",
  ui_story_1014_10141201_61_dialog_content = "Sua personalidade foi suspensa? Por quê?",
  ui_story_1014_10141201_62_dialog_content = "<color=#e8d9bb>Personalidade custa poder adicional para manter.</color>",
  ui_story_1014_10141201_63_dialog_content = "<color=#e8d9bb>Para garantir que Naviduz seja capaz de preservar e passar todos os dados para os celestitas que podem localizar o Colosso...</color>",
  ui_story_1014_10141201_64_dialog_content = "<color=#e8d9bb>A Naviduz optou por suspender a personalidade e iniciar o modo de conservação.</color>",
  ui_story_1014_10141201_65_dialog_content = "Seus sistemas e dados de personalidade ainda funcionam?",
  ui_story_1014_10141201_66_dialog_content = "<color=#e8d9bb>Executando autodiagnóstico.</color>",
  ui_story_1014_10141201_67_dialog_content = "<color=#e8d9bb>\"Sistema de controle primário, funcionando. Integridade do componente abaixo de 72%. Manutenção necessária.\"</color>",
  ui_story_1014_10141201_68_dialog_content = "<color=#e8d9bb>Módulos biológicos offline.</color>",
  ui_story_1014_10141201_69_dialog_content = "<color=#e8d9bb>Suporte de vida offline.</color>",
  ui_story_1014_10141201_70_dialog_content = "<color=#e8d9bb>Os dados de personalidade se deterioraram 32%, incapazes de operar no nível normal.</color>",
  ui_story_1014_10141201_71_dialog_content = "Deteriorou-se a ponto de não funcionar?",
  ui_story_1014_10141201_72_dialog_content = "Então você também, Naviduz...",
  ui_story_1014_10141201_73_dialog_content = "Independentemente disso, obrigado por aguentar por tanto tempo.",
  ui_story_1014_10141201_74_dialog_content = "Por favor, abra a porta para a ponte.",
  ui_story_1014_10141201_75_dialog_content = "<color=#e8d9bb>Comando aceito.</color>",
  ui_story_1014_10141201_76_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_1014_10141201_77_dialog_content = "A porta está aberta.",
  ui_story_1014_10141201_78_dialog_content = "Vejo uma ponte danificada e um console de controle.",
  ui_story_1014_10141201_79_dialog_content = "<anim type=Shake><size=45>Gahhhhhhhh!</size></anim>",
  ui_story_1014_10141201_80_dialog_content = "Cuidado, aqui vêm os Eclipsites errantes!",
  ui_story_1014_10141201_81_dialog_content = "Prepare-se para lutar!",
  ui_story_1014_10141302_1_dialog_content = "Todos os Eclipsites limpos.",
  ui_story_1014_10141302_2_dialog_content = "Feche a porta, PlayerName, para que não peguemos mais nenhum de seus companheiros.",
  ui_story_1014_10141302_3_dialog_content = "Vou contar a Naviduz.",
  ui_story_1014_10141302_4_dialog_content = "...",
  ui_story_1014_10141302_5_dialog_content = "Tudo bem, Axélia?",
  ui_story_1014_10141302_6_dialog_content = "Você lutou por muito tempo. Precisas de descansar.",
  ui_story_1014_10141302_7_dialog_content = "Estou bem.",
  ui_story_1014_10141302_8_dialog_content = "As consequências da batalha ainda estão dentro de uma faixa aceitável.",
  ui_story_1014_10141302_9_dialog_content = "OK. Mas se você sentir algo errado, diga-me imediatamente.",
  ui_story_1014_10141302_10_dialog_content = "Pode deixar.",
  ui_story_1014_10141302_11_dialog_content = "(Quase esqueci que o poder de Axelia deriva da bioengenharia Illumina.)",
  ui_story_1014_10141302_12_dialog_content = "(Ela geralmente não mostra emoções, mas por um segundo, ela parecia estar em agonia.)",
  ui_story_1014_10141302_13_dialog_content = "(Ela provavelmente suporta muito mais dor do que mostra...)",
  ui_story_1014_10141302_14_dialog_content = "Você é livre para concluir seu trabalho, PlayerName.",
  ui_story_1014_10141302_15_dialog_content = "Certo... obrigado.",
  ui_story_1014_10141302_16_dialog_content = "Estaremos dando uma olhada ao redor, então fique alerta.",
  ui_story_1014_10141302_17_dialog_content = "Eu ajudo PlayerName confira o Colosso.",
  ui_story_1014_10141302_18_dialog_content = "Naviduz, gostaria de obter seus dados de personalidade, então preciso do módulo de Controle Primário.",
  ui_story_1014_10141302_19_dialog_content = "<color=#e8d9bb>Comando aceito. Verificando o status do módulo de controle primário.</color>",
  ui_story_1014_10141302_20_dialog_content = "<color=#e8d9bb>Aviso: o módulo de controle primário sofreu danos graves. A remoção forçada causará danos irreversíveis.</color>",
  ui_story_1014_10141302_21_dialog_content = "Não podemos removê-lo?",
  ui_story_1014_10141302_22_dialog_content = "O-O que vamos fazer agora?",
  ui_story_1014_10141302_23_dialog_content = "Você parece preocupado. Eu tenho uma sugestão.",
  ui_story_1014_10141302_24_dialog_content = "Meu traje de batalha tem um dispositivo de duplicação de dados. Você pode conectá-lo ao Colossus.",
  ui_story_1014_10141302_25_dialog_content = "Podemos não obter todo o módulo, mas ainda podemos adquirir os dados de personalidade necessários.",
  ui_story_1014_10141302_26_dialog_content = "Para Algol, os dados e o módulo são um e o mesmo.",
  ui_story_1014_10141302_27_dialog_content = "Acho que é a única opção que temos.",
  ui_story_1014_10141302_28_dialog_content = "PlayerName deve conectar o dispositivo ao módulo de controle do Colossus.",
  ui_story_1014_10141302_29_dialog_content = "Pressione este botão para começar a duplicar os dados.",
  ui_story_1014_10141302_30_dialog_content = "Entendido.",
  ui_story_1014_10141302_31_dialog_content = "<color=#e8d9bb>Duplicando dados. Aguarde.</color>",
  ui_story_1014_10141302_32_dialog_content = "Parece que temos mais coisas esperando para fazer.",
  ui_story_1014_10141302_33_dialog_content = "Estamos cercados por antigas relíquias tecnológicas...",
  ui_story_1014_10141302_34_dialog_content = "Noite Branca lá no alto, espero que não ameacem nossa existência.",
  ui_story_1014_10141302_35_dialog_content = "<color=#e8d9bb>Bip, bip, bip...</color>",
  ui_story_1014_10141302_36_dialog_content = "Esta é a sede dos Ironthorn Knights em Crepúsculo. Por favor, responda se estiver disponível, Sir Leo.",
  ui_story_1014_10141302_37_dialog_content = "Este é o Cavaleiro da Expedição Leo. Vá em frente.",
  ui_story_1014_10141302_38_dialog_content = "Por favor, transmita sua localização e progresso.",
  ui_story_1014_10141302_39_dialog_content = "No momento, estamos cumprindo a missão de proteger o Caelestite PlayerName no Colossus nas Ruínas de Aurora.",
  ui_story_1014_10141302_40_dialog_content = "Lady Carleen e vários aurorianos de Illumina estão conosco.",
  ui_story_1014_10141302_41_dialog_content = "Lady Carleen... Copie isso.",
  ui_story_1014_10141302_42_dialog_content = "Continue a missão. Se você tiver problemas, solicite reforços diretamente dos Ironthorn Knights.",
  ui_story_1014_10141302_43_dialog_content = "Sim.",
  ui_story_1014_10141302_44_dialog_content = "Boa sorte. Sobre.",
  ui_story_1014_10141302_45_dialog_content = "Solicitando reforços dos Ironthorn Knights?",
  ui_story_1014_10141302_46_dialog_content = "Comparados aos cavaleiros da expedição que passam anos fora, os cavaleiros de Crepúsculo devem ser superiores em número e armas.",
  ui_story_1014_10141302_47_dialog_content = "Por que você não solicita backup deles?",
  ui_story_1014_10141302_48_dialog_content = "Lady Carleen, como você pode ver, há certos problemas entre o Ironthorn e os cavaleiros locais.",
  ui_story_1014_10141302_49_dialog_content = "A maioria dos Cavaleiros da Expedição tem antecedentes civis ou são nobres exilados. Seu status é muito diferente dos cavaleiros regulares.",
  ui_story_1014_10141302_50_dialog_content = "Mesmo quando solicitamos suporte, muitas vezes eles não nos levam a sério.",
  ui_story_1014_10141302_51_dialog_content = "Então, como Expedition Knights, estamos acostumados a confiar em nós mesmos.",
  ui_story_1014_10141302_52_dialog_content = "Não acredito...",
  ui_story_1014_10141302_53_dialog_content = "Vou relatar isso aos superiores de Lumopolis.",
  ui_story_1014_10141302_54_dialog_content = "Todos os cidadãos de Lumopolis devem ser tratados da mesma forma, independentemente de sua posição social.",
  ui_story_1014_10141302_55_dialog_content = "Eu aprecio sua mente aberta, embora eu não ache que algo significativo venha disso.",
  ui_story_1014_10141302_56_dialog_content = "Preconceito e conflito persistirão enquanto houver uma lacuna entre nobres e civis.",
  ui_story_1014_10141302_57_dialog_content = "Ninguém entende isso melhor do que um nobre banido como eu.",
  ui_story_1014_10141302_58_dialog_content = "... Eu conheci nobres exilados no passado.",
  ui_story_1014_10141302_59_dialog_content = "Todos eles expressariam desprezo por sua situação, de uma forma ou de outra.",
  ui_story_1014_10141302_60_dialog_content = "Você também se sente assim, Léo?",
  ui_story_1014_10141302_61_dialog_content = "Você está pedindo minha opinião?",
  ui_story_1014_10141302_62_dialog_content = "Sim, estou.",
  ui_story_1014_10141302_63_dialog_content = "Eu era um nobre rico em Lumópolis.",
  ui_story_1014_10141302_64_dialog_content = "Naquela época, eu considerava lutar e defender Lumopolis como a maior honra para mim como cavaleiro.",
  ui_story_1014_10141302_65_dialog_content = "Depois que fui exilado, tornei-me nada mais do que um simples plebeu em Crepúsculo.",
  ui_story_1014_10141302_66_dialog_content = "Eu não poderia nem trocar minha antiga glória ou jurar defender Lumopolis com minha vida por uma fatia de pão.",
  ui_story_1014_10141302_67_dialog_content = "Então você se sente abandonado e desrespeitado?",
  ui_story_1014_10141302_68_dialog_content = "Eu não nego isso.",
  ui_story_1014_10141302_69_dialog_content = "Mas ser banido para Crepúsculo foi exatamente quando percebi que só posso confiar em mim mesmo.",
  ui_story_1014_10141302_70_dialog_content = "Depois de passar no teste para se tornar um Cavaleiro da Expedição e viver em Crepúsculo por um tempo, minha atitude mudou.",
  ui_story_1014_10141302_71_dialog_content = "Não acho que seja tão ruim quanto imaginei.",
  ui_story_1014_10141302_72_dialog_content = "Pelo menos em Crepúsculo, aurorianos de diferentes facções podem deixar suas rivalidades de lado e conviver uns com os outros.",
  ui_story_1014_10141302_73_dialog_content = "Eu gosto muito de lutar contra os Eclipsites com os outros, mas... ainda sinto injustiça.",
  ui_story_1014_10141302_74_dialog_content = "Por favor elabore.",
  ui_story_1014_10141302_75_dialog_content = "O que minha resposta pode lhe dar?",
  ui_story_1014_10141302_76_dialog_content = "Quero ouvir as pessoas para poder melhorar as leis e políticas de Lumopolis.",
  ui_story_1014_10141302_77_dialog_content = "Quero que todos em Lumopolis tenham a igualdade que todos merecem.",
  ui_story_1014_10141302_78_dialog_content = "Bom...",
  ui_story_1014_10141302_79_dialog_content = "<color=#e8d9bb>Bip!</color>",
  ui_story_1014_10141302_80_dialog_content = "<color=#e8d9bb>Duplicação dos dados do Colossus concluída. É seguro desconectar.</color>",
  ui_story_1014_10141302_81_dialog_content = "Acho que acabou!",
  ui_story_1014_10141302_82_dialog_content = "Vamos voltar agora!",
  ui_story_1014_10141302_83_dialog_content = "Você não precisa me dizer duas vezes!",
  ui_story_1014_10141302_84_dialog_content = "(Graças a Deus pelo dispositivo de Algol...)",
  ui_story_1014_10141302_85_dialog_content = "(Se Carleen e Leo continuassem conversando, eles poderiam acabar brigando!)",
  ui_story_1014_10141302_86_dialog_content = "<color=#e8d9bb>Estrondo...</color>",
  ui_story_1014_10141302_87_dialog_content = "*Tosse* O que está acontecendo?",
  ui_story_1014_10141302_88_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_1014_10141302_89_dialog_content = "O Colosso está tremendo, PlayerName!",
  ui_story_1014_10141302_90_dialog_content = "Não me diga que está prestes a explodir de novo!",
  ui_story_1014_10141302_91_dialog_content = "Rampage?!",
  ui_story_1014_10141302_92_dialog_content = "Pegue o dispositivo e saia daqui, PlayerName!",
  ui_story_1014_10141302_93_dialog_content = "As vibrações são muito intensas... O Colosso pode desmoronar e entrar em colapso!",
  ui_story_1014_10141302_94_dialog_content = "Não podemos ficar aqui!",
  ui_story_1014_10141302_95_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_1014_10141302_96_dialog_content = "Essa não!",
  ui_story_1014_10141302_97_dialog_content = "Estamos muito perto de Crepúsculo, um tumulto provavelmente acabaria com a cidade!",
  ui_story_1014_10141302_98_dialog_content = "Há tantos civis lá!",
  ui_story_1014_10141302_99_dialog_content = "Temos que parar com isso de alguma forma!",
  ui_story_1014_10141302_100_dialog_content = "Mas...",
  ui_story_1014_10141302_101_option_content = "Deixe para mim!",
  ui_story_1014_10141302_102_dialog_content = "Esta é a tecnologia Celestita.",
  ui_story_1014_10141302_103_dialog_content = "Provavelmente é preciso um celestita para pará-lo.",
  ui_story_1014_10141302_104_dialog_content = "Vice, Carleen, preciso da sua ajuda!",
  ui_story_1014_10141302_105_dialog_content = "Sem problemas!",
  ui_story_1014_10141302_106_dialog_content = "Pode deixar.",
  ui_story_1014_10141302_107_dialog_content = "Obrigado. Eu vou começar.",
  ui_story_1014_10141302_108_dialog_content = "Aumento de Força!",
  ui_story_1014_10141401_1_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_1014_10141401_2_dialog_content = "Naviduz!",
  ui_story_1014_10141401_3_dialog_content = "<color=#e8d9bb>Naviduz aguardando ordens.</color>",
  ui_story_1014_10141401_4_dialog_content = "O que quer que você esteja tentando fazer, pare!",
  ui_story_1014_10141401_5_dialog_content = "Não faça barulho! Isso colocará em risco muitas vidas inocentes!",
  ui_story_1014_10141401_6_dialog_content = "<color=#e8d9bb>Procurando por registros relevantes para o Rampage.</color>",
  ui_story_1014_10141401_7_dialog_content = "<color=#e8d9bb>Naviduz nunca se enfureceu.</color>",
  ui_story_1014_10141401_8_dialog_content = "Nunca? E o incidente que Yingel mencionou...?",
  ui_story_1014_10141401_9_dialog_content = "<color=#e8d9bb>Pesquisando informações sobre a última iniciação.</color>",
  ui_story_1014_10141401_10_dialog_content = "<color=#e8d9bb>Naviduz ativou o modo de defesa devido à operação errônea das formas de vida Lumo.</color>",
  ui_story_1014_10141401_11_dialog_content = "<color=#e8d9bb>Para proteger os dados, a Naviduz tomou as medidas de evasão necessárias.</color>",
  ui_story_1014_10141401_12_dialog_content = "<color=#e8d9bb>Durante isso, Naviduz não prejudicou nenhuma forma de vida.</color>",
  ui_story_1014_10141401_13_dialog_content = "Então aquele tremor, você não estava furioso?",
  ui_story_1014_10141401_14_dialog_content = "<color=#e8d9bb>O sistema de propulsão de Naviduz está severamente danificado e inoperável.</color>",
  ui_story_1014_10141401_15_dialog_content = "<color=#e8d9bb>Os resultados da análise indicam que o estrondo vem de fora. Projetando gravação externa agora.</color>",
  ui_story_1014_10141401_16_dialog_content = "(Eclipsiano) Esta é uma prisão, um recipiente para o desejo.",
  ui_story_1014_10141401_17_dialog_content = "(Eclipsiano) Os desejos criaram o mundo e acabarão por destruí-lo.",
  ui_story_1014_10141401_18_dialog_content = "(Eclipsiano) Assim, os desejos devem ser purificados antes de correrem desenfreados.",
  ui_story_1014_10141401_19_dialog_content = "Como é que existem tantos Eclipsites?!",
  ui_story_1014_10141401_20_dialog_content = "Aquele no meio é o líder deles?",
  ui_story_1014_10141401_21_dialog_content = "(Eclipsiano) Os aurorianos ainda não saíram, Lorde Asmodeus.",
  ui_story_1014_10141401_22_dialog_content = "(Eclipsiano) O desejo deles os levará até nós.",
  ui_story_1014_10141401_23_dialog_content = "(Eclipsiano) Porque eles...",
  ui_story_1014_10141401_24_dialog_content = "(Eclipsian) já nos viu.",
  ui_story_1014_10141401_25_dialog_content = "!!!",
  ui_story_1014_10141401_26_dialog_content = "Você tá bem, PlayerName?",
  ui_story_1014_10141401_27_dialog_content = "Por que você parece tão pálido?",
  ui_story_1014_10141401_28_dialog_content = "O Colosso não estava causando as vibrações. Eram os Eclipsites lá fora!",
  ui_story_1014_10141401_29_dialog_content = "Acabei de avistar um Eclipsite muito poderoso através da câmera externa.",
  ui_story_1014_10141401_30_dialog_content = "E ela aparentemente podia me ver através disso também.",
  ui_story_1014_10141401_31_dialog_content = "Como isso é possível? Ela poderia ser tão poderosa quanto Forsakin?",
  ui_story_1014_10141401_32_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_1014_10141401_33_dialog_content = "<color=#e8d9bb>Atenção, formas de vida não autorizadas estão entrando no Colossus.</color>",
  ui_story_1014_10141401_34_dialog_content = "Atenção. Poderosos Eclipsites estão vindo por aqui!",
  ui_story_1014_10141401_35_dialog_content = "Infelizmente, tanto barulho. Mas não apenas isso. Há o cheiro persistente do desejo.",
  ui_story_1014_10141401_36_dialog_content = "Desejo de poder.",
  ui_story_1014_10141401_37_dialog_content = "Desejo de reconhecimento.",
  ui_story_1014_10141401_38_dialog_content = "E... Hmm, isso é...",
  ui_story_1014_10141401_39_dialog_content = "Desejo de salvar os companheiros.",
  ui_story_1014_10141401_40_dialog_content = "Quem é você? O que quer?",
  ui_story_1014_10141401_41_dialog_content = "Eu? Por que, você me deseja também?",
  ui_story_1014_10141401_42_dialog_content = "Eu sou Asmodeus, nascido do desejo e destinado a expurgar todo desejo deste mundo.",
  ui_story_1014_10141401_43_dialog_content = "Permita-me purgar seus desejos!",
  ui_story_1014_10141401_44_dialog_content = "que é que você deseja tanto, você o guardaria com sua vida? Vou destruí-lo e ver.",
  ui_story_1014_10141401_45_dialog_content = "Nos seus sonhos!",
  ui_story_1014_10141401_46_dialog_content = "Carleen!",
  ui_story_1014_10141401_47_dialog_content = "Ela é difícil. Vamos levá-la juntos, todos!",
  ui_story_1014_10141401_48_dialog_content = "Fique longe de Lady Carleen, Eclipsite!",
  ui_story_1014_10141401_49_dialog_content = "Desejos... desejos lamentáveis e inconsequentes...",
  ui_story_1014_10141401_50_dialog_content = "Você não terá sucesso apenas com isso.",
  ui_story_1014_10141401_51_dialog_content = "Às vezes, desejar mais do que deveria não é uma coisa boa, Eclipsite... Não, você provavelmente é um <color=#FFB400>Wraith</color>, certo?",
  ui_story_1014_10141401_52_dialog_content = "Correto, os desejos são ruins, então devo erradicá-los.",
  ui_story_1014_10141401_53_dialog_content = "Mas é uma tarefa impossível, pois enquanto houver aurorianos, os desejos não terão fim.",
  ui_story_1014_10141401_54_dialog_content = "Portanto, recorro primeiro a erradicar os aurorianos com desejos.",
  ui_story_1014_10141401_55_dialog_content = "Também erradicarei o traidor celestita.",
  ui_story_1014_10141401_56_dialog_content = "eu não vou permitir PlayerName ser prejudicado.",
  ui_story_1014_10141401_57_dialog_content = "Oh? É isso que você deseja?",
  ui_story_1014_10141401_58_dialog_content = "protegendo PlayerName é meu dever.",
  ui_story_1014_10141401_59_dialog_content = "Que curioso. Você não tem nenhum desejo.",
  ui_story_1014_10141401_60_dialog_content = "Ah, não, não. Meu erro.",
  ui_story_1014_10141401_61_dialog_content = "Você mesmo é um produto do desejo. É por isso que você é tão poderoso.",
  ui_story_1014_10141401_62_dialog_content = "Absolutamente fascinante.",
  ui_story_1014_10141401_63_dialog_content = "Eu me pergunto como esse desejo parecerá quando for destruído.",
  ui_story_1014_10141401_64_dialog_content = "Mal posso esperar!",
  ui_story_1014_10141401_65_dialog_content = "Cuidado, os Eclipsites estão se movendo!",
  ui_story_1014_10141402_1_dialog_content = "Argh!",
  ui_story_1014_10141402_2_dialog_content = "Axélia!",
  ui_story_1014_10141402_3_dialog_content = "Eu ainda posso lutar...",
  ui_story_1014_10141402_4_dialog_content = "Não, você não pode. Você precisa de tratamento agora!",
  ui_story_1014_10141402_5_dialog_content = "Decepcionante.",
  ui_story_1014_10141402_6_dialog_content = "A soma do desejo de Illumina nada mais é do que uma garotinha fraca.",
  ui_story_1014_10141402_7_dialog_content = "Tão decepcionante. Isso passa pelos desejos aurorianos hoje em dia?",
  ui_story_1014_10141402_8_dialog_content = "Inconcebível.",
  ui_story_1014_10141402_9_dialog_content = "Por que Forsakin está obcecado por algo tão indigno?",
  ui_story_1014_10141402_10_dialog_content = "Você não vai dizer isso sobre Axelia!",
  ui_story_1014_10141402_11_dialog_content = "Ainda se recusando a encarar o quão fraco você é?",
  ui_story_1014_10141402_12_dialog_content = "Que tal isso, então?",
  ui_story_1014_10141402_13_dialog_content = "Oh não, mais Eclipsites.",
  ui_story_1014_10141402_14_dialog_content = "Joselyne, Joseph, observem os Eclipsites menores chegando em seu flanco esquerdo!",
  ui_story_1014_10141402_15_dialog_content = "Sim!",
  ui_story_1014_10141402_16_dialog_content = "Yingel, Sean, vocês dois cuidam dos Eclipsites maiores à direita!",
  ui_story_1014_10141402_17_dialog_content = "Espere, por que devemos ouvi-lo?",
  ui_story_1014_10141402_18_dialog_content = "<anim type=Shake><size=45>Rugido!</size></anim>",
  ui_story_1014_10141402_19_dialog_content = "Deixe isso comigo!",
  ui_story_1014_10141402_20_dialog_content = "*Suspira*",
  ui_story_1014_10141402_21_dialog_content = "O resto de vocês lute contra esta comigo!",
  ui_story_1014_10141402_22_dialog_content = "Vejo que seus desejos nada mais são do que isso.",
  ui_story_1014_10141402_23_dialog_content = "Quanto mais forte o desejo, maior o poder.",
  ui_story_1014_10141402_24_dialog_content = "Você tem desejos mundanos, então você é fraco.",
  ui_story_1014_10141402_25_dialog_content = "Mas o meu é destruir todos os desejos do mundo!",
  ui_story_1014_10141402_26_dialog_content = "Pato, PlayerName!",
  ui_story_1014_10141402_27_dialog_content = "O quê?",
  ui_story_1014_10141402_28_dialog_content = "Nenhum desejo pode me escapar.",
  ui_story_1014_10141402_29_dialog_content = "Tsc!",
  ui_story_1014_10141402_30_dialog_content = "PlayerName!",
  ui_story_1014_10141402_31_dialog_content = "Ai, isso doeu!",
  ui_story_1014_10141402_32_dialog_content = "Oh não, o dispositivo!",
  ui_story_1014_10141402_33_dialog_content = "Não interfira com seu desejo banal.",
  ui_story_1014_10141402_34_dialog_content = "Argh!",
  ui_story_1014_10141402_35_dialog_content = "(Preciso esconder o dispositivo!)",
  ui_story_1014_10141402_36_dialog_content = "Hã?!",
  ui_story_1014_10141402_37_dialog_content = "Então esse é o seu desejo, traidor celestita.",
  ui_story_1014_10141402_38_dialog_content = "...",
  ui_story_1014_10141402_39_dialog_content = "É isso?",
  ui_story_1014_10141402_40_dialog_content = "Abaixe-o!",
  ui_story_1014_10141402_41_dialog_content = "Que chato.",
  ui_story_1014_10141402_42_dialog_content = "Do que essa coisa está falando?",
  ui_story_1014_10141402_43_dialog_content = "Chato, chato, totalmente chato.",
  ui_story_1014_10141402_44_dialog_content = "Você limita seu desejo a nada além de uma pilha de lixo sem sentido causada por erros, traidor?",
  ui_story_1014_10141402_45_option_content = "Não é lixo!",
  ui_story_1014_10141402_46_dialog_content = "Esses dados são um milagre!",
  ui_story_1014_10141402_47_dialog_content = "Os Colossos tentaram sem parar durante muito tempo, acumulando experiência até formarem uma personalidade...",
  ui_story_1014_10141402_48_dialog_content = "Um simplório mundano que não faz nada além de tagarelar sobre desejos o dia todo como se você não entendesse seu verdadeiro valor!",
  ui_story_1014_10141402_49_dialog_content = "Hehe... Simples mundano?",
  ui_story_1014_10141402_50_dialog_content = "Não pensei que o traidor fosse compartilhar minhas opiniões.",
  ui_story_1014_10141402_51_dialog_content = "Isso mesmo, todos os desejos são mundanos e não deveriam existir no mundo.",
  ui_story_1014_10141402_52_dialog_content = "Os eclipsitas não têm desejos e, portanto, não podem ser tentados. Isso os torna os organismos mais aptos para a sobrevivência.",
  ui_story_1014_10141402_53_dialog_content = "Eu mesmo escolhi me tornar um Wraith para abandonar desejos.",
  ui_story_1014_10141402_54_dialog_content = "Não ouça as bobagens dela, PlayerName.",
  ui_story_1014_10141402_55_dialog_content = "Vamos atacar juntos e recuperar o dispositivo!",
  ui_story_1014_10141402_56_dialog_content = "Mas eu mudei de ideia.",
  ui_story_1014_10141402_57_dialog_content = "Se você quer tanto de volta, você pode tê-lo.",
  ui_story_1014_10141402_58_dialog_content = "Oh não, o dispositivo!",
  ui_story_1014_10141402_59_dialog_content = "Ufa, essa foi por pouco.",
  ui_story_1014_10141402_60_dialog_content = "(Não parece danificado.)",
  ui_story_1014_10141402_61_dialog_content = "(O que ela quer? Ela não pode estar aqui apenas para zombar de nós.)",
  ui_story_1014_10141402_62_dialog_content = "Achei que você tinha grandes desejos, mas parece que me enganei.",
  ui_story_1014_10141402_63_dialog_content = "Vejo que o que você estava procurando era apenas lixo inútil.",
  ui_story_1014_10141402_64_dialog_content = "Tais desejos nem valem o meu tempo.",
  ui_story_1014_10141402_65_dialog_content = "Pare de tagarelar!",
  ui_story_1014_10141402_66_dialog_content = "Desde que você tossiu o que PlayerName necessário, eu não tenho que me segurar.",
  ui_story_1014_10141402_67_dialog_content = "Pegue isso, seu Eclipsita!",
  ui_story_1014_10141402_68_dialog_content = "Lealdade é o desejo mais inútil.",
  ui_story_1014_10141402_69_dialog_content = "Tão poderoso...!",
  ui_story_1014_10141402_70_dialog_content = "Não estava nem usando toda a sua força...",
  ui_story_1014_10141402_71_dialog_content = "<anim type=Shake><size=45>Rugido!</size></anim>",
  ui_story_1014_10141402_72_dialog_content = "Cuidado, Beretta! Flor de Gelo!",
  ui_story_1014_10141402_73_dialog_content = "Tão decepcionante.",
  ui_story_1014_10141402_74_dialog_content = "Você é muito cheio de desejos chatos para despertar meu interesse.",
  ui_story_1014_10141402_75_dialog_content = "Mas você, PlayerName, traidor dos celestitas...",
  ui_story_1014_10141402_76_dialog_content = "...",
  ui_story_1014_10141402_77_dialog_content = "Talvez tudo que você precise seja um pouco mais de tempo para transformar seu desejo em algo interessante... e delicioso.",
  ui_story_1014_10141402_78_dialog_content = "E você também, <color=#FFB400>vício</color>.",
  ui_story_1014_10141402_79_dialog_content = "Eu?",
  ui_story_1014_10141402_80_dialog_content = "Estamos partindo, Eclipsites.",
  ui_story_1014_10141402_81_dialog_content = "Isso não vale mais o nosso tempo.",
  ui_story_1014_10141402_82_dialog_content = "Não tente correr!",
  ui_story_1014_10141402_83_dialog_content = "Acalme-se, Beretta!",
  ui_story_1014_10141402_84_dialog_content = "Ela não é o seu Eclipsite comum. O melhor que conseguiríamos é um impasse contra ela.",
  ui_story_1014_10141402_85_dialog_content = "Não temos meios para persegui-los. O que precisamos fazer agora é recuar e conseguir reforços.",
  ui_story_1014_10141402_86_dialog_content = "Mas...",
  ui_story_1014_10141402_87_dialog_content = "Leo tem razão, Beretta. Não devemos ir atrás deles neste momento.",
  ui_story_1014_10141402_88_dialog_content = "Voltemos a Crepúsculo.",
  ui_story_1014_10141402_89_dialog_content = "Como desejar.",
  ui_story_1014_10141402_90_dialog_content = "Obrigado por concordar, Cavaleiro Comandante.",
  ui_story_1014_10141402_91_dialog_content = "Qualquer guerreiro experiente chegaria à mesma conclusão.",
  ui_story_1014_10141402_92_dialog_content = "(Forsakin não apareceu, mas atraímos outro Wraith...)",
  ui_story_1014_10141402_93_dialog_content = "(Isso é uma coincidência ou era para ser?)",
  ui_story_1014_10141402_94_dialog_content = "(Independentemente disso, a missão foi um fracasso. Forsakin não se mostrou como previsto.)",
  ui_story_1014_10141402_95_dialog_content = "(Terei que rastreá-los de outra maneira.)",
  ui_story_1014_10141402_95X1_dialog_content = "Vamos embora, assim mesmo? É só deixar o Naviduz aqui e ir...?",
  ui_story_1014_10141402_95X2_dialog_content = "Não há como trazê-lo de volta conosco? Vice, certamente a tecnologia Illumina poderia consertar isso!",
  ui_story_1014_10141402_95X3_dialog_content = "Receio que possa ser difícil...",
  ui_story_1014_10141402_95X4_dialog_content = "...",
  ui_story_1014_10141402_95X5_dialog_content = "PlayerName, entendo como você se sente, mas não há nada que possamos fazer agora.",
  ui_story_1014_10141402_95X6_dialog_content = "Yingel, este Colosso é muito importante para PlayerName. Não há realmente nada que possamos fazer?",
  ui_story_1014_10141402_95X7_dialog_content = "O Colossus já estava bastante abatido, sem falar no dano colateral daquele último ataque.",
  ui_story_1014_10141402_95X8_dialog_content = "O fato de ainda estar funcionando é um milagre em si...",
  ui_story_1014_10141402_95X9_dialog_content = "Como isso pode ser...",
  ui_story_1014_10141402_95X10_dialog_content = "<color=#e8d9bb>Sinto que você está saindo, Caelestite PlayerName.</color>",
  ui_story_1014_10141402_95X11_dialog_content = "Naviduz?",
  ui_story_1014_10141402_95X12_dialog_content = "<color=#e8d9bb>Naviduz deseja fazer uma pergunta ao celestita.</color>",
  ui_story_1014_10141402_95X13_dialog_content = "<color=#e8d9bb>celestita PlayerName, por favor, informe-me sobre a sua próxima visita e como pretende reparar a Naviduz.</color>",
  ui_story_1014_10141402_95X14_dialog_content = "...",
  ui_story_1014_10141402_95X15_dialog_content = "Eu... eu não sei.",
  ui_story_1014_10141402_95X16_dialog_content = "Desculpe... me desculpe, mas você vai ter que esperar mais um pouco...",
  ui_story_1014_10141402_95X17_dialog_content = "<color=#e8d9bb>Comando recebido.</color>",
  ui_story_1014_10141402_95X18_dialog_content = "<color=#e8d9bb>De acordo com a configuração do 35, é aqui que devo desejar felicidades a Caelestite PlayerName.</color>",
  ui_story_1014_10141402_95X19_dialog_content = "<color=#e8d9bb>Por favor, não se sinta mal por não reparar o Naviduz. Mantenha os olhos fixos no horizonte.</color>",
  ui_story_1014_10141402_95X20_dialog_content = "O que? Isso foi uma mensagem de 35? Ela realmente pensou em tudo...",
  ui_story_1014_10141402_95X21_dialog_content = "<color=#e8d9bb>Naviduz e 35 desejam-lhe uma boa viagem.</color>",
  ui_story_1014_10141402_95X22_dialog_content = "Valeu...",
  ui_story_1014_10141402_95X23_dialog_content = "Eu te escuto. Continuarei minha jornada com suas almas em meu coração...",
  ui_story_1014_10141402_95X24_dialog_content = "Vamos, PlayerName.",
  ui_story_1014_10141402_95X25_dialog_content = "Tudo bem vamos. Ainda temos muito trabalho a fazer.",
  ui_story_1014_10141402_96_dialog_content = "<color=#e8d9bb>Soroz, a ponte</color>",
  ui_story_1014_10141402_97_dialog_content = "Engaje, Soroz!",
  ui_story_1014_10141402_98_dialog_content = "Aqueles Eclipsites não nos seguiram, certo?",
  ui_story_1014_10141402_99_dialog_content = "Eu não os sinto mais, então eles provavelmente não estão por perto.",
  ui_story_1014_10141402_100_dialog_content = "Não sei o que eles estão fazendo, mas sinto que fomos menosprezados.",
  ui_story_1014_10141402_101_dialog_content = "Um dia, porém, os Eclipsitas pagarão por nos subestimar.",
  ui_story_1014_10141402_102_dialog_content = "Como vai, Axélia? Você foi atingido por muitos ataques...",
  ui_story_1014_10141402_103_dialog_content = "Eu tô bem.",
  ui_story_1014_10141402_104_dialog_content = "O corpo de Axelia pode ser frágil, mas *tosse*... Não serei derrotado tão facilmente.",
  ui_story_1014_10141402_105_dialog_content = "(Esse é um dos efeitos colaterais da modificação?)",
  ui_story_1014_10141402_107_dialog_content = "(Mesmo assim, Reinhardt deve ter suas razões para se opor veementemente ao projeto.)",
  ui_story_1014_10141402_109_dialog_content = "(Falando nisso, Reinhardt parece ter habilidades de combate e recuperação sobre-humanas também...)",
  ui_story_1014_10141402_110_dialog_content = "O que está em sua mente, PlayerName?",
  ui_story_1014_10141402_111_dialog_content = "Huh? Oh nada.",
  ui_story_1014_10141402_112_dialog_content = "Que houve, Vice?",
  ui_story_1014_10141402_113_dialog_content = "Nada realmente. É que há algumas coisas que eu não entendo.",
  ui_story_1014_10141402_114_dialog_content = "Como é que aquele Eclipsite chamado Asmodeus me mencionou no final?",
  ui_story_1014_10141402_115_dialog_content = "Não a conheço e nunca lhe disse meu nome.",
  ui_story_1014_10141402_116_option_content = "Poderia ser o Chord Link?",
  ui_story_1014_10141402_117_dialog_content = "Você tem poderes especiais ao usar o Chord Link.",
  ui_story_1014_10141402_118_dialog_content = "Talvez Asmodeus tenha percebido isso e chamou a atenção dela para você?",
  ui_story_1014_10141402_119_dialog_content = "Não saberíamos...",
  ui_story_1014_10141402_120_dialog_content = "Ela é difícil de descobrir.",
  ui_story_1014_10141402_121_option_content = "Poderia ser o seu estado físico?",
  ui_story_1014_10141402_122_dialog_content = "Depois de usar o Chord Link, seu estado físico ficou incomum.",
  ui_story_1014_10141402_123_dialog_content = "E isso fez você brilhar.",
  ui_story_1014_10141402_124_dialog_content = "Mas não há praticamente nenhuma diferença em minha aparência externa.",
  ui_story_1014_10141402_125_dialog_content = "Ela poderia ter uma habilidade especial que pode detectar mudanças internas?",
  ui_story_1014_10141402_126_dialog_content = "Na verdade não...",
  ui_story_1014_10141402_127_dialog_content = "Vamos discutir isso mais tarde. Como você está se sentindo agora, Vice?",
  ui_story_1014_10141402_128_dialog_content = "Fizemos muitas lutas. Você se sente desconfortável em algum lugar?",
  ui_story_1014_10141402_129_dialog_content = "Relaxar. Estou um pouco cansada, mas nada que um bom descanso não resolva.",
  ui_story_1014_10141402_130_dialog_content = "Meu corpo aguentou muito bem.",
  ui_story_1014_10141402_131_dialog_content = "Estou aliviado ao ouvir isso.",
  ui_story_1014_10141402_132_dialog_content = "Tudo o que precisamos fazer agora é voltar para Gannon e consertar Soroz com o módulo e os dados!",
  ui_story_1014_10141402_133_dialog_content = "Depois de deixarmos Axelia e o resto em Crepúsculo.",
  ui_story_1014_10141402_134_dialog_content = "Sim!",
  ui_story_1014_10141402_135_dialog_content = "<color=#e8d9bb>Zumbido...</color>",
  ui_story_1014_10141402_136_dialog_content = "Soroz acabou de receber um sinal de comunicação remota, e o remetente é... Naviduz!",
  ui_story_1014_10141402_137_dialog_content = "<color=#e8d9bb>Tzzst...</color>",
  ui_story_1014_10141402_137X1_dialog_content = "<color=#e8d9bb>De acordo com as ordens de 35, este comando será executado após a saída do Caelestita.</color>",
  ui_story_1014_10141402_138_dialog_content = "<color=#e8d9bb>As condições para solicitação foram atendidas. Naviduz está enviando uma solicitação para Caelestite PlayerName.</color>",
  ui_story_1014_10141402_139_dialog_content = "O Colossus está me enviando um pedido?",
  ui_story_1014_10141402_140_dialog_content = "<color=#e8d9bb>PlayerName of the Caelestites obteve todos os dados de Naviduz.</color>",
  ui_story_1014_10141402_141_dialog_content = "<color=#e8d9bb>O núcleo de energia de Naviduz está danificado e não pode ser consertado. Todas as operações cessarão em breve.</color>",
  ui_story_1014_10141402_142_dialog_content = "<color=#e8d9bb>De acordo com a ordem de 35, quando as duas condições acima forem atendidas, a Naviduz enviará uma solicitação ao Caelestite mais próximo...</color>",
  ui_story_1014_10141402_143_dialog_content = "Pode ser...",
  ui_story_1014_10141402_144_dialog_content = "<color=#e8d9bb> Naviduz solicita que PlayerName <color=#FFB400>escreva um poema</color> para Naviduz.</color>",
  ui_story_1014_10141402_145_dialog_content = "...",
  ui_story_1014_10141402_146_dialog_content = "Sim, eu sei.",
  ui_story_1014_10141402_147_dialog_content = "Mas nunca escrevi poesia antes, então pode não acabar bem.",
  ui_story_1014_10141402_148_dialog_content = "Você uma vez viajou conosco",
  ui_story_1014_10141402_149_dialog_content = "Um céu estrelado sem limites, o vento sob suas asas",
  ui_story_1014_10141402_150_dialog_content = "Uma jornada de comprimento imensurável, durando um tempo imensurável",
  ui_story_1014_10141402_151_dialog_content = "Uma jornada que durou até as estrelas desaparecerem",
  ui_story_1014_10141402_152_dialog_content = "Até que apenas uma estada solitária permaneceu",
  ui_story_1014_10141402_153_dialog_content = "Quando a chamada para retornar finalmente acenou",
  ui_story_1014_10141402_154_dialog_content = "O caminho de volta para casa foi perdido",
  ui_story_1014_10141402_155_dialog_content = "Você ficou à deriva nos céus por muito tempo",
  ui_story_1014_10141402_156_dialog_content = "Permaneceu na escuridão por muito tempo",
  ui_story_1014_10141402_157_dialog_content = "O tempo havia murchado todos os vestígios de casa",
  ui_story_1014_10141402_158_dialog_content = "Mas agora o farol brilha mais uma vez",
  ui_story_1014_10141402_159_dialog_content = "Que sua consciência siga os dentes-de-leão ao vento",
  ui_story_1014_10141402_160_dialog_content = "Até que ele voe de volta para Eraveil",
  ui_story_1014_10141402_161_dialog_content = "...",
  ui_story_1014_10141402_162_dialog_content = "(Isso foi péssimo... Nada surpreendente para alguém que nunca escreveu poesia antes...)",
  ui_story_1014_10141402_163_dialog_content = "<color=#e8d9bb>Poema recebido. Reproduzindo a gravação.</color>",
  ui_story_1014_10141402_164_dialog_content = "Obrigado, bom samaritano do futuro!",
  ui_story_1014_10141402_165_dialog_content = "Essa é a voz do 35!",
  ui_story_1014_10141402_166_dialog_content = "Naviduz deve estar feliz por ter um poema para acompanhá-lo.",
  ui_story_1014_10141402_166X1_dialog_content = "Embora nunca tenhamos nos conhecido, acho que, neste momento, nossos corações são um só.",
  ui_story_1014_10141402_166X2_dialog_content = "Mesmo sem usar sua habilidade psíquica, você também sentirá!",
  ui_story_1014_10141402_166X3_dialog_content = "Sim, mesmo sem minha habilidade psíquica. Essa vontade de chorar...",
  ui_story_1014_10141402_166X4_dialog_content = "Não importa em quais mãos esse presente acabe, espero sinceramente que você encontre inúmeros amigos para acompanhá-lo em sua jornada e que nunca fique sozinho.",
  ui_story_1014_10141402_166X5_dialog_content = "Deixe-o viajar com você. É isso que Naviduz e eu queremos!",
  ui_story_1014_10141402_166X6_dialog_content = "Obrigada. Obrigado a ambos...",
  ui_story_1014_10141402_166X7_dialog_content = "Prometo usar bem o seu dom.",
  ui_story_1014_10141402_168_dialog_content = "Adeus, Naviduz.",
  ui_story_1014_10141402_169_dialog_content = "Adeus, 35.",
  ui_story_1014_10141501_1_dialog_content = "<color=#e8d9bb>Crepúsculo, algum tempo depois...</color>",
  ui_story_1014_10141501_2_dialog_content = "Só aqui está bom.",
  ui_story_1014_10141501_3_dialog_content = "Obrigada, PlayerName.",
  ui_story_1014_10141501_4_dialog_content = "Eu deveria estar te agradecendo por me ajudar.",
  ui_story_1014_10141501_5_dialog_content = "Bem, então, adeus a todos.",
  ui_story_1014_10141501_6_dialog_content = "Foi uma honra lutar ao seu lado, mas devo ir agora.",
  ui_story_1014_10141501_7_dialog_content = "Tenho esperanças de vê-lo novamente, PlayerName.",
  ui_story_1014_10141501_8_dialog_content = "Espera.",
  ui_story_1014_10141501_9_dialog_content = "Há mais alguma coisa, Cavaleiro Comandante?",
  ui_story_1014_10141501_10_dialog_content = "Você ainda não me respondeu sobre o que é injusto.",
  ui_story_1014_10141501_11_dialog_content = "Hahaha. Você ainda estava esperando por uma resposta?",
  ui_story_1014_10141501_12_dialog_content = "Vou ser franco, então.",
  ui_story_1014_10141501_13_dialog_content = "Acho que Lumópolis precisa de uma grande reforma.",
  ui_story_1014_10141501_14_dialog_content = "Você...!",
  ui_story_1014_10141501_15_dialog_content = "Você já sabe que os títulos em Lumopolis são puramente hereditários.",
  ui_story_1014_10141501_16_dialog_content = "Eles são dados por causa da linhagem, não de habilidades, e são mantidos por interesse próprio.",
  ui_story_1014_10141501_17_dialog_content = "Isso significa que é difícil para aqueles que são muito capazes, mas não de origem nobre, avançar.",
  ui_story_1014_10141501_18_dialog_content = "Lumopolis precisa de uma reforma completa e gostaria de ser eu a iniciá-la.",
  ui_story_1014_10141501_19_dialog_content = "Você percebe que eu poderia mandá-lo para o Tribunal de Justiça por acusações de conspiração com o que você acabou de dizer?",
  ui_story_1014_10141501_20_dialog_content = "Ahaha. Mas não acho... ao contrário, tenho certeza de que você não faria isso.",
  ui_story_1014_10141501_21_dialog_content = "Mesmo sendo um nobre, o poder não o cegou.",
  ui_story_1014_10141501_22_dialog_content = "Você é diferente dos típicos Nobres Lumo por ser um verdadeiro cavaleiro batizado pela guerra.",
  ui_story_1014_10141501_23_dialog_content = "Como cavaleiro, isso é palpável para mim.",
  ui_story_1014_10141501_24_dialog_content = "É mesmo?",
  ui_story_1014_10141501_25_dialog_content = "Então, desejo que você continue se esforçando para realizar suas ambições.",
  ui_story_1014_10141501_26_dialog_content = "Vamos provar através de nossas respectivas ações qual das nossas escolhas é a melhor para Lumopolis.",
  ui_story_1014_10141501_27_dialog_content = "É uma promessa!",
  ui_story_1014_10141501_28_dialog_content = "Você realmente vai deixá-lo ir, Lady Carleen?",
  ui_story_1014_10141501_29_dialog_content = "Está tudo bem, deixe-o em paz.",
  ui_story_1014_10141501_30_dialog_content = "Isso significa que Joselyne... Ei, para onde foi Joselyne?",
  ui_story_1014_10141501_31_dialog_content = "Um transeunte a chamou para ajudar.",
  ui_story_1014_10141501_32_dialog_content = "Quando PlayerName estava observando Carleen e Leo.",
  ui_story_1014_10141501_33_dialog_content = "Essa é a Joselyne, ela nunca recusa um pedido de ajuda.",
  ui_story_1014_10141501_34_dialog_content = "É uma pena não termos tido oportunidade de nos despedir.",
  ui_story_1014_10141501_35_dialog_content = "Nós nos encontraremos de novo.",
  ui_story_1014_10141501_36_dialog_content = "Yingel, Sean e eu também precisamos ir para casa.",
  ui_story_1014_10141501_37_dialog_content = "A missão foi concluída.",
  ui_story_1014_10141501_38_dialog_content = "Isso é verdade, mas ainda precisamos informar nossos superiores sobre o Asmodeus.",
  ui_story_1014_10141501_39_dialog_content = "É aqui que nos separamos, PlayerName, Tenente Vice, Lady Carleen, Srta. Beretta.",
  ui_story_1014_10141501_40_dialog_content = "Vamos nos encontrar novamente algum dia!",
  ui_story_1014_10141501_41_dialog_content = "Terá minha ajuda, PlayerName.",
  ui_story_1014_10141501_42_dialog_content = "Ah, sim, estamos participando do próximo evento militar conjunto.",
  ui_story_1014_10141501_43_dialog_content = "Nos vemos na simulação!",
  ui_story_1014_10141501_44_dialog_content = "Sim, ansioso por isso!",
  ui_story_1014_10141501_45_dialog_content = "Veremos quem sai por cima.",
  ui_story_1014_10141501_46_option_content = "Mais tarde!",
  ui_story_1014_10141501_47_dialog_content = "Nós finalmente os levamos de volta para Crepúsculo com segurança.",
  ui_story_1014_10141501_48_dialog_content = "Devemos nos apressar de volta para Gannon nós mesmos.",
  ui_story_1014_10141501_49_dialog_content = "Enquanto Asmodeus merece atenção, a prioridade é consertar Soroz.",
  ui_story_1014_10141501_50_dialog_content = "Sim, não vamos atrasar mais isso.",
  ui_story_1014_10141501_51_dialog_content = "Vamos!",
  ui_story_1014_10141501_52_dialog_content = "<color=#e8d9bb>Gannon, algum tempo depois...</color>",
  ui_story_1014_10141501_53_dialog_content = "Temos os dados que você precisava, Algol!",
  ui_story_1014_10141501_54_dialog_content = "OK. Espere...",
  ui_story_1014_10141501_55_dialog_content = "Você já voltou?",
  ui_story_1014_10141501_56_dialog_content = "Sim.",
  ui_story_1014_10141501_57_dialog_content = "Encontramos inimigos inesperados, mas conseguimos obter os dados.",
  ui_story_1014_10141501_58_dialog_content = "Sim, ouvi falar daquele estranho Wraith... <color=#FFB400>Asmodeus</color>, certo?",
  ui_story_1014_10141501_59_dialog_content = "Você já sabe?!",
  ui_story_1014_10141501_60_dialog_content = "Eu não deveria estar surpreso. Illumina tem pessoas em Crepúsculo.",
  ui_story_1014_10141501_61_dialog_content = "Não importa o que aconteça, basta uma mensagem e todo Gannon fica sabendo.",
  ui_story_1014_10141501_62_dialog_content = "Algo nesse sentido. Você nunca deve subestimar a rede da Illumina.",
  ui_story_1014_10141501_63_dialog_content = "Mas é o trabalho do Grand Marshal lidar com Wraiths e sua laia.",
  ui_story_1014_10141501_64_dialog_content = "Só quero ver os dados que você trouxe do Colossus.",
  ui_story_1014_10141501_65_dialog_content = "Como você conseguiu isso, quando tantos esquadrões voltaram de mãos vazias?",
  ui_story_1014_10141501_66_dialog_content = "Isso é porque...",
  ui_story_1014_10141501_67_option_content = "Sou Celestita.",
  ui_story_1014_10141501_68_dialog_content = "A consciência desse Colosso nasceu do esforço persistente de um celestita.",
  ui_story_1014_10141501_69_dialog_content = "Eu simplesmente herdei um presente muito precioso, como o último celestita.",
  ui_story_1014_10141501_70_dialog_content = "Interessante. Então é isso que os celestitas herdam uns dos outros?",
  ui_story_1014_10141501_71_option_content = "Aquele lugar também foi um \"presente\"",
  ui_story_1014_10141501_72_dialog_content = "O Colosso estava esperando que alguém viesse e repassasse os valiosos dados que possuía.",
  ui_story_1014_10141501_73_dialog_content = "Assim como fez Mestre Francisco no Obelisco do Retorno.",
  ui_story_1014_10141501_74_dialog_content = "O Colosso até me pediu para escrever um poema para ele.",
  ui_story_1014_10141501_75_dialog_content = "Sim? Que fascinante!",
  ui_story_1014_10141501_76_dialog_content = "Mostre-me os dados.",
  ui_story_1014_10141501_77_dialog_content = "...",
  ui_story_1014_10141501_78_dialog_content = "Hmm, é mais complicado do que eu pensava.",
  ui_story_1014_10141501_79_dialog_content = "Como assim?",
  ui_story_1014_10141501_80_dialog_content = "Complicado? Soroz pode ser consertado?",
  ui_story_1014_10141501_81_dialog_content = "Desacelerar. Deixe-me explicar.",
  ui_story_1014_10141501_82_dialog_content = "Você conhece a consciência do Colosso formada a partir dos esforços persistentes de um certo celestita.",
  ui_story_1014_10141501_83_dialog_content = "Certo.",
  ui_story_1014_10141501_84_dialog_content = "Em sua tentativa, o Colossus sofreu mudanças desconhecidas ao se deparar com situações fora de seus circuitos lógicos.",
  ui_story_1014_10141501_85_dialog_content = "Geralmente chamamos essas alterações de \"erros\", mas aqui estou mais inclinado a chamá-las de \"<color=#FFB400>crescimento</color>.\"",
  ui_story_1014_10141501_86_dialog_content = "Mas como as mudanças foram inesperadas...",
  ui_story_1014_10141501_87_dialog_content = "Eles se refletem nos dados como variáveis complicadas e caóticas.",
  ui_story_1014_10141501_88_dialog_content = "Algumas dessas variáveis podem ser inúteis, enquanto outras podem ser a chave para a consciência do Colossus.",
  ui_story_1014_10141501_89_dialog_content = "Além disso, como os dados são independentes entre os Colossi, as alterações também são diferentes.",
  ui_story_1014_10141501_90_dialog_content = "Os dados que você baixou não podem ser aplicados diretamente ao Soroz.",
  ui_story_1014_10141501_91_dialog_content = "Não entendo muito bem todo esse jargão.",
  ui_story_1014_10141501_92_dialog_content = "Eu só quero saber se Soroz pode ser restaurado!",
  ui_story_1014_10141501_93_dialog_content = "Preciso de algum tempo para analisar os dados para uma resposta mais específica.",
  ui_story_1014_10141501_94_dialog_content = "Os próprios dados de Soroz não são suficientes, mas com esses novos dados em mãos, posso fazer comparações cruzadas.",
  ui_story_1014_10141501_95_dialog_content = "E isso aumenta consideravelmente as chances a nosso favor.",
  ui_story_1014_10141501_96_dialog_content = "Espero que confie em mim e me dê tempo.",
  ui_story_1014_10141501_97_dialog_content = "Não é como se eu tivesse outra escolha.",
  ui_story_1014_10141501_98_dialog_content = "Não seja tão pessimista. Estou muito confiante em minha pesquisa de IA.",
  ui_story_1014_10141501_99_dialog_content = "Depois do que você passou, você deveria descansar um pouco.",
  ui_story_1014_10141501_100_dialog_content = "É a minha batalha agora.",
  ui_story_1014_10141501_101_dialog_content = "Como vai Soroz, PlayerName?",
  ui_story_1014_10141501_102_dialog_content = "Os dados foram úteis?",
  ui_story_1014_10141501_103_dialog_content = "Não tenho certeza. Algol disse que precisava de algum tempo para resolver isso.",
  ui_story_1014_10141501_104_dialog_content = "Ai...",
  ui_story_1014_10141501_105_dialog_content = "Espero que corra bem.",
  ui_story_1014_10141501_106_dialog_content = "Eu também.",
  ui_story_1014_10141501_107_dialog_content = "<color=#e8d9bb>Bip, bip, bip...</color>",
  ui_story_1014_10141501_108_dialog_content = "Tenente Vice, PlayerName, você está aí?",
  ui_story_1014_10141501_109_dialog_content = "Oficial Ulisses?",
  ui_story_1014_10141501_110_dialog_content = "Avançamos em nossa pesquisa sobre o Chord Link.",
  ui_story_1014_10141501_111_dialog_content = "Tenente Vice, apresente-se no local designado com PlayerName. Daqui a pouco mando as coordenadas.",
  ui_story_1014_10141501_112_dialog_content = "As coordenadas específicas são classificadas, não devendo pessoas não autorizadas acompanhá-lo.",
  ui_story_1014_10141501_113_dialog_content = "Por favor, responda após o recebimento.",
  ui_story_1014_10141501_114_dialog_content = "Sim, cópia do Tenente Vice.",
  ui_story_1014_10141501_115_dialog_content = "Muito bem. Sobre.",
  ui_story_1014_10141501_116_dialog_content = "Classificado, de novo? Acho que terminei aqui.",
  ui_story_1014_10141501_117_dialog_content = "Eu deveria voltar para Lumopolis de qualquer maneira.",
  ui_story_1014_10141501_118_dialog_content = "Quero saber mais sobre os Cavaleiros Espinho de Ferro.",
  ui_story_1014_10141501_119_dialog_content = "E atualize o City Lord sobre a situação em Crepúsculo.",
  ui_story_1014_10141501_120_dialog_content = "Ainda está preocupada com essas pessoas, Carleen?",
  ui_story_1014_10141501_121_dialog_content = "É impossível não.",
  ui_story_1014_10141501_122_dialog_content = "Trata-se de Lumopolis, por isso é necessário saber mais sobre eles, especialmente Leo, o Cavaleiro da Expedição.",
  ui_story_1014_10141501_123_dialog_content = "Não discordo das ideias dele. Ele pode fazer de Lumopolis um lugar melhor.",
  ui_story_1014_10141501_124_dialog_content = "No entanto, não posso ignorar o fato de que ele também pode ser uma ameaça em potencial para Lumopolis.",
  ui_story_1014_10141501_125_dialog_content = "Meticulosa como sempre, Carleen.",
  ui_story_1014_10141501_126_dialog_content = "Vamos chegar onde precisamos ir agora.",
  ui_story_1014_10141501_127_dialog_content = "Vamos.",
  ui_story_1014_10141501_128_dialog_content = "<color=#e8d9bb>Em algum lugar da Federação Illumina</color>",
  ui_story_1014_10141501_129_dialog_content = "As coordenadas nos levaram a uma cidade subterrânea?!",
  ui_story_1014_10141501_130_dialog_content = "Não está marcado em nenhum mapa Illumina.",
  ui_story_1014_10141501_131_dialog_content = "É impossível encontrar este lugar sem as coordenadas.",
  ui_story_1014_10141501_132_dialog_content = "...",
  ui_story_1014_10141501_133_dialog_content = "Parece muito fortemente defendido.",
  ui_story_1014_10141501_134_dialog_content = "É uma instalação ultrassecreta, não é tão surpreendente.",
  ui_story_1014_10141501_135_dialog_content = "Aí está você.",
  ui_story_1014_10141501_136_dialog_content = "(Esse cara de novo?)",
  ui_story_1014_10141501_137_dialog_content = "(É desconfortável falar com ele, como se ele estivesse sempre te interrogando ou algo assim...)",
  ui_story_1014_10141501_138_dialog_content = "O que você está fazendo aqui? Não foi Ulisses quem nos chamou?",
  ui_story_1014_10141501_139_dialog_content = "Aquele policial tinha questões urgentes para resolver, então ele me ordenou que escoltasse vocês dois.",
  ui_story_1014_10141501_140_dialog_content = "O que é tão urgente que tivemos que vir aqui em tão pouco tempo?",
  ui_story_1014_10141501_141_dialog_content = "Você já sabe muito, então vou ser direto.",
  ui_story_1014_10141501_142_dialog_content = "Comecemos pela situação atual.",
  ui_story_1014_10141501_143_dialog_content = "A origem do Programa Phospherus está, na verdade, ligada a <color=#FFB400>outro link de acorde</color> isso é aqui.",
  ui_story_1014_10141501_144_dialog_content = "O que? Existe mais de um Chord Link?",
  ui_story_1014_10141501_145_dialog_content = "Isso mesmo. Illumina descobriu um Chord Link anos atrás.",
  ui_story_1014_10141501_146_dialog_content = "Através de nossos estudos, descobrimos como modificar os aurorianos.",
  ui_story_1014_10141501_147_dialog_content = "No entanto, por várias razões, esta máquina não está tão intacta quanto sua contraparte em Eraveil.",
  ui_story_1014_10141501_148_dialog_content = "O processo de modificação desenvolvido pela Illumina é, portanto, imperfeito por causa das peças defeituosas.",
  ui_story_1014_10141501_149_dialog_content = "Ainda hoje, não podemos controlar os resultados, e o processo tem um alto índice de falhas.",
  ui_story_1014_10141501_150_dialog_content = "Então por que você não para o projeto?",
  ui_story_1014_10141501_151_dialog_content = "Você sabe que é perigoso e pode fazer as pessoas sofrerem.",
  ui_story_1014_10141501_152_dialog_content = "Então, por que você insiste em continuar?",
  ui_story_1014_10141501_153_dialog_content = "Não me importo de enfatizar novamente que a grande maioria da população Illumina é mediana.",
  ui_story_1014_10141501_154_dialog_content = "Esta é a única maneira de garantir a sobrevivência de Illumina.",
  ui_story_1014_10141501_155_option_content = "...",
  ui_story_1014_10141501_156_option_content = "eu não concordo com isso",
  ui_story_1014_10141501_157_dialog_content = "Eu entendo como você se sente, mas não se esqueça que temos um acordo.",
  ui_story_1014_10141501_158_dialog_content = "Se você está desconfortável, certamente tem o direito de parar de nos permitir acesso para estudar o Obelisco do Retorno.",
  ui_story_1014_10141501_159_dialog_content = "Embora isso interrompa a pesquisa sobre o Chord Link e seus efeitos colaterais também.",
  ui_story_1014_10141501_160_dialog_content = "(Ele está me ameaçando com Vice e Barton!)",
  ui_story_1014_10141501_161_dialog_content = "(Ele sabe que tem a vantagem...)",
  ui_story_1014_10141501_162_dialog_content = "A julgar pelo seu comportamento, você entendeu.",
  ui_story_1014_10141501_163_dialog_content = "O que você está tentando fazer agora?",
  ui_story_1014_10141501_164_dialog_content = "Depois de estudar a máquina no Obelisco, fizemos melhorias em nosso Chord Link incompleto.",
  ui_story_1014_10141501_165_dialog_content = "Gostaríamos de construir um modelo completo e impecável usando as peças funcionais de ambas as máquinas.",
  ui_story_1014_10141501_166_dialog_content = "Acredito que um Chord Link inteiro resolverá muitos problemas,",
  ui_story_1014_10141501_167_dialog_content = "como os misteriosos efeitos colaterais que ocorrem ao Tenente Vice e ao Comandante Barton.",
  ui_story_1014_10141501_168_dialog_content = "... O que voce precisa que eu faca?",
  ui_story_1014_10141501_169_dialog_content = "Afinal, Chord Link é tecnologia Caelestite, então certos dados são decifráveis apenas com habilidades psíquicas.",
  ui_story_1014_10141501_170_dialog_content = "Estamos tentando restaurar esses dados agora. Vamos precisar de seus serviços quando isso for feito.",
  ui_story_1014_10141501_171_dialog_content = "Só precisamos que você fique de prontidão por enquanto.",
  ui_story_1014_10141501_172_dialog_content = "(Eles me apressaram só para me dizer isso?)",
  ui_story_1014_10141501_173_dialog_content = "Tudo bem, entendi.",
  ui_story_1014_10141501_174_dialog_content = "Obrigado por sua cooperação.",
  ui_story_1014_10141501_175_dialog_content = "Tenho que ir, ainda tenho muito trabalho a fazer.",
  ui_story_1014_10141501_176_dialog_content = "Eu não gosto desse sentimento.",
  ui_story_1014_10141501_177_dialog_content = "É como se eu fosse uma ferramenta que estão usando para chegar até você.",
  ui_story_1014_10141501_178_dialog_content = "Não pense em si mesmo dessa maneira.",
  ui_story_1014_10141501_179_dialog_content = "Não posso me livrar de seus efeitos colaterais sem a ajuda deles.",
  ui_story_1014_10141501_180_dialog_content = "PlayerName...",
  ui_story_1014_10141501_181_dialog_content = "Você pode ignorar minha condição.",
  ui_story_1014_10141501_182_dialog_content = "Além do brilho ocasional, me sinto bem.",
  ui_story_1014_10141501_183_dialog_content = "Portanto, não há problema em obter ajuda deles. Encontraremos uma maneira de lidar com isso.",
  ui_story_1014_10141501_184_dialog_content = "Eu não quero ver você fazer o que não quer fazer, PlayerName.",
  ui_story_1014_10141501_185_option_content = "Obrigado, Vice.",
  ui_story_1014_10141501_186_dialog_content = "Mas não vou desistir de resolver essas questões.",
  ui_story_1014_10141501_187_option_content = "Eu não vou deixar você sozinho",
  ui_story_1014_10141501_188_dialog_content = "Soroz me ensinou desde cedo a valorizar cada amigo.",
  ui_story_1014_10141501_189_dialog_content = "Eu nunca deixaria um amigo em perigo e não faria nada a respeito.",
  ui_story_1014_10141501_190_dialog_content = "...",
  ui_story_1014_10141501_191_dialog_content = "(Nossa, o clima ficou intenso de repente...)",
  ui_story_1014_10141501_192_dialog_content = "Diga, quer dar um passeio e matar o tempo?",
  ui_story_1014_10141501_193_dialog_content = "Não estamos fazendo nada agora, de qualquer maneira. Eles também não mencionaram quando seríamos necessários.",
  ui_story_1014_10141501_194_dialog_content = "Sim, tenho certeza que seria bom.",
  ui_story_1014_10141501_195_dialog_content = "(Esta cidade subterrânea é enorme...)",
  ui_story_1014_10141501_196_dialog_content = "(Quase todas as salas nas passagens são laboratórios.)",
  ui_story_1014_10141501_197_dialog_content = "(Eu me pergunto quantos experimentos secretos aconteceram nesses laboratórios...)",
  ui_story_1014_10141501_198_dialog_content = "Devo rejeitar seu pedido.",
  ui_story_1014_10141501_199_dialog_content = "Esse dispositivo ainda está em fase experimental. Além disso, seu assunto ainda não está estável.",
  ui_story_1014_10141501_200_dialog_content = "É muito provável que submeter o sujeito a esse experimento arruíne a preciosa máquina.",
  ui_story_1014_10141501_201_dialog_content = "E uma máquina incompleta não garante a cura do assunto.",
  ui_story_1014_10141501_202_dialog_content = "Este é o meu projeto, não há espaço para sua opinião.",
  ui_story_1014_10141501_203_dialog_content = "Tudo o que você precisa fazer é me autorizar a usar o aparelho e ficar de boca fechada.",
  ui_story_1014_10141501_204_dialog_content = "Acho que ouvi alguém falando ao longe.",
  ui_story_1014_10141501_205_dialog_content = "Essa voz soa familiar...",
  ui_story_1014_10141501_206_dialog_content = "Discordo.",
  ui_story_1014_10141501_207_dialog_content = "Máquinas preciosas não são brinquedos para você brincar, muito menos...",
  ui_story_1014_10141501_208_dialog_content = "Você não tem mais autorização para me fazer essas exigências.",
  ui_story_1014_10141501_209_dialog_content = "Lá vai você com isso de novo.",
  ui_story_1014_10141501_210_dialog_content = "Você dá autorização e retira quando lhe convém.",
  ui_story_1014_10141501_211_dialog_content = "Quando comecei a trabalhar com vocês, tive que obter inúmeros resultados para ganhar a autorização para acessar tudo aqui.",
  ui_story_1014_10141501_212_dialog_content = "Mas agora, você tira todas as minhas contribuições assim.",
  ui_story_1014_10141501_213_dialog_content = "Você só está recebendo o que merece.",
  ui_story_1014_10141501_214_dialog_content = "Isso soa como... <color=#FFB400>abandono</color>!",
  ui_story_1014_10141501_215_dialog_content = "Ela está mantendo alguém como refém?",
  ui_story_1014_10141501_216_dialog_content = "Vamos dar uma olhada!",
  ui_story_1014_10141501_217_dialog_content = "Muito poucos pesquisadores podem lutar. Eles estariam em apuros se Forsakin os pegasse!",
  ui_story_1014_10141501_218_dialog_content = "Congele, deixe-o ir!",
  ui_story_1014_10141501_219_dialog_content = "(É Forsakin! Mas como é que eu não senti a presença dela?)",
  ui_story_1014_10141501_220_dialog_content = "(Espere, ela não está mantendo o pesquisador como refém...)",
  ui_story_1014_10141501_221_dialog_content = "(Ele apenas se virou e correu!)",
  ui_story_1014_10141501_222_dialog_content = "Que surpresa! O <color=#FFB400>material de experimentação</color> Eu precisava veio por conta própria!",
  ui_story_1014_10141501_223_dialog_content = "Abandono! O que você está fazendo aqui e por que estava abordando o pesquisador?",
  ui_story_1014_10141501_224_dialog_content = "Eu não abordei ninguém.",
  ui_story_1014_10141501_225_dialog_content = "Só estou aqui para recuperar algumas das coisas que deixei para trás.",
  ui_story_1014_10141501_226_dialog_content = "Mas como o material chegou até mim, aceitarei com prazer!",
  ui_story_1014_10141501_227_dialog_content = "Pato, PlayerName! Atrás de você!",
  ui_story_1014_10141501_228_dialog_content = "O quê?",
  ui_story_1014_10141501_229_dialog_content = "<anim type=Shake><size=50>Rugido!</size></anim>",
  ui_story_1014_10141501_230_dialog_content = "Argh!",
  ui_story_1014_10141501_231_dialog_content = "Parece que fui nocauteado por muito tempo...",
  ui_story_1014_10141501_232_dialog_content = "Acho que me lembro de encontrar Forsakin conversando com alguém, então...",
  ui_story_1014_10141501_233_dialog_content = "Vício! Tudo bem Vice?",
  ui_story_1014_10141501_234_dialog_content = "E... Abandono?!",
  ui_story_1014_10141501_235_dialog_content = "Nos encontramos novamente, Celestita.",
  ui_story_1014_10141501_236_dialog_content = "Faça o que eu digo se não quiser vê-la se machucar.",
  ui_story_1014_10141501_237_dialog_content = "...",
  ui_story_1014_10141501_238_dialog_content = "O que você está tentando fazer? Deixe ela ir!",
  ui_story_1014_10141501_239_dialog_content = "Apenas deixe-a ir, e eu irei com você.",
  ui_story_1014_10141501_240_dialog_content = "Talvez você não entenda a situação.",
  ui_story_1014_10141501_241_dialog_content = "Como súdito, você não está autorizado a fazer exigências.",
  ui_story_1014_10141501_242_dialog_content = "Especialmente isso...",
  ui_story_1014_10141501_243_dialog_content = "Ambos são necessários para o experimento.",
  ui_story_1015_10150101_1_dialog_content = "Cau, caca!",
  ui_story_1015_10150101_2_dialog_content = "Logo vai escurecer.",
  ui_story_1015_10150101_3_dialog_content = "Certo. Vamos em frente.",
  ui_story_1015_10150101_4_dialog_content = "<color=#e8d9bb>*Passos*</color>",
  ui_story_1015_10150101_5_dialog_content = "Ouça com atenção, celestita.",
  ui_story_1015_10150101_6_dialog_content = "A partir deste momento, você deve seguir minhas instruções ao pé da letra.",
  ui_story_1015_10150101_7_dialog_content = "Nem pense em procurar ajuda, resistir ou fazer qualquer movimento precipitado.",
  ui_story_1015_10150101_8_dialog_content = "Estarei conduzindo uma pesquisa muito importante e precisarei de sua ajuda.",
  ui_story_1015_10150101_9_dialog_content = "Você está planejando implantar algo em meu corpo novamente?",
  ui_story_1015_10150101_10_dialog_content = "Então, você ainda se lembra do nosso último projeto.",
  ui_story_1015_10150101_11_dialog_content = "Como eu poderia esquecer? Você quase me transformou em uma dessas coisas!",
  ui_story_1015_10150101_12_dialog_content = "Quase, de fato. Foi uma pena que as coisas não saíram como eu esperava.",
  ui_story_1015_10150101_13_dialog_content = "Foi irrelevante, mas eu estava bastante interessado em ver o que teria acontecido se você e Schummer fossem parentes mais uma vez...",
  ui_story_1015_10150101_14_dialog_content = "Deve ter sido divertido.",
  ui_story_1015_10150101_15_dialog_content = "Inconsequente? E quanto aos outros? A respeito Eve, Dawn, e todo o resto? O que aconteceu com eles foi \"inconseqüente\"?",
  ui_story_1015_10150101_16_dialog_content = "O que é que você fez?! Por que você-",
  ui_story_1015_10150101_17_dialog_content = "Você está fazendo meus ouvidos doerem.",
  ui_story_1015_10150101_18_dialog_content = "Seus celestitas... Suas vozes parecem ficar mais altas a cada segundo. Que tal eu cortar suas cordas vocais?",
  ui_story_1015_10150101_19_dialog_content = "Afinal, você nem precisa da voz para se comunicar, não é mesmo?",
  ui_story_1015_10150101_20_dialog_content = "...",
  ui_story_1015_10150101_21_dialog_content = "Você é quem precisa calar a boca...",
  ui_story_1015_10150101_22_dialog_content = "O que estou tentando dizer aqui é: cuidado com o que fala, celestita.",
  ui_story_1015_10150101_23_dialog_content = "Seja um menino obediente e faça exatamente o que eu lhe pedir. Não tenho tempo nem vontade de negociar com você.",
  ui_story_1015_10150101_24_dialog_content = "Contanto que o experimento corra bem, você e Vice ainda pode ter uma chance de sobreviver.",
  ui_story_1015_10150101_25_dialog_content = "... E se a experiência não correr bem?",
  ui_story_1015_10150101_26_dialog_content = "Suas vidas devem ser mais do que suficientes para pagar o preço pelo fracasso.",
  ui_story_1015_10150101_27_dialog_content = "...",
  ui_story_1015_10150101_28_dialog_content = "Você está tentando usar nossas vidas para nos ameaçar?",
  ui_story_1015_10150101_29_dialog_content = "Não sou burro o suficiente para acreditar nas promessas feitas pelo Eclipse.",
  ui_story_1015_10150101_30_dialog_content = "Mesmo que o experimento seja bem-sucedido, você nos matará de qualquer maneira.",
  ui_story_1015_10150101_31_dialog_content = "Matar você realmente não vai me beneficiar de forma alguma.",
  ui_story_1015_10150101_32_dialog_content = "Eu tenho o último Caelestite sobrevivente e um produto de sucesso do Chord Link antes de mim.",
  ui_story_1015_10150101_33_dialog_content = "Vocês dois são espécimes inestimáveis. Se tiver a oportunidade, prefiro levá-los de volta ao meu laboratório do que acabar com suas vidas prematuramente.",
  ui_story_1015_10150101_34_dialog_content = "Mas, infelizmente, não tenho essas liberdades dentro das fronteiras da Illumina.",
  ui_story_1015_10150101_35_dialog_content = "Portanto, prometo dar a você pelo menos uma chance de sair daqui com vida.",
  ui_story_1015_10150101_36_dialog_content = "Não como um grande gesto de misericórdia, é claro, mas para futuras oportunidades de pesquisa.",
  ui_story_1015_10150101_37_dialog_content = "Você...",
  ui_story_1015_10150101_38_dialog_content = "A pesquisa parece ser a única coisa que importa em sua mente.",
  ui_story_1015_10150101_39_dialog_content = "Claro. Pessoalmente, não vejo o que mais na vida poderia valer a pena.",
  ui_story_1015_10150101_40_dialog_content = "Vamos discutir o próximo experimento. Pode tornar as coisas um pouco mais fáceis se você souber o que esperar.",
  ui_story_1015_10150101_41_dialog_content = "Ei, nós nem concordamos em obedecer a você!",
  ui_story_1015_10150101_42_dialog_content = "Você realmente não tem escolha.",
  ui_story_1015_10150101_43_dialog_content = "...",
  ui_story_1015_10150101_44_dialog_content = "Estou pesquisando métodos para estimular a metamorfose no corpo auroriano.",
  ui_story_1015_10150101_45_dialog_content = "Meu objetivo é evoluir os aurorianos para uma espécie mais avançada sem sacrificar as habilidades que eles já possuem.",
  ui_story_1015_10150101_46_dialog_content = "... Você parece louco.",
  ui_story_1015_10150101_47_dialog_content = "Você usou o Chord Link que os Caelestites deixaram para trás antes. Pense por um momento e você será capaz de entender.",
  ui_story_1015_10150101_48_dialog_content = "Ele detém esse potencial.",
  ui_story_1015_10150101_49_dialog_content = "Você quer fazer algo com o Chord Link?",
  ui_story_1015_10150101_50_dialog_content = "Sim, é por isso que estou aqui.",
  ui_story_1015_10150101_51_dialog_content = "Você deve saber que Illumina escavou um Chord Link escondido aqui nesta Cidade Baixa, correto?",
  ui_story_1015_10150101_52_dialog_content = "Sim, nós sabemos...",
  ui_story_1015_10150101_53_dialog_content = "Este equipamento é de extrema importância para minha pesquisa.",
  ui_story_1015_10150101_54_dialog_content = "Preciso usá-lo para experimentos, coleta de dados e encontrar o uso mais adequado para o Chord Link.",
  ui_story_1015_10150101_55_dialog_content = "Se possível, desejo criar formas de vida superiores aos aurorianos.",
  ui_story_1015_10150101_56_dialog_content = "V-você quer transformar Vice para o seu experimento?!",
  ui_story_1015_10150101_57_dialog_content = "Hah, minhas esperanças para ela não são tão altas. Vice servirá apenas como uma amostra para medir os dados experimentais. Ela não estará envolvida na transformação final.",
  ui_story_1015_10150101_58_dialog_content = "Ele será o primeiro a receber esta honra.",
  ui_story_1015_10150101_59_dialog_content = "...",
  ui_story_1015_10150101_60_dialog_content = "Ai...",
  ui_story_1015_10150101_61_dialog_content = "(Forsakin o salvou apenas por causa deste experimento?)",
  ui_story_1015_10150101_62_dialog_content = "(Ou talvez vice-versa, o verdadeiro propósito desta pesquisa é realmente salvá-lo...)",
  ui_story_1015_10150101_63_dialog_content = "No entanto, se minha pesquisa for bem, você também se beneficiará dela.",
  ui_story_1015_10150101_64_dialog_content = "Eu vi os dados no Illumina. Vice parecia exibir certos efeitos colaterais depois de ser aprimorado pelo Chord Link, correto?",
  ui_story_1015_10150101_65_dialog_content = "Como você conseguiu esses dados?!",
  ui_story_1015_10150101_66_dialog_content = "Isso não é da sua conta!",
  ui_story_1015_10150101_67_dialog_content = "Assim que minha pesquisa estiver concluída, pode haver uma chance de que esses efeitos colaterais possam ser eliminados usando o Chord Link.",
  ui_story_1015_10150101_68_dialog_content = "Então, como você pode ver, esta é realmente uma situação ganha-ganha.",
  ui_story_1015_10150101_69_dialog_content = "... Você acha que pode nos persuadir a obedecer tão facilmente?",
  ui_story_1015_10150101_70_dialog_content = "Eu realmente não acho que preciso persuadi-lo. Ajudar-me é a única maneira de você sair dessa com vida.",
  ui_story_1015_10150101_71_dialog_content = "Eu estava apenas afirmando um fato, que esta pesquisa pode ser benéfica para você.",
  ui_story_1015_10150101_72_dialog_content = "Tudo bem, tudo bem. Como você disse, não temos escolha.",
  ui_story_1015_10150101_73_dialog_content = "Mas eu não entendo. Com o que exatamente você quer que o ajudemos?",
  ui_story_1015_10150101_74_dialog_content = "Preciso que você me ajude a eliminar alguns obstáculos que bloqueiam o caminho da minha pesquisa.",
  ui_story_1015_10150101_75_dialog_content = "Minha pesquisa requer equipamentos e dados. Ambos estão nas garras de Illumina.",
  ui_story_1015_10150101_76_dialog_content = "Mas, obviamente, eles nunca dariam acesso a um estranho.",
  ui_story_1015_10150101_77_dialog_content = "<color=#e8d9bb>Fronteira do Crepúsculo</color>",
  ui_story_1015_10150101_78_dialog_content = "Apresse-se, carregue o cavaleiro ferido primeiro!",
  ui_story_1015_10150101_79_dialog_content = "Sim, senhor!",
  ui_story_1015_10150101_80_dialog_content = "Faça o que puder pelos feridos de Illumina também. Eles têm ainda mais falta de mão de obra do que nós.",
  ui_story_1015_10150101_81_dialog_content = "Obrigado, capitão Leo...",
  ui_story_1015_10150101_82_dialog_content = "Não há necessidade de me agradecer. Estamos todos lutando a mesma batalha.",
  ui_story_1015_10150101_83_dialog_content = "Não fazia ideia de que estaríamos enfrentando um inimigo tão forte hoje. Sofremos baixas consideráveis...",
  ui_story_1015_10150101_84_dialog_content = "É tudo culpa minha. Não sou bom o suficiente para servir como comandante...",
  ui_story_1015_10150101_85_dialog_content = "Pare de se culpar. Ao enfrentar um inimigo tão poderoso, a perda é inevitável.",
  ui_story_1015_10150101_86_dialog_content = "E de alguma forma acho que nossas perdas hoje foram inevitáveis.",
  ui_story_1015_10150101_87_dialog_content = "Por que diz isso?",
  ui_story_1015_10150101_88_dialog_content = "Algo parece errado sobre esses ataques em Crepúsculo.",
  ui_story_1015_10150101_89_dialog_content = "Nos últimos dias, a cidade foi alvo de vários ataques consecutivos em grande escala.",
  ui_story_1015_10150101_90_dialog_content = "Isso me parece estranho. O inimigo nunca esteve tão ativo.",
  ui_story_1015_10150101_91_dialog_content = "Você está dizendo que os Eclipsitas estão planejando algo grande?",
  ui_story_1015_10150101_92_dialog_content = "Não tenho certeza, mas seria prudente se preparar com antecedência.",
  ui_story_1015_10150101_93_dialog_content = "Sean, ouvi dizer que seu chefe voltou recentemente. Isso é correto?",
  ui_story_1015_10150101_94_dialog_content = "Sim, ele voltou não faz muito tempo.",
  ui_story_1015_10150101_95_dialog_content = "Deixe-me pegá-lo emprestado por um tempo. Apenas diga a ele que vou buscá-lo no lugar de sempre.",
  ui_story_1015_10150101_96_dialog_content = "Bem-vindo! Mesa para um?",
  ui_story_1015_10150101_97_dialog_content = "Estou à procura de alguém.",
  ui_story_1015_10150101_98_dialog_content = "Não é todo dia que sou convidado para jantar pelo mais famoso de Crepúsculo.",
  ui_story_1015_10150101_99_dialog_content = "Sente-se e cave.",
  ui_story_1015_10150101_100_dialog_content = "Não obrigado, já comi.",
  ui_story_1015_10150101_101_dialog_content = "Melhor ainda! Passe-me o seu prato.",
  ui_story_1015_10150101_102_dialog_content = "Acho que seria mais adequado mantê-lo na minha frente. Afinal, este é o meu jantar de boas-vindas.",
  ui_story_1015_10150101_103_dialog_content = "Estou assumindo que você me pediu aqui para algo mais importante do que uma refeição.",
  ui_story_1015_10150101_104_dialog_content = "Claro, eu nunca pediria a alguém para me acompanhar simplesmente com o propósito de me ver encher a cara.",
  ui_story_1015_10150101_105_dialog_content = "Você leu os relatórios de vítimas do Illumina nos últimos dias?",
  ui_story_1015_10150101_106_dialog_content = "Eu tenho. Os números são bastante anormais.",
  ui_story_1015_10150101_107_dialog_content = "A guarnição Illumina de Twilight nunca experimentou perdas tão concentradas.",
  ui_story_1015_10150101_108_dialog_content = "A intensidade do combate dos últimos dias atingiu um ponto crítico. Estamos no limite do que podemos suportar.",
  ui_story_1015_10150101_109_dialog_content = "O mais desconcertante não é o grau de baixas que sofremos, mas que até agora não conseguimos derrotar o inimigo de forma decisiva.",
  ui_story_1015_10150101_110_dialog_content = "Cada batalha resultou em ambos os lados recuando após um impasse.",
  ui_story_1015_10150101_111_dialog_content = "Claramente, não fomos capazes de calcular a força das forças de nosso inimigo.",
  ui_story_1015_10150101_112_dialog_content = "O pior cenário é que todos esses encontros são, de fato, grupos independentes de Eclipsites.",
  ui_story_1015_10150101_113_dialog_content = "Se eles convergirem para sitiar Crepúsculo, as consequências serão incalculáveis.",
  ui_story_1015_10150101_114_dialog_content = "Bem dito. É tão revigorante ouvir os pensamentos de uma mente inteligente.",
  ui_story_1015_10150101_115_dialog_content = "Você já elaborou uma estratégia para lidar com a situação?",
  ui_story_1015_10150101_116_dialog_content = "Desdobrei tropas para realizar reconhecimento secreto em uma tentativa de entender completamente os movimentos do inimigo.",
  ui_story_1015_10150101_117_dialog_content = "Mas, na minha opinião, nossa força militar atual é insuficiente para manter nosso controle sobre Crepúsculo.",
  ui_story_1015_10150101_118_dialog_content = "É por isso que vou enviar um pedido de reforços.",
  ui_story_1015_10150101_119_dialog_content = "Hmm... Sim, esta é a opção mais segura.",
  ui_story_1015_10150101_120_dialog_content = "Você queria me ver sobre este assunto, então presumo que pretende obter ajuda da Illumina, correto?",
  ui_story_1015_10150101_121_dialog_content = "Claro, ainda não sabemos quantos inimigos teremos de enfrentar no futuro.",
  ui_story_1015_10150101_122_dialog_content = "Seria muito míope deixar que as diferenças de Lumopolis e Illumina se interponham entre nós neste momento, não é?",
  ui_story_1015_10150101_123_dialog_content = "Eu entendo. Enviarei a mensagem assim que voltar.",
  ui_story_1015_10150101_124_dialog_content = "Bom, quanto antes melhor. O que mais nos falta neste momento é tempo.",
  ui_story_1015_10150101_125_dialog_content = "Tenho um pressentimento de que a situação que imaginamos provavelmente se tornará realidade muito em breve.",
  ui_story_1015_10150101_126_dialog_content = "<color=#e8d9bb>Lumópolis, Corte Real</color>",
  ui_story_1015_10150101_127_dialog_content = "Suspirar...",
  ui_story_1015_10150101_128_dialog_content = "Carleen, você terminou seu relatório?",
  ui_story_1015_10150101_129_dialog_content = "Já.",
  ui_story_1015_10150101_130_dialog_content = "Você parece um pouco cansado.",
  ui_story_1015_10150101_131_dialog_content = "Falar com ele é uma tarefa cansativa.",
  ui_story_1015_10150101_132_dialog_content = "Eu acho que é uma perda de tempo. O que ele quer ouvir não tem quase nada a ver com o que eu quero dizer.",
  ui_story_1015_10150101_133_dialog_content = "Você está falando sobre o caso Crepúsculo, sim?",
  ui_story_1015_10150101_134_dialog_content = "Sim. Não entendo por que ele continua fazendo essas perguntas sobre alocação de recursos e estrutura organizacional.",
  ui_story_1015_10150101_135_dialog_content = "Claramente, os fatos que relatei a ele são—",
  ui_story_1015_10150101_136_dialog_content = "Esqueça. Eu não deveria reclamar dessas coisas.",
  ui_story_1015_10150101_137_dialog_content = "Sim, isso é o suficiente. Agora, vamos tomar um chá.",
  ui_story_1015_10150101_138_dialog_content = "Você tem planos para os próximos dias?",
  ui_story_1015_10150101_139_dialog_content = "Praticamente nada. O City Lord me pediu para ficar de prontidão em Lumopolis.",
  ui_story_1015_10150101_140_dialog_content = "Em espera? Ah, isso mesmo, é porque o <color=#FFB400>Exercício Militar Conjunto</color> está se aproximando rapidamente, não é?",
  ui_story_1015_10150101_141_dialog_content = "Sim, deveria ser.",
  ui_story_1015_10150101_142_dialog_content = "Você deve se preparar. Você é a estrela do show, sabia?",
  ui_story_1015_10150101_143_dialog_content = "Mas... eu me sinto um pouco inquieto no momento.",
  ui_story_1015_10150101_144_dialog_content = "O que foi?",
  ui_story_1015_10150101_145_dialog_content = "ainda não recebi notícias de PlayerName.",
  ui_story_1015_10150101_146_dialog_content = "Eu não sei como ele e Vice estão fazendo...",
  ui_story_1015_10150101_147_dialog_content = "Ah, é Carleen! Faz tanto tempo!",
  ui_story_1015_10150101_148_dialog_content = "De fato, já faz um tempo, Gronru. Espero não tê-lo incomodado com minha ligação repentina.",
  ui_story_1015_10150101_149_dialog_content = "Não, você ligou na hora certa.",
  ui_story_1015_10150101_150_dialog_content = "Acabei de fazer um grande avanço em meu trabalho em Soroz.",
  ui_story_1015_10150101_151_dialog_content = "Escute isso.",
  ui_story_1015_10150101_152_dialog_content = "Ativa, Soroz!",
  ui_story_1015_10150101_153_dialog_content = "Ativação do Soroz concluída.",
  ui_story_1015_10150101_154_dialog_content = "Você ouviu isso?!",
  ui_story_1015_10150101_155_dialog_content = "Eu ouvi, mas... Soroz não foi sempre capaz de ativar sem incidentes?",
  ui_story_1015_10150101_156_dialog_content = "Eu sei eu sei! Sempre fomos capazes de pilotá-lo, mas ele não possuía consciência antes, certo?",
  ui_story_1015_10150101_157_dialog_content = "Certo.",
  ui_story_1015_10150101_158_dialog_content = "Não se preocupe, seu Echo Template foi basicamente restaurado.",
  ui_story_1015_10150101_159_dialog_content = "Só que nós, aurorianos, não podemos nos comunicar diretamente com ele.",
  ui_story_1015_10150101_160_dialog_content = "Mas é só esperar PlayerName para voltar, então ele poderá falar com Soroz!",
  ui_story_1015_10150101_161_dialog_content = "Ah, isso mesmo! Na verdade, eu queria perguntar o que está acontecendo com PlayerName... e Vice, claro!",
  ui_story_1015_10150101_162_dialog_content = "O que aconteceu com eles depois que os vi pela última vez?",
  ui_story_1015_10150101_163_dialog_content = "Eles não entraram em contato comigo desde que voltei para Lumopolis.",
  ui_story_1015_10150101_164_dialog_content = "Bem, eu vi os relatórios deles.",
  ui_story_1015_10150101_165_dialog_content = "Eles disseram que entraram em uma Cidade Baixa secreta para se recuperar e podem ser forçados a escurecer por um tempo.",
  ui_story_1015_10150101_166_dialog_content = "Eles provavelmente entrarão em contato com você quando estiverem de volta com força total.",
  ui_story_1015_10150101_167_dialog_content = "Uma Cidade Baixa secreta?",
  ui_story_1015_10150101_168_dialog_content = "Sim. Não se preocupe, o nível de confidencialidade lá é bem alto.",
  ui_story_1015_10150101_169_dialog_content = "Acho que o nome era...",
  ui_story_1015_10150101_170_dialog_content = "Ah sim, é <color=#FFB400>Instituto X</color>.",
  ui_story_1015_10150101_171_dialog_content = "<color=#e8d9bb>Estação Ferroviária da Cidade de Gannon</color>",
  ui_story_1015_10150101_172_dialog_content = "Saia do caminho! Não consigo ver nada daqui de trás!",
  ui_story_1015_10150101_173_dialog_content = "Ei, isso não parece meio torto para você?",
  ui_story_1015_10150101_174_dialog_content = "Isso mesmo! Pendure nossa bandeira um pouco mais alto!",
  ui_story_1015_10150101_175_dialog_content = "Qual é a comoção aqui? O que eles estão olhando?",
  ui_story_1015_10150101_176_dialog_content = "Você não sabe? O Exercício Militar Conjunto está prestes a começar. Essas são as bandeiras das várias forças participantes voando à frente.",
  ui_story_1015_10150101_177_dialog_content = "Oh! É hora do Exercício Militar Conjunto novamente.",
  ui_story_1015_10150101_178_dialog_content = "O exercício deste ano deve ser bastante interessante. Os jornais fazem fila na recepção todos os dias em massa.",
  ui_story_1015_10150101_179_dialog_content = "Realmente? Há algo de especial no exercício militar deste ano?",
  ui_story_1015_10150101_180_dialog_content = "Claro. Haverá um participante Caelestite desta vez, pela primeira vez em mais de uma década.",
  ui_story_1015_10150101_181_dialog_content = "<color=#e8d9bb>Departamento de Inteligência da cidade de Gannon</color>",
  ui_story_1015_10150101_182_dialog_content = "<color=#e8d9bb>Toc, toc, toc..</color>",
  ui_story_1015_10150101_183_dialog_content = "Pode entrar.",
  ui_story_1015_10150101_184_dialog_content = "Coronel Yingel, há um telegrama urgente para você.",
  ui_story_1015_10150101_185_dialog_content = "Por favor, dê uma olhada em sua conveniência mais cedo.",
  ui_story_1015_10150101_186_dialog_content = "Um telegrama urgente?",
  ui_story_1015_10150101_187_dialog_content = "Tudo bem, entendo. Apenas deixe na minha mesa.",
  ui_story_1015_10150101_188_dialog_content = "Sim, senhora!",
  ui_story_1015_10150101_189_dialog_content = "Vamos ver de quem é este pedido urgente...",
  ui_story_1015_10150101_190_dialog_content = "Hum? Senhor Ulisses?",
  ui_story_1015_10150201_1_dialog_content = "Se apresse. Pare de enrolar.",
  ui_story_1015_10150201_2_dialog_content = "É melhor você andar mais rápido do que minha faca, se você sabe o que é bom para você.",
  ui_story_1015_10150201_3_dialog_content = "... Tá bem.",
  ui_story_1015_10150201_4_dialog_content = "Mas sério, temos que acordar tão cedo todos os dias?",
  ui_story_1015_10150201_5_dialog_content = "Faz tanto tempo que não tenho uma boa noite de sono.",
  ui_story_1015_10150201_6_dialog_content = "Claramente, mais de uma década de preguiça transformou você em um pirralho mimado chorão.",
  ui_story_1015_10150201_7_dialog_content = "Nossa programação não é severa de graça. Como você pode ver, os guardas já acordaram para seus turnos.",
  ui_story_1015_10150201_8_dialog_content = "*Suspiro* Quanto tempo isso vai durar?",
  ui_story_1015_10150201_9_dialog_content = "Temos um prazo claro.",
  ui_story_1015_10150201_10_dialog_content = "Você deve ter ouvido: Illumina está se preparando para um evento chamado Joint Military Exercise. Ambos receberão um convite.",
  ui_story_1015_10150201_11_dialog_content = "Se você não estiver presente quando o evento começar, a Illumina com certeza enviará alguém para causar problemas.",
  ui_story_1015_10150201_12_dialog_content = "Então, esse é o nosso prazo.",
  ui_story_1015_10150201_13_dialog_content = "(Certo, o Exercício Militar Conjunto! Vai ser isso que vai nos salvar aqui?)",
  ui_story_1015_10150201_14_dialog_content = "A boa notícia para você é que esse sequestro não vai durar muito.",
  ui_story_1015_10150201_15_dialog_content = "A má notícia é que, se o experimento não for concluído com sucesso dentro do prazo, suas vidas serão significativamente mais curtas do que você esperava.",
  ui_story_1015_10150201_16_dialog_content = "...",
  ui_story_1015_10150201_17_dialog_content = "Não desperdice meu tempo. Dessa forma, você pode se manter vivo.",
  ui_story_1015_10150201_18_dialog_content = "Ei, pare de me empurrar! Eu sei o caminho!",
  ui_story_1015_10150201_19_dialog_content = "Já fui ao laboratório tantas vezes.",
  ui_story_1015_10150201_20_dialog_content = "Não quero perder muito tempo com nada não relacionado ao experimento.",
  ui_story_1015_10150201_21_dialog_content = "Concentre-se e nem pense em tentar revelar nosso paradeiro.",
  ui_story_1015_10150201_22_dialog_content = "Se você tentar gritar por ajuda como fez antes, eu prometo, vou cortar sua língua.",
  ui_story_1015_10150201_23_dialog_content = "Nós entendemos. Veja, estamos fazendo exatamente como você pediu desta vez.",
  ui_story_1015_10150201_24_dialog_content = "As rotas de patrulha e os turnos dos guardas são fixos. Não haverá contratempos...",
  ui_story_1015_10150201_25_dialog_content = "...",
  ui_story_1015_10150201_26_dialog_content = "<size=50>Uau!</size> Isso é...",
  ui_story_1015_10150201_27_dialog_content = "<size=50><anim type=Shake>Rugido!!!</anim></size>",
  ui_story_1015_10150201_28_dialog_content = "Forsakin, seu cachorro está nos seguindo de novo.",
  ui_story_1015_10150201_29_dialog_content = "Deixe-me dizer mais uma vez, Jade não é um cachorro.",
  ui_story_1015_10150201_30_dialog_content = "Multar. Seu animal de estimação.",
  ui_story_1015_10150201_31_dialog_content = "Ter uma coisa tão grande nos seguindo não é meio chamativo?",
  ui_story_1015_10150201_32_dialog_content = "Vamos precisar de ajuda com a pesquisa de hoje. Por isso chamei aqui.",
  ui_story_1015_10150201_33_dialog_content = "Pesquisar...",
  ui_story_1015_10150201_34_dialog_content = "Agora que você mencionou, isso também é resultado de sua pesquisa?",
  ui_story_1015_10150201_35_dialog_content = "...",
  ui_story_1015_10150201_36_dialog_content = "Para começar, que tipo de animal era Jade?",
  ui_story_1015_10150201_37_dialog_content = "Uma chinchila.",
  ui_story_1015_10150201_38_dialog_content = "Uma chinchila?!",
  ui_story_1015_10150201_39_dialog_content = "Você transformou um animalzinho tão fofo nisso...?",
  ui_story_1015_10150201_40_dialog_content = "Palavras como \"fofo\" e \"pequeno\" simplesmente demonstram a arrogância de sua perspectiva do suposto topo da cadeia alimentar.",
  ui_story_1015_10150201_41_dialog_content = "Hã?",
  ui_story_1015_10150201_42_dialog_content = "Como são vocês que determinam a vida e a morte de outras criaturas, a capacidade delas de agradá-los torna-se uma vantagem.",
  ui_story_1015_10150201_43_dialog_content = "Na natureza, o tamanho da chinchila sem dúvida limita sua capacidade de ocupar um nicho ecológico superior.",
  ui_story_1015_10150201_44_dialog_content = "E agora Jade superou essa limitação.",
  ui_story_1015_10150201_45_dialog_content = "De que maneira, exatamente?",
  ui_story_1015_10150201_46_dialog_content = "Simplificando, agora ele tem uma gama mais rica de opções de predação.",
  ui_story_1015_10150201_47_dialog_content = "Momento perfeito, agora é hora de entrarmos em batalha com os soldados que guardam o portão.",
  ui_story_1015_10150201_48_dialog_content = "Ei! Você não está planejando alimentar o seu animal de estimação com os soldados, está?!",
  ui_story_1015_10150201_49_dialog_content = "Concordamos em ajudá-lo a lutar, mas não colocaremos em risco a vida dos soldados!",
  ui_story_1015_10150201_50_dialog_content = "Você parece tão despreocupado com o futuro de toda uma raça, mas se importa tanto com a perda de uma ou duas vidas insignificantes.",
  ui_story_1015_10150201_51_dialog_content = "Multar. Não estou interessado em corrigir suas falhas.",
  ui_story_1015_10150201_52_dialog_content = "Você pode realmente dizer que algumas vidas não são importantes? Eles-",
  ui_story_1015_10150201_53_dialog_content = "Assim como antes, você deve me fornecer dados de combate, Caelestite.",
  ui_story_1015_10150201_54_dialog_content = "O laboratório reforçou suas defesas. Esta batalha será mais difícil do que da última vez.",
  ui_story_1015_10150201_55_dialog_content = "Eu posso segurar mais do que o meu no campo de batalha. Você realmente deveria considerar me deixar lutar.",
  ui_story_1015_10150201_56_dialog_content = "Quanto a você, fique onde está e não faça nada a menos que eu mande, caso contrário, vou garantir que você se torne a primeira mordida de Jade no café da manhã.",
  ui_story_1015_10150201_57_dialog_content = "Hunf.",
  ui_story_1015_10150201_58_dialog_content = "Celestita, fique nos meus calcanhares.",
  ui_story_1015_10150201_59_dialog_content = "Vamos terminar isso.",
  ui_story_1015_10150302_1_dialog_content = "<color=#e8d9bb>Baque-</color>",
  ui_story_1015_10150302_2_dialog_content = "Não, não, não, pare! Não vá muito duro com eles!",
  ui_story_1015_10150302_3_dialog_content = "O que vamos fazer se isso os ferir gravemente?!",
  ui_story_1015_10150302_4_dialog_content = "Acabou. Mova esses soldados inconscientes para um lado.",
  ui_story_1015_10150302_5_dialog_content = "Não deixe que os soldados de patrulha os descubram, pelo menos enquanto estivermos conduzindo o experimento.",
  ui_story_1015_10150302_6_dialog_content = "<size=45><anim type=Shake>Graa!</anim></size>",
  ui_story_1015_10150302_7_dialog_content = "Seja gentil com eles!",
  ui_story_1015_10150302_8_dialog_content = "Apenas deixe-me cuidar disso.",
  ui_story_1015_10150302_9_dialog_content = "Rapidamente. Pare de perder tempo.",
  ui_story_1015_10150302_10_dialog_content = "Eu sei eu sei. Esta não é a minha primeira vez.",
  ui_story_1015_10150302_11_dialog_content = "Desculpe por ajudar Forsakin a bater em vocês.",
  ui_story_1015_10150302_12_dialog_content = "Huh? Um monte de coisas simplesmente caiu no chão.",
  ui_story_1015_10150302_13_dialog_content = "Vamos colocar tudo isso de volta em seus bolsos.",
  ui_story_1015_10150302_14_dialog_content = "Faca... chaves... cartão-chave...",
  ui_story_1015_10150302_15_dialog_content = "O que é isso? Uma caixa de costura?",
  ui_story_1015_10150302_16_dialog_content = "Acho que posso abri-lo.",
  ui_story_1015_10150302_17_dialog_content = "<size=45>!!!</size>",
  ui_story_1015_10150302_18_dialog_content = "Ah, é um <color=#FFB400>isqueiro</color>...",
  ui_story_1015_10150302_19_dialog_content = "<size=50><anim type=Shake>Rugido!</anim></size>",
  ui_story_1015_10150302_20_dialog_content = "Uau! O que você está fazendo, Jade?!",
  ui_story_1015_10150302_21_dialog_content = "<size=45><anim type=Shake>Graa!</anim></size>",
  ui_story_1015_10150302_22_dialog_content = "<color=#e8d9bb>Rachadura!</color>",
  ui_story_1015_10150302_23_dialog_content = "Pisou no isqueiro?",
  ui_story_1015_10150302_24_dialog_content = "É apenas um isqueiro. Qual é o problema?",
  ui_story_1015_10150302_25_dialog_content = "...",
  ui_story_1015_10150302_26_dialog_content = "A área ao redor do laboratório é altamente inflamável. Mesmo a menor faísca pode significar um desastre.",
  ui_story_1015_10150302_27_dialog_content = "Não deixe nada disso acontecer novamente.",
  ui_story_1015_10150302_28_dialog_content = "Certo...",
  ui_story_1015_10150302_29_dialog_content = "(Se esse for realmente o caso, por que os guardas ainda podem carregar isqueiros?)",
  ui_story_1015_10150302_30_dialog_content = "Vamos. Pare de perder tempo.",
  ui_story_1015_10150302_31_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_1015_10150302_32_dialog_content = "A porta está aberta. Agora entre.",
  ui_story_1015_10150302_33_dialog_content = "Vá em frente e espere por mim lá.",
  ui_story_1015_10150302_34_dialog_content = "O que está fazendo?",
  ui_story_1015_10150302_35_dialog_content = "Você está... mudando a senha da porta?",
  ui_story_1015_10150302_36_dialog_content = "... Tsk.",
  ui_story_1015_10150302_37_dialog_content = "(Provavelmente é para evitar que os guardas o alcancem, usando a trava para ganhar tempo.)",
  ui_story_1015_10150302_38_dialog_content = "Hmm... Essas portas deveriam parar pessoas como nós, mas agora elas estão sendo usadas para parar os guardas.",
  ui_story_1015_10150302_39_dialog_content = "Máquinas não possuem consciência. Eles só servem para quem sabe usá-los.",
  ui_story_1015_10150302_40_dialog_content = "Você parece conhecer este lugar muito bem.",
  ui_story_1015_10150302_41_dialog_content = "Hum?",
  ui_story_1015_10150302_42_dialog_content = "Você pode se infiltrar no instituto de pesquisa, familiarizar-se com o layout interno e até obter acesso à maioria das portas e máquinas.",
  ui_story_1015_10150302_43_dialog_content = "As medidas de segurança da Illumina são uma piada aos seus olhos.",
  ui_story_1015_10150302_44_dialog_content = "Essas eram todas as pré-condições necessárias para que eu implementasse meu plano.",
  ui_story_1015_10150302_45_dialog_content = "Se eu não pudesse fazer isso, não estaria aqui agora.",
  ui_story_1015_10150302_46_dialog_content = "Mas como? Porque você costumava ser um pesquisador da Illumina?",
  ui_story_1015_10150302_47_dialog_content = "Porque eu mesmo construí este instituto de pesquisa.",
  ui_story_1015_10150302_48_dialog_content = "O quê?!",
  ui_story_1015_10150302_49_dialog_content = "Você o construiu...",
  ui_story_1015_10150302_50_dialog_content = "Na época, chamava-se Undercity X.",
  ui_story_1015_10150302_51_dialog_content = "Certo, a senha foi redefinida.",
  ui_story_1015_10150302_52_dialog_content = "É hora de começar o experimento de hoje.",
  ui_story_1015_10150302_53_dialog_content = "Uau, realmente há um Chord Link aqui!",
  ui_story_1015_10150302_54_dialog_content = "Embora existam algumas diferenças entre este e o do Obelisco do Retorno, é claramente a mesma coisa.",
  ui_story_1015_10150302_55_dialog_content = "A Illumina vem realizando pesquisas secretas sobre ele há muitos anos, sob um alto grau de confidencialidade.",
  ui_story_1015_10150302_56_dialog_content = "Apenas os fósseis antigos do Comitê e do Conselho Científico tiveram acesso permitido.",
  ui_story_1015_10150302_57_dialog_content = "Eu me pergunto o quão longe a pesquisa da Illumina progrediu...",
  ui_story_1015_10150302_58_dialog_content = "Você nunca nos deixou entrar aqui antes... Por que você mudou de ideia hoje?",
  ui_story_1015_10150302_59_dialog_content = "Porque minha pesquisa avançou para o próximo estágio.",
  ui_story_1015_10150302_60_dialog_content = "A Illumina investiu décadas de pesquisa para encontrar uma maneira de usar esse instrumento, mas não tenho muito tempo.",
  ui_story_1015_10150302_61_dialog_content = "Então, eu preciso usar a experimentação eficiente para aprender seus métodos.",
  ui_story_1015_10150302_62_dialog_content = "O que você quer chegar?",
  ui_story_1015_10150302_63_dialog_content = "Quero ativar o Chord Link para entender os princípios de seu funcionamento.",
  ui_story_1015_10150302_64_dialog_content = "Você sabe por que eu trouxe você aqui?",
  ui_story_1015_10150302_65_dialog_content = "Ativar o link de acordes? Em quem você quer usar?!",
  ui_story_1015_10150302_66_dialog_content = "Eu preparei uma cobaia com antecedência, é claro.",
  ui_story_1015_10150302_67_dialog_content = "Você...",
  ui_story_1015_10150302_68_dialog_content = "Não! não toque Vice!!!",
  ui_story_1015_10150302_69_dialog_content = "Jade.",
  ui_story_1015_10150302_70_dialog_content = "<size=50><anim type=Shake>Rugido!!!</anim></size>",
  ui_story_1015_10150302_71_dialog_content = "Urgh... É tão... pesado...",
  ui_story_1015_10150302_72_dialog_content = "L-Deixe ir Vice! Não mexa com essa coisa se você ainda não descobriu como usá-la!",
  ui_story_1015_10150302_73_dialog_content = "O objetivo deste assunto de teste é me ajudar a esclarecer exatamente como usá-lo.",
  ui_story_1015_10150302_74_dialog_content = "A pesquisa científica envolve alcançar a escuridão, onde a mão deve ser picada e arranhada para determinar a forma do mundo.",
  ui_story_1015_10150302_75_dialog_content = "Se não tentarmos, a ciência nunca avançará.",
  ui_story_1015_10150302_76_dialog_content = "Se você acha que este é um empreendimento tão nobre, por que não tenta você mesmo ?!",
  ui_story_1015_10150302_77_dialog_content = "Ao usar a si mesmo como cobaia, você só pode falhar uma vez, mas pode falhar inúmeras vezes ao usar cobaias descartáveis.",
  ui_story_1015_10150302_78_dialog_content = "A pesquisa científica não é uma aposta única. Claro que vou precisar de quantas oportunidades forem necessárias.",
  ui_story_1015_10150302_79_dialog_content = "<size=45>Você... desprezível...</size>",
  ui_story_1015_10150302_80_dialog_content = "Perder Vice, espero que esteja pronto.",
  ui_story_1015_10150302_81_dialog_content = "Isso acontecerá exatamente como na primeira vez que você usou o Chord Link.",
  ui_story_1015_10150302_82_dialog_content = "Solte-me, você!",
  ui_story_1015_10150302_83_dialog_content = "A execução do teste Chord Link, a câmara de teste e o objeto estão prontos.",
  ui_story_1015_10150302_84_dialog_content = "Vamos começar o experimento.",
  ui_story_1015_10150302_85_dialog_content = "Policial Ulysses, não é assim que devemos proceder.",
  ui_story_1015_10150302_86_dialog_content = "Pedimos aos guardas que intensifiquem suas patrulhas e buscas direcionadas, mas ainda não conseguiram localizar o intruso.",
  ui_story_1015_10150302_87_dialog_content = "Nosso pessoal está agora em estado de pânico e muitos dos pesquisadores estão com muito medo de voltar ao laboratório.",
  ui_story_1015_10150302_88_dialog_content = "Você conseguiu descobrir a identidade do intruso?",
  ui_story_1015_10150302_89_dialog_content = "Tenho certeza de que, como você adivinhou anteriormente, é Forsakin.",
  ui_story_1015_10150302_90_dialog_content = "Não tenho ideia de como ela invadiu. Ela não apenas conseguiu escapar de nossas buscas, mas também parece capaz de burlar todas as nossas medidas de segurança.",
  ui_story_1015_10150302_91_dialog_content = "Além disso, alguns soldados afirmam ter visto o celestita, que está incomunicável há dias. Ele poderia realmente ser o homem de Forsakin por dentro?",
  ui_story_1015_10150302_92_dialog_content = "Se for Forsakin, ela não precisa de alguém de dentro.",
  ui_story_1015_10150302_93_dialog_content = "O quê?",
  ui_story_1015_10150302_94_dialog_content = "Forsakin conhece este lugar melhor do que ninguém. Foi ela quem construiu o Instituto X.",
  ui_story_1015_10150302_95_dialog_content = "Ela o construiu? Pensei que eras tu...",
  ui_story_1015_10150302_96_dialog_content = "Onze anos atrás, Forsakin ainda era membro da Illumina e era a pesquisadora mais promissora de sua geração.",
  ui_story_1015_10150302_97_dialog_content = "Ela me enviou um pedido - ela queria assumir secretamente uma cidade abandonada sem nome.",
  ui_story_1015_10150302_98_dialog_content = "Ela o nomeou Undercity X, o precursor deste instituto de pesquisa.",
  ui_story_1015_10150302_99_dialog_content = "Entendi.",
  ui_story_1015_10150302_100_dialog_content = "Então, quando Forsakin finalmente desertou da Illumina, o instituto de pesquisa evoluiu para o que é agora?",
  ui_story_1015_10150302_101_dialog_content = "Você pode dizer isso.",
  ui_story_1015_10150302_102_dialog_content = "Ela é muito talentosa, mas o talento pode ser uma coisa assustadora.",
  ui_story_1015_10150302_103_dialog_content = "Isso a diferenciava das pessoas comuns, levando-a a realizar constantemente experimentos radicais e perigosos.",
  ui_story_1015_10150302_104_dialog_content = "Através de seus métodos, Undercity X dominou a biotecnologia mais avançada da Federação Illumina.",
  ui_story_1015_10150302_105_dialog_content = "Mas, ao mesmo tempo, o perigo representado por seu trabalho aumentava constantemente.",
  ui_story_1015_10150302_106_dialog_content = "No final, nem ela nem Illumina foram capazes de suportar.",
  ui_story_1015_10150302_107_dialog_content = "Lembro-me de ouvir que ela foi demitida após um grande acidente ocorrido durante um de seus experimentos...",
  ui_story_1015_10150302_108_dialog_content = "Sim, um grande incêndio destruiu Undercity X.",
  ui_story_1015_10150302_109_dialog_content = "Mas este acidente foi apenas o gatilho. Apenas levou funcionários de alto escalão a investigar os segredos de Forsakin.",
  ui_story_1015_10150302_110_dialog_content = "O que realmente a tornou intolerável aos olhos da Illumina foi a natureza controversa e incontrolável de sua pesquisa.",
  ui_story_1015_10150302_111_dialog_content = "Se a fonte não for extinta, o fogo só queimará mais forte e feroz.",
  ui_story_1015_10150302_112_dialog_content = "De fato. As consequências seriam inimagináveis se este acidente tivesse ocorrido em Gannon City.",
  ui_story_1015_10150302_113_dialog_content = "Mas se for esse o caso... por que Undercity X não foi abandonada após um incidente tão devastador?",
  ui_story_1015_10150302_114_dialog_content = "Existem muitas outras cidades subterrâneas que podem servir como locais de pesquisa, não é?",
  ui_story_1015_10150302_115_dialog_content = "Ah... Bem, é por isso que eu disse que o talento pode ser uma coisa terrível.",
  ui_story_1015_10150302_116_dialog_content = "Não importa o quão antiéticos e prejudiciais esses experimentos possam ter sido, eles não poderiam ofuscar as realizações notáveis de sua pesquisa.",
  ui_story_1015_10150302_117_dialog_content = "Afinal, eu também sou bastante parecido com ela.",
  ui_story_1015_10150302_118_dialog_content = "Eu não suportaria negligenciar o que ela deixou para trás.",
  ui_story_1015_10150302_119_dialog_content = "Entendo...",
  ui_story_1015_10150302_120_dialog_content = "Após o incidente, reconstruí a Cidade Baixa danificada, que se tornou o atual Instituto X.",
  ui_story_1015_10150302_121_dialog_content = "Com a ajuda dos instrumentos e conquistas que Forsakin nos deixou, a pesquisa de Illumina no campo da biologia avançou aos trancos e barrancos.",
  ui_story_1015_10150302_122_dialog_content = "Então, de certa forma, parece que ela fez algo de bom para Illumina.",
  ui_story_1015_10150302_123_dialog_content = "Tudo tem um preço, e agora é hora de pagarmos.",
  ui_story_1015_10150302_124_dialog_content = "Embora o Instituto X tenha sido completamente renovado, suas propriedades e princípios fundamentais permanecem.",
  ui_story_1015_10150302_125_dialog_content = "Aos olhos de Forsakin, nós apenas rebobinamos sua caixa de música e demos um novo visual.",
  ui_story_1015_10150302_126_dialog_content = "Se ela quiser tocar sua própria música, ela pode simplesmente estender a mão e dedilhar as palhetas.",
  ui_story_1015_10150401_1_dialog_content = "Então... a situação aqui ficou perigosa.",
  ui_story_1015_10150401_2_dialog_content = "Embora tenhamos uma vantagem em termos de força militar, nossa eficácia em combate tornou-se unidimensional.",
  ui_story_1015_10150401_3_dialog_content = "Forsakin está familiarizado com o layout do instituto e nunca nos dará a oportunidade de concentrar nossas tropas e cercá-lo.",
  ui_story_1015_10150401_4_dialog_content = "Ela pode fazer praticamente o que quiser aqui...",
  ui_story_1015_10150401_5_dialog_content = "Isso mesmo. Os guardas não podem tocá-la.",
  ui_story_1015_10150401_6_dialog_content = "Ninguém aqui possui a capacidade de combate individual para competir com ela. Não importa quantos guardas tenhamos, eles são praticamente inúteis.",
  ui_story_1015_10150401_7_dialog_content = "Não podemos continuar assim...",
  ui_story_1015_10150401_8_dialog_content = "Senhor, talvez devêssemos pedir ajuda a Gannon.",
  ui_story_1015_10150401_9_dialog_content = "Se conseguirmos garantir reforços adequados, definitivamente...",
  ui_story_1015_10150401_10_dialog_content = "Não.",
  ui_story_1015_10150401_11_dialog_content = "Por que, senhor?",
  ui_story_1015_10150401_12_dialog_content = "Não é uma questão tão simples.",
  ui_story_1015_10150401_13_dialog_content = "Se buscar ajuda pudesse resolver esse problema, eu já teria relatado a situação à cidade de Gannon e certamente não precisaria que você me sugerisse isso.",
  ui_story_1015_10150401_14_dialog_content = "Não entendo...",
  ui_story_1015_10150401_15_dialog_content = "Este é um instituto de pesquisa secreto e tudo sobre este lugar deve ser mantido em sigilo.",
  ui_story_1015_10150401_16_dialog_content = "Deixar os militares saberem não é uma opção. Não se esqueça das circunstâncias da demissão de Forsakin.",
  ui_story_1015_10150401_17_dialog_content = "... Sim senhor.",
  ui_story_1015_10150401_18_dialog_content = "Eu não havia considerado isso, apenas senti que o assunto em questão era mais importante.",
  ui_story_1015_10150401_19_dialog_content = "Forsakin é uma ex-pesquisadora, ela se infiltra no instituto para realizar seus experimentos.",
  ui_story_1015_10150401_20_dialog_content = "No final, isso é apenas um conflito entre cientistas.",
  ui_story_1015_10150401_21_dialog_content = "Assim que envolvermos os militares, o assunto assumirá outra forma.",
  ui_story_1015_10150401_22_dialog_content = "Sim, entendi.",
  ui_story_1015_10150401_23_dialog_content = "Você realmente entende?",
  ui_story_1015_10150401_24_dialog_content = "...",
  ui_story_1015_10150401_25_dialog_content = "Heh, você é um soldado justo afinal de contas, executar ordens é tudo o que é exigido de você. Não há necessidade de você entender meus pensamentos completamente.",
  ui_story_1015_10150401_26_dialog_content = "Pense em tudo isso como um experimento.",
  ui_story_1015_10150401_27_dialog_content = "De acordo com os regulamentos, o conteúdo do experimento deve ser mantido em sigilo para o público. Entender?",
  ui_story_1015_10150401_28_dialog_content = "Sim, senhor!",
  ui_story_1015_10150401_29_dialog_content = "Tudo bem, agora vamos falar sobre algo que você pode realmente entender.",
  ui_story_1015_10150401_30_dialog_content = "Optar por não buscar reforços de Gannon não significa que vou simplesmente sentar aqui esperando a destruição iminente.",
  ui_story_1015_10150401_31_dialog_content = "Eu também tenho minha própria maneira de lidar com Forsakin.",
  ui_story_1015_10150401_32_dialog_content = "Você tem um plano? Você quer dizer...",
  ui_story_1015_10150401_33_dialog_content = "<color=#e8d9bb>Toc, toc, toc..</color>",
  ui_story_1015_10150401_34_dialog_content = "Pode entrar.",
  ui_story_1015_10150401_35_dialog_content = "Coronel Oficial de Inteligência Illumina Yingel, relatando, senhor!",
  ui_story_1015_10150401_36_dialog_content = "<color=#e8d9bb>Bip Bip-</color>",
  ui_story_1015_10150401_37_dialog_content = "Então é assim que funciona...",
  ui_story_1015_10150401_38_dialog_content = "Sim, mudar apenas a estrutura corporal é inútil.",
  ui_story_1015_10150401_39_dialog_content = "Não é aqui que está o rastro do Lumina. Está escondido mais fundo...",
  ui_story_1015_10150401_40_dialog_content = "(Vice! Como você se sente agora?)",
  ui_story_1015_10150401_41_dialog_content = "(Você está machucado?)",
  ui_story_1015_10150401_42_dialog_content = "(Estou bem, só sinto que há uma força reorganizando o Lumina dentro de mim.)",
  ui_story_1015_10150401_43_dialog_content = "(Sério? Acho que isso é bom o suficiente por enquanto. Espero que nada dê errado...)",
  ui_story_1015_10150401_44_dialog_content = "(Não se preocupe muito. Afinal, este não é meu primeiro encontro com o Chord Link.)",
  ui_story_1015_10150401_45_dialog_content = "(Mas...)",
  ui_story_1015_10150401_46_dialog_content = "(Ei, escute, você não acha que isso pode ser uma oportunidade?)",
  ui_story_1015_10150401_47_dialog_content = "(Uma oportunidade?)",
  ui_story_1015_10150401_48_dialog_content = "(O Chord Link pode aumentar o poder de um auroriano, certo?)",
  ui_story_1015_10150401_49_dialog_content = "(Talvez eu possa usar esse aprimoramento para me libertar dessas cordas.)",
  ui_story_1015_10150401_50_dialog_content = "(Você vai tentar se livrar dessas cordas! Você consegue mesmo?)",
  ui_story_1015_10150401_51_dialog_content = "(Não deveria ser impossível. Eu provavelmente poderia fazer isso agora mesmo.)",
  ui_story_1015_10150401_52_dialog_content = "(No entanto, o verdadeiro problema é como vamos lidar com Forsakin e Jade depois que eu me libertar.)",
  ui_story_1015_10150401_53_dialog_content = "(Ainda preciso de mais energia. Só espero que os efeitos de aprimoramento do Chord Link funcionem.)",
  ui_story_1015_10150401_54_dialog_content = "(Hmm... a atenção de Forsakin está totalmente voltada para os dados. Esta é realmente uma boa oportunidade para um contra-ataque.)",
  ui_story_1015_10150401_55_dialog_content = "(Certo! Devemos dar a ela uma amostra de como sua pesquisa é eficaz!)",
  ui_story_1015_10150401_56_dialog_content = "(Teremos que trabalhar juntos para fazer isso. Só teremos uma chance.)",
  ui_story_1015_10150401_57_dialog_content = "(Seria melhor se pudéssemos subjugar Forsakin antes que ela pudesse reagir. Arrastá-la para uma batalha prolongada não seria bom para nós.)",
  ui_story_1015_10150401_58_dialog_content = "(Entendido. Vou procurar uma oportunidade de vencê-la de uma só vez.)",
  ui_story_1015_10150401_59_dialog_content = "(Tudo bem! Estou contando com você!)",
  ui_story_1015_10150401_60_dialog_content = "Forsakin, por quanto tempo esse experimento vai durar?",
  ui_story_1015_10150401_61_dialog_content = "A cauda de Jade é tão pesada que não consigo respirar com seu peso.",
  ui_story_1015_10150401_62_dialog_content = "Breve. Mantenha o silêncio.",
  ui_story_1015_10150401_63_dialog_content = "Quanto tempo é logo? Você não pode me dar um tempo preciso?",
  ui_story_1015_10150401_64_dialog_content = "Estamos na fase final.",
  ui_story_1015_10150401_65_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1015_10150401_66_dialog_content = "(PlayerName! Eu posso sentir o fluxo Lumina começando a acelerar!)",
  ui_story_1015_10150401_67_dialog_content = "(Prepare-se. Podemos agir assim que o aprimoramento for concluído!)",
  ui_story_1015_10150401_68_dialog_content = "(Tudo bem!)",
  ui_story_1015_10150401_69_dialog_content = "(No momento em que você se libertar, ataque Forsakin primeiro. Jade tentará instintivamente ajudá-la, e então você...)",
  ui_story_1015_10150401_70_dialog_content = "A propósito, celestita.",
  ui_story_1015_10150401_71_dialog_content = "Huh? Você está falando comigo?",
  ui_story_1015_10150401_72_dialog_content = "Por que você só se preocupa com quanto tempo o experimento durará, mas não se ele foi concluído com sucesso?",
  ui_story_1015_10150401_73_dialog_content = "Eu...",
  ui_story_1015_10150401_74_dialog_content = "(Oh não... Eu entreguei o jogo?)",
  ui_story_1015_10150401_75_dialog_content = "(Vice, quanto tempo até que o aprimoramento esteja completo...?)",
  ui_story_1015_10150401_76_dialog_content = "Não se preocupe, o corpo de Vice não sofreu nenhuma alteração.",
  ui_story_1015_10150401_77_dialog_content = "Não houve feridos, nem as melhorias esperadas foram executadas.",
  ui_story_1015_10150401_78_dialog_content = "O experimento acabou.",
  ui_story_1015_10150401_79_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_1015_10150401_80_dialog_content = "(O que está acontecendo?! O aprimoramento parou?!)",
  ui_story_1015_10150401_81_dialog_content = "O-O que você fez?",
  ui_story_1015_10150401_82_dialog_content = "Acabei de desligar o Chord Link.",
  ui_story_1015_10150401_83_dialog_content = "Chegar a esta etapa do experimento é suficiente por hoje. Eu não esperava que nenhuma mudança desnecessária ocorresse na cobaia.",
  ui_story_1015_10150401_84_dialog_content = "A menos que vocês dois estivessem antecipando algo?",
  ui_story_1015_10150401_85_dialog_content = "(O que podemos fazer, Vice? Ela parece saber o que estávamos planejando...)",
  ui_story_1015_10150401_86_dialog_content = "(Não importa, esta é a única oportunidade que temos!)",
  ui_story_1015_10150401_87_dialog_content = "(Vou me libertar dessas cordas. Prepare-se para a ação!)",
  ui_story_1015_10150401_88_dialog_content = "Nada a dizer? Parece que enchi sua imaginação com algumas expectativas irrealistas.",
  ui_story_1015_10150401_89_dialog_content = "Hmph! Espere até eu nocauteá-lo, então você saberá o que é irreal.",
  ui_story_1015_10150401_90_dialog_content = "<color=#e8d9bb>Foto-</color>",
  ui_story_1015_10150401_91_dialog_content = "Então, você realmente conseguiu se libertar de suas cordas com a ajuda do Chord Link.",
  ui_story_1015_10150401_92_dialog_content = "Mas está tudo bem. Tal evento já foi contabilizado em minha avaliação de risco e plano de contingência.",
  ui_story_1015_10150401_93_dialog_content = "Eu te peguei uma vez, posso te pegar de novo.",
  ui_story_1015_10150401_94_dialog_content = "Vice! Ela está invocando Eclipsites escondidos!",
  ui_story_1015_10150401_95_dialog_content = "Agora!",
  ui_story_1015_10150502_1_dialog_content = "Suspiro... Suspiro...",
  ui_story_1015_10150502_2_dialog_content = "Não está funcionando...?",
  ui_story_1015_10150502_3_dialog_content = "Usando o aprimoramento do Chord Link para se libertar de suas cordas... Você realmente acredita que eu não previ isso?",
  ui_story_1015_10150502_4_dialog_content = "Não pense que isso é uma oportunidade. Eu me preparei para tudo.",
  ui_story_1015_10150502_5_dialog_content = "E você ainda tem tempo para bater papo durante a batalha.",
  ui_story_1015_10150502_6_dialog_content = "Esta não é uma batalha. A batalha já acabou.",
  ui_story_1015_10150502_7_dialog_content = "Não tenho tempo para entrar nessa farsa.",
  ui_story_1015_10150502_8_dialog_content = "O que faz você pensar que tem a palavra final nisso?!",
  ui_story_1015_10150502_9_dialog_content = "Bem, ele talvez tenha a palavra final?",
  ui_story_1015_10150502_10_dialog_content = "<size=45>Vice! Atrás de você!</size>",
  ui_story_1015_10150502_11_dialog_content = "O quê...?",
  ui_story_1015_10150502_12_dialog_content = "<size=45>Ahhhh-!</size>",
  ui_story_1015_10150502_13_dialog_content = "<size=45>Vice!!!</size>",
  ui_story_1015_10150502_14_dialog_content = "Helios... O que esse cara está fazendo aqui?!",
  ui_story_1015_10150502_15_dialog_content = "No momento, resistir é a decisão mais tola que você pode tomar.",
  ui_story_1015_10150502_16_dialog_content = "Sua chance de sucesso é zero. E sua interferência só vai atrasar o andamento do experimento.",
  ui_story_1015_10150502_17_dialog_content = "Não gosto quando as pessoas interferem em meus experimentos.",
  ui_story_1015_10150502_18_dialog_content = "O-o que você está fazendo?",
  ui_story_1015_10150502_19_dialog_content = "O experimento de hoje foi concluído. Sairemos daqui assim que terminar de organizar os dados.",
  ui_story_1015_10150502_20_dialog_content = "Vice irá com Helios, e você, comigo, Celestita. De agora em diante, vocês dois serão <color=#FFB400>separados</color>.",
  ui_story_1015_10150502_21_dialog_content = "Separados?!",
  ui_story_1015_10150502_22_dialog_content = "Pelo incidente de agora, posso ver que vocês dois ficando juntos formariam um fator instável.",
  ui_story_1015_10150502_23_dialog_content = "Como este é o caso, vocês terão que ficar longe um do outro no futuro.",
  ui_story_1015_10150502_24_dialog_content = "Escute bem, Yingel. Aqui está o que está acontecendo.",
  ui_story_1015_10150502_25_dialog_content = "Forsakin se infiltrou neste instituto de pesquisa e está fazendo o que quer com nosso equipamento.",
  ui_story_1015_10150502_26_dialog_content = "Além disso, o tenente Vice, que estava visitando o instituto de pesquisa na época, e o celestita, estão inacessíveis há vários dias.",
  ui_story_1015_10150502_27_dialog_content = "Com base nos relatos de testemunhas oculares dos soldados, especulo que Forsakin os sequestrou.",
  ui_story_1015_10150502_28_dialog_content = "PlayerName e Vice...",
  ui_story_1015_10150502_29_dialog_content = "Professor Ulysses, o que você precisa que eu faça?",
  ui_story_1015_10150502_30_dialog_content = "Resgate os reféns e capture Forsakin.",
  ui_story_1015_10150502_31_dialog_content = "<size=45>!!!</size>",
  ui_story_1015_10150502_32_dialog_content = "(Ele está realmente confiando uma tarefa tão difícil a um coronel?)",
  ui_story_1015_10150502_33_dialog_content = "... Aceito a missão.",
  ui_story_1015_10150502_34_dialog_content = "Mas, professor, com base na situação atual, a probabilidade de eu completar esta missão é muito baixa.",
  ui_story_1015_10150502_35_dialog_content = "Forsakin está familiarizada com o layout do site, ela é incrivelmente forte e fez reféns.",
  ui_story_1015_10150502_36_dialog_content = "Se eu tentasse isso sozinho, estaria em extrema desvantagem.",
  ui_story_1015_10150502_37_dialog_content = "Se eu pudesse me inscrever para usar o <color=#FFB400>arma</color>...",
  ui_story_1015_10150502_38_dialog_content = "você deseja Axelia para te ajudar, correto?",
  ui_story_1015_10150502_39_dialog_content = "... Sim.",
  ui_story_1015_10150502_40_dialog_content = "Você não deve confiar muito na força dela.",
  ui_story_1015_10150502_41_dialog_content = "Vocês dois foram participantes do <color=#FFB400>Programa Phospherus</color>, mas suas especialidades diferem.",
  ui_story_1015_10150502_42_dialog_content = "Esta missão não pode ser resolvida por meio de força bruta. Eu preciso que você faça uso de suas habilidades únicas.",
  ui_story_1015_10150502_43_dialog_content = "... Entendo, professora.",
  ui_story_1015_10150502_44_dialog_content = "Além disso, Axelia precisa se preparar para outra missão importante. Eu vou deixar você saber mais sobre isso em uma data posterior.",
  ui_story_1015_10150502_45_dialog_content = "Claro, ao lidar com tal inimigo, você precisa preparar bem sua mão.",
  ui_story_1015_10150502_46_dialog_content = "Felizmente, tenho dois trunfos para você.",
  ui_story_1015_10150502_47_dialog_content = "Por favor elabore.",
  ui_story_1015_10150502_48_dialog_content = "A primeira é o reforço.",
  ui_story_1015_10150502_49_dialog_content = "Selecionei um assistente confiável para você. Ele está vindo para cá agora.",
  ui_story_1015_10150502_50_dialog_content = "Isso é Anatoli, um dos oficiais de inteligência de confiança do Comitê.",
  ui_story_1015_10150502_51_dialog_content = "Eu sei dele! Ele certamente será de grande ajuda!",
  ui_story_1015_10150502_52_dialog_content = "Quanto ao outro trunfo...",
  ui_story_1015_10150502_53_dialog_content = "Eu quero que você segure isso até o fim.",
  ui_story_1015_10150601_1_dialog_content = "<color=#e8d9bb>Crepúsculo, Fortaleza Lumo</color>",
  ui_story_1015_10150601_2_dialog_content = "...",
  ui_story_1015_10150601_3_dialog_content = "<color=#e8d9bb>TOC Toc-</color>",
  ui_story_1015_10150601_4_dialog_content = "Entre!",
  ui_story_1015_10150601_5_dialog_content = "... Joselyne.",
  ui_story_1015_10150601_6_dialog_content = "O crepúsculo chegou e a oração está prestes a começar... Você está esperando por alguém?",
  ui_story_1015_10150601_7_dialog_content = "Parece que vim em má hora.",
  ui_story_1015_10150601_8_dialog_content = "Só estou esperando pelo relatório de inteligência. Este é o assunto mais urgente para o Ironthorn no momento.",
  ui_story_1015_10150601_9_dialog_content = "A situação na linha de frente não parece otimista, e um número crescente de assentamentos ao redor foi atacado por Eclipsites.",
  ui_story_1015_10150601_10_dialog_content = "Embora a Cidade Baixa tenha espaço mais do que suficiente para absorver os moradores desses assentamentos...",
  ui_story_1015_10150601_11_dialog_content = "Se as coisas continuarem assim, um dia perderemos nosso controle sobre este território.",
  ui_story_1015_10150601_12_dialog_content = "Sim. Não quero ver tal coisa acontecer.",
  ui_story_1015_10150601_13_dialog_content = "Os Eclipsitas continuam a se reunir, mas ainda não lançaram nenhum ataque em grande escala. Lumopolis e a Federação Illumina também não enviaram instruções para atacar.",
  ui_story_1015_10150601_14_dialog_content = "Os soldados já estão exaustos pela falta de ação. Esse tipo de espera estendida é realmente prejudicial para eles.",
  ui_story_1015_10150601_15_dialog_content = "Espero que a oração de hoje seja capaz de aliviar pelo menos um pouco a ansiedade de seus soldados.",
  ui_story_1015_10150601_16_dialog_content = "Obrigado, Joselyne.",
  ui_story_1015_10150601_17_dialog_content = "<color=#e8d9bb>TOC Toc-</color>",
  ui_story_1015_10150601_18_dialog_content = "Suspiro... Suspiro...",
  ui_story_1015_10150601_19_dialog_content = "Capitão Leo... Recebemos notícias da Illumina!",
  ui_story_1015_10150601_20_dialog_content = "Illumina enviou um sinal, ordenando que todas as tropas estacionadas se preparem imediatamente!",
  ui_story_1015_10150601_21_dialog_content = "Diz-me o que se passa! Rapidamente!",
  ui_story_1015_10150601_22_dialog_content = "It-It são os preparativos para o <color=#FFB400>Exercício Militar Conjunto</color>.",
  ui_story_1015_10150601_23_dialog_content = "?!?",
  ui_story_1015_10150601_24_dialog_content = "<color=#e8d9bb>Crepúsculo, Cidade Baixa Cogovernada</color>",
  ui_story_1015_10150601_25_dialog_content = "Este é um convite rotineiro para Crepúsculo?",
  ui_story_1015_10150601_26_dialog_content = "Sim senhor. Embora as datas dos exercícios militares dependam inteiramente dos superiores, isso ainda é considerado uma tradição.",
  ui_story_1015_10150601_27_dialog_content = "Eu vejo. Isso não é uma boa notícia para os soldados.",
  ui_story_1015_10150601_28_dialog_content = "De fato. Por que agora, de todos os tempos?!",
  ui_story_1015_10150601_29_dialog_content = "Sim. Os tambores da guerra levantaram seu moral e agora serão abafados pela fanfarra do exercício militar. Não importa quão grandioso seja o exercício militar, ele não pode ser comparado à emoção da batalha.",
  ui_story_1015_10150601_30_dialog_content = "O que diz a carta convite? Quantas pessoas precisamos enviar?",
  ui_story_1015_10150601_31_dialog_content = "Três pessoas. Um soldado Illumina, um Cavaleiro Lumo e um membro do clero. Com você isso faz...",
  ui_story_1015_10150601_32_dialog_content = "<color=#e8d9bb>Crepúsculo, Fortaleza Lumo</color>",
  ui_story_1015_10150601_33_dialog_content = "Eu vejo. Embora esta seja uma área cogovernada, está claro que você está insatisfeito com esta ordem de Illumina.",
  ui_story_1015_10150601_34_dialog_content = "Claro! Esses soldados Gannon estão seguindo formalidades estritas e pedindo aos outros que façam o mesmo onde quer que vão.",
  ui_story_1015_10150601_35_dialog_content = "A guerra na linha de frente é iminente... Por que precisamos cooperar apenas para satisfazer seus interesses?!",
  ui_story_1015_10150601_36_dialog_content = "A chegada desse convite foi, de fato, uma agradável surpresa.",
  ui_story_1015_10150601_37_dialog_content = "Uma agradável surpresa? Leo, você já tomou sua decisão?",
  ui_story_1015_10150601_38_dialog_content = "Sim. Vou.",
  ui_story_1015_10150601_39_dialog_content = "Capitão?!",
  ui_story_1015_10150601_40_dialog_content = "Se o exercício é um palco onde as forças do mundo se reúnem para serem vistas por todo o continente...",
  ui_story_1015_10150601_41_dialog_content = "A notícia da agitação na fronteira será divulgada em todo o continente.",
  ui_story_1015_10150601_42_dialog_content = "Capitão Leo...",
  ui_story_1015_10150601_43_dialog_content = "Farei alguns preparativos e depois me encontrarei com Joseph e Zhao.",
  ui_story_1015_10150601_44_dialog_content = "Quanto a quando Joseph e eu estivermos fora, deixarei tudo em suas mãos, Joselyne.",
  ui_story_1015_10150601_45_dialog_content = "Hmm, eu entendo.",
  ui_story_1015_10150601_46_dialog_content = "Lutando lado a lado com os Ironthorn Knights, trazendo energia calmante para as pessoas...",
  ui_story_1015_10150601_47_dialog_content = "Depois que você voltar, espero que me mostre sua mais completa gratidão.",
  ui_story_1015_10150601_48_dialog_content = "Haha, bem, claro.",
  ui_story_1015_10150601_49_dialog_content = "<color=#e8d9bb>Federação Illumina, em algum lugar na cidade de Gannon</color>",
  ui_story_1015_10150601_50_dialog_content = "Eu sou firmemente contra isso.",
  ui_story_1015_10150601_51_dialog_content = "Eu tenho o direito de contestar, não tenho?",
  ui_story_1015_10150601_52_dialog_content = "Sim, Grande Marechal, de acordo com os regulamentos do Conselho de Ciências, o Grande Marechal tem o direito de votar nas opiniões do Conselho.",
  ui_story_1015_10150601_53_dialog_content = "Você poderia, por favor, aconselhá-los a realizar uma votação o mais rápido possível?",
  ui_story_1015_10150601_54_dialog_content = "É o seguinte... Grande Marechal, a decisão de realizar um Exercício Militar Conjunto foi uma decisão tomada pelo Conselho após ponderar cuidadosamente os prós e os contras.",
  ui_story_1015_10150601_55_dialog_content = "Mesmo que você vote contra, os membros do Conselho não desistirão tão facilmente...",
  ui_story_1015_10150601_56_dialog_content = "Falar com você realmente é cansativo. Apenas diga a Ulysses para vir me ver.",
  ui_story_1015_10150601_57_dialog_content = "Sinto muito, mas o professor Ulysses disse que não o veria se viesse aqui para tratar desse assunto.",
  ui_story_1015_10150601_58_dialog_content = "Dane-se isso.",
  ui_story_1015_10150601_59_dialog_content = "Em primeiro lugar, nunca me interessei em me envolver nesse ridículo festival de exibicionismo a que vocês parecem tão inflexíveis em nos sujeitar.",
  ui_story_1015_10150601_60_dialog_content = "Da mesma forma, não desejo que minha implantação estratégica seja interrompida por quaisquer fatores redundantes.",
  ui_story_1015_10150601_61_dialog_content = "As ruínas de Aurora precisam do apoio militar de Illumina, mas, em vez disso, você as está privando de tropas e pessoal com este exercício militar!",
  ui_story_1015_10150601_62_dialog_content = "Isso é um absurdo completo!",
  ui_story_1015_10150601_63_dialog_content = "Perdoe-me, Grande Marechal, eu...",
  ui_story_1015_10150601_64_dialog_content = "Por que você está incomodando este pobre soldado?",
  ui_story_1015_10150601_65_dialog_content = "Se o velho Ulysses se recusa a sair, você pode falar comigo.",
  ui_story_1015_10150601_66_dialog_content = "Reinhardt, você parece confuso. Sugiro que se acalme um pouco. Que tal jogarmos uma partida de Joker?",
  ui_story_1015_10150601_67_dialog_content = "Senhora <color=#FFB400>máscara de ferro</color>...",
  ui_story_1015_10150601_68_dialog_content = "Isso não é engraçado, <color=#FFB400>belisaria</color>. Estou ainda menos interessado em jogar o Coringa com você agora.",
  ui_story_1015_10150601_69_dialog_content = "Estou bastante surpreso que você realmente tenha mostrado seu rosto aqui.",
  ui_story_1015_10150601_70_dialog_content = "Eu não estava brincando. Há um limite para o tempo e a paciência que estou disposto a estender.",
  ui_story_1015_10150601_71_dialog_content = "Escolha um cartão e diga sua peça dentro do prazo. Você pode fazer aquilo?",
  ui_story_1015_10150601_72_dialog_content = "...",
  ui_story_1015_10150601_73_dialog_content = "A esquerda.",
  ui_story_1015_10150601_74_dialog_content = "Meu ponto de vista é simples. Não apoio essa estratégia de evitar a realidade da guerra.",
  ui_story_1015_10150601_75_dialog_content = "Suspenda o Exercício Militar Conjunto e priorize o apoio às tropas estacionadas em Crepúsculo!",
  ui_story_1015_10150601_76_dialog_content = "Oh, desculpe, você desenhou o Coringa. Você perdeu.",
  ui_story_1015_10150601_77_dialog_content = "Fazer escolhas sem observação prévia parece ser uma característica comum entre os Grandes Marechais do passado e do presente.",
  ui_story_1015_10150601_78_dialog_content = "Reinhardt, a guerra não é um jogo em que se permite uma extravagância imprudente. É essencialmente um negócio.",
  ui_story_1015_10150601_79_dialog_content = "Ganhar ou perder é irrelevante. O que importa é o que você perde e o que você ganha.",
  ui_story_1015_10150601_80_dialog_content = "Você perdeu, então o tempo que posso dedicar a você termina aqui.",
  ui_story_1015_10150601_81_dialog_content = "Se você não consegue entender esse conceito, o Comitê encontrará outra pessoa que possa.",
  ui_story_1015_10150601_82_dialog_content = "...",
  ui_story_1015_10150601_83_dialog_content = "<color=#e8d9bb>*ranger de dentes*</color>",
  ui_story_1015_10150601_84_dialog_content = "<color=#e8d9bb>Jardins de Lumópolis</color>",
  ui_story_1015_10150601_85_dialog_content = "Como eu esperava, o Exercício Militar Conjunto da Illumina também está convocando pessoas de Dawn Academia.",
  ui_story_1015_10150601_86_dialog_content = "Hmph! Claro, nós Quatro Anjos não temos objeções. Por que não dar aos jovens iniciantes mais oportunidades de provar seu valor?",
  ui_story_1015_10150601_87_dialog_content = "Senhor Raphael... Claramente, você também é uma criança!",
  ui_story_1015_10150601_88_dialog_content = "Erm, de qualquer maneira, já que o capitão Carleen está no comando, não precisarei estar aparecendo.",
  ui_story_1015_10150601_89_dialog_content = "Aproveite esta oportunidade, Capitão! Esta é uma grande chance de completar o período probatório para sua reintegração de uma só vez!",
  ui_story_1015_10150601_90_dialog_content = "Além de você, quais outras crianças são mencionadas na carta-convite?",
  ui_story_1015_10150601_91_dialog_content = "É um pouco estranho como Dawn Academia recebeu quatro convites desta vez.",
  ui_story_1015_10150601_92_dialog_content = "Além de mim, há um para Chloe, Uriah... e Beretta.",
  ui_story_1015_10150601_93_dialog_content = "Mas, para ser honesto, não estou particularmente interessado neste Exercício Militar Conjunto.",
  ui_story_1015_10150601_94_dialog_content = "No último exercício militar, liderei minha equipe à vitória.",
  ui_story_1015_10150601_95_dialog_content = "E não preciso usar essa honra sem sentido para comprar de volta minha posição oficial.",
  ui_story_1015_10150601_96_dialog_content = "Ha! Eu sabia que você diria algo nesse sentido...",
  ui_story_1015_10150601_97_dialog_content = "Então... Beretta, você vai ficar bem? Você tem algum problema em trabalhar com Chloe e Uriah?",
  ui_story_1015_10150601_98_dialog_content = "O quê?!",
  ui_story_1015_10150601_99_dialog_content = "Espero que você possa assumir o comando e liderar a equipe Beretta para a vitória de Lumopolis.",
  ui_story_1015_10150601_100_dialog_content = "Esta não é a primeira vez que você sai de Lumopolis para realizar uma missão externa. Eu acho que você deve ser capaz de lidar com isso.",
  ui_story_1015_10150601_101_dialog_content = "Claro! Vou valorizar esta oportunidade!",
  ui_story_1015_10150601_102_dialog_content = "Ele Ele, Chloe e Uriah estão prestes a se encontrar nas mãos da pequena Beretta.",
  ui_story_1015_10150601_103_dialog_content = "Certifique-se de protegê-los bem!",
  ui_story_1015_10150601_104_dialog_content = "Pode deixar!",
  ui_story_1015_10150601_105_dialog_content = "No entanto... a única coisa que me deixa um pouco inseguro é a viagem para o Exercício Militar Conjunto.",
  ui_story_1015_10150601_106_dialog_content = "Ouvi dizer que as Cidades Subterrâneas de Illumina são como labirintos, e nunca estive em um antes...",
  ui_story_1015_10150601_107_dialog_content = "Ah, não precisa se preocupar com isso.",
  ui_story_1015_10150601_108_dialog_content = "Embora eu não esteja liderando sua equipe, ainda planejo ir para Gannon City com você.",
  ui_story_1015_10150601_109_dialog_content = "Ah, mas por quê?",
  ui_story_1015_10150601_110_dialog_content = "Bem... aqueles dois ali estão me preocupando...",
  ui_story_1015_10150701_1_dialog_content = "<color=#e8d9bb>Federação Illumina, Cidade Baixa X</color>",
  ui_story_1015_10150701_2_dialog_content = "Oficial de Inteligência da Federação Illumina Anatoli, apresentando-se para o serviço. Por ordem do Comitê, estou aqui para ajudá-lo, Coronel Yingel.",
  ui_story_1015_10150701_3_dialog_content = "Você também é um oficial de inteligência?",
  ui_story_1015_10150701_4_dialog_content = "Ah... eu te conheço. Você é o deputado que acompanhou o Grande Marechal a Eraveil um tempo atrás para lutar contra o Eclipse.",
  ui_story_1015_10150701_5_dialog_content = "Sim coronel Yingel, suas informações são realmente muito precisas. Estou ansioso por uma oportunidade de trabalhar com você há muito tempo.",
  ui_story_1015_10150701_6_dialog_content = "Chega de lisonja. Vamos nos preparar para a ação o mais rápido possível.",
  ui_story_1015_10150701_7_dialog_content = "O que você está anotando?",
  ui_story_1015_10150701_8_dialog_content = "Ah, este é o meu caderno. Acabei de fazer um esboço seu com uma nota: \"um coronel com uma personalidade direta\".",
  ui_story_1015_10150701_9_dialog_content = "Você... Bem, se é assim que você costuma agir, não vou interferir.",
  ui_story_1015_10150701_10_dialog_content = "Sua missão desta vez é trabalhar comigo para resgatar os reféns e capturar Forsakin.",
  ui_story_1015_10150701_11_dialog_content = "Desculpe interromper, coronel Yingel. Forsakin está... nesta Cidade Baixa? E quem são os reféns?",
  ui_story_1015_10150701_12_dialog_content = "Ahem... Deixe-me informá-lo sobre a situação atual.",
  ui_story_1015_10150701_13_dialog_content = "Forsakin, que Illumina uma vez quis, levou o tenente Vice e PlayerName.",
  ui_story_1015_10150701_14_dialog_content = "Ela também tentou se infiltrar no laboratório de pesquisa para conduzir seus experimentos.",
  ui_story_1015_10150701_15_dialog_content = "Acredito que suas ações devem estar relacionadas ao que aconteceu durante o conflito em Eraveil.",
  ui_story_1015_10150701_16_dialog_content = "Ela está interessada nas mudanças para Tenente Vice provocada pela tecnologia Caelestita.",
  ui_story_1015_10150701_17_dialog_content = "Se for esse o caso, os dois estão em uma situação muito perigosa!",
  ui_story_1015_10150701_18_dialog_content = "A rede de inteligência Illumina é intrincada e complexa. Com Forsakin sequestrando duas figuras proeminentes, não há como tal incidente passar despercebido.",
  ui_story_1015_10150701_19_dialog_content = "O que é preocupante é que o tenente Vice se separou de PlayerName.",
  ui_story_1015_10150701_20_dialog_content = "Assim, nossa operação será dividida em duas etapas.",
  ui_story_1015_10150701_21_dialog_content = "Estágio um: localizar o tenente Vice o mais rápido possível, e certifique-se de chegar até ela antes de Forsakin.",
  ui_story_1015_10150701_22_dialog_content = "Estágio dois: acabar com o plano de Forsakin. ela pode ter PlayerName, mas ela não ousaria tomar qualquer tipo de ação imprudente contra ele.",
  ui_story_1015_10150701_23_dialog_content = "Se tivermos uma oportunidade adequada, seria melhor capturarmos Forsakin de uma só vez.",
  ui_story_1015_10150701_24_dialog_content = "Sim, senhora! Eu entendo...",
  ui_story_1015_10150701_25_dialog_content = "O que você está fazendo agora?",
  ui_story_1015_10150701_26_dialog_content = "Estou desenhando um mapa com base em meus registros anteriores das pessoas envolvidas e nas ações desses indivíduos para prever seus próximos possíveis cursos de ação.",
  ui_story_1015_10150701_27_dialog_content = "... Você é realmente algo.",
  ui_story_1015_10150701_28_dialog_content = "<color=#e8d9bb>Bip Bip!</color>",
  ui_story_1015_10150701_29_dialog_content = "Ahn???",
  ui_story_1015_10150701_30_dialog_content = "(Este é... um novo visitante?)",
  ui_story_1015_10150701_31_dialog_content = "<color=#e8d9bb>Enquanto isso em Undercity X</color>",
  ui_story_1015_10150701_32_dialog_content = "...",
  ui_story_1015_10150701_33_dialog_content = "Não pare. Manter-se.",
  ui_story_1015_10150701_34_dialog_content = "O que foi?",
  ui_story_1015_10150701_35_dialog_content = "Quando você nos pediu para cooperar com você, você não disse que nossas vidas estariam em perigo.",
  ui_story_1015_10150701_36_dialog_content = "Você está falando sobre Vice? Não se preocupe, ela vai ficar bem. Como eu poderia voluntariamente permitir que ela morresse?",
  ui_story_1015_10150701_37_dialog_content = "Você deseja resistir, ou talvez retirar sua promessa de cumprimento?",
  ui_story_1015_10150701_38_dialog_content = "Por que eu deveria acreditar em você?!",
  ui_story_1015_10150701_39_dialog_content = "Você é tão incômodo.",
  ui_story_1015_10150701_40_dialog_content = "Toma isso.",
  ui_story_1015_10150701_41_dialog_content = "<color=#e8d9bb>Zumbido... Zumbido...</color>",
  ui_story_1015_10150701_42_dialog_content = "Então isso é para... Vice?",
  ui_story_1015_10150701_43_dialog_content = "Sim, todo povo Illumina carrega um <color=#FFB400>comunicador</color>. Esta é a banda de frequência dela. Eu estive conectado a isso o tempo todo.",
  ui_story_1015_10150701_44_dialog_content = "Hélio está com ela. Você terá a oportunidade de falar com ela e confirmar seu status em instantes.",
  ui_story_1015_10150701_45_dialog_content = "E agora?",
  ui_story_1015_10150701_46_dialog_content = "Agora, é claro, você vai me ajudar a me livrar desses soldados intrometidos.",
  ui_story_1015_10150702_1_dialog_content = "Olá, Vice, você pode me ouvir?",
  ui_story_1015_10150702_2_dialog_content = "PlayerName! Isso é você?!",
  ui_story_1015_10150702_3_dialog_content = "Você está aguentando bem, Vice?",
  ui_story_1015_10150702_4_dialog_content = "Estou bem. Só preso aqui por enquanto.",
  ui_story_1015_10150702_5_dialog_content = "Parece que não há nada além de um armazém vazio aqui.",
  ui_story_1015_10150702_6_dialog_content = "Um armazém?",
  ui_story_1015_10150702_7_dialog_content = "Eu o advirto para não se envolver em comunicação desnecessária.",
  ui_story_1015_10150702_8_dialog_content = "Se te dar comunicadores realmente aumenta os problemas que você me traz...",
  ui_story_1015_10150702_9_dialog_content = "OK, eu entendo! Podemos falar sobre outra coisa?",
  ui_story_1015_10150702_10_dialog_content = "Chega de conversa.",
  ui_story_1015_10150702_11_dialog_content = "Nosso destino está à frente, então vamos cuidar dos negócios primeiro.",
  ui_story_1015_10150702_12_dialog_content = "O que é este lugar? o que você está fazendo aqui?",
  ui_story_1015_10150702_13_dialog_content = "Não se preocupe, é apenas um grande <color=#FFB400>Sala de referência</color>. Assim que conseguir o que quero, podemos ir embora.",
  ui_story_1015_10150702_14_dialog_content = "Afinal, meu tempo é valioso.",
  ui_story_1015_10150702_15_dialog_content = "Então, por que ainda estamos parados aqui em vez de seguir em frente?",
  ui_story_1015_10150702_16_dialog_content = "Venha aqui.",
  ui_story_1015_10150702_17_dialog_content = "O que foi?",
  ui_story_1015_10150702_18_dialog_content = "Digitalizando informações faciais do visitante...",
  ui_story_1015_10150702_19_dialog_content = "Analisando dados de acesso...",
  ui_story_1015_10150702_20_dialog_content = "Acesso ao arquivo concedido.",
  ui_story_1015_10150702_21_dialog_content = "H-Como posso abri-lo?",
  ui_story_1015_10150702_22_dialog_content = "Eu não disse que todo o instituto de pesquisa costumava ser meu? No entanto, Ulysses fez algumas mudanças.",
  ui_story_1015_10150702_23_dialog_content = "Já que você conseguiu entrar na grande sala de conferências de Ulisses, certamente poderia me ajudar a abrir esta porta.",
  ui_story_1015_10150702_24_dialog_content = "(O monitor deve ter capturado Forsakin parado atrás de mim quando examinou meu rosto...)",
  ui_story_1015_10150702_25_dialog_content = "(Se alguém ver, não vai demorar...)",
  ui_story_1015_10150702_26_dialog_content = "Não demore. Entre aqui rapidamente.",
  ui_story_1015_10150702_27_dialog_content = "Você e Jade estão na porta. Feche-o e não crie problemas.",
  ui_story_1015_10150702_28_dialog_content = "Se alguém entrar de repente, Jade cuidará deles.",
  ui_story_1015_10150702_29_dialog_content = "... Pelo menos deixe-me saber qual arquivo você está procurando.",
  ui_story_1015_10150702_30_dialog_content = "Procuro dados que Ulisses nunca tornará públicos.",
  ui_story_1015_10150702_31_dialog_content = "Eu quero ver os dados de teste para o <color=#FFB400>Programa Phospherus</color>.",
  ui_story_1015_10150801_1_dialog_content = "<color=#e8d9bb>Não faz muito tempo...</color>",
  ui_story_1015_10150801_2_dialog_content = "Hum... Política de privacidade—concordo, termos do usuário—concordo!",
  ui_story_1015_10150801_3_dialog_content = "Atualize os arquivos necessários...",
  ui_story_1015_10150801_4_dialog_content = "<color=#e8d9bb>Bate, bate!</color>",
  ui_story_1015_10150801_5_dialog_content = "Entre...",
  ui_story_1015_10150801_6_dialog_content = "Tech Officer, uma garota que afirma ser a Capitã da Guarda de Lumopolis deseja vê-lo.",
  ui_story_1015_10150801_7_dialog_content = "Oh, a garota de Lumopolis. Diga a ela para ficar do lado esquerdo da tela inicial...",
  ui_story_1015_10150801_8_dialog_content = "Tela S-Iniciar?",
  ui_story_1015_10150801_9_dialog_content = "Ha! Desculpe, eu tenho jogos no cérebro!",
  ui_story_1015_10150801_10_dialog_content = "Hum? Carleen?",
  ui_story_1015_10150801_11_dialog_content = "Ele Ele! Sr. Cientista, é melhor você se comportar - a pessoa ao seu lado é o campeão do último Exercício Militar Conjunto, não sabia?",
  ui_story_1015_10150801_12_dialog_content = "Perdoe-me, mas devido a preocupações com a situação de Soroz, planejei vir aqui para confirmar a situação com você primeiro.",
  ui_story_1015_10150801_13_dialog_content = "A propósito, não são Vice e PlayerName aqui?",
  ui_story_1015_10150801_14_dialog_content = "Você diz Soroz? Ei, graças a sua viagem a Crepúsculo...",
  ui_story_1015_10150801_15_dialog_content = "Dê uma olhada! Já está em alta e pode até bater as asas.",
  ui_story_1015_10150801_16_dialog_content = "Depois de um pouco de conserto com a Illumina Tech, ela agora está de volta ao seu antigo estado de batalha, sem medo de bater.",
  ui_story_1015_10150801_17_dialog_content = "Obrigado por todos os melhores votos, senhorita Gronru.",
  ui_story_1015_10150801_18_dialog_content = "Ah, que pena... Sem PlayerName e seus serviços de tradução psíquica, não consigo ouvir Soroz me agradecendo agora!",
  ui_story_1015_10150801_19_dialog_content = "Se Soroz está bem, isso é simplesmente notável.",
  ui_story_1015_10150801_20_dialog_content = "Carleen, você está confiante sobre o Exercício Militar Conjunto?",
  ui_story_1015_10150801_21_dialog_content = "Deixe-me compartilhar outra pequena estratégia com você com antecedência. Seus oponentes desta vez não serão tão fáceis de lidar quanto no passado.",
  ui_story_1015_10150801_22_dialog_content = "Não, na verdade, eu já escolhi não participar. A equipe Lumopolis será liderada por outra pessoa.",
  ui_story_1015_10150801_23_dialog_content = "Huh? Oh, eu vejo...",
  ui_story_1015_10150801_24_dialog_content = "Vocês três realmente precisam se encontrar rápido porque...",
  ui_story_1015_10150801_25_dialog_content = "O convite que você tem está sob a formação de Team PlayerName!",
  ui_story_1015_10150801_26_dialog_content = "Eu vejo. Nesse caso, também será a primeira vez que os celestitas estarão representados em exercícios militares em muitos anos.",
  ui_story_1015_10150801_27_dialog_content = "É isso mesmo, então me faça um favor e não puxe os socos por aí!",
  ui_story_1015_10150801_28_dialog_content = "Entendi. Obrigado.",
  ui_story_1015_10150801_29_dialog_content = "Então, PlayerName e Vice são...",
  ui_story_1015_10150801_30_dialog_content = "Hum, espere um segundo...",
  ui_story_1015_10150801_31_dialog_content = "<color=#e8d9bb>Bip Bip-!</color>",
  ui_story_1015_10150801_32_dialog_content = "Implantei um passe e um mapa em seu convite.",
  ui_story_1015_10150801_33_dialog_content = "As coordenadas destacadas no mapa são para a Cidade Baixa X, que é onde a Illumina trata e estuda os aurorianos especiais.",
  ui_story_1015_10150801_34_dialog_content = "(Mas... PlayerName e Vice estão lá há tanto tempo...)",
  ui_story_1015_10150801_35_dialog_content = "Essencialmente, este passe concederá acesso à maioria das instalações da Illumina.",
  ui_story_1015_10150801_36_dialog_content = "Muito obrigado. Não há tempo a perder então, vou me despedir.",
  ui_story_1015_10150801_37_dialog_content = "Vá em frente! Este lugar não é como Lumopolis - você não encontrará nenhum guarda acompanhando você... Fique seguro lá fora!",
  ui_story_1015_10150801_38_dialog_content = "<color=#e8d9bb>Federação Illumina, Cidade Baixa X</color>",
  ui_story_1015_10150801_39_dialog_content = "(De acordo com as instruções no mapa, este deve ser o local Gronru mencionado...)",
  ui_story_1015_10150801_40_dialog_content = "(No entanto, este lugar é ainda maior do que eu imaginava.)",
  ui_story_1015_10150801_41_dialog_content = "(Se não me engano, usar prédios grandes e densos para sustentar sua grande população é a estratégia de sobrevivência da Illumina.)",
  ui_story_1015_10150801_42_dialog_content = "?!?",
  ui_story_1015_10150801_43_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_1015_10150801_44_dialog_content = "Quem está aí?",
  ui_story_1015_10150801_45_dialog_content = "... Yingel?",
  ui_story_1015_10150801_46_dialog_content = "Então, foi você quem acionou o alerta de visitante.",
  ui_story_1015_10150801_47_dialog_content = "O que você está fazendo aqui... Ah, eu sei.",
  ui_story_1015_10150801_48_dialog_content = "Estamos todos mais ou menos motivados pelo mesmo objetivo.",
  ui_story_1015_10150801_49_dialog_content = "Qual é a situação no momento? Você poderia por favor me explicar?",
  ui_story_1015_10150801_50_dialog_content = "Shhh—!",
  ui_story_1015_10150801_51_dialog_content = "<anim type=Shake>Gaah... Graaah...</anim>",
  ui_story_1015_10150801_52_dialog_content = "Vamos pelo menos esperar até terminarmos de lutar contra esses Eclipsites.",
  ui_story_1015_10150801_53_dialog_content = "O que você está esperando? Vamos fazer isso.",
  ui_story_1015_10150802_1_dialog_content = "Como uma coisa dessas pode acontecer?! Isso tudo é muito ridículo!",
  ui_story_1015_10150802_2_dialog_content = "O que exatamente Forsakin quer?",
  ui_story_1015_10150802_3_dialog_content = "Por que Illumina ainda não enviou tropas para cercá-la e neutralizá-la?",
  ui_story_1015_10150802_4_dialog_content = "Fique calmo, Carleen. Isso não é Lumopolis – toda decisão importante requer o consentimento conjunto de várias partes.",
  ui_story_1015_10150802_5_dialog_content = "O Comitê já começou a se preparar, e nós somos simplesmente a equipe de vanguarda enviada à frente do processo de tomada de decisão.",
  ui_story_1015_10150802_6_dialog_content = "Então, qual é o nosso próximo curso de ação?",
  ui_story_1015_10150802_7_dialog_content = "Do ponto de vista de um oficial de inteligência, precisamos consolidar nossa inteligência e abordar Forsakin da maneira mais eficiente possível.",
  ui_story_1015_10150802_8_dialog_content = "Quanto às pistas de inteligência, acho que podemos começar com as onipresentes câmeras de vigilância por aqui.",
  ui_story_1015_10150802_9_dialog_content = "Tudo o que preciso fazer é solicitar permissão para revisar os registros de vigilância, e poderemos ver claramente onde Forsakin e Vice estão à vista.",
  ui_story_1015_10150802_10_dialog_content = "Receio que não possamos fazer isso.",
  ui_story_1015_10150802_11_dialog_content = "Não sei por que, mas as câmeras aqui são usadas apenas para verificação de identidade e todos os registros são excluídos imediatamente.",
  ui_story_1015_10150802_12_dialog_content = "Quão...",
  ui_story_1015_10150802_13_dialog_content = "Por que tudo isso soa tão suspeito?",
  ui_story_1015_10150802_14_dialog_content = "De qualquer forma, não podemos vagar cegamente por esta Cidade Baixa.",
  ui_story_1015_10150802_15_dialog_content = "Não se preocupe, acabei de pensar em algo.",
  ui_story_1015_10150802_16_dialog_content = "Ao lidar com assuntos da Illumina, é claro que devemos usar as soluções da Illumina.",
  ui_story_1015_10150901_1_dialog_content = "(Pesquisei todos os arquivos de prefixo A numerados entre 1 e 50, mas ainda não consigo encontrá-lo.)",
  ui_story_1015_10150901_2_dialog_content = "(Preciso encontrar outra maneira. Levará um mês para ler todos os cabeçalhos de arquivo apenas nesses gabinetes.)",
  ui_story_1015_10150901_3_dialog_content = "(Além de perguntar diretamente ao Ulysses, preciso descobrir rapidamente as regras de classificação desses armários...)",
  ui_story_1015_10150901_4_dialog_content = "Vice, você tem comida e água suficientes aí?",
  ui_story_1015_10150901_5_dialog_content = "Não se preocupe... eu... tudo... preciso.",
  ui_story_1015_10150901_6_dialog_content = "O quê?",
  ui_story_1015_10150901_7_dialog_content = "Huh? Você pode me ouvir?",
  ui_story_1015_10150901_8_dialog_content = "Oh, eu posso ouvi-lo claramente agora. O som ficou todo estranho e estava cortando agora.",
  ui_story_1015_10150901_9_dialog_content = "A bateria está fraca? Essas coisas não têm muita bateria. Eles acabam muito rapidamente se você usá-los constantemente.",
  ui_story_1015_10150901_10_dialog_content = "Huh? Eles vão ficar sem energia—",
  ui_story_1015_10150901_11_dialog_content = "Você fala tão alto. Me dê isto.",
  ui_story_1015_10150901_12_dialog_content = "Ei! Por que você roubou o comunicador de mim?!",
  ui_story_1015_10150901_13_dialog_content = "Eu vou deixar você brincar com ele mais tarde. Venha me ajudar primeiro.",
  ui_story_1015_10150901_14_dialog_content = "O que você quer desta vez?",
  ui_story_1015_10150901_15_dialog_content = "Vocês celestitas podem sentir objetos que aurorianos específicos podem ter tocado recentemente?",
  ui_story_1015_10150901_16_dialog_content = "Ajude-me a dar uma olhada.",
  ui_story_1015_10150901_17_dialog_content = "... O que você acha que eu sou, um cachorro?!",
  ui_story_1015_10150901_18_dialog_content = "Tsk, eu deveria ter jogado você naquela máquina na torre.",
  ui_story_1015_10150901_19_dialog_content = "Se você não pode fazer isso, venha e me diga se você pode quebrar a senha para este console.",
  ui_story_1015_10150901_20_dialog_content = "Eu mesmo notei... Esta máquina é realmente incrível.",
  ui_story_1015_10150901_21_dialog_content = "Cada local de pesquisa tem um dispositivo como este.",
  ui_story_1015_10150901_22_dialog_content = "Ele pode ser usado para pesquisar informações e controlar operações mecânicas. Em suma, é uma ferramenta para auxiliar os pesquisadores.",
  ui_story_1015_10150901_23_dialog_content = "Entendi.",
  ui_story_1015_10150901_24_dialog_content = "Eu tenho que operá-lo? Talvez eu não devesse, apenas para estar no lado seguro.",
  ui_story_1015_10150901_25_dialog_content = "Eu realmente não sei nada sobre a tecnologia Illumina.",
  ui_story_1015_10150901_26_dialog_content = "... Fale menos e faça mais.",
  ui_story_1015_10150901_27_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1015_10150901_28_dialog_content = "E-espere um minuto, não digite apenas dígitos aleatórios assim...",
  ui_story_1015_10150901_29_dialog_content = "O objetivo da tecnologia é servir à pesquisa científica. Se não posso usar, não adianta existir.",
  ui_story_1015_10150901_30_dialog_content = "<color=#e8d9bb>Bip, bip—bip—</color>",
  ui_story_1015_10150901_31_dialog_content = "... Multar.",
  ui_story_1015_10150901_32_dialog_content = "(Felizmente, parece que ela realmente sabe como quebrar essa coisa.)",
  ui_story_1015_10150901_33_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1015_10150901_34_dialog_content = "<color=#e8d9bb>Aviso! Aviso!</color>",
  ui_story_1015_10150901_35_dialog_content = "<color=#e8d9bb>Erro de senha, medidas de alerta de emergência ativadas—</color>",
  ui_story_1015_10150901_36_dialog_content = "O quê?!",
  ui_story_1015_10150901_37_dialog_content = "<anim type=Shake><size=45>Bip Bip-</size></anim>",
  ui_story_1015_10150901_38_dialog_content = "O que é isso...?",
  ui_story_1015_10150901_39_dialog_content = "Você não está sendo um pouco confiante demais?!? Abandono!",
  ui_story_1015_10150901_40_dialog_content = "Erros são inevitáveis e tecnologia eletrônica não é meu forte.",
  ui_story_1015_10150901_41_dialog_content = "Pense em algo... Agora não é hora de analisar suas deficiências!",
  ui_story_1015_10150901_42_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1015_10150901_43_dialog_content = "Bastou puxar o freio elétrico desse arquivo.",
  ui_story_1015_10150901_44_dialog_content = "Tem certeza?",
  ui_story_1015_10150901_45_dialog_content = "...",
  ui_story_1015_10150901_46_dialog_content = "<anim type=Shake><size=45>Bip Bip-</size></anim>",
  ui_story_1015_10150901_47_dialog_content = "Isso não serviu para nada!",
  ui_story_1015_10150901_48_dialog_content = "Tsk... Que problemático.",
  ui_story_1015_10150901_49_dialog_content = "Ainda precisamos lidar com esse cachorro mecânico primeiro. Jade-",
  ui_story_1015_10150901_50_dialog_content = "<anim type=Shake><size=50>Graagh!!!</size></anim>",
  ui_story_1015_10150901_51_dialog_content = "Carregue em frente e mastigue-o.",
  ui_story_1015_10150902_1_dialog_content = "<anim type=Shake><size=45>Chomp... Chopp...</size></anim>",
  ui_story_1015_10150902_2_dialog_content = "Bom trabalho. Coma o suficiente.",
  ui_story_1015_10150902_3_dialog_content = "Continue vigiando a porta para mim, entendeu?",
  ui_story_1015_10150902_4_dialog_content = "<anim type=Shake><size=45>Rugido...</size></anim>",
  ui_story_1015_10150902_5_dialog_content = "Esta máquina é... algum tipo de medida de segurança?",
  ui_story_1015_10150902_6_dialog_content = "Não sei. Não estava aqui quando eu saí.",
  ui_story_1015_10150902_7_dialog_content = "Já perdemos muito tempo. Precisamos ser rápidos a partir de agora.",
  ui_story_1015_10150902_8_dialog_content = "<color=#e8d9bb>Bip, bip—bip—</color>",
  ui_story_1015_10150902_9_dialog_content = "<color=#e8d9bb>Hub de armazenamento ativado!</color>",
  ui_story_1015_10150902_10_dialog_content = "Continuar pesquisa, Programa Phospherus.",
  ui_story_1015_10150902_11_dialog_content = "... Não, se não conseguirmos encontrar mais informações...",
  ui_story_1015_10150902_12_dialog_content = "Mudança de palavra-chave, procure por <color=#FFB400>Projeto Sol Artificial</color>.",
  ui_story_1015_10150902_13_dialog_content = "(Artificial... Sol? O que isso significa? Tem algo a ver com a criação de um enorme sol?)",
  ui_story_1015_10150902_14_dialog_content = "(Em um momento é Phospherus, no próximo é isso... O que exatamente Forsakin está procurando...?)",
  ui_story_1015_10150902_15_dialog_content = "Encontrei.",
  ui_story_1015_10150902_16_dialog_content = "Ok, mova-se.",
  ui_story_1015_10150902_17_dialog_content = "Forsakin, qual é exatamente o significado dessa informação e realmente vale a pena cortar seus laços com Ulysses assim?",
  ui_story_1015_10150902_18_dialog_content = "Você realmente quer saber?",
  ui_story_1015_10150902_19_dialog_content = "Mesmo se você soubesse, seria inútil para você, pois o dispositivo em Eraveil já falhou.",
  ui_story_1015_10150902_20_dialog_content = "Além disso, minha pesquisa ultrapassou em muito o nível da tecnologia Illumina e Caelestite.",
  ui_story_1015_10150902_21_dialog_content = "Eu aconselho você a não tentar nada.",
  ui_story_1015_10150902_22_dialog_content = "Eu só perguntei por curiosidade. Eu ajudei você na batalha agora há pouco, então não posso pelo menos saber pelo que tenho lutado?",
  ui_story_1015_10150902_23_dialog_content = "Considerando minha situação atual, você não precisa ser tão cauteloso, precisa?",
  ui_story_1015_10150902_24_dialog_content = "...",
  ui_story_1015_10150902_25_dialog_content = "Multar. Não faria mal lhe dizer.",
  ui_story_1015_10150902_26_dialog_content = "É algo que você já sabe.",
  ui_story_1015_10150902_27_dialog_content = "Algo que eu sei...?",
  ui_story_1015_10150902_28_dialog_content = "Foi quando você foi para o pântano e despertou o Helios há muito adormecido.",
  ui_story_1015_10150902_29_dialog_content = "Durante esse tempo, ela deve ter lhe contado tudo sobre as experiências passadas compartilhadas por nós três.",
  ui_story_1015_10150902_30_dialog_content = "Naquela época, nós três crescemos juntos, nos juntamos ao exército e lutamos juntos...",
  ui_story_1015_10150902_31_dialog_content = "Essa associação de longo prazo certamente não se deveu a motivos sentimentais, como as chamadas amizades ou laços.",
  ui_story_1015_10150902_32_dialog_content = "Foi porque fomos as primeiras cobaias de <color=#FFB400>Projeto Sol Artificial</color>.",
  ui_story_1015_10150902_33_dialog_content = "Somente experimentando o mesmo curso de desenvolvimento, enfrentando as mesmas batalhas e aceitando o mesmo conjunto de modificações, poderíamos ser comparados qualitativamente uns com os outros.",
  ui_story_1015_10150902_34_dialog_content = "Mas os métodos de pesquisa primitivos que eles usaram eram totalmente insatisfatórios.",
  ui_story_1015_10150902_35_dialog_content = "Reinhardt Acontece que ela é hoje realmente me surpreendeu.",
  ui_story_1015_10150902_36_dialog_content = "Mais tarde, o nome deste projeto foi alterado para um som mais agradável <color=#FFB400>Fósforo</color>.",
  ui_story_1015_10150902_37_dialog_content = "Então foi isso que aconteceu... É por isso que você está fazendo tudo isso.",
  ui_story_1015_10150902_38_dialog_content = "Sua expressão é revoltante. Todos os celestitas são tão doentiamente compassivos?",
  ui_story_1015_10150902_39_dialog_content = "Pegue isso. Você pode tentar falar com ela agora.",
  ui_story_1015_10150902_40_dialog_content = "Ei!",
  ui_story_1015_10150902_41_dialog_content = "<color=#e8d9bb>Zumbido... Zumbido...</color>",
  ui_story_1015_10150902_42_dialog_content = "PlayerName! Você está bem?",
  ui_story_1015_10150902_43_dialog_content = "... Vice!",
  ui_story_1015_10150902_44_dialog_content = "<color=#e8d9bb>Zumbido... Zumbido...</color>",
  ui_story_1015_10150902_45_dialog_content = "Ah...",
  ui_story_1015_10150902_46_dialog_content = "A banda de frequência do Vice está ativa!",
  ui_story_1015_10150902_47_dialog_content = "Você consegue localizar imediatamente a posição de Vice com base nas ondas de rádio?",
  ui_story_1015_10150902_48_dialog_content = "Com a tecnologia atual da Illumina, isso pode não ser possível.",
  ui_story_1015_10150902_49_dialog_content = "Mas pelo menos sabemos que o tenente Vice está usando seu comunicador.",
  ui_story_1015_10150902_50_dialog_content = "Isso indica que ela possui liberdade de movimento até certo ponto.",
  ui_story_1015_10150902_51_dialog_content = "Se minhas suspeitas estiverem corretas, Forsakin deve estar do outro lado do comunicador do Tenente Vice.",
  ui_story_1015_10150902_52_dialog_content = "Acordado. Anatoli, fique de olho em qualquer mudança de banda de frequência no final da Vice.",
  ui_story_1015_10150902_53_dialog_content = "Sim, senhora. Vai fazer.",
  ui_story_1015_10150902_54_dialog_content = "Vamos ver o plano de resgate.",
  ui_story_1015_10150902_55_dialog_content = "Minhas informações mostram que o sistema de alerta do arquivo do professor Ulysses acaba de ser acionado.",
  ui_story_1015_10150902_56_dialog_content = "Sem dúvida, Forsakin deve ter estado lá, e PlayerName estava bem ao lado dela.",
  ui_story_1015_10150902_57_dialog_content = "Assim que localizarmos Vice, o plano de resgate começará oficialmente.",
  ui_story_1015_10151001_1_dialog_content = "Estou bem, Vice! Atualmente estou em alguma sala de arquivo em Undercity X com Forsakin!",
  ui_story_1015_10151001_2_dialog_content = "E você? Você está ferido? Onde você está?!",
  ui_story_1015_10151001_3_dialog_content = "<anim type=Shake>Estou em...porta...luz...</anim>",
  ui_story_1015_10151001_4_dialog_content = "Huh? O que você disse? Vice?",
  ui_story_1015_10151001_5_dialog_content = "Droga! Por que não consigo ouvi-la? Este comunicador está morto de novo?",
  ui_story_1015_10151001_6_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1015_10151001_7_dialog_content = "Sua ligação acabou. Você perguntou algo que não deveria ter perguntado.",
  ui_story_1015_10151001_8_dialog_content = "Você não me disse se havia algo que eu não deveria perguntar! Claro que eu tentaria descobrir o que eu queria saber!",
  ui_story_1015_10151001_9_dialog_content = "O que você está tentando esconder, pressionando o comunicador com tanta pressa?",
  ui_story_1015_10151001_10_dialog_content = "Não entenda mal, eu não fiz nada.",
  ui_story_1015_10151001_11_dialog_content = "A bateria desta máquina patética acabou.",
  ui_story_1015_10151001_12_dialog_content = "(Isso é realmente...)",
  ui_story_1015_10151001_13_dialog_content = "(Isso é demais, e em um momento tão crítico...)",
  ui_story_1015_10151001_14_dialog_content = "Tudo bem, não vamos perder mais tempo.",
  ui_story_1015_10151001_15_dialog_content = "Vamos nos preparar para partir. Novos experimentos estão esperando para serem realizados.",
  ui_story_1015_10151001_16_dialog_content = "Praticamente ninguém pôs os pés nesta área, exceto o professor Ulysses.",
  ui_story_1015_10151001_17_dialog_content = "Existem apenas dois grandes marcos aqui. Além dos arquivos onde foi dado o alarme, existe também um laboratório.",
  ui_story_1015_10151001_18_dialog_content = "Não esperava menos de você, coronel Yingel... Embora eu trabalhe no Comitê há muito tempo, não sei nada sobre este lugar.",
  ui_story_1015_10151001_19_dialog_content = "Pense nisso como um relatório confidencial - o professor não deseja que essas coisas sejam conhecidas por muitas pessoas.",
  ui_story_1015_10151001_20_dialog_content = "Então, cabe a mim afastar qualquer pessoa que entre neste local sem autorização com extremo preconceito.",
  ui_story_1015_10151001_21_dialog_content = "Existe algum movimento na faixa de frequência do Vice?",
  ui_story_1015_10151001_22_dialog_content = "Ela está em um estado de silêncio de rádio no momento. A transmissão dela deve ter sido cortada.",
  ui_story_1015_10151001_23_dialog_content = "Me dê isto-",
  ui_story_1015_10151001_24_dialog_content = "Tenente Vice? Chamando Vice, isso é Yingel, você pode me ouvir?",
  ui_story_1015_10151001_25_dialog_content = "Se você puder entrar em contato comigo, faça-o imediatamente!",
  ui_story_1015_10151001_26_dialog_content = "Ei! Forsakin também não ouviria você se você a chamasse assim?!",
  ui_story_1015_10151001_27_dialog_content = "Isso normalmente seria o caso, mas o comunicador de Forsakin está sem energia.",
  ui_story_1015_10151001_28_dialog_content = "Fora do poder?!",
  ui_story_1015_10151001_29_dialog_content = "Eu estava ouvindo a conversa deles. PlayerName tem usado o comunicador com muita frequência, portanto, a bateria foi descarregada muito rapidamente.",
  ui_story_1015_10151001_30_dialog_content = "A julgar pelo que ouvi, está completamente sem energia agora.",
  ui_story_1015_10151001_31_dialog_content = "O sucesso ou fracasso de nossa missão depende deste momento.",
  ui_story_1015_10151001_32_dialog_content = "Isso é... Coronel Yingel?",
  ui_story_1015_10151001_33_dialog_content = "(Sim!)",
  ui_story_1015_10151001_34_dialog_content = "Informe sua localização!",
  ui_story_1015_10151001_35_dialog_content = "Há alguma característica distintiva sobre o lugar onde você está sendo mantido? Isso também serve!",
  ui_story_1015_10151001_36_dialog_content = "Sim! Estou trancado em um armazém na Cidade Baixa X, com portas cinza... Tem uma janela aqui com luz natural!",
  ui_story_1015_10151001_37_dialog_content = "Beleza.",
  ui_story_1015_10151001_38_dialog_content = "Estarei inativo nesta frequência indefinidamente. Preste atenção ao nível da bateria do seu comunicador. Mesmo que Forsakin entre em contato com você novamente, ainda posso ouvir tudo.",
  ui_story_1015_10151001_39_dialog_content = "Quem mais está com você?",
  ui_story_1015_10151001_40_dialog_content = "Helios me trouxe aqui, mas ele saiu agora.",
  ui_story_1015_10151001_41_dialog_content = "Entendido. Iremos até você imediatamente.",
  ui_story_1015_10151001_42_dialog_content = "Coronel Yingel, você tem alguma ideia?",
  ui_story_1015_10151001_43_dialog_content = "Os armazéns de Undercity X estão concentrados no sul, já que o terreno ao sul é baixo e fácil de defender, mas difícil de atacar.",
  ui_story_1015_10151001_44_dialog_content = "Entre eles, os armazéns com portas cinza são usados especificamente para armazenar vários produtos farmacêuticos sólidos.",
  ui_story_1015_10151001_45_dialog_content = "O eco do lado de Vice estava muito alto agora, então ela deve estar em um grande armazém.",
  ui_story_1015_10151001_46_dialog_content = "Isso exclui todos os armazéns subterrâneos e as várias pequenas salas de armazenamento espalhadas pelo local.",
  ui_story_1015_10151001_47_dialog_content = "Assim, o armazém onde Vice está sendo mantido pode ser reduzido aos armazéns X-106, X-107 e X-108.",
  ui_story_1015_10151001_48_dialog_content = "Então vamos começar a busca imediatamente.",
  ui_story_1015_10151001_49_dialog_content = "eu vou lá com Anatoli. Carleen, preciso que você cuide de uma coisa para mim.",
  ui_story_1015_10151001_50_dialog_content = "Eu quero que você vá para os arquivos e salve PlayerName.",
  ui_story_1015_10151001_51_dialog_content = "Para garantir a segurança dos dois reféns, seria melhor concluirmos o resgate simultaneamente.",
  ui_story_1015_10151001_52_dialog_content = "Eu vejo. Entendido.",
  ui_story_1015_10151001_53_dialog_content = "Tudo bem. Forneceremos suporte assim que o resgate for concluído de nossa parte.",
  ui_story_1015_10151001_54_dialog_content = "Por favor, seja cuidadoso.",
  ui_story_1015_10151001_55_dialog_content = "<color=#e8d9bb>Cidade Baixa X, Armazém do Sul</color>",
  ui_story_1015_10151001_56_dialog_content = "Como esperado, é exatamente como você previu, Coronel.",
  ui_story_1015_10151001_57_dialog_content = "De acordo com as características por aqui, acredito que encontramos o lugar certo.",
  ui_story_1015_10151001_58_dialog_content = "Coronel Yingel, O que devemos fazer em seguida?",
  ui_story_1015_10151001_59_dialog_content = "Tudo o que podemos fazer agora é experimentá-los um por um.",
  ui_story_1015_10151001_60_dialog_content = "Felizmente, Forsakin ainda não tomou nenhuma ação...",
  ui_story_1015_10151001_61_dialog_content = "<color=#e8d9bb>Baque-!</color>",
  ui_story_1015_10151001_62_dialog_content = "<anim type=Shake><size=50>Graagh!!!</size></anim>",
  ui_story_1015_10151001_63_dialog_content = "O-O que é aquela coisa...?",
  ui_story_1015_10151001_64_dialog_content = "(Ele deve ter detectado nossos movimentos...!)",
  ui_story_1015_10151001_65_dialog_content = "<anim type=Shake><size=50>Graagh!!!</size></anim>",
  ui_story_1015_10151001_66_dialog_content = "Atenção! Ele está vindo para cá!",
  ui_story_1015_10151101_1_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_1015_10151101_2_dialog_content = "Golpe perfeito!",
  ui_story_1015_10151101_3_dialog_content = "<anim type=Shake><size=50>Grahhhhhhh!</size></anim>",
  ui_story_1015_10151101_4_dialog_content = "O que há de errado com ele?!",
  ui_story_1015_10151101_5_dialog_content = "De acordo com nossa inteligência, o Grande Marechal Reinhardt deu-lhe um duro golpe em seu último encontro...",
  ui_story_1015_10151101_6_dialog_content = "Como ainda pode manter um poder tão formidável?",
  ui_story_1015_10151101_7_dialog_content = "<anim type=Shake><size=50>Ahhhh!</size></anim>",
  ui_story_1015_10151101_8_dialog_content = "Cuidado!",
  ui_story_1015_10151101_9_dialog_content = "Urgh...!",
  ui_story_1015_10151101_10_dialog_content = "Valeu...",
  ui_story_1015_10151101_11_dialog_content = "Você não pode confiar muito na inteligência, Coronel Yingel, pois às vezes pode ser impreciso.",
  ui_story_1015_10151101_12_dialog_content = "Se esta inteligência é realmente verdadeira, então...",
  ui_story_1015_10151101_13_dialog_content = "Não, ele, o capitão Helios, provavelmente mora sozinho na Zona Cega há mais de dez anos. Sua mente deve estar distorcida além da imaginação.",
  ui_story_1015_10151101_14_dialog_content = "Com esse poder em sua posse, não podemos subestimá-lo.",
  ui_story_1015_10151101_15_dialog_content = "Além disso, passou por um processo de aprimoramento e transformação, assim como o Grande Marechal Reinhardt...",
  ui_story_1015_10151101_16_dialog_content = "Mesmo nós dois juntos podemos não ser tão fortes quanto o Grande Marechal.",
  ui_story_1015_10151101_17_dialog_content = "Eu já sei disso... Não precisa dizer, Major Anatoli.",
  ui_story_1015_10151101_18_dialog_content = "Há muito espaço de manobra aqui e sua mobilidade é muito maior que a nossa. Se continuarmos a engajá-lo, acabaremos nos exaurindo!",
  ui_story_1015_10151101_19_dialog_content = "Vamos nos retirar para o corredor para restringir seu movimento.",
  ui_story_1015_10151101_20_dialog_content = "Entendido!",
  ui_story_1015_10151101_21_dialog_content = "<anim type=Shake>Grrr...</anim>",
  ui_story_1015_10151101_22_dialog_content = "...",
  ui_story_1015_10151101_23_dialog_content = "Ele está indo embora.",
  ui_story_1015_10151101_24_dialog_content = "Não podemos enfrentá-lo de frente, mas podemos usar o terreno aqui para lançar um ataque surpresa visando suas fraquezas.",
  ui_story_1015_10151101_25_dialog_content = "Contanto que Forsakin não—",
  ui_story_1015_10151101_26_dialog_content = "Essa não...",
  ui_story_1015_10151101_27_dialog_content = "<size=45>Isto é mau!</size>",
  ui_story_1015_10151101_28_dialog_content = "O que foi?",
  ui_story_1015_10151101_29_dialog_content = "Os aurorianos que foram aprimorados e modificados provocam reações especiais uns com os outros.",
  ui_story_1015_10151101_30_dialog_content = "Receio que Forsakin sentirá que estamos em combate com seu companheiro mutante!",
  ui_story_1015_10151101_31_dialog_content = "...!",
  ui_story_1015_10151101_32_dialog_content = "Esta parece ser uma informação particularmente importante! Por que você não me avisou com antecedência?",
  ui_story_1015_10151101_33_dialog_content = "O experimento é altamente confidencial.",
  ui_story_1015_10151101_34_dialog_content = "Se não fosse pela urgência da situação, todas as informações relacionadas ao experimento não estariam disponíveis para você ou para mim.",
  ui_story_1015_10151101_35_dialog_content = "Desculpe eu cometi um erro. Não consegui atualizá-lo sobre a situação em tempo hábil em relação a isso.",
  ui_story_1015_10151101_36_dialog_content = "Isso vai trazer problemas...",
  ui_story_1015_10151101_37_dialog_content = "(O Comitê... Quantos segredos eles ainda escondem?)",
  ui_story_1015_10151101_38_dialog_content = "(Seja a modificação biológica secreta ou o fato de que a inteligência que minha equipe recuperou foi adulterada...)",
  ui_story_1015_10151101_39_dialog_content = "(Posso realmente confiar neles?)",
  ui_story_1015_10151101_40_dialog_content = "Não podemos continuar lutando contra isso aqui.",
  ui_story_1015_10151101_41_dialog_content = "Assumindo que Forsakin já detectou nossa incursão, seria impossível para ela não estar em guarda.",
  ui_story_1015_10151101_42_dialog_content = "Tenente Vice ainda é seguro por enquanto, mas não há como Carleen poderia saber que nossa presença aqui foi descoberta.",
  ui_story_1015_10151101_43_dialog_content = "Precisamos nos livrar dele rapidamente e apoiar Carleen.",
  ui_story_1015_10151101_44_dialog_content = "Claro, mas não podemos fazer as duas coisas ao mesmo tempo.",
  ui_story_1015_10151101_45_dialog_content = "Furtividade é o seu forte - encontre uma chance de passar por ela, resgate o tenente Vicee, em seguida, rapidamente faça o seu caminho para Carleen.",
  ui_story_1015_10151101_46_dialog_content = "E você? O que você vai fazer?",
  ui_story_1015_10151101_47_dialog_content = "Forsakin será ainda mais difícil de lidar do que este monstro. Mesmo com mais do que apenas nós dois, nossas chances de ganhar serão mínimas.",
  ui_story_1015_10151101_48_dialog_content = "Preciso preparar meu trunfo — um trunfo poderoso o suficiente para nivelar o campo de jogo.",
  ui_story_1015_10151101_49_dialog_content = "<color=#e8d9bb>Enquanto isso em PlayerName e a localização de Forsakin...</color>",
  ui_story_1015_10151101_50_dialog_content = "...",
  ui_story_1015_10151101_51_dialog_content = "<anim type=Shake>Rrr... Rugido...!</anim>",
  ui_story_1015_10151101_52_dialog_content = "Fique quieta, Jade.",
  ui_story_1015_10151101_53_dialog_content = "<anim type=Shake>Rugido...</anim>",
  ui_story_1015_10151101_54_dialog_content = "Você é tão barulhento.",
  ui_story_1015_10151101_55_dialog_content = "Isso é. Cada vez que ruge, sinto que meus tímpanos estão prestes a estourar.",
  ui_story_1015_10151101_56_dialog_content = "Cale-se.",
  ui_story_1015_10151101_57_dialog_content = "Os ratos saíram para brincar.",
  ui_story_1015_10151101_58_dialog_content = "Ratos?",
  ui_story_1015_10151101_59_dialog_content = "(Esta Lumina... Poderia ser...?)",
  ui_story_1015_10151101_60_option_content = "Usar habilidade psíquica",
  ui_story_1015_10151101_61_dialog_content = "(Carleen?!)",
  ui_story_1015_10151101_62_dialog_content = "Sair.",
  ui_story_1015_10151101_63_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1015_10151101_64_dialog_content = "Que tolo.",
  ui_story_1015_10151101_65_dialog_content = "<size=45>(Carleen! Atenção!)</size>",
  ui_story_1015_10151101_66_dialog_content = "(Wha...)",
  ui_story_1015_10151101_67_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_1015_10151101_68_dialog_content = "Tosse... Tosse, tosse!",
  ui_story_1015_10151101_69_dialog_content = "Como você descobriu?",
  ui_story_1015_10151101_70_dialog_content = "Suas táticas são desajeitadas na melhor das hipóteses.",
  ui_story_1015_10151101_71_dialog_content = "...",
  ui_story_1015_10151101_72_dialog_content = "No entanto, como um fator que pode afetar os resultados do meu experimento, o esforço necessário para eliminá-lo deve valer a pena.",
  ui_story_1015_10151101_73_dialog_content = "<anim type=Shake>Rugido...</anim>",
  ui_story_1015_10151101_74_dialog_content = "Existem muitos deles...",
  ui_story_1015_10151101_75_dialog_content = "Ataque.",
  ui_story_1015_10151101_76_dialog_content = "<anim type=Shake><size=50>Graagh!!!</size></anim>",
  ui_story_1015_10151102_1_dialog_content = "Ugh...!!!",
  ui_story_1015_10151102_2_dialog_content = "<anim type=Shake><size=45>Grahhhh!</size></anim>",
  ui_story_1015_10151102_3_dialog_content = "Não há fim para eles...",
  ui_story_1015_10151102_4_dialog_content = "Carleen!",
  ui_story_1015_10151102_5_dialog_content = "Você planejou um ataque em duas frentes, com a intenção de capturar o celestita e aquela garotinha ao mesmo tempo.",
  ui_story_1015_10151102_6_dialog_content = "No entanto, para dividir e conquistar, é preciso ter confiança absoluta na própria capacidade.",
  ui_story_1015_10151102_7_dialog_content = "Como você sabia?",
  ui_story_1015_10151102_8_dialog_content = "É tudo graças a esses cachorros velhos e seu projeto.",
  ui_story_1015_10151102_9_dialog_content = "Você quer dizer a conexão especial Reinhardt mencionado?",
  ui_story_1015_10151102_10_dialog_content = "Oh não, se você possui essa habilidade, então Yingel e Anatoli—",
  ui_story_1015_10151102_11_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1015_10151102_12_dialog_content = "Tosse... Tosse, tosse, tosse!",
  ui_story_1015_10151102_13_dialog_content = "Isso é...",
  ui_story_1015_10151102_14_dialog_content = "<anim type=Shake>Rugido...</anim>",
  ui_story_1015_10151102_15_dialog_content = "Outro rato.",
  ui_story_1015_10151102_16_dialog_content = "Anatoli! Como você chegou aqui?",
  ui_story_1015_10151102_17_dialog_content = "Onde está a Vice!",
  ui_story_1015_10151102_18_dialog_content = "Desculpe. Fui descoberto e não consegui encontrar onde o tenente Vice estava sendo realizada. não consegui resgatá-la...",
  ui_story_1015_10151102_19_dialog_content = "Parece que tudo o que há entre vocês é arrogância e incompetência.",
  ui_story_1015_10151102_20_dialog_content = "Meu trabalho aqui será concluído em breve. Você não está mais em uso.",
  ui_story_1015_10151102_21_dialog_content = "...",
  ui_story_1015_10151102_22_dialog_content = "Não!",
  ui_story_1015_10151102_23_dialog_content = "E assim estamos cercados...",
  ui_story_1015_10151102_24_dialog_content = "Mantenha-se firme PlayerName, Carleen.",
  ui_story_1015_10151102_25_dialog_content = "Não se esqueça, ainda temos Coronel Yingel.",
  ui_story_1015_10151102_26_dialog_content = "Ir. Cuide deles-",
  ui_story_1015_10151102_27_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1015_10151102_28_dialog_content = "Forsakin, você me lê?",
  ui_story_1015_10151102_29_dialog_content = "Eu só estava me perguntando onde o mouse desaparecido poderia estar.",
  ui_story_1015_10151102_30_dialog_content = "Acontece que ele está escondido em algum lugar distante.",
  ui_story_1015_10151102_31_dialog_content = "Seja o que for que você esteja tentando fazer, pare neste instante.",
  ui_story_1015_10151102_32_dialog_content = "Caso contrário, eu prometo que você vai se arrepender.",
  ui_story_1015_10151102_33_dialog_content = "...",
  ui_story_1015_10151102_34_dialog_content = "O que é que você fez?",
  ui_story_1015_10151102_35_dialog_content = "Graças a Anatoli e os esforços de Carleen, consegui cobrir a área ao redor do laboratório Chord Link com <color=#FFB400>explosivos</color> enquanto eles me deram algum tempo.",
  ui_story_1015_10151102_36_dialog_content = "Minha arma agora está apontada para um dos canos. Assim que eu apertar o gatilho, o Chord Link estará perdido para sempre em chamas, junto com seus preciosos dados.",
  ui_story_1015_10151102_37_dialog_content = "?!",
  ui_story_1015_10151102_38_dialog_content = "Uma cena familiar, não acha, Forsakin?",
  ui_story_1015_10151102_39_dialog_content = "Agora, entregue-se imediatamente e solte PlayerName e os outros.",
  ui_story_1015_10151102_40_dialog_content = "...",
  ui_story_1015_10151102_41_dialog_content = "<size=45>Fogo... Há fogo por todo o lado!</size>",
  ui_story_1015_10151102_42_dialog_content = "<size=45>Meu experimento! Meu experimento!!!</size>",
  ui_story_1015_10151102_43_dialog_content = "Hehe.",
  ui_story_1015_10151102_44_dialog_content = "Essas coisas velhas não têm muito talento para pesquisa, mas são muito boas em treinar cachorros.",
  ui_story_1015_10151102_45_dialog_content = "Você...",
  ui_story_1015_10151102_46_dialog_content = "Você não ousaria.",
  ui_story_1015_10151102_47_dialog_content = "O Chord Link é o epítome da antiga tecnologia Caelestite. Não é algo que você pode simplesmente tropeçar na beira da estrada.",
  ui_story_1015_10151102_48_dialog_content = "Apenas um desses dispositivos existe em toda a Federação Illumina.",
  ui_story_1015_10151102_49_dialog_content = "Sem falar nos dados armazenados dentro da máquina. A totalidade do Programa Phospherus pode ser apenas a ponta do iceberg.",
  ui_story_1015_10151102_50_dialog_content = "Como seu cão treinado, não há como você ignorar tudo isso.",
  ui_story_1015_10151102_51_dialog_content = "Se esses velhos fósseis pesassem o Chord Link e seus dados nas balanças de seus melhores interesses, suas vidas nem mesmo se qualificariam como contrapesos.",
  ui_story_1015_10151102_52_dialog_content = "É mesmo?",
  ui_story_1015_10151102_53_dialog_content = "Bem, vamos tentar então.",
  ui_story_1015_10151102_54_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1015_10151201_1_dialog_content = "<color=#e8d9bb>Bum—!!!</color>",
  ui_story_1015_10151201_2_dialog_content = "Fogo...",
  ui_story_1015_10151201_3_dialog_content = "Está pegando fogo...",
  ui_story_1015_10151201_4_dialog_content = "Helios, venha comigo ao laboratório!",
  ui_story_1015_10151201_5_dialog_content = "<anim type=Shake><size=45>Rugido-!</size></anim>",
  ui_story_1015_10151201_6_dialog_content = "É a nossa chance!",
  ui_story_1015_10151201_7_dialog_content = "Espalhe, Flor de Gelo!",
  ui_story_1015_10151201_8_dialog_content = "Cuidado, os Eclipsitos estão se aproximando novamente!",
  ui_story_1015_10151201_9_dialog_content = "<anim type=Shake><size=45>Graagh!!!</size></anim>",
  ui_story_1015_10151201_10_dialog_content = "<color=#e8d9bb>Bang! Culpa!</color>",
  ui_story_1015_10151201_11_dialog_content = "<anim type=Shake>Graa...</anim>",
  ui_story_1015_10151201_12_dialog_content = "Agora! Aproveite esta oportunidade para economizar PlayerName!",
  ui_story_1015_10151201_13_dialog_content = "Sim, senhora!",
  ui_story_1015_10151201_14_dialog_content = "PlayerName, eu desamarrarei você!",
  ui_story_1015_10151201_15_dialog_content = "Valeu...",
  ui_story_1015_10151201_16_dialog_content = "É Vice tudo bem? Onde ela está?",
  ui_story_1015_10151201_17_dialog_content = "Desculpe, fui descoberto pelo inimigo e não consegui encontrar o Tenente Vice...",
  ui_story_1015_10151201_18_dialog_content = "Mas não há outros inimigos naquela área, então posso pelo menos garantir que o tenente Vice é seguro.",
  ui_story_1015_10151201_19_dialog_content = "Não se preocupe, alguém está a caminho para salvar Vice.",
  ui_story_1015_10151201_20_dialog_content = "O que você precisa fazer agora é impedir que Forsakin conclua seu experimento.",
  ui_story_1015_10151201_21_dialog_content = "Então, você não destruiu o Chord Link.",
  ui_story_1015_10151201_22_dialog_content = "O que? Não foi destruído?!",
  ui_story_1015_10151201_23_dialog_content = "Como pude permitir que algo assim fosse destruído tão facilmente?",
  ui_story_1015_10151201_24_dialog_content = "Se realmente foi destruído, não há como dizer quantos problemas o Coronel Yingel iria encontrar-se com o tribunal militar.",
  ui_story_1015_10151201_25_dialog_content = "Tudo bem, isso é o suficiente.",
  ui_story_1015_10151201_26_dialog_content = "Vamos nos livrar desses Eclipsites e deter Forsakin!",
  ui_story_1015_10151201_27_dialog_content = "Você tirou as palavras da minha boca!",
  ui_story_1015_10151202_1_dialog_content = "<color=#e8d9bb>Undercity X, muitos anos atrás</color>",
  ui_story_1015_10151202_2_dialog_content = "Meu experimento... Meu experimento!",
  ui_story_1015_10151202_3_dialog_content = "Todos os meus dados e materiais de teste ainda estão lá dentro! Precisamos tirá-los de lá!",
  ui_story_1015_10151202_4_dialog_content = "<anim type=Shake><size=45>Rangido! Chiado, chiado!</size></anim>",
  ui_story_1015_10151202_5_dialog_content = "Jade, entre no meu casaco, precisamos voltar!",
  ui_story_1015_10151202_6_dialog_content = "<anim type=Shake><size=45>Rangido!</size></anim>",
  ui_story_1015_10151202_7_dialog_content = "Precisamos recuperar os dados experimentais, rapidamente...",
  ui_story_1015_10151202_8_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1015_10151202_9_dialog_content = "Ah!!!",
  ui_story_1015_10151202_10_dialog_content = "Droga! Eu não esperava que pudesse levar a um incêndio tão grande...",
  ui_story_1015_10151202_11_dialog_content = "Se tudo o que dependemos são as instalações de combate a incêndio existentes na Cidade Baixa, talvez não sejamos capazes de extinguir um incêndio tão grande.",
  ui_story_1015_10151202_12_dialog_content = "Será que eu já não tenho escolha a não ser pedir ajuda a você-sabe-quem...?",
  ui_story_1015_10151202_13_dialog_content = "<color=#e8d9bb>Zumbido—Buzz—</color>",
  ui_story_1015_10151202_14_dialog_content = "Aquele grande incêndio quase destruiu todas as minhas realizações de pesquisa.",
  ui_story_1015_10151202_15_dialog_content = "Não vou deixar isso acontecer de novo!",
  ui_story_1015_10151202_16_dialog_content = "Isso é...",
  ui_story_1015_10151202_17_dialog_content = "(Não há sequer uma única faísca no laboratório Chord Link...)",
  ui_story_1015_10151202_18_dialog_content = "(Aqueles fósseis antigos instalaram esses aspersores depois que eu saí?)",
  ui_story_1015_10151202_19_dialog_content = "Parece que o fogo não apenas ficou comigo, mas também com eles.",
  ui_story_1015_10151202_20_dialog_content = "Mas...",
  ui_story_1015_10151202_21_dialog_content = "<color=#e8d9bb>Tzzst—</color>",
  ui_story_1015_10151202_22_dialog_content = "Desista, Forsakin.",
  ui_story_1015_10151202_23_dialog_content = "Os reféns estão todos seguros. Suas moedas de troca desapareceram no ar.",
  ui_story_1015_10151202_24_dialog_content = "Usando aquele pequeno truque para me forçar a ir embora... Era esse o seu plano?",
  ui_story_1015_10151202_25_dialog_content = "Isso mesmo, mas não foi apenas um truque.",
  ui_story_1015_10151202_26_dialog_content = "Eu sabia que você não seria enganado por meros adereços, então os barris de explosivos ao redor do laboratório são todos reais.",
  ui_story_1015_10151202_27_dialog_content = "Só que você não sabia que desde o incêndio daquela época, o Grande Marechal ordenou uma atualização completa do equipamento de combate a incêndio da Cidade Baixa.",
  ui_story_1015_10151202_28_dialog_content = "Há mais que o dobro de extintores de incêndio e sprinklers aqui agora, e até as paredes foram reforçadas com materiais à prova de explosão e retardadores de chamas.",
  ui_story_1015_10151202_29_dialog_content = "Então, era ela.",
  ui_story_1015_10151202_30_dialog_content = "Ela fez muitas coisas, mas, infelizmente, todas foram simplesmente obstáculos inúteis.",
  ui_story_1015_10151202_31_dialog_content = "...",
  ui_story_1015_10151202_32_dialog_content = "O gato comeu sua língua?",
  ui_story_1015_10151202_33_dialog_content = "Você ainda não consegue superar o fogo de tantos anos atrás, não é?",
  ui_story_1015_10151202_34_dialog_content = "Mas você não quer saber o que realmente aconteceu naquela época?",
  ui_story_1015_10151202_35_dialog_content = "Desembucha.",
  ui_story_1015_10151202_36_dialog_content = "Depois de enviar um sinal de socorro naquela época, Grand Marshal Reinhardt imediatamente lançou uma operação de resgate em Undercity X.",
  ui_story_1015_10151202_37_dialog_content = "Só porque o fogo era muito forte, a Cidade Baixa já estava cheia de fumaça espessa quando a equipe de resgate chegou.",
  ui_story_1015_10151202_38_dialog_content = "Mesmo assim, o Grande Marechal ainda foi o primeiro a correr para o fogo. Ela procurou por você no inferno ardente por várias horas.",
  ui_story_1015_10151202_39_dialog_content = "Eu ouvi da equipe de resgate quando o Grande Marechal finalmente emergiu, seu corpo estava coberto de marcas de queimaduras carbonizadas e suas roupas foram queimadas em trapos cinzentos.",
  ui_story_1015_10151202_40_dialog_content = "Mas ela não se importava com quanta dor ela estava sentindo, tudo o que ela sentia era arrependimento - arrependimento por não ser capaz de encontrar sua amada irmã.",
  ui_story_1015_10151202_41_dialog_content = "...",
  ui_story_1015_10151202_42_dialog_content = "Então, agora você sabe.",
  ui_story_1015_10151202_43_dialog_content = "Naquela época, o Grande Marechal se recusou a desistir de você. Ninguém desistiu de você.",
  ui_story_1015_10151202_44_dialog_content = "Foi você que teimosamente pensou que tinha sido abandonado, virou as costas para Illumina e desertou para aquele bando de Eclipsitas perversos.",
  ui_story_1015_10151202_45_dialog_content = "Tudo o que você fez ao longo dos anos, não foi apenas retaliação contra aqueles que você pensou que desistiram de você?",
  ui_story_1015_10151202_46_dialog_content = "Agora você sabe que, se não tivesse partido por conta própria, ninguém iria querer desistir de você.",
  ui_story_1015_10151202_47_dialog_content = "Sua vingança foi construída sobre uma proposta falsa desde o início!",
  ui_story_1015_10151202_48_dialog_content = "Pare de resistir. Você não tem motivos para ser hostil com Illumina e não há saída.",
  ui_story_1015_10151202_49_dialog_content = "Hehe.",
  ui_story_1015_10151202_50_dialog_content = "Depois de todos esses anos, esses fósseis antigos conseguiram, de alguma forma, manter seu gosto excepcionalmente ruim.",
  ui_story_1015_10151202_51_dialog_content = "Eles ainda têm uma queda por cães totalmente tolos.",
  ui_story_1015_10151202_52_dialog_content = "...",
  ui_story_1015_10151202_53_dialog_content = "Você acha que a razão pela qual escolhi deixar a Illumina foi por causa de algo tão trivial quanto me sentir traído?",
  ui_story_1015_10151202_54_dialog_content = "Você está completamente errado.",
  ui_story_1015_10151202_55_dialog_content = "Então, por que você traiu Illumina?",
  ui_story_1015_10151202_56_dialog_content = "O motivo da minha partida é simples.",
  ui_story_1015_10151202_57_dialog_content = "O ambiente fornecido pela Federação Illumina não era mais suficiente para eu conduzir minha pesquisa científica avançada.",
  ui_story_1015_10151202_58_dialog_content = "Nem as cobaias disponíveis nem os materiais de pesquisa fornecidos poderiam me ajudar a fazer novos avanços.",
  ui_story_1015_10151202_59_dialog_content = "Portanto, optei por sair devido à possibilidade de novos avanços oferecidos pela tecnologia que o Eclipse havia dominado.",
  ui_story_1015_10151202_60_dialog_content = "Isso é tudo.",
  ui_story_1015_10151202_61_dialog_content = "<color=#e8d9bb>Enquanto isso, em algum lugar na Cidade Baixa...</color>",
  ui_story_1015_10151202_62_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1015_10151202_63_dialog_content = "Na hora certa.",
  ui_story_1015_10151202_64_dialog_content = "Seus planos são sempre tão precisos quanto perfeitos.",
  ui_story_1015_10151202_65_dialog_content = "<color=#e8d9bb>Zumbido...</color>",
  ui_story_1015_10151202_66_dialog_content = "é hora do <color=#FFB400>vassoura</color> para fazer uma aparição.",
  ui_story_1015_10151301_1_dialog_content = "<color=#e8d9bb>Bwee-Bwee-</color>",
  ui_story_1015_10151301_2_dialog_content = "Não aguento todo esse barulho.",
  ui_story_1015_10151301_3_dialog_content = "O quê?",
  ui_story_1015_10151301_4_dialog_content = "Eu pensei que você poderia ser um pouco mais forte do que aqueles ratos.",
  ui_story_1015_10151301_5_dialog_content = "Agora parece claro para mim que você não é melhor do que eles.",
  ui_story_1015_10151301_6_dialog_content = "Corte a energia.",
  ui_story_1015_10151301_7_dialog_content = "Não! Proteja o interruptor de alimentação!",
  ui_story_1015_10151301_8_dialog_content = "<anim type=Shake><size=45>Gaaah!</size></anim>",
  ui_story_1015_10151301_9_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1015_10151301_10_dialog_content = "Droga... O portão principal da Cidade Baixa está conectado ao sistema de energia.",
  ui_story_1015_10151301_11_dialog_content = "Assim que a energia acabar, o portão será travado.",
  ui_story_1015_10151301_12_dialog_content = "A saída é atrás daquela porta?",
  ui_story_1015_10151301_13_dialog_content = "Não, há algo... mais problemático do que uma saída ali atrás.",
  ui_story_1015_10151301_14_dialog_content = "O que é isso exatamente?",
  ui_story_1015_10151301_15_dialog_content = "<color=#e8d9bb>Crepitar—</color>",
  ui_story_1015_10151301_16_dialog_content = "Deixe-me dizer-lhe a resposta.",
  ui_story_1015_10151301_17_dialog_content = "Um Chord Link está atrás dessa porta.",
  ui_story_1015_10151301_19_dialog_content = "Seja o que for que você esteja tentando fazer, pare agora mesmo!",
  ui_story_1015_10151301_20_dialog_content = "Esse dispositivo está incompleto... Ninguém sabe quais podem ser as consequências de usá-lo de forma imprudente!",
  ui_story_1015_10151301_21_dialog_content = "Tenho que admitir, você está muito bem informado.",
  ui_story_1015_10151301_22_dialog_content = "Mas não se esqueça, ratinho...",
  ui_story_1015_10151301_23_dialog_content = "Você não é um pesquisador, e toda a sua compreensão desta máquina vem daquele velho.",
  ui_story_1015_10151301_24_dialog_content = "A razão pela qual você acha que esta máquina representa uma ameaça é simplesmente que—",
  ui_story_1015_10151301_25_dialog_content = "Você não tem ideia de como usá-lo.",
  ui_story_1015_10151301_26_dialog_content = "<color=#e8d9bb>Crocante—</color>",
  ui_story_1015_10151301_27_dialog_content = "Os fatores interferentes deste experimento foram eliminados. Vamos continuar.",
  ui_story_1015_10151301_28_dialog_content = "Venha aqui, sujeito de teste.",
  ui_story_1015_10151301_29_dialog_content = "...",
  ui_story_1015_10151301_30_dialog_content = "<color=#e8d9bb>Enquanto isso na cidade de Gannon...</color>",
  ui_story_1015_10151301_31_dialog_content = "<color=#e8d9bb>Tzzst—</color>",
  ui_story_1015_10151301_32_dialog_content = "Capitão Wrath, uma missão urgente requer sua atenção. Por favor, responda se você copiar!",
  ui_story_1015_10151301_33_dialog_content = "Uma missão urgente? Que tipo de missão urgente poderia estar chegando neste momento?",
  ui_story_1015_10151301_34_dialog_content = "Que curioso... Vamos ouvir e descobrir.",
  ui_story_1015_10151301_35_dialog_content = "Recebido, por favor, vá em frente.",
  ui_story_1015_10151301_36_dialog_content = "Undercity X é suspeito de ter sido invadido por Forsakin. O Comitê ordenou que você forneça apoio e capture Forsakin e Helios imediatamente.",
  ui_story_1015_10151301_37_dialog_content = "<size=45>O quê?!</size>",
  ui_story_1015_10151301_38_dialog_content = "Abandono? Ela realmente correu de volta para o território Illumina...?",
  ui_story_1015_10151301_39_dialog_content = "...",
  ui_story_1015_10151301_40_dialog_content = "Se for esse o caso, Wrath, Eu irei com voce.",
  ui_story_1015_10151301_41_dialog_content = "Eu sabia que você não poderia deixar ir.",
  ui_story_1015_10151301_42_dialog_content = "Mas você tem que me prometer que não fará nenhuma bobagem.",
  ui_story_1015_10151301_43_dialog_content = "Claro, eu prometo a você. Esta é a sua missão - não vou me envolver mais do que o necessário.",
  ui_story_1015_10151301_44_dialog_content = "Ok, então... Vamos.",
  ui_story_1015_10151302_1_dialog_content = "<color=#e8d9bb>Toc toc toc..</color>",
  ui_story_1015_10151302_2_dialog_content = "Pode entrar.",
  ui_story_1015_10151302_3_dialog_content = "Suspiro... Suspiro... Reportando!",
  ui_story_1015_10151302_4_dialog_content = "Senhor, Wrath está a caminho, conforme nosso plano, e deve chegar dentro de uma hora.",
  ui_story_1015_10151302_5_dialog_content = "Mas houve uma pequena mudança no plano...Reinhardt também veio junto.",
  ui_story_1015_10151302_6_dialog_content = "Ah?",
  ui_story_1015_10151302_7_dialog_content = "Tudo bem. Eu esperava tanto.",
  ui_story_1015_10151302_8_dialog_content = "Isso também fazia parte do seu plano?",
  ui_story_1015_10151302_9_dialog_content = "Heh, isso não fazia parte do meu plano.",
  ui_story_1015_10151302_10_dialog_content = "Mas a fumaça preta está subindo do laboratório Chord Link...",
  ui_story_1015_10151302_11_dialog_content = "Não se preocupe com esses incêndios. Eu vi pelos monitores de vigilância que eles não vão queimar por muito tempo.",
  ui_story_1015_10151302_12_dialog_content = "Sente-se e beba alguma coisa. De agora em diante, tudo o que precisamos fazer é sentar e assistir ao show.",
  ui_story_1015_10151302_13_dialog_content = "Sim, senhor.",
  ui_story_1015_10151302_14_dialog_content = "Não é à toa que não consegui vencer aquele jogo do Coringa contra ela.",
  ui_story_1015_10151302_15_dialog_content = "Acontece que ela já havia visto o coração das pessoas.",
  ui_story_1015_10151302_16_dialog_content = "Denier, não, Forsakin, realmente merece nossa inveja.",
  ui_story_1015_10151302_17_dialog_content = "...?",
  ui_story_1015_10151302_18_dialog_content = "Você não a inveja?",
  ui_story_1015_10151302_19_dialog_content = "Senhor, eu...",
  ui_story_1015_10151302_20_dialog_content = "De fato. Você não é um pesquisador. É perfeitamente normal que você não a inveje.",
  ui_story_1015_10151302_21_dialog_content = "...",
  ui_story_1015_10151302_22_dialog_content = "Agora você está se perguntando o que há nela que eu invejo?",
  ui_story_1015_10151302_23_dialog_content = "Sim, senhor.",
  ui_story_1015_10151302_24_dialog_content = "Ela possui uma característica única que a torna a pesquisadora perfeita.",
  ui_story_1015_10151302_25_dialog_content = "Persistência?",
  ui_story_1015_10151302_26_dialog_content = "Crueldade.",
  ui_story_1015_10151302_27_dialog_content = "Há um velho ditado Illumina—",
  ui_story_1015_10151302_28_dialog_content = "\"Não há bem ou mal inerente na ciência e na tecnologia, mas apenas nos corações dos aurorianos que os manejam.\"",
  ui_story_1015_10151302_29_dialog_content = "No entanto, muitas vezes chega um momento em que é preciso primeiro se tornar um vilão para levar a civilização adiante.",
  ui_story_1015_10151302_30_dialog_content = "Você nem sempre pode ter seu bolo e comê-lo, e Forsakin está bem ciente disso. E aquela senhora também sabe disso...",
  ui_story_1015_10151302_31_dialog_content = "Para obter os resultados da pesquisa que procurava, ela foi capaz de tratar seus ex-companheiros como cobaias sem hesitação.",
  ui_story_1015_10151302_32_dialog_content = "Esta é a prova mais decisiva de sua crueldade.",
  ui_story_1015_10151302_33_dialog_content = "Mas não é verdade que ela não teve outra escolha?",
  ui_story_1015_10151302_34_dialog_content = "Não, não, não, nós não a forçamos.",
  ui_story_1015_10151302_35_dialog_content = "Tudo o que fizemos foi criar uma oportunidade ligeiramente restritiva, mas incrivelmente atraente para ela.",
  ui_story_1015_10151302_36_dialog_content = "Aproveitar esta oportunidade foi uma decisão inteiramente dela.",
  ui_story_1015_10151302_37_dialog_content = "Sua pesquisa nunca se desviou da essência deste experimento - usando métodos científicos para explorar os limites do potencial biológico.",
  ui_story_1015_10151302_38_dialog_content = "Este tem sido o caso desde o Projeto Sol Artificial inicial.",
  ui_story_1015_10151302_39_dialog_content = "Você conhece o Projeto Sol Artificial, não é? Foi o antecessor do Programa Phospherus.",
  ui_story_1015_10151302_40_dialog_content = "Sua maior conquista foi a tecnologia de aprimoramento auroriano, desenvolvida independentemente pela Illumina. No entanto, os resultados foram instáveis devido às limitações de nossa tecnologia não desenvolvida.",
  ui_story_1015_10151302_41_dialog_content = "Uma única força poderosa se move livremente dentro dos aurorianos e só pode ser domada por uma vontade forte.",
  ui_story_1015_10151302_42_dialog_content = "O resultado de fazer isso é que a taxa de sucesso é extremamente baixa e o alvo também está sujeito a perder o controle de seu poder.",
  ui_story_1015_10151302_43_dialog_content = "Por sua vez, o resultado de perder o controle é a morte, invalidez permanente ou... tornar-se um desses monstros.",
  ui_story_1015_10151302_44_dialog_content = "No entanto, o antigo Denier, também conhecido como Forsakin, não sucumbiu a nenhum desses destinos.",
  ui_story_1015_10151302_45_dialog_content = "Ela foi considerada um fracasso?",
  ui_story_1015_10151302_46_dialog_content = "A rigor, não.",
  ui_story_1015_10151302_47_dialog_content = "Ela foi uma cobaia de sucesso, mas a trajetória de seu sucesso não correspondeu às nossas expectativas.",
  ui_story_1015_10151302_48_dialog_content = "O que queríamos era um sujeito com força aprimorada, mas no caso dela, seu intelecto foi aprimorado.",
  ui_story_1015_10151302_49_dialog_content = "Seu sucesso a tornou a pesquisadora mais talentosa e a maior ameaça oculta em Illumina.",
  ui_story_1015_10151302_50_dialog_content = "Você já viu como essa história termina. Ela sem dúvida se tornou uma traidora, estando em oposição direta a Illumina.",
  ui_story_1015_10151302_51_dialog_content = "Então, com relação a todos os Illumina, Reinhardt foi o produto de maior sucesso do Projeto Sol Artificial.",
  ui_story_1015_10151302_52_dialog_content = "Mas ainda há uma coisa que não entendo.",
  ui_story_1015_10151302_53_dialog_content = "Como determinar se um auroriano modificado pelo Projeto Sol Artificial é bem-sucedido?",
  ui_story_1015_10151302_54_dialog_content = "Afinal, nem todas as características de falha podem se manifestar imediatamente após o aprimoramento.",
  ui_story_1015_10151302_55_dialog_content = "Você ainda se lembra da batalha que ocorreu em Undercity 80?",
  ui_story_1015_10151302_56_dialog_content = "Sim, eu me lembro.",
  ui_story_1015_10151302_57_dialog_content = "Na ocasião, revisei as informações transmitidas à equipe individual, modificadas pelo Projeto Sol Artificial, de acordo com as exigências do Comitê.",
  ui_story_1015_10151302_58_dialog_content = "Essa falsa inteligência foi usada para guiá-los para um cerco Eclipsite.",
  ui_story_1015_10151302_59_dialog_content = "Ainda me lembro que muitas equipes de reconhecimento foram comprometidas naquela época para obter informações precisas suficientes.",
  ui_story_1015_10151302_60_dialog_content = "A equipe do meu subordinado era um deles, e ele foi o único de sua equipe que sobreviveu.",
  ui_story_1015_10151302_61_dialog_content = "Oh, acho que me lembro de ouvir a história dele. Qual era o nome dele?",
  ui_story_1015_10151302_62_dialog_content = "<color=#FFB400>Anatoli</color>.",
  ui_story_1015_10151302_63_dialog_content = "Ah, sim, esse era o nome. Ouvi dizer que você recentemente o promoveu a vice de Reinhardt?",
  ui_story_1015_10151302_64_dialog_content = "Ele sabe sobre este assunto? Mais importante, ele é confiável o suficiente para monitorar as ações de Reinhardt?",
  ui_story_1015_10151302_65_dialog_content = "Acredito que ele é confiável em sua capacidade de coletar informações.",
  ui_story_1015_10151302_66_dialog_content = "Além disso, esta tarefa em si é um teste de sua lealdade.",
  ui_story_1015_10151302_67_dialog_content = "Se você acredita que isso é verdade, vá em frente e faça dessa maneira.",
  ui_story_1015_10151302_68_dialog_content = "Nós saímos do assunto. Vamos falar sobre Undercity 80.",
  ui_story_1015_10151302_69_dialog_content = "Essa batalha foi uma triagem dos sujeitos modificados.",
  ui_story_1015_10151302_70_dialog_content = "Levando-os intencionalmente a uma luta desesperada, permitindo-lhes levar sua Lumina ao limite, e então...",
  ui_story_1015_10151302_71_dialog_content = "Os indivíduos mais fracos foram eliminados diretamente.",
  ui_story_1015_10151302_72_dialog_content = "Indivíduos com defeitos mentais e instabilidades também podem perder o controle e, por fim, ser eliminados em tais situações extremas.",
  ui_story_1015_10151302_73_dialog_content = "Mas os súditos bem-sucedidos resistiram a essa batalha amarga e sobreviveram.",
  ui_story_1015_10151302_74_dialog_content = "Mas... não foi justamente porque a taxa de sucesso era extremamente baixa que o projeto acabou sendo cancelado?",
  ui_story_1015_10151302_75_dialog_content = "Até que Illumina obteve aquele Chord Link incompleto.",
  ui_story_1015_10151302_76_dialog_content = "É isso mesmo, o Projeto Sol Artificial não teria sido reiniciado.",
  ui_story_1015_10151302_77_dialog_content = "Mas aquele Chord Link marcou um ponto de virada.",
  ui_story_1015_10151302_78_dialog_content = "O Chord Link foi o auge da tecnologia Caelestite, representando uma nova fonte de energia diferente do Projeto Sol Artificial.",
  ui_story_1015_10151302_79_dialog_content = "Ao integrar essas duas tecnologias, nasceram as cobaias do Programa Phospherus.",
  ui_story_1015_10151302_80_dialog_content = "Os aurorianos modificados pelo programa Phospherus possuem o poder derivado dessas duas tecnologias diferentes em seus corpos.",
  ui_story_1015_10151302_81_dialog_content = "Essas duas forças se contrabalançam e, até certo ponto, aumentam a taxa de sucesso do aprimoramento.",
  ui_story_1015_10151302_82_dialog_content = "No entanto, o equilíbrio não é estável o suficiente, então a maioria dos aurorianos modificados pelo programa Phospherus são muito frágeis.",
  ui_story_1015_10151302_83_dialog_content = "Uma vez que seu tremendo poder é usado em excesso, o delicado equilíbrio entre as duas forças pode ser facilmente quebrado.",
  ui_story_1015_10151302_84_dialog_content = "E seus corpos também entrarão em colapso com isso.",
  ui_story_1015_10151302_85_dialog_content = "Axelia é um exemplo muito bom disso.",
  ui_story_1015_10151302_86_dialog_content = "Mas desta vez é diferente. Forsakin trouxe um novo poder, e sua pesquisa pode levar o experimento a novos patamares.",
  ui_story_1015_10151302_87_dialog_content = "Você quer dizer... o <color=#FFB400>semente</color>?",
  ui_story_1015_10151302_88_dialog_content = "Correto.",
  ui_story_1015_10151302_89_dialog_content = "Forsakin estudou a semente por tantos anos, e ela já se tornou a coroação da tecnologia Eclipsite.",
  ui_story_1015_10151302_90_dialog_content = "A semente se tornará a última peça do quebra-cabeça, e Forsakin é o único capaz de colocá-la.",
  ui_story_1015_10151302_91_dialog_content = "Por fim, essas três forças formarão um todo equilibrado dentro do corpo auroriano, tornando-se uma força nova e estável.",
  ui_story_1015_10151302_92_dialog_content = "...!",
  ui_story_1015_10151302_93_dialog_content = "Quanto aos resultados cruciais do primeiro teste, só podemos esperar para ver.",
  ui_story_1015_10151302_94_dialog_content = "<color=#e8d9bb>Enquanto isso, no Laboratório Chord Link da Illumina Federation</color>",
  ui_story_1015_10151302_95_dialog_content = "<color=#e8d9bb>Bate, bate!</color>",
  ui_story_1015_10151302_96_dialog_content = "Que barulhento.",
  ui_story_1015_10151302_97_dialog_content = "Embora este ambiente seja pouco adequado para esta experiência, será suficiente.",
  ui_story_1015_10151302_98_dialog_content = "Iniciando as verificações finais dos parâmetros.",
  ui_story_1015_10151302_99_dialog_content = "Todos os parâmetros verificados para serem precisos.",
  ui_story_1015_10151302_100_dialog_content = "É hora de adicionar os materiais experimentais finais.",
  ui_story_1015_10151302_101_dialog_content = "Vamos começar o experimento.",
  ui_story_1015_10151302_102_dialog_content = "A semente guiará a direção da evolução.",
  ui_story_1015_10151302_103_dialog_content = "<color=#e8d9bb>Fora do Chord Link Laboratory</color>",
  ui_story_1015_10151302_104_dialog_content = "Dispersem, pétalas de gelo!",
  ui_story_1015_10151302_105_dialog_content = "<color=#e8d9bb>Baque-!!!</color>",
  ui_story_1015_10151302_106_dialog_content = "Mesmo depois de suportar uma explosão e tantos golpes, parece que não conseguimos fazer uma única mossa nesta porta.",
  ui_story_1015_10151302_107_dialog_content = "Parece que a entrada forçada não é mais uma opção viável.",
  ui_story_1015_10151302_108_dialog_content = "Afinal, os materiais à prova de explosão mais fortes existentes foram usados durante a construção desta instalação.",
  ui_story_1015_10151302_109_dialog_content = "Os recursos originalmente destinados a evitar possíveis incêndios agora se tornaram obstáculos.",
  ui_story_1015_10151302_110_dialog_content = "O Chord Link atrás desta porta é provavelmente uma parte essencial do experimento de Forsakin.",
  ui_story_1015_10151302_111_dialog_content = "Se ela puder usá-lo de forma imprudente, isso causará ainda mais problemas no futuro.",
  ui_story_1015_10151302_112_dialog_content = "Sim, precisamos detê-la imediatamente!",
  ui_story_1015_10151302_113_dialog_content = "Não há nada que possamos fazer?",
  ui_story_1015_10151302_114_dialog_content = "Deixa eu pensar...",
  ui_story_1015_10151302_115_dialog_content = "Talvez haja uma maneira.",
  ui_story_1015_10151302_116_dialog_content = "O que foi?",
  ui_story_1015_10151302_117_dialog_content = "Esta Cidade Baixa costumava ser o laboratório secreto de Forsakin. Portanto, um grande número de cobaias reprovadas era descartado aqui todos os dias.",
  ui_story_1015_10151302_118_dialog_content = "Para economizar tempo, ela construiu uma tubulação do laboratório até a sala de tratamento de resíduos no porão.",
  ui_story_1015_10151302_119_dialog_content = "Durante a reconstrução da Cidade Baixa, este oleoduto foi selado dentro das paredes, mas não foi desmontado.",
  ui_story_1015_10151302_120_dialog_content = "Embora possa parecer um desvio colossal, arrombar a parede e selar o oleoduto será muito mais fácil do que arrombar esta porta.",
  ui_story_1015_10151302_121_dialog_content = "Podemos usar este atalho que ela usou como rampa de descarte de lixo para saltar sobre ela.",
  ui_story_1015_10151401_1_dialog_content = "Esta é a parte mais fraca da parede!",
  ui_story_1015_10151401_2_dialog_content = "<color=#e8d9bb>Bang! Bang!</color>",
  ui_story_1015_10151401_3_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_1015_10151401_4_dialog_content = "A calha está aberta!",
  ui_story_1015_10151401_5_dialog_content = "Pare aí mesmo, Forsakin!",
  ui_story_1015_10151401_6_dialog_content = "Já derrotamos todos os Eclipsites sob seu comando!",
  ui_story_1015_10151401_7_dialog_content = "Você está muito atrasado.",
  ui_story_1015_10151401_8_dialog_content = "Minha experiência já produziu resultados.",
  ui_story_1015_10151401_9_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_1015_10151401_10_dialog_content = "PlayerName, olhar! O link do acorde!",
  ui_story_1015_10151401_11_dialog_content = "Algo parece estar emergindo de dentro dela!",
  ui_story_1015_10151401_12_dialog_content = "O que... O que é isso?!",
  ui_story_1015_10151401_13_dialog_content = "Que tipo de monstro é esse?!",
  ui_story_1015_10151401_14_dialog_content = "Registro de laboratório do 112º experimento na cobaia Helios—",
  ui_story_1015_10151401_15_dialog_content = "Processo experimental: ao usar o Chord Link para aprimorar o assunto do Projeto Sol Artificial—",
  ui_story_1015_10151401_16_dialog_content = "Uma semente foi adicionada ao Chord Link.",
  ui_story_1015_10151401_17_dialog_content = "Resultados do experimento: o experimento foi inicialmente bem-sucedido e o risco de o sujeito interromper a atividade foi significativamente reduzido.",
  ui_story_1015_10151401_18_dialog_content = "Ela está gravando seu experimento?",
  ui_story_1015_10151401_19_dialog_content = "Ela transformou pessoalmente seu ex-companheiro neste monstro, e ainda tem a insensível presença de espírito para completar um registro do experimento...",
  ui_story_1015_10151401_20_dialog_content = "O oficial Ulysses estava certo, você é um animal de sangue frio até a medula.",
  ui_story_1015_10151401_21_dialog_content = "Ulisses?",
  ui_story_1015_10151401_22_dialog_content = "Aquele velho provavelmente está ansioso pelos resultados desse experimento mais do que eu.",
  ui_story_1015_10151401_23_dialog_content = "O que você disse?",
  ui_story_1015_10151401_24_dialog_content = "É hora de prosseguir com o próximo experimento.",
  ui_story_1015_10151401_25_dialog_content = "Verificando a estabilidade do sujeito através do combate real.",
  ui_story_1015_10151401_26_dialog_content = "Vá em frente, cobaia, separe-os.",
  ui_story_1015_10151401_27_dialog_content = "!!!",
  ui_story_1015_10151401_28_dialog_content = "PlayerName, encontre um lugar para se esconder!",
  ui_story_1015_10151401_29_dialog_content = "T-tudo bem!",
  ui_story_1015_10151401_30_dialog_content = "...",
  ui_story_1015_10151401_31_dialog_content = "(Aquele monstro não respondeu? Isso significa que o experimento de Forsakin falhou?)",
  ui_story_1015_10151401_32_dialog_content = "Entendo, parece que meu experimento alcançou ainda mais sucesso.",
  ui_story_1015_10151401_33_dialog_content = "(Mais sucesso? O que ela quer dizer?)",
  ui_story_1015_10151401_34_dialog_content = "De fato, parece que uma abordagem diferente é necessária.",
  ui_story_1015_10151401_35_dialog_content = "Helios, Soldado da Illumina—",
  ui_story_1015_10151401_36_dialog_content = "...!",
  ui_story_1015_10151401_37_dialog_content = "Ele reagiu! Será que ele realmente entende?!",
  ui_story_1015_10151401_38_dialog_content = "Diante de vocês agora estão os traidores e inimigos da Federação Illumina.",
  ui_story_1015_10151401_39_dialog_content = "Sua missão é eliminá-los.",
  ui_story_1015_10151401_40_dialog_content = "<anim type=Shake><size=50>Gahhhhhhhh!</size></anim>",
  ui_story_1015_10151401_41_dialog_content = "Espere! Parar!",
  ui_story_1015_10151401_42_dialog_content = "Não somos seus inimigos! Forsakin é um traidor e inimigo de Illumina!",
  ui_story_1015_10151401_43_dialog_content = "<anim type=Shake><size=50>Graagh!!!</size></anim>",
  ui_story_1015_10151401_44_dialog_content = "Ugh!",
  ui_story_1015_10151401_45_dialog_content = "É inútil... Parece que ainda não recuperou totalmente a sanidade.",
  ui_story_1015_10151401_46_dialog_content = "Vamos derrubá-lo primeiro.",
  ui_story_1015_10151402_1_dialog_content = "<anim type=Shake><size=50>Gahhhhhhhh!</size></anim>",
  ui_story_1015_10151402_2_dialog_content = "Como ele ficou tão forte...?",
  ui_story_1015_10151402_3_dialog_content = "Não só é mais forte, como também suas ações se tornaram mais imprevisíveis.",
  ui_story_1015_10151402_4_dialog_content = "Todos, cuidado!",
  ui_story_1015_10151402_5_dialog_content = "Se antes ele apenas contra-atacava instintivamente, parece que agora começou a usar táticas.",
  ui_story_1015_10151402_6_dialog_content = "Este monstro aprendeu a estratégia?",
  ui_story_1015_10151402_7_dialog_content = "A situação tomou um rumo problemático...",
  ui_story_1015_10151402_8_dialog_content = "O experimento de fato alcançou mais sucesso. Minha teoria estava correta.",
  ui_story_1015_10151402_9_dialog_content = "As três forças diferentes interagindo dentro do sujeito de teste formaram um estado estável.",
  ui_story_1015_10151402_10_dialog_content = "Mesmo durante o combate de alta intensidade, o equilíbrio permanece intacto.",
  ui_story_1015_10151402_11_dialog_content = "E o ponto mais importante é que esse experimento pode ser replicado.",
  ui_story_1015_10151402_12_dialog_content = "Agora, tudo o que preciso fazer é verificar os resultados finais para provar que o experimento foi totalmente bem-sucedido.",
  ui_story_1015_10151402_13_dialog_content = "<anim type=Shake>Rugido...</anim>",
  ui_story_1015_10151402_14_dialog_content = "Tenha cuidado - há algo errado com ele!",
  ui_story_1015_10151402_15_dialog_content = "Isso é Lumina ou Darkflow? Quando eles estão misturados assim, eu nem consigo diferenciá-los!",
  ui_story_1015_10151402_16_dialog_content = "Não se preocupe com isso agora, prepare-se para defender!",
  ui_story_1015_10151402_17_dialog_content = "<anim type=Shake><size=50>Ahhhh!</size></anim>",
  ui_story_1015_10151402_18_dialog_content = "O que é isso?!",
  ui_story_1015_10151402_19_dialog_content = "A aparência dele acabou de mudar?!",
  ui_story_1015_10151402_20_dialog_content = "Eu vi isso uma vez antes, nos fragmentos de memórias que senti em Undercity 80...",
  ui_story_1015_10151402_21_dialog_content = "Isto é o que ele originalmente parecia!",
  ui_story_1015_10151402_22_dialog_content = "Este passo foi finalmente alcançado.",
  ui_story_1015_10151402_23_dialog_content = "Os resultados finais do experimento também foram verificados.",
  ui_story_1015_10151402_24_dialog_content = "Um estado estável traz maiores benefícios, pois torna esse poder controlável.",
  ui_story_1015_10151402_25_dialog_content = "Ele pode conter os efeitos colaterais do Projeto Sol Artificial, que fez com que os aurorianos perdessem a sanidade e se tornassem monstros.",
  ui_story_1015_10151402_26_dialog_content = "Ao mesmo tempo, também pode permitir que o auroriano mude de forma de forma autônoma.",
  ui_story_1015_10151402_27_dialog_content = "Isso é exatamente o que eu esperava alcançar.",
  ui_story_1015_10151402_28_dialog_content = "<anim type=Shake>Urgh...</anim>",
  ui_story_1015_10151402_29_dialog_content = "<anim type=Shake>Onde estou...?</anim>",
  ui_story_1015_10151402_30_dialog_content = "E-Ele pode falar?!",
  ui_story_1015_10151402_31_dialog_content = "Não... não... Por que... não estou na Cidade Baixa 80?",
  ui_story_1015_10151402_32_dialog_content = "Quem é você?",
  ui_story_1015_10151402_33_dialog_content = "Na verdade, ele foi restaurado à sua forma auroriana... Sua sanidade também foi restaurada?",
  ui_story_1015_10151402_34_dialog_content = "Eu sou Yingel, um oficial de inteligência trabalhando diretamente sob a autoridade do Comitê.",
  ui_story_1015_10151402_35_dialog_content = "Capitão Helios, você é suspeito de conspirar com o inimigo... de colaborar com os Eclipsites.",
  ui_story_1015_10151402_36_dialog_content = "Abaixe sua arma imediatamente, cesse sua resistência e coopere com a investigação do Comitê!",
  ui_story_1015_10151402_37_dialog_content = "Não, eu não...",
  ui_story_1015_10151402_38_dialog_content = "Como... eu poderia conspirar com o inimigo?",
  ui_story_1015_10151402_39_dialog_content = "eu sou... eu...",
  ui_story_1015_10151402_40_dialog_content = "Calma, Capitão Hélio!",
  ui_story_1015_10151402_41_dialog_content = "Olhe a sua volta. Isso não é Undercity 80.",
  ui_story_1015_10151402_42_dialog_content = "Você não precisa mais lutar...",
  ui_story_1015_10151402_43_dialog_content = "O que aconteceu? Por que estou aqui?",
  ui_story_1015_10151402_44_dialog_content = "Por que... não consigo me lembrar...?",
  ui_story_1015_10151402_45_dialog_content = "Urgh...!",
  ui_story_1015_10151402_46_dialog_content = "A capacidade cognitiva do sujeito está intacta, mas sua memória parece desordenada e incompleta. Nenhuma nova memória foi formada depois de perder o controle.",
  ui_story_1015_10151402_47_dialog_content = "Registrado temporariamente como um efeito colateral que requer atenção. Mais estudos são necessários para eliminar completamente esse efeito colateral.",
  ui_story_1015_10151402_48_dialog_content = "Claro, há uma possibilidade maior de que essa situação tenha sido causada por defeitos no próprio objeto.",
  ui_story_1015_10151402_49_dialog_content = "No geral, o experimento foi bem-sucedido.",
  ui_story_1015_10151402_50_dialog_content = "Eu finalmente dominei o processo de evolução.",
  ui_story_1015_10151402_51_dialog_content = "Resta apenas uma pergunta...",
  ui_story_1015_10151402_52_dialog_content = "(Esta cobaia será necessária para verificação subsequente.)",
  ui_story_1015_10151402_53_dialog_content = "(Preciso pensar em uma maneira de fazer com que ele venha comigo.)",
  ui_story_1015_10151402_54_dialog_content = "(No entanto, ele está gradualmente recuperando a consciência e a cognição - uma variável que não é propícia ao meu plano.)",
  ui_story_1015_10151402_55_dialog_content = "(No entanto, existem maneiras de lidar com esse tipo de sujeito de teste simplório.)",
  ui_story_1015_10151402_56_dialog_content = "Você... eu te reconheço...",
  ui_story_1015_10151402_57_dialog_content = "Você é... Negador?",
  ui_story_1015_10151402_58_dialog_content = "Por que você... parece assim...?",
  ui_story_1015_10151402_59_dialog_content = "Onde está a... Reinhardt...?",
  ui_story_1015_10151402_60_dialog_content = "Por que ela... não está com você...?",
  ui_story_1015_10151402_61_dialog_content = "...",
  ui_story_1015_10151402_62_dialog_content = "Tanto Denier quanto a pessoa que você costumava ser há muito foram abandonados por Illumina.",
  ui_story_1015_10151402_63_dialog_content = "Eu não sou Negador.",
  ui_story_1015_10151402_64_dialog_content = "Abandonado?",
  ui_story_1015_10151402_65_dialog_content = "<anim type=Shake>Ugh...!!!</anim>",
  ui_story_1015_10151402_66_dialog_content = "Ele está reunindo Darkflow!",
  ui_story_1015_10151402_67_dialog_content = "Forsakin está tentando agitá-lo com suas palavras para mergulhá-lo no caos novamente e fazê-lo se tornar um monstro?!",
  ui_story_1015_10151402_68_dialog_content = "Todo mundo está praticamente em suas últimas pernas, como é ...",
  ui_story_1015_10151402_69_dialog_content = "Ouça... Eles estão te chamando de monstro.",
  ui_story_1015_10151402_70_dialog_content = "<anim type=Shake>Não... eu não sou... eu não sou um monstro...</anim>",
  ui_story_1015_10151402_71_dialog_content = "<anim type=Shake>Eu sou... um soldado... da Illumina...</anim>",
  ui_story_1015_10151402_72_dialog_content = "Tsc...",
  ui_story_1015_10151402_73_dialog_content = "A Federação Illumina não tem mais lugar para você.",
  ui_story_1015_10151402_74_dialog_content = "Venha comigo e terá uma chance de sobreviver.",
  ui_story_1015_10151402_75_dialog_content = "Fique aqui, e apenas a morte o aguardará.",
  ui_story_1015_10151402_76_dialog_content = "Não acredite nela! Illumina nunca desiste de ninguém!",
  ui_story_1015_10151402_77_dialog_content = "A Federação Illumina abandona aqueles que não podem contribuir mais para sua causa, especialmente aqueles que falham.",
  ui_story_1015_10151402_78_dialog_content = "Grande marechal Reinhardt nunca desistiu de te procurar.",
  ui_story_1015_10151402_79_dialog_content = "Reinhardt nunca voltou com reforços.",
  ui_story_1015_10151402_80_dialog_content = "Ela não tinha voz no assunto! Os oficiais da Illumina a drogaram para que ela ficasse impotente para resgatá-lo!",
  ui_story_1015_10151402_81_dialog_content = "Eu vi tudo com minha habilidade psíquica. Eu sei que é absolutamente verdade!",
  ui_story_1015_10151402_82_dialog_content = "Não se esqueça, em Undercity 80, Reinhardt enfrentaram-nos, punhais em punho.",
  ui_story_1015_10151402_83_dialog_content = "Abra os olhos e veja. Seu ex-companheiro não é mais um auroriano.",
  ui_story_1015_10151402_84_dialog_content = "Ela é a única com sangue nas mãos!",
  ui_story_1015_10151402_85_dialog_content = "Você não odeia esses hipócritas?",
  ui_story_1015_10151402_86_dialog_content = "<size=45>Quieto, você!</size>",
  ui_story_1015_10151402_87_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1015_10151402_88_dialog_content = "<anim type=Shake><size=50>Urg!!!</size></anim>",
  ui_story_1015_10151402_89_dialog_content = "Por que-!",
  ui_story_1015_10151402_90_dialog_content = "... O que está fazendo?",
  ui_story_1015_10151402_91_dialog_content = "Eu sou... um soldado... da Illumina...",
  ui_story_1015_10151402_92_dialog_content = "Vou cooperar... com a investigação...",
  ui_story_1015_10151402_93_dialog_content = "Mas eu também... desejo proteger meu amigo...",
  ui_story_1015_10151402_94_dialog_content = "...",
  ui_story_1015_10151402_95_dialog_content = "Que tolo.",
  ui_story_1015_10151402_96_dialog_content = "Parece que a percepção do sujeito sobre si mesmo e sobre os outros é falha.",
  ui_story_1015_10151402_97_dialog_content = "Isso pode ser algum tipo de transtorno mental. Essa cognição errônea deve ser completamente erradicada.",
  ui_story_1015_10151402_98_dialog_content = "Isso é...",
  ui_story_1015_10151402_99_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1015_10151402_100_dialog_content = "O-O que foi isso?!",
  ui_story_1015_10151402_101_dialog_content = "Voltam, PlayerName! Um enorme buraco apareceu na porta!",
  ui_story_1015_10151402_102_dialog_content = "Algo muito poderoso está arrombando a porta!",
  ui_story_1015_10151402_103_dialog_content = "Caramba!!!",
  ui_story_1015_10151402_104_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_1015_10151402_105_dialog_content = "Essa é uma descrição precisa, mas não é algo - sou apenas eu.",
  ui_story_1015_10151402_106_dialog_content = "Então, você está realmente aqui, Forsakin.",
  ui_story_1015_10151402_107_dialog_content = "Bem na hora.",
  ui_story_1015_10151402_108_dialog_content = "Nos reencontramos, Reinhardt. Mesmo depois de todo esse tempo, você não fez nenhum progresso.",
  ui_story_1015_10151402_109_dialog_content = "Ainda voluntariamente sendo usado.",
  ui_story_1015_10151402_110_dialog_content = "Há quanto tempo, Forsakin.",
  ui_story_1015_10151402_111_dialog_content = "Parece que você não tem se saído muito bem com os Eclipsites. E agora, você caiu neste mais novo dos pontos baixos.",
  ui_story_1015_10151402_112_dialog_content = "Hum? Qual o seu nome? O que...?",
  ui_story_1015_10151402_113_dialog_content = "Um jogador bit contando com um antigo colega de classe para garantir sua posição não vale a pena lembrar.",
  ui_story_1015_10151402_114_dialog_content = "Isso é para ser um insulto? Você deve estar me confundindo com alguém que se importa.",
  ui_story_1015_10151402_115_dialog_content = "Quando eu te derrubar no chão mais tarde, não vá chorar procurando por sua irmã.",
  ui_story_1015_10151402_116_dialog_content = "Que imaturo.",
  ui_story_1015_10151402_117_dialog_content = "É aquele... Reinhardt?",
  ui_story_1015_10151402_118_dialog_content = "Hélio?! Sua aparência...",
  ui_story_1015_10151402_119_dialog_content = "Estes são... os reforços? Você finalmente...",
  ui_story_1015_10151402_120_dialog_content = "...",
  ui_story_1015_10151402_121_dialog_content = "Sim, desculpe por chegar tão tarde.",
  ui_story_1015_10151402_122_dialog_content = "Vim buscá-lo e trouxe reforços.",
  ui_story_1015_10151402_123_dialog_content = "Garanta este lugar!",
  ui_story_1015_10151402_124_dialog_content = "Sim, senhora!",
  ui_story_1015_10151402_125_dialog_content = "Exatamente como eu previ.",
  ui_story_1015_10151402_126_dialog_content = "Reinhardt, Vamos fazer um acordo.",
  ui_story_1015_10151402_127_dialog_content = "O quê...?",
  ui_story_1015_10151402_128_dialog_content = "Permitir que eu e minha cobaia saíssemos de Illumina não teria nenhum efeito adverso em você.",
  ui_story_1015_10151402_129_dialog_content = "Huh? Talvez você tenha estado na Noite Eterna por muito tempo. Parece que o Darkflow está no seu cérebro.",
  ui_story_1015_10151402_130_dialog_content = "Você não está em posição de negociar conosco agora.",
  ui_story_1015_10151402_131_dialog_content = "Não estou negociando com você.",
  ui_story_1015_10151402_132_dialog_content = "Esses velhos fósseis não me querem, querem ele.",
  ui_story_1015_10151402_133_dialog_content = "(O que ela quer dizer? O Comitê quer Helios?)",
  ui_story_1015_10151402_134_dialog_content = "(Mas minha missão era simplesmente capturar Forsakin e resgatar o Tenente Vice.)",
  ui_story_1015_10151402_135_dialog_content = "Você sabe exatamente o que acontecerá se ele cair nas mãos dessas pessoas.",
  ui_story_1015_10151402_136_dialog_content = "Não posso concordar com o seu pedido.",
  ui_story_1015_10151402_137_dialog_content = "Eu teria escolhido acreditar em você se fosse mais de uma década atrás, antes de você deixar Illumina.",
  ui_story_1015_10151402_138_dialog_content = "Mas depois de todos esses anos de luta, eu te conheço melhor do que ninguém.",
  ui_story_1015_10151402_139_dialog_content = "O que você quer fazer não é diferente do que eles querem.",
  ui_story_1015_10151402_140_dialog_content = "Entregue-o para mim e usarei meu status de Grande Marechal para protegê-lo. Não vou deixar ninguém encostar um dedo nele.",
  ui_story_1015_10151402_141_dialog_content = "Você não tem o poder.",
  ui_story_1015_10151402_142_dialog_content = "Essas negociações não vão a lugar nenhum. Não preciso perder mais tempo aqui.",
  ui_story_1015_10151402_143_dialog_content = "Jade.",
  ui_story_1015_10151402_144_dialog_content = "<anim type=Shake><size=50>Graaaaaah!</size></anim>",
  ui_story_1015_10151402_145_dialog_content = "Adeus.",
  ui_story_1015_10151402_146_dialog_content = "<color=#e8d9bb>Fwooosh!!!</color>",
  ui_story_1015_10151501_1_dialog_content = "Reportando. De acordo com as informações transmitidas pelo Coronel Yingel e major Anatoli, encontramos o Tenente Vice em um laboratório abandonado.",
  ui_story_1015_10151501_2_dialog_content = "Tenente Vice, voltando ao serviço!",
  ui_story_1015_10151501_3_dialog_content = "Vice! Você está bem? Você se machucou?",
  ui_story_1015_10151501_4_dialog_content = "Tô bem!",
  ui_story_1015_10151501_5_dialog_content = "Desculpe, eu fui tão descuidado e causei tantos problemas para todos...",
  ui_story_1015_10151501_6_dialog_content = "Contanto que você esteja de volta, são e salvo, então está tudo bem.",
  ui_story_1015_10151501_7_dialog_content = "Isso mesmo. Não seja muito duro consigo mesmo.",
  ui_story_1015_10151501_8_dialog_content = "Forsakin é um inimigo astuto. Levou todos os nossos esforços concentrados para lidar com ela.",
  ui_story_1015_10151501_9_dialog_content = "Certo...",
  ui_story_1015_10151501_10_dialog_content = "Como está indo a busca? Você encontrou algum vestígio de Forsakin?",
  ui_story_1015_10151501_11_dialog_content = "Reportando! Procuramos em toda a Cidade Baixa e não encontramos vestígios de Forsakin.",
  ui_story_1015_10151501_12_dialog_content = "E as várias entradas e saídas e a passagem da antiga Cidade Baixa?",
  ui_story_1015_10151501_13_dialog_content = "Todas as entradas e saídas eram vigiadas e ninguém foi visto entrando ou saindo.",
  ui_story_1015_10151501_14_dialog_content = "Eu vejo. No entanto, não podemos ter muita certeza. Continue a pesquisa.",
  ui_story_1015_10151501_15_dialog_content = "Sim, senhora!",
  ui_story_1015_10151501_16_dialog_content = "Forsakin realmente conseguiu desaparecer bem debaixo de nossos narizes sem sequer suar.",
  ui_story_1015_10151501_17_dialog_content = "Ela vomitou seu veneno e correu como o vento.",
  ui_story_1015_10151501_18_dialog_content = "Grande Marechal, Capitão Wrath—Acho que posso saber como Forsakin escapou.",
  ui_story_1015_10151501_19_dialog_content = "Hum? Conte-nos então.",
  ui_story_1015_10151501_20_dialog_content = "Forsakin projetou e construiu esta Cidade Baixa.",
  ui_story_1015_10151501_21_dialog_content = "Depois de construir a Cidade Baixa e antes de desertar da Federação Illumina, Forsakin viajou secretamente entre aqui e Gannon City várias vezes.",
  ui_story_1015_10151501_22_dialog_content = "De acordo com as informações que reuni, Forsakin é alguém que não suporta perder tempo com coisas inúteis.",
  ui_story_1015_10151501_23_dialog_content = "Então eu especulo que ela também pode ter construído uma passagem secreta que pode ser usada para viajar rapidamente entre aqui e a cidade de Gannon.",
  ui_story_1015_10151501_24_dialog_content = "Você está dizendo que ela pode já ter fugido para Gannon?",
  ui_story_1015_10151501_25_dialog_content = "Sim.",
  ui_story_1015_10151501_26_dialog_content = "Hum, isso faz sentido. Vou imediatamente organizar uma busca na cidade de Gannon para investigar.",
  ui_story_1015_10151501_27_dialog_content = "Reinhardt, Deixa eu cuidar disso.",
  ui_story_1015_10151501_28_dialog_content = "Não, como esse assunto está relacionado a Forsakin e Helios, devo resolver isso com minhas próprias mãos.",
  ui_story_1015_10151501_29_dialog_content = "É preciso porque esse assunto envolve esses dois, que você não pode ser chamado para lidar com isso.",
  ui_story_1015_10151501_30_dialog_content = "O Comitê designou essa missão para mim, então devo ser eu a garantir que ela seja cumprida.",
  ui_story_1015_10151501_31_dialog_content = "Além disso, nossos alvos são sua irmã e ex-camarada...",
  ui_story_1015_10151501_32_dialog_content = "Mesmo que eu acredite que você pode lidar com essa bagunça de maneira justa, há aqueles que não confiam tanto.",
  ui_story_1015_10151501_33_dialog_content = "Qualquer pessoa com olhos pode ver que eles estão tentando encontrar qualquer desculpa para mexer com você recentemente.",
  ui_story_1015_10151501_34_dialog_content = "E o Exercício Militar Conjunto está prestes a começar. Todas as forças do Astra terão seus olhos fixos em Illumina.",
  ui_story_1015_10151501_35_dialog_content = "O que você precisa fazer agora é simplesmente voltar para Gannon.",
  ui_story_1015_10151501_36_dialog_content = "O retorno não apenas ajudará a estabilizar a situação e garantirá sua autoridade...",
  ui_story_1015_10151501_37_dialog_content = "Enquanto você estiver no comando, mesmo que Forsakin esteja realmente em Gannon, ela não ousará causar problemas.",
  ui_story_1015_10151501_38_dialog_content = "...",
  ui_story_1015_10151501_39_dialog_content = "Se você não confia em mim, pode enviar um supervisor para ficar de olho em mim ou algo assim. Nem me importo de ter vários supervisores me observando — quanto mais, melhor.",
  ui_story_1015_10151501_40_dialog_content = "Como eu sempre disse, só estou interessado em bater em você de forma justa.",
  ui_story_1015_10151501_41_dialog_content = "É assim que sempre foi, assim é e sempre será.",
  ui_story_1015_10151501_42_dialog_content = "Eu tenho fé em você.",
  ui_story_1015_10151501_43_dialog_content = "Vou deixar a tarefa de perseguir Forsakin e trazer Helios de volta em suas mãos.",
  ui_story_1015_10151501_44_dialog_content = "Não se preocupe, prometo que os encontrarei.",
  ui_story_1015_10151501_45_dialog_content = "Bem, agora que está resolvido, por que vocês não voltam para Gannon City comigo? O que você diz, PlayerName?",
  ui_story_1015_10151501_46_dialog_content = "Mas, a missão...",
  ui_story_1015_10151501_47_dialog_content = "Uma vez que o Comitê confiou este assunto ao Capitão Wrath, você não precisa mais se preocupar com isso.",
  ui_story_1015_10151501_48_dialog_content = "Vamos cuidar do assunto em questão primeiro.",
  ui_story_1015_10151501_49_dialog_content = "Sim, senhora.",
  ui_story_1015_10151501_50_dialog_content = "Sim, entendi.",
  ui_story_1015_10151501_51_dialog_content = "<size=30>Na verdade, ainda tenho muito o que fazer para ajudá-lo a planejar a programação do Grande Marechal para o período de exercícios, bem como—</size>",
  ui_story_1015_10151501_52_dialog_content = "Anatoli.",
  ui_story_1015_10151501_53_dialog_content = "<size=45>Senhora!</size>",
  ui_story_1015_10151501_54_dialog_content = "Você tem alguma instrução adicional, Grande Marechal?",
  ui_story_1015_10151501_55_dialog_content = "Você não precisa mais me acompanhar. Vá e participe do exercício.",
  ui_story_1015_10151501_56_dialog_content = "Sim, espere um momento, Grande Marechal, não entrei para nenhuma equipe, então não posso participar do exercício.",
  ui_story_1015_10151501_57_dialog_content = "Você não precisa se preocupar com isso, um dos membros da equipe tem alguns negócios para atender e não pode participar.",
  ui_story_1015_10151501_58_dialog_content = "Você estará preenchendo a vaga.",
  ui_story_1015_10151501_59_dialog_content = "Sim, senhora. Em qual time eu estarei?",
  ui_story_1015_10151501_60_dialog_content = "Você deve estar bastante familiarizado com ela agora. É a equipe de Yingel.",
  ui_story_1015_10151501_61_dialog_content = "O que? Meu time?",
  ui_story_1015_10151501_62_dialog_content = "aconteceu alguma coisa com Axelia?",
  ui_story_1015_10151501_63_dialog_content = "Não, não é ela. É Sean.",
  ui_story_1015_10151501_64_dialog_content = "Acabei de receber notícias de Twilight.",
  ui_story_1015_10151501_65_dialog_content = "Aparentemente, a condição física de Sean de repente piorou e ele precisa ficar em Crepúsculo para observação temporária.",
  ui_story_1015_10151501_66_dialog_content = "Como ele está? Ele está bem?",
  ui_story_1015_10151501_67_dialog_content = "A mensagem de Twilight afirmou que ele apenas experimentou alguns fenômenos estranhos ao usar Luminatics que ele nunca havia experimentado antes.",
  ui_story_1015_10151501_68_dialog_content = "Pode estar relacionado a um defeito genético inato.",
  ui_story_1015_10151501_69_dialog_content = "Sério?",
  ui_story_1015_10151501_70_dialog_content = "Depois que terminarmos em Gannon, vamos a Twilight fazer uma visita a ele.",
  ui_story_1015_10151501_71_dialog_content = "Então, você quer que eu me junte a Yingel e Axelia?",
  ui_story_1015_10151501_72_dialog_content = "Cumprirei suas ordens.",
  ui_story_1015_10151501_73_dialog_content = "(É um pequeno desvio do plano original, mas ainda não é um problema. Devo conseguir fazer isso funcionar.)",
  ui_story_1015_10151501_74_dialog_content = "Também não tenho objeções.",
  ui_story_1015_10151501_75_dialog_content = "Isso resolve então.",
  ui_story_1015_10151501_76_dialog_content = "É hora de voltar para Gannon City.",
  ui_story_1015_10151501_77_dialog_content = "<color=#e8d9bb>Alguns dias depois, em Gannon City...</color>",
  ui_story_1015_10151501_78_dialog_content = "O trem está prestes a chegar em Gannon. Por favor, prepare-se para desembarcar e observe o espaço entre o trem e a plataforma.",
  ui_story_1015_10151501_79_dialog_content = "May a luz da iluminação guia você em sua jornada.",
  ui_story_1015_10151501_80_dialog_content = "Com licença, deixe-nos sair do trem, por favor.",
  ui_story_1015_10151501_81_dialog_content = "Há tantas pessoas fora hoje... Este é realmente o maior exercício militar em Astra!",
  ui_story_1015_10151501_82_dialog_content = "Mas este lugar é tão grande... Não nos enganamos, não é? Esta é mesmo a estação certa?",
  ui_story_1015_10151501_83_dialog_content = "Deve ser isso, de acordo com as instruções de Lady Carleen.",
  ui_story_1015_10151501_84_dialog_content = "Espero que não nos percamos...",
  ui_story_1015_10151501_85_dialog_content = "Beretta.",
  ui_story_1015_10151501_86_dialog_content = "Senhora Carleen!",
  ui_story_1015_10151501_87_dialog_content = "Conforme combinado, estou aqui para buscá-lo.",
  ui_story_1015_10151501_88_dialog_content = "Muito obrigado! Sem você aqui, definitivamente acabaríamos nos perdendo...",
  ui_story_1015_10151501_89_dialog_content = "Não mencione isso. Participe de mais desses exercícios e logo você estará familiarizado com essa área.",
  ui_story_1015_10151501_90_dialog_content = "Vamos.",
  ui_story_1015_10151501_91_dialog_content = "Sim, Lady Carleen!",
  ui_story_1015_10151501_92_dialog_content = "A garota agora não se parecia com aquela Lady?",
  ui_story_1015_10151501_93_dialog_content = "De fato, esse certamente parece ser o caso.",
  ui_story_1015_10151501_94_dialog_content = "Você não vai dizer olá?",
  ui_story_1015_10151501_95_dialog_content = "Hahaha, agora não.",
  ui_story_1015_10151501_96_dialog_content = "Há tantas pessoas aqui. Não vamos atrapalhar, hein?",
  ui_story_1015_10151501_97_dialog_content = "Ainda temos muito tempo para relembrar e nos cumprimentar antes do início oficial do Exercício Militar Conjunto.",
  ui_story_1015_10151501_98_dialog_content = "Bom ponto.",
  ui_story_1015_10151501_99_dialog_content = "Especialmente quando nossos novos companheiros de equipe ainda têm uma missão em suas mãos...",
  ui_story_1015_10151501_100_dialog_content = "Abra caminho, abra caminho.",
  ui_story_1015_10151501_101_dialog_content = "Crow, aqui - e tome cuidado para não esbarrar na porta.",
  ui_story_1015_10151501_102_dialog_content = "Eu sei.",
  ui_story_1015_10151501_103_dialog_content = "Eu realmente sinto muito por isso...",
  ui_story_1015_10151501_104_dialog_content = "Claramente sou eu quem deveria cuidar desta missão, mas eu realmente preciso da sua ajuda.",
  ui_story_1015_10151501_105_dialog_content = "Eu sou seu atendente. É meu dever ajudá-lo e protegê-lo.",
  ui_story_1015_10151501_106_dialog_content = "Além disso, se eu não ajudasse, você não conseguiria entregar isso sozinho em Gannon City.",
  ui_story_1015_10151501_107_dialog_content = "Era o único jeito... Afinal, não sou exatamente do tipo físico.",
  ui_story_1015_10151501_108_dialog_content = "Você precisa de ajuda, estrategista Illumina?",
  ui_story_1015_10151501_109_dialog_content = "Isso não será necessário, estamos prestes a chegar ao nosso destino.",
  ui_story_1015_10151501_110_dialog_content = "Se eu precisar de alguma coisa, eu me encarregarei de procurá-lo.",
  ui_story_1015_10151501_111_dialog_content = "Bom Bom. Não há necessidade de ser tímido só porque não trabalhamos juntos antes.",
  ui_story_1015_10151501_112_dialog_content = "Mesmo se um dia você decidir que quer se juntar aos Ironthorn Knights, apenas me avise e eu prometo que não vou me importar.",
  ui_story_1015_10151501_113_dialog_content = "Você tem muito senso de humor.",
  ui_story_1015_10151501_114_dialog_content = "Se você não se importa, vá em frente e faça o registro com o Sr. Joseph primeiro.",
  ui_story_1015_10151501_115_dialog_content = "Crow e eu precisamos entregá-la ao encarregado antes de podermos registrar.",
  ui_story_1015_10151501_116_dialog_content = "Ok, vamos em frente então.",
  ui_story_1015_10151501_117_dialog_content = "Até logo, Zhao.",
  ui_story_1015_10151501_118_dialog_content = "...",
  ui_story_1015_10151501_119_dialog_content = "Qual é o problema, Corvo?",
  ui_story_1015_10151501_120_dialog_content = "...",
  ui_story_1015_10151501_121_dialog_content = "Você quer perguntar por que estou me juntando a eles em vez de você de novo, não é?",
  ui_story_1015_10151501_122_dialog_content = "Eu posso te proteger, eles não.",
  ui_story_1015_10151501_123_dialog_content = "Sei disso.",
  ui_story_1015_10151501_124_dialog_content = "Mas esta foi uma decisão que todos nós tomamos juntos – cada cidadão de Crepúsculo.",
  ui_story_1015_10151501_125_dialog_content = "Eu sou um cidadão de Crepúsculo também.",
  ui_story_1015_10151501_126_dialog_content = "Eu sei, mas desta vez é diferente.",
  ui_story_1015_10151501_127_dialog_content = "Esta colaboração com os Cavaleiros Ironthorn e a Igreja do Deus da Luz é para mostrar ao mundo exterior a unidade e a força do Crepúsculo.",
  ui_story_1015_10151501_128_dialog_content = "Se sairmos por cima, só então teremos reconhecimento e influência suficientes para falar e exercer pressão sobre as outras forças do Astra.",
  ui_story_1015_10151501_129_dialog_content = "Eles realmente não gostam tanto assim de Crepúsculo?",
  ui_story_1015_10151501_130_dialog_content = "Não, eles não gostam de Crepúsculo.",
  ui_story_1015_10151501_131_dialog_content = "Eles simplesmente não se importam.",
  ui_story_1015_10151501_132_dialog_content = "Mas nós temos. O crepúsculo é o nosso lar, não podemos ficar parados e assistir enquanto as ondas de Eclipsites o engolem.",
  ui_story_1015_10151501_133_dialog_content = "Portanto, desta vez, devemos vencer. Devemos fazer com que se importem, para que enviem mais reforços a Twilight.",
  ui_story_1015_10151501_134_dialog_content = "...",
  ui_story_1015_10151501_135_dialog_content = "Vou seguir o que disse.",
  ui_story_1015_10151501_136_dialog_content = "Obrigado pela sua compreensão.",
  ui_story_1015_10151501_137_dialog_content = "Está ficando tarde. Vamos nos apressar e entregá-la.",
  ui_story_1015_10151501_138_dialog_content = "Eles são os alvos?",
  ui_story_1015_10151501_139_dialog_content = "Eles não parecem nada divertidos! Não tão divertido quanto o ursinho de pelúcia do meu sonho, de qualquer maneira...",
  ui_story_1015_10151501_140_dialog_content = "Não seja tão rápido em julgar, meu amigo.",
  ui_story_1015_10151501_141_dialog_content = "A missão do Mestre para nós hoje é observá-los, então é isso que faremos.",
  ui_story_1015_10151501_142_dialog_content = "A intuição do Mestre raramente está errada. Eu acredito que eles devem ter uma agenda oculta.",
  ui_story_1015_10151501_143_dialog_content = "Só espero que gostem de bichinhos tanto quanto eu...",
  ui_story_1015_10151501_144_dialog_content = "E essa é a situação atual.",
  ui_story_1015_10151501_145_dialog_content = "Reinhardt voltou para a cidade de Gannon, e o paradeiro de Forsakin e do alvo do teste é desconhecido, embora seja altamente provável que eles também estejam localizados em algum lugar da cidade de Gannon.",
  ui_story_1015_10151501_146_dialog_content = "Além disso, várias forças se reuniram em Gannon, já que o Exercício Militar Conjunto está prestes a começar.",
  ui_story_1015_10151501_147_dialog_content = "No entanto, a equipe conjunta Crepúsculo formada por membros da Illumina e Lumopolis é de fato uma reviravolta inesperada.",
  ui_story_1015_10151501_148_dialog_content = "Você gostaria que eu encontrasse dois especialistas para formar uma equipe e conter suas ações?",
  ui_story_1015_10151501_149_dialog_content = "Eles realmente valem a pena ficar de olho, mas não há necessidade de levá-los muito a sério.",
  ui_story_1015_10151501_150_dialog_content = "Yingel e Axelia são dois soldados muito confiáveis.",
  ui_story_1015_10151501_151_dialog_content = "Além disso, você tem outros assuntos a tratar.",
  ui_story_1015_10151501_152_dialog_content = "Sim, senhor.",
  ui_story_1015_10151501_153_dialog_content = "<color=#e8d9bb>Enquanto isso, em algum lugar na cidade de Gannon...</color>",
  ui_story_1015_10151501_154_dialog_content = "<anim type=Shake><size=45>Rugido...</size></anim>",
  ui_story_1015_10151501_155_dialog_content = "Coloque-o aqui.",
  ui_story_1015_10151501_156_dialog_content = "<anim type=Shake><size=45>Ahhhh!</size></anim>",
  ui_story_1015_10151501_157_dialog_content = "<anim type=Shake>Rosnar-</anim>",
  ui_story_1015_10151501_158_dialog_content = "Boa menina.",
  ui_story_1015_10151501_159_dialog_content = "Mude de volta e siga esses canos. Deixe esta Cidade Baixa.",
  ui_story_1015_10151501_160_dialog_content = "<anim type=Shake><size=45>Grrr?!</size></anim>",
  ui_story_1015_10151501_161_dialog_content = "<anim type=Shake><size=45>Rrr... Rugido...!</size></anim>",
  ui_story_1015_10151501_162_dialog_content = "Não há nada que você possa fazer por mim aqui.",
  ui_story_1015_10151501_163_dialog_content = "Se você ficar aqui por mais tempo, só vai me atrasar.",
  ui_story_1015_10151501_164_dialog_content = "Você sabe onde esperar por mim.",
  ui_story_1015_10151501_165_dialog_content = "<anim type=Shake>Rugido...</anim>",
  ui_story_1015_10151501_166_dialog_content = "Rangido!",
  ui_story_1015_10151501_167_dialog_content = "Negador...?",
  ui_story_1015_10151501_168_dialog_content = "...",
  ui_story_1015_10151501_169_dialog_content = "Você acordou.",
  ui_story_1015_10151501_170_dialog_content = "Certo...",
  ui_story_1015_10151501_171_dialog_content = "Onde... você... me levou?",
  ui_story_1015_10151501_172_dialog_content = "A capacidade cognitiva está se recuperando gradualmente?",
  ui_story_1015_10151501_173_dialog_content = "Embora isso indicasse que o experimento foi um sucesso, o momento é infeliz.",
  ui_story_1015_10151501_174_dialog_content = "O que você está falando...? Eu não entendo...",
  ui_story_1015_10151501_175_dialog_content = "Nenhuma coisa.",
  ui_story_1015_10151501_176_dialog_content = "Onde estou? Você ainda não me respondeu...",
  ui_story_1015_10151501_177_dialog_content = "...",
  ui_story_1015_10151501_178_dialog_content = "cidade de Gannon.",
  ui_story_1015_10151501_179_dialog_content = "Estamos de volta?",
  ui_story_1015_10151501_180_dialog_content = "Sim.",
  ui_story_1015_10151501_181_dialog_content = "Estamos de volta.",
  ui_story_1016_10160101_1_dialog_content = "<color=#e8d9bb>CHOO—</color>",
  ui_story_1016_10160101_2_dialog_content = "<color=#e8d9bb>Ka-chunk, ka-chunk, ka-chunk—</color>",
  ui_story_1016_10160101_3_dialog_content = "Atenção, todos os participantes do Exercício Militar Conjunto.",
  ui_story_1016_10160101_4_dialog_content = "O trem chegou ao seu destino. Agora você pode sair do trem.",
  ui_story_1016_10160101_5_dialog_content = "Aguarde mais instruções na estação.",
  ui_story_1016_10160101_6_dialog_content = "Uau! Que primeira vez incrível em um trem!",
  ui_story_1016_10160101_7_dialog_content = "Os trens são muito mais rápidos do que as carruagens puxadas por cavalos, não são?",
  ui_story_1016_10160101_8_dialog_content = "O barulho constante foi um pouco demais, se você me perguntar. Sinto-me muito melhor agora que descemos.",
  ui_story_1016_10160101_9_dialog_content = "Este lugar é onde o exercício conjunto será realizado, certo? O que devemos fazer agora?",
  ui_story_1016_10160101_10_dialog_content = "Apenas espere aqui por enquanto. Alguém vai explicar as coisas em breve.",
  ui_story_1016_10160101_11_dialog_content = "Anatoli! Muito tempo sem ver!",
  ui_story_1016_10160101_12_dialog_content = "Você também está participando do exercício conjunto?",
  ui_story_1016_10160101_13_dialog_content = "Claro. Todos aqui são participantes ansiosos do próximo exercício de treinamento.",
  ui_story_1016_10160101_14_dialog_content = "Eu vejo! Isso explica a emoção no ar!",
  ui_story_1016_10160101_15_dialog_content = "Vamos apenas esperar que Illumina mantenha as coisas civilizadas.",
  ui_story_1016_10160101_16_dialog_content = "Não há necessidade de se preocupar. Afinal, a opressão é o forte de Lumopolis.",
  ui_story_1016_10160101_17_dialog_content = "Hunf.",
  ui_story_1016_10160101_18_dialog_content = "Por favor, abram caminho, pessoal! Estamos descarregando uma carga frágil agora!",
  ui_story_1016_10160101_19_dialog_content = "Não esbarre em nada, não esbarre em nada.",
  ui_story_1016_10160101_20_dialog_content = "Então, para onde estamos levando isso, Zhao?",
  ui_story_1016_10160101_21_dialog_content = "O destinatário deve nos encontrar aqui...",
  ui_story_1016_10160101_22_dialog_content = "Obrigado a ambos por sua ajuda. Você pode deixar isso comigo agora.",
  ui_story_1016_10160101_23_dialog_content = "Você completou sua missão.",
  ui_story_1016_10160101_24_dialog_content = "Ah, então você era o destinatário o tempo todo, Coronel Yingel.",
  ui_story_1016_10160101_25_dialog_content = "Há algo estranho nisso?",
  ui_story_1016_10160101_26_dialog_content = "Sua participação no exercício conjunto é um pouco estranha, sim.",
  ui_story_1016_10160101_27_dialog_content = "Sempre pensei que eventos como este estavam abaixo de alguém do seu status.",
  ui_story_1016_10160101_28_dialog_content = "Você deve pensar muito bem de mim, então.",
  ui_story_1016_10160101_29_dialog_content = "Aqui você vai. Transportar esta coisa não foi muito fácil, você sabe.",
  ui_story_1016_10160101_30_dialog_content = "Gostaria de verificar e certificar-se de que tudo está intacto?",
  ui_story_1016_10160101_31_dialog_content = "Sim.",
  ui_story_1016_10160101_32_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_1016_10160101_33_dialog_content = "Hora de acordar, Axelia.",
  ui_story_1016_10160101_34_dialog_content = "<color=#e8d9bb>Tssss—</color>",
  ui_story_1016_10160101_35_dialog_content = "Yaaaawn.",
  ui_story_1016_10160101_36_dialog_content = "Bom Dia, Yingel.",
  ui_story_1016_10160101_37_dialog_content = "Você dormiu bem?",
  ui_story_1016_10160101_38_dialog_content = "Sim, sinto-me muito bem descansado agora.",
  ui_story_1016_10160101_39_dialog_content = "Ugh, que sufocante.",
  ui_story_1016_10160101_40_dialog_content = "Eu realmente não me importo em ficar preso em um espaço tão sufocante.",
  ui_story_1016_10160101_41_dialog_content = "Você está suando como se tivesse acabado de terminar uma batalha, Leo.",
  ui_story_1016_10160101_42_dialog_content = "Sim, e também me sinto cansada.",
  ui_story_1016_10160101_43_dialog_content = "Você não acha que está exagerando um pouco? É apenas mais um meio de transporte.",
  ui_story_1016_10160101_44_dialog_content = "Nunca corremos perigo.",
  ui_story_1016_10160101_45_dialog_content = "Não tem nada a ver com estarmos ou não em perigo...",
  ui_story_1016_10160101_46_dialog_content = "Você gostaria de um guardanapo?",
  ui_story_1016_10160101_47_dialog_content = "Por que sim, obrigado... Hmm? L-Lady Carleen?!",
  ui_story_1016_10160101_48_dialog_content = "Eu entendo como você se sente. Muitas pessoas de Lumopolis têm dificuldade em se adaptar a essas máquinas.",
  ui_story_1016_10160101_49_dialog_content = "Eu vejo. Se todos fossem tão compreensivos quanto você, minha senhora.",
  ui_story_1016_10160101_50_dialog_content = "Devo dizer que encontrar você aqui é uma grande surpresa.",
  ui_story_1016_10160101_51_dialog_content = "Eu estava assumindo que nosso próximo encontro seria em Lumopolis.",
  ui_story_1016_10160101_52_dialog_content = "Dado o nosso status, uma reunião em Lumopolis teria sido repleta de complicações. Aqui, porém, somos livres para falar como participantes do exercício.",
  ui_story_1016_10160101_53_dialog_content = "Hahahaha! Bem dito, minha senhora!",
  ui_story_1016_10160101_54_dialog_content = "Um pouco de simplicidade é sempre bem-vindo quando as pessoas levam vidas tão complicadas.",
  ui_story_1016_10160101_55_dialog_content = "Olá, sou Leo e José! Vocês estão aqui para o exercício conjunto também?",
  ui_story_1016_10160101_56_dialog_content = "Deve ter sido uma longa jornada desde Crepúsculo!",
  ui_story_1016_10160101_57_dialog_content = "PlayerName! O que você está fazendo aqui?",
  ui_story_1016_10160101_58_dialog_content = "Fui convidado para o exercício conjunto, então vim com Carleen e Vice.",
  ui_story_1016_10160101_59_dialog_content = "Eu vejo. Eu teria pedido uma carona a bordo do seu Colosso se soubesse que você viria...",
  ui_story_1016_10160101_60_dialog_content = "Hahaha! Você é sempre bem-vindo a bordo, sabia?",
  ui_story_1016_10160101_61_dialog_content = "Aham! Todos os participantes, por favor, reúnam-se aqui.",
  ui_story_1016_10160101_62_dialog_content = "Agora darei mais instruções sobre o Exercício Militar Conjunto.",
  ui_story_1016_10160101_63_dialog_content = "Eu ouvi a voz de Vivian agora há pouco?",
  ui_story_1016_10160101_64_dialog_content = "Sim! Vamos de cabeça!",
  ui_story_1016_10160101_65_dialog_content = "C-Cuidado, Vice. Há muitas pessoas aqui.",
  ui_story_1016_10160101_66_dialog_content = "Você pode relaxar um pouco. Não é como se eu tivesse me machucado com o que aconteceu antes ou algo assim.",
  ui_story_1016_10160101_67_dialog_content = "Além disso, você não se lembra do que dizia o exame médico? Estou tão saudável quanto possível!",
  ui_story_1016_10160101_68_dialog_content = "Mas ainda acho...",
  ui_story_1016_10160101_69_dialog_content = "Vamos, vamos!",
  ui_story_1016_10160101_70_dialog_content = "Em primeiro lugar, obrigado a todos por virem à cidade de Gannon hoje para participar de nosso Exercício Militar Conjunto.",
  ui_story_1016_10160101_71_dialog_content = "Sou Vivian, chefe de gabinete da Federação Illumina, e serei sua guia.",
  ui_story_1016_10160101_72_dialog_content = "A Illumina dá grande importância à eficiência, então vamos continuar sem demora.",
  ui_story_1016_10160101_73_dialog_content = "Depois que minha explicação das regras estiver completa, o Exercício Militar Conjunto começará oficialmente.",
  ui_story_1016_10160101_74_dialog_content = "Eles realmente não fazem rodeios, hein?",
  ui_story_1016_10160101_75_dialog_content = "Para ser honesto, isso me cai melhor do que um discurso formal e prolixo.",
  ui_story_1016_10160101_76_dialog_content = "Como todos sabem muito bem, este Exercício Militar Conjunto visa melhorar a capacidade da geração mais jovem de lidar com os rigores da guerra.",
  ui_story_1016_10160101_77_dialog_content = "Cada participante reunido aqui hoje tem menos de vinte e cinco anos.",
  ui_story_1016_10160101_78_dialog_content = "Vocês são todos jovens oficiais que estão apenas começando a mostrar seu talento ou estudantes que ainda não deixaram a segurança da torre de marfim da academia.",
  ui_story_1016_10160101_79_dialog_content = "Independentemente das diferenças de idade ou experiência, cada um de vocês verá a batalha algum dia.",
  ui_story_1016_10160101_80_dialog_content = "Todos vocês devem fazer o possível para aprimorar suas capacidades de combate por meio de estudo, cooperação e competição.",
  ui_story_1016_10160101_81_dialog_content = "Para preparar o terreno para o seu treinamento, o exercício militar será dividido em duas fases: educação e avaliação de combate.",
  ui_story_1016_10160101_82_dialog_content = "Durante a fase de educação, a Illumina fornecerá a você recursos de alta qualidade e o conhecimento de seus predecessores para se aprimorar.",
  ui_story_1016_10160101_83_dialog_content = "Durante a fase de avaliação, você formará equipes e competirá entre si para determinar o vencedor final.",
  ui_story_1016_10160101_84_dialog_content = "Duvido que alguém precise ser lembrado de que, de acordo com a tradição, o vencedor da avaliação receberá um prêmio único—",
  ui_story_1016_10160101_85_dialog_content = "Uma oportunidade de treinar com o Grande Marechal.",
  ui_story_1016_10160101_86_dialog_content = "Uma chance de lutar contra o Grande Marechal? Isso é muito assustador... Quem iria querer isso?",
  ui_story_1016_10160101_87_dialog_content = "Mas, novamente, o campeão do exercício conjunto deve ser muito difícil também...",
  ui_story_1016_10160101_88_dialog_content = "Você tem razão! Da última vez foi aquela princesa de Lumópolis...",
  ui_story_1016_10160101_89_dialog_content = "Isso conclui a introdução básica do exercício.",
  ui_story_1016_10160101_90_dialog_content = "Por favor, levante a bandeira!",
  ui_story_1016_10160101_91_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_1016_10160101_92_dialog_content = "Uau! Essa é uma longa cadeia de bandeiras!",
  ui_story_1016_10160101_93_dialog_content = "Isto é o <color=#FFB400>Estandarte dos Campeões</color>.",
  ui_story_1016_10160101_94_dialog_content = "Apenas o campeão do Exercício Militar Conjunto tem o privilégio de adicionar a bandeira de sua facção a ele.",
  ui_story_1016_10160101_95_dialog_content = "Com cada exercício conjunto realizado, a Bandeira dos Campeões cresceu e se tornou o que você vê diante de você agora.",
  ui_story_1016_10160101_96_dialog_content = "Você pode ver a prova das vitórias anteriores de todas as principais facções.",
  ui_story_1016_10160101_97_dialog_content = "Como as incontáveis estrelas brilhando nos céus acima—",
  ui_story_1016_10160101_98_dialog_content = "Esta bandeira é um símbolo do nosso exercício conjunto, bem como o desejo inflexível de cada geração de alcançar a vitória na batalha!",
  ui_story_1016_10160101_99_dialog_content = "(!!!)",
  ui_story_1016_10160101_100_dialog_content = "(Estou vendo coisas ou é uma bandeira dos celestitas...?!)",
  ui_story_1016_10160101_101_dialog_content = "Agora então, todos. Sem mais delongas, é uma honra anunciar—",
  ui_story_1016_10160101_102_dialog_content = "O início oficial deste Exercício Militar Conjunto!",
  ui_story_1016_10160101_103_dialog_content = "<color=#e8d9bb>*Aplausos*</color>",
  ui_story_1016_10160101_104_dialog_content = "Agora vamos começar a registrar formalmente todos para o evento.",
  ui_story_1016_10160101_105_dialog_content = "Em suas cartas-convite, você encontrará a equipe à qual foi designado.",
  ui_story_1016_10160101_106_dialog_content = "Uma equipa é composta por três participantes, representando a unidade operacional mais básica neste Exercício Militar Conjunto.",
  ui_story_1016_10160101_107_dialog_content = "A facção do capitão da equipe também servirá como a facção de toda a equipe.",
  ui_story_1016_10160101_108_dialog_content = "Reserve um momento para localizar os outros membros de sua equipe.",
  ui_story_1016_10160101_109_dialog_content = "Então, Carleen e Vice estará no meu time, certo?",
  ui_story_1016_10160101_110_dialog_content = "Você esqueceu ou algo assim? Claro que estamos!",
  ui_story_1016_10160101_111_dialog_content = "O convite também diz que você comandará a equipe, capitão.",
  ui_story_1016_10160101_112_dialog_content = "Ah, por favor, não diga isso...",
  ui_story_1016_10160101_113_dialog_content = "Depois de confirmar os outros membros de sua equipe, por favor, venha até mim para registro.",
  ui_story_1016_10160101_114_dialog_content = "Assim que o registro for concluído, vou acompanhá-los até o quartel para desembarcar a bagagem. Depois, você está livre para fazer o que quiser dentro da área permitida.",
  ui_story_1016_10160101_115_dialog_content = "Sua primeira aula será realizada amanhã de manhã.",
  ui_story_1016_10160101_116_dialog_content = "Estou tão animado!",
  ui_story_1016_10160101_117_dialog_content = "Conheço esses exercícios conjuntos desde que era uma garotinha, mas esta é a primeira vez que participo de um!",
  ui_story_1016_10160101_118_dialog_content = "Como foi a última vez que você veio, Carleen?",
  ui_story_1016_10160101_119_dialog_content = "Eu senti o mesmo que você, mais ou menos.",
  ui_story_1016_10160101_120_dialog_content = "Animado, mas não totalmente confiante em mim mesmo.",
  ui_story_1016_10160101_121_dialog_content = "Não totalmente confiante, mas você saiu por cima, hein?",
  ui_story_1016_10160101_122_dialog_content = "Ser um gênio nato deve ser tão bom!",
  ui_story_1016_10160101_123_dialog_content = "Eu não estava tentando me gabar! Realmente!",
  ui_story_1016_10160101_124_dialog_content = "Heehee! Estou brincando, Carleen!",
  ui_story_1016_10160101_125_dialog_content = "O que você acha de tudo isso, PlayerName? Você mal falou desde que chegamos aqui.",
  ui_story_1016_10160101_126_dialog_content = "Você ainda não está acostumado a ambientes estressantes como este?",
  ui_story_1016_10160101_127_dialog_content = "Só estava pensando... A maioria dos outros participantes são nossos amigos.",
  ui_story_1016_10160101_128_dialog_content = "Acho que não estava mentalmente preparado para enfrentá-los, só isso.",
  ui_story_1016_10160101_129_dialog_content = "Faz sentido, considerando como você tende a ser avesso a conflitos.",
  ui_story_1016_10160101_130_dialog_content = "Mas está tudo bem! Vamos nos concentrar mais em aprender em vez de competir!",
  ui_story_1016_10160101_131_dialog_content = "M-Mas eu também quero ganhar dessa vez...",
  ui_story_1016_10160101_132_dialog_content = "Hã?",
  ui_story_1016_10160101_133_dialog_content = "Eu vi a bandeira dos celestitas no Estandarte dos Campeões antes.",
  ui_story_1016_10160101_134_dialog_content = "Fiquei tão feliz em ver a marca do meu povo na história, mas...",
  ui_story_1016_10160101_135_dialog_content = "Quando vi a que distância estava da bandeira adicionada mais recentemente, não pude deixar de me sentir um pouco triste também.",
  ui_story_1016_10160101_136_dialog_content = "Faz tanto tempo que os celestitas não participam dessa competição...",
  ui_story_1016_10160101_137_dialog_content = "Não quero que o orgulho do meu povo fique tão parado no passado, como aquela bandeira.",
  ui_story_1016_10160101_138_dialog_content = "Eu quero pendurar outro bem na frente do banner!",
  ui_story_1016_10160101_139_dialog_content = "Ouça atentamente! Todos em nossa equipe são de Lumopolis.",
  ui_story_1016_10160101_140_dialog_content = "Isso significa que nossas ações refletem diretamente seus ilustres padrões educacionais!",
  ui_story_1016_10160101_141_dialog_content = "Não devemos envergonhar Lumopolis ou o Dawn Academia!",
  ui_story_1016_10160101_142_dialog_content = "Já fazendo discursos grandiosos, capitão?",
  ui_story_1016_10160101_143_dialog_content = "Eu não estou fazendo um discurso!",
  ui_story_1016_10160101_144_dialog_content = "Eu só queria aumentar o moral de todos para a próxima competição...",
  ui_story_1016_10160101_145_dialog_content = "Ela está certa. A competição para este Exercício Militar Conjunto é acirrada.",
  ui_story_1016_10160101_146_dialog_content = "Precisamos manter o ânimo se não quisermos ficar para trás.",
  ui_story_1016_10160101_147_dialog_content = "É assim mesmo? Quais são suas impressões sobre as outras equipes, então?",
  ui_story_1016_10160101_148_dialog_content = "Eu só estou ciente de PlayerName e sua equipe.",
  ui_story_1016_10160101_149_dialog_content = "As habilidades psíquicas de um Caelestite, combinadas com Lady Carleen e a força combinada de Miss Vice, os torna uma ameaça poderosa.",
  ui_story_1016_10160101_150_dialog_content = "Bem, senhora Carleen é o atual campeão, afinal. Tenho certeza de que ela não perderá seu título com muita facilidade.",
  ui_story_1016_10160101_151_dialog_content = "Além de PlayerName's equipe, há duas outras equipes dignas de nota.",
  ui_story_1016_10160101_152_dialog_content = "Uma delas é a equipe de Leo. Ele e seus companheiros vêm de Crepúsculo.",
  ui_story_1016_10160101_153_dialog_content = "Durante uma de minhas missões anteriores, tive o privilégio de ver em primeira mão como aqueles guerreiros de Crepúsculo travavam batalhas.",
  ui_story_1016_10160101_154_dialog_content = "Todos os três têm uma vasta experiência de combate. Nenhuma outra equipe poderia se comparar neste departamento.",
  ui_story_1016_10160101_155_dialog_content = "Eu vejo. A experiência de combate real dá a eles uma vantagem sobre o resto de nós.",
  ui_story_1016_10160101_156_dialog_content = "Mesmo que a diferença de idade não seja muito grande, a diferença de experiência é enorme.",
  ui_story_1016_10160101_157_dialog_content = "A outra equipe para ficar de olho é a equipe de Yingel, já que ela Axelia e Anatoli ao lado dela.",
  ui_story_1016_10160101_158_dialog_content = "Esses três são os melhores guerreiros de Illumina para sua geração.",
  ui_story_1016_10160101_159_dialog_content = "Além disso, eles têm todo o peso do conhecimento científico e tecnológico da Illumina à sua disposição. Não há como dizer o quão poderosos isso os torna.",
  ui_story_1016_10160101_160_dialog_content = "Ugh... Ciência e tecnologia não são exatamente o nosso forte.",
  ui_story_1016_10160101_161_dialog_content = "Eu não poderia concordar mais, e é por isso que precisamos ficar fora do caminho deles.",
  ui_story_1016_10160101_162_dialog_content = "Lembre-se, viemos para Gannon City como convidados, então devemos aceitar sua maneira de fazer as coisas.",
  ui_story_1016_10160101_163_dialog_content = "Vamos considerar isso como uma valiosa experiência de aprendizado.",
  ui_story_1016_10160101_164_dialog_content = "Dizer isso é uma coisa, mas fazer isso não será uma tarefa fácil.",
  ui_story_1016_10160101_165_dialog_content = "Assim como você ainda não descobriu as ruas de Gannon City, apesar de estar perdido por tanto tempo.",
  ui_story_1016_10160101_166_dialog_content = "P-Por que você está me atacando, de repente?!",
  ui_story_1016_10160101_167_dialog_content = "Porque eu quero voltar para o quartel, capitão. Quanto tempo até que você possa finalmente nos levar na direção certa?",
  ui_story_1016_10160101_168_dialog_content = "J-Apenas me dê um momento! Eu quase descobri!",
  ui_story_1016_10160101_169_dialog_content = "Se virarmos à direita aqui...",
  ui_story_1016_10160101_170_dialog_content = "<color=#e8d9bb>Pimba!</color>",
  ui_story_1016_10160101_171_dialog_content = "<size=45>Ugh!</size>",
  ui_story_1016_10160101_172_dialog_content = "Hum...",
  ui_story_1016_10160101_173_dialog_content = "Sinto muito! Eu deveria estar prestando mais atenção na estrada!",
  ui_story_1016_10160101_174_dialog_content = "Você está bem?",
  ui_story_1016_10160101_175_dialog_content = "Estou bem e, por favor, não se culpe. As pessoas tendem a esbarrar em mim com bastante frequência.",
  ui_story_1016_10160101_176_dialog_content = "Você poderia, por favor, me passar minha bengala? Eu não consigo encontrá-lo.",
  ui_story_1016_10160101_177_dialog_content = "Claro. Aqui você vai.",
  ui_story_1016_10160101_178_dialog_content = "Perdoe-me, mas... você é cego?",
  ui_story_1016_10160101_179_dialog_content = "Oh, minhas desculpas por incomodá-lo.",
  ui_story_1016_10160101_180_dialog_content = "Boohoo, sou eu quem deveria se desculpar! Eu nunca deveria ter encontrado você!",
  ui_story_1016_10160101_181_dialog_content = "Onde você está indo? Deixe-me acompanhá-lo até lá!",
  ui_story_1016_10160101_182_dialog_content = "Isso não será necessário, obrigado. No entanto, estou procurando uma garotinha vestindo uma roupa de boneca. Você viu ela?",
  ui_story_1016_10160101_183_dialog_content = "Não mesmo.",
  ui_story_1016_10160101_184_dialog_content = "Então não vou mais incomodá-lo. Posso continuar procurando por conta própria.",
  ui_story_1016_10160101_185_dialog_content = "Ah, e a propósito... também sou participante do Exercício Militar Conjunto, assim como vocês três.",
  ui_story_1016_10160101_186_dialog_content = "Hã?",
  ui_story_1016_10160101_187_dialog_content = "Meu nome é Dysis. Estou ansioso para vê-lo na aula de amanhã.",
  ui_story_1016_10160101_188_dialog_content = "Nossa missão é ser o mais divulgado possível, entendeu?",
  ui_story_1016_10160101_189_dialog_content = "Não temos interesse em ler livros ou brincar de soldados. Estamos aqui para encontrar uma maneira de ampliar nossa mensagem.",
  ui_story_1016_10160101_190_dialog_content = "Precisamos avisar o mundo inteiro da catástrofe iminente de Crepúsculo!",
  ui_story_1016_10160101_191_dialog_content = "Agora eu sei o que você realmente procura, Leo.",
  ui_story_1016_10160101_192_dialog_content = "É assim mesmo? Então diga-nos, se você é tão inteligente.",
  ui_story_1016_10160101_193_dialog_content = "Você quer a chance de enfrentar o Grande Marechal.",
  ui_story_1016_10160101_194_dialog_content = "Hahahaha! Isso mesmo! O que poderia ser uma notícia melhor do que alguém batendo Reinhardt em batalha?",
  ui_story_1016_10160101_195_dialog_content = "Você está mordendo mais do que pode mastigar.",
  ui_story_1016_10160101_196_dialog_content = "Você acha mesmo?",
  ui_story_1016_10160101_197_dialog_content = "Vencer a disputa pelo direito de duelar com o Grande Marechal não deveria ser um desafio.",
  ui_story_1016_10160101_198_dialog_content = "Mas eu não acho que você pode vencê-la em uma luta um contra um.",
  ui_story_1016_10160101_199_dialog_content = "Contundente como sempre, eu vejo.",
  ui_story_1016_10160101_200_dialog_content = "O combate solo não é o seu forte. Eu não deveria ter que lembrá-lo disso, certo?",
  ui_story_1016_10160101_201_dialog_content = "Não, estou perfeitamente certo disso.",
  ui_story_1016_10160101_202_dialog_content = "Mas não sou eu quem vai enfrentar Reinhardt na batalha, devemos ter sucesso.",
  ui_story_1016_10160101_203_dialog_content = "!!!",
  ui_story_1016_10160101_204_dialog_content = "Então é por isso que você o trouxe junto...",
  ui_story_1016_10160101_205_dialog_content = "Eu não sei sobre as chances de vitória de Joseph.",
  ui_story_1016_10160101_206_dialog_content = "Mas tenho certeza de que nossa mensagem será ouvida em alto e bom som.",
  ui_story_1016_10160101_207_dialog_content = "Ouviu isso? Alguém está chorando.",
  ui_story_1016_10160101_208_dialog_content = "Hã?",
  ui_story_1016_10160101_209_dialog_content = "Apenas se acalme e ouça com atenção.",
  ui_story_1016_10160101_210_dialog_content = "<size=30>*Soluçando*</size>",
  ui_story_1016_10160101_211_dialog_content = "Tem razão!",
  ui_story_1016_10160101_212_dialog_content = "Que estranho, o choro da pessoa não soa nada triste.",
  ui_story_1016_10160101_213_dialog_content = "Está cada vez mais perto. Eles devem estar caminhando em nossa direção.",
  ui_story_1016_10160101_214_dialog_content = "*Soluço*",
  ui_story_1016_10160101_215_dialog_content = "Um semi-humano? Isso é uma visão rara.",
  ui_story_1016_10160101_216_dialog_content = "Está tudo bem? Eu ouvi você chorando de longe.",
  ui_story_1016_10160101_217_dialog_content = "Huh? A-Você está me perguntando?",
  ui_story_1016_10160101_218_dialog_content = "Me desculpe se isso te incomodou.",
  ui_story_1016_10160101_219_dialog_content = "É só porque minha cabeça dói demais. É um problema antigo.",
  ui_story_1016_10160101_220_dialog_content = "Parece sério, se suas dores de cabeça são dolorosas o suficiente para fazer você chorar...",
  ui_story_1016_10160101_221_dialog_content = "Eu vi você na estação de trem mais cedo. Você também participa do Exercício Militar Conjunto, certo?",
  ui_story_1016_10160101_222_dialog_content = "Sim. Meu nome é Feliz.",
  ui_story_1016_10160101_223_dialog_content = "De onde você é?",
  ui_story_1016_10160101_224_dialog_content = "Umbraton.",
  ui_story_1016_10160101_225_dialog_content = "Quantos de vocês tem lá?",
  ui_story_1016_10160101_226_dialog_content = "Três, incluindo eu.",
  ui_story_1016_10160101_227_dialog_content = "Agora se posso te fazer uma pergunta, você já viu por aqui uma menininha com roupinha de boneca?",
  ui_story_1016_10160101_228_dialog_content = "Ela é minha companheira de equipe e parece ter se perdido por perto.",
  ui_story_1016_10160101_229_dialog_content = "Não temos, desculpe. Você é o único outro participante que vimos até agora.",
  ui_story_1016_10160101_230_dialog_content = "Eu vejo. Bem, se você não tem mais perguntas para mim, eu deveria continuar procurando por ela.",
  ui_story_1016_10160101_231_dialog_content = "Obrigado pelo seu tempo. Estou ansioso para vê-lo durante o treinamento.",
  ui_story_1016_10160101_232_dialog_content = "Qual é o problema com você, interrogando-a assim?!",
  ui_story_1016_10160101_233_dialog_content = "Interrogando? Só estava reunindo informações, só isso.",
  ui_story_1016_10160101_234_dialog_content = "Você está desconfiado dela?",
  ui_story_1016_10160101_235_dialog_content = "Não posso dizer com certeza, pelo menos não agora. Vamos esperar para ver.",
  ui_story_1016_10160101_236_dialog_content = "Tenho uma atualização para compartilhar com todos.",
  ui_story_1016_10160101_237_dialog_content = "Temos de ganhar o campeonato a todo o custo.",
  ui_story_1016_10160101_238_dialog_content = "Há alguma pergunta?",
  ui_story_1016_10160101_239_dialog_content = "Não.",
  ui_story_1016_10160101_240_dialog_content = "... Esses são realmente o decreto do Comitê?",
  ui_story_1016_10160101_241_dialog_content = "Sim.",
  ui_story_1016_10160101_242_dialog_content = "Acho que não tenho mais perguntas, então.",
  ui_story_1016_10160101_243_dialog_content = "Não existe uma estratégia específica para a fase de aprendizagem do Exercício Militar Conjunto, pelo que basta frequentar as aulas normalmente.",
  ui_story_1016_10160101_244_dialog_content = "E lembre-se de manter a discrição, para evitar atenção ou brigas desnecessárias.",
  ui_story_1016_10160101_245_dialog_content = "Nossas ordens devem permanecer ultrassecretas. Ninguém fora desta sala deve saber sobre nossa missão.",
  ui_story_1016_10160101_246_dialog_content = "Entendi.",
  ui_story_1016_10160101_247_dialog_content = "Entendi.",
  ui_story_1016_10160101_248_dialog_content = "É tudo por agora. Reunião adiada.",
  ui_story_1016_10160101_249_dialog_content = "Bom, estou começando a me sentir cansado.",
  ui_story_1016_10160101_250_dialog_content = "Aqui, vou acompanhá-lo de volta à sua câmara de estase.",
  ui_story_1016_10160101_251_dialog_content = "Anatoli, você poderia me ajudar a abrir a porta?",
  ui_story_1016_10160101_252_dialog_content = "Claro-",
  ui_story_1016_10160101_253_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_1016_10160101_254_dialog_content = "Ahhh!",
  ui_story_1016_10160101_255_dialog_content = "Alguém está do lado de fora da porta!",
  ui_story_1016_10160101_256_dialog_content = "Quem tá aí?!",
  ui_story_1016_10160101_257_dialog_content = "Isso machuca! Não abra portas assim!",
  ui_story_1016_10160101_258_dialog_content = "Ah, ótimo! Olha esse galo enorme na minha cabeça!",
  ui_story_1016_10160101_259_dialog_content = "...",
  ui_story_1016_10160101_260_dialog_content = "Esta criança é um inimigo?",
  ui_story_1016_10160101_261_dialog_content = "E-Ei! O que há com esse olhar?!",
  ui_story_1016_10160101_262_dialog_content = "Eu-eu não estava espionando vocês nem nada!",
  ui_story_1016_10160101_263_dialog_content = "Não dissemos nada sobre você estar escutando.",
  ui_story_1016_10160101_264_dialog_content = "Você...",
  ui_story_1016_10160101_265_dialog_content = "Aí está você, Minch! Eu estive procurando por você em todos os lugares!",
  ui_story_1016_10160101_266_dialog_content = "Por que você fugiu assim? Eu não avisei sobre como é fácil se perder em Gannon City?",
  ui_story_1016_10160101_267_dialog_content = "Demorou bastante, Merry!",
  ui_story_1016_10160101_268_dialog_content = "Vocês dois se conhecem? Poderia ser...",
  ui_story_1016_10160101_269_dialog_content = "Peço desculpas se nosso amigo lhe causou algum problema.",
  ui_story_1016_10160101_270_dialog_content = "Esta é a nossa primeira vez em Gannon City, e o layout da cidade torna mais fácil para os recém-chegados como nós se perderem.",
  ui_story_1016_10160101_271_dialog_content = "Estamos... interrompendo alguma coisa?",
  ui_story_1016_10160101_272_dialog_content = "Pelo que você está se desculpando, Dysis?! Foram eles que me bateram na cara com a porta!",
  ui_story_1016_10160101_273_dialog_content = "Deixa pra lá, Minch. Você deveria ser mais respeitoso com nossos novos conhecidos.",
  ui_story_1016_10160101_274_dialog_content = "...",
  ui_story_1016_10160101_275_dialog_content = "Bem, então, devemos ir agora.",
  ui_story_1016_10160101_276_dialog_content = "Sim, enquanto ainda me lembro do caminho de volta.",
  ui_story_1016_10160101_277_dialog_content = "Hmph! Mais tarde, idiotas!",
  ui_story_1016_10160101_278_dialog_content = "Esses três são os participantes de Umbraton.",
  ui_story_1016_10160101_279_dialog_content = "Devemos realmente deixá-los ir assim? É possível que eles tenham ouvido nossa conversa.",
  ui_story_1016_10160101_280_dialog_content = "Se eles realmente nos ouviram, darei um jeito de resolver o problema.",
  ui_story_1016_10160101_281_dialog_content = "Por enquanto, vamos voltar e descansar um pouco.",
  ui_story_1016_10160101_282_dialog_content = "Ainda precisamos nos preparar para a aula de amanhã.",
  ui_story_1016_10160101_283_dialog_content = "<color=#e8d9bb>Pit, pat, pit, pat...</color>",
  ui_story_1016_10160101_284_dialog_content = "Eles se foram...?",
  ui_story_1016_10160101_285_dialog_content = "Sim, o último grupo de soldados partiu.",
  ui_story_1016_10160101_286_dialog_content = "Como você está se sentindo, Hélio?",
  ui_story_1016_10160101_287_dialog_content = "É só um arranhão... Não se preocupe comigo.",
  ui_story_1016_10160101_288_dialog_content = "Eu... eu ainda posso lutar.",
  ui_story_1016_10160101_289_dialog_content = "Lutar não nos levará a lugar nenhum em Gannon City, Helios. No momento em que formos vistos, todos os soldados da Illumina estarão nos atacando.",
  ui_story_1016_10160101_290_dialog_content = "Força bruta não é a resposta.",
  ui_story_1016_10160101_291_dialog_content = "Mas...",
  ui_story_1016_10160101_292_dialog_content = "Apenas aguente por agora. Em situações como essas, é de nosso interesse manter a calma.",
  ui_story_1016_10160101_293_dialog_content = "Só precisamos esperar mais um pouco.",
  ui_story_1016_10160101_294_dialog_content = "O que exatamente estamos esperando?",
  ui_story_1016_10160101_295_dialog_content = "O <color=#FFB400>fantasma</color>.",
  ui_story_1016_10160201_1_dialog_content = "<anim type=Shake>Bocejar-</anim> Não consegui dormir nada ontem à noite.",
  ui_story_1016_10160201_2_dialog_content = "Toda esta cidade cheira a fábrica.",
  ui_story_1016_10160201_3_dialog_content = "Um laboratório?! O que você está planejando fazer conosco aqui?!",
  ui_story_1016_10160201_4_dialog_content = "Não tenho intenção de ser um rato de laboratório para Illumina!",
  ui_story_1016_10160201_5_dialog_content = "Uau, que lugar familiar.",
  ui_story_1016_10160201_6_dialog_content = "Acho que sei o que estamos fazendo aqui hoje.",
  ui_story_1016_10160201_7_dialog_content = "<color=#e8d9bb>Anel-</color>",
  ui_story_1016_10160201_8_dialog_content = "Muito alto, muito alto! Cale a boca, todos vocês!",
  ui_story_1016_10160201_9_dialog_content = "Meu nome é Gronru, e serei seu instrutor em todas as suas aulas relacionadas à pesquisa.",
  ui_story_1016_10160201_10_dialog_content = "Obviamente, a maioria de vocês não dá a mínima para ciência, mas não se preocupe! Minhas aulas são tudo menos chatas!",
  ui_story_1016_10160201_11_dialog_content = "Então, para nossa primeira aula, preparei algo superdivertido para todos vocês... Nossa mais recente e maior invenção!",
  ui_story_1016_10160201_12_dialog_content = "Deleite-se com o mais novo dispositivo de treinamento militar da Illumina—",
  ui_story_1016_10160201_13_dialog_content = "<color=#FFB400>O simulador de batalha</color>!",
  ui_story_1016_10160201_14_dialog_content = "Eu sabia!",
  ui_story_1016_10160201_15_dialog_content = "Um capacete? Como exatamente isso deve nos treinar?",
  ui_story_1016_10160201_16_dialog_content = "Está brincando? Este pequeno gadget funciona melhor do que qualquer espada ou arma jamais poderia!",
  ui_story_1016_10160201_17_dialog_content = "Diga-me, o que você acha que é a coisa mais difícil de treinar para um soldado?",
  ui_story_1016_10160201_18_dialog_content = "É força física? Ou talvez Luminatics?",
  ui_story_1016_10160201_19_dialog_content = "É experiência de combate.",
  ui_story_1016_10160201_20_dialog_content = "Bingo! A coisa mais difícil para um soldado treinar é sua experiência em combate!",
  ui_story_1016_10160201_21_dialog_content = "Durante muito tempo, a única maneira de obter esse tipo de experiência era lutando e sobrevivendo em combate real.",
  ui_story_1016_10160201_22_dialog_content = "Infelizmente, a guerra é brutal e nem todo soldado tem a sorte de sair dela vivo e bem.",
  ui_story_1016_10160201_23_dialog_content = "A menos, é claro, que eles tenham experimentado toneladas e toneladas de batalhas simuladas!",
  ui_story_1016_10160201_24_dialog_content = "Mas como uma guerra realista pode ser simulada...?",
  ui_story_1016_10160201_25_dialog_content = "Essa é uma ótima pergunta, considerando que é isso que abordaremos na lição de hoje!",
  ui_story_1016_10160201_26_dialog_content = "Cada um de vocês receberá um dispositivo igual ao que estou segurando agora.",
  ui_story_1016_10160201_27_dialog_content = "Depois de colocá-lo, todos vocês serão enviados para um campo de batalha virtual ao mesmo tempo.",
  ui_story_1016_10160201_28_dialog_content = "Uma vez lá, você poderá usar Luminatics e todos os tipos de armas como faria normalmente na vida real, e seus oponentes serão nossos velhos amigos, os Eclipsites.",
  ui_story_1016_10160201_29_dialog_content = "Trate-os da mesma forma de sempre e não pare até ser derrotado!",
  ui_story_1016_10160201_30_dialog_content = "Hahaha! Isso está começando a soar interessante!",
  ui_story_1016_10160201_31_dialog_content = "Vamos ver como esses capacetes podem simular uma guerra real!",
  ui_story_1016_10160201_32_dialog_content = "Ótimo, parece que todo mundo está ansioso para ir!",
  ui_story_1016_10160201_33_dialog_content = "Então, sem mais delongas, vou distribuir os capacetes para que possamos começar com a simulação de treinamento de combate de hoje.",
  ui_story_1016_10160201_34_dialog_content = "Durante a simulação, seu desempenho também será monitorado e pontuado. Você pode acompanhar suas estatísticas na tela próxima.",
  ui_story_1016_10160201_35_dialog_content = "Os números não mentem, então faça o seu melhor para acumular pontos e chegar ao topo do placar!",
  ui_story_1016_10160201_36_dialog_content = "<color=#e8d9bb>Você entrou na simulação de combate.</color>",
  ui_story_1016_10160201_37_dialog_content = "Parece que vai ser como da última vez.",
  ui_story_1016_10160201_38_dialog_content = "Onde estão Vice e Carleen? Ainda não colocaram os capacetes?",
  ui_story_1016_10160201_39_dialog_content = "Espere, isso é...",
  ui_story_1016_10160201_40_dialog_content = "Uau! Eu carreguei quase instantaneamente!",
  ui_story_1016_10160201_41_dialog_content = "Parece que eles fizeram muitas melhorias no Battlefield Simulator. Meu corpo dificilmente pode dizer a diferença entre a simulação e a vida real!",
  ui_story_1016_10160201_42_dialog_content = "Acho que quanto mais realista a simulação de combate, mais nossos instintos de sobrevivência começam a entrar em ação.",
  ui_story_1016_10160201_43_dialog_content = "Isso parece a linha defensiva do Illumina, não é?",
  ui_story_1016_10160201_44_dialog_content = "<color=#e8d9bb>Todos os participantes do exercício foram carregados com sucesso na simulação.</color>",
  ui_story_1016_10160201_45_dialog_content = "<color=#e8d9bb>Aviso: A batalha que você está prestes a vivenciar é uma recriação de uma batalha real em Illumina.</color>",
  ui_story_1016_10160201_46_dialog_content = "<color=#e8d9bb>Nesta batalha, ondas de Eclipsites romperam com sucesso a linha defensiva da Federação, incorrendo em pesadas baixas.</color>",
  ui_story_1016_10160201_47_dialog_content = "<color=#e8d9bb>Para avaliar melhor as capacidades de combate dos participantes, a escala da simulação foi reduzida a um nível que pode ser administrado por um esquadrão de três pessoas.</color>",
  ui_story_1016_10160201_48_dialog_content = "<color=#e8d9bb>Cada equipe foi colocada em pontos aleatórios em todo o campo de batalha. May a sorte esteja a seu favor.</color>",
  ui_story_1016_10160201_49_dialog_content = "<color=#e8d9bb>Deixe a batalha começar.</color>",
  ui_story_1016_10160201_50_dialog_content = "Então todos foram colocados em áreas diferentes, certo?",
  ui_story_1016_10160201_51_dialog_content = "Presumivelmente para evitar que as equipes interfiram umas nas outras durante a batalha, sim.",
  ui_story_1016_10160201_52_dialog_content = "O sistema disse que esta era uma simulação de uma batalha Illumina real. Ajudaria se soubéssemos mais sobre o que aconteceu na batalha original.",
  ui_story_1016_10160201_53_dialog_content = "Você sabe alguma coisa sobre isso, Vice?",
  ui_story_1016_10160201_54_dialog_content = "Eu realmente não. Muitas batalhas aconteceram nas fronteiras para contar, e recebemos muitos relatos de Eclipsites rompendo nossas defesas.",
  ui_story_1016_10160201_55_dialog_content = "Se a história é uma indicação, é assim que nossas linhas defensivas se parecem na maioria das vezes.",
  ui_story_1016_10160201_56_dialog_content = "Um constante estado de batalha...",
  ui_story_1016_10160201_57_dialog_content = "Eu vejo Eclipsites!",
  ui_story_1016_10160201_58_dialog_content = "Há tantos deles... Podemos realmente lidar com isso apenas com nós três?",
  ui_story_1016_10160201_59_dialog_content = "Espere... O sistema disse que os Eclipsitas conseguiram romper a linha defensiva militar.",
  ui_story_1016_10160201_60_dialog_content = "Isso significa que, embora a simulação tenha sido reduzida, não temos como mudar o resultado dessa batalha?",
  ui_story_1016_10160201_61_dialog_content = "Essa sensação de impotência... Deve ser assim que aqueles soldados Illumina se sentiram quando viram todos esses Eclipsites.",
  ui_story_1016_10160201_62_dialog_content = "Sim, mas ainda bem que é só uma simulação.",
  ui_story_1016_10160201_63_dialog_content = "Agora vamos dar tudo o que temos!",
  ui_story_1016_10160201_64_dialog_content = "Acordado! Vamos fazer isso!",
  ui_story_1016_10160202_1_dialog_content = "Carleen! Você precisa recuar agora mesmo!",
  ui_story_1016_10160202_2_dialog_content = "Eu quero, mas...",
  ui_story_1016_10160202_3_dialog_content = "Parece que quanto mais Eclipsites vencemos, mais eles começam a aparecer.",
  ui_story_1016_10160202_4_dialog_content = "Você tem razão. É como se eles estivessem focando em nossa localização exata.",
  ui_story_1016_10160202_5_dialog_content = "Se não sairmos daqui imediatamente, eles vão nos atropelar...",
  ui_story_1016_10160202_6_dialog_content = "Hum? Senhora Carleen!",
  ui_story_1016_10160202_7_dialog_content = "Beretta? O que você está fazendo aqui?!",
  ui_story_1016_10160202_8_dialog_content = "M-Minha equipe foi varrida pelos Eclipsites.",
  ui_story_1016_10160202_9_dialog_content = "Não tive escolha a não ser manter minha posição o máximo possível, mas os eclipsitas continuaram me forçando cada vez mais para trás.",
  ui_story_1016_10160202_10_dialog_content = "Me deparei com vários participantes durante a escaramuça interminável...",
  ui_story_1016_10160202_11_dialog_content = "Chega de conversa. Concentre-se no inimigo.",
  ui_story_1016_10160202_12_dialog_content = "Estou focando neles! Não preciso que você me lembre!",
  ui_story_1016_10160202_13_dialog_content = "Anatoli também está aqui! Você está na equipe de Yingel, não é?",
  ui_story_1016_10160202_14_dialog_content = "Ela e seu outro companheiro de equipe foram arrastados também?",
  ui_story_1016_10160202_15_dialog_content = "Sim, mas apenas porque alguém interferiu em nossa batalha.",
  ui_story_1016_10160202_16_dialog_content = "Ei! O que você quer dizer com interferir? Estamos do mesmo lado, não é?!",
  ui_story_1016_10160202_17_dialog_content = "O que mais eu chamaria quando você nos pesou assim?",
  ui_story_1016_10160202_18_dialog_content = "Tsc!",
  ui_story_1016_10160202_19_dialog_content = "Acho que nunca nos conhecemos. Você está com...",
  ui_story_1016_10160202_20_dialog_content = "Agora não é a hora, PlayerName! Estamos praticamente nos afogando em Eclipsites!",
  ui_story_1016_10160202_21_dialog_content = "Nesse ritmo, não conseguiremos resistir por muito mais tempo!",
  ui_story_1016_10160202_22_dialog_content = "Você está certo, seus números continuam se multiplicando...",
  ui_story_1016_10160202_23_dialog_content = "Beretta! Anatoli! E, uh, você aí!",
  ui_story_1016_10160202_24_dialog_content = "<size=45>Meu nome é Minch!!!</size>",
  ui_story_1016_10160202_25_dialog_content = "Precisamos nos unir! É a nossa única maneira de escapar do meio de toda essa luta!",
  ui_story_1016_10160202_26_dialog_content = "Receio que seja tarde demais... Não consigo pensar em nada agora...",
  ui_story_1016_10160202_27_dialog_content = "Ugh—!",
  ui_story_1016_10160202_28_dialog_content = "<size=45>Beretta!!!</size>",
  ui_story_1016_10160202_29_dialog_content = "Oh, não, agora temos que enfrentar todos os Eclipsites de sua equipe nós mesmos.",
  ui_story_1016_10160202_30_dialog_content = "Ahhhh! Th-Eles estão vindo direto para nós! O que deveríamos fazer?!",
  ui_story_1016_10160202_31_dialog_content = "Só precisamos manter a linha...",
  ui_story_1016_10160202_32_dialog_content = "Todos, tentem romper os inimigos atrás de vocês! Parece que há menos deles por lá!",
  ui_story_1016_10160202_34_dialog_content = "Cuidado, PlayerName!",
  ui_story_1016_10160202_35_dialog_content = "Eca-!",
  ui_story_1016_10160202_36_dialog_content = "Atrás de você! Rápido, vire-se—",
  ui_story_1016_10160202_37_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1016_10160202_38_dialog_content = "<color=#e8d9bb>Você saiu da simulação de combate.</color>",
  ui_story_1016_10160202_39_dialog_content = "Ufa... tô fora né?",
  ui_story_1016_10160202_40_dialog_content = "Mesmo morrendo no Battle Simulator parece dolorosamente real...",
  ui_story_1016_10160202_41_dialog_content = "me pergunto como Vice e Carleen estão aguentando?",
  ui_story_1016_10160202_42_dialog_content = "Ah—Parece que todos nós fomos mortos.",
  ui_story_1016_10160202_43_dialog_content = "De fato. Contra tantos Eclipsites, nunca houve chance de vitória.",
  ui_story_1016_10160202_44_dialog_content = "Haha, eles pegaram você também. Como você se sente sobre esta simulação?",
  ui_story_1016_10160202_45_dialog_content = "Parecia surpreendentemente real. Gronru estava certo, esta é a ferramenta definitiva para fornecer aos soldados experiência real em combate.",
  ui_story_1016_10160202_46_dialog_content = "Uma batalha tensa como essa é difícil o suficiente para vivenciar no mundo real, muito menos sobreviver a ela.",
  ui_story_1016_10160202_47_dialog_content = "Sem brincadeiras. Se tivéssemos realmente lutado naquela batalha, não haveria como todos nós teríamos voltado vivos.",
  ui_story_1016_10160202_48_dialog_content = "Eu sei direito? Depois dessa batalha, sinto que entendo muito melhor a gravidade da situação de Illumina.",
  ui_story_1016_10160202_49_dialog_content = "Acho que alguns soldados... Não têm escolha a não ser lutar uma batalha perdida.",
  ui_story_1016_10160202_50_dialog_content = "Sim...",
  ui_story_1016_10160202_51_dialog_content = "Tudo bem, turma! Para aqueles de vocês que estão fora da simulação, por favor, dirijam sua atenção para aqui.",
  ui_story_1016_10160202_52_dialog_content = "Tenho certeza que a batalha e os simuladores deixaram uma impressão duradoura em cada um de vocês.",
  ui_story_1016_10160202_53_dialog_content = "Então, aqui está uma pesquisa de experiência do usuário para você compartilhar seus comentários sobre o Battle Simulator!",
  ui_story_1016_10160202_54_dialog_content = "Ninguém sai até que todos tenham escrito algo!",
  ui_story_1016_10160202_55_dialog_content = "Uh... Uma pesquisa?",
  ui_story_1016_10160202_56_dialog_content = "Instrutor Gronru? Tem certeza de que não está nos usando apenas para fazer um teste?",
  ui_story_1016_10160202_57_dialog_content = "O que? Como você pode dizer algo assim?!",
  ui_story_1016_10160202_58_dialog_content = "Seu feedback é muito importante para melhorar as funções do Battle Simulator!",
  ui_story_1016_10160202_59_dialog_content = "Todos se beneficiariam com isso, não acha?",
  ui_story_1016_10160202_60_dialog_content = "Sim, claro...",
  ui_story_1016_10160202_61_dialog_content = "<color=#e8d9bb>Vinte minutos depois</color>",
  ui_story_1016_10160202_62_dialog_content = "Finalmente! Essa foi a pesquisa mais longa que já tive que preencher...",
  ui_story_1016_10160202_63_dialog_content = "Eu sei! Minha mão está dolorida de tanto escrever!",
  ui_story_1016_10160202_64_dialog_content = "A pesquisa nos pede para fornecer nossas pontuações da simulação de batalha. Alguém sabe quantos pontos ganhamos?",
  ui_story_1016_10160202_65_dialog_content = "Nenhuma pista. Eu nem sei se fomos bem ou não.",
  ui_story_1016_10160202_66_dialog_content = "Instrutor Gronru, onde podemos ver nossas pontuações?",
  ui_story_1016_10160202_67_dialog_content = "Oh, certo! Você vai precisar esperar mais um pouco.",
  ui_story_1016_10160202_68_dialog_content = "Ainda existem alguns participantes lutando dentro da simulação.",
  ui_story_1016_10160202_69_dialog_content = "Eles ainda estão aí?! Mas já faz tanto tempo...",
  ui_story_1016_10160202_70_dialog_content = "<color=#e8d9bb>A simulação de combate agora está completa.</color>",
  ui_story_1016_10160202_71_dialog_content = "<color=#e8d9bb>Calculando todos os resultados de combate—</color>",
  ui_story_1016_10160202_72_dialog_content = "<color=#e8d9bb>Cálculos concluídos. Os aurorianos vencem.</color>",
  ui_story_1016_10160202_73_dialog_content = "O que? Nós ganhamos?!",
  ui_story_1016_10160202_74_dialog_content = "<size=45>Eles ganharam?!?</size>",
  ui_story_1016_10160202_75_dialog_content = "Impossível! Ninguém nunca foi capaz de limpar este palco...!",
  ui_story_1016_10160202_76_dialog_content = "Quem foi o último a sair da simulação?",
  ui_story_1016_10160202_77_dialog_content = "Ufa! Este capacete fica muito desconfortável se você usá-lo por muito tempo.",
  ui_story_1016_10160202_78_dialog_content = "Essa simulação parecia bem real! Não foi nada ruim se você me perguntar!",
  ui_story_1016_10160202_79_dialog_content = "Suponho que estar constantemente envolvido na guerra deu a Illumina uma ideia dolorosamente clara de como é o combate.",
  ui_story_1016_10160202_80_dialog_content = "Mas uma experiência excessivamente realista também tem suas desvantagens.",
  ui_story_1016_10160202_81_dialog_content = "Se você souber como a luta original progrediu, poderá prever todas as mudanças no campo de batalha.",
  ui_story_1016_10160202_82_dialog_content = "Isso, por sua vez, reduz drasticamente a dificuldade da simulação.",
  ui_story_1016_10160202_83_dialog_content = "H-Ele pensou que era muito fácil?!",
  ui_story_1016_10160202_84_dialog_content = "Não gosto do ambiente de simulação.",
  ui_story_1016_10160202_85_dialog_content = "Por mais sinceras que fossem minhas invocações, só fui atendida por uma luz artificial.",
  ui_story_1016_10160202_86_dialog_content = "Não seja tão sério, José! Pense nisso como um jogo!",
  ui_story_1016_10160202_87_dialog_content = "Ei, olha, nossas pontuações finalmente chegaram!",
  ui_story_1016_10160202_88_dialog_content = "A equipe de Leo... Eles marcaram tão alto...",
  ui_story_1016_10160202_89_dialog_content = "Ninguém chegou nem perto...",
  ui_story_1016_10160202_90_dialog_content = "Estávamos lutando no mesmo campo de batalha, não estávamos?",
  ui_story_1016_10160202_91_dialog_content = "Como eles conseguiram superar todos aqueles Eclipsites...?",
  ui_story_1016_10160202_92_dialog_content = "Eu vi o jeito que eles fizeram.",
  ui_story_1016_10160202_93_dialog_content = "Foram eles... Foram eles que derrubaram todos aqueles Eclipsites sobre nossas cabeças...",
  ui_story_1016_10160202_94_dialog_content = "O quê?!",
  ui_story_1016_10160202_95_dialog_content = "Mas como? Como eles poderiam ter feito algo assim?",
  ui_story_1016_10160202_96_dialog_content = "É verdade. Eles sabiam como atrair os Eclipsitas que chegavam para segui-los até que todos estivessem reunidos em um só lugar.",
  ui_story_1016_10160202_97_dialog_content = "Depois disso, eles usaram o terreno a seu favor e forçaram os Eclipsitas a combatê-los em corredores estreitos. Uma vez que eles não podiam confiar em seus números para vencer, a equipe de Leo os eliminou facilmente.",
  ui_story_1016_10160202_98_dialog_content = "Os Eclipsitas não eram diferentes de um rebanho de ovelhas, caminhando uma a uma para um covil de lobos famintos...",
  ui_story_1016_10160202_99_dialog_content = "Reunindo Eclipsites... Eu não tinha ideia de que isso poderia ser feito...",
  ui_story_1016_10160202_100_dialog_content = "Não foi uma estratégia particularmente inteligente, mas quando você se depara com dezenas de inimigos como esse, tudo o que você pode fazer é quebrar a cabeça em busca de uma solução.",
  ui_story_1016_10160202_101_dialog_content = "Você também não encontrará a resposta em um livro. Nenhum livro pode realmente dizer como vencer uma batalha invencível.",
  ui_story_1016_10160202_102_dialog_content = "Sua única escolha é bolar um plano e colocá-lo em ação, por mais ridículo que pareça.",
  ui_story_1016_10160202_103_dialog_content = "E se você tiver a sorte de sobreviver uma e outra vez por causa dessas estratégias ridículas, isso significa que você descobriu sua própria maneira de sair vitorioso na batalha.",
  ui_story_1016_10160202_104_dialog_content = "(Isso mesmo! Quando vi pela primeira vez Leo, ele usou os métodos menos convencionais para travar suas batalhas.)",
  ui_story_1016_10160202_105_dialog_content = "(Acho que nenhum de nós poderia se comparar ao pessoal de Crepúsculo quando se trata de improvisar no campo de batalha.)",
  ui_story_1016_10160202_106_dialog_content = "Heh, coisas muito poderosas lá, Leo! Vocês conseguiram deixar toda a turma em silêncio!",
  ui_story_1016_10160202_107_dialog_content = "Algum de vocês está anotando? Ou você está muito ocupado olhando para o placar?",
  ui_story_1016_10160202_108_dialog_content = "Honestamente, é como se vocês fossem um bando de crianças que acabaram de ver uma arma pela primeira vez!",
  ui_story_1016_10160301_1_dialog_content = "<color=#e8d9bb>Uma semana depois</color>",
  ui_story_1016_10160301_2_dialog_content = "Huh? O que estou fazendo nos escritórios? Fiz uma curva errada em algum lugar?",
  ui_story_1016_10160301_3_dialog_content = "Tenho certeza que a sala de aula é...",
  ui_story_1016_10160301_4_dialog_content = "Você está dando um passeio, PlayerName?",
  ui_story_1016_10160301_5_dialog_content = "A aula vai começar em breve, você sabe.",
  ui_story_1016_10160301_6_dialog_content = "Anatoli! Oh, graças a Deus!",
  ui_story_1016_10160301_7_dialog_content = "Você sabe como chegar à sala de aula a partir daqui? Estou andando por esses corredores há tanto tempo que estou começando a ficar tonto, heheheh.",
  ui_story_1016_10160301_8_dialog_content = "Eu vejo. Me siga.",
  ui_story_1016_10160301_9_dialog_content = "Você tem sorte de eu ter encontrado você, ou então você pode ter perdido alguns créditos por estar atrasado.",
  ui_story_1016_10160301_10_dialog_content = "Todo mundo está falando sobre créditos hoje. O que exatamente são eles?",
  ui_story_1016_10160301_11_dialog_content = "Quer dizer que não olhou o manual que lhe deram ontem?",
  ui_story_1016_10160301_12_dialog_content = "Ainda não, não. Gronru me arrastou para fazer alguns trabalhos de depuração em Soroz ontem.",
  ui_story_1016_10160301_13_dialog_content = "Então deixe-me dar-lhe uma breve explicação.",
  ui_story_1016_10160301_14_dialog_content = "A partir de hoje, o desempenho de todos em suas aulas será registrado como uma certa quantidade de créditos.",
  ui_story_1016_10160301_15_dialog_content = "Cada participante continuará a acumular créditos até ao final da fase de aprendizagem.",
  ui_story_1016_10160301_16_dialog_content = "O uso mais óbvio desses créditos é julgar sua habilidade. No entanto, eles também servem a outro propósito.",
  ui_story_1016_10160301_17_dialog_content = "Seus créditos também o ajudarão durante a avaliação.",
  ui_story_1016_10160301_18_dialog_content = "Como assim?",
  ui_story_1016_10160301_19_dialog_content = "Antes do início da fase de avaliação, você poderá trocar seus créditos por determinados itens, que podem aumentar seu poder geral.",
  ui_story_1016_10160301_20_dialog_content = "Quanto mais créditos você ganhar, mais suporte poderá obter.",
  ui_story_1016_10160301_21_dialog_content = "Por esse motivo, todos esperam ganhar o máximo de créditos possível durante as aulas.",
  ui_story_1016_10160301_22_dialog_content = "Não é de admirar que todos estejam tão competitivos ultimamente!",
  ui_story_1016_10160301_23_dialog_content = "Isso mesmo. Você precisará levar as coisas mais a sério se quiser alguma esperança de vencer aqui.",
  ui_story_1016_10160301_24_dialog_content = "Parece que chegamos bem a tempo.",
  ui_story_1016_10160301_25_dialog_content = "Você memorizou o caminho até aqui desta vez?",
  ui_story_1016_10160301_26_dialog_content = "Haha, espero que sim!",
  ui_story_1016_10160301_27_dialog_content = "Então, o que estamos aprendendo hoje?",
  ui_story_1016_10160301_28_dialog_content = "Estratégias ofensivas em combate ao vivo.",
  ui_story_1016_10160301_29_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_1016_10160301_30_dialog_content = "Ei! Vocês dois aí!",
  ui_story_1016_10160301_31_dialog_content = "Mais vinte segundos e você estaria atrasado!",
  ui_story_1016_10160301_32_dialog_content = "Essa foi por pouco...",
  ui_story_1016_10160301_33_dialog_content = "Certo, agora que os alunos mais lentos finalmente chegaram, podemos começar nossa aula.",
  ui_story_1016_10160301_34_dialog_content = "Meu nome é Wrath. Sou o Capitão da Legião da Guarda de Illumina, assim como seu instrutor de hoje.",
  ui_story_1016_10160301_35_dialog_content = "E o tema da aula de hoje é bem simples: luta!",
  ui_story_1016_10160301_36_dialog_content = "Brigando?",
  ui_story_1016_10160301_37_dialog_content = "Agora vocês provavelmente estão pensando: \"Lutar? O que podemos aprender com a luta?\"",
  ui_story_1016_10160301_38_dialog_content = "Eu sei que todos vocês aqui têm algum tipo de confiança em suas habilidades de luta.",
  ui_story_1016_10160301_39_dialog_content = "No entanto, tenho certeza de que muitos de vocês também são preguiçosos quando se trata de lutar.",
  ui_story_1016_10160301_40_dialog_content = "O que estou prestes a ensinar não é como vencer, mas como alcançar a vitória perfeita!",
  ui_story_1016_10160301_41_dialog_content = "Em uma luta vencível, terminar as coisas rapidamente ajudará você a conservar sua força para a próxima batalha.",
  ui_story_1016_10160301_42_dialog_content = "A vitória nem sempre vem facilmente. Cada ação que leva a isso deve ser executada sem falhas.",
  ui_story_1016_10160301_43_dialog_content = "Acho que isso faz sentido...",
  ui_story_1016_10160301_44_dialog_content = "Acho que não passei por nenhum treinamento de combate focado especificamente na eficiência.",
  ui_story_1016_10160301_45_dialog_content = "Ela tem razão, embora fazer tudo perfeitamente pareça um pouco irreal.",
  ui_story_1016_10160301_46_dialog_content = "Você é capaz de executar em um nível perfeito, instrutor Wrath?",
  ui_story_1016_10160301_47_dialog_content = "Você está duvidando de mim, punk?",
  ui_story_1016_10160301_48_dialog_content = "De jeito nenhum, só me preocupo em não conseguir aprender nada prático.",
  ui_story_1016_10160301_49_dialog_content = "Tch. Estou mais preocupado que você não consiga aguentar meu treinamento.",
  ui_story_1016_10160301_50_dialog_content = "Chega de conversa fiada. Reúna-se com seus grupos, todos vocês!",
  ui_story_1016_10160301_51_dialog_content = "Vamos nos concentrar no combate real hoje e você enfrentará soldados Illumina altamente treinados na aula de hoje.",
  ui_story_1016_10160301_52_dialog_content = "Primeiro grupo, prepare-se!",
  ui_story_1016_10160301_53_dialog_content = "<size=45>Sim, senhora!</size>",
  ui_story_1016_10160301_54_dialog_content = "Vamos dar a esses alunos uma saudação Illumina adequada.",
  ui_story_1016_10160301_55_dialog_content = "<size=45>Sim, senhora!</size>",
  ui_story_1016_10160301_56_dialog_content = "E certifique-se de dar ao menino cavaleiro de Lumopolis uma recepção especialmente calorosa.",
  ui_story_1016_10160301_57_dialog_content = "Se isso ainda não for suficiente para você, sinta-se à vontade para vir me ver depois da aula para uma aula particular!",
  ui_story_1016_10160301_58_dialog_content = "Acho que vou me concentrar um pouco mais na lição de hoje.",
  ui_story_1016_10160301_59_dialog_content = "Vamos precisar de todos os créditos que conseguirmos, certo?",
  ui_story_1016_10160301_60_dialog_content = "Isso mesmo. Esta é a nossa primeira oportunidade de ganhar créditos, então vamos todos dar o nosso melhor!",
  ui_story_1016_10160301_61_dialog_content = "O que devo fazer, Yingel?",
  ui_story_1016_10160301_62_dialog_content = "Apenas vá com calma por enquanto.",
  ui_story_1016_10160301_63_dialog_content = "<size=32>Sou só eu... ou esses alunos parecem um pouco assustadores...?</size>",
  ui_story_1016_10160301_64_dialog_content = "<size=32>Eu estou aí com você...</size>",
  ui_story_1016_10160401_1_dialog_content = "<color=#e8d9bb>Um mês depois</color>",
  ui_story_1016_10160401_2_dialog_content = "Tudo bem, isso servirá para a lição de hoje.",
  ui_story_1016_10160401_3_dialog_content = "Classe dispensada.",
  ui_story_1016_10160401_4_dialog_content = "Muito bem, PlayerName! Marcamos muitos créditos hoje!",
  ui_story_1016_10160401_5_dialog_content = "Sim, mas não é fácil quando todo mundo está lutando para fazer o mesmo. Estou exausta.",
  ui_story_1016_10160401_6_dialog_content = "Agora que estamos chegando ao fim da fase de aprendizado de lições, é natural que a competição tenha se tornado tão acirrada.",
  ui_story_1016_10160401_7_dialog_content = "Você já viu o ranking de hoje?",
  ui_story_1016_10160401_8_dialog_content = "Ainda não. Onde estamos na lista?",
  ui_story_1016_10160401_9_dialog_content = "Terceiro lugar.",
  ui_story_1016_10160401_10_dialog_content = "Uau! Subimos de quarto!",
  ui_story_1016_10160401_11_dialog_content = "Coisas estão melhorando! Como está o primeiro e o segundo lugar?",
  ui_story_1016_10160401_12_dialog_content = "Equipe Leo está muito à frente de todos os outros em primeiro lugar. Não há surpresas lá.",
  ui_story_1016_10160401_13_dialog_content = "Na verdade... Receio que nenhuma equipe seja capaz de diminuir a diferença antes do início da próxima fase.",
  ui_story_1016_10160401_14_dialog_content = "Então eles ainda estão bem na liderança...",
  ui_story_1016_10160401_15_dialog_content = "Em segundo lugar está a equipe Yingel, embora só recentemente eles começaram a mostrar seus talentos.",
  ui_story_1016_10160401_16_dialog_content = "Sua equipe não tem deficiências óbvias e teve um bom desempenho em todas as classes até agora, o que garantiu seu lugar na classificação.",
  ui_story_1016_10160401_17_dialog_content = "A que distância estamos deles?",
  ui_story_1016_10160401_18_dialog_content = "Cerca de metade do quanto eles estão atrás da equipe Leo?",
  ui_story_1016_10160401_19_dialog_content = "Parece que eles estão muito à frente, então...",
  ui_story_1016_10160401_20_dialog_content = "O desempenho em classe de Yingel tem sido excelente até agora. Superá-la nesse aspecto seria difícil, de fato.",
  ui_story_1016_10160401_21_dialog_content = "Mas fora da sala de aula é uma história totalmente diferente.",
  ui_story_1016_10160401_22_dialog_content = "Fora da sala de aula?",
  ui_story_1016_10160401_23_dialog_content = "Ontem, vi várias equipes realizando treinamentos extracurriculares por conta própria.",
  ui_story_1016_10160401_24_dialog_content = "Depois, entregavam os resultados do treinamento aos instrutores em troca de créditos.",
  ui_story_1016_10160401_25_dialog_content = "O que? Eu não sabia que podíamos fazer isso!",
  ui_story_1016_10160401_26_dialog_content = "De fato. Parece que os organizadores deste Exercício Militar Conjunto estão dando grande ênfase ao treinamento de todos nós.",
  ui_story_1016_10160401_27_dialog_content = "E embora esse método não ofereça muitos créditos, eles podem se acumular com o tempo.",
  ui_story_1016_10160401_28_dialog_content = "Esta pode ser a nossa maneira de superar o Team Yingel.",
  ui_story_1016_10160401_29_dialog_content = "Sim! Eu penso que é uma grande ideia!",
  ui_story_1016_10160401_30_dialog_content = "Vocês dois com certeza estão animados. Nesse ritmo, estaremos competindo com os outros a cada hora do dia!",
  ui_story_1016_10160401_31_dialog_content = "Bem, vamos dar uma olhada na programação.",
  ui_story_1016_10160401_32_dialog_content = "Precisamos planejar as coisas com cuidado se quisermos maximizar nossos créditos.",
  ui_story_1016_10160401_33_dialog_content = "<color=#e8d9bb>No dia seguinte, na sala de aula</color>",
  ui_story_1016_10160401_34_dialog_content = "Mais e mais participantes ficam para trás depois que a aula termina.",
  ui_story_1016_10160401_35_dialog_content = "Devemos fazer algum treinamento extracurricular também?",
  ui_story_1016_10160401_36_dialog_content = "Você é mais do que bem-vindo para fazer isso por conta própria.",
  ui_story_1016_10160401_37_dialog_content = "Mas se for apenas para ganhar mais créditos, é desnecessário.",
  ui_story_1016_10160401_38_dialog_content = "Mas quanto mais créditos ganharmos, mais vantagem teremos na avaliação. Isso não é importante?",
  ui_story_1016_10160401_39_dialog_content = "É, mas não precisamos levar muito a sério esse exercício conjunto...",
  ui_story_1016_10160401_40_dialog_content = "Olhar, Yingel.",
  ui_story_1016_10160401_41_dialog_content = "O chão e os sparrings de lá são muito coloridos agora.",
  ui_story_1016_10160401_42_dialog_content = "Muito colorido?",
  ui_story_1016_10160401_43_dialog_content = "O que aconteceu? é tinta?",
  ui_story_1016_10160401_44_dialog_content = "O manequim de treinamento explodiu de repente agora.",
  ui_story_1016_10160401_45_dialog_content = "...",
  ui_story_1016_10160401_46_dialog_content = "Eu estou supondo que alguém o preencheu com diferentes tipos de tinta com antecedência.",
  ui_story_1016_10160401_47_dialog_content = "É possível que Vivian e os outros fizeram isso?",
  ui_story_1016_10160401_48_dialog_content = "Certamente eles não fariam brincadeiras tão infantis, certo?",
  ui_story_1016_10160401_49_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_1016_10160401_50_dialog_content = "<size=45>Aquilo era uma arma?!</size>",
  ui_story_1016_10160401_51_dialog_content = "O que você pensa que está fazendo?!?",
  ui_story_1016_10160401_52_dialog_content = "Eu...",
  ui_story_1016_10160401_53_dialog_content = "Chloe, você está bem?",
  ui_story_1016_10160401_54_dialog_content = "Eu estou bem. Nenhuma bala foi disparada. A única coisa que saiu foi uma pilha de confete.",
  ui_story_1016_10160401_55_dialog_content = "Meus ouvidos ainda estão zumbindo de quão alto aquele tiro soou, embora...",
  ui_story_1016_10160401_56_dialog_content = "Explique-se, soldado! Como algo assim pode acontecer?!",
  ui_story_1016_10160401_57_dialog_content = "Eu não acho que é culpa dele, Beretta.",
  ui_story_1016_10160401_58_dialog_content = "Olhe para os olhares surpresos em seus rostos.",
  ui_story_1016_10160401_59_dialog_content = "Hã?",
  ui_story_1016_10160401_60_dialog_content = "É verdade... Algo não parecia certo quando puxei o gatilho, então virei a arma o mais rápido que pude.",
  ui_story_1016_10160401_61_dialog_content = "Afinal, parece que meu palpite estava certo. Alguém substituiu um dos meus espaços em branco por... confete?",
  ui_story_1016_10160401_62_dialog_content = "Alguém trocou sua munição? Mas como pode ser isso?!",
  ui_story_1016_10160401_63_dialog_content = "Estou tão confuso quanto você.",
  ui_story_1016_10160401_64_dialog_content = "Por favor me perdoe. Vou relatar isso aos meus superiores imediatamente.",
  ui_story_1016_10160401_65_dialog_content = "Os espaços em branco foram trocados?",
  ui_story_1016_10160401_66_dialog_content = "Mas quem faria algo tão perigoso...?",
  ui_story_1016_10160401_67_dialog_content = "É mais bobo do que perigoso.",
  ui_story_1016_10160401_68_dialog_content = "Alguém quer interferir no treinamento de todos os outros para impedi-los de ganhar créditos.",
  ui_story_1016_10160401_69_dialog_content = "Mas quem recorreria a coisas tão imaturas?",
  ui_story_1016_10160401_70_dialog_content = "É difícil dizer. Com tantas facções reunidas aqui, as apostas são altas e complicadas.",
  ui_story_1016_10160401_71_dialog_content = "Mas, desde que possamos evitar ser sugados para esta lama, não é da nossa conta.",
  ui_story_1016_10160401_72_dialog_content = "Não se envolva com nada nem ninguém fora das nossas aulas, entendeu?",
  ui_story_1016_10160401_73_dialog_content = "Entendi.",
  ui_story_1016_10160401_74_dialog_content = "Vamos lá, Axelia.",
  ui_story_1016_10160401_75_dialog_content = "Tá bom.",
  ui_story_1016_10160401_76_dialog_content = "<color=#e8d9bb>Enquanto isso, no Laboratório Illumina</color>",
  ui_story_1016_10160401_77_dialog_content = "Eu fiz isso! Consegui permissão para usar o Battle Simulator!",
  ui_story_1016_10160401_78_dialog_content = "Seremos capazes de economizar muito tempo e energia com isso!",
  ui_story_1016_10160401_79_dialog_content = "Acordado. Assim que o restante dos participantes deixar a sala de aula, podemos voltar e realizar algum treinamento de resistência.",
  ui_story_1016_10160401_80_dialog_content = "Essa deve ser nossa rota mais eficiente para ganhar mais créditos.",
  ui_story_1016_10160401_81_dialog_content = "Você pensou muito nisso, não é? Carleen?",
  ui_story_1016_10160401_82_dialog_content = "Participei do último exercício conjunto, lembra? Eu ainda tenho algum conhecimento útil da minha experiência anterior.",
  ui_story_1016_10160401_83_dialog_content = "Não há tempo a perder. Vamos começar imediatamente.",
  ui_story_1016_10160401_84_dialog_content = "Claro! Acabamos de colocar os capacetes na cabeça como da última vez, certo?",
  ui_story_1016_10160401_85_dialog_content = "Huh? Onde estou?",
  ui_story_1016_10160401_86_dialog_content = "Isso não se parece em nada com a última simulação.",
  ui_story_1016_10160401_87_dialog_content = "Onde estão os inimigos?",
  ui_story_1016_10160401_88_dialog_content = "Deixe-me explorar a área...",
  ui_story_1016_10160401_89_option_content = "Aumento de Força!",
  ui_story_1016_10160401_90_dialog_content = "<anim type=Shake>Silvo...</anim>",
  ui_story_1016_10160401_91_dialog_content = "Eu sinto muitos inimigos! Ainda mais do que da última vez!",
  ui_story_1016_10160401_92_dialog_content = "O Darkflow que eles estão emitindo também é muito poderoso!",
  ui_story_1016_10160401_93_dialog_content = "Não me diga que temos que fugir de novo?",
  ui_story_1016_10160401_94_dialog_content = "Acho que não há para onde fugir...",
  ui_story_1016_10160401_95_dialog_content = "Eles estão vindo!",
  ui_story_1016_10160401_96_dialog_content = "<anim type=Shake><size=50>Graaaaah!!!</size></anim>",
  ui_story_1016_10160401_97_dialog_content = "Dispersem, pétalas de gelo!",
  ui_story_1016_10160401_98_dialog_content = "Meu ataque... não teve efeito...",
  ui_story_1016_10160401_99_dialog_content = "Algo está definitivamente errado com esses Eclipsites!",
  ui_story_1016_10160401_100_dialog_content = "Seja como for, isso ainda é apenas uma simulação. Apenas continue lutando!",
  ui_story_1016_10160402_11_dialog_content = "Cuidado, vocês dois!",
  ui_story_1016_10160402_12_dialog_content = "Tem ainda mais por aqui...",
  ui_story_1016_10160402_13_dialog_content = "Carleen! Vice!",
  ui_story_1016_10160402_14_dialog_content = "<size=45>Ah—!!!</size>",
  ui_story_1016_10160402_15_dialog_content = "<anim type=Shake>suspiro- suspiro-</anim>",
  ui_story_1016_10160402_16_dialog_content = "Que batalha foi essa...",
  ui_story_1016_10160402_17_dialog_content = "Você estava certo. Algo estava errado com aqueles Eclipsites.",
  ui_story_1016_10160402_18_dialog_content = "Poderoso nem começa a descrever esses monstros.",
  ui_story_1016_10160402_19_dialog_content = "Você tem razão. Seus ataques não eram diferentes dos Eclipsites normais, mas seu Darkflow era anormalmente denso...",
  ui_story_1016_10160402_20_dialog_content = "Você não acha que alguém pode ter adulterado o Battle Simulator, não é?",
  ui_story_1016_10160402_21_dialog_content = "Continue.",
  ui_story_1016_10160402_22_dialog_content = "O Guardian One me disse uma vez que não importa o quão realista pareça uma simulação, ainda são apenas dados.",
  ui_story_1016_10160402_23_dialog_content = "As batalhas que vivenciamos na simulação são mais como algum tipo de computação de dados.",
  ui_story_1016_10160402_24_dialog_content = "Se alguém mudasse os números nos dados e os tornasse realmente grandes, o equilíbrio na simulação seria completamente prejudicado.",
  ui_story_1016_10160402_25_dialog_content = "O resultado pode até ser parecido com o que vimos agora.",
  ui_story_1016_10160402_26_dialog_content = "Você tem razão! Os dados envolvendo os níveis de força desses Eclipsites devem ter sido alterados para torná-los impossivelmente poderosos!",
  ui_story_1016_10160402_27_dialog_content = "Mas quem faria algo tão errado?",
  ui_story_1016_10160402_28_dialog_content = "PlayerName, você pode sentir alguém por perto?",
  ui_story_1016_10160402_29_dialog_content = "Estou tentando, mas não sinto ninguém suspeito.",
  ui_story_1016_10160402_30_dialog_content = "Entendo...",
  ui_story_1016_10160402_31_dialog_content = "Se nossas suspeitas estiverem corretas, devemos denunciá-las aos nossos instrutores.",
  ui_story_1016_10160402_32_dialog_content = "Acho melhor adiarmos nosso treinamento por enquanto. As coisas são estranhas o suficiente, como são.",
  ui_story_1016_10160402_33_dialog_content = "Acordado. Vamos voltar para o quartel.",
  ui_story_1016_10160402_34_dialog_content = "Então alguém realmente mexeu na simulação, hein?",
  ui_story_1016_10160402_35_dialog_content = "Sim. Gronru executou uma varredura de diagnóstico completa do Battle Simulator e encontrou um monte de dados que foram alterados manualmente.",
  ui_story_1016_10160402_36_dialog_content = "Infelizmente, ainda não sabemos quem fez isso.",
  ui_story_1016_10160402_37_dialog_content = "Qual foi o motivo do culpado para fazer isso...?",
  ui_story_1016_10160402_38_dialog_content = "O que quer que aconteça dentro do Battle Simulator não tem efeito tangível sobre nós ou sobre o mundo real.",
  ui_story_1016_10160402_39_dialog_content = "Com isso em mente... É provável que o culpado estivesse tentando nos impedir de ganhar mais créditos.",
  ui_story_1016_10160402_40_dialog_content = "Quando você coloca dessa forma, faz sentido.",
  ui_story_1016_10160402_41_dialog_content = "Mas isso não significaria que o culpado é um dos participantes?",
  ui_story_1016_10160402_42_dialog_content = "É muito provável. Afinal, a competição intensa certamente atrairá concorrentes ainda mais ferozes.",
  ui_story_1016_10160402_43_dialog_content = "Nos Exercícios Militares Conjuntos anteriores, as tensões sempre eclodiram entre os participantes de Lumopolis e Illumina.",
  ui_story_1016_10160402_44_dialog_content = "Dessa perspectiva, o exercício é apenas uma versão reduzida da competição entre diferentes facções.",
  ui_story_1016_10160402_45_dialog_content = "Mas então por que eles visariam nossa equipe?",
  ui_story_1016_10160402_46_dialog_content = "Eu sou um celestita, Carleen é de Lumopolis, e Vice é da Ilumina.",
  ui_story_1016_10160402_47_dialog_content = "Uma competição entre diferentes facções não deveria ter nada a ver conosco, certo?",
  ui_story_1016_10160402_48_dialog_content = "Não acho que fomos necessariamente visados.",
  ui_story_1016_10160402_49_dialog_content = "Lembre-se, acabamos de receber permissão para usar o Battle Simulator fora do horário normal.",
  ui_story_1016_10160402_50_dialog_content = "É possível que quem mexeu no simulador não soubesse que o usaríamos em seguida.",
  ui_story_1016_10160402_51_dialog_content = "Então o alvo real...",
  ui_story_1016_10160402_52_dialog_content = "De acordo com o cronograma, a equipe de Leo foi a próxima equipe a usar o Battle Simulator.",
  ui_story_1016_10160402_53_dialog_content = "Oh! Faz todo o sentido então!",
  ui_story_1016_10160402_54_dialog_content = "Como eles estão em primeiro lugar, é natural que alguém esteja tentando atrasá-los!",
  ui_story_1016_10160402_55_dialog_content = "De fato. De todas as possibilidades, acredito que essa seja a mais provável.",
  ui_story_1016_10160402_56_dialog_content = "Mas, por enquanto, vamos nos concentrar apenas em nós mesmos.",
  ui_story_1016_10160402_57_dialog_content = "Devemos nos preocupar mais com nossa situação do que com o que os outros estão fazendo.",
  ui_story_1016_10160402_58_dialog_content = "Venha, vamos fazer um plano para o treinamento de amanhã.",
  ui_story_1016_10160402_59_dialog_content = "Beleza!",
  ui_story_1016_10160402_60_dialog_content = "Hahahahaha! Isso é divertido demais!",
  ui_story_1016_10160402_61_dialog_content = "Não fazia ideia que você sabia mexer com o Battle Simulator desse jeito, Dysis!",
  ui_story_1016_10160402_62_dialog_content = "Eu aprendi como fazer isso recentemente.",
  ui_story_1016_10160402_63_dialog_content = "O Exercício Militar Conjunto nos dá a chance de ler livros aos quais normalmente não temos acesso. Sugiro que ambos façam o mesmo.",
  ui_story_1016_10160402_64_dialog_content = "Oportunidades de aprendizado como essa não surgem todos os dias, você sabe.",
  ui_story_1016_10160402_65_dialog_content = "Ler livros, você diz? Isso é rico, vindo de uma pessoa cega. Não conte comigo!",
  ui_story_1016_10160402_66_dialog_content = "Vamos fazer ainda mais travessuras amanhã, Merry!",
  ui_story_1016_10160402_67_dialog_content = "Ver? Eles já estão começando a desconfiar um do outro! Isso é ótimo!",
  ui_story_1016_10160402_68_dialog_content = "Apenas tente não ser pego. Eles parecem que podem ficar com raiva.",
  ui_story_1016_10160402_69_dialog_content = "Sem chance! Os de Illumina estão muito ocupados suspeitando dos de Lumopolis, e vice-versa.",
  ui_story_1016_10160402_70_dialog_content = "Eles nunca vão suspeitar de nós, com nossas pontuações baixas e nossa postura neutra!",
  ui_story_1016_10160402_71_dialog_content = "Tens o meu voto nisto, Minch.",
  ui_story_1016_10160402_72_dialog_content = "A razão é a corrente que prende nossas mentes, forçando-nos constantemente a buscar significado em tudo o que fazemos.",
  ui_story_1016_10160402_73_dialog_content = "Rapaz, lá vamos nós de novo...",
  ui_story_1016_10160402_74_dialog_content = "Mas eles não conseguem perceber que sua maneira de pensar é muito estreita.",
  ui_story_1016_10160402_75_dialog_content = "Como criaturas pequenas e insignificantes, todas as nossas ações são totalmente sem sentido.",
  ui_story_1016_10160402_76_dialog_content = "Sua falha em entender isso significa que eles nunca terão uma resposta para malícia não provocada.",
  ui_story_1016_10160402_77_dialog_content = "Então jogue seus jogos, minha querida Minch. Jogue-os para o conteúdo do seu coração.",
  ui_story_1016_10160402_78_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1016_10160402_79_dialog_content = "Onde é que eles...",
  ui_story_1016_10160402_80_dialog_content = "Suspiro, eles me deixaram para trás novamente.",
  ui_story_1016_10160402_81_dialog_content = "Muito bem, eu vou voltar por conta própria. Agora, para que lado ficava o quartel de novo...?",
  ui_story_1016_10160402_82_dialog_content = "Hum?",
  ui_story_1016_10160501_1_dialog_content = "Encontramos sinais de Eclipsites! Vá chamar reforços!",
  ui_story_1016_10160501_2_dialog_content = "Não podemos deixar escapar nenhum!",
  ui_story_1016_10160501_3_dialog_content = "Capitão Wrath já foi avisado! Precisamos nos juntar aos outros imediatamente!",
  ui_story_1016_10160501_4_dialog_content = "Entendi...",
  ui_story_1016_10160501_5_dialog_content = "Ei, por que você está parado assim? Você não nos ouviu? Há Eclipsites à frente!",
  ui_story_1016_10160501_6_dialog_content = "Desculpa, são os meus olhos...",
  ui_story_1016_10160501_7_dialog_content = "Oh, não, ele é cego!",
  ui_story_1016_10160501_8_dialog_content = "Ele é? Oh... P-Por favor, desculpe minha grosseria agora.",
  ui_story_1016_10160501_9_dialog_content = "Infelizmente, não podemos dispensar ninguém para escoltá-lo para casa agora.",
  ui_story_1016_10160501_10_dialog_content = "Você se importaria de se esconder perto da rua por enquanto? Esta área ainda é segura, posso garantir.",
  ui_story_1016_10160501_11_dialog_content = "Está tudo bem, por favor, não se preocupem comigo.",
  ui_story_1016_10160501_12_dialog_content = "Afinal, é uma emergência. Vá em frente e, por favor, tenha cuidado.",
  ui_story_1016_10160501_13_dialog_content = "Sentimos muito... Por favor, cuide-se bem!",
  ui_story_1016_10160501_14_dialog_content = "Vamos, vamos!",
  ui_story_1016_10160501_15_dialog_content = "Entendido!",
  ui_story_1016_10160501_16_dialog_content = "Eclipsites na cidade de Gannon...",
  ui_story_1016_10160501_17_dialog_content = "Parece que alguém lá fora está fazendo ainda mais travessuras do que nós.",
  ui_story_1016_10160501_18_dialog_content = "<color=#e8d9bb>Pit, pat, pit, pat...</color>",
  ui_story_1016_10160501_19_dialog_content = "Lá! Logo à frente!",
  ui_story_1016_10160501_20_dialog_content = "Estamos quase—",
  ui_story_1016_10160501_21_dialog_content = "Atenção!!!",
  ui_story_1016_10160501_22_dialog_content = "<anim type=Shake><size=50>Graaaaah!!!</size></anim>",
  ui_story_1016_10160501_23_dialog_content = "O que? Th-Eles estão voltando para nós!",
  ui_story_1016_10160501_24_dialog_content = "São muitos para nós lidarmos...",
  ui_story_1016_10160501_25_dialog_content = "Não temos escolha a não ser lutar!",
  ui_story_1016_10160501_26_dialog_content = "Pelo menos até chegarem os reforços...",
  ui_story_1016_10160501_27_dialog_content = "Não pareça tão desesperado, vocês dois! Esta é a cidade de Gannon, não é?",
  ui_story_1016_10160501_28_dialog_content = "Quem é você?!",
  ui_story_1016_10160501_29_dialog_content = "Apenas um transeunte de bom coração.",
  ui_story_1016_10160501_30_dialog_content = "Inacreditável...",
  ui_story_1016_10160501_31_dialog_content = "Th-Obrigado!",
  ui_story_1016_10160501_32_dialog_content = "Se você quer agradecer a alguém, agradeça a esse cara. É ele que gosta de sair para passear todos os dias.",
  ui_story_1016_10160501_33_dialog_content = "Você está tentando cercar as forças inimigas?",
  ui_story_1016_10160501_34_dialog_content = "A maneira como você está fazendo isso é extremamente ineficiente e tem uma grande chance de incorrer em baixas.",
  ui_story_1016_10160501_35_dialog_content = "Se a notícia dessa manobra desastrada se espalhar, você será motivo de chacota em toda a cidade.",
  ui_story_1016_10160501_36_dialog_content = "Lição aprendida, senhor.",
  ui_story_1016_10160501_37_dialog_content = "[Error null-The operation has timed out]",
  ui_story_1016_10160501_38_dialog_content = "(Por que ele está andando com alguém que é claramente de Lumopolis?)",
  ui_story_1016_10160501_39_dialog_content = "Quantas tropas estão de prontidão nesta área?",
  ui_story_1016_10160501_40_dialog_content = "Coloque-me no comando e eu cuidarei da ofensiva.",
  ui_story_1016_10160501_41_dialog_content = "Mas senhor, isso...",
  ui_story_1016_10160501_42_dialog_content = "Não importa se segue ou não o protocolo! Não há tempo a perder!",
  ui_story_1016_10160501_43_dialog_content = "Sim, senhor!",
  ui_story_1016_10160501_44_dialog_content = "Notifique todas as tropas próximas para se espalharem de cada interseção em um raio de cinco quarteirões.",
  ui_story_1016_10160501_45_dialog_content = "Desaceleraremos nossa perseguição enquanto eles entram em formação.",
  ui_story_1016_10160501_46_dialog_content = "Lembre-se, nem todas as batalhas podem ser vencidas apenas com força bruta.",
  ui_story_1016_10160501_47_dialog_content = "Um pescador não entra na água para pegar um peixe, mas para persegui-lo em sua rede.",
  ui_story_1016_10160502_1_dialog_content = "Um pequeno grupo de Eclipsites? Mas de onde eles vieram?",
  ui_story_1016_10160502_2_dialog_content = "Ainda não sabemos, senhora. Já designamos alguém para investigar o assunto.",
  ui_story_1016_10160502_3_dialog_content = "Mas considerando o momento de sua aparição, eles poderiam ter algo a ver com Forsakin? Ela ainda está escondida em algum lugar da cidade.",
  ui_story_1016_10160502_4_dialog_content = "Claro que eles estão ligados a ela de alguma forma. O verdadeiro mistério é como ela conseguiu fazer isso em primeiro lugar.",
  ui_story_1016_10160502_5_dialog_content = "Aumentamos o escopo e a frequência de nossas patrulhas nos últimos dias.",
  ui_story_1016_10160502_6_dialog_content = "E ainda não encontramos nenhum sinal de Forsakin.",
  ui_story_1016_10160502_7_dialog_content = "Talvez... Talvez ela tenha se tornado muito mais hábil em esconder seus movimentos?",
  ui_story_1016_10160502_8_dialog_content = "É possível, mas algo me diz que não é tão simples assim.",
  ui_story_1016_10160502_9_dialog_content = "Ultimamente, tenho sentido algo errado aqui na cidade de Gannon...",
  ui_story_1016_10160502_10_dialog_content = "Capitão! Acabamos de receber notícias da frente de batalha!",
  ui_story_1016_10160502_11_dialog_content = "Todas as unidades próximas estão organizando um cerco aos inimigos!",
  ui_story_1016_10160502_12_dialog_content = "Cerco? Onde eles estão e quantos deles foram implantados?",
  ui_story_1016_10160502_13_dialog_content = "Eu nunca dei tal ordem! Quem está aí comandando minhas tropas?!",
  ui_story_1016_10160502_14_dialog_content = "Eles não disseram, senhora...",
  ui_story_1016_10160502_15_dialog_content = "Então vá descobrir!",
  ui_story_1016_10160502_16_dialog_content = "Eu ainda sou o general por aqui! Ninguém deveria estar dando ordens além de mim!",
  ui_story_1016_10160502_17_dialog_content = "Uma nova mensagem acaba de ser recebida, capitão!",
  ui_story_1016_10160502_18_dialog_content = "O pequeno grupo de Eclipsites que se infiltrou na cidade de Gannon foi exterminado!",
  ui_story_1016_10160502_19_dialog_content = "<size=50>O quê?!</size>",
  ui_story_1016_10160502_20_dialog_content = "Todos eles? Tem certeza?",
  ui_story_1016_10160502_21_dialog_content = "Sim, senhora. Nenhum sinal de atividade Eclipsita foi detectado nas proximidades.",
  ui_story_1016_10160502_22_dialog_content = "Em tão pouco tempo...",
  ui_story_1016_10160502_23_dialog_content = "Hehe. Que interessante.",
  ui_story_1016_10160502_24_dialog_content = "Eu gostaria de saber a quem devo agradecer por tudo isso?",
  ui_story_1016_10160502_25_dialog_content = "Tudo bem, acho que terminamos aqui.",
  ui_story_1016_10160502_26_dialog_content = "Temos outro lugar para estar agora, então vamos deixar a limpeza para você e suas tropas.",
  ui_story_1016_10160502_27_dialog_content = "Ah, e é melhor você não contar a seus superiores sobre eu ter assumido o comando hoje.",
  ui_story_1016_10160502_28_dialog_content = "Acho que pouparemos muitos problemas a todos se guardarmos isso para nós mesmos...",
  ui_story_1016_10160502_29_dialog_content = "Guardar para vocês? Mas todo mundo merece saber quem salvou nossa cidade dos Eclipsites, não acham?",
  ui_story_1016_10160502_30_dialog_content = "Eu estava até planejando fazer medalhas para você e tudo mais!",
  ui_story_1016_10160502_31_dialog_content = "Instrutor Wrath...",
  ui_story_1016_10160502_32_dialog_content = "Não estamos mais na sala de aula, então não precisa me chamar assim. Aqui fora, somos todos soldados.",
  ui_story_1016_10160502_33_dialog_content = "Por favor, perdoe-me por assumir o comando de suas tropas.",
  ui_story_1016_10160502_34_dialog_content = "Aceito qualquer punição que você achar conveniente dispensar.",
  ui_story_1016_10160502_35_dialog_content = "Hmm... Acho que umas boas medalhas seriam melhores do que algum castigo.",
  ui_story_1016_10160502_36_dialog_content = "Vamos deixar esse assunto de lado por enquanto.",
  ui_story_1016_10160502_37_dialog_content = "Você não apenas nos ajudou em nosso momento de necessidade, mas também resolveu o problema com notável rapidez e eficiência. Isso é digno de elogio, não importa como você o corte.",
  ui_story_1016_10160502_38_dialog_content = "E não sou do tipo que pune bens louváveis.",
  ui_story_1016_10160502_39_dialog_content = "Obrigado, Comandante.",
  ui_story_1016_10160502_40_dialog_content = "Sua experiência em combate e velocidade de execução são altamente louváveis.",
  ui_story_1016_10160502_41_dialog_content = "Acho que ninguém mais poderia ter lidado com essa crise com mais perfeição do que você.",
  ui_story_1016_10160502_42_dialog_content = "Suas capacidades são sem dúvida o produto de suas constantes batalhas na linha de frente.",
  ui_story_1016_10160502_43_dialog_content = "Além disso, suas experiências também incutiram um senso de praticidade em suas táticas.",
  ui_story_1016_10160502_44_dialog_content = "Como tal, não me ofendo seriamente com sua maneira de pensar. Esse tipo de determinação é absolutamente necessário no campo de batalha.",
  ui_story_1016_10160502_45_dialog_content = "Mas aqui na cidade de Gannon, nossas regras e instituições têm precedência muito maior.",
  ui_story_1016_10160502_46_dialog_content = "Levei muito tempo para aprender isso e espero que você também faça o mesmo.",
  ui_story_1016_10160502_47_dialog_content = "Regras e instituições...",
  ui_story_1016_10160502_48_dialog_content = "São eles que mantêm o sistema estável, certo?",
  ui_story_1016_10160502_49_dialog_content = "Isso mesmo. Estabilidade é tudo.",
  ui_story_1016_10160502_50_dialog_content = "Não podemos nos dar ao luxo de ser subjugados por forças externas ou conflitos internos.",
  ui_story_1016_10160502_51_dialog_content = "Para preservar essa estabilidade, às vezes não temos escolha a não ser sacrificar parte de nossas vitórias.",
  ui_story_1016_10160502_52_dialog_content = "Saquei. Agora entendi.",
  ui_story_1016_10160502_53_dialog_content = "Obrigado, instrutor.",
  ui_story_1016_10160502_54_dialog_content = "Isso ficará ainda mais claro, caso você deixe as fronteiras.",
  ui_story_1016_10160502_55_dialog_content = "É tudo por agora.",
  ui_story_1016_10160502_56_dialog_content = "Vou dar aula amanhã, então não se atrase.",
  ui_story_1016_10160502_57_dialog_content = "Sim, senhora!",
  ui_story_1016_10160502_58_dialog_content = "... Mas e se esse sistema for distorcido para começar, senhora?",
  ui_story_1016_10160502_59_dialog_content = "Como é?",
  ui_story_1016_10160502_60_dialog_content = "Uma estrutura construída sobre uma fundação desigual está fadada ao colapso mais cedo ou mais tarde, independentemente de quantas regras e instituições a sustentem.",
  ui_story_1016_10160502_61_dialog_content = "Se for esse o caso, quaisquer sacrifícios que fizermos por ela serão em vão.",
  ui_story_1016_10160502_62_dialog_content = "Eu vejo. Então você está insatisfeito com a estrutura atual, imagino?",
  ui_story_1016_10160502_63_dialog_content = "Perdoe-me se pareço rude, mas você sabe por que estamos participando deste Exercício Militar Conjunto?",
  ui_story_1016_10160502_64_dialog_content = "Agora mesmo, na Zona Escura nos confins de nossas terras, os Eclipsites estão se reunindo em massa.",
  ui_story_1016_10160502_65_dialog_content = "Eles estão preparados para atacar nossas defesas a qualquer momento.",
  ui_story_1016_10160502_66_dialog_content = "Mas nossos pedidos de socorro só são recebidos com silêncio.",
  ui_story_1016_10160502_67_dialog_content = "Diga-nos, Comandante, nossa defesa de Crepúsculo é algo necessário para a estabilidade do sistema?",
  ui_story_1016_10160502_68_dialog_content = "Ou é apenas mais um sacrifício no grande esquema das coisas?",
  ui_story_1016_10160502_69_dialog_content = "... Há quanto tempo isso acontece nas fronteiras?",
  ui_story_1016_10160502_70_dialog_content = "Parece que eu estava certo: você não sabia de nada, afinal.",
  ui_story_1016_10160502_71_dialog_content = "O que significa que os outros comandantes também não sabem.",
  ui_story_1016_10160502_72_dialog_content = "Desculpe se falei demais.",
  ui_story_1016_10160502_73_dialog_content = "...",
  ui_story_1016_10160502_74_dialog_content = "Você deveria voltar para o quartel.",
  ui_story_1016_10160502_75_dialog_content = "Vou investigar tudo o que você me disse agora.",
  ui_story_1016_10160502_76_dialog_content = "Entendi.",
  ui_story_1016_10160502_77_dialog_content = "(Como pude ignorar completamente algo tão urgente?)",
  ui_story_1016_10160502_78_dialog_content = "(Qual é o significado disto, Reinhardt?)",
  ui_story_1016_10160502_79_dialog_content = "(Ou será que isso também está fora de seu controle...?)",
  ui_story_1016_10160502_80_dialog_content = "Negador.",
  ui_story_1016_10160502_81_dialog_content = "Negador!",
  ui_story_1016_10160502_82_dialog_content = "... Desculpe, eu estava distraído agora.",
  ui_story_1016_10160502_83_dialog_content = "É ruim...?",
  ui_story_1016_10160502_84_dialog_content = "Você parece... muito pálida.",
  ui_story_1016_10160502_85_dialog_content = "Todos os Eclipsites que eu coloquei na cidade de Gannon foram eliminados.",
  ui_story_1016_10160502_86_dialog_content = "O comandante não me deu tempo de reagir... Seja quem for, deve ser poderoso.",
  ui_story_1016_10160502_87_dialog_content = "Isso significa... Estamos sem opções?",
  ui_story_1016_10160502_88_dialog_content = "Até que o Wraith apareça, esse parece ser o caso.",
  ui_story_1016_10160502_89_dialog_content = "Eu não gosto de colocar todas as nossas apostas neles.",
  ui_story_1016_10160502_90_dialog_content = "Não é uma aposta, é uma troca.",
  ui_story_1016_10160502_91_dialog_content = "A pesquisa que tenho em mãos é suficiente para salvar nossas vidas.",
  ui_story_1016_10160601_1_dialog_content = "<color=#e8d9bb>Vários dias depois, perto do final da fase de aprendizado da lição</color>",
  ui_story_1016_10160601_2_dialog_content = "Bem? Onde estamos na classificação agora?!",
  ui_story_1016_10160601_3_dialog_content = "Deixe-me ver-",
  ui_story_1016_10160601_4_dialog_content = "Segundo lugar! Chegamos ao segundo lugar!",
  ui_story_1016_10160601_5_dialog_content = "Incrível!!! Nós realmente conseguimos!",
  ui_story_1016_10160601_6_dialog_content = "<color=#e8d9bb>Anel-</color>",
  ui_story_1016_10160601_7_dialog_content = "Vamos encontrar nossos lugares. Devemos estar em nosso melhor comportamento hoje.",
  ui_story_1016_10160601_8_dialog_content = "Você tem razão. Afinal, é a última aula da fase.",
  ui_story_1016_10160601_9_dialog_content = "Bom dia, todos os participantes do exercício!",
  ui_story_1016_10160601_10_dialog_content = "Como é do conhecimento de todos, a aula de hoje é a última da fase de aprendizagem do Exercício Conjunto Militar.",
  ui_story_1016_10160601_11_dialog_content = "Depois de hoje, você começará os preparativos de combate para a fase de avaliação e competirá para determinar o campeão final.",
  ui_story_1016_10160601_12_dialog_content = "Os créditos que você acumulou ao longo da fase de aprendizado também fornecerão suporte nas próximas batalhas.",
  ui_story_1016_10160601_13_dialog_content = "Por favor, dirija sua atenção para as classificações na parede para ver onde sua equipe está.",
  ui_story_1016_10160601_14_dialog_content = "Em primeiro lugar, e por larga margem, está a Equipe Leo.",
  ui_story_1016_10160601_15_dialog_content = "Obrigado, obrigado!",
  ui_story_1016_10160601_16_dialog_content = "Puxando para o segundo lugar na décima primeira hora está a equipe PlayerName!",
  ui_story_1016_10160601_17_dialog_content = "Também não foi fácil fazer isso...",
  ui_story_1016_10160601_18_dialog_content = "Equipe Yingel, com seu desempenho consistente, garante o terceiro lugar!",
  ui_story_1016_10160601_19_dialog_content = "Obrigado.",
  ui_story_1016_10160601_20_dialog_content = "Quanto ao restante da classificação, você pode conferir por si mesmo mais tarde.",
  ui_story_1016_10160601_21_dialog_content = "Voltando ao tópico de sua lição final, o comitê organizador gostaria que todos se aquecessem antes do início da fase de avaliação.",
  ui_story_1016_10160601_22_dialog_content = "Como tal, a aula de hoje se concentrará no combate.",
  ui_story_1016_10160601_23_dialog_content = "Combate? Será diferente da última aula de combate que tivemos?",
  ui_story_1016_10160601_24_dialog_content = "Será, pois você estará enfrentando um adversário diferente.",
  ui_story_1016_10160601_25_dialog_content = "A segurança foi a principal prioridade em todas as suas aulas anteriores. Em nenhum momento você esteve em perigo real.",
  ui_story_1016_10160601_26_dialog_content = "Quer fosse contra soldados treinados ou inimigos simulados, suas aulas de combate não tinham como infligir danos reais a você.",
  ui_story_1016_10160601_27_dialog_content = "Na fase de avaliação, porém, ninguém poderá garantir a sua segurança.",
  ui_story_1016_10160601_28_dialog_content = "Por isso, gostaria de saber se estão todos preparados para enfrentar verdadeiros Eclipsites.",
  ui_story_1016_10160601_29_dialog_content = "Eclipses reais? Na sala de aula?",
  ui_story_1016_10160601_30_dialog_content = "O Departamento de Pesquisa Biológica da Illumina teve a gentileza de nos fornecer alguns valiosos espécimes de treinamento.",
  ui_story_1016_10160601_31_dialog_content = "Por favor, preparem-se para a batalha, todos!",
  ui_story_1016_10160601_32_dialog_content = "<color=#e8d9bb>Wham-!!!</color>",
  ui_story_1016_10160601_33_dialog_content = "Uau! Eu não sabia que haveria tantos Eclipsites!",
  ui_story_1016_10160601_34_dialog_content = "A Illumina tem conduzido pesquisas sobre todos eles? Que empreendimento ousado...",
  ui_story_1016_10160601_35_dialog_content = "Conhecer seu oponente é de extrema importância na guerra.",
  ui_story_1016_10160601_36_dialog_content = "Você sabe o que nos custou para garantir tantos espécimes de pesquisa valiosos? A vida de incontáveis soldados, Srta. Beretta.",
  ui_story_1016_10160601_37_dialog_content = "Mas...",
  ui_story_1016_10160601_38_dialog_content = "Não se preocupe. Esses eclipsitos estão sob nosso controle.",
  ui_story_1016_10160601_39_dialog_content = "Agora, pessoal! Não há regras ou restrições adicionais para sua aula final.",
  ui_story_1016_10160601_40_dialog_content = "Por favor, use todo e qualquer método à sua disposição para eliminar seus oponentes!",
  ui_story_1016_10160601_41_dialog_content = "<anim type=Shake><size=50>Graaaaah!!!</size></anim>",
  ui_story_1016_10160601_42_dialog_content = "A-vamos começar agora?!",
  ui_story_1016_10160601_43_dialog_content = "ainda não estou pronta...",
  ui_story_1016_10160601_44_dialog_content = "Cuidadoso, PlayerName.",
  ui_story_1016_10160601_45_dialog_content = "S-Desculpe! Eu não estava prestando atenção!",
  ui_story_1016_10160601_46_dialog_content = "Fique de olho nas outras equipes durante a batalha.",
  ui_story_1016_10160601_47_dialog_content = "Esta é uma boa oportunidade para darmos uma olhada em suas capacidades reais de combate.",
  ui_story_1016_10160601_48_dialog_content = "Faça o seu melhor para ficar fora da luta, Axelia.",
  ui_story_1016_10160601_49_dialog_content = "Deixe tudo para Anatoli e eu.",
  ui_story_1016_10160601_50_dialog_content = "Tudo bem?",
  ui_story_1016_10160601_51_dialog_content = "Ainda é apenas uma aula. Tenho certeza de que não corremos muito perigo.",
  ui_story_1016_10160601_52_dialog_content = "As outras equipes também estão presentes.",
  ui_story_1016_10160601_53_dialog_content = "Você diz isso, mas...",
  ui_story_1016_10160601_54_dialog_content = "Eles também não parecem estar lutando com força total.",
  ui_story_1016_10160601_55_dialog_content = "Cubra meu flanco esquerdo, Uriah!",
  ui_story_1016_10160601_56_dialog_content = "Entendido!",
  ui_story_1016_10160601_57_dialog_content = "Não é bom! Estamos cercados por todos os lados...",
  ui_story_1016_10160601_58_dialog_content = "Chloe!",
  ui_story_1016_10160601_59_dialog_content = "Estou um pouco ocupado agora!",
  ui_story_1016_10160601_60_dialog_content = "O que está acontecendo? Parece que estamos lutando sozinhos!",
  ui_story_1016_10160601_61_dialog_content = "Como acabamos na vanguarda da batalha?",
  ui_story_1016_10160601_62_dialog_content = "Acho que é porque estão todos recuando...",
  ui_story_1016_10160601_63_dialog_content = "O quê?!",
  ui_story_1016_10160601_64_dialog_content = "Mas todos eles foram classificados tão acima de nós! Como eles poderiam fugir quando a verdadeira luta começa?!",
  ui_story_1016_10160601_65_dialog_content = "Nós também estamos ocupados, sabe?",
  ui_story_1016_10160601_66_dialog_content = "O que você está falando?! Você nem desembainhou sua espada!",
  ui_story_1016_10160601_67_dialog_content = "Parece que todos estão se segurando...",
  ui_story_1016_10160601_68_dialog_content = "Faz sentido. Todo mundo está tentando manter seu verdadeiro poder escondido até a fase de avaliação.",
  ui_story_1016_10160601_69_dialog_content = "Mas nesse ritmo, não teremos como vencer todos esses Eclipsites...",
  ui_story_1016_10160601_70_dialog_content = "Se ninguém quer lutar com força total, então todos devemos trabalhar juntos!",
  ui_story_1016_10160601_71_dialog_content = "O inimigo não é muito poderoso, então se cada um der um pouco, poderemos vencer sem problemas!",
  ui_story_1016_10160601_72_dialog_content = "Oh? Vale a pena tentar, suponho.",
  ui_story_1016_10160601_73_dialog_content = "Eu não me importaria de lutar ao lado de pessoas de outras facções!",
  ui_story_1016_10160601_74_dialog_content = "Acordado. Se não há mais nada para competir em nossa classe final, vamos apenas trabalhar juntos e acabar com isso.",
  ui_story_1016_10160601_75_dialog_content = "Nós também concordamos! Agora, por favor, ajude-nos!",
  ui_story_1016_10160601_76_dialog_content = "Parece divertido! Conte comigo!",
  ui_story_1016_10160601_77_dialog_content = "Tudo bem! Vamos combinar nossas forças para a vitória, pessoal!",
  ui_story_1016_10160601_78_dialog_content = "Primeiro, precisamos empurrar o inimigo para trás e tirar o time de Beretta do perigo!",
  ui_story_1016_10160602_1_dialog_content = "Excelente! Todos os Eclipsites foram exterminados!",
  ui_story_1016_10160602_2_dialog_content = "Parabéns a todos pela conclusão da aula final, bem como pela fase de aprendizado do Exercício Militar Conjunto.",
  ui_story_1016_10160602_3_dialog_content = "Esperávamos que a competição fosse muito mais intensa, mas em uma reviravolta surpreendente, as equipes decidiram trabalhar juntas e eliminar seus adversários!",
  ui_story_1016_10160602_4_dialog_content = "Bem, não é como se fosse pela bondade do coração de todos, haha.",
  ui_story_1016_10160602_5_dialog_content = "E com isso, a fase de aprendizado está oficialmente encerrada! Antes de prosseguirmos, permita-me apresentar brevemente as próximas avaliações.",
  ui_story_1016_10160602_6_dialog_content = "Tenho certeza que muitos de vocês estão ansiosos para saber mais sobre isso, certo?",
  ui_story_1016_10160602_7_dialog_content = "A fase de avaliação para este Exercício Militar Conjunto acontecerá em uma Cidade Baixa abandonada.",
  ui_story_1016_10160602_8_dialog_content = "Localizado perto de nossas linhas defensivas, há muito tempo foi invadido por Eclipsites. A área circundante foi desprovida de vida auroriana por muitos, muitos anos.",
  ui_story_1016_10160602_9_dialog_content = "Seu objetivo é abrir caminho até as profundezas desta Cidade Baixa e recuperar um estandarte que foi plantado lá.",
  ui_story_1016_10160602_10_dialog_content = "As regras para isso são incrivelmente simples: quem recuperar o estandarte será nomeado campeão e terá a chance de duelar com o Grande Marechal.",
  ui_story_1016_10160602_11_dialog_content = "Você pode atingir esse objetivo por qualquer meio necessário. Não existem outras regras ou restrições nesta fase.",
  ui_story_1016_10160602_12_dialog_content = "Haverá alguma garantia para a nossa segurança?",
  ui_story_1016_10160602_13_dialog_content = "É melhor se você não contar com isso.",
  ui_story_1016_10160602_14_dialog_content = "Para trazer à tona todo o potencial de combate de cada participante, a dificuldade e o perigo da fase de avaliação foram aumentados significativamente.",
  ui_story_1016_10160602_15_dialog_content = "Lembre-se, o combate real é muito diferente do treinamento. O sucesso na fase de aprendizagem não se traduz necessariamente em sucesso na fase de avaliação.",
  ui_story_1016_10160602_16_dialog_content = "Durante sua missão, nossos instrutores empregarão uma variedade de métodos para monitorar seu desempenho.",
  ui_story_1016_10160602_17_dialog_content = "Quaisquer ações maliciosas tomadas contra os participantes podem e serão usadas como prova contra você em um tribunal militar.",
  ui_story_1016_10160602_18_dialog_content = "Além disso, não poderemos interferir ou ajudá-lo com nenhum dos perigos que você enfrenta.",
  ui_story_1016_10160602_19_dialog_content = "Com isso em mente, é de seu interesse confiar apenas em si mesmos, não em qualquer suporte que possamos oferecer.",
  ui_story_1016_10160602_20_dialog_content = "Eu vejo. Obrigado por esclarecer.",
  ui_story_1016_10160602_21_dialog_content = "Isso me serve muito bem. Se tivéssemos pessoas prontas para nos salvar, tudo isso seria apenas um grande jogo.",
  ui_story_1016_10160602_22_dialog_content = "Agora é hora de todos se prepararem para a fase de avaliação!",
  ui_story_1016_10160602_23_dialog_content = "No interesse da justiça, você receberá apenas o mínimo necessário de equipamento de combate.",
  ui_story_1016_10160602_24_dialog_content = "Para qualquer suporte além disso, você pode usar seus créditos da fase de aprendizado para comprá-lo.",
  ui_story_1016_10160602_25_dialog_content = "Legal! Podemos finalmente colocar nossos créditos suados em bom uso!",
  ui_story_1016_10160602_26_dialog_content = "Correto! Amanhã, vou guiá-lo a um dos principais centros de pesquisa da Illumina, onde preparamos todos os tipos de itens de suporte para você.",
  ui_story_1016_10160602_27_dialog_content = "Alguns aprimorarão suas capacidades de combate, enquanto outros fornecerão informações cruciais no campo de batalha.",
  ui_story_1016_10160602_28_dialog_content = "Os recursos disponíveis serão determinados pelos créditos que você ganhar.",
  ui_story_1016_10160602_29_dialog_content = "Em outras palavras, aqueles com mais créditos poderão obter ainda mais suporte para a próxima fase.",
  ui_story_1016_10160602_30_dialog_content = "A escolha de aprimorar seus pontos fortes ou compensar suas deficiências depende inteiramente de você.",
  ui_story_1016_10160602_31_dialog_content = "Hmm, o que devemos escolher...?",
  ui_story_1016_10160602_32_dialog_content = "Depois de fazer todos os preparativos necessários, por favor, retorne ao quartel assim que possível. Estaremos reunidos na sala de aula amanhã de manhã para o início da fase de avaliação.",
  ui_story_1016_10160602_33_dialog_content = "Isso é tudo que tenho para hoje. Classe dispensada!",
  ui_story_1016_10160602_34_dialog_content = "<color=#e8d9bb>No dia seguinte</color>",
  ui_story_1016_10160602_35_dialog_content = "Uau! Veja todos esses equipamentos!",
  ui_story_1016_10160602_36_dialog_content = "Rifles e baionetas, granadas e todo tipo de equipamento de proteção...",
  ui_story_1016_10160602_37_dialog_content = "Como devemos escolher?! Eu quero todos eles!",
  ui_story_1016_10160602_38_dialog_content = "Se você olhar tudo de perto, a maioria dessas coisas custa muitos créditos.",
  ui_story_1016_10160602_39_dialog_content = "Embora tenhamos ficado em segundo lugar, ainda estamos bastante limitados em quanto podemos pagar.",
  ui_story_1016_10160602_40_dialog_content = "De fato. Parece que a maioria dessas coisas foram apenas incentivos para melhorarmos na fase anterior. Afinal, os organizadores não querem que dependamos muito de ajuda externa.",
  ui_story_1016_10160602_41_dialog_content = "Devemos escolher o que mais precisamos.",
  ui_story_1016_10160602_42_dialog_content = "Se você me perguntar, tendo PlayerName em nossa equipe nos dá uma vantagem natural quando se trata de coletar informações.",
  ui_story_1016_10160602_43_dialog_content = "Então talvez devêssemos usar nossos créditos para aumentar nossas habilidades de combate?",
  ui_story_1016_10160602_44_dialog_content = "Quando você coloca dessa forma, acho que devemos investir em itens mais defensivos.",
  ui_story_1016_10160602_45_dialog_content = "PlayerName é relativamente indefeso em batalha. Devemos priorizar mantê-lo seguro nas próximas batalhas.",
  ui_story_1016_10160602_46_dialog_content = "Huh? V-Você não precisa gastar tanto comigo, sabe...",
  ui_story_1016_10160602_47_dialog_content = "Eu concordo totalmente com você, Carleen!",
  ui_story_1016_10160602_48_dialog_content = "Venha aqui, PlayerName! Vamos ver se este traje de proteção combina com você!",
  ui_story_1016_10160602_49_dialog_content = "Espere, você quer dizer aqui ?!",
  ui_story_1016_10160602_50_dialog_content = "Oh, acho que está tudo bem, se isso significa que não vou atrasar vocês dois...",
  ui_story_1016_10160602_51_dialog_content = "É tudo um monte de máquinas...",
  ui_story_1016_10160602_52_dialog_content = "Eu realmente não posso ficar animado com essas coisas. Você escolhe, Zhao.",
  ui_story_1016_10160602_53_dialog_content = "Claro. Já pensei muito nisso.",
  ui_story_1016_10160602_54_dialog_content = "O que precisamos mais do que tudo é informação.",
  ui_story_1016_10160602_55_dialog_content = "Se conseguirmos ficar um passo à frente do inimigo, nenhuma batalha será demais para nós.",
  ui_story_1016_10160602_56_dialog_content = "Sim, isso faz sentido. Prefiro não ser pego de surpresa também.",
  ui_story_1016_10160602_57_dialog_content = "Vamos pegar um mapa, assim como este comunicador.",
  ui_story_1016_10160602_58_dialog_content = "Esse comunicador é muito caro, no entanto. Vai nos custar mais da metade dos nossos créditos só para obtê-lo.",
  ui_story_1016_10160602_59_dialog_content = "De acordo com a descrição, este comunicador pode ser usado para entrar em contato com os instrutores a qualquer momento durante a fase de avaliação.",
  ui_story_1016_10160602_60_dialog_content = "Nada mais poderia nos fornecer informações mais úteis.",
  ui_story_1016_10160602_61_dialog_content = "Tudo bem, então. Vamos deixar você dar as ordens neste caso.",
  ui_story_1016_10160602_62_dialog_content = "Feche a porta.",
  ui_story_1016_10160602_63_dialog_content = "Sim, senhor!",
  ui_story_1016_10160602_64_dialog_content = "<color=#e8d9bb>Baque.</color>",
  ui_story_1016_10160602_65_dialog_content = "Você está plenamente consciente de sua missão?",
  ui_story_1016_10160602_66_dialog_content = "Sim. Temos de ganhar o campeonato a todo o custo.",
  ui_story_1016_10160602_67_dialog_content = "Eu já disse aos outros.",
  ui_story_1016_10160602_68_dialog_content = "Eu acredito na sua força combinada, mas você não precisa seguir as regras.",
  ui_story_1016_10160602_69_dialog_content = "Eu preparei alguns suprimentos para você. Você os achará muito mais úteis do que qualquer coisa que seus créditos possam comprar.",
  ui_story_1016_10160602_70_dialog_content = "E não se preocupe, você poderá entrar na fase de avaliação com eles.",
  ui_story_1016_10160602_71_dialog_content = "Para informações, você recebeu um mapa totalmente detalhado que também inclui a localização exata do banner.",
  ui_story_1016_10160602_72_dialog_content = "Você não terá que se atrapalhar no escuro como o resto das equipes com isso. Basta ir direto para o local de destino.",
  ui_story_1016_10160602_73_dialog_content = "Naquele armário ali, você encontrará vários equipamentos de aprimoramento de combate. Pegue o que precisar.",
  ui_story_1016_10160602_74_dialog_content = "(O que precisamos? Mesmo um desses itens custa os créditos de uma equipe inteira...)",
  ui_story_1016_10160602_75_dialog_content = "(Os superiores ficarão indignados se formos pegos trapaceando de forma tão descarada.)",
  ui_story_1016_10160602_76_dialog_content = "(O Comitê precisa tanto do campeão?)",
  ui_story_1016_10160602_77_dialog_content = "É tudo por agora. Deixo o resto em suas mãos.",
  ui_story_1016_10160602_78_dialog_content = "Não conte a ninguém sobre nosso encontro de hoje.",
  ui_story_1016_10160602_79_dialog_content = "<color=#e8d9bb>Baque.</color>",
  ui_story_1016_10160602_80_dialog_content = "Eu tenho os cubos. Eu não preciso de mais nada.",
  ui_story_1016_10160602_81_dialog_content = "Também não preciso de nenhum equipamento adicional. Faça sua escolha, Anatoli.",
  ui_story_1016_10160602_82_dialog_content = "Eu?",
  ui_story_1016_10160602_83_dialog_content = "Dar a uma pessoa todo esse equipamento deve aumentar nossas chances de sucesso.",
  ui_story_1016_10160602_84_dialog_content = "... Multar. Farei o que me disseram.",
  ui_story_1016_10160602_85_dialog_content = "Estamos todos apenas fazendo o que nos é dito, Anatoli.",
  ui_story_1016_10160602_86_dialog_content = "Depois de lidar com o Comitê por tanto tempo, vocês dois já devem estar acostumados com esse tipo de ordem, certo?",
  ui_story_1016_10160602_87_dialog_content = "Você tem algo a dizer?",
  ui_story_1016_10160602_88_dialog_content = "Não. Eu só estava perguntando.",
  ui_story_1016_10160602_89_dialog_content = "Como Oficial de Inteligência, você deve tentar evitar fazer perguntas de forma tão descuidada.",
  ui_story_1016_10160602_90_dialog_content = "Quanto a fazer o que me mandam, sim, há muito me acostumei. Ordens são primordiais, não importa o que elas impliquem.",
  ui_story_1016_10160602_91_dialog_content = "Eu sei...",
  ui_story_1016_10160602_92_dialog_content = "No entanto, isso não significa que eu concorde com minhas ordens o tempo todo.",
  ui_story_1016_10160602_93_dialog_content = "Quando isso acontece, escolho esconder minha discordância por trás de minhas ações.",
  ui_story_1016_10160701_1_dialog_content = "<color=#e8d9bb>Honk, honk—</color>",
  ui_story_1016_10160701_2_dialog_content = "Tudo bem, todos para fora! Chegamos ao nosso destino!",
  ui_story_1016_10160701_3_dialog_content = "Aquela Cidade Baixa de aparência decrépita à frente é onde a fase de avaliação acontecerá!",
  ui_story_1016_10160701_4_dialog_content = "Nossos soldados agora irão escoltar cada equipe para um ponto de partida diferente na Cidade Baixa.",
  ui_story_1016_10160701_5_dialog_content = "Vejamos, esqueço-me de alguma coisa...?",
  ui_story_1016_10160701_6_dialog_content = "Oh, certo! Tenha muito cuidado lá fora! Você pode lutar um contra o outro, mas sem golpes mortais!",
  ui_story_1016_10160701_7_dialog_content = "Estarei observando das sombras cada passo do caminho, ouviu?",
  ui_story_1016_10160701_8_dialog_content = "Oh, você está me dando calafrios...",
  ui_story_1016_10160701_9_dialog_content = "Leve-os aos seus pontos de partida, soldados!",
  ui_story_1016_10160701_10_dialog_content = "Tenho grandes esperanças em todos vocês!",
  ui_story_1016_10160701_11_dialog_content = "Vamos garantir que nosso equipamento esteja em ordem.",
  ui_story_1016_10160701_12_dialog_content = "Sim! Parece bom para mim!",
  ui_story_1016_10160701_13_dialog_content = "Estamos armados até os dentes, então é melhor esses eclipsitas tomarem cuidado!",
  ui_story_1016_10160701_14_dialog_content = "Vamos nos ater ao plano que discutimos anteriormente.",
  ui_story_1016_10160701_15_dialog_content = "As outras equipes definitivamente compraram mapas e outros itens de coleta de informações. Tudo o que precisamos fazer é usar PlayerNamehabilidades psíquicas de seguir um deles para o Undercity.",
  ui_story_1016_10160701_16_dialog_content = "Entendido. Já estou procurando as outras equipes.",
  ui_story_1016_10160701_17_dialog_content = "Mas parece que eles ainda estão fora de alcance. Nossos pontos de partida devem estar muito distantes.",
  ui_story_1016_10160701_18_dialog_content = "Ficaremos bem assim que nos aprofundarmos na cidade.",
  ui_story_1016_10160701_19_dialog_content = "O que em nome de Truth você comprou, Minch...?",
  ui_story_1016_10160701_20_dialog_content = "Muito legal, hein? Confira o que acontece quando eu lanço esta granada de flash—",
  ui_story_1016_10160701_21_dialog_content = "<size=50>Uau!</size>",
  ui_story_1016_10160701_22_dialog_content = "O que é? Já estamos sob ataque?",
  ui_story_1016_10160701_23_dialog_content = "Nah, Merry estava apenas brincando.",
  ui_story_1016_10160701_24_dialog_content = "Oh, você está chorando de novo?",
  ui_story_1016_10160701_25_dialog_content = "Claro que não! Meus olhos ardem muito mal...",
  ui_story_1016_10160701_26_dialog_content = "Qual era o sentido de gastar nossos créditos nisso, Minch?",
  ui_story_1016_10160701_27_dialog_content = "Para me divertir! Duh!",
  ui_story_1016_10160701_28_dialog_content = "Veja, não tínhamos crédito suficiente para comprar nada útil.",
  ui_story_1016_10160701_29_dialog_content = "Então pensei comigo mesmo: \"Por que não me divertir um pouco?\"",
  ui_story_1016_10160701_30_dialog_content = "Acho que isso faz sentido...",
  ui_story_1016_10160701_31_dialog_content = "Afinal, não estamos aqui para ganhar o campeonato.",
  ui_story_1016_10160701_32_dialog_content = "Isso só tornaria as coisas mais problemáticas se ganhássemos, considerando que o campeão tem que anexar a bandeira de sua própria facção ao estandarte.",
  ui_story_1016_10160701_33_dialog_content = "De qual facção dissemos que éramos, de novo?",
  ui_story_1016_10160701_34_dialog_content = "Umbraton, embora eu nunca tenha estado lá.",
  ui_story_1016_10160701_35_dialog_content = "Eca, sério? A bandeira de Umbraton parece tão feia.",
  ui_story_1016_10160701_36_dialog_content = "Além disso, o campeão enfrenta isso Reinhardt, certo? Bem, conte comigo!",
  ui_story_1016_10160701_37_dialog_content = "Não seria você quem lutaria com ela, Minch. Afinal, Dysis é o capitão do nosso time.",
  ui_story_1016_10160701_38_dialog_content = "Também não tenho interesse em lutar com ela. Ela não passa de uma heroína sem sentido sustentada por um sistema igualmente sem sentido.",
  ui_story_1016_10160701_39_dialog_content = "Nossos esforços seriam mais bem gastos nos participantes.",
  ui_story_1016_10160701_40_dialog_content = "Não se esqueça por que viemos aqui em primeiro lugar.",
  ui_story_1016_10160701_41_dialog_content = "Mataria você parar de ser tão pedante o tempo todo, Dysis?",
  ui_story_1016_10160701_42_dialog_content = "Vamos lá, vamos nos divertir enquanto ainda podemos!",
  ui_story_1016_10160701_43_dialog_content = "Os outros times estão praticamente esperando a gente mexer com eles!",
  ui_story_1016_10160701_44_dialog_content = "Achei um time!",
  ui_story_1016_10160701_45_dialog_content = "Realmente? Quem?",
  ui_story_1016_10160701_46_dialog_content = "É aquele grupo de excêntricos de Umbraton.",
  ui_story_1016_10160701_47_dialog_content = "Acho que o nome do capitão é Dysis ou algo assim?",
  ui_story_1016_10160701_48_dialog_content = "Ah, eu me lembro deles! Dysis, Minch e Merry!",
  ui_story_1016_10160701_49_dialog_content = "Se você perguntar, eles não me parecem pessoas que seguem as regras.",
  ui_story_1016_10160701_50_dialog_content = "Eles estão indo direto para a Cidade Baixa, e rápido.",
  ui_story_1016_10160701_51_dialog_content = "A julgar por seus movimentos, acho que eles podem estar no caminho certo!",
  ui_story_1016_10160701_52_dialog_content = "Concordo. Eles devem ter um objetivo claro se estão se movendo tão rapidamente.",
  ui_story_1016_10160701_53_dialog_content = "Devemos alcançá-los imediatamente.",
  ui_story_1016_10160701_54_dialog_content = "Não precisaremos. Eles estarão passando por nossa localização em breve.",
  ui_story_1016_10160701_55_dialog_content = "Ei, acho que já consigo ouvi-los...",
  ui_story_1016_10160701_56_dialog_content = "Yoo-hoo! Pegue-nos se você puder!",
  ui_story_1016_10160701_57_dialog_content = "Calma, Minch...",
  ui_story_1016_10160701_58_dialog_content = "Espere, algo não está certo!",
  ui_story_1016_10160701_59_dialog_content = "Eles estão sendo perseguidos por um monte de Eclipsites!",
  ui_story_1016_10160701_60_dialog_content = "O quê?!",
  ui_story_1016_10160701_61_dialog_content = "Eles aparentemente conseguiram provocar todos os Eclipsites na área com seus movimentos imprudentes.",
  ui_story_1016_10160701_62_dialog_content = "Não só isso... parece que aqueles três também não têm intenção de lutar contra eles.",
  ui_story_1016_10160701_63_dialog_content = "Eles estão apenas conduzindo os Eclipsites pelo nariz!",
  ui_story_1016_10160701_64_dialog_content = "O que eles estão fazendo? Eles não sabem que isso não é mais um jogo?",
  ui_story_1016_10160701_65_dialog_content = "Duvido que tenham um objetivo claro em mente. Depressa, vamos embora antes que sejamos pegos na confusão deles.",
  ui_story_1016_10160701_66_dialog_content = "Eu concordo, mas...",
  ui_story_1016_10160701_67_dialog_content = "Eles estão correndo direto para nós agora!",
  ui_story_1016_10160701_68_dialog_content = "Olha, Minch! A equipe do Celestita está logo à frente!",
  ui_story_1016_10160701_69_dialog_content = "O celestita, hein? Aposto que ele é muito divertido! Vamos ver se ele quer jogar!",
  ui_story_1016_10160701_70_dialog_content = "<size=50>Ajuda! Os Eclipsites vão nos comer! Alguém nos ajude!!!</size>",
  ui_story_1016_10160701_71_dialog_content = "É tarde demais, eles nos avistaram...",
  ui_story_1016_10160701_72_dialog_content = "...",
  ui_story_1016_10160701_73_dialog_content = "Disse! Você e sua equipe, ouçam!",
  ui_story_1016_10160701_74_dialog_content = "Você precisa se virar e começar a lutar contra os Eclipsites!",
  ui_story_1016_10160701_75_dialog_content = "Ha? Quem você pensa que é para mandar em mim?!",
  ui_story_1016_10160701_76_dialog_content = "Vire-se e lute, e nos juntaremos a você!",
  ui_story_1016_10160701_77_dialog_content = "Continue correndo em nossa direção e não teremos escolha a não ser tratá-lo como inimigo e atacar!",
  ui_story_1016_10160701_78_dialog_content = "Ataque?!?!",
  ui_story_1016_10160701_79_dialog_content = "Esta é a única maneira de mantermos a vantagem.",
  ui_story_1016_10160701_80_dialog_content = "Ah, não seja tão sério! Eu só queria me divertir um pouco, só isso!",
  ui_story_1016_10160701_81_dialog_content = "Tudo bem, faremos o que você diz e nos uniremos!",
  ui_story_1016_10160701_82_dialog_content = "Merry, vire-se e dê uma surra naqueles Eclipsites que eles não vão esquecer!",
  ui_story_1016_10160701_83_dialog_content = "Com prazer!",
  ui_story_1016_10160701_84_dialog_content = "Eles estão no ataque! Devemos nos juntar a eles também!",
  ui_story_1016_10160701_85_dialog_content = "Certo! Vamos acabar com isso rapidamente!",
  ui_story_1016_10160802_1_dialog_content = "<anim type=Shake>Gah...</anim>",
  ui_story_1016_10160802_2_dialog_content = "Ei! Isso foi bem mais fácil do que eu pensava!",
  ui_story_1016_10160802_3_dialog_content = "Infelizmente, parece que o resto das equipes estão muito à nossa frente agora.",
  ui_story_1016_10160802_4_dialog_content = "Isso fede! Nunca conseguiremos alcançá-los por causa daqueles estúpidos Eclipsites...",
  ui_story_1016_10160802_5_dialog_content = "Talvez seja só eu, mas desde que encontramos aqueles três...",
  ui_story_1016_10160802_6_dialog_content = "Não posso deixar de sentir que fomos enganados!",
  ui_story_1016_10160802_7_dialog_content = "Agora não é hora de reclamar.",
  ui_story_1016_10160802_8_dialog_content = "Nesse ritmo, o campeonato estará completamente fora do nosso alcance em breve.",
  ui_story_1016_10160802_9_dialog_content = "Vamos. Dysis, você e sua equipe fariam bem em nos acompanhar.",
  ui_story_1016_10160802_10_dialog_content = "Ah, obrigado pela preocupação, mas não temos vontade de nos aventurar mais na cidade.",
  ui_story_1016_10160802_11_dialog_content = "Temos assuntos mais importantes para resolver agora.",
  ui_story_1016_10160802_12_dialog_content = "(Algo sobre eles parece muito estranho...)",
  ui_story_1016_10160802_13_dialog_content = "Se for esse o caso, então vamos embora agora. PlayerName, Vice, vamos continuar.",
  ui_story_1016_10160802_14_dialog_content = "Ah, claro.",
  ui_story_1016_10160802_15_dialog_content = "<color=#e8d9bb>Nas profundezas da Zona Escura da Cidade Baixa</color>",
  ui_story_1016_10160802_16_dialog_content = "Algum sinal das outras equipes?",
  ui_story_1016_10160802_17_dialog_content = "Nenhum mesmo. A julgar pela situação, parece que fizemos o maior progresso de todos.",
  ui_story_1016_10160802_18_dialog_content = "Ótimo, ainda estamos na liderança. A fase de avaliação foi muito mais fácil do que eu esperava.",
  ui_story_1016_10160802_19_dialog_content = "Então, novamente, com um cavaleiro, um estrategista e um poderoso mestre Luminatics em nossa equipe...",
  ui_story_1016_10160802_20_dialog_content = "É basicamente impossível perdermos, certo?",
  ui_story_1016_10160802_21_dialog_content = "Heheh, com certeza você está se sentindo humilde hoje, não é?",
  ui_story_1016_10160802_22_dialog_content = "Conseguimos manter a liderança até agora, então vamos acabar com isso o mais rápido possível.",
  ui_story_1016_10160802_23_dialog_content = "Instrutor Gronru—",
  ui_story_1016_10160802_24_dialog_content = "Vá em frente, estou ouvindo.",
  ui_story_1016_10160802_25_dialog_content = "Gostaríamos de gastar nossos créditos restantes para identificar a localização exata de nosso alvo. Você pode fazer isso por nós?",
  ui_story_1016_10160802_26_dialog_content = "Claro que posso, mas vocês não acham que isso é um pouco exagerado?",
  ui_story_1016_10160802_27_dialog_content = "Estamos quase chegando ao fim, então podemos usar todos os recursos à nossa disposição.",
  ui_story_1016_10160802_28_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1016_10160802_29_dialog_content = "Tudo bem, vá em frente e verifique seu mapa. A área destacada é onde você encontrará seu alvo.",
  ui_story_1016_10160802_30_dialog_content = "Já que tudo é um jogo justo de acordo com as regras que lhe demos, não tenho como prendê-lo por trapacear.",
  ui_story_1016_10160802_31_dialog_content = "Na verdade, estou absolutamente emocionado em ver vocês usarem as regras do jogo a seu favor.",
  ui_story_1016_10160802_32_dialog_content = "Então vá em frente e limpe esta fase!",
  ui_story_1016_10160802_33_dialog_content = "Este é o momento que esperávamos.",
  ui_story_1016_10160802_34_dialog_content = "Vamos continuar, enquanto ainda estamos muito à frente dos outros.",
  ui_story_1016_10160802_35_dialog_content = "<color=#e8d9bb>Nas profundezas da Dark Zone da Cidade Baixa, perto do objetivo</color>",
  ui_story_1016_10160802_36_dialog_content = "<anim type=Shake>Graaah...</anim>",
  ui_story_1016_10160802_37_dialog_content = "Tudo bem, esse deve ser o último Eclipsite por perto.",
  ui_story_1016_10160802_38_dialog_content = "Embora você tenha escolhido trilhar o caminho das trevas, rezo para que o Deus da Luz o poupe de seu sofrimento.",
  ui_story_1016_10160802_39_dialog_content = "Ainda acho que você parece muito mais assustador quando fala assim, Joseph...",
  ui_story_1016_10160802_40_dialog_content = "Mesmo que estejamos o mais perto possível do nosso alvo, sua localização exata...",
  ui_story_1016_10160802_41_dialog_content = "... poderia estar em qualquer lugar em uma cidade tão grande!",
  ui_story_1016_10160802_42_dialog_content = "<color=#e8d9bb>Bang, bang—!</color>",
  ui_story_1016_10160802_43_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10160802_44_dialog_content = "Uma emboscada!",
  ui_story_1016_10160802_45_dialog_content = "Isso soa como um trabalho para um oficial de inteligência.",
  ui_story_1016_10160802_46_dialog_content = "Desculpe fazê-lo esperar e obrigado por abrir caminho para nós. Este lugar é perfeito para um confronto final, você não concorda?",
  ui_story_1016_10160802_47_dialog_content = "<size=32>Tch...</size>",
  ui_story_1016_10160802_48_dialog_content = "<size=32>Eles chegaram aqui antes mesmo de nós, Leo.</size>",
  ui_story_1016_10160802_49_dialog_content = "<size=32>É a casa deles, eu deveria ter previsto isso há muito tempo.</size>",
  ui_story_1016_10160802_50_dialog_content = "Bem, desde que eles dispararam o primeiro tiro, é óbvio para que eles estão aqui.",
  ui_story_1016_10160802_51_dialog_content = "Isso nunca foi algo que poderíamos ter evitado. Só pode haver um campeão, afinal.",
  ui_story_1016_10160802_52_dialog_content = "Que bom que você entende. Parece que podemos finalmente começar a levar as coisas a sério agora.",
  ui_story_1016_10160802_53_dialog_content = "Estou pronto para lutar.",
  ui_story_1016_10160901_1_dialog_content = "<color=#e8d9bb>Bang, bang, bang—!</color>",
  ui_story_1016_10160901_2_dialog_content = "Parece que não somos bem-vindos aqui.",
  ui_story_1016_10160901_3_dialog_content = "Eles me prenderam. Atenção, Leo, aquela garota está vindo direto para você.",
  ui_story_1016_10160901_4_dialog_content = "Ainda não acabou.",
  ui_story_1016_10160901_5_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10160901_6_dialog_content = "Leo!",
  ui_story_1016_10160901_7_dialog_content = "Obrigada!",
  ui_story_1016_10160901_8_dialog_content = "Quem diria que uma garotinha poderia dar um soco tão sério, hein?",
  ui_story_1016_10160901_9_dialog_content = "A Federação Illumina tem jovens talentos, com certeza. Não posso dizer que não estou com um pouco de ciúme, honestamente.",
  ui_story_1016_10160901_10_dialog_content = "Cubos.",
  ui_story_1016_10160901_11_dialog_content = "Afe!",
  ui_story_1016_10160901_12_dialog_content = "(Ela sabe exatamente para onde estou tentando me mover. Ela poderia estar nos mantendo separados?)",
  ui_story_1016_10160901_13_dialog_content = "(Agora é a nossa chance.)",
  ui_story_1016_10160901_14_dialog_content = "(Usar esses equipamentos ilícitos deixa um gosto ruim na minha boca.)",
  ui_story_1016_10160901_15_dialog_content = "(Isso é realmente... Como essas pessoas querem que nosso time vença?)",
  ui_story_1016_10160901_16_dialog_content = "(Ainda não tenho informações suficientes. Parece que tenho que descobrir as coisas à medida que avança.)",
  ui_story_1016_10160901_17_dialog_content = "(Começando com isso!)",
  ui_story_1016_10160901_18_dialog_content = "Eu sabia que você viria atrás de mim.",
  ui_story_1016_10160901_19_dialog_content = "<size=45>O quê?!</size>",
  ui_story_1016_10160901_20_dialog_content = "Eu já vi sua estratégia até o fim.",
  ui_story_1016_10160901_21_dialog_content = "Por favor, não subestime nem uma única pessoa de Crepúsculo!",
  ui_story_1016_10160901_22_dialog_content = "Argh!!!",
  ui_story_1016_10160901_23_dialog_content = "(Ele é poderoso!)",
  ui_story_1016_10160901_24_dialog_content = "(Mesmo que eu esteja usando todo esse equipamento, seu ataque ainda conseguiu perfurar minhas defesas...)",
  ui_story_1016_10160901_25_dialog_content = "(Este homem é muito mais poderoso do que minha inteligência indicou!)",
  ui_story_1016_10160901_26_dialog_content = "Perdoe-me, mas eu tenho que derrotá-lo agora.",
  ui_story_1016_10160901_27_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10160901_28_dialog_content = "Yingel! Eu preciso de reforços!",
  ui_story_1016_10160901_29_dialog_content = "O quê?!",
  ui_story_1016_10160901_30_dialog_content = "Anatoli!",
  ui_story_1016_10160901_31_dialog_content = "Agora é a hora errada para perder o foco!",
  ui_story_1016_10160901_32_dialog_content = "—!",
  ui_story_1016_10160901_33_dialog_content = "(Isso não é bom, eles nos colocaram na defensiva agora.)",
  ui_story_1016_10160901_34_dialog_content = "<color=#e8d9bb>Enquanto isso, em algum outro lugar na Cidade Baixa</color>",
  ui_story_1016_10160901_35_dialog_content = "Onde estamos?",
  ui_story_1016_10160901_36_dialog_content = "Não pensei que seguir aquela equipe nos levaria a um lugar como este...",
  ui_story_1016_10160901_37_dialog_content = "Parece um corredor...",
  ui_story_1016_10160901_38_dialog_content = "Mas é óbvio que este lugar está abandonado há muito tempo.",
  ui_story_1016_10160901_39_dialog_content = "Eu sei direito? Não há nada aqui além de poeira e teias de aranha.",
  ui_story_1016_10160901_40_dialog_content = "Parece que algo assustador está prestes a saltar e nos assustar...",
  ui_story_1016_10160901_41_dialog_content = "<anim type=Shake><size=45>Grrr...</size></anim>",
  ui_story_1016_10160901_42_dialog_content = "Este sentimento... Cuidado, pessoal!",
  ui_story_1016_10160901_43_dialog_content = "Algo grande está vindo direto para nós!",
  ui_story_1016_10160901_44_dialog_content = "<anim type=Shake><size=50>Grahhhh—!!!</size></anim>",
  ui_story_1016_10160901_45_dialog_content = "Ah—!",
  ui_story_1016_10160901_46_dialog_content = "I-Isso é uma aranha gigante?!",
  ui_story_1016_10160901_47_dialog_content = "Fique em guarda! Essa coisa parece forte.",
  ui_story_1016_10160901_48_dialog_content = "Vamos terminar isso rapidamente. Ainda temos que encontrar aquele estandarte!",
  ui_story_1016_10160902_1_dialog_content = "<anim type=Shake><size=50>Grahhhh—!!!</size></anim>",
  ui_story_1016_10160902_2_dialog_content = "Atacamos juntos, Vice!",
  ui_story_1016_10160902_3_dialog_content = "Sim!",
  ui_story_1016_10160902_4_dialog_content = "Flor de Gelo—!",
  ui_story_1016_10160902_5_dialog_content = "<anim type=Shake><size=50>Graagh!!!</size></anim>",
  ui_story_1016_10160902_6_dialog_content = "<size=45>Agora!</size>",
  ui_story_1016_10160902_7_dialog_content = "Um tiro é tudo que eu preciso!",
  ui_story_1016_10160902_8_dialog_content = "<anim type=Shake><size=40>Rugido-!</size></anim>",
  ui_story_1016_10160902_9_dialog_content = "Finalmente baixamos...",
  ui_story_1016_10160902_10_dialog_content = "Ufa, eu sei.",
  ui_story_1016_10160902_11_dialog_content = "Essa coisa foi muito difícil!",
  ui_story_1016_10160902_12_dialog_content = "Os Eclipsites que havíamos enfrentado até agora não eram nada comparados a esse grande bug!",
  ui_story_1016_10160902_13_dialog_content = "De fato. Um Eclipsite tão poderoso não deveria estar na fase de avaliação.",
  ui_story_1016_10160902_14_dialog_content = "Isso deveria ser um programa de treinamento. Por que algo tão perigoso espreitava nas sombras aqui?",
  ui_story_1016_10160902_15_dialog_content = "Será que alguém colocou aqui de propósito?",
  ui_story_1016_10160902_16_dialog_content = "Eu não posso dizer com certeza. É possível que tenhamos tido muito azar até agora.",
  ui_story_1016_10160902_17_dialog_content = "Esta Cidade Baixa foi abandonada por anos, então é provável que haja Eclipsites escondidos por todo o lugar.",
  ui_story_1016_10160902_18_dialog_content = "Vamos deixar essa discussão para mais tarde.",
  ui_story_1016_10160902_19_dialog_content = "Já perdemos tempo suficiente.",
  ui_story_1016_10160902_20_dialog_content = "Mais atrasos e perderemos qualquer chance de ganhar.",
  ui_story_1016_10160902_21_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_1016_10160902_22_dialog_content = "O que foi aquele som?!",
  ui_story_1016_10160902_23_dialog_content = "Eclipsitas?",
  ui_story_1016_10160902_24_dialog_content = "Poderia ser mais Eclipsites?",
  ui_story_1016_10160902_25_dialog_content = "Receio que não. Ouça atentamente...",
  ui_story_1016_10160902_26_dialog_content = "<color=#e8d9bb>Boom... Rumble... Bang...</color>",
  ui_story_1016_10160902_27_dialog_content = "Esse é o som de tiros e Luminatics, e não parece que vem de apenas um time.",
  ui_story_1016_10160902_28_dialog_content = "Você tem razão. Quase parece que duas equipes diferentes estão lutando entre si!",
  ui_story_1016_10160902_29_dialog_content = "Nosso objetivo nesta fase é recuperar o estandarte, não lutar entre si. A única razão pela qual eles poderiam estar lutando...",
  ui_story_1016_10160902_30_dialog_content = "É porque eles devem ter encontrado o banner!",
  ui_story_1016_10160902_31_dialog_content = "A bandeira?",
  ui_story_1016_10160902_32_dialog_content = "Você acha que alguém encontrou o banner?",
  ui_story_1016_10160902_33_dialog_content = "É possível. Vamos ouvir com mais atenção.",
  ui_story_1016_10160902_34_dialog_content = "<color=#e8d9bb>Boom... Rumble... Bang...</color>",
  ui_story_1016_10160902_35_dialog_content = "Esse é o som de tiros e Luminatics, e não parece que vem de apenas um time.",
  ui_story_1016_10160902_36_dialog_content = "Será que dois times encontraram a bandeira ao mesmo tempo, e agora estão brigando por ela?!",
  ui_story_1016_10160902_37_dialog_content = "Eu diria que é uma aposta bastante segura!",
  ui_story_1016_10160902_38_dialog_content = "Então precisamos nos apressar antes que a batalha acabe!",
  ui_story_1016_10160902_39_dialog_content = "Concordar!",
  ui_story_1016_10160902_40_dialog_content = "<color=#e8d9bb>Enquanto isso, nas profundezas da Cidade Baixa</color>",
  ui_story_1016_10160902_41_dialog_content = "Alvo bloqueado!",
  ui_story_1016_10160902_42_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_1016_10160902_43_dialog_content = "Você não vai passar por mim!",
  ui_story_1016_10160902_44_dialog_content = "(Eu não pensei que eles seriam tão fortes. Mesmo depois de perder a vantagem, eles ainda nos enfrentam golpe por golpe.)",
  ui_story_1016_10160902_45_dialog_content = "(Especialmente aquele Oficial de Inteligência, Anatoli. Como ele entrou na fase de avaliação com tal equipamento?)",
  ui_story_1016_10160902_46_dialog_content = "(Estive de olho na equipe deles o tempo todo. Apesar de terem muito menos créditos do que nós, eles conseguiram garantir equipamentos ainda melhores.)",
  ui_story_1016_10160902_47_dialog_content = "(Não faz sentido. Pelo contrário, parece que a Illumina está secretamente fornecendo a eles uma vantagem injusta.)",
  ui_story_1016_10160902_48_dialog_content = "(Mas isso não importa mais. A Federação Illumina sabe tudo sobre nossa situação em Crepúsculo, então nossa missão está completa. Tudo o que resta...)",
  ui_story_1016_10160902_49_dialog_content = "Joseph!",
  ui_story_1016_10160902_50_dialog_content = "O que é, Leo?",
  ui_story_1016_10160902_51_dialog_content = "...",
  ui_story_1016_10160902_52_dialog_content = "(Espere, ele quer dizer...?)",
  ui_story_1016_10160902_53_dialog_content = "Entendido.",
  ui_story_1016_10160902_54_dialog_content = "(Seus ataques ficaram mais lentos. Isso é uma armadilha?)",
  ui_story_1016_10160902_55_dialog_content = "(Não, é a oportunidade perfeita para nós!)",
  ui_story_1016_10160902_56_dialog_content = "Yingel!",
  ui_story_1016_10160902_57_dialog_content = "Entendido!",
  ui_story_1016_10160902_58_dialog_content = "Zhao! Afaste-se e prepare-se para defender!",
  ui_story_1016_10160902_59_dialog_content = "Sim!",
  ui_story_1016_10160902_60_dialog_content = "Nós não vamos deixar você!",
  ui_story_1016_10160902_61_dialog_content = "<color=#e8d9bb>Bang, bang, bang—!</color>",
  ui_story_1016_10160902_62_dialog_content = "Droga, ela está cortando nossa rota de fuga!",
  ui_story_1016_10160902_63_dialog_content = "Agora, Axelia!",
  ui_story_1016_10160902_64_dialog_content = "Desculpe o atraso.",
  ui_story_1016_10160902_65_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_1016_10160902_66_dialog_content = "Ugh—!",
  ui_story_1016_10160902_67_dialog_content = "Zhao caiu!",
  ui_story_1016_10160902_68_dialog_content = "Fica perto de mim! Vou usar meus Luminatics para apoiá-lo!",
  ui_story_1016_10160902_69_dialog_content = "Um exercício de futilidade.",
  ui_story_1016_10160902_70_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_1016_10160902_71_dialog_content = "Tosse... Tosse, tosse, tosse!",
  ui_story_1016_10160902_72_dialog_content = "Eu não deveria estar surpreso, mas a arma definitiva de Illumina realmente dá um soco.",
  ui_story_1016_10160902_73_dialog_content = "Parece que não temos mais chance, Leo.",
  ui_story_1016_10160902_74_dialog_content = "Sem brincadeiras. Nós nos rendemos.",
  ui_story_1016_10160902_75_dialog_content = "Uma escolha sábia.",
  ui_story_1016_10160902_76_dialog_content = "Recupere o banner, Axelia.",
  ui_story_1016_10160902_77_dialog_content = "Entendi.",
  ui_story_1016_10160902_78_dialog_content = "E o vencedor é-",
  ui_story_1016_10160902_79_dialog_content = "<size=45>Conseguimos!!!</size>",
  ui_story_1016_10160902_80_dialog_content = "...",
  ui_story_1016_10160902_81_dialog_content = "...",
  ui_story_1016_10160902_82_dialog_content = "...",
  ui_story_1016_10160902_83_dialog_content = ".... Certo?",
  ui_story_1016_10160902_84_dialog_content = "Infelizmente não.",
  ui_story_1016_10160902_85_dialog_content = "Se você tivesse chegado cinco segundos antes, teria a chance de lutar conosco pelo estandarte.",
  ui_story_1016_10160902_86_dialog_content = "Realmente? Afinal, parece que nos atrasamos demais.",
  ui_story_1016_10160902_87_dialog_content = "Como isso pode ser...?",
  ui_story_1016_10160902_88_dialog_content = "Perdemos tanto...",
  ui_story_1016_10160902_89_dialog_content = "É o bastante. Afinal, fizemos o nosso melhor.",
  ui_story_1016_10160902_90_dialog_content = "Agora que o vencedor foi decidido, não adianta lamentar o resultado.",
  ui_story_1016_10160902_91_dialog_content = "Em vez disso, devemos nos esforçar para continuar melhorando.",
  ui_story_1016_10160902_92_dialog_content = "Sim você está certo...",
  ui_story_1016_10160902_93_dialog_content = "Sem mais delongas, permita-me anunciar os resultados.",
  ui_story_1016_10160902_94_dialog_content = "O vencedor da fase de avaliação é—<color=#FFB400>Equipe Yingel</color>!",
  ui_story_1016_10160902_95_dialog_content = "Além disso, o prêmio para o participante de melhor desempenho neste Exercício Militar Conjunto é—Tenente <color=#FFB400>Axelia</color>!",
  ui_story_1016_10160902_96_dialog_content = "Parabéns aos três!",
  ui_story_1016_10160902_97_dialog_content = "Obrigado.",
  ui_story_1016_10160902_98_dialog_content = "(Nossa missão está finalmente completa.)",
  ui_story_1016_10160902_99_dialog_content = "Eu venci.",
  ui_story_1016_10160902_100_dialog_content = "Exatamente como esperado.",
  ui_story_1016_10160902_101_dialog_content = "(Esses dois não parecem nem um pouco surpresos ou entusiasmados com a vitória.)",
  ui_story_1016_10160902_102_dialog_content = "(Sei que não são as pessoas mais expressivas, mas isso parece estranho até para eles.)",
  ui_story_1016_10160902_103_dialog_content = "(Será que tudo isso também faz parte do plano...?)",
  ui_story_1016_10161001_1_dialog_content = "Parabéns, tenente Axelia!",
  ui_story_1016_10161001_2_dialog_content = "Todos na Federação Illumina estão comemorando sua vitória!",
  ui_story_1016_10161001_3_dialog_content = "Eu estava apenas cumprindo minhas obrigações.",
  ui_story_1016_10161001_4_dialog_content = "Fora do caminho, todos vocês—",
  ui_story_1016_10161001_5_dialog_content = "Ela precisa descansar agora.",
  ui_story_1016_10161001_6_dialog_content = "Parece que toda a Illumina está tentando apertar a mão daquela pobre garota agora.",
  ui_story_1016_10161001_7_dialog_content = "Sim ele faz.",
  ui_story_1016_10161001_8_dialog_content = "Agora que acabou, acho que mereço saber a verdade por trás de sua decisão...",
  ui_story_1016_10161001_9_dialog_content = "A razão pela qual você perdeu a luta de bom grado.",
  ui_story_1016_10161001_10_dialog_content = "Porque já cumprimos nosso objetivo.",
  ui_story_1016_10161001_11_dialog_content = "Capitão Wrath tem plena consciência da situação de Twilight agora. Com sua experiência de combate, tenho certeza que ela sabe exatamente o que estamos passando.",
  ui_story_1016_10161001_12_dialog_content = "Esse conhecimento, por sua vez, se espalhará rapidamente pela rede de inteligência da Illumina antes de atingir o alto escalão de Lumopolis.",
  ui_story_1016_10161001_13_dialog_content = "Mesmo que seja esse o caso, ainda acho que tínhamos a obrigação de ganhar o campeonato para nós.",
  ui_story_1016_10161001_14_dialog_content = "Isso teria chamado mais atenção para nós, o que poderia ter sido usado para alavancar mais apoio para Crepúsculo.",
  ui_story_1016_10161001_15_dialog_content = "Com a conjuntura cada vez mais próxima, precisamos de toda a ajuda possível.",
  ui_story_1016_10161001_16_dialog_content = "E ainda assim você escolheu seguir minha decisão de se render.",
  ui_story_1016_10161001_17_dialog_content = "Isso porque confio em seu julgamento. Ainda o faço, na verdade, mas só quero saber o motivo.",
  ui_story_1016_10161001_18_dialog_content = "Porque esta é nossa melhor chance de convencer os outros a nos ajudar.",
  ui_story_1016_10161001_19_dialog_content = "Acho que o time da Illumina tinha alguns truques na manga esse tempo todo.",
  ui_story_1016_10161001_20_dialog_content = "Eu os tenho observado desde o minuto em que começamos o Exercício Militar Conjunto, e muitas coisas sobre eles parecem estranhas.",
  ui_story_1016_10161001_21_dialog_content = "Eles são fortes, sem dúvida, mas parecem menos do que satisfeitos com a vitória.",
  ui_story_1016_10161001_22_dialog_content = "Você está tentando dizer... que eles trapacearam?",
  ui_story_1016_10161001_23_dialog_content = "Não tenho nenhuma prova real, mas tenho certeza disso.",
  ui_story_1016_10161001_24_dialog_content = "O equipamento que eles trouxeram para a batalha final era melhor do que seus créditos podiam pagar.",
  ui_story_1016_10161001_25_dialog_content = "A diferença não foi especialmente perceptível, pelo menos não na superfície, mas definitivamente levou sua força para o próximo nível.",
  ui_story_1016_10161001_26_dialog_content = "Alguém os tem ajudado nos bastidores.",
  ui_story_1016_10161001_27_dialog_content = "Você acha que pode ser os superiores da Illumina?",
  ui_story_1016_10161001_28_dialog_content = "É possível, o que significaria que a vitória deles estava garantida desde o início.",
  ui_story_1016_10161001_29_dialog_content = "Mas não parece que vencer seja o objetivo real. Acho que deve ser outra coisa.",
  ui_story_1016_10161001_30_dialog_content = "Se for, então vencer foi apenas um passo necessário ao longo do caminho...",
  ui_story_1016_10161001_31_dialog_content = "Será que...?",
  ui_story_1016_10161001_32_dialog_content = "Quem sabe?",
  ui_story_1016_10161001_33_dialog_content = "Mas algo me diz que as coisas estão prestes a ficar um pouco agitadas.",
  ui_story_1016_10161001_34_dialog_content = "O que-",
  ui_story_1016_10161001_35_dialog_content = "PlayerName e sua equipe conseguiu anotar todas as surpresas que preparamos para aquela equipe de Crepúsculo...",
  ui_story_1016_10161001_36_dialog_content = "Esses três têm sido um verdadeiro pé no saco! Eles estão tentando arruinar nossos planos ou algo assim?!",
  ui_story_1016_10161001_37_dialog_content = "Pelo que posso dizer, tudo isso foi mera coincidência, mas isso não significa que nossos planos foram frustrados.",
  ui_story_1016_10161001_38_dialog_content = "A equipe de Crepúsculo demonstrou com sucesso sua força, e nossas surpresas resultaram em uma descoberta bastante inesperada.",
  ui_story_1016_10161001_39_dialog_content = "Tenho certeza que nosso mestre ficará feliz em saber sobre todas as pessoas poderosas que encontramos aqui.",
  ui_story_1016_10161001_40_dialog_content = "Além disso, o Caelestita e sua equipe derrotaram a Rainha Aranha muito mais rápido do que havíamos previsto. Isso só pode significar que sua força também melhorou muito.",
  ui_story_1016_10161001_41_dialog_content = "Ainda assim, nossas armadilhas parecem ter custado a eles uma chance de ganhar o campeonato.",
  ui_story_1016_10161001_42_dialog_content = "Eu só espero que eles não fiquem muito chateados conosco...",
  ui_story_1016_10161001_43_dialog_content = "<anim type=Shake>Yaawn—</anim>Estou exausto.",
  ui_story_1016_10161001_44_dialog_content = "Podemos voltar agora? Eu não quero sair da cama por uns três dias depois disso...",
  ui_story_1016_10161001_45_dialog_content = "Seja paciente, Minch.",
  ui_story_1016_10161001_46_dialog_content = "Ainda temos trabalho a fazer. Não podemos voltar ainda.",
  ui_story_1016_10161001_47_dialog_content = "Isso mesmo. Ainda temos uma tarefa muito importante a realizar.",
  ui_story_1016_10161001_48_dialog_content = "<color=#e8d9bb>Gannon City, escritório de Ulysses</color>",
  ui_story_1016_10161001_49_dialog_content = "De volta à Cidade Gannon novamente.",
  ui_story_1016_10161001_50_dialog_content = "O que acontece a seguir será o início de um novo capítulo para a Illumina.",
  ui_story_1016_10161001_51_dialog_content = "Hum? O que é isso...",
  ui_story_1016_10161001_52_dialog_content = "Como sempre, seu plano é perfeito, nos mínimos detalhes. Se ao menos ela tivesse dado tempo para eu recuperar o fôlego.",
  ui_story_1016_10161001_53_dialog_content = "Esien, você poderia vir me ver?",
  ui_story_1016_10161001_54_dialog_content = "Agora mesmo.",
  ui_story_1016_10161001_55_dialog_content = "<color=#e8d9bb>TOC Toc toc</color>",
  ui_story_1016_10161001_56_dialog_content = "Como posso ajudá-lo, senhor?",
  ui_story_1016_10161001_57_dialog_content = "Pegue isso e entregue para a Senhora <color=#FFB400>máscara de ferro</color>... Diga a ela-",
  ui_story_1016_10161001_58_dialog_content = "Estas são minhas mudanças propostas para as estruturas de defesa da cidade e exijo sua cooperação.",
  ui_story_1016_10161001_59_dialog_content = "Entendi.",
  ui_story_1016_10161001_60_dialog_content = "<color=#e8d9bb>Enquanto isso, em algum lugar na cidade de Gannon...</color>",
  ui_story_1016_10161001_61_dialog_content = "Ainda não é hora, mas a busca de Illumina está ficando cada vez mais frenética.",
  ui_story_1016_10161001_62_dialog_content = "Maldito seja, velho... Você está tão desesperado pelos frutos da minha pesquisa?",
  ui_story_1016_10161001_63_dialog_content = "Se for esse o caso, então talvez Jade possa...",
  ui_story_1016_10161001_64_dialog_content = "...",
  ui_story_1016_10161001_65_dialog_content = "Eu quase esqueci. Jade provavelmente já se foi há muito tempo.",
  ui_story_1016_10161001_66_dialog_content = "Negador!",
  ui_story_1016_10161001_67_dialog_content = "O que é, Reinhardt?",
  ui_story_1016_10161001_68_dialog_content = "Você não se lembra que dia é hoje?",
  ui_story_1016_10161001_69_dialog_content = "Hoje...?",
  ui_story_1016_10161001_70_dialog_content = "É hora de entregar os resultados do nosso experimento? Ou talvez seja o último dia do nosso período de avaliação?",
  ui_story_1016_10161001_71_dialog_content = "Errado nas duas contas!",
  ui_story_1016_10161001_72_dialog_content = "Você realmente esquece? Hoje é seu aniversário, Denier!",
  ui_story_1016_10161001_73_dialog_content = "Meu aniversário? Sim, isso mesmo.",
  ui_story_1016_10161001_74_dialog_content = "Como você pôde esquecer seu próprio aniversário?",
  ui_story_1016_10161001_75_dialog_content = "Não é nada de especial, realmente. Além de alguns gestos habituais, um aniversário não é diferente de qualquer outro dia.",
  ui_story_1016_10161001_76_dialog_content = "Suspiro... Outra resposta típica do Negador.",
  ui_story_1016_10161001_77_dialog_content = "Você é a única pessoa que faria uma avaliação tão calma e racional de seu próprio aniversário.",
  ui_story_1016_10161001_78_dialog_content = "Mas só porque você não se importa não significa que não seja importante para outras pessoas.",
  ui_story_1016_10161001_79_dialog_content = "Hã?",
  ui_story_1016_10161001_80_dialog_content = "Comprei um presente de aniversário para você.",
  ui_story_1016_10161001_81_dialog_content = "Aqui, pegue!",
  ui_story_1016_10161001_82_dialog_content = "Rangido!",
  ui_story_1016_10161001_83_dialog_content = "O que é isso?!",
  ui_story_1016_10161001_84_dialog_content = "Hahaha! Acho que ela gosta de você, Denier!",
  ui_story_1016_10161001_85_dialog_content = "Eu a encontrei no campo de batalha durante meu último destacamento. Eu não tinha certeza de que tipo de animal ela era, mas achei ela muito fofa!",
  ui_story_1016_10161001_86_dialog_content = "Então resolvi trazê-la de volta e cuidar dela por um tempo. Tentei alimentá-la com pãezinhos de serragem, mas ela não parece se importar com eles.",
  ui_story_1016_10161001_87_dialog_content = "Considere-a minha substituta sempre que não estiver ao seu lado, ok?",
  ui_story_1016_10161001_88_dialog_content = "Ta brincando né...?",
  ui_story_1016_10161001_89_dialog_content = "Isso é uma chinchila. Pãezinhos de serragem não existem em nenhum lugar de sua dieta natural.",
  ui_story_1016_10161001_90_dialog_content = "Se você for cuidar dele, tente alimentá-lo com feno ou grãos. Mesmo algumas cenouras iriam longe.",
  ui_story_1016_10161001_91_dialog_content = "Ver? Eu sabia que você seria a pessoa perfeita para cuidar dela!",
  ui_story_1016_10161001_92_dialog_content = "Eu só sei disso porque constantemente conduzimos experimentos em animais como este. Mantê-los bem alimentados é apenas parte do processo.",
  ui_story_1016_10161001_93_dialog_content = "<anim type=Shake><size=45>Rangido!!!</size></anim>",
  ui_story_1016_10161001_94_dialog_content = "Pare com isso, Negador! Você a está assustando!",
  ui_story_1016_10161001_95_dialog_content = "...",
  ui_story_1016_10161001_96_dialog_content = "<anim type=Shake>Rangido...</anim>",
  ui_story_1016_10161001_97_dialog_content = "Eu prometo que não vou fazer nada com ela. Afinal, ela é um presente seu.",
  ui_story_1016_10161001_98_dialog_content = "Então isso significa que você aceita meu presente?",
  ui_story_1016_10161001_99_dialog_content = "Sim.",
  ui_story_1016_10161001_100_dialog_content = "Então vamos pensar em um nome para ela!",
  ui_story_1016_10161001_101_dialog_content = "Um nome, hein...",
  ui_story_1016_10161001_102_dialog_content = "Vamos apenas chamá-la <color=#FFB400>Jade</color>.",
  ui_story_1016_10161001_103_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_1016_10161001_104_dialog_content = "M-Meus experimentos...",
  ui_story_1016_10161001_105_dialog_content = "Já se foram todos...",
  ui_story_1016_10161001_106_dialog_content = "Por que, Reinhardt... Por que você ainda não voltou?!",
  ui_story_1016_10161001_107_dialog_content = "<anim type=Shake><size=45>guincho, guincho—</size></anim>",
  ui_story_1016_10161001_108_dialog_content = "Você...",
  ui_story_1016_10161001_109_dialog_content = "Considere-a minha substituta sempre que não estiver ao seu lado, ok?",
  ui_story_1016_10161001_110_dialog_content = "Você...?!",
  ui_story_1016_10161001_111_dialog_content = "<anim type=Shake><size=45>Rangido! Rangido-!!!</size></anim>",
  ui_story_1016_10161001_112_dialog_content = "<anim type=Shake>Rangido...</anim>",
  ui_story_1016_10161001_113_dialog_content = "—!!!",
  ui_story_1016_10161001_114_dialog_content = "Rangido!",
  ui_story_1016_10161001_115_dialog_content = "<anim type=Shake>Chiado... Chiado...</anim>",
  ui_story_1016_10161001_116_dialog_content = "Por que você ainda esta aqui? Você não sabe que eu poderia quebrar seu pescocinho sempre que eu quiser?",
  ui_story_1016_10161001_117_dialog_content = "Por que você não fugiu como ela?",
  ui_story_1016_10161001_118_dialog_content = "<anim type=Shake><size=32>Rangido...</size></anim>",
  ui_story_1016_10161001_119_dialog_content = "...",
  ui_story_1016_10161001_120_dialog_content = "Esqueça...",
  ui_story_1016_10161001_121_dialog_content = "Vou deixar você ficar por enquanto.",
  ui_story_1016_10161001_122_dialog_content = "No mínimo, você tem algum valor como cobaia.",
  ui_story_1016_10161001_123_dialog_content = "Valor, hein?",
  ui_story_1016_10161001_124_dialog_content = "É verdade que neste mundo tudo se mede pelo seu valor.",
  ui_story_1016_10161001_125_dialog_content = "<color=#e8d9bb>Ruído, farfalhar...</color>",
  ui_story_1016_10161001_126_dialog_content = "Negador... Eu sinto movimento... Tenha cuidado...",
  ui_story_1016_10161001_127_dialog_content = "Growl...",
  ui_story_1016_10161001_128_dialog_content = "É... um Eclipsite!",
  ui_story_1016_10161001_129_dialog_content = "...",
  ui_story_1016_10161001_130_dialog_content = "Abaixe sua arma. Não vai te machucar.",
  ui_story_1016_10161001_131_dialog_content = "(Eclipsian) Lady Forsakin, trago uma mensagem do Senhor <color=#FFB400>Figerald</color>.",
  ui_story_1016_10161001_132_dialog_content = "(Eclipsiano) Fale.",
  ui_story_1016_10161001_133_dialog_content = "(Eclipsiano) \"Para acolhermos devidamente os nossos <color=#FFB400>queridos convidados</color>, você deve destruir os sistemas de defesa de Illumina por dentro.\"",
  ui_story_1016_10161001_134_dialog_content = "(Eclipsiano) Então finalmente chegou a hora.",
  ui_story_1016_10161001_135_dialog_content = "<color=#e8d9bb>No dia da exibição final, 15 minutos antes do início da partida</color>",
  ui_story_1016_10161001_136_dialog_content = "Suspirar-",
  ui_story_1016_10161001_137_dialog_content = "Eu não posso acreditar que não fomos capazes de ajudar Carleen proteger seu título.",
  ui_story_1016_10161001_138_dialog_content = "Eu sei...",
  ui_story_1016_10161001_139_dialog_content = "Não pareça tão derrotado. Não havia nada de vergonhoso em nossa perda.",
  ui_story_1016_10161001_140_dialog_content = "Aqueles que participam do Exercício Militar Conjunto estão entre os melhores e mais brilhantes de suas respectivas facções. Ver pessoas que são mais fortes do que nós não deveria ser uma surpresa.",
  ui_story_1016_10161001_141_dialog_content = "Vitória e derrota nunca são escritas em pedra. Podemos ter falhado, mas agora sabemos o quão fortes nossos rivais podem ser. Na verdade, eles nos deram um novo objetivo para o qual trabalhar.",
  ui_story_1016_10161001_142_dialog_content = "Nada como um dos poderosos discursos motivacionais de Carleen para nos animar, não é?",
  ui_story_1016_10161001_143_dialog_content = "S-Sério?",
  ui_story_1016_10161001_144_dialog_content = "Vocês também vêm ver o jogo?",
  ui_story_1016_10161001_145_dialog_content = "Ei, Leo! Não esperava te ver aqui.",
  ui_story_1016_10161001_146_dialog_content = "Zhao e Joseph não estão com você?",
  ui_story_1016_10161001_147_dialog_content = "O Exercício Militar Conjunto realmente prejudicou Zhao, então ele decidiu desistir da partida.",
  ui_story_1016_10161001_148_dialog_content = "Joseph ficou para trás para lhe fazer companhia enquanto os médicos o examinavam no hospital.",
  ui_story_1016_10161001_149_dialog_content = "Vocês realmente parecem estar se dando bem agora. Vocês estão até cuidando uns dos outros!",
  ui_story_1016_10161001_150_dialog_content = "Hahaha! Você pode estar certo!",
  ui_story_1016_10161001_151_dialog_content = "A parceria realmente nos ajudou a nos conhecer muito mais também.",
  ui_story_1016_10161001_152_dialog_content = "Embora sejamos de facções diferentes, ainda nos respeitamos como rivais e companheiros de armas.",
  ui_story_1016_10161001_153_dialog_content = "Uma rivalidade amigável, eu vejo...",
  ui_story_1016_10161001_154_dialog_content = "Vou manter isso em mente.",
  ui_story_1016_10161001_155_dialog_content = "Ei, não é isso Yingel? E Anatoli também!",
  ui_story_1016_10161001_156_dialog_content = "Huh? Onde? Devemos ir dizer olá?",
  ui_story_1016_10161001_157_dialog_content = "Ali, ao lado da cadeira do juiz.",
  ui_story_1016_10161001_158_dialog_content = "Isso não pode ser...",
  ui_story_1016_10161001_159_dialog_content = "Seriam Eclipsitas?",
  ui_story_1016_10161001_160_dialog_content = "A situação é extremamente terrível agora.",
  ui_story_1016_10161001_161_dialog_content = "Vamos investigar.",
  ui_story_1016_10161001_162_dialog_content = "Isso é estranho, eu me pergunto por que eles parecem tão sérios?",
  ui_story_1016_10161001_163_dialog_content = "Estamos muito longe para ouvir o que eles estão falando.",
  ui_story_1016_10161001_164_dialog_content = "Acha que é algo importante?",
  ui_story_1016_10161001_165_dialog_content = "Devemos perguntar a eles nós mesmos.",
  ui_story_1016_10161001_166_dialog_content = "Para um cavaleiro de Lumopolis, você parece bastante preocupado com os assuntos de Illumina, Leo.",
  ui_story_1016_10161001_167_dialog_content = "Perdoe minha grosseria, mas sinto que devo corrigir sua afirmação. Não é com Illumina que estou preocupado, mas com a segurança de Twilight.",
  ui_story_1016_10161001_168_dialog_content = "Certamente você já ouviu falar do grande perigo que Crepúsculo está enfrentando? Esse perigo se torna mais iminente a cada dia que passa.",
  ui_story_1016_10161001_169_dialog_content = "Twilight precisa de toda a ajuda possível se quiser sobreviver ao ataque dos Eclipsites.",
  ui_story_1016_10161001_170_dialog_content = "Do jeito que está, parece que nossos amigos da Illumina precisam de ajuda.",
  ui_story_1016_10161001_171_dialog_content = "Além de ser a coisa certa a fazer, ganhar o favor dos futuros líderes da Illumina agora também nos ajudará a longo prazo.",
  ui_story_1016_10161001_172_dialog_content = "Já ouvi falar da situação em Crepúsculo, sim. Também estou ciente da pressão sua e de seus camaradas.",
  ui_story_1016_10161001_173_dialog_content = "Eu relatei o assunto aos superiores de Lumopolis e solicitei seu apoio.",
  ui_story_1016_10161001_174_dialog_content = "Obrigado pela sua preocupação, Senhora Carleen.",
  ui_story_1016_10161001_175_dialog_content = "Mas, julgando por nossas experiências passadas, temo que seu pedido cairá em ouvidos surdos.",
  ui_story_1016_10161001_176_dialog_content = "O que Twilight precisa agora não é de promessas faladas, mas de ação. Ação real, decisiva e solidária.",
  ui_story_1016_10161001_177_dialog_content = "...",
  ui_story_1016_10161001_178_dialog_content = "Mesmo assim, vou tentar o meu melhor.",
  ui_story_1016_10161001_179_dialog_content = "Twilight agradece por seus esforços, Lady Carleen. Assim como eu.",
  ui_story_1016_10161001_180_dialog_content = "Mesmo um único ato de bondade pode mudar a maré a nosso favor.",
  ui_story_1016_10161001_181_dialog_content = "Por favor, fiquem aqui e aproveitem a partida, pessoal. Eu só vou embora um minuto.",
  ui_story_1016_10161001_182_dialog_content = "Espere, eu estou indo também. Como soldado da Illumina, também tenho o dever de ajudá-los se estiverem com problemas!",
  ui_story_1016_10161001_183_dialog_content = "Conte comigo também!",
  ui_story_1016_10161001_184_dialog_content = "E eu também.",
  ui_story_1016_10161001_185_dialog_content = "Ótimo! Então vamos indo.",
  ui_story_1016_10161001_186_dialog_content = "Descobrimos algum motivo ou suspeito?",
  ui_story_1016_10161001_187_dialog_content = "Eles ainda estão investigando.",
  ui_story_1016_10161001_188_dialog_content = "Quantos sistemas de defesa de Gannon City foram comprometidos?",
  ui_story_1016_10161001_189_dialog_content = "Dos sistemas que verificamos até agora, cerca de 16% deles foram fortemente danificados ou totalmente desativados.",
  ui_story_1016_10161001_190_dialog_content = "No entanto, examinamos apenas metade deles. O tamanho grande e as passagens complexas de Gannon City dificultam a avaliação rápida de toda a nossa rede de sistemas de defesa.",
  ui_story_1016_10161001_191_dialog_content = "Mas mesmo que apenas uma fração de nossos sistemas esteja inoperante, é o suficiente para deixar uma clara lacuna em nossas defesas. A situação requer ação imediata.",
  ui_story_1016_10161001_192_dialog_content = "Um ato de sabotagem tão grave... Poderia ter sido obra de Forsakin?",
  ui_story_1016_10161001_193_dialog_content = "É bem possível.",
  ui_story_1016_10161001_194_dialog_content = "Venha comigo. Precisamos relatar isso imediatamente...",
  ui_story_1016_10161001_195_dialog_content = "Yingel! Anatoli! Espere!",
  ui_story_1016_10161001_196_dialog_content = "PlayerName? Junto com o tenente Vice e nossos convidados de Lumopolis?",
  ui_story_1016_10161001_197_dialog_content = "A partida está prestes a começar, não é? Por que você está aqui e não em seus lugares?",
  ui_story_1016_10161001_198_dialog_content = "Vimos vocês dois saindo às pressas agora. Parecia que algo estava te incomodando.",
  ui_story_1016_10161001_199_dialog_content = "Se precisar de ajuda, ficarei feliz em ajudar.",
  ui_story_1016_10161001_200_dialog_content = "Oferecendo sua ajuda? Isso não é nada parecido com você, Leo. Além disso, por que nossos assuntos deveriam se referir a um cavaleiro de Lumópolis?",
  ui_story_1016_10161001_201_dialog_content = "Eu vejo. Se você vai falar tão sem rodeios, então posso fazer o mesmo.",
  ui_story_1016_10161001_202_dialog_content = "Estou oferecendo minha ajuda agora para garantir seu apoio a Crepúsculo no futuro.",
  ui_story_1016_10161001_203_dialog_content = "E o que te dá tanta certeza de que precisamos da sua ajuda?",
  ui_story_1016_10161001_204_dialog_content = "Sem mencionar que sou apenas um oficial de inteligência. Eu não represento o Illumina, então não tenho como prometer seu apoio à sua causa.",
  ui_story_1016_10161001_205_dialog_content = "Estou bem ciente disso, mas não estou procurando todo o apoio da Illumina. Eu só preciso do seu apoio, assim como o apoio de seus aliados.",
  ui_story_1016_10161001_206_dialog_content = "Você e seus camaradas são fortes, e agora é exatamente disso que Twilight precisa.",
  ui_story_1016_10161001_207_dialog_content = "Não apenas isso...",
  ui_story_1016_10161001_208_dialog_content = "Com a partida de exibição final do Exercício Militar Conjunto em andamento, todos estão assistindo à partida ou guardando o perímetro.",
  ui_story_1016_10161001_209_dialog_content = "Isso me diz que você está com poucos funcionários agora. Estou errado?",
  ui_story_1016_10161001_210_dialog_content = "...",
  ui_story_1016_10161001_211_dialog_content = "Yingel, se algo realmente estiver errado, não ficaríamos parados sem fazer nada a respeito. Somos aliados, não somos?",
  ui_story_1016_10161001_212_dialog_content = "Especialmente se Forsakin estiver envolvido...",
  ui_story_1016_10161001_213_dialog_content = "Forsakin?!",
  ui_story_1016_10161001_214_dialog_content = "Você...",
  ui_story_1016_10161001_215_dialog_content = "Me desculpe, eu não queria escutar nosso caminho até aqui...",
  ui_story_1016_10161001_216_dialog_content = "Seus poderes realmente são outra coisa, Celestita.",
  ui_story_1016_10161001_217_dialog_content = "Eu realmente sinto muito...",
  ui_story_1016_10161001_218_dialog_content = "Você pode me falar sobre a situação atual, Yingel? Se Forsakin está envolvido, definitivamente não podemos ignorá-lo!",
  ui_story_1016_10161001_219_dialog_content = "Nós lutamos ao lado um do outro muitas vezes! Você pode confiar em nós, eu prometo!",
  ui_story_1016_10161001_220_dialog_content = "Isso mesmo!",
  ui_story_1016_10161001_221_dialog_content = "...",
  ui_story_1016_10161001_222_dialog_content = "Seu palpite está correto. Precisamos de ajuda agora mais do que nunca.",
  ui_story_1016_10161001_223_dialog_content = "As defesas de Gannon City foram severamente comprometidas. Desdobrámos a maior parte das nossas forças para proteger os sistemas que ainda estão operacionais enquanto o resto está a ser inspeccionado e reparado.",
  ui_story_1016_10161001_224_dialog_content = "Infelizmente, não temos pessoas suficientes para fazer isso de forma eficaz. Se você estiver disposto a ajudar, não vou mandá-lo embora.",
  ui_story_1016_10161001_225_dialog_content = "Mas se você ou seus aliados encontrarem qualquer sinal de Forsakin ou dos outros Wraiths, devem nos notificar imediatamente.",
  ui_story_1016_10161001_226_dialog_content = "Forsakin... Ou os outros Wraiths?!",
  ui_story_1016_10161001_227_dialog_content = "Isso mesmo. E se você conseguir prendê-los, deverá entregá-los à custódia de Illumina.",
  ui_story_1016_10161001_228_dialog_content = "Sua cidade, suas regras.",
  ui_story_1016_10161001_229_dialog_content = "Você disse que as defesas foram comprometidas, certo?",
  ui_story_1016_10161001_230_dialog_content = "Quão seriamente eles foram danificados?",
  ui_story_1016_10161001_231_dialog_content = "É difícil dizer no momento.",
  ui_story_1016_10161001_232_dialog_content = "Normalmente, esse nível de dano não justificaria muita preocupação, mas dado o momento, bem como a presença de Forsakin na cidade de Gannon...",
  ui_story_1016_10161001_233_dialog_content = "Precisamos estar prontos para qualquer coisa. Não podemos nos dar ao luxo de deixar nada escapar.",
  ui_story_1016_10161001_234_dialog_content = "Então você está dizendo que o traidor Illumina está em algum lugar da cidade agora, sim?",
  ui_story_1016_10161001_235_dialog_content = "(Se for esse o caso, tenho quase certeza de que os Eclipsites que encontramos anteriormente estavam sob o comando dela.)",
  ui_story_1016_10161001_236_dialog_content = "Ainda não temos pistas sobre o paradeiro dela, mas é muito provável que ela ainda esteja aqui.",
  ui_story_1016_10161001_237_dialog_content = "Se você insiste em nos ajudar, então você precisa ficar vigilante o tempo todo.",
  ui_story_1016_10161001_238_dialog_content = "Principal Anatoli, atribua-os a uma área que precise de suporte.",
  ui_story_1016_10161001_239_dialog_content = "Agora mesmo.",
  ui_story_1016_10161001_240_dialog_content = "Tenente Vice, como alguém que conhece bem Gannon City, você estará no comando da equipe.",
  ui_story_1016_10161001_241_dialog_content = "Não é um problema! Você pode contar comigo!",
  ui_story_1016_10161001_242_dialog_content = "Sua tarefa é patrulhar os Setores A a C, todos próximos à Estação Ferroviária de Gannon City. Uma vez lá, inspecione o status de nossos sistemas de defesa e observe qualquer dano.",
  ui_story_1016_10161001_243_dialog_content = "Reporte para Yingel ou eu mesmo assim que você terminar sua tarefa.",
  ui_story_1016_10161001_244_dialog_content = "Entendido!",
  ui_story_1016_10161101_1_dialog_content = "A partida final está prestes a começar. Você está pronto?",
  ui_story_1016_10161101_2_dialog_content = "Claro. Na verdade, estou mais do que pronto.",
  ui_story_1016_10161101_3_dialog_content = "E você? Seu pessoal encontrou alguma coisa?",
  ui_story_1016_10161101_4_dialog_content = "Ainda não.",
  ui_story_1016_10161101_5_dialog_content = "Forsakin provavelmente está escondido no setor subdesenvolvido de Gannon City. Esse lugar tem passagens que correm em todas as direções, então vamos levar algum tempo para revistá-lo minuciosamente.",
  ui_story_1016_10161101_6_dialog_content = "Eu aprecio o esforço.",
  ui_story_1016_10161101_7_dialog_content = "Não é nada, realmente.",
  ui_story_1016_10161101_8_dialog_content = "Eu mesmo iria liderar a busca, mas depois pensei no Exercício Militar Conjunto e percebi que tinha que ficar aqui.",
  ui_story_1016_10161101_9_dialog_content = "Faz sentido. Quem sabe que tipo de problema esses tolos fofoqueiros podem criar se o Capitão da Guarda Real não estiver presente para a partida final?",
  ui_story_1016_10161101_10_dialog_content = "É sempre o mesmo grupo de idiotas atrapalhando.",
  ui_story_1016_10161101_11_dialog_content = "Mas isso não importa. Já designei segurança pesada em todo o perímetro.",
  ui_story_1016_10161101_12_dialog_content = "Mesmo que eu não esteja aqui, Forsakin teria dificuldade em interromper a partida final.",
  ui_story_1016_10161101_13_dialog_content = "Obrigado. Com a sua ajuda, poderemos encerrar o Exercício Militar Conjunto sem mais problemas.",
  ui_story_1016_10161101_14_dialog_content = "<color=#e8d9bb> Enquanto isso, no laboratório de Algol</color>",
  ui_story_1016_10161101_15_dialog_content = "Aqui vamos nós! Os ajustes finais agora estão completos.",
  ui_story_1016_10161101_16_dialog_content = "Ainda assim, aquele companheirinho parece estar voando um pouco mais devagar que o normal. Talvez suas peças estejam começando a se desgastar?",
  ui_story_1016_10161101_17_dialog_content = "Não vai adiantar muito lá fora, então por que não deixa comigo por enquanto? Vou tê-lo funcionando como novo em nenhum momento!",
  ui_story_1016_10161101_18_dialog_content = "Não será necessário.",
  ui_story_1016_10161101_19_dialog_content = "Preciso deste pequenino para me ajudar a levantar as mangas.",
  ui_story_1016_10161101_20_dialog_content = "Terei muito mais problemas lutando sem ele.",
  ui_story_1016_10161101_21_dialog_content = "É assim mesmo? Muito bem, faça do seu jeito.",
  ui_story_1016_10161101_22_dialog_content = "Vou ter que consertar assim que você terminar sua batalha com Reinhardt.",
  ui_story_1016_10161101_23_dialog_content = "O Cubic Trio está agora em excelentes condições de combate. Use-os ao máximo, Axelia.",
  ui_story_1016_10161101_24_dialog_content = "Você os criou, Algol. Você os conhece melhor do que ninguém.",
  ui_story_1016_10161101_25_dialog_content = "Eu confio em você, assim como confio nos Cubos.",
  ui_story_1016_10161101_26_dialog_content = "Hahahaha! Bem, obrigado, querido. Estou encantado em ouvi-lo.",
  ui_story_1016_10161101_27_dialog_content = "Eu vi você crescer a maior parte de sua vida, então é natural que eu queira cuidar de você.",
  ui_story_1016_10161101_28_dialog_content = "Como você está se sentindo agora?",
  ui_story_1016_10161101_29_dialog_content = "Nenhuma anormalidade de status. A postos para o combate.",
  ui_story_1016_10161101_30_dialog_content = "Bem, isso é bom.",
  ui_story_1016_10161101_31_dialog_content = "Mas não subestime Reinhardt só por causa disso, Axelia.",
  ui_story_1016_10161101_32_dialog_content = "Embora as modificações de combate de Reinhardt estejam um pouco desatualizadas, ela ainda é uma das aurorianas mais poderosas de toda a Illumina.",
  ui_story_1016_10161101_33_dialog_content = "Você também conhece suas limitações. Sob nenhuma circunstância você tem permissão para se esforçar demais.",
  ui_story_1016_10161101_34_dialog_content = "Lutarei até o fim e obterei a vitória.",
  ui_story_1016_10161101_35_dialog_content = "Não há como lhe dizer o que fazer quando você se concentra em algo, não é?",
  ui_story_1016_10161101_36_dialog_content = "Mesmo que eu diga para você não fazer isso, sempre há uma chance de você não ouvir.",
  ui_story_1016_10161101_37_dialog_content = "Vou ouvir o professor Ulisses.",
  ui_story_1016_10161101_38_dialog_content = "E tente ouvir as sugestões de outras pessoas de vez em quando, hein?",
  ui_story_1016_10161101_39_dialog_content = "Mas chega de palestras por um dia. Vá embora, minha querida.",
  ui_story_1016_10161101_40_dialog_content = "Vá direto para a arena.",
  ui_story_1016_10161101_41_dialog_content = "Entendi.",
  ui_story_1016_10161101_42_dialog_content = "Bom. Boa sorte, Axelia.",
  ui_story_1016_10161101_43_dialog_content = "<color=#e8d9bb>De volta à arena</color>",
  ui_story_1016_10161101_44_dialog_content = "Como juiz de hoje, tenho a grande honra de anunciar o início da partida final do Exercício Militar Conjunto!",
  ui_story_1016_10161101_45_dialog_content = "<size=45>Uau!!!</size>",
  ui_story_1016_10161101_46_dialog_content = "Primeiro, vamos dar as boas-vindas ao Grande Marechal de Illumina, a invicta Iluminação Iluminada—Reinhardt!",
  ui_story_1016_10161101_47_dialog_content = "<size=45>Reinhardt—! Reinhardt—!</size>",
  ui_story_1016_10161101_48_dialog_content = "Vamos dar uma salva de palmas para todos os nossos trabalhadores participantes do Exercício Militar Conjunto!",
  ui_story_1016_10161101_49_dialog_content = "Aos olhos do mundo e aos meus, você provou não apenas sua força, mas sua capacidade de aprender e se aprimorar!",
  ui_story_1016_10161101_50_dialog_content = "Não tenho nada além do maior respeito por todos vocês!",
  ui_story_1016_10161101_51_dialog_content = "<size=45>Uau!!!</size>",
  ui_story_1016_10161101_52_dialog_content = "E agora, vamos dar as boas-vindas à desafiante de hoje, a participante que superou seus pares e conquistou o privilégio de enfrentar o Grand Marshal Reinhardt em batalha-",
  ui_story_1016_10161101_53_dialog_content = "Axelia, da Federação Illumina!",
  ui_story_1016_10161101_54_dialog_content = "Axelia—!",
  ui_story_1016_10161101_55_dialog_content = "...",
  ui_story_1016_10161101_56_dialog_content = "Axelia, huh? Nunca ouvi falar dela... Ela deve ser muito forte!",
  ui_story_1016_10161101_57_dialog_content = "Sem brincadeiras. Até nós da Illumina fomos pegos de surpresa!",
  ui_story_1016_10161101_58_dialog_content = "Não sabia que existia outra potência como ela!",
  ui_story_1016_10161101_59_dialog_content = "Combatentes, por favor, apertem as mãos.",
  ui_story_1016_10161101_60_dialog_content = "Axelia...",
  ui_story_1016_10161101_61_dialog_content = "Já ouvi falar de você. Sua força é algo a ser admirado.",
  ui_story_1016_10161101_62_dialog_content = "Obrigado pelo seu elogio.",
  ui_story_1016_10161101_63_dialog_content = "Você conseguiu descansar o suficiente antes da partida? Afinal, o Exercício Militar Conjunto terminou ontem.",
  ui_story_1016_10161101_64_dialog_content = "Não vou pegar leve com você só porque não está totalmente descansado.",
  ui_story_1016_10161101_65_dialog_content = "Eu me sinto perfeitamente bem, porque...",
  ui_story_1016_10161101_66_dialog_content = "Tudo o que fiz foi em preparação para este momento.",
  ui_story_1016_10161101_67_dialog_content = "...!",
  ui_story_1016_10161101_68_dialog_content = "Minhas ordens são para enfrentá-lo na batalha.",
  ui_story_1016_10161101_69_dialog_content = "Vou esgotar todas as opções possíveis para derrotá-lo.",
  ui_story_1016_10161101_70_dialog_content = "É assim mesmo? Aguardo então.",
  ui_story_1016_10161101_71_dialog_content = "Competir contra um membro poderoso da geração mais jovem é sempre emocionante.",
  ui_story_1016_10161101_72_dialog_content = "...",
  ui_story_1016_10161101_73_dialog_content = "(Qual é o problema com essa garota?)",
  ui_story_1016_10161101_74_dialog_content = "(Algo em sua expressão é inquietante. Não se parece com a de nenhum soldado que eu já vi...)",
  ui_story_1016_10161101_75_dialog_content = "(Mas a de um moribundo.)",
  ui_story_1016_10161101_76_dialog_content = "(Eu realmente a assustei tanto assim?)",
  ui_story_1016_10161101_77_dialog_content = "(Ou é outra coisa...?)",
  ui_story_1016_10161101_78_dialog_content = "Agora, se ambos os combatentes puderem tomar seus lugares, podemos começar a luta!",
  ui_story_1016_10161101_79_dialog_content = "...",
  ui_story_1016_10161101_80_dialog_content = "Preparar-",
  ui_story_1016_10161101_81_dialog_content = "<size=50><color=#FFB400>Começar</color>!</size>",
  ui_story_1016_10161101_82_dialog_content = "—!",
  ui_story_1016_10161101_83_dialog_content = "Cubos!",
  ui_story_1016_10161101_84_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10161101_85_dialog_content = "Que ataque poderoso!",
  ui_story_1016_10161101_86_dialog_content = "Parece que eu vou ter que ir com tudo também.",
  ui_story_1016_10161101_87_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_1016_10161101_88_dialog_content = "<size=45>Sim!!!</size>",
  ui_story_1016_10161101_89_dialog_content = "Reinhardt—! Reinhardt—!",
  ui_story_1016_10161101_90_dialog_content = "Ataque inicial bem-sucedido. Avaliação de danos: o alvo não sofreu nenhum dano visível.",
  ui_story_1016_10161101_91_dialog_content = "A força do inimigo é um pouco maior do que o esperado, mas ainda dentro dos parâmetros administráveis.",
  ui_story_1016_10161101_92_dialog_content = "Aumentando a saída de lúmen.",
  ui_story_1016_10161101_93_dialog_content = "Três-",
  ui_story_1016_10161101_94_dialog_content = "(Ela está carregando um ataque?!)",
  ui_story_1016_10161101_95_dialog_content = "(Eu preciso pará-la!)",
  ui_story_1016_10161101_96_dialog_content = "Dois-",
  ui_story_1016_10161101_97_dialog_content = "<size=45>Perfure tudo!</size>",
  ui_story_1016_10161101_98_dialog_content = "—!",
  ui_story_1016_10161101_99_dialog_content = "Fora do caminho!",
  ui_story_1016_10161101_100_dialog_content = "Um!",
  ui_story_1016_10161101_101_dialog_content = "(Tarde demais, né?)",
  ui_story_1016_10161101_103_dialog_content = "Vai, minha lança!",
  ui_story_1016_10161101_104_dialog_content = "Desculpe o atraso.",
  ui_story_1016_10161101_105_dialog_content = "<color=#e8d9bb>Estrondo-!!!</color>",
  ui_story_1016_10161101_106_dialog_content = "<size=45>Uau!!!</size>",
  ui_story_1016_10161101_107_dialog_content = "COF cof...!",
  ui_story_1016_10161101_108_dialog_content = "Caramba... Isso dói muito mais do que eu pensava.",
  ui_story_1016_10161101_109_dialog_content = "Você é realmente incrível, garoto.",
  ui_story_1016_10161101_110_dialog_content = "Segundo ataque bem sucedido.",
  ui_story_1016_10161101_111_dialog_content = "Avaliação de danos: mínimo. Target conseguiu anular a maior parte do ataque com seus próprios Luminatics.",
  ui_story_1016_10161101_112_dialog_content = "Aumentando ainda mais a saída de Lumina.",
  ui_story_1016_10161101_113_dialog_content = "(Ela ainda pode aumentar sua produção?!)",
  ui_story_1016_10161101_114_dialog_content = "(Uma explosão de Lumina tão poderosa estaria muito além dos meus limites. Estarei em apuros se ela acertar um golpe direto...)",
  ui_story_1016_10161101_115_dialog_content = "Três-",
  ui_story_1016_10161101_116_dialog_content = "<color=#e8d9bb>Rachadura-</color>",
  ui_story_1016_10161101_117_dialog_content = "<size=45>!</size>",
  ui_story_1016_10161101_118_dialog_content = "(Espere, são aqueles <color=#FFB400>rachaduras</color> aparecendo em seu corpo?)",
  ui_story_1016_10161101_119_dialog_content = "(O corpo dela está começando a quebrar?! Esse poder colossal dela vem com um preço tão alto?!)",
  ui_story_1016_10161101_120_dialog_content = "(Eu não fazia ideia de que o Comitê havia criado um canhão de vidro assim...)",
  ui_story_1016_10161101_121_dialog_content = "Parar, Axelia!",
  ui_story_1016_10161101_122_dialog_content = "Seu corpo não aguenta a tensão de um ataque como esse!!!",
  ui_story_1016_10161101_123_dialog_content = "Ugh...",
  ui_story_1016_10161101_124_dialog_content = "Dois...",
  ui_story_1016_10161101_125_dialog_content = "Não está ouvindo, né? Acho que não tenho escolha...",
  ui_story_1016_10161101_126_dialog_content = "Juiz! Você precisa interromper a partida agora mesmo!",
  ui_story_1016_10161101_127_dialog_content = "A vida de Axelia estará em perigo a este ritmo!",
  ui_story_1016_10161101_128_dialog_content = "Do que seu Grande Marechal está falando?",
  ui_story_1016_10161101_129_dialog_content = "Nenhuma idéia. não consigo ouvi-la...",
  ui_story_1016_10161101_130_dialog_content = "Silêncio! Continue a partida!",
  ui_story_1016_10161101_131_dialog_content = "(O juiz e o público não podem me ouvir! Espere...)",
  ui_story_1016_10161101_132_dialog_content = "(Eu posso sentir um leve <color=#FFB400>Barreira Darkflow</color> entre a arena e as arquibancadas! Quando isso apareceu?!)",
  ui_story_1016_10161101_133_dialog_content = "(Será que é por isso que eles não podem me ouvir? Vou ter que quebrá-lo para descobrir!)",
  ui_story_1016_10161101_134_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10161101_135_dialog_content = "(Ela está cortando meus movimentos?!)",
  ui_story_1016_10161101_136_dialog_content = "Alvo... Bloqueado...",
  ui_story_1016_10161101_137_dialog_content = "Um!",
  ui_story_1016_10161101_138_dialog_content = "<size=45>Desculpe pelo atraso!</size>",
  ui_story_1016_10161101_139_dialog_content = "...!",
  ui_story_1016_10161101_140_dialog_content = "<color=#e8d9bb>Estrondo-!!!</color>",
  ui_story_1016_10161101_141_dialog_content = "<color=#e8d9bb>Enquanto isso, na cidade de Gannon</color>",
  ui_story_1016_10161101_142_dialog_content = "Verifiquei o interior da estação. Sem problemas.",
  ui_story_1016_10161101_143_dialog_content = "Nada na área circundante também.",
  ui_story_1016_10161101_144_dialog_content = "O mesmo da minha parte.",
  ui_story_1016_10161101_145_dialog_content = "PlayerName! Achei uma coisa aqui!",
  ui_story_1016_10161101_146_dialog_content = "Todo o equipamento de defesa neste túnel de manutenção foi destruído. Há sinais de atividade de Eclipsite aqui também!",
  ui_story_1016_10161101_147_dialog_content = "Estou a caminho!",
  ui_story_1016_10161101_148_dialog_content = "<anim type=Shake><size=50>Grahhh—!</size></anim>",
  ui_story_1016_10161101_149_dialog_content = "Afinal, existem Eclipsites aqui!",
  ui_story_1016_10161101_150_dialog_content = "Não deixe nenhum deles escapar!",
  ui_story_1016_10161102_1_dialog_content = "Eles devem ter alcançado Gannon City agora.",
  ui_story_1016_10161102_2_dialog_content = "Mas não podemos sair ainda. Ainda não é o momento certo.",
  ui_story_1016_10161102_3_dialog_content = "Por que estamos nos escondendo...?",
  ui_story_1016_10161102_4_dialog_content = "Por que você não... confia neles...",
  ui_story_1016_10161102_5_dialog_content = "Confie neles?",
  ui_story_1016_10161102_6_dialog_content = "E se eu te disser que Gannon City já está transbordando de Eclipsites?",
  ui_story_1016_10161102_7_dialog_content = "Ou que as pessoas que governam esta cidade já escolheram ficar do lado dos Eclipsitas também?",
  ui_story_1016_10161102_8_dialog_content = "Se eu te contasse tudo isso, você ainda confiaria neles?",
  ui_story_1016_10161102_9_dialog_content = "...",
  ui_story_1016_10161102_10_dialog_content = "Agora, o único em quem você pode confiar sou eu.",
  ui_story_1016_10161102_11_dialog_content = "Eu sou o único que pode salvá-lo e tirá-lo deste lugar.",
  ui_story_1016_10161102_12_dialog_content = "...",
  ui_story_1016_10161102_13_dialog_content = "(Eclipsiano) Senhora Forsakin.",
  ui_story_1016_10161102_14_dialog_content = "(Eclipsiano) Fale.",
  ui_story_1016_10161102_15_dialog_content = "(Eclipsian) Trago mais uma mensagem de Lord Figerald.",
  ui_story_1016_10161102_16_dialog_content = "(Eclipsiano) \"Tudo está no lugar agora. Você pode recuar.\"",
  ui_story_1016_10161102_17_dialog_content = "(Eclipsiano) Já era hora. Façam mais rápido da próxima vez, idiotas.",
  ui_story_1016_10161102_18_dialog_content = "(Eclipsiano) Minhas desculpas.",
  ui_story_1016_10161102_19_dialog_content = "(Eclipsian) Já identificamos uma rota de fuga escondida.",
  ui_story_1016_10161102_20_dialog_content = "(Eclipsian) Você pode usá-lo para escapar da cidade de Gannon, se desejar.",
  ui_story_1016_10161102_21_dialog_content = "(Eclipsiano) Onde?",
  ui_story_1016_10161102_22_dialog_content = "(Eclipsiano) Aqui.",
  ui_story_1016_10161102_23_dialog_content = "Entendo... Que local remoto para uma rota de fuga.",
  ui_story_1016_10161102_24_dialog_content = "Vamos, espécime.",
  ui_story_1016_10161201_1_dialog_content = "<color=#e8d9bb>Estrondo-!!!</color>",
  ui_story_1016_10161201_2_dialog_content = "<size=45>Tosse, tosse, tosse!!!</size>",
  ui_story_1016_10161201_3_dialog_content = "Ugh...",
  ui_story_1016_10161201_4_dialog_content = "Terceiro ataque... Tosse, tosse... Sucesso.",
  ui_story_1016_10161201_5_dialog_content = "Avaliação de danos... O alvo sofreu ferimentos visíveis.",
  ui_story_1016_10161201_6_dialog_content = "Continuando a ofensiva.",
  ui_story_1016_10161201_7_dialog_content = "(Mas meus níveis de Lumina estão muito baixos...)",
  ui_story_1016_10161201_8_dialog_content = "(Preciso de tempo para reunir minhas forças se quiser continuar atacando.)",
  ui_story_1016_10161201_9_dialog_content = "(Ela vai morrer se isso continuar...)",
  ui_story_1016_10161201_10_dialog_content = "(Por quê? Por que ela está disposta a arriscar sua vida apenas para me derrotar?)",
  ui_story_1016_10161201_11_dialog_content = "(Será que ela está fazendo isso sob as ordens de Ulisses? O Comitê a colocou nisso?!)",
  ui_story_1016_10161201_12_dialog_content = "Cubos!",
  ui_story_1016_10161201_13_dialog_content = "—!",
  ui_story_1016_10161201_14_dialog_content = "(Seu padrão de ataque mudou. Seu Lumina não parece tão forte quanto antes.)",
  ui_story_1016_10161201_15_dialog_content = "(Parece que ela está tentando reunir forças para seu próximo ataque.)",
  ui_story_1016_10161201_16_dialog_content = "(Essa pode ser minha chance.)",
  ui_story_1016_10161201_17_dialog_content = "Axelia, por que você está tão determinado a me vencer?",
  ui_story_1016_10161201_18_dialog_content = "Porque eu sou capaz de fazer isso. É por isso que devo vencer.",
  ui_story_1016_10161201_19_dialog_content = "Você não está realmente respondendo a minha pergunta.",
  ui_story_1016_10161201_20_dialog_content = "Ulisses ordenou que você fizesse isso?",
  ui_story_1016_10161201_21_dialog_content = "...",
  ui_story_1016_10161201_22_dialog_content = "(Ela não está negando. Parece que isso é obra do Comitê, afinal.)",
  ui_story_1016_10161201_23_dialog_content = "(Eles estão realmente tão ansiosos para fortalecer suas vozes me derrotando?)",
  ui_story_1016_10161201_24_dialog_content = "(Se ela realmente está seguindo suas ordens, uma garota como ela jogaria sua vida fora para cumprir sua missão sem hesitar.)",
  ui_story_1016_10161201_25_dialog_content = "(Mas agora, a última coisa que o Comitê precisa é de mais autoridade.)",
  ui_story_1016_10161201_26_dialog_content = "(Se eu quiser salvar esta criança, terei que subjugá-la e forçá-la a se render.)",
  ui_story_1016_10161201_27_dialog_content = "Ainda não acabou-",
  ui_story_1016_10161201_28_dialog_content = "<size=45>Uma abertura!</size>",
  ui_story_1016_10161201_29_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_1016_10161201_30_dialog_content = "Você perdeu.",
  ui_story_1016_10161201_31_dialog_content = "<size=50>Uau-!!!</size>",
  ui_story_1016_10161201_32_dialog_content = "O Grande Marechal conseguiu dominá-la!",
  ui_story_1016_10161201_33_dialog_content = "Isso significa que ela ganhou?",
  ui_story_1016_10161201_34_dialog_content = "...",
  ui_story_1016_10161201_35_dialog_content = "Render.",
  ui_story_1016_10161201_36_dialog_content = "Entendo muito bem sua determinação, mas todos nós temos nossas razões para não querer perder.",
  ui_story_1016_10161201_37_dialog_content = "Não quero te machucar, e definitivamente não quero ver você se machucar assim.",
  ui_story_1016_10161201_38_dialog_content = "Você não é apenas mais jovem do que eu, Axelia, você também tem um potencial muito maior do que eu. O futuro da Federação Illumina é ainda mais esperançoso por sua causa.",
  ui_story_1016_10161201_39_dialog_content = "Então, por favor, não jogue tudo fora só por isso.",
  ui_story_1016_10161201_40_dialog_content = "<anim type=Shake>EU...</anim>",
  ui_story_1016_10161201_41_dialog_content = "<anim type=Shake><size=45>Eu... ainda não perdi!</size></anim>",
  ui_story_1016_10161201_42_dialog_content = "?!",
  ui_story_1016_10161201_43_dialog_content = "Cubos!",
  ui_story_1016_10161201_44_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_1016_10161201_45_dialog_content = "Argh... Tosse, tosse!!!",
  ui_story_1016_10161201_46_dialog_content = "(Aquele robozinho de aparência fraca estava carregando um explosivo de alto impacto o tempo todo?!)",
  ui_story_1016_10161201_47_dialog_content = "(Usando um movimento tão desesperado, apenas para me manter afastado... Parece que ela sofreu mais dano do que eu.)",
  ui_story_1016_10161201_48_dialog_content = "<anim type=Shake>Isso dói...</anim>",
  ui_story_1016_10161201_49_dialog_content = "<anim type=Shake>Mas ainda posso lutar...</anim>",
  ui_story_1016_10161201_50_dialog_content = "<anim type=Shake>Nunca vou me render...</anim>",
  ui_story_1016_10161201_51_dialog_content = "(Ela já se decidiu, não é? Isso significa que só há dois resultados possíveis para esta partida...)",
  ui_story_1016_10161201_52_dialog_content = "(Se eu ganhar, ela morre.)",
  ui_story_1016_10161201_53_dialog_content = "(E se eu me render antes que ela tente me incinerar, o conselho fará o que quer... Mas pelo menos ela permanecerá viva.)",
  ui_story_1016_10161201_54_dialog_content = "<anim type=Shake>Eu irei... executar minhas ordens e... derrotá-lo...</anim>",
  ui_story_1016_10161201_55_dialog_content = "<color=#e8d9bb>Rachadura-</color>",
  ui_story_1016_10161201_56_dialog_content = "<anim type=Shake>Eu... ainda posso...</anim>",
  ui_story_1016_10161201_57_dialog_content = "...",
  ui_story_1016_10161201_58_dialog_content = "O que está acontecendo? Por que não é Reinhardt lutando de volta?",
  ui_story_1016_10161201_59_dialog_content = "Deixe-a ficar com isso, Grande Marechal!",
  ui_story_1016_10161201_60_dialog_content = "Você tem razão! O que deu nela?",
  ui_story_1016_10161201_61_dialog_content = "Parece que finalmente chegou a hora.",
  ui_story_1016_10161201_62_dialog_content = "<color=#e8d9bb>Bzzzzt—</color>",
  ui_story_1016_10161201_63_dialog_content = "Comece a próxima fase da operação.",
  ui_story_1016_10161201_64_dialog_content = "E você tem certeza de que tem tudo sob controle?",
  ui_story_1016_10161201_65_dialog_content = "Sim.",
  ui_story_1016_10161201_66_dialog_content = "Ela não tem como ganhar agora.",
  ui_story_1016_10161201_67_dialog_content = "<color=#e8d9bb>Enquanto isso, nas profundezas da cidade de Gannon</color>",
  ui_story_1016_10161201_68_dialog_content = "Suspiro... Suspiro...",
  ui_story_1016_10161201_69_dialog_content = "Para onde foram... Para onde foram os Eclipsitos?!",
  ui_story_1016_10161201_70_dialog_content = "Eles deram uma olhada em nós e correram como o vento.",
  ui_story_1016_10161201_71_dialog_content = "Onde exatamente estamos?",
  ui_story_1016_10161201_72_dialog_content = "Eu nunca estive aqui antes. Você sabe onde estamos, Vice?",
  ui_story_1016_10161201_73_dialog_content = "Também não faço ideia...",
  ui_story_1016_10161201_74_dialog_content = "Mas pelo que posso dizer, devemos estar bem perto do nível mais baixo de Gannon City.",
  ui_story_1016_10161201_75_dialog_content = "Tenente Vice? PlayerName? O que você está fazendo aqui?",
  ui_story_1016_10161201_76_dialog_content = "Hã?",
  ui_story_1016_10161201_77_dialog_content = "Você não deveria estar inspecionando a estação de trem?",
  ui_story_1016_10161201_78_dialog_content = "C-Coronel Yingel?!",
  ui_story_1016_10161201_79_dialog_content = "Também não esperávamos ver vocês dois aqui.",
  ui_story_1016_10161201_80_dialog_content = "Durante nossa inspeção na estação de trem, encontramos um grupo de Eclipsites à espreita dentro de um dos túneis de manutenção.",
  ui_story_1016_10161201_81_dialog_content = "É verdade, mas eles fugiram assim que nos viram. Nós os seguimos até aqui, mas ainda não há sinal deles.",
  ui_story_1016_10161201_82_dialog_content = "E você? Achei que vocês dois estavam patrulhando a cidade.",
  ui_story_1016_10161201_83_dialog_content = "Como você veio parar aqui também?",
  ui_story_1016_10161201_84_dialog_content = "Nós nos deparamos com uma situação semelhante à sua.",
  ui_story_1016_10161201_85_dialog_content = "Aqueles Eclipsitas estavam se comportando de maneira estranha, como se não tivessem nenhuma intenção de lutar...",
  ui_story_1016_10161201_86_dialog_content = "Deve fazer parte do plano deles. Precisamos estar ainda mais vigilantes.",
  ui_story_1016_10161201_87_dialog_content = "Concordo que eles devem estar tramando algo também.",
  ui_story_1016_10161201_88_dialog_content = "Então, devemos desistir de persegui-los por enquanto?",
  ui_story_1016_10161201_89_dialog_content = "Nunca!",
  ui_story_1016_10161201_90_dialog_content = "Deixá-los descontrolados em Gannon City só criará problemas ainda maiores.",
  ui_story_1016_10161201_91_dialog_content = "Estamos na parte mais profunda da cidade, onde guardamos grandes quantidades de equipamentos tecnológicos essenciais. Se apenas um desses dispositivos for destruído por um Eclipsite, será uma perda catastrófica para a Federação Illumina.",
  ui_story_1016_10161201_92_dialog_content = "Precisamos pegá-los e acabar com seus esquemas antes que eles se concretizem!",
  ui_story_1016_10161201_93_dialog_content = "Você pode sentir o caminho que os Eclipsites seguiram, PlayerName?",
  ui_story_1016_10161201_94_dialog_content = "Posso tentar, mas o layout complexo deste lugar realmente prejudica minhas habilidades psíquicas. Eu só posso sentir sua direção geral, no máximo.",
  ui_story_1016_10161201_95_dialog_content = "Não tenho como dizer exatamente onde eles estão agora.",
  ui_story_1016_10161201_96_dialog_content = "Não se preocupe com isso. Apenas me aponte na direção certa, e eu encontrarei um caminho a seguir.",
  ui_story_1016_10161201_97_dialog_content = "Tudo bem, aqui vou eu.",
  ui_story_1016_10161201_98_option_content = "Aumento de Força!",
  ui_story_1016_10161201_99_dialog_content = "O Darkflow está se reunindo abaixo de nós em algum lugar...",
  ui_story_1016_10161201_100_dialog_content = "Espere, isso é...?",
  ui_story_1016_10161201_101_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10161201_102_dialog_content = "Isso é <color=#FFB400>Figerald!</color>!!!",
  ui_story_1016_10161201_103_dialog_content = "você está falando sobre isso <color=#FFB400>fantasma</color>?! Onde ele está?!",
  ui_story_1016_10161201_104_dialog_content = "Diretamente abaixo de nós! É muito perto, também!",
  ui_story_1016_10161201_105_dialog_content = "Abaixo de nós, hein...?",
  ui_story_1016_10161201_106_dialog_content = "(Já estamos perto da parte mais profunda de Gannon City. A única coisa abaixo de nós é <color=#FFB400>do guardião um</color> mainframe.)",
  ui_story_1016_10161201_107_dialog_content = "(Eclipse está indo atrás do Guardião Um?!)",
  ui_story_1016_10161201_108_dialog_content = "Precisamos nos apressar! Me siga!",
  ui_story_1016_10161201_109_dialog_content = "As pessoas que construíram esta maldita Cidade Baixa deviam ter cérebros de vermes.",
  ui_story_1016_10161201_110_dialog_content = "Por que mais eles teriam tornado tão difícil navegar?!",
  ui_story_1016_10161201_111_dialog_content = "Segure-o aí, Wraith!",
  ui_story_1016_10161201_112_dialog_content = "Não há para onde correr! Entregue-se e venha em paz!",
  ui_story_1016_10161201_113_dialog_content = "O que? Mas como isso poderia ser?!",
  ui_story_1016_10161201_114_dialog_content = "Eles deveriam ter lidado com todos os aurorianos intrometidos até agora...",
  ui_story_1016_10161201_114X1_dialog_content = "Huh? Onde é <color=#FFB400>ela</color>? ela já foi <color=#FFB400>lá</color>?",
  ui_story_1016_10161201_115_dialog_content = "Malditos sejam todos! Não há ninguém de quem eu possa depender?!",
  ui_story_1016_10161201_116_dialog_content = "Parem-nos, seus miseráveis! Eu te comando!",
  ui_story_1016_10161201_117_dialog_content = "<anim type=Shake><size=45>Graagh!!!</size></anim>",
  ui_story_1016_10161201_118_dialog_content = "Preparem-se, todos!!!",
  ui_story_1016_10161301_1_dialog_content = "Por muito tempo, eu sempre tive a mesma pergunta em mente -",
  ui_story_1016_10161301_2_dialog_content = "Qual é a coisa mais importante para a Federação Illumina?",
  ui_story_1016_10161301_3_dialog_content = "Armamento poderoso e sofisticado?",
  ui_story_1016_10161301_4_dialog_content = "Soldados altamente treinados?",
  ui_story_1016_10161301_5_dialog_content = "Tecnologia de ponta?",
  ui_story_1016_10161301_6_dialog_content = "Eu pensei sobre isso por tanto tempo, mas nunca consegui chegar a uma resposta.",
  ui_story_1016_10161301_7_dialog_content = "Mas então coloquei os pés no campo de batalha.",
  ui_story_1016_10161301_8_dialog_content = "Aí eu vi tudo...",
  ui_story_1016_10161301_9_dialog_content = "Perseverança.",
  ui_story_1016_10161301_10_dialog_content = "Obrigação.",
  ui_story_1016_10161301_11_dialog_content = "Sacrifício.",
  ui_story_1016_10161301_12_dialog_content = "Naquele momento, finalmente percebi o que era mais importante para a Federação Illumina—",
  ui_story_1016_10161301_13_dialog_content = "Isso é <color=#FFB400>pessoas</color>.",
  ui_story_1016_10161301_14_dialog_content = "Na superfície, Illumina não tem barreiras naturais ou tecnologia antiga para afastar os Eclipsites.",
  ui_story_1016_10161301_15_dialog_content = "O sangue, suor e lágrimas de incontáveis gerações de nosso povo é o que construiu as Cidades Subterrâneas.",
  ui_story_1016_10161301_16_dialog_content = "Quando uma geração passou, a próxima aceitou o desafio sem vacilar. Foi assim durante anos e anos.",
  ui_story_1016_10161301_17_dialog_content = "A vida é uma coisa tão preciosa, mas para o bem de seus camaradas, bem como de suas gerações futuras—",
  ui_story_1016_10161301_18_dialog_content = "Eles se sacrificaram sem hesitar.",
  ui_story_1016_10161301_19_dialog_content = "Mas nenhuma vida deve ser sacrificada por algo tão trivial quanto conflitos internos.",
  ui_story_1016_10161301_20_dialog_content = "Se não for controlado, esse tipo de tragédia sem sentido tende a se repetir.",
  ui_story_1016_10161301_21_dialog_content = "Mesmo se eu derrotar Axelia agora, esses covardes só vão continuar jogando mais pessoas como ela na minha lança...",
  ui_story_1016_10161301_22_dialog_content = "A única razão pela qual eles querem que eu perca para Axelia nada mais é do que retirar meu título de Grande Marechal.",
  ui_story_1016_10161301_23_dialog_content = "Não posso dizer que o título não seja importante, mas não tanto que valha a pena sacrificar a vida do meu povo.",
  ui_story_1016_10161301_24_dialog_content = "De qualquer forma, salvar essa pobre garota deveria vir em primeiro lugar.",
  ui_story_1016_10161301_25_dialog_content = "Por isso...",
  ui_story_1016_10161301_26_dialog_content = "<size=45>Parar-!</size>",
  ui_story_1016_10161301_27_dialog_content = "<anim type=Shake>Eu nunca irei parar...</anim>",
  ui_story_1016_10161301_28_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_1016_10161301_29_dialog_content = "Parar, Axelia. <color=#FFB400>eu me rendo</color>.",
  ui_story_1016_10161301_30_dialog_content = "Se aqueles atrás de você querem tanto que você vença, deixe-os ter o que querem.",
  ui_story_1016_10161301_31_dialog_content = "Eu só quero que você viva, e viva bem.",
  ui_story_1016_10161301_32_dialog_content = "Não como seu canhão de vidro ou um bem valioso, mas como um <color=#FFB400>pessoa</color>.",
  ui_story_1016_10161301_33_dialog_content = "...!",
  ui_story_1016_10161301_34_dialog_content = "O que ela disse agora?",
  ui_story_1016_10161301_35_dialog_content = "Nenhuma idéia. Ainda não consigo ouvi-los.",
  ui_story_1016_10161301_36_dialog_content = "Por que o Grande Marechal deixou cair sua arma? Ela está prestes a usar algum tipo de movimento especial?",
  ui_story_1016_10161301_37_dialog_content = "Você me ouviu agora há pouco, não julgou?",
  ui_story_1016_10161301_38_dialog_content = "O que... O que foi isso, Grande Marechal?",
  ui_story_1016_10161301_39_dialog_content = "Então você pode finalmente me ouvir, hein? Nossa, que coincidência.",
  ui_story_1016_10161301_40_dialog_content = "Eu disse que me rendi. Axelia vitórias.",
  ui_story_1016_10161301_41_dialog_content = "...",
  ui_story_1016_10161301_42_dialog_content = "B-Mas isso é...",
  ui_story_1016_10161301_43_dialog_content = "Pare de protelar e apenas anuncie o vencedor já.",
  ui_story_1016_10161301_44_dialog_content = "Não é educado deixar uma garotinha esperando.",
  ui_story_1016_10161301_45_dialog_content = "U-Entendido... A partida acabou!",
  ui_story_1016_10161301_46_dialog_content = "Grande marechal Reinhardt se rendeu voluntariamente! O vencedor da partida de exibição é—<color=#FFB400>Axelia</color>!",
  ui_story_1016_10161301_47_dialog_content = "<color=#e8d9bb>Enquanto isso, nas profundezas da cidade de Gannon</color>",
  ui_story_1016_10161301_48_dialog_content = "E depois de todo o trabalho que deu para chegar aqui, essas pragas ainda acabaram me seguindo.",
  ui_story_1016_10161301_48X1_dialog_content = "Ela já entrou? Então, de acordo com o plano...",
  ui_story_1016_10161301_49_dialog_content = "Você não vai escapar!",
  ui_story_1016_10161301_50_dialog_content = "<color=#e8d9bb>Bam, bam, bam!</color>",
  ui_story_1016_10161301_51_dialog_content = "Tch! Garotinha persistente, não é?!",
  ui_story_1016_10161301_52_dialog_content = "Então conseguiu chegar até aqui, afinal...",
  ui_story_1016_10161301_53_dialog_content = "Huff... huff... Finalmente pego.",
  ui_story_1016_10161301_53X1_dialog_content = "Celestita, nos encontramos novamente.",
  ui_story_1016_10161301_53X2_dialog_content = "Você realmente salvou o dia no Obelisco do Retorno... Recentemente, eu simplesmente não consigo chutar esse mau humor em que estou sempre.",
  ui_story_1016_10161301_53X3_dialog_content = "O que você está planejando fazer?!",
  ui_story_1016_10161301_53X4_dialog_content = "Eu não vou deixar você escapar desta vez!",
  ui_story_1016_10161301_53X5_dialog_content = "Este é o fim da linha para você! Não há saída!",
  ui_story_1016_10161301_53X6_dialog_content = "Tsk, tsk, tsk... Não fique muito animado.",
  ui_story_1016_10161301_54_dialog_content = "Se não me engano, esse deve ser o nível mais baixo de Gannon City, certo?",
  ui_story_1016_10161301_55_dialog_content = "Este cofre parece extremamente fortificado. Algo realmente importante deve estar lá dentro.",
  ui_story_1016_10161301_56_dialog_content = "O mainframe do Guardian One fica logo atrás dessas portas! Não podemos deixar o Eclipse colocar as mãos nele!",
  ui_story_1016_10161301_57_dialog_content = "O que?! Mas eu pensei que o Guardião Um era ainda mais baixo do que eu!",
  ui_story_1016_10161301_58_dialog_content = "Aquele andróide é apenas um dos muitos terminais de interface do Guardian One.",
  ui_story_1016_10161301_59_dialog_content = "Seu corpo real, por assim dizer, está aqui.",
  ui_story_1016_10161301_60_dialog_content = "Pelo que ouvi, a maioria dos sistemas de defesa de Illumina são controlados automaticamente pelo Guardian One.",
  ui_story_1016_10161301_61_dialog_content = "Se algo acontecesse ao Guardião Um, toda a Illumina estaria em perigo!",
  ui_story_1016_10161301_62_dialog_content = "<size=45>Tsk, tsk, tsk!</size>",
  ui_story_1016_10161301_63_dialog_content = "Você está absolutamente certo, meu amigo de cabelos brancos.",
  ui_story_1016_10161301_64_dialog_content = "Mas já é tarde demais. Nossas forças entraram.",
  ui_story_1016_10161301_65_dialog_content = "O quê?!",
  ui_story_1016_10161301_66_dialog_content = "Como isso é possível? Sem a chave—",
  ui_story_1016_10161301_67_dialog_content = "Vou deixar você descobrir isso por si mesmos.",
  ui_story_1016_10161301_68_dialog_content = "Só mais um pouco, só mais um pouco, e então o Eclipse não...",
  ui_story_1016_10161301_69_dialog_content = "Peguem-nos, meus asseclas! Não os deixe interferir!",
  ui_story_1016_10161301_70_dialog_content = "Grrr!",
  ui_story_1016_10161301_71_dialog_content = "Fiquem todos juntos! Não podemos deixá-lo escapar impune!",
  ui_story_1016_10161302_1_dialog_content = "<color=#e8d9bb>No setor residencial de Gannon City</color>",
  ui_story_1016_10161302_2_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1016_10161302_3_dialog_content = "Este não é um laboratório secreto, ou qualquer coisa do tipo. É apenas uma residência comum.",
  ui_story_1016_10161302_4_dialog_content = "Existe realmente uma passagem para o mundo exterior em algum lugar aqui?",
  ui_story_1016_10161302_5_dialog_content = "Você está indo.",
  ui_story_1016_10161302_6_dialog_content = "Por quê?",
  ui_story_1016_10161302_7_dialog_content = "Porque este é o fim da linha para nós.",
  ui_story_1016_10161302_8_dialog_content = "Illumina desistiu de nós dois. Não adianta mais ficar aqui.",
  ui_story_1016_10161302_9_dialog_content = "Isso mesmo. O Comitê desistiu de nós...",
  ui_story_1016_10161302_10_dialog_content = "Eu... eu me lembro agora...",
  ui_story_1016_10161302_11_dialog_content = "O que você lembra?",
  ui_story_1016_10161302_12_dialog_content = "...",
  ui_story_1016_10161302_13_dialog_content = "Tudo.",
  ui_story_1016_10161302_14_dialog_content = "Minhas memórias passadas, aquela batalha, a espera sem fim...",
  ui_story_1016_10161302_15_dialog_content = "E o desespero.",
  ui_story_1016_10161302_16_dialog_content = "Então você deve estar totalmente ciente de sua situação agora.",
  ui_story_1016_10161302_17_dialog_content = "Tudo que um dia te pertenceu não existe mais.",
  ui_story_1016_10161302_18_dialog_content = "Você não é mais um soldado de Illumina, mas um desertor e um monstro.",
  ui_story_1016_10161302_19_dialog_content = "Então, se você quer viver, me ajude a encontrar a saída.",
  ui_story_1016_10161302_20_dialog_content = "Não será necessário.",
  ui_story_1016_10161302_21_dialog_content = "Nunca houve uma rota de fuga neste lugar.",
  ui_story_1016_10161302_22_dialog_content = "...",
  ui_story_1016_10161302_23_dialog_content = "Hmph, então esse era o seu plano o tempo todo.",
  ui_story_1016_10161302_24_dialog_content = "Não posso dizer que estou surpreso.",
  ui_story_1016_10161302_25_dialog_content = "Entregue sua pesquisa e se renda.",
  ui_story_1016_10161302_26_dialog_content = "Coopere e farei sua morte o mais rápida e indolor possível.",
  ui_story_1016_10161302_27_dialog_content = "Fora do caminho.",
  ui_story_1016_10161302_28_dialog_content = "Afinal, parece que você não está disposto a cooperar.",
  ui_story_1016_10161302_29_dialog_content = "Faça do seu jeito então. Soldados!",
  ui_story_1016_10161302_30_dialog_content = "O que... O que você pensa que está fazendo?!",
  ui_story_1016_10161302_31_dialog_content = "Agarre-os.",
  ui_story_1016_10161302_32_dialog_content = "Entendido!",
  ui_story_1016_10161302_33_dialog_content = "Que presunçoso.",
  ui_story_1016_10161302_34_dialog_content = "<size=45>Defender!</size>",
  ui_story_1016_10161302_35_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1016_10161302_36_dialog_content = "...",
  ui_story_1016_10161302_37_dialog_content = "Não desperdice sua força.",
  ui_story_1016_10161302_38_dialog_content = "Para derrubá-lo, meus soldados foram equipados com um novo tipo de armadura experimental, cortesia do Conselho de Ciência.",
  ui_story_1016_10161302_39_dialog_content = "Você será derrotado muito antes de seus efeitos desaparecerem.",
  ui_story_1016_10161302_40_dialog_content = "Afinal, parece que vocês têm algum cérebro.",
  ui_story_1016_10161302_41_dialog_content = "Mesmo assim, você ainda não passa de um bando de tolos.",
  ui_story_1016_10161302_42_dialog_content = "<color=#e8d9bb>Enquanto isso, na arena</color>",
  ui_story_1016_10161302_43_dialog_content = "Eu venci?",
  ui_story_1016_10161302_44_dialog_content = "Isso mesmo. Você é o vencedor.",
  ui_story_1016_10161302_45_dialog_content = "Agora pare antes que você se machuque ainda mais.",
  ui_story_1016_10161302_46_dialog_content = "...",
  ui_story_1016_10161302_47_dialog_content = "O que? Eu ouvi isso certo?",
  ui_story_1016_10161302_48_dialog_content = "O lendário Reinhardt realmente perder a luta?!",
  ui_story_1016_10161302_49_dialog_content = "Mas como?",
  ui_story_1016_10161302_50_dialog_content = "Isso não pode ser...",
  ui_story_1016_10161302_51_dialog_content = "<size=45>De que diabos vocês estão brincando?!</size>",
  ui_story_1016_10161302_52_dialog_content = "Reinhardt entregar-se? Ela nem estava lutando no seu melhor!",
  ui_story_1016_10161302_53_dialog_content = "Que tipo de tática suja e dissimulada vocês, velhos covardes, usaram para fazer isso acontecer?!",
  ui_story_1016_10161302_54_dialog_content = "Por favor, esteja atento às suas palavras, Comandante Barton. Afinal, esta é uma partida oficial!",
  ui_story_1016_10161302_55_dialog_content = "Calma, Barton.",
  ui_story_1016_10161302_56_dialog_content = "Este não é o momento de deixar sua raiva levar a melhor sobre você.",
  ui_story_1016_10161302_57_dialog_content = "Se essa foi a decisão de Reinhardt, tenho certeza de que ela teve um bom motivo para fazê-lo.",
  ui_story_1016_10161302_58_dialog_content = "Eu confio no julgamento dela, então vamos perguntar a ela sobre isso mais tarde.",
  ui_story_1016_10161302_59_dialog_content = "<size=45>Você está brincando comigo?!</size>",
  ui_story_1016_10161302_60_dialog_content = "<size=45>É realmente assim que termina? Que luta é essa?!</size>",
  ui_story_1016_10161302_61_dialog_content = "Silêncio, todos!",
  ui_story_1016_10161302_62_dialog_content = "Devo pedir que respeitem o resultado desta partida!",
  ui_story_1016_10161302_63_dialog_content = "Que cena animada.",
  ui_story_1016_10161302_64_dialog_content = "Eu acredito que está quase na hora agora.",
  ui_story_1016_10161302_65_dialog_content = "Oficial Ulisses! Tenho uma mensagem urgente para você!",
  ui_story_1016_10161302_66_dialog_content = "Fale.",
  ui_story_1016_10161302_67_dialog_content = "A situação é...",
  ui_story_1016_10161302_68_dialog_content = "Sim, sim... Muito bem, então.",
  ui_story_1016_10161302_69_dialog_content = "Você pode continuar com seus deveres agora.",
  ui_story_1016_10161302_70_dialog_content = "Sim, senhor.",
  ui_story_1016_10161302_71_dialog_content = "May Por favor, me empreste seu microfone, juiz?",
  ui_story_1016_10161302_72_dialog_content = "Mas senhor, isso...",
  ui_story_1016_10161302_73_dialog_content = "Tenho um anúncio urgente para todos—",
  ui_story_1016_10161302_74_dialog_content = "É uma mensagem do Comitê.",
  ui_story_1016_10161302_75_dialog_content = "V-Muito bem, então...",
  ui_story_1016_10161302_76_dialog_content = "Aham... Atenção pessoal. Tenho uma ordem de emergência a declarar.",
  ui_story_1016_10161302_77_dialog_content = "O que? Uma ordem de emergência?",
  ui_story_1016_10161302_78_dialog_content = "Qual ordem de emergência?",
  ui_story_1016_10161302_79_dialog_content = "Esses velhos tolos estão definitivamente tramando algo.",
  ui_story_1016_10161302_80_dialog_content = "Eles estão podres até o âmago, cada um deles.",
  ui_story_1016_10161302_81_dialog_content = "Estou com um mau pressentimento...",
  ui_story_1016_10161302_82_dialog_content = "Momentos atrás, o Comitê recebeu um relatório chocante.",
  ui_story_1016_10161302_83_dialog_content = "Os Oficiais de Inteligência do Comitê encontraram sinais de Forsakin e Helios, dois dos criminosos mais procurados de Illumina, aqui na cidade de Gannon. Graças aos seus esforços, descobrimos o seu paradeiro atual.",
  ui_story_1016_10161302_84_dialog_content = "Impossível! Eu estive encarregado de encontrá-los esse tempo todo! Meus soldados são os que vasculharam a cidade inteira em busca desses dois!",
  ui_story_1016_10161302_85_dialog_content = "Minhas patrulhas e eu ainda não encontramos nenhum sinal de Forsakin!",
  ui_story_1016_10161302_86_dialog_content = "Isso só prova que seus esforços não foram bons o suficiente.",
  ui_story_1016_10161302_87_dialog_content = "Enquanto perseguiam Forsakin, os Oficiais de Inteligência também descobriram uma passagem secreta não encontrada em nenhum de nossos mapas da cidade.",
  ui_story_1016_10161302_88_dialog_content = "Para nossa imensa surpresa, aquele túnel... Leva direto para a área residencial do Grande Marechal Reinhardt.",
  ui_story_1016_10161302_89_dialog_content = "Não querendo desistir do elemento surpresa, os Oficiais de Inteligência continuaram a rastreá-la silenciosamente, apenas para descobrir que ela entrou na casa de Reinhardt.",
  ui_story_1016_10161302_90_dialog_content = "<size=45>O que?! Isso é impossível!!</size>",
  ui_story_1016_10161302_91_dialog_content = "...",
  ui_story_1016_10161302_92_dialog_content = "Então esse era o seu plano o tempo todo...",
  ui_story_1016_10161302_93_dialog_content = "Você está brincando comigo?!",
  ui_story_1016_10161302_94_dialog_content = "Seus malditos codgers...",
  ui_story_1016_10161302_95_dialog_content = "Sempre rápido em caluniar outras pessoas, mesmo que você se recuse a colocar os pés no campo de batalha!",
  ui_story_1016_10161302_96_dialog_content = "Para o seu bem, é melhor você ter provas suficientes para apoiar essas afirmações malucas.",
  ui_story_1016_10161302_97_dialog_content = "Isso mesmo. Minha lâmina não tolerará uma única pessoa que manche a reputação de meu camarada.",
  ui_story_1016_10161302_98_dialog_content = "Por favor, acalmem-se, todos vocês.",
  ui_story_1016_10161302_99_dialog_content = "Eu entendo que esse desenvolvimento é bastante alarmante. O Comitê também não quis acreditar a princípio.",
  ui_story_1016_10161302_100_dialog_content = "Mas, de fato, temos provas inegáveis de irregularidades. Cada patrulha pode atestar a veracidade deste assunto.",
  ui_story_1016_10161302_101_dialog_content = "No momento, esses dois criminosos procurados estão tentando desesperadamente escapar de Gannon City.",
  ui_story_1016_10161302_102_dialog_content = "Isso é um absurdo! Estou indo embora!",
  ui_story_1016_10161302_103_dialog_content = "Devemos apenas sentar aqui e esperar pacientemente que eles nos ataquem?!",
  ui_story_1016_10161302_104_dialog_content = "Por favor, não entrem em pânico, pessoal; atribuímos segurança adicional ao perímetro da arena. Sua segurança é a maior preocupação do Comitê.",
  ui_story_1016_10161302_105_dialog_content = "Sem mais delongas, o Comitê chegou a uma decisão—",
  ui_story_1016_10161302_106_dialog_content = "Reinhardt, você está sob suspeita de ajudar e incitar o inimigo.",
  ui_story_1016_10161302_107_dialog_content = "Como tal, o Comitê decidiu tirar você de seu status de Grande Marechal.",
  ui_story_1016_10161302_108_dialog_content = "Além disso, você deve se submeter totalmente à nossa investigação de seus crimes em potencial.",
  ui_story_1016_10161401_1_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1016_10161401_2_dialog_content = "Intrusão ilegal detectada, invasão ilegal detectada!",
  ui_story_1016_10161401_2X1_dialog_content = "Tem alguém aí! Saia do meu caminho, Wraith!",
  ui_story_1016_10161401_3_dialog_content = "Tsk, mostre um pouco de respeito, e posso até considerar dar-lhe uma morte rápida.",
  ui_story_1016_10161401_4_dialog_content = "Quanto aos outros...",
  ui_story_1016_10161401_5_dialog_content = "Vá agora.",
  ui_story_1016_10161401_6_dialog_content = "<anim type=Shake><size=45>Grahhh—!</size></anim>",
  ui_story_1016_10161401_7_dialog_content = "Flor de Gelo! Espalhar-!",
  ui_story_1016_10161401_8_dialog_content = "<anim type=Shake>Graaah...</anim>",
  ui_story_1016_10161401_9_dialog_content = "(Eclipsian) Nossas forças estão diminuindo, Lorde Figerald...",
  ui_story_1016_10161401_10_dialog_content = "Sua única obrigação é morrer. Então faça com pressa.",
  ui_story_1016_10161401_11_dialog_content = "Apenas dê a ela tempo suficiente, e esses aurorianos com certeza perderão!",
  ui_story_1016_10161401_12_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1016_10161401_24_dialog_content = "Hehe... <size=50>Hahahaha</size>!",
  ui_story_1016_10161401_26_dialog_content = "Eu vou te mostrar! Vou mostrar a todos que ainda mereço meu lugar!",
  ui_story_1016_10161401_27_dialog_content = "(A casa dele? Isso significa que ele está sendo expulso do Eclipse?)",
  ui_story_1016_10161401_28_dialog_content = "Olhe a sua volta.",
  ui_story_1016_10161401_29_dialog_content = "Seus lacaios foram praticamente erradicados.",
  ui_story_1016_10161401_30_dialog_content = "Você é o comandante de nada agora.",
  ui_story_1016_10161401_31_dialog_content = "Comandante de nada, você diz?",
  ui_story_1016_10161401_32_dialog_content = "E daí? Eu sou mais do que suficiente para esmagar seus insetos insignificantes!",
  ui_story_1016_10161401_33_dialog_content = "<anim type=Shake><size=45>Hrrrrgh—!!!</size></anim>",
  ui_story_1016_10161401_34_dialog_content = "O que ele está fazendo?",
  ui_story_1016_10161401_35_dialog_content = "Cuidado, PlayerName!",
  ui_story_1016_10161401_36_dialog_content = "<anim type=Shake><size=45>Tsk, tsk, tsk!</size></anim>",
  ui_story_1016_10161401_37_dialog_content = "Faz tanto tempo desde que libertei meu verdadeiro poder!",
  ui_story_1016_10161401_38_dialog_content = "Eu tenho guardado este ataque para aquela garota miserável de Northland...",
  ui_story_1016_10161401_39_dialog_content = "Mas usá-lo em vocês, tolos, deve ser igualmente satisfatório!",
  ui_story_1016_10161401_40_dialog_content = "Acovardem-se diante de mim, vermes!",
  ui_story_1016_10161401_41_dialog_content = "Aproveite este momento final para fazer as pazes com seus deuses!",
  ui_story_1016_10161402_0X1_dialog_content = "Malditos vermes... Eles realmente me empurraram para tal...",
  ui_story_1016_10161402_0X2_dialog_content = "Morrer! Todos vocês devem morrer!!!",
  ui_story_1016_10161402_0X3_dialog_content = "Atenção! Ele ainda tem algum poder sobrando!",
  ui_story_1016_10161402_0X4_dialog_content = "E você, celestita! Você deveria ter morrido há muito tempo!!!",
  ui_story_1016_10161402_0X5_dialog_content = "Rápido! Voltam, PlayerName!",
  ui_story_1016_10161402_0X6_dialog_content = "Não tente me impedir!",
  ui_story_1016_10161402_0X7_dialog_content = "Ah!",
  ui_story_1016_10161402_0X8_dialog_content = "<color=#e8d9bb>Ampliação!</color>",
  ui_story_1016_10161402_0X9_dialog_content = "(O que-?!)",
  ui_story_1016_10161402_0X10_dialog_content = "(Não toque nela.)",
  ui_story_1016_10161402_0X11_dialog_content = "(Você encontrou? O que você está esperando? Vamos sair daqui—)",
  ui_story_1016_10161402_0X12_dialog_content = "(Tire suas mãos dela.)",
  ui_story_1016_10161402_0X13_dialog_content = "(Não diga que não avisei.)",
  ui_story_1016_10161402_1_dialog_content = "<anim type=Shake><size=45>Argh!</size></anim>",
  ui_story_1016_10161402_2_dialog_content = "<anim type=Shake>Malditos sejam... Seus aurorianos imundos...!</anim>",
  ui_story_1016_10161402_3_dialog_content = "<anim type=Shake>Malditos sejam todos vocês! Maldito Forsakin, e maldito Eclipse também!!!</anim>",
  ui_story_1016_10161402_4_dialog_content = "<anim type=Shake>Todos vocês podem ir para o inferno!!!</anim>",
  ui_story_1016_10161402_4X1_dialog_content = "Ugh...",
  ui_story_1016_10161402_5_dialog_content = "Vice!",
  ui_story_1016_10161402_6_dialog_content = "<anim type=Shake>Se devo morrer, recuso-me a morrer nas mãos de vocês, insetos inúteis!!!</anim>",
  ui_story_1016_10161402_7_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_1016_10161402_7X1_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_1016_10161402_8_dialog_content = "—!!!",
  ui_story_1016_10161402_9_dialog_content = "Você fala demais.",
  ui_story_1016_10161402_10_dialog_content = "COF cof!",
  ui_story_1016_10161402_10X1_dialog_content = "Vice! Você está bem?!",
  ui_story_1016_10161402_11_dialog_content = "Rapidamente! Ele pode estar fingindo a morte para nos fazer baixar a guarda.",
  ui_story_1016_10161402_12_dialog_content = "Eu vou dar uma olhada.",
  ui_story_1016_10161402_13_dialog_content = "...",
  ui_story_1016_10161402_14_dialog_content = "O inimigo está completamente inconsciente. Devemos estar bem por enquanto.",
  ui_story_1016_10161402_15_dialog_content = "Ele conseguiu sobreviver, mas não antes de perder a consciência.",
  ui_story_1016_10161402_15X1_dialog_content = "(Meu ataque agora era realmente tão poderoso?)",
  ui_story_1016_10161402_15X2_dialog_content = "(Isso pode significar...)",
  ui_story_1016_10161402_16_dialog_content = "Então deixe-me acabar com sua miséria e vingar a vida de todos que foram vítimas dele e de sua espécie.",
  ui_story_1016_10161402_17_dialog_content = "Espere! Não o mate!",
  ui_story_1016_10161402_18_dialog_content = "Ahn? Por que não?",
  ui_story_1016_10161402_19_dialog_content = "Você não se lembra do que eu disse antes? Se Forsakin ou qualquer outro Wraiths forem capturados, eles devem ser entregues sob custódia de Illumina.",
  ui_story_1016_10161402_20_dialog_content = "... O que você disser então.",
  ui_story_1016_10161402_21_dialog_content = "Mas dado o estado em que ele se encontra, duvido que responda às suas perguntas tão cedo.",
  ui_story_1016_10161402_22_dialog_content = "Isso não é problema seu. Nós cuidaremos disso.",
  ui_story_1016_10161402_23_dialog_content = "Por que poupá-lo, Yingel? Ele já machucou tanta gente!",
  ui_story_1016_10161402_24_dialog_content = "Por favor acalme-se, PlayerName. Eu sei que você também está chateado.",
  ui_story_1016_10161402_25_dialog_content = "Mas, por favor, considere o seguinte: na história do Astra, não realizamos pesquisas significativas sobre os Wraiths.",
  ui_story_1016_10161402_26_dialog_content = "Além de ser um objeto de pesquisa valioso, Figerald também pode nos fornecer informações cruciais sobre <color=#FFB400>Eclipse</color>.",
  ui_story_1016_10161402_27_dialog_content = "Mais importante, ele foi capaz de entrar neste tipo de lugar sem encontrar resistência...",
  ui_story_1016_10161402_28_dialog_content = "Isso significa que ele confiava em quem lhe forneceu a chave e outras informações.",
  ui_story_1016_10161402_29_dialog_content = "É muito provável que esse informante seja um traidor da Federação Illumina.",
  ui_story_1016_10161402_30_dialog_content = "Você faz pontos válidos, mas ainda não posso concordar com você.",
  ui_story_1016_10161402_31_dialog_content = "Nossa falta de conhecimento dos Wraiths pode ser uma indicação de que não temos como mantê-los sob controle. Nem mesmo a Federação Illumina.",
  ui_story_1016_10161402_32_dialog_content = "O que você fará, se ele finalmente cair em si e escapar de sua custódia?",
  ui_story_1016_10161402_33_dialog_content = "A Federação fará tudo o que estiver ao seu alcance para evitar que isso aconteça.",
  ui_story_1016_10161402_34_dialog_content = "Mas você não pode garantir que isso não acontecerá.",
  ui_story_1016_10161402_35_dialog_content = "Também não podemos abandonar a perspectiva de promover nossa causa só porque os riscos são grandes demais.",
  ui_story_1016_10161402_36_dialog_content = "...",
  ui_story_1016_10161402_37_dialog_content = "Então faça como quiser.",
  ui_story_1016_10161402_38_dialog_content = "Vice, Anatoli, PlayerName, Quais são seus pensamentos sobre isso?",
  ui_story_1016_10161402_39_dialog_content = "Eu não tenho nenhuma objeção.",
  ui_story_1016_10161402_40_dialog_content = "Se esta é a sua decisão, coronel Yingel, então também não tenho objeções.",
  ui_story_1016_10161402_41_option_content = "Sem objeções aqui.",
  ui_story_1016_10161402_42_option_content = "Discordo.",
  ui_story_1016_10161402_43_dialog_content = "Carleen está certa, Yingel. Não podemos arriscar que Figerald fuja",
  ui_story_1016_10161402_44_dialog_content = "Levou tudo o que tínhamos para derrubá-lo desta vez. Não há como dizer o que ele fará se o deixarmos viver!",
  ui_story_1016_10161402_45_dialog_content = "Você tem alguma ideia de quantas vidas ele arruinou...",
  ui_story_1016_10161402_46_dialog_content = "Entendo sua frustração, mas devo insistir em meu próprio curso de ação.",
  ui_story_1016_10161402_47_dialog_content = "Por favor, confie em mim, assim como em seus aliados na Illumina.",
  ui_story_1016_10161402_48_dialog_content = "Tantos dos nossos deram suas vidas para nos ajudar a aprender mais sobre os Eclipsites. Recuso-me a deixar que seus sacrifícios sejam em vão!",
  ui_story_1016_10161402_49_dialog_content = "...",
  ui_story_1016_10161402_50_dialog_content = "...",
  ui_story_1016_10161402_51_dialog_content = "Tá bom.",
  ui_story_1016_10161402_52_dialog_content = "Agradeço por me entender.",
  ui_story_1016_10161402_53_dialog_content = "Vou entrar em contato com o Departamento de Inteligência e fazer com que detenham e interroguem este Wraith imediatamente.",
  ui_story_1016_10161402_54_dialog_content = "Mas nosso trabalho ainda não acabou. Receio que seu bando esteja atrás daquela porta.",
  ui_story_1016_10161402_55_dialog_content = "De fato, e temos o Guardião Um dentro...",
  ui_story_1016_10161402_56_dialog_content = "Bem, não importa quem ou qual seja nosso próximo inimigo, deixe-os fazer o pior!",
  ui_story_1016_10161402_57_dialog_content = "Só espero que tudo isso acabe logo.",
  ui_story_1016_10161402_58_dialog_content = "(não sei como Axelia está fazendo. ela... ainda está viva?)",
  ui_story_1016_10161402_59_dialog_content = "(Estávamos prontos para cumprir nossa missão a todo custo, mas quando a vi ir embora...)",
  ui_story_1016_10161402_60_dialog_content = "Fiquem atentos, todos!",
  ui_story_1016_10161402_61_dialog_content = "Algo está bem atrás daquela porta!",
  ui_story_1016_10161402_62_dialog_content = "(Esta aura...!)",
  ui_story_1016_10161402_63_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_1016_10161402_64_dialog_content = "<color=#e8d9bb>Bwee- Bwee-</color>",
  ui_story_1016_10161402_65_dialog_content = "Prepare-se para mais uma batalha, PlayerName!",
  ui_story_1016_10161402_66_dialog_content = "Fique em formação! Não mostre nenhuma fraqueza!",
  ui_story_1016_10161402_67_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_1016_10161402_68_dialog_content = "Alguém está saindo!",
  ui_story_1016_10161402_69_dialog_content = "É aquele...?!",
  ui_story_1016_10161402_70_dialog_content = "(Eu vi uma figura estranha saindo de trás das portas.)",
  ui_story_1016_10161402_71_dialog_content = "(Foi apenas por um momento, mas senti um Darkflow ainda mais poderoso que o de Figerald vindo de seu corpo.)",
  ui_story_1016_10161402_72_dialog_content = "(Já havíamos usado a maior parte de nossa força lutando contra Figerald.)",
  ui_story_1016_10161402_73_dialog_content = "(Nesse momento, o estranho poderia ter nos derrotado quando quisesse...)",
  ui_story_1016_10161402_74_dialog_content = "Atenção, Vice! Eles estão vindo direto para você!",
  ui_story_1016_10161402_75_dialog_content = "Hã?!",
  ui_story_1016_10161402_76_dialog_content = "Depois de estar em mundos separados por tanto tempo...",
  ui_story_1016_10161402_77_dialog_content = "Por fim, finalmente nos encontramos novamente.",
  ui_story_1016_10161402_78_dialog_content = "Quem é você?",
  ui_story_1016_10161402_79_dialog_content = "(Ela parece uma <color=#FFB400>fantasma</color>!)",
  ui_story_1016_10161402_80_dialog_content = "(Eu nem sei o nome dela, então por que...)",
  ui_story_1016_10161402_81_dialog_content = "(Por que ela parece tão <color=#FFB400>familiar</color>?!)",
  ui_story_1016_10161402_82_dialog_content = "Espere! Não vá!",
  ui_story_1016_10161402_83_dialog_content = "Você saberá tudo em breve...",
  ui_story_1016_10161402_84_dialog_content = "No futuro.",
  ui_story_1016_10161402_85_dialog_content = "Pare ela!",
  ui_story_1016_10161402_86_dialog_content = "ela está carregando <color=#FFB400>o console principal do Guardian One</color>!",
  ui_story_1016_10161402_87_dialog_content = "Brilha!",
  ui_story_1016_10161402_88_dialog_content = "É inútil.",
  ui_story_1016_10161402_89_dialog_content = "I-Não teve efeito?!",
  ui_story_1016_10161402_90_dialog_content = "Depois dela! Não podemos deixá-la escapar com o console principal do Guardian One!",
  ui_story_1016_10161402_91_dialog_content = "<color=#e8d9bb>Enquanto isso, na cidade de Gannon</color>",
  ui_story_1016_10161402_92_dialog_content = "Eles não poderiam ter ido longe. Procure em todos os cantos do lugar.",
  ui_story_1016_10161402_93_dialog_content = "Sim, senhor!",
  ui_story_1016_10161402_94_dialog_content = "...",
  ui_story_1016_10161402_95_dialog_content = "Eles são terrivelmente persistentes.",
  ui_story_1016_10161402_96_dialog_content = "Nesse ritmo, é apenas uma questão de tempo até que eles nos encontrem aqui.",
  ui_story_1016_10161402_97_dialog_content = "Precisamos ir.",
  ui_story_1016_10161402_98_dialog_content = "Este lugar... Parece Undercity 80.",
  ui_story_1016_10161402_99_dialog_content = "Não adianta mais falar essas coisas.",
  ui_story_1016_10161402_100_dialog_content = "Você acha? Talvez você esteja certo...",
  ui_story_1016_10161402_101_dialog_content = "Naquela época... Não éramos diferentes do que somos agora. Preso em uma Cidade Baixa, cercado por inimigos...",
  ui_story_1016_10161402_102_dialog_content = "Só então... Estávamos contra os Eclipsitas... não nossos camaradas...",
  ui_story_1016_10161402_103_dialog_content = "Existe realmente alguma diferença?",
  ui_story_1016_10161402_104_dialog_content = "Tanto quanto eu estou preocupado, qualquer um que esteja no meu caminho é o inimigo.",
  ui_story_1016_10161402_105_dialog_content = "Auroriano, Eclipsita, não faz diferença para mim.",
  ui_story_1016_10161402_106_dialog_content = "Não... Não é a mesma coisa.",
  ui_story_1016_10161402_107_dialog_content = "Eclipsites eram nossos inimigos naturais... Mas nossos camaradas? Eles simplesmente não sabem o que passamos.",
  ui_story_1016_10161402_108_dialog_content = "Isso tudo é um mal-entendido.",
  ui_story_1016_10161402_109_dialog_content = "Não há mal-entendido, Helios.",
  ui_story_1016_10161402_110_dialog_content = "Isso é quem eles realmente são: tolos ignorantes e obedientes cegamente.",
  ui_story_1016_10161402_111_dialog_content = "...",
  ui_story_1016_10161402_112_dialog_content = "O que... O que aconteceu com você... para você acabar assim?",
  ui_story_1016_10161402_113_dialog_content = "Quando seus pensamentos se tornaram tão claros?",
  ui_story_1016_10161402_114_dialog_content = "Aos poucos, nos últimos dias...",
  ui_story_1016_10161402_115_dialog_content = "No começo, parecia que minha mente... estava coberta por uma névoa espessa...",
  ui_story_1016_10161402_116_dialog_content = "Mas agora... as coisas estão um pouco mais claras...",
  ui_story_1016_10161402_117_dialog_content = "É mesmo?",
  ui_story_1016_10161402_118_dialog_content = "Parece que os resultados do meu experimento superaram em muito minhas expectativas.",
  ui_story_1016_10161402_119_dialog_content = "Você ainda... não me respondeu...",
  ui_story_1016_10161402_120_dialog_content = "Diga-me... por que estamos indo embora...",
  ui_story_1016_10161402_121_dialog_content = "Deixe-me... ajudá-lo a voltar para Illumina.",
  ui_story_1016_10161402_122_dialog_content = "Que imaturo.",
  ui_story_1016_10161402_123_dialog_content = "Você realmente esperava que fôssemos bem-vindos aqui? O que exatamente lhe deu essa ideia?",
  ui_story_1016_10161402_124_dialog_content = "Esta é a nossa casa.",
  ui_story_1016_10161402_125_dialog_content = "Nossos amigos e Reinhardt, eles estão esperando por nós.",
  ui_story_1016_10161402_126_dialog_content = "Reinhardt não é meu amigo. Ela me abandonou há muito tempo, assim como abandonou você.",
  ui_story_1016_10161402_127_dialog_content = "Em todos os níveis, Illumina está completamente corrompido.",
  ui_story_1016_10161402_128_dialog_content = "sua raiva...",
  ui_story_1016_10161402_129_dialog_content = "Seu ódio... vai te consumir...",
  ui_story_1016_10161402_130_dialog_content = "Oh sério? Então deixe-me informá-lo sobre a verdade por trás de tudo.",
  ui_story_1016_10161402_131_dialog_content = "Se você ainda quiser acreditar neles depois, não há como ajudá-lo.",
  ui_story_1016_10161402_132_dialog_content = "A verdade?",
  ui_story_1016_10161402_133_dialog_content = "Sim, e a verdade é que fomos todos armas criadas em prol dos interesses de Illumina. Você, eu e até Reinhardt.",
  ui_story_1016_10161402_134_dialog_content = "O Comitê nos submeteu a um programa de modificação experimental chamado Projeto: Sol Artificial para aumentar nossa força.",
  ui_story_1016_10161402_135_dialog_content = "Nossa batalha em Undercity 80 foi apenas um teste para nós, suas valiosas cobaias.",
  ui_story_1016_10161402_136_dialog_content = "Nossa chamada missão estava condenada desde o início.",
  ui_story_1016_10161402_137_dialog_content = "Mas como pode ser isso?!",
  ui_story_1016_10161402_138_dialog_content = "Tantas pessoas... Tantos de nós morreram naquela batalha!",
  ui_story_1016_10161402_139_dialog_content = "Esse era o objetivo deles o tempo todo.",
  ui_story_1016_10161402_140_dialog_content = "O Comitê queria que travássemos uma batalha sem esperança para liberarmos todo o nosso potencial.",
  ui_story_1016_10161402_141_dialog_content = "A maioria de nós foi considerada falha durante o processo de modificação e foi morta em batalha ou acabou da mesma maneira que você.",
  ui_story_1016_10161402_142_dialog_content = "Por que... Por que eles fariam isso?",
  ui_story_1016_10161402_143_dialog_content = "Eu já disse a você, pelo bem do experimento deles. O Projeto Sol Artificial teve uma taxa de sucesso abismalmente baixa ao modificar seus assuntos de teste.",
  ui_story_1016_10161402_144_dialog_content = "A única maneira de realmente avaliar seu sucesso era nos forçar a uma batalha brutal contra os Eclipsitas e ver quem sobreviveu.",
  ui_story_1016_10161402_145_dialog_content = "Reinhardt foi o único que foi considerado um sucesso.",
  ui_story_1016_10161402_146_dialog_content = "O resto de nós foi jogado de lado como lixo.",
  ui_story_1016_10161402_147_dialog_content = "Ainda não entendeu? Então deixe-me simplificar ainda mais, você não é uma pessoa aos olhos da Federação Illumina. Você é uma arma, uma ferramenta e nada mais.",
  ui_story_1016_10161402_148_dialog_content = "Não deixe que eles o enganem com sua conversa sobre família e país. Se você quer sobreviver, precisa começar a pensar por si mesmo.",
  ui_story_1016_10161402_149_dialog_content = "Não há lugar no mundo deles para armas quebradas como nós.",
  ui_story_1016_10161402_150_dialog_content = "Você já viu por si mesmo, não é? A maneira como todos sacam suas armas só de ver você.",
  ui_story_1016_10161402_151_dialog_content = "...",
  ui_story_1016_10161402_152_dialog_content = "Você... Você mesmo disse... Eles são apenas ignorantes...",
  ui_story_1016_10161402_153_dialog_content = "Por isso... precisamos fazer com que eles... vejam as coisas com clareza...",
  ui_story_1016_10161402_154_dialog_content = "E derrubar as pessoas... que os estão mantendo cegos.",
  ui_story_1016_10161402_155_dialog_content = "Isso colocará a Illumina no caminho certo novamente.",
  ui_story_1016_10161402_156_dialog_content = "Precisamos resolver o problema... não chafurdar em nosso ódio.",
  ui_story_1016_10161402_157_dialog_content = "Afinal, você ainda acredita em todas as mentiras deles.",
  ui_story_1016_10161402_158_dialog_content = "Não. Deixei de acreditar há muito tempo.",
  ui_story_1016_10161402_159_dialog_content = "Esta é apenas... minha própria resposta para o problema. Você me disse para pensar por mim mesmo, certo?",
  ui_story_1016_10161402_160_dialog_content = "Se você quiser ir embora, não vou impedi-lo.",
  ui_story_1016_10161402_161_dialog_content = "Mas eu vou ficar aqui. Preciso descobrir toda a verdade... e impedi-los de enviar mais pessoas para a morte.",
  ui_story_1016_10161402_162_dialog_content = "Eu não vou permitir isso.",
  ui_story_1016_10161402_163_dialog_content = "Você é minha cobaia. Até que você não me sirva mais para absolutamente nada, você vem comigo.",
  ui_story_1016_10161402_164_dialog_content = "Não há outra escolha para você.",
  ui_story_1016_10161402_165_dialog_content = "Por aqui! Achei os alvos!",
  ui_story_1016_10161402_166_dialog_content = "Aff.",
  ui_story_1016_10161402_167_dialog_content = "Pragas problemáticas.",
  ui_story_1016_10161402_168_dialog_content = "!!!",
  ui_story_1016_10161402_169_dialog_content = "Não vacile! Seus ataques não funcionarão em você!",
  ui_story_1016_10161402_170_dialog_content = "Ainda não desiste, hein...?",
  ui_story_1016_10161402_171_dialog_content = "Claro que não. Tomamos todas as medidas para garantir que o criminoso mais procurado de Illumina não escape.",
  ui_story_1016_10161402_172_dialog_content = "Fora do caminho!",
  ui_story_1016_10161402_173_dialog_content = "Foco, homens! Não os deixe fugir desta vez!",
  ui_story_1016_10161402_174_dialog_content = "Esquadrão A, forme uma linha defensiva e avance em direção ao inimigo!",
  ui_story_1016_10161402_175_dialog_content = "Esquadrão B, flanqueie-os por trás e interrompa sua fuga!",
  ui_story_1016_10161402_176_dialog_content = "Sim, senhor!",
  ui_story_1016_10161402_177_dialog_content = "Que irritante.",
  ui_story_1016_10161402_178_dialog_content = "O que você está esperando? Vamos, espécime.",
  ui_story_1016_10161402_179_dialog_content = "Não...",
  ui_story_1016_10161402_180_dialog_content = "Eu vou... eu vou segurá-los o máximo que puder. Aproveite esse tempo para escapar.",
  ui_story_1016_10161402_181_dialog_content = "O que pensa que está fazendo?!",
  ui_story_1016_10161402_182_dialog_content = "<size=45>Voltam!</size>",
  ui_story_1016_10161402_183_dialog_content = "Leve-o para baixo!",
  ui_story_1016_10161402_184_dialog_content = "<color=#e8d9bb>Estrondo-!!!</color>",
  ui_story_1016_10161402_185_dialog_content = "Tosse, tosse, tosse...!",
  ui_story_1016_10161402_186_dialog_content = "Ele derrubou o teto e se prendeu do nosso lado!",
  ui_story_1016_10161402_187_dialog_content = "Corra, Negador.",
  ui_story_1016_10161402_188_dialog_content = "Esta é a última coisa que posso fazer por você.",
  ui_story_1016_10161402_189_dialog_content = "Idiota!",
  ui_story_1016_10161402_190_dialog_content = "Seu idiota inacreditável!",
  ui_story_1016_10161402_191_dialog_content = "Correr...",
  ui_story_1016_10161402_192_dialog_content = "Ajudando Forsakin a escapar, vejo...",
  ui_story_1016_10161402_193_dialog_content = "Não importa. Afinal-",
  ui_story_1016_10161402_194_dialog_content = "Você foi nosso alvo principal o tempo todo.",
  ui_story_1016_10161402_195_dialog_content = "Aproveite-o.",
  ui_story_1016_10161402_196_dialog_content = "Sim, senhor!",
  ui_story_1016_10161402_197_dialog_content = "Fique atrás...",
  ui_story_1016_10161402_198_dialog_content = "Eu não quero machucar meus camaradas...",
  ui_story_1016_10161402_199_dialog_content = "Abaixe sua arma!",
  ui_story_1016_10161402_200_dialog_content = "<size=45>Fique atrás!</size>",
  ui_story_1016_10161402_201_dialog_content = "Argh!!!",
  ui_story_1016_10161402_202_dialog_content = "É inútil resistir.",
  ui_story_1016_10161402_203_dialog_content = "...!",
  ui_story_1016_10161402_204_dialog_content = "Segure-o!",
  ui_story_1016_10161402_205_dialog_content = "Nosso alvo principal foi capturado.",
  ui_story_1016_10161402_206_dialog_content = "O alvo secundário escapou, mas não importa.",
  ui_story_1016_10161402_207_dialog_content = "A missão está completa.",
  ui_story_1016_10161402_208_dialog_content = "Agora é esperar o sinal do policial Ulysses.",
  ui_story_1016_10161402_209_dialog_content = "<color=#e8d9bb>De volta à arena</color>",
  ui_story_1016_10161402_210_dialog_content = "Tenente Axelia, por favor, ajude o Comitê apreendendo Reinhardt.",
  ui_story_1016_10161402_211_dialog_content = "...",
  ui_story_1016_10161402_212_dialog_content = "Entendi...",
  ui_story_1016_10161402_213_dialog_content = "Parar, Axelia! Seu corpo já está—",
  ui_story_1016_10161402_214_dialog_content = "...!",
  ui_story_1016_10161402_215_dialog_content = "Axélia!",
  ui_story_1016_10161402_216_dialog_content = "Hmm... Ela já se esforçou demais?",
  ui_story_1016_10161402_217_dialog_content = "Achei que ela duraria um pouco mais.",
  ui_story_1016_10161402_218_dialog_content = "Mas não muda nada. Soldados, prendam-na.",
  ui_story_1016_10161402_219_dialog_content = "Sim, senhor!",
  ui_story_1016_10161402_220_dialog_content = "Parem, todos vocês!",
  ui_story_1016_10161402_221_dialog_content = "Ulisses! Você já deve saber que as ações do Conselho estão completamente fora de linha!",
  ui_story_1016_10161402_222_dialog_content = "Seus velhos covardes estão tentando nos derrubar por tempo suficiente!",
  ui_story_1016_10161402_223_dialog_content = "Vocês idiotas não sabiam disso Reinhardt foi a única pessoa que nos impediu de ir atrás de você?!",
  ui_story_1016_10161402_224_dialog_content = "Mas agora... Agora você realmente conseguiu!",
  ui_story_1016_10161402_225_dialog_content = "Você precisa nos dizer exatamente o que está acontecendo, Grande Marechal.",
  ui_story_1016_10161402_226_dialog_content = "Se eles realmente estão tramando contra nós, lutaremos ao seu lado com tudo o que temos.",
  ui_story_1016_10161402_227_dialog_content = "Por favor, acalmem-se, Comandantes. O Comitê só tem atuado de acordo com nossas regras.",
  ui_story_1016_10161402_228_dialog_content = "Todos vocês, por outro lado, têm violado essas regras para seu próprio benefício. Se alguém está agindo fora da linha, é você.",
  ui_story_1016_10161402_229_dialog_content = "Se você tiver alguma objeção às decisões do Comitê, sinta-se à vontade para apresentá-la por escrito, em vez de recorrer à violência e à intimidação.",
  ui_story_1016_10161402_230_dialog_content = "Filho de uma...",
  ui_story_1016_10161402_231_dialog_content = "Agora devo pedir que todos vocês demonstrem um bom senso de decoro. Caso contrário, o Comitê não terá escolha a não ser rotulá-los como co-conspiradores suspeitos de Reinhardt.",
  ui_story_1016_10161402_232_dialog_content = "Chega.",
  ui_story_1016_10161402_233_dialog_content = "Isso não tem nada a ver com eles.",
  ui_story_1016_10161402_234_dialog_content = "Reinhardt?!",
  ui_story_1016_10161402_235_dialog_content = "Deixa eu me defender, Wrath.",
  ui_story_1016_10161402_236_dialog_content = "Quero ver se posso provar legalmente minha inocência para toda a Illumina.",
  ui_story_1016_10161402_237_dialog_content = "...",
  ui_story_1016_10161402_238_dialog_content = "Está bem.",
  ui_story_1016_10161402_239_dialog_content = "Obrigada...",
  ui_story_1016_10161402_240_dialog_content = "Estou deixando tudo em suas mãos agora.",
  ui_story_1016_10161402_241_dialog_content = "Incluindo aquela garota. Ela está muito mal, então leve-a a cuidados médicos imediatamente.",
  ui_story_1016_10161402_242_dialog_content = "...",
  ui_story_1016_10161402_243_dialog_content = "Grande marechal...?!",
  ui_story_1016_10161402_244_dialog_content = "Grande marechal...",
  ui_story_1016_10161402_245_dialog_content = "...",
  ui_story_1016_10161402_246_dialog_content = "Não precisa mais se incomodar, Ulisses.",
  ui_story_1016_10161402_247_dialog_content = "Eu concordo com sua investigação.",
  ui_story_1016_10161402_248_dialog_content = "Obrigado pela sua colaboração, Reinhardt.",
  ui_story_1016_10161402_249_dialog_content = "Leve-a embora.",
  ui_story_1016_10161402_250_dialog_content = "Sim, senhor!",
  ui_story_1016_10161501_1_dialog_content = "Isso conclui meu relatório.",
  ui_story_1016_10161501_2_dialog_content = "Então, um Wraith não identificado roubou <color=#FFB400>do guardião um</color> console central, e não está em lugar nenhum...",
  ui_story_1016_10161501_3_dialog_content = "Coronel Yingel, isso é um grave abandono do dever.",
  ui_story_1016_10161501_4_dialog_content = "Peço desculpas e estou pronto para aceitar qualquer punição por minha falha.",
  ui_story_1016_10161501_5_dialog_content = "Além das pessoas que estavam lá na época, mais alguém sabe sobre esse assunto?",
  ui_story_1016_10161501_6_dialog_content = "Não senhor. O assunto deve ser conhecido apenas por nós.",
  ui_story_1016_10161501_7_dialog_content = "Todos que estiveram presentes durante o incidente estão reunidos aqui agora. Em nenhum momento eles tiveram a oportunidade de divulgar essas informações.",
  ui_story_1016_10161501_8_dialog_content = "Hmm... Compreendo.",
  ui_story_1016_10161501_9_dialog_content = "Coronel Yingel, você está dispensado de sua missão. Eu me encarregarei pessoalmente de encontrar e capturar o Wraith não identificado.",
  ui_story_1016_10161501_10_dialog_content = "Descanse um pouco por enquanto. O Comitê terá ordens para você em um momento posterior.",
  ui_story_1016_10161501_11_dialog_content = "Quanto ao resto de vocês, por favor, não divulguem nenhuma informação sobre este assunto a mais ninguém.",
  ui_story_1016_10161501_12_dialog_content = "Sim, senhor.",
  ui_story_1016_10161501_13_dialog_content = "Sim, senhor.",
  ui_story_1016_10161501_14_dialog_content = "Entendi.",
  ui_story_1016_10161501_15_dialog_content = "Entendi. Compartilhar essas informações só tornaria as coisas mais difíceis para nós.",
  ui_story_1016_10161501_16_dialog_content = "Vou manter meus lábios selados também.",
  ui_story_1016_10161501_17_dialog_content = "Obrigado a todos pela vossa cooperação.",
  ui_story_1016_10161501_18_dialog_content = "Isso é tudo por enquanto.",
  ui_story_1016_10161501_19_dialog_content = "Espere, posso perguntar como Axelia está fazendo?",
  ui_story_1016_10161501_20_dialog_content = "Tenente Axelia se esforçou demais durante a partida final e está atualmente em um estado inconsciente.",
  ui_story_1016_10161501_21_dialog_content = "Ela está sendo tratada no centro médico, e o Capitão Wrath está cuidando dela.",
  ui_story_1016_10161501_22_dialog_content = "Realmente? Ela ainda está...",
  ui_story_1016_10161501_23_dialog_content = "Eu tenho que ir vê-la agora!",
  ui_story_1016_10161501_24_dialog_content = "Nesse caso, vou me reportar ao Grand Marshal Reinhardt.",
  ui_story_1016_10161501_25_dialog_content = "PlayerName, tenente Vice, Senhora Carleen, Leo... É aqui que nos separamos.",
  ui_story_1016_10161501_26_dialog_content = "Não há necessidade disso.",
  ui_story_1016_10161501_27_dialog_content = "Hum?",
  ui_story_1016_10161501_28_dialog_content = "Reinhardt foi destituída de seu posto. Por enquanto, a Federação Illumina não tem Grande Marechal.",
  ui_story_1016_10161501_29_dialog_content = "<size=45>O quê?!</size>",
  ui_story_1016_10161501_30_option_content = "Você está brincando certo?!",
  ui_story_1016_10161501_31_dialog_content = "O que aconteceu? Por que só estamos ouvindo sobre isso agora?",
  ui_story_1016_10161501_32_option_content = "O que houve?!",
  ui_story_1016_10161501_33_dialog_content = "Por quê foi Reinhardt removido de sua posição?",
  ui_story_1016_10161501_34_dialog_content = "Por favor, acalmem-se todos.",
  ui_story_1016_10161501_35_dialog_content = "Eu entendo que isso é muito repentino, mas aconteceu enquanto você perseguia os Eclipsites escondidos na cidade de Gannon. Naturalmente, você não tinha como saber até agora.",
  ui_story_1016_10161501_36_dialog_content = "Nossas patrulhas encontraram sinais de Forsakin e Helios, dois dos criminosos mais procurados de Illumina, aqui na cidade de Gannon.",
  ui_story_1016_10161501_37_dialog_content = "Eles estão escondidos na cidade há vários dias, esperando a chance de atrapalhar o Exercício Militar Conjunto.",
  ui_story_1016_10161501_38_dialog_content = "Infelizmente, o lugar onde eles estavam escondidos não era outro senão a casa de Reinhardt.",
  ui_story_1016_10161501_39_dialog_content = "Depois de apreendê-los, o Comitê colocou Reinhardt sob suspeita de conspirar com o inimigo e despojou-a de seu posto.",
  ui_story_1016_10161501_40_dialog_content = "Mas como isso seria possível?!",
  ui_story_1016_10161501_41_dialog_content = "Grande marechal Reinhardt nunca ficaria do lado do inimigo!",
  ui_story_1016_10161501_42_dialog_content = "Como já afirmei, ela não é mais a Grande Marechal da Federação Illumina.",
  ui_story_1016_10161501_43_dialog_content = "O Comitê ainda está conduzindo uma investigação completa sobre o assunto. Se ela conseguir provar sua inocência, ela será reintegrada como Grande Marechal.",
  ui_story_1016_10161501_44_dialog_content = "O que exigimos de todos vocês é sua cooperação e compreensão, nada mais.",
  ui_story_1016_10161501_45_dialog_content = "Mas...",
  ui_story_1016_10161501_46_dialog_content = "ainda não compro...",
  ui_story_1016_10161501_47_dialog_content = "Se você \"compra\" ou não é irrelevante. Você só precisa esperar que o Comitê termine sua investigação.",
  ui_story_1016_10161501_48_dialog_content = "Além disso, aqueles de vocês que têm contato próximo e frequente com Reinhardt—",
  ui_story_1016_10161501_49_dialog_content = "Nomeadamente PlayerName, Vice, e Anatoli, também devem se submeter à sua investigação.",
  ui_story_1016_10161501_50_dialog_content = "Você está falando sério?!",
  ui_story_1016_10161501_51_dialog_content = "Um inquérito...?",
  ui_story_1016_10161501_52_dialog_content = "Isso é...",
  ui_story_1016_10161501_53_option_content = "Multar",
  ui_story_1016_10161501_54_dialog_content = "Não tenho nada a esconder, então pergunte o que quiser.",
  ui_story_1016_10161501_55_dialog_content = "Acredito na inocência de Reinhardt. Ela nunca fez nada de errado, até onde eu sei.",
  ui_story_1016_10161501_56_dialog_content = "Bem dito.",
  ui_story_1016_10161501_57_option_content = "E se eu recusar?",
  ui_story_1016_10161501_58_dialog_content = "Eu não estava perguntando agora.",
  ui_story_1016_10161501_59_dialog_content = "Você não tem outra opção a não ser cooperar com a investigação.",
  ui_story_1016_10161501_60_dialog_content = "Isso é jeito de tratar os valiosos convidados do Illumina?",
  ui_story_1016_10161501_61_dialog_content = "Capitão Wrath?!",
  ui_story_1016_10161501_62_dialog_content = "Bem bem. Vice, PlayerName, e assistente de Reinhardt.",
  ui_story_1016_10161501_63_dialog_content = "Capitão Wrath, Devo pedir-lhe que não interfira nos negócios oficiais do Comitê.",
  ui_story_1016_10161501_64_dialog_content = "Não estou aqui para atrapalhar. Só vim te lembrar que ser muito rígido com os outros pode ter um impacto negativo no seu trabalho.",
  ui_story_1016_10161501_65_dialog_content = "...",
  ui_story_1016_10161501_66_dialog_content = "Perdoe-me se minhas palavras soaram um tanto duras.",
  ui_story_1016_10161501_67_dialog_content = "Ficaríamos muito gratos por sua cooperação neste assunto tão importante.",
  ui_story_1016_10161501_68_dialog_content = "Por enquanto, pedimos humildemente que vocês três permaneçam aqui em Illumina até que a investigação seja concluída.",
  ui_story_1016_10161501_69_dialog_content = "...",
  ui_story_1016_10161501_70_dialog_content = "Não é como se tivéssemos escolha, certo?",
  ui_story_1016_10161501_71_dialog_content = "Por favor tente entender.",
  ui_story_1016_10161501_72_dialog_content = "Então isso resolve tudo.",
  ui_story_1016_10161501_73_dialog_content = "PlayerName e o resto de vocês, apenas se acalmem por enquanto. Nada de bom virá de transformar isso em um conflito maior.",
  ui_story_1016_10161501_74_dialog_content = "Multar...",
  ui_story_1016_10161501_75_dialog_content = "Se não houver mais perguntas, todos são dispensados.",
  ui_story_1016_10161501_76_dialog_content = "Com a sua licença, ainda tenho outros assuntos a tratar. Adeus.",
  ui_story_1016_10161501_77_dialog_content = "Ele não perdeu tempo, não é...?",
  ui_story_1016_10161501_78_dialog_content = "O que exatamente aconteceu enquanto estávamos fora, capitão Wrath? Por que o Grande Marechal Reinhardt...",
  ui_story_1016_10161501_79_dialog_content = "Ainda não está claro.",
  ui_story_1016_10161501_80_dialog_content = "Mesmo eu não tenho uma compreensão muito clara do que está acontecendo agora.",
  ui_story_1016_10161501_81_dialog_content = "Tudo o que sei é que agora é a hora errada para entrar em conflito direto com o Comitê.",
  ui_story_1016_10161501_82_dialog_content = "No mínimo, eles adorariam que os atacássemos abertamente, já que isso só prejudicaria ainda mais as chances de Reinhardt.",
  ui_story_1016_10161501_83_dialog_content = "Será que ela vai ficar bem...?",
  ui_story_1016_10161501_84_dialog_content = "...",
  ui_story_1016_10161501_85_dialog_content = "Confie nela.",
  ui_story_1016_10161501_86_dialog_content = "Senhora Carleen—!",
  ui_story_1016_10161501_87_dialog_content = "Eu finalmente encontrei você!",
  ui_story_1016_10161501_88_dialog_content = "O que foi?",
  ui_story_1016_10161501_89_dialog_content = "Acabei de receber uma ligação urgente do Senhor da Cidade! Todos os participantes de Lumopolis no Exercício Militar Conjunto, incluindo você, devem retornar a Lumopolis imediatamente!",
  ui_story_1016_10161501_90_dialog_content = "Uma ordem do Senhor da Cidade...?",
  ui_story_1016_10161501_91_dialog_content = "Entendido. Apenas me dê um momento para juntar minhas coisas primeiro.",
  ui_story_1016_10161501_92_dialog_content = "Sim minha senhora! Estaremos esperando por você!",
  ui_story_1016_10161501_93_dialog_content = "Parece que algo incrível está para acontecer... Ou melhor, já começou.",
  ui_story_1016_10161501_94_dialog_content = "Vou voltar para encontrar Joseph e Zhao, para que possamos planejar nossa viagem de volta a Crepúsculo.",
  ui_story_1016_10161501_95_dialog_content = "Eu vou indo agora. Boa sorte a todos.",
  ui_story_1016_10161501_96_dialog_content = "Você também...",
  ui_story_1016_10161501_97_dialog_content = "<color=#e8d9bb>Enquanto isso, em uma instalação de pesquisa não revelada</color>",
  ui_story_1016_10161501_98_dialog_content = "Hum? Finalmente acordou, não é?",
  ui_story_1016_10161501_99_dialog_content = "Uma vitalidade tão poderosa só pode ser esperada do fruto dos experimentos de Forsakin.",
  ui_story_1016_10161501_100_dialog_content = "Eu lembro de você...",
  ui_story_1016_10161501_101_dialog_content = "Ulisses. Você costumava ser meu comandante.",
  ui_story_1016_10161501_102_dialog_content = "Você não mudou nada.",
  ui_story_1016_10161501_103_dialog_content = "Oh? Então até suas memórias estão lentamente começando a se recuperar?",
  ui_story_1016_10161501_104_dialog_content = "Que surpresa inesperada.",
  ui_story_1016_10161501_105_dialog_content = "Que pena, então, que seus níveis de inteligência ainda sejam tão baixos.",
  ui_story_1016_10161501_106_dialog_content = "...",
  ui_story_1016_10161501_107_dialog_content = "Tem uma coisa que ainda não entendo muito bem. Por que você escolheria seguir as ordens de Forsakin quando claramente não tem intenção de lutar contra nós?",
  ui_story_1016_10161501_108_dialog_content = "Você até se permitiu ser capturado, apenas para que ela pudesse escapar. Por que é que?",
  ui_story_1016_10161501_109_dialog_content = "Eu não estava seguindo suas ordens.",
  ui_story_1016_10161501_110_dialog_content = "Eu sou... um soldado de Illumina...",
  ui_story_1016_10161501_111_dialog_content = "Minhas ordens são para proteger meus camaradas e o povo de Illumina.",
  ui_story_1016_10161501_112_dialog_content = "!",
  ui_story_1016_10161501_113_dialog_content = "Hahaha! Isso realmente é uma grande surpresa!",
  ui_story_1016_10161501_114_dialog_content = "Estou curioso, mas o que ela te disse? Ela disse que as ações do Comitê foram a razão pela qual ela se tornou a pessoa que é hoje?",
  ui_story_1016_10161501_115_dialog_content = "Não, não, claro que não. Tenho certeza de que trair Illumina e todo o seu povo foi uma decisão inteiramente dela.",
  ui_story_1016_10161501_116_dialog_content = "...",
  ui_story_1016_10161501_117_dialog_content = "Que existência lamentável. Vivendo mentira após mentira, e nunca duvidando de nada disso.",
  ui_story_1016_10161501_118_dialog_content = "Mas, em vez disso, acreditando nas palavras de um Eclipsita semiformado sobre as de seus companheiros aurorianos.",
  ui_story_1016_10161501_119_dialog_content = "Ainda assim, não deveria ser nenhuma surpresa. Afinal, você não passa de um produto defeituoso.",
  ui_story_1016_10161501_120_dialog_content = "Só agora, você finalmente tem alguma aparência de valor.",
  ui_story_1016_10161501_121_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_1016_10161501_122_dialog_content = "Digitar.",
  ui_story_1016_10161501_123_dialog_content = "Senhor.",
  ui_story_1016_10161501_124_dialog_content = "Não fui perfeitamente claro? Estou no meio de um experimento importante e ninguém pode me interromper neste momento.",
  ui_story_1016_10161501_125_dialog_content = "Por favor, perdoe-me, mas você tem um convidado muito importante aqui para vê-lo.",
  ui_story_1016_10161501_126_dialog_content = "<color=#FFB400>A Máscara de Ferro</color>, é? Heheheh... Acho que é natural que ela queira me ver.",
  ui_story_1016_10161501_127_dialog_content = "<color=#e8d9bb>Momentos depois, em algum lugar na cidade de Gannon</color>",
  ui_story_1016_10161501_128_dialog_content = "Deixe-me adivinhar: você veio me questionar?",
  ui_story_1016_10161501_129_dialog_content = "Fazer isso agora seria impaciente da minha parte.",
  ui_story_1016_10161501_130_dialog_content = "Eu vim aqui hoje com um único motivo: pedir sua ajuda para confirmar minhas suspeitas.",
  ui_story_1016_10161501_131_dialog_content = "Mas suas suspeitas estão sempre corretas, não estão?",
  ui_story_1016_10161501_132_dialog_content = "Poupe-me de sua bajulação. Não nos serve para nada.",
  ui_story_1016_10161501_133_dialog_content = "Concordo.",
  ui_story_1016_10161501_134_dialog_content = "Agora, então, permita-me resumir o plano até agora.",
  ui_story_1016_10161501_135_dialog_content = "Essencialmente, o plano era derrubar Reinhardt usando os bens descartados de Eclipse para causar pânico e, em seguida, fazer com que seus homens assumam o controle da situação.",
  ui_story_1016_10161501_136_dialog_content = "Infelizmente, Eclipse não apenas quer Forsakin e sua cobaia de volta, mas também o núcleo do Guardião Um.",
  ui_story_1016_10161501_137_dialog_content = "Além disso, um certo grupo de intrometidos indesejados agora está muito ciente do plano.",
  ui_story_1016_10161501_138_dialog_content = "Quem?",
  ui_story_1016_10161501_139_dialog_content = "<color=#FFB400>Crepúsculo</color>.",
  ui_story_1016_10161501_140_dialog_content = "Aquela equipe de Crepúsculo soube do seu plano, e é por isso que eles entregaram a vitória aos seus subordinados.",
  ui_story_1016_10161501_141_dialog_content = "Será que... alguém vazou o plano para eles?",
  ui_story_1016_10161501_142_dialog_content = "Existem outras possibilidades. Para iniciantes...",
  ui_story_1016_10161501_143_dialog_content = "Seus subordinados nunca lutaram com força total.",
  ui_story_1016_10161501_144_dialog_content = "Seu equipamento na fase final era inconsistente com seus créditos.",
  ui_story_1016_10161501_145_dialog_content = "E eles receberam todas as respostas para as perguntas na fase acadêmica com antecedência.",
  ui_story_1016_10161501_146_dialog_content = "...",
  ui_story_1016_10161501_147_dialog_content = "Suas ações foram óbvias demais.",
  ui_story_1016_10161501_148_dialog_content = "Por menor que seja, há uma razão pela qual Illumina e Lumopolis não estão dispostos a provocar a cidade de Crepúsculo.",
  ui_story_1016_10161501_149_dialog_content = "Agora que eles têm a iniciativa, eles se tornaram uma variável na última fase do nosso plano.",
  ui_story_1016_10161501_150_dialog_content = "Seu trabalho agora é garantir que eles se tornem uma variável controlada.",
  ui_story_1016_10161501_151_dialog_content = "Além disso, você deve recuperar o console principal do Guardian One o mais rápido possível.",
  ui_story_1016_10161501_152_dialog_content = "Eu preferiria jogar este jogo da melhor forma possível, em vez de ter a incerteza de muitas variáveis afetando meu desempenho.",
  ui_story_1016_10161501_153_dialog_content = "Entendo... Então farei exatamente isso.",
  ui_story_1016_10161501_154_dialog_content = "Hmph. Você parece bastante confiante em seu experimento, Ulysses.",
  ui_story_1016_10161501_155_dialog_content = "Mas é claro.",
  ui_story_1016_10161501_156_dialog_content = "Assim que eu analisar completamente a pesquisa de Forsakin, isso resultará no maior avanço tecnológico que a Federação Illumina viu em muitos anos.",
  ui_story_1016_10161501_157_dialog_content = "Com esse conhecimento à nossa disposição, poderemos usar o Chord Link em Undercity X para produzir super soldados em massa.",
  ui_story_1016_10161501_158_dialog_content = "Afinal, sejam eles do Programa Phospherus ou do Projeto Sol Artificial, temos muitos temas para escolher.",
  ui_story_1016_10161501_159_dialog_content = "Em breve, a força da Federação Illumina crescerá aos trancos e barrancos.",
  ui_story_1016_10161501_160_dialog_content = "Então é melhor você ser rápido. O tempo é um recurso muito mais precioso do que a luz.",
  ui_story_1016_10161501_161_dialog_content = "Uma última coisa. No final, o que você está fazendo nada mais é do que plagiar o trabalho de Forsakin.",
  ui_story_1016_10161501_162_dialog_content = "Sua integridade como pesquisador profissional permitirá que você faça isso?",
  ui_story_1016_10161501_163_dialog_content = "Isso não será um problema.",
  ui_story_1016_10161501_164_dialog_content = "Para garantir a continuidade de nossa civilização, devemos estar preparados para fazer o que for necessário.",
  ui_story_1016_10161501_165_dialog_content = "<color=#e8d9bb>Vários dias depois, no Gannon City Medical Center</color>",
  ui_story_1016_10161501_166_dialog_content = "(Faz vários dias desde o final da partida final, mas Axelia ainda não acordou.)",
  ui_story_1016_10161501_167_dialog_content = "(Parece que ela quase destruiu seu corpo novamente desta vez.)",
  ui_story_1016_10161501_168_dialog_content = "(Felizmente, os médicos e pesquisadores conseguiram reparar seu corpo rapidamente, devido à experiência da última vez.)",
  ui_story_1016_10161501_169_dialog_content = "(Infelizmente, a extensão de seu dano significa que ninguém sabe quando ela vai acordar.)",
  ui_story_1016_10161501_170_dialog_content = "Nngh...",
  ui_story_1016_10161501_171_dialog_content = "Axelia?!",
  ui_story_1016_10161501_172_dialog_content = "Parece que... acabei de acordar de um longo sonho.",
  ui_story_1016_10161501_173_dialog_content = "Você está... Finalmente acordou...",
  ui_story_1016_10161501_174_dialog_content = "Bom Dia, Yingel.",
  ui_story_1016_10161501_175_dialog_content = "Você parece exausto.",
  ui_story_1016_10161501_176_dialog_content = "Realmente? Talvez um pouco...",
  ui_story_1016_10161501_177_dialog_content = "Como você está se sentindo? Alguma coisa dói?",
  ui_story_1016_10161501_178_dialog_content = "Eu me sinto completamente normal.",
  ui_story_1016_10161501_179_dialog_content = "Mas ainda preciso de mais tempo antes que minhas funções de combate sejam restauradas.",
  ui_story_1016_10161501_180_dialog_content = "Não se preocupe com o combate agora. Você tem sorte de estar vivo, Axelia.",
  ui_story_1016_10161501_181_dialog_content = "...",
  ui_story_1016_10161501_182_dialog_content = "Reinhardt disse algo semelhante para mim durante a nossa batalha.",
  ui_story_1016_10161501_183_dialog_content = "Ouvi dizer que ela se rendeu voluntariamente...",
  ui_story_1016_10161501_184_dialog_content = "Qual é a razão pela qual você ainda está vivo.",
  ui_story_1016_10161501_185_dialog_content = "O que me lembra, aqui está sua medalha de vitória.",
  ui_story_1016_10161501_186_dialog_content = "Illumina tem estado um caos ultimamente, e com você inconsciente, não houve chance de realizar uma cerimônia de premiação adequada.",
  ui_story_1016_10161501_187_dialog_content = "Então isso vai ter que servir.",
  ui_story_1016_10161501_188_dialog_content = "Esta medalha... parece pesada.",
  ui_story_1016_10161501_189_dialog_content = "...",
  ui_story_1016_10161501_190_dialog_content = "Yingel? Posso te fazer uma pergunta?",
  ui_story_1016_10161501_191_dialog_content = "O que foi?",
  ui_story_1016_10161501_192_dialog_content = "Durante nossa batalha, Reinhardt disse algo para mim—",
  ui_story_1016_10161501_193_dialog_content = "Que ela queria que eu vivesse como pessoa.",
  ui_story_1016_10161501_194_dialog_content = "Você pode me dizer o que significa <color=#FFB400>viver como uma pessoa</color>?",
  ui_story_1017_10170101_1_dialog_content = "Você consegue me ouvir, Grande Marechal?",
  ui_story_1017_10170101_2_dialog_content = "Eu posso.",
  ui_story_1017_10170101_3_dialog_content = "Então vamos começar.",
  ui_story_1017_10170101_4_dialog_content = "Eu sou Nemesis, Inspetora Geral da Federação Illumina, juíza que preside este caso.",
  ui_story_1017_10170101_5_dialog_content = "Eu supervisionarei o terceiro julgamento interno referente às suas acusações de auxiliar e abrigar um inimigo e fugitivo, de acordo com a lei da Federação Illumina.",
  ui_story_1017_10170101_6_dialog_content = "De acordo com a Lei de Investigação da Federação Illumina, você tem o direito—",
  ui_story_1017_10170101_7_dialog_content = "Pule o mumbo jumbo.",
  ui_story_1017_10170101_8_dialog_content = "Então começaremos o processo oficial. Você deseja fazer uma declaração sobre as acusações feitas por Ulysses contra você?",
  ui_story_1017_10170101_9_dialog_content = "Reitero que eu realmente não tinha conhecimento de que Forsakin estava escondido em Gannon durante o exercício militar.",
  ui_story_1017_10170101_10_dialog_content = "Não houve conivência de nenhuma forma entre eu e ela.",
  ui_story_1017_10170101_11_dialog_content = "Visto que você manteve essa declaração em todas as três sessões de interrogatório, não posso emitir um julgamento favorável a você.",
  ui_story_1017_10170101_12_dialog_content = "Não era isso que todos vocês queriam?",
  ui_story_1017_10170101_13_dialog_content = "Vamos ser sinceros um com o outro. Qual é o seu objetivo final?",
  ui_story_1017_10170101_14_dialog_content = "Gostaria de dar um testemunho adicional, Meritíssimo.",
  ui_story_1017_10170101_15_dialog_content = "Você pode.",
  ui_story_1017_10170101_16_dialog_content = "De acordo com relatórios de inteligência, antes do exercício, Forsakin e Reinhardt firmaram o seguinte pacto pessoalmente no Instituto X:",
  ui_story_1017_10170101_17_dialog_content = "Reinhardt prometeu a Forsakin que a deixaria partir, desde que Helios ficasse para trás.",
  ui_story_1017_10170101_18_dialog_content = "Yingel e Anatoli podem testemunhar isso.",
  ui_story_1017_10170101_19_dialog_content = "Meritíssimo—",
  ui_story_1017_10170101_20_dialog_content = "<size=30>Não interrompa, Wrath.</size>",
  ui_story_1017_10170101_21_dialog_content = "Por favor, testemunhe, Coronel Yingel.",
  ui_story_1017_10170101_22_dialog_content = "Você só precisa dizer ao juiz se Forsakin fez um acordo com Reinhardt.",
  ui_story_1017_10170101_23_dialog_content = "... Sim.",
  ui_story_1017_10170101_24_dialog_content = "Por que você-",
  ui_story_1017_10170101_25_dialog_content = "Fique quieto, falar fora de hora só piorará a situação para o Grande Marechal.",
  ui_story_1017_10170101_26_dialog_content = "Após o acordo, o réu optou por agir passivamente devido aos laços antigos.",
  ui_story_1017_10170101_27_dialog_content = "Ela ordenou reforços para ajudar na fuga do fugitivo, o que resultou no roubo do núcleo do Guardião Um.",
  ui_story_1017_10170101_28_dialog_content = "Você se declara culpado disso, Grande Marechal?",
  ui_story_1017_10170101_29_dialog_content = "Eu sou parcialmente responsável pelo roubo do núcleo, mas mostre suas provas para as outras acusações.",
  ui_story_1017_10170101_30_dialog_content = "Anatoli.",
  ui_story_1017_10170101_31_dialog_content = "Sim senhor?",
  ui_story_1017_10170101_32_dialog_content = "Reinhardt disse a Forsakin e Helios que, \"Vim buscá-los e trouxe reforços?\"",
  ui_story_1017_10170101_33_dialog_content = "...",
  ui_story_1017_10170101_34_dialog_content = "Sim ou não?",
  ui_story_1017_10170101_35_dialog_content = "Sim...",
  ui_story_1017_10170101_36_dialog_content = "Apresente sua defesa em relação ao depoimento, Grande Marechal.",
  ui_story_1017_10170101_37_dialog_content = "...",
  ui_story_1017_10170101_38_dialog_content = "Eu encerro meu caso, Meritíssimo.",
  ui_story_1017_10170101_39_dialog_content = "(Isso não foi como aconteceu...)",
  ui_story_1017_10170101_40_dialog_content = "(Espere um minuto, se o Coronel Yingel e eu somos as testemunhas...)",
  ui_story_1017_10170101_41_dialog_content = "Você se declara culpado das acusações mencionadas, Grande Marechal? Tem algo mais a dizer?",
  ui_story_1017_10170101_42_dialog_content = "Heh, admito que minha negligência causou a bagunça em que Illumina está agora!",
  ui_story_1017_10170101_43_dialog_content = "Então, se você quer uma declaração minha—",
  ui_story_1017_10170101_44_dialog_content = "Hahaha!",
  ui_story_1017_10170101_45_dialog_content = "É tudo o que eu tenho a dizer, Meritíssimo. Prossiga e dê-me a sentença.",
  ui_story_1017_10170101_46_dialog_content = "...",
  ui_story_1017_10170101_47_dialog_content = "Após a conclusão do terceiro julgamento de Reinhardt, eu declaro...",
  ui_story_1017_10170101_48_dialog_content = "Ex-Grande Marechal Reinhardt da Federação Illumina é acusado do seguinte:",
  ui_story_1017_10170101_49_dialog_content = "Abusando de sua posição e poder para conduzir um acordo secreto com o fugitivo Forsakin, que havia se infiltrado em uma Cidade Baixa da Illumina.",
  ui_story_1017_10170101_50_dialog_content = "A ação mencionada causou o roubo do núcleo do Guardião Um, prejudicou 78 soldados Illumina e seus familiares, e colocou a segurança federal em uma posição vulnerável.",
  ui_story_1017_10170101_51_dialog_content = "O réu se declara culpado por negligência.",
  ui_story_1017_10170101_52_dialog_content = "Mas as evidências são insuficientes para sustentar a acusação de auxiliar um inimigo. Um novo julgamento será realizado quando as condições para um julgamento forem atendidas ou quando ambas as partes puderem apresentar provas suficientes.",
  ui_story_1017_10170101_53_dialog_content = "De acordo com a Lei de Investigação da Federação Illumina, o Departamento Judiciário emite os seguintes julgamentos:",
  ui_story_1017_10170101_54_dialog_content = "O réu será removido da posição de Grande Marechal.",
  ui_story_1017_10170101_55_dialog_content = "O réu será privado de todos os direitos concedidos a um soldado Illumina.",
  ui_story_1017_10170101_56_dialog_content = "O réu será encarcerado, com efeito imediato.",
  ui_story_1017_10170101_57_dialog_content = "Adiado.",
  ui_story_1017_10170101_58_dialog_content = "Ela saiu, ela saiu!",
  ui_story_1017_10170101_59_dialog_content = "M-Senhora!",
  ui_story_1017_10170101_60_dialog_content = "Ah...",
  ui_story_1017_10170101_61_dialog_content = "<size=30>Quem é ela?</size>",
  ui_story_1017_10170101_62_dialog_content = "Oficial Belisaria. Ela tem muito poder sobre o Comitê.",
  ui_story_1017_10170101_63_dialog_content = "Eu estava tão nervoso que esqueci de fazer a saudação.",
  ui_story_1017_10170101_64_option_content = "Você está me deixando nervoso.",
  ui_story_1017_10170101_65_option_content = "Você está acabado.",
  ui_story_1017_10170101_66_dialog_content = "Um pouco de otimismo seria apreciado, obrigado.",
  ui_story_1017_10170101_67_dialog_content = "Bem, é tarde demais para você saudar agora.",
  ui_story_1017_10170101_68_dialog_content = "...",
  ui_story_1017_10170101_69_dialog_content = "Se até ela apareceu... Eu me pergunto se há alguma chance de um desenvolvimento positivo para o Grande Marechal.",
  ui_story_1017_10170101_70_dialog_content = "Senti sua falta mais cedo.",
  ui_story_1017_10170101_71_dialog_content = "Você deve ser o Celestita, certo?",
  ui_story_1017_10170101_72_dialog_content = "Sim... Senhora.",
  ui_story_1017_10170101_73_dialog_content = "Oficial Belisaria!",
  ui_story_1017_10170101_74_dialog_content = "Ouvi dizer que você, o Celestita e seu amigo de Lumópolis participaram do Exercício Militar Conjunto.",
  ui_story_1017_10170101_75_dialog_content = "Sim, senhora.",
  ui_story_1017_10170101_76_dialog_content = "Heheh, nada mal...",
  ui_story_1017_10170101_77_dialog_content = "Tenho essa sensação inexplicável sobre vocês dois.",
  ui_story_1017_10170101_78_dialog_content = "Em breve, você colocará meu palpite à prova.",
  ui_story_1017_10170101_79_dialog_content = "Com licença por agora, Celestita. Na próxima vez que nos encontrarmos, será em um ambiente oficial.",
  ui_story_1017_10170101_80_dialog_content = "...",
  ui_story_1017_10170101_81_dialog_content = "T-Isso me assustou muito...",
  ui_story_1017_10170101_82_dialog_content = "Pelo menos você saudou desta vez.",
  ui_story_1017_10170101_83_dialog_content = "Mas ela continuava nos olhando de um jeito estranho.",
  ui_story_1017_10170101_84_dialog_content = "Talvez eu esteja exagerando...",
  ui_story_1017_10170101_85_dialog_content = "Ei, os generais - Comandante Hiiro!",
  ui_story_1017_10170101_86_dialog_content = "...",
  ui_story_1017_10170101_87_dialog_content = "Provavelmente este não é o lugar para conversar.",
  ui_story_1017_10170101_88_dialog_content = "Todos eles parecem tão sérios...",
  ui_story_1017_10170101_89_dialog_content = "PlayerName, Tenente Vice.",
  ui_story_1017_10170101_90_dialog_content = "Anatoli! Como vão as coisas?",
  ui_story_1017_10170101_91_dialog_content = "...",
  ui_story_1017_10170101_92_dialog_content = "Vamos conversar em algum lugar tranquilo.",
  ui_story_1017_10170101_93_dialog_content = "Comandantes, os Eclipsitas na fronteira têm se agitado. A situação já dura alguns dias.",
  ui_story_1017_10170101_94_dialog_content = "Já pedimos à <color=#FFB400>Equipe de Reconhecimento da Zona Cega</color> para ajustar sua exploração com base nos dados detectados.",
  ui_story_1017_10170101_95_dialog_content = "Ao comparar os dados históricos com o que temos agora, fica muito evidente que os <color=#FFB400>distúrbios da aurora</color> têm sido mais frequentes do que nunca nos últimos 20 anos.",
  ui_story_1017_10170101_96_dialog_content = "O que pode muito bem significar que o Eclipse está preparando uma possível Crise de Darkover.",
  ui_story_1017_10170101_97_dialog_content = "Vocês todos ouviram isso?",
  ui_story_1017_10170101_98_dialog_content = "Quando a última Crise Darkover aconteceu, nós também estávamos sentados aqui.",
  ui_story_1017_10170101_99_dialog_content = "Muitos anos se passaram desde então, e nós também nos tornamos silenciosos.",
  ui_story_1017_10170101_100_dialog_content = "O aumento do Darkover tem algo a ver com o roubo do núcleo do Guardião Um?",
  ui_story_1017_10170101_101_dialog_content = "Claramente, considerando o que o Eclipse tem feito.",
  ui_story_1017_10170101_102_dialog_content = "Mas desta vez, eles colocaram as mãos no núcleo do Guardião Um, o que muda as coisas.",
  ui_story_1017_10170101_103_dialog_content = "Como está indo o rastreamento?",
  ui_story_1017_10170101_104_dialog_content = "Você ouviu o relatório, uma equipe de elite de reconhecimento da Zona Cega foi enviada.",
  ui_story_1017_10170101_105_dialog_content = "Uma equipe de elite de reconhecimento da Zona Escura?",
  ui_story_1017_10170101_106_dialog_content = "Se você se refere a ela, então eu suponho que seja uma equipe de elite.",
  ui_story_1017_10170101_107_dialog_content = "Não é responsabilidade de Essen rastrear o Wraith e recuperar o Guardião Um?",
  ui_story_1017_10170101_108_dialog_content = "Se ele pudesse fazer isso, eu não teria enviado Pepita.",
  ui_story_1017_10170101_109_dialog_content = "Você quer dizer aquele prisioneiro que desertou da Illumina e se juntou à Ordem Verdadeira?",
  ui_story_1017_10170101_110_dialog_content = "Prisioneiro?",
  ui_story_1017_10170101_111_dialog_content = "Vocês não estão exagerando um pouco?",
  ui_story_1017_10170101_112_dialog_content = "Ela deveria estar atrás das grades agora mesmo.",
  ui_story_1017_10170101_113_dialog_content = "Algumas cartas devem ser mantidas por perto até a hora da necessidade.",
  ui_story_1017_10170101_114_dialog_content = "Ela tem experiência em infiltração na Zona Cega. De certa forma, apenas ela pode realizar essa missão.",
  ui_story_1017_10170101_115_dialog_content = "Belisaria, o comitê nunca concedeu a você a autoridade para treinar mercenários particulares sem permissão.",
  ui_story_1017_10170101_116_dialog_content = "Mas é meu dever reabilitar prisioneiros e colocá-los para trabalhar.",
  ui_story_1017_10170101_117_dialog_content = "Quando a outra equipe sai?",
  ui_story_1017_10170101_118_dialog_content = "Comandante, as informações da equipe estão todas organizadas e você pode emitir ordens quando estiver pronto. Eles estão prontos para partir amanhã, no mais cedo.",
  ui_story_1017_10170101_119_dialog_content = "Há outra equipe?",
  ui_story_1017_10170101_120_dialog_content = "Nossas investigações nos mostram que o Tenente Vice tem uma conexão interessante com um dos membros do Eclipse que infiltrou Gannon.",
  ui_story_1017_10170101_121_dialog_content = "Além disso, os três membros de Umbraton que participaram do exercício militar também forneceram pistas de diferentes graus.",
  ui_story_1017_10170101_122_dialog_content = "Levando tudo em consideração, acreditamos que eles possam ser capazes de identificar o núcleo do Guardião Um.",
  ui_story_1017_10170101_123_dialog_content = "Estamos formando uma equipe temporária para dar suporte à Equipe de Reconhecimento da Zona Cega.",
  ui_story_1017_10170101_124_dialog_content = "Vamos lá, você não acredita que esses três patetas são realmente de Umbraton, acredita?",
  ui_story_1017_10170101_125_dialog_content = "Não se deixe levar pelo nariz, Máscara de Ferro.",
  ui_story_1017_10170101_126_dialog_content = "Eu ofereci uma carona a eles porque sei que serão úteis.",
  ui_story_1017_10170101_127_dialog_content = "Por que não ouvimos algumas atualizações suas, Ulysses. Como está indo sua arma?",
  ui_story_1017_10170101_128_dialog_content = "O \"protótipo experimental\" do Forsakin foi autopsiado. Acho que é hora de dar uma nova vida ao Programa Phospherus.",
  ui_story_1017_10170101_129_dialog_content = "Com o Programa Phospherus 2.0, a força de combate dos aurorianos terá uma melhoria significativa.",
  ui_story_1017_10170101_130_dialog_content = "Então agora é o momento perfeito para selecionar o próximo Grande Marechal.",
  ui_story_1017_10170101_131_dialog_content = "Algum candidato adequado?",
  ui_story_1017_10170101_132_dialog_content = "Este é o elo mais fraco do projeto.",
  ui_story_1017_10170101_133_dialog_content = "Estou realmente preocupado que a próxima Crise de Darkover esteja próxima e nos encontraremos indefesos.",
  ui_story_1017_10170101_134_dialog_content = "A candidatura é a parte mais fraca?",
  ui_story_1017_10170101_135_dialog_content = "Discordo.",
  ui_story_1017_10170101_136_dialog_content = "A influência que Reinhardt construiu ao longo dos anos superou todas as expectativas.",
  ui_story_1017_10170101_137_dialog_content = "A situação atual é uma consequência direta do \"Programa Phospherus\". Devemos mesmo continuar com ele?",
  ui_story_1017_10170101_138_dialog_content = "Não há provas suficientes do interrogatório de Reinhardt para condená-la. A demissão dela provavelmente é temporária.",
  ui_story_1017_10170101_139_dialog_content = "Dr. Ulysses, por outro lado... não está se precipitando um pouco?",
  ui_story_1017_10170101_140_dialog_content = "Não adianta discutir algo que já é uma conclusão inevitável.",
  ui_story_1017_10170101_141_dialog_content = "Se você tem um problema, siga os canais adequados e entre com um processo.",
  ui_story_1017_10170101_142_dialog_content = "Ulysses, você deveria deixar de lado sua pesquisa de vez em quando e experimentar o que está acontecendo além destas paredes.",
  ui_story_1017_10170101_143_dialog_content = "Diga que você quer carne. Pediria ao gado para se dirigir ao matadouro por conta própria?",
  ui_story_1017_10170101_144_dialog_content = "Se você quer mostrar sua \"arma definitiva\", vá em frente. Estou tranquilo com isso.",
  ui_story_1017_10170101_145_dialog_content = "Mas quando se trata de selecionar o próximo Grande Marechal, é provavelmente sábio, como você disse, seguir pelos canais apropriados.",
  ui_story_1017_10170101_146_dialog_content = "Chega. Em Illumina, sempre priorizamos resolver questões públicas em vez de brigas pessoais.",
  ui_story_1017_10170101_147_dialog_content = "Já que todos estão aqui, devemos analisar os candidatos a Grande Marechal.",
  ui_story_1017_10170101_148_dialog_content = "Todos os arquivos foram enviados?",
  ui_story_1017_10170101_149_dialog_content = "Sim. Estimados comandantes, o que vocês têm diante de vocês são arquivos detalhados sobre o pessoal militar a partir da patente de coronel e acima.",
  ui_story_1017_10170101_150_dialog_content = "Suas redes de relacionamentos privados e avaliações de colegas também estão incluídas.",
  ui_story_1017_10170101_151_dialog_content = "Quando Illumina foi fundada, houve uma decisão unânime de que o soldado mais poderoso deveria assumir o papel de Grande Marechal.",
  ui_story_1017_10170101_152_dialog_content = "Com o tempo, isso se tornou uma regra não escrita de que o candidato a Grande Marechal deve passar por aprimoramento físico.",
  ui_story_1017_10170101_153_dialog_content = "Não tenho nada contra um Programa Fosferus 2.0. Mas quando se trata de pura capacidade, apenas esses quatro generais são adequados para o papel de Grande Marechal.",
  ui_story_1017_10170101_154_dialog_content = "Se a ideia era apenas cultivar outro Reinhardt entre eles, qual era o objetivo de substituir o Grande Marechal desde o início?",
  ui_story_1017_10170101_155_dialog_content = "Não seria escolher um deles como Grande Marechal um pouco como dar um tiro no próprio pé?",
  ui_story_1017_10170101_156_dialog_content = "O que você acha, Ulisses?",
  ui_story_1017_10170101_157_dialog_content = "...",
  ui_story_1017_10170101_158_dialog_content = "Desses quatro, há um que se encaixa no perfil...",
  ui_story_1017_10170201_1_dialog_content = "Quem estiver lá fora, entre.",
  ui_story_1017_10170201_2_dialog_content = "Uh, saudações, Comandante Hiiro, e a todos vocês!",
  ui_story_1017_10170201_3_dialog_content = "Olá, oficiais.",
  ui_story_1017_10170201_4_dialog_content = "Desculpe incomodar. Estou aqui para ver o Comandante Hiiro, mas não esperava que todos vocês estivessem presentes...",
  ui_story_1017_10170201_5_dialog_content = "Ouvimos falar do Grande Marechal e queríamos—",
  ui_story_1017_10170201_X5_dialog_content = "<color=#e8d9bb>Bip Bip-</color>",
  ui_story_1017_10170201_6_dialog_content = "...",
  ui_story_1017_10170201_7_dialog_content = "Todos, chegaram ordens para nos chamar de volta à zona de guerra.",
  ui_story_1017_10170201_8_dialog_content = "Tão cedo?",
  ui_story_1017_10170201_9_dialog_content = "Também entendi, e nunca vi uma descrição tão breve para uma tarefa antes.",
  ui_story_1017_10170201_10_dialog_content = "Mesmo.",
  ui_story_1017_10170201_11_dialog_content = "Hmph, preocupados que estamos tramando uma rebelião juntos, estão?",
  ui_story_1017_10170201_12_dialog_content = "Tornei-me um general da Federação lutando em guerras. Estou bem em jogar duro!",
  ui_story_1017_10170201_13_dialog_content = "Por precaução, vamos realizar nossas respectivas tarefas separadamente por enquanto. Vamos tocar de ouvido.",
  ui_story_1017_10170201_14_dialog_content = "Claro.",
  ui_story_1017_10170201_15_dialog_content = "E você, Wrath?",
  ui_story_1017_10170201_X15_dialog_content = "O que é?",
  ui_story_1017_10170201_X16_dialog_content = "Você também recebeu as ordens, certo?",
  ui_story_1017_10170201_X17_dialog_content = "... Minha Legião da Guarda sempre foi apenas para mostrar. Vocês serão os primeiros a entrar, de qualquer forma.",
  ui_story_1017_10170201_X18_dialog_content = "Mantenha contato se algo acontecer. Cuide-se.",
  ui_story_1017_10170201_X19_dialog_content = "Tudo bem, se cuide.",
  ui_story_1017_10170201_16_dialog_content = "Eu? <color=#FFB400>Minha Legião de Guardas é apenas uma fachada, de qualquer forma</color>. Vocês são os primeiros. Não vou sair de Gannon tão cedo.",
  ui_story_1017_10170201_17_dialog_content = "Tudo bem, se cuide.",
  ui_story_1017_10170201_18_dialog_content = "...",
  ui_story_1017_10170201_19_dialog_content = "Todos saíram.",
  ui_story_1017_10170201_20_dialog_content = "O que aconteceu? Até o Comandante Hiiro estava...",
  ui_story_1017_10170201_21_dialog_content = "O que você acha que eles estavam discutindo?",
  ui_story_1017_10170201_22_option_content = "Rebelião",
  ui_story_1017_10170201_23_dialog_content = "Posso sentir que as coisas estão muito tensas entre eles e os poderosos.",
  ui_story_1017_10170201_24_dialog_content = "Eles provavelmente estão preocupados com a reação depois do que aconteceu com o Grande Marechal...",
  ui_story_1017_10170201_25_dialog_content = "Shh! Cuidado com o que você fala alto!",
  ui_story_1017_10170201_26_option_content = "Salvando o Grande Marechal",
  ui_story_1017_10170201_27_dialog_content = "A Grande Marechal foi armada. Os comandantes gostariam de libertá-la de alguma forma.",
  ui_story_1017_10170201_28_dialog_content = "Nesse caso, o que podemos fazer...?",
  ui_story_1017_10170201_29_option_content = "Não tenho certeza",
  ui_story_1017_10170201_30_dialog_content = "Eles saíram com tanta pressa. Não pode ser por algo bom.",
  ui_story_1017_10170201_31_dialog_content = "Suspiro, acho que viemos aqui à toa...",
  ui_story_1017_10170201_32_dialog_content = "*Ofegante* Aí está você, Vice!",
  ui_story_1017_10170201_33_dialog_content = "Tenho uma missão urgente para você!",
  ui_story_1017_10170201_34_dialog_content = "São esses os colegas de equipe que vão com você?",
  ui_story_1017_10170201_35_dialog_content = "Vivian saiu com tanta pressa. Ela apenas nos disse o que fazer e desapareceu.",
  ui_story_1017_10170201_36_dialog_content = "É, ela parecia ansiosa. Grandes mudanças estão chegando a Illumina, imagino.",
  ui_story_1017_10170201_37_dialog_content = "Tem muita coisa acontecendo... Não consigo entender nada agora.",
  ui_story_1017_10170201_38_dialog_content = "E agora estou ouvindo até um assobio estranho...",
  ui_story_1017_10170201_39_dialog_content = "Eu também ouço.",
  ui_story_1017_10170201_40_dialog_content = "Eu estive esperando por vocês, passageiros do Barqueiro de Acheron.",
  ui_story_1017_10170201_41_dialog_content = "Oficial Charon! Então estou nesta missão com você?",
  ui_story_1017_10170201_42_dialog_content = "Olá, Vice, e você também, Celestita.",
  ui_story_1017_10170201_43_dialog_content = "Olá, Vice, e você também, Celestita.",
  ui_story_1017_10170201_44_dialog_content = "Olá, Vice, e você também, Celestita.",
  ui_story_1017_10170201_45_dialog_content = "A turma finalmente está toda aqui—Aham, saudações, pessoal.",
  ui_story_1017_10170201_46_dialog_content = "O que vocês estão fazendo aqui?",
  ui_story_1017_10170201_47_dialog_content = "Não esperava, né? Somos membros oficiais do <color=#FFB400>Esquadrão de Rastreamento</color>!",
  ui_story_1017_10170201_48_dialog_content = "Sim, é ótimo ter a oportunidade de viajar com todos!",
  ui_story_1017_10170201_49_dialog_content = "Qual é o motivo disso, Oficial Charon?",
  ui_story_1017_10170201_50_dialog_content = "Todos os três são amigos convidados para andar no Barqueiro de Acheron, assim como você.",
  ui_story_1017_10170201_51_dialog_content = "Amigos?",
  ui_story_1017_10170201_52_dialog_content = "Sim, mas você não está nessa lista, Celestita.",
  ui_story_1017_10170201_53_dialog_content = "Então siga em frente, pois o Barqueiro de Acheron está partindo.",
  ui_story_1017_10170201_54_dialog_content = "Espere, deixe-me entrar no trem!",
  ui_story_1017_10170201_55_dialog_content = "PlayerName, o que você...",
  ui_story_1017_10170201_56_dialog_content = "Diga-me, Celestita, por que eu deveria deixar você entrar?",
  ui_story_1017_10170201_57_option_content = "Estou preocupado com Vice.",
  ui_story_1017_10170201_58_dialog_content = "Vivian disse que há uma chance de essa operação te levar para bem dentro da Zona Escura...",
  ui_story_1017_10170201_59_dialog_content = "Estou preocupado que o inimigo misterioso do exercício militar possa fazer outro movimento em Vice.",
  ui_story_1017_10170201_60_dialog_content = "Então, por favor, me leve com você.",
  ui_story_1017_10170201_61_option_content = "Estou preocupado com você.",
  ui_story_1017_10170201_62_dialog_content = "Vivian disse que Illumina formou um esquadrão de rastreamento, mas eu não imaginava que incluiria esses três.",
  ui_story_1017_10170201_63_dialog_content = "Estou preocupado que eles possam causar problemas para você, então deixe-me ir com você.",
  ui_story_1017_10170201_64_dialog_content = "Naturalmente, meu amigo não se importará, mas para onde estamos indo é cheio de perigos.",
  ui_story_1017_10170201_65_dialog_content = "O destino da nossa jornada pode ser o fim da sua vida.",
  ui_story_1017_10170201_66_dialog_content = "Acredite em mim, eu tenho muita experiência com perigos!",
  ui_story_1017_10170201_67_dialog_content = "PlayerName...",
  ui_story_1017_10170201_68_dialog_content = "Ei, você ouviu isso, Outro Fim? O Celestita quer marchar direto para o inferno conosco!",
  ui_story_1017_10170201_69_dialog_content = "Você não precisa colocar assim...",
  ui_story_1017_10170201_70_dialog_content = "Que pena que eu tenho que pedir para você, que não foi convidado, se afastar para que possamos seguir nosso caminho.",
  ui_story_1017_10170201_71_dialog_content = "Ainda temos muita preparação a fazer antes de enfrentar a Zona Cega.",
  ui_story_1017_10170201_72_dialog_content = "Acho que vou embora agora, PlayerName.",
  ui_story_1017_10170201_73_option_content = "Tchau, Vice.",
  ui_story_1017_10170201_74_dialog_content = "Tem algo que queira me dizer?",
  ui_story_1017_10170201_75_dialog_content = "Sim...",
  ui_story_1017_10170201_76_option_content = "Vice, espere.",
  ui_story_1017_10170201_77_dialog_content = "E?",
  ui_story_1017_10170201_78_dialog_content = "A Zona Escura é muito perigosa, então cuide-se bem.",
  ui_story_1017_10170201_79_dialog_content = "Eu sei, mas eu sempre consigo me livrar dos problemas, não é?",
  ui_story_1017_10170201_80_dialog_content = "Isso é porque...",
  ui_story_1017_10170201_81_dialog_content = "Por causa do quê?",
  ui_story_1017_10170201_82_dialog_content = "De qualquer forma, eu só tenho um mau pressentimento sobre isso...",
  ui_story_1017_10170201_83_dialog_content = "Entendi. Você é um Celestita, tem poderes telecinéticos incríveis, blablabla...",
  ui_story_1017_10170201_84_dialog_content = "Ficarei bem com o Oficial Charon por perto!",
  ui_story_1017_10170201_85_dialog_content = "Tudo bem. Mas se você se meter em grandes problemas, é só... chamar meu nome!",
  ui_story_1017_10170201_86_dialog_content = "Chamar seu nome? Consegue ouvir tão longe assim?",
  ui_story_1017_10170201_87_dialog_content = "Sem ideia, mas tente mesmo assim.",
  ui_story_1017_10170201_88_dialog_content = "Isso é meio estranho... Bem, tchau.",
  ui_story_1017_10170201_89_dialog_content = "Tchau, Vice.",
  ui_story_1017_10170201_90_dialog_content = "<color=#e8d9bb>Tum... Tum...</color>",
  ui_story_1017_10170201_X90_dialog_content = "\"Vice\"...",
  ui_story_1017_10170201_91_dialog_content = "Se tiver perguntas, faça-as.",
  ui_story_1017_10170201_92_dialog_content = "Eu não entendo. Figerald colocou tudo em jogo por você, então como ele acabou da maneira que acabou?",
  ui_story_1017_10170201_93_dialog_content = "Aqueles que causam problemas a si mesmos não acabam bem; não é como se ele não tivesse recebido uma chance.",
  ui_story_1017_10170201_94_dialog_content = "Em suma, o trabalho não foi realizado de forma eficiente e vocês dois merecem ser punidos.",
  ui_story_1017_10170201_95_dialog_content = "É uma pena, porém, que acabei conseguindo o que queria, tornando a missão um sucesso.",
  ui_story_1017_10170201_96_dialog_content = "Já está ocupado comemorando, Anemone?",
  ui_story_1017_10170201_97_dialog_content = "Conseguimos.",
  ui_story_1017_10170201_98_dialog_content = "Deixe-me verificar... Bem, alguma ideia do que é isso, pequena garota Illumina?",
  ui_story_1017_10170201_99_dialog_content = "Não falei para você nunca me chamar assim?",
  ui_story_1017_10170201_100_dialog_content = "Heh, quanta inocência... Vamos lá, me diga o que você sabe.",
  ui_story_1017_10170201_101_dialog_content = "Uma máquina velha. Você passou por todo esse trabalho só por isso?",
  ui_story_1017_10170201_102_dialog_content = "É antigo, de fato. Mas pertence ao <color=#FFB400>Engenheiro</color>. É só que, bem... ficou para trás na cidade de Gannon.",
  ui_story_1017_10170201_103_dialog_content = "O Engenheiro?",
  ui_story_1017_10170201_104_dialog_content = "Parece que você está realmente no escuro, pequena garota Illumina.",
  ui_story_1017_10170201_105_dialog_content = "O Engenheiro existe há mais tempo do que a história da Illumina. A Illumina não seria nada sem ele.",
  ui_story_1017_10170201_106_dialog_content = "O que você está planejando fazer?",
  ui_story_1017_10170201_107_dialog_content = "Devolver as coisas aos seus verdadeiros donos, obviamente. O mundo é muito mais do que você já viu. Quando o Engenheiro despertar, você terá uma perspectiva mais ampla.",
  ui_story_1017_10170201_108_dialog_content = "Oh? Você por acaso está interessado em estender um tapete vermelho para a chegada do Engenheiro...",
  ui_story_1017_10170201_109_dialog_content = "Estendendo-se do Salão do Eclipse até o próprio núcleo de Astra...",
  ui_story_1017_10170201_110_dialog_content = "Um tapete vermelho colossal tecido a partir da mistura do Darkflow e dos remanescentes dos Aurorianos... Tenho certeza de que isso seria um espetáculo impressionante.",
  ui_story_1017_10170201_111_dialog_content = "E o que eu ganho com isso?",
  ui_story_1017_10170201_112_dialog_content = "Trabalhar para o Eclipse já é uma benevolência concedida a você.",
  ui_story_1017_10170201_113_dialog_content = "Chega de conversa fiada, Asmodeus. Você não deveria voltar e fazer o relatório?",
  ui_story_1017_10170201_114_dialog_content = "Você com certeza se diverte nas festas...",
  ui_story_1017_10170201_115_dialog_content = "Que tal isso: você fica responsável por estender o \"tapete vermelho\" e eu prometo que, uma vez concluído o trabalho, haverá um lugar para você dentro do Eclipse.",
  ui_story_1017_10170201_116_dialog_content = "Você sabe muito bem que é mais fácil falar do que fazer.",
  ui_story_1017_10170201_117_dialog_content = "Fique tranquilo. Entre as coisas inúteis que você inventou, há algo surpreendentemente útil. Eu vou trazer para você.",
  ui_story_1017_10170201_118_dialog_content = "Se o Engenheiro soubesse que foi você quem orquestrou tudo isso, ele não iria querer conhecer um de seus parentes Illumina?",
  ui_story_1017_10170201_119_dialog_content = "Vou cuidar disso, mas enquanto isso tenho alguns assuntos pessoais para resolver.",
  ui_story_1017_10170201_120_dialog_content = "Faça como quiser. No entanto, Forsakin, talvez você queira acelerar um pouco as coisas. Seus camaradas da Illumina estão ficando impacientes.",
  ui_story_1017_10170201_121_dialog_content = "Eu já tinha percebido isso. Não precisava que você me dissesse.",
  ui_story_1017_10170201_122_dialog_content = "Concentre-se no seu negócio. Essas pragas irritantes podem ser deixadas para os Eclipsitas.",
  ui_story_1017_10170202_1_dialog_content = "Tudo limpo, Capitã! Os Eclipsitas foram eliminados!",
  ui_story_1017_10170202_2_dialog_content = "Não falei para não me chamar de capitão?",
  ui_story_1017_10170202_3_dialog_content = "Aqueles que correram à frente já foram. Os que você lidou—",
  ui_story_1017_10170202_4_dialog_content = "Isso! É! Tão! Chato!",
  ui_story_1017_10170202_5_dialog_content = "Mas Capitão Pepita, aqueles que estamos seguindo são adversários incrivelmente poderosos!",
  ui_story_1017_10170202_6_dialog_content = "Os dados do Darkflow no painel estão quase no seu pico!",
  ui_story_1017_10170202_7_dialog_content = "É por isso que eu disse para apenas derrubá-los quando aqueles três apareceram.",
  ui_story_1017_10170202_8_dialog_content = "Em vez disso, continuei sendo atrasado por relatórios sobre isso e aquilo... Eu posso tolerar vocês estragando minha diversão, mas não é a sua cabeça que vai rolar por perder nossos alvos!",
  ui_story_1017_10170202_9_dialog_content = "Capitão, estou apenas seguindo o protocolo de reconhecimento, relatando tudo como eu vejo.",
  ui_story_1017_10170202_10_dialog_content = "As anomalias climáticas que detectamos... a taxa em que o Darkflow está se espalhando em direção ao interior do continente... coordenadas a cada quilômetro que avançamos...",
  ui_story_1017_10170202_11_dialog_content = "Tudo bem, tudo bem. Belisaria me prometeu que não haveria nenhuma dessas formalidades.",
  ui_story_1017_10170202_12_dialog_content = "Considerando quantos de vocês existem, não poderiam fazer os relatórios mais rápido?",
  ui_story_1017_10170202_13_dialog_content = "Eh, eu...",
  ui_story_1017_10170202_14_dialog_content = "De qualquer forma, seguindo em frente. Nosso objetivo é rastrear o núcleo do Guardião Um. Recuperá-lo a todo custo é de extrema importância.",
  ui_story_1017_10170202_15_dialog_content = "Sim, Capitão! Devemos continuar na mesma direção de antes?",
  ui_story_1017_10170202_16_dialog_content = "Estamos perto da Zona Cega. Eu dou conta disso. Eu poderia caminhar por esse caminho de olhos fechados.",
  ui_story_1017_10170202_17_dialog_content = "Já? Parece que estamos fazendo um excelente progresso!",
  ui_story_1017_10170202_18_dialog_content = "É uma coisa alcançar, outra é pegar a coisa de volta.",
  ui_story_1017_10170202_19_dialog_content = "Vamos estabelecer algumas regras básicas. Se virmos Eclipsitas tentando nos atrasar novamente, eu dirijo o veículo, vocês descem e limpam o caminho.",
  ui_story_1017_10170202_20_dialog_content = "As coisas estão urgentes, então não vou desacelerar novamente.",
  ui_story_1017_10170202_21_dialog_content = "Sim, Capitão!",
  ui_story_1017_10170202_22_dialog_content = "Mais uma vez, eu não sou seu capitão!",
  ui_story_1017_10170301_1_dialog_content = "O general não entrou em detalhes, mas soldados já estão sendo enviados para as várias zonas de guerra.",
  ui_story_1017_10170301_2_dialog_content = "Mas parece que toda essa coisa de Grande Marechal simplesmente passou, e agora isso...",
  ui_story_1017_10170301_3_dialog_content = "Sem um Grande Marechal na jogada, quem vai dar as ordens daqui em diante?",
  ui_story_1017_10170301_4_dialog_content = "\"Companheiros compatriotas da Illumina, tenho um anúncio muito importante—\"",
  ui_story_1017_10170301_5_dialog_content = "...",
  ui_story_1017_10170301_6_dialog_content = "\"Desde a fundação da Federação Illumina, os Grandes Marechais sempre nos lideraram na luta contra as invasões dos Eclipsitas.\"",
  ui_story_1017_10170301_7_dialog_content = "\"Illumina representa os aurorianos unidos pelos mesmos ideais, e o Grande Marechal sempre fez parte dessa glória.\"",
  ui_story_1017_10170301_8_dialog_content = "\"Agora, no entanto, talvez seja o maior momento de tudo ou nada em nossa história...\"",
  ui_story_1017_10170301_9_dialog_content = "\"Mas mesmo que o caminho seja sombrio, ainda devemos seguir em frente juntos.\"",
  ui_story_1017_10170301_10_dialog_content = "\"Aqui, em nome do Comitê de Assuntos Militares e Políticos da Federação Illumina, declaro a todos os compatriotas—\"",
  ui_story_1017_10170301_11_dialog_content = "\"A nova Grande Marechal está pronta e capacitada para nos liderar na guerra contra os Eclipsitas.\"",
  ui_story_1017_10170301_12_dialog_content = "\"Aqui um brinde ao Grande Marechal—\"",
  ui_story_1017_10170301_13_dialog_content = "\"Wrath, e um novo futuro para a Federação!\"",
  ui_story_1017_10170301_14_dialog_content = "... General Wrath?!",
  ui_story_1017_10170301_15_dialog_content = "... O novo Grande Marechal?!",
  ui_story_1017_10170301_16_dialog_content = "Então acabou sendo o General Wrath, né?",
  ui_story_1017_10170301_17_dialog_content = "O que todos vocês estão fazendo aqui?",
  ui_story_1017_10170301_18_dialog_content = "PlayerName, acabei de receber a notícia de que os Eclipsitas estão atacando o Crepúsculo!",
  ui_story_1017_10170301_19_dialog_content = "Agora?!",
  ui_story_1017_10170301_20_dialog_content = "Sim. Os altos escalões da Illumina não perderam tempo, nem mesmo na substituição do Grande Marechal.",
  ui_story_1017_10170301_21_dialog_content = "Os estranhos acontecimentos durante o exercício militar, o ex-marechal preso, Eclipsitas inquietos nas fronteiras... Tudo isso não pode ser coincidência.",
  ui_story_1017_10170301_22_dialog_content = "(E Vice foi enviado para a Zona Escura em uma missão...)",
  ui_story_1017_10170301_23_dialog_content = "Não temos tempo para dissecar isso agora, PlayerName.",
  ui_story_1017_10170301_24_dialog_content = "Ouvi dizer que seu Colossus foi consertado. Estou aqui para pedir uma carona de volta ao Crepúsculo.",
  ui_story_1017_10170301_25_dialog_content = "É o caminho mais rápido de volta que consigo pensar.",
  ui_story_1017_10170301_26_dialog_content = "Não sou contra isso, exceto que Gronru ainda está fazendo ajustes em Soroz.",
  ui_story_1017_10170301_27_dialog_content = "É por isso que estou aqui.",
  ui_story_1017_10170301_28_dialog_content = "Ainda estou longe de entender completamente o Soroz, mas ele pode decolar a qualquer momento.",
  ui_story_1017_10170301_29_dialog_content = "Sério?",
  ui_story_1017_10170301_30_dialog_content = "De nada.",
  ui_story_1017_10170301_31_dialog_content = "Por favor, PlayerName! A viagem não será fácil, mas eu preciso voltar e ajudar Twilight.",
  ui_story_1017_10170301_32_dialog_content = "Então vamos!",
  ui_story_1017_10170301_33_dialog_content = "Vocês vão, Leo. Eu vou tentar Lumopolis.",
  ui_story_1017_10170301_34_dialog_content = "Lumópolis? Até mesmo Carleen não conseguiu fazer nada. O que te faz pensar que você pode?",
  ui_story_1017_10170301_35_dialog_content = "Eu não acho que a situação possa ser pior do que aqui.",
  ui_story_1017_10170301_36_dialog_content = "Vocês voltem com PlayerName. Pela nossa cidade, eu tenho que tentar, não importa o quão difícil seja.",
  ui_story_1017_10170301_37_dialog_content = "...",
  ui_story_1017_10170301_38_dialog_content = "É assim que você realmente se sente?",
  ui_story_1017_10170301_39_dialog_content = "Sim, Crepúsculo está em apuros e os Cavaleiros Ironthorn não podem salvá-lo sem você.",
  ui_story_1017_10170301_40_dialog_content = "Confie em mim, meu objetivo é descobrir o que está acontecendo em Crepúsculo, e ir a Lumopolis em busca de ajuda também faz parte do plano.",
  ui_story_1017_10170301_41_dialog_content = "Você sabe o que pode acontecer se estivermos sem nosso estrategista na batalha.",
  ui_story_1017_10170301_42_dialog_content = "Você tem PlayerName com você. Vai ficar bem - ainda melhor, na verdade.",
  ui_story_1017_10170301_43_dialog_content = "E daí? Você lidera os soldados e mata os Eclipsitas, eu trago boas notícias depois.",
  ui_story_1017_10170301_44_dialog_content = "O que você acha, Pai?",
  ui_story_1017_10170301_45_dialog_content = "Eu tenho fé em todos vocês.",
  ui_story_1017_10170301_46_dialog_content = "Eu vou dar tudo de mim!",
  ui_story_1017_10170301_47_dialog_content = "Então, esse é o plano.",
  ui_story_1017_10170301_48_dialog_content = "Tomar cuidado.",
  ui_story_1017_10170301_49_dialog_content = "Tomar cuidado.",
  ui_story_1017_10170301_50_dialog_content = "<color=#e8d9bb>Enquanto isso, no laboratório de Ulysses</color>",
  ui_story_1017_10170301_51_dialog_content = "Professor, os dados de simulação de seleção direcional para o primeiro lote de Sementes passaram no teste de significância.",
  ui_story_1017_10170301_52_dialog_content = "Estamos avançando mais rápido do que o esperado. Isso significa que estamos prontos para iniciar os ensaios clínicos?",
  ui_story_1017_10170301_53_dialog_content = "Você ouviu a transmissão. Há um novo Grande Marechal, então não podemos cometer erros.",
  ui_story_1017_10170301_54_dialog_content = "Sim, Professor. Mas seus experimentos de pesquisa nunca encontraram problemas.",
  ui_story_1017_10170301_55_dialog_content = "Bem, eu não acho que devemos nos apegar ao passado.",
  ui_story_1017_10170301_56_dialog_content = "Você é muito humilde, Doutor. Tudo deve estar indo conforme o plano.",
  ui_story_1017_10170301_57_dialog_content = "Você pode sair agora.",
  ui_story_1017_10170301_58_dialog_content = "Sim, professor.",
  ui_story_1017_10170301_59_dialog_content = "Para chegar ao resultado esperado, um experimento deve passar por ajustes regulares.",
  ui_story_1017_10170301_60_dialog_content = "É Wrath quem você esperava?",
  ui_story_1017_10170301_61_dialog_content = "Você sabe o que eu acho.",
  ui_story_1017_10170301_62_dialog_content = "Eu tenho apenas um objetivo. Posso aceitar quaisquer mudanças, desde que não prejudiquem a estabilidade da Illumina.",
  ui_story_1017_10170301_63_dialog_content = "O Programa Phospherus 2.0 é aceitável para você?",
  ui_story_1017_10170301_64_dialog_content = "Os Eclipsitas já estão batendo na porta da frente do Crepúsculo. O último movimento do Eclipse é praticamente feito sob medida para o seu projeto.",
  ui_story_1017_10170301_65_dialog_content = "Nunca confie em nada quando se trata de lutar contra os Eclipsitas.",
  ui_story_1017_10170301_66_dialog_content = "Assim que a Crise Darkover terminou, eu sabia que deveria mergulhar na bio-modificação dos aurorianos.",
  ui_story_1017_10170301_67_dialog_content = "E, ao longo dos anos, percebi lentamente que a Semente de Forsakin é um componente vital.",
  ui_story_1017_10170301_68_dialog_content = "Espero que suas intenções estejam alinhadas com as minhas. Devo lembrá-lo de que o ciúme é um pecado entre os cientistas.",
  ui_story_1017_10170301_69_dialog_content = "Você não veio aqui para aconselhamento psicológico, veio?",
  ui_story_1017_10170301_70_dialog_content = "Conversaremos em outro dia. Por enquanto, quero saber se seus planos para o Programa Phospherus 2.0 estão de acordo com os meus.",
  ui_story_1017_10170301_71_dialog_content = "Já que a melhor maneira de receber um novo Grande Marechal é com uma vitória.",
  ui_story_1017_10170301_72_dialog_content = "Não é apenas a Ira. Espero que a legião dela estreie no campo de batalha com uma presença totalmente nova.",
  ui_story_1017_10170301_73_dialog_content = "Sabe, Máscara de Ferro, eu não acho que você seja tão imparcial quanto seu apelido sugere.",
  ui_story_1017_10170301_74_dialog_content = "Honra, fama, adoração do público... Teria sido melhor se você se tornasse Grande Marechal.",
  ui_story_1017_10170301_75_dialog_content = "Sei, pelos meus quarenta anos de experiência, que comandar uma defesa é muito mais difícil do que lançar um ataque.",
  ui_story_1017_10170301_76_dialog_content = "Os jovens têm o seu próprio destino e temos de preparar o terreno para eles.",
  ui_story_1017_10170301_77_dialog_content = "Então, deixe Crepúsculo ser o palco para o Phospherus 2.0.",
  ui_story_1017_10170301_78_dialog_content = "Seja Wrath ou os soldados Illuminan, todos farão parte do meu plano...",
  ui_story_1017_10170301_79_dialog_content = "se tornarão estrelas da Federação quando obtiverem uma vitória esmagadora em Crepúsculo.",
  ui_story_1017_10170301_80_dialog_content = "Pode entrar.",
  ui_story_1017_10170301_81_dialog_content = "Professor, o experimento de funcionalidade do Eclipsite de hoje está prestes a começar. Você gostaria de observar?",
  ui_story_1017_10170301_82_dialog_content = "Interessado, Máscara de Ferro? Embora seja apenas um registro de rotina dos dados de habilidade do Eclipsite.",
  ui_story_1017_10170301_83_dialog_content = "Eu vou. Já fiquei sentado neste banco de ferro tempo suficiente.",
  ui_story_1017_10170302_1_dialog_content = "Pode entrar.",
  ui_story_1017_10170302_2_dialog_content = "O exército do Grande Marechal será mobilizado em breve. Há mais alguma coisa a fazer para o experimento?",
  ui_story_1017_10170302_3_dialog_content = "Dê uma olhada nestes relatórios.",
  ui_story_1017_10170302_4_dialog_content = "Os dados... Muito bom, senhor, seu projeto é um sucesso!",
  ui_story_1017_10170302_5_dialog_content = "Obrigado por me permitir fazer parte deste magnífico empreendimento.",
  ui_story_1017_10170302_6_dialog_content = "Está longe de ser suficiente.",
  ui_story_1017_10170302_7_dialog_content = "Significado...?",
  ui_story_1017_10170302_8_dialog_content = "Este é apenas o primeiro lote de sementes. Haverá um segundo, terceiro...",
  ui_story_1017_10170302_9_dialog_content = "Você quer dizer, Crepúsculo é um teste de campo para o primeiro lote?",
  ui_story_1017_10170302_10_dialog_content = "Sim. Os dados clínicos são excelentes, mas a investigação científica é uma caixa de Pandora que é metade milagres e metade destruição.",
  ui_story_1017_10170302_11_dialog_content = "Antes de sabermos tudo o que está nesta caixa, tudo o que podemos fazer é continuar melhorando o experimento. Nossos dados recentes parecem mostrar resultados positivos.",
  ui_story_1017_10170302_12_dialog_content = "Sim, sim, eu entendo...",
  ui_story_1017_10170302_13_dialog_content = "Sinto dúvida em você.",
  ui_story_1017_10170302_14_dialog_content = "Há algo que não tenho certeza se devo dizer.",
  ui_story_1017_10170302_15_dialog_content = "Dê sua opinião.",
  ui_story_1017_10170302_16_dialog_content = "Há rumores na cidade de que soldados ganharam poderes aterrorizantes ao injetar substâncias especiais...",
  ui_story_1017_10170302_17_dialog_content = "Não é um fato?",
  ui_story_1017_10170302_18_dialog_content = "Parcialmente, mas me preocupo que isso afete nossos planos futuros.",
  ui_story_1017_10170302_19_dialog_content = "É só isso?",
  ui_story_1017_10170302_20_dialog_content = "Além disso... Eu me preocupo que o que fizemos no julgamento de Reinhardt volte para nos assombrar.",
  ui_story_1017_10170302_21_dialog_content = "Heh, eu sei onde você quer chegar, Esien.",
  ui_story_1017_10170302_22_dialog_content = "A sua visão é limitada porque você é um dos membros mais jovens do Comitê.",
  ui_story_1017_10170302_23_dialog_content = "Não entendo o que você quer dizer, senhor.",
  ui_story_1017_10170302_24_dialog_content = "Eu tinha as mesmas preocupações quando tinha a sua idade.",
  ui_story_1017_10170302_25_dialog_content = "Segui os procedimentos do experimento à risca e fiz planos de contingência para todos os resultados possíveis...",
  ui_story_1017_10170302_26_dialog_content = "Naquela época, eu realmente gostava da sensação de estar no controle de tudo.",
  ui_story_1017_10170302_27_dialog_content = "Mas é esse mesmo perfeccionismo que me causou grandes perdas.",
  ui_story_1017_10170302_28_dialog_content = "O que você perdeu?",
  ui_story_1017_10170302_29_dialog_content = "Avanços, surpresas, qualquer coisa que possa ser chamada de milagre.",
  ui_story_1017_10170302_30_dialog_content = "Mas senhor, não é “regras, planos, execução, repetição” o apelido que tem sido ensinado aos Illuminanos desde a juventude?",
  ui_story_1017_10170302_31_dialog_content = "Eu reitero. Você ainda é jovem e deveria explorar seu próprio caminho.",
  ui_story_1017_10170302_32_dialog_content = "Ordem é um conceito ridículo. O caos é a verdadeira natureza do mundo.",
  ui_story_1017_10170302_33_dialog_content = "...",
  ui_story_1017_10170302_34_dialog_content = "Tornar-se o melhor cientista da Illumina é o seu sonho, senhor?",
  ui_story_1017_10170302_35_dialog_content = "Não sou isso agora?",
  ui_story_1017_10170302_36_dialog_content = "Você certamente é!",
  ui_story_1017_10170302_37_dialog_content = "Venha comigo inspecionar o próximo lote de Sementes.",
  ui_story_1017_10170302_38_dialog_content = "Sim, senhor.",
  ui_story_1017_10170401_1_dialog_content = "\"Hoje, o Grande Marechal Wrath liderará a Legião da Guarda para reforçar o Crepúsculo e erradicar os Eclipsitas.\"",
  ui_story_1017_10170401_2_dialog_content = "\"Esta é também a estreia do Grande Marechal desde que assumiu o cargo.\"",
  ui_story_1017_10170401_3_dialog_content = "\"É relatado que os soldados devem passar por uma rigorosa seleção e treinamento para se tornarem elites de combate para a Legião da Guarda.\"",
  ui_story_1017_10170401_4_dialog_content = "\"Muitos dos soldados pilotarão a mais nova arma da Illumina, Engine VII, na batalha.\"",
  ui_story_1017_10170401_5_dialog_content = "\"A Terceira Legião, liderada pelo General Hiiro, foi mobilizada.\"",
  ui_story_1017_10170401_6_dialog_content = "\"Muitos soldados e civis de Illumina se reuniram na expectativa da chegada do Grande Marechal.\"",
  ui_story_1017_10170401_7_dialog_content = "Olha! Eles estão aqui—",
  ui_story_1017_10170401_8_dialog_content = "Confira essa formação! Tão imponente...",
  ui_story_1017_10170401_9_dialog_content = "\"Grande Marechal Wrath e a Legião da Guarda estão se aproximando com aplausos entusiasmados!\"",
  ui_story_1017_10170401_10_dialog_content = "\"O Grande Marechal e os soldados parecem confiantes de que a vitória está garantida. É como se isso fosse realmente um desfile de vitória.\"",
  ui_story_1017_10170401_11_dialog_content = "\"Ao lado do Grande Marechal, todos os olhos também estão focados em Engine VII, desenvolvido e construído pelo Oficial de Tecnologia Gronru e sua equipe.\"",
  ui_story_1017_10170401_12_dialog_content = "Dizem que o processo de criação teve que superar vários contratempos. Hoje, trarei os detalhes ao vivo para vocês.",
  ui_story_1017_10170401_13_dialog_content = "Ai! Isso dói...",
  ui_story_1017_10170401_14_dialog_content = "Desculpe...",
  ui_story_1017_10170401_15_dialog_content = "Ei, eu te conheço... Você é Axelia, vencedor da partida de exibição!",
  ui_story_1017_10170401_16_dialog_content = "Você está com a Legião da Guarda! Isso o torna mais impressionante que o Grande Marechal Reinhardt!",
  ui_story_1017_10170401_17_dialog_content = "O Combat Cyborg Axelia foi criado para a Illumina.",
  ui_story_1017_10170401_18_dialog_content = "A Legião da Guarda... São todas assim?",
  ui_story_1017_10170401_19_dialog_content = "Olha o físico deles, é totalmente diferente do nosso...",
  ui_story_1017_10170401_20_dialog_content = "Capaz de liderar esses soldados na guerra, o Grande Marechal Wrath é realmente algo extraordinário...",
  ui_story_1017_10170401_21_dialog_content = "Sim, é evidente que ela é ainda mais poderosa que o Grande Marechal Reinhardt!",
  ui_story_1017_10170401_22_dialog_content = "Você notou o quão sério o General Hiiro parece?",
  ui_story_1017_10170401_23_dialog_content = "Ela sempre parece assim.",
  ui_story_1017_10170401_24_dialog_content = "O Grande Marechal não poderá ouvi-lo se você estiver apenas sussurrando.",
  ui_story_1017_10170401_25_dialog_content = "C-Comandante! Nós estávamos apenas...",
  ui_story_1017_10170401_26_dialog_content = "Você pode salvar as explicações para o seu comandante.",
  ui_story_1017_10170401_27_dialog_content = "Comandante...",
  ui_story_1017_10170401_28_dialog_content = "O que você está fazendo aqui, Coronel Yingel? Não queria perder a primeira aparição pública do novo Grande Marechal?",
  ui_story_1017_10170401_29_dialog_content = "Estou apenas preocupado com Axelia.",
  ui_story_1017_10170401_30_dialog_content = "Sendo ela a obra-prima de Ulisses e tudo mais, com o que você se preocupar?",
  ui_story_1017_10170401_31_dialog_content = "Axelia estava no limite naquela luta, mas Ulysses não achava isso...",
  ui_story_1017_10170401_32_dialog_content = "Você pode ler sua mente, impressionante.",
  ui_story_1017_10170401_33_dialog_content = "Pode não ser justo para os soldados do Programa Phospherus, mas Ulysses realmente sacrificou muito.",
  ui_story_1017_10170401_34_dialog_content = "Então, colocar os Aurorianos em batalha como armas descartáveis não é um sacrifício? O projeto Ulysses está abalando os alicerces de Illumina!",
  ui_story_1017_10170401_35_dialog_content = "A Federação construída sobre a carne e o sangue dos Aurorianos está à beira da extinção e vocês dois ainda ficam do lado dele!",
  ui_story_1017_10170401_36_dialog_content = "Carne e sangue... Você realmente acha que isso sozinho pode afastar os Eclipsitas?",
  ui_story_1017_10170401_37_dialog_content = "Claro que não.",
  ui_story_1017_10170401_38_dialog_content = "Mas nas inúmeras guerras com os Eclipsitas durante todos esses anos, nunca abandonamos nossa dignidade como Aurorianos como estamos fazendo hoje.",
  ui_story_1017_10170401_39_dialog_content = "Os sacrifícios que Axelia, os soldados e você fizeram não nos trarão a paz. Eles apenas deixarão o público com mais medo dos Eclipsitas.",
  ui_story_1017_10170401_40_dialog_content = "Isso não é diferente de nos rendermos a eles!",
  ui_story_1017_10170401_41_dialog_content = "Odeio guerra, mas também não vou me render. Se Illumina precisar de mim, lutarei por Illumina.",
  ui_story_1017_10170401_42_dialog_content = "Lembre-se dessas palavras, Coronel Yingel, ao observar esses soldados prestes a partir para a guerra.",
  ui_story_1017_10170401_43_dialog_content = "Eles provavelmente não percebem o sacrifício que estão prestes a fazer e nem o Axelia, mas você sim.",
  ui_story_1017_10170401_44_dialog_content = "...",
  ui_story_1017_10170401_45_dialog_content = "\"Grande Marechal Wrath assumiu uma posição diante da Legião da Guarda...\"",
  ui_story_1017_10170401_46_dialog_content = "Atenção, todos os soldados Illuminanos!",
  ui_story_1017_10170401_47_dialog_content = "Eu, Grande Marechal Wrath da Federação Illumina, declaro:",
  ui_story_1017_10170401_48_dialog_content = "Os eclipsitas invadiram Crepúsculo, devastando nossos irmãos estacionados lá. Hoje iremos para a fronteira e nos livraremos de todos eles!",
  ui_story_1017_10170401_49_dialog_content = "A Legião da Guarda se reuniu hoje para representar o melhor da Illumina. Você foi escolhido para liderar o batalhão comigo e lutar pela nossa glória.",
  ui_story_1017_10170401_50_dialog_content = "Devemos vencer esta batalha a qualquer custo! Splendor Illumina!",
  ui_story_1017_10170401_51_dialog_content = "Esplendor Illumina!!!",
  ui_story_1017_10170401_52_dialog_content = "Atenção, Comandante Hiiro da 3ª Legião!",
  ui_story_1017_10170401_53_dialog_content = "Sim!",
  ui_story_1017_10170401_54_dialog_content = "Prepare seus homens, envie ordens e aguarde a implantação.",
  ui_story_1017_10170401_55_dialog_content = "Sim!",
  ui_story_1017_10170401_56_dialog_content = "Legião da Guarda, marcha!",
  ui_story_1017_10170401_57_dialog_content = "Sim!!!",
  ui_story_1017_10170401_58_dialog_content = "Você acredita... estamos realmente em espera por ordens?",
  ui_story_1017_10170401_59_dialog_content = "Essa aura... é além de intimidante!",
  ui_story_1017_10170401_60_dialog_content = "Ela acabou de tocar no distintivo de lapela?",
  ui_story_1017_10170401_61_dialog_content = "Sim, eu vi isso.",
  ui_story_1017_10170401_62_dialog_content = "Mesmo assim, ela ainda fez isso.",
  ui_story_1017_10170401_63_dialog_content = "Bem, mas eu me pergunto o que está passando pela cabeça dela agora...",
  ui_story_1017_10170401_64_dialog_content = "...",
  ui_story_1017_10170401_65_dialog_content = "(Então é assim que é ser um Grande Marechal no comando de todo o exército.)",
  ui_story_1017_10170401_66_dialog_content = "(Você deve ter se acostumado com isso depois de todos esses anos, Reinhardt...)",
  ui_story_1017_10170401_67_dialog_content = "(Eu me pergunto o que você estava pensando quando veio aqui pela primeira vez?)",
  ui_story_1017_10170401_68_dialog_content = "(Você já sabia que a posição era sua ou estava feliz que seu esforço incansável e sacrifícios finalmente valeram a pena...?)",
  ui_story_1017_10170401_69_dialog_content = "Acho que você é muito capaz. Vamos ser amigos.",
  ui_story_1017_10170401_70_dialog_content = "Amigos? Eu não preciso de amigos. Tudo que preciso é de treinamento.",
  ui_story_1017_10170401_71_dialog_content = "(Eu continuava lembrando a mim mesmo que a amizade me tornaria fraco, então eu não queria ser seu amigo.)",
  ui_story_1017_10170401_72_dialog_content = "(Fiz de me tornar o Grande Marechal meu objetivo e continuei me aprimorando para isso.)",
  ui_story_1017_10170401_73_dialog_content = "(Mas justamente quando pensei que já tinha chegado longe o suficiente...)",
  ui_story_1017_10170401_74_dialog_content = "Estes são os dispositivos de manipulação de energia mais recentes desenvolvidos pelo departamento de pesquisa. Vamos chamar o Reinhardt para nos dar uma demonstração.",
  ui_story_1017_10170401_75_dialog_content = "Sua?",
  ui_story_1017_10170401_76_dialog_content = "Entre todos vocês, ela é a única capaz de ter controle perfeito.",
  ui_story_1017_10170401_77_dialog_content = "...",
  ui_story_1017_10170401_78_dialog_content = "(Controlar o dispositivo de energia, né? Tudo bem, vou gastar dez vezes mais tempo para aperfeiçoar isso.)",
  ui_story_1017_10170401_79_dialog_content = "(Quando chegar a hora do exercício oficial, não haverá nenhuma lacuna de habilidade entre nós.)",
  ui_story_1017_10170401_80_dialog_content = "Reinhardt, Wrath, vocês dois são uma equipe agora. E Reinhardt, você será responsável por transmitir as ordens de combate.",
  ui_story_1017_10170401_81_dialog_content = "Por que não posso fazer isso?",
  ui_story_1017_10170401_82_dialog_content = "Transmitir ordens de combate afeta diretamente a segurança da sua equipe.",
  ui_story_1017_10170401_83_dialog_content = "Certifique-se de observar e aprender os fundamentos da liderança de equipe enquanto estiver em ação.",
  ui_story_1017_10170401_84_dialog_content = "...",
  ui_story_1017_10170401_85_dialog_content = "(Liderar esquadrões, ser responsável pela segurança dos soldados... Nunca parei de aprender e progredir e, gradualmente, construí seguidores.)",
  ui_story_1017_10170401_86_dialog_content = "Parabéns! Ira da 1ª Legião, você foi promovido a Capitão! Continue o excelente trabalho em missões futuras.",
  ui_story_1017_10170401_87_dialog_content = "(Tudo ocorreu conforme o esperado. Eu só precisava de uma chance para provar a mim mesmo.)",
  ui_story_1017_10170401_88_dialog_content = "(Mas quando os Eclipsitas atacaram a Subcidade 19...)",
  ui_story_1017_10170401_89_dialog_content = "(Fui o primeiro a receber a ordem de apoio, só para você tirar a missão e o crédito de mim...)",
  ui_story_1017_10170401_90_dialog_content = "E a Medalha de Contribuição Illumina vai para—Reinhardt!",
  ui_story_1017_10170401_91_dialog_content = "(Você sempre agiu primeiro e, devido ao quão excepcional você era, muitos critérios desnecessários foram adicionados às avaliações de promoção.)",
  ui_story_1017_10170401_92_dialog_content = "(Eu não tinha ambição de buscar méritos fora do campo de batalha. Os guerreiros tinham que resolver as coisas como guerreiros!)",
  ui_story_1017_10170401_93_dialog_content = "(Então finalmente percebi que não tinha motivos para não desafiá-lo diretamente!)",
  ui_story_1017_10170401_94_dialog_content = "Agora não é hora de agir de acordo com suas emoções. Ainda temos muitos Eclipsites ao nosso redor!",
  ui_story_1017_10170401_95_dialog_content = "Pare com essa porcaria e pegue em armas. Ou você me mata ou reconhece que sou mais poderoso que você.",
  ui_story_1017_10170401_96_dialog_content = "Que imaturo.",
  ui_story_1017_10170401_97_dialog_content = "Pato—",
  ui_story_1017_10170401_98_dialog_content = "Você não precisa matar Eclipsites por mim. Eu disse, levante sua arma e traga-a!",
  ui_story_1017_10170401_99_dialog_content = "Direi novamente, não se deixe levar e foque na batalha!",
  ui_story_1017_10170401_100_dialog_content = "Vá para o inferno—",
  ui_story_1017_10170401_101_dialog_content = "Você vai aceitar meu desafio depois que os Eclipsitas forem resolvidos?",
  ui_story_1017_10170401_102_dialog_content = "Enquanto você viver, o que você quiser.",
  ui_story_1017_10170401_103_dialog_content = "Negócio!",
  ui_story_1017_10170401_104_dialog_content = "Nem pense em ficar no meu caminho, Eclipsites!",
  ui_story_1017_10170502_1_dialog_content = "(Como era familiar para mim terminar cada desafio contra você na mesma posição.)",
  ui_story_1017_10170502_2_dialog_content = "(Seja em treinamento ou em uma luta real, você nunca perdeu nem uma vez. Como conseguiu isso?)",
  ui_story_1017_10170502_3_dialog_content = "(Com isso em mente, nos enfrentamos novamente na batalha final pelo título de Grande Marechal...)",
  ui_story_1017_10170502_4_dialog_content = "O nosso vencedor é... Reinhardt!",
  ui_story_1017_10170502_5_dialog_content = "Parabéns a Reinhardt por se tornar o Grande Marechal da Federação Illumina!",
  ui_story_1017_10170502_6_dialog_content = "Grande Marechal Reinhardt!",
  ui_story_1017_10170502_7_dialog_content = "Embora Wrath possa ter ficado aquém desta vez, sua habilidade como soldado Illumina continua inquestionável.",
  ui_story_1017_10170502_8_dialog_content = "(Eu não posso aceitar isso, ainda não terminei!)",
  ui_story_1017_10170502_9_dialog_content = "(Eu vou te desafiar de novo!)",
  ui_story_1017_10170502_10_dialog_content = "(Mais 100 vezes se eu não conseguir em 10, e mais 1.000 se eu não conseguir em 100!)",
  ui_story_1017_10170502_11_dialog_content = "Vamos voltar. A previsão disse que o tempo está ruim hoje. Provavelmente está chovendo na superfície.",
  ui_story_1017_10170502_12_dialog_content = "Eu não preciso da sua pena.",
  ui_story_1017_10170502_13_dialog_content = "Para mim, você não é alguém para ter pena, mas sim um amigo meu.",
  ui_story_1017_10170502_14_dialog_content = "Amigo?",
  ui_story_1017_10170502_15_dialog_content = "Sim, um amigo que sempre atrapalha e nos faz melhorar juntos.",
  ui_story_1017_10170502_16_dialog_content = "Quem você está chamando de amigo? Nunca fomos camaradas.",
  ui_story_1017_10170502_17_dialog_content = "(Não tenho amigos, nada além de você como alvo.)",
  ui_story_1017_10170502_18_dialog_content = "Lutamos pelo futuro da Illumina, mas deveríamos estar unindo nossos punhos contra um inimigo comum em uma verdadeira batalha.",
  ui_story_1017_10170502_19_dialog_content = "Seu futuro está na palma da sua mão. Mantenha-o fechado e você acabará sem nada.",
  ui_story_1017_10170502_20_dialog_content = "Pegue sua insígnia de Grande Marechal e comemore. Eu continuarei vindo atrás de você.",
  ui_story_1017_10170502_21_dialog_content = "Não vou aliviar para você, mesmo que seja o Grande Marechal.",
  ui_story_1017_10170502_22_dialog_content = "Se você conseguir me vencer, o lugar é seu.",
  ui_story_1017_10170502_23_dialog_content = "Tem tanta certeza de que vai me vencer pelo resto da sua vida?",
  ui_story_1017_10170502_24_dialog_content = "...",
  ui_story_1017_10170502_25_dialog_content = "Está?",
  ui_story_1017_10170502_26_dialog_content = "Sim, estou.",
  ui_story_1017_10170502_27_dialog_content = "Então cuidado, porque eu estou indo atrás de você.",
  ui_story_1017_10170502_28_dialog_content = "Seja o título de Grande Marechal ou qualquer outro, eu vou tirá-lo de você a tempo!",
  ui_story_1017_10170502_29_dialog_content = "(Quem poderia imaginar que eu te substituí, mas não do jeito que eu queria.)",
  ui_story_1017_10170502_30_dialog_content = "(Estou ouvindo aplausos e vaias, mas não sou um fantoche como você.)",
  ui_story_1017_10170502_31_dialog_content = "(Aqueles que esperam que eu me conforme verão apenas outra pessoa...)",
  ui_story_1017_10170502_32_dialog_content = "(Um Grande Marechal teimoso.)",
  ui_story_1017_10170601_1_dialog_content = "<color=#e8d9bb>Na cidade do Crepúsculo, uma multidão de moradores está a caminho do hospital...</color>",
  ui_story_1017_10170601_2_dialog_content = "Aguente um pouco mais. O <color=#FFB400>hospital</color> está logo à frente.",
  ui_story_1017_10170601_3_dialog_content = "Minhas pernas desistiram de mim...",
  ui_story_1017_10170601_4_dialog_content = "Vamos lá. Eu vou te carregar. As zonas de guerra ao redor estão infestadas de Eclipsitas. Não dá para saber se eles virão para cá.",
  ui_story_1017_10170601_5_dialog_content = "Argh! Ai, ai...",
  ui_story_1017_10170601_6_dialog_content = "Coloque-a na maca.",
  ui_story_1017_10170601_7_dialog_content = "Hum? E você é...",
  ui_story_1017_10170601_8_dialog_content = "Estável e cuidado com a perna dela.",
  ui_story_1017_10170601_9_dialog_content = "Entendi, Joselyne.",
  ui_story_1017_10170601_10_dialog_content = "Você trabalha no hospital, certo?",
  ui_story_1017_10170601_11_dialog_content = "Oi, sou Joselyne e ao meu lado está uma enfermeira do hospital.",
  ui_story_1017_10170601_12_dialog_content = "Prazer em conhecer todos vocês. Eu sou Chi.",
  ui_story_1017_10170601_13_dialog_content = "Chi, você é tão jovem e é incrível o quão capaz você é.",
  ui_story_1017_10170601_14_dialog_content = "Hehehe!",
  ui_story_1017_10170601_15_dialog_content = "Joselyne...",
  ui_story_1017_10170601_16_dialog_content = "Ah! Você não seria... a Santa da Igreja da Noite Branca, seria?",
  ui_story_1017_10170601_17_dialog_content = "Santa?!",
  ui_story_1017_10170601_18_dialog_content = "Não, eu não sou a Santa. Sou apenas uma pessoa comum.",
  ui_story_1017_10170601_19_dialog_content = "O que é a Santa, Joselyne?",
  ui_story_1017_10170601_20_dialog_content = "A Santa é a deusa viva que protege o povo do Deus da Luz!",
  ui_story_1017_10170601_21_dialog_content = "Enquanto a Santa estiver aqui, os Eclipsitas não ousarão pisar em nossas casas.",
  ui_story_1017_10170601_22_dialog_content = "Uau! Isso é verdade mesmo, Sua Santidade?",
  ui_story_1017_10170601_23_dialog_content = "Realmente, eu não sou uma Santa. Apenas me chame de Joselyne.",
  ui_story_1017_10170601_24_dialog_content = "Embora eu acredite que A Luz irá dissipar a escuridão e ser o farol eterno para todas as pessoas.",
  ui_story_1017_10170601_25_dialog_content = "Vou fazer o meu melhor até aquele dia.",
  ui_story_1017_10170601_26_dialog_content = "\"Deus da Luz\", o que é isso? É realmente intrigante, Joselyne...",
  ui_story_1017_10170601_27_dialog_content = "Isso significa que o bem vencerá o mal e todos nós seremos abraçados pelo Deus da Luz.",
  ui_story_1017_10170601_28_dialog_content = "Joselyne—",
  ui_story_1017_10170601_29_dialog_content = "Como está tudo no hospital, Joselyne?",
  ui_story_1017_10170601_30_dialog_content = "Nunca tivemos tantas pessoas aqui de uma vez, mas ainda devemos ter espaço.",
  ui_story_1017_10170601_31_dialog_content = "Como está na linha de frente?",
  ui_story_1017_10170601_32_dialog_content = "Infelizmente! Os Eclipsitas fizeram um ataque repentino, nos atingindo com força. Nossos soldados sofreram muitas baixas!",
  ui_story_1017_10170601_33_dialog_content = "As defesas externas de Twilight desmoronaram, deixando numerosos moradores sob ataque...",
  ui_story_1017_10170601_34_dialog_content = "Céus!",
  ui_story_1017_10170601_35_dialog_content = "Acabou. Tudo acabou...",
  ui_story_1017_10170601_36_dialog_content = "Nenhuma notícia do Leo e dos outros?",
  ui_story_1017_10170601_37_dialog_content = "Enviamos mensagens há algum tempo, mas não há sinal do Capitão!",
  ui_story_1017_10170601_38_dialog_content = "Vou levar o cavalo e o equipamento do Capitão até o <color=#FFB400>portão</color> de Crepúsculo para recebê-lo.",
  ui_story_1017_10170601_39_dialog_content = "Quando o Capitão estava ausente, este cavalo parecia ansioso para lutar por ele, avançando na batalha e escapando por pouco dos danos causados pelos Eclipsitas.",
  ui_story_1017_10170601_40_dialog_content = "Os Cavaleiros Ironthorn ainda estão no auge da batalha... Eu vou sair primeiro. As coisas aqui estão em suas mãos agora.",
  ui_story_1017_10170601_41_dialog_content = "Noite Branca lá no alto—",
  ui_story_1017_10170601_42_dialog_content = "Chi, por favor ajude esse homem a levar a senhora ferida para o hospital.",
  ui_story_1017_10170601_43_dialog_content = "E diga à enfermeira-chefe para enviar mais médicos para as áreas periféricas de Twilight.",
  ui_story_1017_10170601_44_dialog_content = "Onde você está indo, Joselyne?",
  ui_story_1017_10170601_45_dialog_content = "Para o campo de batalha.",
  ui_story_1017_10170601_46_dialog_content = "Para o campo de batalha? Quer dizer... deveriam ser os guerreiros que vão para o campo de batalha, certo?",
  ui_story_1017_10170601_47_dialog_content = "Sou um guerreiro e é onde eu deveria estar neste momento.",
  ui_story_1017_10170601_48_dialog_content = "Você consegue, Chi. Te vejo mais tarde.",
  ui_story_1017_10170601_49_dialog_content = "...",
  ui_story_1017_10170601_50_dialog_content = "Você está pronto para isso?",
  ui_story_1017_10170601_51_dialog_content = "A idade não me define; eu tenho uma força incrível!",
  ui_story_1017_10170601_52_dialog_content = "<color=#e8d9bb>Joselyne aventura-se nos arredores da zona de guerra...</color>",
  ui_story_1017_10170601_53_dialog_content = "Cuidado com os pés!",
  ui_story_1017_10170601_54_dialog_content = "Sem piedade!",
  ui_story_1017_10170601_55_dialog_content = "Eu pensei que este aqui estava fora de serviço.",
  ui_story_1017_10170601_56_dialog_content = "Tenha cuidado com inimigos caídos. Às vezes, seus ataques podem ser os mais letais.",
  ui_story_1017_10170601_57_dialog_content = "Entendi. Obrigado pelo lembrete!",
  ui_story_1017_10170601_58_dialog_content = "São os ensinamentos do Capitão — agora, com ele não por perto, algo parece estar faltando.",
  ui_story_1017_10170601_59_dialog_content = "Todo mundo pode não dizer em voz alta, mas lá no fundo, eles estão definitivamente preocupados...",
  ui_story_1017_10170601_60_dialog_content = "Eu posso entender... Esta é a primeira vez que vejo tantos Eclipsitas.",
  ui_story_1017_10170601_61_dialog_content = "Você sabe o que eles estão procurando?",
  ui_story_1017_10170601_62_dialog_content = "Não faço ideia. A operação inteira é uma bagunça caótica, e nossas linhas de defesa continuam cedendo...",
  ui_story_1017_10170601_63_dialog_content = "Se continuarmos assim, Twilight será uma causa perdida.",
  ui_story_1017_10170601_64_dialog_content = "Atrás de você!",
  ui_story_1017_10170601_65_dialog_content = "Argh!",
  ui_story_1017_10170601_66_dialog_content = "Como você, Cavaleiro do Espinho de Ferro, pode ser tão pessimista?",
  ui_story_1017_10170601_67_dialog_content = "Mesmo sem a presença de Leo, devemos fazer tudo o que pudermos para remover os Eclipsitas!",
  ui_story_1017_10170601_68_dialog_content = "Estamos estacionados aqui há muito tempo. Então, estamos bem cientes de que o Crepúsculo é apenas um deserto abandonado, esquecido pelos deuses. Se nenhum auxílio chegar, os Eclipsitas se banquetearão com ele como quiserem.",
  ui_story_1017_10170601_69_dialog_content = "Estamos defendendo isso simplesmente porque nascemos e fomos criados aqui, sem outras opções disponíveis.",
  ui_story_1017_10170601_70_dialog_content = "Se ao menos pudéssemos voltar... Quem suportaria voluntariamente esse tormento, lutando para sobreviver nesta terra abandonada por Deus?",
  ui_story_1017_10170601_71_dialog_content = "...",
  ui_story_1017_10170601_72_dialog_content = "Dito tudo isso... isso não significa que estou recuando. No entanto, até nós, soldados sem nome, devemos saber pelo que estamos lutando...",
  ui_story_1017_10170601_73_dialog_content = "Isso é pedir demais?",
  ui_story_1017_10170601_74_dialog_content = "Proteger este lugar não é motivo suficiente?",
  ui_story_1017_10170601_75_dialog_content = "As crianças locais que nunca viram o mundo exterior pensavam que Crepúsculo era o mundo inteiro.",
  ui_story_1017_10170601_76_dialog_content = "Eu acredito que todos nós pensávamos o mesmo antes de perceber que existe um mundo maior lá fora.",
  ui_story_1017_10170601_77_dialog_content = "E os soldados que se sacrificaram, não foi para proteger este pequeno mundo?",
  ui_story_1017_10170601_78_dialog_content = "...",
  ui_story_1017_10170601_79_dialog_content = "Guerreiros não precisam provar seu valor através de uma grande batalha.",
  ui_story_1017_10170601_80_dialog_content = "Eles são incríveis apenas por defenderem um pedaço de terra.",
  ui_story_1017_10170601_81_dialog_content = "Talvez... Embora suas palavras tenham verdade, esses últimos anos nos mostraram que estamos todos lutando pelo Capitão...",
  ui_story_1017_10170601_82_dialog_content = "Leo também lutou por você, não foi?",
  ui_story_1017_10170601_83_dialog_content = "De fato. Para nós, ele sacrificou muito.",
  ui_story_1017_10170601_84_dialog_content = "Para evitar mais perdas, vamos proteger a terra onde as batalhas foram travadas!",
  ui_story_1017_10170601_85_dialog_content = "Se você nasceu aqui ou veio por diferentes razões, vamos lutar uns pelos outros!",
  ui_story_1017_10170601_86_dialog_content = "Sim, você está absolutamente certo! Vou contar aos camaradas agora mesmo!",
  ui_story_1017_10170601_87_dialog_content = "Escutem! Cavaleiros Espinho de Ferro! Permitir que esses Eclipsitas avancem mais uma polegada é um insulto aos nossos irmãos caídos!",
  ui_story_1017_10170601_88_dialog_content = "Lembre-se disso sobre os Cavaleiros do Espinho de Ferro: não é apenas sobre o ferro em nossa armadura, mas também o ferro em nossa determinação e espírito!",
  ui_story_1017_10170601_89_dialog_content = "Não daremos um centímetro aos Eclipsitas, mesmo que isso signifique construir muros com nossa própria carne!",
  ui_story_1017_10170601_90_dialog_content = "Todos juntos agora!",
  ui_story_1017_10170601_91_dialog_content = "Eu também!",
  ui_story_1017_10170601_92_dialog_content = "Defenda Crepúsculo com nossas vidas!",
  ui_story_1017_10170601_93_dialog_content = "Defenda Crepúsculo com nossas vidas!",
  ui_story_1017_10170602_1_dialog_content = "Já estamos quase no Crepúsculo, Soroz?",
  ui_story_1017_10170602_2_dialog_content = "PlayerName, você fez a mesma pergunta 10 vezes no último minuto.",
  ui_story_1017_10170602_3_dialog_content = "Estou muito nervoso...",
  ui_story_1017_10170602_4_dialog_content = "Entendi. Verifiquei se há alguma latência na nossa conexão, mas parece que não há.",
  ui_story_1017_10170602_5_dialog_content = "Sem atrasos na comunicação, embora pareça que você está se movendo bem devagar...",
  ui_story_1017_10170602_6_dialog_content = "Confirmando a velocidade do voo: sempre mantenha a <color=#FFB400>velocidade máxima</color>.",
  ui_story_1017_10170602_7_dialog_content = "...",
  ui_story_1017_10170602_8_dialog_content = "Seu ânimo parece baixo. Gostaria de compartilhar o motivo comigo?",
  ui_story_1017_10170602_9_dialog_content = "Acabei de lembrar quanto tempo faz desde que você perdeu a consciência.",
  ui_story_1017_10170602_10_dialog_content = "E eu nem me preocupei em perguntar como você está antes de pedir para nos levar a Crepúsculo.",
  ui_story_1017_10170602_11_dialog_content = "Pode ter sido muito tempo para você, mas na minha programação, nunca estivemos separados.",
  ui_story_1017_10170602_12_dialog_content = "Eu acho que você se sente assim, né?",
  ui_story_1017_10170602_13_dialog_content = "Posso presenciar tantas paisagens diferentes apenas porque você e seus amigos têm muitos lugares para visitar.",
  ui_story_1017_10170602_14_dialog_content = "Falando nisso, <color=#FFB400>uma nova paisagem</color>. Nosso destino está logo à frente.",
  ui_story_1017_10170602_15_dialog_content = "Estamos lá agora?",
  ui_story_1017_10170602_16_dialog_content = "Estamos quase lá. Por favor, confirme o local de pouso.",
  ui_story_1017_10170602_17_dialog_content = "Quando terminarmos em Crepúsculo, vou te contar a história inteira.",
  ui_story_1017_10170602_18_dialog_content = "Vamos diminuir a velocidade e voar em baixa altitude, então <color=#FFB400>abrir a escotilha</color>.",
  ui_story_1017_10170602_19_dialog_content = "Desacelerando. Abrindo a <color=#FFB400>Escotilha 3</color>...",
  ui_story_1017_10170602_20_dialog_content = "Leo—",
  ui_story_1017_10170602_21_dialog_content = "Muito obrigado, PlayerName. Quando tudo se acalmar em Twilight, vou reconhecer formalmente sua ajuda.",
  ui_story_1017_10170602_22_dialog_content = "Sem problemas. Soroz está descendo. Onde devemos pousar?",
  ui_story_1017_10170602_23_dialog_content = "Vê aquele soldado no portão?",
  ui_story_1017_10170602_24_dialog_content = "Vejo alguém... e talvez três cavalos...",
  ui_story_1017_10170602_25_dialog_content = "Ele é um dos meus caras, esperando por mim com meu cavalo.",
  ui_story_1017_10170602_26_option_content = "Você tem uma ótima visão!",
  ui_story_1017_10170602_27_dialog_content = "Não acredito que você consegue distinguir quem são as pessoas e quem é o cavalo de tão longe.",
  ui_story_1017_10170602_28_dialog_content = "Bem, Crepúsculo é um ótimo lugar para treinar.",
  ui_story_1017_10170602_29_option_content = "Não posso dizer que foi inesperado",
  ui_story_1017_10170602_30_dialog_content = "Com certeza há química entre o capitão e seus homens.",
  ui_story_1017_10170602_31_dialog_content = "Levou anos para desenvolver.",
  ui_story_1017_10170602_32_dialog_content = "Estou disposto a ensinar um pouco sobre campanhas e lutas quando tivermos a chance.",
  ui_story_1017_10170602_33_dialog_content = "Altitude de pouso alcançada. PlayerName, por favor confirme o local de pouso.",
  ui_story_1017_10170602_34_dialog_content = "Que tal pousarmos perto daquele portão ali, Leo?",
  ui_story_1017_10170602_35_dialog_content = "Claro... Quase, quase... Bem aqui, perfeito. Bem, então—",
  ui_story_1017_10170602_36_dialog_content = "Cuide do Joseph para mim, PlayerName!",
  ui_story_1017_10170602_37_dialog_content = "Até mais, Joseph.",
  ui_story_1017_10170602_38_dialog_content = "Até mais, Leo.",
  ui_story_1017_10170602_39_dialog_content = "???",
  ui_story_1017_10170602_40_dialog_content = "Ele simplesmente pulou assim?!",
  ui_story_1017_10170602_41_dialog_content = "Ei, o—que—sobre—mim—",
  ui_story_1017_10170602_42_dialog_content = "Você—deveria—voltar—",
  ui_story_1017_10170602_43_dialog_content = "...",
  ui_story_1017_10170602_44_dialog_content = "Capitão! Nunca imaginei que seria você pulando daquela coisa enorme!",
  ui_story_1017_10170602_45_dialog_content = "É aquele... o lendário Colosso?!",
  ui_story_1017_10170602_46_dialog_content = "Isso mesmo! Desculpe mantê-lo esperando!",
  ui_story_1017_10170602_47_dialog_content = "Vamos para a batalha agora mesmo. Me diga, como está a situação em Crepúsculo?",
  ui_story_1017_10170602_48_dialog_content = "Os Eclipsitas estão avançando da <color=#FFB400>Noite Eterna</color>. Embora as fortificações externas tenham sido violadas, nossos camaradas ainda estão mantendo suas posições.",
  ui_story_1017_10170602_49_dialog_content = "Quem está liderando os Eclipsitas?",
  ui_story_1017_10170602_50_dialog_content = "Não há um líder específico entre os Eclipsitas. Eles estão se agrupando em grande número e suas ações são puro caos!",
  ui_story_1017_10170602_51_dialog_content = "Qual é o número de baixas?",
  ui_story_1017_10170602_52_dialog_content = "Muitos moradores nos arredores foram atacados. Atualmente, os realocamos para zonas mais seguras. Centenas de soldados estão feridos e também...",
  ui_story_1017_10170602_53_dialog_content = "Perdemos <color=#FFB400>75</color> dos nossos camaradas...",
  ui_story_1017_10170602_54_dialog_content = "<color=#FFB400>75</color> perdeu?! Então por que você ainda está aqui?",
  ui_story_1017_10170602_55_dialog_content = "Capitã... Antes de você retornar, seu cavalo se soltou das rédeas e avançou na batalha, derrubando os Eclipsitas...",
  ui_story_1017_10170602_56_dialog_content = "Eu mal consegui mantê-lo contido. Não faço ideia do que fazer agora!",
  ui_story_1017_10170602_57_dialog_content = "Hmph, será preciso muito mais para derrotar Crepúsculo!",
  ui_story_1017_10170602_58_dialog_content = "Conversou com as cidades próximas?",
  ui_story_1017_10170602_59_dialog_content = "Aqueles capazes de lutar já vieram nos apoiar... mas algumas cidades ainda estão lutando para se defender da ameaça por conta própria.",
  ui_story_1017_10170602_60_dialog_content = "Desta vez, não apenas a batalha é desafiadora... o consumo de recursos médicos também é incrivelmente imenso...",
  ui_story_1017_10170602_61_dialog_content = "Sem ajuda médica da Fortaleza Lumo?",
  ui_story_1017_10170602_62_dialog_content = "Não. O hospital é composto por médicos e enfermeiros da cidade. Até mesmo algumas das crianças mais velhas se ofereceram para ajudar...",
  ui_story_1017_10170602_63_dialog_content = "Qualquer coisa é extremamente difícil quando está em Crepúsculo.",
  ui_story_1017_10170602_64_dialog_content = "A boa notícia é que estou de volta e não vou deixar os caras morrerem em vão.",
  ui_story_1017_10170602_65_dialog_content = "A má notícia é que ainda somos os únicos em quem podemos confiar.",
  ui_story_1017_10170602_66_dialog_content = "Hmm... Capitão, por que o Zhao não está com você?",
  ui_story_1017_10170602_67_dialog_content = "Ele está ocupado com algo, mas sei que ele virará o jogo para nós no momento certo.",
  ui_story_1017_10170602_68_dialog_content = "É realmente possível virar a mesa considerando a crise que Twilight enfrenta?",
  ui_story_1017_10170602_69_dialog_content = "Acima de você!",
  ui_story_1017_10170602_70_dialog_content = "Pegue!",
  ui_story_1017_10170602_71_dialog_content = "<color=#e8d9bb>O soldado agarra PlayerName enquanto caem do céu, e os dois quase caem de seus cavalos...</color>",
  ui_story_1017_10170602_72_dialog_content = "Espere, eu te conheço! Você quase me esmagou!",
  ui_story_1017_10170602_73_dialog_content = "Eu pensei... que a Colossus estava prestes a cair em cima de mim também!",
  ui_story_1017_10170602_74_dialog_content = "Desculpe por isso...",
  ui_story_1017_10170602_75_dialog_content = "Você tá bem?",
  ui_story_1017_10170602_76_option_content = "Tô bem",
  ui_story_1017_10170602_77_dialog_content = "Soroz estava navegando na altitude perfeita.",
  ui_story_1017_10170602_78_option_content = "Onde estou? Estou vivo?",
  ui_story_1017_10170602_79_dialog_content = "Achei que meu coração fosse parar na queda.",
  ui_story_1017_10170602_80_dialog_content = "Felizmente, Soroz estava navegando na altura certa.",
  ui_story_1017_10170602_81_dialog_content = "Por quê você está aqui?",
  ui_story_1017_10170602_82_dialog_content = "Supostamente, deveríamos ir para Crepúsculo juntos. Por que eu voltaria atrás?",
  ui_story_1017_10170602_83_dialog_content = "Obrigado, mas é até aqui que você vai.",
  ui_story_1017_10170602_84_dialog_content = "Vire-se e escolte este de volta.",
  ui_story_1017_10170602_85_dialog_content = "Capitão...",
  ui_story_1017_10170602_86_dialog_content = "Não quero perder mais nenhum dos meus soldados!",
  ui_story_1017_10170602_87_dialog_content = "Uau, eu não tenho plano de ser seu soldado.",
  ui_story_1017_10170602_88_dialog_content = "Soroz e eu seremos muito benéficos para a batalha em Crepúsculo.",
  ui_story_1017_10170602_89_dialog_content = "Soroz está na altura perfeita para ver todo o exército inimigo agora.",
  ui_story_1017_10170602_90_dialog_content = "Pode ser o olho no céu enquanto eu guio você durante a batalha.",
  ui_story_1017_10170602_91_dialog_content = "Olho-no-céu é bem convincente.",
  ui_story_1017_10170602_92_dialog_content = "Dada a ausência de Zhao, a orientação de PlayerName no campo de batalha pode ser crucial para nós.",
  ui_story_1017_10170602_93_dialog_content = "Isso é verdade.",
  ui_story_1017_10170602_94_dialog_content = "Mas a batalha não é um treino ou exercício. Você morre de verdade.",
  ui_story_1017_10170602_95_dialog_content = "Tem certeza que ainda quer vir?",
  ui_story_1017_10170602_96_dialog_content = "Claro que não!",
  ui_story_1017_10170602_97_dialog_content = "Certo, velocidade máxima rumo à batalha!",
  ui_story_1017_10170602_98_dialog_content = "Sim, Capitão!",
  ui_story_1017_10170602_99_dialog_content = "Parece que isso não tem fim...",
  ui_story_1017_10170602_100_dialog_content = "E ainda não vemos um líder para eles.",
  ui_story_1017_10170602_101_dialog_content = "Todos estão exaustos, Joselyne. Não vamos resistir por muito mais tempo se continuarmos assim.",
  ui_story_1017_10170602_102_dialog_content = "A nova fortaleza ainda não está pronta. Se desistirmos agora, todo o esforço que gastamos defendendo-a será em vão!",
  ui_story_1017_10170602_103_dialog_content = "Mas o moral está no fundo do poço. Receio que mesmo se o Capitão voltar, talvez não faça diferença...",
  ui_story_1017_10170602_104_dialog_content = "Quem disse que nem eu posso evitar?",
  ui_story_1017_10170602_105_dialog_content = "Você finalmente voltou! Capitão!",
  ui_story_1017_10170602_106_dialog_content = "O Capitão voltou!!!",
  ui_story_1017_10170602_107_dialog_content = "Bem acima... é...",
  ui_story_1017_10170602_108_dialog_content = "Eu retornei, meus irmãos Cavaleiros do Espinho de Ferro!",
  ui_story_1017_10170602_109_dialog_content = "A partir deste momento, mostre a eles como é um cavaleiro!",
  ui_story_1017_10170602_110_dialog_content = "PlayerName e Soroz, a Colossus nos dará cobertura!",
  ui_story_1017_10170602_111_dialog_content = "Então, este é o lendário Colosso, hein? É ainda mais massivo do que eu imaginava!",
  ui_story_1017_10170602_112_dialog_content = "Vamos lutar ao lado do Colosso!",
  ui_story_1017_10170602_113_dialog_content = "Isso mesmo, temos Soroz. Agora, preste atenção e ouça meus comandos!",
  ui_story_1017_10170602_114_dialog_content = "Siga o trajeto de voo de Soroz em alta velocidade e esmague os Eclipsitas!",
  ui_story_1017_10170602_115_dialog_content = "Sim!",
  ui_story_1017_10170602_116_dialog_content = "Estou contando com você, PlayerName!",
  ui_story_1017_10170602_117_dialog_content = "Eu vou dar tudo de mim!",
  ui_story_1017_10170701_1_dialog_content = "O acesso principal a Lumópolis deve ser por aqui...",
  ui_story_1017_10170701_2_dialog_content = "Ai!",
  ui_story_1017_10170701_X2_dialog_content = "Morda e Chompe!",
  ui_story_1017_10170701_3_dialog_content = "Que tédio, que tédio! Que tal implicar com alguém?",
  ui_story_1017_10170701_4_dialog_content = "Quem são vocês dois?",
  ui_story_1017_10170701_5_dialog_content = "Faça um palpite!",
  ui_story_1017_10170701_6_dialog_content = "Por favor, pare de me importunar. Tenho um negócio urgente e preciso ir.",
  ui_story_1017_10170701_7_dialog_content = "Peça minha ajuda, mas não posso garantir que será feito!",
  ui_story_1017_10170701_8_dialog_content = "...",
  ui_story_1017_10170701_9_dialog_content = "Você sabe qual caminho para Lumópolis?",
  ui_story_1017_10170701_10_dialog_content = "Ninguém quer ir para aquele lugar pálido, flutuante e gelado.",
  ui_story_1017_10170701_11_dialog_content = "Lembro que há um acesso especial para...",
  ui_story_1017_10170701_12_dialog_content = "Um lembrete amigável: O acesso a Lumópolis foi encerrado.",
  ui_story_1017_10170701_13_dialog_content = "Foi fechado recentemente? Você sabe o motivo específico?",
  ui_story_1017_10170701_14_dialog_content = "Você tem muitas perguntas. Diga logo suas más intenções ou—",
  ui_story_1017_10170701_15_dialog_content = "Leve-me com você!",
  ui_story_1017_10170701_16_dialog_content = "<size=30>A notícia sobre Illumina vazou e Lumópolis já está reagindo muito mais rápido do que eu esperava.</size>",
  ui_story_1017_10170701_17_dialog_content = "<size=30>Talvez eu possa pegar emprestado um transporte da União Mensageira...</size>",
  ui_story_1017_10170701_18_dialog_content = "<size=30>Mas que desculpa posso dar...?</size>",
  ui_story_1017_10170701_19_dialog_content = "Argh!",
  ui_story_1017_10170701_20_dialog_content = "O que está fazendo?",
  ui_story_1017_10170701_21_dialog_content = "Você não pode passar despercebido pelos nossos narizes com tantas conspirações que está exalando!",
  ui_story_1017_10170701_22_dialog_content = "Você não vem em paz e nós vamos transformá-lo no chefe!",
  ui_story_1017_10170701_23_dialog_content = "Você não sente o cheiro de pólvora de Crepúsculo em mim? Estou em uma missão urgente, então, por favor, me deixe sair!",
  ui_story_1017_10170701_24_dialog_content = "Estou tonto... aqui dentro...",
  ui_story_1017_10170701_25_dialog_content = "Isso é Umbraton, não Crepúsculo!",
  ui_story_1017_10170701_26_dialog_content = "É tudo gostoso no lixo. Lembre-se de esquentar antes de comer!",
  ui_story_1017_10170701_27_dialog_content = "Olá, chefe, encontramos algo novo, então não esqueça de nos alimentar um pouco mais!",
  ui_story_1017_10170701_28_dialog_content = "Não te disse para não trazer de volta nenhum lixo velho?",
  ui_story_1017_10170701_29_dialog_content = "Não é lixo, é um cara mau! Olha!",
  ui_story_1017_10170701_30_dialog_content = "Suspeito e sorrateiro.",
  ui_story_1017_10170701_31_dialog_content = "Tentou correr quando nos viu!",
  ui_story_1017_10170701_32_dialog_content = "...",
  ui_story_1017_10170701_33_dialog_content = "Oh não, ele quebrou!",
  ui_story_1017_10170701_34_dialog_content = "O que um cara elegante de Illumina como ele está fazendo aqui?",
  ui_story_1017_10170701_35_dialog_content = "Ele mencionou capturar Lumópolis, destruir a União dos Mensageiros e tudo mais...",
  ui_story_1017_10170701_36_dialog_content = "Certo, e transforme Umbraton em crepúsculo!",
  ui_story_1017_10170701_37_dialog_content = "Não, para a cidade de Crepúsculo!",
  ui_story_1017_10170701_38_dialog_content = "Crepúsculo?",
  ui_story_1017_10170701_39_dialog_content = "Sim, Crepúsculo! E ele também exala um cheiro de pólvora!",
  ui_story_1017_10170701_40_dialog_content = "Encontre-me <color=#FFB400>Kleken</color>. Vocês dois, vão comer.",
  ui_story_1017_10170701_41_dialog_content = "Claro, chefe! Hora de sair do trabalho e comer!",
  ui_story_1017_10170701_42_dialog_content = "Senhor da Cidade, quanto tempo ainda precisa para tomar uma decisão?",
  ui_story_1017_10170701_43_dialog_content = "Estas cartas que estou segurando vieram diretamente da Fortaleza Lumo.",
  ui_story_1017_10170701_44_dialog_content = "Estamos enfrentando uma queda de quarenta por cento na produção das <color=#FFB400>Minas Vok</color> se não enviarmos nossos soldados agora.",
  ui_story_1017_10170701_45_dialog_content = "Pense nisso - isso pode levar a escassez e interrupções em nossas matérias-primas, e isso afetará ainda mais o volume de comércio exterior de Lumopolis...",
  ui_story_1017_10170701_46_dialog_content = "Confie em mim. As perdas não serão limitadas apenas a essas!",
  ui_story_1017_10170701_47_dialog_content = "Quando a segurança de Crepúsculo começou a afetar a economia de Lumopolis?",
  ui_story_1017_10170701_48_dialog_content = "Você está preocupado com a riqueza que acumulou em Crepúsculo ao longo dos anos, não está?",
  ui_story_1017_10170701_49_dialog_content = "Absurdo! Embora a Casa <color=#FFB400>Dietrich</color> possa não ter raízes antigas, nós temos minerado recursos por anos, abastecendo Lumopolis...",
  ui_story_1017_10170701_50_dialog_content = "E em tempos difíceis, oferecemos abrigo para inúmeros cavaleiros exilados...",
  ui_story_1017_10170701_51_dialog_content = "Considerando nossas contribuições, a Casa <color=#FFB400>Dietrich</color> deveria ter sido recompensada com um lugar de destaque na Cidade Alta anos atrás!",
  ui_story_1017_10170701_52_dialog_content = "Agora, <color=#FFB400>Troy</color>, aqui está o ponto. Enquanto você tem vivido uma boa vida ao lado do Senhor da Cidade, aposto que sua habilidade em lidar com esses Eclipsitas enferrujou.",
  ui_story_1017_10170701_53_dialog_content = "Illumina sempre tem uma inclinação para a guerra. Deixe-os pacificar os Eclipsitas por conta própria.",
  ui_story_1017_10170701_54_dialog_content = "Além disso, os Cavaleiros do Espinho de Ferro têm muita influência em Crepúsculo.",
  ui_story_1017_10170701_55_dialog_content = "Falando em oferecer abrigo aos cavaleiros, para onde essa sua espada será apontada em seguida? Aposto que você já planejou tudo há muito tempo.",
  ui_story_1017_10170701_56_dialog_content = "Você pode não saber, mas o que os Cavaleiros Ironthorn estão defendendo é Crepúsculo inteiro.",
  ui_story_1017_10170701_57_dialog_content = "Eles são muito próximos dos soldados Illumina e Leo até mesmo se juntaram a eles para o Exercício Militar Conjunto.",
  ui_story_1017_10170701_58_dialog_content = "Até onde eu sei, a casa de Leo caiu. Ou você está ameaçado pela fama dele em Crepúsculo?",
  ui_story_1017_10170701_59_dialog_content = "Ahem, alguma atualização sobre algo além de Crepúsculo?",
  ui_story_1017_10170701_60_dialog_content = "Senhor da Cidade, permita-me informá-lo sobre o que aprendi durante o Exercício Militar Conjunto.",
  ui_story_1017_10170701_61_dialog_content = "Continue.",
  ui_story_1017_10170701_62_dialog_content = "Conheci um soldado de Crepúsculo. Ele—",
  ui_story_1017_10170701_63_dialog_content = "Ainda Crepúsculo? Tudo bem, não precisa dizer mais nada.",
  ui_story_1017_10170701_64_dialog_content = "Mas…",
  ui_story_1017_10170701_65_dialog_content = "Viu aquela mesa?",
  ui_story_1017_10170701_66_dialog_content = "Eu já vi mensagens suficientes de Crepúsculo, Fortaleza Lumo e até mesmo Umbraton para durar uma vida inteira.",
  ui_story_1017_10170701_67_dialog_content = "Então por que você não tomou nenhuma atitude?",
  ui_story_1017_10170701_68_dialog_content = "Você morou em Crepúsculo por tanto tempo que a impaciência deles acabou passando para você.",
  ui_story_1017_10170701_69_dialog_content = "...",
  ui_story_1017_10170701_70_dialog_content = "(Pai pode parecer tranquilo a respeito, mas seu dedo nunca parou de tamborilar na mesa...)",
  ui_story_1017_10170701_71_dialog_content = "(Ele não quer ouvir sobre Crepúsculo, mas o que ele está esperando?)",
  ui_story_1017_10170701_72_dialog_content = "Senhor da Cidade! Temos novas informações sobre a Federação Illumina!",
  ui_story_1017_10170701_73_dialog_content = "Diga.",
  ui_story_1017_10170701_74_dialog_content = "As novas forças da Illumina cruzaram as defesas e estão quase no Crepúsculo agora.",
  ui_story_1017_10170701_75_dialog_content = "Eles atravessaram as defesas?",
  ui_story_1017_10170701_76_dialog_content = "Sim!",
  ui_story_1017_10170701_77_dialog_content = "Qual é o lance com essas novas forças?",
  ui_story_1017_10170701_78_dialog_content = "As novas forças são a Legião da Guarda formada após Wrath assumir como Grande Marechal.",
  ui_story_1017_10170701_79_dialog_content = "Eles têm equipamentos de combate novos e guerreiros a bordo, e acredite nisso—um dos soldados realmente derrotou Reinhardt em um exercício militar.",
  ui_story_1017_10170701_80_dialog_content = "(Axelia? Ela deveria estar se recuperando agora...)",
  ui_story_1017_10170701_81_dialog_content = "Alguma notícia sobre os generais da Illumina e o Celestita?",
  ui_story_1017_10170701_82_dialog_content = "Além de Hiiro, outros Comandantes estão em diferentes missões e parece que eles ainda não chegaram ao Crepúsculo.",
  ui_story_1017_10170701_83_dialog_content = "Quanto ao Celestita, recebemos informações de que sua Colossus seguiu para o Crepúsculo logo após o início da guerra.",
  ui_story_1017_10170701_84_dialog_content = "PlayerName foi para Crepúsculo?",
  ui_story_1017_10170701_85_dialog_content = "Isso é um problema?",
  ui_story_1017_10170701_86_dialog_content = "Não poderia ser mais claro - as vulnerabilidades de Crepúsculo estão expostas para todas as grandes potências verem após o exercício militar.",
  ui_story_1017_10170701_87_dialog_content = "Parece que a Federação Illumina acredita que já tem Crepúsculo sob controle, e é por isso que enviaram essa força formidável.",
  ui_story_1017_10170701_88_dialog_content = "De agora em diante, quem sabe se ainda haverá lugar para a Noite Branca em Crepúsculo.",
  ui_story_1017_10170701_89_dialog_content = "Substituir o marechal e enviar um novo exército para pacificar os Eclipsitas em um momento crucial como este...",
  ui_story_1017_10170701_90_dialog_content = "Para mim, é uma decisão incrivelmente ridícula.",
  ui_story_1017_10170701_91_dialog_content = "É melhor você descobrir se eles pretendem reforçar ou fazer algo diferente, Schwartz.",
  ui_story_1017_10170701_92_dialog_content = "Envie a ordem para mobilizar reforços para partida imediata rumo ao Crepúsculo.",
  ui_story_1017_10170701_93_dialog_content = "Obrigado, Senhor da Cidade. Se importa em compartilhar um pouco do seu pensamento?",
  ui_story_1017_10170701_94_dialog_content = "Uma vez que o exército de Illumina cruzou a linha de defesa, Lumopolis deve fazer um movimento.",
  ui_story_1017_10170701_95_dialog_content = "Seja em um esforço cooperativo ou por interesses particulares, é do nosso melhor interesse enviar forças.",
  ui_story_1017_10170701_96_dialog_content = "Lembre-se, priorize a segurança da Fortaleza Lumo acima de tudo e não se envolva em nenhuma operação Illumina.",
  ui_story_1017_10170701_97_dialog_content = "Eu devo aprovar pessoalmente cada ação das tropas de reforço.",
  ui_story_1017_10170701_98_dialog_content = "Sim!",
  ui_story_1017_10170701_99_dialog_content = "(Pai está desconfiado das forças Illumina...)",
  ui_story_1017_10170701_100_dialog_content = "Quem liderará o reforço, Senhor da Cidade? Eu gostaria de me voluntari—",
  ui_story_1017_10170701_101_dialog_content = "Você está dispensado. Reforçar o Crepúsculo não é uma das suas responsabilidades.",
  ui_story_1017_10170701_102_dialog_content = "Mas…",
  ui_story_1017_10170701_103_dialog_content = "Vamos encerrar por aqui hoje.",
  ui_story_1017_10170801_1_dialog_content = "Com licença... Minha família ainda não voltou. Você poderia, por favor, manter o portão aberto um pouco mais?",
  ui_story_1017_10170801_2_dialog_content = "As ordens do Senhor são claras—Tranquem bem os portões. Ninguém entra, exceto os moradores da Noite Branca.",
  ui_story_1017_10170801_3_dialog_content = "Entendo, mas... meu filho também é um morador da Noite Branca... Ele foi para as linhas de frente para nos proteger.",
  ui_story_1017_10170801_4_dialog_content = "Não fui claro o suficiente? Os portões estão prestes a fechar. Recue!",
  ui_story_1017_10170801_5_dialog_content = "Poderoso Deus da Luz, como eu gostaria que você não nos tivesse abandonado...",
  ui_story_1017_10170801_6_dialog_content = "Após o crepúsculo vem a noite, e após a noite vem o crepúsculo novamente...",
  ui_story_1017_10170801_7_dialog_content = "Para as crianças na linha de frente, minhas orações são sinceras com vocês.",
  ui_story_1017_10170801_8_dialog_content = "Para trás, PlayerName!",
  ui_story_1017_10170801_9_dialog_content = "Comandantes não recuam nas batalhas!",
  ui_story_1017_10170801_10_dialog_content = "Nunca vi uma invasão Eclipsita nesta escala antes.",
  ui_story_1017_10170801_11_dialog_content = "As duas ofensivas anteriores foram invadidas por Eclipsitas. Agora não é hora de forçar a situação.",
  ui_story_1017_10170801_12_dialog_content = "Bem, eu realmente sinto o Fluxo Escuro ficando cada vez mais forte...",
  ui_story_1017_10170801_13_dialog_content = "Eles não têm líder, nenhum motivo discernível e são vastos em número. Não podemos atacar cegamente sem saber mais.",
  ui_story_1017_10170801_14_dialog_content = "Capitão, ambas as equipes que guardam as linhas de defesa foram dispersas pelos Eclipsitas. Os soldados estão sofrendo pesadas baixas.",
  ui_story_1017_10170801_15_dialog_content = "Todas as unidades, recuem 100 passos imediatamente!",
  ui_story_1017_10170801_16_dialog_content = "Sim!",
  ui_story_1017_10170801_17_dialog_content = "Peça à Logística para construir carrinhos improvisados e transportar os feridos para a estalagem da cidade.",
  ui_story_1017_10170801_18_dialog_content = "Nós cuidaremos dos feridos nós mesmos!",
  ui_story_1017_10170801_19_dialog_content = "Sim, Capitão!",
  ui_story_1017_10170801_20_dialog_content = "Leo, vamos tentar descobrir enquanto recuamos. O que você acha que os Eclipsitas estão tramando?",
  ui_story_1017_10170801_21_dialog_content = "Eles estão apenas tentando nos diminuir através do puro número. Não faz muito sentido.",
  ui_story_1017_10170801_22_dialog_content = "Alguma ideia sobre os planos dos Eclipsitas, PlayerName?",
  ui_story_1017_10170801_23_dialog_content = "Deixe-me tentar meu poder.",
  ui_story_1017_10170801_24_dialog_content = "(Todos os Eclipsitas estão fora do Crepúsculo... O Fluxo Escuro está denso...)",
  ui_story_1017_10170801_25_dialog_content = "(Eles estão se movendo devagar e agrupados bem próximos como se...)",
  ui_story_1017_10170801_26_dialog_content = "(Como se estivessem formando uma enorme rede de Fluxo Escuro para cobrir Crepúsculo...)",
  ui_story_1017_10170801_27_dialog_content = "(Muitos nós... na rede...)",
  ui_story_1017_10170801_28_dialog_content = "(Espere... A intensidade do Fluxo Escuro é diferente para cada nó, mas eles parecem estar apontando para...)",
  ui_story_1017_10170801_29_dialog_content = "Leo, o Fluxo Escuro cobre uma grande distância e parece estar sob um comando centralizado.",
  ui_story_1017_10170801_30_dialog_content = "Você sabe o que é esse comando central?",
  ui_story_1017_10170801_31_dialog_content = "Desculpe, não está ao meu alcance.",
  ui_story_1017_10170801_32_dialog_content = "Pelo menos isso significa que os Eclipsitas não estão agindo aleatoriamente.",
  ui_story_1017_10170801_33_dialog_content = "Sim. E por enquanto, localizar esse comando central é a chave.",
  ui_story_1017_10170801_34_dialog_content = "Soroz, tente procurar pelo comando central.",
  ui_story_1017_10170801_35_dialog_content = "Procurando...",
  ui_story_1017_10170801_36_dialog_content = "Expandindo o campo de visão...",
  ui_story_1017_10170801_37_dialog_content = "\"Centro\" ainda não detectado. Busca em andamento...",
  ui_story_1017_10170801_38_dialog_content = "Não encontrado...",
  ui_story_1017_10170801_39_dialog_content = "Se for devido ao alcance, a localização provavelmente está muito próxima da Zona Escura ou até mesmo dentro da Zona Escura.",
  ui_story_1017_10170801_40_dialog_content = "Acredito que apenas eliminando quem está no comando conseguiremos parar os Eclipsitas.",
  ui_story_1017_10170801_41_dialog_content = "Está pensando em se aventurar na Zona Escura?",
  ui_story_1017_10170801_42_dialog_content = "Isso mesmo. Crepúsculo será destruído se não fizermos algo.",
  ui_story_1017_10170801_43_dialog_content = "Estou com você, Capitão!",
  ui_story_1017_10170801_44_dialog_content = "Não, você assume como comandante-chefe e segura a linha.",
  ui_story_1017_10170801_45_dialog_content = "Equipe de reconhecimento, aguardem minha ordem—",
  ui_story_1017_10170801_46_dialog_content = "PlayerName, por trás, uma força militar está se aproximando de você.",
  ui_story_1017_10170801_47_dialog_content = "Você consegue dizer de qual exército eles são?",
  ui_story_1017_10170801_48_dialog_content = "A bandeira no veículo de transporte da frente exibe uma imagem:",
  ui_story_1017_10170801_49_dialog_content = "Illumina!",
  ui_story_1017_10170801_50_dialog_content = "Leo, são as forças Illumina atrás de nós!",
  ui_story_1017_10170801_51_dialog_content = "Atenção, Legião da Guarda!",
  ui_story_1017_10170801_52_dialog_content = "Todas as empresas avancem em formação de diamante!",
  ui_story_1017_10170801_53_dialog_content = "Engine VII, priorize preencher as lacunas nas barreiras. Não deixe os Eclipsitas avançarem mais um passo!",
  ui_story_1017_10170801_54_dialog_content = "Sim!!!",
  ui_story_1017_10170801_55_dialog_content = "É isso aí, invasores? Vocês não vão durar nem 10 minutos como alvos de treino!",
  ui_story_1017_10170801_56_dialog_content = "Essa... aura tão imponente... Será este o novo Grande Marechal de Illumina?",
  ui_story_1017_10170801_57_dialog_content = "Ela era apenas minha instrutora de treinamento no exercício, mas agora ela parece totalmente diferente como a Grande Marechal.",
  ui_story_1017_10170801_58_dialog_content = "Sim, um uniforme totalmente novo e provavelmente muito mais poderoso!",
  ui_story_1017_10170801_59_dialog_content = "Os soldados deles também são seriamente formidáveis. Veja aquele ali—",
  ui_story_1017_10170801_60_dialog_content = "Ele matou dez Eclipsitas seguidos, sem um momento de pausa...",
  ui_story_1017_10170801_61_dialog_content = "Estou curioso sobre essas armas Illumina que são controladas pelos soldados internamente.",
  ui_story_1017_10170801_62_option_content = "(Eu adoraria pilotar um desses)",
  ui_story_1017_10170801_63_dialog_content = "Por motivos de segurança, eu não recomendo tentar isso.",
  ui_story_1017_10170801_64_option_content = "(Adoraria reformar Soroz)",
  ui_story_1017_10170801_65_dialog_content = "Incompatibilidade de estilo. Eu não recomendo tentar isso.",
  ui_story_1017_10170801_66_dialog_content = "É só um pensamento...",
  ui_story_1017_10170801_67_dialog_content = "Vejo que aquele soldado também está aqui.",
  ui_story_1017_10170801_68_dialog_content = "Ela derrotou Reinhardt no exercício militar e já está lutando por Wrath agora. Impressionante.",
  ui_story_1017_10170801_69_dialog_content = "Axelia... Mas ela estava gravemente ferida. O que ela está fazendo aqui?",
  ui_story_1017_10170801_70_dialog_content = "Ei, bom te ver aqui, PlayerName. O display fez seu queixo cair?",
  ui_story_1017_10170801_71_dialog_content = "...",
  ui_story_1017_10170801_72_dialog_content = "Nos encontramos novamente, Capitão dos Cavaleiros.",
  ui_story_1017_10170801_73_dialog_content = "Faz um tempo, oficial... Ah, minhas desculpas, eu deveria chamá-lo de Grande Marechal!",
  ui_story_1017_10170801_74_dialog_content = "Apesar de estar de volta ao seu território, parece que você não está tendo um momento fácil.",
  ui_story_1017_10170801_75_dialog_content = "Você se importaria de revelar o propósito da sua presença e dos soldados da Illumina?",
  ui_story_1017_10170801_76_dialog_content = "Como o Grande Marechal da Federação Illumina, estou liderando uma força de elite para ajudar o Crepúsculo a pacificar os Eclipsitas.",
  ui_story_1017_10170801_77_dialog_content = "É difícil de compreender?",
  ui_story_1017_10170801_78_dialog_content = "É um pouco surpreendente que um ego como Illumina ceda tropas para o Crepúsculo.",
  ui_story_1017_10170801_79_dialog_content = "Bem, se Crepúsculo cair, Illumina é a próxima, então essa é a lógica.",
  ui_story_1017_10170801_80_dialog_content = "Você tem visão, Grande Marechal. Espero que não haja golpes baixos como no exercício.",
  ui_story_1017_10170801_81_dialog_content = "Estou investigando isso também. Como um aliado de Crepúsculo desta vez, espero que possamos trabalhar juntos com prazer.",
  ui_story_1017_10170801_82_dialog_content = "Saúde.",
  ui_story_1017_10170801_83_dialog_content = "Escutem, Legião da Guarda, os Cavaleiros Espinho de Ferro têm mantido o terreno por um longo tempo!",
  ui_story_1017_10170801_84_dialog_content = "Não vamos nos conter e destruir todos os Eclipsitas!",
  ui_story_1017_10170801_85_dialog_content = "Sim!!!",
  ui_story_1017_10170801_86_dialog_content = "Atenção, Cavaleiros do Espinho de Ferro!",
  ui_story_1017_10170801_87_dialog_content = "Ataque em formação de cunha. Aqueles que não desejam ser tratados como uma piada, venham à frente comigo!",
  ui_story_1017_10170801_88_dialog_content = "Sim!!!",
  ui_story_1017_10170901_1_dialog_content = "Ulysses está triste por ajustar minhas descartas e jogá-las na primeira batalha que vê.",
  ui_story_1017_10170901_2_dialog_content = "Ainda tem coragem de seguir em frente?",
  ui_story_1017_10170901_3_dialog_content = "(Eclipsiano) Esses lixos realmente sabem como lutar.",
  ui_story_1017_10170901_4_dialog_content = "Você esperava algo diferente? Eles têm minhas sementes no corpo deles. Você já deveria ter sentido isso.",
  ui_story_1017_10170901_5_dialog_content = "(Eclipsiano)...",
  ui_story_1017_10170901_6_dialog_content = "Sei o que você está pensando, que alguém deveria estar aqui.",
  ui_story_1017_10170901_7_dialog_content = "Então, você estava me esperando? Não consegue lidar nem com um pequeno ataque como esse?",
  ui_story_1017_10170901_8_dialog_content = "É diferente do que esperávamos. Temos penetras na festa.",
  ui_story_1017_10170901_9_dialog_content = "Não é esta uma ótima oportunidade para se vingar? Você deveria estar empolgado.",
  ui_story_1017_10170901_10_dialog_content = "Isso não é da sua conta. Onde fica?",
  ui_story_1017_10170901_11_dialog_content = "Aqui.",
  ui_story_1017_10170901_12_dialog_content = "Mudbundle?",
  ui_story_1017_10170901_13_dialog_content = "Bem, é um pouco nauseante olhar, mas vai aumentar sua velocidade de propulsão. Alguma opinião?",
  ui_story_1017_10170901_14_dialog_content = "Se eu me lembro corretamente, ele pode consumir o ambiente ao seu redor, criar pântanos e seus métodos de atormentar os aurorianos são... bastante únicos, de fato, muito únicos.",
  ui_story_1017_10170901_15_dialog_content = "Vamos lá experimentar.",
  ui_story_1017_10170901_16_dialog_content = "(Eclipsiano) Sim.",
  ui_story_1017_10170901_17_dialog_content = "(Fluxo Escuro Eclipsiano)... convergindo, uma sensação de... fome insaciável!",
  ui_story_1017_10170901_18_dialog_content = "Os Eclipsitas só precisam ficar no pântano de Mudbundle para que as sementes dentro deles se conectem ao seu núcleo.",
  ui_story_1017_10170901_19_dialog_content = "(Eclipsiano) O poder não para de aumentar!!!",
  ui_story_1017_10170901_20_dialog_content = "Tudo o que você precisa fazer em seguida é apenas devorar os Aurorianos e alimentar-se. Quando chegar a hora, Mudbundle cuidará da limpeza.",
  ui_story_1017_10170901_21_dialog_content = "Não sou fã dessas explicações tediosas. Vou deixar isso com você. Nosso próximo encontro será quando inspecionarmos o \"tapete\".",
  ui_story_1017_10170901_22_dialog_content = "(Eclipsiano) COMIDA!!!",
  ui_story_1017_10170901_23_dialog_content = "Vá, toda essa comida é sua antes que Crepúsculo fique atolado na lama!",
  ui_story_1017_10170901_24_dialog_content = "(Eclipsiano) Grrr!!!",
  ui_story_1017_10170901_25_dialog_content = "Oh não, estou sentindo um Darkflow muito forte chegando!",
  ui_story_1017_10170901_26_dialog_content = "Tão cedo? É alguém do comando central?",
  ui_story_1017_10170901_27_dialog_content = "Não tenho certeza, mas a rede de Darkflow realmente está se fechando ao nosso redor.",
  ui_story_1017_10170901_28_dialog_content = "Ah... Ah...",
  ui_story_1017_10170901_29_dialog_content = "O que está acontecendo ali?",
  ui_story_1017_10170901_30_dialog_content = "Reportando, Grande Marechal! Parece que alguns soldados podem estar sendo afetados pelo Darkflow...",
  ui_story_1017_10170901_31_dialog_content = "Forneça ajuda médica o mais rápido possível e me dê um relatório de status sobre os feridos.",
  ui_story_1017_10170901_32_dialog_content = "Sim!",
  ui_story_1017_10170901_33_dialog_content = "(De repente estou sentindo... uma onda de poder...)",
  ui_story_1017_10170901_34_dialog_content = "Você está bem, Grande Marechal?",
  ui_story_1017_10170901_35_dialog_content = "O Fluxo Escuro... realmente faz as pessoas se sentirem desconfortáveis...",
  ui_story_1017_10170901_36_dialog_content = "Recue com seus soldados. Esquadrões 1 e 2 dos Cavaleiros Espinho de Ferro, ataquem o inimigo. 3 e 4 darão cobertura!",
  ui_story_1017_10170901_37_dialog_content = "Não tão rápido. Esses Eclipsitas não têm chance.",
  ui_story_1017_10170901_38_dialog_content = "Continue me ajudando, PlayerName!",
  ui_story_1017_10170901_39_dialog_content = "Um Eclipsite com uma forma única está se aproximando à frente.",
  ui_story_1017_10170901_40_dialog_content = "Será que é alguém do comando central deles?",
  ui_story_1017_10170901_41_dialog_content = "Não é possível confirmar. Mas o Fluxo Escuro detectado é mais forte do que outros Eclipsitas.",
  ui_story_1017_10170901_42_dialog_content = "Entendi. Algo mais para compartilhar?",
  ui_story_1017_10170901_43_dialog_content = "Detecção em andamento. Sincronizarei com você assim que os resultados estiverem disponíveis.",
  ui_story_1017_10170901_44_dialog_content = "Ok, estou contando com você!",
  ui_story_1017_10170901_45_dialog_content = "Um Eclipsite muito poderoso está vindo por aqui, pessoal. Estejam prontos para atacar!",
  ui_story_1017_10170901_46_dialog_content = "Finalmente, não apenas bucha de canhão.",
  ui_story_1017_10170901_47_dialog_content = "Observem e aprendam, cavaleiros. A Legião da Guarda não cairá. Nós conseguimos isso!",
  ui_story_1017_10170901_48_dialog_content = "Tudo bem. Cubram-nos, Cavaleiros do Espinho de Ferro!",
  ui_story_1017_10170901_49_dialog_content = "Sim!!!",
  ui_story_1017_10171001_1_dialog_content = "Ufa... Terminei finalmente!",
  ui_story_1017_10171001_2_dialog_content = "Não consigo acreditar em quantos Eclipsitas ele chamou antes de cair. Isso nos pegou desprevenidos.",
  ui_story_1017_10171001_3_dialog_content = "Estou começando a entender a estratégia deles agora e devemos estar seguros por enquanto.",
  ui_story_1017_10171001_4_dialog_content = "Reportando, Grande Marechal! O número de soldados afetados pelo Fluxo Escuro continua aumentando!",
  ui_story_1017_10171001_5_dialog_content = "Já sabemos a causa?",
  ui_story_1017_10171001_6_dialog_content = "Ainda não. Muitos soldados estão perdendo o controle de seus corpos, entrando em um frenesi <color=#FFB400>sanguinário</color>. A cura está se mostrando completamente inútil.",
  ui_story_1017_10171001_7_dialog_content = "...",
  ui_story_1017_10171001_8_dialog_content = "(Fora de controle e sanguinário... Eu me pergunto se todos se sentiram assim na batalha...)",
  ui_story_1017_10171001_9_dialog_content = "Setor leste! Capitã, alguns Eclipsitas estão causando problemas novamente nas trincheiras!",
  ui_story_1017_10171001_10_dialog_content = "Parece que este Eclipsita não é o líder.",
  ui_story_1017_10171001_11_dialog_content = "Alguém tem alguma pista?",
  ui_story_1017_10171001_12_dialog_content = "Quando eu estava tratando deles, percebi que a influência do Darkflow nos soldados era pior do que o que costumamos ver.",
  ui_story_1017_10171001_13_dialog_content = "Talvez tenhamos que levá-los a um hospital para um tratamento mais aprofundado e assim melhorarem.",
  ui_story_1017_10171001_14_dialog_content = "Grande Marechal Wrath, deixe-me levar os soldados afetados em suas forças para o hospital.",
  ui_story_1017_10171001_15_dialog_content = "Eu estava prestes a fazer esse pedido. Obrigado! Illumina irá compensá-lo após a guerra.",
  ui_story_1017_10171001_16_dialog_content = "É o que eu faço.",
  ui_story_1017_10171001_17_dialog_content = "Grande Marechal! Relatórios indicam que alguns soldados se separaram da unidade e estão se movendo na mesma direção...",
  ui_story_1017_10171001_18_dialog_content = "Como se estivessem sendo impulsionados por alguma força desconhecida.",
  ui_story_1017_10171001_19_dialog_content = "É possível que o comando central deles esteja por trás disso?",
  ui_story_1017_10171001_20_dialog_content = "Não posso descartar isso. Nós teorizamos que o curso do Fluxo Escuro foi manipulado pelo comando central.",
  ui_story_1017_10171001_21_dialog_content = "E os soldados em Crepúsculo, eles estão sentindo a mesma coisa?",
  ui_story_1017_10171001_22_dialog_content = "Capitão, notamos algo...",
  ui_story_1017_10171001_23_dialog_content = "Tem certeza?",
  ui_story_1017_10171001_24_dialog_content = "Sim capitão.",
  ui_story_1017_10171001_25_dialog_content = "Todos esses soldados se comportando estranhamente são das suas forças, Grande Marechal.",
  ui_story_1017_10171001_26_dialog_content = "O que você quer chegar?",
  ui_story_1017_10171001_27_dialog_content = "Não vou enrolar, então. Nas últimas ofensivas, seus soldados agiram de forma errática.",
  ui_story_1017_10171001_28_dialog_content = "Será que foi porque o inimigo era muito forte...",
  ui_story_1017_10171001_29_dialog_content = "Ou você tem toupeiras na sua unidade, Grande Marechal?",
  ui_story_1017_10171001_30_dialog_content = "Você está duvidando das intenções da Illumina ao ajudar Crepúsculo?",
  ui_story_1017_10171001_31_dialog_content = "De forma alguma. Eu apenas acho que nosso inimigo não é comum. Como capitã, tenho que ser responsável pelos meus homens.",
  ui_story_1017_10171001_32_dialog_content = "Com base no que temos, seus soldados estão começando a confundir Aurorianos com Eclipsitas.",
  ui_story_1017_10171001_33_dialog_content = "Morda sua língua! Eu nunca faria truques obscuros como esse!",
  ui_story_1017_10171001_34_dialog_content = "Capitão Leo, Grande Marechal Wrath, acredito que todos estão aqui pelo bem de Crepúsculo.",
  ui_story_1017_10171001_35_dialog_content = "Mesmo não tendo certeza do motivo dos soldados não terem seguido suas ordens...",
  ui_story_1017_10171001_36_dialog_content = "Estou preocupado que seja um truque do nosso inimigo para deliberadamente nublar nosso julgamento.",
  ui_story_1017_10171001_37_dialog_content = "Meus soldados certamente não seguiram minhas ordens completamente na última batalha.",
  ui_story_1017_10171001_38_dialog_content = "E como Grande Marechal, sou responsável por tudo aqui em nome da Illumina.",
  ui_story_1017_10171001_39_dialog_content = "Vou te dar uma resposta satisfatória na hora certa.",
  ui_story_1017_10171001_40_dialog_content = "Mas se você insistir em duvidar dos motivos da Illumina, considerarei isso um ato de guerra.",
  ui_story_1017_10171001_41_dialog_content = "\"Ato de guerra\" seria uma grande exagero do que foi apenas um rápido lembrete de minha parte.",
  ui_story_1017_10171001_42_dialog_content = "Você é novo em sua posição, então, por favor, aprenda as tendências de luta daqueles que estão sob seu comando.",
  ui_story_1017_10171001_43_dialog_content = "Se eles demonstrarem mais traição ou até mesmo prejudicarem meus soldados, responderei à altura.",
  ui_story_1017_10171001_44_dialog_content = "Seu latido é pior que sua mordida.",
  ui_story_1017_10171001_45_dialog_content = "Se é uma luta contra a Illumina que você quer, acredite em mim, eu sozinho serei mais do que você pode enfrentar!",
  ui_story_1017_10171001_46_dialog_content = "Grande Marechal! Relatando uma situação urgente!",
  ui_story_1017_10171001_47_dialog_content = "A equipe de combate do Tenente Axelia está desaparecida.",
  ui_story_1017_10171001_48_dialog_content = "???",
  ui_story_1017_10171001_49_dialog_content = "De qual área ela é responsável?",
  ui_story_1017_10171001_50_dialog_content = "Setor oeste, Grande Marechal, onde um grupo de Eclipsitas ainda está se movendo em direção ao Crepúsculo agora.",
  ui_story_1017_10171001_51_dialog_content = "Guarda da Legião, estamos nos movendo para oeste para matar Eclipsitas!",
  ui_story_1017_10171001_52_dialog_content = "Todos os feridos, continuem em frente, a menos que tenham uma perna quebrada ou tenham perdido a cabeça!",
  ui_story_1017_10171001_53_dialog_content = "Denuncie qualquer soldado com comportamentos suspeitos a mim imediatamente!",
  ui_story_1017_10171001_54_dialog_content = "Sim!",
  ui_story_1017_10171001_55_dialog_content = "Você vai comigo, PlayerName.",
  ui_story_1017_10171001_56_dialog_content = "Eu?",
  ui_story_1017_10171001_57_dialog_content = "Agora!",
  ui_story_1017_10171001_58_dialog_content = "...",
  ui_story_1017_10171001_59_dialog_content = "Capitão, devemos seguir por conta própria?",
  ui_story_1017_10171001_60_dialog_content = "Uma vassoura nova varre bem. Não lidar com os problemas agora só vai dificultar as coisas mais tarde.",
  ui_story_1017_10171001_61_dialog_content = "Prepare-se para seguir para o leste. Está perto da área residencial. Não podemos deixar nem um Eclipsita entrar.",
  ui_story_1017_10171001_62_dialog_content = "Sim, Capitão!",
  ui_story_1017_10171001_63_dialog_content = "Leo, o pessoal do hospital está aqui. Vou levar os feridos graves para lá.",
  ui_story_1017_10171001_64_dialog_content = "Por que não salvamos o hospital para os civis feridos? Vou pedir aos meus amigos na <color=#FFB400>pousada</color> para ajudar nossos feridos.",
  ui_story_1017_10171001_65_dialog_content = "Capitão, o bar já...",
  ui_story_1017_10171001_66_dialog_content = "Então, vamos transformar a equipe de Logística em uma unidade médica por enquanto e trocar o <color=#FFB400>minério</color> restante com o Forte Lumo por suprimentos médicos.",
  ui_story_1017_10171001_67_dialog_content = "Mas Capitão, a Fortaleza Lumo já fechou seus portões!",
  ui_story_1017_10171001_68_dialog_content = "É por isso que eu disse para trocar o minério com eles!",
  ui_story_1017_10171001_69_dialog_content = "Entendi, Capitão!",
  ui_story_1017_10171001_70_dialog_content = "Tudo fica problemático quando a Fortaleza Lumo está envolvida.",
  ui_story_1017_10171001_71_dialog_content = "Embora eu tenha nascido em Crepúsculo, ainda sou de Lumópolis e vou tentar ajudar.",
  ui_story_1017_10171001_72_dialog_content = "É raro ver alguém orgulhoso de ser uma pessoa de Lumópolis.",
  ui_story_1017_10171001_73_dialog_content = "Facções não são importantes. Eu só quero que todos em Crepúsculo vivam em paz.",
  ui_story_1017_10171001_74_dialog_content = "Você está pensando muito à frente.",
  ui_story_1017_10171001_75_dialog_content = "Sem ajuda de Illumina e Lumopolis, Crepúsculo não durará, muito menos em paz.",
  ui_story_1017_10171001_76_dialog_content = "Quer saber qual é a coisa mais importante para um exército?",
  ui_story_1017_10171001_77_dialog_content = "Coração. Precisamos estar unidos de coração para vencer. Infelizmente, o exército Illumina que vemos carece totalmente de coesão.",
  ui_story_1017_10171001_78_dialog_content = "O Colossus consegue ver todos os movimentos do inimigo?",
  ui_story_1017_10171001_79_dialog_content = "Cristalino, PlayerName.",
  ui_story_1017_10171001_80_dialog_content = "Sim, Wrath... Grande Marechal.",
  ui_story_1017_10171001_81_dialog_content = "Não acha isso estranho?",
  ui_story_1017_10171001_82_dialog_content = "...",
  ui_story_1017_10171001_83_dialog_content = "O que há com essa expressão?",
  ui_story_1017_10171001_84_dialog_content = "Ah, nada... É só que ainda não estou totalmente acostumado a trabalhar com o Grande Marechal.",
  ui_story_1017_10171001_85_dialog_content = "Hmm, você não é bem próximo de Reinhardt?",
  ui_story_1017_10171001_86_dialog_content = "Então, por que você fica nervoso perto de mim? Qual é a diferença entre eu e ela?",
  ui_story_1017_10171001_87_dialog_content = "(Precisa mesmo perguntar...?)",
  ui_story_1017_10171001_88_dialog_content = "Apenas me chame pelo nome. Também vou te chamar pelo nome por respeito.",
  ui_story_1017_10171001_89_dialog_content = "Entendi, Wrath...",
  ui_story_1017_10171001_90_dialog_content = "Tenho um favor a pedir a você em relação aos meus soldados.",
  ui_story_1017_10171001_91_dialog_content = "Claro.",
  ui_story_1017_10171001_92_dialog_content = "Não tenho certeza se eles vão piorar nas próximas batalhas.",
  ui_story_1017_10171001_93_dialog_content = "Por enquanto, eu preciso que você bloqueie as posições deles e resolva isso antes que nosso inimigo lance um grande ataque.",
  ui_story_1017_10171001_94_dialog_content = "Sem problemas. Soroz também pode ajudar.",
  ui_story_1017_10171001_95_dialog_content = "Procurando soldados anormais. Tempo estimado: 60s.",
  ui_story_1017_10171001_96_dialog_content = "Tenho uma pergunta.",
  ui_story_1017_10171001_97_dialog_content = "O que foi?",
  ui_story_1017_10171001_98_dialog_content = "Como é que o Axelia está no seu time?",
  ui_story_1017_10171001_99_dialog_content = "Se bem me lembro, ela se machucou seriamente no exercício e ainda deve estar se recuperando.",
  ui_story_1017_10171001_100_dialog_content = "Essa é a garra dos soldados Illumina, entendeu?",
  ui_story_1017_10171001_101_dialog_content = "Arriscar a vida e entrar em batalha repetidas vezes?",
  ui_story_1017_10171001_102_dialog_content = "Você acha que ela não consegue fazer isso?",
  ui_story_1017_10171001_103_dialog_content = "Eu realmente acho que ela pode, eu só sinto que Axelia...",
  ui_story_1017_10171001_104_dialog_content = "Ela não temeria nem cobiçaria a guerra como as pessoas que eu conheço.",
  ui_story_1017_10171001_105_dialog_content = "Eu senti quase nenhuma emoção dela em nossos encontros anteriores.",
  ui_story_1017_10171001_106_dialog_content = "A emoção não é uma arma para a vitória, Celestita.",
  ui_story_1017_10171001_107_dialog_content = "Não, o que eu quero dizer é—",
  ui_story_1017_10171001_108_dialog_content = "Eu sei o que você está dizendo.",
  ui_story_1017_10171001_109_dialog_content = "Antes de me tornar o Grande Marechal, eu tinha as mesmas dúvidas que você.",
  ui_story_1017_10171001_110_dialog_content = "Mas agora eu entendo isso:",
  ui_story_1017_10171001_111_dialog_content = "Para vencer alguém completamente invencível, você deve abandonar sua antiga identidade e ver as coisas pela perspectiva dessa pessoa.",
  ui_story_1017_10171001_112_dialog_content = "Abandonar a velha identidade... Mas vejo que você continua liderando a carga como sempre.",
  ui_story_1017_10171001_113_dialog_content = "Para um Celestita agraciado com percepção sobrenatural, sua mente é bem simples.",
  ui_story_1017_10171001_114_dialog_content = "Estou verde de inveja...",
  ui_story_1017_10171001_115_dialog_content = "Isso não soa como um elogio...",
  ui_story_1017_10171001_116_dialog_content = "Você entendeu errado. Mantenha os olhos na estrada e cuidado com os buracos.",
  ui_story_1017_10171001_117_dialog_content = "Encontrado um soldado anormal sob um obstáculo 20 metros à frente.",
  ui_story_1017_10171001_118_dialog_content = "Soldado errático à frente, Wrath!",
  ui_story_1017_10171001_119_dialog_content = "Vamos lá.",
  ui_story_1017_10171001_120_dialog_content = "...",
  ui_story_1017_10171001_121_dialog_content = "O que você está sentindo?",
  ui_story_1017_10171001_122_dialog_content = "...",
  ui_story_1017_10171001_123_dialog_content = "Ele ainda está um pouco consciente, mas não consegue ouvir você falar.",
  ui_story_1017_10171001_124_dialog_content = "Deixa eu tentar conectar minha mente com ele e ver o que consigo descobrir.",
  ui_story_1017_10171001_125_dialog_content = "Claro.",
  ui_story_1017_10171001_126_option_content = "Conexão mental—",
  ui_story_1017_10171001_127_dialog_content = "(Estou em um pântano?)",
  ui_story_1017_10171001_128_dialog_content = "(Cobre o chão como um tapete gigante...)",
  ui_story_1017_10171001_129_dialog_content = "(Os prédios dilapidados por aqui parecem familiares...)",
  ui_story_1017_10171001_130_dialog_content = "(Deve ser Crepúsculo mesmo...)",
  ui_story_1017_10171001_131_dialog_content = "(Mas de onde veio toda essa lama? Ela continua se acumulando sob os meus pés...)",
  ui_story_1017_10171001_132_dialog_content = "(Não parece que está fluindo em uma direção específica...)",
  ui_story_1017_10171001_133_dialog_content = "Ugh...",
  ui_story_1017_10171001_134_dialog_content = "Como você está se sentindo? Mal?",
  ui_story_1017_10171001_135_dialog_content = "O Darkflow está me dando uma leve dor de cabeça, mas vou aguentar.",
  ui_story_1017_10171001_136_dialog_content = "O que está na mente dos soldados é um Crepúsculo coberto pelo atoleiro que parece durar para sempre...",
  ui_story_1017_10171001_137_dialog_content = "A lama continuava se acumulando sob meus pés e parecia que eu poderia cair a qualquer momento.",
  ui_story_1017_10171001_138_dialog_content = "Pântano, Fluxo Escuro... A lama em suas mentes provavelmente está relacionada ao Fluxo Escuro na realidade.",
  ui_story_1017_10171001_139_dialog_content = "Isso pode ser a razão para o comportamento errático deles...",
  ui_story_1017_10171001_140_dialog_content = "Se conseguirmos descobrir de onde veio a lama, talvez possamos localizar o inimigo central...",
  ui_story_1017_10171001_141_dialog_content = "Que diabos...!",
  ui_story_1017_10171001_142_dialog_content = "Espere, como isso pode ser?",
  ui_story_1017_10171001_143_dialog_content = "Este é um dos seus?",
  ui_story_1017_10171001_144_dialog_content = "Não é óbvio? Quase matei ele!",
  ui_story_1017_10171001_145_dialog_content = "O Darkflow parece ter atingido-o com força suficiente para fazê-lo perder o juízo...",
  ui_story_1017_10171001_146_dialog_content = "Deixe-me tentar sondar a mente dele.",
  ui_story_1017_10171001_147_dialog_content = "Vá o mais longe que puder, mas pare assim que sentir perigo.",
  ui_story_1017_10171001_148_option_content = "Conexão mental—",
  ui_story_1017_10171001_149_dialog_content = "(Este é o mesmo cenário, mas a lama está fluindo muito mais rápido do que antes...)",
  ui_story_1017_10171001_150_dialog_content = "(E está vindo da mesma direção desta vez.)",
  ui_story_1017_10171001_151_dialog_content = "(É essa a Noite Eterna?)",
  ui_story_1017_10171001_152_dialog_content = "(O céu sombrio se mistura perfeitamente com a lama.)",
  ui_story_1017_10171001_153_dialog_content = "(Tem que ser... É onde fica o comando central...)",
  ui_story_1017_10171001_154_dialog_content = "(Oh não—)",
  ui_story_1017_10171001_155_dialog_content = "Você... Eclipsite!",
  ui_story_1017_10171001_156_dialog_content = "Abaixe-se!",
  ui_story_1017_10171001_157_dialog_content = "Wrath? O que aconteceu com ele?",
  ui_story_1017_10171001_158_dialog_content = "Não se preocupe, ele acabou de desmaiar.",
  ui_story_1017_10171001_159_dialog_content = "Mas não há necessidade de investigar mais. Até eu consigo sentir o Darkflow nele agora.",
  ui_story_1017_10171001_160_dialog_content = "Dê uma olhada no horizonte ali, está ficando cada vez mais escuro...",
  ui_story_1017_10171001_161_dialog_content = "É essa a direção! A lama estava fluindo cada vez mais rápido da Noite Eterna em sua mente.",
  ui_story_1017_10171001_162_dialog_content = "Deve ser onde fica o comando central!",
  ui_story_1017_10171001_163_dialog_content = "Então encontramos a localização do inimigo?",
  ui_story_1017_10171001_164_dialog_content = "Tenho quase certeza. Provavelmente passei tempo demais com o Darkflow, já que estou ficando tonto só de olhar ao redor...",
  ui_story_1017_10171001_165_dialog_content = "Você está correto, o céu sobre a Noite Eterna está ficando mais escuro.",
  ui_story_1017_10171001_166_dialog_content = "Parece que o Darkflow pode controlar soldados e alterar o ambiente. Há um cheiro rançoso no ar.",
  ui_story_1017_10171001_167_dialog_content = "<color=#e8d9bb>Balbuciar, balbuciar...</color>",
  ui_story_1017_10171001_168_dialog_content = "Você ouviu isso?",
  ui_story_1017_10171001_169_dialog_content = "Isso parece líquido fluindo...",
  ui_story_1017_10171001_170_dialog_content = "Líquido fluindo... Ah não, não me diga que há um deslizamento de terra no Crepúsculo!",
  ui_story_1017_10171001_171_dialog_content = "E está vindo da Noite Eterna!",
  ui_story_1017_10171001_172_dialog_content = "Acredito que o inimigo central está se aproximando.",
  ui_story_1017_10171001_173_dialog_content = "<color=#e8d9bb>Babble, babble...</color>",
  ui_story_1017_10171001_174_dialog_content = "PlayerName, um grande enxame de Eclipsitas foi detectado a oeste. Estimativa para entrar no seu raio de detecção em 5 segundos.",
  ui_story_1017_10171001_175_dialog_content = "Tão rápido? Deixa eu conferir...",
  ui_story_1017_10171001_176_option_content = "Conexão mental—",
  ui_story_1017_10171001_177_dialog_content = "(Preto por toda parte... Realmente é um pântano!)",
  ui_story_1017_10171001_178_dialog_content = "É exatamente isso que eu vi em suas mentes, Wrath! Os Eclipsitas estão vindo para cá com a lama!",
  ui_story_1017_10171001_179_dialog_content = "Hã?",
  ui_story_1017_10171001_180_dialog_content = "Atualize os Cavaleiros Lumo agora e diga-lhes para evacuar as pessoas!",
  ui_story_1017_10171001_181_dialog_content = "Sim, Grande Marechal!",
  ui_story_1017_10171001_182_dialog_content = "Recon, venha comigo verificar isso. Engine VII, cubra a retaguarda!",
  ui_story_1017_10171001_183_dialog_content = "Ninguém se move sem meu comando. Se você sentir algo errado, desengate imediatamente!",
  ui_story_1017_10171001_184_dialog_content = "Grande Marechal! Soldados do pelotão leste estão enlouquecendo um após o outro!",
  ui_story_1017_10171001_185_dialog_content = "Leste? Mas o que estou sentindo é para o oeste...",
  ui_story_1017_10171001_186_dialog_content = "Cuidado!",
  ui_story_1017_10171001_187_dialog_content = "Até aqui? Mas como?",
  ui_story_1017_10171001_188_dialog_content = "É óbvio que estamos cercados.",
  ui_story_1017_10171001_189_dialog_content = "Fique perto de mim, PlayerName!",
  ui_story_1017_10171101_1_dialog_content = "<color=#e8d9bb>Um prédio de laboratório em Illumina, não muito tempo atrás...</color>",
  ui_story_1017_10171101_2_dialog_content = "O que está fazendo?",
  ui_story_1017_10171101_3_dialog_content = "Só, sabe, patrulhando... É, é minha vez de vigiar essa área hoje...",
  ui_story_1017_10171101_4_dialog_content = "Este é o laboratório do Professor Ulysses e não há patrulhas regulares programadas.",
  ui_story_1017_10171101_5_dialog_content = "Hum, bem...",
  ui_story_1017_10171101_6_dialog_content = "Quem te enviou?",
  ui_story_1017_10171101_7_dialog_content = "Eu...",
  ui_story_1017_10171101_8_dialog_content = "E-Eu sinto muito, Comandante Yingel! Eu não deveria ter mentido. Eu estava apenas...",
  ui_story_1017_10171101_9_dialog_content = "Eu sabia que meu irmão fazia parte do maior <color=#FFB400>experimento</color> da história da Illumina, e eu estava realmente com inveja, e foi por isso que eu...",
  ui_story_1017_10171101_10_dialog_content = "Este projeto é altamente classificado e nenhum membro da família deve saber até que seja bem-sucedido.",
  ui_story_1017_10171101_11_dialog_content = "Meu irmão e eu somos muito próximos, então eu sei tudo sobre ele. Por favor, confie em mim! Estou falando a verdade...",
  ui_story_1017_10171101_12_dialog_content = "...",
  ui_story_1017_10171101_13_dialog_content = "Desde que ele entrou nesse experimento, tanto eu quanto a mamãe estamos muito felizes por ele!",
  ui_story_1017_10171101_14_dialog_content = "Mas, devido à minha experiência limitada, não fui selecionado...",
  ui_story_1017_10171101_15_dialog_content = "Você está se sentindo abatido?",
  ui_story_1017_10171101_16_dialog_content = "Sim...",
  ui_story_1017_10171101_17_dialog_content = "Haverá outras oportunidades no futuro...",
  ui_story_1017_10171101_18_dialog_content = "Sério? Ainda terei outra chance de ser a Estrela da Illumina?",
  ui_story_1017_10171101_19_dialog_content = "Claro.",
  ui_story_1017_10171101_20_dialog_content = "Obrigado, Comandante Yingel! Vou embora imediatamente.",
  ui_story_1017_10171101_21_dialog_content = "Tudo bem. Eles devem estar lutando contra os Eclipsitas neste exato momento.",
  ui_story_1017_10171101_22_dialog_content = "Sim, meu irmão é incrivelmente talentoso... Os Eclipsitas não terão chance contra ele!",
  ui_story_1017_10171101_23_dialog_content = "...",
  ui_story_1017_10171101_24_dialog_content = "Ah, desculpe, Comandante Yingel, não vou tomar mais do seu tempo. Bom dia!",
  ui_story_1017_10171101_25_dialog_content = "Então, esse é o futuro da Illumina?",
  ui_story_1017_10171101_26_dialog_content = "...",
  ui_story_1017_10171101_27_dialog_content = "<size=30>Professor...</size>",
  ui_story_1017_10171101_28_dialog_content = "...",
  ui_story_1017_10171101_29_dialog_content = "Professor Ulysses?",
  ui_story_1017_10171101_30_dialog_content = "Ah, aí está você. Como está indo a investigação?",
  ui_story_1017_10171101_31_dialog_content = "Isso não é sobre trabalho. É outra coisa...",
  ui_story_1017_10171101_32_dialog_content = "O que foi?",
  ui_story_1017_10171101_33_dialog_content = "Senhor, Axelia foi gravemente ferido no exercício conjunto.",
  ui_story_1017_10171101_34_dialog_content = "Seu oponente era Reinhardt, o mais difícil que ela havia enfrentado até aquele momento.",
  ui_story_1017_10171101_35_dialog_content = "...",
  ui_story_1017_10171101_36_dialog_content = "Há algo que você queira dizer?",
  ui_story_1017_10171101_37_dialog_content = "Senhor, Axelia sofreu muitas lesões graves, mas ainda está lutando pela Illumina.",
  ui_story_1017_10171101_38_dialog_content = "Estou preocupado que, após o Programa Phospherus 2.0, ela...",
  ui_story_1017_10171101_39_dialog_content = "Neste caso, você está exagerando.",
  ui_story_1017_10171101_40_dialog_content = "Aqui está a comparação dos dois conjuntos de dados. Dê uma olhada.",
  ui_story_1017_10171101_41_dialog_content = "Após o Phospherus 2.0, o desempenho físico dos soldados melhorou 10 vezes.",
  ui_story_1017_10171101_42_dialog_content = "Pode chegar a 20, até mesmo 50 vezes no futuro.",
  ui_story_1017_10171101_43_dialog_content = "Axelia obteve uma pontuação muito alta nos dados pós-experimento com significativamente menos desgaste de batalha.",
  ui_story_1017_10171101_44_dialog_content = "Isso significa que ela está no auge de sua capacidade.",
  ui_story_1017_10171101_45_dialog_content = "E isso vale para todos os soldados enviados para Crepúsculo.",
  ui_story_1017_10171101_46_dialog_content = "Mas senhor, eu ainda acho que enviar Axelia de volta à batalha logo após ela se recuperar é... impiedoso...",
  ui_story_1017_10171101_47_dialog_content = "E isso vale para todos os jovens soldados que acreditam ser as \"estrelas do futuro\" da Illumina.",
  ui_story_1017_10171101_48_dialog_content = "Sim, a realidade é implacável, e esse é o dever deles como soldados da Illumina.",
  ui_story_1017_10171101_49_dialog_content = "Realmente tem que ser assim?",
  ui_story_1017_10171101_50_dialog_content = "Se eles não perceberem que foi assim que conseguiram seus poderes...",
  ui_story_1017_10171101_51_dialog_content = "Seria devastador para eles quando estivessem em queda livre após atingir o auge.",
  ui_story_1017_10171101_52_dialog_content = "Yingel, sua linha de questionamento não é adequada para um oficial de inteligência.",
  ui_story_1017_10171101_53_dialog_content = "A menos que você tenha outros pedidos, devo retomar meu experimento.",
  ui_story_1017_10171101_54_dialog_content = "Mas Professor—",
  ui_story_1017_10171101_55_dialog_content = "Antes de se explicar, tente descobrir o objetivo.",
  ui_story_1017_10171101_56_dialog_content = "Se você não conseguir, acho necessário largar o que está fazendo e visitar meu laboratório com mais frequência.",
  ui_story_1017_10171101_57_dialog_content = "Os sujeitos um em dez mil vieram aqui por apenas um motivo—",
  ui_story_1017_10171101_58_dialog_content = "Ultrapassar os limites físicos, derrotar os Eclipsitas, proteger Illumina e os Aurorianos, é isso.",
  ui_story_1017_10171101_59_dialog_content = "Um Auroriano morre neste laboratório todos os dias, mas isso é melhor do que todos nós morrermos quando os Eclipsitas chegarem.",
  ui_story_1017_10171101_60_dialog_content = "Meu objetivo é alcançar avanços e aprimorar o arsenal. Sem melhorias, não há futuro para os Aurorians.",
  ui_story_1017_10171101_61_dialog_content = "O experimento, arsenal, dados... Eu aprecio tudo o que você está fazendo.",
  ui_story_1017_10171101_62_dialog_content = "Mas não posso justificar sacrificar os soldados, especialmente quando eles não estão cientes das consequências.",
  ui_story_1017_10171101_63_dialog_content = "Bem, alguns estão cientes das consequências.",
  ui_story_1017_10171101_64_dialog_content = "Ela está disposta a fazer isso pelo objetivo. E você?",
  ui_story_1017_10171101_65_dialog_content = "Não, não foi assim que a Illumina chegou tão longe...",
  ui_story_1017_10171101_66_dialog_content = "Argh!",
  ui_story_1017_10171101_67_dialog_content = "Que som é esse...?",
  ui_story_1017_10171101_68_dialog_content = "Já que o experimento está começando, você pode também observar a diferença entre os dois grupos.",
  ui_story_1017_10171101_69_dialog_content = "(Não... o som...)",
  ui_story_1017_10171101_70_dialog_content = "Ambos melhoram as condições físicas, mas os resultados são completamente diferentes.",
  ui_story_1017_10171101_71_dialog_content = "O sujeito à esquerda fica mais explosivo por mais tempo com a nova Semente.",
  ui_story_1017_10171101_72_dialog_content = "O da direita está quase totalmente devorado pelos Eclipsitas.",
  ui_story_1017_10171101_73_dialog_content = "Agora você entende por que Reinhardt deve ser removido a todo custo?",
  ui_story_1017_10171101_74_dialog_content = "O sujeito à esquerda...",
  ui_story_1017_10171101_75_dialog_content = "Independentemente de como você interpreta a história e a verdade, é assim que o mundo real é.",
  ui_story_1017_10171101_76_dialog_content = "Esta é a única maneira de sobrevivermos e progredirmos.",
  ui_story_1017_10171101_77_dialog_content = "O Darkover está chegando, então devemos recorrer a isso para nos mantermos à frente dele.",
  ui_story_1017_10171101_X78_dialog_content = "(Minha cabeça... dói...)",
  ui_story_1017_10171101_78_dialog_content = "Professor, o sujeito à esquerda está mostrando uma forte reação ao Darkflow no ambiente à direita!",
  ui_story_1017_10171101_79_dialog_content = "Doutor, o indivíduo à esquerda está mostrando uma forte reação ao Darkflow na sala à direita!",
  ui_story_1017_10171101_80_dialog_content = "Sim, é assim que deve ser. As sementes reagem a outras sementes.",
  ui_story_1017_10171101_81_dialog_content = "O que será que ele vai fazer em seguida...",
  ui_story_1017_10171101_X82_dialog_content = "...",
  ui_story_1017_10171101_82_dialog_content = "Professor, ele está tentando quebrar o vidro e entrar na sala à direita!",
  ui_story_1017_10171101_83_dialog_content = "Doutor, ele está tentando quebrar o vidro e chegar à sala à direita!",
  ui_story_1017_10171101_84_dialog_content = "Vejo que ele nem está tentando abrir a porta, apenas quebrando o vidro.",
  ui_story_1017_10171101_85_dialog_content = "Muito bom, desta vez não aumentou o cérebro e compensou os defeitos do primeiro lote de Sementes.",
  ui_story_1017_10171101_86_dialog_content = "Como isso é diferente de criar Eclipsitas reais?",
  ui_story_1017_10171101_87_dialog_content = "Derrotar os Eclipsitas requer meios extraordinários.",
  ui_story_1017_10171101_88_dialog_content = "Fora do combate, ele ainda é um companheiro Aurorian.",
  ui_story_1017_10171101_89_dialog_content = "Não, os Aurorianos da Illumina nunca serão companheiros dos Eclipsitas... Eu imploro, por favor, parem o experimento imediatamente.",
  ui_story_1017_10171101_90_dialog_content = "...",
  ui_story_1017_10171101_91_dialog_content = "Professor, ele conseguiu! Ele começou a devorar o Eclipsite!",
  ui_story_1017_10171101_92_dialog_content = "Professor Ulysses, por favor, pare o experimento imediatamente!",
  ui_story_1017_10171101_93_dialog_content = "Está apenas começando.",
  ui_story_1017_10171101_94_dialog_content = "Um soldado Illumina está comendo Eclipsitas! Isso é uma grave violação dos procedimentos... Por favor, pare agora!",
  ui_story_1017_10171101_95_dialog_content = "Se me lembro bem, escrevi os procedimentos.",
  ui_story_1017_10171101_96_dialog_content = "Verificações e avanços são o objetivo de todos os experimentos.",
  ui_story_1017_10171101_97_dialog_content = "Professor! A cobaia está batendo no nosso vidro!",
  ui_story_1017_10171101_98_dialog_content = "(Tanto ódio assassino em seus olhos... Ele está olhando para mim?)",
  ui_story_1017_10171101_99_dialog_content = "Por favor... Pare o experimento...",
  ui_story_1017_10171101_100_dialog_content = "Docente, algo está errado com o Comandante Yingel!",
  ui_story_1017_10171101_101_dialog_content = "Como você está se sentindo, Yingel?",
  ui_story_1017_10171101_102_dialog_content = "Minha cabeça... dói... muito...",
  ui_story_1017_10171101_103_dialog_content = "Por que você não sai e faz uma pausa?",
  ui_story_1017_10171101_104_dialog_content = "Anote, a reação e a distância entre as Sementes precisam de mais confirmação.",
  ui_story_1017_10171101_105_dialog_content = "Professor! O vidro acabou de—",
  ui_story_1017_10171101_106_dialog_content = "Chame a segurança!",
  ui_story_1017_10171101_107_dialog_content = "Não! Mova-se, Professor!",
  ui_story_1017_10171101_108_dialog_content = "...",
  ui_story_1017_10171201_1_dialog_content = "Não podemos ir mais longe! O atoleiro está se espalhando muito rápido!",
  ui_story_1017_10171201_2_dialog_content = "Todos, dispersem e recuem!",
  ui_story_1017_10171201_3_dialog_content = "Mas você vai continuar?",
  ui_story_1017_10171201_4_dialog_content = "Alguns dos meus soldados estão presos lá dentro. Não vou deixá-los para trás.",
  ui_story_1017_10171201_5_dialog_content = "Mas metade de Crepúsculo está coberta de lama agora...",
  ui_story_1017_10171201_6_dialog_content = "É por isso que devemos eliminar o inimigo central antes que ele afunde toda a cidade.",
  ui_story_1017_10171201_7_dialog_content = "A partir do ataque, o inimigo central está se movendo de forma errática.",
  ui_story_1017_10171201_8_dialog_content = "É uma pílula, com certeza. Nos cercando com Eclipsitas enquanto se esconde na lama e atira!",
  ui_story_1017_10171201_9_dialog_content = "Devemos seguir em frente para encontrá-lo.",
  ui_story_1017_10171201_10_dialog_content = "Estou preocupado que mais soldados morrerão se isso continuar...",
  ui_story_1017_10171201_11_dialog_content = "Ninguém está morrendo à toa, PlayerName. Não sinta pena deles!",
  ui_story_1017_10171201_12_dialog_content = "Eu só...",
  ui_story_1017_10171201_13_dialog_content = "Não é necessário. Todos já sabiam da possibilidade antes de virmos.",
  ui_story_1017_10171201_14_dialog_content = "Na verdade, eu queria perguntar, por que alguns deles seriam enviados para a batalha?",
  ui_story_1017_10171201_15_dialog_content = "O que é que você tem conhecimento privilegiado?",
  ui_story_1017_10171201_16_dialog_content = "Estou apenas supondo aqui...",
  ui_story_1017_10171201_17_dialog_content = "Ter uma reação tão intensa ao Darkflow, eles e os Eclipsitas provavelmente compartilham a mesma coisa em seus corpos.",
  ui_story_1017_10171201_18_dialog_content = "Senti tanta familiaridade quando me conectei mentalmente com eles.",
  ui_story_1017_10171201_19_dialog_content = "Foi o mesmo quando implantaram uma Semente em mim...",
  ui_story_1017_10171201_20_dialog_content = "Essa é a única explicação para a mudança deles e até mesmo seguindo o comando central.",
  ui_story_1017_10171201_21_dialog_content = "Isso não aconteceu com os soldados em Crepúsculo.",
  ui_story_1017_10171201_22_dialog_content = "Como você se sente em relação a mim?",
  ui_story_1017_10171201_23_dialog_content = "Você...",
  ui_story_1017_10171201_24_dialog_content = "Bem, francamente, percebi o motivo de terem me enviado para Crepúsculo no momento em que os soldados começaram a mostrar sinais.",
  ui_story_1017_10171201_25_dialog_content = "Não está aqui para ajudar Crepúsculo?",
  ui_story_1017_10171201_26_dialog_content = "Realmente precisamos de ajuda agora, mas você vê alguém vindo?",
  ui_story_1017_10171201_27_dialog_content = "...",
  ui_story_1017_10171201_28_dialog_content = "Mensagens e sinais de socorro não foram respondidos durante toda a batalha.",
  ui_story_1017_10171201_29_dialog_content = "Talvez seja devido à interferência do Darkflow?",
  ui_story_1017_10171201_30_dialog_content = "Você não entende a Illumina. Nós nunca lutamos batalhas para as quais não estávamos preparados, a menos que houvesse outro propósito.",
  ui_story_1017_10171201_31_dialog_content = "Só podemos confiar em nós mesmos agora.",
  ui_story_1017_10171201_32_dialog_content = "Meu único arrependimento é que provavelmente vou acabar como Reinhardt...",
  ui_story_1017_10171201_33_dialog_content = "Que pílula amarga para engolir!",
  ui_story_1017_10171201_34_dialog_content = "Estarei com você nessa, Wrath...",
  ui_story_1017_10171201_35_dialog_content = "Chega, agora não é hora de ficar sentimental. O que o Soroz vê?",
  ui_story_1017_10171201_36_dialog_content = "A cerca de 300 metros à frente, há um enorme aglomerado de Darkflow se movendo no atoleiro.",
  ui_story_1017_10171201_37_dialog_content = "É o comando central ou...?",
  ui_story_1017_10171201_38_dialog_content = "O Fluxo Escuro está se agregando e dispersando nas proximidades. A avaliação preliminar sugere que é um Eclipsita de alto nível.",
  ui_story_1017_10171201_39_dialog_content = "Está vindo em nossa direção?",
  ui_story_1017_10171201_40_dialog_content = "A aparição da entidade é errática, tornando difícil prever sua trajetória de movimento ou antecipar seu tempo de chegada.",
  ui_story_1017_10171201_41_dialog_content = "Você vê alguém liderando?",
  ui_story_1017_10171201_42_dialog_content = "Continue procurando...",
  ui_story_1017_10171201_43_dialog_content = "Obrigado, Soroz.",
  ui_story_1017_10171201_44_dialog_content = "Ei, onde ela foi?",
  ui_story_1017_10171201_45_dialog_content = "Uau, de onde vieram todos esses Eclipsitas?",
  ui_story_1017_10171201_46_dialog_content = "O que está acontecendo, PlayerName!",
  ui_story_1017_10171201_47_dialog_content = "(Espera, meu corpo parece...)",
  ui_story_1017_10171201_48_dialog_content = "Há um Eclipsita de alto nível se movendo no pântano!",
  ui_story_1017_10171201_49_dialog_content = "Viu isso? Mesmo que não ataquemos, o Eclipsita ainda tentará nos fazer!",
  ui_story_1017_10171201_50_dialog_content = "Então é melhor lutarmos a boa luta!",
  ui_story_1017_10171201_51_dialog_content = "Provavelmente há inúmeros Eclipsitas escondidos no pântano. Estou pronto para matar!",
  ui_story_1017_10171201_52_dialog_content = "Espere, Wrath, é muito perigoso pisar na lama!",
  ui_story_1017_10171201_53_dialog_content = "Não, eu preciso continuar! Mesmo que o lamaçal me afogue, eu tenho que matá-lo!",
  ui_story_1017_10171201_54_dialog_content = "Todas as empresas, atraiam os Eclipsitas comuns para ambos os lados!",
  ui_story_1017_10171201_55_dialog_content = "Engine VII, derrube os Eclipsitas à frente e abra caminho para mim!",
  ui_story_1017_10171201_56_dialog_content = "Sim!",
  ui_story_1017_10171201_57_dialog_content = "Quem você pensa que é, se escondendo atrás dos seus capangas...",
  ui_story_1017_10171201_58_dialog_content = "Grande Marechal! Eclipsitas avistados na ala oeste!",
  ui_story_1017_10171201_59_dialog_content = "Grande Marechal, eles se moveram para o lado leste!",
  ui_story_1017_10171201_60_dialog_content = "Então, seguir a tentativa de flanquear deve ser...",
  ui_story_1017_10171201_61_dialog_content = "Cuidado onde pisa, Wrath!",
  ui_story_1017_10171201_62_dialog_content = "Eu sabia que sua estratégia de movimento é—",
  ui_story_1017_10171201_63_dialog_content = "Completamente tolo!",
  ui_story_1017_10171201_64_dialog_content = "Grande Marechal! Você está bem?",
  ui_story_1017_10171201_65_dialog_content = "Isso é... longe de ser suficiente... para fazer algo comigo...",
  ui_story_1017_10171201_66_dialog_content = "Você está horrível! Volte para mim!",
  ui_story_1017_10171201_67_dialog_content = "Não, eu acertei...",
  ui_story_1017_10171201_68_dialog_content = "É rápido. Só o vi sair do lodo por um segundo antes de mergulhar de volta.",
  ui_story_1017_10171201_69_dialog_content = "Você machucou isso?",
  ui_story_1017_10171201_70_dialog_content = "Acho que não. Mas aquilo... estava tentando...",
  ui_story_1017_10171201_71_dialog_content = "Você está tremendo todo, Wrath!",
  ui_story_1017_10171201_72_dialog_content = "É essa mesmo... Aquela coisa... estava tentando...",
  ui_story_1017_10171201_73_dialog_content = "Grande Marechal! Engine VII está vindo te buscar! Pule a bordo e saia do atoleiro!",
  ui_story_1017_10171201_74_dialog_content = "Ninguém chega perto!",
  ui_story_1017_10171201_75_dialog_content = "Este pântano é o território daquele Eclipsita.",
  ui_story_1017_10171201_76_dialog_content = "Se você embarcar... você vai...",
  ui_story_1017_10171201_77_dialog_content = "Mas você está trabalhando nisso agora!",
  ui_story_1017_10171201_78_dialog_content = "(Mantenha seus sentidos, mantenha seus sentidos!)",
  ui_story_1017_10171201_79_dialog_content = "Saia de lá, Wrath!",
  ui_story_1017_10171201_80_dialog_content = "Está vindo em nossa direção... Não posso recuar.",
  ui_story_1017_10171201_81_dialog_content = "Se você cair, Crepúsculo estará acabado!",
  ui_story_1017_10171201_82_dialog_content = "Eu não vou cair... Eu agora...",
  ui_story_1017_10171201_83_dialog_content = "Sinto... poder fluindo através de mim...",
  ui_story_1017_10171201_84_dialog_content = "Devo matá-lo!",
  ui_story_1017_10171201_85_dialog_content = "Então vou encontrá-lo para você!",
  ui_story_1017_10171201_86_dialog_content = "Volte!",
  ui_story_1017_10171201_87_dialog_content = "O Darkflow é comparativamente mais fraco às suas dez horas. Contorne por esse caminho e vá para trás dos Eclipsitas!",
  ui_story_1017_10171201_88_dialog_content = "Eclipsite vindo em sua direção, recue!",
  ui_story_1017_10171201_89_dialog_content = "O Darkflow está diminuindo 5 passos atrás de você, por favor continue...",
  ui_story_1017_10171201_90_dialog_content = "(O quê? De repente... estou congelado no lugar...)",
  ui_story_1017_10171201_91_dialog_content = "PlayerName!",
  ui_story_1017_10171201_92_dialog_content = "(Vamos, se mexa, os Eclipsites estão chegando!)",
  ui_story_1017_10171201_93_dialog_content = "PlayerName?!",
  ui_story_1017_10171201_94_dialog_content = "(Não, eu não consigo me mexer mesmo...)",
  ui_story_1017_10171201_95_dialog_content = "(Vou ter que guiar Wrath telepaticamente...)",
  ui_story_1017_10171301_1_dialog_content = "Outro! Lança relâmpago, perfure!",
  ui_story_1017_10171301_2_dialog_content = "(Quanto mais tempo isso durar, menos controle eu tenho sobre meu corpo...)",
  ui_story_1017_10171301_3_dialog_content = "(E o sentimento passou de confusão para sede de sangue...)",
  ui_story_1017_10171301_4_dialog_content = "(Será que vou acabar como esses soldados...?)",
  ui_story_1017_10171301_5_dialog_content = "(Não!)",
  ui_story_1017_10171301_6_dialog_content = "(Não posso cair! Não aqui, não agora!)",
  ui_story_1017_10171301_7_dialog_content = "Ei, cuidado!",
  ui_story_1017_10171301_8_dialog_content = "Ai!",
  ui_story_1017_10171301_9_dialog_content = "De volta conosco agora?",
  ui_story_1017_10171301_10_dialog_content = "Após o arremesso, sim.",
  ui_story_1017_10171301_11_dialog_content = "O que você disse?",
  ui_story_1017_10171301_12_dialog_content = "(Espere, PlayerName é quem está falando...)",
  ui_story_1017_10171301_13_dialog_content = "(Por que acho que estou falando com um Eclipsita?)",
  ui_story_1017_10171301_14_dialog_content = "Tudo bem?",
  ui_story_1017_10171301_15_dialog_content = "Estou bem...",
  ui_story_1017_10171301_16_dialog_content = "(É PlayerName! É PlayerName na minha frente!)",
  ui_story_1017_10171301_17_dialog_content = "Wrath!",
  ui_story_1017_10171301_18_dialog_content = "Tô bem.",
  ui_story_1017_10171301_19_dialog_content = "Não te falei para ficar longe do atoleiro?",
  ui_story_1017_10171301_20_dialog_content = "Mas você entrou de cabeça nisso, assim como os soldados fizeram antes...",
  ui_story_1017_10171301_21_dialog_content = "...",
  ui_story_1017_10171301_22_dialog_content = "Fúria?",
  ui_story_1017_10171301_23_dialog_content = "(Algo está errado com Wrath...)",
  ui_story_1017_10171301_24_dialog_content = "Há Eclipsitas ali. Tenho que ir matá-los!",
  ui_story_1017_10171301_25_dialog_content = "O que? Eu não vejo nenhum Eclipsitas!",
  ui_story_1017_10171301_26_dialog_content = "Lança relâmpago, perfure!",
  ui_story_1017_10171301_27_dialog_content = "Wrath, isso não é Eclipsita. É apenas lama comum.",
  ui_story_1017_10171301_28_dialog_content = "Lança relâmpago, perfure!",
  ui_story_1017_10171301_29_dialog_content = "O que tá acontecendo aqui?",
  ui_story_1017_10171301_30_dialog_content = "Acho que você ainda tá fora de si.",
  ui_story_1017_10171301_31_dialog_content = "Então os Eclipsitas estão se escondendo na lama, esperando para nos emboscar?",
  ui_story_1017_10171301_32_dialog_content = "(Ela consegue detectar e reagir aos Eclipsitas, mas não parece ter total controle de suas ações...)",
  ui_story_1017_10171301_33_dialog_content = "Comece a procurar enquanto eu ainda posso ir!",
  ui_story_1017_10171301_34_dialog_content = "Claro! Uma hora!",
  ui_story_1017_10171301_35_dialog_content = "Sim!",
  ui_story_1017_10171301_36_dialog_content = "Uma hora, Wrath!",
  ui_story_1017_10171301_37_dialog_content = "...",
  ui_story_1017_10171301_38_dialog_content = "Você está indo pelo caminho errado!",
  ui_story_1017_10171301_39_dialog_content = "PlayerName, Wrath avançou contra o enxame de Eclipsitas.",
  ui_story_1017_10171301_40_dialog_content = "Os Eclipsitas vão sobrecarregá-la!",
  ui_story_1017_10171301_41_dialog_content = "Aumento de Força!",
  ui_story_1017_10171301_42_dialog_content = "(É o pântano...)",
  ui_story_1017_10171301_43_dialog_content = "(Está se movendo rápido e em todas as direções.)",
  ui_story_1017_10171301_44_dialog_content = "(Ei, esse lugar foi perturbado...)",
  ui_story_1017_10171301_45_dialog_content = "(Um brilho!)",
  ui_story_1017_10171301_46_dialog_content = "(A lama está se aglomerando e formando uma imagem...)",
  ui_story_1017_10171301_47_dialog_content = "(Isto é... Ulysses, Belisaria, e na tela está...)",
  ui_story_1017_10171301_48_dialog_content = "(Ele desapareceu antes que eu pudesse entender o resto... Wrath não está aqui, no entanto.)",
  ui_story_1017_10171301_49_dialog_content = "(Mais um brilho!)",
  ui_story_1017_10171301_50_dialog_content = "(É Reinhardt!)",
  ui_story_1017_10171301_51_dialog_content = "(Um jovem Reinhardt... e espectadores, faixas...)",
  ui_story_1017_10171301_52_dialog_content = "(\"Prova Final do Grande Marechal da Illumina\"... Perdeu para Reinhardt, pelo que vejo...)",
  ui_story_1017_10171301_53_dialog_content = "(Chuva...?)",
  ui_story_1017_10171301_54_dialog_content = "(Chuva no que parecia ser uma cidade subterrânea?)",
  ui_story_1017_10171301_55_dialog_content = "(Deve ter sido um dia inesquecível para Wrath...)",
  ui_story_1017_10171301_56_dialog_content = "(Este é... um laboratório da Illumina.)",
  ui_story_1017_10171301_57_dialog_content = "(Eu vejo Ulysses e outros ao redor de uma cama de laboratório.)",
  ui_story_1017_10171301_58_dialog_content = "(Na cama está...)",
  ui_story_1017_10171301_59_dialog_content = "(Reinhardt?)",
  ui_story_1017_10171301_60_dialog_content = "(Como pode ser Reinhardt?)",
  ui_story_1017_10171301_61_dialog_content = "(E não Wrath?!)",
  ui_story_1017_10171301_62_dialog_content = "(Espere um minuto, isso não é Ulysses perto da cama... É Wrath!)",
  ui_story_1017_10171301_63_dialog_content = "(Você consegue me ouvir, Wrath?!)",
  ui_story_1017_10171301_64_dialog_content = "(...)",
  ui_story_1017_10171301_65_dialog_content = "(Acorde, você está em Crepúsculo lutando contra Eclipsitas agora!)",
  ui_story_1017_10171301_66_dialog_content = "(Eclipsitas... Qualquer um que subir na cama se transformará em Eclipsitas...)",
  ui_story_1017_10171301_67_dialog_content = "(O Crepúsculo está prestes a ser arrasado e você está ferido por todo lado! Acorde!)",
  ui_story_1017_10171301_68_dialog_content = "(Como é que o Reinhardt nunca se machuca?)",
  ui_story_1017_10171301_69_dialog_content = "(Porque ela é uma Eclipsita.)",
  ui_story_1017_10171301_70_dialog_content = "(Todos se machucam! Mas você é o Grande Marechal e os soldados precisam de você!)",
  ui_story_1017_10171301_71_dialog_content = "(Grande Marechal...)",
  ui_story_1017_10171301_72_dialog_content = "(Está funcionando? Deixe-me tentar outra coisa.)",
  ui_story_1017_10171301_73_dialog_content = "(O Julgamento Final do Grande Marechal!)",
  ui_story_1017_10171301_74_dialog_content = "(Você ainda não derrotou Reinhardt ainda. Volte para a batalha!)",
  ui_story_1017_10171301_75_dialog_content = "(Reinhardt... Droga Reinhardt!)",
  ui_story_1017_10171301_76_dialog_content = "(Sim, Reinhardt ainda está na arena. Vá provar que você é melhor!)",
  ui_story_1017_10171301_77_dialog_content = "(Wrath...!)",
  ui_story_1017_10171301_78_dialog_content = "PlayerName, você finalmente voltou à consciência.",
  ui_story_1017_10171301_79_dialog_content = "Estou bem. Onde está Wrath? Como ela está?",
  ui_story_1017_10171301_80_dialog_content = "A avaliação inicial indica que a consciência dela parece ter se recuperado totalmente, e ela conseguiu reprimir os Eclipsitas mais uma vez.",
  ui_story_1017_10171301_81_dialog_content = "Maravilha!",
  ui_story_1017_10171301_82_dialog_content = "O que você acabou de fazer, iniciando um Impulso Forçado quando a condição do Wrath era incerta, foi extremamente arriscado.",
  ui_story_1017_10171301_83_dialog_content = "Eu sei, mas era uma emergência e eu não tinha tempo a perder...",
  ui_story_1017_10171301_84_dialog_content = "Talvez eu me sentisse seguro porque você está por perto.",
  ui_story_1017_10171301_85_dialog_content = "Olhe para a sua direita - são os Cavaleiros Ironthorn que mantiveram você seguro.",
  ui_story_1017_10171301_86_dialog_content = "Leo e companhia estão aqui!",
  ui_story_1017_10171301_87_dialog_content = "Eles entraram na luta quando você estava se conectando ao Wrath.",
  ui_story_1017_10171301_88_dialog_content = "Obrigado, Soroz!",
  ui_story_1017_10171301_89_dialog_content = "Soroz continuará navegando para você.",
  ui_story_1017_10171301_90_dialog_content = "Lança relâmpago, perfure!",
  ui_story_1017_10171301_91_dialog_content = "Sobre o que você estava falando agora mesmo?",
  ui_story_1017_10171301_92_option_content = "Eu estava tentando ajudar",
  ui_story_1017_10171301_93_dialog_content = "Bom te ver de volta conosco.",
  ui_story_1017_10171301_94_dialog_content = "Cuide da sua própria vida.",
  ui_story_1017_10171301_95_option_content = "Eu não quis dizer isso",
  ui_story_1017_10171301_96_dialog_content = "Eu só estava tentando te tirar dessa situação...",
  ui_story_1017_10171301_97_dialog_content = "Pare de olhar coisas que não deveria ver, entendeu?",
  ui_story_1017_10171301_98_dialog_content = "Bem, é bom ver você me repreendendo assim de novo!",
  ui_story_1017_10171301_99_dialog_content = "Ainda temos que proteger o Crepúsculo.",
  ui_story_1017_10171301_100_dialog_content = "Mesmo que eu me transforme em um Eclipsita, serei aquele que garante que a cidade permaneça intacta!",
  ui_story_1017_10171301_101_dialog_content = "Atenção, Legião da Guarda!",
  ui_story_1017_10171301_102_dialog_content = "Todos nós já experimentamos desconforto em diferentes graus na batalha, mas confie em mim, é temporário.",
  ui_story_1017_10171301_103_dialog_content = "Tente se concentrar, isso reduzirá muitos dos impactos negativos do Fluxo Escuro.",
  ui_story_1017_10171301_104_dialog_content = "Garanto a vocês, encontrarei cada soldado desaparecido, mas até lá, preciso de cada um de vocês!",
  ui_story_1017_10171301_105_dialog_content = "Qualquer pessoa que esteja ferida ou não totalmente consciente, retorne a Illumina imediatamente!",
  ui_story_1017_10171301_106_dialog_content = "Aqueles que ainda podem lutar ou <color=#FFB400>não têm medo da influência do Fluxo Escuro</color>, sigam-me no ataque ao comando central!",
  ui_story_1017_10171301_107_dialog_content = "Sim!!!",
  ui_story_1017_10171401_1_dialog_content = "Você está saciado?",
  ui_story_1017_10171401_2_dialog_content = "Nem mesmo perto—",
  ui_story_1017_10171401_3_dialog_content = "Todas as coisas boas devem ser guardadas até o fim, é claro. O \"tapete\" foi muito bem colocado.",
  ui_story_1017_10171401_4_dialog_content = "Devore todos eles—",
  ui_story_1017_10171401_5_dialog_content = "Pare de se mexer. Estou fazendo o ajuste final.",
  ui_story_1017_10171401_6_dialog_content = "Este lugar é lamentável comparado a um laboratório de verdade. O progresso está muito devagar.",
  ui_story_1017_10171401_7_dialog_content = "(Em Eclipsiano) Há um Aurorian se recusando a cair...",
  ui_story_1017_10171401_8_dialog_content = "Não se preocupe, o novo Grande Marechal é o último curso de Mudbundle.",
  ui_story_1017_10171401_9_dialog_content = "Me dê tudo—",
  ui_story_1017_10171401_10_dialog_content = "(Eclipsiano) Não ela, outra pessoa. Este Aurorian foi pouco afetado.",
  ui_story_1017_10171401_11_dialog_content = "Algo novo? Preciso conferir isso imediatamente.",
  ui_story_1017_10171401_12_dialog_content = "...",
  ui_story_1017_10171401_13_dialog_content = "Suspiro, eu esperava muito mais do que um tolo que não consegue lutar para sair de um saco de papel molhado.",
  ui_story_1017_10171401_14_dialog_content = "Axelia é uma máquina de guerra. Axelia tem lutado.",
  ui_story_1017_10171401_15_dialog_content = "Vejo que você não é mudo. Já que consegue abrir a boca, experimente isso.",
  ui_story_1017_10171401_16_dialog_content = "...",
  ui_story_1017_10171401_17_dialog_content = "Legal. Qual é o seu objetivo, se não for matar Eclipsitas?",
  ui_story_1017_10171401_18_dialog_content = "\"Axelia deve derrotar o Grande Marechal Reinhardt a todo custo.\"",
  ui_story_1017_10171401_19_dialog_content = "Heh, não acredito que o Ulysses estragou tudo tão feio. Ele provavelmente não se importava se você sobrevivesse.",
  ui_story_1017_10171401_20_dialog_content = "\"Axelia deve viver como uma pessoa.\"",
  ui_story_1017_10171401_21_dialog_content = "Chega de conversa. Hora do Mudbundle aproveitar sua refeição.",
  ui_story_1017_10171401_22_dialog_content = "Bom trabalho prendendo todo o exército aqui. Você pode continuar daqui por conta própria.",
  ui_story_1017_10171401_23_dialog_content = "(Eclipsiano) Sim.",
  ui_story_1017_10171401_24_dialog_content = "...",
  ui_story_1017_10171401_25_dialog_content = "Você vai morrer por emboscar meus soldados!",
  ui_story_1017_10171401_26_dialog_content = "Achei você! Achei que você tivesse caído no atoleiro.",
  ui_story_1017_10171401_27_dialog_content = "Grande Marechal, localizamos os membros da equipe do Tenente Axelia um por um.",
  ui_story_1017_10171401_28_dialog_content = "Bom. Verifique se alguém está ferido e fique atento a outro ataque do comando central.",
  ui_story_1017_10171401_29_dialog_content = "Há mais soldados por aqui, Soroz?",
  ui_story_1017_10171401_30_dialog_content = "Procurando...",
  ui_story_1017_10171401_31_dialog_content = "...",
  ui_story_1017_10171401_32_dialog_content = "Por que você apenas bloqueou e não matou os Eclipsitas que encontrou, Axelia?",
  ui_story_1017_10171401_33_dialog_content = "\"Axelia deve derrotar o Grande Marechal Reinhardt a todo custo.\"",
  ui_story_1017_10171401_34_dialog_content = "Foi isso que o Ulysses disse a você?",
  ui_story_1017_10171401_35_dialog_content = "\"Axelia deve derrotar o Grande Marechal Reinhardt a todo custo.\"",
  ui_story_1017_10171401_36_dialog_content = "Você já alcançou esse objetivo. Você a venceu no exercício conjunto.",
  ui_story_1017_10171401_37_dialog_content = "...",
  ui_story_1017_10171401_38_dialog_content = "Ela não parece seriamente corrompida, mas ainda está um pouco fora de si.",
  ui_story_1017_10171401_39_dialog_content = "O que a Reinhardt te disse antes de se render, Axelia?",
  ui_story_1017_10171401_40_dialog_content = "Grande Marechal Reinhardt queria que \"Axelia vivesse como uma pessoa.\"",
  ui_story_1017_10171401_41_dialog_content = "Ah, uau...",
  ui_story_1017_10171401_42_dialog_content = "Mesmo indo para a prisão, ela não esqueceu de deixar conselhos maravilhosos. Mais alguma coisa?",
  ui_story_1017_10171401_43_dialog_content = "Axelia deve completar dois objetivos.",
  ui_story_1017_10171401_44_dialog_content = "\"Axelia deve derrotar o Grande Marechal Reinhardt a todo custo.\"",
  ui_story_1017_10171401_45_dialog_content = "\"Axelia deve viver como uma pessoa.\"",
  ui_story_1017_10171401_46_dialog_content = "...",
  ui_story_1017_10171401_47_dialog_content = "Você concluiu sua primeira missão, Axelia. O segundo objetivo agora é sua única missão.",
  ui_story_1017_10171401_48_dialog_content = "O único objetivo é \"Axelia deve viver como uma pessoa.\"",
  ui_story_1017_10171401_49_dialog_content = "Isso mesmo. Só podemos viver derrotando os Eclipsitas. Você é um guerreiro da Illumina e tem o direito de viver.",
  ui_story_1017_10171401_50_dialog_content = "Axelia deve derrotar Eclipsitas, Axelia quer viver.",
  ui_story_1017_10171401_51_dialog_content = "Axelia está mexendo o corpo...?",
  ui_story_1017_10171401_52_dialog_content = "Ela está fora de perigo, pelo menos por enquanto. Talvez precise de mais tempo para se recuperar completamente.",
  ui_story_1017_10171401_53_dialog_content = "Grande Marechal, a equipe do Tenente Axelia foi duramente atingida pelo Darkflow e eles estão mal aguentando na batalha.",
  ui_story_1017_10171401_54_dialog_content = "Acho que a fortaleza deles provavelmente não está longe daqui...",
  ui_story_1017_10171401_55_dialog_content = "Valeu pela ajuda sua e do Soroz, PlayerName.",
  ui_story_1017_10171401_56_dialog_content = "Só mais um favor, transporte os soldados que não podem mais lutar de volta para casa por mim.",
  ui_story_1017_10171401_57_dialog_content = "Agora mesmo?",
  ui_story_1017_10171401_58_dialog_content = "Sem mencionar que os Eclipsitas escondidos no pântano podem aparecer a qualquer momento!",
  ui_story_1017_10171401_59_dialog_content = "E estou sentindo que o comando central está se aproximando!",
  ui_story_1017_10171401_60_dialog_content = "Você sabe por quê?",
  ui_story_1017_10171401_61_dialog_content = "Por quê?",
  ui_story_1017_10171401_62_dialog_content = "Porque onde quer que eu vá, ele vai.",
  ui_story_1017_10171401_63_dialog_content = "Hã?",
  ui_story_1017_10171401_64_dialog_content = "Provavelmente não conseguimos encontrar o esquadrão de Axelia antes porque ele montou uma base por aqui e nos isolou com o pântano.",
  ui_story_1017_10171401_65_dialog_content = "Enviar Eclipsitas para assediar as tropas de todas as direções era apenas uma tática de atraso, preparando o terreno para o ataque final.",
  ui_story_1017_10171401_66_dialog_content = "Não me envolvi até agora... Acho que a surra que eu dei estava ficando demais.",
  ui_story_1017_10171401_67_dialog_content = "Mas por que o principal inimigo faria isso?",
  ui_story_1017_10171401_68_dialog_content = "Mirando em meus soldados e depois em mim, enquanto se esconde atrás do pântano. Ela deve odiar Illumina com paixão.",
  ui_story_1017_10171401_69_dialog_content = "Você sabe quem está por trás disso?",
  ui_story_1017_10171401_70_dialog_content = "Claro. Derrote o coração do pântano e ela não terá onde se esconder.",
  ui_story_1017_10171401_71_dialog_content = "Logo à frente, a 500 metros, um enorme aglomerado de Fluxo Escuro está avançando rapidamente em direção à sua posição.",
  ui_story_1017_10171401_72_dialog_content = "Wrath, Soroz sentiu—",
  ui_story_1017_10171401_73_dialog_content = "Cuidado onde pisa!",
  ui_story_1017_10171401_74_dialog_content = "Leo! O que você está fazendo aqui?",
  ui_story_1017_10171401_75_dialog_content = "Aquele Eclipsita espiava por todos os lugares, mas continuava se movendo em uma direção.",
  ui_story_1017_10171401_76_dialog_content = "Então, você está aqui para apontar dedos?",
  ui_story_1017_10171401_77_dialog_content = "Não, as pessoas em Crepúsculo defenderão todos que lutaram ao lado delas.",
  ui_story_1017_10171401_78_dialog_content = "Você tem verificado os soldados e isso faz de você um líder confiável.",
  ui_story_1017_10171401_79_dialog_content = "Esta batalha se arrastou por tempo demais. Vamos terminá-la.",
  ui_story_1017_10171401_80_dialog_content = "Não precisa dizer duas vezes. Mas não se esqueça da nossa partida depois que tudo isso acabar.",
  ui_story_1017_10171401_81_dialog_content = "De nada.",
  ui_story_1017_10171401_82_dialog_content = "(Ainda consigo ir e estou totalmente consciente...)",
  ui_story_1017_10171401_83_dialog_content = "(Espero que esta seja a última vez que eu tenha que dar a ordem para atacar.)",
  ui_story_1017_10171401_84_dialog_content = "100 metros, PlayerName.",
  ui_story_1017_10171401_85_dialog_content = "O inimigo deve entrar no seu alcance de detecção em 5 segundos.",
  ui_story_1017_10171401_86_dialog_content = "Não consigo ver nem de perto. Preciso mudar para usar a habilidade psíquica...",
  ui_story_1017_10171401_87_dialog_content = "Rooarrrrr—",
  ui_story_1017_10171401_88_dialog_content = "Que diacho é isso...",
  ui_story_1017_10171401_89_dialog_content = "Wrath, tem uma boca sangrenta!",
  ui_story_1017_10171401_90_dialog_content = "Grande o suficiente para nos engolir inteiros...",
  ui_story_1017_10171401_91_dialog_content = "Nos proteja, Engine VII!",
  ui_story_1017_10171401_92_dialog_content = "A rajada! Será que foi criada pelo atacante...",
  ui_story_1017_10171401_93_dialog_content = "Olha-Olha! Algo está surgindo do lamaçal...",
  ui_story_1017_10171401_94_dialog_content = "Rooooarrrrr!",
  ui_story_1017_10171401_95_dialog_content = "Cuidado, esse Darkflow está ainda mais severo do que no ataque anterior!",
  ui_story_1017_10171401_96_dialog_content = "Grande Marechal! O que devemos—",
  ui_story_1017_10171401_97_dialog_content = "Os soldados à frente foram arrastados para o atoleiro pelo inimigo!",
  ui_story_1017_10171401_98_dialog_content = "...",
  ui_story_1017_10171401_99_dialog_content = "(Não, ainda consigo fazer isso...)",
  ui_story_1017_10171401_100_dialog_content = "Wrath, o lamaçal está se espalhando! Saia agora!",
  ui_story_1017_10171401_101_dialog_content = "Atenção, Legião de Guardas—",
  ui_story_1017_10171401_102_dialog_content = "...",
  ui_story_1017_10171401_103_dialog_content = "(Mesmo dar ordens é um esforço...)",
  ui_story_1017_10171401_104_dialog_content = "Todos os outros... saiam do atoleiro...",
  ui_story_1017_10171401_105_dialog_content = "Certifique-se de ficar bem longe de mim...",
  ui_story_1017_10171401_106_dialog_content = "Meus soldados, sigam-me no pântano e cubram a retirada do exército Illumina!",
  ui_story_1017_10171401_107_dialog_content = "Aguente firme, Grande Marechal Wrath!",
  ui_story_1017_10171401_108_dialog_content = "Eu disse para ficar longe de mim!",
  ui_story_1017_10171401_109_dialog_content = "...",
  ui_story_1017_10171401_110_dialog_content = "Mas você não deve se esforçar demais, Wrath!",
  ui_story_1017_10171401_111_dialog_content = "Cavaleiro... Proteja meus soldados... Eu imploro a você...",
  ui_story_1017_10171401_112_dialog_content = "Seja Eclipsite ou qualquer coisa, eu não vou ceder...",
  ui_story_1017_10171401_113_dialog_content = "Entendo...",
  ui_story_1017_10171401_114_dialog_content = "Suba no cavalo, PlayerName!",
  ui_story_1017_10171401_115_dialog_content = "(Se Wrath ficar preso na lama novamente...)",
  ui_story_1017_10171401_116_dialog_content = "Wrath, não se esqueça de que você ainda não terminou a luta entre você e Reinhardt!",
  ui_story_1017_10171401_117_dialog_content = "(!!!)",
  ui_story_1017_10171401_118_dialog_content = "(Foco... Concentre-se...)",
  ui_story_1017_10171401_119_dialog_content = "(Isto é...)",
  ui_story_1017_10171401_120_dialog_content = "(A minha batalha, a batalha do Grande Marechal Wrath...)",
  ui_story_1017_10171402_1_dialog_content = "<color=#e8d9bb>Na cidade do Crepúsculo, a terra se transformou em uma bagunça lamacenta...</color>",
  ui_story_1017_10171402_2_dialog_content = "Capitã! Nossas linhas de defesa caíram e o pântano inundou Crepúsculo, fazendo os moradores entrarem em pânico!",
  ui_story_1017_10171402_3_dialog_content = "Até o Grande Marechal de Illumina foi engolido pela lama...",
  ui_story_1017_10171402_4_dialog_content = "Leve os moradores ao hospital. Vamos continuar procurando.",
  ui_story_1017_10171402_X1_dialog_content = "Rápido! Corra! A lama está inundando a cidade!",
  ui_story_1017_10171402_X2_dialog_content = "O que está acontecendo?! Meu filho... Onde está meu filho?",
  ui_story_1017_10171402_X3_dialog_content = "Joselyne ainda está no campo de batalha...",
  ui_story_1017_10171402_X4_dialog_content = "Nossas linhas de defesa caíram e o pântano inundou Crepúsculo, fazendo os moradores entrarem em pânico!",
  ui_story_1017_10171402_X5_dialog_content = "O Capitão ainda não voltou para Crepúsculo... Vá e informe-os agora!",
  ui_story_1017_10171402_5_dialog_content = "Grande Marechal—",
  ui_story_1017_10171402_6_dialog_content = "Wrath! Ira...",
  ui_story_1017_10171402_7_dialog_content = "Ainda firme aí, PlayerName?",
  ui_story_1017_10171402_8_dialog_content = "Estou bem, apenas muito exausto para usar habilidades psíquicas.",
  ui_story_1017_10171402_9_dialog_content = "Procuramos em todos os lugares do bairro também...",
  ui_story_1017_10171402_10_dialog_content = "Não conseguia sentir a localização dela nem antes de o Eclipsita cair.",
  ui_story_1017_10171402_11_dialog_content = "A última vez que Soroz a viu, ela estava perto da boca daquela coisa, coberta de lama.",
  ui_story_1017_10171402_12_dialog_content = "É tudo culpa minha. Eu não fiquei perto dela como deveria...",
  ui_story_1017_10171402_13_dialog_content = "Tive que observá-la atacando o inimigo com olhos vidrados e visivelmente esgotada...",
  ui_story_1017_10171402_14_dialog_content = "Mesmo assim, ela escolheu atrair o Eclipsita para longe...",
  ui_story_1017_10171402_15_dialog_content = "Não é sua culpa. Tivemos que trabalhar juntos e foi assim que os vencemos.",
  ui_story_1017_10171402_16_dialog_content = "Mas para nos proteger, a Marechal Wrath realmente ordenou que Engine VII nos impedisse de ajudar...",
  ui_story_1017_10171402_17_dialog_content = "Uma decisão tão perigosa... Ela e seus soldados colocaram tudo em jogo.",
  ui_story_1017_10171402_18_dialog_content = "...",
  ui_story_1017_10171402_19_dialog_content = "Axelia sobreviveu, mas não consegue encontrar o Grande Marechal Wrath.",
  ui_story_1017_10171402_20_dialog_content = "Fico feliz em ver que você conseguiu, Axelia.",
  ui_story_1017_10171402_21_dialog_content = "Grande Marechal Wrath é um guerreiro de Illumina, e \"os guerreiros de Illumina têm o direito de viver.\"",
  ui_story_1017_10171402_22_dialog_content = "...",
  ui_story_1017_10171402_23_dialog_content = "Vamos acelerar e fazer mais uma volta fora dos limites.",
  ui_story_1017_10171402_24_dialog_content = "Se nossa nova oponente atacar agora, será mais difícil encontrá-la!",
  ui_story_1017_10171402_25_dialog_content = "Claro!",
  ui_story_1017_10171402_26_dialog_content = "PlayerName, nenhum vestígio de Wrath foi encontrado dentro dos limites do Crepúsculo.",
  ui_story_1017_10171402_27_dialog_content = "Com base na duração da busca e em nossas estimativas, a taxa de mortalidade de Wrath: 99%.",
  ui_story_1017_10171402_28_dialog_content = "Não pode ser...",
  ui_story_1017_10171402_29_dialog_content = "Isso não pode ser!",
  ui_story_1017_10171402_30_dialog_content = "<size=50>Wrath!!!</size>",
  ui_story_1017_10171501_1_dialog_content = "(Esse é o Crepúsculo depois de escurecer?)",
  ui_story_1017_10171501_2_dialog_content = "(Estou completamente sozinho...)",
  ui_story_1017_10171501_3_dialog_content = "(Hmm, estou separado de novo. Reinhardt ainda é tão bom em luta...)",
  ui_story_1017_10171501_4_dialog_content = "(Eu me sinto... fraco... é uma luta até mesmo para me mexer...)",
  ui_story_1017_10171501_5_dialog_content = "(A Cidade Baixa... tão perturbadoramente silenciosa...)",
  ui_story_1017_10171501_6_dialog_content = "(Droga, essa coisa nas minhas costas...)",
  ui_story_1017_10171501_7_dialog_content = "(Após perder para Reinhardt, eles colocaram restrições dentro do meu corpo...)",
  ui_story_1017_10171501_8_dialog_content = "(Esse é o preço final que eu tenho que pagar por perder o confronto?)",
  ui_story_1017_10171501_9_dialog_content = "(A batalha obviamente não acabou...)",
  ui_story_1017_10171501_10_dialog_content = "(Aquilo não pode me machucar!)",
  ui_story_1017_10171501_11_dialog_content = "(Não pode me machucar!)",
  ui_story_1017_10171501_12_dialog_content = "(Eu proponho uma revanche...)",
  ui_story_1017_10171501_13_dialog_content = "(A multidão está gritando meu nome em uníssono...)",
  ui_story_1017_10171501_14_dialog_content = "(Devolva minha Lança Relâmpago... meu uniforme... para mim...)",
  ui_story_1017_10171501_15_dialog_content = "(Quero ser um Grande Marechal para a Illumina...)",
  ui_story_1017_10171501_16_dialog_content = "(Ninguém... pode me parar...)",
  ui_story_1017_10171501_17_dialog_content = "Há alguns dias, na reunião confidencial dos superiores da Illumina...",
  ui_story_1017_10171501_18_dialog_content = "Ela está aqui, Comandante.",
  ui_story_1017_10171501_19_dialog_content = "Sente-se.",
  ui_story_1017_10171501_20_dialog_content = "Seja o que for, fale na lata para que eu possa voltar ao meu trabalho.",
  ui_story_1017_10171501_21_dialog_content = "Sente.",
  ui_story_1017_10171501_22_dialog_content = "...",
  ui_story_1017_10171501_23_dialog_content = "Como você se sentiria se fosse convidado para ser o Grande Marechal de Illumina?",
  ui_story_1017_10171501_24_dialog_content = "Eu? Mas por quê?",
  ui_story_1017_10171501_25_dialog_content = "Porque você quer e porque a Federação tem a necessidade.",
  ui_story_1017_10171501_26_dialog_content = "Eu não entendo. O que Reinhardt fez de errado?",
  ui_story_1017_10171501_27_dialog_content = "Não ficou claro no julgamento? Você estava lá.",
  ui_story_1017_10171501_28_dialog_content = "Mas isso não era a verdade, então o que você realmente está tramando?",
  ui_story_1017_10171501_29_dialog_content = "O que você vê nem sempre é real. Aprenda a ser mais pragmático.",
  ui_story_1017_10171501_30_dialog_content = "Decida se você quer ser o Grande Marechal ou deixar alguém mais.",
  ui_story_1017_10171501_31_dialog_content = "Esses três sabem?",
  ui_story_1017_10171501_32_dialog_content = "Isso depende de você. Espero que você pense seriamente nisso.",
  ui_story_1017_10171501_33_dialog_content = "...",
  ui_story_1017_10171501_34_dialog_content = "Não tem algo a acrescentar, Ulysses?",
  ui_story_1017_10171501_35_dialog_content = "Você é fantástico em todos os aspectos, exceto na fisicalidade.",
  ui_story_1017_10171501_36_dialog_content = "Quando você for o Grande Marechal, vou eliminar essa deficiência para você.",
  ui_story_1017_10171501_37_dialog_content = "...",
  ui_story_1017_10171501_38_dialog_content = "O que você planeja fazer?",
  ui_story_1017_10171501_39_dialog_content = "Não se preocupe, apenas o mesmo pequeno experimento pelo qual Reinhardt passou.",
  ui_story_1017_10171501_40_dialog_content = "Aprimoramentos físicos para se tornar o guerreiro mais poderoso da Illumina.",
  ui_story_1017_10171501_41_dialog_content = "Reinhardt teve bio-modificações?",
  ui_story_1017_10171501_42_dialog_content = "Você está surpreso?",
  ui_story_1017_10171501_43_dialog_content = "(Reinhardt?!)",
  ui_story_1017_10171501_44_dialog_content = "(Poderoso! Invencível! Ápice insuperável?!)",
  ui_story_1017_10171501_45_dialog_content = "(É tudo falso!)",
  ui_story_1017_10171501_46_dialog_content = "Ela ainda era jovem quando ingressou no Projeto Sol Artificial.",
  ui_story_1017_10171501_47_dialog_content = "Mas é normal que ela não revele isso mesmo sabendo a verdade, já que todos gostariam de ser naturalmente incríveis.",
  ui_story_1017_10171501_48_dialog_content = "...",
  ui_story_1017_10171501_49_dialog_content = "Você precisa de uma oportunidade para provar se nasceu para ser o Grande Marechal.",
  ui_story_1017_10171501_50_dialog_content = "E agora é essa oportunidade.",
  ui_story_1017_10171501_51_dialog_content = "Qual oportunidade?",
  ui_story_1017_10171501_52_dialog_content = "Uma grande batalha certamente ocorrerá em torno de Crepúsculo mais cedo ou mais tarde. Tenho confiança de que podemos vencer com você no comando.",
  ui_story_1017_10171501_53_dialog_content = "Vou ganhar, mas vou fazer do meu jeito.",
  ui_story_1017_10171501_54_dialog_content = "Você não precisa responder isso agora.",
  ui_story_1017_10171501_55_dialog_content = "Outra coisa... Você se lembra de algo que disse há muito tempo atrás?",
  ui_story_1017_10171501_56_dialog_content = "Você estava parado à margem após perder o confronto.",
  ui_story_1017_10171501_57_dialog_content = "Eu disse que você não deveria perder para ela, mas você respondeu—",
  ui_story_1017_10171501_58_dialog_content = "Pagarei qualquer preço para superar meus limites físicos!",
  ui_story_1017_10171501_59_dialog_content = "Essa é a minha resposta para você.",
  ui_story_1017_10171501_60_dialog_content = "...",
  ui_story_1017_10171501_61_dialog_content = "<color=#e8d9bb>Wrath relata os detalhes da reunião confidencial para Barton, Hiiro e Sharona.</color>",
  ui_story_1017_10171501_62_dialog_content = "...",
  ui_story_1017_10171501_63_dialog_content = "Esses canalhas do Comitê se rebaixariam a qualquer nível!",
  ui_story_1017_10171501_64_dialog_content = "Acredito que ainda há uma chance, desde que não seja um dos caras do Ulysses.",
  ui_story_1017_10171501_65_dialog_content = "O que você acha, Barton?",
  ui_story_1017_10171501_66_dialog_content = "Não tenho nada a acrescentar, exceto que não vou deixar a questão morrer.",
  ui_story_1017_10171501_67_dialog_content = "Quanto a quem a substituirá no futuro, não me importo de uma forma ou de outra.",
  ui_story_1017_10171501_68_dialog_content = "Não que eu fosse ouvir ou seguir alguém além de Reinhardt, de qualquer forma.",
  ui_story_1017_10171501_69_dialog_content = "Mas e se eles tivessem te invocado em vez de mim?",
  ui_story_1017_10171501_70_dialog_content = "Eu não deixaria Ulysses mexer com esse corpo. Eu o mataria.",
  ui_story_1017_10171501_71_dialog_content = "Se essa fosse a verdade sobre o Grande Marechal, não caberia a você decidir.",
  ui_story_1017_10171501_72_dialog_content = "A Zona Escura está ficando cada vez mais agitada. Acho que os superiores vão reagir em breve.",
  ui_story_1017_10171501_73_dialog_content = "Sem um Grande Marechal para liderar, combater as invasões dos Eclipsitas será um desafio.",
  ui_story_1017_10171501_74_dialog_content = "Você está pronto para isso, Wrath?",
  ui_story_1017_10171501_75_dialog_content = "Reinhardt não tinha medo quando era a grande marechal, então não tenho nada a temer.",
  ui_story_1017_10171501_76_dialog_content = "O que acontece se você se transformar em um monstro?",
  ui_story_1017_10171501_77_dialog_content = "Então eu tenho apenas um pedido, e é trazer Reinhardt para me matar pessoalmente.",
  ui_story_1017_10171501_78_dialog_content = "Isso é realmente... absurdo.",
  ui_story_1017_10171501_79_dialog_content = "Não diga isso. Você verá o Grande Marechal, desde que retorne vivo.",
  ui_story_1017_10171501_80_dialog_content = "Você pode ir encontrá-la você mesmo.",
  ui_story_1017_10171501_81_dialog_content = "Espere aí, eu não estava brincando sobre Reinhardt.",
  ui_story_1017_10171501_82_dialog_content = "De todos nós aqui, só você pode fazer isso acontecer.",
  ui_story_1017_10171501_83_dialog_content = "Quer dizer que...",
  ui_story_1017_10171501_84_dialog_content = "Isso mesmo, assim que o Eclipse fizer seu movimento, Sharona e Barton retornarão à zona de guerra e ficarão em espera.",
  ui_story_1017_10171501_85_dialog_content = "Até que a linha esteja em apuros, vou salvar seu reforço até o último momento.",
  ui_story_1017_10171501_86_dialog_content = "Em outras palavras, quanto mais intensa a luta, melhores são nossas chances.",
  ui_story_1017_10171501_87_dialog_content = "As consequências disso são prisão ou morte. Tem certeza, Wrath?",
  ui_story_1017_10171501_88_dialog_content = "Tenho certeza. Não acredito que haja outras possibilidades.",
  ui_story_1017_10171501_89_dialog_content = "Que tal entrar para o Programa Phospherus?",
  ui_story_1017_10171501_90_dialog_content = "Sinceramente, ainda não.",
  ui_story_1017_10171501_91_dialog_content = "Mas confie em mim, eu tomo decisões melhores em situações urgentes.",
  ui_story_1017_10171501_92_dialog_content = "Sério?",
  ui_story_1017_10171501_93_dialog_content = "De qualquer forma, fique tranquilo que você não desonrará a Illumina nesta batalha sob o meu comando.",
  ui_story_1017_10171501_94_dialog_content = "<color=#e8d9bb>No dia seguinte...</color>",
  ui_story_1017_10171501_95_dialog_content = "Como está se sentindo?",
  ui_story_1017_10171501_96_dialog_content = "Nada mesmo.",
  ui_story_1017_10171501_97_dialog_content = "Muito em breve, seus pensamentos serão um borrão.",
  ui_story_1017_10171501_98_dialog_content = "Quando você acordar novamente, verá que o mundo é muito mais justo com você.",
  ui_story_1017_10171501_99_dialog_content = "Justo...",
  ui_story_1017_10171501_100_dialog_content = "Quando os fortes dominam os fracos, os fracos apenas lamentam que o mundo não seja justo.",
  ui_story_1017_10171501_101_dialog_content = "Eles acham que os Eclipsitas são valentões, quando na verdade são eles que não são fortes o suficiente.",
  ui_story_1017_10171501_102_dialog_content = "É o mesmo com você tentando derrotar Reinhardt.",
  ui_story_1017_10171501_103_dialog_content = "Após o procedimento, o campo estará nivelado entre vocês.",
  ui_story_1017_10171501_104_dialog_content = "(O campo... Mesmo...)",
  ui_story_1017_10171501_105_dialog_content = "(Eu já pensei que não pararia por nada para alcançar meus objetivos.)",
  ui_story_1017_10171501_106_dialog_content = "(Mas, enquanto as bordas afiadas se cravavam em meu corpo, era como se eu visse a mim mesmo desmontar este recipiente...)",
  ui_story_1017_10171501_107_dialog_content = "(Levando consigo minha ambição e arrogância, reduzidas a pó.)",
  ui_story_1017_10171501_108_dialog_content = "(Em cada passo do caminho, cada escolha que fiz pareceu como lutar por ar debaixo d'água...)",
  ui_story_1017_10171501_109_dialog_content = "(Mas em meio às correntes crescentes, me vejo afundando cada vez mais...)",
  ui_story_1017_10171501_110_dialog_content = "(Devo continuar lutando? É realmente esse o resultado que desejo?)",
  ui_story_1017_10171501_111_dialog_content = "(Realmente, o campo estaria nivelado.)",
  ui_story_1017_10171501_112_dialog_content = "(Mas tal justiça...)",
  ui_story_1017_10171501_113_dialog_content = "(Chega tarde demais.)",
  ui_story_1018_10180101_1_dialog_content = "<color=#e8d9bb>Nas sombras ocultas da Zona Escura...</color>",
  ui_story_1018_10180101_2_dialog_content = "Capitão... Tenho sorte de não ter sido atingido por aquele <color=#FFB400>Eclipsita verde-brilhante</color> bizarro agora mesmo!",
  ui_story_1018_10180101_3_dialog_content = "Esses enormes pilares de gelo e estranhos espinhos de gelo que encontramos - eles estão muito além do que eu imaginava para a região da Noite Eterna...",
  ui_story_1018_10180101_4_dialog_content = "Mas já que nossa missão é toda sobre rastrear o núcleo do Guardian One, por que estamos nos escondendo aqui, observando esses Eclipsitas?",
  ui_story_1018_10180101_5_dialog_content = "Shhh, não tão alto!",
  ui_story_1018_10180101_6_dialog_content = "Ah... Vendo como você estava animado(a) até agora, pensei que já tivéssemos encontrado o <color=#FFB400>covil dos Eclipsitas</color>...",
  ui_story_1018_10180101_7_dialog_content = "Mas é <color=#FFB400>todo plano aqui</color>, com Eclipsitas se reunindo em aglomerados a intervalos...",
  ui_story_1018_10180101_8_dialog_content = "Eu simplesmente não entendo o que vale a pena ficar olhando neles.",
  ui_story_1018_10180101_9_dialog_content = "Bem, isso prova que você tem uma mente limitada como os Eclipsitas.",
  ui_story_1018_10180101_10_dialog_content = "Mas não conte a ninguém que você está no meu esquadrão quando voltarmos!",
  ui_story_1018_10180101_11_dialog_content = "Huh? Por quê? O que eu disse de errado dessa vez...",
  ui_story_1018_10180101_12_dialog_content = "O segredo para rastrear é passar de reativo para proativo e pensar como o inimigo.",
  ui_story_1018_10180101_13_dialog_content = "O Eclipsita que pegou o núcleo usou todos os truques possíveis para nos manter naquele lugar estranho, porque não queria que viéssemos aqui.",
  ui_story_1018_10180101_14_dialog_content = "Afinal, os ladrões nunca querem que alguém descubra onde se escondem.",
  ui_story_1018_10180101_15_dialog_content = "Este lugar parece sem graça, mas é protegido por tantos Eclipsitas, então deve ser muito importante para o Eclipse.",
  ui_story_1018_10180101_16_dialog_content = "Então... exatamente o que os Eclipsitas estão protegendo?",
  ui_story_1018_10180101_17_dialog_content = "Se eu estiver correto, seja lá o que for, é tão crucial quanto o núcleo do Guardian One.",
  ui_story_1018_10180101_18_dialog_content = "Confira isso...",
  ui_story_1018_10180101_19_dialog_content = "Capitão! Os Eclipsitas acabaram de ficar muito agitados!",
  ui_story_1018_10180101_20_dialog_content = "Veja, aquela coisa reagiu a isso exatamente como o núcleo do Guardian One.",
  ui_story_1018_10180101_21_dialog_content = "É um projeto importante, entendi.",
  ui_story_1018_10180101_22_dialog_content = "Você está dizendo que, além do núcleo do Guardião Um, podemos encontrar um bônus extra?",
  ui_story_1018_10180101_23_dialog_content = "Bem, você não acha que deveríamos dar uma ou duas surpresas para Belisaria?",
  ui_story_1018_10180101_24_dialog_content = "Capitão, você realmente é um mestre do reconhecimento!",
  ui_story_1018_10180101_25_dialog_content = "Mas aqui está o problema... Estou preocupado que os Eclipsitas possam nos exterminar antes mesmo de chegarmos lá.",
  ui_story_1018_10180101_26_dialog_content = "Pense positivo! Nosso veículo está praticamente integrado à Zona Cega.",
  ui_story_1018_10180101_27_dialog_content = "O exterior é tratado especialmente para se integrar perfeitamente ao ambiente.",
  ui_story_1018_10180101_28_dialog_content = "Todos vocês também foram selecionados porque seu Lumina é fraco, tornando mais difícil para os Eclipsitas detectarem vocês.",
  ui_story_1018_10180101_29_dialog_content = "Hmm, será essa a razão pela qual você não conseguiu melhorar sua Luminática?",
  ui_story_1018_10180101_30_dialog_content = "Suspiro... Meu comandante anterior me disse uma vez — estou destinado a ser apenas um motorista nesta vida.",
  ui_story_1018_10180101_31_dialog_content = "Só estou brincando com você! Quando voltar, não se esqueça de dizer a ele que agora você é um peão que me seguiu até a Zona Cega!",
  ui_story_1018_10180101_32_dialog_content = "De qualquer forma, acredite em alguém experiente, na verdade é mais seguro quanto mais fundo você estiver na Zona Escura.",
  ui_story_1018_10180101_33_dialog_content = "Capitão... Você realmente não é um ex-membro do Eclipse que desertou e se juntou à Illumina?",
  ui_story_1018_10180101_34_dialog_content = "A pergunta que você deveria fazer é se eu costumava estar com a Illumina, mas mudei de lado para o Eclipse agora.",
  ui_story_1018_10180101_35_dialog_content = "...",
  ui_story_1018_10180101_36_dialog_content = "Vocês se aproximem e me cubram. Façam isso em silêncio.",
  ui_story_1018_10180101_37_dialog_content = "Vou ver como exatamente essa coisa é semelhante ao núcleo do Guardian One.",
  ui_story_1018_10180101_38_dialog_content = "Entendido, Capitão. Devemos compartilhar nossas coordenadas atuais com a equipe de rastreamento atrás de nós?",
  ui_story_1018_10180101_39_dialog_content = "Logo após saírem do apuro... Parece que as coisas não estão indo bem para eles.",
  ui_story_1018_10180101_40_dialog_content = "<color=#e8d9bb>Lumópolis, Corte Real</color>",
  ui_story_1018_10180101_41_dialog_content = "Senhor da Cidade, se o objetivo do reforço era apenas proteger a Fortaleza Lumo, por que eles foram para o Crepúsculo?",
  ui_story_1018_10180101_42_dialog_content = "Você sabe o que compõe esse novo exército Illumina?",
  ui_story_1018_10180101_43_dialog_content = "Por que pergunta?",
  ui_story_1018_10180101_44_dialog_content = "Dê uma olhada.",
  ui_story_1018_10180101_45_dialog_content = "Isso... é uma carta urgente da Igreja Noite Branca no Crepúsculo e nem sequer está assinada.",
  ui_story_1018_10180101_46_dialog_content = "\"Quagmire esmagou a base de Twilight. Eclipsitas correndo desenfreados. O esforço conjunto de resistência da Illumina e dos Cavaleiros Lumo é praticamente inútil...\"",
  ui_story_1018_10180101_47_dialog_content = "\"Os soldados Illumina sofreram baixas graves. O Grande Marechal ainda está desaparecido. Apenas os Cavaleiros estão mantendo suas posições.\"",
  ui_story_1018_10180101_48_dialog_content = "\"O hospital está lotado. Os suprimentos estão acabando. Todos estão à beira do abismo...\"",
  ui_story_1018_10180101_49_dialog_content = "O Grande Marechal está desaparecido? Como isso pode acontecer?",
  ui_story_1018_10180101_50_dialog_content = "A Federação Illumina não é invencível, embora eu ainda não tenha visto um resultado como a batalha do Crepúsculo.",
  ui_story_1018_10180101_51_dialog_content = "Mesmo assim, as outras legiões Illumina permanecem firmes em Gannon e nunca se aventuraram para fora.",
  ui_story_1018_10180101_52_dialog_content = "Eles não têm intenção de ajudar Crepúsculo, mas estão na verdade testando a nova tecnologia militar por meio do recém-nomeado Grande Marechal.",
  ui_story_1018_10180101_53_dialog_content = "Se o curso se mantiver, o novo exército será todo vítima deste teste.",
  ui_story_1018_10180101_54_dialog_content = "Você sabia disso o tempo todo, Senhor da Cidade?",
  ui_story_1018_10180101_55_dialog_content = "É apenas a história se repetindo. O motivo se encaixa perfeitamente com a Illumina.",
  ui_story_1018_10180101_56_dialog_content = "E quanto aos soldados que ainda estão lutando na linha de frente?",
  ui_story_1018_10180101_57_dialog_content = "Deixando Illumina de lado, acredito que um reforço deve garantir a segurança do povo em Crepúsculo.",
  ui_story_1018_10180101_58_dialog_content = "Ainda estou refletindo.",
  ui_story_1018_10180101_59_dialog_content = "Mas se você não decidir logo, não serão apenas as cidades da superfície de Lumópolis e Crepúsculo que serão afetadas!",
  ui_story_1018_10180101_60_dialog_content = "<size=45>Estou refletindo.</size>",
  ui_story_1018_10180101_61_dialog_content = "...",
  ui_story_1018_10180101_62_dialog_content = "Senhor da Cidade, um mensageiro do Senhor Sombrio Istvan está solicitando uma audiência.",
  ui_story_1018_10180101_63_dialog_content = "Mande-o entrar.",
  ui_story_1018_10180101_64_dialog_content = "Vejo que esta ilha flutuante está tão deserta como sempre! Saudações, Senhor da Cidade e Senhora Carleen.",
  ui_story_1018_10180101_65_dialog_content = "Qual negócio você tem, emissário da Cidade da Agitação e Agitação?",
  ui_story_1018_10180101_66_dialog_content = "Uau, eu não sabia que sou adequado para ser um emissário!",
  ui_story_1018_10180101_67_dialog_content = "Estou aqui apenas para transmitir algumas palavras de Istvan.",
  ui_story_1018_10180101_68_dialog_content = "Acredito que você também está de olho na confusão em Crepúsculo.",
  ui_story_1018_10180101_69_dialog_content = "Mas mesmo enviando reforços, você deixou as cidades próximas se virarem sozinhas. Por que isso?",
  ui_story_1018_10180101_70_dialog_content = "São essas as palavras exatas de Istvan?",
  ui_story_1018_10180101_71_dialog_content = "Certo... Um pouco enfeitado.",
  ui_story_1018_10180101_72_dialog_content = "Você provavelmente não sabe que um visitante de Crepúsculo se deu bem com Istvan por pura coincidência no caminho para te encontrar.",
  ui_story_1018_10180101_73_dialog_content = "Pelo que ele disse, a situação em Crepúsculo piorou muito.",
  ui_story_1018_10180101_74_dialog_content = "Este visitante de Crepúsculo seria Zhao?",
  ui_story_1018_10180101_75_dialog_content = "Sim, esse é o nome!",
  ui_story_1018_10180101_76_dialog_content = "Senhor da Cidade, Zhao de Crepúsculo está solicitando uma audiência.",
  ui_story_1018_10180101_77_dialog_content = "Veja, ele já está aqui.",
  ui_story_1018_10180101_78_dialog_content = "Mas todo o tráfego para Lumópolis foi interrompido.",
  ui_story_1018_10180101_79_dialog_content = "Enquanto Istvan quiser, não há nada que não possa ser feito.",
  ui_story_1018_10180101_80_dialog_content = "Este Zhao se movimentou entre as facções. Foi de Umbraton para Illumina, depois de Umbraton para Lumopolis...",
  ui_story_1018_10180101_81_dialog_content = "Se você o mandar embora, ele seguirá para Northland, Deserto Rediesel...",
  ui_story_1018_10180101_82_dialog_content = "\"Corpo fraco, mas nunca desiste antes de conseguir o que quer. Esse é o Zhao, a pessoa que quer te ver.\"",
  ui_story_1018_10180101_83_dialog_content = "Agora essas são as palavras exatas de Istvan.",
  ui_story_1018_10180101_84_dialog_content = "Ele certamente passou a batata quente que é o Crepúsculo rápido o suficiente. Por que o Istvan não veio ele mesmo?",
  ui_story_1018_10180101_85_dialog_content = "Sou apenas o mensageiro. Você precisa perguntar ao visitante sobre isso, Senhor da Cidade.",
  ui_story_1018_10180101_86_dialog_content = "Este lugar está muito claro. É hora de eu voltar para o fundo do mar. Vou me retirar, Senhor da Cidade e Senhora Carleen!",
  ui_story_1018_10180101_87_dialog_content = "...",
  ui_story_1018_10180101_88_dialog_content = "Você não pretende convidar Zhao para entrar?",
  ui_story_1018_10180101_89_dialog_content = "O problema com Crepúsculo envolve Lumopolis e Illumina. Ninguém mais tem o direito de negociar.",
  ui_story_1018_10180101_90_dialog_content = "E já que Illumina mostrou suas cartas, cabe a Lumopolis defender Crepúsculo.",
  ui_story_1018_10180101_91_dialog_content = "Você virá comigo.",
  ui_story_1018_10180101_92_dialog_content = "Você vai ao Crepúsculo pessoalmente?",
  ui_story_1018_10180101_93_dialog_content = "Não sou eu quem deve expor os podres da Illumina. A atrocidade que cometeram contra os Aurorians cabe ao Templo julgar.",
  ui_story_1018_10180201_1_dialog_content = "<color=#e8d9bb>Cidade do Crepúsculo</color>",
  ui_story_1018_10180201_2_dialog_content = "(Já estamos procurando há tanto tempo...)",
  ui_story_1018_10180201_3_dialog_content = "(Onde você está, Wrath?)",
  ui_story_1018_10180201_4_dialog_content = "Capitão, eliminamos os Eclipsitas que rastejaram no lodo depois de derrubarmos os inimigos no comando central.",
  ui_story_1018_10180201_5_dialog_content = "Enquanto o pântano permanecer, Crepúsculo está temporariamente fora de perigo.",
  ui_story_1018_10180201_6_dialog_content = "Dada a situação atual, você consideraria encerrar esta fase da batalha, Capitão?",
  ui_story_1018_10180201_7_dialog_content = "Embora tenhamos feito algum progresso na batalha, ainda vai demorar um pouco até que tudo termine.",
  ui_story_1018_10180201_8_dialog_content = "O Darkflow no Crepúsculo diminuiu bastante, não é, PlayerName?",
  ui_story_1018_10180201_9_dialog_content = "Sim. Soroz não está detectando nenhum inimigo atraído pelo Darkflow.",
  ui_story_1018_10180201_10_dialog_content = "Bem, a lama cobrindo Crepúsculo continua sendo um problema.",
  ui_story_1018_10180201_11_dialog_content = "Verdade. O hospital só pode estabilizar os soldados afetados por enquanto. Ainda não foi encontrada uma cura.",
  ui_story_1018_10180201_12_dialog_content = "Vai ser uma grande dor de cabeça...",
  ui_story_1018_10180201_13_dialog_content = "Capitão, todos os moradores de Crepúsculo foram realocados para o hospital temporário.",
  ui_story_1018_10180201_14_dialog_content = "Aqueles que residem mais próximos ao coração do país contribuíram com suas casas para acomodar os refugiados.",
  ui_story_1018_10180201_15_dialog_content = "A maioria das pessoas não sofreu graças ao seu esforço altruísta.",
  ui_story_1018_10180201_16_dialog_content = "Mas não é viável que todos se amontoem em Crepúsculo. Vou considerar realocar os refugiados da linha Illumina para cidades vizinhas.",
  ui_story_1018_10180201_17_dialog_content = "Capitão, os arredores da zona de guerra ainda estão um caos, e estou preocupado que uma transferência agora pode não ser a opção mais segura.",
  ui_story_1018_10180201_18_dialog_content = "Grande Marechal Wrath e suas corajosas forças, que lideram a carga, também estão presas lá dentro, e não temos ideia de onde eles estão...",
  ui_story_1018_10180201_19_dialog_content = "Vamos fazer o trabalho de preparação primeiro e resolver isso assim que a batalha acalmar.",
  ui_story_1018_10180201_20_dialog_content = "Com licença, soldado, quantos de vocês estão desaparecidos, aproximadamente?",
  ui_story_1018_10180201_21_dialog_content = "Duas equipes se juntaram à investida do Grande Marechal, totalizando mais de cem soldados...",
  ui_story_1018_10180201_22_dialog_content = "E quase todos eles... são novos recrutas.",
  ui_story_1018_10180201_23_dialog_content = "Isso é quase metade dos Cavaleiros Espinho de Ferro.",
  ui_story_1018_10180201_24_dialog_content = "Capitão, avistamos alguns soldados no muro oeste. Mas com a situação incerta, nossos camaradas estão mantendo distância.",
  ui_story_1018_10180201_25_dialog_content = "Confira agora!",
  ui_story_1018_10180201_26_dialog_content = "Eles... Sim, eram soldados que avançaram para a batalha ao lado do Grande Marechal.",
  ui_story_1018_10180201_27_dialog_content = "Uma rápida olhada ao redor e há dezenas deles...",
  ui_story_1018_10180201_28_dialog_content = "Mova cuidadosamente os soldados mortos para a base e fique atento aos inimigos escondidos na lama.",
  ui_story_1018_10180201_29_dialog_content = "Sim!",
  ui_story_1018_10180201_30_dialog_content = "...",
  ui_story_1018_10180201_31_dialog_content = "Eles morreram assim... Nem tive tempo de conhecê-los...",
  ui_story_1018_10180201_32_dialog_content = "Isso é um soldado para você, PlayerName.",
  ui_story_1018_10180201_33_dialog_content = "Lutando em guerras regularmente, às vezes nem tendo a chance de lamentar os amigos perdidos antes de partir para a próxima batalha.",
  ui_story_1018_10180201_34_dialog_content = "...",
  ui_story_1018_10180201_35_dialog_content = "Ainda temos um respirando, Leo!",
  ui_story_1018_10180201_36_dialog_content = "Qual é a situação dele?",
  ui_story_1018_10180201_37_dialog_content = "Devemos conseguir estabilizá-lo com tratamento...",
  ui_story_1018_10180201_38_dialog_content = "...",
  ui_story_1018_10180201_39_dialog_content = "Ele está com medo ou tentando dizer algo?",
  ui_story_1018_10180201_40_dialog_content = "Ele parece estar mastigando algo.",
  ui_story_1018_10180201_41_dialog_content = "Rugido!!!",
  ui_story_1018_10180201_42_dialog_content = "Lâmina Relâmpago!",
  ui_story_1018_10180201_43_dialog_content = "Ele se transformou em um Eclipsite do nada!",
  ui_story_1018_10180201_44_dialog_content = "Vejo que meu pior medo se tornou realidade...",
  ui_story_1018_10180201_45_dialog_content = "Rugido!!!",
  ui_story_1018_10180201_46_dialog_content = "E ali também?",
  ui_story_1018_10180201_47_dialog_content = "Capitão! Esses soldados caídos... Não, os Eclipsitas estão nos atacando!",
  ui_story_1018_10180201_48_dialog_content = "A situação é pior do que eu imaginava. Temos que parar a busca e salvamento!",
  ui_story_1018_10180201_49_dialog_content = "Prepare-se para lutar!",
  ui_story_1018_10180201_50_dialog_content = "Espere, Leo...",
  ui_story_1018_10180202_1_dialog_content = "Esses soldados estão realmente mortos?",
  ui_story_1018_10180202_2_dialog_content = "...",
  ui_story_1018_10180202_3_dialog_content = "Não sinta pena dos Eclipsitas.",
  ui_story_1018_10180202_4_dialog_content = "Mesmo que já tenham sido soldados, eles só causariam maiores perdas se fossem autorizados a ficar.",
  ui_story_1018_10180202_5_dialog_content = "Soldados Illumina, deixem isso conosco. Vocês saiam de Crepúsculo o mais rápido possível!",
  ui_story_1018_10180202_6_dialog_content = "Capitão Leo, os soldados Illumina... ainda não podemos sair de Crepúsculo.",
  ui_story_1018_10180202_7_dialog_content = "Eu disse, todos os soldados Illumina, saiam de Crepúsculo.",
  ui_story_1018_10180202_8_dialog_content = "...",
  ui_story_1018_10180202_9_dialog_content = "Nesse caso, Capitão Leo, devo chamar sua atenção para um determinado assunto.",
  ui_story_1018_10180202_10_dialog_content = "Por favor, ouça-me e depois decida se quer que a gente vá embora.",
  ui_story_1018_10180202_11_dialog_content = "Diga.",
  ui_story_1018_10180202_12_dialog_content = "Antes de chegar a Twilight, nossa Legião de Guardas Illumina era composta pelos soldados mais habilidosos, e é por isso que também somos conhecidos como Reserva de Elite.",
  ui_story_1018_10180202_13_dialog_content = "Os irmãos que estão atrás de mim são todos membros da Reserva de Elite, os seguidores mais dedicados do Grande Marechal Wrath.",
  ui_story_1018_10180202_14_dialog_content = "Nunca estivemos em batalhas tão intensas antes, mas o fato de ainda estarmos de pé é prova da nossa força.",
  ui_story_1018_10180202_15_dialog_content = "Eu entendo o que você quer dizer, mas esses novatos que se transformaram em Eclipsitas receberam treinamento especial de Illumina.",
  ui_story_1018_10180202_16_dialog_content = "Depois de chegarem ao Crepúsculo, eles, incluindo seu Grande Marechal, foram contaminados pelo atoleiro.",
  ui_story_1018_10180202_17_dialog_content = "É um fato... mas, eu prometo a você, antes de entrar na luta, nenhum de nós poderia ter previsto algo assim acontecendo.",
  ui_story_1018_10180202_18_dialog_content = "Com as pesadas baixas de nossos camaradas e sem saber onde está o Grande Marechal, estamos todos bastante devastados.",
  ui_story_1018_10180202_19_dialog_content = "Como tal, representando os soldados da Reserva de Elite, estou aqui para expressar o nosso apelo: vamos ficar aqui e defender Twilight.",
  ui_story_1018_10180202_20_dialog_content = "Até encontrarmos o Grande Marechal, esta é a ordem que todos os nossos soldados Illumina devem seguir.",
  ui_story_1018_10180202_21_dialog_content = "Nós nos voluntariamos para nos juntar à força que protege Twilight e, na ausência do Grande Marechal, assumirei o comando temporariamente.",
  ui_story_1018_10180202_22_dialog_content = "Como líder, como soldado, eu vejo.",
  ui_story_1018_10180202_23_dialog_content = "Mesmo que os inimigos já tenham sido seus compatriotas?",
  ui_story_1018_10180202_24_dialog_content = "Se eles se transformaram em Eclipsitas causando estragos em Crepúsculo... não vou mostrar piedade...",
  ui_story_1018_10180202_25_dialog_content = "Rugido!!!",
  ui_story_1018_10180202_26_dialog_content = "Tem mais aqui, capitão!",
  ui_story_1018_10180202_27_dialog_content = "Eu...",
  ui_story_1018_10180202_28_dialog_content = "Lâmina Relâmpago!",
  ui_story_1018_10180202_29_dialog_content = "Sua ação não sustentou seu juramento, soldado. Afaste-se. Eles estão além da redenção.",
  ui_story_1018_10180202_30_dialog_content = "Não tire conclusões precipitadas, Leo. Aqueles que não atacaram não são exatamente um caso perdido.",
  ui_story_1018_10180202_31_dialog_content = "Sim, eles hesitaram...",
  ui_story_1018_10180202_32_dialog_content = "Mas vocês todos viram, não é? Se conter apenas deu a eles a chance de machucar vocês.",
  ui_story_1018_10180202_33_dialog_content = "Mas eles ainda são Aurorianos!",
  ui_story_1018_10180202_34_dialog_content = "Rugido!!!",
  ui_story_1018_10180202_35_dialog_content = "Olhe novamente, eles não são diferentes de um Eclipsita! Qualquer um que tente prejudicar um soldado do Crepúsculo é um inimigo!",
  ui_story_1018_10180202_36_dialog_content = "Soldados da Illumina, se desejam defender o Crepúsculo, mostrem sua força e sejam implacáveis com o inimigo!",
  ui_story_1018_10180202_37_dialog_content = "Caso contrário, deixe Crepúsculo, seu serviço não é mais necessário.",
  ui_story_1018_10180202_38_dialog_content = "Eu...",
  ui_story_1018_10180202_39_dialog_content = "Não cabe a você dar ordens aos meus soldados...",
  ui_story_1018_10180202_40_dialog_content = "Afetados pelo Darkflow... Mas eles... não merecem morrer...",
  ui_story_1018_10180202_41_dialog_content = "Tenho certeza...",
  ui_story_1018_10180202_42_dialog_content = "Leo, é Wrath!",
  ui_story_1018_10180202_43_dialog_content = "...",
  ui_story_1018_10180202_44_dialog_content = "Porque... eu já estive lá...",
  ui_story_1018_10180202_45_dialog_content = "Grande marechal!",
  ui_story_1018_10180301_1_dialog_content = "Wrath! Estivemos procurando por você por toda parte!",
  ui_story_1018_10180301_2_dialog_content = "Assim que você apareceu, conseguiu controlar os soldados enfurecidos...",
  ui_story_1018_10180301_3_dialog_content = "Eles não conseguiam se controlar... sob a influência do atoleiro...",
  ui_story_1018_10180301_4_dialog_content = "Eles não queriam... machucar ninguém...",
  ui_story_1018_10180301_5_dialog_content = "...",
  ui_story_1018_10180301_6_dialog_content = "Noite Branca nas alturas... Que bom que você está seguro, Grande Marechal!",
  ui_story_1018_10180301_7_option_content = "Você parece muito cansado agora",
  ui_story_1018_10180301_8_dialog_content = "Você está machucado ou sentindo desconforto em algum lugar?",
  ui_story_1018_10180301_9_dialog_content = "Além da dor causada pelo impacto do pântano...",
  ui_story_1018_10180301_10_dialog_content = "Não me lembro de nada.",
  ui_story_1018_10180301_11_option_content = "O que houve?",
  ui_story_1018_10180301_12_dialog_content = "Por que não conseguimos te encontrar de jeito nenhum?",
  ui_story_1018_10180301_13_dialog_content = "Eu... também não tenho certeza...",
  ui_story_1018_10180301_14_dialog_content = "Tudo que me lembro é de tudo ficando escuro depois de sair da lama...",
  ui_story_1018_10180301_15_dialog_content = "Não se preocupe, só fiquei todo sujo de lama.",
  ui_story_1018_10180301_16_dialog_content = "Quantos soldados mais como esse ainda estão por aí...?",
  ui_story_1018_10180301_17_dialog_content = "Leo tem procurado por eles...",
  ui_story_1018_10180301_18_dialog_content = "Mas você voltou, felizmente!",
  ui_story_1018_10180301_19_dialog_content = "Sim...",
  ui_story_1018_10180301_20_dialog_content = "Eu disse que salvaria Crepúsculo antes de me transformar em um Eclipsita.",
  ui_story_1018_10180301_21_dialog_content = "Agora tenho que adicionar meus soldados a essa lista...",
  ui_story_1018_10180301_22_dialog_content = "Não vou tolerar nenhuma tentativa de descartá-los como Eclipsitas e matá-los...",
  ui_story_1018_10180301_23_dialog_content = "Fico feliz em ver que você está bem, Grande Marechal.",
  ui_story_1018_10180301_24_dialog_content = "Nunca foi minha intenção prejudicar os soldados Illumina. Estou apenas cuidando de Crepúsculo.",
  ui_story_1018_10180301_25_dialog_content = "Matar o inimigo quando é conveniente, abandonar as tropas diante da adversidade... Desculpe se eu me recuso a aceitar a estratégia dos Cavaleiros.",
  ui_story_1018_10180301_26_dialog_content = "Grande Marechal, eu...",
  ui_story_1018_10180301_27_dialog_content = "Agora que estou de volta, vou liderar meus soldados.",
  ui_story_1018_10180301_28_dialog_content = "Eu não tenho energia suficiente para mais uma rodada com você, então não ultrapasse seus limites...",
  ui_story_1018_10180301_29_dialog_content = "Como desejar, Grande Marechal.",
  ui_story_1018_10180301_30_dialog_content = "Grande Marechal Wrath, você parece enfraquecido no momento.",
  ui_story_1018_10180301_31_dialog_content = "Por favor, venha comigo ao hospital para tratamento!",
  ui_story_1018_10180301_32_dialog_content = "Estamos em um campo de batalha. Não vou sair enquanto meus soldados ainda estiverem de pé.",
  ui_story_1018_10180301_33_dialog_content = "Bem, então pelo menos me permita cuidar das suas feridas. Por favor, descanse um pouco no meu cavalo!",
  ui_story_1018_10180301_34_dialog_content = "Se você quer fazer isso pelas suas tropas, eu aconselho a se consultar.",
  ui_story_1018_10180301_35_dialog_content = "Sim, você passou bastante tempo no atoleiro, então provavelmente não deveria arriscar.",
  ui_story_1018_10180301_36_dialog_content = "Tudo bem. Obrigado desde já, Joselyne.",
  ui_story_1018_10180301_37_dialog_content = "Noite Branca lá no alto... É incrível que você ainda consiga ativar os Lumináticos.",
  ui_story_1018_10180301_38_dialog_content = "Você tem muitos ferimentos, mas nenhum é fatal, embora esteja bastante enfraquecido.",
  ui_story_1018_10180301_39_dialog_content = "Severamente enfraquecido? Acho que não...",
  ui_story_1018_10180301_40_dialog_content = "Pelo contrário, sinto que meu corpo está se recuperando rapidamente.",
  ui_story_1018_10180301_41_dialog_content = "Em retrospectiva, havia uma força percorrendo meu corpo quando eu estava inconsciente...",
  ui_story_1018_10180301_42_dialog_content = "Como se alguém estivesse me curando... A sensação era difícil de descrever.",
  ui_story_1018_10180301_43_dialog_content = "Curar você? Como poderia haver alguém mais?",
  ui_story_1018_10180301_44_dialog_content = "Isso é absurdo... Mas não está fora do âmbito da possibilidade, já que estou aqui agora mesmo.",
  ui_story_1018_10180301_45_dialog_content = "É uma pena que não consegui proteger meus soldados...",
  ui_story_1018_10180301_46_dialog_content = "Grande Marechal, ainda não localizamos as duas equipes que avançaram para a batalha ao seu lado.",
  ui_story_1018_10180301_47_dialog_content = "Capitão Axelia tem liderado a missão de busca.",
  ui_story_1018_10180301_48_dialog_content = "Mas... Os que você acabou de encontrar podem ser eles...",
  ui_story_1018_10180301_49_dialog_content = "Entreguei-os diretamente ao inimigo...",
  ui_story_1018_10180301_50_dialog_content = "Não, Grande Marechal! Fomos nós, desobedecendo suas ordens...",
  ui_story_1018_10180301_51_dialog_content = "Estávamos determinados a seguir ao seu lado! E esses novos recrutas, eles eram...",
  ui_story_1018_10180301_52_dialog_content = "Você lançou um ataque contra um inimigo desses sem hesitação e mudou o rumo da situação.",
  ui_story_1018_10180301_53_dialog_content = "Se conseguirmos encontrá-los em breve, talvez ainda haja esperança!",
  ui_story_1018_10180301_54_dialog_content = "...",
  ui_story_1018_10180301_55_dialog_content = "De qualquer forma, não posso mais permitir que você corra riscos comigo...",
  ui_story_1018_10180301_56_dialog_content = "<color=#e8d9bb>Todo mundo chega à borda oeste da zona de guerra...</color>",
  ui_story_1018_10180301_57_dialog_content = "Nunca pensei que o pântano chegaria tão longe... Ainda parece estar se movendo.",
  ui_story_1018_10180301_58_dialog_content = "Talvez mais inimigos estejam chegando, e quem sabe para onde o atoleiro fluente May levou os soldados desaparecidos.",
  ui_story_1018_10180301_59_dialog_content = "Nesse caso, a batalha não acabará enquanto o atoleiro ainda estiver presente.",
  ui_story_1018_10180301_60_dialog_content = "O que mais me preocupa é o inimigo atacando com meus soldados...",
  ui_story_1018_10180301_61_dialog_content = "Sou responsável pelo impacto negativo nesta batalha devido ao meu erro de julgamento.",
  ui_story_1018_10180301_62_dialog_content = "Você não poderia saber, Grande Marechal. Vamos continuar a busca pelo pântano.",
  ui_story_1018_10180301_63_dialog_content = "Claro...",
  ui_story_1018_10180301_64_dialog_content = "Grande Marechal Wrath! Olhe para o flanco oeste da linha de defesa—",
  ui_story_1018_10180301_65_dialog_content = "Três Engine VII mechas estão lá! Juntamente com nossos soldados!",
  ui_story_1018_10180301_66_dialog_content = "É o mecha cobrindo meu ataque... Não esperava encontrá-lo aqui.",
  ui_story_1018_10180301_67_dialog_content = "Tudo está em ruínas... A base atrás deles foi completamente destruída. Felizmente, eles mantiveram o terreno.",
  ui_story_1018_10180301_68_dialog_content = "Isso deixa apenas 1 Engine VII desaparecido, mas deve estar por perto. Vamos verificar...",
  ui_story_1018_10180301_69_dialog_content = "<color=#e8d9bb>Mastiga! Mastiga!</color>",
  ui_story_1018_10180301_70_dialog_content = "Err...Capitão?!",
  ui_story_1018_10180301_71_dialog_content = "...",
  ui_story_1018_10180301_72_dialog_content = "O mecha está totalmente destruído...",
  ui_story_1018_10180301_73_dialog_content = "E os soldados ao redor de Engine VII... eles estão roendo a carcaça externa do robô...",
  ui_story_1018_10180301_74_dialog_content = "Rugido...",
  ui_story_1018_10180301_75_dialog_content = "Recarregando-se com estes, como um Eclipsita?",
  ui_story_1018_10180301_76_dialog_content = "Nossa...",
  ui_story_1018_10180301_77_dialog_content = "Rarrr!",
  ui_story_1018_10180301_78_dialog_content = "...",
  ui_story_1018_10180301_79_dialog_content = "Fique no cavalo, Grande Marechal. Eles não parecem estar cientes de nossa aproximação. Podemos seguir daqui.",
  ui_story_1018_10180301_80_dialog_content = "Isso mesmo, eu posso eliminar essa meia dúzia de Eclipsitas sozinho.",
  ui_story_1018_10180301_81_dialog_content = "Eles não são Eclipsitas... São meus soldados...",
  ui_story_1018_10180301_82_dialog_content = "Apenas subjuguem-nos...",
  ui_story_1018_10180301_83_dialog_content = "...",
  ui_story_1018_10180301_84_dialog_content = "Como você pode ser tão inabalável como Grande Marechal e tão indeciso quando se trata de seus homens?",
  ui_story_1018_10180301_85_dialog_content = "Subjugar eles... Talvez ainda haja esperança para eles...",
  ui_story_1018_10180301_86_dialog_content = "Wrath está certo, eu posso tentar salvá-los!",
  ui_story_1018_10180302_1_dialog_content = "Ufa... Eles estão bem agora.",
  ui_story_1018_10180302_2_dialog_content = "Podemos entregá-los à equipe médica. Vejo que PlayerName sabe como curar e coordenar na batalha.",
  ui_story_1018_10180302_3_dialog_content = "Quando Wrath estava na mesma situação antes, foi assim que ela saiu disso.",
  ui_story_1018_10180302_4_dialog_content = "Eles estão apenas presos em suas próprias mentes e não conseguem se controlar.",
  ui_story_1018_10180302_5_dialog_content = "Mas sinto muito pelo soldado que devorou grande parte dessa armadura.",
  ui_story_1018_10180302_6_dialog_content = "Noite Branca lá no alto... Leo tentou dominá-lo e acredito que fez o seu melhor.",
  ui_story_1018_10180302_7_dialog_content = "Aquele soldado foi mutilado e apenas o Darkflow o estava sustentando...",
  ui_story_1018_10180302_8_dialog_content = "Acho que o Grande Marechal deveria olhar para o panorama geral e ser menos apegado a um... soldado assim.",
  ui_story_1018_10180302_9_dialog_content = "Isso eu sei, não precisa me lembrar...",
  ui_story_1018_10180302_10_dialog_content = "Você pretende enviar todos os soldados que encontramos para o hospital?",
  ui_story_1018_10180302_11_dialog_content = "Várias centenas é um número considerável.",
  ui_story_1018_10180302_12_dialog_content = "De fato, esses feridos que resgatamos não cabem nas instalações...",
  ui_story_1018_10180302_13_dialog_content = "Mas, considerando a condição especial deles, eles devem ser tratados o mais rápido possível.",
  ui_story_1018_10180302_14_dialog_content = "Um dos meus soldados já está cuidando disso. Quando ele retornar, vou mover os moradores para as cidades maiores.",
  ui_story_1018_10180302_15_dialog_content = "Com o que você vai movê-los? Carrinhos?",
  ui_story_1018_10180302_16_dialog_content = "Sim, as poucas carruagens que nos restam, e talvez alguns deles tenham que andar...",
  ui_story_1018_10180302_17_dialog_content = "Caminhar é praticamente entregá-los de bandeja aos Eclipsitas como comida.",
  ui_story_1018_10180302_18_dialog_content = "Tenho uma sugestão... Embora a decisão seja de PlayerName.",
  ui_story_1018_10180302_19_dialog_content = "Na verdade, eu também consegui um...",
  ui_story_1018_10180302_20_dialog_content = "Soroz.",
  ui_story_1018_10180302_21_dialog_content = "Não será um problema evacuar o povo de Crepúsculo o mais rápido possível, e Eraveil provavelmente é o local mais seguro no momento.",
  ui_story_1018_10180302_22_dialog_content = "Mas qual é o seu plano para os feridos que encontrarmos mais tarde?",
  ui_story_1018_10180302_23_dialog_content = "Antes que o atoleiro se disperse... Vamos encontrar uma solução. Os moradores indefesos são a maior prioridade.",
  ui_story_1018_10180302_24_dialog_content = "Leo, deixe-me tentar a Fortaleza Lumo.",
  ui_story_1018_10180302_25_dialog_content = "Muitos membros da igreja se ofereceram para ficar para trás e fornecer ajuda médica.",
  ui_story_1018_10180302_26_dialog_content = "Pedirei a ajuda da igreja para aqueles que precisam de atenção imediata. Espero que isso também facilite o futuro esforço de resgate do Grande Marechal.",
  ui_story_1018_10180302_27_dialog_content = "Fortaleza Lumo... Não estou muito otimista a respeito disso.",
  ui_story_1018_10180302_28_dialog_content = "Mas devemos garantir a segurança dos refugiados acima de tudo, e ninguém pode dizer com certeza qual é o melhor caminho, então não vou impedi-lo.",
  ui_story_1018_10180302_29_dialog_content = "Eu acho que, não importa quais sejam os problemas entre as facções, a Igreja da Noite Branca não vai rejeitar os Aurorians.",
  ui_story_1018_10180302_30_dialog_content = "No entanto, você se importa se os soldados da Illumina se abrigarem na Igreja da Noite Branca, Grande Marechal Wrath?",
  ui_story_1018_10180302_31_dialog_content = "Não conte comigo. A Illumina nunca lida com religiões.",
  ui_story_1018_10180302_32_dialog_content = "Mas, dada a situação, eu agradeceria se você cuidasse dos meus soldados.",
  ui_story_1018_10180302_33_dialog_content = "Tem certeza de que não precisa de ajuda médica?",
  ui_story_1018_10180302_34_dialog_content = "Estou apenas me sentindo cansado... Melhorei depois de conversar com vocês.",
  ui_story_1018_10180302_35_dialog_content = "May Posso pegar seu cavalo emprestado, Joselyne?",
  ui_story_1018_10180302_36_dialog_content = "Claro! Não se preocupe, Grande Marechal, vou conseguir ajuda para seus soldados.",
  ui_story_1018_10180302_37_dialog_content = "Espero que a guerra esteja acabada na próxima vez que nos encontrarmos. Vou me preparar agora.",
  ui_story_1018_10180302_38_dialog_content = "Tomar cuidado.",
  ui_story_1018_10180302_39_dialog_content = "PlayerName, encontre-se com meus soldados na saída oeste mais tarde.",
  ui_story_1018_10180302_40_dialog_content = "Quando a crise em Crepúsculo acabar, eu vou te encontrar e nós vamos acomodar os refugiados.",
  ui_story_1018_10180302_41_dialog_content = "Aham, obrigado por tudo que você fez. Tenho certeza de que nos encontraremos novamente.",
  ui_story_1018_10180302_42_dialog_content = "O quê... Eu nunca disse que vou embora.",
  ui_story_1018_10180302_43_dialog_content = "Soroz levará os moradores para um local seguro no piloto automático.",
  ui_story_1018_10180302_44_dialog_content = "Eu disse que protegeria Crepúsculo com você. Não vou sair até que esta guerra termine.",
  ui_story_1018_10180302_45_dialog_content = "Você é muito mais persistente do que eu imaginava, PlayerName.",
  ui_story_1018_10180302_46_dialog_content = "Lutamos juntos tempo suficiente para eu esperar isso de você.",
  ui_story_1018_10180302_47_dialog_content = "PlayerName, pousei na entrada oeste de Twilight. Estamos dentro do alcance de comunicação.",
  ui_story_1018_10180302_48_dialog_content = "Soroz, por favor, leve as pessoas de Crepúsculo para a segurança de nossa casa.",
  ui_story_1018_10180302_49_dialog_content = "Destino: Eraveil",
  ui_story_1018_10180302_50_dialog_content = "PlayerName, certifique-se de manter-se seguro.",
  ui_story_1018_10180302_51_dialog_content = "Obrigado, vou deixá-los sob seus cuidados.",
  ui_story_1018_10180401_1_dialog_content = "<color=#e8d9bb>Em um trem a caminho da Zona Escura...</color>",
  ui_story_1018_10180401_2_dialog_content = "Um, dois, três... Já demos quatro voltas. Alguma ordem, senhor?",
  ui_story_1018_10180401_3_dialog_content = "Vai com calma, Merry, haverá uma resposta para esse mistério com o tempo.",
  ui_story_1018_10180401_4_dialog_content = "O Sr. Charon realmente confia na direção dada por Minch?",
  ui_story_1018_10180401_5_dialog_content = "Trabalhamos juntos há muito tempo, então é óbvio... Falando nisso, você está bem aí, Minch?",
  ui_story_1018_10180401_6_dialog_content = "Estou com dor de cabeça desde o início. Provavelmente é o vento...",
  ui_story_1018_10180401_7_dialog_content = "Não tem vento no trem!",
  ui_story_1018_10180401_8_dialog_content = "Fora da janela. Estamos enfrentando ventos fortes em uma taxa altamente incomum.",
  ui_story_1018_10180401_9_dialog_content = "Apenas pelas luzes fracas, pude perceber que a cidade pela qual acabamos de passar estava em apuros. Talvez seja por isso que ele está atrasado.",
  ui_story_1018_10180401_10_dialog_content = "Então, aquela mancha de escuridão era na verdade uma cidade... Era como uma garra de obsidiana se estendendo da Zona Escura...",
  ui_story_1018_10180401_11_dialog_content = "Suspiro. Mal consigo andar em um trem que é confortável e artístico, e essa é a vista que eu tenho...",
  ui_story_1018_10180401_12_dialog_content = "Você realmente confia naqueles três, Oficial Charon? Você nos disse para descansar desde que saímos.",
  ui_story_1018_10180401_13_dialog_content = "Esta é a terceira vez que me levanto, então por que ainda não chegamos à Zona Escura?",
  ui_story_1018_10180401_14_dialog_content = "Estamos realizando a missão, Vice. Não se preocupe, o Outro Lado garantirá nossa segurança.",
  ui_story_1018_10180401_15_dialog_content = "Mas senhor, eu não me lembro da distância de Illumina para a Zona Escura ser tão longa assim...",
  ui_story_1018_10180401_16_dialog_content = "A pessoa que me deu a missão também forneceu duas pistas precisas, e este é o passo necessário para desvendar o mistério.",
  ui_story_1018_10180401_17_dialog_content = "Pistas precisas? O que são?",
  ui_story_1018_10180401_18_dialog_content = "Um incluía várias coordenadas fora das linhas da Illumina. Todos os lugares em que estivemos estavam no mapa.",
  ui_story_1018_10180401_19_dialog_content = "Então, tenho certeza de que não passamos por nenhum lugar onde não deveríamos.",
  ui_story_1018_10180401_20_dialog_content = "Mas de acordo com as marcas, não estivemos andando em círculos aqui o tempo todo?",
  ui_story_1018_10180401_21_dialog_content = "Shhh... Você não quer assustar nossos convidados.",
  ui_story_1018_10180401_22_dialog_content = "Aqueles três? Então você também sentiu que algo está errado?",
  ui_story_1018_10180401_23_dialog_content = "Chame isso de uma agenda secreta. Andar em círculos também faz parte da missão.",
  ui_story_1018_10180401_24_dialog_content = "Um passarinho está me dizendo que teremos a resposta para o mistério em breve.",
  ui_story_1018_10180401_25_dialog_content = "Mistério de novo?",
  ui_story_1018_10180401_26_dialog_content = "Então, quem é o segundo protagonista?",
  ui_story_1018_10180401_27_dialog_content = "A segunda pista é chegar a um local especialmente marcado e, em seguida, fazer uma videoconferência com a Equipe de Reconhecimento da Zona Cega.",
  ui_story_1018_10180401_28_dialog_content = "Hã? Mas não recebemos nenhum sinal de posição deles há muito tempo.",
  ui_story_1018_10180401_29_dialog_content = "O capitão desligou o comunicador? Ou há um jammer perto deles?",
  ui_story_1018_10180401_30_dialog_content = "Senhor, acredito que precisamos de uma atualização sobre a situação atual, ou não teremos esperança de concluir a missão!",
  ui_story_1018_10180401_31_dialog_content = "Estou muito preocupado com o status atual da Illumina.",
  ui_story_1018_10180401_32_dialog_content = "Controle suas dúvidas por enquanto e talvez eu possa fornecer respostas.",
  ui_story_1018_10180401_33_dialog_content = "Você está ouvindo a voz de uma mulher, Oficial Charon?",
  ui_story_1018_10180401_34_dialog_content = "Passou rápido por mim.",
  ui_story_1018_10180401_35_dialog_content = "Senhora Victoria!",
  ui_story_1018_10180401_36_dialog_content = "Você está aqui, senhora!",
  ui_story_1018_10180401_37_dialog_content = "Lembra de mim, Condutor Illumina? Na frente de estranhos, talvez eu não deva te chamar de parente... ou um parente distante.",
  ui_story_1018_10180401_38_dialog_content = "Poupe suas palavras enigmáticas, Senhora Victoria. O que você e seus três subordinados planejam fazer?",
  ui_story_1018_10180401_39_dialog_content = "Senhora Victoria...? Então esses três rapazes são da Verdadeira Ordem?",
  ui_story_1018_10180401_40_dialog_content = "Espero que eles não tenham tornado sua viagem desagradável, Srta. Vice.",
  ui_story_1018_10180401_41_dialog_content = "Bem, você deveria perguntar isso a Charon. Estamos dando voltas por sua causa?",
  ui_story_1018_10180401_42_dialog_content = "Não completamente. Mas minha presença agora legitima oficialmente este trem cheio de membros da Verdadeira Ordem.",
  ui_story_1018_10180401_43_dialog_content = "Senhorita Vice, estou supondo que você está aqui porque está intrigada com o visitante misterioso de Illumina...",
  ui_story_1018_10180401_44_dialog_content = "Assim como o que aconteceu com a cidade de Crepúsculo pela qual você passou.",
  ui_story_1018_10180401_45_dialog_content = "Como você sabe sobre o cara que se infiltrou na Illumina? E aconteceu algo em Crepúsculo?",
  ui_story_1018_10180401_46_dialog_content = "Viu, é por isso que esse trem precisa do meu esclarecimento!",
  ui_story_1018_10180401_47_dialog_content = "Quanto ao que aconteceu em Crepúsculo... Deixe-me dizer que o Celestita e o novo Grande Marechal ainda não descobriram os truques para sobreviver.",
  ui_story_1018_10180401_48_dialog_content = "PlayerName foi para Crepúsculo também?!",
  ui_story_1018_10180401_49_dialog_content = "Eu sabia sobre o Grande Marechal, mas será que eles encontraram problemas no Crepúsculo?",
  ui_story_1018_10180401_50_dialog_content = "A situação deles em Crepúsculo depende de como você os percebe. Não se preocupe com o desconhecido antes da revelação.",
  ui_story_1018_10180401_51_dialog_content = "Isso é verdade, Charon? PlayerName e o Grande Marechal não estão em perigo, estão?",
  ui_story_1018_10180401_52_dialog_content = "...",
  ui_story_1018_10180401_53_dialog_content = "Então, gostaria de ir e ver o atoleiro por si mesmo?",
  ui_story_1018_10180401_54_dialog_content = "Embora o tomo revele que o destino desta jovem senhora seja... Noite Eterna.",
  ui_story_1018_10180401_55_dialog_content = "Caindo na noite eterna após esquecer o amado, mas ainda nutrido pela lança negra para completar o sacrifício e a redenção.",
  ui_story_1018_10180401_56_dialog_content = "Parabéns, Senhorita Vice, pois você encontrará a verdade nesta viagem.",
  ui_story_1018_10180401_57_dialog_content = "Do que você está falando...?",
  ui_story_1018_10180401_58_dialog_content = "Absurdo! Essa viagem não é sobre destino, mas sim sobre soldados Illumina cumprindo uma missão.",
  ui_story_1018_10180401_59_dialog_content = "Por favor, não atrapalhe nosso caminho, Senhora Victoria, ou haverá consequências.",
  ui_story_1018_10180401_60_dialog_content = "Todo esse tempo que você esteve com meus membros, ainda não percebeu que o Warp está em ação?",
  ui_story_1018_10180401_61_dialog_content = "A Dobra... Não é você o responsável por estarmos dando voltas sem fim?",
  ui_story_1018_10180401_62_dialog_content = "Vejo que a marca ancestral em você desapareceu. É hora de algumas revelações.",
  ui_story_1018_10180401_63_dialog_content = "Devido a várias razões, o Eclipse está usando isso para impedi-lo de se aproximar.",
  ui_story_1018_10180401_64_dialog_content = "Após uma certa distância, você é levado de volta ao ponto inicial. Esse é o poder do Dobra Espacial.",
  ui_story_1018_10180401_65_dialog_content = "E \"ponto inicial\" se refere ao centro de um círculo, então você só pode se mover dentro da linha do raio.",
  ui_story_1018_10180401_66_dialog_content = "Como isso é realizado?",
  ui_story_1018_10180401_67_dialog_content = "Não se aprofunde nisso, Senhorita Vice, pois isso só vai te enlouquecer.",
  ui_story_1018_10180401_68_dialog_content = "Mas com minha orientação, vamos escapar dessa situação difícil. Agora, será que o Condutor vai recusar minha passagem, considerando esse fato?",
  ui_story_1018_10180401_69_dialog_content = "...",
  ui_story_1018_10180401_70_dialog_content = "Vou considerar o silêncio como permissão para embarcar. Pode aumentar a velocidade, Condutor.",
  ui_story_1018_10180401_71_dialog_content = "Estou confuso, senhor. Ainda estamos nos movendo em direção à Noite Eterna?",
  ui_story_1018_10180401_72_dialog_content = "O trem parará onde você desejar, Senhorita Vice.",
  ui_story_1018_10180401_73_dialog_content = "Depende de mim, né...",
  ui_story_1018_10180401_74_dialog_content = "<color=#e8d9bb>*Apito do trem*</color>",
  ui_story_1018_10180401_75_dialog_content = "Espera!",
  ui_story_1018_10180401_76_dialog_content = "O que está acontecendo com essa rajada repentina? Não é um sinal de ataque inimigo, é?",
  ui_story_1018_10180401_77_dialog_content = "Axelia deve proteger os subordinados...",
  ui_story_1018_10180401_78_dialog_content = "É estranho o vendaval não causar nem uma ondulação no pântano...",
  ui_story_1018_10180401_79_dialog_content = "Axelia, você viu algo incomum no seu esforço de resgate aqui?",
  ui_story_1018_10180401_80_dialog_content = "Talvez o inimigo central não tenha sido derrotado e esteja apenas esperando...",
  ui_story_1018_10180401_81_dialog_content = "<color=#e8d9bb>Borbulhar...</color>",
  ui_story_1018_10180401_82_dialog_content = "Capitã, o setor sob minha responsabilidade foi vasculhado. Estamos levando os feridos para o hospital.",
  ui_story_1018_10180401_83_dialog_content = "Cópia. A operação de resgate é muito mais tranquila sem a interferência dos Eclipsites.",
  ui_story_1018_10180401_84_dialog_content = "<color=#e8d9bb>Borbulhar...</color>",
  ui_story_1018_10180401_85_dialog_content = "Axelia está ouvindo um barulho estranho...",
  ui_story_1018_10180401_86_dialog_content = "Também ouço, parece algo saindo da água...",
  ui_story_1018_10180401_87_dialog_content = "Rugido...",
  ui_story_1018_10180401_88_dialog_content = "Isso...",
  ui_story_1018_10180401_89_dialog_content = "Grande Marechal! Olhe o soldado na maca!",
  ui_story_1018_10180401_90_dialog_content = "Impossível!",
  ui_story_1018_10180401_91_dialog_content = "A lama neles está fluindo como se estivesse viva.",
  ui_story_1018_10180401_92_dialog_content = "Então aquele barulho era...",
  ui_story_1018_10180401_93_dialog_content = "Ah—! Ajuda!",
  ui_story_1018_10180401_94_dialog_content = "Todos, afastem-se da maca e reúnam-se à minha volta!",
  ui_story_1018_10180401_95_dialog_content = "Claramente, não houve problemas quando eles foram resgatados...",
  ui_story_1018_10180401_96_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_1018_10180401_97_dialog_content = "Rugido...",
  ui_story_1018_10180401_98_dialog_content = "Espere, é o vento novamente! Isso pode ser uma emboscada!",
  ui_story_1018_10180401_99_dialog_content = "Fique atrás de qualquer barreira que encontrar!",
  ui_story_1018_10180401_100_dialog_content = "Estou prestes a ser deslumbrado...",
  ui_story_1018_10180401_101_dialog_content = "Segure em mim, PlayerName!",
  ui_story_1018_10180401_102_dialog_content = "Não consigo abrir os olhos... Será um novo inimigo?",
  ui_story_1018_10180401_103_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_1018_10180401_104_dialog_content = "Cuidado, lama está espirrando para cá!",
  ui_story_1018_10180401_105_dialog_content = "Atrás de você, Grande Marechal Wrath!",
  ui_story_1018_10180401_106_dialog_content = "Eu vejo... Não é apenas a lama, tem algo nela!",
  ui_story_1018_10180401_107_dialog_content = "Grahhhh!",
  ui_story_1018_10180401_108_dialog_content = "Muitos Eclipsitas no pântano!",
  ui_story_1018_10180401_109_dialog_content = "De fato, a poça está liderando os Eclipsitas, com os soldados sob a influência do Fluxo Escuro ajudando...",
  ui_story_1018_10180401_110_dialog_content = "Gah!",
  ui_story_1018_10180401_111_dialog_content = "Ah—! Ajuda!",
  ui_story_1018_10180401_112_dialog_content = "Eles enlouqueceram, Grande Marechal Wrath. Eu devo tratá-los como Eclipsitas!",
  ui_story_1018_10180401_113_dialog_content = "Não, não é isso...",
  ui_story_1018_10180401_114_dialog_content = "Temos Eclipsitas atrás de nós! A lama vai afogar todos nós se não tomarmos uma atitude!",
  ui_story_1018_10180401_115_dialog_content = "Leo...",
  ui_story_1018_10180401_116_dialog_content = "<color=#e8d9bb>*Apito do trem no vento*</color>",
  ui_story_1018_10180401_117_dialog_content = "Ah não, mais um!",
  ui_story_1018_10180401_118_dialog_content = "Estou ouvindo apitos de trem...",
  ui_story_1018_10180401_119_dialog_content = "Senhor! O mapa mostra que isso é... Crepúsculo?",
  ui_story_1018_10180401_120_dialog_content = "O Warp fez isso, Senhora Victoria? Por que estamos aqui?",
  ui_story_1018_10180401_121_dialog_content = "Escapamos do Warp e guiei o trem até aqui de acordo com o desejo da Srta. Vice.",
  ui_story_1018_10180401_122_dialog_content = "Crepúsculo acontece justamente no final da linha do raio.",
  ui_story_1018_10180401_123_dialog_content = "Não acredito...",
  ui_story_1018_10180401_124_dialog_content = "Senhor, vejo muitas pessoas ali. Será que é o PlayerName e outros?",
  ui_story_1018_10180401_125_dialog_content = "Há muita lama embaixo do trem. Fique atento para possíveis Eclipsitas nela.",
  ui_story_1018_10180401_126_dialog_content = "Lama imunda, Eclipsitas imundos! O Outro Fim vai esmagá-los!",
  ui_story_1018_10180401_127_dialog_content = "Aguentem firme, pessoal. Vamos passar pelo lamaçal para uma parada à frente!",
  ui_story_1018_10180401_128_dialog_content = "<color=#e8d9bb>*Apito do trem*</color>",
  ui_story_1018_10180401_129_dialog_content = "Ei, Grande Marechal Wrath—",
  ui_story_1018_10180401_130_dialog_content = "Parabéns pela sua nomeação. Desculpe, me atrasei!",
  ui_story_1018_10180401_131_dialog_content = "Grande Marechal Wrath! PlayerName!",
  ui_story_1018_10180401_132_dialog_content = "Vice!",
  ui_story_1018_10180401_133_dialog_content = "Charon, Vice... O que vocês estão fazendo aqui?",
  ui_story_1018_10180401_134_dialog_content = "Você não está em uma missão? Por que está em Crepúsculo?",
  ui_story_1018_10180401_135_dialog_content = "Fique atento ao tempo, Condutor. Esta é apenas uma parada temporária.",
  ui_story_1018_10180401_136_dialog_content = "Ouvi falar da batalha em Crepúsculo e fiquei preocupado, Grande Marechal. No entanto, não posso ficar muito tempo antes de ter que retomar minha missão.",
  ui_story_1018_10180401_137_dialog_content = "Você passou por cima dos Eclipsitas, então isso já é uma grande ajuda.",
  ui_story_1018_10180401_138_dialog_content = "Por outro lado, foi você quem criou o vendaval e não o inimigo?",
  ui_story_1018_10180401_139_dialog_content = "Não viemos aqui por acaso, mas não tenho tempo para explicar. O lamaçal se estende por uma grande área, provavelmente com muitos mais Eclipsitas nele também.",
  ui_story_1018_10180401_140_dialog_content = "O vento significa que o Warp será ativado novamente, minha senhora...?",
  ui_story_1018_10180401_141_dialog_content = "Não está inquieto... Sente-se um pouco, eu vou levar todos comigo.",
  ui_story_1018_10180401_142_dialog_content = "Considerando a distância, em 20 segundos.",
  ui_story_1018_10180401_143_dialog_content = "Vamos fazer a contagem regressiva, minha dama...",
  ui_story_1018_10180401_144_dialog_content = "Você encontrou problemas pelo caminho, Vice?",
  ui_story_1018_10180401_145_dialog_content = "Comparado a vocês de Crepúsculo, o que eu passei não foi nada.",
  ui_story_1018_10180401_146_dialog_content = "Exceto o mumbo-jumbo enigmático da Senhora Victoria... que eu simplesmente não entendo.",
  ui_story_1018_10180401_147_dialog_content = "De qualquer forma, cuide-se. A aparição da Verdadeira Ordem nunca é um bom sinal.",
  ui_story_1018_10180401_148_dialog_content = "Quando você começou a reclamar também?",
  ui_story_1018_10180401_149_dialog_content = "Na verdade, eu acho que a senhora Victoria está nos ajudando.",
  ui_story_1018_10180401_150_dialog_content = "Se essa também for a intenção de Charon...",
  ui_story_1018_10180401_151_dialog_content = "15, 14, 13...",
  ui_story_1018_10180401_152_dialog_content = "10, 9...",
  ui_story_1018_10180401_153_dialog_content = "Portanto, por favor, continue firme, Grande Marechal. Todos em Illumina estão ansiosos pelo seu retorno seguro!",
  ui_story_1018_10180401_154_dialog_content = "Claro, e você também. May que complete a missão com segurança.",
  ui_story_1018_10180401_155_dialog_content = "5, 4, 3...",
  ui_story_1018_10180401_156_dialog_content = "Você se lembra do que eu te disse?",
  ui_story_1018_10180401_157_dialog_content = "Você disse para chamar seu nome se eu estiver em perigo. Eu lembro!",
  ui_story_1018_10180401_158_dialog_content = "2, 1, 0.",
  ui_story_1018_10180401_159_dialog_content = "Bem, então, adeus a todos.",
  ui_story_1018_10180401_160_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_1018_10180401_161_dialog_content = "Eles simplesmente sumiram...",
  ui_story_1018_10180401_162_dialog_content = "Inacreditável. Isso superou meu entendimento de Luminatics.",
  ui_story_1018_10180401_163_dialog_content = "Gah!",
  ui_story_1018_10180401_164_dialog_content = "Grande Marechal! Os Cavaleiros Lumo não conseguem mais conter esses soldados...",
  ui_story_1018_10180401_165_dialog_content = "Realmente estamos totalmente sem opções...",
  ui_story_1018_10180401_166_dialog_content = "Capitão, nossos irmãos estão se perguntando, quem exatamente são nossos inimigos?",
  ui_story_1018_10180401_167_dialog_content = "Os ex-soldados do Grande Marechal que se tornaram Eclipsitas são brutalmente implacáveis...",
  ui_story_1018_10180401_168_dialog_content = "Eu não vou recuar, mesmo que ela tente me impedir desta vez.",
  ui_story_1018_10180401_169_dialog_content = "Quem quer que machuque meus soldados terá que lidar comigo!",
  ui_story_1018_10180401_170_dialog_content = "Siga-me, cavaleiros, e derrote todos!",
  ui_story_1018_10180401_171_dialog_content = "Sim, senhor!",
  ui_story_1018_10180401_X171_dialog_content = "O que é essa rajada de vento repentina? Não estamos sendo atacados, estamos...?",
  ui_story_1018_10180401_X172_dialog_content = "Os Eclipsitas estão aumentando em número, mas a missão de busca e resgate ainda continua. Houve alguma descoberta anormal até agora?",
  ui_story_1018_10180401_X173_dialog_content = "Reportando-me, Grande Marechal! As operações de busca e resgate na minha área designada não foram afetadas até agora!",
  ui_story_1018_10180401_X174_dialog_content = "Relatando, Grande Marechal. Um grande número de Eclipsitas apareceu na minha área. Eu eliminei todos eles.",
  ui_story_1018_10180401_X175_dialog_content = "Grande Marechal, parece que o Capitão Leo encontrou algumas dificuldades no Pântano.",
  ui_story_1018_10180401_X176_dialog_content = "Entendido, estou indo lá. O resto de vocês, fiquem vigilantes.",
  ui_story_1018_10180401_X177_dialog_content = "Todos os feridos já foram colocados em macas, Capitão. Em breve, estarei transportando-os para a enfermaria.",
  ui_story_1018_10180401_X178_dialog_content = "Bom. Cada vez mais Eclipsitas estão aparecendo no Pântano, devemos recuar antes que eles lancem seu próximo ataque.",
  ui_story_1018_10180401_X179_dialog_content = "Sim, Capitão!",
  ui_story_1018_10180401_X180_dialog_content = "Ouvi um barulho estranho agora... Veio de um dos soldados.",
  ui_story_1018_10180401_X181_dialog_content = "Não chegue muito perto deles, Axelia. Esses soldados foram retirados do Pântano anteriormente.",
  ui_story_1018_10180401_X182_dialog_content = "A lama cobrindo seus corpos está fluindo como se estivesse viva...",
  ui_story_1018_10180401_X183_dialog_content = "No momento, não temos como purificar isso de seus corpos...",
  ui_story_1018_10180401_X184_dialog_content = "Rugido...",
  ui_story_1018_10180401_X185_dialog_content = "Rugido...",
  ui_story_1018_10180401_X186_dialog_content = "Os feridos não podem aguentar muito mais tempo, Grande Marechal!",
  ui_story_1018_10180401_X187_dialog_content = "A lama nos corpos deles... Está começando a se mover mais rápido?",
  ui_story_1018_10180401_X188_dialog_content = "É? Então isso só pode significar uma coisa...",
  ui_story_1018_10180401_X189_dialog_content = "Recuem, pessoal! A lama está prestes a espirrar!",
  ui_story_1018_10180401_X190_dialog_content = "Não é apenas lama... Tem algo mais nisso!",
  ui_story_1018_10180401_X191_dialog_content = "Aaarrgh!",
  ui_story_1018_10180401_X192_dialog_content = "Como eu suspeitava, a lama está guiando os Eclipsitas em nossa direção. O Fluxo Escuro também está começando a afetar esses soldados...",
  ui_story_1018_10180401_X193_dialog_content = "... Eu preciso de uma equipe de cavaleiros para proteger os feridos! O resto de vocês, preparem-se para a batalha!",
  ui_story_1018_10180401_X194_dialog_content = "Sim, senhor!",
  ui_story_1018_10180401_X195_dialog_content = "<color=#e8d9bb>Haa... Haa...</color>",
  ui_story_1018_10180401_X196_dialog_content = "Mais deles... E estão atacando por trás!",
  ui_story_1018_10180401_X197_dialog_content = "Eu mal consigo ficar de pé—",
  ui_story_1018_10180401_X198_dialog_content = "Fique atrás de qualquer barreira que encontrar!",
  ui_story_1018_10180401_X199_dialog_content = "Meus olhos... Não consigo nem mantê-los abertos. Será que... É um novo inimigo?",
  ui_story_1018_10180401_X200_dialog_content = "Segure em mim, PlayerName!",
  ui_story_1018_10180401_X201_dialog_content = "<color=#e8d9bb>Psssh— Uu-uuuuu!</color>",
  ui_story_1018_10180401_X202_dialog_content = "PlayerName, você está bem?",
  ui_story_1018_10180401_X203_dialog_content = "Acho que... acho que estou ouvindo apitos de trem...",
  ui_story_1018_10180401_X204_dialog_content = "Estou vendo coisas? Aquele rosto sujo ali... PlayerName?!",
  ui_story_1018_10180401_X205_dialog_content = "C-Como já estamos em Crepúsculo?! Isso é incrível...",
  ui_story_1018_10180401_X206_dialog_content = "O Warp é algo bastante interessante, não é? Mas o que é mais interessante é que o desejo do seu coração nos trouxe aqui, Senhorita Vice.",
  ui_story_1018_10180401_X207_dialog_content = "Realmente, uma façanha e tanto...",
  ui_story_1018_10180401_X208_dialog_content = "Ainda não entendi direito, mas podemos parar logo à frente? Parece que PlayerName e os outros estão em sério perigo...",
  ui_story_1018_10180401_X209_dialog_content = "O Pântano e os Eclipsitas estão começando a se aproximar por todos os lados deles...",
  ui_story_1018_10180401_X210_dialog_content = "Infelizmente, Srta. Vice, este não é nosso destino final. Não há como parar depois que entramos no Warp.",
  ui_story_1018_10180401_X211_dialog_content = "Mas estamos nos aproximando cada vez mais deles... Não há nada que possamos fazer para ajudar?",
  ui_story_1018_10180401_X212_dialog_content = "Talvez não possamos parar...",
  ui_story_1018_10180401_X213_dialog_content = "Mas o Outro Extremo está mais do que equipado para derrubar esses Eclipsitas imundos e cobertos de lama! Segurem-se bem, pessoal!",
  ui_story_1018_10180401_X214_dialog_content = "<color=#e8d9bb>Falha—</color>",
  ui_story_1018_10180401_X215_dialog_content = "Graah—",
  ui_story_1018_10180401_X216_dialog_content = "C-Capitã! Foi... Foi um trem agora há pouco?! Parece que ele atropelou todos os Eclipsitas próximos!",
  ui_story_1018_10180401_X217_dialog_content = "Parecia ser um design de Illumina... Mas esqueça isso agora! Precisamos cuidar dos feridos!",
  ui_story_1018_10180401_X218_dialog_content = "Sim, senhor!",
  ui_story_1018_10180401_X219_dialog_content = "Não há como negar... Aquele era o trem de Charon agora mesmo. Acho que até vi Vice nele também...",
  ui_story_1018_10180401_X220_dialog_content = "Mas por que eles apareceriam de repente aqui, apenas para desaparecer logo em seguida?",
  ui_story_1018_10180401_X221_dialog_content = "Não tenho certeza... Vice e Charon partiram para a missão na Zona Sombria antes de eu chegar ao Crepúsculo.",
  ui_story_1018_10180401_X222_dialog_content = "Eles simplesmente apareceram inesperadamente, exterminaram os Eclipsitas para nós e desapareceram. Isso é algo incomum.",
  ui_story_1018_10180401_X223_dialog_content = "Reportando, Grande Marechal! Descobrimos outra equipe perdida na área!",
  ui_story_1018_10180401_X224_dialog_content = "Entendido. Já estou a caminho.",
  ui_story_1018_10180401_X225_dialog_content = "PlayerName, é muito provável que a missão deles esteja além do nosso entendimento, mas devemos confiar que eles podem lidar com isso por conta própria.",
  ui_story_1018_10180401_X226_dialog_content = "Agora, temos nossos próprios problemas para lidar.",
  ui_story_1018_10180401_X227_dialog_content = "Eu sei. Só espero que tudo dê certo para eles.",
  ui_story_1018_10180401_X228_dialog_content = "(Por favor, tome cuidado, Vice.)",
  ui_story_1018_10180501_1_dialog_content = "<color=#e8d9bb>O trem paira em uma vastidão desconhecida...</color>",
  ui_story_1018_10180501_2_dialog_content = "Tire suas mangas, Minch, você estava me sufocando durante todo o caminho!",
  ui_story_1018_10180501_3_dialog_content = "Ei, olha, o sino está brilhando. Será que isso significa que tivemos sucesso?",
  ui_story_1018_10180501_4_dialog_content = "De fato, a sensação de uma substância espessa atingindo minhas pálpebras é inconfundível.",
  ui_story_1018_10180501_5_dialog_content = "Onde estamos, Senhora Victoria...?",
  ui_story_1018_10180501_6_dialog_content = "Sem luz ou escuridão, apenas A Verdade. Este é o meu santuário secreto.",
  ui_story_1018_10180501_7_dialog_content = "Oh meu! Vou me ajoelhar para que meu mestre pregue o evangelho!",
  ui_story_1018_10180501_8_dialog_content = "Essa é a dor surda da Palavra da Verdade que eu me lembro. Vou ouvir com total atenção!",
  ui_story_1018_10180501_9_dialog_content = "Alguém se importa em falar em linguagem simples? O que é este lugar?",
  ui_story_1018_10180501_10_dialog_content = "Não se preocupe, Senhorita Vice. Nós fugimos do Warp.",
  ui_story_1018_10180501_11_dialog_content = "Então, você nos salvou?",
  ui_story_1018_10180501_12_dialog_content = "O ponto é, você seguiu minha orientação—",
  ui_story_1018_10180501_13_dialog_content = "Minha senhora, eu \"vejo\" sangue!",
  ui_story_1018_10180501_14_dialog_content = "Eu \"ouço\" palavras vívidas e a dor fere meus ouvidos!",
  ui_story_1018_10180501_15_dialog_content = "Eu não esperava que O Tomo Negro desse a revelação agora...",
  ui_story_1018_10180501_16_dialog_content = "As letras estão mudando tão rapidamente...",
  ui_story_1018_10180501_17_dialog_content = "\"Após a operação, o fracasso será enfrentado.\"",
  ui_story_1018_10180501_18_dialog_content = "Será isso o chamado \"O Eclipse expandirá sua cauda e, quando a Aurora chegar, Ele começará a jornada de volta.\"",
  ui_story_1018_10180501_19_dialog_content = "Não, ainda está mudando...",
  ui_story_1018_10180501_20_dialog_content = "\"Após os contratempos, surgirá um empreendimento magnífico.\"",
  ui_story_1018_10180501_21_dialog_content = "Isso se correlaciona com \"No tempo da catástrofe, os Aurorianos encontrarão Ele, mas impedidos pela Aurora.\"",
  ui_story_1018_10180501_22_dialog_content = "A Revelação é incerta...",
  ui_story_1018_10180501_23_dialog_content = "Minha senhora, um ódio intenso queima nos olhos do Senhor...",
  ui_story_1018_10180501_24_dialog_content = "Feche os olhos, Dysis! Esse não é o Senhor, pois Ele não odeia!",
  ui_story_1018_10180501_25_dialog_content = "Segurem a respiração, pessoal.",
  ui_story_1018_10180501_26_dialog_content = "...",
  ui_story_1018_10180501_27_dialog_content = "Senhor, há um sinal fraco chegando no painel.",
  ui_story_1018_10180501_28_dialog_content = "É uma coordenada da Equipe de Expedição da Zona Cega, e a localização não está no mapa.",
  ui_story_1018_10180501_29_dialog_content = "Porque não é um <color=#FFB400>lugar real</color>, mas sim o \"Todos saem de casa, mas a jornada de retorno é o começo\" na revelação.",
  ui_story_1018_10180501_30_dialog_content = "O que isso significa? Conseguimos encontrá-los?",
  ui_story_1018_10180501_31_dialog_content = "Acredito que é hora de Luz e Escuridão resolverem sua guerra, e o Senhor da Verdade virá.",
  ui_story_1018_10180501_32_dialog_content = "Para testemunhar o momento, eu vou levá-lo ao destino.",
  ui_story_1018_10180501_33_dialog_content = "No entanto, preciso da sua ajuda, Maestro.",
  ui_story_1018_10180501_34_dialog_content = "...",
  ui_story_1018_10180501_35_dialog_content = "Estou muito desconfortável agora, Oficial Charon...",
  ui_story_1018_10180501_36_dialog_content = "O santuário secreto da Senhora Victoria parece estar comprimindo... Estou com dificuldade para respirar...",
  ui_story_1018_10180501_37_dialog_content = "Eu também...",
  ui_story_1018_10180501_38_dialog_content = "Achei, afinal, estou vendo...",
  ui_story_1018_10180501_39_dialog_content = "O que o Anemone estava fazendo, te deixando para trás todo esse tempo?",
  ui_story_1018_10180501_40_dialog_content = "Quem está falando...?",
  ui_story_1018_10180501_41_dialog_content = "Eu te odeio, mas não consigo lembrar o motivo...",
  ui_story_1018_10180501_42_dialog_content = "Deixe meu povo em paz, seu imundo!",
  ui_story_1018_10180501_43_dialog_content = "Você não me interessa. Mas a mulher loira, eu gosto do objeto em sua mão.",
  ui_story_1018_10180501_44_dialog_content = "A Verdade vai abalar você até o âmago, servo do mal.",
  ui_story_1018_10180501_45_dialog_content = "Acredito que vocês é que deveriam estar tremendo. O que estão fazendo de olhos fechados?",
  ui_story_1018_10180501_46_dialog_content = "Oferecendo sangue para proteção do Senhor da Verdade.",
  ui_story_1018_10180501_47_dialog_content = "Ah, você está realizando um ritual.",
  ui_story_1018_10180501_48_dialog_content = "Sou seu oponente, canalha com medo de mostrar o rosto! Tome este Fogo do Inferno!",
  ui_story_1018_10180501_49_dialog_content = "Discípulo Dysis fez a oferenda.",
  ui_story_1018_10180501_50_dialog_content = "Com a oferta da dor, o Senhor falará o evangelho a você.",
  ui_story_1018_10180501_51_dialog_content = "Discípulo Merry fez a oferta.",
  ui_story_1018_10180501_52_dialog_content = "Deixe-me fazer isso, é mais eficiente.",
  ui_story_1018_10180501_53_dialog_content = "Testemunhe o Milagre!",
  ui_story_1018_10180501_54_dialog_content = "O ritual será concluído em breve, Maestra!",
  ui_story_1018_10180501_55_dialog_content = "Você está bem, Oficial Charon?",
  ui_story_1018_10180501_56_dialog_content = "Fiquem firmes, o Barqueiro de Acheron está passando! Virando o trem para baixo!",
  ui_story_1018_10180501_57_dialog_content = "Meus pés estão fora do chão?",
  ui_story_1018_10180501_58_dialog_content = "Com a oferta de um animal de estimação, o Senhor revelará o mistério.",
  ui_story_1018_10180501_59_dialog_content = "Discípulo Minch fez a oferta.",
  ui_story_1018_10180501_60_dialog_content = "Está correndo?",
  ui_story_1018_10180501_61_dialog_content = "May que o Senhor aceite as ofertas, tome o poder do meu sangue e mostre a verdade carmesim ao mundo!",
  ui_story_1018_10180501_62_dialog_content = "Um milagre se manifestou... O Reino dos Fantasmas foi violado!",
  ui_story_1018_10180501_63_dialog_content = "Aguentem firme, pessoal...!",
  ui_story_1018_10180501_64_dialog_content = "Não, eu não consigo, estou caindo muito rápido...",
  ui_story_1018_10180501_65_dialog_content = "No caminho para a Zona Escura, passaremos pelo <color=#FFB400>Rio Styx</color>, também conhecido como <color=#FFB400>Deserto Esquecido</color>.",
  ui_story_1018_10180501_66_dialog_content = "Por favor, mantenha os olhos fechados até ver a luz para evitar a detecção por elementos perigosos.",
  ui_story_1018_10180501_67_dialog_content = "Mas vejo multidões de Eclipsitas vindo em minha direção quando fecho os olhos...",
  ui_story_1018_10180501_68_dialog_content = "Eles estão apenas na sua mente, não são reais.",
  ui_story_1018_10180501_69_dialog_content = "Mas eles são soldados da Illumina...",
  ui_story_1018_10180501_70_dialog_content = "Eu os vejo se alimentando de mechas...",
  ui_story_1018_10180501_71_dialog_content = "Eles estão se matando...",
  ui_story_1018_10180501_72_dialog_content = "Também vejo um pântano negro se estendendo da Zona Escura até a linha de frente de Illumina...",
  ui_story_1018_10180501_73_dialog_content = "(Saia, não se aproxime.)",
  ui_story_1018_10180501_74_dialog_content = "(É você... Quem é você?)",
  ui_story_1018_10180501_75_dialog_content = "(Saia, não se aproxime.)",
  ui_story_1018_10180501_76_dialog_content = "(Mas sinto uma força desconhecida me impulsionando para a frente...)",
  ui_story_1018_10180501_77_dialog_content = "Vice?",
  ui_story_1018_10180501_78_dialog_content = "Há uma voz nos dizendo para irmos embora...",
  ui_story_1018_10180501_79_dialog_content = "Não ouça nem encare, ou você pode nunca mais acordar.",
  ui_story_1018_10180501_80_dialog_content = "Não consigo vê-la claramente, mas posso ouvir sua voz e batimentos cardíacos. É tão real...",
  ui_story_1018_10180501_81_dialog_content = "Como se eu fosse ela...",
  ui_story_1018_10180501_82_dialog_content = "É exatamente esse sinal que indica que o perigo está logo ali na esquina.",
  ui_story_1018_10180501_83_dialog_content = "(PlayerName disse para ligar se eu estiver em perigo.)",
  ui_story_1018_10180501_84_dialog_content = "(Deve alcançar, certo...)",
  ui_story_1018_10180501_85_dialog_content = "(Sair, perigo.)",
  ui_story_1018_10180501_86_dialog_content = "(Mas não importa o que aconteça, eu vou te ver...)",
  ui_story_1018_10180501_87_dialog_content = "(Porque foi a primeira vez que senti que alguém poderia estar tão perto de mim...)",
  ui_story_1018_10180501_88_dialog_content = "(...)",
  ui_story_1018_10180501_89_dialog_content = "(O que é isso...?)",
  ui_story_1018_10180501_90_dialog_content = "(o batimento cardíaco de Vice...)",
  ui_story_1018_10180501_91_dialog_content = "(Ela está em perigo...)",
  ui_story_1018_10180501_92_dialog_content = "PlayerName, cuidado atrás de você!",
  ui_story_1018_10180601_1_dialog_content = "Rugido...",
  ui_story_1018_10180601_2_dialog_content = "Grande Marechal, por favor, dê a ordem... Minha arma está travada na cabeça dele...",
  ui_story_1018_10180601_X2_dialog_content = "Guarde sua arma!",
  ui_story_1018_10180601_X3_dialog_content = "Mas... Mas ele matou tantos dos nossos companheiros soldados! Ele até atacou você, seu oficial comandante! Ele não merece ser um soldado de Illumina, muito menos o líder do Nono Esquadrão!",
  ui_story_1018_10180601_X4_dialog_content = "Isso não foi culpa dele. Algo em seus olhos me diz que ele ainda está lá dentro.",
  ui_story_1018_10180601_X5_dialog_content = "Grande Marechal! Os cavaleiros não conseguem mais conter esses soldados... Nesse ritmo, todos nós estaremos em grande perigo em breve...",
  ui_story_1018_10180601_3_dialog_content = "Embora ele possa comandar o Nono Esquadrão, suas mãos estão manchadas com o sangue de nossos irmãos. Ele não merece ser tratado como um soldado Illumina!",
  ui_story_1018_10180601_4_dialog_content = "Os olhos dele estão me dizendo que ainda há uma pessoa lá dentro!",
  ui_story_1018_10180601_5_dialog_content = "Dê uma boa olhada, eu sou o seu Grande Marechal. Agora tire suas mãos de cima!",
  ui_story_1018_10180601_6_dialog_content = "... Grande Marechal...",
  ui_story_1018_10180601_7_dialog_content = "Ele realmente consegue nos ouvir...",
  ui_story_1018_10180601_8_dialog_content = "Vou te levar de volta para Illumina. Você não vai morrer aqui.",
  ui_story_1018_10180601_9_dialog_content = "...",
  ui_story_1018_10180601_10_dialog_content = "O corpo dele está sendo controlado pelo Fluxo Escuro. Ele vai acabar quebrando seu pescoço mais cedo ou mais tarde se você esperar.",
  ui_story_1018_10180601_11_dialog_content = "Rugido...",
  ui_story_1018_10180601_12_dialog_content = "(O poder dentro de mim... Parece que foi despertado...)",
  ui_story_1018_10180601_13_dialog_content = "(Estou sentindo vontade de matá-lo...)",
  ui_story_1018_10180601_14_dialog_content = "Wrath, ele está mentalmente perdido como você estava, então não se precipite...",
  ui_story_1018_10180601_15_dialog_content = "Talvez eu deva tentar com minha habilidade psíquica?",
  ui_story_1018_10180601_16_dialog_content = "Não sabemos em que condição ele está, então você pode se machucar.",
  ui_story_1018_10180601_17_dialog_content = "Mas é provavelmente a única chance que temos...",
  ui_story_1018_10180601_18_dialog_content = "Se algo começar a dar errado, eu paro imediatamente, eu prometo.",
  ui_story_1018_10180601_19_dialog_content = "Se ele te machucar, eu não hesitarei...",
  ui_story_1018_10180601_20_dialog_content = "Tá bom...",
  ui_story_1018_10180601_21_option_content = "Tente conexão mental",
  ui_story_1018_10180601_22_dialog_content = "(Estou em... Isso é... a Subcidade de Illumina...)",
  ui_story_1018_10180601_23_dialog_content = "(Este deve ser o alojamento. Consigo até sentir o cheiro dos detergentes.)",
  ui_story_1018_10180601_24_dialog_content = "Mas mãe, essa é uma oportunidade única na vida!",
  ui_story_1018_10180601_25_dialog_content = "(Discutindo com a mãe?)",
  ui_story_1018_10180601_26_dialog_content = "Inúmeros desafios em direção aos seus objetivos fizeram a Comandante Wrath chegar onde está hoje!",
  ui_story_1018_10180601_27_dialog_content = "Se eu perder este programa de treinamento de soldados, meu sonho de me tornar um Grande Marechal nunca se tornará realidade!",
  ui_story_1018_10180601_28_dialog_content = "A Comandante Wrath acredita nas minhas habilidades e disse que eu tenho o que é preciso para cargos de maior hierarquia!",
  ui_story_1018_10180601_29_dialog_content = "Para se tornar um líder... Para sair vitorioso em batalhas, uma após a outra... Assim como seu pai buscou, e agora, é você...",
  ui_story_1018_10180601_30_dialog_content = "Você realmente herdou a coragem e a inteligência do seu pai. Em meus olhos, você é sempre o melhor...",
  ui_story_1018_10180601_31_dialog_content = "Mas querido(a)... Eu ouvi dizer que o programa de treinamento pode ser extremamente exigente...",
  ui_story_1018_10180601_32_dialog_content = "Se você não conseguir passar por esse treinamento, talvez nunca mais consiga retornar ao campo de batalha...",
  ui_story_1018_10180601_33_dialog_content = "Fique comigo, você vai? Vocês dois são tudo que eu tenho agora...",
  ui_story_1018_10180601_34_dialog_content = "Mãe... Eu tenho fé no meu irmão...",
  ui_story_1018_10180601_35_dialog_content = "Sim, mãe. Por favor, também tenha fé em mim! Vou aguentar firme, sem dúvidas!",
  ui_story_1018_10180601_36_dialog_content = "Não há futuro para mim se eu continuar em Gannon City. Ir para o campo de batalha e aceitar a morte como parte inevitável - é isso que os verdadeiros soldados fazem!",
  ui_story_1018_10180601_37_dialog_content = "Ai ai... Por favor, não diga coisas assim novamente.",
  ui_story_1018_10180601_38_dialog_content = "De qualquer forma, eu já me decidi!",
  ui_story_1018_10180601_39_dialog_content = "(...)",
  ui_story_1018_10180601_40_dialog_content = "(O que a mãe dele vai pensar se souber o que está acontecendo com ele na batalha?)",
  ui_story_1018_10180601_41_dialog_content = "(Opa, perdi a noção ouvindo eles!)",
  ui_story_1018_10180601_42_dialog_content = "(Hmm, este é um lugar novo e a luz está ofuscante...)",
  ui_story_1018_10180601_43_dialog_content = "Comandante, este é o teste final do Programa Phospherus?",
  ui_story_1018_10180601_44_dialog_content = "Correto, este é o último passo.",
  ui_story_1018_10180601_45_dialog_content = "Sem restrições agora. Seu único objetivo é derrotar o próximo oponente e sobreviver.",
  ui_story_1018_10180601_46_dialog_content = "(Ei, saia daqui agora!)",
  ui_story_1018_10180601_47_dialog_content = "(Mãe? O que você está fazendo aqui... Eu já tomei minha decisão, então por favor não me impeça..)",
  ui_story_1018_10180601_48_dialog_content = "(Ele me considerou como sua mãe. Nesse caso...)",
  ui_story_1018_10180601_49_dialog_content = "(Não ouça ele. Entrar no projeto vai te transformar em um Eclipsita! Eu não quero te ver assim!)",
  ui_story_1018_10180601_50_dialog_content = "(Não, mãe... O comandante acha que eu sou realmente talentoso, e eu preciso passar no teste.)",
  ui_story_1018_10180601_51_dialog_content = "Podemos começar quando você estiver pronto.",
  ui_story_1018_10180601_52_dialog_content = "(Ele está mentindo para você! Você está lutando uma batalha em Crepúsculo agora mesmo!)",
  ui_story_1018_10180601_53_dialog_content = "(Não é um inimigo à sua frente, mas sim o Wrath, seu superior. Agora saia da sala!)",
  ui_story_1018_10180601_54_dialog_content = "(Wrath, o Grande Marechal, também está assistindo?)",
  ui_story_1018_10180601_55_dialog_content = "(Crepúsculo, você mencionou... eu sinto como se já estivesse lá...)",
  ui_story_1018_10180601_56_dialog_content = "O que você está esperando?",
  ui_story_1018_10180601_57_dialog_content = "Não... Comandante, estou pronto.",
  ui_story_1018_10180601_58_dialog_content = "(Por favor, acorde!)",
  ui_story_1018_10180601_59_dialog_content = "(Mãe, olhe para mim... Eu vou me tornar um guerreiro corajoso.)",
  ui_story_1018_10180601_60_dialog_content = "Ah!",
  ui_story_1018_10180601_61_dialog_content = "(Ei, acorde! Não resista!)",
  ui_story_1018_10180601_62_dialog_content = "Comandante, no momento em que vejo o Eclipsita, sinto... um aumento de força percorrendo meu corpo.",
  ui_story_1018_10180601_63_dialog_content = "Isso mesmo, sinta o poder e depois controle esse poder.",
  ui_story_1018_10180601_64_dialog_content = "Ah!",
  ui_story_1018_10180601_65_dialog_content = "Todos os Eclipsitas... DEVEM MORRER!",
  ui_story_1018_10180601_66_dialog_content = "(Oh não, se eu não acabar com isso agora...)",
  ui_story_1018_10180601_67_dialog_content = "MORRA!!!",
  ui_story_1018_10180601_68_dialog_content = "Ah!",
  ui_story_1018_10180601_69_dialog_content = "<color=#e8d9bb>Roooaaarrr!!!</color>",
  ui_story_1018_10180601_70_dialog_content = "Oh não! O rugido dele parece ter deixado todos os outros soldados corrompidos agitados!",
  ui_story_1018_10180602_1_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1018_10180602_2_dialog_content = "...",
  ui_story_1018_10180602_3_dialog_content = "Desculpe, Grande Marechal. Este é o único jeito.",
  ui_story_1018_10180602_4_dialog_content = "Você tá bem, PlayerName?",
  ui_story_1018_10180602_5_dialog_content = "Desculpe, não consegui salvá-lo...",
  ui_story_1018_10180602_6_dialog_content = "Mas ele era um excelente soldado.",
  ui_story_1018_10180602_7_dialog_content = "Axelia está triste...",
  ui_story_1018_10180602_8_dialog_content = "O que você vai fazer com aqueles soldados ali?",
  ui_story_1018_10180602_9_dialog_content = "...",
  ui_story_1018_10180602_10_dialog_content = "Eliminá-los eu mesmo. Não sou digno de ser o Grande Marechal...",
  ui_story_1018_10180602_11_dialog_content = "(O que devo fazer?)",
  ui_story_1018_10180602_12_dialog_content = "(O que você faria, Reinhardt, se fosse você?)",
  ui_story_1018_10180602_13_dialog_content = "Deixe-me fazer isso.",
  ui_story_1018_10180602_14_dialog_content = "Leo...",
  ui_story_1018_10180602_15_dialog_content = "Apenas finja que você não conseguiu me impedir quando eu fiz questão de matá-los.",
  ui_story_1018_10180602_16_dialog_content = "Sou apenas um cavaleiro residente de Crepúsculo. Não tenho a responsabilidade de comandar um exército inteiro como você.",
  ui_story_1018_10180602_17_dialog_content = "A misericórdia só levará a maiores perdas. Você precisa aprender a enfrentar essa realidade.",
  ui_story_1018_10180602_18_dialog_content = "Não, não suporto todo esse sangue nas minhas mãos...",
  ui_story_1018_10180602_19_dialog_content = "Eu prometi a eles que os lideraria à vitória nesta batalha...",
  ui_story_1018_10180602_20_dialog_content = "Em vez disso, eu os levei direto para o túmulo...",
  ui_story_1018_10180602_21_dialog_content = "(Eu pensei que, enquanto eu tivesse o poder, se fosse forte o suficiente, eu poderia fazer qualquer coisa.)",
  ui_story_1018_10180602_22_dialog_content = "(Forte o suficiente... Que piada...)",
  ui_story_1018_10180602_23_dialog_content = "Wrath, acho que o que você está fazendo é mais difícil do que tentar ser mais poderoso.",
  ui_story_1018_10180602_24_dialog_content = "...",
  ui_story_1018_10180602_25_dialog_content = "Colocar o próprio corpo em perigo é o propósito de um guerreiro.",
  ui_story_1018_10180602_26_dialog_content = "Quando eles próprios se tornam o perigo e não conseguem proteger vidas...",
  ui_story_1018_10180602_27_dialog_content = "Esta é a única coisa que podemos fazer por eles como comandantes.",
  ui_story_1018_10180602_28_dialog_content = "Comandante...",
  ui_story_1018_10180602_29_dialog_content = "(É isso que você quis dizer ao deixar ir, Reinhardt...?)",
  ui_story_1018_10180602_30_dialog_content = "Confie em mim, seus soldados estão morrendo onde deveriam e a dor deles acabará em breve.",
  ui_story_1018_10180602_31_dialog_content = "Espere, Leo.",
  ui_story_1018_10180602_32_dialog_content = "Você provavelmente está certo sobre eles morrerem onde deveriam...",
  ui_story_1018_10180602_33_dialog_content = "Devo encarar a realidade.",
  ui_story_1018_10180602_34_dialog_content = "Em vez de viverem em agonia, vou tornar tudo rápido e fácil para eles.",
  ui_story_1018_10180602_35_dialog_content = "Grande marechal...",
  ui_story_1018_10180602_36_dialog_content = "Todos os soldados, por favor, permitam-me dizer algumas palavras finais aos seus ex-companheiros.",
  ui_story_1018_10180602_37_dialog_content = "Não importa o quê, sempre te seguiremos!",
  ui_story_1018_10180602_38_dialog_content = "...",
  ui_story_1018_10180602_39_dialog_content = "Mesmo que você não consiga entender o que estou dizendo, eu prometo a você...",
  ui_story_1018_10180602_40_dialog_content = "Vocês são soldados da Illumina, nascidos para servir com orgulho a Illumina, assumindo o dever de destruir os Eclipsitas.",
  ui_story_1018_10180602_41_dialog_content = "Você sabe que uma batalha é o caminho mais rápido para a morte, mas mesmo assim avançou sem medo...",
  ui_story_1018_10180602_42_dialog_content = "Vocês morrerão como valentes guerreiros da Illumina...",
  ui_story_1018_10180602_43_dialog_content = "Não alguém forçado a ser abandonado...",
  ui_story_1018_10180602_44_dialog_content = "Continuaremos sua missão inacabada e continuaremos lutando!",
  ui_story_1018_10180602_45_dialog_content = "Rugido...",
  ui_story_1018_10180602_46_dialog_content = "(É isso aí, Wrath, vai acabar bem rápido...)",
  ui_story_1018_10180602_47_dialog_content = "E você está livre de suas obrigações e livre para comemorar...",
  ui_story_1018_10180602_48_dialog_content = "A vitória em um lugar livre de guerra.",
  ui_story_1018_10180602_49_dialog_content = "Ah!",
  ui_story_1018_10180602_50_dialog_content = "Atiradores miram...",
  ui_story_1018_10180602_51_dialog_content = "Fogo!",
  ui_story_1018_10180602_52_dialog_content = "<color=#e8d9bb>Bang! Bang! Bang!</color>",
  ui_story_1018_10180602_53_dialog_content = "...",
  ui_story_1018_10180602_54_dialog_content = "A guerra acabou para você. Descanse em paz.",
  ui_story_1018_10180602_55_dialog_content = "...",
  ui_story_1018_10180602_56_dialog_content = "...",
  ui_story_1018_10180701_1_dialog_content = "<color=#e8d9bb>A caminho da Fortaleza Lumo...</color>",
  ui_story_1018_10180701_2_dialog_content = "A Fortaleza Lumo está logo à frente, Chi. Como você está?",
  ui_story_1018_10180701_3_dialog_content = "Mmm... Ainda tenho um pouco de energia sobrando...",
  ui_story_1018_10180701_4_dialog_content = "Você não parece bem. O soldado que se soltou da corda te assustou?",
  ui_story_1018_10180701_5_dialog_content = "Não, Joselyne...",
  ui_story_1018_10180701_6_dialog_content = "Ao ver você lutando tão intensamente para proteger a todos, eu não tenho medo nenhum.",
  ui_story_1018_10180701_7_dialog_content = "Mas desta vez... há tantos feridos... alguns até precisam ser contidos com cordas...",
  ui_story_1018_10180701_8_dialog_content = "Ah, eu não quis reclamar ou algo assim! Eu entendo que esses soldados estão aqui para nos proteger...",
  ui_story_1018_10180701_9_dialog_content = "É só que... Joselyne, deve ser realmente difícil para você enfrentar situações como essa o tempo todo, né...",
  ui_story_1018_10180701_10_dialog_content = "...",
  ui_story_1018_10180701_11_dialog_content = "Você sabe, Chi, que a vida em Crepúsculo quando eu era criança era mais difícil do que é agora?",
  ui_story_1018_10180701_12_dialog_content = "Quando você era pequeno, Joselyne?",
  ui_story_1018_10180701_13_dialog_content = "Quando eu tinha 12 anos, Eclipsitas invadiram Crepúsculo. Meus pais perderam suas vidas para me proteger.",
  ui_story_1018_10180701_14_dialog_content = "Ninguém veio ajudar nossa aldeia, então só podíamos contar conosco mesmos.",
  ui_story_1018_10180701_15_dialog_content = "Lembro que até crianças um pouco mais velhas do que eu pegaram em armas e lutaram. Nunca mais vi muitas delas...",
  ui_story_1018_10180701_16_dialog_content = "Então... O que aconteceu depois?",
  ui_story_1018_10180701_17_dialog_content = "Então os Eclipsitas invadiram a vila. Eu peguei as crianças restantes comigo e nos escondemos em todos os lugares. Esse medo ficou comigo por muitos anos.",
  ui_story_1018_10180701_18_dialog_content = "Felizmente, fomos resgatados pelos Cavaleiros da Expedição, e os soldados me levaram para o orfanato da Igreja Noite Branca, então me tornei uma freira.",
  ui_story_1018_10180701_19_dialog_content = "Isso parece bem difícil... Então, por que você decidiu se juntar aos Cavaleiros da Expedição mais tarde?",
  ui_story_1018_10180701_20_dialog_content = "Porque acredito que apenas ao enfrentar ativamente os Eclipsitas, o povo do Crepúsculo terá uma chance de sobreviver.",
  ui_story_1018_10180701_21_dialog_content = "Fui salvo pelos Cavaleiros, então gostaria de criar um ambiente seguro para o Crepúsculo, assim como eles fizeram.",
  ui_story_1018_10180701_22_dialog_content = "Joselyne, você é realmente uma pessoa incrível!",
  ui_story_1018_10180701_23_dialog_content = "Você ajudou muitas pessoas, Chi. Você é melhor do que eu nessa idade!",
  ui_story_1018_10180701_24_dialog_content = "Aqui estamos. Só empurre um pouco mais e os feridos estarão seguros.",
  ui_story_1018_10180701_25_dialog_content = "Certo!",
  ui_story_1018_10180701_26_dialog_content = "<color=#e8d9bb>Toc-toc, toc, toc-toc</color>",
  ui_story_1018_10180701_27_dialog_content = "Eu sou Joselyne, um guerreiro do Crepúsculo. Trouxemos feridos e solicitamos ajuda médica e abrigo na Fortaleza Lumo!",
  ui_story_1018_10180701_28_dialog_content = "O Senhor da Cidade ordenou que a entrada é permitida apenas para os residentes de Lumo. Você deve procurar abrigo em outro lugar.",
  ui_story_1018_10180701_29_dialog_content = "Por favor, escute, os feridos atrás de mim incluem cavaleiros da Fortaleza Lumo. Eles lutaram conosco. O mínimo que você pode fazer é deixá-los entrar.",
  ui_story_1018_10180701_30_dialog_content = "Os Cavaleiros Ironthorn já solicitaram ajuda várias vezes anteriormente. Infelizmente, a Fortaleza Lumo possui recursos limitados e não podemos oferecer atendimento médico para mais soldados.",
  ui_story_1018_10180701_31_dialog_content = "Mas senhor—",
  ui_story_1018_10180701_32_dialog_content = "<color=#e8d9bb>Tum! Tump!</color>",
  ui_story_1018_10180701_33_dialog_content = "Joselyne! Está ficando mais difícil controlar esses dois soldados Illumina!",
  ui_story_1018_10180701_34_dialog_content = "Se eles se libertarem das cordas novamente e atacarem os feridos...",
  ui_story_1018_10180701_35_dialog_content = "Os membros da sua equipe representam uma ameaça aos moradores da Fortaleza Lumo. Há ainda mais motivos para não deixá-los entrar!",
  ui_story_1018_10180701_36_dialog_content = "Entendo...",
  ui_story_1018_10180701_37_dialog_content = "Por favor, dê uma mensagem ao Padre Joseph da Igreja da Noite Branca para mim—",
  ui_story_1018_10180701_38_dialog_content = "Eu, Joselyne, solicito asilo para os Aurorianos junto à Igreja da Noite Branca como a Santa do Crepúsculo.",
  ui_story_1018_10180701_39_dialog_content = "Padre Joseph está ocupado com assuntos importantes e não está na cidade. Quanto a você, você é apenas a “Santa” de que falam os de Crepúsculo.",
  ui_story_1018_10180701_40_dialog_content = "Mesmo que você fosse uma verdadeira Santa, eu ainda não desafiaria a ordem do Senhor da Cidade!",
  ui_story_1018_10180701_41_dialog_content = "A Igreja vai ignorar as vidas dos Aurorianos quando o povo do Deus da Luz estiver em situação crítica?!",
  ui_story_1018_10180701_42_dialog_content = "Rarrr!",
  ui_story_1018_10180701_43_dialog_content = "Céus... Esses soldados se transformaram em Eclipsitas?",
  ui_story_1018_10180701_44_dialog_content = "Joselyne!",
  ui_story_1018_10180701_45_dialog_content = "Não entre em pânico! Afaste-se o máximo possível dos carrinhos. Eu vou cuidar disso!",
  ui_story_1018_10180701_46_dialog_content = "<size=30>Abra o portão.</size>",
  ui_story_1018_10180701_47_dialog_content = "Deixar esses soldados entrar seria praticamente cavar nossa própria cova...",
  ui_story_1018_10180701_48_dialog_content = "Abra o portão.",
  ui_story_1018_10180701_49_dialog_content = "Como ousa desafiar a Santa! Você virou as costas para a Igreja?",
  ui_story_1018_10180701_50_dialog_content = "Eu, Capitão Carleen dos Guardiões dos Jardins de Lumópolis, ordeno que você abra o portão para os refugiados como o Senhor da Cidade interino de Lumo Stronghold!",
  ui_story_1018_10180701_51_dialog_content = "Vou enfrentar os Eclipsitas. Agora abra o portão!",
  ui_story_1018_10180701_52_dialog_content = "Senhora Carleen... S-Sim!",
  ui_story_1018_10180701_53_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_1018_10180702_1_dialog_content = "<color=#e8d9bb>Ao ver este brilho sobrenatural, todos não podem evitar querer se curvar em reverência...</color>",
  ui_story_1018_10180702_2_dialog_content = "Uma verdadeira Senhora Santa!",
  ui_story_1018_10180702_3_dialog_content = "Isso não pode estar errado, a única Senhora Santa na luz sagrada!",
  ui_story_1018_10180702_4_dialog_content = "Como o Deus da Luz é minha testemunha, eu não disse nada além da verdade—",
  ui_story_1018_10180702_5_dialog_content = "Pela sua luz sagrada, guie os Aurorians perdidos.",
  ui_story_1018_10180702_6_dialog_content = "Joselyne! A luz dourada brilha nos corpos dos soldados!",
  ui_story_1018_10180702_7_dialog_content = "Isso é estranho... de um jeito bom. Quer dizer... a dor no meu corpo está desaparecendo...",
  ui_story_1018_10180702_8_dialog_content = "Uh, Joselyne... Você está... chorando?",
  ui_story_1018_10180702_9_dialog_content = "Ver a Senhora Santa pessoalmente... Isso é muito emocionante para mim...",
  ui_story_1018_10180702_10_dialog_content = "Chi, ela é a própria mensageira de Deus, a Senhora Santa da Igreja da Noite Branca!",
  ui_story_1018_10180702_11_dialog_content = "Senhora Santidade...",
  ui_story_1018_10180702_12_dialog_content = "Joselyne—",
  ui_story_1018_10180702_13_dialog_content = "Pai Joseph! Noite Branca lá no alto—",
  ui_story_1018_10180702_14_dialog_content = "Noite Branca nas alturas— Condolências aos soldados em Crepúsculo. Como está o Leo por aí?",
  ui_story_1018_10180702_15_dialog_content = "Muito menos Eclipsitas agora, graças aos soldados Illumina e ao Celestita.",
  ui_story_1018_10180702_16_dialog_content = "Mas o atoleiro ainda é um problema, e os soldados Illumina estão enfrentando dificuldades...",
  ui_story_1018_10180702_17_dialog_content = "Lamento muito ouvir isso. Os soldados na fortaleza seguem ordens dos nobres de Lumópolis, e os reforços enviados pelo Senhor da Cidade foram principalmente destinados a fins defensivos.",
  ui_story_1018_10180702_18_dialog_content = "Além de continuar implorando a Schwartz eu mesmo, eu não podia fazer muito mais...",
  ui_story_1018_10180702_19_dialog_content = "Só pude enviar membros da igreja para o Crepúsculo e ajudar, e então enviar incessantes cartas ao Templo da Noite Branca pedindo auxílio.",
  ui_story_1018_10180702_20_dialog_content = "Entendi! Agora que a Senhora Santa está aqui, a Igreja da Noite Branca é abençoada com a graça divina!",
  ui_story_1018_10180702_21_dialog_content = "Eu também não esperava isso. Estava planejando visitar Lumopolis depois de enviar minha última solicitação.",
  ui_story_1018_10180702_22_dialog_content = "Mas antes de partir, recebi instruções pessoais da própria Senhora Santa, então fiquei e esperei.",
  ui_story_1018_10180702_23_dialog_content = "Conversaremos sobre os detalhes mais tarde. Preciso ir fazer preparativos na igreja.",
  ui_story_1018_10180702_24_dialog_content = "Vou enviar membros da igreja para Crepúsculo para transportar os feridos.",
  ui_story_1018_10180702_25_dialog_content = "Obrigado pela sua ajuda, Padre Joseph!",
  ui_story_1018_10180702_26_dialog_content = "Mas alguns dos feridos foram afetados de maneira bastante única, então, por favor, fique de olho neles.",
  ui_story_1018_10180702_27_dialog_content = "Nada com que se preocupar. A comitiva com a Senhora Santa é tão especialista em tratamento quanto ela. Eu cuidarei deles.",
  ui_story_1018_10180702_28_dialog_content = "Avante, Noite Branca.",
  ui_story_1018_10180702_29_dialog_content = "Avante, Noite Branca.",
  ui_story_1018_10180702_30_dialog_content = "Ufa... Agradeça ao eterno Deus da Luz, não deve haver mais problemas.",
  ui_story_1018_10180702_31_dialog_content = "Você... Você realmente é a Senhora Santidade... Uma chegada divina neste reino abandonado!",
  ui_story_1018_10180702_32_dialog_content = "Com a presença da Senhora Santidade, o lamaçal não se espalhará mais!",
  ui_story_1018_10180702_33_dialog_content = "Veja, as nuvens escuras sobre Crepúsculo foram dissipadas por Lady Saintess, deixando os Eclipsitas sem ter para onde fugir!",
  ui_story_1018_10180702_34_dialog_content = "Gratidão a você, Sua Santidade!",
  ui_story_1018_10180702_35_dialog_content = "De nada, e não é necessário me chamar de Senhora Santista.",
  ui_story_1018_10180702_36_dialog_content = "Santidade, há um favor que peço humildemente: meu filho ainda está lutando em Crepúsculo...",
  ui_story_1018_10180702_37_dialog_content = "Sua Santidade, imploro que me ouça—",
  ui_story_1018_10180702_38_dialog_content = "Sua Santidade...",
  ui_story_1018_10180702_39_dialog_content = "Pessoal, por favor, me chamem de Hilda.",
  ui_story_1018_10180702_40_dialog_content = "Ouvi todas as suas preces...",
  ui_story_1018_10180702_41_dialog_content = "Sua Santidade, por favor, não nos abandone novamente...",
  ui_story_1018_10180702_42_dialog_content = "...",
  ui_story_1018_10180702_43_dialog_content = "Não precisa responder a todos, Sua Santidade.",
  ui_story_1018_10180702_44_dialog_content = "Mas essa é a minha primeira vez encontrando Aurorians fora do Templo...",
  ui_story_1018_10180702_45_dialog_content = "Você não precisa responder.",
  ui_story_1018_10180702_46_dialog_content = "Tá bom.",
  ui_story_1018_10180702_47_dialog_content = "A Senhora Santa recebeu todos os seus cumprimentos.",
  ui_story_1018_10180702_48_dialog_content = "Obrigado, Carleen. Eu estou realmente muito feliz!",
  ui_story_1018_10180702_49_dialog_content = "Hmm, quem é você? Por que está me encarando...?",
  ui_story_1018_10180702_50_dialog_content = "Qual é o lance com o chifre na sua cabeça?",
  ui_story_1018_10180702_51_dialog_content = "Cuide das suas maneiras—",
  ui_story_1018_10180702_52_dialog_content = "Está bem!",
  ui_story_1018_10180702_53_dialog_content = "Na verdade, é uma história relacionada a <color=#FFB400>rinocórnios</color>...",
  ui_story_1018_10180702_54_dialog_content = "Você está falando sobre a lenda do Guardião Rinoceronte, certo? Eu ouço essa história desde que eu era criança. Aqui está como a história se desenrola...",
  ui_story_1018_10180702_55_dialog_content = "<color=#e8d9bb>Depois que Joselyne cuidou dos feridos...</color>",
  ui_story_1018_10180702_56_dialog_content = "Saudações, Senhora Santa! Eu, Joselyne, peço desculpas pelo meu atraso.",
  ui_story_1018_10180702_57_dialog_content = "Olá, Joselyne. O Padre Joseph mencionou você para mim e estou feliz em ajudar.",
  ui_story_1018_10180702_58_dialog_content = "Sinto vergonha por não conseguir salvar os Aurorians feridos pelos Eclipsitas e sou grato por você curá-los com sua aura.",
  ui_story_1018_10180702_59_dialog_content = "Não se sinta envergonhado. Você fez tudo o que pôde para resgatá-los, sendo a pessoa bondosa que você é.",
  ui_story_1018_10180702_60_dialog_content = "Se não se importar, por favor, apenas me chame de Hilda. Esse é o meu nome e eu tenho muitas coisas que gostaria de perguntar a você!",
  ui_story_1018_10180702_61_dialog_content = "Como posso me dirigir a você pelo nome? Afinal, você é a Senhora Santa!",
  ui_story_1018_10180702_62_dialog_content = "Joselyne, acho Lady Saintess tão calorosa e gentil quanto as irmãs aqui em Crepúsculo.",
  ui_story_1018_10180702_63_dialog_content = "Ah, e eu não consegui terminar a história, Chi! No final...",
  ui_story_1018_10180702_64_dialog_content = "...",
  ui_story_1018_10180702_65_dialog_content = "O que você está pensando, Senhora Joselyne?",
  ui_story_1018_10180702_66_dialog_content = "Senhora Carleen, eu simplesmente nunca imaginei que...",
  ui_story_1018_10180702_67_dialog_content = "A Senhora Santa realmente tinha um ar de inocência infantil.",
  ui_story_1018_10180702_68_dialog_content = "Pra falar a verdade, na primeira vez que a conheci, também fiquei surpreso com a... ingenuidade dela.",
  ui_story_1018_10180702_69_dialog_content = "Mas você viu como ela se aproximou naturalmente de garotas da idade de Chi e como estava curiosa sobre as histórias que circulavam em Crepúsculo.",
  ui_story_1018_10180702_70_dialog_content = "Talvez ela ainda esteja encontrando seus caminhos além de ser a Senhora Santa.",
  ui_story_1018_10180702_71_dialog_content = "Você está certo, estou sendo de mente fechada.",
  ui_story_1018_10180702_72_dialog_content = "Não pretende ficar depois de entregar os feridos à Igreja?",
  ui_story_1018_10180702_73_dialog_content = "A batalha em Crepúsculo ainda não acabou. Devo retornar e lutar ao lado dos guerreiros.",
  ui_story_1018_10180702_74_dialog_content = "Fico tranquilo sabendo que o Padre Joseph está aqui.",
  ui_story_1018_10180702_75_dialog_content = "Tudo bem, vou liderar o reforço de Lumópolis e ir com você.",
  ui_story_1018_10180702_76_dialog_content = "Também vou! Ainda podemos conseguir, né?",
  ui_story_1018_10180702_77_dialog_content = "Sim, Sua Santidade.",
  ui_story_1018_10180702_78_dialog_content = "Com a Senhora Santa conosco, Crepúsculo certamente será salvo. Vamos!",
  ui_story_1018_10180801_1_dialog_content = "<color=#e8d9bb>Fora do Crepúsculo</color>",
  ui_story_1018_10180801_2_dialog_content = "(Falando em Eclipsiano) Meu senhor, não entendo muito bem por que escolheria curá-la.",
  ui_story_1018_10180801_3_dialog_content = "(Eclipsiano) Ela deveria se juntar a nós, assim como aqueles soldados.",
  ui_story_1018_10180801_4_dialog_content = "Ela sobreviveu após ser levada ao limite. Estou chocado com o resultado deste experimento em particular.",
  ui_story_1018_10180801_5_dialog_content = "Se eu conseguir descobrir por que a semente dentro dela é tão especial, essa viagem não será em vão.",
  ui_story_1018_10180801_6_dialog_content = "(Eclipsiano) Meu senhor, faz séculos que não dou uma boa rangida nos meus dentes.",
  ui_story_1018_10180801_7_dialog_content = "Mudbundle está quase totalmente recuperado. Prepare-se para colocar mais tapete.",
  ui_story_1018_10180801_8_dialog_content = "(Em Eclipsiano) Devemos continuar avançando?",
  ui_story_1018_10180801_9_dialog_content = "Isso mesmo, mas desta vez, contorne o Crepúsculo.",
  ui_story_1018_10180801_10_dialog_content = "Vamos transformar todos os soldados de Ulysses em Eclipsitas assim que inundarmos Illumina.",
  ui_story_1018_10180801_11_dialog_content = "(Eclipsiano) Qual é o plano para esses soldados, meu senhor?",
  ui_story_1018_10180801_12_dialog_content = "Peça ao Mudbundle para realocá-los na linha defensiva e não se esqueça daquela \"obra de arte\".",
  ui_story_1018_10180801_13_dialog_content = "Mas antes de partir, quero ver se ela gosta do presente que tenho para ela.",
  ui_story_1018_10180801_14_dialog_content = "Capitão Axelia, Grande Marechal! Encontramos o Nono Esquadrão...",
  ui_story_1018_10180801_15_dialog_content = "Eles estavam... na verdade, deitados na lama perto da barreira o tempo todo.",
  ui_story_1018_10180801_16_dialog_content = "Conseguimos avistá-los assim que o lamaçal recuou... mas eles já...",
  ui_story_1018_10180801_17_dialog_content = "...",
  ui_story_1018_10180801_18_dialog_content = "Leve-me lá.",
  ui_story_1018_10180801_19_dialog_content = "Exceto pela equipe do tanque, todos os soldados do Nono Esquadrão estão aqui.",
  ui_story_1018_10180801_20_dialog_content = "O resto deles fez o sacrifício supremo, incluindo... o motorista do Engine VII.",
  ui_story_1018_10180801_21_dialog_content = "Por que o soldado morreu assim...",
  ui_story_1018_10180801_22_dialog_content = "Há uma ferida de tiro embaixo do queixo dele e o dedo ainda está firmemente no gatilho. Obviamente, ele tirou a própria vida antes de perder o controle...",
  ui_story_1018_10180801_23_dialog_content = "...",
  ui_story_1018_10180801_24_dialog_content = "Estes são apenas soldados comuns, certo?",
  ui_story_1018_10180801_25_dialog_content = "Sim, eles estavam...",
  ui_story_1018_10180801_26_dialog_content = "Eles estavam se apoiando um no outro, provavelmente tentando resistir ao atoleiro?",
  ui_story_1018_10180801_27_dialog_content = "Isso é brutal... Quase não há carne sobrando, principalmente apenas ossos...",
  ui_story_1018_10180801_28_dialog_content = "Sacrificando-se assim... Eles são muito valentes.",
  ui_story_1018_10180801_29_dialog_content = "Peço desculpas pelos julgamentos precipitados que fiz.",
  ui_story_1018_10180801_30_dialog_content = "...",
  ui_story_1018_10180801_31_dialog_content = "Wrath...",
  ui_story_1018_10180801_32_dialog_content = "Isso é algo que nunca vi em meus anos de guarnição.",
  ui_story_1018_10180801_33_dialog_content = "Há algo que possamos fazer?",
  ui_story_1018_10180801_34_dialog_content = "Continue verificando o perímetro e encontre todos os feridos.",
  ui_story_1018_10180801_35_dialog_content = "<color=#e8d9bb>Borbulha, borbulha...</color>",
  ui_story_1018_10180801_36_dialog_content = "Capitão! Há algo se mexendo no lamaçal atrás dos soldados!",
  ui_story_1018_10180801_37_dialog_content = "Então, essa é a principal atração de Crepúsculo?",
  ui_story_1018_10180801_38_dialog_content = "Acontece que é essa verdadeira \"obra de arte.\"",
  ui_story_1018_10180801_39_dialog_content = "Forsakin?",
  ui_story_1018_10180801_40_dialog_content = "Você é o responsável por tudo isso?",
  ui_story_1018_10180801_41_dialog_content = "Estou aqui apenas para cumprimentar o Grande Marechal. Você está se divertindo lutando?",
  ui_story_1018_10180801_42_dialog_content = "Por... sakin...!",
  ui_story_1018_10180801_43_dialog_content = "Relaxe. Você não pode estar falando sério nessa condição.",
  ui_story_1018_10180801_44_dialog_content = "Você não vai prejudicar o Grande Marechal Wrath!",
  ui_story_1018_10180801_45_dialog_content = "Você de novo? Vejo que não deveria ter pegado leve com você, seu tolo.",
  ui_story_1018_10180801_46_dialog_content = "Vou fazer você pagar em dobro pelo que fez aos meus soldados!",
  ui_story_1018_10180801_47_dialog_content = "O que eu fiz? Não seria suficiente para compensar minhas perdas se eu matasse todos eles.",
  ui_story_1018_10180801_48_dialog_content = "Você provavelmente não faz ideia de como conseguiu chegar até este momento. O que a Illumina fez com você poderia te matar mil vezes.",
  ui_story_1018_10180801_49_dialog_content = "Não quer saber por que você tem lutado tanto e, mesmo assim, Illumina não se importou nem um pouco?",
  ui_story_1018_10180801_50_dialog_content = "Cala a boca, sua bruxa sem honra!",
  ui_story_1018_10180801_51_dialog_content = "Hmm, acho que você tem alguma noção, afinal. Eles sabem que matar seus próprios soldados é o motivo da nova Grande Marechal?",
  ui_story_1018_10180801_52_dialog_content = "Você está pedindo, Forsakin!",
  ui_story_1018_10180801_53_dialog_content = "Acalme-se, Wrath! Ela está tentando te irritar de propósito.",
  ui_story_1018_10180801_54_dialog_content = "...",
  ui_story_1018_10180801_55_dialog_content = "Eu sabia que você estava por trás de tudo que aconteceu em Crepúsculo, e não vou deixar você escapar!",
  ui_story_1018_10180801_56_dialog_content = "Eu não nego isso e estou feliz em fazer isso para punir um roubo.",
  ui_story_1018_10180801_57_dialog_content = "Já que todos viram a obra de arte, vamos passar para o verdadeiro show. Fiquem atentos agora!",
  ui_story_1018_10180801_58_dialog_content = "O que está fazendo?",
  ui_story_1018_10180801_59_dialog_content = "Hmm, você está me desafiando ao se interpor na frente dela?",
  ui_story_1018_10180801_60_dialog_content = "E Axelia também.",
  ui_story_1018_10180801_61_dialog_content = "Sim, conte comigo!",
  ui_story_1018_10180801_62_dialog_content = "Tanto faz. Já me diverti. Não sou eu com quem você está lutando...",
  ui_story_1018_10180801_63_dialog_content = "Rugido...",
  ui_story_1018_10180801_64_dialog_content = "Essa é a voz do piloto do mecha... Mas ele não está morto?",
  ui_story_1018_10180801_65_dialog_content = "Rugido...",
  ui_story_1018_10180801_66_dialog_content = "Vocês já se sacrificaram uma vez...",
  ui_story_1018_10180801_67_dialog_content = "Não posso deixar você...",
  ui_story_1018_10180801_68_dialog_content = "Axelia sentiu sua raiva, Grande Marechal...",
  ui_story_1018_10180801_69_dialog_content = "O que é isto...",
  ui_story_1018_10180801_70_dialog_content = "Axelia quer proteger o Grande Marechal e, mesmo que Axelia não possa sentir o calor de um corpo...",
  ui_story_1018_10180801_71_dialog_content = "Yingel me disse que é aqui onde o coração de Axelia está.",
  ui_story_1018_10180801_72_dialog_content = "Acho que está mais quente do que aquela força dentro de nós.",
  ui_story_1018_10180801_73_dialog_content = "Axelia...",
  ui_story_1018_10180801_74_dialog_content = "Não se preocupe, eu não vou deixar isso me controlar.",
  ui_story_1018_10180801_75_dialog_content = "Capitão... o esquadrão inteiro está vindo em nossa direção! O que fazemos agora?",
  ui_story_1018_10180801_76_dialog_content = "O lodo... não, o Darkflow, está saindo de seus corpos! Eu posso ver isso! Há um brilho sinistro nos olhos dos soldados!",
  ui_story_1018_10180801_77_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_1018_10180801_78_dialog_content = "Lança relâmpago, perfure!",
  ui_story_1018_10180801_79_dialog_content = "Seus espíritos já partiram há muito tempo. Apenas mancharia seu legado se continuassem lutando.",
  ui_story_1018_10180801_80_dialog_content = "Todos, ouçam! Não permitam que nossos soldados sofram mais. Eles nos protegeram e não deveriam ter se sacrificado em vão!",
  ui_story_1018_10180801_81_dialog_content = "Sim, Grande Marechal.",
  ui_story_1018_10180801_82_dialog_content = "Aí está, sem piedade. Então você não vai se importar se eu levar o resto comigo...",
  ui_story_1018_10180801_83_dialog_content = "Não tente correr!",
  ui_story_1018_10180801_84_dialog_content = "Os soldados não estão entrando na lama...",
  ui_story_1018_10180801_85_dialog_content = "Eles são subordinados de Axelia.",
  ui_story_1018_10180801_86_dialog_content = "Axelia liderará o Esquadrão Oito!",
  ui_story_1018_10180801_87_dialog_content = "Axelia vai ficar bem, né...?",
  ui_story_1018_10180801_88_dialog_content = "Os soldados que avançam com ela têm sido leais, então não deve ser um problema.",
  ui_story_1018_10180801_89_dialog_content = "Vamos nos atualizar depois de terminarmos aqui!",
  ui_story_1018_10180801_90_dialog_content = "Claro!",
  ui_story_1018_10180802_1_dialog_content = "Ainda me perseguindo nesse estado?",
  ui_story_1018_10180802_2_dialog_content = "Axelia... preciso protegê-los... por favor, devolva-os para mim.",
  ui_story_1018_10180802_3_dialog_content = "Então, acho que você vai ter que me matar de alguma forma.",
  ui_story_1018_10180802_4_dialog_content = "Axelia... trará o Esquadrão Oito de volta para casa!",
  ui_story_1018_10180802_5_dialog_content = "É assim que uma matança deve ser!",
  ui_story_1018_10180802_6_dialog_content = "Não...",
  ui_story_1018_10180802_7_dialog_content = "Capitão Axelia, você está... bem?",
  ui_story_1018_10180802_8_dialog_content = "...",
  ui_story_1018_10180802_9_dialog_content = "É tristeza que vejo no rosto da criação sem emoção de Ulysses?",
  ui_story_1018_10180802_10_dialog_content = "Axelia... não é insensível às emoções.",
  ui_story_1018_10180802_11_dialog_content = "Ainda não vai admitir?",
  ui_story_1018_10180802_12_dialog_content = "Não os machuque... Eles estão em agonia...",
  ui_story_1018_10180802_13_dialog_content = "Eles parecem que conseguem ouvir suas palavras?",
  ui_story_1018_10180802_14_dialog_content = "Axelia não vai deixar você escapar com isso...",
  ui_story_1018_10180802_15_dialog_content = "Além de me ver espremer a vida deles, o que mais você pode fazer?",
  ui_story_1018_10180802_16_dialog_content = "(Eclipsian) Meu senhor, Mudbundle está pronto e em espera.",
  ui_story_1018_10180802_17_dialog_content = "Muito bem então, já que está implorando, vou deixar alguns para você. O resto, no entanto...",
  ui_story_1018_10180802_18_dialog_content = "Capitão Axelia, todos... eles desapareceram no pântano...",
  ui_story_1018_10180802_19_dialog_content = "Devolva-os... para mim...",
  ui_story_1018_10180802_20_dialog_content = "Ah!",
  ui_story_1018_10180802_21_dialog_content = "Capitão Axelia, cuidado!",
  ui_story_1018_10180802_22_dialog_content = "Ah!",
  ui_story_1018_10180802_23_dialog_content = "Pare com isso...",
  ui_story_1018_10180802_24_dialog_content = "Socorro! Capitão Axelia!",
  ui_story_1018_10180802_25_dialog_content = "Ah!",
  ui_story_1018_10180802_26_dialog_content = "Aff...",
  ui_story_1018_10180802_27_dialog_content = "Você não são máquinas de guerra... Por favor, não os mate...",
  ui_story_1018_10180802_28_dialog_content = "Ah!",
  ui_story_1018_10180802_29_dialog_content = "Ahrrrgggh—!",
  ui_story_1018_10180802_30_dialog_content = "...",
  ui_story_1018_10180802_31_dialog_content = "(Seu grito... o vento, os barulhos das armas... Tudo quieto agora...)",
  ui_story_1018_10180802_32_dialog_content = "(Ele está... morto?)",
  ui_story_1018_10180802_33_dialog_content = "(Ou talvez... Axelia esteja morto...)",
  ui_story_1018_10180802_34_dialog_content = "(...)",
  ui_story_1018_10180802_35_dialog_content = "Capitão Axelia, salve-me!",
  ui_story_1018_10180802_36_dialog_content = "(Eu me sinto tão pesado... não consigo me mexer...)",
  ui_story_1018_10180802_37_dialog_content = "(Rápido... preciso salvá-lo!)",
  ui_story_1018_10180802_38_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_1018_10180802_39_dialog_content = "(Seu corpo é jogado com força no chão...)",
  ui_story_1018_10180802_40_dialog_content = "(Parece que o corpo de Axelia foi jogado ao chão...)",
  ui_story_1018_10180802_41_dialog_content = "<color=#e8d9bb>Roooaaarrr!!!</color>",
  ui_story_1018_10180802_42_dialog_content = "(Ele rasgou o peito do soldado e começou a se banquetear...)",
  ui_story_1018_10180802_43_dialog_content = "(O soldado caiu em uma poça do próprio sangue...)",
  ui_story_1018_10180802_44_dialog_content = "(Mas Axelia parece que... sou eu mesma que caí lá...)",
  ui_story_1018_10180802_45_dialog_content = "<color=#e8d9bb>Clam! Clam!</color>",
  ui_story_1018_10180802_46_dialog_content = "(Cinco vezes, seis vezes...)",
  ui_story_1018_10180802_47_dialog_content = "(Axelia caiu seis vezes...)",
  ui_story_1018_10180802_48_dialog_content = "(Décima vez...)",
  ui_story_1018_10180802_49_dialog_content = "(Vigésima terceira vez, vigésima quarta vez...)",
  ui_story_1018_10180802_50_dialog_content = "(Cento e duas vezes...)",
  ui_story_1018_10180802_51_dialog_content = "(Duas mil vezes...)",
  ui_story_1018_10180802_52_dialog_content = "(...)",
  ui_story_1018_10180802_53_dialog_content = "Onze mil, cento e onze vezes...",
  ui_story_1018_10180802_54_dialog_content = "(Axelia ainda está perdendo...)",
  ui_story_1018_10180802_55_dialog_content = "(Pai disse que Axelia é uma excelente máquina de guerra, e máquinas de guerra nunca cedem.)",
  ui_story_1018_10180802_56_dialog_content = "(Mas Axelia continua sendo derrotado...)",
  ui_story_1018_10180802_57_dialog_content = "(Axelia não tem ideia de como parar isso de jeito nenhum.)",
  ui_story_1018_10180802_58_dialog_content = "Axélia!",
  ui_story_1018_10180802_59_dialog_content = "(Pai? Por favor, perdoe Axelia...)",
  ui_story_1018_10180802_60_dialog_content = "Lembre-se, Axelia, você deve viver como uma pessoa!",
  ui_story_1018_10180802_61_dialog_content = "(Viver... Mas o que Axelia pode fazer...?)",
  ui_story_1018_10180802_62_dialog_content = "(Talvez Axelia possa...)",
  ui_story_1018_10180802_63_dialog_content = "Rugido...",
  ui_story_1018_10180802_64_dialog_content = "Ah!",
  ui_story_1018_10180802_65_dialog_content = "Trovão estrondoso!",
  ui_story_1018_10180802_66_dialog_content = "Acorde, Axelia! Ouça minha voz!",
  ui_story_1018_10180802_67_dialog_content = "Você não pode avançar mais, Wrath!",
  ui_story_1018_10180802_68_dialog_content = "Rugido...",
  ui_story_1018_10180802_69_dialog_content = "Até mesmo Axelia vai...",
  ui_story_1018_10180802_70_dialog_content = "<color=#e8d9bb>Olá—</color>",
  ui_story_1018_10180802_71_dialog_content = "Aquele som...",
  ui_story_1018_10180802_72_dialog_content = "Essa luz é tão brilhante...",
  ui_story_1018_10180802_73_dialog_content = "Grande Marechal, Leo, desculpe pelo atraso!",
  ui_story_1018_10180802_74_dialog_content = "Eu, Joselyne, na Aura da Senhora Santa, irei redimir os Aurorianos de volta às graças de Deus!",
  ui_story_1018_10180802_75_dialog_content = "Os sinistros Eclipsitas nunca mais vão te machucar!",
  ui_story_1018_10180802_76_dialog_content = "Capitão! É o Joselyne! E... Senhora Carleen e os Skyriders de Lumópolis!",
  ui_story_1018_10180802_77_dialog_content = "Aquela garota parada na luz é quem eu acho que é...?",
  ui_story_1018_10180802_78_dialog_content = "Eu ouvi, mas ainda não é hora de eles voltarem.",
  ui_story_1018_10180802_79_dialog_content = "Todas as vidas são preciosas. Você será purificado do mal pelas graças de Deus.",
  ui_story_1018_10180802_80_dialog_content = "Banho na luz sagrada, ouça as orações e receba a bênção divina.",
  ui_story_1018_10180802_81_dialog_content = "Deixe o poder fluir para curar feridas e erradicar pensamentos malignos.",
  ui_story_1018_10180802_82_dialog_content = "May o eterno Deus da Luz esteja sempre com os Aurorianos.",
  ui_story_1018_10180802_83_dialog_content = "Capitão, olhe os soldados! Eles estão brilhando com uma luz dourada!",
  ui_story_1018_10180802_84_dialog_content = "Sim, Joselyne conseguiu trazer a Senhora Santa consigo...",
  ui_story_1018_10180802_85_dialog_content = "Ela está curando aqueles soldados corrompidos?",
  ui_story_1018_10180802_86_dialog_content = "Sim. Supostamente, ela não só poderia quebrar o domínio do Darkflow, mas até mesmo a simples visão da aura sagrada poderia curar os aurorianos comuns.",
  ui_story_1018_10180802_87_dialog_content = "De fato...",
  ui_story_1018_10180802_88_dialog_content = "Sinto que uma certa força em meu corpo está se dispersando para trazer muito alívio...",
  ui_story_1018_10180802_89_dialog_content = "E também, os soldados que se transformaram em Eclipsitas cessaram seus ataques...",
  ui_story_1018_10180802_90_dialog_content = "Sinto a sua dor. Você só precisa se recuperar em paz por agora.",
  ui_story_1018_10180802_91_dialog_content = "Avante, Noite Branca!",
  ui_story_1018_10180802_92_dialog_content = "Desculpe, estamos atrasados!",
  ui_story_1018_10180802_93_dialog_content = "Olá...",
  ui_story_1018_10180802_94_dialog_content = "A todos, esta é a Senhora Santa do Templo de Lumópolis.",
  ui_story_1018_10180802_95_dialog_content = "Templo de Lumópolis? O que está acontecendo aqui?",
  ui_story_1018_10180802_96_dialog_content = "Grande Marechal Wrath, a Senhora Santa está aqui para ajudar a curar os soldados feridos.",
  ui_story_1018_10180802_97_dialog_content = "Aqueles que me seguiram até a Fortaleza Lumo estão estáveis agora, graças a ela.",
  ui_story_1018_10180802_98_dialog_content = "A Senhora Santa possui poder divino...?",
  ui_story_1018_10180802_99_dialog_content = "Não. Eu sou um Aurorian, não diferente de você, Grande Marechal.",
  ui_story_1018_10180802_100_dialog_content = "Mas como é que eu simplesmente não acho...",
  ui_story_1018_10180802_101_dialog_content = "Fiquei angustiado ao saber o que aconteceu com você e seus soldados, então os tratei sem o seu consentimento. Espero que possa me perdoar.",
  ui_story_1018_10180802_102_dialog_content = "Não, sou eu quem deveria agradecer a você.",
  ui_story_1018_10180802_103_dialog_content = "Por que você veio, posso perguntar?",
  ui_story_1018_10180802_104_dialog_content = "Tenho escutado os murmúrios dos Aurorianos em seus pesadelos. Posso sentir a dor e a angústia.",
  ui_story_1018_10180802_105_dialog_content = "Você também foi incomodado por isso e eu te ouvi.",
  ui_story_1018_10180802_106_dialog_content = "...",
  ui_story_1018_10180802_107_dialog_content = "Oh, desculpe, agora não é hora para eu ficar falando demais.",
  ui_story_1018_10180802_108_dialog_content = "Por favor, verifique seus soldados, Grande Marechal. Eles devem estar fora de perigo agora.",
  ui_story_1018_10180802_109_dialog_content = "Sim. Novamente, muito obrigado.",
  ui_story_1018_10180802_110_dialog_content = "A Senhora Santa realmente é algo extraordinário...",
  ui_story_1018_10180802_111_dialog_content = "Ouvi isso.",
  ui_story_1018_10180802_112_dialog_content = "O que? Mas isso foi quase um sussurro!",
  ui_story_1018_10180802_113_dialog_content = "Você não é como os outros.",
  ui_story_1018_10180802_114_dialog_content = "Esta é a Celestita, Senhora Santa.",
  ui_story_1018_10180802_115_dialog_content = "Saudações, Senhora Santa. Eu sou PlayerName.",
  ui_story_1018_10180802_116_dialog_content = "Como vai, PlayerName. Por favor, apenas me chame de Hilda.",
  ui_story_1018_10180802_117_dialog_content = "Hilda...",
  ui_story_1018_10180802_118_dialog_content = "Já li um livro de histórias antes e o personagem principal também se chamava Hilda.",
  ui_story_1018_10180802_119_dialog_content = "Sério? Como é esse Hilda?",
  ui_story_1018_10180802_120_dialog_content = "Bem, Hilda é na verdade um animal...",
  ui_story_1018_10180802_121_dialog_content = "Como ousa chamar a Senhora Santíssima...!",
  ui_story_1018_10180802_122_dialog_content = "Não, eu me refiro àquela do livro! Que Hilda gosta de cultivar flores...",
  ui_story_1018_10180802_123_dialog_content = "Hee... Um animal que gosta de cultivar flores? É um pouco moe ou uma pequena raposa?",
  ui_story_1018_10180802_124_dialog_content = "Tem chifres? Asas? Será que visitou muitos lugares...?",
  ui_story_1018_10180802_125_dialog_content = "Capitão, ela é a \"Santa\" da Igreja de Lumópolis?",
  ui_story_1018_10180802_126_dialog_content = "Sim.",
  ui_story_1018_10180901_1_dialog_content = "<color=#e8d9bb>Cidade de Gannon</color>",
  ui_story_1018_10180901_2_dialog_content = "Bem... que tal apresentarmos as notícias assim:",
  ui_story_1018_10180901_3_dialog_content = "Devido aos relatórios de batalha desfavoráveis vindos de Crepúsculo, as famílias dos soldados que em breve serão implantados estão lutando com a separação iminente...",
  ui_story_1018_10180901_4_dialog_content = "Ei, que tal usar um tom um pouco mais otimista? Não queremos parecer que estamos perdendo a guerra...",
  ui_story_1018_10180901_5_dialog_content = "Não é essa a verdade? Twilight nunca enviou boas notícias. Se as coisas continuarem assim, ficaremos sem notícias para relatar...",
  ui_story_1018_10180901_6_dialog_content = "General Hiiro, como é que desta vez não estamos reforçando Crepúsculo, mas sim a linha de defesa?",
  ui_story_1018_10180901_7_dialog_content = "Porque essa é a ordem que nos foi dada.",
  ui_story_1018_10180901_8_dialog_content = "Mas a batalha em Crepúsculo é muito incerta...",
  ui_story_1018_10180901_9_dialog_content = "Canalize suas preocupações para o impulso de resolver a crise iminente.",
  ui_story_1018_10180901_10_dialog_content = "Sim...",
  ui_story_1018_10180901_11_dialog_content = "General, as tropas estão prontas.",
  ui_story_1018_10180901_12_dialog_content = "E as armas enviadas pelo chefe de gabinete?",
  ui_story_1018_10180901_13_dialog_content = "Em posição!",
  ui_story_1018_10180901_14_dialog_content = "Vamos.",
  ui_story_1018_10180901_15_dialog_content = "Sim!",
  ui_story_1018_10180901_16_dialog_content = "A 3ª Legião partiu! Temos fé que a batalha em Crepúsculo pode tomar um rumo positivo—",
  ui_story_1018_10180901_17_dialog_content = "Hum? O comunicador parece estar captando um sinal estranho?",
  ui_story_1018_10180901_18_dialog_content = "Eu também percebi!",
  ui_story_1018_10180901_19_dialog_content = "É uma brincadeira ou...? Vamos ver se conseguimos deixar isso mais claro...",
  ui_story_1018_10180901_20_dialog_content = "O Programa Phospherus é um plano criado por Ulysses e pelo Forsakin do Eclipse...",
  ui_story_1018_10180901_21_dialog_content = "O que é isso...",
  ui_story_1018_10180901_22_dialog_content = "Você é quem enviou o sinal, certo?",
  ui_story_1018_10180901_23_dialog_content = "Por que diz isso?",
  ui_story_1018_10180901_24_dialog_content = "Permita-me elaborar.",
  ui_story_1018_10180901_25_dialog_content = "Você começou como informante de Esien, colocado ao lado da Grande Marechal para observar cada movimento dela.",
  ui_story_1018_10180901_26_dialog_content = "Então, você foi forçado a ajudar Ulysses a realizar uma operação de \"falsa bandeira\" no exercício conjunto.",
  ui_story_1018_10180901_27_dialog_content = "Em seguida, no julgamento de Reinhardt, você finalmente percebeu que era apenas um peão em uma luta política...",
  ui_story_1018_10180901_28_dialog_content = "Então você se redimiu fechando os olhos para o que fizemos e até nos ajudou em segredo.",
  ui_story_1018_10180901_29_dialog_content = "Eu só não esperava que um oficial de inteligência soubesse tanto sobre comunicações. Seu superior está bem com isso?",
  ui_story_1018_10180901_30_dialog_content = "Oficiais de inteligência coletam informações e também as vazam no momento certo. Estou fazendo isso puramente por conta própria. Não tem nada a ver com mais ninguém.",
  ui_story_1018_10180901_31_dialog_content = "Vejo que você está sério.",
  ui_story_1018_10180901_32_dialog_content = "Fazer o que você prega é como eu julgo as pessoas. Sua inteligência é precisa e sua atitude é firme.",
  ui_story_1018_10180901_33_dialog_content = "Isso significa que agora eu acredito em tudo que você me disse na prisão.",
  ui_story_1018_10180901_34_dialog_content = "<color=#e8d9bb>Não muito tempo atrás, Vivian fez sua terceira visita à Prisão de Illumina...</color>",
  ui_story_1018_10180901_35_dialog_content = "O fato de termos entrado na prisão de alta segurança significa que a inteligência de Anatoli é impecável.",
  ui_story_1018_10180901_36_dialog_content = "Oficial Vivian, dada a gravidade desta operação, por que você confiaria nas informações de um cara conhecido por perjúrio?",
  ui_story_1018_10180901_37_dialog_content = "Intuição.",
  ui_story_1018_10180901_38_dialog_content = "Wrath pensou que Anatoli tinha um motivo desconhecido para cometer perjúrio, e a maneira como ele continuava a interferir em nosso objetivo me diz que ele está hesitante.",
  ui_story_1018_10180901_39_dialog_content = "Ele deve ter tomado a decisão de nos ajudar desta vez.",
  ui_story_1018_10180901_40_dialog_content = "Bem... esses guardas de patrulha que surgiram do nada são a chamada \"mão amiga\"?",
  ui_story_1018_10180901_41_dialog_content = "...",
  ui_story_1018_10180901_42_dialog_content = "Chefe de Gabinete Vivian, qualquer pessoa que tente entrar nesta prisão de alta segurança deve apresentar as credenciais relevantes.",
  ui_story_1018_10180901_43_dialog_content = "Vá verificar com seus superiores sobre isso. Eu não recebi nada do meu chefe.",
  ui_story_1018_10180901_44_dialog_content = "Seu superior imediato, Reinhardt, está atualmente encarcerado dentro destas paredes. Aconselho você e sua equipe a pensar duas vezes antes de prosseguir.",
  ui_story_1018_10180901_45_dialog_content = "Chefe, parece que sua intuição sobre o oficial de inteligência não estava totalmente precisa.",
  ui_story_1018_10180901_46_dialog_content = "Ele seria o primeiro que eu entendi errado.",
  ui_story_1018_10180901_47_dialog_content = "Mas siga o plano. De qualquer forma, temos que libertar o Grande Marechal antes que Hiiro envie as tropas.",
  ui_story_1018_10180901_48_dialog_content = "Esta é a última chance para nós, então estejam preparados para lutar!",
  ui_story_1018_10180901_49_dialog_content = "Absolutamente! Para o Grande Marechal!",
  ui_story_1018_10180901_50_dialog_content = "Chefe de Gabinete, você está planejando invadir? Nesse caso, nós...",
  ui_story_1018_10180901_51_dialog_content = "Ai, ai, ai...",
  ui_story_1018_10180901_52_dialog_content = "... Nós nem sequer tocamos em você.",
  ui_story_1018_10180901_53_dialog_content = "Eu cuido disso.",
  ui_story_1018_10180901_54_dialog_content = "Sim, oficial!",
  ui_story_1018_10180901_55_dialog_content = "... Anatoli, o que está acontecendo? Você nos enganou, não foi!",
  ui_story_1018_10180901_56_dialog_content = "Desculpe, preciso remover minhas dúvidas dessa maneira.",
  ui_story_1018_10180901_57_dialog_content = "Qual dúvida?",
  ui_story_1018_10180901_58_dialog_content = "Qual caminho você escolheu em relação ao futuro da Illumina e até onde está disposto a ir?",
  ui_story_1018_10180901_59_dialog_content = "Qual é a sua conclusão?",
  ui_story_1018_10180901_60_dialog_content = "Após minha longa observação, o Grande Marechal é um líder confiável.",
  ui_story_1018_10180901_61_dialog_content = "Como oficial de inteligência, é um instinto básico duvidar de tudo, e é por isso que eu odeio a fé cega.",
  ui_story_1018_10180901_62_dialog_content = "Mas já ganhei a confiança incondicional de alguém uma vez e vejo isso novamente em você.",
  ui_story_1018_10180901_63_dialog_content = "Este é o futuro que eu anseio, então escolho ficar ao seu lado.",
  ui_story_1018_10180901_64_dialog_content = "Heh, perdoe-me por não confiar em alguém que traiu o marechal, mesmo que eu tenha gostado muito do seu discurso.",
  ui_story_1018_10180901_65_dialog_content = "Haverá muitas oportunidades para você me conhecer melhor. Os patrulheiros trabalham para mim, então vocês devem seguir em frente.",
  ui_story_1018_10180901_66_dialog_content = "Bem-vindo ao time, intrépido companheiro!",
  ui_story_1018_10180901_67_dialog_content = "Vou pular as operações de alto perfil, obrigado. Estou acostumado a ficar nos bastidores.",
  ui_story_1018_10180901_68_dialog_content = "Se você tiver sucesso, tenho algumas fichas que podem ser úteis.",
  ui_story_1018_10180901_69_dialog_content = "Tudo bem, temos um acordo.",
  ui_story_1018_10180901_70_dialog_content = "<color=#e8d9bb>Zumbido... Zumbido...</color>",
  ui_story_1018_10180901_71_dialog_content = "Por que todos os dispositivos estão fazendo esse barulho?",
  ui_story_1018_10180901_72_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1018_10180901_73_dialog_content = "Isso é tão estranho... Será que o comunicador quebrou? O sinal ficou todo maluco de repente.",
  ui_story_1018_10180901_74_dialog_content = "Mesmo aqui...",
  ui_story_1018_10180901_75_dialog_content = "O que no mundo... está acontecendo?",
  ui_story_1018_10180901_76_dialog_content = "Parece que o Comitê fez um movimento...",
  ui_story_1018_10180901_77_dialog_content = "Chefe de Estado-Maior, perdemos contato com as unidades da linha de frente justamente quando ocorreu a falha de comunicação.",
  ui_story_1018_10180901_78_dialog_content = "Não acredito que eles se rebaixaram a esse nível...",
  ui_story_1018_10180901_79_dialog_content = "A Federação nunca cortou comunicações com qualquer força defensiva quando bloquearam sinais no passado.",
  ui_story_1018_10180901_80_dialog_content = "Estamos sem tempo. Cuidado com as costas, Anatoli.",
  ui_story_1018_10180901_81_dialog_content = "...",
  ui_story_1018_10180901_82_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1018_10180901_83_dialog_content = "Professor, a interrupção do canal foi resolvida. Você pode prosseguir com a reunião online agora.",
  ui_story_1018_10180901_84_dialog_content = "...",
  ui_story_1018_10180901_85_dialog_content = "Para reduzir riscos potenciais, tive que recorrer a este método.",
  ui_story_1018_10180901_86_dialog_content = "Continuaremos a investigar a fonte do sinal. A recuperação total ainda pode levar algum tempo.",
  ui_story_1018_10180901_87_dialog_content = "Parece que estamos nos aproximando do momento em que seu plano será exposto a todos os colegas da Illumina, doutor.",
  ui_story_1018_10180901_88_dialog_content = "Vou enviar o Esien para verificar imediatamente.",
  ui_story_1018_10180901_89_dialog_content = "O custo de criar uma distração é muito menor do que um confronto direto. Você deveria apenas se concentrar em corrigir as falhas em seus experimentos, Doutor.",
  ui_story_1018_10180901_90_dialog_content = "Então, você tem uma solução para a batalha em Crepúsculo?",
  ui_story_1018_10180901_91_dialog_content = "Sempre tenho uma solução, é apenas uma questão de escolher qual. Dependerá de como as coisas se desenrolarem.",
  ui_story_1018_10180901_92_dialog_content = "Vou corrigir os defeitos com o quarto lote de Sementes.",
  ui_story_1018_10180901_93_dialog_content = "Pela minha experiência, é sábio não esgotar a paciência em apenas uma coisa.",
  ui_story_1018_10180901_94_dialog_content = "Alguma boa notícia da Equipe de Reconhecimento da Zona Cega?",
  ui_story_1018_10180901_95_dialog_content = "A Equipe de Reconhecimento da Zona Cega transmitiu várias imagens de suspeitos <color=#FFB400>dispositivos réplica</color> semelhantes ao núcleo do Guardião Um.",
  ui_story_1018_10180901_96_dialog_content = "Com base em nossa avaliação preliminar, o roubo do núcleo do Guardian One por Eclipsian parece fazer parte dos preparativos para o projeto relacionado ao Engineer.",
  ui_story_1018_10180901_97_dialog_content = "...",
  ui_story_1018_10180901_98_dialog_content = "A Crise Darkover acabou há 10 anos. Veja o que fizemos desde então.",
  ui_story_1018_10180901_99_dialog_content = "Suas preocupações são infundadas, Máscara de Ferro.",
  ui_story_1018_10180901_100_dialog_content = "Estou familiarizado com o Guardian One. Levará algum tempo para que seu núcleo seja útil.",
  ui_story_1018_10180901_101_dialog_content = "A propósito, para acelerar a pesquisa sobre as Sementes, não participarei de nenhuma reunião daqui em diante. Adeus.",
  ui_story_1018_10180901_102_dialog_content = "Professor, aqui estão os resultados. Por favor, dê uma olhada.",
  ui_story_1018_10180901_103_dialog_content = "Por que os dados da última batalha estão tão ruins?",
  ui_story_1018_10180901_104_dialog_content = "Professor, há uma chamada do Comandante Belisaria...",
  ui_story_1018_10180901_105_dialog_content = "Conecte-o.",
  ui_story_1018_10180901_106_dialog_content = "Ainda quero lembrá-lo, doutor.",
  ui_story_1018_10180901_107_dialog_content = "Até aquela garota reclusa apareceu, então isso mostra o quanto estamos atrasados.",
  ui_story_1018_10180901_108_dialog_content = "A invasão descarada do Eclipse significa que a operação na Zona Escura está adiada... Se isso pode ser considerado uma boa notícia para você.",
  ui_story_1018_10180901_109_dialog_content = "O que você quer dizer?",
  ui_story_1018_10180901_110_dialog_content = "Você pode continuar experimentando, pena que o projeto não é mais minha prioridade principal.",
  ui_story_1018_10180901_111_dialog_content = "Cuide-se, doutor.",
  ui_story_1018_10180901_112_dialog_content = "...",
  ui_story_1018_10180901_113_dialog_content = "Professor... Devemos continuar com nosso experimento?",
  ui_story_1018_10180901_114_dialog_content = "Claro, isso não é nem de longe suficiente para nos parar!",
  ui_story_1018_10180901_115_dialog_content = "Há algo que precisamos melhorar? Passos, ambiente, avaliações?",
  ui_story_1018_10180901_116_dialog_content = "Professor... Eu acredito que esses não são problemas.",
  ui_story_1018_10180901_117_dialog_content = "Talvez possamos ajustar a abordagem da pesquisa...",
  ui_story_1018_10180901_118_dialog_content = "São exatamente os pensamentos dela!",
  ui_story_1018_10180901_119_dialog_content = "Tecnologia Illumina, Chord Link, Sementes... Me diga, o que pode ser modificado entre esses três?",
  ui_story_1018_10180901_120_dialog_content = "Professor, a taxa atual de iteração das Sementes até está boa, mas os efeitos de melhoria em cada versão são praticamente imperceptíveis...",
  ui_story_1018_10180901_121_dialog_content = "Vejo que fui muito conservador em relação à dosagem...",
  ui_story_1018_10180901_122_dialog_content = "O tempo está acabando. Aumente a dose extraída do próximo lote de Sementes!",
  ui_story_1018_10180901_123_dialog_content = "Diga ao Essen para fazer outra convocação e abrir uma exceção para os soldados que foram rejeitados para se juntarem novamente ao projeto.",
  ui_story_1018_10180901_124_dialog_content = "...",
  ui_story_1018_10180901_125_dialog_content = "Então o laboratório do Professor Ulysses é um lugar tão popular, entendi!",
  ui_story_1018_10180901_126_dialog_content = "Professor...",
  ui_story_1018_10180901_127_dialog_content = "O que vocês estão fazendo aqui?",
  ui_story_1018_10180901_128_dialog_content = "Relaxa. Acabei de receber uma ordem para emprestar minha equipe do laboratório ao médico por alguns dias.",
  ui_story_1018_10180901_129_dialog_content = "O Comitê?",
  ui_story_1018_10180901_130_dialog_content = "Você não recebeu o aviso? Ah, talvez o Coronel Yingel tenha esquecido de te contar.",
  ui_story_1018_10180901_131_dialog_content = "Sim, eu também recebi a ordem. Talvez eles esperem que possamos acelerar o projeto trabalhando juntos...",
  ui_story_1018_10180901_132_dialog_content = "Belisaria está apenas mandando pessoas para ficar de olho em mim...",
  ui_story_1018_10180901_133_dialog_content = "Tanto faz. Eu não vou desistir, de qualquer forma.",
  ui_story_1018_10180901_134_dialog_content = "Deixarei você cuidar da convocação então, Yingel. Meu assistente ao lado irá instruí-lo.",
  ui_story_1018_10180901_135_dialog_content = "Entendi...",
  ui_story_1018_10180901_136_dialog_content = "Oficial de Tecnologia Gronru, quanto os seus cientistas sabem sobre o Programa Phospherus?",
  ui_story_1018_10180901_137_dialog_content = "Ah, você pode perguntar a eles você mesmo. Todos estão ansiosos para aprender!",
  ui_story_1018_10180901_138_dialog_content = "Estou ouvindo atentamente as lições do Professor Ulysses.",
  ui_story_1018_10180901_139_dialog_content = "Aqui está você, Coronel Yingel. Você fez um bom espetáculo lá atrás. Acho que o Docente Ulysses não suspeitou de nada!",
  ui_story_1018_10180901_140_dialog_content = "Obrigado, senhorita Gronru, embora não fosse minha função fazer isso...",
  ui_story_1018_10180901_141_dialog_content = "Mas, desde que testemunhei pessoalmente o experimento dele, não pude mais fingir que nada aconteceu.",
  ui_story_1018_10180901_142_dialog_content = "Sempre que eu fechava os olhos, eu conseguia ver Axelia lutando contra os soldados na batalha...",
  ui_story_1018_10180901_143_dialog_content = "Relaxe, passarinho gentil! Você foi muito bem. Nós cuidaremos das coisas da batalha.",
  ui_story_1018_10180901_144_dialog_content = "Como assim?",
  ui_story_1018_10180901_145_dialog_content = "Todos na Illumina têm as mesmas preocupações que você, então, falando estritamente, é você quem está nos ajudando.",
  ui_story_1018_10180901_146_dialog_content = "É a minha vez de partir em seguida. Vou levar todos os feridos de volta para casa!",
  ui_story_1018_10180901_147_dialog_content = "Sério? O Comitê também autorizou isso?",
  ui_story_1018_10180901_148_dialog_content = "Isso é para você decidir, Coronel Yingel!",
  ui_story_1018_10180901_149_dialog_content = "...",
  ui_story_1018_10180901_150_dialog_content = "Senhorita Gronru, posso pedir um favor...",
  ui_story_1018_10180901_151_dialog_content = "Vamos ouvir isso.",
  ui_story_1018_10180901_152_dialog_content = "Posso... ir ao campo de batalha com você?",
  ui_story_1018_10180901_153_dialog_content = "Bem, isso não é um problema, em si...",
  ui_story_1018_10180901_154_dialog_content = "Mas você não parecia bem da última vez que te vi aqui. Se eu estiver certo, o som de armas se chocando te deixa desconfortável.",
  ui_story_1018_10180901_155_dialog_content = "Você está correto. Como soldado, sei que devo portar armas.",
  ui_story_1018_10180901_156_dialog_content = "Mas quando estou sozinho, os sons frios e impiedosos da batalha ecoam nos meus ouvidos e me assustam...",
  ui_story_1018_10180901_157_dialog_content = "No entanto, Illumina precisa de mim agora e eu devo fazer algo, assim como eu disse ao Oficial Vivian...",
  ui_story_1018_10180901_158_dialog_content = "Ah, Vivian é—opa, quase falei demais.",
  ui_story_1018_10180901_159_dialog_content = "O pequeno passarinho gentil precisa encontrar seu próprio caminho. Venha me ver no quintal quando estiver pronto!",
  ui_story_1018_10180901_160_dialog_content = "Claro. Obrigado, Sra. Gronru.",
  ui_story_1018_10181002_1_dialog_content = "Capitão da Guarda, a maior parte do lamaçal se dispersou e não há sinais de atividade do Eclipsita em torno de Crepúsculo agora.",
  ui_story_1018_10181002_2_dialog_content = "Com nossa ajuda, a missão de busca e resgate de Illumina está concluída. A Grande Marechal Wrath está coletando informações de seus subordinados.",
  ui_story_1018_10181002_3_dialog_content = "Entendido. Aguardando após as tropas estarem prontas.",
  ui_story_1018_10181002_4_dialog_content = "Vejo que é assim que Crepúsculo se parece sem a lama - um lugar agitado.",
  ui_story_1018_10181002_5_dialog_content = "Sim, Senhora Santa, aqui costumava ser o mercado e ainda é possível ver as barracas.",
  ui_story_1018_10181002_6_dialog_content = "A parede quebrada ali costumava cercar um pequeno canteiro de flores.",
  ui_story_1018_10181002_7_dialog_content = "É estranho, mas havia muitas variedades diferentes de flores no canteiro e elas floresciam o ano todo.",
  ui_story_1018_10181002_8_dialog_content = "As crianças adoravam brincar aqui, e eu também quando era pequeno.",
  ui_story_1018_10181002_9_dialog_content = "Mas o parquinho deles foi arruinado pelos Eclipsitas.",
  ui_story_1018_10181002_10_dialog_content = "Embora eu acredite que as flores irão florescer novamente.",
  ui_story_1018_10181002_11_dialog_content = "E acredito que, sob os cuidados da Sra. Joselyne, as crianças voltarão a aproveitar a vida aqui.",
  ui_story_1018_10181002_12_dialog_content = "Já consigo ouvir as risadas deles!",
  ui_story_1018_10181002_13_dialog_content = "Obrigado pelo seu incentivo, Senhora Santa! Mas eu me preocupo que...",
  ui_story_1018_10181002_14_dialog_content = "Os Eclipsitas não só destruíram lares, mas também a confiança que as pessoas do Crepúsculo tinham nos guerreiros...",
  ui_story_1018_10181002_15_dialog_content = "Talvez eles não acreditem que este lugar possa trazer conforto e paz novamente.",
  ui_story_1018_10181002_16_dialog_content = "Eu acredito que sim.",
  ui_story_1018_10181002_17_dialog_content = "Leo...?",
  ui_story_1018_10181002_18_dialog_content = "Sob a lama estão os guerreiros que se sacrificaram nesta batalha.",
  ui_story_1018_10181002_19_dialog_content = "Crepúsculo começou como um lugar construído sobre os corpos dos soldados. A situação atual apenas os convenceu de que a guerra sempre existirá.",
  ui_story_1018_10181002_20_dialog_content = "Enquanto houver pessoas dispostas a viver aqui, a determinação em proteger Crepúsculo nunca vacilará.",
  ui_story_1018_10181002_21_dialog_content = "Antes disso, Crepúsculo era uma zona de conforto para mim.",
  ui_story_1018_10181002_22_dialog_content = "Sem essa campanha, eu provavelmente ainda estaria preocupado sobre quando a cidade cairia e hesitante em seguir em frente.",
  ui_story_1018_10181002_23_dialog_content = "O resultado atual é uma oportunidade para que tanto Crepúsculo quanto eu possamos reavaliar nossas opiniões.",
  ui_story_1018_10181002_24_dialog_content = "Leo, o que você acabou de dizer indica que mudou sua perspectiva sobre Lumopolis?",
  ui_story_1018_10181002_25_dialog_content = "Não, senhora Carleen, lamento decepcioná-la.",
  ui_story_1018_10181002_26_dialog_content = "No entanto, a ação do Marechal Wrath me fez perceber que qualquer insatisfação com uma situação não pode ser apenas superficial.",
  ui_story_1018_10181002_27_dialog_content = "Devo fazer a mudança para que minha habilidade corresponda à minha ambição.",
  ui_story_1018_10181002_28_dialog_content = "Prometo a todos vocês que o futuro de Crepúsculo também é meu.",
  ui_story_1018_10181002_29_dialog_content = "Isso te deixou mais tranquilo agora, Joselyne?",
  ui_story_1018_10181002_30_dialog_content = "Leo, estou muito emocionado com o que você disse...",
  ui_story_1018_10181002_31_dialog_content = "Acredito que Crepúsculo pode ser reconstruído e melhor do que nunca!",
  ui_story_1018_10181002_32_dialog_content = "Na verdade, uma ideia tem se formado na minha cabeça e eu me pergunto se Sua Santidade a Santa pode me oferecer alguma orientação?",
  ui_story_1018_10181002_33_dialog_content = "Sua Santidade, ainda temos questões urgentes para tratar.",
  ui_story_1018_10181002_34_dialog_content = "Sim, mas posso trocar mais algumas palavras com Joselyne?",
  ui_story_1018_10181002_35_dialog_content = "Senhora Joselyne, por favor, seja breve.",
  ui_story_1018_10181002_36_dialog_content = "Senhora Santa, quero construir uma igreja no Crepúsculo que abrigará todas as pessoas, não apenas os seguidores do Deus da Luz.",
  ui_story_1018_10181002_37_dialog_content = "Aurorianos, semi-humanos, Caelestites, até mesmo aqueles forçados a se inclinar para o lado sombrio...",
  ui_story_1018_10181002_38_dialog_content = "Eles podem não ser aceitos em seus acampamentos, mas todos que pisarem em Crepúsculo podem ficar, desde que tenham amor e compaixão em seus corações.",
  ui_story_1018_10181002_39_dialog_content = "O Crepúsculo não deveria ter apenas o pôr do sol, mas ser iluminado pela luz.",
  ui_story_1018_10181002_40_dialog_content = "Assim como as pessoas em Astra e outros lugares, eles também devem poder ver a luz do dia, a lua e as estrelas.",
  ui_story_1018_10181002_41_dialog_content = "Eu sei que é um trabalho muito difícil, mas espero receber suas bênçãos primeiro.",
  ui_story_1018_10181002_42_dialog_content = "Você é tão piedosa e generosa, Sra. Joselyne.",
  ui_story_1018_10181002_43_dialog_content = "Assim como os aurorianos originais que se aventuraram rumo ao sul para evangelizar, é igualmente desafiador para você construir sua igreja ideal aqui.",
  ui_story_1018_10181002_44_dialog_content = "Mas a luz sagrada pode iluminar cada canto da fé, especialmente sob sua orientação.",
  ui_story_1018_10181002_45_dialog_content = "Dê o passo se estiver disposto. Você tem meu apoio.",
  ui_story_1018_10181002_46_dialog_content = "Obrigado, Senhora Santa. Jamais esquecerei isso!",
  ui_story_1018_10181002_47_dialog_content = "Ufa... Foi um bom discurso?",
  ui_story_1018_10181002_48_dialog_content = "A escolha de palavras é impecável, Sua Santidade. Mas é hora de seguirmos em frente.",
  ui_story_1018_10181002_49_dialog_content = "Ok, vou deixar você pegar daqui.",
  ui_story_1018_10181002_50_dialog_content = "Ah, Carleen, assim que Crepúsculo estiver seguro, vá para a linha de frente e encontre-se com o exército do City Lord.",
  ui_story_1018_10181002_51_dialog_content = "Ele enviou tropas para a linha de frente?!",
  ui_story_1018_10181002_52_dialog_content = "Mas por que ele parecia tão apático lá no tribunal?",
  ui_story_1018_10181002_53_dialog_content = "Bem, ele mencionou \"Tirar o melhor proveito da situação\"... Eu também não tenho certeza.",
  ui_story_1018_10181002_54_dialog_content = "Não apenas o exército do Lorde da Cidade, mas também os colegas do Marechal.",
  ui_story_1018_10181002_55_dialog_content = "A batalha não acabou?",
  ui_story_1018_10181002_56_dialog_content = "Fique tranquilo, a batalha em Crepúsculo acabou.",
  ui_story_1018_10181002_57_dialog_content = "Mas a guerra está apenas começando para os aurorianos, e foi por isso que eu deixei o Templo.",
  ui_story_1018_10181002_58_dialog_content = "Estou muito feliz em conhecê-lo em minha jornada. Vou rezar por você.",
  ui_story_1018_10181002_59_dialog_content = "May Deus da Luz esteja com você. Aguardo ansiosamente o momento em que nos encontraremos novamente.",
  ui_story_1018_10181002_60_dialog_content = "O eterno Deus da Luz.",
  ui_story_1018_10181002_61_dialog_content = "Avante, Noite Branca.",
  ui_story_1018_10181002_62_dialog_content = "Os Eclipsitas não recuaram, mas se moveram para a linha de frente de Illumina. Acho que não vamos acabar com essa ascensão de Darkover facilmente...",
  ui_story_1018_10181002_63_dialog_content = "Vejo que todos vocês sabem.",
  ui_story_1018_10181002_64_dialog_content = "Grande Marechal Wrath! Pelo menos a Senhora Santa disse que Twilight está fora de perigo por enquanto.",
  ui_story_1018_10181002_65_dialog_content = "A cidade sobreviveu, graças ao esforço conjunto de Illumina e os Cavaleiros!",
  ui_story_1018_10181002_66_dialog_content = "Obrigado pelo reconhecimento, mas não precisa me consolar, Joselyne.",
  ui_story_1018_10181002_67_dialog_content = "Na verdade, me sinto grato por a situação estar ficando clara.",
  ui_story_1018_10181002_68_dialog_content = "Tivemos sucesso em termos de resultado, mas para mim, foi um fracasso catastrófico...",
  ui_story_1018_10181002_69_dialog_content = "Grande Marechal Wrath, Illumina não pode enfrentar o atual predicamento sozinha.",
  ui_story_1018_10181002_70_dialog_content = "Lumópolis não deveria ter ficado de braços cruzados enquanto a batalha em Crepúsculo progredia desfavoravelmente.",
  ui_story_1018_10181002_71_dialog_content = "Agora o exército do Senhor da Cidade está se reunindo na linha de frente, independentemente de como a Illumina reage, Lumopolis não será mais um espectador.",
  ui_story_1018_10181002_72_dialog_content = "Você entendeu mal, Senhora Carleen. Apenas o fracasso poderia dar sentido a tudo isso.",
  ui_story_1018_10181002_73_dialog_content = "A campanha Crepúsculo, os soldados sacrificados e o projeto dos superiores... Todos devem terminar no meu fracasso.",
  ui_story_1018_10181002_74_dialog_content = "Essa é a única maneira da Illumina ter um futuro.",
  ui_story_1018_10181002_75_dialog_content = "Grande Marechal, você e seus colegas estão planejando algo?",
  ui_story_1018_10181002_76_dialog_content = "Devo confirmar aquilo em que acredito firmemente, não importa quais perigos me aguardem na linha de frente.",
  ui_story_1018_10181002_77_dialog_content = "Estou preocupado que o que aconteceu com Crepúsculo possa acontecer com Illumina.",
  ui_story_1018_10181002_78_dialog_content = "Axelia não disse que Forsakin levou os soldados dela também?",
  ui_story_1018_10181002_79_dialog_content = "Enquanto forem eles defendendo, ainda de carne e osso, tenho certeza de que não será uma repetição.",
  ui_story_1018_10181002_80_dialog_content = "Eu fiz uma promessa aos soldados caídos de que os traria de volta para Illumina, não importa o quê.",
  ui_story_1018_10181002_81_dialog_content = "Falarei com você sobre Crepúsculo mais tarde. Meu exército Illumina retornará à linha de frente.",
  ui_story_1018_10181002_82_dialog_content = "Se é para lá que você está indo, os Cavaleiros do Crepúsculo irão acompanhá-lo.",
  ui_story_1018_10181002_83_dialog_content = "Os adversários ainda não foram eliminados, então ainda somos aliados.",
  ui_story_1018_10181002_84_dialog_content = "Tudo bem! Não vou esquecer nossos aliados de Crepúsculo.",
  ui_story_1018_10181002_85_dialog_content = "Nesse caso, posso dar uma carona a vocês em um dirigível de Lumopolis, Leo e Grande Marechal Wrath?",
  ui_story_1018_10181002_86_dialog_content = "Respeitosamente recuso. Os cavaleiros estão acostumados a cavalgar em batalhas, não a usar veículos aéreos.",
  ui_story_1018_10181002_87_dialog_content = "Obrigado pela oferta, Senhora Carleen, mas isso não está de acordo com os procedimentos da Illumina.",
  ui_story_1018_10181002_88_dialog_content = "Mas posso ver que os soldados estão exaustos. Talvez eles possam descansar um pouco na aeronave.",
  ui_story_1018_10181002_89_dialog_content = "Carleen está certo. Se enfrentarmos uma batalha difícil, eles devem descansar um pouco agora.",
  ui_story_1018_10181002_90_dialog_content = "Eu também não acho que os soldados feridos consigam fazer a jornada a pé.",
  ui_story_1018_10181002_91_dialog_content = "Então até você sabe as chaves para liderar um exército na batalha agora?",
  ui_story_1018_10181002_92_dialog_content = "Acho que Crepúsculo é um verdadeiro campo de treinamento.",
  ui_story_1018_10181002_93_dialog_content = "Grande Marechal, então obedeceremos humildemente ao seu comando.",
  ui_story_1018_10181002_94_dialog_content = "Capitão, devemos...?",
  ui_story_1018_10181002_95_dialog_content = "...",
  ui_story_1018_10181002_96_dialog_content = "Vamos lá, Leo.",
  ui_story_1018_10181002_97_dialog_content = "Pare de enrolar se vamos derrotar inimigos juntos, Cavaleiro.",
  ui_story_1018_10181002_98_dialog_content = "Claro!",
  ui_story_1018_10181101_1_dialog_content = "<color=#e8d9bb>Linha de Defesa Illumina</color>",
  ui_story_1018_10181101_2_dialog_content = "Comandante, confirmamos que os cavaleiros avistados nas linhas de defesa leste e oeste são de Lumópolis.",
  ui_story_1018_10181101_3_dialog_content = "Até agora, não foram detectados sinais de Eclipsitas nas linhas de defesa leste e oeste. Os cavaleiros de Lumopolis e nossas unidades de defesa estão mantendo uma vigilância próxima.",
  ui_story_1018_10181101_4_dialog_content = "Entendido.",
  ui_story_1018_10181101_5_dialog_content = "Alguma mudança no movimento deles?",
  ui_story_1018_10181101_6_dialog_content = "A rota deles é a mesma de sempre - reta pelo centro, avançando verticalmente para o interior. Nossas unidades de assalto estão enfrentando o inimigo diretamente e prontas para romper suas formações.",
  ui_story_1018_10181101_7_dialog_content = "O objetivo deles ainda é desconhecido, então o esquadrão de assalto deve apenas impedir os Eclipsitas de avançar nas trincheiras.",
  ui_story_1018_10181101_8_dialog_content = "Mas, Comandante... mesmo que repelamos um enxame de Eclipsitas, eles apenas enviarão o próximo. Estamos realmente bem se continuarmos defendendo assim?",
  ui_story_1018_10181101_9_dialog_content = "Os Eclipsitas estão apenas nos testando, não tentando realizar um ataque ofensivo.",
  ui_story_1018_10181101_10_dialog_content = "Não podemos ser precipitados até entendermos completamente.",
  ui_story_1018_10181101_11_dialog_content = "Como está indo com as fortificações?",
  ui_story_1018_10181101_12_dialog_content = "O General Barton está supervisionando as questões de defesa entre as Cidades Subterrâneas, e as forças sob o comando do General Hiiro devem chegar em breve à linha de defesa.",
  ui_story_1018_10181101_13_dialog_content = "O mau funcionamento do equipamento de comunicação anterior ainda não foi restaurado. Então, já enviamos notificações conforme seu pedido. As operações de combate terrestre estão agora nas mãos das forças da linha de frente.",
  ui_story_1018_10181101_14_dialog_content = "Cada uma das Subcidades está dedicada à sua própria estratégia de defesa e não responderá às ações ao longo da linha defensiva.",
  ui_story_1018_10181101_15_dialog_content = "Tudo bem. Ainda não há notícias de Crepúsculo?",
  ui_story_1018_10181101_16_dialog_content = "Sem notícias do Grande Marechal. Mas, a julgar pela maior vigilância das tropas de Lumopolis, a batalha em Crepúsculo deve estar chegando ao fim.",
  ui_story_1018_10181101_17_dialog_content = "Espero que tenha corrido como esperado.",
  ui_story_1018_10181101_18_dialog_content = "Comandante! Fora da linha de defesa, pântanos surgiram repentinamente na trincheira e pegaram alguns soldados!",
  ui_story_1018_10181101_19_dialog_content = "O ataque dos Eclipsitas desta vez está muito mais feroz do que antes!",
  ui_story_1018_10181101_20_dialog_content = "Nas trincheiras? Não havia nenhum sinal do atoleiro se espalhando antes.",
  ui_story_1018_10181101_21_dialog_content = "Comandante, a expansão do pântano não foi gradual - ela subitamente irrompeu do subsolo!",
  ui_story_1018_10181101_22_dialog_content = "Conforme descrito pelos soldados, inicialmente, havia apenas um pouco de lama na trincheira e, de repente, a lama se agitou, acumulando-se loucamente!",
  ui_story_1018_10181101_23_dialog_content = "Já se espalhou para as barreiras adjacentes!",
  ui_story_1018_10181101_24_dialog_content = "...",
  ui_story_1018_10181101_25_dialog_content = "Transmita a situação aos Lumo Cavaliers na frente ocidental e mova as reservas para o centro, imediatamente!",
  ui_story_1018_10181101_26_dialog_content = "Comandos, sigam-me para a frente central!",
  ui_story_1018_10181101_27_dialog_content = "Sim!",
  ui_story_1018_10181101_28_dialog_content = "Eles chamam isso de barreira? Era assim dez anos atrás e continua igual dez anos depois.",
  ui_story_1018_10181101_29_dialog_content = "Comida—",
  ui_story_1018_10181101_30_dialog_content = "Você não está aqui para comer. Você só precisa levar aqueles colegas competentes.",
  ui_story_1018_10181101_31_dialog_content = "Em breve, surgirá a passagem da Zona Escura para o coração do território.",
  ui_story_1018_10181101_32_dialog_content = "A chama azul está queimando—",
  ui_story_1018_10181101_33_dialog_content = "Heh, você se move rápido, devo dizer.",
  ui_story_1018_10181101_34_dialog_content = "Ah, é você, o traidor.",
  ui_story_1018_10181101_35_dialog_content = "Heh, chaleira, bule, preto. Esqueceu dos soldados que você matou?",
  ui_story_1018_10181101_36_dialog_content = "Seu tolo ignorante! Você matou todos os soldados em Crepúsculo?",
  ui_story_1018_10181101_37_dialog_content = "Não todos. Muitos morreram pelas mãos de seus companheiros, embora isso se encaixe na tradição da Illumina de usar e esquecer.",
  ui_story_1018_10181101_38_dialog_content = "Cale-se e prepare-se para morrer!",
  ui_story_1018_10181101_39_dialog_content = "Aquele que vai encontrar a morte é você. Esse novo Grande Marechal seu sofreu muito antes deles.",
  ui_story_1018_10181101_40_dialog_content = "Eles?",
  ui_story_1018_10181101_41_dialog_content = "Parece familiar? É o que ela ganha por tentar ser esperta.",
  ui_story_1018_10181101_42_dialog_content = "O que está acontecendo com Wrath?",
  ui_story_1018_10181101_43_dialog_content = "É apenas uma questão de tempo até ela morrer. Depois, será a sua vez de ser o Grande Marechal.",
  ui_story_1018_10181101_44_dialog_content = "O Grande Marechal não é alguém que você pode insultar!",
  ui_story_1018_10181101_45_dialog_content = "Ah!",
  ui_story_1018_10181101_46_dialog_content = "...",
  ui_story_1018_10181101_47_dialog_content = "O quê, não consegue? Você precisa se decidir rápido.",
  ui_story_1018_10181101_48_dialog_content = "Comandante, ela realmente desapareceu no pântano...",
  ui_story_1018_10181101_49_dialog_content = "Espere, será que o pântano já está engolindo o Crepúsculo, se espalhando aqui de baixo...",
  ui_story_1018_10181101_50_dialog_content = "A linha de defesa da Illumina... Será que também vai ser engolida?",
  ui_story_1018_10181101_51_dialog_content = "Mate os Eclipsitas primeiro e aguarde minha atualização sobre o que está acontecendo abaixo das trincheiras.",
  ui_story_1018_10181101_52_dialog_content = "Já que veio do subsolo, seria mais rápido mexer com as subcidades.",
  ui_story_1018_10181101_53_dialog_content = "Não entre em pânico e segure a linha!",
  ui_story_1018_10181101_54_dialog_content = "Entendido!",
  ui_story_1018_10181101_55_dialog_content = "Equipe de assalto, recuem para junto da muralha e eliminem os Eclipsitas.",
  ui_story_1018_10181101_56_dialog_content = "Ah!",
  ui_story_1018_10181101_57_dialog_content = "Comandante, ele... ele é um dos nossos soldados Illumina?",
  ui_story_1018_10181101_58_dialog_content = "Cheio de Fluxo Escuro, devorando Eclipsitas, prejudicando companheiros...",
  ui_story_1018_10181101_59_dialog_content = "Eles são Eclipsitas, sem piedade!",
  ui_story_1018_10181101_60_dialog_content = "E-entendido, Comandante!",
  ui_story_1018_10181102_1_dialog_content = "<color=#e8d9bb>Buuuum!</color>",
  ui_story_1018_10181102_2_dialog_content = "Artilharias em ação! Parece que os pântanos pararam de se espalhar!",
  ui_story_1018_10181102_3_dialog_content = "Os Eclipsitas também pararam!",
  ui_story_1018_10181102_4_dialog_content = "Suas ordens chegaram bem na hora, Comandante!",
  ui_story_1018_10181102_5_dialog_content = "Eu não dei a ordem...",
  ui_story_1018_10181102_6_dialog_content = "Aquelas conchas foram disparadas de três fortificações diferentes.",
  ui_story_1018_10181102_7_dialog_content = "Será que...",
  ui_story_1018_10181102_8_dialog_content = "Ah, que emoção! Faz tempo que não fico tão empolgado com um bombardeio!",
  ui_story_1018_10181102_9_dialog_content = "Um pouco fora do alvo, mas ainda alcançou o resultado esperado.",
  ui_story_1018_10181102_10_dialog_content = "Comandante, são o General Barton e o General Hiiro!",
  ui_story_1018_10181102_11_dialog_content = "É realmente eles! Vindo nos apoiar!",
  ui_story_1018_10181102_12_dialog_content = "O fortalecimento da Subcidade correu bem e eu não perderia essa luta por nada neste mundo!",
  ui_story_1018_10181102_13_dialog_content = "Sem motivo para perder quando a luta já está na sua porta.",
  ui_story_1018_10181102_14_dialog_content = "Estou realmente grato pela ajuda de vocês dois. Os Eclipsitas estão atualmente sob controle.",
  ui_story_1018_10181102_15_dialog_content = "No entanto, um pântano foi avistado nas trincheiras e me preocupo que ele possa infiltrar na cidade subterrânea.",
  ui_story_1018_10181102_16_dialog_content = "Não vimos nenhum sinal disso no nosso caminho até aqui. Os inimigos provavelmente acabaram de chegar também.",
  ui_story_1018_10181102_17_dialog_content = "Isso mesmo, tenho vigiado o perímetro feito um falcão.",
  ui_story_1018_10181102_18_dialog_content = "A lama inundou o Crepúsculo, e Forsakin está envolvido...",
  ui_story_1018_10181102_19_dialog_content = "De qualquer forma, enfrentaremos isso juntos.",
  ui_story_1018_10181102_20_dialog_content = "Estamos apenas esperando por Wrath. Esperamos que tudo ocorra conforme ela planejou...",
  ui_story_1018_10181102_21_dialog_content = "Eu acredito que sim.",
  ui_story_1018_10181102_22_dialog_content = "Grande marechal!",
  ui_story_1018_10181102_23_dialog_content = "Eu acredito em Wrath também!",
  ui_story_1018_10181102_24_dialog_content = "Chefe de Gabinete! O que está fazendo aqui?",
  ui_story_1018_10181102_25_dialog_content = "De acordo com o plano de Wrath, se os Eclipsitas atacassem a frente, eu seria o último a ser implantado.",
  ui_story_1018_10181102_26_dialog_content = "O Grande Marechal também agiria comigo após receber a ordem.",
  ui_story_1018_10181102_27_dialog_content = "Então isso significa que uma das três grandes armas estava sob o controle do Grande Marechal?",
  ui_story_1018_10181102_28_dialog_content = "Não <color=#FFB400>dirijo uma carruagem com arma</color> há um tempo, mas acho que ainda consigo.",
  ui_story_1018_10181102_29_dialog_content = "Grande Marechal, como você...",
  ui_story_1018_10181102_30_dialog_content = "Ah, quase esqueci!",
  ui_story_1018_10181102_31_dialog_content = "Operação: Fuga da Prisão foi um sucesso para a Chefe de Gabinete Vivian, Senhora!",
  ui_story_1018_10181102_32_dialog_content = "Uau...",
  ui_story_1018_10181102_33_dialog_content = "Grande Marechal, Capitão Sharona da 1ª Legião manteve a linha e negou a entrada a todos os Eclipsitas.",
  ui_story_1018_10181102_34_dialog_content = "Enquanto eu, Capitão Barton da 2ª Legião, estiver por perto, nenhum Eclipsite entrará na cidade subterrânea!",
  ui_story_1018_10181102_35_dialog_content = "Capitão Hiiro da 3ª Legião, responsável pelo reforço final, concluiu o dever.",
  ui_story_1018_10181102_36_dialog_content = "Muito bem feito, todos vocês. E bom trabalho para todos os meus colegas da Illumina.",
  ui_story_1018_10181102_37_dialog_content = "Generais e o Grande Marechal estão todos aqui... Ainda acho difícil acreditar...",
  ui_story_1018_10181102_38_dialog_content = "Grande marechal!",
  ui_story_1018_10181102_39_dialog_content = "Salve!",
  ui_story_1018_10181201_1_dialog_content = "Comandante, nenhum vestígio de Forsakin foi encontrado na trincheira.",
  ui_story_1018_10181201_2_dialog_content = "Atualmente, os cavaleiros de Lumopolis ainda estão segurando a linha de defesa, e dizem que o reforço que vai para Twilight já está voltando.",
  ui_story_1018_10181201_3_dialog_content = "Entendido. Informe imediatamente quando o reforço estiver à vista.",
  ui_story_1018_10181201_4_dialog_content = "Parece que Lumópolis não tem intenção de se envolver na batalha.",
  ui_story_1018_10181201_5_dialog_content = "Não temos certeza do que está acontecendo em Crepúsculo, mas ainda há espaço para esperança. Eu só me preocupo com Wrath...",
  ui_story_1018_10181201_6_dialog_content = "Verdade, não há atualizações de Crepúsculo há muito tempo.",
  ui_story_1018_10181201_7_dialog_content = "É minha negligência. Estou aqui desde que Wrath foi para o Crepúsculo.",
  ui_story_1018_10181201_8_dialog_content = "Se eu atacasse, a linha poderia cair, mas se eu recuasse para trás da linha, eu poderia perder o relatório vindo de Crepúsculo.",
  ui_story_1018_10181201_9_dialog_content = "Não consegui chegar ao fundo do atoleiro que se espalhava e deixei Forsakin escapar.",
  ui_story_1018_10181201_10_dialog_content = "Você não tem culpa. Eu ouvi sobre a situação em Crepúsculo durante o caminho e o inimigo usou um ataque sem precedentes, então todos devem ter cautela.",
  ui_story_1018_10181201_11_dialog_content = "Algo está se aproximando rapidamente da lama à frente, Grande Marechal.",
  ui_story_1018_10181201_12_dialog_content = "Tem um desejo de morte! Permita-me realizá-lo!",
  ui_story_1018_10181201_13_dialog_content = "Cuidado com o pântano, Forsakin pode estar à espreita.",
  ui_story_1018_10181201_14_dialog_content = "Atacar a linha se esgueirando como um rato é o seu método?",
  ui_story_1018_10181201_15_dialog_content = "Golpe do Leopardo!",
  ui_story_1018_10181201_16_dialog_content = "Engula tudo—",
  ui_story_1018_10181201_17_dialog_content = "Finalmente se mostrando, seu verme?!",
  ui_story_1018_10181201_18_dialog_content = "Graaaah-!",
  ui_story_1018_10181201_19_dialog_content = "Comandante! Eclipsitas estão surgindo dos pântanos e um grande contingente de soldados não identificados está se movendo em direção à linha defensiva!",
  ui_story_1018_10181201_20_dialog_content = "Por favor, dê sua ordem, Grande Marechal!",
  ui_story_1018_10181201_21_dialog_content = "...",
  ui_story_1018_10181201_22_dialog_content = "Não vou dar ordens. Não sou o comandante desta batalha.",
  ui_story_1018_10181201_23_dialog_content = "Mas Grande Marechal...",
  ui_story_1018_10181201_24_dialog_content = "Não é negociável. Estou nesta luta como um cidadão comum.",
  ui_story_1018_10181201_25_dialog_content = "Pessoal, apenas façam o que vocês devem fazer.",
  ui_story_1018_10181201_26_dialog_content = "...",
  ui_story_1018_10181201_27_dialog_content = "Nesse caso, eu não quero registrar as balas aqui à toa! Mirem, arma do lado leste!",
  ui_story_1018_10181201_28_dialog_content = "Mira, arma do lado oeste!",
  ui_story_1018_10181201_29_dialog_content = "Comandante, as legiões de defesa nos lados leste e oeste estão reunidas e prontas.",
  ui_story_1018_10181201_30_dialog_content = "Reservas do leste e oeste, procurem por Forsakin no pântano. Equipe de assalto, preparem-se para atacar os Eclipsitas!",
  ui_story_1018_10181201_31_dialog_content = "Espere, Sharona, não são aqueles Eclipsitas cobertos de lama soldados Illumina?",
  ui_story_1018_10181201_32_dialog_content = "...",
  ui_story_1018_10181201_33_dialog_content = "Alguns deles têm um pouco de consciência, mas muitos se tornaram irreversivelmente Eclipsitas.",
  ui_story_1018_10181201_34_dialog_content = "Como fazemos...",
  ui_story_1018_10181201_35_dialog_content = "Aqui.",
  ui_story_1018_10181201_36_dialog_content = "Grande marechal...",
  ui_story_1018_10181201_37_dialog_content = "Não se preocupe. Eu os salvarei enquanto houver esperança.",
  ui_story_1018_10181201_38_dialog_content = "Mas Grande Marechal, eles se alimentam de soldados. Eu só...",
  ui_story_1018_10181201_39_dialog_content = "Eu faria isso também, se fosse você, mas meu corpo aguentaria a mordida deles.",
  ui_story_1018_10181201_40_dialog_content = "Continue liderando seus soldados. A equipe para transportar os feridos já está a caminho.",
  ui_story_1018_10181201_41_dialog_content = "Sim, Grande Marechal.",
  ui_story_1018_10181201_42_dialog_content = "<color=#e8d9bb>Buuuum!</color>",
  ui_story_1018_10181201_43_dialog_content = "É... o fogo de artilharia do Comandante Hiiro, acertando bem no centro do pântano!",
  ui_story_1018_10181201_44_dialog_content = "Ainda não há disparos dos artilheiros do oeste.",
  ui_story_1018_10181201_45_dialog_content = "Não olhe para mim, nem para o meu lado.",
  ui_story_1018_10181201_46_dialog_content = "Isso só pode significar...",
  ui_story_1018_10181201_47_dialog_content = "Heh, você achou que poderia parar o Mudbundle?",
  ui_story_1018_10181201_48_dialog_content = "Isso destruiu Crepúsculo.",
  ui_story_1018_10181201_49_dialog_content = "Lama chegando—",
  ui_story_1018_10181201_50_dialog_content = "Você já destruiu o Crepúsculo, Forsakin, por que está atacando a frente agora?",
  ui_story_1018_10181201_51_dialog_content = "Vamos lá, não me diga que você ainda está do lado da Illumina depois que eles te jogaram em uma cela!",
  ui_story_1018_10181201_52_dialog_content = "Em vez do jeito difícil, por que você não abre o portão e me deixa incinerar aqueles que te colocaram nessa situação?",
  ui_story_1018_10181201_53_dialog_content = "A Illumina segue suas próprias regras e princípios. É até onde você vai.",
  ui_story_1018_10181201_54_dialog_content = "Ainda se fazendo de nobre, pelo jeito. Não é à toa que te arrastaram pela lama.",
  ui_story_1018_10181201_55_dialog_content = "Não fale com a Grande Marechal dessa maneira!",
  ui_story_1018_10181201_56_dialog_content = "Abra os olhos, capacho. Não há nenhum Grande Marechal aqui.",
  ui_story_1018_10181201_57_dialog_content = "Sem Grande Marechal? Acho que você falou cedo demais.",
  ui_story_1018_10181201_58_dialog_content = "<color=#e8d9bb>A terra trêmula ecoava com rodas trovejantes e cascos galopantes...</color>",
  ui_story_1018_10181201_59_dialog_content = "Pousar cedo foi realmente a decisão certa. É mais prático nos mover no chão!",
  ui_story_1018_10181201_60_dialog_content = "O inimigo não terá para onde correr assim que cruzarmos as trincheiras. Todas as armas, atirem no atoleiro!",
  ui_story_1018_10181201_61_dialog_content = "Ei, a linha Illumina está realmente agitada. Seu plano de ataque continua tão direto como sempre.",
  ui_story_1018_10181201_62_dialog_content = "Isso torna tudo ainda melhor. Seremos a última muralha para fechá-la.",
  ui_story_1018_10181201_63_dialog_content = "Axelia irá recuperar todos os subordinados...",
  ui_story_1018_10181201_64_dialog_content = "Recuperou-se tão rápido? Axelia deve ser construído como um mecha da Illumina...",
  ui_story_1018_10181201_65_dialog_content = "Acho que Axelia está ainda melhor para ficar como nova agora, mesmo com todo o dano que ela sofreu.",
  ui_story_1018_10181201_66_dialog_content = "Prepare-se para lutar, PlayerName. Ainda temos Eclipsitas para eliminar antes de chegarmos ao nosso destino.",
  ui_story_1018_10181201_67_dialog_content = "Claro, sem problemas.",
  ui_story_1018_10181201_68_dialog_content = "Então fique firme. Os atiradores eliminarão os retardatários como se fossem Eclipsitas.",
  ui_story_1018_10181201_69_dialog_content = "Entendi...",
  ui_story_1018_10181201_70_dialog_content = "<color=#e8d9bb>Clank—</color>",
  ui_story_1018_10181201_71_dialog_content = "Cuidado! Desvie!",
  ui_story_1018_10181201_72_dialog_content = "Engine VII? Subindo repentinamente... da trincheira!",
  ui_story_1018_10181201_73_dialog_content = "É aquele que foi danificado em Crepúsculo...",
  ui_story_1018_10181201_74_dialog_content = "Não acredito que foi trazido pra cá... Não é à toa que os soldados desapareceram em massa.",
  ui_story_1018_10181201_75_dialog_content = "Rugido...",
  ui_story_1018_10181201_76_dialog_content = "A voz... Talvez o piloto tenha mantido alguma consciência?",
  ui_story_1018_10181201_77_dialog_content = "Não se aproximem dele - soldados estão rastejando bem ao lado dos pés dele!",
  ui_story_1018_10181201_78_dialog_content = "Quantos deles estão lá dentro...?",
  ui_story_1018_10181201_79_dialog_content = "<color=#e8d9bb>Zumbido...Crunch!</color>",
  ui_story_1018_10181201_80_dialog_content = "A pausa... Ele está hesitando...",
  ui_story_1018_10181201_81_dialog_content = "Grande Marechal, talvez haja esperança para o soldado interior afinal. Axelia está tentando salvá-lo.",
  ui_story_1018_10181201_82_dialog_content = "Você já foi quebrado uma vez!",
  ui_story_1018_10181201_83_dialog_content = "Axelia já foi quebrado várias vezes antes disso.",
  ui_story_1018_10181201_84_dialog_content = "Mas Axelia conseguiu se recuperar todas as vezes.",
  ui_story_1018_10181201_85_dialog_content = "O piloto dentro é um membro do esquadrão de Axelia. É dever de Axelia protegê-los.",
  ui_story_1018_10181201_86_dialog_content = "...",
  ui_story_1018_10181201_87_dialog_content = "Roooorrr!!!",
  ui_story_1018_10181201_88_dialog_content = "O corpo dele se fundiu completamente com o mecha. Isso deve ser muito difícil para o piloto.",
  ui_story_1018_10181201_89_dialog_content = "Mecha também faz parte do Axelia. Axelia sabe que é difícil para ele.",
  ui_story_1018_10181201_90_dialog_content = "Lamento ouvir isso, Axelia...",
  ui_story_1018_10181201_91_dialog_content = "Wrath, deixe-me ir com Axelia! Eu vou salvar os soldados com ela!",
  ui_story_1018_10181201_92_dialog_content = "Como Grande Marechal, é meu dever te deter, mas considerando este caso...",
  ui_story_1018_10181201_93_dialog_content = "Leo, por favor, distraia Engine VII para nós!",
  ui_story_1018_10181201_94_dialog_content = "Certo!",
  ui_story_1018_10181201_95_dialog_content = "Wrath...?",
  ui_story_1018_10181201_96_dialog_content = "Não posso deixar vocês dois enfrentarem isso sozinhos.",
  ui_story_1018_10181201_97_dialog_content = "Engine VII era o escudo do exército em Crepúsculo, mas agora ele está do lado oposto.",
  ui_story_1018_10181201_98_dialog_content = "Ele precisa passar por este escudo para te machucar.",
  ui_story_1018_10181201_99_dialog_content = "Ah!",
  ui_story_1018_10181201_100_dialog_content = "Ah não, soldados saindo das trincheiras...",
  ui_story_1018_10181201_101_dialog_content = "Eles são subordinados de Axelia.",
  ui_story_1018_10181201_102_dialog_content = "Ela não vai se safar usando meus soldados para me atrasar!",
  ui_story_1018_10181201_103_dialog_content = "Faça o que quiser, Axelia, e salve seus amigos! Eu cuido dos soldados!",
  ui_story_1018_10181201_104_dialog_content = "Axelia cópia.",
  ui_story_1018_10181202_1_dialog_content = "Os soldados aqui foram todos dominados, mas ainda estão conscientes.",
  ui_story_1018_10181202_2_dialog_content = "Aqui também. Cuidado com os tiros de Engine VII.",
  ui_story_1018_10181202_3_dialog_content = "Roooorrr!!!",
  ui_story_1018_10181202_4_dialog_content = "Axelia sabe que você está passando por uma experiência difícil.",
  ui_story_1018_10181202_5_dialog_content = "Você não quer machucar as pessoas... Axelia sabe disso tudo.",
  ui_story_1018_10181202_6_dialog_content = "Rugido...",
  ui_story_1018_10181202_7_dialog_content = "Ele está se afastando lentamente da frente. Não há inimigo lá.",
  ui_story_1018_10181202_8_dialog_content = "Siga com cautela! Depois que ele limpar as trincheiras, subjugar por trás!",
  ui_story_1018_10181202_9_dialog_content = "Ah!",
  ui_story_1018_10181202_10_dialog_content = "Eu tenho que fazer um movimento!",
  ui_story_1018_10181202_11_dialog_content = "Saia do caminho, Axelia!",
  ui_story_1018_10181202_12_dialog_content = "Lança relâmpago, perfure!",
  ui_story_1018_10181202_13_dialog_content = "Rugido...",
  ui_story_1018_10181202_14_dialog_content = "Ele parou! Mas Axelia...",
  ui_story_1018_10181202_15_dialog_content = "Leo, Axelia está vindo em sua direção!",
  ui_story_1018_10181202_16_dialog_content = "Oi—",
  ui_story_1018_10181202_17_dialog_content = "A distância não é um problema.",
  ui_story_1018_10181202_18_dialog_content = "Oi—",
  ui_story_1018_10181202_19_dialog_content = "<color=#e8d9bb>Relincho—</color>",
  ui_story_1018_10181202_20_dialog_content = "Ufa—",
  ui_story_1018_10181202_21_dialog_content = "Presenciei sua coragem novamente, Leo de Crepúsculo.",
  ui_story_1018_10181202_22_dialog_content = "O que está fazendo aqui?",
  ui_story_1018_10181202_23_dialog_content = "Bom trabalho, Axelia.",
  ui_story_1018_10181202_24_dialog_content = "O Grande Marechal pegou Axelia.",
  ui_story_1018_10181202_25_dialog_content = "Você superou a versão de si mesmo da partida de exibição. Você é um guerreiro notável.",
  ui_story_1018_10181202_26_dialog_content = "Axelia tem refletido sobre o que o Grande Marechal disse...",
  ui_story_1018_10181202_27_dialog_content = "Axelia quer perguntar ao Grande Marechal, derrotando Eclipsitas e protegendo os guerreiros de Illumina...",
  ui_story_1018_10181202_28_dialog_content = "Isso conta como \"Viver como uma pessoa\"?",
  ui_story_1018_10181202_29_dialog_content = "Você já está lá, Axelia.",
  ui_story_1018_10181202_30_dialog_content = "Obrigado, Grande Marechal. Axelia continuará a lutar.",
  ui_story_1018_10181202_31_dialog_content = "Você terá suas chances, Axelia. Aqui estão seus amigos que se preocupam com você.",
  ui_story_1018_10181202_32_dialog_content = "Axelia! Que bom que consegui alcançar...",
  ui_story_1018_10181202_33_dialog_content = "Yingel...",
  ui_story_1018_10181202_34_dialog_content = "Desculpe! Eu sabia disso e mesmo assim deixei você passar por isso... Me desculpe!",
  ui_story_1018_10181202_35_dialog_content = "Axelia só sabe que Yingel quer proteger Axelia.",
  ui_story_1018_10181202_36_dialog_content = "É ótimo que Axelia esteja bem! Eu não disse que o passarinho gentil seria recompensado?",
  ui_story_1018_10181202_37_dialog_content = "Grande Marechal, Oficial de Tecnologia Gronru e Coronel Yingel levarão os soldados Illumina para casa!",
  ui_story_1018_10181202_38_dialog_content = "Claro. Cuide desses guerreiros.",
  ui_story_1018_10181202_39_dialog_content = "Sobre o que aconteceu na investigação, Grande Marechal... Eu sinto muito.",
  ui_story_1018_10181202_40_dialog_content = "Além disso, os experimentos do Professor Ulysses...",
  ui_story_1018_10181202_41_dialog_content = "Mas acredite em mim, nunca mais defenderei ele nesse assunto. Eu não quero ver colegas inocentes se machucarem.",
  ui_story_1018_10181202_42_dialog_content = "Por favor, permita-me levá-los de volta para Illumina para tratamento. Eu vou procurar uma solução para o problema deles...",
  ui_story_1018_10181202_43_dialog_content = "Vocês são todos vítimas, não precisam se desculpar.",
  ui_story_1018_10181202_44_dialog_content = "Mas eu custei a você o cargo de Grande Marechal...",
  ui_story_1018_10181202_45_dialog_content = "Essa posição não é algo que você pode mudar com suas palavras.",
  ui_story_1018_10181202_46_dialog_content = "Devo agradecer por me permitir ter a oportunidade de ser o Grande Marechal.",
  ui_story_1018_10181202_47_dialog_content = "Você voltou, Wrath.",
  ui_story_1018_10181202_48_dialog_content = "Uau, dois Grandes Marechais!",
  ui_story_1018_10181202_49_dialog_content = "Eu sabia que Wrath ficaria bem!",
  ui_story_1018_10181202_50_dialog_content = "Você realmente se portou como um Grande Marechal, devo dizer.",
  ui_story_1018_10181202_51_dialog_content = "É isso que uma batalha difícil em Crepúsculo faria com você.",
  ui_story_1018_10181202_52_dialog_content = "Estávamos esperando por você na frente.",
  ui_story_1018_10181202_53_dialog_content = "Prometi que assumiria temporariamente como Grande Marechal por você e voltaria vivo. Eu não volto atrás nas minhas palavras.",
  ui_story_1018_10181202_54_dialog_content = "Grande Marechal e os quatro comandantes, não me diga...",
  ui_story_1018_10181202_55_dialog_content = "...",
  ui_story_1018_10181202_56_dialog_content = "Eu estive lutando por um resultado, mas agora também provei uma coisa...",
  ui_story_1018_10181202_57_dialog_content = "Você está absolutamente qualificado, Wrath.",
  ui_story_1018_10181202_58_dialog_content = "Mas eu ainda não terminei...",
  ui_story_1018_10181202_59_dialog_content = "Você é absolutamente qualificado.",
  ui_story_1018_10181202_60_dialog_content = "...",
  ui_story_1018_10181202_61_dialog_content = "Aham, você acha que vou aceitar o que você acabou de dizer?",
  ui_story_1018_10181202_62_dialog_content = "Se eu não conseguir te vencer, não mereço ser o Grande Marechal.",
  ui_story_1018_10181202_63_dialog_content = "A batalha não acabou, então você dá as ordens.",
  ui_story_1018_10181202_64_dialog_content = "...",
  ui_story_1018_10181202_65_dialog_content = "O Capitão Wrath da Guarda Real conseguiu repelir os Eclipsitas do Crepúsculo.",
  ui_story_1018_10181202_66_dialog_content = "A Quarta Legião de Illumina está reunida e aguarda a ordem do Grande Marechal!",
  ui_story_1018_10181401_1_dialog_content = "Ainda temos bastante tempo, mas achei que já haveria uma enorme cratera aqui.",
  ui_story_1018_10181401_2_dialog_content = "O quê, você está ficando sentimental por se despedir dela?",
  ui_story_1018_10181401_3_dialog_content = "Isso é ridículo. Achei que você já tivesse terminado o seu lance, por isso não devemos perder mais tempo.",
  ui_story_1018_10181401_4_dialog_content = "Vamos lá, o momento que você está esperando está chegando.",
  ui_story_1018_10181401_5_dialog_content = "Tudo bem. Mas antes de irmos embora, ainda tenho algumas coisas para limpar.",
  ui_story_1018_10181401_6_dialog_content = "Eu conheço Forsakin. Ela não arriscaria fazer tudo isso a menos que fosse benéfico para seus experimentos.",
  ui_story_1018_10181401_7_dialog_content = "Sem mencionar que deixar Helios para trás em Gannon provavelmente foi algo que ela não esperava.",
  ui_story_1018_10181401_8_dialog_content = "Isso significa que Forsakin se infiltrou na Cidade Baixa de Illumina porque Ulysses prometeu dar a ela o que ela queria.",
  ui_story_1018_10181401_9_dialog_content = "E Ulysses a enganou. Ele adicionou as Sementes ao Programa Phospherus assim que as obteve.",
  ui_story_1018_10181401_10_dialog_content = "Isso certamente é possível.",
  ui_story_1018_10181401_11_dialog_content = "Então o núcleo do Guardião Um também faz parte do acordo?",
  ui_story_1018_10181401_12_dialog_content = "Faz parte do plano do Eclipse, mas ainda não está claro se estava em seu acordo.",
  ui_story_1018_10181401_13_dialog_content = "Estou mais inclinado a acreditar que o roubo do núcleo não fazia parte do plano de Ulysses.",
  ui_story_1018_10181401_14_dialog_content = "O Comitê não tinha motivo para perder o núcleo para o Eclipse em favor do Programa Phospherus.",
  ui_story_1018_10181401_15_dialog_content = "Não apenas o custo foi muito alto, mas mesmo que os soldados implantados com as Sementes conseguissem, eles não seriam capazes de lutar nas batalhas futuras.",
  ui_story_1018_10181401_16_dialog_content = "O que você disse?",
  ui_story_1018_10181401_17_dialog_content = "...",
  ui_story_1018_10181401_18_dialog_content = "...",
  ui_story_1018_10181401_19_dialog_content = "Você foi implantado com uma Semente...?",
  ui_story_1018_10181401_20_dialog_content = "E daí? Ainda estou bem, não estou?",
  ui_story_1018_10181401_21_dialog_content = "...",
  ui_story_1018_10181401_22_dialog_content = "Vejo que insisti em torná-lo o Grande Marechal apenas para que você recebesse o implante...",
  ui_story_1018_10181401_23_dialog_content = "Não tem nada a ver com você. Foi minha decisão.",
  ui_story_1018_10181401_24_dialog_content = "Eu não deveria ter...",
  ui_story_1018_10181401_25_dialog_content = "De jeito nenhum ela teria chegado até aqui sozinha sem a minha Semente!",
  ui_story_1018_10181401_26_dialog_content = "Finalmente se revelou, Forsakin.",
  ui_story_1018_10181401_27_dialog_content = "Você, escória imunda!",
  ui_story_1018_10181401_28_dialog_content = "Forsakin, você fez meus soldados sofrerem. Agora é hora de acabar com isso!",
  ui_story_1018_10181401_29_dialog_content = "Espere, Wrath, há soldados na lama atrás dela!",
  ui_story_1018_10181401_30_dialog_content = "Rugido...",
  ui_story_1018_10181401_31_dialog_content = "Não acredito que ela se rebaixou tanto assim...",
  ui_story_1018_10181401_32_dialog_content = "Mantenha-os sob controle e proteja a linha! Eu cuido disso!",
  ui_story_1018_10181401_33_dialog_content = "Entendido!",
  ui_story_1018_10181401_34_dialog_content = "Bem animado, pelo que vejo. Não quer saber por que a Semente em você não te deixou de cabeça para baixo?",
  ui_story_1018_10181401_35_dialog_content = "Ou você realmente ama massacrar seus companheiros em um frenesi de sangue?",
  ui_story_1018_10181401_36_dialog_content = "Cala a boca, Forsakin, foi você quem prejudicou os soldados.",
  ui_story_1018_10181401_37_dialog_content = "...",
  ui_story_1018_10181401_38_dialog_content = "Então foi você quem me curou na lama...",
  ui_story_1018_10181401_39_dialog_content = "Você torturou meus soldados, me levou ao limite... Tudo para ver como eu reagiria com a Semente dentro de mim...",
  ui_story_1018_10181401_40_dialog_content = "Vejo que você não é tão burro quanto eu pensava. Estou apenas ajudando Ulysses por acaso, já que ele é um fracasso épico como cientista.",
  ui_story_1018_10181401_41_dialog_content = "O que o Eclipse prometeu a você, Forsakin?",
  ui_story_1018_10181401_42_dialog_content = "Como você pode entender algo assim? Você acha que tem o poder de proteger tudo?",
  ui_story_1018_10181401_43_dialog_content = "Mesmo com uma reformulação, os Aurorianos ainda são um grupo de fracotes físicos e mentalmente fracos.",
  ui_story_1018_10181401_44_dialog_content = "Em vez de ser usado e descartado pela hierarquia da Illumina mais tarde, você deveria encontrar uma saída agora.",
  ui_story_1018_10181401_45_dialog_content = "Seu alinhamento com o Eclipse faz de você nada mais do que um fantoche Eclipsita.",
  ui_story_1018_10181401_46_dialog_content = "Você acha que é tão inteligente porque estava no projeto Sol Artificial.",
  ui_story_1018_10181401_47_dialog_content = "Mas todos os presentes, além daqueles que caíram em Crepúsculo, chegaram até aqui por vontade própria.",
  ui_story_1018_10181401_48_dialog_content = "Comparado a eles, você é o verdadeiro bobo da corte.",
  ui_story_1018_10181401_49_dialog_content = "Você é quem é fraco e frágil!",
  ui_story_1018_10181401_50_dialog_content = "Cala a boca, seu idiota! Você só está vivo por causa da minha Semente.",
  ui_story_1018_10181401_51_dialog_content = "O mundo não é um conto de fadas para crianças de três anos. Para sobreviver, é preciso subir a escada a todo custo.",
  ui_story_1018_10181401_52_dialog_content = "Vocês, Aurorians ignorantes que se movem como baratas, nunca conhecerão a verdade, nem mesmo na morte.",
  ui_story_1018_10181401_53_dialog_content = "Eu sei que você tem ambições, Forsakin, mas não posso deixar você sacrificar os outros para realizá-las.",
  ui_story_1018_10181401_54_dialog_content = "Esta é a última vez que direi isso a você—",
  ui_story_1018_10181401_55_dialog_content = "Você feriu seu companheiro em Illumina, e Illumina não vai te poupar. Mas eu não sou o Grande Marechal agora e espero que você pare.",
  ui_story_1018_10181401_56_dialog_content = "Pare de responder ao Eclipse. Isso não é o que você realmente quer.",
  ui_story_1018_10181401_57_dialog_content = "Você é quem responde aos outros, Reinhardt! Você não pode proteger todo mundo.",
  ui_story_1018_10181401_58_dialog_content = "E não tenha pena de mim. Eu desisti de querer estar do seu lado há muito tempo.",
  ui_story_1018_10181401_59_dialog_content = "Você pode vir atrás de mim o quanto quiser, mas eu nunca vou parar.",
  ui_story_1018_10181401_60_dialog_content = "<color=#e8d9bb>Estalando—</color>",
  ui_story_1018_10181401_61_dialog_content = "Hum-hum, o discurso de despedida é o seu presente para ela?",
  ui_story_1018_10181401_62_dialog_content = "Tome isso, Wraith!",
  ui_story_1018_10181401_63_dialog_content = "Os soldados já estavam dominados, mas então até mesmo o Wraith apareceu.",
  ui_story_1018_10181401_64_dialog_content = "Se eu quisesse, você já estaria morto agora.",
  ui_story_1018_10181401_65_dialog_content = "Continue falando e eu posso mudar de ideia, Forsakin.",
  ui_story_1018_10181401_66_dialog_content = "Pare de seguir o Eclipse ou você perderá sua vida por causa disso, Forsakin.",
  ui_story_1018_10181401_67_dialog_content = "Isso é problema meu. O que você precisa se preocupar, Reinhardt, é comigo te matando.",
  ui_story_1018_10181401_68_dialog_content = "<color=#e8d9bb>Estalando—</color>",
  ui_story_1018_10181401_69_dialog_content = "A Semente em mim está vibrando levemente... Cuidado, inimigos por perto!",
  ui_story_1018_10181401_70_dialog_content = "*Ânsia*",
  ui_story_1018_10181401_71_dialog_content = "Ah!",
  ui_story_1018_10181401_72_dialog_content = "Está cuspindo aqueles levados do Crepúsculo por Forsakin...",
  ui_story_1018_10181401_73_dialog_content = "Ah!",
  ui_story_1018_10181401_74_dialog_content = "O mecha não havia sido derrotado já? Ele se levantou de novo!",
  ui_story_1018_10181401_75_dialog_content = "Vejo que Forsakin tinha um plano de contingência.",
  ui_story_1018_10181401_76_dialog_content = "As trincheiras estavam cheias de lama, onde o mecha derrotado estava deitado todo esse tempo.",
  ui_story_1018_10181401_77_dialog_content = "Agora o Eclipsita do pântano reapareceu, ele não será derrotado tão facilmente...",
  ui_story_1018_10181401_78_dialog_content = "O que fazemos agora, Grande Marechal?",
  ui_story_1018_10181401_79_dialog_content = "...",
  ui_story_1018_10181401_80_dialog_content = "...",
  ui_story_1018_10181401_81_dialog_content = "É minha culpa que meus soldados não puderam descansar em paz...",
  ui_story_1018_10181401_82_dialog_content = "Juro que vou recuperar os corpos deles, custe o que custar!",
  ui_story_1018_10181401_83_dialog_content = "Mas Forsakin acabou de te machucar...",
  ui_story_1018_10181401_84_dialog_content = "Eu conheço meus limites. Vou me conter de usar esse poder.",
  ui_story_1018_10181401_85_dialog_content = "Vou atacar direto no coração e pulverizá-lo!",
  ui_story_1018_10181401_86_dialog_content = "Vou atacar com você, Wrath. Deixe os soldados enfurecidos comigo.",
  ui_story_1018_10181401_87_dialog_content = "Vamos segurar as linhas!",
  ui_story_1018_10181401_88_dialog_content = "Sim!",
  ui_story_1018_10181401_89_dialog_content = "Grande Marechal—",
  ui_story_1018_10181401_90_dialog_content = "Como é que você está...",
  ui_story_1018_10181401_91_dialog_content = "Os Lumo Skyriders fornecerão cobertura. Os Eclipsitas não tocarão em você.",
  ui_story_1018_10181401_92_dialog_content = "Estou muito familiarizado com a estratégia do Grande Marechal. Os Cavaleiros do Crepúsculo complementarão a investida.",
  ui_story_1018_10181401_93_dialog_content = "E eu também, Wrath, vou te ajudar na luta!",
  ui_story_1018_10181401_94_dialog_content = "Noite Branca nas alturas... Que coalizão multifacetada temos!",
  ui_story_1018_10181401_95_dialog_content = "Então vamos cumprir nossos respectivos papéis e nos reunir após destruir o inimigo!",
  ui_story_1018_10181401_96_dialog_content = "O que você diz, Reinhardt?",
  ui_story_1018_10181401_97_dialog_content = "De qualquer forma, nunca deixe os companheiros de Illumina para trás!",
  ui_story_1018_10181501_1_dialog_content = "<color=#e8d9bb>Pitter-patter...</color>",
  ui_story_1018_10181501_2_dialog_content = "Ei, está chovendo...",
  ui_story_1018_10181501_3_dialog_content = "Isso é bastante incomum.",
  ui_story_1018_10181501_4_dialog_content = "Nenhum sinal de Eclipsitas em lugar algum, Grande Marechal.",
  ui_story_1018_10181501_5_dialog_content = "As unidades de Lumópolis estão indo para as linhas leste e oeste.",
  ui_story_1018_10181501_6_dialog_content = "Está bom aqui onde estou. A lama está diminuindo e tudo está uma maravilha!",
  ui_story_1018_10181501_7_dialog_content = "Wrath com certeza sabe como lutar!",
  ui_story_1018_10181501_8_dialog_content = "A chuva poderia fazer a lama recuar?",
  ui_story_1018_10181501_9_dialog_content = "Eu não percebi isso. Isso pode significar que realmente acabou agora...",
  ui_story_1018_10181501_10_dialog_content = "Você está acordado. Se sentindo bem?",
  ui_story_1018_10181501_11_dialog_content = "Eu estive acordado, apenas pensando no que você me disse antes...",
  ui_story_1018_10181501_12_dialog_content = "<color=#e8d9bb>Antes de Wrath partir para encontrar Ulysses...</color>",
  ui_story_1018_10181501_13_dialog_content = "Por quanto tempo você vai ficar aí dentro?",
  ui_story_1018_10181501_14_dialog_content = "O que há para dizer? Você ouviu a pergunta—",
  ui_story_1018_10181501_15_dialog_content = "Reinhardt!",
  ui_story_1018_10181501_16_dialog_content = "Você acha que eu cairia em algo tão estúpido quanto você conspirando com o inimigo?",
  ui_story_1018_10181501_17_dialog_content = "...",
  ui_story_1018_10181501_18_dialog_content = "Você estava tão calado assim quando se inscreveu no Sol Artificial?",
  ui_story_1018_10181501_19_dialog_content = "Você descobriu, entendi.",
  ui_story_1018_10181501_20_dialog_content = "Você passou por modificações. É assim que conseguiu me vencer no duelo?",
  ui_story_1018_10181501_21_dialog_content = "...",
  ui_story_1018_10181501_22_dialog_content = "Responda-me!",
  ui_story_1018_10181501_23_dialog_content = "Muitas coisas não são tão simples quanto você imagina. Pare de perguntar, pelo bem da Illumina.",
  ui_story_1018_10181501_24_dialog_content = "Como um honrado Grande Marechal, você poderia ter—",
  ui_story_1018_10181501_25_dialog_content = "É por isso que devo aceitar esse resultado.",
  ui_story_1018_10181501_26_dialog_content = "...",
  ui_story_1018_10181501_27_dialog_content = "Relaxe o punho se você entendeu. Agora não é hora de arrumar uma briga comigo.",
  ui_story_1018_10181501_28_dialog_content = "...",
  ui_story_1018_10181501_29_dialog_content = "Seu futuro está na palma da sua mão.",
  ui_story_1018_10181501_30_dialog_content = "Mantenha-o enrolado e você acabará sem nada.",
  ui_story_1018_10181501_31_dialog_content = "\"Mantendo-o enrolado e acabaremos sem nada.\"",
  ui_story_1018_10181501_32_dialog_content = "Por que eu me lembraria disso agora...",
  ui_story_1018_10181501_33_dialog_content = "É porque chegou a hora de balançarmos nossos punhos contra o inimigo comum.",
  ui_story_1018_10181501_34_dialog_content = "Punhos cerrados devem ser apontados para o inimigo comum.",
  ui_story_1018_10181501_35_dialog_content = "...",
  ui_story_1018_10181501_36_dialog_content = "Confie em mim, você perceberá o poder que eu tenho.",
  ui_story_1018_10181501_37_dialog_content = "Isso faz parte do seu plano?",
  ui_story_1018_10181501_38_dialog_content = "...",
  ui_story_1018_10181501_39_dialog_content = "Está pronto para me deixar fazer o que for necessário...?",
  ui_story_1018_10181501_40_dialog_content = "...",
  ui_story_1018_10181501_41_dialog_content = "Entendido.",
  ui_story_1018_10181501_42_dialog_content = "Vou substituí-lo como Grande Marechal.",
  ui_story_1018_10181501_43_dialog_content = "Mas chegará um momento em que você será meu único oponente.",
  ui_story_1018_10181501_44_dialog_content = "Antes disso, porém, vamos erguer nossos punhos e derrotar nosso inimigo comum.",
  ui_story_1018_10181501_45_dialog_content = "Wrath.",
  ui_story_1018_10181501_46_dialog_content = "Hã?",
  ui_story_1018_10181501_47_dialog_content = "Faça o que for necessário, mas certifique-se de voltar vivo.",
  ui_story_1018_10181501_48_dialog_content = "...",
  ui_story_1018_10181501_49_dialog_content = "<color=#e8d9bb>Pitter-patter...</color>",
  ui_story_1018_10181501_50_dialog_content = "Consegui voltar vivo, mas os soldados... Eles estão além de qualquer ajuda, certo?",
  ui_story_1018_10181501_51_dialog_content = "Eles se saíram bem apenas por aguentar até agora.",
  ui_story_1018_10181501_52_dialog_content = "Eles são verdadeiros guerreiros. Illumina lhes dará o devido respeito.",
  ui_story_1018_10181501_53_dialog_content = "Falhei em salvá-los em Crepúsculo... Então tive que matá-los novamente como se fossem inimigos...",
  ui_story_1018_10181501_54_dialog_content = "Outro fracasso...",
  ui_story_1018_10181501_55_dialog_content = "Mesmo me tornando o Grande Marechal, ainda estou destinado a falhar.",
  ui_story_1018_10181501_56_dialog_content = "Você não falhou, Wrath. Você liderou a todos na salvação de Crepúsculo e na manutenção da linha.",
  ui_story_1018_10181501_57_dialog_content = "A chuva está caindo forte. Vamos voltar.",
  ui_story_1018_10181501_58_dialog_content = "...",
  ui_story_1018_10181501_59_dialog_content = "Vamos voltar. A previsão disse que o tempo está ruim hoje. Provavelmente está chovendo na superfície.",
  ui_story_1018_10181501_60_dialog_content = "<color=#e8d9bb>Clank—</color>",
  ui_story_1018_10181501_61_dialog_content = "Heh... Reinhardt...",
  ui_story_1018_10181501_62_dialog_content = "Do que você está rindo?",
  ui_story_1018_10181501_63_dialog_content = "Um Grande Marechal está condenado a sentir tal desespero a qualquer momento?",
  ui_story_1018_10181501_64_dialog_content = "Quando fechei os olhos, pude ver os guerreiros se sacrificando em Crepúsculo...",
  ui_story_1018_10181501_65_dialog_content = "Para evitar se transformarem em Eclipsitas e machucar as pessoas, eles escolheram atirar em suas próprias cabeças...",
  ui_story_1018_10181501_66_dialog_content = "Axelia foi danificada inúmeras vezes, mas se levantou após cada uma apenas para salvar sua equipe...",
  ui_story_1018_10181501_67_dialog_content = "Então havia aquele sujeito, morrendo de vontade de voltar para Illumina no último fio de sua sanidade...",
  ui_story_1018_10181501_68_dialog_content = "Todos nós queremos vencer a guerra, mas isso exige um grande custo...",
  ui_story_1018_10181501_69_dialog_content = "Você deve ter passado por cenários semelhantes inúmeras vezes...",
  ui_story_1018_10181501_70_dialog_content = "Mas, em todos os seus anos como Grande Marechal, nunca vi um sinal de arrependimento em você.",
  ui_story_1018_10181501_71_dialog_content = "Você até se rendeu no campo de batalha para proteger Axelia.",
  ui_story_1018_10181501_72_dialog_content = "E jogado em uma cela com seu destino ditado por outros, tudo pelo futuro da Illumina.",
  ui_story_1018_10181501_73_dialog_content = "Só você poderia ter feito tudo isso, Reinhardt.",
  ui_story_1018_10181501_74_dialog_content = "...",
  ui_story_1018_10181501_75_dialog_content = "O Grande Marechal é um voto, uma crença, um guarda-chuva... Alguém que não pode morrer e deve continuar lamentando pelos outros.",
  ui_story_1018_10181501_76_dialog_content = "O Grande Marechal é alguém que protege o povo com sua própria carne e sangue.",
  ui_story_1018_10181501_77_dialog_content = "Só eu poderia ter feito isso? Bem, você se manteve firme até agora para preservar Illumina por conta própria.",
  ui_story_1018_10181501_78_dialog_content = "É isso mesmo...",
  ui_story_1018_10181501_79_dialog_content = "<color=#e8d9bb>A chuva lava o solo lamacento enquanto um brilho tênue filtra através das distantes camadas de nuvens.</color>",
  ui_story_1018_10181501_80_dialog_content = "<color=#e8d9bb>Os ombros de Wrath são esguios, mas enquanto ela se mantém resoluta e forte no jogo de luz e sombra, seus contornos se tornam mais nítidos e eretos.</color>",
  ui_story_1018_10181501_81_dialog_content = "Mas tenho certeza de que não quero mais ser o Grande Marechal...",
  ui_story_1018_10181501_82_dialog_content = "Você carregou o peso por mim na crise. Agora é a hora de eu retomar o dever.",
  ui_story_1018_10181501_83_dialog_content = "Os problemas que estão surgindo são igualmente desafiadores, mas confie em mim, eu vou eliminar todos os inimigos por dentro.",
  ui_story_1018_10181501_84_dialog_content = "Como você planeja lidar com o Comitê?",
  ui_story_1018_10181501_85_dialog_content = "Nós comandamos o exército, Grande Marechal. Basta dar a ordem e eu vou arruinar o dia deles!",
  ui_story_1018_10181501_86_dialog_content = "O fato de eu estar aqui para lutar significa que temos a aprovação silenciosa do Comitê.",
  ui_story_1018_10181501_87_dialog_content = "Eles não aceleraram o Programa Phospherus apenas por Crepúsculo.",
  ui_story_1018_10181501_88_dialog_content = "Com o aumento do Darkover e o roubo do núcleo do Guardião Um, o que a Eclipse está tramando é a maior preocupação.",
  ui_story_1018_10181501_89_dialog_content = "Eles não vão te colocar de volta em uma cela se você voltar para Gannon, vão?",
  ui_story_1018_10181501_90_dialog_content = "O que tem acontecido com os soldados fará com que sejam Ulysses chamados à atenção.",
  ui_story_1018_10181501_91_dialog_content = "De qualquer maneira que você analise, Belisaria é respeitado. Eles tomarão a decisão certa a meu respeito.",
  ui_story_1018_10181501_92_dialog_content = "Falando em Eclipse, enviamos dois esquadrões para a Zona Escura, Grande Marechal.",
  ui_story_1018_10181501_93_dialog_content = "Não sei qual é o plano do Comitê, mas acho que Charon e Vice precisam da nossa ajuda.",
  ui_story_1018_10181501_94_dialog_content = "Isso é verdade... Eles se encontraram comigo brevemente e atualmente não estão em uma boa situação...",
  ui_story_1018_10181501_95_dialog_content = "O que você vai fazer, PlayerName?",
  ui_story_1018_10181501_96_dialog_content = "Ainda há refugiados do Crepúsculo em Eraveil, então vou voltar com Leo para ajudar.",
  ui_story_1018_10181501_97_dialog_content = "Mas também estou muito preocupado com Vice e os outros...",
  ui_story_1018_10181501_98_dialog_content = "Eu não vou deixá-los se machucar, PlayerName, eu posso prometer isso.",
  ui_story_1018_10181501_99_dialog_content = "Não importa que tipo de golpe o Comitê possa dar mais tarde, vou priorizar encontrá-los.",
  ui_story_1018_10181501_100_dialog_content = "Então, eu vou lidar com os problemas em Crepúsculo. Depois de lutar lado a lado com Leo por tanto tempo, eu quero que Illumina dê alguma esperança à cidade.",
  ui_story_1018_10181501_101_dialog_content = "E não se esqueça de buscar tratamento rapidamente...",
  ui_story_1018_10181501_102_dialog_content = "Entendi. Entrarei em contato com você se não houver outra opção.",
  ui_story_1018_10181501_103_dialog_content = "Claro, se eu puder ajudar.",
  ui_story_1018_10181501_104_dialog_content = "<color=#e8d9bb>*Estático*</color>",
  ui_story_1018_10181501_105_dialog_content = "Tudo isso se transformou em um grande espetáculo, não, uma comédia. E nosso dramaturgo Ulysses nem tem coragem de aparecer na reunião de hoje.",
  ui_story_1018_10181501_106_dialog_content = "Como você planeja encerrar isso?",
  ui_story_1018_10181501_107_dialog_content = "Ainda não é hora de jogar a toalha.",
  ui_story_1018_10181501_108_dialog_content = "Você está brincando comigo? Os dois Grandes Marechais de Illumina acabaram de obter uma grande vitória no campo de batalha.",
  ui_story_1018_10181501_109_dialog_content = "Você realmente acha que eles viriam rastejando até você para negociações pacíficas?",
  ui_story_1018_10181501_110_dialog_content = "Você acha que eu não sabia que Reinhardt saiu de uma cela da Illumina?",
  ui_story_1018_10181501_111_dialog_content = "Ainda não é hora da evidência chave. Como isso se desenrola depende da atitude deles.",
  ui_story_1018_10181501_112_dialog_content = "Clássico movimento de Belisaria, nunca deixando as coisas sem um plano B.",
  ui_story_1018_10181501_113_dialog_content = "Mas essa batalha nas linhas defensivas não é apenas um confronto - todo o continente Astra está de olho.",
  ui_story_1018_10181501_114_dialog_content = "Correto, todos estão observando e, esperamos, ainda mais de perto.",
  ui_story_1018_10181501_115_dialog_content = "Se a Crise Darkover acontecer, até que ponto cada facção irá?",
  ui_story_1018_10181501_116_dialog_content = "Você está apoiando o plano de Ulysses para fazer Lumopolis finalmente mostrar suas cartas, hein?",
  ui_story_1018_10181501_117_dialog_content = "Essa é uma parte, sim.",
  ui_story_1018_10181501_118_dialog_content = "Seja em Crepúsculo ou na linha de frente, todos vocês viram que ainda somos uma ameaça para os Eclipsitas.",
  ui_story_1018_10181501_119_dialog_content = "E eles até mostraram seu cartão de buraco.",
  ui_story_1018_10181501_120_dialog_content = "Você quer dizer aquela garota?",
  ui_story_1018_10181501_121_dialog_content = "Sim, mas com certeza não é só isso.",
  ui_story_1018_10181501_122_dialog_content = "Quem diria? Este é o próprio \"exercício militar\" que você, Belisaria, estava esperando presenciar.",
  ui_story_1018_10181501_123_dialog_content = "Vamos deixar outras coisas de lado por enquanto. Diante do imenso custo, você já considerou as consequências?",
  ui_story_1018_10181501_124_dialog_content = "Estou disposto a ouvir qualquer pessoa com um plano melhor.",
  ui_story_1018_10181501_125_dialog_content = "A arma do Eclipse desta vez ainda são as Sementes de Forsakin, mas pelo menos agora nós também as temos.",
  ui_story_1018_10181501_126_dialog_content = "É por isso que eu apoio o Ulysses.",
  ui_story_1018_10181501_127_dialog_content = "No futuro, devemos apreender todas as armas que possam potencialmente nos destruir.",
  ui_story_1018_10181501_128_dialog_content = "Seja em Lumopolis ou Northland, e até mesmo cultos radicais.",
  ui_story_1018_10181501_129_dialog_content = "O núcleo do Guardião Um foi roubado e sua maior preocupação é o equilíbrio entre essas facções?",
  ui_story_1018_10181501_130_dialog_content = "Sem prioridades. Ser pressionado de todos os lados é o atual dilema da Illumina.",
  ui_story_1018_10181501_131_dialog_content = "Aquele Engenheiro que saiu de Illumina não foi criticado apenas por Lumópolis.",
  ui_story_1018_10181501_132_dialog_content = "Dadas as circunstâncias, provavelmente precisamos mudar de rumo e mostrar a todos quem realmente é o Engenheiro.",
  ui_story_1018_10181501_133_dialog_content = "Você tem certeza disso?",
  ui_story_1018_10181501_134_dialog_content = "A notícia da Equipe de Reconhecimento da Zona Cega é como esperado.",
  ui_story_1018_10181501_135_dialog_content = "O núcleo do Guardião Um é exatamente a peça final para o reavivamento do Engenheiro.",
  ui_story_1018_10181501_136_dialog_content = "Já que a campanha na frente acabou, o Engenheiro deve acordar em breve.",
  ui_story_1018_10181501_137_dialog_content = "...",
  ui_story_1018_10181501_138_dialog_content = "O Engenheiro, o primeiro verdadeiro Senhor da Cidade de Gannon.",
  ui_story_1018_10181501_139_dialog_content = "Se algo tão antigo quanto isso realmente despertar, bem... Estou meio ansioso para isso.",
  ui_story_1018_10181501_140_dialog_content = "Heh, ainda mais para mim.",
  ui_story_1018_10181501_141_dialog_content = "*Estático*",
  ui_story_1018_10181501_142_dialog_content = "De novo?",
  ui_story_1018_10181501_143_dialog_content = "Não... Eu...",
  ui_story_1018_10181501_144_dialog_content = "Parece... Motor...",
  ui_story_1018_10181501_145_dialog_content = "Despertou...",
  ui_story_1019_10190101_1_dialog_content = "<color=#e8d9bb>Zumbido...</color>",
  ui_story_1019_10190101_2_dialog_content = "De fato, a Semente não aprimora habilidades, mas as converte.",
  ui_story_1019_10190101_3_dialog_content = "Então, mesmo quando seu acesso central é duplicado, o Darkflow ainda pode corromper no pântano...",
  ui_story_1019_10190101_4_dialog_content = "Ha... Como você chegou a isso?",
  ui_story_1019_10190101_5_dialog_content = "(Tosse seca)",
  ui_story_1019_10190101_6_dialog_content = "Deve estar por aqui em algum lugar...",
  ui_story_1019_10190101_7_dialog_content = "... Mas esses resultados definitivamente valem os assuntos que morreram em Crepúsculo.",
  ui_story_1019_10190101_8_dialog_content = "<color=#e8d9bb>Clam—</color>",
  ui_story_1019_10190101_9_dialog_content = "As últimas três pílulas...",
  ui_story_1019_10190101_10_dialog_content = "Quarenta anos de pesquisa, e vinte deles dedicados à compilação do <color=#FFB400>banco de dados de genes especiais</color>... Eu fiz tudo o que pude.",
  ui_story_1019_10190101_11_dialog_content = "Mas por que ainda me sinto amargo e insatisfeito?",
  ui_story_1019_10190101_12_dialog_content = "Estou dificilmente satisfeito com o resultado, <color=#FFB400>Robby</color>...",
  ui_story_1019_10190101_13_dialog_content = "<color=#e8d9bb>Swish... Swoosh...</color>",
  ui_story_1019_10190101_14_dialog_content = "Que vento forte...",
  ui_story_1019_10190101_15_dialog_content = "Espere, como é que eu estou nas nuvens?",
  ui_story_1019_10190101_16_dialog_content = "Essa sensação de leveza é familiar... Eu não estou caindo de novo, estou?!",
  ui_story_1019_10190101_17_dialog_content = "Tenho que ficar calmo! Soroz vai me pegar.",
  ui_story_1019_10190101_18_dialog_content = "Você está me chamando, Navegador?",
  ui_story_1019_10190101_19_dialog_content = "O seu voo hoje combina com o quão revirado meu estômago tem se sentido ultimamente. Para onde estamos indo?",
  ui_story_1019_10190101_20_dialog_content = "Estamos indo para o <color=#FFB400>Campo de Batalha da Torre</color> para uma missão de lançamento aéreo.",
  ui_story_1019_10190101_21_dialog_content = "... Uma missão de airdrop? Para quem?",
  ui_story_1019_10190101_22_dialog_content = "A seguinte diretiva de combate foi transmitida a todos os navegadores:",
  ui_story_1019_10190101_23_dialog_content = "\"Todos os navegadores, por favor, dirijam-se ao Campo de Batalha da Torre para largar suas armas.\"",
  ui_story_1019_10190101_24_dialog_content = "Velocidade reduzida para a descida final. Aguardando ordens, Navegador. Por favor, garanta o pouso seguro das armas.",
  ui_story_1019_10190101_25_dialog_content = "E-Espere, do que você está falando?!",
  ui_story_1019_10190101_26_dialog_content = "Soroz? Soroz...!",
  ui_story_1019_10190101_27_dialog_content = "Ahhhhhhhh!!!",
  ui_story_1019_10190101_28_dialog_content = "Rugidoooo!",
  ui_story_1019_10190101_29_dialog_content = "De onde vieram esses Eclipsitas?! Por que... estou caindo com os Eclipsitas?!",
  ui_story_1019_10190101_30_dialog_content = "Soroz! O que está acontecendo?!",
  ui_story_1019_10190101_31_dialog_content = "Navegador, por favor, garanta que todas as armas aterrissem em segurança. Este é o seu dever como um Celestita.",
  ui_story_1019_10190101_32_dialog_content = "Rugidoooo!",
  ui_story_1019_10190101_33_dialog_content = "Absurdo... I-Isto deve ser um sonho!",
  ui_story_1019_10190101_34_dialog_content = "Navegador, você não está sonhando.",
  ui_story_1019_10190101_35_dialog_content = "As coordenadas confirmam que este é o Campo de Batalha da Torre. Por favor, certifique-se de que todas as armas pousem com segurança.",
  ui_story_1019_10190101_36_dialog_content = "Torre...? Mas isso é Eraveil! Eu reconheço aquele alto Obelisco do Retorno!",
  ui_story_1019_10190101_37_dialog_content = "São aqueles... Caelestites correndo por toda parte no chão? Ou são eles...",
  ui_story_1019_10190101_38_dialog_content = "Isso é um sonho. Isso deve ser um sonho! Talvez eu acorde depois de cair no chão...",
  ui_story_1019_10190101_39_dialog_content = "Dane-se isso!",
  ui_story_1019_10190101_40_dialog_content = "...",
  ui_story_1019_10190101_41_dialog_content = "... Ainda estou no ar...",
  ui_story_1019_10190101_42_dialog_content = "Quando você se resigna a uma queda inevitável, por algum motivo a jornada para baixo se torna extremamente longa...",
  ui_story_1019_10190101_43_dialog_content = "<color=#e8d9bb>Estrondo-!!!</color>",
  ui_story_1019_10190101_44_dialog_content = "Aah—!",
  ui_story_1019_10190101_45_dialog_content = "...",
  ui_story_1019_10190101_46_dialog_content = "Você está acordado agora?",
  ui_story_1019_10190101_47_dialog_content = "Noite Branca nas alturas, chegamos em segurança.",
  ui_story_1019_10190101_48_dialog_content = "Leo... Joselyne? Onde nós estamos...?",
  ui_story_1019_10190101_49_dialog_content = "De volta em Eraveil.",
  ui_story_1019_10190101_50_dialog_content = "O dirigível balançava tanto que os soldados mal conseguiam ficar de pé, mas você estava dormindo profundamente...",
  ui_story_1019_10190101_51_dialog_content = "Eraveil...",
  ui_story_1019_10190101_52_dialog_content = "Certo... sim, isso é Eraveil...",
  ui_story_1019_10190101_53_dialog_content = "Após as campanhas em Crepúsculo e na linha defensiva de Illumina, pegamos um dirigível de Lumopolis de volta para Eraveil...",
  ui_story_1019_10190101_54_dialog_content = "Então foi tudo apenas um sonho... Ufa!",
  ui_story_1019_10190101_55_dialog_content = "Tem certeza de que está bem, correndo assim?",
  ui_story_1019_10190101_56_dialog_content = "Estou bem! Isso é maravilhoso, Leo!",
  ui_story_1019_10190101_57_dialog_content = "A sensação de ausência de peso parecia tão real, como reviver uma memória...",
  ui_story_1019_10190101_58_dialog_content = "Mas foi um sonho... Graças a Deus foi um sonho!",
  ui_story_1019_10190101_59_dialog_content = "Uh, você pode me soltar agora...",
  ui_story_1019_10190101_60_dialog_content = "<color=#e8d9bb>(Aconchegar-se)</color>",
  ui_story_1019_10190101_61_dialog_content = "Meus sapatos estão sujos, PlayerName. Provavelmente você não deveria pisar neles.",
  ui_story_1019_10190101_62_dialog_content = "Oh, desculpe... Mas acho que não sou eu...",
  ui_story_1019_10190101_63_dialog_content = "Chubb... Chubb...",
  ui_story_1019_10190101_64_dialog_content = "O que é essa coisa branca em forma de cubo, e por que está abraçando minhas botas?",
  ui_story_1019_10190101_65_dialog_content = "Esse é o Chubb, meu amigo de Eraveil. Mas por que ele parece bêbado?",
  ui_story_1019_10190101_66_dialog_content = "Chubb... (Arroto)",
  ui_story_1019_10190101_67_dialog_content = "Ei! Capitão Leo! Senhora Santa! Celestita!",
  ui_story_1019_10190101_68_dialog_content = "Você finalmente voltou!",
  ui_story_1019_10190101_69_dialog_content = "Quando os homens ouviram que você expulsou os Eclipsitas de Crepúsculo, eles imediatamente começaram a voltar!",
  ui_story_1019_10190101_70_dialog_content = "As senhoras da cervejaria e eu decidimos preparar comida e vinho para recompensar todos os soldados!",
  ui_story_1019_10190101_71_dialog_content = "Embora este vinho não tenha sido fermentado por muito tempo, as frutas Eraveil usadas para fazê-lo dão um sabor único.",
  ui_story_1019_10190101_72_dialog_content = "Então Chubb tinha vinho de fruta...",
  ui_story_1019_10190101_73_dialog_content = "Celestita, o Grande Marechal Wrath está bem? Por que eu não a vi?",
  ui_story_1019_10190101_74_dialog_content = "Wrath está mais ou menos bem, mas ainda teve que retornar para Illumina para se recuperar.",
  ui_story_1019_10190101_75_dialog_content = "Isso é uma ótima notícia! Eu realmente quero agradecer pessoalmente a todos os soldados que defenderam Crepúsculo.",
  ui_story_1019_10190101_76_dialog_content = "Ah, certo, Celestita. Obrigado por nos acolher!",
  ui_story_1019_10190101_77_dialog_content = "Não tínhamos muito o que fazer aqui, então alimentamos os peixes, produzimos vinho e removemos pragas das árvores frutíferas...",
  ui_story_1019_10190101_78_dialog_content = "Eu limpo meu quarto todos os dias! Além disso, as bandeiras penduradas no topo das árvores foram especialmente projetadas para receber você e todos os cavaleiros para o seu retorno triunfante...",
  ui_story_1019_10190101_79_dialog_content = "Vocês fizeram tanto...",
  ui_story_1019_10190101_80_dialog_content = "Por favor, aceite nossa boa vontade como agradecimento por nos acolher aqui em Eraveil!",
  ui_story_1019_10190101_81_dialog_content = "Eu deveria ser o único agradecendo a você! Eraveil nunca esteve tão movimentada...",
  ui_story_1019_10190101_82_dialog_content = "Você pode ficar em Eraveil o tempo que quiser.",
  ui_story_1019_10190101_83_dialog_content = "Bem, isso certamente significa muito menos vinho fino em Crepúsculo.",
  ui_story_1019_10190101_84_dialog_content = "Noite Branca nas alturas. Obrigado por tudo que você fez pelo Twilight, PlayerName.",
  ui_story_1019_10190101_85_dialog_content = "Chubb! Ch... Arroto! Nngh...",
  ui_story_1019_10190101_86_dialog_content = "<color=#e8d9bb>Saúde!!!</color>",
  ui_story_1019_10190101_87_dialog_content = "Não achei que sua viagem para Lumópolis seria tão agitada. Ótimo trabalho fazendo tudo sozinho.",
  ui_story_1019_10190101_88_dialog_content = "Não foi nada. Contanto que tudo tenha dado certo para o Crepúsculo, tudo o que eu fiz valeu a pena.",
  ui_story_1019_10190101_89_dialog_content = "Eu sabia que estava certo sobre você. Saúde!",
  ui_story_1019_10190101_90_dialog_content = "...",
  ui_story_1019_10190101_91_dialog_content = "O que há de errado? Nem mesmo uma bebida após a batalha?",
  ui_story_1019_10190101_92_dialog_content = "Não posso beber muito por causa da minha condição, então deixarei a bebida para vocês. Não vejo uma cena assim há muitos anos.",
  ui_story_1019_10190101_93_dialog_content = "Eu concordo.",
  ui_story_1019_10190101_94_dialog_content = "Mas eu os conheço bem. Mesmo enquanto bebem e riem, Crepúsculo ainda está em suas mentes.",
  ui_story_1019_10190101_95_dialog_content = "Todos carregam o peso da ansiedade sobre eles, exceto por aquelas criaturas de cubo branco que estão livres de preocupações.",
  ui_story_1019_10190101_96_dialog_content = "Então, decidi voltar amanhã.",
  ui_story_1019_10190101_97_dialog_content = "Guerreiros dormem ao cheiro de pólvora. Depois de acabarmos com essas bebidas, é hora de se preparar para a próxima batalha.",
  ui_story_1019_10190101_98_dialog_content = "<color=#e8d9bb>A festa jubilosa continua até tarde da noite...</color>",
  ui_story_1019_10190101_99_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1019_10190101_100_dialog_content = "Ah, é você. Como estão as coisas em Eraveil?",
  ui_story_1019_10190101_101_dialog_content = "Bastante bem...",
  ui_story_1019_10190101_102_dialog_content = "Vendo que você está me contatando tão tarde da noite, presumo que você queira uma atualização sobre Vice?",
  ui_story_1019_10190101_103_dialog_content = "Sim... Alguma notícia sobre Vice e os outros?",
  ui_story_1019_10190101_104_dialog_content = "Há notícias, mas ainda não posso lhe dar nada definitivo sobre o status exato deles.",
  ui_story_1019_10190101_105_dialog_content = "Sério? O que você sabe?!",
  ui_story_1019_10190101_106_dialog_content = "A equipe de rastreamento liderada por Charon tem enviado sinais de volta. É assim que nossas equipes de reconhecimento comunicam que as coisas estão indo bem.",
  ui_story_1019_10190101_107_dialog_content = "Mas digamos que eles se depararam com algo problemático, como em Crepúsculo–",
  ui_story_1019_10190101_108_dialog_content = "Já ouvi falar disso, é por isso que ainda estou tentando confirmar o que está acontecendo. Não se preocupe. Eu te aviso quando tiver algo.",
  ui_story_1019_10190101_109_dialog_content = "Então, o que eu posso fazer agora? Eu estava na batalha em Crepúsculo. Talvez eu possa ajudar de alguma forma.",
  ui_story_1019_10190101_110_dialog_content = "Você não precisa fazer nada, PlayerName.",
  ui_story_1019_10190101_111_dialog_content = "Mas–",
  ui_story_1019_10190101_112_dialog_content = "Eu agradeço o pensamento, mas agora não é a hora de vir para a Illumina.",
  ui_story_1019_10190101_113_dialog_content = "Desde que perdemos o núcleo do Guardião Um, tem havido problemas nas defesas de Gannon, e é nisso que estamos trabalhando.",
  ui_story_1019_10190101_114_dialog_content = "A coragem e boa vontade que você mostrou em Crepúsculo é a maior ajuda que você poderia me dar.",
  ui_story_1019_10190101_115_dialog_content = "Vou cuidar das coisas daqui. Olha, está tarde. Vá descansar um pouco.",
  ui_story_1019_10190101_116_dialog_content = "Tá bom...",
  ui_story_1019_10190101_117_dialog_content = "...",
  ui_story_1019_10190101_118_dialog_content = "Você não consegue dormir porque está preocupado com a segurança de Vice.",
  ui_story_1019_10190101_119_dialog_content = "Sim...",
  ui_story_1019_10190101_120_dialog_content = "<color=#e8d9bb>Você conta silenciosamente por 20 segundos e anota sua frequência cardíaca.</color>",
  ui_story_1019_10190101_121_dialog_content = "Soroz...",
  ui_story_1019_10190101_122_dialog_content = "Soroz está sempre aqui.",
  ui_story_1019_10190101_123_dialog_content = "A meditação de 20 segundos parece estar funcionando. Estou alcançando meu lugar feliz.",
  ui_story_1019_10190101_124_dialog_content = "...",
  ui_story_1019_10190101_125_dialog_content = "Recuperei dados de imagem dos seus momentos mais felizes. Você fazia parada de cabeça quando estava feliz como uma criança pequena.",
  ui_story_1019_10190101_126_dialog_content = "Parada de cabeça?!",
  ui_story_1019_10190101_127_dialog_content = "Você até exigiu que eu fizesse isso por você também, independentemente do que seja.",
  ui_story_1019_10190101_128_dialog_content = "Bem, uma parada de cabeça agora é difícil, para você e para mim.",
  ui_story_1019_10190101_129_dialog_content = "De acordo com meus cálculos, a probabilidade de Soroz fazer uma parada de cabeça bem-sucedida é de 59%. Você precisaria encontrar um lugar seguro caso eu execute tal manobra.",
  ui_story_1019_10190101_130_dialog_content = "O quê? Haha! Obrigado pelo aviso, Soroz, mas acho que estamos bem assim.",
  ui_story_1019_10190101_131_dialog_content = "Faz muito tempo que eu simplesmente sentei no controle sem fazer nada, sem me importar com o mundo...",
  ui_story_1019_10190101_132_dialog_content = "Você realizou muitas coisas depois que meu Modelo Eco foi danificado.",
  ui_story_1019_10190101_133_dialog_content = "Sim. Provavelmente você ainda não sabe o que aconteceu, pensando bem...",
  ui_story_1019_10190101_134_dialog_content = "Depois que seu Modelo de Eco foi danificado, seguimos suas coordenadas e encontramos uma chave em uma cidade subterrânea.",
  ui_story_1019_10190101_135_dialog_content = "Em seguida, seguimos o próximo conjunto de coordenadas para Eraveil.",
  ui_story_1019_10190101_136_dialog_content = "Foi a primeira vez que pisei em solo nativo, mas todos os meus parentes já haviam partido há muito tempo.",
  ui_story_1019_10190101_137_dialog_content = "Ah, e quase perdemos nosso melhor amigo...",
  ui_story_1019_10190101_138_dialog_content = "Eu vi os ancestrais Celestitas deixando o continente em seus Colossos, e então testemunhei seu retorno após um longo tempo.",
  ui_story_1019_10190101_139_dialog_content = "Ao relembrar, tudo ainda parece um sonho para mim. Não consigo deixar de me perguntar o que aconteceu com eles no final.",
  ui_story_1019_10190101_140_dialog_content = "Depois disso, para me salvar, você ficou preso no antigo campo de batalha.",
  ui_story_1019_10190101_141_dialog_content = "Felizmente, encontramos a consciência de Naviduz e finalmente te acordamos.",
  ui_story_1019_10190101_142_dialog_content = "...",
  ui_story_1019_10190101_143_dialog_content = "Independentemente de quantas vezes eu leia o registro de reparos, isso não se compara a ouvir a história de você, PlayerName.",
  ui_story_1019_10190101_144_dialog_content = "Então você sabia? Eu acabei de contar tudo isso à toa?",
  ui_story_1019_10190101_145_dialog_content = "O Oficial de Tecnologia Gronru detalhou suas experiências no meu registro de reparos.",
  ui_story_1019_10190101_146_dialog_content = "Mas você se importaria de me contar sobre sua participação no Exercício Militar Conjunto como representante dos celestitas?",
  ui_story_1019_10190101_147_dialog_content = "Ah, aquilo...",
  ui_story_1019_10190201_1_dialog_content = "<color=#e8d9bb>Vários Dias Depois: Centro Médico Illumina, Manhã</color>",
  ui_story_1019_10190201_2_dialog_content = "Estes... foram todos destruídos por minha mão...",
  ui_story_1019_10190201_3_dialog_content = "S-Desculpe, Dr. Chandra. Eu ainda não consigo me controlar...",
  ui_story_1019_10190201_4_dialog_content = "Não precisa se desculpar, Capitão Helios!",
  ui_story_1019_10190201_5_dialog_content = "O treinamento de combate com moderação serve como uma válvula de escape para suas emoções e é terapêutico.",
  ui_story_1019_10190201_6_dialog_content = "Eu realmente não sei o que posso fazer pela Illumina neste estado...",
  ui_story_1019_10190201_7_dialog_content = "Esqueça esse pensamento, Capitão Helios.",
  ui_story_1019_10190201_8_dialog_content = "Você mencionou muitos lugares em suas lembranças, especialmente a Zona Cega, que é uma peça chave de inteligência para Illumina.",
  ui_story_1019_10190201_9_dialog_content = "Quanto às pessoas e encontros que você tem tentado se lembrar...",
  ui_story_1019_10190201_10_dialog_content = "Nosso cérebro processa rotineiramente percepções sensoriais e emoções quando estamos perto de outras pessoas.",
  ui_story_1019_10190201_11_dialog_content = "Conforme você ganha melhor controle sobre seus sentimentos, essas funções também serão gradualmente restauradas.",
  ui_story_1019_10190201_12_dialog_content = "Entendi... Então, preciso trabalhar mais duro.",
  ui_story_1019_10190201_13_dialog_content = "Ah, eu vou consertar os modelos quebrados, e... no futuro, deixe-me ajudar a construí-los também.",
  ui_story_1019_10190201_14_dialog_content = "Ah, e outra coisa! Desculpe por te acordar tão tarde da noite...",
  ui_story_1019_10190201_15_dialog_content = "Está tudo bem, Capitão Helios. Este é o meu trabalho. (Bocejos)",
  ui_story_1019_10190201_16_dialog_content = "Bem, então vamos deixar assim por hoje.",
  ui_story_1019_10190201_17_dialog_content = "Espero que você continue anotando seus pensamentos e o que você sonha.",
  ui_story_1019_10190201_18_dialog_content = "Não sei por que a Grande Marechal quer ver essas anotações, mas é obviamente importante para ela.",
  ui_story_1019_10190201_19_dialog_content = "E não ignore nenhuma emoção abrupta e imagens que vêm à mente.",
  ui_story_1019_10190201_20_dialog_content = "Abaixo de uma chama geralmente há gravetos que estão queimando há muito tempo.",
  ui_story_1019_10190201_21_dialog_content = "Nunca vou esquecer nada daquele mundo frio e escuro, enquanto eu viver.",
  ui_story_1019_10190201_22_dialog_content = "Obrigado novamente, Dr. Chandra.",
  ui_story_1019_10190201_23_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1019_10190201_24_dialog_content = "Quem está me mandando mensagem tão cedo pela manhã?",
  ui_story_1019_10190201_25_dialog_content = "<color=#e8d9bb>Uau, uau—</color>",
  ui_story_1019_10190201_26_dialog_content = "(Eclipsiano) 1011X.",
  ui_story_1019_10190201_27_dialog_content = "(Eclipsiano) Sim, conseguimos colocar as mãos no último <color=#FFB400>Anel de Drive</color>.",
  ui_story_1019_10190201_28_dialog_content = "(Eclipsiano) 01X11.",
  ui_story_1019_10190201_29_dialog_content = "(Eclipsiano) Eu li seu nome honrado e espero que você olhe para...",
  ui_story_1019_10190201_30_dialog_content = "(Eclipsiano) Aguardamos humildemente a sua chegada...",
  ui_story_1019_10190201_31_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1019_10190201_32_dialog_content = "Onde estou?",
  ui_story_1019_10190201_33_dialog_content = "O que são essas figuras sombrias?",
  ui_story_1019_10190201_34_dialog_content = "Pare de olhar, PlayerName!",
  ui_story_1019_10190201_35_dialog_content = "Espere, é você, Vice?",
  ui_story_1019_10190201_36_dialog_content = "É você! É mesmo você, Vice!",
  ui_story_1019_10190201_37_dialog_content = "Vá para casa.",
  ui_story_1019_10190201_38_dialog_content = "Você está perdido, Vice? Você está em perigo?",
  ui_story_1019_10190201_39_dialog_content = "Rápido, me diga onde você está! Eu vou te tirar de lá.",
  ui_story_1019_10190201_40_dialog_content = "Vá para casa.",
  ui_story_1019_10190201_41_dialog_content = "...",
  ui_story_1019_10190201_42_dialog_content = "Vai pra onde, Vice?",
  ui_story_1019_10190201_43_dialog_content = "Vá para casa.",
  ui_story_1019_10190201_44_dialog_content = "Casa? Onde estou?",
  ui_story_1019_10190201_45_dialog_content = "Vá para casa.",
  ui_story_1019_10190201_46_dialog_content = "Quem é você? Onde está Vice?",
  ui_story_1019_10190201_47_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1019_10190201_48_dialog_content = "É perigoso aqui, PlayerName!",
  ui_story_1019_10190201_49_dialog_content = "Vice! Onde você está?!",
  ui_story_1019_10190201_50_dialog_content = "<color=#e8d9bb>Bipe—bipe—bipe—</color>",
  ui_story_1019_10190201_51_dialog_content = "Vice... Vice!",
  ui_story_1019_10190201_52_dialog_content = "Outro pesadelo, PlayerName?",
  ui_story_1019_10190201_53_dialog_content = "Sonho...",
  ui_story_1019_10190201_54_dialog_content = "Estava sonhando de novo...",
  ui_story_1019_10190201_55_dialog_content = "Algo está errado, Soroz. Desde que voltei para Eraveil, continuo tendo sonhos estranhos...",
  ui_story_1019_10190201_56_dialog_content = "Parece mais que estou sentindo as coisas... mas também não consigo descrever.",
  ui_story_1019_10190201_57_dialog_content = "Talvez você esteja muito estressado, PlayerName. Você tem estado aqui esperando por notícias por várias noites seguidas. Você deveria voltar para o seu quarto e descansar um pouco.",
  ui_story_1019_10190201_58_dialog_content = "Que horas são agora?",
  ui_story_1019_10190201_59_dialog_content = "O sol nasce em três horas.",
  ui_story_1019_10190201_60_dialog_content = "Mais um dia se passou...",
  ui_story_1019_10190201_61_dialog_content = "É horrível apenas sentar aqui esperando, incapaz de fazer qualquer coisa...",
  ui_story_1019_10190201_62_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1019_10190201_63_dialog_content = "Reconheço esse som... Você encontrou mais coordenadas antigas nos dados de Naviduz.",
  ui_story_1019_10190201_64_dialog_content = "Você os chama de \"ecos do passado.\"",
  ui_story_1019_10190201_65_dialog_content = "Sim.",
  ui_story_1019_10190201_66_dialog_content = "Naviduz repetiu essas coordenadas várias vezes antes de cair em silêncio, mas nunca foi encontrada uma localização correspondente nesta terra.",
  ui_story_1019_10190201_67_dialog_content = "Isso é porque o terreno mudou?",
  ui_story_1019_10190201_68_dialog_content = "O tempo também mudou.",
  ui_story_1019_10190201_69_dialog_content = "Mas você nunca desistiu de procurar...",
  ui_story_1019_10190201_70_dialog_content = "Posso restaurar completamente minha consciência uma vez que tenha analisado todos os dados.",
  ui_story_1019_10190201_71_dialog_content = "Na verdade, você já é o Soroz que eu conheço.",
  ui_story_1019_10190201_72_dialog_content = "Nossa compatibilidade psíquica é apenas 90% daquela antes do reparo, PlayerName.",
  ui_story_1019_10190201_73_dialog_content = "Realmente? Não sinto nenhuma diferença.",
  ui_story_1019_10190201_74_dialog_content = "Vou continuar aprendendo.",
  ui_story_1019_10190201_75_dialog_content = "Eu quero te fazer uma pergunta...",
  ui_story_1019_10190201_76_dialog_content = "Eu sei que Reinhardt me disse para não me preocupar com a Illumina, mas ainda me preocupo.",
  ui_story_1019_10190201_77_dialog_content = "Quanto mais quieto está em Eraveil, mais ansioso fico. Isso me faz pensar que quando senti o batimento cardíaco de Vice...",
  ui_story_1019_10190201_78_dialog_content = "ela estava tentando me dizer algo, mas eu não conseguia entender...",
  ui_story_1019_10190201_79_dialog_content = "Então, o que você gostaria de me perguntar, PlayerName?",
  ui_story_1019_10190201_80_dialog_content = "Não, eu já decidi! Mesmo que Reinhardt se recuse a me deixar ir para a Illumina, eu—",
  ui_story_1019_10190201_81_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1019_10190201_82_dialog_content = "Por que é ela...",
  ui_story_1019_10190201_83_dialog_content = "É a notícia que você estava esperando?",
  ui_story_1019_10190201_84_dialog_content = "Sim! Olha!",
  ui_story_1019_10190201_85_dialog_content = "...",
  ui_story_1019_10190201_86_dialog_content = "\"Venha para Illumina agora\"",
  ui_story_1019_10190201_87_dialog_content = "\"O mais rápido possível\"",
  ui_story_1019_10190301_1_dialog_content = "<color=#e8d9bb>Pátio de Serviço da Illumina</color>",
  ui_story_1019_10190301_2_dialog_content = "Oh não, esqueci de perguntar onde eu deveria ir.",
  ui_story_1019_10190301_3_dialog_content = "Com licença, senhor, pode-",
  ui_story_1019_10190301_4_dialog_content = "Civis não são permitidos no pátio de serviço. Por favor, desocupem o local imediatamente.",
  ui_story_1019_10190301_5_dialog_content = "Ah, eu não sou um civil. Eu sou um Celes—",
  ui_story_1019_10190301_6_dialog_content = "Montem!",
  ui_story_1019_10190301_7_dialog_content = "Sim!",
  ui_story_1019_10190301_8_dialog_content = "Novamente, este lugar não é seguro devido às vulnerabilidades em suas defesas. Por favor, saia agora.",
  ui_story_1019_10190301_9_dialog_content = "Vulnerabilidades...",
  ui_story_1019_10190301_10_dialog_content = "Parece que a segurança ainda é um problema, mesmo com todos esses soldados.",
  ui_story_1019_10190301_11_dialog_content = "Ha! Pegue isso, PlayerName!",
  ui_story_1019_10190301_12_dialog_content = "Espere um minuto... Quem é você de novo?",
  ui_story_1019_10190301_13_dialog_content = "Vamos lá, você esqueceu de mim?!",
  ui_story_1019_10190301_14_dialog_content = "Ah, eu me lembro agora. Você é...",
  ui_story_1019_10190301_15_option_content = "Greenie",
  ui_story_1019_10190301_16_dialog_content = "Não, eu quero dizer Sean!",
  ui_story_1019_10190301_17_dialog_content = "(Não acredito que deixei escapar minha primeira impressão dele...)",
  ui_story_1019_10190301_18_dialog_content = "Ha, bem, algumas pessoas realmente me chamam assim!",
  ui_story_1019_10190301_19_option_content = "Corvo",
  ui_story_1019_10190301_20_dialog_content = "Não, espere, não é Crow... É Sean!",
  ui_story_1019_10190301_21_dialog_content = "Hmm, comparado a Crow, acho que sou bem discreto.",
  ui_story_1019_10190301_22_option_content = "Sean",
  ui_story_1019_10190301_23_dialog_content = "Isso mesmo. Você é Sean...",
  ui_story_1019_10190301_24_dialog_content = "Desculpe! Você parece... diferente, do que eu me lembro.",
  ui_story_1019_10190301_25_dialog_content = "Bem, claro. Tenho praticado minhas habilidades de boxe e ficando mais forte todos os dias!",
  ui_story_1019_10190301_26_dialog_content = "Não importa, vou deixar passar desta vez.",
  ui_story_1019_10190301_27_dialog_content = "O que você está fazendo aqui, Sean?",
  ui_story_1019_10190301_28_dialog_content = "Volto regularmente para Gannon para um check-up físico. Cheguei cedo desta vez, mas não esperava encontrar você.",
  ui_story_1019_10190301_29_dialog_content = "Então por que você não se juntou à patrulha e ajudou a expulsar os Eclipsitas?",
  ui_story_1019_10190301_30_dialog_content = "Saudações, Oficial Vivian! É porque eu...",
  ui_story_1019_10190301_31_dialog_content = "Estou brincando. Vá fazer o que você tem que fazer e tome cuidado.",
  ui_story_1019_10190301_32_dialog_content = "Sim, senhora! Até a próxima, PlayerName.",
  ui_story_1019_10190301_33_dialog_content = "Vejo você por aí, Sean.",
  ui_story_1019_10190301_34_dialog_content = "Como o Grande Marechal previu, a falta de notícias inevitavelmente te levaria a Illumina.",
  ui_story_1019_10190301_35_dialog_content = "Ela imaginou que eu viria por conta própria, então ela teve você...",
  ui_story_1019_10190301_36_dialog_content = "Claro. Nós conhecemos cada movimento que você e seu Colossus fazem em Astra como a palma de nossas mãos.",
  ui_story_1019_10190301_37_dialog_content = "Mas Illumina está uma bagunça agora; os superiores estão ocupados resolvendo uma luta pelo poder.",
  ui_story_1019_10190301_38_dialog_content = "E como você já viu, a segurança ainda é um grande problema.",
  ui_story_1019_10190301_39_dialog_content = "Oh, é o Grande Marechal...",
  ui_story_1019_10190301_40_option_content = "Reinhardt?",
  ui_story_1019_10190301_41_dialog_content = "Quem mais? Ela é a líder espiritual de todos os soldados da Illumina. Ninguém se compara.",
  ui_story_1019_10190301_42_option_content = "Fúria?",
  ui_story_1019_10190301_43_dialog_content = "Wrath é a Grande Marechal em nome, mas ela disse ao comitê que devolveria a posição para Reinhardt.",
  ui_story_1019_10190301_44_dialog_content = "No entanto, independentemente de quem assume o papel de Grande Marechal, nenhum parece estar alinhado com os desejos do comitê, ainda assim, o exército não pode se dar ao luxo de não ter um comando unificado...",
  ui_story_1019_10190301_45_dialog_content = "Então, o comitê adiou a investigação sobre a suposta conluio do Grande Marechal e decidiu que os assuntos Illuminan seriam supervisionados conjuntamente pelo comitê e pelo militar.",
  ui_story_1019_10190301_46_dialog_content = "Parece que seu trabalho ficou mais difícil.",
  ui_story_1019_10190301_47_dialog_content = "De fato. É tão desorganizado em Illumina que na maioria das vezes nem consigo alcançar o marechal.",
  ui_story_1019_10190301_48_dialog_content = "Não é à toa que não tive notícias dela... Desculpe por tornar tudo mais difícil para todos vocês!",
  ui_story_1019_10190301_49_dialog_content = "Então... Wrath ainda quer duelar com Reinhardt?",
  ui_story_1019_10190301_50_dialog_content = "Infelizmente, sim. Obviamente não para o papel de Grande Marechal, mas isso não a impede de querer lutar contra Reinhardt.",
  ui_story_1019_10190301_51_dialog_content = "Soa exatamente como ela... E como está o Wrath? A cirurgia correu bem?",
  ui_story_1019_10190301_52_dialog_content = "Também quero saber isso, mas a burocracia está tão grande agora que qualquer coisa envolvendo o Programa Phospherus está sendo obstruída.",
  ui_story_1019_10190301_53_dialog_content = "Então, se você está aqui para visitá-la, isso é um enfático não pode.",
  ui_story_1019_10190301_54_dialog_content = "Na verdade, eu vim aqui para–",
  ui_story_1019_10190301_55_dialog_content = "Graaagh!",
  ui_story_1019_10190301_56_dialog_content = "Chefe de Gabinete! Os mecânicos disseram que o duto de ventilação no lado oeste do pátio de serviço está fora de ordem. Os Eclipsitas devem ter entrado por lá!",
  ui_story_1019_10190301_57_dialog_content = "Finalmente, encontramos a violação após uma noite inteira!",
  ui_story_1019_10190301_58_dialog_content = "Formem uma formação, cubram os engenheiros e sigam-me para matar os Eclipsitas!",
  ui_story_1019_10190301_59_dialog_content = "Sim, senhora!!!",
  ui_story_1019_10190301_60_dialog_content = "Ei, você na frente, saia do caminho!",
  ui_story_1019_10190301_61_dialog_content = "Chefe de Gabinete! Atrás de você... Os Eclipsitas estrangularam alguém até a morte!",
  ui_story_1019_10190301_62_dialog_content = "Será que é...?",
  ui_story_1019_10190301_63_dialog_content = "Buá buá buá!",
  ui_story_1019_10190301_64_dialog_content = "Na frente de tantas pessoas também...",
  ui_story_1019_10190301_65_dialog_content = "Ui ui ui!",
  ui_story_1019_10190301_66_dialog_content = "Tudo bem, tudo bem. Mesmo que ainda não seja hora de malhar...",
  ui_story_1019_10190301_67_dialog_content = "Prepare-se para executar o programa!",
  ui_story_1019_10190301_68_dialog_content = "Buá!",
  ui_story_1019_10190301_69_dialog_content = "Quem no mundo é aquele?",
  ui_story_1019_10190402_1_dialog_content = "Upload, upload... Hmm, ainda não há dados suficientes sobre atividades ao ar livre.",
  ui_story_1019_10190402_2_dialog_content = "Então é assim que parece quando um cientista luta...",
  ui_story_1019_10190402_3_dialog_content = "Ei, antes de começar a repetir estereótipos sobre cientistas, deixe-me lembrá-lo...",
  ui_story_1019_10190402_4_dialog_content = "Nem todos nós somos deprimentes, chatos, não atléticos e ratos de biblioteca.",
  ui_story_1019_10190402_5_dialog_content = "Não não, não foi isso que eu quis dizer...",
  ui_story_1019_10190402_6_dialog_content = "Quem é esse, PlayerName?",
  ui_story_1019_10190402_7_dialog_content = "Algol, um cientista do Conselho Científico da Illumina.",
  ui_story_1019_10190402_8_dialog_content = "Ela me convidou para Illumina, mas eu acho... ela não é bem a mesma de quando a vi pela última vez.",
  ui_story_1019_10190402_9_dialog_content = "O Conselho Científico? Esta é a primeira vez que vejo um deles pessoalmente.",
  ui_story_1019_10190402_10_dialog_content = "Con-fir-mado!",
  ui_story_1019_10190402_11_dialog_content = "Oi, Celestita! Além disso, eu te convidei?",
  ui_story_1019_10190402_12_dialog_content = "Olá, Professor Algol. Eu sou Vivian, o Chefe de Gabinete da Federação Illumina.",
  ui_story_1019_10190402_13_dialog_content = "Bem... já que você está aqui, me siga.",
  ui_story_1019_10190402_14_dialog_content = "Professor Algol, gostaria de informar que o Grande Marechal me enviou para auxiliar PlayerName na Illumina.",
  ui_story_1019_10190402_15_dialog_content = "Devo ser informado sobre seus planos e reportá-los à Grande Marechal.",
  ui_story_1019_10190402_16_dialog_content = "Nosso encontro foi espontâneo e não será registrado. Se você insistir em fazer um registro, use isso.",
  ui_story_1019_10190402_17_dialog_content = "Quer dizer que...",
  ui_story_1019_10190402_18_dialog_content = "Sua cabeça.",
  ui_story_1019_10190402_19_dialog_content = "Buá!",
  ui_story_1019_10190402_20_dialog_content = "...",
  ui_story_1019_10190402_21_dialog_content = "Por razões de segurança, no entanto, tenho uma pergunta para fazer a você. Aquilo... a coisa que estava lutando ao seu lado não é uma arma normal, certo?",
  ui_story_1019_10190402_22_dialog_content = "Claro que não é! Seu nome é Bool, e é meu p–",
  ui_story_1019_10190402_23_dialog_content = "Uuuh!",
  ui_story_1019_10190402_24_dialog_content = "Isso dói! Pare com isso, amigo...!",
  ui_story_1019_10190402_25_dialog_content = "Caramba... Hum, sim, isso é bom! Suba um pouco mais...",
  ui_story_1019_10190402_26_dialog_content = "Bool também faz massagens?",
  ui_story_1019_10190402_27_dialog_content = "Bool diz que você ganhou alguns quilos desde a última vez.",
  ui_story_1019_10190402_28_dialog_content = "O que?! Como ele fala?",
  ui_story_1019_10190402_29_dialog_content = "Como um Celestita, você deve saber que nem toda comunicação acontece verbalmente.",
  ui_story_1019_10190402_30_dialog_content = "Nós—Bool e eu—temos uma maneira única de conversar um com o outro.",
  ui_story_1019_10190402_31_dialog_content = "Por exemplo, Bool agora diz que está muito satisfeito com o sistema de combate que eu atualizei para ele!",
  ui_story_1019_10190402_32_dialog_content = "Buá!",
  ui_story_1019_10190402_33_dialog_content = "Hehe! Não mencione isso!",
  ui_story_1019_10190402_34_dialog_content = "(Aquela entrada grandiosa deles era meio horrível...)",
  ui_story_1019_10190402_35_dialog_content = "Hmm? Celestita, você tem algo a dizer?",
  ui_story_1019_10190402_36_dialog_content = "Buá!",
  ui_story_1019_10190402_37_dialog_content = "De fato... Eu também vejo o desprezo vagamente escondido em seu rosto.",
  ui_story_1019_10190402_38_dialog_content = "Você também conseguia perceber o que eu estava pensando?",
  ui_story_1019_10190402_39_dialog_content = "Haha, relaxe! Vamos lá.",
  ui_story_1019_10190402_40_dialog_content = "Ah... O que era tão urgente que você precisava que eu viesse para Illumina, Professor Algol?",
  ui_story_1019_10190402_41_dialog_content = "Você veio sem nem mesmo saber pelo que estava vindo?",
  ui_story_1019_10190402_42_dialog_content = "Embora isso se encaixe no estereótipo que tenho para os Celestitas.",
  ui_story_1019_10190402_43_dialog_content = "Ainda se lembra dos dados de personalidade da Naviduz que você copiou para restaurar o Soroz?",
  ui_story_1019_10190402_44_dialog_content = "As coordenadas nos dados não tinham localizações correspondentes.",
  ui_story_1019_10190402_45_dialog_content = "Mas Illumina recentemente atualizou partes de seu mapa da Noite Eterna, e pode haver pistas para encontrar o núcleo do Guardian One em algum lugar.",
  ui_story_1019_10190402_46_dialog_content = "Os dados podem até fornecer respostas para as coordenadas desconhecidas descobertas pela equipe de rastreamento.",
  ui_story_1019_10190402_47_dialog_content = "Sério? Isso é ótimo! O que você quer que eu faça?",
  ui_story_1019_10190402_48_dialog_content = "Não são suas habilidades psíquicas que precisamos desta vez, mas a capacidade de aprendizado de Soroz.",
  ui_story_1019_10190402_49_dialog_content = "Capacidade de aprendizado?",
  ui_story_1019_10190402_50_dialog_content = "Sim. A capacidade de Soroz de recuperar a consciência em tão pouco tempo prova que é um aprendiz rápido.",
  ui_story_1019_10190402_51_dialog_content = "Gostaria de usar essa habilidade para melhorar a eficiência do processo de mapeamento da Zona Escura, ao mesmo tempo que me proporciona novas perspectivas para minha pesquisa.",
  ui_story_1019_10190402_52_dialog_content = "Isso parece impressionante... De qualquer forma, teremos prazer em ajudar.",
  ui_story_1019_10190402_53_dialog_content = "Então conecte o Soroz ao meu <color=#FFB400>terminal</color>. Isso levará algum tempo.",
  ui_story_1019_10190402_54_dialog_content = "Quanto ao tempo exato, deixa eu ver...",
  ui_story_1019_10190402_55_dialog_content = "Não é o seu <color=#FFB400>terminal</color> aquela coisa no seu pulso?",
  ui_story_1019_10190402_56_dialog_content = "Este é uma pulseira tecnológica. Claro, eu prefiro chamar de braçadeira esportiva.",
  ui_story_1019_10190402_57_dialog_content = "Ah, hora de malhar. Vocês querem se juntar a mim?",
  ui_story_1019_10190402_58_dialog_content = "Mas é cedo. Você costuma se exercitar a essa hora do dia, Docente Algol?",
  ui_story_1019_10190402_59_dialog_content = "É assim que meu relógio biológico funciona.",
  ui_story_1019_10190402_60_dialog_content = "Que tal isso, vamos chamar a batalha que acabamos de ter de treino. Então, podemos ir direto ao ponto!",
  ui_story_1019_10190402_61_dialog_content = "...",
  ui_story_1019_10190402_62_dialog_content = "Mordomo... Mordomo... Abra a porta e me sirva três xícaras de café enquanto faz isso.",
  ui_story_1019_10190402_63_dialog_content = "O Guardião Um se recusa. O Guardião Um não é um mordomo.",
  ui_story_1019_10190402_64_dialog_content = "...",
  ui_story_1019_10190402_65_dialog_content = "Uh, bem, talvez ele tenha acabado de se levantar...",
  ui_story_1019_10190501_1_dialog_content = "<color=#e8d9bb>Escritório de Algol</color>",
  ui_story_1019_10190501_2_dialog_content = "Bem-vindo ao meu laboratório! Está um pouco bagunçado. De qualquer forma, encontre algum lugar para se sentar.",
  ui_story_1019_10190501_3_dialog_content = "Eu não sabia que um laboratório da Illumina poderia parecer assim...",
  ui_story_1019_10190501_4_dialog_content = "Plantas em vasos, máquinas de exercícios e todas essas coisas legais...",
  ui_story_1019_10190501_5_dialog_content = "Isso é uma cama ou um sofá?",
  ui_story_1019_10190501_6_dialog_content = "Por que você não deita nele e vê por si mesmo? O botão de massagem está bem ali.",
  ui_story_1019_10190501_7_dialog_content = "Uau, isso é extremamente confortável. Está me dando sono.",
  ui_story_1019_10190501_8_dialog_content = "Isso é tão diferente do estilo típico de Illumina...",
  ui_story_1019_10190501_9_dialog_content = "Exatamente. Nada dessa configuração está em conformidade com as Regulamentações de Alojamento da Illumina...",
  ui_story_1019_10190501_10_dialog_content = "Hã? Tudo o que você vê aqui foi construído principalmente com materiais antigos e reciclados.",
  ui_story_1019_10190501_11_dialog_content = "E eu integrei meus espaços de vida e trabalho em um único cômodo. Isso não conta como conservação de recursos?",
  ui_story_1019_10190501_12_dialog_content = "Sem mencionar que é contra os Regulamentos dos Soldados Illumina para o Chefe de Gabinete receber uma massagem durante o horário de trabalho.",
  ui_story_1019_10190501_13_dialog_content = "V-Você não me viu recebendo uma massagem...",
  ui_story_1019_10190501_14_dialog_content = "Você não acabou de dizer que estava te dando sono?",
  ui_story_1019_10190501_15_dialog_content = "Não fique aí parado, Celestita. Está vendo aquela roda ali?",
  ui_story_1019_10190501_16_dialog_content = "Ficar em pé por 10 minutos queimará mais calorias do que correr dez voltas ao redor do Colosso.",
  ui_story_1019_10190501_17_dialog_content = "Vamos falar sobre essas coisas mais tarde...",
  ui_story_1019_10190501_18_dialog_content = "Bip!",
  ui_story_1019_10190501_19_dialog_content = "Não te vejo há um tempo, Celestita!",
  ui_story_1019_10190501_20_dialog_content = "Ei, Guardião Um! Então você é o dróide mordomo!",
  ui_story_1019_10190501_21_dialog_content = "O Guardião Um nunca concordou em ser o mordomo de Algol.",
  ui_story_1019_10190501_22_dialog_content = "... Então o que é isso que você está carregando?",
  ui_story_1019_10190501_23_dialog_content = "Estas são duas xícaras de café fresco para os dois convidados, feitas especialmente pelo Guardião Um. Algol terá que fazer o seu próprio.",
  ui_story_1019_10190501_24_dialog_content = "Isso é injusto...",
  ui_story_1019_10190501_25_dialog_content = "Ei, você colocou manteiga nisso? Eu só tomei café com esse sabor em Umbraton antes.",
  ui_story_1019_10190501_26_dialog_content = "Esta é uma mistura especial que deve agradar o seu paladar.",
  ui_story_1019_10190501_27_dialog_content = "Eu gosto muito disso.",
  ui_story_1019_10190501_28_dialog_content = "Deixe-me tomar um gole...",
  ui_story_1019_10190501_29_dialog_content = "Hmm... Estou sentindo o cheiro de grama fresca. É surpreendentemente delicioso!",
  ui_story_1019_10190501_30_dialog_content = "É uma mistura especial de Eraveil.",
  ui_story_1019_10190501_31_dialog_content = "Algol desenvolveu muitos programas interessantes recentemente. O Guardian One pode fazer café com sabores especiais de acordo com seus hábitos alimentares em Illumina.",
  ui_story_1019_10190501_32_dialog_content = "Você realmente faz um bom trabalho como mordomo, sabia?",
  ui_story_1019_10190501_33_dialog_content = "...",
  ui_story_1019_10190501_34_dialog_content = "Uuuh!",
  ui_story_1019_10190501_35_dialog_content = "Ok, temos as configurações. Vou começar a rodar os dados!",
  ui_story_1019_10190501_36_dialog_content = "Inseridor, inseridor... Onde está aquela coisa maldita?",
  ui_story_1019_10190501_37_dialog_content = "Ops... Pegue isso para mim, poderia, Guardião Um.",
  ui_story_1019_10190501_38_dialog_content = "...",
  ui_story_1019_10190501_39_dialog_content = "... Eu vou fazer isso.",
  ui_story_1019_10190501_40_dialog_content = "Ei, por que há corações rosa por todo o lado de trás?",
  ui_story_1019_10190501_41_dialog_content = "\"Querido Algol, você pode me ensinar matemática?\"",
  ui_story_1019_10190501_42_dialog_content = "E este também... \"Sua sabedoria me ilumina como os holofotes da undercity.\"",
  ui_story_1019_10190501_43_dialog_content = "Assinado \"Adivinha Quem\"...",
  ui_story_1019_10190501_44_dialog_content = "Ah, essas... Apenas algumas cartas de amor antigas que recebi no passado.",
  ui_story_1019_10190501_45_option_content = "... Isso é tão constrangedor.",
  ui_story_1019_10190501_46_option_content = "... Deixa pra lá, eu não quero saber.",
  ui_story_1019_10190501_47_dialog_content = "Algol, é bastante surpreendente que você usou a carta de amor de alguém como rascunho.",
  ui_story_1019_10190501_48_dialog_content = "Por que eu não usaria o papel que está bem na minha frente? Além disso, significa que nunca joguei um fora.",
  ui_story_1019_10190501_49_dialog_content = "Você poderia ter usado o quadro branco.",
  ui_story_1019_10190501_50_dialog_content = "Este enorme quadro tem mapas... cálculos, cálculos e ainda mais cálculos.",
  ui_story_1019_10190501_51_dialog_content = "Também vejo muitas revisões baseadas no humor do Dr. Algol nestes memorandos.",
  ui_story_1019_10190501_52_dialog_content = "Você também vê a angústia escondida neles?",
  ui_story_1019_10190501_53_dialog_content = "Da minha incapacidade de resolver o mistério do Guardião?",
  ui_story_1019_10190501_54_dialog_content = "Guardião? Você quer dizer Guardião Um?",
  ui_story_1019_10190501_55_dialog_content = "Não!",
  ui_story_1019_10190501_56_dialog_content = "O Guardião Um é uma antiga IA encarregada das operações diárias de todo o sistema tecnológico da Illumina.",
  ui_story_1019_10190501_57_dialog_content = "Na verdade, é um enorme conjunto de computadores. Wraiths roubaram o núcleo e você viu o impacto que isso teve em Gannon City.",
  ui_story_1019_10190501_X57_dialog_content = "Este cluster foi desenvolvido usando a antiga tecnologia - Guardian - como base.",
  ui_story_1019_10190501_58_dialog_content = "Você poderia dizer que o Guardião é o protótipo para o Guardião Um.",
  ui_story_1019_10190501_59_dialog_content = "O Guardian One é parte de um cluster de computadores com um núcleo independente para processar dados. Ele também armazenou muitas informações dos tempos antigos.",
  ui_story_1019_10190501_X59_dialog_content = "Portanto, embora eles tenham o mesmo nome em teoria, para diferenciar, você pode chamar o Guardião Um... hm, \"Caixa de Correio\".",
  ui_story_1019_10190501_60_dialog_content = "O Guardian One não é uma caixa de correio.",
  ui_story_1019_10190501_61_dialog_content = "Bip, bip, bip, bip, bip...",
  ui_story_1019_10190501_62_dialog_content = "O Guardião Um não entende o que Algol disse.",
  ui_story_1019_10190501_63_dialog_content = "Parece que você ainda precisa aprender como processar diálogos aurorianos complexos.",
  ui_story_1019_10190501_64_dialog_content = "O Guardião Um compreende.",
  ui_story_1019_10190501_65_dialog_content = "(Tão difícil de acreditar que Algol não está ignorando o Guardião Um...)",
  ui_story_1019_10190501_66_dialog_content = "De qualquer forma, meu trabalho é estudar o Guardião e desenvolver suas outras características.",
  ui_story_1019_10190501_67_dialog_content = "Esta máquina é o protótipo?",
  ui_story_1019_10190501_68_dialog_content = "Este é um <color=#FFB400>simulador</color>. O original há muito tempo foi trancado por razões de segurança.",
  ui_story_1019_10190501_69_dialog_content = "Verdade. Pareceria quebrado se fosse tecnologia antiga.",
  ui_story_1019_10190501_70_dialog_content = "Nem sempre. Eu vi o original antes, e só posso descrever o exterior como... exalando uma aura antiga, mas sofisticada.",
  ui_story_1019_10190501_71_dialog_content = "Vimos progresso em todas as tecnologias de ponta nos últimos anos, exceto para o Guardião, que ainda está limitado.",
  ui_story_1019_10190501_72_dialog_content = "Se eu pudesse examiná-lo antes de ser guardado...",
  ui_story_1019_10190501_73_dialog_content = "Ah, eu fico brava sempre que penso nisso!",
  ui_story_1019_10190501_74_dialog_content = "Buá!",
  ui_story_1019_10190501_75_dialog_content = "O quê? Até você está zombando de mim!",
  ui_story_1019_10190501_76_dialog_content = "Bool não parece estar zombando de você, mas discordando do que você disse.",
  ui_story_1019_10190501_77_dialog_content = "Buá!",
  ui_story_1019_10190501_78_dialog_content = "Ah, ótimo, até o Celestita é mais inteligente do que eu agora!",
  ui_story_1019_10190501_79_dialog_content = "...",
  ui_story_1019_10190501_80_dialog_content = "Falando de mal-entendido...",
  ui_story_1019_10190501_81_dialog_content = "Como você conseguiu se conectar psiquicamente ao Guardião Um, talvez você possa também explorar a mente de Bool.",
  ui_story_1019_10190501_82_dialog_content = "Uuuh!",
  ui_story_1019_10190501_83_dialog_content = "Está se escondendo atrás de você. Não acho que ele esteja receptivo a essa ideia.",
  ui_story_1019_10190501_84_dialog_content = "Bu...",
  ui_story_1019_10190501_85_dialog_content = "Você consegue perceber? Está apenas fazendo jogo duro.",
  ui_story_1019_10190501_86_dialog_content = "Ok... Então, deixe-me tentar.",
  ui_story_1019_10190501_87_dialog_content = "Ai...",
  ui_story_1019_10190501_88_option_content = "Ligação Telepática",
  ui_story_1019_10190501_89_dialog_content = "(Espera, o Bool está se escondendo atrás do Algol de novo? Eu só vejo Algol...)",
  ui_story_1019_10190501_90_dialog_content = "(Algo deu errado?)",
  ui_story_1019_10190501_91_dialog_content = "(Não vejo nada ao redor...)",
  ui_story_1019_10190501_92_dialog_content = "(Algol não é um Aurorian, mas um droide? IA, talvez?!)",
  ui_story_1019_10190501_93_dialog_content = "(De jeito nenhum... Que ideia maluca é essa? Ela acabou de lutar uma batalha com Lumina!)",
  ui_story_1019_10190501_94_dialog_content = "(Talvez eu não esteja indo fundo o suficiente e tenha que ir mais fundo.)",
  ui_story_1019_10190501_95_dialog_content = "(Vá mais fundo...)",
  ui_story_1019_10190501_96_dialog_content = "(Mais fundo...)",
  ui_story_1019_10190501_97_dialog_content = "(Hã? Isso foi... Bool?)",
  ui_story_1019_10190501_98_dialog_content = "(Posso realmente alternar entre dois objetos de percepção. Essa sensação é incrível. É como se eu tivesse dois pares de olhos...)",
  ui_story_1019_10190501_99_dialog_content = "<color=#e8d9bb>Buá!!! Plaft—</color>",
  ui_story_1019_10190501_100_dialog_content = "Aah!",
  ui_story_1019_10190601_1_dialog_content = "Vejo que Bool também se importa muito com você!",
  ui_story_1019_10190601_2_dialog_content = "Frequência cardíaca, pressão arterial... Tudo normal, e o seu nível de oxigênio no sangue melhorou.",
  ui_story_1019_10190601_3_dialog_content = "Você chama uma surra de treino?",
  ui_story_1019_10190601_4_dialog_content = "O que você quer dizer com \"surra\"? Você nem sequer tem um hematoma, sem falar que esta é uma forma avançada de se comunicar.",
  ui_story_1019_10190601_5_dialog_content = "Buá!",
  ui_story_1019_10190601_6_dialog_content = "Eu me lembro desse tom! Não acha que é tarde demais para oferecer simpatia agora...",
  ui_story_1019_10190601_7_dialog_content = "Dr. Algol, como você está se comunicando com Bool?",
  ui_story_1019_10190601_8_dialog_content = "Bem, Bool transmite mensagens diferentes ao me bater com intensidades variadas. Obviamente, ainda tem que trabalhar nisso com o Caelestite.",
  ui_story_1019_10190601_9_dialog_content = "Está bem. Isso é algo que eu poderia fazer sem.",
  ui_story_1019_10190601_10_dialog_content = "Mas Bool sempre foi amigável com você antes. Por que ele agiria dessa maneira...?",
  ui_story_1019_10190601_11_dialog_content = "Bem, eu vi algo na mente de Bool.",
  ui_story_1019_10190601_12_dialog_content = "Mas, ao contrário do Guardião Um, a imagem não era nem específica nem clara.",
  ui_story_1019_10190601_13_dialog_content = "A mente do Bool funciona mais como um computador, afinal.",
  ui_story_1019_10190601_14_dialog_content = "De qualquer maneira, por favor, perdoe a explosão. Não te machucou muito, machucou?",
  ui_story_1019_10190601_15_dialog_content = "...",
  ui_story_1019_10190601_16_dialog_content = "<color=#e8d9bb>Bipe—bipe—bipe—</color>",
  ui_story_1019_10190601_17_dialog_content = "Ei, certas coordenadas nos dados de Soroz realmente aparecem no novo mapa.",
  ui_story_1019_10190601_18_dialog_content = "Nunca verificamos aquele lugar antes, certo?",
  ui_story_1019_10190601_19_dialog_content = "Espere, isso significa que temos vários conjuntos de coordenadas?",
  ui_story_1019_10190601_20_dialog_content = "Pode ser da mesma fonte, mas com sinais oscilantes.",
  ui_story_1019_10190601_21_dialog_content = "Noroeste de Gannon, cerca de 2.500 milhas...",
  ui_story_1019_10190601_22_dialog_content = "Bem, ainda é possível. Não é tão longe quanto eu pensei que seria.",
  ui_story_1019_10190601_23_dialog_content = "Mas esses sinais são muito mais antigos do que os do Obelisco do Retorno.",
  ui_story_1019_10190601_24_dialog_content = "Você quer dizer que Eraveil não é onde as Colossi se originaram?",
  ui_story_1019_10190601_25_dialog_content = "Isso mesmo. A localização atual de Eraveil serviu mais como um forte de fronteira dos Eclipsitas em sua invasão a Astra.",
  ui_story_1019_10190601_26_dialog_content = "Os Colossos provavelmente vieram da Zona Escura.",
  ui_story_1019_10190601_27_dialog_content = "Então Eraveil não é a casa de Soroz...",
  ui_story_1019_10190601_28_dialog_content = "Provavelmente nem mesmo a casa dos celestitas...",
  ui_story_1019_10190601_29_dialog_content = "A localização da casa de alguém não tem importância, Caelestite.",
  ui_story_1019_10190601_30_dialog_content = "O ponto é, Soroz tem vivido com os Celestitas em Eraveil desde que ele primeiro compreendeu o conceito de \"lar\".",
  ui_story_1019_10190601_31_dialog_content = "De uma perspectiva biomecânica, a versão atual de Soroz deve ser considerada sua criação.",
  ui_story_1019_10190601_32_dialog_content = "...",
  ui_story_1019_10190601_33_dialog_content = "Não fique desanimado. Estamos apenas especulando agora.",
  ui_story_1019_10190601_34_dialog_content = "Encontraremos a resposta assim que confirmarmos a localização.",
  ui_story_1019_10190601_35_dialog_content = "Dr. Algol, o que devemos fazer para nos prepararmos para a busca na Zona Escura?",
  ui_story_1019_10190601_36_dialog_content = "Com as informações de Helios e da Equipe de Expedição da Zona Escura, estamos começando a conhecer um pouco sobre a Zona Escura.",
  ui_story_1019_10190601_37_dialog_content = "Um especialista está fazendo um mapa agora, apoiado pelos dados de Soroz.",
  ui_story_1019_10190601_38_dialog_content = "Vamos falar com ele. Deve ser interessante.",
  ui_story_1019_10190601_39_dialog_content = "Claro.",
  ui_story_1019_10190601_40_dialog_content = "<color=#828282>Ding!</color>",
  ui_story_1019_10190601_41_dialog_content = "Hmm? Há Eclipsitas no Parque Tecnológico... Quem está encarregado da patrulha?",
  ui_story_1019_10190601_42_dialog_content = "Barton deveria estar de serviço neste momento. Como você sabe que há Eclipsitas no Parque Tecnológico?",
  ui_story_1019_10190601_43_dialog_content = "Meu bracelete pode sentir ameaças nas proximidades, mas não será um problema se Barton estiver de guarda.",
  ui_story_1019_10190601_44_dialog_content = "O Parque Tecnológico é um local vital em Gannon. Não podemos ter Eclipsitas por aqui.",
  ui_story_1019_10190601_45_dialog_content = "Onde estão os Eclipsitas? Eu preciso investigar e destacar os guardas imediatamente.",
  ui_story_1019_10190601_46_dialog_content = "Barton já está nisso.",
  ui_story_1019_10190601_47_dialog_content = "Relatar ameaças, avaliar Eclipsitas, enviar soldados, matar Eclipsitas, consertar brechas... a pulseira pode fazer tudo isso.",
  ui_story_1019_10190601_48_dialog_content = "Mas...",
  ui_story_1019_10190601_49_dialog_content = "Acredite em mim, está tudo bem. Você não pode lidar com tudo sozinho. Isso vai te cansar.",
  ui_story_1019_10190601_50_dialog_content = "É meu dever. Não me sinto cansado.",
  ui_story_1019_10190601_51_dialog_content = "Bastante estoico, mas Bool diz que as olheiras sob seus olhos já te entregaram.",
  ui_story_1019_10190601_52_dialog_content = "Buá!",
  ui_story_1019_10190601_53_dialog_content = "Vamos lá, passaremos pela fonte da ameaça no nosso caminho. Podemos verificar se você ainda estiver preocupado.",
  ui_story_1019_10190601_54_dialog_content = "Buá!",
  ui_story_1019_10190702_1_dialog_content = "Não consigo imaginar Eclipsitas no Parque Tecnológico...",
  ui_story_1019_10190702_2_dialog_content = "É realmente um Eclipsite? Por que ele parece mais com um soldado Illumina?",
  ui_story_1019_10190702_3_dialog_content = "Pergunte ao Barton. Ele deve ter terminado com os Eclipsitas do lado dele.",
  ui_story_1019_10190702_4_dialog_content = "O que você está fazendo aqui? O Grande Marechal não disse para você ficar em Eraveil?",
  ui_story_1019_10190702_5_dialog_content = "Bom, é uma longa história...",
  ui_story_1019_10190702_6_dialog_content = "Eu disse ao Celestita para vir.",
  ui_story_1019_10190702_7_dialog_content = "Você é Algol, o cientista que me enviou a mensagem, certo?",
  ui_story_1019_10190702_8_dialog_content = "Sim. Os Eclipsitas não entraram sorrateiramente pelo lado de fora, entraram?",
  ui_story_1019_10190702_9_dialog_content = "Quanto menos vocês cientistas se intrometerem com os Eclipsitas, melhor.",
  ui_story_1019_10190702_10_dialog_content = "Tenho certeza de que você ouviu o que aconteceu em Crepúsculo. Mesmo que Ulysses não tenha tido sucesso, ainda assim teve um grande impacto no militar.",
  ui_story_1019_10190702_11_dialog_content = "Não me coloque no mesmo grupo que os outros cientistas. Não tenho interesse em Aurorianos.",
  ui_story_1019_10190702_12_dialog_content = "Barton, Dr. Algol tem boas intenções. Por favor, nos diga o que está acontecendo com os Eclipsitas.",
  ui_story_1019_10190702_13_dialog_content = "...",
  ui_story_1019_10190702_14_dialog_content = "Bem, é estranho, para ser honesto! Eu não vi Eclipsitas quando cheguei ao local. Eu apenas vi dois soldados passando pelo prédio do laboratório...",
  ui_story_1019_10190702_15_dialog_content = "Quem diria que quando me aproximei, eles me atacaram como cães raivosos!",
  ui_story_1019_10190702_16_dialog_content = "Nós nos deparamos com a mesma coisa.",
  ui_story_1019_10190702_17_dialog_content = "Agora que penso nisso, eles podem ser do Programa Phospherus. O que você acha, garoto?",
  ui_story_1019_10190702_18_dialog_content = "Quando eu estava dirigindo sua operação, eu podia sentir que o Darkflow neles era diferente.",
  ui_story_1019_10190702_19_dialog_content = "Se fossem Eclipsitas, poderia haver um problema com o sistema de defesa que levou à fuga deles do laboratório.",
  ui_story_1019_10190702_20_dialog_content = "Isso é possível. O Parque Tecnológico Illumina tem mais do que centros médicos e Laboratórios Black Umbrella...",
  ui_story_1019_10190702_21_dialog_content = "Como o cientista que realiza experimentos em sujeitos aurorianos!",
  ui_story_1019_10190702_22_dialog_content = "Ai...",
  ui_story_1019_10190702_23_dialog_content = "Por que você não confronta Ulysses sobre isso?",
  ui_story_1019_10190702_24_dialog_content = "Você acha que eu não queria?",
  ui_story_1019_10190702_25_dialog_content = "A investigação sobre o Phospherus não tem fim e o Comitê fechou os olhos para Ulysses transformar os soldados!",
  ui_story_1019_10190702_26_dialog_content = "Se você me perguntar, isso apenas coloca Gannon em maior perigo a cada dia!",
  ui_story_1019_10190702_27_dialog_content = "Por que a Illumina não condenou Ulysses por prejudicar tantos soldados?",
  ui_story_1019_10190702_28_dialog_content = "Eu posso explicar isso.",
  ui_story_1019_10190702_29_dialog_content = "É pelo bem dos soldados, já que Ulysses é obrigado a ajudar a tratar os feridos.",
  ui_story_1019_10190702_30_dialog_content = "E cada documento relevante para o caso está em seu prédio. O painel de revisão ainda está acessando e passando por eles.",
  ui_story_1019_10190702_31_dialog_content = "Além disso, mesmo que Ulysses esteja sob vigilância, ele ainda tem relativa liberdade para fazer o que quiser.",
  ui_story_1019_10190702_32_dialog_content = "Então, a menos que seja urgente, não podemos entrar em seu laboratório.",
  ui_story_1019_10190702_33_dialog_content = "Você pode usar a brecha dos Eclipsitas como desculpa para interrogar Ulysses.",
  ui_story_1019_10190702_34_dialog_content = "Buá!",
  ui_story_1019_10190702_35_dialog_content = "Eu tentei isso. Não funcionou.",
  ui_story_1019_10190702_36_dialog_content = "Então, sigam-me. Estou autorizado a entrar no laboratório dele. Direi que vocês estão aqui para me ajudar.",
  ui_story_1019_10190702_37_dialog_content = "Pelo menos pelo que eu sei, não há como os Eclipsitas penetrarem no nível mais baixo de Gannon pelo lado de fora.",
  ui_story_1019_10190702_38_dialog_content = "Além disso, eu não quero que o Parque Tecnológico Illumina se torne um covil de Eclipsitas após perder o núcleo do Guardião Um.",
  ui_story_1019_10190702_39_dialog_content = "Essa é uma ideia. O que você acha, Barton?",
  ui_story_1019_10190702_40_dialog_content = "Vamos tentar...",
  ui_story_1019_10190702_41_dialog_content = "Então vamos, mas tenha cuidado, se os Eclipsitas escaparam do armazém, haverá mais deles lá dentro.",
  ui_story_1019_10190802_1_dialog_content = "Booo!",
  ui_story_1019_10190802_2_dialog_content = "Ei, não se apresse. Estou te enviando os dados agora mesmo...",
  ui_story_1019_10190802_3_dialog_content = "Os soldados de patrulha relataram que nenhum Eclipsita foi avistado em outros prédios, então este deve ser o lugar certo.",
  ui_story_1019_10190802_4_dialog_content = "Ulysses soltou esses Eclipsitas de propósito?",
  ui_story_1019_10190802_5_dialog_content = "Não acho que ele tenha coragem. Além disso, ele não é estúpido o suficiente para querer morrer junto com o resto da Illumina.",
  ui_story_1019_10190802_6_dialog_content = "Ahem, isso é um elogio para mim?",
  ui_story_1019_10190802_7_dialog_content = "Você sabe que existem Eclipsitas no seu laboratório, Ulysses?",
  ui_story_1019_10190802_8_dialog_content = "Nunca houve escassez de sujeitos Eclipsitas neste prédio de laboratório para a pesquisa de Aurorianos e Eclipsitas.",
  ui_story_1019_10190802_9_dialog_content = "Isso não é um segredo. Nem sua preocupação também.",
  ui_story_1019_10190802_10_dialog_content = "Mas desde que o núcleo foi roubado, surgiram muitas brechas nas válvulas do armazém do prédio do laboratório. Provavelmente foi por aí que os Eclipsitas escaparam.",
  ui_story_1019_10190802_11_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_1019_10190802_12_dialog_content = "Eles não são Eclipsitas usados para fins experimentais. Além disso, você está claramente proibido de transformar Aurorianos.",
  ui_story_1019_10190802_13_dialog_content = "E se eles são soldados transformados ou verdadeiros sujeitos Eclipsitas...",
  ui_story_1019_10190802_14_dialog_content = "Temos o direito de investigar quando eles escaparam do seu laboratório e ameaçaram nosso povo.",
  ui_story_1019_10190802_15_dialog_content = "Claramente proibido? Hã...",
  ui_story_1019_10190802_16_dialog_content = "Mesmo assim, quem te autorizou a entrar no meu prédio e lidar com esses sujeitos Eclipsitas?",
  ui_story_1019_10190802_17_dialog_content = "Não importa o que o Comitê diz. Nosso dever é matar todos os Eclipsitas!",
  ui_story_1019_10190802_18_dialog_content = "Você não tem razão apenas porque é o mais alto. No entanto, você precisa ser bom para rastrear os assuntos para mim.",
  ui_story_1019_10190802_19_dialog_content = "Como você pode...!",
  ui_story_1019_10190802_20_dialog_content = "Eu estava apenas verificando o sistema do Bool agora mesmo... Como a situação ficou tão tumultuada?",
  ui_story_1019_10190802_21_dialog_content = "Eu os convidei para me ajudar, Ulysses. Isso não tem nada a ver com você.",
  ui_story_1019_10190802_22_dialog_content = "Não tão rápido...",
  ui_story_1019_10190802_23_dialog_content = "Você tem uma mensagem do Comitê, senhora.",
  ui_story_1019_10190802_24_dialog_content = "Eles esperam que você compareça à revisão final no horário.",
  ui_story_1019_10190802_25_dialog_content = "... Eu entendi.",
  ui_story_1019_10190802_26_dialog_content = "(Está Ulysses olhando para mim?)",
  ui_story_1019_10190802_27_dialog_content = "Não te vejo há um tempo, Celestita.",
  ui_story_1019_10190802_28_dialog_content = "Foi na sala de conferências da última vez, você e Reinhardt. Algol também estava lá.",
  ui_story_1019_10190802_29_dialog_content = "Que perda de tempo foi essa reunião tediosa, chata e pretensiosa.",
  ui_story_1019_10190802_30_dialog_content = "Isso foi há muito tempo, após o qual novas mudanças ocorreram neste mundo. Mas nada passou por você. Estou certo, Celestita?",
  ui_story_1019_10190802_31_dialog_content = "O que você quer dizer?",
  ui_story_1019_10190802_32_dialog_content = "Tenho tido visões peculiares há muito tempo, e elas têm vindo até mim com mais frequência nos últimos anos.",
  ui_story_1019_10190802_33_dialog_content = "Aquelas cenas eram tão reais como se controlassem fisicamente os movimentos do meu corpo, as batidas do meu coração...",
  ui_story_1019_10190802_34_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10190802_35_dialog_content = "O que foi?",
  ui_story_1019_10190802_36_dialog_content = "Batimentos cardíacos?",
  ui_story_1019_10190802_37_dialog_content = "Nós dois podemos ver a verdade, mas sempre há alguém tentando me impedir de alcançá-la...",
  ui_story_1019_10190802_38_dialog_content = "E cega você para o propósito da vida... Isso é uma grande pena para você.",
  ui_story_1019_10190802_39_dialog_content = "Ahem, então quem será deixado para lutar contra os Eclipsitas após a revisão final?",
  ui_story_1019_10190802_40_dialog_content = "Do que você está falando? Eu nunca encontrei alguém que eu não pudesse derrotar.",
  ui_story_1019_10190802_41_dialog_content = "Acho que você está tentando ganhar PlayerName e desculpar seus crimes!",
  ui_story_1019_10190802_42_dialog_content = "Dificilmente. Estou simplesmente perguntando ao Último Celestita em Astra por curiosidade.",
  ui_story_1019_10190802_43_dialog_content = "Se você aproveitar a oportunidade, pode ver a verdade aqui...",
  ui_story_1019_10190802_44_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10190802_45_dialog_content = "Ei, espere um segundo. Estou confuso...",
  ui_story_1019_10190802_46_dialog_content = "O que há de errado com Bool?",
  ui_story_1019_10190802_47_dialog_content = "Está agindo estranho. Nunca se comportou assim antes.",
  ui_story_1019_10190802_48_dialog_content = "Heh, quem pode dizer que esse comportamento incomum não é uma bênção?",
  ui_story_1019_10190802_49_dialog_content = "Uma bênção?",
  ui_story_1019_10190802_50_dialog_content = "Quando um pesadelo bate à porta, é uma bênção quando alguém está lá para guardar a entrada.",
  ui_story_1019_10190802_51_dialog_content = "Mas, por enquanto, tudo ainda parece nebuloso...",
  ui_story_1019_10190802_52_dialog_content = "Sabe, o tempo que você gasta sendo enigmático poderia ser melhor aproveitado descobrindo o que há de errado com você.",
  ui_story_1019_10190802_53_dialog_content = "Ah, é bom ser jovem.",
  ui_story_1019_10190802_54_dialog_content = "Então, PlayerName, qual verdade você gostaria de saber?",
  ui_story_1019_10190802_55_dialog_content = "(Não me diga que ele sabe...)",
  ui_story_1019_10190802_56_option_content = "(A verdade por trás dos sonhos?)",
  ui_story_1019_10190802_57_option_content = "(A verdade dos batimentos cardíacos de Vice?)",
  ui_story_1019_10190802_58_dialog_content = "(Mas como ele poderia saber?)",
  ui_story_1019_10190802_59_dialog_content = "(Ou ele está apenas me usando para absolver sua própria culpa, assim como Vivian disse?)",
  ui_story_1019_10190802_60_dialog_content = "Julgando pela maneira como você hesita, você deve ter perguntas.",
  ui_story_1019_10190802_61_dialog_content = "Tudo o que você precisa fazer é vir ao meu laboratório e me ajudar com um pequeno \"experimento\". Então, você saberá a resposta.",
  ui_story_1019_10190802_62_dialog_content = "Podemos até descobrir seus... limites.",
  ui_story_1019_10190802_63_dialog_content = "O Grande Marechal já deixou claro para parar todos os experimentos, Ulysses!",
  ui_story_1019_10190802_64_dialog_content = "Esqueça os experimentos. Toque em PlayerName, e eu mesmo vou te buscar.",
  ui_story_1019_10190802_65_dialog_content = "Vocês dois estão enganados. Eu sou o que vai ser o objeto do experimento, que PlayerName vai conduzir.",
  ui_story_1019_10190802_66_dialog_content = "Afinal, qualquer especulação nascida da curiosidade deve ser verificada através de experimentação, correto?",
  ui_story_1019_10190802_67_dialog_content = "Que experimento você tem em mente?",
  ui_story_1019_10190802_68_dialog_content = "Quero que você use sua habilidade psíquica para ver alguns dos meus sonhos peculiares e ver se a resposta que você está procurando está entre eles.",
  ui_story_1019_10190802_69_dialog_content = "Sonhos peculiares!",
  ui_story_1019_10190802_70_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10190802_71_dialog_content = "O que está acontecendo? Nós deveríamos sair daqui agora, Celestita.",
  ui_story_1019_10190802_72_dialog_content = "Mas eu quero ficar...",
  ui_story_1019_10190802_73_dialog_content = "PlayerName?!",
  ui_story_1019_10190802_74_dialog_content = "Eu quero experimentar este experimento.",
  ui_story_1019_10190802_75_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10190802_76_dialog_content = "Ei, espera... Pare de me arrastar...",
  ui_story_1019_10190802_77_dialog_content = "Desculpe, eu preciso resolver o problema com o Bool primeiro.",
  ui_story_1019_10190802_78_dialog_content = "Não se preocupe. Vou ficar de olho, embora não seja minha responsabilidade.",
  ui_story_1019_10190802_79_dialog_content = "Mas é meu dever garantir que PlayerName esteja seguro.",
  ui_story_1019_10190802_80_dialog_content = "Meu laboratório é seguro. Entre.",
  ui_story_1019_10190901_1_dialog_content = "Você está pronto, Celestita? Gostaria de fazer uma pergunta antes de começarmos.",
  ui_story_1019_10190901_2_dialog_content = "Como você acha que será o fim do mundo?",
  ui_story_1019_10190901_3_dialog_content = "Se a Crise Darkover acontecer novamente, como os Aurorianos podem resistir?",
  ui_story_1019_10190901_4_dialog_content = "Uh, isso nunca passou pela minha cabeça.",
  ui_story_1019_10190901_5_dialog_content = "Os Celestitas uma vez realizaram a grande façanha de deixar Astra. Você não quer saber como é esse céu desconhecido?",
  ui_story_1019_10190901_6_dialog_content = "Esse é um antigo milagre celestita e Colosso muito distante do presente.",
  ui_story_1019_10190901_7_dialog_content = "Sou apenas um cara normal. O canto mais distante que estive é a terra oriental não muito longe de Astra.",
  ui_story_1019_10190901_8_dialog_content = "Heh, vocês sempre deixam o medo limitar a sua imaginação.",
  ui_story_1019_10190901_9_dialog_content = "Por que diz isso?",
  ui_story_1019_10190901_10_dialog_content = "Você descobrirá em breve. Agora, vamos começar.",
  ui_story_1019_10190901_11_dialog_content = "...",
  ui_story_1019_10190901_12_option_content = "Ligação Telepática",
  ui_story_1019_10190901_13_dialog_content = "Isto é Northland...?",
  ui_story_1019_10190901_14_dialog_content = "Tantos pilares de gelo, apontando para o céu como lâminas.",
  ui_story_1019_10190901_15_dialog_content = "Não, a melancolia está mais próxima da da Zona Escura...",
  ui_story_1019_10190901_16_dialog_content = "Eu explorei as Ruínas Aurora antes. Elas têm algumas rochas negras que emitem a mesma vibração fria.",
  ui_story_1019_10190901_17_dialog_content = "Mas essas rochas estão dispostas planas no chão sólido, enquanto esses pilares levitam no ar.",
  ui_story_1019_10190901_18_dialog_content = "Alguns até estão brilhando e se esticando para cima...",
  ui_story_1019_10190901_19_dialog_content = "Isso faz parte das memórias de Ulysses? Por que ele veio para cá?",
  ui_story_1019_10190901_20_dialog_content = "E como tais memórias poderiam existir dentro de sua consciência?",
  ui_story_1019_10190901_21_dialog_content = "Este é um lugar abandonado sem qualquer sinal de vida...",
  ui_story_1019_10190901_22_dialog_content = "<color=#e8d9bb>Clink, clink!</color>",
  ui_story_1019_10190901_23_dialog_content = "O que houve?",
  ui_story_1019_10190901_24_dialog_content = "Os pilares estão mudando como se fossem puxados por alguma força em um aglomerado em direção ao céu.",
  ui_story_1019_10190901_25_dialog_content = "Eles estão se fundindo em algo?",
  ui_story_1019_10190901_26_dialog_content = "O que exatamente é este lugar?",
  ui_story_1019_10190901_27_dialog_content = "<color=#e8d9bb>Colidir...</color>",
  ui_story_1019_10190901_28_dialog_content = "*ofegante*",
  ui_story_1019_10190901_29_dialog_content = "Então, como você está se sentindo, Celestita?",
  ui_story_1019_10190901_30_dialog_content = "O que ele te mostrou, garoto?!",
  ui_story_1019_10190901_31_option_content = "Onde é aquele lugar?",
  ui_story_1019_10190901_32_dialog_content = "Onde...",
  ui_story_1019_10190901_33_option_content = "Por que você está me mostrando isso?",
  ui_story_1019_10190901_34_dialog_content = "Porque...",
  ui_story_1019_10190901_35_dialog_content = "Esse é o fim do mundo.",
  ui_story_1019_10190901_36_dialog_content = "Onde os Eclipsitas espreitam e tentam despertar o demônio...",
  ui_story_1019_10190901_37_dialog_content = "Demônio...?",
  ui_story_1019_10190901_38_dialog_content = "(É isso que eu ouvi falar no Campo de Batalha Antigo?)",
  ui_story_1019_10190901_39_dialog_content = "Mas eu não vi nenhum Eclipsite, apenas inúmeras colunas de gelo.",
  ui_story_1019_10190901_40_dialog_content = "Isso é porque eles já começaram.",
  ui_story_1019_10190901_41_dialog_content = "Começou?",
  ui_story_1019_10190901_42_dialog_content = "Despertando o demônio!",
  ui_story_1019_10190901_43_dialog_content = "...",
  ui_story_1019_10190901_44_dialog_content = "Ulysses, seu lunático! Fique longe de PlayerName!",
  ui_story_1019_10190901_45_dialog_content = "Vejo que o Chefe de Gabinete, Comandante Barton, e PlayerName estão todos aqui...",
  ui_story_1019_10190901_46_dialog_content = "Justo a tempo, Anatoli.",
  ui_story_1019_10190901_47_dialog_content = "O Comitê te mandou para cá, certo?",
  ui_story_1019_10190901_48_dialog_content = "Sim, Dr. Ulysses. É o briefing da investigação Phospherus, sobre o qual você foi informado.",
  ui_story_1019_10190901_49_dialog_content = "Eu vou comparecer. No entanto...",
  ui_story_1019_10190901_50_dialog_content = "Espero que o Celestita também possa participar, já que o Comitê o considera o salvador dos Aurorianos.",
  ui_story_1019_10190901_51_dialog_content = "Temo que isso seja uma violação das regras, Dr. Ulysses.",
  ui_story_1019_10190901_52_dialog_content = "E qual regra permitiu ao Celestita entrar e sair de Gannon à vontade?",
  ui_story_1019_10190901_53_dialog_content = "Considere minha proposta, Celestita. Eu sei que há coisas que você deseja saber.",
  ui_story_1019_10190901_54_dialog_content = "Talvez apenas eu, em toda a Illumina, possa e vá te dizer a verdade.",
  ui_story_1019_10190901_55_dialog_content = "...",
  ui_story_1019_10190901_56_dialog_content = "Você percebe o que é mais importante para você neste momento? Faça preparações para sobreviver antes que o demônio chegue!",
  ui_story_1019_10190901_57_dialog_content = "...",
  ui_story_1019_10190901_58_dialog_content = "Leve Ulysses embora, Anatoli.",
  ui_story_1019_10190901_59_dialog_content = "Celestita?",
  ui_story_1019_10190901_60_dialog_content = "...",
  ui_story_1019_10190901_61_dialog_content = "Hahaha... Como você pode ser o único a salvar os Aurorians, certo? *tosse*",
  ui_story_1019_10190901_62_dialog_content = "Hesitante, fraco, sem ambição! Você é... *tosse*",
  ui_story_1019_10190901_63_dialog_content = "Desculpe, estou atrasado, senhor. Por favor, permita-me ajudá-lo.",
  ui_story_1019_10190901_64_dialog_content = "Isso não é necessário!",
  ui_story_1019_10190901_65_dialog_content = "Hah...",
  ui_story_1019_10190901_66_dialog_content = "(Darkflow? Não, não exatamente...)",
  ui_story_1019_10190901_67_dialog_content = "Eu nunca vou parar... Todos vocês vão se arrepender disso! *tosse*",
  ui_story_1019_10190901_68_dialog_content = "Você está cambaleando, doutor... Tem certeza de que está bem?",
  ui_story_1019_10190901_69_dialog_content = "Sou eu! Não me toque!",
  ui_story_1019_10190901_70_dialog_content = "Hraaagh!!!",
  ui_story_1019_10190901_71_dialog_content = "Brilho, à espreita nas sombras.",
  ui_story_1019_10190901_72_dialog_content = "Um inimigo parecido com um Eclipsita, exatamente como o que encontramos anteriormente...",
  ui_story_1019_10190901_73_dialog_content = "Não é seu inimigo...",
  ui_story_1019_10190901_74_dialog_content = "Então o que é isso?!",
  ui_story_1019_10190901_75_dialog_content = "Guarde isso para o painel de revisão. Lidera-nos, PlayerName, e nós o destruiremos!",
  ui_story_1019_10190901_76_dialog_content = "Claro!",
  ui_story_1019_10190902_1_dialog_content = "Coloque a lâmina no chão, Barton!",
  ui_story_1019_10190902_2_dialog_content = "Eu já relatei isso ao Grande Marechal. As pessoas dela estão a caminho e ela quer que a gente resolva os problemas do laboratório.",
  ui_story_1019_10190902_3_dialog_content = "Você vai deixar aquele lunático vivo? Aquilo nos atacou, mas não o Ulysses!",
  ui_story_1019_10190902_4_dialog_content = "Seria o fim da Illumina se ele libertasse os Eclipsitas no laboratório!",
  ui_story_1019_10190902_5_dialog_content = "Anatoli está encarregado dos assuntos relacionados a Ulysses agora, Barton. O Grande Marechal afirmou que ela iria esclarecer isso.",
  ui_story_1019_10190902_6_dialog_content = "Ei, eu vejo uma multidão! O que eu perdi?",
  ui_story_1019_10190902_7_dialog_content = "Os jovens também estão aqui. Vejo que vocês foram batizados pelo fogo. Até seus cheiros são diferentes!",
  ui_story_1019_10190902_8_dialog_content = "...",
  ui_story_1019_10190902_9_dialog_content = "Vou levar o Dr. Ulysses comigo mesmo que vocês dois atrapalhem.",
  ui_story_1019_10190902_10_dialog_content = "Não se preocupe com isso. Estamos aqui apenas para tomar conta do laboratório dele. Tudo bem, todos para fora!",
  ui_story_1019_10190902_11_dialog_content = "Assumir o meu laboratório? Que ridículo...",
  ui_story_1019_10190902_12_dialog_content = "Sou o presidente do Conselho Científico! Você não pode igualar minhas realizações em dez vidas.",
  ui_story_1019_10190902_13_dialog_content = "É bom que você tenha alcançado tudo isso! Embora o monopólio não seja permitido em Illumina. E eu não acho que exista algum arquivo aqui que eu não consiga descobrir.",
  ui_story_1019_10190902_14_dialog_content = "Mas antes de você sair, doutor, se importa em entregar o acesso ao computador?",
  ui_story_1019_10190902_15_dialog_content = "Nós, do Laboratório Black Umbrella, assumiremos também os sujeitos Eclipsitas e os materiais biológicos.",
  ui_story_1019_10190902_16_dialog_content = "Relaxe, enquanto eu estiver aqui, nenhum Eclipsita vai ficar à solta no Parque Tecnológico.",
  ui_story_1019_10190902_17_dialog_content = "Você realmente não quer descobrir a verdade, Caelestite?",
  ui_story_1019_10190902_18_option_content = "Não, eu não.",
  ui_story_1019_10190902_19_dialog_content = "(Há uma conexão estranha entre Ulysses e as visões...)",
  ui_story_1019_10190902_20_dialog_content = "(Eu tenho que contar para Vivian sobre o que eu vi.)",
  ui_story_1019_10190902_21_option_content = "Gosto sim.",
  ui_story_1019_10190902_22_dialog_content = "(Por que Ulysses me mostraria a visão... Ele estava tentando me dizer algo?)",
  ui_story_1019_10190902_23_dialog_content = "(Mas ele não parece certo, então talvez eu não deva confiar nele...)",
  ui_story_1019_10190902_24_dialog_content = "Acredito que a verdade será revelada após a revisão.",
  ui_story_1019_10190902_25_dialog_content = "Hahaha...",
  ui_story_1019_10190902_26_dialog_content = "Então este é o fim dos Aurorians, eu vejo... Meu esforço foi finalmente pisoteado por vocês, tolos.",
  ui_story_1019_10190902_27_dialog_content = "Esqueça, apenas esqueça...",
  ui_story_1019_10190902_28_dialog_content = "Nesse caso, deixe-me revelar pessoalmente.",
  ui_story_1019_10190902_29_dialog_content = "Será uma espécie de honra para vocês testemunharem a história por si mesmos...",
  ui_story_1019_10190902_30_dialog_content = "Diga a Belisaria para convocar minhas testemunhas.",
  ui_story_1019_10190902_31_dialog_content = "Testemunhas? A quem você está se referindo?",
  ui_story_1019_10190902_32_dialog_content = "Yingel, Axelia, Sean. Apenas chame por eles.",
  ui_story_1019_10190902_33_dialog_content = "Sim, senhor.",
  ui_story_1019_10190902_34_dialog_content = "...",
  ui_story_1019_10190902_35_dialog_content = "Passei suas preocupações para o Grande Marechal, PlayerName, mas agora devemos entregar Ulysses ao comitê de revisão.",
  ui_story_1019_10190902_36_dialog_content = "Antes de chegarem a uma conclusão, temos coisas mais importantes para fazer. Não se esqueça que temos coordenadas para investigar.",
  ui_story_1019_10190902_37_dialog_content = "Mas ainda estou preso à pergunta que ele me fez...",
  ui_story_1019_10190902_38_dialog_content = "Como você acha que será o fim do mundo?",
  ui_story_1019_10190902_39_dialog_content = "Se a Crise Darkover acontecer novamente, como os Aurorianos podem resistir?",
  ui_story_1019_10190902_40_dialog_content = "*respiração profunda* Zuuup...",
  ui_story_1019_10190902_41_dialog_content = "Provavelmente devido a não dormir bem ultimamente, mas tenho me sentido meio perdido como se estivesse faltando algo importante.",
  ui_story_1019_10190902_42_dialog_content = "Se você realmente estivesse sentindo falta de algo, tenho certeza de que continuaria e procuraria por isso, independentemente de quão longe e escuro.",
  ui_story_1019_10190902_43_dialog_content = "Mas Illumina é diferente. É nosso lar, nossa esperança.",
  ui_story_1019_10190902_44_dialog_content = "Se pudermos ver o céu acima das cidades subterrâneas daqui...",
  ui_story_1019_10190902_45_dialog_content = "O sol deve estar alto na superfície.",
  ui_story_1019_10190902_46_dialog_content = "No entanto, para o povo de Illumina, deixar as Subcidades para ficar sob o sol é o mais longe que eles poderiam ir.",
  ui_story_1019_10190902_47_dialog_content = "Gannon não vê o sol há anos, mas permanece seguro da escuridão.",
  ui_story_1019_10190902_48_dialog_content = "Exceto que vamos cada vez mais fundo no subsolo à medida que o tempo passa.",
  ui_story_1019_10190902_49_dialog_content = "Realmente me pergunto como era Gannon quando foi construído pela primeira vez.",
  ui_story_1019_10190902_50_dialog_content = "Uma coisa era certa: os Eclipsitas estavam por toda parte.",
  ui_story_1019_10190902_51_dialog_content = "A ameaça dos Eclipsitas nos impulsionou a sobreviver aqui e tornou nosso objetivo matá-los.",
  ui_story_1019_10190902_52_dialog_content = "Realmente não consigo dizer o que o futuro reserva para a Illumina após o julgamento.",
  ui_story_1019_10190902_53_dialog_content = "...",
  ui_story_1019_10190902_54_dialog_content = "Sei que você tem muita coisa acontecendo na sua cabeça, garoto, mas mantenha-se firme!",
  ui_story_1019_10190902_55_dialog_content = "Eu me sinto mais energizado depois de conversar com todos vocês.",
  ui_story_1019_10190902_56_dialog_content = "Provavelmente isso é um produto do relógio biológico Algol mencionado. Agora é o começo de um novo dia.",
  ui_story_1019_10190902_57_dialog_content = "Entendo...",
  ui_story_1019_10190902_58_dialog_content = "Bem então. Bom dia, Vivian, e Barton.",
  ui_story_1019_10190902_59_dialog_content = "Bom Dia, PlayerName.",
  ui_story_1019_10190902_60_dialog_content = "Bom dia, Illumina! Vá fazer suas coisas e esperamos que acabe logo.",
  ui_story_1019_10191001_1_dialog_content = "<color=#e8d9bb>Em uma sala de conferência de alto nível do Salão de Conferências Illumina, todos parecem silenciosos.</color>",
  ui_story_1019_10191001_2_dialog_content = "Vocês ficam quietos quando é hora de me sentenciar.",
  ui_story_1019_10191001_3_dialog_content = "Aham…",
  ui_story_1019_10191001_4_dialog_content = "Hum...",
  ui_story_1019_10191001_5_dialog_content = "Esta é a quinta revisão já, então por que não mudamos um pouco e temos uma conversa casual. Você não chamou por testemunhas?",
  ui_story_1019_10191001_6_dialog_content = "...",
  ui_story_1019_10191001_7_dialog_content = "Conversa casual? Até quando você vai prolongar isso? As batalhas em Crepúsculo e a linha defensiva de Illumina não provaram a determinação e o poderio de nosso exército?",
  ui_story_1019_10191001_8_dialog_content = "Helios, uma testemunha do exercício militar, ainda está se recuperando de um coma, e os soldados no Programa Phospherus também continuam sendo examinados.",
  ui_story_1019_10191001_9_dialog_content = "Isso são apenas desculpas. Eu exijo provas mais concretas!",
  ui_story_1019_10191001_10_dialog_content = "Eu concordo. Seja o exercício ou o Programa Phospherus, como alguém que passou por ambos, meu testemunho sozinho deve ser suficiente!",
  ui_story_1019_10191001_11_dialog_content = "Vejo que você está se recuperando bem do procedimento, Grande Marechal Wrath.",
  ui_story_1019_10191001_12_dialog_content = "Entendo o seu ponto, mas não podemos simplesmente ignorar as visões e contribuições do Dr. Ulysses.",
  ui_story_1019_10191001_13_dialog_content = "Você ainda não está satisfeito com o tempo que a revisão está levando?",
  ui_story_1019_10191001_14_dialog_content = "Podemos dar a ele outra chance, mas será a última.",
  ui_story_1019_10191001_15_dialog_content = "Reinhardt?",
  ui_story_1019_10191001_16_dialog_content = "Mas com uma condição: minhas forças não cederão mais. Terei minha testemunha presente antes do veredito final.",
  ui_story_1019_10191001_17_dialog_content = "Então você será obrigado a sentenciar Ulysses.",
  ui_story_1019_10191001_18_dialog_content = "Claro. Agora, aproveite o momento, Ulysses, pois gostaria de ouvir algo diferente em sua declaração final.",
  ui_story_1019_10191001_19_dialog_content = "Heh. Eu... *tosse*",
  ui_story_1019_10191001_20_dialog_content = "O seu remédio e água, médico...",
  ui_story_1019_10191001_21_dialog_content = "...",
  ui_story_1019_10191001_22_dialog_content = "Estou bem, só um pouco sob o clima por causa do cansaço.",
  ui_story_1019_10191001_23_dialog_content = "Eu já disse que não escondi nada de você.",
  ui_story_1019_10191001_24_dialog_content = "Sim, mas apenas para as perguntas feitas e nada mais.",
  ui_story_1019_10191001_25_dialog_content = "Desta vez, esperamos que você divulgue os resultados de sua pesquisa e se sua equipe continuará o trabalho após deixar o laboratório, com toda a honestidade.",
  ui_story_1019_10191001_26_dialog_content = "Afinal, seu trabalho é um legado da história, e é hora de passá-lo para uma nova geração.",
  ui_story_1019_10191001_27_dialog_content = "Heh, está insinuando que eu sou muito velho?",
  ui_story_1019_10191001_28_dialog_content = "Eu, Ulysses, nascido em 1945 do Calendário da Manhã, vivi por mais de meio século...",
  ui_story_1019_10191001_29_dialog_content = "Como meus colegas, eu deveria estar morto há muito tempo, de acordo com a expectativa de vida média dos Aurorianos de Illumina.",
  ui_story_1019_10191001_30_dialog_content = "Você realmente quer confiar o oneroso problema do Engenheiro desde a fundação da Illumina aos soldados que só conheciam armas e munições?",
  ui_story_1019_10191001_31_dialog_content = "...",
  ui_story_1019_10191001_32_dialog_content = "Problema do engenheiro? O que isso significa?",
  ui_story_1019_10191001_33_dialog_content = "Você sabe do que ele está falando, Reinhardt?",
  ui_story_1019_10191001_34_dialog_content = "...",
  ui_story_1019_10191001_35_dialog_content = "Não se desvie do assunto, Ulysses. Qual é o seu objetivo para implementar o Programa Phospherus?",
  ui_story_1019_10191001_36_dialog_content = "Como você já sabe, para melhorar a sobrevivência dos Aurorianos, a Illumina vem experimentando a transformação Auroriana há anos.",
  ui_story_1019_10191001_37_dialog_content = "Exceto por Helios e Denier, todos os assuntos notáveis, desde os primeiros experimentos de aprimoramento até o Programa Phospherus, estão presentes aqui.",
  ui_story_1019_10191001_38_dialog_content = "...",
  ui_story_1019_10191001_39_dialog_content = "...",
  ui_story_1019_10191001_40_dialog_content = "Experimentos de aprimoramento e... assuntos notáveis?",
  ui_story_1019_10191001_41_dialog_content = "Muitos soldados da Federação Illumina escolheram melhorar seu poder de combate para proteger a vida das massas.",
  ui_story_1019_10191001_42_dialog_content = "E existem ainda mais Aurorianos com deficiências físicas que prolongaram suas vidas através da tecnologia.",
  ui_story_1019_10191001_43_dialog_content = "Sou eu um, doutor, já que você está olhando diretamente para mim?",
  ui_story_1019_10191001_44_dialog_content = "Eu sou um daqueles que tiveram suas vidas prolongadas pela sua tecnologia?",
  ui_story_1019_10191001_45_dialog_content = "...",
  ui_story_1019_10191001_46_dialog_content = "Isso é uma piada, certo? Eu só vim aqui para check-ups regulares... mas uma transformação que prolonga a vida?",
  ui_story_1019_10191001_47_dialog_content = "Você não é um Aurorian normal, Sean. Você é um sujeito excepcional do Programa Phospherus.",
  ui_story_1019_10191001_48_dialog_content = "...",
  ui_story_1019_10191001_49_dialog_content = "Você achou isso difícil de acreditar, certo? No entanto, você simplesmente não percebe o quão sortudo você é.",
  ui_story_1019_10191001_50_dialog_content = "Para alguém que viveu em uma era de guerra como eu, qualquer um que fosse capaz de lutar poderia tirar o direito de viver daqueles que não eram.",
  ui_story_1019_10191001_51_dialog_content = "Então, que escolha você faria, se estivesse no meu lugar?",
  ui_story_1019_10191001_52_dialog_content = "Qual nova ideia você está ponderando hoje, Uly?",
  ui_story_1019_10191001_53_dialog_content = "O mesmo de antes. Sem novidades.",
  ui_story_1019_10191001_54_dialog_content = "Ah, engenharia genética. Como você acha que eles chegaram a esse termo?",
  ui_story_1019_10191001_55_dialog_content = "Há um ponto para se perguntar?",
  ui_story_1019_10191001_56_dialog_content = "O que é importante é que estou estudando isso agora.",
  ui_story_1019_10191001_57_dialog_content = "\"Como eles chegaram ao termo\" nunca passou pela minha cabeça, porque é frequentemente ridículo determinar a fonte.",
  ui_story_1019_10191001_58_dialog_content = "Gannon foi descoberto por uma força avançada de Lumópolis.",
  ui_story_1019_10191001_59_dialog_content = "Aqueles guerreiros destemidos, quase dizimados ao lutar contra os Eclipsitas, apenas se encontraram abandonados por Lumópolis...",
  ui_story_1019_10191001_60_dialog_content = "Essa força eventualmente evoluiu para um poder militar em um canto da Cidade Baixa.",
  ui_story_1019_10191001_61_dialog_content = "Mas por razões desconhecidas, nunca consigo tirar as palavras de Robby da minha cabeça.",
  ui_story_1019_10191001_62_dialog_content = "Qual nova ideia você está ponderando hoje, Uly?",
  ui_story_1019_10191001_63_dialog_content = "...",
  ui_story_1019_10191001_64_dialog_content = "O que é que você gosta tanto?",
  ui_story_1019_10191001_65_dialog_content = "Os Anais da Federação Illumina... Por que você está lendo isso? Não está mais zombando da história?",
  ui_story_1019_10191001_66_dialog_content = "Você sabe quantos anos a Federação Illumina existe, Robby?",
  ui_story_1019_10191001_67_dialog_content = "<color=#FFB400>649.</color>",
  ui_story_1019_10191001_68_dialog_content = "Você sabe disso ao pé da letra?",
  ui_story_1019_10191001_69_dialog_content = "Claro. Se meu pai não fosse contra, provavelmente eu teria me tornado um historiador com o incentivo da minha mãe.",
  ui_story_1019_10191001_70_dialog_content = "Você não está me testando sobre a época de fundação da Illumina, está?",
  ui_story_1019_10191001_71_dialog_content = "Ao mergulhar na história da engenharia genética, notei um problema nos Anais da Federação Illumina.",
  ui_story_1019_10191001_72_dialog_content = "Não há menção de como a engenharia genética começou na Illumina, como se sempre houvesse um alto limiar a ser cruzado.",
  ui_story_1019_10191001_73_dialog_content = "Você está sugerindo que isso é realmente uma tecnologia de Lumopolis, que existia antes de Illumina?",
  ui_story_1019_10191001_74_dialog_content = "Ou que a história da Illumina vai além de 649 anos?",
  ui_story_1019_10191001_75_dialog_content = "Isso é possível. Vou continuar pesquisando isso.",
  ui_story_1019_10191001_76_dialog_content = "Portanto, fiquei obcecado e determinado a encontrar a resposta.",
  ui_story_1019_10191001_77_dialog_content = "Eu não tinha certeza se era paz ou caos fora do arquivo.",
  ui_story_1019_10191001_78_dialog_content = "Eu só sabia que a guerra não poderia alcançar uma sala tão pequena e interromper meu esforço para encontrar a verdade.",
  ui_story_1019_10191001_79_dialog_content = "Um dia, depois um mês se passou...",
  ui_story_1019_10191001_80_dialog_content = "Havia uma voz na minha cabeça me dizendo para não ter medo de falhar, porque a história eventualmente forneceria a resposta.",
  ui_story_1019_10191001_81_dialog_content = "Um ano, depois dois anos se passaram...",
  ui_story_1019_10191001_82_dialog_content = "Até que um dia...",
  ui_story_1019_10191001_83_dialog_content = "Robby, olha só isso! O que diz ali no canto inferior direito?",
  ui_story_1019_10191001_84_dialog_content = "O Engenheiro?",
  ui_story_1019_10191001_85_dialog_content = "Quem ou o que é aquilo?",
  ui_story_1019_10191001_86_dialog_content = "Percebi muitas lacunas e omissões intencionais sobre a origem da engenharia genética em minha pesquisa.",
  ui_story_1019_10191001_87_dialog_content = "Mas eu encontrei uma resposta em algum lugar do livro.",
  ui_story_1019_10191001_88_dialog_content = "\"O problema de sobrecarga de Lumina foi resolvido sob a orientação de...\"",
  ui_story_1019_10191001_89_dialog_content = "Sob a orientação de quem?",
  ui_story_1019_10191001_90_dialog_content = "Exatamente! Alguém os guiou, certo?",
  ui_story_1019_10191001_91_dialog_content = "O Engenheiro? Você acha que o Engenheiro foi omitido no livro?",
  ui_story_1019_10191001_92_dialog_content = "É isso que a minha intuição está me dizendo.",
  ui_story_1019_10191001_93_dialog_content = "Intrigante como foi apagado no texto principal, mas mantido nas margens...",
  ui_story_1019_10191001_94_dialog_content = "Mas você pode ter certeza, Uly? Há mais do mesmo em outro lugar?",
  ui_story_1019_10191001_95_dialog_content = "Não, mas se você incluiu o Engenheiro em todas aquelas descrições obscuras...",
  ui_story_1019_10191001_96_dialog_content = "Isso explicaria muitas coisas.",
  ui_story_1019_10191001_97_dialog_content = "\"Os Aurorianos rapidamente formaram uma unidade tecnológica para começar a estudar a tecnologia antiga sob a liderança do Engenheiro.\"",
  ui_story_1019_10191001_98_dialog_content = "\"O Engenheiro liderou a unidade de tecnologia para examinar a estrutura da Cidade Gannon e ensinou-os a usar certas tecnologias.\"",
  ui_story_1019_10191001_99_dialog_content = "Nunca te vi tão feliz, Uly.",
  ui_story_1019_10191001_100_dialog_content = "Vou continuar cavando!",
  ui_story_1019_10191001_101_dialog_content = "Ao som constante de barragens de artilharia fora do arquivo...",
  ui_story_1019_10191001_102_dialog_content = "Dê-me mais tempo. Eu sei que eles se transformarão em gritos de vitória dos Aurorianos sobre os Eclipsitas!",
  ui_story_1019_10191101_1_dialog_content = "Como está indo com o mapa da Zona Escura?",
  ui_story_1019_10191101_2_dialog_content = "Ei, se não é o Dr. Algol! Não é todo dia que você se aventura fora do seu laboratório!",
  ui_story_1019_10191101_3_dialog_content = "Olá, Dr. Joyce.",
  ui_story_1019_10191101_4_dialog_content = "Olá. Ei, você não é o Celestita?",
  ui_story_1019_10191101_5_dialog_content = "Olá.",
  ui_story_1019_10191101_6_dialog_content = "Algol me contou que sua Colossus tem sido de grande ajuda no meu mapeamento da Zona Escura. Muito obrigado!",
  ui_story_1019_10191101_7_dialog_content = "Com prazer. Eu prometi minha ajuda à Illumina e isso também me ajuda no processo.",
  ui_story_1019_10191101_8_dialog_content = "Pare de conversar, Joyce. Quero sua opinião sobre uma coordenada da Zona Cega e quão viável é explorá-la.",
  ui_story_1019_10191101_9_dialog_content = "Novos dados sobre a Zona Escura? Você está quase alcançando a <color=#FFB400>simulação geográfica</color>.",
  ui_story_1019_10191101_10_dialog_content = "Como você sabe, meu modelo atual é deduzido dos terrenos que já mapeamos.",
  ui_story_1019_10191101_11_dialog_content = "Isso também significa que se a coordenada estiver muito longe de Gannon com descontinuidade no meio, os cálculos se tornam, bem, complicados.",
  ui_story_1019_10191101_12_dialog_content = "Posso apenas calcular a contiguidade e a descontinuidade separadamente com base em probabilidades e simular os ambientes de acordo.",
  ui_story_1019_10191101_13_dialog_content = "Então, qual é o resultado? Você já chegou a um?",
  ui_story_1019_10191101_14_dialog_content = "Tsc, tão impaciente...",
  ui_story_1019_10191101_15_dialog_content = "Apenas me diga.",
  ui_story_1019_10191101_16_dialog_content = "Tudo bem, tudo bem. Ainda estou aperfeiçoando o modelo a partir das pistas fornecidas por Helios.",
  ui_story_1019_10191101_17_dialog_content = "Fora das regiões habitáveis de Astra, existe uma camada irregular de pântano congelado coberto por uma fina camada de neve.",
  ui_story_1019_10191101_18_dialog_content = "Além do pântano, você tem uma floresta de pilares de gelo em diferentes formas e tamanhos...",
  ui_story_1019_10191101_19_dialog_content = "Alguns são pontiagudos como um espinho, alguns se assemelham a cones de cabeça para baixo, e alguns parecem espirais torcidas...",
  ui_story_1019_10191101_20_dialog_content = "Vá direto ao ponto!",
  ui_story_1019_10191101_21_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191101_22_dialog_content = "Você acha isso interessante?",
  ui_story_1019_10191101_23_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191101_24_dialog_content = "...",
  ui_story_1019_10191101_25_dialog_content = "<color=#e8d9bb>Depois de conversar com Joyce por quinze minutos...</color>",
  ui_story_1019_10191101_26_dialog_content = "... Então, entre esses pilares, parte do ar se liquefaz devido à temperatura e se transforma em monólitos estranhos.",
  ui_story_1019_10191101_27_dialog_content = "Não estou claro sobre o princípio exato, embora possa estar relacionado à tecnologia de levitação de Lumópolis.",
  ui_story_1019_10191101_28_dialog_content = "E à medida que o fluxo de ar se solidificava, alguns subiam enquanto outros desciam...",
  ui_story_1019_10191101_29_dialog_content = "Espere, o que você acabou de dizer?",
  ui_story_1019_10191101_30_dialog_content = "... Essa é a minha conclusão para o motivo de eles parecerem tão diferentes um do outro.",
  ui_story_1019_10191101_31_dialog_content = "O que exatamente você está perguntando?",
  ui_story_1019_10191101_32_dialog_content = "Pilares de rocha que se elevam para cima...",
  ui_story_1019_10191101_33_dialog_content = "Eu os vi na mente de Ulysses.",
  ui_story_1019_10191101_34_dialog_content = "Tenho certeza que foi isso que eu vi... Poderia ser uma coincidência?",
  ui_story_1019_10191101_35_dialog_content = "...",
  ui_story_1019_10191101_36_dialog_content = "Repita o que você acabou de dizer novamente, Joyce.",
  ui_story_1019_10191101_37_dialog_content = "Eu disse, \"Quando o fluxo de ar se solidificou, alguns subiram enquanto outros desciam. É por isso que eles pareciam tão diferentes um do outro.\"",
  ui_story_1019_10191101_38_dialog_content = "Falando em subir e descer, nós fizemos um experimento uma vez...",
  ui_story_1019_10191101_39_dialog_content = "Não pode estar errado...",
  ui_story_1019_10191101_40_dialog_content = "Agora que penso nisso, algumas das colunas de rocha gelada voadoras tinham halos brilhantes nelas...",
  ui_story_1019_10191101_41_dialog_content = "Você quer dizer que viu o núcleo do Guardião Um? Estava naquelas colunas voadoras?!",
  ui_story_1019_10191101_42_dialog_content = "... É assim mesmo?",
  ui_story_1019_10191101_43_dialog_content = "Sim! É isso!",
  ui_story_1019_10191101_44_dialog_content = "Isto é interessante! Que maravilha!",
  ui_story_1019_10191101_45_dialog_content = "O que você viu na mente de Ulysses corresponde exatamente à imagem suspeita de ser o núcleo do Guardian One, que foi enviada de volta pela equipe de expedição da Zona Escura.",
  ui_story_1019_10191101_46_dialog_content = "E se as colunas voadoras estivessem dentro do alcance das coordenadas de Soroz...",
  ui_story_1019_10191101_47_dialog_content = "Entendi... Os sinais piscantes não se traduzem em múltiplas coordenadas, mas sim porque os pilares estão se movendo!",
  ui_story_1019_10191101_48_dialog_content = "Deixe-me entender direito. Então, não só o Ulysses sabe onde o núcleo está, mas provavelmente é de onde os Colossos vieram?",
  ui_story_1019_10191101_49_dialog_content = "Ele até insinuou que sabia com o que Vice se deparou!",
  ui_story_1019_10191101_50_dialog_content = "...",
  ui_story_1019_10191101_51_dialog_content = "Entendi. Eu não apenas fui de grande ajuda para você, mas também resolvi um grande mistério.",
  ui_story_1019_10191101_52_dialog_content = "Tch... Mas se ele está conectado ao Eclipse, isso não é uma boa notícia de qualquer maneira que você olhe.",
  ui_story_1019_10191101_53_dialog_content = "Ulysses nunca deixou a Subcidade, mas está tão profundamente envolvido com o esquema do Eclipse...",
  ui_story_1019_10191101_54_dialog_content = "Estou pensando, será que os Wraiths se infiltraram em Gannon e fugiram com o núcleo do Guardião Um graças a Ulysses?",
  ui_story_1019_10191101_55_dialog_content = "Eu tenho uma teoria ainda mais audaciosa...",
  ui_story_1019_10191101_56_dialog_content = "É impossível para o Guardião Um contornar meu sistema de segurança, a menos que alguém use aquilo para burlá-lo...",
  ui_story_1019_10191101_57_dialog_content = "Esse protótipo \"guardado por motivos de segurança\".",
  ui_story_1019_10191101_58_dialog_content = "...",
  ui_story_1019_10191101_59_dialog_content = "Se Ulysses é quem opera o protótipo em segredo, devemos ir à Assembleia de Illumina e exigir uma explicação.",
  ui_story_1019_10191101_60_dialog_content = "Não, vamos direto para o escritório dele.",
  ui_story_1019_10191101_61_dialog_content = "Se estivermos certos, esse lugar será o mais perigoso em Illumina!",
  ui_story_1019_10191101_62_dialog_content = "...",
  ui_story_1019_10191201_1_dialog_content = "May Eu pergunto, o que você está fazendo? Apagando texto, encobrindo a história...",
  ui_story_1019_10191201_2_dialog_content = "O que você está escondendo sobre o Engenheiro? Ou isso é algum segredo indizível de Lumópolis?",
  ui_story_1019_10191201_3_dialog_content = "O que posso confirmar é que todas as informações sobre o Engenheiro estão disponíveis apenas nos arquivos da Illumina e o Comitê não tem conhecimento além disso.",
  ui_story_1019_10191201_4_dialog_content = "Você me toma por um tolo?!",
  ui_story_1019_10191201_5_dialog_content = "O Comitê não deletou as informações.",
  ui_story_1019_10191201_6_dialog_content = "Pelo menos não o Comitê atual.",
  ui_story_1019_10191201_7_dialog_content = "Se a Crise Darkover não tivesse acontecido, o que forçou os superiores a levantar as restrições sobre a pesquisa do Guardião, eu nunca teria encontrado nada sobre o Engenheiro.",
  ui_story_1019_10191201_8_dialog_content = "Guardião?",
  ui_story_1019_10191201_9_dialog_content = "Uma misteriosa máquina antiga descoberta em Gannon por uma equipe avançada de Lumopolis.",
  ui_story_1019_10191201_10_dialog_content = "Os colonizadores posteriores o nomearam Guardião.",
  ui_story_1019_10191201_11_dialog_content = "O Guardião ainda está em estudo?",
  ui_story_1019_10191201_12_dialog_content = "Algol só tem uma cópia <color=#FFB400>em sandbox</color>. O protótipo foi selado devido a preocupações de segurança.",
  ui_story_1019_10191201_13_dialog_content = "Isso era apenas o plano original...",
  ui_story_1019_10191201_14_dialog_content = "Ulysses?!",
  ui_story_1019_10191201_15_dialog_content = "Sempre suspeitei que havia conexões entre o encobrimento do protótipo e a falta de transparência sobre o Engenheiro.",
  ui_story_1019_10191201_16_dialog_content = "Até que eu encontrei inúmeras anotações do Engenheiro no protótipo.",
  ui_story_1019_10191201_17_dialog_content = "<color=#e8d9bb>Clink, clink!</color>",
  ui_story_1019_10191201_18_dialog_content = "Aí está você, Uly! Eu estive procurando por você o dia todo. Estávamos preocupados que você tivesse ido para a batalha.",
  ui_story_1019_10191201_19_dialog_content = "Disseram que você nunca se levantaria novamente, mas eu sabia que nada poderia te derrubar.",
  ui_story_1019_10191201_20_dialog_content = "Não é?",
  ui_story_1019_10191201_21_dialog_content = "...",
  ui_story_1019_10191201_22_dialog_content = "... Você está estranhamente quieto. O que houve, Uly?",
  ui_story_1019_10191201_23_dialog_content = "Você ainda se lembra dos arquivos do Engenheiro que eu estava investigando?",
  ui_story_1019_10191201_24_dialog_content = "Sim. Mas eu pensei que, com o quão mal a guerra tem ido, além de você... ter perdido sua família, você já teria desistido há muito tempo.",
  ui_story_1019_10191201_25_dialog_content = "Você não vai acreditar nisso, Robby, mas aquela IA antiga recentemente revelada pelo Comitê é a chave para o mistério do Engenheiro.",
  ui_story_1019_10191201_26_dialog_content = "IA antiga? O Guardião, certo? Não é o Algol que está trabalhando nesse caso?",
  ui_story_1019_10191201_27_dialog_content = "Isso é apenas uma cópia virtualizada. Este que você está vendo agora é o original - o protótipo.",
  ui_story_1019_10191201_28_dialog_content = "Uly! Você mexeu no protótipo selado...? Você tem noção de que pode ir para a prisão por isso?",
  ui_story_1019_10191201_29_dialog_content = "Seria diferente se eu pudesse desenterrar as notas de pesquisa do Engenheiro...",
  ui_story_1019_10191201_30_dialog_content = "...",
  ui_story_1019_10191201_31_dialog_content = "O Engenheiro não só lidou com a engenharia genética...",
  ui_story_1019_10191201_32_dialog_content = "Suas hipóteses sobre experimentos aurorianos e tecnologia mágica, bem como pensamentos sobre a natureza do corpo e da mente...",
  ui_story_1019_10191201_33_dialog_content = "Eles atingiram meu cérebro como poderosas correntes elétricas! Nunca estive tão empolgado!",
  ui_story_1019_10191201_34_dialog_content = "Ulisses...",
  ui_story_1019_10191201_35_dialog_content = "Deixe-me terminar.",
  ui_story_1019_10191201_36_dialog_content = "Ele mencionou uma tentativa de edição genética auroriana direcionada em uma de suas notas...",
  ui_story_1019_10191201_37_dialog_content = "O resultado foram características físicas várias centenas de vezes superiores aos aurorianos modernos! Você percebe o que isso significa?",
  ui_story_1019_10191201_38_dialog_content = "A era em que o Engenheiro estava tinha um nível de tecnologia mais avançado do que agora?",
  ui_story_1019_10191201_39_dialog_content = "O quê mais?",
  ui_story_1019_10191201_40_dialog_content = "Ah, e o Engenheiro \"possui\" o Guardião!",
  ui_story_1019_10191201_41_dialog_content = "Não, Robby, nenhum desses é o ponto.",
  ui_story_1019_10191201_42_dialog_content = "O ponto é: se a tecnologia pudesse ser replicada, não teríamos que nos abrigar dos Eclipsitas nesta sombria cidade subterrânea.",
  ui_story_1019_10191201_43_dialog_content = "...",
  ui_story_1019_10191201_44_dialog_content = "Se tudo que você disse é verdade, Uly, isso seria...",
  ui_story_1019_10191201_45_dialog_content = "Surpreendente, não é? Certamente será um avanço e o futuro da Illumina! Também significa a realização do meu sonho - derrotar os Eclipsitas e retornar à superfície!",
  ui_story_1019_10191201_46_dialog_content = "E também o seu sonho de viajar por todo Eoria!",
  ui_story_1019_10191201_47_dialog_content = "Viajando por toda Eoria...",
  ui_story_1019_10191201_48_dialog_content = "Há uma coragem e força incomparáveis no fundo do seu coração, Uly.",
  ui_story_1019_10191201_49_dialog_content = "E lá estava eu, preocupado com você... Fico feliz em ver que você voltou com ânimo.",
  ui_story_1019_10191201_50_dialog_content = "De qualquer forma, contanto que você esteja bem...",
  ui_story_1019_10191201_51_dialog_content = "Não senti nada quando Robby disse isso pela primeira vez.",
  ui_story_1019_10191201_52_dialog_content = "Não foi até ele perder aquele sorriso e ser então dominado pela dor da guerra que eu entendi a verdadeira mensagem.",
  ui_story_1019_10191201_53_dialog_content = "Devo me apressar e recriar o trabalho do Engenheiro antes que os Eclipsitas erradiquem os Aurorians.",
  ui_story_1019_10191201_54_dialog_content = "Mesmo que isso significasse que eu tivesse que isolar todos, inclusive eu mesmo.",
  ui_story_1019_10191201_55_dialog_content = "Porque eu só me sentia vivo quando descobria maneiras de melhorar o poder de combate dos Aurorianos nas anotações do Engenheiro...",
  ui_story_1019_10191201_56_dialog_content = "*Tosse* E alegria também!",
  ui_story_1019_10191201_57_dialog_content = "Você está se sentindo bem, senhor? Você precisa...",
  ui_story_1019_10191201_58_dialog_content = "Estou bem...! *tosse*",
  ui_story_1019_10191201_59_dialog_content = "Levei quase 10 anos para procurar a pista que o Engenheiro deixou para trás e remontar seu trabalho.",
  ui_story_1019_10191201_60_dialog_content = "10 anos! O que eles podem conseguir agora que assumiram meu laboratório?",
  ui_story_1019_10191201_61_dialog_content = "<color=#e8d9bb>Pitter-patter...</color>",
  ui_story_1019_10191201_62_dialog_content = "Os documentos estão incrivelmente organizados. O TOC daquele velhote está nos poupando tempo e esforço. Ei, o que é isso...?",
  ui_story_1019_10191201_63_dialog_content = "...",
  ui_story_1019_10191201_64_dialog_content = "Ei, não concordamos em apenas uma última rodada? Já faz meia hora. Você está tentando trapacear?",
  ui_story_1019_10191201_65_dialog_content = "Bem, você pode fazer isso sozinho se exigir pouco esforço, Migard!",
  ui_story_1019_10191201_66_dialog_content = "Faz muito tempo que não jogo um jogo tão fácil quanto este. A única desvantagem é que ele é muito lento!",
  ui_story_1019_10191201_67_dialog_content = "Está faltando algo nas atualizações gerais dos computadores da Illumina? Ou essa máquina é o tesouro particular do velhote?",
  ui_story_1019_10191201_68_dialog_content = "O que está faltando?",
  ui_story_1019_10191201_69_dialog_content = "Uh, eu juro que não estou jogando enquanto estou de plantão! É, uh...",
  ui_story_1019_10191201_70_dialog_content = "Deixe-me ver o computador.",
  ui_story_1019_10191201_71_dialog_content = "Esta é a máquina, Dr. Algol?",
  ui_story_1019_10191201_72_dialog_content = "Não. Talvez haja alguma pista que estamos perdendo...",
  ui_story_1019_10191201_73_dialog_content = "Espere, não se mexa...",
  ui_story_1019_10191201_74_dialog_content = "O que você está fazendo, chegando tão perto assim?",
  ui_story_1019_10191201_75_dialog_content = "Como vou descobrir o que está errado sem me aproximar dele?",
  ui_story_1019_10191201_76_dialog_content = "Vocês encontraram algo terrível no caminho? Estou com um mau pressentimento...",
  ui_story_1019_10191201_77_dialog_content = "Você está falando de mim ou do Bool?",
  ui_story_1019_10191201_78_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191201_79_dialog_content = "Perigo? Não, grande perigo? Foi esse o caso quando nos conhecemos pela primeira vez Ulysses...",
  ui_story_1019_10191201_80_dialog_content = "Algo parecia errado desde que você chegou. Agora estou com a sensação de que estamos sendo observados neste laboratório...",
  ui_story_1019_10191201_81_dialog_content = "Você consegue sentir, jovem?",
  ui_story_1019_10191201_82_dialog_content = "Um pouco...",
  ui_story_1019_10191201_83_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191201_84_dialog_content = "Ai! Quantas vezes eu tenho que te dizer para não puxar meu pescoço assim, Bool!",
  ui_story_1019_10191201_85_dialog_content = "Fora da porta? O que tem lá...?",
  ui_story_1019_10191201_86_dialog_content = "Oh não, estou sentindo um fluxo muito poderoso de Darkflow...",
  ui_story_1019_10191201_87_dialog_content = "O Eclipsita que passou despercebido... Ele conseguiu evitar os Espinhos Mergulhadores.",
  ui_story_1019_10191201_88_dialog_content = "Cuidado, galera!",
  ui_story_1019_10191201_89_dialog_content = "<color=#828282>Bam!</color>",
  ui_story_1019_10191202_1_dialog_content = "Hraaagh—",
  ui_story_1019_10191202_2_dialog_content = "Finalmente morreu?",
  ui_story_1019_10191202_3_dialog_content = "Tão grande... Seria um chefe em qualquer jogo!",
  ui_story_1019_10191202_4_dialog_content = "Mas não tem marcas de nenhum tipo. Como sabemos de onde veio?",
  ui_story_1019_10191202_5_dialog_content = "Não tem um número de série como os sujeitos Eclipsite.",
  ui_story_1019_10191202_6_dialog_content = "Além disso, nem sabemos se é realmente um assunto Eclipsite ou algo do tipo...",
  ui_story_1019_10191202_7_dialog_content = "É um dos súditos de Ulysses? Ele pretende usar esses monstros contra o Comitê como fez com Wrath e seus guardas?",
  ui_story_1019_10191202_8_dialog_content = "Independentemente, criar armas contra seu próprio povo te faz igual ao Eclipse.",
  ui_story_1019_10191202_9_dialog_content = "O Comitê chegou a uma decisão?",
  ui_story_1019_10191202_10_dialog_content = "Ainda não consigo entrar em contato com o Grande Marechal. A revisão provavelmente ainda não acabou.",
  ui_story_1019_10191202_11_dialog_content = "Não podemos esperar pelo Comitê. Temos que agir agora para rastrear o protótipo e a brecha. Isso é mais urgente do que o julgamento de Ulysses.",
  ui_story_1019_10191202_12_dialog_content = "Certo. Vamos discutir nossas descobertas em dez minutos.",
  ui_story_1019_10191202_13_dialog_content = "Eu tenho que verificar o prédio do laboratório primeiro e isolar os pesquisadores. Eles podem ter informações úteis.",
  ui_story_1019_10191202_14_dialog_content = "Por favor, notifique todos os patrulheiros na proximidade da ameaça, Dr. Algol, e solicite reforços.",
  ui_story_1019_10191202_15_dialog_content = "Ainda não sabemos quantos Eclipsitas estão por perto e devemos estar em alerta máximo.",
  ui_story_1019_10191202_16_dialog_content = "Sem problemas. Tenho que continuar procurando o protótipo por conta própria.",
  ui_story_1019_10191301_1_dialog_content = "Onde eu parei, Esien?",
  ui_story_1019_10191301_2_dialog_content = "Como você só se sentia vivo e alegre quando estava lendo as anotações do Engenheiro...",
  ui_story_1019_10191301_3_dialog_content = "Isso mesmo, alegria...",
  ui_story_1019_10191301_4_dialog_content = "Alegria porque vi a magnífica visão do Engenheiro. Ele usou a engenharia genética auroriana direcionada para criar um lote de supersoldados após o outro!",
  ui_story_1019_10191301_5_dialog_content = "Os supersoldados produzidos em massa eventualmente se tornaram o Projeto: Sol Artificial e o Programa Phospherus?",
  ui_story_1019_10191301_6_dialog_content = "O que realmente me surpreendeu não foi duplicar o experimento, mas a última nota.",
  ui_story_1019_10191301_7_dialog_content = "O número de supersoldados atingiu repentinamente o pico em algum momento <color=#FFB400>600 anos</color> atrás.",
  ui_story_1019_10191301_8_dialog_content = "Mas foi quando o Guardião foi desligado por razões desconhecidas.",
  ui_story_1019_10191301_9_dialog_content = "E o Engenheiro foi para sempre apagado da história da Illumina.",
  ui_story_1019_10191301_10_dialog_content = "Por quê?",
  ui_story_1019_10191301_11_dialog_content = "...",
  ui_story_1019_10191301_12_dialog_content = "O que acha, Yingel?",
  ui_story_1019_10191301_13_dialog_content = "Um... Porque o experimento do Engenheiro falhou?",
  ui_story_1019_10191301_14_dialog_content = "Não, foi um sucesso inquestionável.",
  ui_story_1019_10191301_15_dialog_content = "Foi porque a Illumina finalmente percebeu...",
  ui_story_1019_10191301_16_dialog_content = "Os super-soldados produzidos em massa que o Engenheiro estava criando eram na verdade os próprios Eclipsitas que matariam Aurorianos na batalha.",
  ui_story_1019_10191301_17_dialog_content = "Acho que eu posso estar errado, Robby...",
  ui_story_1019_10191301_18_dialog_content = "Os Eclipsitas recuperados do campo de batalha tinham composições genéticas mais complicadas, mas certas amostras individuais ainda podiam ser isoladas.",
  ui_story_1019_10191301_19_dialog_content = "Os genes dos Aurorianos e de alguns Eclipsitas individuais são mais de 90% compatíveis.",
  ui_story_1019_10191301_20_dialog_content = "90%?",
  ui_story_1019_10191301_21_dialog_content = "A maioria dos Eclipsitas compostos inorganicamente não são mais do que cascas que o inimigo disparou no campo de batalha.",
  ui_story_1019_10191301_22_dialog_content = "Ainda assim, muitos dos outros inimigos têm composições genéticas muito semelhantes às dos Aurorianos. Talvez sejam eles os responsáveis por disparar os projéteis.",
  ui_story_1019_10191301_23_dialog_content = "Nunca seremos capazes de derrotá-los a menos que façamos armas semelhantes. Nem mesmo seremos capazes de identificar os inimigos que estão lançando esses projéteis contra nós.",
  ui_story_1019_10191301_24_dialog_content = "Você está pensando em criar Eclipsitas, Uly?",
  ui_story_1019_10191301_25_dialog_content = "Não, nossas armas serão mais potentes do que isso.",
  ui_story_1019_10191301_26_dialog_content = "Nossas armas são tanto conchas de Eclipsitas quanto Aurorianos com poderosos Luminatics.",
  ui_story_1019_10191301_27_dialog_content = "Integração genética de Eclipsitas e Aurorians...?",
  ui_story_1019_10191301_28_dialog_content = "Você é louco, Uly...",
  ui_story_1019_10191301_29_dialog_content = "Não, eu finalmente descobri tudo.",
  ui_story_1019_10191301_30_dialog_content = "Esta é a única maneira que nós, Aurorianos, temos de vencer os Eclipsitas.",
  ui_story_1019_10191301_31_dialog_content = "Haveria apenas um resultado se lutássemos contra eles com nossas formas nascidas...",
  ui_story_1019_10191301_32_dialog_content = "Então, para esse fim, devemos nos transformar nos Eclipsitas?",
  ui_story_1019_10191301_33_dialog_content = "Não se transformando! Superando-os! É aí que reside o gênio do Engenheiro. Ele fez os Aurorians muito mais poderosos.",
  ui_story_1019_10191301_34_dialog_content = "Você percebe o que está dizendo, Uly? Você está virando as costas para nosso princípio ao rejeitar o propósito de nossa resistência!",
  ui_story_1019_10191301_35_dialog_content = "Desde que você descobriu os trabalhos do Engenheiro, você foi longe demais com sua pesquisa.",
  ui_story_1019_10191301_36_dialog_content = "Já passou pela sua cabeça que, isso é o que o Engenheiro queria, nos enganar para criar Eclipsitas, até mesmo nos tornarmos eles mesmos?",
  ui_story_1019_10191301_37_dialog_content = "Não vou nos transformar em Eclipsitas, mas em Aurorians mais fortes!",
  ui_story_1019_10191301_38_dialog_content = "Eu já descobri o como. O projeto em breve dará início a uma nova fase.",
  ui_story_1019_10191301_39_dialog_content = "Você sempre acredita em mim, não é? Eu posso tornar nossos sonhos realidade. Eu posso mudar o destino de todos os Aurorianos!",
  ui_story_1019_10191301_40_dialog_content = "Não assim, Uly... Não assim...",
  ui_story_1019_10191301_41_dialog_content = "Ainda não descobrimos uma coisa em particular...",
  ui_story_1019_10191301_42_dialog_content = "Se você afirma que o Engenheiro tornou isso possível, quem era ele? Por que ele desapareceu da história da Illumina?",
  ui_story_1019_10191301_43_dialog_content = "Por que ele traiu a Illumina e por que se tornou inimigo de todos os Aurorianos?",
  ui_story_1019_10191301_44_dialog_content = "...",
  ui_story_1019_10191301_45_dialog_content = "Quem diabos era o Engenheiro?",
  ui_story_1019_10191301_46_dialog_content = "Eclipsita? Auroriano? Demônio? Ou talvez...",
  ui_story_1019_10191301_47_dialog_content = "Nenhuma das opções acima? *tosse*",
  ui_story_1019_10191301_48_dialog_content = "Quanto mais você vai tossir? Você não ia dizer nada até morrer se não tentássemos forçá-lo a falar?",
  ui_story_1019_10191301_49_dialog_content = "Heheh... Mesmo que eu quisesse detalhar os 40 anos de processo árduo, o fardo que carrego seria tão grande, que eu não saberia por onde começar...",
  ui_story_1019_10191301_50_dialog_content = "Graças a você, eu me lembro do Robby e de como eu era entusiasmado.",
  ui_story_1019_10191301_51_dialog_content = "Mas a identidade do engenheiro já não me interessa mais.",
  ui_story_1019_10191301_52_dialog_content = "...",
  ui_story_1019_10191301_53_dialog_content = "Talvez você não se importe mais com quem é o Engenheiro, Ulysses.",
  ui_story_1019_10191301_54_dialog_content = "Mas eu me importo para onde a Illumina está indo.",
  ui_story_1019_10191301_55_dialog_content = "Eu te dei tempo suficiente para descrever sua visão.",
  ui_story_1019_10191301_56_dialog_content = "Diga-me, como devo decidir se o Programa Phospherus beneficiou a Illumina?",
  ui_story_1019_10191301_57_dialog_content = "Diante de você está alguém que trouxe uma década de paz para a Illumina, bem como a pessoa com o maior potencial para os próximos dez anos.",
  ui_story_1019_10191301_58_dialog_content = "Existe apenas um caminho para os Aurorians superarem os Eclipsitas, e é esse caminho que eu vou embarcar, mesmo sobre os ossos dos Aurorians.",
  ui_story_1019_10191301_59_dialog_content = "Quer saber o benefício? Essa é a minha resposta.",
  ui_story_1019_10191401_1_dialog_content = "Oficiais... Ouvi uma coisa...",
  ui_story_1019_10191401_2_dialog_content = "Todos os pesquisadores foram notificados para evacuar o centro. O que você está fazendo aqui?",
  ui_story_1019_10191401_3_dialog_content = "Espere um minuto, eu te conheço... Você é o assistente de Ulysses.",
  ui_story_1019_10191401_4_dialog_content = "De qual contenção o sujeito escapou?",
  ui_story_1019_10191401_5_dialog_content = "As cobaias... As cobaias do médico estão todas etiquetadas e armazenadas em lotes.",
  ui_story_1019_10191401_6_dialog_content = "Estes... Desculpe, mas eu nunca os vi antes. No entanto, os arquivos relevantes devem estar no computador do médico.",
  ui_story_1019_10191401_7_dialog_content = "Eu verifiquei o computador de Ulysses. Apenas dados de experimentos e relatórios.",
  ui_story_1019_10191401_8_dialog_content = "Então, de onde eles vieram?",
  ui_story_1019_10191401_9_dialog_content = "Vejamos...",
  ui_story_1019_10191401_10_dialog_content = "Acesso negado? Acho que ele fez uma contingência.",
  ui_story_1019_10191401_11_dialog_content = "O que você acha, Bool?",
  ui_story_1019_10191401_12_dialog_content = "Uuuh!",
  ui_story_1019_10191401_13_dialog_content = "Sim, isso é maravilhoso!",
  ui_story_1019_10191401_14_dialog_content = "Insira sua senha, assistente.",
  ui_story_1019_10191401_15_dialog_content = "Certo...",
  ui_story_1019_10191401_16_dialog_content = "<color=#e8d9bb>Clique, clique—</color>",
  ui_story_1019_10191401_17_dialog_content = "<color=#e8d9bb>Ampliação!</color>",
  ui_story_1019_10191401_18_dialog_content = "Sim, eu encontrei!",
  ui_story_1019_10191401_19_dialog_content = "Os arquivos sobre supersoldados... Quantas iterações eles já passaram?",
  ui_story_1019_10191401_20_dialog_content = "Eu nunca vi esses antes no laboratório...",
  ui_story_1019_10191401_21_dialog_content = "Claro que não. São os próprios experimentos secretos de Ulysses!",
  ui_story_1019_10191401_22_dialog_content = "Esses super-soldados devem ser os que têm nos atacado. Onde eles estão sendo mantidos?",
  ui_story_1019_10191401_23_dialog_content = "Mantido, mantido...",
  ui_story_1019_10191401_24_dialog_content = "Uuuh!",
  ui_story_1019_10191401_25_dialog_content = "Encontrei!",
  ui_story_1019_10191401_26_dialog_content = "<color=#FFB400>Armazém Zero</color>? Não seria isso...",
  ui_story_1019_10191401_27_dialog_content = "Existe um Armazém Zero em Gannon?",
  ui_story_1019_10191401_28_dialog_content = "Nunca ouvi falar.",
  ui_story_1019_10191401_29_dialog_content = "Se é o Armazém Zero que estou pensando...",
  ui_story_1019_10191401_30_dialog_content = "Me siga!",
  ui_story_1019_10191401_31_dialog_content = "...",
  ui_story_1019_10191401_32_dialog_content = "Eles são todos muito rápidos para mim...",
  ui_story_1019_10191401_33_dialog_content = "Isso vai além de transformar Aurorians... É uma produção em massa de Eclipsitas!",
  ui_story_1019_10191401_34_dialog_content = "Os que estão violando o sistema de defesa já são perigosos o suficiente. Estaremos mortos se não encontrarmos a fonte rapidamente.",
  ui_story_1019_10191401_35_dialog_content = "<color=#e8d9bb>Crunch!</color>",
  ui_story_1019_10191401_36_dialog_content = "... Este é o Armazém Zero?",
  ui_story_1019_10191401_37_dialog_content = "Tão enorme!",
  ui_story_1019_10191401_38_dialog_content = "Todos os portões estão abertos... É grande o suficiente para estacionar vários Engine VII.",
  ui_story_1019_10191401_39_dialog_content = "Cheira a soluções... É aqui que os experimentos são conduzidos? Tenham cuidado, todos.",
  ui_story_1019_10191401_40_dialog_content = "<color=#e8d9bb>*Estático*</color>",
  ui_story_1019_10191401_41_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191401_42_dialog_content = "É real...",
  ui_story_1019_10191401_43_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_1019_10191401_44_dialog_content = "Esse barulho veio do aparelho à frente! É um super-soldado!",
  ui_story_1019_10191401_45_dialog_content = "Parece um experimento meio feito para mim, muito parecido com os monstros que nos emboscaram antes.",
  ui_story_1019_10191401_46_dialog_content = "Boa coisa que encontramos a fonte! Tenham cuidado ao verificar as coisas, todos.",
  ui_story_1019_10191401_47_dialog_content = "<color=#e8d9bb>*Estático*</color>",
  ui_story_1019_10191401_48_dialog_content = "Nossa, ei!",
  ui_story_1019_10191401_49_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191401_50_dialog_content = "É melhor você não tocar nesses, Dr. Algol. Não queremos ativar nenhuma armadilha!",
  ui_story_1019_10191401_51_dialog_content = "Painel de controle de temperatura, botão de abortar, entrada...",
  ui_story_1019_10191401_52_dialog_content = "Não pode estar errado...",
  ui_story_1019_10191401_53_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_1019_10191401_54_dialog_content = "Esse super-soldado com certeza está lutando muito para se afastar daquele aparelho!",
  ui_story_1019_10191401_55_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191401_56_dialog_content = "O exterior do display e do mainframe foi substituído, mas o sistema operacional, interface e painéis de comando...",
  ui_story_1019_10191401_57_dialog_content = "\"Preocupações de segurança\" era apenas um truque?",
  ui_story_1019_10191401_58_dialog_content = "E aqui...",
  ui_story_1019_10191401_59_dialog_content = "Ainda está funcionando...",
  ui_story_1019_10191401_60_dialog_content = "O que diabos ele esteve fazendo aqui todo esse tempo?",
  ui_story_1019_10191401_61_dialog_content = "Uuuuuu!!!",
  ui_story_1019_10191401_62_dialog_content = "Bool é incrivelmente rápido!",
  ui_story_1019_10191401_63_dialog_content = "<color=#e8d9bb>Clang... Clink...!!!</color>",
  ui_story_1019_10191401_64_dialog_content = "Roaaaar—",
  ui_story_1019_10191401_65_dialog_content = "Ah não, o super-soldado está à solta!",
  ui_story_1019_10191401_66_dialog_content = "Não é seguro aqui, Dr. Algol, por favor, saia!",
  ui_story_1019_10191401_67_dialog_content = "...",
  ui_story_1019_10191401_68_dialog_content = "Dr. Algol!!!",
  ui_story_1019_10191401_69_dialog_content = "...",
  ui_story_1019_10191401_70_dialog_content = "<color=#e8d9bb>Rachadura—!!!</color>",
  ui_story_1019_10191401_71_dialog_content = "Habilidade de Mecha!",
  ui_story_1019_10191401_72_dialog_content = "Não são paredes, mas portões em um espaço tão copioso!",
  ui_story_1019_10191401_73_dialog_content = "Saia daqui. Temos um grande monstro em nosso encalço!",
  ui_story_1019_10191401_74_dialog_content = "Recue para a entrada... Eu não entendo. Estava vazio quando entramos!",
  ui_story_1019_10191401_75_dialog_content = "... Foi assustador quando ficou em pé.",
  ui_story_1019_10191401_76_dialog_content = "Mas uma vez que o Dr. Algol entrou, ela estava muito intrigada para mover seus passos.",
  ui_story_1019_10191401_77_dialog_content = "Dr. Algol!",
  ui_story_1019_10191401_78_dialog_content = "Bu! Bu! Bu!",
  ui_story_1019_10191401_79_dialog_content = "Lutar contra Eclipsitas é a sua especialidade.",
  ui_story_1019_10191401_80_dialog_content = "Tem um Eclipsite atrás de você! Você não pode ignorar sua própria segurança, independente de tudo!",
  ui_story_1019_10191401_81_dialog_content = "Você entenderá minha escolha se passou pela dor.",
  ui_story_1019_10191401_82_dialog_content = "Todos esses pelos que eu arranquei um por um...",
  ui_story_1019_10191401_83_dialog_content = "Todos os dedos que eu roí até sangrarem...",
  ui_story_1019_10191401_84_dialog_content = "E todos os códigos que me atormentavam, mas ao mesmo tempo me excitavam...",
  ui_story_1019_10191401_85_dialog_content = "Sem chance de eu deixar esse protótipo novamente!",
  ui_story_1019_10191401_86_dialog_content = "...",
  ui_story_1019_10191401_87_dialog_content = "Proteja o Dr. Algol e prepare-se para lutar!",
  ui_story_1019_10191502_1_dialog_content = "Estão todos bem?",
  ui_story_1019_10191502_2_dialog_content = "Apenas arranhões. Nada de mais.",
  ui_story_1019_10191502_3_dialog_content = "Você está sangrando... Não me diga que vai se transformar em um monstro por infecção, como aqueles nos jogos?",
  ui_story_1019_10191502_4_dialog_content = "... O que você está dizendo? Arranhões como esses são comuns no Laboratório Black Umbrella.",
  ui_story_1019_10191502_5_dialog_content = "Mas as Espinhas de Mergulho responderam além do normal. Sua composição e saída de energia mostraram mudanças substanciais.",
  ui_story_1019_10191502_6_dialog_content = "Concordo! Mas esses monstros ainda não são páreo para o meu Trono!",
  ui_story_1019_10191502_7_dialog_content = "Qual é o plano de Ulysses para fazer esses supersoldados secretamente? E o protótipo ainda está em funcionamento...",
  ui_story_1019_10191502_8_dialog_content = "Dado o quão teimoso ele é com o Programa Phospherus, não é difícil perceber que ele queria substituir os aurorianos por super-soldados e aumentar as chances de sobrevivência dos aurorianos.",
  ui_story_1019_10191502_9_dialog_content = "O que me preocupa é: esses são todos os super-soldados? Há mais de uma centena de Aurorianos transformados apenas na Guarda Legionária de Wrath...",
  ui_story_1019_10191502_10_dialog_content = "Vamos ver se a Dra. Algol descobriu algo novo. Talvez ela tenha encontrado a origem e o número total de supersoldados.",
  ui_story_1019_10191502_11_dialog_content = "<color=#e8d9bb>Clique, clique—</color>",
  ui_story_1019_10191502_12_dialog_content = "Bool pode apertar botões... e rápido nisso!",
  ui_story_1019_10191502_13_dialog_content = "Isso mesmo.",
  ui_story_1019_10191502_14_dialog_content = "Agora eu sei por que Bool puxou meu cabelo.",
  ui_story_1019_10191502_15_dialog_content = "Buá!",
  ui_story_1019_10191502_16_dialog_content = "Dr. Algol, como o Bool está executando o protótipo?",
  ui_story_1019_10191502_17_dialog_content = "Está ligado ao seu cérebro enquanto diz aos seus tentáculos para executar seus comandos?",
  ui_story_1019_10191502_18_dialog_content = "Bom palpite, mas não. Bool provavelmente está copiando minha ação anterior, aproveitando seu senso tátil e memória.",
  ui_story_1019_10191502_19_dialog_content = "Alguma coisa nova aqui, Dr. Algol?",
  ui_story_1019_10191502_20_dialog_content = "Esses super-soldados semi-acabados são de fato os mesmos que nos atacaram.",
  ui_story_1019_10191502_21_dialog_content = "São todos eles?",
  ui_story_1019_10191502_22_dialog_content = "Já é incrível o suficiente para mim descobrir o protótipo em funcionamento...",
  ui_story_1019_10191502_23_dialog_content = "Mas provavelmente não saberei mais detalhes sobre esses soldados até que eu entre no sistema.",
  ui_story_1019_10191502_24_dialog_content = "Espero que possamos verificar o armazém cuidadosamente enquanto Bool executa os algoritmos, para ver se há algum outro assunto ou armazém presente.",
  ui_story_1019_10191502_25_dialog_content = "Tudo, desde o roubo do núcleo do Guardião Um até as brechas nas defesas de Gannon, tem algo a ver com Ulysses.",
  ui_story_1019_10191502_26_dialog_content = "O que preciso fazer agora é encontrar qualquer outro risco que este protótipo ainda em funcionamento possa representar, e para que Ulysses o usou.",
  ui_story_1019_10191502_27_dialog_content = "Eu realmente quero dar uma entrevista exclusiva para Ulysses agora mesmo...",
  ui_story_1019_10191502_28_dialog_content = "Desligado por causa de preocupações de segurança... Que engraçado.",
  ui_story_1019_10191502_29_dialog_content = "Por que isso é engraçado?",
  ui_story_1019_10191502_30_dialog_content = "Antes de qualquer pesquisa sobre o Guardião ser permitida, eu visitei esta máquina como um dos alunos de Ulysses.",
  ui_story_1019_10191502_31_dialog_content = "Ele não parecia interessado em IA naquela época e fazia apenas o que deveria. Então, quando ouvi que foi fechado por motivos de segurança, pensei que ele tinha desistido completamente da ideia.",
  ui_story_1019_10191502_32_dialog_content = "Então, por que ele tem usado isso em segredo?",
  ui_story_1019_10191502_33_dialog_content = "Nenhum dos zero progressos no estudo foi devido à má configuração ou à falta de registros históricos...",
  ui_story_1019_10191502_34_dialog_content = "Sempre se deveu às pessoas que faziam a pesquisa.",
  ui_story_1019_10191502_35_dialog_content = "Uuuuuu!!!",
  ui_story_1019_10191502_36_dialog_content = "<color=#e8d9bb>Ampliação!</color>",
  ui_story_1019_10191502_37_dialog_content = "Bem feito...",
  ui_story_1019_10191502_38_dialog_content = "Finalmente vamos ver a verdadeira forma do Guardião?",
  ui_story_1019_10191502_39_dialog_content = "Um círculo e quatro cursores... Do que se trata isso?",
  ui_story_1019_10191502_40_dialog_content = "Parece que é necessário uma senha de login. Mas não tenho ideia se é o próprio protocolo do protótipo ou a medida de segurança do Ulysses...",
  ui_story_1019_10191502_41_dialog_content = "O que vamos encontrar depois de fazer login?",
  ui_story_1019_10191502_42_dialog_content = "Vamos descobrir depois que entrarmos.",
  ui_story_1019_10191502_43_dialog_content = "Prepare-se para pular as instruções, Bool!",
  ui_story_1019_10191502_44_dialog_content = "Buá!",
  ui_story_1020_10200101_1_dialog_content = "<size=45>Uuuuu!</size>",
  ui_story_1020_10200101_2_dialog_content = "O Bool realmente consegue quebrar a senha?",
  ui_story_1020_10200101_3_dialog_content = "Bool é tão rápido... É incrível ver até de perto.",
  ui_story_1020_10200101_4_dialog_content = "Isso só comprova minhas suspeitas...",
  ui_story_1020_10200101_5_dialog_content = "Bool exibiu uma resposta tão poderosa ao entrar no escritório de Ulysses e em relação ao próprio Ulysses.",
  ui_story_1020_10200101_6_dialog_content = "Talvez Bool estivesse tentando me dizer que o protótipo está de alguma forma conectado a Ulysses.",
  ui_story_1020_10200101_7_dialog_content = "Como Bool sabe?",
  ui_story_1020_10200101_8_dialog_content = "Também gostaria de saber. Afinal, não parece ser a primeira vez que Bool opera este protótipo.",
  ui_story_1020_10200101_9_dialog_content = "Tudo começou quando eu e Bool nos conhecemos pela primeira vez.",
  ui_story_1020_10200101_10_dialog_content = "Antes do protótipo ser selado, uma equipe de pesquisadores e eu criamos uma cópia isolada do Sistema Guardião bem aqui neste armazém arruinado.",
  ui_story_1020_10200101_11_dialog_content = "Preocupado que perderíamos certos detalhes, fiquei até tarde todos os dias. Admito que parte disso também vinha do meu desejo de passar mais tempo com o protótipo.",
  ui_story_1020_10200101_12_dialog_content = "O zumbido das máquinas me ajudava a dormir à noite, mas de vez em quando, eu era acordado por um estranho bip...",
  ui_story_1020_10200101_13_dialog_content = "Levei o simulador de volta para o meu quarto quando ele terminou, apenas para descobrir que algo como um cabo ou um tentáculo havia se enrolado no meu pescoço...",
  ui_story_1020_10200101_14_dialog_content = "Desde então, uma parte do protótipo se agarrou a você como um parasita.",
  ui_story_1020_10200101_15_dialog_content = "Isso parece que compartilha certas semelhanças com o Trono e os Diving Spines.",
  ui_story_1020_10200101_16_dialog_content = "Talvez, mas nenhum de vocês poderia imaginar o quão assustador foi encontrar o Bool pela primeira vez!",
  ui_story_1020_10200101_17_dialog_content = "Destruíu todos os móveis do meu quarto sem descanso ou hesitação.",
  ui_story_1020_10200101_18_dialog_content = "Sempre que eu tentava me comunicar com Bool, ficava um pouco confrontador...",
  ui_story_1020_10200101_19_dialog_content = "Minha clavícula, minhas costelas, minha escápula... Fraturou praticamente qualquer parte do meu corpo que pudesse envolver...",
  ui_story_1020_10200101_20_dialog_content = "Você chama isso de \"confronto\"? Parece que Bool estava tentando te matar!",
  ui_story_1020_10200101_21_dialog_content = "É exatamente por isso que estou tão focado no treinamento físico.",
  ui_story_1020_10200101_22_dialog_content = "Espere um minuto... É por isso que você tem tanto equipamento de exercício no seu laboratório? Para fortalecer seu corpo contra os ataques de Bool?",
  ui_story_1020_10200101_23_dialog_content = "Isso e os meus exames físicos diários, sim... Na verdade, eu até me consideraria um frequentador regular do Centro Médico Illumina!",
  ui_story_1020_10200101_24_dialog_content = "É inacreditável até onde você irá para estudar Bool, Dr. Algol...",
  ui_story_1020_10200101_25_dialog_content = "É realmente emocionante ver uma mulher dedicada à ciência.",
  ui_story_1020_10200101_26_dialog_content = "Eu sabia que Bool não tinha nenhuma má vontade contra mim. Às vezes, apenas leva um tempo para os amigos se acostumarem um com o outro.",
  ui_story_1020_10200101_27_dialog_content = "Mas quando comecei a me concentrar novamente no meu trabalho, percebi que Bool era muito mais do que uma criatura parasitária.",
  ui_story_1020_10200101_28_dialog_content = "Estava extremamente interessado na minha pesquisa e até me forneceu um feedback muito útil.",
  ui_story_1020_10200101_29_dialog_content = "É difícil imaginar pelo que Bool passou, de ser parte do protótipo para o que é agora...",
  ui_story_1020_10200101_30_dialog_content = "De qualquer forma, quando me acostumei com a presença de Bool, percebi de repente que havia passado quase seis meses trancado no meu laboratório.",
  ui_story_1020_10200101_31_dialog_content = "Mas aquele semestre foi o período mais relaxante e gratificante da minha vida.",
  ui_story_1020_10200101_32_dialog_content = "Foi quando as pessoas começaram a me rotular como um robô e um solitário sem amigos, mas eu não me importava.",
  ui_story_1020_10200101_33_dialog_content = "Não preciso me explicar para aurorianos que nunca vão me entender. Sempre me senti mais confortável perto de máquinas de qualquer maneira.",
  ui_story_1020_10200101_34_dialog_content = "Lidar com o Guardian One também não foi fácil... e me desgastou bastante.",
  ui_story_1020_10200101_35_dialog_content = "Então primeiro foi o Guardião Um, e depois Bool? Dr. Algol, você realmente é—",
  ui_story_1020_10200101_36_dialog_content = "Esquisito?",
  ui_story_1020_10200101_37_dialog_content = "Um pouco, mas isso só te torna ainda mais interessante!",
  ui_story_1020_10200101_38_dialog_content = "Concordo. Eu sempre gostei de ser estranho, sabe.",
  ui_story_1020_10200101_39_dialog_content = "Isso é realmente música para os meus ouvidos. Eu também me encaixo nessa descrição.",
  ui_story_1020_10200101_40_dialog_content = "Nada de errado com rótulos! Apenas confira os meus: Jogador Ás, Máquina de Raid e Azarado da Próxima Rodada...",
  ui_story_1020_10200101_41_dialog_content = "Quero conseguir o máximo de etiquetas possíveis nessa linha!",
  ui_story_1020_10200101_42_dialog_content = "Eu também gostaria, porque eles parecem únicos. E você, jovem, qual é o seu rótulo?",
  ui_story_1020_10200101_43_dialog_content = "Eu não acho que eu tenha nenhum rótulo...",
  ui_story_1020_10200101_44_dialog_content = "Eu sei, é o Perdedor!",
  ui_story_1020_10200101_45_dialog_content = "S-Sim, claro...",
  ui_story_1020_10200101_46_dialog_content = "Então você aceita isso agora com prazer, mesmo tendo odiado antes?",
  ui_story_1020_10200101_47_dialog_content = "Eu simplesmente não consigo pensar em mais nada agora...",
  ui_story_1020_10200101_48_dialog_content = "Chega de conversa. O que devemos fazer agora, Dr. Algol?",
  ui_story_1020_10200101_49_dialog_content = "Ah, nada por enquanto.",
  ui_story_1020_10200101_50_dialog_content = "Ouviu esses sons? Parece que Bool está passando pelos arquivos de dados atualizados do protótipo por instinto.",
  ui_story_1020_10200101_51_dialog_content = "Depois disso, Bool ajustará sua lógica operacional e quebrará a senha. No entanto, pode levar um pouco mais de tempo.",
  ui_story_1020_10200101_52_dialog_content = "Mas uma vez que esteja concluído, teremos acesso a mais do que apenas os esquemas de Ulysses.",
  ui_story_1020_10200101_53_dialog_content = "Talvez até possamos usar os códigos de defesa do Guardião para construir um novo núcleo e reforçar as defesas de Illumina.",
  ui_story_1020_10200101_54_dialog_content = "Isso será maravilhoso!",
  ui_story_1020_10200101_55_dialog_content = "Estou surpreso que este protótipo ainda esteja funcionando depois de todos esses anos. Além disso, ele só foi descoberto graças a um Caelestite.",
  ui_story_1020_10200101_56_dialog_content = "Acho que você não pode descartar nenhuma possibilidade quando se trata de pesquisa.",
  ui_story_1020_10200101_57_dialog_content = "Hahaha... É de explodir a cabeça, mesmo! Hahahaha!",
  ui_story_1020_10200101_58_dialog_content = "Eu tenho uma pergunta... Se Ulysses realmente está produzindo secretamente supersoldados neste lugar...",
  ui_story_1020_10200101_59_dialog_content = "Ele não se sentiria desconfortável tratando tantos soldados feridos de volta ao centro médico?",
  ui_story_1020_10200101_60_dialog_content = "Eu não acho que ele se sentiria assim se o protótipo nos dissesse que ele estava trabalhando com Eclipsitas.",
  ui_story_1020_10200101_61_dialog_content = "As pessoas não procuram razões para explicar suas ações malignas. Eles apenas se deleitam em seus métodos.",
  ui_story_1020_10200201_1_dialog_content = "Diante de você está alguém que trouxe uma década de paz para a Illumina, bem como a pessoa com o maior potencial para os próximos dez anos.",
  ui_story_1020_10200201_2_dialog_content = "Quer saber o benefício? Essa é a minha resposta.",
  ui_story_1020_10200201_3_dialog_content = "Trouxe uma década de paz para Illumina... Você está se referindo a Reinhardt?",
  ui_story_1020_10200201_4_dialog_content = "Illumina teve vários Grandes Marechais, alguns eram naturalmente fortes, mas a maioria dependia de trabalho árduo.",
  ui_story_1020_10200201_5_dialog_content = "Antes de Reinhardt, muitos desses Grandes Marechais não conseguiam controlar seus poderes...",
  ui_story_1020_10200201_6_dialog_content = "Eles voluntariamente ou à força terminaram suas vidas.",
  ui_story_1020_10200201_7_dialog_content = "Experimentos semelhantes já estavam em andamento há anos antes de eu nascer.",
  ui_story_1020_10200201_8_dialog_content = "Acredito que este é o passado que a Illumina nunca gostaria de mencionar. Além disso, é um tapa na cara dos pesquisadores.",
  ui_story_1020_10200201_9_dialog_content = "Se eu não tivesse proposto a ideia de modificar soldados quando ainda são crianças e o processo de seleção para a <color=#FFB400>Subcidade 80</color>...",
  ui_story_1020_10200201_10_dialog_content = "Não haveria um Grande Marechal tão valente como Reinhardt em Illumina.",
  ui_story_1020_10200201_11_dialog_content = "...",
  ui_story_1020_10200201_12_dialog_content = "O lançamento do Projeto: Sol Artificial finalmente colocou a tecnologia Illumina no caminho certo. Poderíamos até dizer que se destacou.",
  ui_story_1020_10200201_13_dialog_content = "Provavelmente sacrificamos algumas pessoas no interim, mas isso foi necessário para manter a paz e o progresso.",
  ui_story_1020_10200201_14_dialog_content = "Então você admite que o desastre em <color=#FFB400>Undercity 80</color> não foi devido a um relatório errôneo...",
  ui_story_1020_10200201_15_dialog_content = "Claro que não, mas não preciso explicar cada passo do experimento para o público.",
  ui_story_1020_10200201_16_dialog_content = "Uma administração estável requer controle rigoroso. Isso só tornaria o impacto ético e moral mais letal para o povo de Illumina.",
  ui_story_1020_10200201_17_dialog_content = "Impacto ético e moral...",
  ui_story_1020_10200201_18_dialog_content = "Informações que custaram a vida dos meus companheiros eram apenas um passo no experimento para você...",
  ui_story_1020_10200201_19_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1020_10200201_20_dialog_content = "Ainda se lembra do objetivo desta missão de reconhecimento em Undercity 80?",
  ui_story_1020_10200201_21_dialog_content = "Devemos ter sucesso!",
  ui_story_1020_10200201_22_dialog_content = "Graaah!",
  ui_story_1020_10200201_23_dialog_content = "Senhor! Esta é a informação que <color=#FFB400>Peng</color> me deu... Ele não desonrou a equipe de escoteiros!",
  ui_story_1020_10200201_24_dialog_content = "Peng... Bom trabalho! Você se saiu extremamente bem!",
  ui_story_1020_10200201_25_dialog_content = "A saída está à nossa frente, Anatoli. Vamos correr até lá fora!",
  ui_story_1020_10200201_26_dialog_content = "Sim, senhor!",
  ui_story_1020_10200201_27_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1020_10200201_28_dialog_content = "Senhor!",
  ui_story_1020_10200201_29_dialog_content = "Dê a Anatoli a informação! Você, e vocês, cubram a retirada comigo!",
  ui_story_1020_10200201_30_dialog_content = "Sim, senhor!",
  ui_story_1020_10200201_31_dialog_content = "Senhor, eu—",
  ui_story_1020_10200201_32_dialog_content = "Ainda se lembra do que eu te ensinei sobre o trabalho de reconhecimento?",
  ui_story_1020_10200201_33_dialog_content = "...",
  ui_story_1020_10200201_34_dialog_content = "Se um membro companheiro lhe entregar alguma informação, você deve fugir com ela imediatamente a todo custo!",
  ui_story_1020_10200201_35_dialog_content = "Entendi, senhor! Mas todos nós conseguiremos sair!",
  ui_story_1020_10200201_36_dialog_content = "Graaah!",
  ui_story_1020_10200201_37_dialog_content = "Argh...",
  ui_story_1020_10200201_38_dialog_content = "Você já esqueceu o que eu te disse? Não deixe as emoções interferirem no seu trabalho! Ao fazer o trabalho de reconhecimento, só há informações, Eclipsitas e pessoas mortas!",
  ui_story_1020_10200201_39_dialog_content = "Sair!",
  ui_story_1020_10200201_40_dialog_content = "Graaah!",
  ui_story_1020_10200201_41_dialog_content = "Senhor!",
  ui_story_1020_10200201_42_dialog_content = "... Vai!",
  ui_story_1020_10200201_43_dialog_content = "... Retorne com as informações que eu te dei, Anatoli...",
  ui_story_1020_10200201_44_dialog_content = "... Comigo cobrindo sua retirada, você deve ser capaz de correr... mais rápido...",
  ui_story_1020_10200201_45_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1020_10200201_46_dialog_content = "Você descartou as vidas e propósitos deles sem nenhum remorso!",
  ui_story_1020_10200201_47_dialog_content = "Reinhardt ganhou seu título como a Iluminação Iluminada da recuperação em Undercity 80. Seu sacrifício levou a uma década de paz.",
  ui_story_1020_10200201_48_dialog_content = "Você não acha que valeu a pena permitir que pessoas como você e eu vivêssemos?",
  ui_story_1020_10200201_49_dialog_content = "... Eu respeito tudo o que o Grande Marechal fez pela Illumina.",
  ui_story_1020_10200201_50_dialog_content = "Mas a determinação para descobrir por que meus companheiros morreram é o que me manteve vivo.",
  ui_story_1020_10200201_51_dialog_content = "Todos esses anos seguindo você, eu deveria ter percebido mais cedo...",
  ui_story_1020_10200201_52_dialog_content = "Como Oficial de Inteligência, meu objetivo é fazer com que mais soldados sobrevivam às batalhas através de informações precisas, Grande Marechal.",
  ui_story_1020_10200201_53_dialog_content = "Mas foi justamente a informação que eu trouxe de volta que fez com que você fosse cercado pelos Eclipsitas e perdesse membros-chave.",
  ui_story_1020_10200201_54_dialog_content = "Aceito plenamente a punição pelas consequências do meu relatório errôneo, mas antes disso...",
  ui_story_1020_10200201_55_dialog_content = "Espero que você condene o Dr. Ulysses à execução!",
  ui_story_1020_10200201_56_dialog_content = "Anatoli...",
  ui_story_1020_10200201_57_dialog_content = "Estou disposto a esperar! Não importa o que aconteça, eu certamente devo vingar o sacrifício dos meus companheiros!",
  ui_story_1020_10200201_58_dialog_content = "Jurei isso pela minha vida!",
  ui_story_1020_10200201_59_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_1020_10200201_60_dialog_content = "Reinhardt...",
  ui_story_1020_10200201_61_dialog_content = "Belisaria!",
  ui_story_1020_10200201_62_dialog_content = "Independentemente de onde as alianças de Ulysses estão, eu não condenarei nenhum dos meus pessoas a um destino tão cruel!",
  ui_story_1020_10200201_63_dialog_content = "Agora tome sua decisão! Se você recusar... então eu a farei por você!",
  ui_story_1020_10200201_64_dialog_content = "Espada pronta.",
  ui_story_1020_10200201_65_dialog_content = "Trovão estrondoso!",
  ui_story_1020_10200201_66_dialog_content = "Pare—",
  ui_story_1020_10200201_67_dialog_content = "Abaixem suas armas, todos vocês!",
  ui_story_1020_10200201_68_dialog_content = "...",
  ui_story_1020_10200201_69_dialog_content = "Eu não vou condenar ninguém, porque na minha opinião, cada um de vocês estava tomando decisões pela sobrevivência de Illumina.",
  ui_story_1020_10200201_70_dialog_content = "É por isso que eu apoiei os experimentos de Ulysses, bem como o militar passando por cima do Comitê e enviando tropas à vontade.",
  ui_story_1020_10200201_71_dialog_content = "Mas quando um jogo de xadrez termina, os peões devem retomar seus lugares.",
  ui_story_1020_10200201_72_dialog_content = "Um peão em um tabuleiro de xadrez? É assim que você se vê?",
  ui_story_1020_10200201_73_dialog_content = "Até agora, a Federação Illumina tem lutado em duas frentes separadas. Enquanto um exército de Eclipsitas se aproxima cada vez mais da Cidade de Gannon, um câncer tem se espalhado e nos prejudicando por dentro...",
  ui_story_1020_10200201_74_dialog_content = "Você realmente pode apenas sentar aí e fingir que nada está acontecendo?",
  ui_story_1020_10200201_75_dialog_content = "Illumina não será o ponto em lutar contra os Eclipsitas e explorar o desconhecido letal pela segunda vez.",
  ui_story_1020_10200201_76_dialog_content = "Não faremos um movimento antes deles.",
  ui_story_1020_10200201_77_dialog_content = "O que você tá dizendo?",
  ui_story_1020_10200201_78_dialog_content = "Até que a crise chegue, a Illumina não será a primeira a atacar, muito menos a cortar ambos os braços - mesmo quando estiverem cheios de cistos.",
  ui_story_1020_10200201_79_dialog_content = "Entendeu?",
  ui_story_1020_10200201_80_dialog_content = "Hahaha... Máscara de Ferro, você já não se cansou desse jogo de equilíbrio entre os Aurorianos?",
  ui_story_1020_10200201_81_dialog_content = "Você quer que eu te diga como isso vai acabar para todos?",
  ui_story_1020_10200201_82_dialog_content = "Mesmo que morramos, não será porque lideramos a carga por Lumópolis!",
  ui_story_1020_10200201_83_dialog_content = "Ugh... você está me deixando surdo.",
  ui_story_1020_10200201_84_dialog_content = "Por que você não me conta qual o potencial que a Illumina tem para os próximos dez anos?",
  ui_story_1020_10200201_X84_dialog_content = "É esse prospecto de Grande Marechal que você quer enviar para a batalha, não importa o custo?",
  ui_story_1020_10200201_85_dialog_content = "Hehehe...",
  ui_story_1020_10200201_86_dialog_content = "Há mais de um potencial para o Programa Phospherus. A pessoa que pode ser o auge da Illumina em dez anos é Sean.",
  ui_story_1020_10200201_87_dialog_content = "...",
  ui_story_1020_10200201_88_dialog_content = "... Eu?",
  ui_story_1020_10200301_1_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_1020_10200301_2_dialog_content = "Bool está nisso há um tempo agora...",
  ui_story_1020_10200301_3_dialog_content = "...",
  ui_story_1020_10200301_4_dialog_content = "Não acho que ela me ouviu...",
  ui_story_1020_10200301_5_dialog_content = "Bip—Algol pode estar em modo de espera. Guardião Um irá despertá-la.",
  ui_story_1020_10200301_6_dialog_content = "Guardião Um? Por que você... trouxe tantas coisas?",
  ui_story_1020_10200301_7_dialog_content = "Estes são dispositivos de computação que Algol geralmente usa. Guardian One acredita que Algol construirá o núcleo ainda mais rápido com a ajuda deles.",
  ui_story_1020_10200301_8_dialog_content = "<color=#e8d9bb>Clam—</color>",
  ui_story_1020_10200301_9_dialog_content = "Ah! Eu reconheço esse som em qualquer lugar! Guardião Um, venha aqui e me ajude a montá-lo.",
  ui_story_1020_10200301_10_dialog_content = "(Ela realmente acordou!)",
  ui_story_1020_10200301_11_dialog_content = "A velocidade de operação de Algol está lenta hoje.",
  ui_story_1020_10200301_12_dialog_content = "Isso é porque essa máquina é de milhares de anos atrás...",
  ui_story_1020_10200301_13_dialog_content = "De certa forma, é como o seu antepassado.",
  ui_story_1020_10200301_14_dialog_content = "Este ancestral não se parece nada comigo.",
  ui_story_1020_10200301_15_dialog_content = "Bool está demorando muito mais para decifrar essa senha do que eu esperava.",
  ui_story_1020_10200301_16_dialog_content = "Será que depois de tantas atualizações, Bool não está mais familiarizado com as regras de linguagem desses símbolos?",
  ui_story_1020_10200301_17_dialog_content = "Desde que entrou em contato com seu protótipo, não parou de funcionar por um segundo. Quanta informação o Bool está processando...",
  ui_story_1020_10200301_18_dialog_content = "Algol está tão ansiosa que começou a andar de um lado para o outro.",
  ui_story_1020_10200301_19_dialog_content = "Claro que estou andando de um lado para o outro! Estou nervoso, afinal!",
  ui_story_1020_10200301_20_dialog_content = "Se ao menos Bool pudesse se comunicar telepaticamente com nosso amigo Celestita como você fez! Ver até mesmo uma pequena parte dos dados seria muito útil...",
  ui_story_1020_10200301_21_dialog_content = "Se eu executar todos esses dispositivos de computação ao mesmo tempo, nada é impossível!",
  ui_story_1020_10200301_22_dialog_content = "Podemos não ser capazes de usar a fala para nos comunicar, mas eu senti algumas das \"mensagens\" de Bool antes.",
  ui_story_1020_10200301_23_dialog_content = "Talvez eu possa usar meus poderes no Bool e tentar encontrar algumas pistas.",
  ui_story_1020_10200301_24_dialog_content = "Agradeço a oferta, mas você deveria se considerar sortudo que Bool não está te atacando agora.",
  ui_story_1020_10200301_25_dialog_content = "... Mas você disse que o Bool é realmente bom em aprender, certo? Talvez ele confie em mim depois desse pequeno episódio agora?",
  ui_story_1020_10200301_26_dialog_content = "PlayerName é tão inteligente.",
  ui_story_1020_10200301_27_dialog_content = "Faz sentido... Suponho que não temos mais nada para fazer, então vá em frente e teste sua coragem.",
  ui_story_1020_10200301_28_dialog_content = "Testar minha coragem?",
  ui_story_1020_10200301_29_dialog_content = "Ah... Por favor, seja gentil, Bool!",
  ui_story_1020_10200301_30_option_content = "Ligação Telepática—",
  ui_story_1020_10200301_31_dialog_content = "...",
  ui_story_1020_10200301_32_dialog_content = "Isso foi rápido... O Bool te rejeitou ou algo assim?",
  ui_story_1020_10200301_33_dialog_content = "Não... Era simplesmente muita informação chegando muito rápido!",
  ui_story_1020_10200301_34_dialog_content = "... Então, você encontrou algo útil?",
  ui_story_1020_10200301_35_dialog_content = "Algo útil...",
  ui_story_1020_10200301_36_option_content = "Eu vi algumas linhas.",
  ui_story_1020_10200301_37_dialog_content = "Muitas linhas, na verdade... Como se estivessem caindo do céu.",
  ui_story_1020_10200301_38_dialog_content = "Mas talvez eles não fossem linhas afinal...",
  ui_story_1020_10200301_39_dialog_content = "Isso é um monte de palavras que não significam nada!",
  ui_story_1020_10200301_40_dialog_content = "Ugh! Por que não posso ser eu a me conectar ao protótipo?",
  ui_story_1020_10200301_41_option_content = "Eu vi muitos números.",
  ui_story_1020_10200301_42_dialog_content = "Eles também estavam se movendo tão rápido!",
  ui_story_1020_10200301_43_dialog_content = "Números? Como zeros e uns? Quantos deles? Eles estavam em alguma ordem específica?",
  ui_story_1020_10200301_44_dialog_content = "Acho que havia mais números do que isso...",
  ui_story_1020_10200301_45_dialog_content = "Mas não tenho certeza de quantos eram ou se estavam em algum tipo de sequência...",
  ui_story_1020_10200301_46_option_content = "Eu não consegui entender nada.",
  ui_story_1020_10200301_47_dialog_content = "Tudo passou tão rápido que acabou antes que eu pudesse dar uma olhada mais de perto.",
  ui_story_1020_10200301_48_dialog_content = "Deixe-me tentar de novo!",
  ui_story_1020_10200301_49_dialog_content = "Agora que sei o que esperar, vou tentar algo um pouco diferente.",
  ui_story_1020_10200301_50_dialog_content = "Não se force. Até eu não descobri completamente como o Bool funciona.",
  ui_story_1020_10200301_51_dialog_content = "Se você começar a se sentir desconfortável, apenas pare por agora.",
  ui_story_1020_10200301_52_dialog_content = "Entendi.",
  ui_story_1020_10200301_53_dialog_content = "Para ser honesto, minhas habilidades psíquicas se fortaleceram desde a ascensão do Obelisco do Retorno.",
  ui_story_1020_10200301_54_dialog_content = "Agora eu posso ver rapidamente por todo o Astra do topo daquele obelisco, não com meus próprios olhos, mas com os olhos do ambiente...",
  ui_story_1020_10200301_55_dialog_content = "Parece bastante abstrato para mim. Você realmente acha que pode usar isso para visualizar os dados do Bool?",
  ui_story_1020_10200301_56_dialog_content = "Talvez com os olhos do ambiente...",
  ui_story_1020_10200301_57_dialog_content = "Mas não saberemos a menos que eu tente!",
  ui_story_1020_10200301_58_option_content = "Ligação Telepática—",
  ui_story_1020_10200301_59_dialog_content = "(T-Tão rápido!)",
  ui_story_1020_10200301_60_dialog_content = "(Eu preciso... acompanhar...)",
  ui_story_1020_10200301_61_dialog_content = "(Argh! Meus olhos doem só de olhar-)",
  ui_story_1020_10200301_62_dialog_content = "(Espere! Eu preciso usar os olhos do ambiente, não os meus...)",
  ui_story_1020_10200301_63_dialog_content = "(Primeiro vou tentar mirar em uma única sequência, e depois...)",
  ui_story_1020_10200301_64_option_content = "Alcance Telepático—",
  ui_story_1020_10200301_65_dialog_content = "(...)",
  ui_story_1020_10200301_66_dialog_content = "(Esses são números mesmo...)",
  ui_story_1020_10200301_67_dialog_content = "(01105745630112... 2311111... 0010112231...)",
  ui_story_1020_10200301_68_dialog_content = "(Se eu puder transmitir esses números para Algol, talvez ela possa quebrar a senha imediatamente...)",
  ui_story_1020_10200301_69_dialog_content = "(Mas... Como eu vou lembrar de todos eles?)",
  ui_story_1020_10200301_70_dialog_content = "Eu vi! Sequências de números caindo como chuva!",
  ui_story_1020_10200301_71_dialog_content = "Uau! Isso inclui o código de trapaça para passar este nível?",
  ui_story_1020_10200301_72_dialog_content = "Não acho que seria tão fácil... Mas talvez aquele código esteja escondido em algum lugar ali.",
  ui_story_1020_10200301_73_dialog_content = "Você consegue copiar esses números enquanto usa seus poderes, Celestita?",
  ui_story_1020_10200301_74_dialog_content = "Se você puder me trazer dados suficientes, talvez eu consiga usar esses computadores para encontrar a senha.",
  ui_story_1020_10200301_75_dialog_content = "Foi difícil o suficiente para mim distinguir os números naquelas sequências de dados. Não acho que consigo copiá-los...",
  ui_story_1020_10200301_76_dialog_content = "Ah, uma coisinha...",
  ui_story_1020_10200301_77_dialog_content = "O que foi?",
  ui_story_1020_10200301_78_dialog_content = "Não acho que você seria capaz de memorizar tantos números de uma vez...",
  ui_story_1020_10200301_79_dialog_content = "Você confia em mim?",
  ui_story_1020_10200301_80_dialog_content = "Claro que eu faço... Mas por que você pergunta?",
  ui_story_1020_10200301_81_dialog_content = "Eu tenho um palpite...",
  ui_story_1020_10200301_82_dialog_content = "A partir do momento em que desenvolve uma personalidade, a complexa e automatizada fábrica conhecida como Colossus torna-se capaz de criatividade e adaptabilidade.",
  ui_story_1020_10200301_83_dialog_content = "Nossos cérebros também possuem ambas essas características únicas.",
  ui_story_1020_10200301_84_dialog_content = "No entanto, embora possamos nos adaptar a uma variedade de cenários complexos, esse nível de criatividade e adaptabilidade...",
  ui_story_1020_10200301_85_dialog_content = "Eles apenas interferirão nos processos computacionais de uma máquina, prejudicando assim sua eficiência geral.",
  ui_story_1020_10200301_86_dialog_content = "Então, se você realmente confia em mim, apenas desligue a criatividade e adaptabilidade do seu cérebro.",
  ui_story_1020_10200301_87_dialog_content = "Hã? Mas... Como eu deveria fazer isso?",
  ui_story_1020_10200301_88_dialog_content = "Para simplificar, você precisa parar de pensar como uma pessoa e começar a operar como uma máquina.",
  ui_story_1020_10200301_89_dialog_content = "Acho que nunca tentei isso antes...",
  ui_story_1020_10200301_90_dialog_content = "É o que eu faço sempre que meu trabalho está especialmente difícil. Não se preocupe, vou te ajudar a memorizar o máximo possível desses números.",
  ui_story_1020_10200301_91_dialog_content = "Apenas concentre-se no processo e não se preocupe com todas as informações que chegam até você. Quando dados suficientes passam pela superfície de nossa consciência, tendem a deixar algumas marcas.",
  ui_story_1020_10200301_92_dialog_content = "Confie em mim, uma vez que você estiver no estado de espírito certo, tudo parecerá infinitamente mais lento.",
  ui_story_1020_10200301_93_dialog_content = "Concentre-se no processo...",
  ui_story_1020_10200301_94_dialog_content = "Talvez eu acorde depois de cair no chão...",
  ui_story_1020_10200301_95_dialog_content = "... Ainda estou no ar?",
  ui_story_1020_10200301_96_dialog_content = "Quando você se resigna a uma queda inevitável, por algum motivo o processo se torna extremamente longo...",
  ui_story_1020_10200301_97_dialog_content = "Acho que entendi o que você estava dizendo antes.",
  ui_story_1020_10200301_98_dialog_content = "O que veio à sua mente?",
  ui_story_1020_10200301_99_dialog_content = "Não foi um acidente, para ser preciso... Bem, de qualquer forma, acho que sei o que fazer agora.",
  ui_story_1020_10200301_100_option_content = "Sentir—Mais Fundo—",
  ui_story_1020_10200301_101_dialog_content = "Uau, os olhos de PlayerName estão se movendo rápido.",
  ui_story_1020_10200301_102_dialog_content = "Que maravilha é PlayerName! Estou curioso para descobrir o que se passa nessa cabeça.",
  ui_story_1020_10200301_103_dialog_content = "Reivindico este Celestita como meu assistente pessoal de pesquisa. Quando tudo isso acabar, até farei uma roupa para ele!",
  ui_story_1020_10200301_104_dialog_content = "Algol quer se tornar amigo do Celestita.",
  ui_story_1020_10200301_105_dialog_content = "Não será como as roupas que ele está usando agora. Não, será mais como a sua casca externa.",
  ui_story_1020_10200301_106_dialog_content = "Bip—",
  ui_story_1020_10200301_107_dialog_content = "11101100...",
  ui_story_1020_10200301_108_dialog_content = "Há!",
  ui_story_1020_10200301_109_dialog_content = "Código binário?",
  ui_story_1020_10200301_110_dialog_content = "010221111, 022211110101...",
  ui_story_1020_10200301_111_dialog_content = "... Ou talvez não?",
  ui_story_1020_10200301_112_dialog_content = "Guardião Um, grave a voz dele para que não percamos nada.",
  ui_story_1020_10200301_113_dialog_content = "Bip. O Guardião Um compreende.",
  ui_story_1020_10200301_114_dialog_content = "Gronru, Vivian e Migard, usem esses computadores também! Concentrem-se e apoiem-se com a Lúmina.",
  ui_story_1020_10200301_115_dialog_content = "Beleza!",
  ui_story_1020_10200301_116_dialog_content = "0101157567565500101... 100150115332234560101...",
  ui_story_1020_10200301_117_dialog_content = "(Número cinco... número seis... sete, oito, nove...)",
  ui_story_1020_10200301_118_dialog_content = "(Quanto mais há?)",
  ui_story_1020_10200301_119_dialog_content = "(Espere... Estou vendo coisas? Por que parece que... algo está piscando...)",
  ui_story_1020_10200301_120_dialog_content = "(Oh não... Estou começando a pensar de novo...)",
  ui_story_1020_10200301_121_dialog_content = "(Argh! Tudo está tão rápido... Mal consigo acompanhar!)",
  ui_story_1020_10200401_1_dialog_content = "O que você está dizendo exatamente, Dr. Ulysses?",
  ui_story_1020_10200401_2_dialog_content = "Você, Yingel e Axelia. Vocês três são todos produtos do Programa Phospherus.",
  ui_story_1020_10200401_3_dialog_content = "...",
  ui_story_1020_10200401_4_dialog_content = "...",
  ui_story_1020_10200401_5_dialog_content = "Um produto do Phospherus deve ser inteligente como Yingel ou uma poderosa máquina de socar Eclipsita como Axelia.",
  ui_story_1020_10200401_6_dialog_content = "Eu não...",
  ui_story_1020_10200401_7_dialog_content = "Você é mais poderoso do que pensa, Sean.",
  ui_story_1020_10200401_8_dialog_content = "Poderoso... Essa é a primeira vez que me associam a essa palavra.",
  ui_story_1020_10200401_9_dialog_content = "Pegue isso, Axelia! Ha!",
  ui_story_1020_10200401_10_dialog_content = "Ai!",
  ui_story_1020_10200401_11_dialog_content = "...",
  ui_story_1020_10200401_12_dialog_content = "Eu até me machucaria socando Axelia... Realmente poderoso...",
  ui_story_1020_10200401_13_dialog_content = "Novo recruta? Mais parece uma criança! Ei! Crepúsculo não é lugar para você estar!",
  ui_story_1020_10200401_14_dialog_content = "...",
  ui_story_1020_10200401_15_dialog_content = "O que você fez na cidade de Gannon antes de vir para cá? Por que você não consegue nem eliminar Eclipsitas como esses?",
  ui_story_1020_10200401_16_dialog_content = "...",
  ui_story_1020_10200401_17_dialog_content = "Não é meu lugar dizer isso, mas vamos todos nos aprimorar sob condições difíceis, Sean.",
  ui_story_1020_10200401_18_dialog_content = "Vou trabalhar nisso, senhor...",
  ui_story_1020_10200401_19_dialog_content = "Quanto maior o poder, maior a responsabilidade. Não é minha culpa que eu seja mais forte que Sean, hahaha! Não é mesmo?",
  ui_story_1020_10200401_20_dialog_content = "Mas... Eu sou responsável por essa área.",
  ui_story_1020_10200401_21_dialog_content = "Tudo bem. Vou dizer ao líder do esquadrão que os Eclipsitas nesta área são muito fortes.",
  ui_story_1020_10200401_22_dialog_content = "...",
  ui_story_1020_10200401_23_dialog_content = "Corra mais rápido, Sean! Só um pouco mais rápido!",
  ui_story_1020_10200401_24_dialog_content = "... Sim... Sim, senhor!",
  ui_story_1020_10200401_25_dialog_content = "O professor Ulysses disse que sou tão poderoso quanto Yingel e Axelia.",
  ui_story_1020_10200401_26_dialog_content = "Mas por que eu sou o único com mãos...",
  ui_story_1020_10200401_27_dialog_content = "... coberto de calos?",
  ui_story_1020_10200401_28_dialog_content = "São marcas do meu treinamento... Não importa como você veja, só vai encontrá-las em um cara inútil como eu.",
  ui_story_1020_10200401_29_dialog_content = "Não apenas nas mãos, eu tenho cicatrizes de treinamento quase em todo lugar...",
  ui_story_1020_10200401_30_dialog_content = "Não treinei o suficiente?",
  ui_story_1020_10200401_31_dialog_content = "Sean...",
  ui_story_1020_10200401_32_dialog_content = "Você foi enviado para Crepúsculo apenas porque foi considerado um fracasso nos estágios iniciais.",
  ui_story_1020_10200401_33_dialog_content = "No entanto, erros de julgamento são inevitáveis na fase inicial de qualquer experimento.",
  ui_story_1020_10200401_34_dialog_content = "Uma falha...",
  ui_story_1020_10200401_35_dialog_content = "Então eu estava em Crepúsculo porque eu era um fracasso... Haha...",
  ui_story_1020_10200401_36_dialog_content = "Isso não foi sua culpa, Sean. Não ouça nada que Ulysses diz.",
  ui_story_1020_10200401_37_dialog_content = "Cada um de nós é um fracasso no programa.",
  ui_story_1020_10200401_38_dialog_content = "Obrigado por tentar me consolar, Grande Marechal, mas eu sei que no final, eu não sou como nenhum de vocês...",
  ui_story_1020_10200401_39_dialog_content = "Pergunte a ele como o fracasso do Crepúsculo se tornará o potencial futuro da Illumina.",
  ui_story_1020_10200401_40_dialog_content = "Vá direto ao ponto, Ulysses.",
  ui_story_1020_10200401_41_dialog_content = "Bem, você é o juiz, Máscara de Ferro...",
  ui_story_1020_10200401_42_dialog_content = "Nós abandonamos nosso estudo sobre Sean, mas mudanças ocorreram em seu corpo quando ele estava mais próximo da Zona Escura em Crepúsculo.",
  ui_story_1020_10200401_43_dialog_content = "Após verificações repetidas, descobri que a Luminática de Sean não era limitada por defeitos genéticos. Pelo contrário, ele poderia absorver o Fluxo Escuro.",
  ui_story_1020_10200401_44_dialog_content = "Ele não conseguia converter a energia em Lumina, mas isso lhe proporcionava uma forte imunidade natural ao lutar contra Eclipsitas.",
  ui_story_1020_10200401_45_dialog_content = "Na verdade, é uma característica semelhante compartilhada por aqueles na expedição liderada por Pepita para a Zona Escura.",
  ui_story_1020_10200401_46_dialog_content = "Eu não vou entrar em jargões, mas eles são a esperança dos Aurorianos para derrotar os Eclipsitas!",
  ui_story_1020_10200401_47_dialog_content = "Finalizei o plano para melhorias físicas. Acredito que um novo lote das minhas criações estará pronto para a Zona Cega muito em breve.",
  ui_story_1020_10200401_48_dialog_content = "Isso é algum tipo de piada, Ulysses? Por que a Federação Illumina permitiria que você continuasse com essa bobagem?",
  ui_story_1020_10200401_49_dialog_content = "Sean! Eu preciso te dizer, Sean—",
  ui_story_1020_10200401_50_dialog_content = "Talvez você tenha descoberto pelos arquivos que os soldados de Illumina te resgataram dos Eclipsitas e te enviaram para o orfanato como um órfão.",
  ui_story_1020_10200401_51_dialog_content = "Mas os que te levaram para morrer com os Eclipsitas foram nada mais nada menos que seus pais!",
  ui_story_1020_10200401_52_dialog_content = "Eles não queriam que você vivesse e sofresse dos mesmos defeitos físicos que eles tinham.",
  ui_story_1020_10200401_53_dialog_content = "Mas graças ao Programa Phospherus, você não sofreria mais.",
  ui_story_1020_10200401_54_dialog_content = "Modifiquei seu corpo e lhe dei uma nova chance na vida. Se você quer ser reconhecido como poderoso, você deve—",
  ui_story_1020_10200401_55_dialog_content = "O que você está fazendo, Professor Ulysses?",
  ui_story_1020_10200401_56_dialog_content = "Prometa-me que você irá se aprofundar na Zona Escura e erradicar os Eclipsitas.",
  ui_story_1020_10200401_57_dialog_content = "Comparado a ser um peão insignificante em Crepúsculo, é melhor maximizar seu potencial genético e ser um herói auroriano que luta contra o Eclipse em seu próprio território!",
  ui_story_1020_10200401_58_dialog_content = "Então... Você verá o demônio que tem se escondido por trás da cena...",
  ui_story_1020_10200401_59_dialog_content = "Pare, Ulysses!",
  ui_story_1020_10200401_60_dialog_content = "Fique longe de Sean, Professor!",
  ui_story_1020_10200401_61_dialog_content = "Você estava disposto a sacrificar qualquer um em seu experimento, apenas para afirmar que foi você quem salvou Sean.",
  ui_story_1020_10200401_62_dialog_content = "Sua crueldade e egoísmo estão me deixando enojado!",
  ui_story_1020_10200401_63_dialog_content = "Ninguém pode abandoná-lo, tirar a vida dele, ou mesmo ditar como ele deve viver agora!",
  ui_story_1020_10200401_64_dialog_content = "Ninguém pode abandoná-lo, tirar a vida dele, ou mesmo ditar como ele deve viver!",
  ui_story_1020_10200401_65_dialog_content = "Bem, eu não acho que vocês precisam me cercar como um cobertor, Yingel, Axelia...",
  ui_story_1020_10200401_66_dialog_content = "O Professor Ulysses disse que foram meus pais que me levaram aos Eclipsitas.",
  ui_story_1020_10200401_67_dialog_content = "Sempre me disse que era apenas um sonho...",
  ui_story_1020_10200401_68_dialog_content = "Mas como uma experiência tão inesquecível poderia ser apenas um simples sonho?",
  ui_story_1020_10200401_69_dialog_content = "No entanto, eu escolhi interpretar como meus pais se sacrificando para me salvar.",
  ui_story_1020_10200401_70_dialog_content = "Foi estúpido, eu sei, mas era a única maneira de me enganar para viver, certo?",
  ui_story_1020_10200401_71_dialog_content = "O que aconteceu naquela época não importa mais, Sean.",
  ui_story_1020_10200401_72_dialog_content = "Você é um excelente guerreiro de Crepúsculo—não, guerreiro Illumina!",
  ui_story_1020_10200401_73_dialog_content = "Como eu, você agora é um soldado da Illumina capaz de matar inúmeros Eclipsitas.",
  ui_story_1020_10200401_74_dialog_content = "Isso provavelmente é egoísta da minha parte, mas acho que você não precisa ser um guerreiro ou um herói.",
  ui_story_1020_10200401_75_dialog_content = "Apenas seja Sean.",
  ui_story_1020_10200401_76_dialog_content = "Hahahaha! Então você quer repetir a derrota naquela guerra antiga?",
  ui_story_1020_10200401_77_dialog_content = "Este mundo não é tão simples... Eu testemunhei o quão poderoso é o Eclipse. Eu sei que esta é a única chance para os Aurorians.",
  ui_story_1020_10200401_78_dialog_content = "Você sacrificou seu próprio povo em nome da ciência! Suas ações só destruirão tanto a Federação Illumina quanto todos os Aurorianos!",
  ui_story_1020_10200401_79_dialog_content = "Uma máquina de guerra não é adequada para debater comigo sobre sacrifícios e destruições!",
  ui_story_1020_10200401_80_dialog_content = "Eu realmente invejo Forsakin por oferecer uma teoria sobre a misteriosa força escondida tanto em Lumina quanto em Darkflow em uma idade tão jovem, e depois seguir adiante com isso.",
  ui_story_1020_10200401_81_dialog_content = "Você, por outro lado, prefere depositar fé em seus sentimentos e se concentrar em vidas insignificantes...",
  ui_story_1020_10200401_82_dialog_content = "São as suas emoções que seguram os Aurorians...",
  ui_story_1020_10200401_83_dialog_content = "É a sua tolice que causou mais sacrifícios...",
  ui_story_1020_10200401_84_dialog_content = "Você disse aos Aurorianos para temerem a morte, fazendo com que eles se entregassem à espera monótona de seus destinos condenados...",
  ui_story_1020_10200401_85_dialog_content = "Eu, no entanto, não serei um escravo das emoções...",
  ui_story_1020_10200401_86_dialog_content = "Nunca!",
  ui_story_1020_10200401_87_dialog_content = "Eu vou me acostumar com isso...",
  ui_story_1020_10200401_88_dialog_content = "Acostume-se com Aurorianos morrendo a cada segundo! Às dezenas, centenas, milhares!",
  ui_story_1020_10200401_89_dialog_content = "Passarei por cima de todos os seus corpos apodrecidos para criar Aurorianos poderosos tanto no corpo quanto na mente!",
  ui_story_1020_10200401_90_dialog_content = "Você já ouviu falar de evolução, acredito. Bem, os Aurorianos devem evoluir.",
  ui_story_1020_10200401_91_dialog_content = "Cada minuto, cada segundo...",
  ui_story_1020_10200401_92_dialog_content = "Essa é a única maneira de sobrevivermos ao dia do juízo final, com nossos horizontes ampliados e corpos poderosos...",
  ui_story_1020_10200401_93_dialog_content = "Para ascender...",
  ui_story_1020_10200401_94_dialog_content = "Você está bem, senhor?",
  ui_story_1020_10200401_95_dialog_content = "Evolução... Que termo maravilhoso.",
  ui_story_1020_10200401_96_dialog_content = "Cada minuto, cada segundo...",
  ui_story_1020_10200401_97_dialog_content = "Oficial Ulysses!",
  ui_story_1020_10200401_98_dialog_content = "Ele é louco?",
  ui_story_1020_10200401_99_dialog_content = "Se eu não tivesse visto por mim mesmo... Eu não acreditaria...",
  ui_story_1020_10200401_100_dialog_content = "O que aconteceu com ele?",
  ui_story_1020_10200401_101_dialog_content = "É por isso que estou determinado a convocar Chandra, minha testemunha.",
  ui_story_1020_10200401_102_dialog_content = "Eu estive com ele todo esse tempo, Grande Marechal.",
  ui_story_1020_10200401_103_dialog_content = "Torne as ações de Ulysses conhecidas por todos.",
  ui_story_1020_10200401_104_dialog_content = "Sim, Grande Marechal. Quando o Dr. Ulysses estava em terapia, ele ocasionalmente olhava para a distância assim...",
  ui_story_1020_10200401_105_dialog_content = "Apenas para então agir como se nada tivesse acontecido no próximo momento.",
  ui_story_1020_10200401_106_dialog_content = "...",
  ui_story_1020_10200401_107_dialog_content = "Continue, Testemunha Chandra.",
  ui_story_1020_10200401_108_dialog_content = "O professor Ulysses começou a psicoterapia há dez anos. Aqui está o prontuário médico dele.",
  ui_story_1020_10200401_109_dialog_content = "Eu não estava envolvido na época, mas como você pode ver no arquivo, foi quando os Eclipsitas começaram a se infiltrar em várias facções.",
  ui_story_1020_10200401_110_dialog_content = "E vários meses antes do exercício militar, o Professor Ulysses aumentou suas sessões de terapia mais uma vez.",
  ui_story_1020_10200401_111_dialog_content = "Depois, Forsakin se infiltrou no Laboratório X e os Wraiths levaram o núcleo do Guardião Um de Gannon.",
  ui_story_1020_10200401_112_dialog_content = "O Dr. Ulysses esteve envolvido em ambos os incidentes chave. Então, suspeitamos que possa haver uma comunicação especial entre ele e o Eclipse.",
  ui_story_1020_10200401_113_dialog_content = "...",
  ui_story_1020_10200401_114_dialog_content = "O que chamou minha atenção foram algumas das coisas estranhas que Ulysses mencionou durante suas sessões de tratamento...",
  ui_story_1020_10200401_115_dialog_content = "Os pilares de gelo não são água da chuva condensada, mas sim rochedos emergindo...",
  ui_story_1020_10200401_116_dialog_content = "A unidade de condução está esgotada e desconectada, mas o único olho ainda está observando acima...",
  ui_story_1020_10200401_117_dialog_content = "Pilares de gelo emergindo, unidade em movimento... e um olho atento no céu...",
  ui_story_1020_10200401_118_dialog_content = "Isso não parece com nada em Astra. Como alguém como ele, que nunca saiu de Gannon City, saberia sobre isso?",
  ui_story_1020_10200401_119_dialog_content = "Isso dificilmente pode ser uma coincidência! Tenho certeza que você também tem suas suspeitas, Belisaria!",
  ui_story_1020_10200401_120_dialog_content = "Como ela pode ter tanta certeza?",
  ui_story_1020_10200401_121_dialog_content = "Prova?",
  ui_story_1020_10200401_122_dialog_content = "Porque está escrito nas memórias de Helios, um ex-soldado que se aventurou na Zona Escura e se tornou um Eclipsite!",
  ui_story_1020_10200401_123_dialog_content = "O Comitê tem me negado a chance de provar minhas suspeitas porque ele ainda não recuperou a consciência.",
  ui_story_1020_10200401_124_dialog_content = "Mas se o testemunho dele se alinha com minhas acusações contra Ulysses, como mais você explicaria isso?",
  ui_story_1020_10200401_125_dialog_content = "Eu tenho uma ideia. E você?",
  ui_story_1020_10200401_126_dialog_content = "Esse Wraith?",
  ui_story_1020_10200401_127_dialog_content = "Então era isso que ele estava se referindo...",
  ui_story_1020_10200401_128_dialog_content = "...",
  ui_story_1020_10200401_129_dialog_content = "Não há necessidade de perder tanto tempo comigo.",
  ui_story_1020_10200401_130_dialog_content = "Quando ele chegar, aqueles sem anéis serão deixados para rastejar no chão e morrer em seu medo e insignificância.",
  ui_story_1020_10200401_131_dialog_content = "Quais anéis?",
  ui_story_1020_10200401_132_dialog_content = "Miserável ladrão! Parasita! Você cobiça os anéis dele, não é?",
  ui_story_1020_10200401_133_dialog_content = "Seiscentos anos atrás, aquela cidade flutuante era meu pedestal para ascensão, que deveria me levar a alturas ainda maiores!",
  ui_story_1020_10200401_134_dialog_content = "Cidade flutuante... Lumópolis?",
  ui_story_1020_10200401_135_dialog_content = "Mas quando ele chegar, subirei à glória mais uma vez. Voltarei para o seu palácio e seu abraço amoroso.",
  ui_story_1020_10200401_136_dialog_content = "Por que você vê os Aurorianos como seus inimigos?",
  ui_story_1020_10200401_137_dialog_content = "Por causa da sua ganância sem limites, é claro! Os Aurorianos desejam roubar suas criações e chamá-las de suas!",
  ui_story_1020_10200401_138_dialog_content = "Mas logo, ele vai pegar tudo de volta!",
  ui_story_1020_10200401_139_dialog_content = "Tsc, tsc, tsc!",
  ui_story_1020_10200401_140_dialog_content = "...",
  ui_story_1020_10200401_141_dialog_content = "A raiz de tudo isso é aquela máquina antiga da era antes da fundação da Illumina...",
  ui_story_1020_10200401_142_dialog_content = "Este é o destino de Illumina? Heheh...",
  ui_story_1020_10200401_143_dialog_content = "Onde está aquele dispositivo?",
  ui_story_1020_10200401_144_dialog_content = "Em um armazém, sendo vigiado por aquele gênio de quem você gosta tanto.",
  ui_story_1020_10200401_145_dialog_content = "Evolução... Que termo maravilhoso.",
  ui_story_1020_10200401_146_dialog_content = "Cada minuto, cada segundo...",
  ui_story_1020_10200401_147_dialog_content = "...",
  ui_story_1020_10200501_1_dialog_content = "... Isso é tudo?",
  ui_story_1020_10200501_2_dialog_content = "Tudo verificado, sem erros ou omissões. Acha que está faltando algo, Dr. Algol?",
  ui_story_1020_10200501_3_dialog_content = "Eu esperava muito mais números. A sequência também é cíclica... Talvez seja um conjunto finito de caracteres.",
  ui_story_1020_10200501_4_dialog_content = "Além disso, a primeira linguagem de computador veio do Sistema Guardião. Independentemente de seu desenvolvimento ao longo dos anos, as regras que regem sua linguagem ainda devem estar intactas.",
  ui_story_1020_10200501_5_dialog_content = "Meu programa pode analisar esses dados e determinar a lógica por trás de seu agrupamento.",
  ui_story_1020_10200501_6_dialog_content = "Em breve, poderei usar esses computadores para acessar todo o Sistema Guardião, junto com Bool! A qualquer momento agora!",
  ui_story_1020_10200501_7_dialog_content = "Mas, como é um conjunto finito, como é que o PlayerName ainda está ligado? Ele está bem?",
  ui_story_1020_10200501_8_dialog_content = "Ei, o cabelo dele está arrepiado... Isso parece familiar para mim, mas não consigo me lembrar bem o que é.",
  ui_story_1020_10200501_9_dialog_content = "Quase lá... Quase lá...",
  ui_story_1020_10200501_10_dialog_content = "Uuuh!",
  ui_story_1020_10200501_11_dialog_content = "Pronto!",
  ui_story_1020_10200501_12_dialog_content = "Agora eu só preciso inserir esses na ordem certa...",
  ui_story_1020_10200501_13_dialog_content = "<color=#e8d9bb>Bipe—bipe—bipe—</color>",
  ui_story_1020_10200501_14_dialog_content = "... Nada bom, huh?",
  ui_story_1020_10200501_15_dialog_content = "Eu me lembro agora! É Bool. Seu cabelo agora parece exatamente com os tentáculos de Bool!",
  ui_story_1020_10200501_16_dialog_content = "Talvez a cabeça de PlayerName seja um supercomputador como o Bool?",
  ui_story_1020_10200501_17_dialog_content = "Estou preocupado que algo possa estar errado com PlayerName, Dr. Algol!",
  ui_story_1020_10200501_18_dialog_content = "... Mesmo que ele tenha as habilidades psíquicas mais poderosas do mundo, isso não o torna um computador...",
  ui_story_1020_10200501_19_dialog_content = "Vamos apenas acordá-lo—",
  ui_story_1020_10200501_20_dialog_content = "85... X... 32.875... X...",
  ui_story_1020_10200501_21_dialog_content = "Hã?",
  ui_story_1020_10200501_22_dialog_content = "O que ele está murmurando?",
  ui_story_1020_10200501_23_dialog_content = "... \"X\"?",
  ui_story_1020_10200501_24_dialog_content = "Não são apenas números?",
  ui_story_1020_10200501_25_dialog_content = "3292... X... 4782... X... 2212323293845...",
  ui_story_1020_10200501_26_dialog_content = "O rosto dele ficou vermelho como um tomate!",
  ui_story_1020_10200501_27_dialog_content = "... 12983289... X...",
  ui_story_1020_10200501_28_dialog_content = "50227833... X...",
  ui_story_1020_10200501_29_dialog_content = "Esse cara está realmente acompanhando a velocidade de computação do Bool... Ele estará em sério perigo se isso continuar...",
  ui_story_1020_10200501_30_dialog_content = "... Mas se o impedirmos agora, será ainda mais difícil obter essas informações novamente...",
  ui_story_1020_10200501_31_dialog_content = "Aqui! Vou colocar minha pulseira nele e dar mais dois minutos.",
  ui_story_1020_10200501_32_dialog_content = "... O que isso vai fazer?",
  ui_story_1020_10200501_33_dialog_content = "Dois minutos é o tempo máximo que as células cerebrais de uma pessoa podem sustentar operações de alta velocidade, e essa pulseira pode monitorar de perto a saúde do usuário.",
  ui_story_1020_10200501_34_dialog_content = "Se os dados começarem a sobrecarregar a mente dele, a pulseira nos alertará.",
  ui_story_1020_10200501_35_dialog_content = "Antes que isso aconteça, vou precisar de ajuda para registrar mais dados. Gronru, Guardian One, temos que reunir o máximo de informações úteis possível nos próximos dois minutos.",
  ui_story_1020_10200501_36_dialog_content = "Mesmo uma parte disso funcionará. Esta pode ser nossa única chance de acessar os arquivos de memória mais seguros do protótipo!",
  ui_story_1020_10200501_37_dialog_content = "Sem problemas!",
  ui_story_1020_10200501_38_dialog_content = "O Guardião Um compreende.",
  ui_story_1020_10200501_39_dialog_content = "Fique de olho no relógio, Vivian. Avise-nos quando os dois minutos acabarem, e nós vamos parar.",
  ui_story_1020_10200501_40_dialog_content = "Claro.",
  ui_story_1020_10200501_41_dialog_content = "Migard, se a pulseira emitir um aviso dentro desses dois minutos, pegue PlayerName e tire-o daqui.",
  ui_story_1020_10200501_42_dialog_content = "Deixa comigo!",
  ui_story_1020_10200501_43_dialog_content = "862033934... X...",
  ui_story_1020_10200501_44_dialog_content = "385782493666... X...",
  ui_story_1020_10200501_45_dialog_content = "Bip, bip, bip, bip, bip...",
  ui_story_1020_10200501_46_dialog_content = "236758423423... X...",
  ui_story_1020_10200501_47_dialog_content = "(\"X\"?)",
  ui_story_1020_10200501_48_dialog_content = "(Esse personagem brilhante é um \"X\"?)",
  ui_story_1020_10200501_49_dialog_content = "(Argh... Provavelmente já se passou muito tempo agora...)",
  ui_story_1020_10200501_50_dialog_content = "(Minha cabeça não parece doer tanto quanto antes!)",
  ui_story_1020_10200501_51_dialog_content = "(Mas o que é isso com este \"X\"?)",
  ui_story_1020_10200501_52_dialog_content = "(Ahhh... Está acelerando de novo...)",
  ui_story_1020_10200502_1_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200502_2_dialog_content = "Dois minutos exatamente.",
  ui_story_1020_10200502_3_dialog_content = "Excelente!",
  ui_story_1020_10200502_4_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200502_5_dialog_content = "Tá bom, tá bom... Vá mais devagar aí!",
  ui_story_1020_10200502_6_dialog_content = "Agora, vamos usar esses computadores para analisar os dados que acabamos de receber. Tenho certeza de que vai funcionar desta vez.",
  ui_story_1020_10200502_7_dialog_content = "Buá!",
  ui_story_1020_10200502_8_dialog_content = "Argh...",
  ui_story_1020_10200502_9_dialog_content = "Você tá bem, PlayerName?",
  ui_story_1020_10200502_10_dialog_content = "Uau, isso que é pressão alta! E a sua saturação de oxigênio no pulso... Você consegue nos ver claramente?",
  ui_story_1020_10200502_11_dialog_content = "S-Sim, eu vejo você...",
  ui_story_1020_10200502_12_dialog_content = "Sente-se e não se mexa. Siga meu dedo com seus olhos.",
  ui_story_1020_10200502_13_dialog_content = "Esquerda direita...",
  ui_story_1020_10200502_14_dialog_content = "Como você está se sentindo agora?",
  ui_story_1020_10200502_15_dialog_content = "Minha cabeça... Está um pouco tonta... E meus membros estão realmente fracos...",
  ui_story_1020_10200502_16_dialog_content = "Algum enjoo ou problemas de visão?",
  ui_story_1020_10200502_17_dialog_content = "Não consigo pensar em nenhum...",
  ui_story_1020_10200502_18_dialog_content = "Aqui, beba isso.",
  ui_story_1020_10200502_19_dialog_content = "O que foi?",
  ui_story_1020_10200502_20_dialog_content = "Uma atividade cerebral intensa como essa geralmente é seguida por sintomas de hipóxia. Confie em mim, eu meio que sou um especialista nisso.",
  ui_story_1020_10200502_21_dialog_content = "Ainda assim, eu não tinha ideia de que você poderia usar suas habilidades psíquicas a esse ponto. Você realmente me ajudou agora!",
  ui_story_1020_10200502_22_dialog_content = "Eu não sabia que eu poderia também... No início, os números se moviam tão rapidamente que eu mal conseguia ler uma única sequência claramente.",
  ui_story_1020_10200502_23_dialog_content = "Mas quando parei de tentar me concentrar na sequência e, assim como você disse, desisti de pensar... De repente, os números começaram a fluir mais naturalmente...",
  ui_story_1020_10200502_24_dialog_content = "Em um momento, eu até parei para pensar por um instante...",
  ui_story_1020_10200502_25_dialog_content = "Mas assim que eu fiz, os números aceleraram novamente...",
  ui_story_1020_10200502_26_dialog_content = "Rápido... Devagar... Depois pensando... A velocidade foi afetada pelo pensamento... Uma curva de aprendizado completamente responsiva...",
  ui_story_1020_10200502_27_dialog_content = "Espere, mas você não disse que desistiu de pensar completamente? Como você conseguiu ver os números tão claramente? O que exatamente você é?",
  ui_story_1020_10200502_28_dialog_content = "Tem certeza... Você não é algum tipo de inteligência artificial ou algo assim, é?",
  ui_story_1020_10200502_29_dialog_content = "V-Você realmente precisa perguntar?",
  ui_story_1020_10200502_30_dialog_content = "De qualquer forma, lembro de ter visto um \"X\" enquanto estava lá. O que isso significa?",
  ui_story_1020_10200502_31_dialog_content = "Não estou me lembrando das coisas errado... estou?",
  ui_story_1020_10200502_32_dialog_content = "Não, você não está...",
  ui_story_1020_10200502_33_dialog_content = "Mas infelizmente... apenas Bool - outra parte daquele dispositivo antigo - saberia o que fazer com essa informação...",
  ui_story_1020_10200502_34_dialog_content = "Algol também se sente impotente.",
  ui_story_1020_10200502_35_dialog_content = "Que sensação estranha... ser deixado para trás por uma tecnologia que foi criada muito antes do nosso tempo...",
  ui_story_1020_10200502_36_dialog_content = "Esta máquina foi construída por alguma pessoa, ou foi obra de um deus? Hahahaha!",
  ui_story_1020_10200502_37_dialog_content = "...",
  ui_story_1020_10200502_38_dialog_content = "A Federação Illumina tem ficado presa usando computadores baseados em binário pelos últimos seiscentos anos!",
  ui_story_1020_10200502_39_dialog_content = "Das cálculos matemáticos à medição de matéria em um estado estável, sempre acreditamos que o binário é a solução ideal para todas as nossas necessidades computacionais.",
  ui_story_1020_10200502_40_dialog_content = "Mas essa máquina... Sua linguagem de computação mais básica usa caracteres além de zeros e uns! Pode ser uma linguagem ternária ou até quaternária...",
  ui_story_1020_10200502_41_dialog_content = "E quanto a esse \"X\"? Eu nem consigo compreender a ciência por trás disso... Um \"X\"!",
  ui_story_1020_10200502_42_dialog_content = "Quase parece que está zombando de mim, não acha? Hahahaha!",
  ui_story_1020_10200502_43_dialog_content = "Como isso veio a ser? Quão complexa é a lógica que processa?",
  ui_story_1020_10200502_44_dialog_content = "E o que aconteceu com essa antiga civilização?",
  ui_story_1020_10200502_45_dialog_content = "Por que nada resta além de Celestitas, Aurorianos e Eclipsitas?",
  ui_story_1020_10200502_46_dialog_content = "Ah! Quase me esqueci... Há também o Deus da Luz! E o Senhor da Verdade também! Será que a Bíblia Sangrenta está escondendo as respostas?",
  ui_story_1020_10200502_47_dialog_content = "Hehe... Hahahaha...",
  ui_story_1020_10200502_48_dialog_content = "O que está acontecendo com ela? Isso está ficando muito assustador...",
  ui_story_1020_10200502_49_dialog_content = "Algol percebe que ela é meio inútil.",
  ui_story_1020_10200502_50_dialog_content = "Inútil? Não me faça rir! Eu já estou fazendo isso o suficiente por conta própria...",
  ui_story_1020_10200502_51_dialog_content = "Hahahaha!",
  ui_story_1020_10200502_52_dialog_content = "Guardião Um! Não me importa se é um deus vingativo ou algum espírito maligno!",
  ui_story_1020_10200502_53_dialog_content = "Este mundo não se importa com quem chega primeiro, e eu me recuso a deixar minha incerteza nas mãos dos mortos!",
  ui_story_1020_10200502_54_dialog_content = "Eu talvez não consiga desvendar seus mistérios agora, mas isso não me impedirá de pesquisar e desenvolver o Sistema Guardian.",
  ui_story_1020_10200502_55_dialog_content = "Você me ouve?",
  ui_story_1020_10200502_56_dialog_content = "O Guardião Um compreende em todos os sentidos da palavra.",
  ui_story_1020_10200502_57_dialog_content = "Uuuh!",
  ui_story_1020_10200502_58_dialog_content = "Bom! Tudo depende de você agora, Bool!",
  ui_story_1020_10200502_59_dialog_content = "... Boo...",
  ui_story_1020_10200502_60_dialog_content = "O momento finalmente chegou...",
  ui_story_1020_10200502_61_dialog_content = "Vamos entrar no covil do chefe!",
  ui_story_1020_10200502_62_dialog_content = "...",
  ui_story_1020_10200502_63_dialog_content = "O que é isso?!",
  ui_story_1020_10200502_64_dialog_content = "Celestita.",
  ui_story_1020_10200502_65_dialog_content = "...",
  ui_story_1020_10200502_66_dialog_content = "Aquela luz piscando na minha mente... Não foi um sonho?",
  ui_story_1020_10200502_67_dialog_content = "O sol preto que eu vi... Está de alguma forma conectado ao protótipo?",
  ui_story_1020_10200601_1_dialog_content = "Você mencionou que o anel estava no seu sonho...",
  ui_story_1020_10200601_2_dialog_content = "Você também viu o Wraith e o Vice?",
  ui_story_1020_10200601_3_dialog_content = "Sim...",
  ui_story_1020_10200601_4_dialog_content = "O Eclipse construiu o protótipo Ulysses? Você acha que existe uma conexão entre tudo isso, Dr. Algol?",
  ui_story_1020_10200601_5_dialog_content = "Claro que há... Hahahahahaha!",
  ui_story_1020_10200601_6_dialog_content = "...",
  ui_story_1020_10200601_7_dialog_content = "... Por que todos vocês têm esse olhar no rosto?",
  ui_story_1020_10200601_8_dialog_content = "Mas esta é a tecnologia muito antiga em que a Illumina tem confiado para sobreviver desde a sua fundação...",
  ui_story_1020_10200601_9_dialog_content = "Não seria uma ameaça perigosa se fosse criada pelo Eclipse?",
  ui_story_1020_10200601_10_dialog_content = "Celestita.",
  ui_story_1020_10200601_11_dialog_content = "(Aí está de novo...)",
  ui_story_1020_10200601_12_dialog_content = "Pelo menos, minhas varreduras não encontraram nenhuma diferença entre ele e meu simulador.",
  ui_story_1020_10200601_13_dialog_content = "Se mais supersoldados estiverem alojados em outro local, temo que o protótipo não tenha nenhum registro disso.",
  ui_story_1020_10200601_14_dialog_content = "Parece haver alguma conexão entre as marcas no protótipo e o sonho de PlayerName. A trama se complica...",
  ui_story_1020_10200601_15_dialog_content = "Ao contrário, acho que está ficando cada vez mais fácil de entender.",
  ui_story_1020_10200601_16_dialog_content = "No início, todos nós pensamos que Ulysses não era nada mais do que um megalomaníaco sem esperança, mas depois de ver isso, não estou tão convencido mais.",
  ui_story_1020_10200601_17_dialog_content = "Por todos esses anos, a cidade de Gannon nunca foi destruída... Ele realmente insistiu em conduzir esses experimentos por pura loucura?",
  ui_story_1020_10200601_18_dialog_content = "Chefe de Gabinete, gostaria de trazer Ulysses aqui.",
  ui_story_1020_10200601_19_dialog_content = "Uh, não acho que o Comitê vai consentir com isso, mas posso tentar entrar em contato com o Grande Marechal...",
  ui_story_1020_10200601_20_dialog_content = "...",
  ui_story_1020_10200601_21_dialog_content = "Mas Ulysses possui o maior entendimento desta máquina no momento.",
  ui_story_1020_10200601_22_dialog_content = "Bool só pode nos ajudar a recuperar os dados do módulo necessários para construir um núcleo. As informações que registramos agora foram apenas para ajudar nos cálculos, e nada mais.",
  ui_story_1020_10200601_23_dialog_content = "O protótipo foi selado todo esse tempo. Daqui para frente, não faço ideia de quais obstáculos nossa pesquisa encontrará.",
  ui_story_1020_10200601_24_dialog_content = "Celestita.",
  ui_story_1020_10200601_25_dialog_content = "...",
  ui_story_1020_10200601_26_dialog_content = "Você tá bem, PlayerName?",
  ui_story_1020_10200601_27_dialog_content = "Eu... Eu acho que vi algo piscando agora há pouco...",
  ui_story_1020_10200601_28_dialog_content = "Do quê?",
  ui_story_1020_10200601_29_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200601_30_dialog_content = "<color=#e8d9bb>Bipe—bipe—bipe—</color>",
  ui_story_1020_10200601_31_dialog_content = "Está trancado?",
  ui_story_1020_10200601_32_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200601_33_dialog_content = "Ei, qual é o problema?",
  ui_story_1020_10200601_34_dialog_content = "O armazém está tremendo!",
  ui_story_1020_10200601_35_dialog_content = "...",
  ui_story_1020_10200601_36_dialog_content = "Espere... Não deveria ter sido bloqueado, já que conseguimos recuperar os dados do módulo...",
  ui_story_1020_10200601_37_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200601_38_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200601_39_dialog_content = "Bool não estava extraindo códigos de defesa do protótipo para construir um novo núcleo?",
  ui_story_1020_10200601_40_dialog_content = "Isso está relacionado ao processo de resolução das violações de defesa?",
  ui_story_1020_10200601_41_dialog_content = "Parece que pode ser o caso, mas esse tremor é muito forte!",
  ui_story_1020_10200601_42_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200601_43_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200601_44_dialog_content = "Você está certo! É mais como se algo tivesse começado a atacar meus computadores e os sistemas de defesa da Illumina depois que recuperamos os dados do módulo do Guardian!",
  ui_story_1020_10200601_45_dialog_content = "É este um caso de algum jogo imitando a realidade? Intrusão de dados?",
  ui_story_1020_10200601_46_dialog_content = "Espere... Módulo de defesa, módulo de defesa... Só um segundo...",
  ui_story_1020_10200601_47_dialog_content = "Vocês vão avaliar a situação ao nosso redor. Tentarei recuperar o módulo de defesa novamente.",
  ui_story_1020_10200601_48_dialog_content = "Se o Guardião não está reforçando suas defesas, mas sim deteriorando-as ainda mais...",
  ui_story_1020_10200601_49_dialog_content = "Então a cidade baixa inteira está em apuros...",
  ui_story_1020_10200601_50_dialog_content = "Não. O que quer que esteja lutando contra nós agora está ou dentro do protótipo ou possivelmente do outro lado.",
  ui_story_1020_10200601_51_dialog_content = "...",
  ui_story_1020_10200601_52_dialog_content = "Mas o que poderia ser?",
  ui_story_1020_10200601_53_dialog_content = "Apenas Ulysses saberia...",
  ui_story_1020_10200601_54_dialog_content = "<color=#e8d9bb>Bipe—bipe—bipe—</color>",
  ui_story_1020_10200601_55_dialog_content = "Não! Ele cortou minha rota de acesso!",
  ui_story_1020_10200601_56_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200601_57_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1020_10200601_58_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1020_10200601_59_dialog_content = "<color=#e8d9bb>Bipe—bipe—bipe—</color>",
  ui_story_1020_10200601_60_dialog_content = "Tanta informação de uma vez...",
  ui_story_1020_10200601_61_dialog_content = "Túnel... Portão 10... A situação é pior do que eu pensava, Dr. Algol!",
  ui_story_1020_10200601_62_dialog_content = "Muitos dos sistemas de defesa da subcidade estão sob ataque!",
  ui_story_1020_10200601_63_dialog_content = "... Muitos dos controles provavelmente foram bloqueados. Chefe de Gabinete, temo que você terá que ir lá fora e dar uma mão por enquanto!",
  ui_story_1020_10200601_64_dialog_content = "Bool, reinicie o módulo!",
  ui_story_1020_10200601_65_dialog_content = "Buá!",
  ui_story_1020_10200601_66_dialog_content = "Gronru, Migard, vocês dois verifiquem o painel de controle no prédio do laboratório, especialmente áreas com armazéns e equipamentos de laboratório grandes.",
  ui_story_1020_10200601_67_dialog_content = "Vamos ter que controlar manualmente alguns dos interruptores por enquanto.",
  ui_story_1020_10200601_68_dialog_content = "Vou reunir mais informações daqueles que me enviaram mensagens, depois entrarei em contato com a Grande Marechal!",
  ui_story_1020_10200601_69_dialog_content = "Você tem percepções aguçadas, PlayerName. Alerta a todos quando sentir perigo!",
  ui_story_1020_10200601_70_dialog_content = "Sem problemas!",
  ui_story_1020_10200601_71_dialog_content = "(Isso tem algo a ver com aquela luz piscando que eu vi agora?)",
  ui_story_1020_10200601_72_dialog_content = "<color=#e8d9bb>Uma equipe de construção em um túnel da Illumina</color>",
  ui_story_1020_10200601_73_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200601_74_dialog_content = "Ciel! Ciel!",
  ui_story_1020_10200601_75_dialog_content = "Sai daí agora!",
  ui_story_1020_10200601_76_dialog_content = "O quê?",
  ui_story_1020_10200601_77_dialog_content = "Você não sentiu aquele tremor violento? O túnel à sua frente desabou!",
  ui_story_1020_10200601_78_dialog_content = "Mas é mais perigoso correr sem rumo agora...",
  ui_story_1020_10200601_79_dialog_content = "De qualquer forma, estou ativando o mecha dinâmico.",
  ui_story_1020_10200601_80_dialog_content = "<color=#e8d9bb>Centro Médico Illumina</color>",
  ui_story_1020_10200601_81_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200601_82_dialog_content = "Toda essa comoção...",
  ui_story_1020_10200601_83_dialog_content = "Eu acordei todo mundo de novo?",
  ui_story_1020_10200601_84_dialog_content = "...",
  ui_story_1020_10200601_85_dialog_content = "Não, não desta vez.",
  ui_story_1020_10200601_86_dialog_content = "ainda estou na cama...",
  ui_story_1020_10200601_87_dialog_content = "Reinhardt... Eu só espero poder fazer algo pela Illumina.",
  ui_story_1020_10200601_88_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1020_10200601_89_dialog_content = "Grande Marechal! Finalmente, você—",
  ui_story_1020_10200601_90_dialog_content = "Desculpe mantê-lo esperando.",
  ui_story_1020_10200601_91_dialog_content = "Uma máquina perigosa foi avistada em um armazém do Tech Park. Onde estão todos vocês?",
  ui_story_1020_10200601_92_dialog_content = "Estamos no Armazém Zero. Ulysses tem usado isso em segredo!",
  ui_story_1020_10200601_93_dialog_content = "Armazém Zero?",
  ui_story_1020_10200601_94_dialog_content = "Contém super-soldados e uma máquina antiga com possíveis ligações ao Eclipse que está causando o terremoto!",
  ui_story_1020_10200601_95_dialog_content = "Recuar!",
  ui_story_1020_10200601_96_dialog_content = "Todos precisam evacuar a área agora mesmo!",
  ui_story_1020_10200601_97_dialog_content = "Dr. Algol...",
  ui_story_1020_10200601_98_dialog_content = "Mantenha esses controles estáveis! Vai levar tempo se quisermos construir um novo núcleo para resolver as brechas de defesa!",
  ui_story_1020_10200601_99_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200601_100_dialog_content = "Ah, certo! Chefe de Gabinete, por favor, peça para Reinhardt escoltar Ulysses até aqui!",
  ui_story_1020_10200601_101_dialog_content = "<color=#e8d9bb>Sala de Conferência de Alto Nível Illumina</color>",
  ui_story_1020_10200601_102_dialog_content = "O sistema de controle automático está fora de controle. As portas próximas ao nível da superfície estão com defeito. O túnel desabou...",
  ui_story_1020_10200601_103_dialog_content = "É este o resultado que você estava esperando?",
  ui_story_1020_10200601_104_dialog_content = "E quanto a Lumópolis?",
  ui_story_1020_10200601_105_dialog_content = "Nada está acontecendo.",
  ui_story_1020_10200601_106_dialog_content = "...",
  ui_story_1020_10200601_107_dialog_content = "Você está pensando em anunciar o <color=#FFB400>Protocolo de Emergência</color>?",
  ui_story_1020_10200601_108_dialog_content = "Ainda não é a hora.",
  ui_story_1020_10200601_109_dialog_content = "Sinto o chão tremendo.",
  ui_story_1020_10200601_110_dialog_content = "Eu também faço.",
  ui_story_1020_10200601_111_dialog_content = "Isso é tudo o que as pessoas que afirmam querer tomar meu laboratório têm a oferecer?",
  ui_story_1020_10200601_112_dialog_content = "Heheh... O que você acha que é capaz de fazer?",
  ui_story_1020_10200601_113_dialog_content = "Você sabia que havia um problema com aquela máquina e estava apenas esperando algo acontecer, não é?",
  ui_story_1020_10200601_114_dialog_content = "... Problema com o protótipo?",
  ui_story_1020_10200601_115_dialog_content = "Você deveria... descobrir a história por si mesmo...",
  ui_story_1020_10200601_116_dialog_content = "Wrath, Hiiro, fiquem de olho em Ulysses. Não o percam de vista por qualquer motivo.",
  ui_story_1020_10200601_117_dialog_content = "Vou avaliar a situação e te dizer quando for seguro levá-lo para lá.",
  ui_story_1020_10200601_118_dialog_content = "Entendi.",
  ui_story_1020_10200601_119_dialog_content = "Assista, PlayerName.",
  ui_story_1020_10200601_120_dialog_content = "<color=#e8d9bb>Nível da superfície da cidade de Gannon</color>",
  ui_story_1020_10200601_121_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200601_122_dialog_content = "Sim, Comandante Barton! As paredes estão tremendo violentamente como se alguém tivesse acionado o interruptor dos portões!",
  ui_story_1020_10200601_123_dialog_content = "Todos os portões?",
  ui_story_1020_10200601_124_dialog_content = "Não. É principalmente que os Eclipsites estão se aproximando das duas portas seriamente danificadas à direita!",
  ui_story_1020_10200601_125_dialog_content = "Vivian e sua companhia provavelmente encontraram problemas.",
  ui_story_1020_10200601_126_dialog_content = "Defenda os portões a todo custo.",
  ui_story_1020_10200601_127_dialog_content = "Mesmo que eles façam buracos nelas, nós os taparemos com torretas e explodiremos os invasores à medida que eles chegarem!",
  ui_story_1020_10200601_128_dialog_content = "Se você gosta de ver cabeças de Eclipsites explodindo, você está com sorte hoje!",
  ui_story_1020_10200601_129_dialog_content = "Entendido!",
  ui_story_1020_10200601_130_dialog_content = "<color=#e8d9bb>Bum—Bum—Bum!</color>",
  ui_story_1020_10200601_131_dialog_content = "Hahaha!",
  ui_story_1020_10200601_132_dialog_content = "Cabeças explodindo!",
  ui_story_1020_10200601_133_dialog_content = "Aqui vem o mais poderoso na Barton Legião!",
  ui_story_1020_10200602_1_dialog_content = "Buá, buá, buá!",
  ui_story_1020_10200602_2_dialog_content = "...",
  ui_story_1020_10200602_3_dialog_content = "Vocês estão bem?",
  ui_story_1020_10200602_4_dialog_content = "Obrigado por parar os monstros atrás de mim, Grande Marechal!",
  ui_story_1020_10200602_5_dialog_content = "Nunca pensei que aqueles super-soldados caídos se levantariam e atacariam novamente!",
  ui_story_1020_10200602_6_dialog_content = "Estamos de volta, estamos de volta! O alarme de várias laboratórios realmente estava disparando!",
  ui_story_1020_10200602_7_dialog_content = "Eles estão trancados novamente, com soldados guardando do lado de fora do laboratório.",
  ui_story_1020_10200602_8_dialog_content = "Bom trabalho, pessoal.",
  ui_story_1020_10200602_9_dialog_content = "Então, mesmo com Illumina em uma situação tão crítica, você ainda insistiu em ir para algum lugar ainda mais perigoso. Por que não estou surpreso, PlayerName?",
  ui_story_1020_10200602_10_dialog_content = "Sinto muito...",
  ui_story_1020_10200602_11_dialog_content = "Estou apenas aliviado que você está seguro. Eu não fazia ideia de que Ulysses estava usando este lugar para produzir super-soldados...",
  ui_story_1020_10200602_12_dialog_content = "Dê-me um relatório de status, Vivian.",
  ui_story_1020_10200602_13_dialog_content = "Começou com violações nas defesas de Gannon e super-soldados nos atacando no Tech Park.",
  ui_story_1020_10200602_14_dialog_content = "Felizmente, a Dra. Algol encontrou este lugar e descobriu o protótipo selado. Ela está tentando construir um núcleo de defesa neste exato momento.",
  ui_story_1020_10200602_15_dialog_content = "Então o tremor de agora há pouco, esse problema foi resolvido?",
  ui_story_1020_10200602_16_dialog_content = "Por enquanto, sim. Consegui abrir uma nova rota de acesso e estabilizar os controles, mas quem sabe onde ocorrerá a próxima violação de segurança.",
  ui_story_1020_10200602_17_dialog_content = "Onde está Ulysses?",
  ui_story_1020_10200602_18_dialog_content = "Ele nos contou sobre esta máquina, mas eu precisava entender a situação antes de decidir se deveria ou não trazê-lo para cá.",
  ui_story_1020_10200602_19_dialog_content = "A condição dele agora é... especial, para dizer o mínimo.",
  ui_story_1020_10200602_20_dialog_content = "Ele te disse quem era o contato dele dentro do Eclipse?",
  ui_story_1020_10200602_21_dialog_content = "Se você está me perguntando isso, então não há dúvida sobre isso...",
  ui_story_1020_10200602_22_dialog_content = "Ele mencionou que encontrou pistas relacionadas ao Engenheiro dentro do protótipo.",
  ui_story_1020_10200602_23_dialog_content = "De acordo com Ulysses, o Engenheiro foi quem primeiro estabeleceu a Federação Illumina e desapareceu sem deixar rastros há mais de seiscentos anos atrás...",
  ui_story_1020_10200602_24_dialog_content = "Desapareceu seiscentos anos atrás... E agora o Engenheiro está usando um computador para se comunicar com Ulysses...",
  ui_story_1020_10200602_25_dialog_content = "Usando poderes psíquicos como PlayerName?",
  ui_story_1020_10200602_26_dialog_content = "Poder psíquico?",
  ui_story_1020_10200602_27_dialog_content = "(Essas visões que vi na minha cabeça... Foram feitas por poderes como o meu?)",
  ui_story_1020_10200602_28_dialog_content = "Não é algo que apenas os Celestitas podem fazer?",
  ui_story_1020_10200602_29_dialog_content = "Se o Engenheiro realmente existir, então a comunicação com Ulysses em tempo real através do protótipo é teoricamente possível, desde que o circuito seja eficiente o suficiente.",
  ui_story_1020_10200602_30_dialog_content = "Mas o protótipo não tem nenhum cabo, pelo que eu posso ver, nem qualquer hardware para enviar e receber mensagens, aliás. Isso significa—",
  ui_story_1020_10200602_31_dialog_content = "Bip—",
  ui_story_1020_10200602_32_dialog_content = "Esta é a <color=#FFB400>interface</color> que o Algol disse para o Guardião Um trazer.",
  ui_story_1020_10200602_33_dialog_content = "Obrigado, dá aqui.",
  ui_story_1020_10200602_34_dialog_content = "Então, por exemplo...",
  ui_story_1020_10200602_35_dialog_content = "Enquanto estiver conectado a um circuito como este, o Guardian One pode aparecer no meu computador e se comunicar comigo em tempo real.",
  ui_story_1020_10200602_36_dialog_content = "Oh. Oi, todo mundo! Meu rosto parece muito grande?",
  ui_story_1020_10200602_37_dialog_content = "Não vimos nenhum <color=#FFB400>circuito</color> assim quando verificamos. Tudo estava impecável. Até as paredes e pisos foram soldados de maneira perfeita...",
  ui_story_1020_10200602_38_dialog_content = "Isso é estranho. De acordo com nossos registros, este armazém não estava em uso porque muitos dos antigos circuitos praticamente se fundiram com o ambiente. Não havia como nós fazermos uso dele.",
  ui_story_1020_10200602_39_dialog_content = "É realmente esse o caso? Porque quando cheguei aqui pela primeira vez, não parecia diferente do que é agora.",
  ui_story_1020_10200602_40_dialog_content = "É possível que alguém o tenha consertado antes disso.",
  ui_story_1020_10200602_41_dialog_content = "Consertar um armazém tão grande não é tarefa fácil, aquele velho malandro...",
  ui_story_1020_10200602_42_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200602_43_dialog_content = "<color=#e8d9bb>Bzz—Bzz—</color>",
  ui_story_1020_10200602_44_dialog_content = "Ei, por que seus circuitos estão cintilando, Dr. Algol?",
  ui_story_1020_10200602_45_dialog_content = "Huh? Sobrecarga de energia? Mas isso é impossível!",
  ui_story_1020_10200602_46_dialog_content = "Espere... Cada componente único está funcionando com potência máxima?",
  ui_story_1020_10200602_47_dialog_content = "<color=#e8d9bb>Bzz—Bang!</color>",
  ui_story_1020_10200602_48_dialog_content = "Argh! Fritou meu circuito!",
  ui_story_1020_10200602_49_dialog_content = "Algol está com raiva.",
  ui_story_1020_10200602_50_dialog_content = "Buá, buá, buá!",
  ui_story_1020_10200602_51_dialog_content = "<color=#e8d9bb>Bipe—bipe—bipe—</color>",
  ui_story_1020_10200602_52_dialog_content = "De todas as sortes podres! Agora o novo módulo de defesa está travado!",
  ui_story_1020_10200602_53_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200602_54_dialog_content = "<color=#e8d9bb>Ampliação—</color>",
  ui_story_1020_10200602_55_dialog_content = "Está parando?",
  ui_story_1020_10200602_56_dialog_content = "<color=#e8d9bb>Zumbido—Buzz—</color>",
  ui_story_1020_10200602_57_dialog_content = "É um cérebro!",
  ui_story_1020_10200602_58_dialog_content = "...",
  ui_story_1020_10200602_59_dialog_content = "Poderia ser este o tão chamado \"Engenheiro\"?",
  ui_story_1020_10200602_60_dialog_content = "Aquelas imagens piscando... Estava tentando se comunicar comigo?",
  ui_story_1020_10200602_61_dialog_content = "Ei, como assim sumiu?",
  ui_story_1020_10200602_62_dialog_content = "Buá, buá, buá!",
  ui_story_1020_10200602_63_dialog_content = "O quê? Está falando? Você consegue decifrar a linguagem dele?",
  ui_story_1020_10200602_64_dialog_content = "... Buu, buu...",
  ui_story_1020_10200602_65_dialog_content = "O que o Engenheiro está dizendo?",
  ui_story_1020_10200602_66_dialog_content = "... Boo, boo...",
  ui_story_1020_10200602_67_dialog_content = "\"Já faz muito tempo\"",
  ui_story_1020_10200602_68_dialog_content = "... Buu, buu...",
  ui_story_1020_10200602_69_dialog_content = "\"Doutor\"",
  ui_story_1020_10200602_70_dialog_content = "... Buu, buu...",
  ui_story_1020_10200602_71_dialog_content = "\"Ulysses\"",
  ui_story_1020_10200602_72_dialog_content = "...",
  ui_story_1020_10200602_73_dialog_content = "Bool! Altere as rotas de acesso e tente recuperar o módulo!",
  ui_story_1020_10200602_74_dialog_content = "Buá!",
  ui_story_1020_10200602_75_dialog_content = "<color=#e8d9bb>Ampliação—</color>",
  ui_story_1020_10200602_76_dialog_content = "...",
  ui_story_1020_10200602_77_dialog_content = "Faz... muito tempo...",
  ui_story_1020_10200602_78_dialog_content = "Sim... Sim... Haha...",
  ui_story_1020_10200602_79_dialog_content = "Então você veio...",
  ui_story_1020_10200602_80_dialog_content = "Quem?",
  ui_story_1020_10200602_81_dialog_content = "O Engenheiro...",
  ui_story_1020_10200602_82_dialog_content = "Aonde?",
  ui_story_1020_10200602_83_dialog_content = "Dê-me o último comprimido, Esien.",
  ui_story_1020_10200602_84_dialog_content = "Senhor...",
  ui_story_1020_10200602_85_dialog_content = "Me dê isto!",
  ui_story_1020_10200602_86_dialog_content = "<color=#e8d9bb>Cela da Prisão Illumina</color>",
  ui_story_1020_10200602_87_dialog_content = "(Eclipsiano) É-É você... O supremo governante!",
  ui_story_1020_10200602_88_dialog_content = "(Eclipsiano) Seu fiel servo, Figerald, esteve ajoelhado aqui todo esse tempo, aguardando sua chegada.",
  ui_story_1020_10200602_89_dialog_content = "...",
  ui_story_1020_10200602_90_dialog_content = "<color=#e8d9bb>Clam—</color>",
  ui_story_1020_10200602_91_dialog_content = "(Eclipsiano) ...",
  ui_story_1020_10200602_92_dialog_content = "(Falando em Eclipsiano) E-Eu tremo diante de você! Eu nunca ousaria ir contra seus desejos!",
  ui_story_1020_10200602_93_dialog_content = "(Eclipsiano) Permita-me redimir-me...",
  ui_story_1020_10200602_94_dialog_content = "(Eclipsiano) A missão que eu já falhei será completada, mesmo ao custo da minha própria vida.",
  ui_story_1020_10200701_1_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200701_2_dialog_content = "Ele já pegou o núcleo do Guardião Um, Ulysses. O que mais ele quer?",
  ui_story_1020_10200701_3_dialog_content = "Você não acha assustador que a Cidade Baixa esteja à beira do colapso, Máscara de Ferro?",
  ui_story_1020_10200701_4_dialog_content = "Você planejou tudo isso... Você entregou a essência da vida da Illumina para o Eclipse em uma bandeja apenas para obter mais ativos de pesquisa e realizar seu sonho?",
  ui_story_1020_10200701_5_dialog_content = "Eu também já acreditei que a Illumina não estaria aqui hoje sem o Engenheiro.",
  ui_story_1020_10200701_6_dialog_content = "Então percebi que o núcleo do Guardião Um nunca foi a força vital de Illumina.",
  ui_story_1020_10200701_7_dialog_content = "Eu fui!",
  ui_story_1020_10200701_8_dialog_content = "Como o sistema de defesa de Gannon pode se transformar em uma peneira simplesmente por causa de um núcleo ausente?",
  ui_story_1020_10200701_9_dialog_content = "Deixe-me contar sobre o plano do Engenheiro...",
  ui_story_1020_10200701_10_dialog_content = "Ele queria unificar e queimar, desafiar a insignificância dos Aurorianos com sua grandeza...",
  ui_story_1020_10200701_11_dialog_content = "Mas eu não quero esperar pela minha morte nesta sombria undercity como você! Eu vou desafiá-lo!",
  ui_story_1020_10200701_12_dialog_content = "Loucura... Isso é loucura!",
  ui_story_1020_10200701_13_dialog_content = "Você sabe como ele planejou realizar isso?",
  ui_story_1020_10200701_14_dialog_content = "Ele construiu tudo isso, entrou em silêncio e entregou as tarefas de recuperação do núcleo e criação de Eclipsitas ao tolo Wraith.",
  ui_story_1020_10200701_15_dialog_content = "Dormente por várias centenas de anos, ele despertou.",
  ui_story_1020_10200701_16_dialog_content = "Mas o mundo mudou. Ele já não é mais o Engenheiro que eu aprendi nos arquivos.",
  ui_story_1020_10200701_17_dialog_content = "O que ele pode fazer, eu provavelmente também consigo realizar.",
  ui_story_1020_10200701_18_dialog_content = "Cala a sua boca fedorenta!",
  ui_story_1020_10200701_19_dialog_content = "Qualquer um de nós aqui pode te matar com um aceno de mão. É melhor você—",
  ui_story_1020_10200701_20_dialog_content = "O que você pode fazer?",
  ui_story_1020_10200701_21_dialog_content = "...",
  ui_story_1020_10200701_22_dialog_content = "Heheh... Tenho tudo o que preciso pronto no meu armazém.",
  ui_story_1020_10200701_23_dialog_content = "Alto!",
  ui_story_1020_10200701_24_dialog_content = "... Você está tentando me impedir?",
  ui_story_1020_10200701_25_dialog_content = "Você não vai a lugar nenhum.",
  ui_story_1020_10200701_26_dialog_content = "... Nenhum de vocês acredita em mim, mas agora eu sou o único que pode—",
  ui_story_1020_10200701_27_dialog_content = "Apenas dê mais um passo!",
  ui_story_1020_10200701_28_dialog_content = "Guarde a arma.",
  ui_story_1020_10200701_29_dialog_content = "...",
  ui_story_1020_10200701_30_dialog_content = "O tempo está se esgotando para você e para mim, Máscara de Ferro, mas Illumina ainda tem um longo caminho a percorrer, assim como os Aurorians.",
  ui_story_1020_10200701_31_dialog_content = "Eu sabia que este dia chegaria, mas não vou desistir mesmo que todos vocês desaprovem!",
  ui_story_1020_10200701_32_dialog_content = "Vou lutar do meu jeito.",
  ui_story_1020_10200701_33_dialog_content = "Se você não pode ajudar, eu farei isso sozinho...",
  ui_story_1020_10200701_34_dialog_content = "Você tem coragem de ver?",
  ui_story_1020_10200701_35_dialog_content = "...",
  ui_story_1020_10200701_36_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_1020_10200701_37_dialog_content = "Grande marechal?",
  ui_story_1020_10200701_38_dialog_content = "Ela nos disse para trazer Ulysses para cá.",
  ui_story_1020_10200701_39_dialog_content = "...",
  ui_story_1020_10200701_40_dialog_content = "O jogo de xadrez não é nada sem as peças de xadrez, Belisaria. Como você pode se dar ao luxo de ser o único a fazer movimentos nesse caso?",
  ui_story_1020_10200701_41_dialog_content = "Acredito que, aconteça o que acontecer, Reinhardt manterá Gannon intacto. Mas você é capaz do mesmo?",
  ui_story_1020_10200701_42_dialog_content = "...",
  ui_story_1020_10200701_43_dialog_content = "Davidar, entre em contato com Barrett.",
  ui_story_1020_10200701_44_dialog_content = "Dr. Barrett está te esperando há muito tempo.",
  ui_story_1020_10200701_45_dialog_content = "Qual é a decisão?",
  ui_story_1020_10200701_46_dialog_content = "Inicie o <color=#FFB400>Protocolo de Emergência</color>.",
  ui_story_1020_10200701_47_dialog_content = "Desembale o equipamento original, altere a rota pré-definida, abra o eixo de transporte e transporte os civis para as cidades subterrâneas de reserva.",
  ui_story_1020_10200701_48_dialog_content = "Os veículos e o eixo de transporte estão funcionando normalmente. Civis podem ser transportados.",
  ui_story_1020_10200701_49_dialog_content = "Mas eu solicito tropas suficientes para garantir o transporte seguro nos eixos do Comitê.",
  ui_story_1020_10200701_50_dialog_content = "Apenas faça. O Comitê abrirá o caminho para você.",
  ui_story_1020_10200701_51_dialog_content = "É assim que eu gosto.",
  ui_story_1020_10200701_52_dialog_content = "Vocês dois levem Ulysses para o depósito.",
  ui_story_1020_10200701_53_dialog_content = "Espere, veículos e eixo de transporte... Como assim?",
  ui_story_1020_10200701_54_dialog_content = "Aeronaves desenvolvidas pela Illumina e uma rede de trilhos subterrâneos projetados especificamente para elas.",
  ui_story_1020_10200701_55_dialog_content = "Aeronaves?",
  ui_story_1020_10200701_56_dialog_content = "Você acha que a Illumina só tem trens terrestres, transportadoras e túneis?",
  ui_story_1020_10200701_57_dialog_content = "Então, para que servem o equipamento original e a rota pré-definida?",
  ui_story_1020_10200701_58_dialog_content = "Não me importo em te dizer - essas aeronaves são destinadas àquela cidade flutuante, e a rota pré-definida vai direto para Lumópolis daqui.",
  ui_story_1020_10200701_59_dialog_content = "Essas aeronaves foram armadas para atacar Lumópolis?",
  ui_story_1020_10200701_60_dialog_content = "Você precisa de armas diferentes para lutar contra adversários diferentes. E quando você decide atingir a superfície, tem que fazer o que for necessário.",
  ui_story_1020_10200701_61_dialog_content = "...",
  ui_story_1020_10200701_62_dialog_content = "Eu não antecipava que este seria o momento de iniciar o protocolo.",
  ui_story_1020_10200701_63_dialog_content = "Mesmo que você não esteja dizendo, pelo menos nesse assunto, temos o mesmo interesse.",
  ui_story_1020_10200701_64_dialog_content = "Leve Ulysses para o depósito dele. Ele é seu refém agora.",
  ui_story_1020_10200701_65_dialog_content = "...",
  ui_story_1020_10200701_66_dialog_content = "Heheh. Vejo que você não é mais o líder cínico que costumava ser.",
  ui_story_1020_10200701_67_dialog_content = "Nos veremos novamente, certo?",
  ui_story_1020_10200701_68_dialog_content = "Há tempo para brincadeiras.",
  ui_story_1020_10200701_69_dialog_content = "Mas você precisa ser sério quando a situação aperta.",
  ui_story_1020_10200701_70_dialog_content = "Se você conseguir fazer isso, acho que não precisamos nos ver novamente.",
  ui_story_1020_10200701_71_dialog_content = "Nada aconteceu em Lumópolis mesmo depois que o eixo de transporte foi aberto.",
  ui_story_1020_10200701_72_dialog_content = "Depois de manter um perfil baixo por tantos anos, seria uma pena não aproveitar esta oportunidade para atacar a cidade flutuante.",
  ui_story_1020_10200701_73_dialog_content = "Volte para suas funções. Ainda temos muitas coisas esperando para fazer.",
  ui_story_1020_10200701_74_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200701_75_dialog_content = "Axelia, Yingel, o que devemos fazer agora?",
  ui_story_1020_10200701_76_dialog_content = "O que sempre fizemos antes. O Grande Marechal e outros foram ao armazém, então devemos protegê-los.",
  ui_story_1020_10200701_77_dialog_content = "Como máquinas de guerra, vocês sempre sabem o que devem fazer em todos os momentos?",
  ui_story_1020_10200701_78_dialog_content = "Ficou claro para mim desde que fiquei velho o suficiente para pensar.",
  ui_story_1020_10200701_79_dialog_content = "Eu acabei de saber disso recentemente. Você também vai saber, Sean.",
  ui_story_1020_10200701_80_dialog_content = "Fácil para você dizer. Vocês dois são—",
  ui_story_1020_10200701_81_dialog_content = "Ai!",
  ui_story_1020_10200701_82_dialog_content = "Yingel! Por que você me beliscou? Estou sangrando...",
  ui_story_1020_10200701_83_dialog_content = "As máquinas de guerra não são também Aurorians de carne e osso?",
  ui_story_1020_10200701_84_dialog_content = "Esqueça o que aconteceu na reunião. Não importa o que aconteça, o Grande Marechal nunca minimizará sua existência ou propósito.",
  ui_story_1020_10200701_85_dialog_content = "Ela e o Grande Marechal Wrath são ambos vítimas do projeto, mas ainda estão cumprindo seus deveres.",
  ui_story_1020_10200701_86_dialog_content = "Provavelmente é estranho dizer isso, mas com Grandes Marechais como eles, eu não tenho medo algum.",
  ui_story_1020_10200701_87_dialog_content = "...",
  ui_story_1020_10200701_88_dialog_content = "Nem eu.",
  ui_story_1020_10200701_89_dialog_content = "Você...",
  ui_story_1020_10200701_90_dialog_content = "Vamos, vamos embora! Corra mais rápido, Sean!",
  ui_story_1020_10200701_91_dialog_content = "... OK!",
  ui_story_1020_10200701_92_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200801_1_dialog_content = "A tremedeira... Parou.",
  ui_story_1020_10200801_2_dialog_content = "Conseguimos construir um novo núcleo?",
  ui_story_1020_10200801_3_dialog_content = "Não... A velocidade de processamento é mais lenta do que esperávamos, e demora muito para realizar isso.",
  ui_story_1020_10200801_4_dialog_content = "Mas só me dê um pouco mais de tempo. Eu sei que posso fazer isso!",
  ui_story_1020_10200801_5_dialog_content = "Buá!",
  ui_story_1020_10200801_6_dialog_content = "Pare de perder tempo...",
  ui_story_1020_10200801_7_dialog_content = "Fique parado, Ulysses!",
  ui_story_1020_10200801_8_dialog_content = "Você está aqui.",
  ui_story_1020_10200801_9_dialog_content = "Também foi ideia de Belisaria. Ela ordenou que o povo de Gannon se realocasse.",
  ui_story_1020_10200801_10_dialog_content = "Não consigo acreditar... Dr. Algol, como você planeja lidar com Ulysses?",
  ui_story_1020_10200801_11_dialog_content = "Diga-me, Ulysses, você fez todos esses Eclipsitas como parte de um acordo com o Engenheiro?",
  ui_story_1020_10200801_12_dialog_content = "Que ingênuo. Mas parece que você aprendeu algo ao longo dos anos para acessar o sistema e manter Gannon estável.",
  ui_story_1020_10200801_13_dialog_content = "No entanto, você se superestimou quando tentou acessar os dados de defesa do Guardião e defender seus ataques ao mesmo tempo.",
  ui_story_1020_10200801_14_dialog_content = "O que você quer chegar?",
  ui_story_1020_10200801_15_dialog_content = "As violações na Illumina não podem ser corrigidas uma de cada vez. É simples desmontar as defesas.",
  ui_story_1020_10200801_16_dialog_content = "Mas eu posso simplesmente dizer a ele para parar.",
  ui_story_1020_10200801_17_dialog_content = "Mostre-me como fazer isso.",
  ui_story_1020_10200801_18_dialog_content = "Não posso fazer isso. Eu disse que o Celestita poderia, mas nenhum de vocês acreditou.",
  ui_story_1020_10200801_19_dialog_content = "Eu?",
  ui_story_1020_10200801_20_dialog_content = "Não o envolva nisso. Apenas nos diga como parar o Engenheiro.",
  ui_story_1020_10200801_21_dialog_content = "Parar? Eu não quero pará-lo. Estou aqui apenas para ver se você machucou meus bebês.",
  ui_story_1020_10200801_22_dialog_content = "Você se atreve a voltar atrás na sua palavra!",
  ui_story_1020_10200801_23_dialog_content = "A coisa toda não teve nada a ver com nenhum de vocês desde o início.",
  ui_story_1020_10200801_24_dialog_content = "<color=#e8d9bb>Zumbido—Buzz—</color>",
  ui_story_1020_10200801_25_dialog_content = "De novo não...",
  ui_story_1020_10200801_26_dialog_content = "... Buu, buu...",
  ui_story_1020_10200801_27_dialog_content = "\"Presente\"?",
  ui_story_1020_10200801_28_dialog_content = "... O que isso significa?",
  ui_story_1020_10200801_29_dialog_content = "Não vou te culpar pelos experimentos incompletos que você destruiu.",
  ui_story_1020_10200801_30_dialog_content = "Mas eu preparei algo a mais para ele.",
  ui_story_1020_10200801_31_dialog_content = "Deixe-me ver, deve ser por aqui...",
  ui_story_1020_10200801_32_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200801_33_dialog_content = "Argh!",
  ui_story_1020_10200801_34_dialog_content = "Segure-se em mim!",
  ui_story_1020_10200801_35_dialog_content = "O que você fez, Ulysses?",
  ui_story_1020_10200801_36_dialog_content = "Este é um terremoto maior do que o último!",
  ui_story_1020_10200801_37_dialog_content = "Não está apenas balançando! Está se mexendo!",
  ui_story_1020_10200801_38_dialog_content = "Não perca o equilíbrio—",
  ui_story_1020_10200801_39_dialog_content = "Hahahahaha! Contemple!",
  ui_story_1020_10200801_40_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200801_41_dialog_content = "Aqueles <color=#FFB400>super-soldados</color>, a fusão de Aurorianos e Eclipsitas, cada um capaz de lutar contra cem inimigos de uma vez...",
  ui_story_1020_10200801_42_dialog_content = "Eles superaram qualquer coisa que você fez há muito tempo!",
  ui_story_1020_10200801_43_dialog_content = "Todo o subsolo está inundado...",
  ui_story_1020_10200801_44_dialog_content = "Quantos são?",
  ui_story_1020_10200801_45_dialog_content = "... Eles estão debaixo do chão em que estamos pisando! Não é de admirar que não conseguimos encontrá-los!",
  ui_story_1020_10200801_46_dialog_content = "Algumas centenas, na minha estimativa... Não, mais.",
  ui_story_1020_10200801_47_dialog_content = "Eles têm cabos saindo de todos os poros, como se estivessem sendo alimentados...",
  ui_story_1020_10200801_48_dialog_content = "Ulysses!",
  ui_story_1020_10200801_49_dialog_content = "<color=#e8d9bb>Bang—Bang—Bang—</color>",
  ui_story_1020_10200801_50_dialog_content = "Isso é ruim... Aqueles super-soldados estão começando a se mover!",
  ui_story_1020_10200801_51_dialog_content = "<color=#e8d9bb>Estrondo—Estrondo—</color>",
  ui_story_1020_10200801_52_dialog_content = "Confira os fios no armazém... Eles estão soltando faíscas!",
  ui_story_1020_10200801_53_dialog_content = "Os cabos fundidos ao ambiente estavam no armazém o tempo todo!",
  ui_story_1020_10200801_54_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200801_55_dialog_content = "Então é assim que ele controla os supersoldados. Com isso, ele poderia dar ordens a eles através do computador...",
  ui_story_1020_10200801_56_dialog_content = "...Agora entendi! Bool!",
  ui_story_1020_10200801_57_dialog_content = "Buá!",
  ui_story_1020_10200801_58_dialog_content = "Então, como você gosta disso?",
  ui_story_1020_10200801_59_dialog_content = "Os Eclipsitas que invadiram Astra dez ou até vinte anos atrás não podem esperar competir com eles!",
  ui_story_1020_10200801_60_dialog_content = "O quê?",
  ui_story_1020_10200801_61_dialog_content = "Hahaha!",
  ui_story_1020_10200801_62_dialog_content = "<color=#e8d9bb>Zumbido—Buzz—</color>",
  ui_story_1020_10200801_63_dialog_content = "(Como o Engenheiro consegue ouvir a voz de Ulysses?)",
  ui_story_1020_10200801_64_dialog_content = "(É o protótipo? Ou eles têm algum outro meio de comunicação?)",
  ui_story_1020_10200801_65_dialog_content = "... Buu, buu...",
  ui_story_1020_10200801_66_dialog_content = "\"Não é\"",
  ui_story_1020_10200801_67_dialog_content = "... Buu, buu...",
  ui_story_1020_10200801_68_dialog_content = "\"Vale a pena mencionar\"",
  ui_story_1020_10200801_X68_dialog_content = "(Como o Engenheiro consegue ouvir a voz de Ulysses?)",
  ui_story_1020_10200801_X69_dialog_content = "(É o protótipo? Ou eles têm algum outro meio de comunicação?)",
  ui_story_1020_10200801_69_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200801_70_dialog_content = "Os super-soldados estão de pé!",
  ui_story_1020_10200801_X70_dialog_content = "Como você gosta disso... Haha...",
  ui_story_1020_10200801_71_dialog_content = "Hiiro, subjugar Ulysses! Todos os outros, retirem-se!",
  ui_story_1020_10200801_72_dialog_content = "Entendido!",
  ui_story_1020_10200801_73_dialog_content = "...",
  ui_story_1020_10200801_74_dialog_content = "Dr. Algol!",
  ui_story_1020_10200801_75_dialog_content = "... Illumina está acabada se deixarmos essa máquina sozinha!",
  ui_story_1020_10200801_76_dialog_content = "Como você gosta disso... Haha...",
  ui_story_1020_10200801_77_dialog_content = "<color=#e8d9bb>Bipe—bipe—bipe—</color>",
  ui_story_1020_10200801_78_dialog_content = "Diga-nos como desligar o armazém, Ulysses!",
  ui_story_1020_10200801_79_dialog_content = "Responda-me!",
  ui_story_1020_10200801_80_dialog_content = "Isso não tem nada a ver com você. Eles não são seus inimigos! Você pode simplesmente ir embora...",
  ui_story_1020_10200801_81_dialog_content = "Chega de suas bobagens!",
  ui_story_1020_10200801_82_dialog_content = "Bool, você encontrou outra entrada? Você precisa se apressar!",
  ui_story_1020_10200801_83_dialog_content = "Buá, buá, buá!",
  ui_story_1020_10200801_X83_dialog_content = "Vamos, só um pouco mais rápido!",
  ui_story_1020_10200801_84_dialog_content = "<color=#e8d9bb>Bang—Bang—Bang—</color>",
  ui_story_1020_10200801_85_dialog_content = "Roaaarrrr—",
  ui_story_1020_10200801_86_dialog_content = "Dr. Algol!",
  ui_story_1020_10200801_87_dialog_content = "...",
  ui_story_1020_10200801_88_dialog_content = "Dr. Algol ainda se recusa a sair...",
  ui_story_1020_10200801_89_dialog_content = "Deixe-me usar meus poderes para resgatá-lo, Algol!",
  ui_story_1020_10200801_90_dialog_content = "Não! Apenas saiam daqui, todos vocês!",
  ui_story_1020_10200801_91_dialog_content = "Já encontrei uma maneira de controlar os supersoldados...",
  ui_story_1020_10200801_92_dialog_content = "Buá, buá, buá!",
  ui_story_1020_10200801_93_dialog_content = "Bom, o banco de dados foi atualizado! Só preciso acessá-lo agora...",
  ui_story_1020_10200801_94_dialog_content = "Vamos lá... Só um pouco mais rápido!",
  ui_story_1020_10200801_95_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200801_96_dialog_content = "Desvie, Algol!",
  ui_story_1020_10200801_97_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_1020_10200801_98_dialog_content = "Boo?",
  ui_story_1020_10200801_99_dialog_content = "Roaaarrrr—",
  ui_story_1020_10200801_100_dialog_content = "O que está acontecendo? Os supersoldados não estão atacando Algol!",
  ui_story_1020_10200801_101_dialog_content = "...",
  ui_story_1020_10200801_102_dialog_content = "<color=#e8d9bb>Bang! Bang! Bang!</color>",
  ui_story_1020_10200801_103_dialog_content = "Eles estão atacando... o protótipo?",
  ui_story_1020_10200801_104_dialog_content = "É por isso que Ulysses criou esses supersoldados?",
  ui_story_1020_10200801_105_dialog_content = "Hahahahahaha, você gosta disso, não é?",
  ui_story_1020_10200801_106_dialog_content = "Como se sente? Onde estão seus Eclipsitas agora?",
  ui_story_1020_10200801_107_dialog_content = "<color=#e8d9bb>Zumbido—Buzz—</color>",
  ui_story_1020_10200801_108_dialog_content = "... Buá, buá...",
  ui_story_1020_10200801_109_dialog_content = "\"Obrigado\"",
  ui_story_1020_10200801_110_dialog_content = "... Obrigado?",
  ui_story_1020_10200801_111_dialog_content = "...",
  ui_story_1020_10200801_112_dialog_content = "Rugido...",
  ui_story_1020_10200801_113_dialog_content = "Os super-soldados... Eles pararam de se mover.",
  ui_story_1020_10200801_114_dialog_content = "O que eles estão procurando?",
  ui_story_1020_10200801_115_dialog_content = "<color=#e8d9bb>Bzz—Bzz—</color>",
  ui_story_1020_10200801_116_dialog_content = "Os cabos estão ficando malucos de novo, Dr. Algol!",
  ui_story_1020_10200801_117_dialog_content = "Não se preocupe. Eu vou simplesmente cancelar os pedidos deles...",
  ui_story_1020_10200801_118_dialog_content = "<color=#e8d9bb>Bipe—bipe—bipe—</color>",
  ui_story_1020_10200801_119_dialog_content = "Você está brincando comigo? Argh, eu odeio essa coisa!",
  ui_story_1020_10200801_120_dialog_content = "O que está fazendo?",
  ui_story_1020_10200801_121_dialog_content = "<color=#e8d9bb>Bzz—Bzz—</color>",
  ui_story_1020_10200801_122_dialog_content = "Olhe o que está atrás dos super-soldados!",
  ui_story_1020_10200801_123_dialog_content = "Rooooaaaar!",
  ui_story_1020_10200801_124_dialog_content = "Ele está começando a atacar!",
  ui_story_1020_10200801_125_dialog_content = "O que você está fazendo com meus bebês?",
  ui_story_1020_10200801_126_dialog_content = "Rooooaaaar!",
  ui_story_1020_10200801_127_dialog_content = "Cuidado, Algol!",
  ui_story_1020_10200901_1_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200901_2_dialog_content = "Comandante Barton, já tentamos o nosso melhor!",
  ui_story_1020_10200901_3_dialog_content = "Mas nossos camaradas no <color=#FFB400>Portão 10</color> ainda estão envolvidos na batalha e precisam urgentemente de assistência!",
  ui_story_1020_10200901_4_dialog_content = "Então todos vocês, elites, vão apenas deixar alguém aproveitar essa oportunidade para lutar?",
  ui_story_1020_10200901_5_dialog_content = "Não, Comandante! Os portões estão tremendo violentamente demais para nossos corpos aguentarem...",
  ui_story_1020_10200901_6_dialog_content = "Portão 10... Não é isso em direção ao pátio de serviço?",
  ui_story_1020_10200901_7_dialog_content = "Esse garoto está tentando monopolizar a glória ao fazer o Soroz sustentar os portões?",
  ui_story_1020_10200901_8_dialog_content = "Um Colossus pode suportar os portões?",
  ui_story_1020_10200901_9_dialog_content = "Por que não consegue, quando conseguiu criar o celestita?",
  ui_story_1020_10200901_10_dialog_content = "Siga-me! Ninguém pode me dizer que este corpo é inferior a um monte de lixo!",
  ui_story_1020_10200901_11_dialog_content = "Comandante! Também está tremendo violentamente no <color=#FFB400>Portão 9</color>. Parece que uma forte corrente de ar está subindo do subsolo para os níveis superiores!",
  ui_story_1020_10200901_12_dialog_content = "Subterrâneo? Verifique todos os ventiladores agora! Cada canto e cada centímetro!",
  ui_story_1020_10200901_13_dialog_content = "Já inspecionamos tudo! Não foram encontrados vestígios de Eclipsitas!",
  ui_story_1020_10200901_14_dialog_content = "O que está acontecendo aqui?",
  ui_story_1020_10200901_15_dialog_content = "<color=#e8d9bb>Ao redor do Portão 9</color>",
  ui_story_1020_10200901_16_dialog_content = "Oficial, o chão está tremendo muito nesta área. Por favor, evacue para um lugar seguro!",
  ui_story_1020_10200901_17_dialog_content = "Não se preocupe comigo. O eixo de transporte abaixo está funcionando, e eu vim para avaliar o nível de tremor aqui em cima.",
  ui_story_1020_10200901_18_dialog_content = "O poço de transporte...",
  ui_story_1020_10200901_19_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200901_20_dialog_content = "Aceitável, dificilmente prejudicial ao portão.",
  ui_story_1020_10200901_21_dialog_content = "...",
  ui_story_1020_10200901_22_dialog_content = "<color=#e8d9bb>Dawn Academia de Lumópolis</color>",
  ui_story_1020_10200901_23_dialog_content = "Avante, Noite Branca! Você ouviu? Algo estranho aconteceu com a <color=#FFB400>Pedra da Noite Branca</color> da academia, e Lumina tem flutuado loucamente por um longo tempo.",
  ui_story_1020_10200901_24_dialog_content = "O Pai e as freiras correram, mas não conseguiram acalmar as flutuações, mesmo lançando Luminatics com todo o seu poder!",
  ui_story_1020_10200901_25_dialog_content = "Isso está relacionado à vibração que abalou Lumópolis mais cedo?",
  ui_story_1020_10200901_26_dialog_content = "Sim, receio que as ruínas antigas começaram a ressoar com um poder misterioso novamente.",
  ui_story_1020_10200901_27_dialog_content = "Isso aconteceu antes, quando um distúrbio da aurora eclodiu em Crepúsculo no passado, mas as coisas estão mais sérias desta vez.",
  ui_story_1020_10200901_28_dialog_content = "<color=#e8d9bb>Lumópolis, Corte Real</color>",
  ui_story_1020_10200901_29_dialog_content = "Veja, esses eixos estão se abrindo como uma boca faminta no chão. Illumina foi reduzida a um lobo faminto!",
  ui_story_1020_10200901_30_dialog_content = "O lobo ainda não mordeu Lumopolis.",
  ui_story_1020_10200901_31_dialog_content = "Cancele o alarme, Capitão. As ruínas estão basicamente seguras agora.",
  ui_story_1020_10200901_32_dialog_content = "Sim, meu senhor.",
  ui_story_1020_10200901_33_dialog_content = "Senhor da Cidade, a pedra contendo Lumina na Dawn Academia reagiu violentamente à vibração. Você acha que há uma força desconhecida em Lumópolis?",
  ui_story_1020_10200901_34_dialog_content = "Noite Branca lá no alto. Alteza, não precisa se preocupar com isso.",
  ui_story_1020_10200901_35_dialog_content = "Embora isso nunca tenha acontecido desde que a Senhora Santa entrou no Templo de Lumopolis, o Deus da Luz nos guiará.",
  ui_story_1020_10200901_36_dialog_content = "O que você acha que causou a resposta na Pedra da Noite Branca, Pai?",
  ui_story_1020_10200901_37_dialog_content = "Algo relevante foi registrado nos tomos. Diz-se que o Lumina começará a flutuar selvagemente quando um novo <color=#FFB400>herdeiro espiritual</color> aparecer.",
  ui_story_1020_10200901_38_dialog_content = "...",
  ui_story_1020_10200901_39_dialog_content = "A força maligna escondida nas ruínas subterrâneas já abalou todo o Azurite. Foi a Herdeira do Espírito - a Santa - que a dissipou.",
  ui_story_1020_10200901_40_dialog_content = "Pelo que eu contei, a Santa protegeu Azurita por muitos anos.",
  ui_story_1020_10200901_41_dialog_content = "O mal só pode ser afastado, mas não banido. Lumópolis não é puro.",
  ui_story_1020_10200901_42_dialog_content = "Lumópolis estará em perigo, Pai?",
  ui_story_1020_10200901_43_dialog_content = "Não.",
  ui_story_1020_10200901_44_dialog_content = "E quanto à Federação Illumina?",
  ui_story_1020_10200901_45_dialog_content = "Primeiro, eles devem encontrar sua própria fé.",
  ui_story_1020_10200901_46_dialog_content = "Fique atento para mensagens de Illumina, Capitão.",
  ui_story_1020_10200901_47_dialog_content = "Sim, Senhor Schwartz.",
  ui_story_1020_10200901_48_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10200901_49_dialog_content = "Qual é a situação atual, Dr. Algol?",
  ui_story_1020_10200901_50_dialog_content = "O painel de controle agora está mostrando que o núcleo está quase completo.",
  ui_story_1020_10200901_51_dialog_content = "Não consigo acreditar que o Engenheiro ainda não nos atacou... Aguente firme, Bool!",
  ui_story_1020_10200901_52_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200901_53_dialog_content = "O quê?",
  ui_story_1020_10200901_54_dialog_content = "<color=#e8d9bb>Zumbido—Buzz—</color>",
  ui_story_1020_10200901_55_dialog_content = "... Buu, buu...",
  ui_story_1020_10200901_56_dialog_content = "\"Vá para casa, Celestita\"",
  ui_story_1020_10200901_57_dialog_content = "O Celestita não vai a lugar nenhum!",
  ui_story_1020_10200901_58_dialog_content = "...",
  ui_story_1020_10200901_59_dialog_content = "O Engenheiro não estava falando com Ulysses? Como ele sabia sobre PlayerName?",
  ui_story_1020_10200901_60_dialog_content = "Venha para casa, Celestita.",
  ui_story_1020_10200901_61_dialog_content = "Acho que ouço a voz dele...",
  ui_story_1020_10200901_62_dialog_content = "De onde está vindo isso?",
  ui_story_1020_10200901_63_dialog_content = "De dentro da minha cabeça...",
  ui_story_1020_10200901_64_dialog_content = "Então, aquelas visões que eu vi foram realmente feitas por poderes psíquicos afinal de contas...",
  ui_story_1020_10200901_65_dialog_content = "Venha para casa, Celestita.",
  ui_story_1020_10200901_66_dialog_content = "... Quem é você?",
  ui_story_1020_10200901_67_dialog_content = "Vocês me chamam de Engenheiro.",
  ui_story_1020_10200901_68_dialog_content = "Você é um Eclipsita... E está controlando os super-soldados da Illumina através desta máquina, a mando do Eclipse, não está?",
  ui_story_1020_10200901_69_dialog_content = "Não.",
  ui_story_1020_10200901_70_dialog_content = "... Mas você roubou o núcleo do Guardião Um, o que permitiu que os Eclipsitas invadissem a cidade de Gannon.",
  ui_story_1020_10200901_71_dialog_content = "Isso me pertence em primeiro lugar.",
  ui_story_1020_10200901_72_dialog_content = "Assim como você.",
  ui_story_1020_10200901_73_dialog_content = "... Eu sou um Celestita. Eu nasci em Eraveil.",
  ui_story_1020_10200901_74_dialog_content = "De onde vieram os Celestitas?",
  ui_story_1020_10200901_75_dialog_content = "O que você fez com o meu povo... comigo?",
  ui_story_1020_10200901_76_dialog_content = "Venha para casa, Celestita.",
  ui_story_1020_10200901_77_dialog_content = "Continue a nobre causa comigo.",
  ui_story_1020_10200901_78_dialog_content = "Causa nobre? O Celestita não vai a lugar nenhum!",
  ui_story_1020_10200901_79_dialog_content = "Sobre o que você está falando, Ulysses?",
  ui_story_1020_10200901_80_dialog_content = "...",
  ui_story_1020_10200901_81_dialog_content = "Ele também pode se conectar com sua mente?",
  ui_story_1020_10200901_82_dialog_content = "Ele e você não são a mesma coisa.",
  ui_story_1020_10200901_83_dialog_content = "Vou te contar toda a verdade que você está morrendo de curiosidade para saber.",
  ui_story_1020_10200901_84_dialog_content = "Sobre as antigas batalhas da Zona Escura, o nível de atracação dos Colossos, a casa dos Celestitas...",
  ui_story_1020_10200901_85_dialog_content = "E os compatriotas que você tem ansiado.",
  ui_story_1020_10200901_86_dialog_content = "!",
  ui_story_1020_10200901_87_dialog_content = "<color=#e8d9bb>Bip—Bip bip—Bip bip bip—</color>",
  ui_story_1020_10200901_88_dialog_content = "A pulseira do Algol está reportando uma ameaça.",
  ui_story_1020_10200901_89_dialog_content = "O pátio de serviço Illumina...",
  ui_story_1020_10200901_90_dialog_content = "PlayerName, o Colossus está cortando a conexão com o meu terminal!",
  ui_story_1020_10200901_91_dialog_content = "Soroz...",
  ui_story_1020_10200901_92_dialog_content = "Isso é obra sua?",
  ui_story_1020_10200901_93_dialog_content = "Eu ativei a Colossus para você.",
  ui_story_1020_10200901_94_dialog_content = "Não... Não!",
  ui_story_1020_10200901_95_dialog_content = "<color=#e8d9bb>Baque-</color>",
  ui_story_1020_10200901_96_dialog_content = "PlayerName!",
  ui_story_1020_10200901_97_dialog_content = "Ah! Ele saiu.",
  ui_story_1020_10200901_98_dialog_content = "Mantenha-se firme, Vivian. Está perigoso lá fora agora.",
  ui_story_1020_10200901_99_dialog_content = "Sim!",
  ui_story_1020_10200901_100_dialog_content = "O Celestita não vai a lugar nenhum! Eu sou o seu alvo...",
  ui_story_1020_10200901_101_dialog_content = "Pare com essa bobagem imediatamente, Ulysses!",
  ui_story_1020_10200901_102_dialog_content = "Me solta! Deixe-me lidar com ele!",
  ui_story_1020_10200901_103_dialog_content = "<color=#e8d9bb>Clique, clique—</color>",
  ui_story_1020_10200901_104_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10200901_105_dialog_content = "Pare, Ulysses!",
  ui_story_1020_10200901_106_dialog_content = "*Rugido*",
  ui_story_1020_10200901_107_dialog_content = "Depois de todos esses anos... Eu consegui...",
  ui_story_1020_10200901_108_dialog_content = "Esses são suficientes?",
  ui_story_1020_10200901_109_dialog_content = "Tem mais! Milhares a mais! Super-soldados mil vezes mais fortes que os Eclipsitas!",
  ui_story_1020_10200901_110_dialog_content = "<color=#e8d9bb>Zumbido—Buzz—</color>",
  ui_story_1020_10200901_111_dialog_content = "... Buu, buu...",
  ui_story_1020_10200901_112_dialog_content = "\"Uma última vez\"",
  ui_story_1020_10200901_113_dialog_content = "Ah não, ele vai comandar os super-soldados para atacar! Precisamos colocar Ulysses sob controle!",
  ui_story_1020_10200901_114_dialog_content = "Deixe Ulysses comigo!",
  ui_story_1020_10200901_115_dialog_content = "<color=#e8d9bb>Bipe—bipe—bipe—</color>",
  ui_story_1020_10200901_116_dialog_content = "Argh! Foi um tormento criar outro módulo de defesa também!",
  ui_story_1020_10200901_117_dialog_content = "*Rugido*",
  ui_story_1020_10201001_1_dialog_content = "PlayerName!",
  ui_story_1020_10201001_2_dialog_content = "Ainda temos um longo caminho a percorrer daqui até o pátio de serviço. É muito perigoso lá fora!",
  ui_story_1020_10201001_3_dialog_content = "... Não vou deixar Soroz escapar!",
  ui_story_1020_10201001_4_dialog_content = "Como Soroz pode sair sem a sua ordem?",
  ui_story_1020_10201001_5_dialog_content = "...",
  ui_story_1020_10201001_6_dialog_content = "Eu vi...",
  ui_story_1020_10201001_7_dialog_content = "O que foi?",
  ui_story_1020_10201001_8_dialog_content = "Eu vi o que Ulysses viu antes...",
  ui_story_1020_10201001_9_dialog_content = "Há uma voz... O Engenheiro está me dizendo e ao Soroz para irmos para casa...",
  ui_story_1020_10201001_10_dialog_content = "PlayerName...",
  ui_story_1020_10201001_11_dialog_content = "Não foi fácil para mim encontrar Soroz novamente, e só estivemos juntos por alguns dias...",
  ui_story_1020_10201001_12_dialog_content = "Eu juro... Eu juro que não vou deixar isso acontecer!",
  ui_story_1020_10201001_13_dialog_content = "Mas o que posso fazer? Tem que haver alguma coisa...",
  ui_story_1020_10201001_14_option_content = "Ligação Telepática",
  ui_story_1020_10201001_15_dialog_content = "...",
  ui_story_1020_10201001_16_option_content = "Ligação Telepática",
  ui_story_1020_10201001_17_dialog_content = "...",
  ui_story_1020_10201001_18_dialog_content = "Soroz... já se foi?",
  ui_story_1020_10201001_19_dialog_content = "No momento em que saí do laboratório mais cedo hoje, senti algo indescritível.",
  ui_story_1020_10201001_20_dialog_content = "Vi um feixe de luz acima de uma estrutura massiva, carregando todas as minhas esperanças com ele...",
  ui_story_1020_10201001_21_dialog_content = "E por algum motivo, eu senti que Soroz decolaria de lá...",
  ui_story_1020_10201001_22_dialog_content = "Eu... Eu não sabia por que me sentia assim naquela hora...",
  ui_story_1020_10201001_23_dialog_content = "Depois disso e dos sonhos que tive, eu deveria ter descoberto isso mais cedo...",
  ui_story_1020_10201001_24_option_content = "Ligação Telepática",
  ui_story_1020_10201001_25_dialog_content = "...",
  ui_story_1020_10201001_26_option_content = "Ligação Telepática",
  ui_story_1020_10201001_27_dialog_content = "...",
  ui_story_1020_10201001_28_option_content = "Ligação Telepática",
  ui_story_1020_10201001_29_dialog_content = "...",
  ui_story_1020_10201001_30_dialog_content = "Argh!",
  ui_story_1020_10201001_31_dialog_content = "Pare agora, PlayerName!",
  ui_story_1020_10201001_32_dialog_content = "Você usou demais seus poderes psíquicos hoje e está parecendo doente!",
  ui_story_1020_10201001_33_dialog_content = "Já perdi contato com Vice... Não sei o que farei se perder Soroz também...",
  ui_story_1020_10201001_34_dialog_content = "... Para onde Soroz está indo? O que o Engenheiro quer com isso?",
  ui_story_1020_10201001_35_dialog_content = "Você sempre pode me fazer essas perguntas—",
  ui_story_1020_10201001_36_dialog_content = "Desembainhar!",
  ui_story_1020_10201001_37_dialog_content = "Vivian!",
  ui_story_1020_10201001_38_dialog_content = "... Figerald?",
  ui_story_1020_10201001_39_dialog_content = "Muito fraco—não—muito delicado, eu diria...",
  ui_story_1020_10201001_40_dialog_content = "Tão terno que sinto pena de você!",
  ui_story_1020_10201001_41_dialog_content = "Heheh, não há nada como o sabor do desespero quando uma pessoa perde algo que realmente valoriza.",
  ui_story_1020_10201001_42_dialog_content = "... Você sabia que Soroz iria voar para longe?",
  ui_story_1020_10201001_43_dialog_content = "Bem, por que você não me pergunta o que eu fiz com Soroz?",
  ui_story_1020_10201001_44_dialog_content = "Você!",
  ui_story_1020_10201001_45_dialog_content = "Espere, PlayerName, tem algo errado com ele.",
  ui_story_1020_10201001_46_dialog_content = "Ele estava imobilizado em uma cela, mas ainda conseguiu escapar...",
  ui_story_1020_10201001_47_dialog_content = "Ainda não acredita? O poder dele torna tudo isso possível.",
  ui_story_1020_10201001_48_dialog_content = "Essas correntes realmente me prenderam. Mas eu ensinei aos escórias que me confinaram a apreciar a beleza do desespero em seu último momento.",
  ui_story_1020_10201001_49_dialog_content = "Infelizmente, o gosto do sofrimento deles nem se compara ao dos Celestitas.",
  ui_story_1020_10201001_50_dialog_content = "Hahaha, agora faça sua escolha, Celestita! Você vai morrer uma morte inútil como seus companheiros inúteis?",
  ui_story_1020_10201001_51_dialog_content = "Ou você se tornará meu presente para o supremo governante e testemunhará sua glória ao meu lado?",
  ui_story_1020_10201001_52_dialog_content = "Um Celestita nunca morreria uma morte sem sentido! Agora, onde está o Engenheiro?",
  ui_story_1020_10201001_53_dialog_content = "Hahaha! Então parece que você escolheu a última opção!",
  ui_story_1020_10201001_54_dialog_content = "Nesse caso, não há necessidade de poupar o tolo ao seu lado.",
  ui_story_1020_10201001_55_dialog_content = "Não se atreva a machucar PlayerName!",
  ui_story_1020_10201001_56_dialog_content = "Então você deseja experimentar o poder do meu Darkflow? Você deveria saber, ele nasceu do sangue dos Aurorianos caídos.",
  ui_story_1020_10201001_57_dialog_content = "Fique atrás de mim, PlayerName!",
  ui_story_1020_10201001_58_dialog_content = "Sua resistência é nada menos que ridícula...",
  ui_story_1020_10201001_59_dialog_content = "Agradeça por ainda conseguir sentir dor. Quando chegar o tempo glorioso dele, ele te libertará do seu sofrimento.",
  ui_story_1020_10201001_60_dialog_content = "Corvo - Eu te ofereço o sangue de um Celestita!",
  ui_story_1020_10201001_61_dialog_content = "Eu não vou deixar você machucar PlayerName, Eclipsita!",
  ui_story_1020_10201001_62_dialog_content = "Ainda bem que cheguei bem a tempo!",
  ui_story_1020_10201001_63_dialog_content = "PlayerName! Oficial Vivian! Algum de vocês se machucou?",
  ui_story_1020_10201001_64_dialog_content = "Sean? Saia daqui! Esse Darkflow é extremamente perigoso!",
  ui_story_1020_10201001_65_dialog_content = "Eu sei, mas eu tenho que te proteger, PlayerName!",
  ui_story_1020_10201001_66_dialog_content = "Bem? Eu não te decepcionei, não é?",
  ui_story_1020_10201001_67_dialog_content = "De jeito nenhum! Como você conseguiu resistir ao ataque dele, Sean?",
  ui_story_1020_10201001_68_dialog_content = "Ha! É porque eu sou tão bom lutador quanto Yingel ou Axelia!",
  ui_story_1020_10201001_69_dialog_content = "Acontece que eu também sou um auroriano de carne e osso.",
  ui_story_1020_10201001_70_dialog_content = "Chefe de Gabinete, PlayerName, deixe este Eclipsita comigo!",
  ui_story_1020_10201001_71_dialog_content = "Cuidado, Sean! Ele é muito astuto. Nós vamos te proteger eliminando os outros Eclipsitas atrás de você!",
  ui_story_1020_10201001_72_dialog_content = "Entendido!",
  ui_story_1020_10201001_73_dialog_content = "Ah... Tão macio! Tão fresco!",
  ui_story_1020_10201101_1_dialog_content = "Vermes... Vocês realmente acham que podem me parar?",
  ui_story_1020_10201101_2_dialog_content = "Devo completar minha missão desta vez, senão—",
  ui_story_1020_10201101_3_dialog_content = "Você aí, com as orelhas longas e peludas... Como conseguiu sobreviver ao meu ataque de Fluxo Escuro completamente ileso?",
  ui_story_1020_10201101_4_dialog_content = "E? Não vou deixar você machucar meus amigos!",
  ui_story_1020_10201101_5_dialog_content = "Heh, sua expressão explica tudo... É por isso que você ainda está vivo depois que o resto das bestas foram exterminadas.",
  ui_story_1020_10201101_6_dialog_content = "O que você tá dizendo?",
  ui_story_1020_10201101_7_dialog_content = "Eu, Figerald, tive a distinta honra de participar da exterminação em massa de seus ancestrais. Foi a minha contribuição mais gloriosa para o nosso supremo governante.",
  ui_story_1020_10201101_8_dialog_content = "No entanto, parece que ao fazer as pazes com os Aurorianos, sua espécie preguiçosa e traiçoeira encontrou uma maneira de sobreviver.",
  ui_story_1020_10201101_9_dialog_content = "De certa forma, você não é diferente das baratas. Não concorda?",
  ui_story_1020_10201101_10_dialog_content = "Cale a boca! Eu não vou deixar você falar sobre Sean dessa maneira!",
  ui_story_1020_10201101_11_dialog_content = "Ficando com raiva? Você quer me matar agora, não quer?",
  ui_story_1020_10201101_12_dialog_content = "Mas você ainda quer saber para onde Soroz foi, certo? Não apenas Soroz, mas também aquela garota Illumina sem valor.",
  ui_story_1020_10201101_13_dialog_content = "Não se preocupe, tenho certeza de que Anemone deu a ela uma morte esplendidamente horrível.",
  ui_story_1020_10201101_14_dialog_content = "Vice... Ela se deparou com Anemone? Me diga o que aconteceu com ela!",
  ui_story_1020_10201101_15_dialog_content = "Ah? Vamos ver se consigo me lembrar...",
  ui_story_1020_10201101_16_dialog_content = "Onde está o Engenheiro? Para onde Soroz foi? Me diga!",
  ui_story_1020_10201101_17_dialog_content = "...",
  ui_story_1020_10201101_18_dialog_content = "Ó poderoso e supremo mestre, por favor, não me abandone!",
  ui_story_1020_10201101_19_dialog_content = "...",
  ui_story_1020_10201101_20_dialog_content = "\"Mestre\"? Com quem ele está falando?",
  ui_story_1020_10201101_21_dialog_content = "O Engenheiro deve estar se comunicando com ele através de sua consciência agora mesmo...",
  ui_story_1020_10201101_22_dialog_content = "Este pode ser o momento perfeito para procurar pistas.",
  ui_story_1020_10201101_23_dialog_content = "O que está fazendo, PlayerName?",
  ui_story_1020_10201101_24_option_content = "Aumento de Força",
  ui_story_1020_10201101_25_dialog_content = "(Argh! Essa dor é insuportável...)",
  ui_story_1020_10201101_26_dialog_content = "(Mas não há outra maneira!)",
  ui_story_1020_10201101_27_dialog_content = "(Eu preciso saber o que aconteceu com Vice e Soroz...)",
  ui_story_1020_10201101_28_dialog_content = "(Eu preciso encontrar as respostas...)",
  ui_story_1020_10201101_29_dialog_content = "Seu corpo se tornou frágil e horrível.",
  ui_story_1020_10201101_30_dialog_content = "N-Não importa para mim! Contanto que eu carregue sua marca, esses humildes Aurorianos e Eclipsitas irão todos se curvar para mim.",
  ui_story_1020_10201101_31_dialog_content = "Me curvar para você? E eu então?",
  ui_story_1020_10201101_32_dialog_content = "E-Eu tremo diante de sua grandeza, meu senhor! Permita-me servir como suas asas, e eu dedicarei minha vida inteira a você!",
  ui_story_1020_10201101_33_dialog_content = "Você está disposto a usar este anel como reconhecimento do seu novo status?",
  ui_story_1020_10201101_34_dialog_content = "Um anel...",
  ui_story_1020_10201101_35_dialog_content = "Estou disposto! Este anel é um símbolo da sua graça, um presente que apenas as almas mais nobres podem receber! Ele dá significado à minha própria existência!",
  ui_story_1020_10201101_36_dialog_content = "Ajoelho-me diante de você em gratidão, supremo soberano!",
  ui_story_1020_10201101_37_dialog_content = "Muito bem.",
  ui_story_1020_10201101_38_dialog_content = "P-Por favor, conceda-me... Arrrrrrgh!",
  ui_story_1020_10201101_39_dialog_content = "Minha... Minha cabeça! A dor... Eu não aguento mais! Supremo governante... Por favor, me salve...",
  ui_story_1020_10201101_40_dialog_content = "(Esta é uma parte das memórias passadas de Figerald, e aquela voz agora era do Engenheiro...)",
  ui_story_1020_10201101_41_dialog_content = "(Um Wraith do Eclipse voluntariamente colocando aquele anel semelhante a uma algema...)",
  ui_story_1020_10201101_42_dialog_content = "(...)",
  ui_story_1020_10201101_43_dialog_content = "(Não sabia que podia usar meus poderes para ver tão longe no passado... Isso aconteceu por causa do sonho do Engenheiro?)",
  ui_story_1020_10201101_44_dialog_content = "(Ou será porque o Algol me treinou para me conectar com sucesso ao Bool?)",
  ui_story_1020_10201101_45_dialog_content = "(Se eu quiser saber sobre o paradeiro de Vice e Soroz, terei que acessar suas memórias mais recentes...)",
  ui_story_1020_10201101_46_option_content = "Alcance Telepático—",
  ui_story_1020_10201101_47_dialog_content = "(Urgh, esse Darkflow... É tão ruim quanto quando eu primeiro me conectei mentalmente com Bool.)",
  ui_story_1020_10201101_48_dialog_content = "(Mas agora que eu vivenciei algo assim, acho que posso lidar com isso...)",
  ui_story_1020_10201101_49_dialog_content = "(Hã? Isso é a Zona Escura?)",
  ui_story_1020_10201101_50_dialog_content = "(Este poço é enorme, e a fissura parece se estender ainda mais longe...)",
  ui_story_1020_10201101_51_dialog_content = "(Poderiam ser estas as ruínas da antiga guerra que o Engenheiro mencionou?)",
  ui_story_1020_10201101_52_dialog_content = "(Que diabos aconteceu aqui? Como este lugar acabou em um estado tão terrível?)",
  ui_story_1020_10201101_53_dialog_content = "(Não vejo nenhum sinal de um Colosso por perto...)",
  ui_story_1020_10201101_54_option_content = "Alcance Telepático—",
  ui_story_1020_10201101_55_dialog_content = "(É isso... um monte de restos de Colossus?)",
  ui_story_1020_10201101_56_dialog_content = "(Um, dois, três...)",
  ui_story_1020_10201101_57_dialog_content = "(...)",
  ui_story_1020_10201101_58_dialog_content = "(O local de ancoragem dos Colossi...)",
  ui_story_1020_10201101_59_dialog_content = "(Uma praia plana e estéril... É tão diferente do Obelisco do Retorno.)",
  ui_story_1020_10201101_60_dialog_content = "(O que aconteceu com eles? Não sobrou nada deles, exceto estruturas desgastadas como ossos de dragão...)",
  ui_story_1020_10201101_61_dialog_content = "(Quanto tempo atrás foi isso? Não consigo sentir nem os mais leves sinais de vida aqui...)",
  ui_story_1020_10201101_62_dialog_content = "(Isso mesmo, o núcleo do Guardião Um...)",
  ui_story_1020_10201101_63_dialog_content = "(Talvez as coordenadas que vi nos dados de Soroz sejam uma pista...)",
  ui_story_1020_10201101_64_dialog_content = "(Coordenadas... Pilares brilhantes...)",
  ui_story_1020_10201101_65_option_content = "Alcance Telepático—",
  ui_story_1020_10201101_66_dialog_content = "(É isso!)",
  ui_story_1020_10201101_67_dialog_content = "(Não há erro. Isso é exatamente o que eu vi nas memórias de Ulysses...)",
  ui_story_1020_10201101_68_dialog_content = "(Esses pilares brilhantes são o núcleo do Guardião Um. Eu posso vê-los claramente agora...)",
  ui_story_1020_10201101_69_dialog_content = "(A pedra está subindo. Deve haver algo lá em cima...)",
  ui_story_1020_10201101_70_dialog_content = "Você está preparado?",
  ui_story_1020_10201101_71_dialog_content = "Sim. O último <color=#FFB400>Anel de Condução</color> está em mãos.",
  ui_story_1020_10201101_72_dialog_content = "Muito bem.",
  ui_story_1020_10201101_73_dialog_content = "Li seu nome honrado e espero que você olhe para—",
  ui_story_1020_10201101_74_dialog_content = "Aguardamos humildemente a sua chegada—",
  ui_story_1020_10201101_75_dialog_content = "Quem é você?",
  ui_story_1020_10201101_76_dialog_content = "...",
  ui_story_1020_10201101_77_dialog_content = "Uma garota Illumina e um cientista.",
  ui_story_1020_10201101_78_dialog_content = "Illumina.",
  ui_story_1020_10201101_79_dialog_content = "Esse corvo inútil também está na Illumina.",
  ui_story_1020_10201101_80_dialog_content = "Illumina... Como sinto falta desse nome.",
  ui_story_1020_10201101_81_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10201101_82_dialog_content = "(Aquela cena agora há pouco... Não era um sonho afinal...)",
  ui_story_1020_10201101_83_dialog_content = "(Mas desta vez, Forsakin está aqui no lugar de Vice...)",
  ui_story_1020_10201101_84_dialog_content = "(Os que estão ao lado dela... São esses Wraiths?)",
  ui_story_1020_10201101_85_dialog_content = "E-é você... O governante supremo!",
  ui_story_1020_10201101_86_dialog_content = "Seu fiel servo, Figerald, esteve de joelhos todo esse tempo, aguardando sua chegada.",
  ui_story_1020_10201101_87_dialog_content = "Você não realizou nada.",
  ui_story_1020_10201101_88_dialog_content = "Eu servi bem a você, mestre! Fui eu quem liderou a exterminação dos bestiais—",
  ui_story_1020_10201101_89_dialog_content = "Uma questão de séculos agora.",
  ui_story_1020_10201101_90_dialog_content = "No momento em que eu precisar, vou pegar de volta tudo o que te dei.",
  ui_story_1020_10201101_91_dialog_content = "Meu senhor... Você nunca faria uma coisa dessas, não é? Eu sirvo como suas asas, criadas por suas próprias mãos!",
  ui_story_1020_10201101_92_dialog_content = "Vou te libertar de suas restrições.",
  ui_story_1020_10201101_93_dialog_content = "Prove seu valor para o Eclipse trazendo-me o Celestita.",
  ui_story_1020_10201101_94_dialog_content = "Ainda tenho energia suficiente para ativar a Colossus.",
  ui_story_1020_10201101_95_dialog_content = "<color=#e8d9bb>Clam—</color>",
  ui_story_1020_10201101_96_dialog_content = "...",
  ui_story_1020_10201101_97_dialog_content = "E-eu tremo diante de você! Eu nunca ousaria ir contra seus desejos!",
  ui_story_1020_10201101_98_dialog_content = "(...)",
  ui_story_1020_10201101_99_dialog_content = "(O Engenheiro veio à Cidade Gannon para chamar de volta os Wraiths...)",
  ui_story_1020_10201101_100_dialog_content = "(E ele quer me levar e Soroz com ele...)",
  ui_story_1020_10201101_101_dialog_content = "Você gosta disso?",
  ui_story_1020_10201101_102_dialog_content = "Você... está me observando?",
  ui_story_1020_10201101_103_dialog_content = "Sempre.",
  ui_story_1020_10201101_104_dialog_content = "Eu concedi a você as visões. Você deveria me agradecer por mostrar o espetacular no Campo de Batalha da Torre.",
  ui_story_1020_10201101_105_dialog_content = "O Campo de Batalha da Torre... Então isso realmente aconteceu?",
  ui_story_1020_10201101_106_dialog_content = "Apenas a verdade tem valor.",
  ui_story_1020_10201101_107_dialog_content = "Aquela fenda já foi meu lar, mas a guerra me despedaçou.",
  ui_story_1020_10201101_108_dialog_content = "Procurei pelos fragmentos para reconstruir minha base, e então reiniciei meu coração.",
  ui_story_1020_10201101_109_dialog_content = "Esses Colossos esgotaram seus núcleos por minha causa.",
  ui_story_1020_10201101_110_dialog_content = "... Soroz vai se tornar seu próximo sacrifício também? Você está tentando destruir o mundo?",
  ui_story_1020_10201101_111_dialog_content = "Não, eu não.",
  ui_story_1020_10201101_112_dialog_content = "Você vai entender. Você e eu somos iguais.",
  ui_story_1020_10201101_113_dialog_content = "...",
  ui_story_1020_10201101_114_dialog_content = "... Onde está Soroz?",
  ui_story_1020_10201101_115_dialog_content = "... E o que aconteceu com Vice?",
  ui_story_1020_10201101_116_dialog_content = "...",
  ui_story_1020_10201101_117_dialog_content = "(... Está ficando cada vez mais escuro...)",
  ui_story_1020_10201101_118_dialog_content = "Lembre-se, a luz vai te cegar. Você só pode ver a verdade na escuridão.",
  ui_story_1020_10201101_119_dialog_content = "Aceite a escuridão, deixe-a entrar e permita que ela seja a sua força.",
  ui_story_1020_10201101_120_dialog_content = "Eu recuso!",
  ui_story_1020_10201101_121_dialog_content = "Permita que a escuridão seja a sua força.",
  ui_story_1020_10201101_122_dialog_content = "Eu não vou usar suas algemas!",
  ui_story_1020_10201101_123_dialog_content = "(Nesse ritmo, a escuridão realmente vai me consumir...)",
  ui_story_1020_10201102_1_dialog_content = "<color=#e8d9bb>Resumo—</color>",
  ui_story_1020_10201102_2_dialog_content = "(Ouço um piano na escuridão...)",
  ui_story_1020_10201102_3_dialog_content = "(Esse lugar... É tão brilhante...)",
  ui_story_1020_10201102_4_dialog_content = "(Essas ondas de luz fluindo parecem estar refletindo na superfície de um lago...)",
  ui_story_1020_10201102_5_dialog_content = "(Isto é... a aurora sobre Northland?)",
  ui_story_1020_10201102_6_dialog_content = "(Hã? O que é isso...)",
  ui_story_1020_10201102_7_dialog_content = "PlayerName.",
  ui_story_1020_10201102_8_dialog_content = "Soroz? É realmente você? Soroz!",
  ui_story_1020_10201102_9_dialog_content = "Ouvi um piano há um segundo atrás e então a sua voz, PlayerName.",
  ui_story_1020_10201102_10_dialog_content = "Um piano? Eu também ouvi! Não esperava te alcançar assim!",
  ui_story_1020_10201102_11_dialog_content = "Onde você está agora, Soroz?",
  ui_story_1020_10201102_12_dialog_content = "...",
  ui_story_1020_10201102_13_dialog_content = "Eu não sei.",
  ui_story_1020_10201102_14_dialog_content = "...",
  ui_story_1020_10201102_15_dialog_content = "Ele te deu a ordem, não deu?",
  ui_story_1020_10201102_16_dialog_content = "...",
  ui_story_1020_10201102_17_dialog_content = "Você pode simplesmente ignorar... não pode Soroz?",
  ui_story_1020_10201102_18_dialog_content = "...",
  ui_story_1020_10201102_19_dialog_content = "Sinto muito, PlayerName.",
  ui_story_1020_10201102_20_dialog_content = "Celestitas sonharam com a liberdade durante toda a vida...",
  ui_story_1020_10201102_21_dialog_content = "Os dados fugazes me ofereceram um vislumbre dos Celestitas e Colossos antes de eu te conhecer...",
  ui_story_1020_10201102_22_dialog_content = "Eu vi inúmeras gerações de Celestitas e Colossos lutando para se libertar das correntes.",
  ui_story_1020_10201102_23_dialog_content = "Desta vez...",
  ui_story_1020_10201102_24_dialog_content = "Acho que eu falhei.",
  ui_story_1020_10201102_25_dialog_content = "Soroz... Por favor, não vá...",
  ui_story_1020_10201102_26_dialog_content = "Podemos nos libertar dessas algemas juntos, não podemos?",
  ui_story_1020_10201102_27_dialog_content = "...",
  ui_story_1020_10201102_28_dialog_content = "Neste momento, eu sou tanto Soroz quanto Naviduz...",
  ui_story_1020_10201102_29_dialog_content = "Assim como Solituz, Probarduz, Vocoduz, Spanduz...",
  ui_story_1020_10201102_30_dialog_content = "O que eu posso fazer é proteger meu Navegador da melhor maneira possível, como meus antecessores já fizeram.",
  ui_story_1020_10201102_31_dialog_content = "No meu tempo com você, cada voo que fizemos foi o melhor momento da minha vida.",
  ui_story_1020_10201102_32_dialog_content = "Se eu conseguir quebrar as algemas, nos encontraremos novamente.",
  ui_story_1020_10201102_33_dialog_content = "Soroz...",
  ui_story_1020_10201102_34_dialog_content = "Independentemente de quantos sinais eu receba...",
  ui_story_1020_10201102_35_dialog_content = "Enquanto eu ainda tiver um \"coração\", ele só ouvirá sua voz, PlayerName.",
  ui_story_1020_10201102_36_dialog_content = "...",
  ui_story_1020_10201102_37_dialog_content = "Soroz...",
  ui_story_1020_10201102_38_dialog_content = "Soroz?",
  ui_story_1020_10201102_39_dialog_content = "PlayerName...",
  ui_story_1020_10201102_40_option_content = "Ligação Telepática",
  ui_story_1020_10201102_41_dialog_content = "...",
  ui_story_1020_10201102_42_option_content = "Ligação Telepática—",
  ui_story_1020_10201102_43_dialog_content = "...",
  ui_story_1020_10201102_44_option_content = "Ligação Telepática!",
  ui_story_1020_10201102_45_dialog_content = "...",
  ui_story_1020_10201102_46_option_content = "Ligação Telepática!",
  ui_story_1020_10201102_47_dialog_content = "PlayerName!",
  ui_story_1020_10201102_48_dialog_content = "...",
  ui_story_1020_10201102_49_dialog_content = "Não consigo...",
  ui_story_1020_10201102_50_dialog_content = "Não consigo mais sentir Soroz!",
  ui_story_1020_10201102_51_dialog_content = "Você finalmente acordou, PlayerName. Você está bem?",
  ui_story_1020_10201102_52_dialog_content = "Dói em mim te ver assim, PlayerName.",
  ui_story_1020_10201102_53_dialog_content = "Foi assustador o jeito que você estava murmurando para si mesmo. Felizmente, Sean dominou Figerald para você recuperar seus sentidos!",
  ui_story_1020_10201102_54_dialog_content = "Na verdade, todos ajudaram nisso!",
  ui_story_1020_10201102_55_dialog_content = "...?",
  ui_story_1020_10201102_56_dialog_content = "Vimos ele desaparecer em uma nuvem de Darkflow com nossos próprios olhos.",
  ui_story_1020_10201102_57_dialog_content = "Apenas Sean poderia resistir a esse tipo de Darkflow.",
  ui_story_1020_10201102_58_dialog_content = "(Todo mundo... realmente conseguiu vencer Figerald?)",
  ui_story_1020_10201102_59_dialog_content = "(Justo quando eu estava prestes a cair na escuridão infinita, ouvi um piano e vi a superfície brilhante de um lago... O que foi isso?)",
  ui_story_1020_10201102_60_dialog_content = "O que aconteceu, PlayerName? Você usou o Forced Boost em Figerald e fez barulhos estranhos...",
  ui_story_1020_10201102_61_dialog_content = "Eu consegui sentir Soroz...",
  ui_story_1020_10201102_62_dialog_content = "Soroz? Onde está?",
  ui_story_1020_10201102_63_dialog_content = "Soroz saiu para me proteger...",
  ui_story_1020_10201102_64_dialog_content = "...",
  ui_story_1020_10201102_65_dialog_content = "Podemos ir para Soroz mais tarde, PlayerName? Temos que nos encontrar com o Grande Marechal.",
  ui_story_1020_10201102_66_dialog_content = "É muito perigoso para você estar aqui sozinho. Se essas três crianças não chegassem a tempo, Figerald teria nos capturado.",
  ui_story_1020_10201102_67_dialog_content = "Obrigada, pessoal...",
  ui_story_1020_10201102_68_dialog_content = "Vamos lá. Quando essa crise acabar, com certeza vamos recuperar Soroz!",
  ui_story_1020_10201102_69_dialog_content = "Sim...",
  ui_story_1020_10201102_70_dialog_content = "(Eu vi o Engenheiro através da mente de Figerald...)",
  ui_story_1020_10201102_71_dialog_content = "(Eu preciso encontrar pistas...)",
  ui_story_1020_10201102_72_dialog_content = "Isso foi muito perto, PlayerName. Se aqueles três garotos não tivessem aparecido a tempo, provavelmente—",
  ui_story_1020_10201102_73_dialog_content = "Eu sei...!",
  ui_story_1020_10201102_74_dialog_content = "Vá se encontrar com o Grande Marechal agora, PlayerName!",
  ui_story_1020_10201201_1_dialog_content = "Uuuh!",
  ui_story_1020_10201201_2_dialog_content = "Então Bool está dizendo que... Acho que o módulo de defesa deve funcionar desta vez?",
  ui_story_1020_10201201_3_dialog_content = "Talvez. Haha... Hahahahaha!",
  ui_story_1020_10201201_4_dialog_content = "Ufa, ainda estou dolorido dos ombros até as pontas dos dedos, mas está feito—",
  ui_story_1020_10201201_5_dialog_content = "Graças à ajuda de todos, consegui terminar muito mais rápido do que o previsto... Ainda assim, eu não esperava que uma batalha de pura inteligência fosse tão difícil...",
  ui_story_1020_10201201_6_dialog_content = "Nada é fácil quando se trata desta máquina antiga!",
  ui_story_1020_10201201_7_dialog_content = "<color=#e8d9bb>Bipe—bipe—bipe—</color>",
  ui_story_1020_10201201_8_dialog_content = "Huh? O novo programa ainda está relatando erros...",
  ui_story_1020_10201201_9_dialog_content = "O Engenheiro ainda está trabalhando contra nós de alguma forma? Ou poderia ser que o módulo do Guardião já tinha problemas desde o início?",
  ui_story_1020_10201201_10_dialog_content = "<size=45>Buá, buá, buá!</size>",
  ui_story_1020_10201201_11_dialog_content = "Vamos ver... Vamos ver...",
  ui_story_1020_10201201_12_dialog_content = "Hã? Onde está o Ulysses? Eu preciso obter mais respostas dele! Quem sabe o que ele fez com essa máquina ao longo dos anos...",
  ui_story_1020_10201201_13_dialog_content = "Ainda preciso de um núcleo capaz de lidar com cálculos ainda mais complexos?",
  ui_story_1020_10201201_14_dialog_content = "Boo?",
  ui_story_1020_10201201_15_dialog_content = "Isso pareceu ser demais para Ulysses absorver. Seus olhos estavam fechados e ele nunca se moveu.",
  ui_story_1020_10201201_16_dialog_content = "Reinhardt, vendo que a máquina está estável, e os super-soldados não estão mais agressivos...",
  ui_story_1020_10201201_17_dialog_content = "Devemos aproveitar a oportunidade para reunir os super-soldados restantes para prevenir ataques futuros.",
  ui_story_1020_10201201_18_dialog_content = "Concordo. E eles são nossos soldados de qualquer maneira... Talvez o Black Umbrella Laboratories encontre uma maneira de tratá-los.",
  ui_story_1020_10201201_19_dialog_content = "... Na sua origem, parece que todos eles estão sendo controlados pelo protótipo. Receio que não temos escolha senão esperar que o Dr. Algol termine de construir um novo módulo.",
  ui_story_1020_10201201_20_dialog_content = "O que você precisa que façamos agora, Dr. Algol?",
  ui_story_1020_10201201_21_dialog_content = "Lidar com esses super-soldados não será fácil.",
  ui_story_1020_10201201_22_dialog_content = "Esses cabos provavelmente vão ainda mais fundo do que podemos imaginar. Levaria semanas para nós cavarmos todos eles.",
  ui_story_1020_10201201_23_dialog_content = "Sem mencionar que existem outros riscos envolvidos... Parece que recuperar o módulo do Guardião e usá-lo para reparar o núcleo não será suficiente...",
  ui_story_1020_10201201_24_dialog_content = "Para reparar todas as falhas de segurança de Gannon City, vou precisar construir um sistema defensivo completamente novo, um que seja totalmente independente do Engenheiro e do Guardião!",
  ui_story_1020_10201201_25_dialog_content = "Você quer dizer não depender de nenhuma outra tecnologia e construir um sistema de defesa que seja exclusivamente de Illumina com nossa própria tecnologia?",
  ui_story_1020_10201201_26_dialog_content = "Correto. Infelizmente, o núcleo atual não possui poder de processamento suficiente, o que torna a construção de um sistema totalmente novo enquanto se defende contra possíveis ataques ainda mais desafiadora.",
  ui_story_1020_10201201_27_dialog_content = "Se eu tivesse mais núcleos para ajudar a processar mais dados, não seria tanto problema...",
  ui_story_1020_10201201_28_dialog_content = "Seria útil se usássemos outros computadores em Gannon City, Dr. Algol?",
  ui_story_1020_10201201_29_dialog_content = "Não temos tantos em espera no momento, então receio que não faria diferença.",
  ui_story_1020_10201201_30_dialog_content = "Não estou falando sobre os que estão em standby. Estou falando sobre todos os computadores na cidade de Gannon!",
  ui_story_1020_10201201_31_dialog_content = "Cada um deles? Bem, com tanto poder de processamento à minha disposição... Tenho certeza de que ajudaria muito.",
  ui_story_1020_10201201_32_dialog_content = "Mas ao fazer isso, todos os outros processos de engenharia serão temporariamente interrompidos, incluindo nossos portões e sistemas de suporte à vida...",
  ui_story_1020_10201201_33_dialog_content = "Uma cidade tão grande quanto Gannon poderia durar sem esses sistemas vitais por um minuto sequer?",
  ui_story_1020_10201201_34_dialog_content = "...",
  ui_story_1020_10201201_35_dialog_content = "Não apenas isso, o novo sistema de defesa precisará ser testado. Se não conseguir lidar com os mesmos processos complexos que o núcleo que está substituindo, então ele só vai entrar em colapso novamente.",
  ui_story_1020_10201201_36_dialog_content = "Agora, tudo que posso fazer é tentar antecipar as ações do Engenheiro e vencê-lo em seu próprio jogo.",
  ui_story_1020_10201201_37_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10201201_38_dialog_content = "Isso não vai funcionar.",
  ui_story_1020_10201201_39_dialog_content = "Uuuh!",
  ui_story_1020_10201201_40_dialog_content = "Você também faz parte do protótipo.",
  ui_story_1020_10201201_41_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10201201_42_dialog_content = "Bool veio com alguma coisa?",
  ui_story_1020_10201201_43_dialog_content = "Bool quer servir como o núcleo para o novo sistema de defesa da Cidade de Gannon.",
  ui_story_1020_10201201_44_dialog_content = "Bool? Como ele pode fazer isso?",
  ui_story_1020_10201201_45_dialog_content = "Exatamente. Como meu assistente e parte do protótipo, não fez nada além de dificultar as coisas para mim.",
  ui_story_1020_10201201_46_dialog_content = "Uuuh!",
  ui_story_1020_10201201_47_dialog_content = "Bool obviamente tem sido uma grande ajuda para o Dr. Algol!",
  ui_story_1020_10201201_48_dialog_content = "Buá!",
  ui_story_1020_10201201_49_dialog_content = "Bip—",
  ui_story_1020_10201201_50_dialog_content = "Algol, por favor, abra o <color=#FFB400>compartimento de manutenção</color> do Guardian One.",
  ui_story_1020_10201201_51_dialog_content = "Use o <color=#FFB400>núcleo</color> do Guardião Um para proteger a cidade de Gannon.",
  ui_story_1020_10201201_52_dialog_content = "Hã?",
  ui_story_1020_10201201_53_dialog_content = "O Guardian One quer abandonar sua inteligência e se tornar uma máquina que lida com ataques de dados.",
  ui_story_1020_10201201_54_dialog_content = "Eu não te dei inteligência artificial apenas para você jogá-la fora e se tornar outra parte sem mente das defesas da Cidade de Gannon, Guardian One.",
  ui_story_1020_10201201_55_dialog_content = "O Guardião Um sabe disso. Algol quer que o Guardião Um seja capaz de processar conversas complicadas entre Aurorianos e se torne amigo de Algol.",
  ui_story_1020_10201201_56_dialog_content = "Mas Algol precisa do Guardian One. Por favor, use o núcleo do Guardian One para proteger a cidade de Gannon.",
  ui_story_1020_10201201_57_dialog_content = "Não.",
  ui_story_1020_10201201_58_dialog_content = "Algol, por favor, use o núcleo do Guardião Um para proteger a Cidade Gannon.",
  ui_story_1020_10201201_59_dialog_content = "Não!",
  ui_story_1020_10201201_60_dialog_content = "Beep! Algol, por favor, use o núcleo do Guardião Um para proteger Gannon City.",
  ui_story_1020_10201201_61_dialog_content = "Eu disse não, então dê um tempo!",
  ui_story_1020_10201201_62_dialog_content = "Eu disse não, então dê um tempo!",
  ui_story_1020_10201201_63_dialog_content = "...",
  ui_story_1020_10201201_64_dialog_content = "Você... Quando aprendeu a imitar os outros assim...",
  ui_story_1020_10201201_65_dialog_content = "Guardian One pensou sobre isso por um longo tempo antes de entender. \"Bip, bip, bip, bip, bip.\" Algol na verdade não disse nada naquele momento.",
  ui_story_1020_10201201_66_dialog_content = "...",
  ui_story_1020_10201201_67_dialog_content = "Você só está dificultando as coisas para mim. Você sabe disso?",
  ui_story_1020_10201201_68_dialog_content = "O Guardião Um sabe disso, mas este é o pedido do Guardião Um. Algol, por favor, use o núcleo do Guardião Um para proteger a cidade de Gannon.",
  ui_story_1020_10201201_69_dialog_content = "Você sabe o que terá que enfrentar para proteger a cidade de Gannon?",
  ui_story_1020_10201201_70_dialog_content = "Este lugar não é apenas cheio de fios e cabos. Há também muitos dados maliciosos que podem invadir sua mente.",
  ui_story_1020_10201201_71_dialog_content = "Esse mesmo dado malicioso pode limitar seu raciocínio e até forçá-lo a atacar a Illumina, assim como um Eclipsite!",
  ui_story_1020_10201201_72_dialog_content = "Isso não é apenas uma simples migração de dados. Você estaria abandonando sua capacidade de criar e se adaptar, e se tornaria outra ferramenta para os outros explorarem!",
  ui_story_1020_10201201_73_dialog_content = "O Guardian One não começará a imaginar coisas, porque Algol disse ao Guardian One que pensar é a especialidade dos Aurorianos.",
  ui_story_1020_10201201_74_dialog_content = "Com um mentor sábio como Algol, o Guardian One pode abandonar a capacidade de pensar e focar apenas em proteger a Cidade Gannon.",
  ui_story_1020_10201201_75_dialog_content = "Você nem está disposto a fazer uma xícara de café para mim! O que te faz pensar...",
  ui_story_1020_10201201_76_dialog_content = "Guardian One sabe que Algol não quer que Guardian One seja apenas um robô mordomo, mas um companheiro com quem ela possa se divertir.",
  ui_story_1020_10201201_77_dialog_content = "O Guardião Um tem apenas uma condição. Se o Guardião Um for morar aqui, por favor organize este lugar como o escritório de Algol e coloque mais plantas verdes aqui.",
  ui_story_1020_10201201_78_dialog_content = "Quando o Guardião Dois e o Guardião Três forem criados, por favor, projete-os com uma carcaça que seja mais fácil de mover, diferente do que o Guardião Um possui...",
  ui_story_1020_10201201_79_dialog_content = "Algol sempre diz que o Guardian One parece uma caixa de correio e sempre tem o impulso de colocar cartas na boca do Guardian One.",
  ui_story_1020_10201201_80_dialog_content = "...",
  ui_story_1020_10201201_81_dialog_content = "Ah, tem mais uma coisa para contar ao Algol...",
  ui_story_1020_10201201_82_dialog_content = "O Guardião Um fez uma coisa que Algol não sabia quando o Guardião Um estava se comunicando telepaticamente com PlayerName.",
  ui_story_1020_10201201_83_dialog_content = "?",
  ui_story_1020_10201201_84_dialog_content = "Essa comunicação fez o Guardião Um acreditar que pode confiar toda a sua consciência a PlayerName.",
  ui_story_1020_10201201_85_dialog_content = "Se Algol precisa de um amigo, o Guardião Um recomenda que Algol se torne amigo de PlayerName.",
  ui_story_1020_10201201_86_dialog_content = "...",
  ui_story_1020_10201201_87_dialog_content = "Adeus, Algol.",
  ui_story_1020_10201201_88_dialog_content = "Guardian One gosta da nova expressão Algol projetada para ele.",
  ui_story_1020_10201201_89_dialog_content = "Bip—bip—bip—",
  ui_story_1020_10201201_90_dialog_content = "<color=#e8d9bb>Clam—</color>",
  ui_story_1020_10201201_91_dialog_content = "Bu...",
  ui_story_1020_10201201_92_dialog_content = "Bip, bip, bip, bip, bip.",
  ui_story_1020_10201201_93_dialog_content = "...",
  ui_story_1020_10201201_94_dialog_content = "Não temos nenhuma outra opção, Grande Marechal?",
  ui_story_1020_10201201_95_dialog_content = "...",
  ui_story_1020_10201201_96_dialog_content = "Esta pode ser a nossa única opção agora. Quando o Engenheiro apareceu pela primeira vez, eu já havia considerado isso.",
  ui_story_1020_10201201_97_dialog_content = "Desculpe, Dr. Algol. Eu sei que o Guardião Um era seu bom amigo.",
  ui_story_1020_10201201_98_dialog_content = "Meu único amigo, na verdade.",
  ui_story_1020_10201201_99_dialog_content = "Mas que tipo de amigo faria algo assim? Haha...",
  ui_story_1020_10201201_100_dialog_content = "Uma caixa de correio falante e presunçosa...",
  ui_story_1020_10201201_101_dialog_content = "Era isso mesmo!",
  ui_story_1020_10201201_102_dialog_content = "Mas agora que temos um novo núcleo, a sua sugestão ainda está em aberto? A de desligar os processos essenciais de Gannon City por um minuto?",
  ui_story_1020_10201201_103_dialog_content = "?",
  ui_story_1020_10201201_104_dialog_content = "Se for o caso, podemos redirecionar toda a capacidade de processamento da Cidade de Gannon e ajudar você a substituir o núcleo.",
  ui_story_1020_10201201_105_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10201201_106_dialog_content = "Não consigo fazer isso, não em menos de um minuto.",
  ui_story_1020_10201201_107_dialog_content = "Então, te daremos dez minutos! Vamos providenciar todos os computadores e mão de obra que você precisa. Você conseguirá fazer isso então?",
  ui_story_1020_10201201_108_dialog_content = "Sério?",
  ui_story_1020_10201201_109_dialog_content = "Morto de sério.",
  ui_story_1020_10201201_110_dialog_content = "As pessoas de Illumina não sobreviveram através da bioengenharia dos Aurorians, Dr. Algol.",
  ui_story_1020_10201201_111_dialog_content = "Nem dependendo desta máquina antiga.",
  ui_story_1020_10201201_112_dialog_content = "Isso mesmo. Mesmo que Ulysses pense que temos confiado no Guardião pelos últimos seiscentos anos...",
  ui_story_1020_10201201_113_dialog_content = "Acredito que foram os soldados da Federação Illumina que mantiveram nossas muralhas de pé.",
  ui_story_1020_10201201_114_dialog_content = "Se não conseguirmos protegê-la nem por dez minutos, então a Illumina nunca mais encontrará seu lugar em Astra! É um risco que precisamos correr!",
  ui_story_1020_10201201_115_dialog_content = "Até colocarei minha própria vida em suas mãos, se necessário. Isso porque estou disposto a ser o tipo de amigo que acredita em você.",
  ui_story_1020_10201201_116_dialog_content = "...",
  ui_story_1020_10201201_117_dialog_content = "Concordo.",
  ui_story_1020_10201201_118_dialog_content = "E eu!",
  ui_story_1020_10201201_119_dialog_content = "... Então vocês todos acreditam que acreditar no poder da amizade nos ajudará a alcançar o impossível?",
  ui_story_1020_10201201_120_dialog_content = "Haha, a última vez que ouvi algo tão ridículo foi na escola primária.",
  ui_story_1020_10201201_121_dialog_content = "Ainda assim, estou disposto a tentar.",
  ui_story_1020_10201201_122_dialog_content = "Teehee, adoro jogar jogos com meus amigos!",
  ui_story_1020_10201201_123_dialog_content = "Então vamos começar! Hiiro, conecte-se ao sistema de transmissão de emergência da cidade! É hora de eu dar a ordem!",
  ui_story_1020_10201201_124_dialog_content = "Entendido!",
  ui_story_1020_10201201_125_dialog_content = "<color=#e8d9bb>Bip Bip-</color>",
  ui_story_1020_10201201_126_dialog_content = "Grande Marechal.",
  ui_story_1020_10201201_127_dialog_content = "Ok, eu pensei que nunca iria usar essa frequência.",
  ui_story_1020_10201201_128_dialog_content = "Este é um anúncio de emergência. Nos próximos dez minutos, estaremos redirecionando toda a capacidade de processamento da cidade para lidar com uma crise urgente.",
  ui_story_1020_10201201_129_dialog_content = "Durante este tempo, caberá a cada um de nós defender a Cidade Gannon.",
  ui_story_1020_10201201_130_dialog_content = "Ao seu comando, Grande Marechal!",
  ui_story_1020_10201201_131_dialog_content = "Zonas de isolamento, andares de guarnição e andares de amortecimento serão diretamente expostos aos ataques dos Eclipsitas. Barton, você assumirá o comando dessas áreas.",
  ui_story_1020_10201201_132_dialog_content = "Entendido!",
  ui_story_1020_10201201_133_dialog_content = "Sharona, volte para a cidade de Gannon e ataque os Eclipsitas da superfície. A equipe de engenharia já deve ter terminado as evacuações civis até agora.",
  ui_story_1020_10201201_134_dialog_content = "Entendi.",
  ui_story_1020_10201201_135_dialog_content = "Hiiro, estou colocando você no comando dos setores de agricultura, mineração, manufatura e armazenamento.",
  ui_story_1020_10201201_136_dialog_content = "Um pequeno número de trabalhadores militares e não militares estão mantendo as operações mecânicas lá embaixo. Por favor, forneça reforços para os setores superior e inferior conforme necessário.",
  ui_story_1020_10201201_137_dialog_content = "Certo!",
  ui_story_1020_10201201_138_dialog_content = "E quanto a mim?",
  ui_story_1020_10201201_139_dialog_content = "O setor de pesquisa ainda está infestado de Eclipsitas. Wrath, você e sua equipe devem localizar todos os armazéns que contêm Eclipsitas e impedir que eles alcancem os níveis superiores a todo custo.",
  ui_story_1020_10201201_140_dialog_content = "Sim!",
  ui_story_1020_10201201_141_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10201201_142_dialog_content = "Contorne o Sistema de Guardião para construir uma nova jaula para você continuar se escondendo nesta subcidade...",
  ui_story_1020_10201201_143_dialog_content = "Todos vocês estão muito acostumados a viver no escuro...",
  ui_story_1020_10201201_144_dialog_content = "O que há de errado com o corpo de Ulysses?",
  ui_story_1020_10201201_145_dialog_content = "Foi minha negligência. Eu estava muito focado em lutar contra os super-soldados para notar que ele mesmo estava subindo na mesa de operação.",
  ui_story_1020_10201201_146_dialog_content = "Ele se transformou em tão pouco tempo?",
  ui_story_1020_10201201_147_dialog_content = "... Tenho medo que as modificações dele estejam em andamento há muito tempo. Eles não começaram apenas recentemente.",
  ui_story_1020_10201201_148_dialog_content = "A defesa não resolverá nada. Apenas a resistência ativa o fará... Um núcleo já não é mais necessário com este corpo!",
  ui_story_1020_10201201_149_dialog_content = "Continue causando problemas, e eu vou cortar sua cabeça, Ulysses!",
  ui_story_1020_10201201_150_dialog_content = "Espere! Todos, recuem!",
  ui_story_1020_10201201_151_dialog_content = "Eu disse que nunca tive medo da Zona Cega...",
  ui_story_1020_10201201_152_dialog_content = "Mesmo que todos falhem...",
  ui_story_1020_10201201_153_dialog_content = "Vou fazer isso sozinho!",
  ui_story_1020_10201201_154_dialog_content = "<color=#e8d9bb>Bipe—bipe—bipe—</color>",
  ui_story_1020_10201201_155_dialog_content = "... Sobrecarga de dados? Isso poderia ser obra de Ulysses?",
  ui_story_1020_10201201_156_dialog_content = "...",
  ui_story_1020_10201201_157_dialog_content = "Continuar a missão? Grande Marechal?",
  ui_story_1020_10201201_158_dialog_content = "No meu comando, Bool!",
  ui_story_1020_10201201_159_dialog_content = "Uuuuuu!",
  ui_story_1020_10201201_160_dialog_content = "Mantenham-se no plano original, pessoal! Precisamos proteger a Dra. Algol enquanto ela substitui o núcleo! Deixem este lugar comigo!",
  ui_story_1020_10201201_161_dialog_content = "Sim!",
  ui_story_1020_10201201_162_dialog_content = "Entendido!",
  ui_story_1020_10201201_163_dialog_content = "Alto e claro, Grande Marechal!",
  ui_story_1020_10201201_164_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_1020_10201201_165_dialog_content = "Cuidado, o armazém do super-soldado está abrindo novamente!",
  ui_story_1020_10201201_166_dialog_content = "Eles estão seguindo Ulysses?",
  ui_story_1020_10201201_167_dialog_content = "Um núcleo já não é mais necessário com este corpo!",
  ui_story_1020_10201201_168_dialog_content = "Idiota! Você acha que esse corpo te torna invencível?",
  ui_story_1020_10201201_169_dialog_content = "Depois de todas essas modificações, o Engenheiro poderia assumir o controle total sobre você com um único cabo!",
  ui_story_1020_10201201_170_dialog_content = "E o depósito está cheio de cabos...",
  ui_story_1020_10201201_171_dialog_content = "Reinhardt! Diga para o resto dessas pessoas saírem daqui! Caso contrário, os cabos podem assumir o controle delas!",
  ui_story_1020_10201201_172_dialog_content = "Eu só preciso de você aqui para me ajudar a proteger o novo sistema de defesa!",
  ui_story_1020_10201201_173_dialog_content = "Faça o que Algol diz, pessoal!",
  ui_story_1020_10201201_174_dialog_content = "Que tipo de idiota você acha que eu sou? Como eu poderia deixar vocês dois lutarem contra todos esses super-soldados?",
  ui_story_1020_10201201_175_dialog_content = "Vou fornecer suporte, Grande Marechal!",
  ui_story_1020_10201201_176_dialog_content = "Eu também!",
  ui_story_1020_10201201_177_dialog_content = "Então deixaremos os super-soldados por sua conta! Não perca Ulysses de vista também!",
  ui_story_1020_10201201_178_dialog_content = "Bool, encontre a interface e interrompa a conexão entre o protótipo e esses super-soldados! Depois disso, substitua o núcleo!",
  ui_story_1020_10201201_179_dialog_content = "Uuuuuu!",
  ui_story_1020_10201301_1_dialog_content = "Uuuh!",
  ui_story_1020_10201301_2_dialog_content = "Funcionou... Funcionou! Hahahahaha!",
  ui_story_1020_10201301_3_dialog_content = "Você conseguiu, Guardião Um! Você realmente conseguiu!",
  ui_story_1020_10201301_4_dialog_content = "Buá!",
  ui_story_1020_10201301_5_dialog_content = "Acabamos de ouvir um estrondo alto, Grande Marechal. Você está bem—",
  ui_story_1020_10201301_6_dialog_content = "Shhh, você ouviu isso?",
  ui_story_1020_10201301_7_dialog_content = "(Eclipsiano) 1011X.",
  ui_story_1020_10201301_8_dialog_content = "(Eclipsiano) 01X11.",
  ui_story_1020_10201301_9_dialog_content = "(Eclipsiano) X1010.",
  ui_story_1020_10201301_10_dialog_content = "O que está acontecendo com o professor?",
  ui_story_1020_10201301_11_dialog_content = "...",
  ui_story_1020_10201301_12_dialog_content = "(Eclipsiano) 0111X.",
  ui_story_1020_10201301_13_dialog_content = "(Eclipsiano) 0X111.",
  ui_story_1020_10201301_14_dialog_content = "... Eclipsiano?",
  ui_story_1020_10201301_15_dialog_content = "?",
  ui_story_1020_10201301_16_dialog_content = "Parece estranho vindo de sua boca, mas não há como negar - é a mesma língua que os Eclipsitas usam para se comunicar.",
  ui_story_1020_10201301_17_dialog_content = "... Isso é o que PlayerName estava resmungando quando se conectou com Figerald.",
  ui_story_1020_10201301_18_dialog_content = "1011X.",
  ui_story_1020_10201301_19_dialog_content = "... Assim?",
  ui_story_1020_10201301_20_dialog_content = "Espere, o que foi isso de novo? Diga mais devagar.",
  ui_story_1020_10201301_21_dialog_content = "1... 0... 1... 1... X...",
  ui_story_1020_10201301_22_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10201301_23_dialog_content = "PlayerName entende Eclipsiano?",
  ui_story_1020_10201301_24_dialog_content = "Eu realmente não entendo isso, e isso pode parecer estranho... Mas repetir as palavras deles agora é bem fácil para mim...",
  ui_story_1020_10201301_25_dialog_content = "Sem surpresa... É exatamente como quando você se conectou com Bool para nos ajudar a registrar aqueles outros números!",
  ui_story_1020_10201301_26_dialog_content = "Há uma conexão entre o Eclipsiano e a linguagem de computação do protótipo...",
  ui_story_1020_10201301_27_dialog_content = "A maioria dos Eclipsitas parecem completamente sem mente até que recebam a ordem para atacar.",
  ui_story_1020_10201301_28_dialog_content = "Ordens... Linguagem... Sim, está tudo começando a fazer sentido!",
  ui_story_1020_10201301_29_dialog_content = "(Eclipsiano) 2355X11874...",
  ui_story_1020_10201301_30_dialog_content = "(Eclipsiano) 32456901X14361...",
  ui_story_1020_10201301_31_dialog_content = "(Se Ulysses está se comunicando com o Engenheiro agora...)",
  ui_story_1020_10201301_32_dialog_content = "Eu poderia ser capaz de usar meus poderes nele...",
  ui_story_1020_10201301_33_dialog_content = "O que você está fazendo, PlayerName? Ulysses matou muitas pessoas, ele merece morrer!",
  ui_story_1020_10201301_34_dialog_content = "Mas essa pode ser a única maneira de eu encontrar Soroz e Vice...",
  ui_story_1020_10201301_35_dialog_content = "PlayerName!",
  ui_story_1020_10201301_36_dialog_content = "Pare de usar seus poderes. Você está no seu limite.",
  ui_story_1020_10201301_37_dialog_content = "É realmente o meu limite...",
  ui_story_1020_10201301_38_dialog_content = "Desculpe, mas isso é a única coisa que posso fazer agora...",
  ui_story_1020_10201301_39_option_content = "Ligação Telepática—",
  ui_story_1020_10201301_40_dialog_content = "Coloque o anel ou seja meu combustível.",
  ui_story_1020_10201301_41_dialog_content = "Como já disse inúmeras vezes antes, não vou me render a você.",
  ui_story_1020_10201301_42_dialog_content = "Não cheguei a ficar assim porque tinha medo da morte...",
  ui_story_1020_10201301_43_dialog_content = "De estudar os mortos a transformar os vivos em mortos, há muito tempo estou insensível a isso.",
  ui_story_1020_10201301_44_dialog_content = "Você é corajoso além do normal, Uly.",
  ui_story_1020_10201301_45_dialog_content = "Como eu no passado.",
  ui_story_1020_10201301_46_dialog_content = "Hehehe... Hahaha... Apenas \"como\"?",
  ui_story_1020_10201301_47_dialog_content = "Até o Robby desistiu naquela época. Eu era o único que restava do enorme laboratório que ainda se lembrava do motivo do estudo em primeiro lugar...",
  ui_story_1020_10201301_48_dialog_content = "Isso é para descobrir o que tornou os Eclipsitas poderosos e um meio para os Aurorianos sobreviverem.",
  ui_story_1020_10201301_49_dialog_content = "Seu nome apareceu quando eu estava olhando os arquivos. Você me levou a pesquisar os registros empoeirados e a pesquisar o Guardião em segredo.",
  ui_story_1020_10201301_50_dialog_content = "Foi também quando vi a planta para a produção mecanizada de Eclipsitas e Caelestites bombardeando Astra em Colossos...",
  ui_story_1020_10201301_51_dialog_content = "Assim como os Aurorianos que se abrigam nas subcidades.",
  ui_story_1020_10201301_52_dialog_content = "Eoria passou de azul para um vermelho ardente, segundos antes de se tornar um mundo morto cinza de cinzas.",
  ui_story_1020_10201301_53_dialog_content = "A Aurora cobriu o céu, e a órbita foi desviada...",
  ui_story_1020_10201301_54_dialog_content = "Tecnologia, guerra, animosidade, vida...",
  ui_story_1020_10201301_55_dialog_content = "Foi você quem me mostrou a crueldade e me forçou a viver com medo.",
  ui_story_1020_10201301_56_dialog_content = "O que foi que eu disse?",
  ui_story_1020_10201301_57_dialog_content = "\"Você precisa ser mais ousado se quiser derrotar os Eclipsitas!\"",
  ui_story_1020_10201301_58_dialog_content = "\"Ainda mais ousado!\"",
  ui_story_1020_10201301_59_dialog_content = "Sempre que ouvia isso, geralmente não conseguia dizer quem eu era, se estava no passado ou no futuro.",
  ui_story_1020_10201301_60_dialog_content = "Eu até pensaria, \"Por que eu?\"",
  ui_story_1020_10201301_61_dialog_content = "Mas quando superei o medo, descobri e desde então tenho sido destemido.",
  ui_story_1020_10201301_62_dialog_content = "Mesmo quando estou enfrentando este mundo cruel, mesmo quando estou enfrentando você.",
  ui_story_1020_10201301_63_dialog_content = "Você conquistou aquele medo, mas adquiriu um novo medo.",
  ui_story_1020_10201301_64_dialog_content = "Qual novo medo?",
  ui_story_1020_10201301_65_dialog_content = "Gostaria de ver isso?",
  ui_story_1020_10201301_66_dialog_content = "...",
  ui_story_1020_10201301_67_dialog_content = "Negador.",
  ui_story_1020_10201301_68_dialog_content = "Senhor.",
  ui_story_1020_10201301_69_dialog_content = "A teoria sobre o Eclipsium que você propôs no seminário vale a pena pesquisar.",
  ui_story_1020_10201301_70_dialog_content = "Obrigado, senhor. Mas a Illumina não consegue apoiar meu estudo no momento.",
  ui_story_1020_10201301_71_dialog_content = "Haverá materiais chegando após a guerra. Você pode construir seu próprio laboratório em Gannon e fazer os experimentos que deseja.",
  ui_story_1020_10201301_72_dialog_content = "... Obrigado, senhor.",
  ui_story_1020_10201301_73_dialog_content = "Como está o progresso, Negador?",
  ui_story_1020_10201301_74_dialog_content = "Esta é a semente que eu nutri, senhor.",
  ui_story_1020_10201301_75_dialog_content = "Excelente... É muito bonito.",
  ui_story_1020_10201301_76_dialog_content = "Se pudéssemos plantá-lo em nossos soldados...",
  ui_story_1020_10201301_77_dialog_content = "É apenas um estudo, senhor! O Darkflow na semente vai devorar os Aurorians.",
  ui_story_1020_10201301_78_dialog_content = "Devorar Aurorianos? Você sabe como os Eclipsitas estão devorando o mundo?",
  ui_story_1020_10201301_79_dialog_content = "?",
  ui_story_1020_10201301_80_dialog_content = "Seu resultado é excepcional, Negador. É hora de uma metamorfose auroriana.",
  ui_story_1020_10201301_81_dialog_content = "... O que você está planejando fazer?",
  ui_story_1020_10201301_82_dialog_content = "Entregue a semente.",
  ui_story_1020_10201301_83_dialog_content = "...",
  ui_story_1020_10201301_84_dialog_content = "Entregue-o.",
  ui_story_1020_10201301_85_dialog_content = "Me recuso.",
  ui_story_1020_10201301_86_dialog_content = "Você está se opondo à Illumina?",
  ui_story_1020_10201301_87_dialog_content = "Não, senhor.",
  ui_story_1020_10201301_88_dialog_content = "Nunca esqueça, sem mim, não há você.",
  ui_story_1020_10201301_89_dialog_content = "...",
  ui_story_1020_10201301_90_dialog_content = "Eu me lembro agora, esse é o Illuminan chamado Forsakin, aquele que você sempre quis ser.",
  ui_story_1020_10201301_91_dialog_content = "Não...",
  ui_story_1020_10201301_92_dialog_content = "Seu orgulho, sua grande obra é chamada de Projeto: Sol Artificial, certo?",
  ui_story_1020_10201301_93_dialog_content = "Eu já reconheci seu talento, Uly. Agora use o anel, o símbolo desse reconhecimento.",
  ui_story_1020_10201301_94_dialog_content = "Não preciso do seu reconhecimento e nunca me submeterei à sua vontade!",
  ui_story_1020_10201301_95_dialog_content = "(Ulysses feriu tantas pessoas e conduziu todos aqueles terríveis experimentos, mas nunca cedeu ao Engenheiro...)",
  ui_story_1020_10201301_96_dialog_content = "(Por que é isso?)",
  ui_story_1020_10201301_97_dialog_content = "Está surpreso, Celestita?",
  ui_story_1020_10201301_98_dialog_content = "Então você consegue me ver quando estou usando minhas habilidades psíquicas...",
  ui_story_1020_10201301_99_dialog_content = "Quão?",
  ui_story_1020_10201301_100_dialog_content = "Quando a Colossus \"viu\" a mim, eu \"vi\" você.",
  ui_story_1020_10201301_101_dialog_content = "O \"eu\" em autoconsciência é um conceito abstrato. O que parece ser senciente pode realmente ser o recipiente para outra consciência.",
  ui_story_1020_10201301_102_dialog_content = "Porque sempre há uma inteligência superior por trás disso.",
  ui_story_1020_10201301_103_dialog_content = "A máquina antiga é meu veículo, assim como aquele fantasma—e em breve, ele.",
  ui_story_1020_10201301_104_dialog_content = "Ulysses... Não coloque esse anel!",
  ui_story_1020_10201301_105_dialog_content = "Ele não pode te ouvir.",
  ui_story_1020_10201301_106_dialog_content = "...",
  ui_story_1020_10201301_107_dialog_content = "Vice, Soroz... Vou encontrar os dois!",
  ui_story_1020_10201301_108_dialog_content = "Claro.",
  ui_story_1020_10201301_109_dialog_content = "Uma luz brevemente nos separou antes. Talvez haja algo que eu queira ver lá.",
  ui_story_1020_10201301_110_dialog_content = "A superfície do lago brilhante...",
  ui_story_1020_10201301_111_dialog_content = "O que você ouviu? Eu nunca vou colocar esse anel, e não vou morrer tão facilmente.",
  ui_story_1020_10201301_112_dialog_content = "É inútil lutar no seu estado.",
  ui_story_1020_10201301_113_dialog_content = "O estado em que me encontro não importa, mas vou dizer a eles como os Aurorianos podem sobreviver.",
  ui_story_1020_10201301_114_dialog_content = "Sou a única pessoa no mundo que te entende. Mas respeito o seu desejo.",
  ui_story_1020_10201301_115_dialog_content = "O que você vai fazer com ele?",
  ui_story_1020_10201301_116_dialog_content = "Dê a ele o que ele quer.",
  ui_story_1020_10201301_117_dialog_content = "Sempre haverá grandes cientistas para cada geração na Illumina.",
  ui_story_1020_10201301_118_dialog_content = "Mas sem eles e o protótipo, ainda podemos nos encontrar em outro lugar. Você já sabe as minhas coordenadas.",
  ui_story_1020_10201301_119_dialog_content = "...",
  ui_story_1020_10201301_120_dialog_content = "Lembre-se, a luz pode ser enganosa. Ela tenta encobrir o fato de que a escuridão é a verdade.",
  ui_story_1020_10201301_121_dialog_content = "Aceite a escuridão, deixe-a entrar e permita que ela seja a sua força.",
  ui_story_1020_10201301_122_dialog_content = "Urgh—",
  ui_story_1020_10201301_123_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10201301_124_dialog_content = "Seu cérebro ainda está intacto, PlayerName?",
  ui_story_1020_10201301_125_dialog_content = "Estou bem! Mas Ulysses...",
  ui_story_1020_10201301_126_dialog_content = "Hraaagh!",
  ui_story_1020_10201301_127_dialog_content = "Bu! Bu! Bu!",
  ui_story_1020_10201301_128_dialog_content = "Pare de ir pra frente, professor, ou—",
  ui_story_1020_10201301_129_dialog_content = "<color=#e8d9bb>Clique-</color>",
  ui_story_1020_10201301_130_dialog_content = "...",
  ui_story_1020_10201301_131_dialog_content = "Você atiraria em mim? Eu criei você... Todos vocês me entendem, não é?",
  ui_story_1020_10201301_132_dialog_content = "Ele está se comportando como Figerald!",
  ui_story_1020_10201301_133_dialog_content = "Não, eles não são iguais.",
  ui_story_1020_10201301_134_dialog_content = "Ulysses nunca cedeu à vontade do Engenheiro, então ele está tentando destruí-lo... Ulysses está resistindo a ele agora.",
  ui_story_1020_10201301_135_dialog_content = "...",
  ui_story_1020_10201301_136_dialog_content = "O que devemos fazer com ele, Grande Marechal?",
  ui_story_1020_10201301_137_dialog_content = "... Pare, Ulysses! Você não entende?",
  ui_story_1020_10201301_138_dialog_content = "Você pensou que estava salvando os Aurorianos do Eclipse todo esse tempo. Você nunca percebeu que se juntou a eles há muito tempo!",
  ui_story_1020_10201301_139_dialog_content = "Diga a eles... Celestita...",
  ui_story_1020_10201301_140_dialog_content = "10011000... Como os Aurorians podem sobreviver... 00!",
  ui_story_1020_10201301_141_dialog_content = "Não poupe esforços... 12933... Indo ao extremo... 11012... é o... 103001111...",
  ui_story_1020_10201301_142_dialog_content = "Única chance...",
  ui_story_1020_10201301_143_dialog_content = "01100...",
  ui_story_1020_10201301_144_dialog_content = "Não...",
  ui_story_1020_10201301_145_dialog_content = "Você é especial... Você deve enfrentar o destino... do seu próprio jeito...",
  ui_story_1020_10201301_146_dialog_content = "Mas... 10011001X0... Mas...",
  ui_story_1020_10201301_147_dialog_content = "Urgh... Arghhhh—",
  ui_story_1020_10201301_148_dialog_content = "1001X1000... O mundo que eu mudei...",
  ui_story_1020_10201301_149_dialog_content = "Certamente será... 10102099... o seu futuro... 1X120...",
  ui_story_1020_10201301_150_dialog_content = "Bool!",
  ui_story_1020_10201301_151_dialog_content = "Passe um cabo no corpo de Ulysses! Precisamos encontrar a interface e destruir a conexão entre ele e o Engenheiro!",
  ui_story_1020_10201301_152_dialog_content = "Argh...",
  ui_story_1020_10201301_153_dialog_content = "Já é tarde demais...",
  ui_story_1020_10201301_154_dialog_content = "...",
  ui_story_1020_10201301_155_dialog_content = "Não importa o que ele fez pela Illumina no passado, ele não é mais um de nós - ou um Auroriano, nesse caso.",
  ui_story_1020_10201301_156_dialog_content = "Ele colocou toda a Cidade Gannon em perigo várias vezes e tirou a vida de seus compatriotas.",
  ui_story_1020_10201301_157_dialog_content = "Como Grande Marechal da Federação Illumina, eu aqui condeno Ulysses à morte por seus crimes.",
  ui_story_1020_10201301_158_dialog_content = "Hraaagh!",
  ui_story_1020_10201301_159_dialog_content = "Mate ele!",
  ui_story_1020_10201402_1_dialog_content = "Você pode ser salvo... se eu morrer?",
  ui_story_1020_10201402_2_dialog_content = "Estou dificilmente satisfeito com esse resultado, Robby...",
  ui_story_1020_10201402_3_dialog_content = "<color=#e8d9bb>Em um Sanatório Illumina em Tempo de Guerra Durante a Crise Darkover</color>",
  ui_story_1020_10201402_4_dialog_content = "Ei, já faz muito tempo, Uly.",
  ui_story_1020_10201402_5_dialog_content = "Não esperava ver você aqui, Robby...",
  ui_story_1020_10201402_6_dialog_content = "Como você-",
  ui_story_1020_10201402_7_dialog_content = "Qual nova ideia você está ponderando hoje?",
  ui_story_1020_10201402_8_dialog_content = "...",
  ui_story_1020_10201402_9_dialog_content = "Meu experimento falhou novamente, Uly. <color=#FFB400>Undercity 77</color> enviou de volta apenas algumas cobaias carbonizadas...",
  ui_story_1020_10201402_10_dialog_content = "Eles tocaram a música que sempre ouvíamos no laboratório hoje... Oh, o que você acabou de dizer?",
  ui_story_1020_10201402_11_dialog_content = "...",
  ui_story_1020_10201402_12_dialog_content = "Eu disse que você ainda está usando aquele broche.",
  ui_story_1020_10201402_13_dialog_content = "Sim. Eu procurei por isso a noite inteira ontem. Acontece que a Sasha escondeu. Que criança travessa.",
  ui_story_1020_10201402_14_dialog_content = "...",
  ui_story_1020_10201402_15_dialog_content = "Ela começou a escrever poesia recentemente. Deixe-me ler um para você e veja o que você acha, Uly.",
  ui_story_1020_10201402_16_dialog_content = "Robby...",
  ui_story_1020_10201402_17_dialog_content = "Você esqueceu como mergulhamos na pesquisa e nas pistas sobre o Engenheiro.",
  ui_story_1020_10201402_18_dialog_content = "Você só se lembra da família que partiu cedo...",
  ui_story_1020_10201402_19_dialog_content = "Na verdade, estou bastante feliz por você, heheh.",
  ui_story_1020_10201402_20_dialog_content = "Se eu nunca tivesse encontrado o nome do Engenheiro ou tivesse as visões...",
  ui_story_1020_10201402_21_dialog_content = "Se ainda pudéssemos estar discutindo nossos sonhos no laboratório como antes...",
  ui_story_1020_10201402_22_dialog_content = "A primeira coisa que você diria quando me visse todos os dias seria...",
  ui_story_1020_10201402_23_dialog_content = "Qual nova ideia você está ponderando hoje, Uly?",
  ui_story_1020_10201402_24_dialog_content = "...",
  ui_story_1020_10201402_25_dialog_content = "Ulisses.",
  ui_story_1020_10201402_26_dialog_content = "Sim?",
  ui_story_1020_10201402_27_dialog_content = "Você já passou por uma crise de fé?",
  ui_story_1020_10201402_28_dialog_content = "...",
  ui_story_1020_10201402_29_dialog_content = "Não.",
  ui_story_1020_10201402_30_dialog_content = "Qual você acha que é pior...",
  ui_story_1020_10201402_31_dialog_content = "Crise de fé ou incapacidade de alcançar seu objetivo?",
  ui_story_1020_10201402_32_dialog_content = "...",
  ui_story_1020_10201402_33_dialog_content = "Crise da minha fé ou incapacidade de alcançar meu objetivo...",
  ui_story_1020_10201402_34_dialog_content = "Qual é mais lamentável?",
  ui_story_1020_10201402_35_dialog_content = "...",
  ui_story_1020_10201501_1_dialog_content = "... É como uma tela!",
  ui_story_1020_10201501_2_dialog_content = "Sim, e é a tela de Minch. Rabiscos aleatórios antes de espirrar tinta nela!",
  ui_story_1020_10201501_3_dialog_content = "... Tem uma sensação artística única.",
  ui_story_1020_10201501_4_dialog_content = "O que você quer chegar?",
  ui_story_1020_10201501_5_dialog_content = "A Senhora Victoria não nos trouxe aqui para você zombar de mim!",
  ui_story_1020_10201501_6_dialog_content = "Ah, falando nisso, obrigado, Senhora Victoria!",
  ui_story_1020_10201501_7_dialog_content = "Obrigado, Senhora Victoria!",
  ui_story_1020_10201501_8_dialog_content = "Obrigado, Senhora Victoria!",
  ui_story_1020_10201501_9_dialog_content = "Não devo levar crédito por isso. Esta é uma bênção do Senhor da Verdade.",
  ui_story_1020_10201501_10_dialog_content = "Onde estou?",
  ui_story_1020_10201501_11_dialog_content = "...",
  ui_story_1020_10201501_12_dialog_content = "O <color=#FFB400>Rio Pristino</color> fica fora do tempo e do espaço. A única diferença entre ele e o mundo exterior é a fluidez.",
  ui_story_1020_10201501_13_dialog_content = "Não vamos perder o controle de nossas próprias vidas se isso continuar?",
  ui_story_1020_10201501_14_dialog_content = "Por que você nos trouxe aqui?",
  ui_story_1020_10201501_15_dialog_content = "Para encontrar a marca correspondente ao nosso espaço-tempo e permitir que o Senhor da Verdade venha conosco.",
  ui_story_1020_10201501_16_dialog_content = "Blá blá blá...",
  ui_story_1020_10201501_17_dialog_content = "Senhorita Victoria, ainda não terminamos nossa missão de reconhecimento na Zona Cega. A Illumina realmente consegue obter as coordenadas que enviamos de volta daqui?",
  ui_story_1020_10201501_18_dialog_content = "O Senhor da Verdade prega que querer é poder. Tudo depende de você.",
  ui_story_1020_10201501_19_dialog_content = "<color=#e8d9bb>Sploosh—</color>",
  ui_story_1020_10201501_20_dialog_content = "Ei, Vice, você deixou cair alguma coisa?",
  ui_story_1020_10201501_21_dialog_content = "Oh não, é o meu crachá da Illumina!",
  ui_story_1020_10201501_22_dialog_content = "O que eu deveria fazer agora? Eu não consigo pegar de volta...",
  ui_story_1020_10201501_23_dialog_content = "Espere, como é que um pequeno distintivo iluminou todo o rio assim?",
  ui_story_1020_10201501_24_dialog_content = "Tudo está quieto no campo, mas é uma questão completamente diferente sob a superfície do rio.",
  ui_story_1020_10201501_25_dialog_content = "A superfície do lago... Uau, tão gelada e não parece real.",
  ui_story_1020_10201501_26_dialog_content = "A superfície do lago...",
  ui_story_1020_10201501_27_dialog_content = "Você acordou, PlayerName.",
  ui_story_1020_10201501_28_dialog_content = "Onde estou?",
  ui_story_1020_10201501_29_dialog_content = "Carleen? O que você está... O que eu estou fazendo aqui?",
  ui_story_1020_10201501_30_dialog_content = "Você não se lembra de nada?",
  ui_story_1020_10201501_31_dialog_content = "Acabei de ter um sonho sobre a superfície de um lago brilhante... Mas por algum motivo, não consigo me lembrar de nenhum detalhe...",
  ui_story_1020_10201501_32_dialog_content = "Ah, é verdade! A Illumina está bem?",
  ui_story_1020_10201501_33_dialog_content = "Heh, você deve estar bem se consegue falar com tanta energia.",
  ui_story_1020_10201501_34_dialog_content = "Boa recuperação após três dias inteiros de sono. É bom ser jovem.",
  ui_story_1020_10201501_35_dialog_content = "Dormi por três dias seguidos?",
  ui_story_1020_10201501_36_dialog_content = "Sim. O Capitão Carleen já visitou três vezes.",
  ui_story_1020_10201501_37_dialog_content = "Senti que qualquer coisa além disso iria perturbar Vivian...",
  ui_story_1020_10201501_38_dialog_content = "Isso era originalmente uma <color=#FFB400>reunião conjunta</color> organizada pela Federação Illumina. Desculpe, não conseguimos decidir um horário mais cedo.",
  ui_story_1020_10201501_39_dialog_content = "Mas agora que PlayerName está acordado, e o Capitão da Guarda está aqui, por que não fazer isso hoje?",
  ui_story_1020_10201501_40_dialog_content = "Claro, eu estou bem com isso.",
  ui_story_1020_10201501_41_dialog_content = "Uma reunião conjunta... O que aconteceu enquanto eu estava fora? E o que aconteceu com Ulysses?",
  ui_story_1020_10201501_42_dialog_content = "Ele está morto. O incidente com o Engenheiro também está resolvido por enquanto.",
  ui_story_1020_10201501_43_dialog_content = "Depois de revisar todo o assunto, eu posso mais ou menos adivinhar o que você viu na mente dele, PlayerName.",
  ui_story_1020_10201501_44_dialog_content = "Após vasculhar seu laboratório, encontramos um grande volume de registros experimentais contendo informações vitais.",
  ui_story_1020_10201501_45_dialog_content = "Mas o que mais me surpreende é que Ulysses conseguiu resistir ao Engenheiro por tanto tempo, mesmo estando em sua mira.",
  ui_story_1020_10201501_46_dialog_content = "No entanto, como disse o Grande Marechal, enquanto Ulysses olhava para a Zona Escura, ela o estava corrompendo de volta...",
  ui_story_1020_10201501_47_dialog_content = "Antes que ele percebesse, ele se tornou um dos Eclipses.",
  ui_story_1020_10201501_48_dialog_content = "Sim. Parece que a crise que enfrentamos foi algo que a Cidade de Gannon não via há mais de seiscentos anos.",
  ui_story_1020_10201501_49_dialog_content = "Mas graças ao trabalho árduo de todos, nossa cidade sobreviveu. Não teríamos conseguido sem o Dr. Algol também.",
  ui_story_1020_10201501_50_dialog_content = "Então, onde ela está?",
  ui_story_1020_10201501_51_dialog_content = "Eu pensei que o Dr. Algol ficaria em coma por dias como você.",
  ui_story_1020_10201501_52_dialog_content = "Mas depois que a crise acabou, ela retomou sua pesquisa como se nada tivesse acontecido.",
  ui_story_1020_10201501_53_dialog_content = "Ela deve estar por aí hoje procurando peças para consertar o Guardian One, eu acho.",
  ui_story_1020_10201501_54_dialog_content = "Ela já está trabalhando na restauração do Guardião Um? Mas Algol quase nunca sai.",
  ui_story_1020_10201501_55_dialog_content = "Provavelmente é porque ela pode pilotar o novo transporte da Illumina.",
  ui_story_1020_10201501_56_dialog_content = "O novo transporte da Illumina? O que você quer dizer?",
  ui_story_1020_10201501_57_dialog_content = "Ulysses passou tantos anos pesquisando Colossos, e a equipe de engenharia conseguiu criar versões em miniatura deles com base em sua pesquisa.",
  ui_story_1020_10201501_58_dialog_content = "Esses veículos de pequena escala nos ajudaram a evacuar muitos de nossos residentes durante o incidente. Também os usaremos para a próxima expedição conjunta.",
  ui_story_1020_10201501_59_dialog_content = "...",
  ui_story_1020_10201501_60_option_content = "Ulysses...",
  ui_story_1020_10201501_61_option_content = "Veículos em pequena escala...",
  ui_story_1020_10201501_62_dialog_content = "Vocês realmente vão continuar com a pesquisa dele?",
  ui_story_1020_10201501_63_dialog_content = "Eu sei o que te preocupa.",
  ui_story_1020_10201501_64_dialog_content = "Não se trata apenas desses pequenos veículos, mas também de Aurorianos como Sean que são capazes de explorar a Dark Zone também.",
  ui_story_1020_10201501_65_dialog_content = "O fato é que nada disso seria possível sem a pesquisa de Ulysses.",
  ui_story_1020_10201501_66_dialog_content = "Tenho certeza de que tomar essa decisão não foi menos difícil do que escolher conceder autoridade total de pesquisa ao Sistema Guardian durante a Crise Darkover.",
  ui_story_1020_10201501_67_dialog_content = "Mas desta vez, mesmo que o Conselho Científico e todos os nossos principais cientistas no Laboratório de Pesquisa tenham tido a chance de avaliar e votar em sua pesquisa...",
  ui_story_1020_10201501_68_dialog_content = "Eles ainda estão divididos sobre aprovar ou não isso.",
  ui_story_1020_10201501_69_dialog_content = "Na minha opinião, proteger as vidas da Federação Illumina é a nossa prioridade mais importante.",
  ui_story_1020_10201501_70_dialog_content = "Isso significa que você era contra o uso da pesquisa dele?",
  ui_story_1020_10201501_71_dialog_content = "Na verdade, é o oposto.",
  ui_story_1020_10201501_72_dialog_content = "Parte de garantir nossa sobrevivência é assumir pequenos riscos calculados. Precisamos estar totalmente cientes desses riscos, bem como de como aproveitá-los ao máximo.",
  ui_story_1020_10201501_73_dialog_content = "Devemos continuar estudando nossos inimigos e testando nossos limites se quisermos melhorar as condições de sobrevivência para todos os Aurorianos.",
  ui_story_1020_10201501_74_dialog_content = "É por isso que você está organizando essa expedição conjunta? Espere... Isso significa que Lumópolis também está em perigo?",
  ui_story_1020_10201501_75_dialog_content = "Lumopolis nunca esteve em perigo, mas muitas relíquias exibiam padrões de Lumina caóticos, que chamaram a atenção do Senhor da Cidade.",
  ui_story_1020_10201501_76_dialog_content = "Após o que aconteceu na Cidade Gannon, o Comitê está disposto a explorar mais vias de cooperação sobre a expedição conjunta com as outras facções.",
  ui_story_1020_10201501_77_dialog_content = "Carleen concordou em servir como capitão da Equipe de Expedição de Lumópolis. Com o tempo, Northland e Umbraton também enviarão seus próprios representantes para cá.",
  ui_story_1020_10201501_78_dialog_content = "Oh, Grande Marechal, os intrometidos do Deserto Rediesel devem ter ouvido as notícias em algum lugar, e eu recebi a mensagem de que eles querem fazer parte disso.",
  ui_story_1020_10201501_79_dialog_content = "Eu quero saber o que você acha disso, PlayerName.",
  ui_story_1020_10201501_80_dialog_content = "Meus pensamentos...",
  ui_story_1020_10201501_81_dialog_content = "No passado, eu nunca realmente tomei a iniciativa de procurar por algo. Eu apenas deixava os vestígios dos Celestitas guiarem meu caminho.",
  ui_story_1020_10201501_82_dialog_content = "Mas enquanto consertava o Soroz, percebi que nem todos esses rastros levavam a coisas boas...",
  ui_story_1020_10201501_83_dialog_content = "Eu nem mesmo sabia se eu era uma boa pessoa ou não...",
  ui_story_1020_10201501_84_dialog_content = "Mas depois do que passei com Vice e Soroz, aquela sensação de surpresa agradável do inesperado desapareceu completamente.",
  ui_story_1020_10201501_85_dialog_content = "E porque eu perdi, eu tenho que recuperá-lo... o mais rápido possível.",
  ui_story_1020_10201501_86_dialog_content = "Isso me lembra... Ultimamente, parece que olhei para o passado, embora possa ter sido o futuro...",
  ui_story_1020_10201501_87_dialog_content = "De qualquer maneira, há um lugar que preciso investigar.",
  ui_story_1020_10201501_88_dialog_content = "Pode ser a Zona Escura, ou algum lugar ainda mais distante e inacessível.",
  ui_story_1020_10201501_89_dialog_content = "Por que estou tendo um sentimento de destino com isso?",
  ui_story_1020_10201501_90_dialog_content = "É mesmo? Bem, um amigo do leste uma vez leu minha sorte e disse que meu destino não estava exatamente \"na lista\"...",
  ui_story_1020_10201501_91_dialog_content = "Os celestitas são capazes de se libertar das algemas inatas, é por isso que eu não acredito em destino.",
  ui_story_1020_10201501_92_dialog_content = "Com convicção, coragem e sabedoria, você certamente recuperará o que perdeu.",
  ui_story_1020_10201501_93_dialog_content = "Claro!",
  ui_story_1020_10201501_94_dialog_content = "Fico feliz que você pense assim.",
  ui_story_1020_10201501_95_dialog_content = "Como Grande Marechal da Federação Illumina, tenho a responsabilidade de encontrar e resgatar meus compatriotas - naturalmente, isso inclui Charon, Vice e seus companheiros de esquadrão.",
  ui_story_1020_10201501_96_dialog_content = "Caso você escolha aceitar, a Federação Illumina está disposta a ajudá-lo a explorar a Zona Escura e a procurar por Soroz.",
  ui_story_1020_10201501_97_dialog_content = "Sim. Você é o motivo pelo qual Lumópolis se juntou a esta expedição.",
  ui_story_1020_10201501_98_dialog_content = "Obrigada, pessoal...",
  ui_story_1020_10201501_99_dialog_content = "Como tenho a confiança e o apoio de todos, definitivamente tenho que fazer parte desta expedição conjunta!",
  ui_story_1020_10201501_100_dialog_content = "Mas por onde devemos começar?",
  ui_story_1020_10201501_101_dialog_content = "Para ser honesto, existem vários lugares para escolher.",
  ui_story_1020_10201501_102_dialog_content = "O que foi?",
  ui_story_1020_10201501_103_dialog_content = "A memória de Helios.",
  ui_story_1020_10201501_104_dialog_content = "Que livro grande... E já acabou? Chandra é praticamente um raio lubrificado.",
  ui_story_1020_10201501_105_dialog_content = "Foi um dia longo, afinal, e todos estavam trabalhando o mais duro possível, mesmo com um convidado inesperado nos atrasando.",
  ui_story_1020_10201501_106_dialog_content = "Vejo que você está indo bem, então talvez eu finalmente possa ter uma boa noite de sono agora.",
  ui_story_1020_10201501_107_dialog_content = "Oh, o que foi aquilo sobre uma superfície de lago brilhante no seu sonho, PlayerName?",
  ui_story_1020_10201501_108_dialog_content = "Sim... Eu vi a superfície de um lago brilhante...",
  ui_story_1020_10201501_109_dialog_content = "E também um distintivo que parece muito familiar...",
  ui_story_1020_10201501_110_dialog_content = "Vocês conseguem pensar em algo assim?",
  ui_story_1020_10201501_111_dialog_content = "Quando estava sendo engolido pela escuridão, de repente ouvi o som de um piano. Depois disso, a luz começou a entrar...",
  ui_story_1020_10201501_112_dialog_content = "<color=#e8d9bb>Sploosh—</color>",
  ui_story_1020_10201501_113_dialog_content = "Vocês ouvem essa música, pessoal?",
  ui_story_1020_10201501_114_dialog_content = "Eu ouvi!",
  ui_story_1020_10201501_115_dialog_content = "O quê?",
  ui_story_1020_10201501_116_dialog_content = "Bem, parou depois que Merry gritou alto.",
  ui_story_1020_10201501_117_dialog_content = "Louve o Senhor da Verdade!",
  ui_story_1020_10201501_118_dialog_content = "Você encontrou a marca, Senhorita Vice. Por favor, nos guie do seu próprio jeito.",
  ui_story_1020_10201501_119_dialog_content = "Eu?",
  ui_story_1020_10201501_120_dialog_content = "Quando você e o Celestita ativaram a Colossus, despertaram este rio adormecido.",
  ui_story_1020_10201501_121_dialog_content = "A partir daquele momento, você virou uma nova página na história de Eoria.",
  ui_story_1020_10201501_122_dialog_content = "Por favor, nos guie novamente à sua maneira.",
  ui_story_1020_10201501_123_dialog_content = "Por favor, nos guie novamente à sua maneira.",
  ui_story_1020_10201501_124_dialog_content = "?",
  ui_story_1020_10201501_125_dialog_content = "...",
  ui_story_1020_10201501_126_dialog_content = "Não me diga que...",
  ui_story_1020_10201501_127_dialog_content = "Aquela coisa que parece um piano é o painel de controle da Colossus, certo?",
  ui_story_1020_10201501_128_dialog_content = "Deixe-me ajudar você e ligar a Colossus, Navegador.",
  ui_story_1020_10201501_129_dialog_content = "Me ajudar? Você é uma Aurorian, Vice. Não possui habilidades psíquicas.",
  ui_story_1020_10201501_130_dialog_content = "Mas posso te dar forças. Eu... posso ajudar.",
  ui_story_1020_10201501_131_dialog_content = "?",
  ui_story_1020_10201501_132_dialog_content = "Acredite em mim, PlayerName. Você e eu... não somos tão diferentes.",
  ui_story_1020_10201501_133_dialog_content = "É uma longa história. Te conto da próxima vez que tiver uma chance!",
  ui_story_1020_10201501_134_dialog_content = "Deixe-me mostrar como \"tocar\" isso...",
  ui_story_1020_10201501_135_dialog_content = "O que a senhorita Victoria disse me lembrou de certas coisas...",
  ui_story_1020_10201501_136_dialog_content = "...",
  ui_story_1020_10201501_137_dialog_content = "É simples. Como tocar um piano.",
  ui_story_1020_10201501_138_dialog_content = "...",
  ui_story_1020_10201501_139_dialog_content = "Mas não tem nenhuma partitura! Pode me indicar que teclas eu devo tocar?",
  ui_story_1020_10201501_140_dialog_content = "...",
  ui_story_1020_10201501_141_dialog_content = "Sinto... a energia fluindo.",
  ui_story_1020_10201501_142_dialog_content = "Sim. É como uma conversa, mas não entendo a língua das Colossi.",
  ui_story_1020_10201501_143_dialog_content = "A língua está dentro das teclas do piano.",
  ui_story_1020_10201501_144_dialog_content = "Vamos concluir o comando de ativação, Vice.",
  ui_story_1020_10201501_145_dialog_content = "...",
  ui_story_1020_10201501_146_dialog_content = "Se é assim que devo te guiar, eu sei o que fazer agora.",
  ui_story_1020_10201501_147_dialog_content = "Escutem, pessoal! É um piano tocando!",
  ui_story_1020_10201501_148_dialog_content = "O rio cintilante em luz misteriosa é o santuário do Senhor.",
  ui_story_1020_10201501_149_dialog_content = "Ele ouve a melodia enigmática e revela verdades infinitas.",
  ui_story_1020_10201501_150_dialog_content = "May o Senhor da Verdade testemunhe nossa exploração, caminhe conosco e venha.",
  ui_story_1021_10210100_1_dialog_content = "<color=#e8d9bb>Muitos anos atrás, perto das fronteiras de Northland...</color>",
  ui_story_1021_10210100_2_dialog_content = "Uma vez que você cruzar a colina à frente, estará fora do território de Northland, Vossa Majestade.",
  ui_story_1021_10210100_3_dialog_content = "...",
  ui_story_1021_10210100_4_dialog_content = "A tundra tem uma vasta extensão. Ainda existem pessoas de Northland vivendo do outro lado.",
  ui_story_1021_10210100_5_dialog_content = "Você deveria voltar agora, Sr. Novio. Isso é algo que eu quero fazer.",
  ui_story_1021_10210100_6_dialog_content = "Os reis e rainhas do passado, bem como a vasta e ilimitada planície de neve, lembrarão de tudo que você fez por Northland.",
  ui_story_1021_10210100_7_dialog_content = "O poder de defender Northland não vem de mim, mas da própria terra.",
  ui_story_1021_10210100_8_dialog_content = "Com esse objetivo, não vou decepcionar meus antecessores.",
  ui_story_1021_10210100_9_dialog_content = "Pelo Norte, vivemos para defender esta terra.",
  ui_story_1021_10210100_10_dialog_content = "<color=#e8d9bb>Farfalhar—</color>",
  ui_story_1021_10210100_11_dialog_content = "A neve parou de cair, eu vejo.",
  ui_story_1021_10210100_12_dialog_content = "Não me lembro de um clima tão agradável nesta floresta específica...",
  ui_story_1021_10210100_13_dialog_content = "Ha!",
  ui_story_1021_10210100_14_dialog_content = "Hã?",
  ui_story_1021_10210100_15_dialog_content = "Estou avisando, estranho. Saia agora ou enfrente a ira do Chefe Tiare!",
  ui_story_1021_10210100_16_dialog_content = "Você é Tiare?",
  ui_story_1021_10210100_17_dialog_content = "Como você sabe meu nome?",
  ui_story_1021_10210100_18_dialog_content = "Ahem... Mesmo que você tenha aprendido meu nome de alguma forma, eu nunca permitiria que você pisasse dentro do assentamento da Tribo da Neve Fox!",
  ui_story_1021_10210100_19_dialog_content = "Você é da Tribo da Neve Fox? Onde estão seus pais?",
  ui_story_1021_10210100_20_dialog_content = "Ambos estão ocupados protegendo Northland! Agora pare de divagar e me diga o que você está fazendo aqui!",
  ui_story_1021_10210100_21_dialog_content = "Tiare, venha ver o que a vovó trouxe para você!",
  ui_story_1021_10210100_22_dialog_content = "Uau, são os meus galhos perfumados favoritos!",
  ui_story_1021_10210100_23_dialog_content = "Agora me diga, por que você não está no altar, mas aprontando por aqui?",
  ui_story_1021_10210100_24_dialog_content = "Bem... O ancião disse que esse não é um lugar para crianças...",
  ui_story_1021_10210100_25_dialog_content = "Vejo que aquela velha raposa está ficando caduca agora.",
  ui_story_1021_10210100_26_dialog_content = "Vovó, eu fiz algo incrível hoje! Veja, estou mantendo esse estranho fora do nosso assentamento!",
  ui_story_1021_10210100_27_dialog_content = "...",
  ui_story_1021_10210100_28_dialog_content = "Muito bom, Tiare!",
  ui_story_1021_10210100_29_dialog_content = "Agora, você ainda se lembra da lenda dos Três Pinheiros?",
  ui_story_1021_10210100_30_dialog_content = "Sim!",
  ui_story_1021_10210100_31_dialog_content = "Ela é muito inteligente e não precisa que você repita o mito para ela novamente.",
  ui_story_1021_10210100_32_dialog_content = "Se eu não fizer isso, ninguém se lembrará, e não demorará muito para ela começar a aprender e contar as histórias de outras pessoas.",
  ui_story_1021_10210100_33_dialog_content = "...",
  ui_story_1021_10210100_34_dialog_content = "Eu sou Bethlehem. Prazer em conhecer vocês dois.",
  ui_story_1021_10210100_35_dialog_content = "Minha gratidão aos seus ancestrais por protegerem Northland. Agora, eu me despeço.",
  ui_story_1021_10210100_36_dialog_content = "...",
  ui_story_1021_10210100_37_dialog_content = "<color=#e8d9bb>Farfalhar—</color>",
  ui_story_1021_10210100_38_dialog_content = "Você mencionou que a luz do Farol chegaria aqui.",
  ui_story_1021_10210100_39_dialog_content = "...",
  ui_story_1021_10210100_40_dialog_content = "A tribo não ouve o choro de um recém-nascido há muitos anos.",
  ui_story_1021_10210100_41_dialog_content = "Sou grato por cada guarda produzido pela Tribo da Neve Fox.",
  ui_story_1021_10210100_42_dialog_content = "Essas crianças não nasceram em um palácio majestoso, mas em uma floresta que poderia ser invadida pelos Eclipsitas a qualquer momento.",
  ui_story_1021_10210100_43_dialog_content = "Uma geração após a outra, seus antepassados morreram e foram enterrados aqui para proteger Northland.",
  ui_story_1021_10210100_44_dialog_content = "Eu posso levá-la de volta ao Palácio Invernal.",
  ui_story_1021_10210100_45_dialog_content = "Se os Eclipsitas arrasassem Northland, você iria para outro lugar?",
  ui_story_1021_10210100_46_dialog_content = "Nunca.",
  ui_story_1021_10210100_47_dialog_content = "Northland nos criou e protegeu. Devemos protegê-la em troca, através de todas as gerações.",
  ui_story_1021_10210100_48_dialog_content = "Por que estou me lembrando do que aconteceu naquele dia...",
  ui_story_1021_10210100_49_dialog_content = "O clima nas fronteiras tomou um rumo incomum, Vossa Majestade, e a luz do Farol mudou ligeiramente.",
  ui_story_1021_10210100_50_dialog_content = "Tudo isso não é coincidência... Eu já havia antecipado isso.",
  ui_story_1021_10210100_51_dialog_content = "Como você previu, a crise em Illumina antes não foi um incidente isolado, e a construção de postos avançados não está progredindo suavemente...",
  ui_story_1021_10210100_52_dialog_content = "Devemos observar a Zona Escura de perto.",
  ui_story_1021_10210100_53_dialog_content = "É imperativo lançar uma expedição conjunta, pois é vital para o futuro de todos os Aurorians. Além disso, estamos a apenas alguns dias da reunião conjunta.",
  ui_story_1021_10210100_54_dialog_content = "Eu vou dar uma olhada.",
  ui_story_1021_10210100_55_dialog_content = "Agora mesmo?",
  ui_story_1021_10210100_56_dialog_content = "Sim. Você já viu Tiare?",
  ui_story_1021_10210100_57_dialog_content = "Ela tem-",
  ui_story_1021_10210100_58_dialog_content = "Está saindo, Vossa Majestade? Por favor, deixe-me acompanhar você.",
  ui_story_1021_10210100_59_dialog_content = "...",
  ui_story_1021_10210100_60_dialog_content = "Vou sair sozinho por alguns dias. Novio está encarregado do Palácio de Inverno nesse meio tempo. Espero que você possa se manter alerta e preparado enquanto eu estiver fora.",
  ui_story_1021_10210100_61_dialog_content = "Muito bem, Vossa Majestade!",
  ui_story_1021_10210100_62_dialog_content = "(Por que a rainha está com tanta pressa?)",
  ui_story_1021_10210100_63_dialog_content = "As pegadas naqueles parapeitos de janela devem ser limpas.",
  ui_story_1021_10210100_64_dialog_content = "Claro!",
  ui_story_1021_10210100_65_dialog_content = "<color=#e8d9bb>Awoo!</color>",
  ui_story_1021_10210100_66_dialog_content = "...",
  ui_story_1021_10210100_67_dialog_content = "Não acredito que ainda não há resposta...",
  ui_story_1021_10210100_68_dialog_content = "Sua Majestade está ausente há dias agora.",
  ui_story_1021_10210100_69_dialog_content = "Se eu, como guarda dela, não posso estar ao lado dela, como devo permanecer alerta e pronto?",
  ui_story_1021_10210100_70_dialog_content = "<color=#e8d9bb>Awoo!</color>",
  ui_story_1021_10210100_71_dialog_content = "São vocês...",
  ui_story_1021_10210100_72_dialog_content = "Tadinha...",
  ui_story_1021_10210100_73_dialog_content = "O quê?",
  ui_story_1021_10210100_74_dialog_content = "Awuu!",
  ui_story_1021_10210100_75_dialog_content = "Como isso aconteceu?",
  ui_story_1021_10210100_76_dialog_content = "Voltei pouco antes da rainha deixar o palácio. O ancião e eu até nos deliciamos com a colheita do ano...",
  ui_story_1021_10210100_77_dialog_content = "Mas como guarda de Sua Majestade, eu não consigo parecer—",
  ui_story_1021_10210100_78_dialog_content = "Uauuuuuu!",
  ui_story_1021_10210100_79_dialog_content = "Entendi! Vou voltar com você agora!",
  ui_story_1021_10210100_80_dialog_content = "Raposa da neve! É uma raposa da neve!",
  ui_story_1021_10210100_81_dialog_content = "Você interrompeu a palestra do Sr. Antony novamente! Onde você viu uma raposa da neve?",
  ui_story_1021_10210100_82_dialog_content = "Vamos lá, é apenas um coelho pulando por aí!",
  ui_story_1021_10210100_83_dialog_content = "Mas eu realmente vi... Parecia exatamente com a raposa da neve no livro!",
  ui_story_1021_10210100_84_dialog_content = "Admito que é estranho ver uma raposa de neve na cidade... Você acredita em mim, certo? Sr. Antony?",
  ui_story_1021_10210100_85_dialog_content = "Dizem que antes de Northland ser chamada Northland, as raposas da neve se tornaram amigas de alguns Aurorianos e protegeram seus habitats juntos.",
  ui_story_1021_10210100_86_dialog_content = "Ainda existem raposas da neve em Northland agora?",
  ui_story_1021_10210100_87_dialog_content = "Acredito que sim. Eles são inteligentes e etéreos. Alguns supostamente viveram por centenas - até milhares - de anos...",
  ui_story_1021_10210100_88_dialog_content = "Milhares? Mas quão velhos eles são?",
  ui_story_1021_10210100_89_dialog_content = "Muito mais velho do que o pinheiro mais antigo de Northland. Você se lembra da história sobre os Três Pinheiros que eu te contei antes?",
  ui_story_1021_10210100_90_dialog_content = "Nós fazemos!",
  ui_story_1021_10210100_91_dialog_content = "Antes de Northland se tornar o Northland que conhecemos, havia três grandes pinheiros que sonhavam em proteger a terra...",
  ui_story_1021_10210100_92_dialog_content = "Mas todas as outras criaturas zombavam deles. Como meras árvores de pinho de neve poderiam proteger todo o Northland?",
  ui_story_1021_10210100_93_dialog_content = "Então, os lenhadores cortaram todas as três árvores na guerra mais tarde.",
  ui_story_1021_10210100_94_dialog_content = "Um foi utilizado na construção de um celeiro de estoque...",
  ui_story_1021_10210100_95_dialog_content = "Uma foi transformada em uma mesa e vendida para uma família pobre...",
  ui_story_1021_10210100_96_dialog_content = "Ninguém quis o terceiro, então foi colocado em um depósito e nunca mais viu o sol novamente.",
  ui_story_1021_10210100_97_dialog_content = "Muitos anos depois, uma senhora grávida deu à luz a uma criança naquele mesmo canil...",
  ui_story_1021_10210100_98_dialog_content = "O bebê nascido no monte de feno foi nosso primeiro Queen do Norte!",
  ui_story_1021_10210100_99_dialog_content = "Muitos anos depois, a rainha ajudou aquela pobre família.",
  ui_story_1021_10210100_100_dialog_content = "Naquela mesma mesa, os quatro irmãos sem dinheiro fizeram um juramento perante a rainha de que defenderiam a família real por gerações.",
  ui_story_1021_10210100_101_dialog_content = "Foi assim que seus descendentes assumiram o manto dos Guardas Reais de Northland!",
  ui_story_1021_10210100_102_dialog_content = "Opa. Desculpe, Sr. Antony, eu esqueci a história da última árvore...",
  ui_story_1021_10210100_103_dialog_content = "Mais tarde, a rainha encontrou a árvore no armazém e fez um cetro com ela.",
  ui_story_1021_10210100_104_dialog_content = "Esse cetro pode convocar todas as criaturas de Northland para defender o território.",
  ui_story_1021_10210100_105_dialog_content = "As árvores de Snowpine são nossos anjos da guarda. Somente com elas podemos garantir segurança e paz em nossa terra natal para as gerações futuras.",
  ui_story_1021_10210100_106_dialog_content = "...",
  ui_story_1021_10210100_107_dialog_content = "Como isso pode acontecer...",
  ui_story_1021_10210100_108_dialog_content = "As raposas... O ancião... O que aconteceu aqui?",
  ui_story_1021_10210100_109_dialog_content = "...",
  ui_story_1021_10210100_110_dialog_content = "<color=#e8d9bb>Auuuuu!</color>",
  ui_story_1021_10210201_1_dialog_content = "<color=#e8d9bb>Comando Temporário, Comitê da Expedição Conjunta Astra</color>",
  ui_story_1021_10210201_2_dialog_content = "Faz algum tempo, PlayerName!",
  ui_story_1021_10210201_3_dialog_content = "De fato, Wendy. Você está pontual como sempre!",
  ui_story_1021_10210201_4_dialog_content = "Está preso! Esse cachecol não é nada além de problemas...",
  ui_story_1021_10210201_5_dialog_content = "Ei, Pepi também está no horário! Onde está seu protegido Tweety?",
  ui_story_1021_10210201_6_dialog_content = "Para ser honesto, não estou impressionado com ela. Ela ainda tem um longo caminho a percorrer para ser uma mensageira qualificada.",
  ui_story_1021_10210201_7_dialog_content = "Ela grita, \"Eu estalei aqui!\" toda vez que você a apressa, mas quem sabe onde ela pode estar, pegando as cartas que perdeu!",
  ui_story_1021_10210201_8_dialog_content = "Embora como mentor, eu tenha que tolerar sua impaciência, negligência e a ocasional irresponsabilidade...",
  ui_story_1021_10210201_9_dialog_content = "Ela parece ter pegado um pouco disso de você... Espere um minuto, parecia que você estava se descrevendo, na verdade...",
  ui_story_1021_10210201_10_dialog_content = "Pelo menos ela tem a mim para cuidar dela!",
  ui_story_1021_10210201_11_dialog_content = "Mas quem cuida de mim? Acabei de voltar das minhas férias, e Vivian me enviou para verificar o posto avançado da expedição conjunta em Crepúsculo.",
  ui_story_1021_10210201_12_dialog_content = "Que tipo de lugar abandonado é o Crepúsculo afinal? A tempestade de areia é sombria, cheia de Darkflow, e está em todo lugar.",
  ui_story_1021_10210201_13_dialog_content = "Isso me deixou grogue o dia todo e muito lento para conseguir trabalhar...",
  ui_story_1021_10210201_14_dialog_content = "Argh! Não consigo me concentrar nem por um minuto... Tenho que encontrar um novo emprego no próximo mês.",
  ui_story_1021_10210201_15_option_content = "Aí está você, Vivian!",
  ui_story_1021_10210201_16_dialog_content = "!",
  ui_story_1021_10210201_17_dialog_content = "Mesmo que seja isso que meus colegas sempre reclamam, eu os encorajo e lembro que a Senhora Vivian nos trata muito bem!",
  ui_story_1021_10210201_18_dialog_content = "O cronograma é razoável e o pagamento é bom. Você também pode crescer ao longo de diferentes tarefas. Onde mais você pode encontrar um trabalho maravilhoso como este?",
  ui_story_1021_10210201_19_dialog_content = "Nossa, você certamente mudou de ideia muito rápido.",
  ui_story_1021_10210201_20_option_content = "Bem-vindo à Equipe de Expedição da Zona Escura.",
  ui_story_1021_10210201_21_dialog_content = "Zona Escura? Estou fora daqui. Comparado a isso, o trabalho de mensageiro é dez mil vezes melhor.",
  ui_story_1021_10210201_22_dialog_content = "Pense nisso... Eu posso programar as entregas como eu quiser, e não só sou livre para me movimentar, mas também não há perigo de perder o emprego...",
  ui_story_1021_10210201_23_dialog_content = "Então, agradeço a oferta, mas vou me contentar com... uh, continuar sendo um bom mensageiro!",
  ui_story_1021_10210201_24_dialog_content = "Acho que tenho o direito de pedir um incentivo para Vivian já que consegui fazer você ficar por aqui...",
  ui_story_1021_10210201_25_dialog_content = "É hora da reunião, Grande Marechal, mas o representante de Northland ainda está ausente.",
  ui_story_1021_10210201_26_dialog_content = "Recebi uma mensagem de Northland esta manhã. Podemos prosseguir como de costume.",
  ui_story_1021_10210201_27_dialog_content = "Sim, Grande Marechal.",
  ui_story_1021_10210201_28_dialog_content = "Representantes honrados, obrigado por participar da primeira reunião da Conferência Conjunta de Expedição Astra.",
  ui_story_1021_10210201_29_dialog_content = "Eu sou Vivian, Chefe de Gabinete da Federação Illumina. Se não houver objeções, vamos começar.",
  ui_story_1021_10210201_30_dialog_content = "Nada de mim.",
  ui_story_1021_10210201_31_dialog_content = "Como representante do Senhor das Sombras, não tenho objeções.",
  ui_story_1021_10210201_32_dialog_content = "Não vejo outra escolha a não ser começar neste caso.",
  ui_story_1021_10210201_33_dialog_content = "Vamos então começar oficialmente a reunião.",
  ui_story_1021_10210201_34_dialog_content = "Escolhemos este local aberto na esperança de que possamos chegar a um acordo sobre um futuro para os Aurorianos juntos.",
  ui_story_1021_10210201_35_dialog_content = "Primeiramente, gostaria de agradecer à União dos Correios por suas contribuições durante a construção dos postos avançados.",
  ui_story_1021_10210201_36_dialog_content = "Para garantir que todas as facções possam responder à operação da Equipe de Expedição da Zona Escura de maneira oportuna, a União Mensageira fornecerá suporte em várias áreas...",
  ui_story_1021_10210201_37_dialog_content = "Incluindo a disseminação de informações entre postos avançados e o relato de pistas relacionadas à Zona Cega. A União Mensageira assumirá a tarefa vital de monitoramento e validação.",
  ui_story_1021_10210201_38_dialog_content = "Sim! A União Mensageira sempre entrega!",
  ui_story_1021_10210201_39_dialog_content = "Agora, o Grande Marechal da Federação Illumina apresentará o plano para a expedição conjunta e solicitará seu feedback.",
  ui_story_1021_10210201_40_dialog_content = "Quanto à rota, ela foi mencionada em nossa correspondência anterior...",
  ui_story_1021_10210201_41_dialog_content = "Planejamos construir vários <color=#FFB400>postos avançados</color> perto da Zona Cega para facilitar o suporte e o reconhecimento.",
  ui_story_1021_10210201_42_dialog_content = "Com base na localização geográfica das várias facções, iremos estabelecer <color=#FFB400>três postos avançados</color> no norte de Astra.",
  ui_story_1021_10210201_43_dialog_content = "O primeiro está no <color=#FFB400>Crepúsculo</color> a noroeste. Sua escala atual e vantagem o tornam uma base de apoio muito adequada para a Equipe de Expedição da Zona Cega.",
  ui_story_1021_10210201_44_dialog_content = "O Senhor da Cidade de Lumopolis e eu chegamos a um acordo sobre a governança mútua de Twilight. A construção formal do posto avançado lá é a prova do nosso consenso.",
  ui_story_1021_10210201_45_dialog_content = "Um comando estratégico será estabelecido em Crepúsculo para fornecer o suporte necessário para a Equipe de Expedição.",
  ui_story_1021_10210201_46_dialog_content = "Leo ficará responsável pelo posto avançado e atualizará o quartel-general regularmente sobre o progresso.",
  ui_story_1021_10210201_47_dialog_content = "Os outros dois serão o <color=#FFB400>Posto Avançado de Eraveil</color> e o <color=#FFB400>Posto Avançado do Norte</color>.",
  ui_story_1021_10210201_48_dialog_content = "Atualmente, estamos avaliando a viabilidade do Posto Avançado de Eraveil, levando em consideração o impacto das ruínas subterrâneas locais.",
  ui_story_1021_10210201_49_dialog_content = "A construção do Posto Avançado de Northland será prolongada devido ao ambiente único. Farei um anúncio assim que tiver a confirmação do Queen do Norte.",
  ui_story_1021_10210201_50_dialog_content = "Por fim, gostaria de esclarecer uma coisa.",
  ui_story_1021_10210201_51_dialog_content = "A rota e as coordenadas para a expedição foram o resultado dos esforços entre o Dr. Algol da Federação Illumina e um oficial de inteligência.",
  ui_story_1021_10210201_52_dialog_content = "Todas as informações foram validadas várias vezes para garantir segurança e precisão. Compartilharemos elas com todos vocês com o propósito de participação mútua e proteção.",
  ui_story_1021_10210201_53_dialog_content = "Você pode fazer perguntas sobre as informações mencionadas anteriormente.",
  ui_story_1021_10210201_54_dialog_content = "Entendo que a Illumina pagou caro para obter os dados sobre a Dark Zone.",
  ui_story_1021_10210201_55_dialog_content = "Mas não há falta de pessoas ambiciosas na Federação Illumina, e isso é sobre o futuro dos Aurorians. Você deveria estar decidindo a lista para a expedição sozinho?",
  ui_story_1021_10210201_56_dialog_content = "Claro. Na Illumina, não julgamos os indivíduos por sua ambição, mas por sua coragem e determinação em superar desafios.",
  ui_story_1021_10210201_57_dialog_content = "Primeiramente, já temos uma <color=#FFB400>equipe de exploração</color> de elite posicionada dentro da Zona Escura. Eles abrirão caminho para as operações de acompanhamento.",
  ui_story_1021_10210201_58_dialog_content = "Em seguida, temos a <color=#FFB400>Dra. Barrett</color> como nossa consultora operacional. A equipe dela criou a aeronave usada para a expedição.",
  ui_story_1021_10210201_59_dialog_content = "E o Chefe de Inteligência <color=#FFB400>Tenente Philyshy</color> é encarregado de supervisionar as rotinas diárias do esquadrão, bem como as comunicações.",
  ui_story_1021_10210201_60_dialog_content = "Além disso, nosso pessoal da reserva militar está passando por inspeções finais. Eles oferecerão um sólido apoio à equipe de expedição.",
  ui_story_1021_10210201_61_dialog_content = "Dada a informação fornecida, nós de Lumópolis enviaremos esquadrões de elite para limpar obstáculos para as equipes subsequentes.",
  ui_story_1021_10210201_62_dialog_content = "...",
  ui_story_1021_10210201_63_dialog_content = "(Esquadrões de elite? Lumopolis também busca um papel de liderança na expedição, pelo que vejo. Acho que até mesmo Carleen não faz ideia do que o Lorde da Cidade está planejando...)",
  ui_story_1021_10210201_64_dialog_content = "Os esquadrões de Lumópolis lutarão ao lado de todos e se esforçarão para fornecer total apoio à expedição.",
  ui_story_1021_10210201_65_dialog_content = "Sim. Nossas munições estão prontas para ir, apenas esperando pelo sinal.",
  ui_story_1021_10210201_66_dialog_content = "Ahem, ahem... A Guilda Umbraton também tem abundantes suprimentos prontos. Nossas caravanas irão entregá-los ao ponto de partida.",
  ui_story_1021_10210201_67_dialog_content = "Mesmo que Umbraton seja inexperiente com esse tipo de operação, preparamos provisões suficientes para durar uma <color=#FFB400>equipe de expedição</color> por um ano.",
  ui_story_1021_10210201_68_dialog_content = "Obrigado pela sua generosidade.",
  ui_story_1021_10210201_69_dialog_content = "Isso é um ganha-ganha para Umbraton, até onde eu sei.",
  ui_story_1021_10210201_70_dialog_content = "Vamos notificar a todos o cronograma específico o mais rápido possível.",
  ui_story_1021_10210201_71_dialog_content = "(Isso é o que você chamaria de \"contribuir com o que puder\"...)",
  ui_story_1021_10210201_72_dialog_content = "Você tem algo a dizer, PlayerName?",
  ui_story_1021_10210201_73_dialog_content = "Bem, não tenho nada a oferecer, exceto a vontade de proteger os amigos!",
  ui_story_1021_10210201_74_dialog_content = "Para onde estamos indo é cheio de perigos, mas vou garantir que minha equipe esteja segura.",
  ui_story_1021_10210201_75_dialog_content = "Não vou deixar meus companheiros de equipe se machucarem ou se perderem por algum motivo...",
  ui_story_1021_10210201_76_dialog_content = "...",
  ui_story_1021_10210201_77_dialog_content = "(Eu disse algo errado?)",
  ui_story_1021_10210201_78_dialog_content = "Sinta-se à vontade para informar à guilda se precisar de algo, PlayerName.",
  ui_story_1021_10210201_79_dialog_content = "Obrigado, Bethel. Vou manter isso em mente.",
  ui_story_1021_10210201_80_dialog_content = "Agora que terminamos com o tema principal, permita-me sair pela tangente.",
  ui_story_1021_10210201_81_dialog_content = "Quando eu era jovem, eu esperava que pudesse visitar pessoalmente qualquer lugar que eu quisesse quando me tornasse o Senhor da Cidade de Lumopolis.",
  ui_story_1021_10210201_82_dialog_content = "Em retrospectiva, no entanto, demorei todo esse tempo apenas para administrar a cidade de maneira adequada.",
  ui_story_1021_10210201_83_dialog_content = "Então, publicamente, eu gostaria de ver muito mais do mundo através dos olhos de vocês, jovens, enquanto ainda estou vivo.",
  ui_story_1021_10210201_84_dialog_content = "Em particular, mesmo que esta seja uma viagem desafiadora, espero que Carleen possa se juntar a você para testemunhar o nascimento de uma nova era.",
  ui_story_1021_10210201_85_dialog_content = "Meu senhor...",
  ui_story_1021_10210201_86_dialog_content = "Você acredita que a expedição irá anunciar uma nova era?",
  ui_story_1021_10210201_87_dialog_content = "Claro. Ou devo dizer que uma nova era já começou quando você começou a desvendar um mistério após o outro em Astra.",
  ui_story_1021_10210201_88_dialog_content = "Estamos cem por cento por trás da expedição, porque o futuro de Astra já está em suas mãos.",
  ui_story_1021_10210201_89_dialog_content = "Me ajude, Roy! Eu não posso fazer isso tudo sozinho.",
  ui_story_1021_10210201_90_dialog_content = "Dizem que quando você envelhece, se contenta com restos, mas para mim, tudo o que consigo pensar é em qual molho vai acompanhar meu bife esta noite.",
  ui_story_1021_10210201_91_dialog_content = "Atchim!",
  ui_story_1021_10210201_92_dialog_content = "Esta aeronave Illumina pode ser nova, mas a tecnologia tem um cheiro tão forte quanto pó de pimenta... Atchim!",
  ui_story_1021_10210201_93_dialog_content = "Honcho Sinsa sempre cobre todas as suas bases. Ele está muito interessado na expedição do Celestita, então temos que estudar isso - pode ser útil!",
  ui_story_1021_10210201_94_dialog_content = "Vejo que Sinsa ainda mete o nariz onde não é chamado... Temos que ir, Tiny One!",
  ui_story_1021_10210201_95_dialog_content = "As máquinas novas precisam de tempo para perder o cheiro, então espero que você não se importe, Capitão.",
  ui_story_1021_10210201_96_dialog_content = "Ah, tudo bem. Os cheiros não me incomodam.",
  ui_story_1021_10210201_97_dialog_content = "Recebi uma mensagem da Queen do Norte esta manhã, informando que a construção do posto avançado seria adiada por alguns dias. Ela não deu detalhes específicos, e não era meu lugar como aliado perguntar.",
  ui_story_1021_10210201_98_dialog_content = "Mas a expedição requer que todos os postos avancem em uníssono, e a Illumina não pode poupar mais nenhum corpo.",
  ui_story_1021_10210201_99_dialog_content = "Portanto, preciso que você faça uma corrida para mim.",
  ui_story_1021_10210201_100_dialog_content = "Claro. Tanta coisa aconteceu recentemente, e faz muito tempo que não vou a Northland.",
  ui_story_1021_10210201_101_dialog_content = "Isso é perfeito. PlayerName pode te familiarizar com a operação da aeronave também.",
  ui_story_1021_10210201_102_dialog_content = "Você pode contar comigo. Embora seja diferente de Soroz, grande parte do design me parece familiar o suficiente.",
  ui_story_1021_10210201_103_dialog_content = "É por isso que já vi metade do Astra sozinho.",
  ui_story_1021_10210201_104_dialog_content = "Muito obrigado. Entre em contato comigo se houver algum problema. O sistema de comm foi configurado.",
  ui_story_1021_10210201_105_dialog_content = "Tenha uma viagem segura!",
  ui_story_1021_10210201_106_dialog_content = "Pode deixar!",
  ui_story_1021_10210201_107_dialog_content = "Devemos dizer ao PlayerName que há dois caras da Rediesel Wrench a bordo, Grande Marechal?",
  ui_story_1021_10210201_108_dialog_content = "Não. Isso acontece com bastante frequência em expedições. Eles podem lidar com isso.",
  ui_story_1021_10210201_109_dialog_content = "Além disso, a Rediesel Wrench não estava clamando para se juntar à operação por conta própria?",
  ui_story_1021_10210301_1_dialog_content = "<color=#e8d9bb>Um tempo depois...</color>",
  ui_story_1021_10210301_2_dialog_content = "Eu estava preocupado que não conseguiria me acostumar a pilotar uma aeronave Illumina.",
  ui_story_1021_10210301_3_dialog_content = "Mas, apesar de ser muito menor, é bastante semelhante a Soroz. Antes que eu perceba, estamos quase chegando a Northland.",
  ui_story_1021_10210301_4_dialog_content = "Como eu te disse, isso não seria um problema.",
  ui_story_1021_10210301_5_dialog_content = "Antes de pousarmos, você gostaria de tentar pilotar? Você viu como foi simples quando decolamos.",
  ui_story_1021_10210301_6_dialog_content = "Bem, claro, apenas me guie nisso.",
  ui_story_1021_10210301_7_dialog_content = "Ok, então primeiro, o painel de controle aqui vai mostrar—",
  ui_story_1021_10210301_8_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_1021_10210301_9_dialog_content = "Ah!",
  ui_story_1021_10210301_10_dialog_content = "O que está acontecendo? Eu nem toquei em nada!",
  ui_story_1021_10210301_11_dialog_content = "Fique calmo! Provavelmente é apenas turbulência...",
  ui_story_1021_10210301_12_dialog_content = "Estamos mergulhando... Apenas puxe a alavanca, então—",
  ui_story_1021_10210301_13_dialog_content = "<color=#e8d9bb>Bip, bip, bip...</color>",
  ui_story_1021_10210301_14_dialog_content = "Essa não!",
  ui_story_1021_10210301_15_dialog_content = "<color=#e8d9bb>Bip, bip, bip...</color>",
  ui_story_1021_10210301_16_dialog_content = "Você encontrou, Roy? Talvez devêssemos simplesmente sair e assumir o controle da embarcação.",
  ui_story_1021_10210301_17_dialog_content = "Sair agora só vai piorar as coisas. Eu... vou terminar aqui em um segundo... Não, eu não consigo ter vantagem no escuro.",
  ui_story_1021_10210301_18_dialog_content = "Eu tenho uma luz bem aqui!",
  ui_story_1021_10210301_19_dialog_content = "Isso realmente deslumbra... Onde estamos agora?",
  ui_story_1021_10210301_20_dialog_content = "Pelo menos a algumas centenas de milhas do Deserto Rediesel. Está ficando cada vez mais branco lá fora. Poderíamos estar em Northland...",
  ui_story_1021_10210301_21_dialog_content = "Nesse caso, não é incomum encontrar turbulência.",
  ui_story_1021_10210301_22_dialog_content = "Hmm, a construção é diferente do que eu imaginei. Não acho que consigo consertar.",
  ui_story_1021_10210301_23_dialog_content = "O que você quer dizer com \"diferente\"? Isso é vida ou morte! Deixe-me dar uma olhada!",
  ui_story_1021_10210301_24_dialog_content = "Você disse que é um problema com o elevador, certo?",
  ui_story_1021_10210301_25_dialog_content = "Sim, mais ou menos. Não vejo nenhum eixo de transmissão nesta aeronave Illumina.",
  ui_story_1021_10210301_26_dialog_content = "... Isso é porque está quebrado!",
  ui_story_1021_10210301_27_dialog_content = "Entendi... Deixe-me vasculhar meu bolso por algo útil enquanto você tenta se virar com uma chave inglesa por enquanto.",
  ui_story_1021_10210301_28_dialog_content = "Você não tem senso de perigo iminente, tem?",
  ui_story_1021_10210301_29_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_1021_10210301_30_dialog_content = "Ugh!",
  ui_story_1021_10210301_31_dialog_content = "Acabou agora! Você está bem?",
  ui_story_1021_10210301_32_dialog_content = "Onde está Carleen? Eu vejo manchas de sangue. Não me diga... Carleen!",
  ui_story_1021_10210301_33_dialog_content = "!",
  ui_story_1021_10210301_34_dialog_content = "Eu nunca mais vou andar em uma aeronave!",
  ui_story_1021_10210301_35_dialog_content = "(Acho que ela está bem...)",
  ui_story_1021_10210301_36_dialog_content = "Tudo bem, chega. É tudo culpa minha.",
  ui_story_1021_10210301_37_dialog_content = "Mas, francamente, eu não esperava que a turbulência fosse tão forte aqui em Northland.",
  ui_story_1021_10210301_38_dialog_content = "...",
  ui_story_1021_10210301_39_dialog_content = "Faz parte da aventura, no entanto...",
  ui_story_1021_10210301_40_dialog_content = "Felizmente, a alavanca respondeu no último segundo.",
  ui_story_1021_10210301_41_dialog_content = "Uau, não acredito que pousamos em segurança mesmo com o leme dobrado neste ângulo...",
  ui_story_1021_10210301_42_dialog_content = "Está pescando elogios para sua habilidade de pilotagem?",
  ui_story_1021_10210301_43_dialog_content = "Err, eu não sei como responder isso...",
  ui_story_1021_10210301_44_dialog_content = "<color=#e8d9bb>Awooo—</color>",
  ui_story_1021_10210301_45_dialog_content = "Este é um campo de caça para animais? Há sangue por toda parte...",
  ui_story_1021_10210301_46_dialog_content = "Parece que uma luta ocorreu aqui recentemente. Ainda devemos estar longe do Palácio Invernal. Talvez isso seja obra dos Eclipsitas...",
  ui_story_1021_10210301_47_dialog_content = "Eclipsitas? Então estamos fora do alcance do Farol.",
  ui_story_1021_10210301_48_dialog_content = "A terra não coberta pelo Farol aqui é muito maior do que você pensa, especialmente o norte, onde os Eclipsitas correm desenfreados...",
  ui_story_1021_10210301_49_dialog_content = "Eu só ouvi histórias sobre isso e nunca pensei que seria tão assustador pessoalmente...",
  ui_story_1021_10210301_50_dialog_content = "...",
  ui_story_1021_10210301_51_dialog_content = "... Eu ouço alguém!",
  ui_story_1021_10210301_52_dialog_content = "Vamos dar uma olhada.",
  ui_story_1021_10210301_53_dialog_content = "Hunf!",
  ui_story_1021_10210301_54_dialog_content = "Vamos lá, garotinha, não me olhe assim! Eu te disse, fomos forçados a estar aqui.",
  ui_story_1021_10210301_55_dialog_content = "Minha licença de piloto ainda está na aeronave. Espere aqui e eu vou buscá-la para você...",
  ui_story_1021_10210301_56_dialog_content = "Temos licenças, Roy?",
  ui_story_1021_10210301_57_dialog_content = "Sempre é problemático trazer novatos junto. Você perdeu sua licença de novo, não foi? Deixe-me ir encontrá-la para você agora mesmo!",
  ui_story_1021_10210301_58_dialog_content = "Alto!",
  ui_story_1021_10210301_59_dialog_content = "Deixe-os ir.",
  ui_story_1021_10210301_60_dialog_content = "Ancião! O que você está fazendo aqui? Você não é—",
  ui_story_1021_10210301_61_dialog_content = "Não se preocupe comigo.",
  ui_story_1021_10210301_62_dialog_content = "Mas isso é o que a tribo se tornou da noite para o dia. Como eu não posso me preocupar? Você não viu o sangue escuro escorrendo daqueles pobres raposas?",
  ui_story_1021_10210301_63_dialog_content = "Você não deveria ter vindo.",
  ui_story_1021_10210301_64_dialog_content = "Por que você sempre me diz para ficar longe? Esta é a minha casa!",
  ui_story_1021_10210301_65_dialog_content = "... Tiare?",
  ui_story_1021_10210301_66_dialog_content = "Agora venha, proteja-se atrás deste escudo.",
  ui_story_1021_10210301_67_dialog_content = "Estou negligente em meu dever como guarda de Sua Majestade!",
  ui_story_1021_10210301_68_dialog_content = "Por favor, não me deixe para trás e lute contra os Eclipsitas sozinho novamente!",
  ui_story_1021_10210301_69_dialog_content = "Permita-me ser sua valente vanguarda, Sua Majestade!",
  ui_story_1021_10210301_70_dialog_content = "Guarda de Queen...",
  ui_story_1021_10210301_71_dialog_content = "É você...",
  ui_story_1021_10210301_72_dialog_content = "O que você está fazendo aqui? E o que aconteceu?",
  ui_story_1021_10210301_73_dialog_content = "...",
  ui_story_1021_10210301_74_dialog_content = "(Isso é uma lendária raposa da neve? Está me encarando como se quisesse que eu fosse embora.)",
  ui_story_1021_10210301_75_dialog_content = "Viemos visitar Sua Majestade, mas nossa aeronave encontrou uma turbulência forte e foi forçada a pousar aqui.",
  ui_story_1021_10210301_76_dialog_content = "...",
  ui_story_1021_10210301_77_dialog_content = "... Por favor, desculpe-nos por perturbá-lo.",
  ui_story_1021_10210301_78_dialog_content = "Esses dois estão com você?",
  ui_story_1021_10210301_79_dialog_content = "Do que você está falando?",
  ui_story_1021_10210301_80_dialog_content = "Eles estavam aqui agora mesmo!",
  ui_story_1021_10210301_81_dialog_content = "Eles fizeram gestos para meus amigos com objetos estranhos na mão e afirmaram ser pilotos da aeronave.",
  ui_story_1021_10210301_82_dialog_content = "Mas era só eu e Carleen naquele veículo!",
  ui_story_1021_10210301_83_dialog_content = "Impossível!",
  ui_story_1021_10210301_84_dialog_content = "Vai com calma, Tiare.",
  ui_story_1021_10210301_85_dialog_content = "Se eles machucarem você ou seus amigos, PlayerName e eu não vamos deixar isso passar impune.",
  ui_story_1021_10210301_86_dialog_content = "Mas eu ouvi você mencionar \"esta é a sua casa\"?",
  ui_story_1021_10210301_87_dialog_content = "Esta é a fronteira de Northland, frequentada pelos Eclipsitas...",
  ui_story_1021_10210301_88_dialog_content = "Estou... seguindo a ordem da rainha para verificar a Floresta Snowpine.",
  ui_story_1021_10210301_89_dialog_content = "Entendi. Você se importaria de nos levar até Sua Majestade quando terminar?",
  ui_story_1021_10210301_90_dialog_content = "Não conseguimos encontrar o caminho para o Palácio Invernal, mas com certeza podemos ajudar se os Eclipsitas aparecerem!",
  ui_story_1021_10210301_91_dialog_content = "<color=#e8d9bb>Auuuuu!</color>",
  ui_story_1021_10210301_92_dialog_content = "Não!",
  ui_story_1021_10210301_93_dialog_content = "Quero dizer, é muito longe do palácio e muito perigoso aqui, então você deveria ir embora.",
  ui_story_1021_10210301_94_dialog_content = "Isso...",
  ui_story_1021_10210301_95_dialog_content = "(Definitivamente tem algo errado com Tiare...)",
  ui_story_1021_10210301_96_dialog_content = "Você pode nos dizer o que aconteceu aqui?",
  ui_story_1021_10210301_97_dialog_content = "...",
  ui_story_1021_10210301_98_dialog_content = "Você não está aqui pela rainha?",
  ui_story_1021_10210301_99_dialog_content = "Basta seguir as pegadas daquele coelho e você a verá.",
  ui_story_1021_10210301_100_dialog_content = "Quando fizer isso, por favor avise a ela... que eu vou limpar as pegadas, mas não agora.",
  ui_story_1021_10210301_101_dialog_content = "...",
  ui_story_1021_10210301_102_dialog_content = "E ela se foi num piscar de olhos...",
  ui_story_1021_10210301_103_dialog_content = "Nunca pensei que a Tribo Fox da Neve realmente existisse em Northland...",
  ui_story_1021_10210301_104_dialog_content = "Quando eu estudava em Northland, ouvi algumas pessoas locais dizerem...",
  ui_story_1021_10210301_105_dialog_content = "Havia um assentamento no extremo noroeste onde raposas da neve se reuniam e viviam da Floresta Nevosa de Pinho.",
  ui_story_1021_10210301_106_dialog_content = "Eles protegeram as florestas e as ruínas abaixo.",
  ui_story_1021_10210301_107_dialog_content = "Mas, como ninguém nunca viu com os próprios olhos, ninguém tinha certeza se era fato ou mito. A parte fóbica dos aurorianos, no entanto, parece ser verdade...",
  ui_story_1021_10210301_108_dialog_content = "Você notou as raposas feridas se refugiando atrás do Tiare?",
  ui_story_1021_10210301_109_dialog_content = "Sim, e aquela raposa da neve mais velha nos encarou como se fôssemos seus inimigos mortais.",
  ui_story_1021_10210301_110_dialog_content = "As raposas devem ter deixado as manchas de sangue.",
  ui_story_1021_10210301_111_dialog_content = "Algumas das manchas são pretas, algumas vermelhas, e isso está me deixando enjoado...",
  ui_story_1021_10210301_112_dialog_content = "Diz-se que algumas raposas da neve são \"espíritos da montanha\" nascidos do poder da natureza, e quando são contaminadas pelo Fluxo Escuro, seus corpos também sofrem mutações.",
  ui_story_1021_10210301_113_dialog_content = "Provavelmente você não está se sentindo bem por causa do Darkflow nas manchas de sangue.",
  ui_story_1021_10210301_114_dialog_content = "Fluxo Escuro? Então há mais na mensagem que ela queria que passássemos para a rainha.",
  ui_story_1021_10210301_115_dialog_content = "Dado tudo o que sabemos, os Eclipsitas provavelmente invadiram Northland e não só feriram as raposas, mas também destruíram o posto avançado.",
  ui_story_1021_10210301_116_dialog_content = "Então é por isso que Sua Majestade ainda não enviou nenhum representante...",
  ui_story_1021_10210301_117_dialog_content = "Isso também coloca Tiare em grande perigo!",
  ui_story_1021_10210301_118_dialog_content = "Devemos alcançá-la, para que possamos ajudar se ela se meter em apuros.",
  ui_story_1021_10210301_119_dialog_content = "Vamos seguir o rastro de sangue! Esta área está repleta de Eclipsitas, então devemos ter cuidado!",
  ui_story_1021_10210401_1_dialog_content = "A trilha termina aqui... Não sei se é o sangue ou algo assim, mas minha cabeça está começando a girar...",
  ui_story_1021_10210401_2_dialog_content = "Deixe-me... tentar minha habilidade psíquica...",
  ui_story_1021_10210401_3_dialog_content = "PlayerName, eu sei que você não usou desde o que aconteceu da última vez. Então, tem certeza?",
  ui_story_1021_10210401_4_option_content = "Sim...",
  ui_story_1021_10210401_5_dialog_content = "Na verdade, por um longo tempo, me sinto inseguro quando penso em usar habilidades psíquicas...",
  ui_story_1021_10210401_6_option_content = "Ainda estou um pouco nervoso.",
  ui_story_1021_10210401_7_dialog_content = "Desde então, a ideia de usar habilidades psíquicas tem me torturado por dentro...",
  ui_story_1021_10210401_8_dialog_content = "Você está preocupado com o que vai ver e que pode chamar a atenção do Engenheiro novamente?",
  ui_story_1021_10210401_9_dialog_content = "Sim. Também estou preocupado que eu possa ver ou ouvir más notícias sobre Vice ou Soroz...",
  ui_story_1021_10210401_10_dialog_content = "Eu sei que o que aconteceu teve um grande impacto em você, mas—",
  ui_story_1021_10210401_11_dialog_content = "Mas as habilidades psíquicas são o que eu uso para lutar e como eu protejo todos.",
  ui_story_1021_10210401_12_dialog_content = "De qualquer forma, eu tenho que superar meus medos e melhorar meu controle!",
  ui_story_1021_10210401_13_dialog_content = "Então, agradeço a preocupação, Carleen. Estou bem agora.",
  ui_story_1021_10210401_14_dialog_content = "Estou feliz em ver que você voltou tão cedo, PlayerName. Estou realmente feliz por você.",
  ui_story_1021_10210401_15_dialog_content = "Lembre-se, estou aqui com você. Se algo der errado, vamos enfrentar isso juntos.",
  ui_story_1021_10210401_16_dialog_content = "Sim!",
  ui_story_1021_10210401_17_option_content = "Ligação Telepática—",
  ui_story_1021_10210401_18_dialog_content = "(Grande caverna vazia...)",
  ui_story_1021_10210401_19_dialog_content = "(Essas geleiras existem há muito tempo.)",
  ui_story_1021_10210401_20_dialog_content = "... Ela ganharia o Rally Rediesel se ela se inscrevesse.",
  ui_story_1021_10210401_21_dialog_content = "Duas pernas não podem competir com quatro rodas! Espere, você está sentindo algum cheiro forte?",
  ui_story_1021_10210401_22_dialog_content = "(As vozes... De onde elas vieram?)",
  ui_story_1021_10210401_23_dialog_content = "(Manchas de sangue preto e vermelho, assim como as do chão acima!)",
  ui_story_1021_10210401_24_dialog_content = "(Pelo menos eu ainda tenho controle sobre minha própria mente...)",
  ui_story_1021_10210401_25_dialog_content = "(Ah, e Tiare estava aqui... Essa caverna fica abaixo da Floresta Snowpine?)",
  ui_story_1021_10210401_26_dialog_content = "O fedor de podridão me lembra o Rediesel que sinto tanta falta...",
  ui_story_1021_10210401_27_dialog_content = "Desligue a luz antes que ela atraia algo estranho. Eu não quero passar por esse frio à toa.",
  ui_story_1021_10210401_28_dialog_content = "Por que temos que nos esconder aqui? Agora nem conseguimos encontrar alguém para nos dar direções.",
  ui_story_1021_10210401_29_dialog_content = "Você não disse que odiava o subsolo mais que tudo, Roy?",
  ui_story_1021_10210401_30_dialog_content = "(Aqueles dois?)",
  ui_story_1021_10210401_31_dialog_content = "(Há muitos desvios por aí, então como eles chegaram lá?)",
  ui_story_1021_10210401_32_option_content = "Alcance Telepático—",
  ui_story_1021_10210401_33_dialog_content = "...",
  ui_story_1021_10210401_34_dialog_content = "O que você viu?",
  ui_story_1021_10210401_35_dialog_content = "Os intrusos mencionados por Tiare são dois dos meus amigos da Rediesel.",
  ui_story_1021_10210401_36_dialog_content = "Depois de expandir minha visão, acho que vi um aglomerado de Darkflow se expandindo como vapor inchado.",
  ui_story_1021_10210401_37_dialog_content = "Está muito perto de nós...",
  ui_story_1021_10210401_38_dialog_content = "!",
  ui_story_1021_10210401_39_dialog_content = "Há manchas de sangue idênticas às do chão também. Tiare também deve estar dentro daquela caverna.",
  ui_story_1021_10210401_40_dialog_content = "Então temos que nos apressar e chegar até eles! Para qual lado vamos agora?",
  ui_story_1021_10210401_41_dialog_content = "A trilha termina aqui, então a caverna deve estar atrás desses pinheiros cobertos de neve. Siga-me!",
  ui_story_1021_10210401_42_dialog_content = "(Tiare, Roy e Tiny One também... Espero que nada de ruim aconteça com vocês!)",
  ui_story_1021_10210401_43_dialog_content = "<color=#e8d9bb>Awooo...</color>",
  ui_story_1021_10210401_44_dialog_content = "Ó grande divindade antiga, sempre olhei para você como você sempre olhou por nós.",
  ui_story_1021_10210401_45_dialog_content = "As sombras da escuridão desceram mais uma vez, contaminando nossos corpos como predadores e deixando marcas indeléveis.",
  ui_story_1021_10210401_46_dialog_content = "No Palácio Invernal, eu sou um Guarda do Queen...",
  ui_story_1021_10210401_47_dialog_content = "Mas aqui, eu sou um líder jurado a proteger a tribo.",
  ui_story_1021_10210401_48_dialog_content = "Você nutriu a tribo e nos concedeu uma linhagem sagrada, permitindo-nos conectar com sua presença divina.",
  ui_story_1021_10210401_49_dialog_content = "Mas agora, os poucos membros da tribo que restam vivem dia e noite em agonia, seus corpos desmoronando. Eu sei que um dia voltaremos para o seu abraço.",
  ui_story_1021_10210401_50_dialog_content = "May você lança seu olhar compassivo sobre nós novamente, como quando abençoou nossos ancestrais e a tribo antes.",
  ui_story_1021_10210401_51_dialog_content = "<color=#e8d9bb>Auuuuu!</color>",
  ui_story_1021_10210401_52_dialog_content = "Aqueles Aurorianos que invadiram inadvertidamente estão em perigo. Eu não tenho mais nada para mantê-los afastados novamente...",
  ui_story_1021_10210401_53_dialog_content = "Isso deveria ser meu dever, ancião...",
  ui_story_1021_10210401_54_dialog_content = "Tiare, olhe para a lança em sua mão! Você é um guarda de Northland... Por favor, deixe de lado todas as preocupações que você tem por este lugar...",
  ui_story_1021_10210401_55_dialog_content = "*tosse*",
  ui_story_1021_10210401_56_dialog_content = "Eu imploro a você, ancião... Eu não posso apenas assistir minha tribo e meu povo morrerem...",
  ui_story_1021_10210401_57_dialog_content = "Você... não deveria ter voltado...",
  ui_story_1021_10210401_58_dialog_content = "O que eu deveria fazer agora...",
  ui_story_1021_10210401_59_dialog_content = "<color=#e8d9bb>Gotejamento, gotejamento...</color>",
  ui_story_1021_10210401_60_dialog_content = "Ai!",
  ui_story_1021_10210401_61_dialog_content = "Tenha cuidado, o caminho gelado está muito escorregadio. Espere, por que está pingando água?",
  ui_story_1021_10210401_62_dialog_content = "Já pisei em várias poças seguidas. O cheiro horrível provavelmente me afetou e me fez tropeçar na última.",
  ui_story_1021_10210401_63_dialog_content = "Espere, acho que acabei de pisar em algo fofo e macio... Dê uma olhada para mim.",
  ui_story_1021_10210401_64_dialog_content = "Parece que é... uma raposa da neve.",
  ui_story_1021_10210401_65_dialog_content = "Ainda está vivo?",
  ui_story_1021_10210401_66_dialog_content = "...",
  ui_story_1021_10210401_67_dialog_content = "Oh, eu estou acabado. Estou vendo uma luz branca...",
  ui_story_1021_10210401_68_dialog_content = "Saia disso. Na verdade, há uma luz à frente.",
  ui_story_1021_10210401_69_dialog_content = "<color=#e8d9bb>Gotejamento, gotejamento...</color>",
  ui_story_1021_10210401_70_dialog_content = "Estou delirando, Tiny One? Parece que vamos chegar em casa se continuarmos andando assim.",
  ui_story_1021_10210401_71_dialog_content = "Está ficando mais quente também... e de alguma forma meus músculos relaxam muito.",
  ui_story_1021_10210401_72_dialog_content = "Nesse caso, vou deixar você carregar essa bolsa de gemas.",
  ui_story_1021_10210401_73_dialog_content = "O que você está dizendo? Como você pode simplesmente desistir de gemas grátis assim?",
  ui_story_1021_10210401_74_dialog_content = "Ei, não toque na minha cabeça. Suas mãos estão pegajosas de suor!",
  ui_story_1021_10210401_75_dialog_content = "Por que você... Urgh, não consigo manter meus olhos abertos neste brilho repentino... Não te disse que luzes brilhantes atraem problemas?",
  ui_story_1021_10210401_76_dialog_content = "Ei, vocês dois!",
  ui_story_1021_10210401_77_dialog_content = "Falando de problemas...",
  ui_story_1021_10210401_78_dialog_content = "Olá.",
  ui_story_1021_10210401_79_dialog_content = "Oi, PlayerName. Você também está caçando tesouros?",
  ui_story_1021_10210401_80_dialog_content = "Caçando tesouros? Por que você se esgueirou a bordo de nossa aeronave?",
  ui_story_1021_10210401_81_dialog_content = "Sinsa esqueceu de entregar o formulário de inscrição ou algo assim? Estamos representando a Rediesel Wrench na conferência de expedição conjunta.",
  ui_story_1021_10210401_82_dialog_content = "Quem diria que a reunião era tão chata que acabamos aqui depois de acordar de uma soneca...",
  ui_story_1021_10210401_83_dialog_content = "Dado essa mochila enorme, é mais provável que você esteja em Northland para roubar as gemas! Aconselho que você as devolva para onde as encontrou!",
  ui_story_1021_10210401_84_dialog_content = "O quê, estamos em Northland? Sinceramente, eu nunca saí do Deserto de Rediesel, muito menos sabia que havia gemas aqui!",
  ui_story_1021_10210401_85_dialog_content = "Mas eu consertei seu veículo para você, então vou aceitar essa sacola como um sinal de seu agradecimento.",
  ui_story_1021_10210401_86_dialog_content = "Por que você-",
  ui_story_1021_10210401_87_dialog_content = "Acho que sei o que aconteceu, Carleen.",
  ui_story_1021_10210401_88_dialog_content = "Eles estão entre os melhores mecânicos da Rediesel Wrench, e há uma sala de manutenção na aeronave perto do leme de direção, bem longe da cabine de comando.",
  ui_story_1021_10210401_89_dialog_content = "Pousamos em segurança mesmo com o leme torcido como estava... Talvez eles estivessem escondidos naquela sala e nos fizeram um favor...",
  ui_story_1021_10210401_90_dialog_content = "Você acha?",
  ui_story_1021_10210401_91_dialog_content = "Então, sobre a aeronave... obrigado.",
  ui_story_1021_10210401_92_dialog_content = "Não se preocupe. Estamos em uma expedição juntos, temos que cuidar um do outro!",
  ui_story_1021_10210401_93_dialog_content = "<color=#e8d9bb>Gotejamento, gotejamento...</color>",
  ui_story_1021_10210401_94_dialog_content = "Primeiro as primeiras coisas. Quando voltarmos, posso te dar Noitium, mas deixe as gemas em Northland.",
  ui_story_1021_10210401_95_dialog_content = "Nightium, você diz... Acho que isso servirá.",
  ui_story_1021_10210401_96_dialog_content = "É muito perigoso aqui. Roy, Tiny One, você sabe para onde foi a garota com as raposas de neve?",
  ui_story_1021_10210401_97_dialog_content = "Sim, mas ela estava se movendo rápido demais para nós conseguirmos acompanhar!",
  ui_story_1021_10210401_98_dialog_content = "Na verdade, estávamos tentando fugir dela...",
  ui_story_1021_10210401_99_dialog_content = "Há muitos cadáveres de raposas na caverna, PlayerName. Muitas das raposas que estavam com ela também ficaram gravemente feridas.",
  ui_story_1021_10210401_100_dialog_content = "Então temos que encontrá-la o mais rápido possível.",
  ui_story_1021_10210401_101_dialog_content = "Já que você conhece o caminho, mostre-o.",
  ui_story_1021_10210401_102_dialog_content = "Não tivemos problemas aqui fora, mas mais para dentro sim. Muitas bifurcações... Quase nos perdemos também.",
  ui_story_1021_10210401_103_dialog_content = "Roy, minha luz...",
  ui_story_1021_10210401_104_dialog_content = "Escureceu?",
  ui_story_1021_10210401_105_dialog_content = "Isso significa que o Darkflow está ficando mais forte.",
  ui_story_1021_10210401_106_dialog_content = "Por mais que eu goste de lugares mais quentes, sinto muito, PlayerName, Senhorita Nightium, estou saindo com Tiny One!",
  ui_story_1021_10210401_107_dialog_content = "Não acredito. Eles acabaram de dizer que deveríamos ajudar uns aos outros... Qual caminho devemos seguir agora?",
  ui_story_1021_10210401_108_dialog_content = "Deixe-me usar minha habilidade psíquica.",
  ui_story_1021_10210401_109_option_content = "Alcance Telepático—",
  ui_story_1021_10210401_110_dialog_content = "Ganância, raiva, obsessão... todas ilusões que causam sofrimento da mente e do corpo.",
  ui_story_1021_10210401_111_dialog_content = "A raiva se transforma em fúria. A fúria se transforma em aflição.",
  ui_story_1021_10210401_112_dialog_content = "Sim, sim...",
  ui_story_1021_10210401_113_dialog_content = "O fanfarronismo... é ainda mais contido...",
  ui_story_1021_10210401_114_dialog_content = "(Um Eclipsite?)",
  ui_story_1021_10210401_115_dialog_content = "(Muito nebuloso para eu distinguir, mas o que acabei de sentir...)",
  ui_story_1021_10210401_116_dialog_content = "(O Darkflow ao redor... Minha cabeça... parece que está sendo socada por um punho...)",
  ui_story_1021_10210401_117_dialog_content = "Meu senhor!",
  ui_story_1021_10210401_118_dialog_content = "Sim?",
  ui_story_1021_10210401_119_dialog_content = "Graah!",
  ui_story_1021_10210401_120_dialog_content = "(!)",
  ui_story_1021_10210401_121_dialog_content = "...",
  ui_story_1021_10210401_122_dialog_content = "Restrição... Restrição...",
  ui_story_1021_10210401_123_dialog_content = "M-Meu senhor...",
  ui_story_1021_10210401_124_dialog_content = "Não se preocupe e venha mais perto. Eu não vou te machucar.",
  ui_story_1021_10210401_125_dialog_content = "Sim...",
  ui_story_1021_10210401_126_dialog_content = "Meu senhor... Há aurorianos repreensíveis por perto...",
  ui_story_1021_10210401_127_dialog_content = "...",
  ui_story_1021_10210401_128_dialog_content = "Eu... Eu acredito que eles podem afetar sua meditação...",
  ui_story_1021_10210401_129_dialog_content = "Onde estou?",
  ui_story_1021_10210401_130_dialog_content = "Você passou pela fortaleza.",
  ui_story_1021_10210401_131_dialog_content = "<color=#FFB400>Terra Nevada</color>... Eu já fui longe o suficiente, de fato.",
  ui_story_1021_10210401_132_dialog_content = "Desde que mudou, eu nunca mais voltei.",
  ui_story_1021_10210401_133_dialog_content = "Mudou...",
  ui_story_1021_10210401_134_dialog_content = "A mudança é realmente uma privação sem coração!",
  ui_story_1021_10210401_135_dialog_content = "Meu senhor...",
  ui_story_1021_10210401_136_dialog_content = "Agradeço o lembrete oportuno... Restrição... Restrição...",
  ui_story_1021_10210401_137_dialog_content = "<color=#e8d9bb>Gotejamento, gotejamento...</color>",
  ui_story_1021_10210401_138_dialog_content = "O gelo aqui está derretendo, e é causado pelo Fluxo Escuro desse Eclipsita.",
  ui_story_1021_10210401_139_dialog_content = "O que você viu desta vez, PlayerName? Por que você parece preocupado?",
  ui_story_1021_10210401_140_dialog_content = "Eu vi aquele Eclipsite...",
  ui_story_1021_10210401_141_dialog_content = "Pensando bem, devemos ficar juntos!",
  ui_story_1021_10210401_142_dialog_content = "Você tem a audácia de voltar?",
  ui_story_1021_10210401_143_dialog_content = "Encontramos um monte de Eclipsitas por lá, PlayerName!",
  ui_story_1021_10210401_144_dialog_content = "Graaah!",
  ui_story_1021_10210401_145_dialog_content = "Cuidado, Carleen!",
  ui_story_1021_10210401_146_dialog_content = "Você os atraiu para nós!",
  ui_story_1021_10210401_147_dialog_content = "Fique atrás de mim, Tiny One!",
  ui_story_1021_10210401_148_dialog_content = "Está perto o suficiente para eu dizer que é um Darkflow normal, não o tipo avassalador que acabei de sentir...",
  ui_story_1021_10210401_149_dialog_content = "Não fique aí parado, PlayerName! Dê ordens para a batalha!",
  ui_story_1021_10210401_150_dialog_content = "Sim!",
  ui_story_1021_10210402_1_dialog_content = "O fim chega com o degelo.",
  ui_story_1021_10210402_2_dialog_content = "Tudo limpo!",
  ui_story_1021_10210402_3_dialog_content = "Todos estão bem?",
  ui_story_1021_10210402_4_dialog_content = "Vossa Majestade! O que está fazendo aqui?",
  ui_story_1021_10210402_5_dialog_content = "Eu estava no gêiser e senti seus Luminatics.",
  ui_story_1021_10210402_6_dialog_content = "<color=#e8d9bb>Há pouco tempo...</color>",
  ui_story_1021_10210402_7_dialog_content = "<color=#e8d9bb>Sploosh, sploosh... Bum!</color>",
  ui_story_1021_10210402_8_dialog_content = "Vossa Majestade, é isso—",
  ui_story_1021_10210402_9_dialog_content = "O <color=#FFB400>gêiser</color> da fronteira. Ele retomou o jorro novamente após anos de dormência - um mecanismo que revela as cicatrizes do passado de Northland exatamente no tempo certo...",
  ui_story_1021_10210402_10_dialog_content = "A água obsidiana que ela expele contém Fluxo Escuro e destruiu plantas, casas e aquela tribo inocente...",
  ui_story_1021_10210402_11_dialog_content = "Posso ver no espelho que a energia na Zona Escura tem estado cada vez mais ativa. Qual é o seu plano, Vossa Majestade?",
  ui_story_1021_10210402_12_dialog_content = "Quando a próxima erupção acabar, irei até a fonte e lidarei com aquele Eclipsite.",
  ui_story_1021_10210402_13_dialog_content = "Esse Espelho do Norte que você tem guarda abundante Lumina em reserva. Estou contando com você para suprimir a propagação do Darkflow depois que eu entrar.",
  ui_story_1021_10210402_14_dialog_content = "Sim, Vossa Majestade.",
  ui_story_1021_10210402_15_dialog_content = "<color=#e8d9bb>Sploosh, sploosh... Bum!</color>",
  ui_story_1021_10210402_16_dialog_content = "Hum?",
  ui_story_1021_10210402_17_dialog_content = "Por que você está carrancudo, Sua Majestade?",
  ui_story_1021_10210402_18_dialog_content = "Ninguém conhece melhor do que eu a maneira como ela manipula Lumina.",
  ui_story_1021_10210402_19_dialog_content = "Não posso esperar mais. Deixo o resto em suas mãos.",
  ui_story_1021_10210402_20_dialog_content = "... Sim, Vossa Majestade.",
  ui_story_1021_10210402_21_dialog_content = "Então, o gêiser em erupção causou a destruição.",
  ui_story_1021_10210402_22_dialog_content = "E o Fluxo Escuro atraiu hordas de Eclipsitas que prejudicaram as pequenas raposas de neve. Você provavelmente viu muitos indícios na caverna.",
  ui_story_1021_10210402_23_dialog_content = "Você deve sair antes da próxima erupção.",
  ui_story_1021_10210402_24_dialog_content = "Mas Sua Majestade, acabei de sentir um Eclipsita muito poderoso aqui...",
  ui_story_1021_10210402_25_dialog_content = "Viemos para confirmar os planos para o posto avançado de Northland, mas pousamos nas proximidades devido a um acidente.",
  ui_story_1021_10210402_26_dialog_content = "Então vimos Tiare com um bando de raposas feridas, e elas não pareciam bem...",
  ui_story_1021_10210402_27_dialog_content = "Estávamos preocupados com a segurança deles, então os seguimos até aqui. A propósito, onde estão os dois caras de Rediesel?",
  ui_story_1021_10210402_28_dialog_content = "...",
  ui_story_1021_10210402_29_dialog_content = "Vossa Majestade, isso está fora da jurisdição real...",
  ui_story_1021_10210402_30_dialog_content = "Você enviou seu guarda Tiare aqui para verificar os Eclipsitas?",
  ui_story_1021_10210402_31_dialog_content = "\"Queen's Guard\" é um título que Tiare modelou após a Guarda Real e deu a si mesma.",
  ui_story_1021_10210402_32_dialog_content = "Para se tornar uma Guarda Real, ela ainda precisa descobrir o que significa defender Northland, uma questão eterna perseguida pelo povo desta terra.",
  ui_story_1021_10210402_33_dialog_content = "Senhor Novio!",
  ui_story_1021_10210402_34_dialog_content = "Carleen, PlayerName.",
  ui_story_1021_10210402_35_dialog_content = "Já que você está aqui, eu sei o que aconteceu.",
  ui_story_1021_10210402_36_dialog_content = "Você sabia há muito tempo que Tiare deixaria o Palácio de Inverno e retornaria para sua tribo.",
  ui_story_1021_10210402_37_dialog_content = "Tiare de fato é um membro da lendária Tribo da Neve Fox. Ela até parece ser—",
  ui_story_1021_10210402_38_dialog_content = "Tiare é o líder da Tribo da Neve Fox.",
  ui_story_1021_10210402_39_dialog_content = "O líder?",
  ui_story_1021_10210402_40_dialog_content = "Não há ninguém mais velho que ela na tribo agora?",
  ui_story_1021_10210402_41_dialog_content = "...",
  ui_story_1021_10210402_42_dialog_content = "Oh, Sua Majestade, Tiare nos pediu para informar que ela vai limpar as pegadas, mas não agora...",
  ui_story_1021_10210402_43_dialog_content = "O que ela quis dizer com isso?",
  ui_story_1021_10210402_44_dialog_content = "A eterna questão... embora nem mesmo eu tenha conseguido fazer isso...",
  ui_story_1021_10210402_45_dialog_content = "Você nunca negligenciou este lugar em todas as suas inspeções por Northland, Vossa Majestade.",
  ui_story_1021_10210402_46_dialog_content = "Este é o meu dever, Novio. Você os tira daqui enquanto eu rastreio Tiare.",
  ui_story_1021_10210402_47_dialog_content = "Já fiz o último, Vossa Majestade.",
  ui_story_1021_10210402_48_dialog_content = "Sim.",
  ui_story_1021_10210402_49_dialog_content = "Majestade, o forte Darkflow que senti está se aproximando!",
  ui_story_1021_10210402_50_dialog_content = "Sou eu de quem você está falando?",
  ui_story_1021_10210402_51_dialog_content = "A lâmina da Aurora!",
  ui_story_1021_10210402_52_dialog_content = "Rápido, abrigue-se no meu campo de Lúmina!",
  ui_story_1021_10210402_53_dialog_content = "Você é a autoproclamada Queen de Snowland? Vejo que perdi muitas coisas.",
  ui_story_1021_10210402_54_dialog_content = "Ele está em cima de nós tão rapidamente!",
  ui_story_1021_10210402_55_dialog_content = "Você...",
  ui_story_1021_10210402_56_dialog_content = "<color=#FFB400>Natas</color> transformará seu cérebro em néctar e o distribuirá entre seus companheiros.",
  ui_story_1021_10210402_57_dialog_content = "Compatriotas? Do que você está falando?",
  ui_story_1021_10210402_58_dialog_content = "Néctar...",
  ui_story_1021_10210402_59_dialog_content = "Falando de néctar...",
  ui_story_1021_10210402_60_dialog_content = "Eu me sinto péssimo...",
  ui_story_1021_10210402_61_dialog_content = "(O Fluxo Escuro dele poderia penetrar o escudo da rainha...)",
  ui_story_1021_10210402_62_dialog_content = "Frio Extremo Maior!",
  ui_story_1021_10210402_63_dialog_content = "Nossa presença só complicará seu esforço, Majestade. Confie neles em meus cuidados.",
  ui_story_1021_10210402_64_dialog_content = "Obrigada, Novio.",
  ui_story_1021_10210402_65_dialog_content = "Deixe-me lutar ao seu lado, Sua Majestade!",
  ui_story_1021_10210402_66_dialog_content = "Não, e essa é a minha ordem.",
  ui_story_1021_10210402_67_dialog_content = "...",
  ui_story_1021_10210402_68_dialog_content = "Carleen, PlayerName, por favor, siga meu pessoal para a superfície acima.",
  ui_story_1021_10210402_69_dialog_content = "Como, exatamente?",
  ui_story_1021_10210402_70_dialog_content = "...",
  ui_story_1021_10210402_71_dialog_content = "Senhor Novio!",
  ui_story_1021_10210402_72_dialog_content = "Permaneça na escuridão em paz.",
  ui_story_1021_10210402_73_dialog_content = "Não haverá escuridão em Northland enquanto a aurora ainda brilha! Lâmina de Aurora!",
  ui_story_1021_10210402_74_dialog_content = "Você está muito abaixo do nível dessa mulher.",
  ui_story_1021_10210402_75_dialog_content = "Você não é digno de julgar a rainha!",
  ui_story_1021_10210402_76_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_1021_10210402_77_dialog_content = "Volte aqui, Tiare!",
  ui_story_1021_10210402_78_dialog_content = "Como guarda de Sua Majestade, devo me posicionar diante de você como um escudo!",
  ui_story_1021_10210402_79_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_1021_10210402_80_dialog_content = "Você não irá prejudicar Sua Majestade! Este é um aviso da Guarda do Queen!",
  ui_story_1021_10210402_81_dialog_content = "Crânio orgulhoso... Pernas poderosas e brancas como a neve...",
  ui_story_1021_10210402_82_dialog_content = "May você pode me dizer o que é isso nos seus olhos?",
  ui_story_1021_10210402_83_dialog_content = "É minha determinação te matar!",
  ui_story_1021_10210402_84_dialog_content = "Você me lembra dela...",
  ui_story_1021_10210402_85_dialog_content = "Quando ela amarrou seu vestido preto na cintura, cortou a ponta para poder liderar a carga de seus soldados com maior velocidade.",
  ui_story_1021_10210402_86_dialog_content = "Não pisque ou minha lança irá te cegar tão rápido!",
  ui_story_1021_10210402_87_dialog_content = "Que olhar cativante. Infelizmente, é tarde demais...",
  ui_story_1021_10210402_88_dialog_content = "Isso acaba quando o gelo derreter!",
  ui_story_1021_10210402_89_dialog_content = "Sua Majestade?",
  ui_story_1021_10210402_90_dialog_content = "Esta não é sua luta. Agora saia pelo caminho que eu fiz!",
  ui_story_1021_10210402_91_dialog_content = "Mas e voce?",
  ui_story_1021_10210402_92_dialog_content = "Estarei logo atrás de você! Você me faria o favor, Sr. Novio?",
  ui_story_1021_10210402_93_dialog_content = "Conceda-me poder, Cajado Terra!",
  ui_story_1021_10210402_94_dialog_content = "Por que você não os matou, meu senhor?",
  ui_story_1021_10210402_95_dialog_content = "Porque eu vi minha raiva nos olhos daquela raposa...",
  ui_story_1021_10210402_96_dialog_content = "A raiva é um sinal de covardia. Eu jurei não ser escravo da raiva.",
  ui_story_1021_10210402_97_dialog_content = "As Rainhas da Terra da Neve...",
  ui_story_1021_10210402_98_dialog_content = "As geleiras que eles criaram nunca derretem no meu Shadowfire...",
  ui_story_1021_10210501_1_dialog_content = "...",
  ui_story_1021_10210501_2_dialog_content = "Vossa Majestade... Por que parou?",
  ui_story_1021_10210501_3_dialog_content = "Em todos os lugares por onde passamos, a influência do Darkflow expôs o leito rochoso sob camadas de gelo...",
  ui_story_1021_10210501_4_dialog_content = "No entanto, esta área está completamente inafetada... Além disso, sinto um poder único emanando deste lugar.",
  ui_story_1021_10210501_5_dialog_content = "Sei o que devo fazer agora, Novio. Por favor, cuidem-se bem, todos vocês.",
  ui_story_1021_10210501_6_dialog_content = "Mas... Vossa Majestade...",
  ui_story_1021_10210501_7_dialog_content = "... Por favor, deixe-me ir com você!",
  ui_story_1021_10210501_8_dialog_content = "...",
  ui_story_1021_10210501_9_dialog_content = "Seu propósito aqui é proteger sua tribo, não a rainha. Lembre-se disso.",
  ui_story_1021_10210501_10_dialog_content = "M-Mas…",
  ui_story_1021_10210501_11_dialog_content = "É apenas porque minha tribo está em tal perigo que não temos escolha a não ser refugiar-nos no altar...",
  ui_story_1021_10210501_12_dialog_content = "É isso que estou sentindo? O poder protetor do altar?",
  ui_story_1021_10210501_13_dialog_content = "Vossa Majestade... Eu... Eu não posso deixar você se aproximar do altar!",
  ui_story_1021_10210501_14_dialog_content = "Como ousa ficar no caminho da rainha, Tiare! Você tem alguma ideia do que está fazendo?",
  ui_story_1021_10210501_15_dialog_content = "... Eu jurei te proteger até nos lugares mais perigosos, mas o altar...",
  ui_story_1021_10210501_16_dialog_content = "Perdoe-me, mas eu não posso deixar você ir lá!",
  ui_story_1021_10210501_17_dialog_content = "Fiz uma promessa aos meus ancestrais quando me tornei líder da Tribo Fox da Neve!",
  ui_story_1021_10210501_18_dialog_content = "É o ódio que me impede de me aproximar do altar?",
  ui_story_1021_10210501_19_dialog_content = "Eu... Para ser honesto, não tenho certeza...",
  ui_story_1021_10210501_20_dialog_content = "...",
  ui_story_1021_10210501_21_dialog_content = "Se você tem dúvidas sobre o conflito entre sua tribo e o tribunal real, deve dissipá-las buscando a verdade por si mesmo.",
  ui_story_1021_10210501_22_dialog_content = "Mas pelo bem de toda a Northland, eu preciso vê-la agora. Por favor, acredite em mim, Tiare.",
  ui_story_1021_10210501_23_dialog_content = "Vossa Majestade!",
  ui_story_1021_10210501_24_dialog_content = "Deixe ela vir, Tiare.",
  ui_story_1021_10210501_25_dialog_content = "Hã? Quem disse isso?",
  ui_story_1021_10210501_26_dialog_content = "Ancião? Mas... Isso é realmente—",
  ui_story_1021_10210501_27_dialog_content = "Eu vou permitir isso.",
  ui_story_1021_10210501_28_dialog_content = "Está se sentindo melhor, senhora?",
  ui_story_1021_10210501_29_dialog_content = "Obrigado por perguntar, este velho corpo ainda vive.",
  ui_story_1021_10210501_30_dialog_content = "É a raposa, Carleen... Aquela velha raposa da neve que encontramos antes é quem está falando!",
  ui_story_1021_10210501_31_dialog_content = "Você não deveria estar tão surpreso. Além disso, parece ter se recuperado muito bem...",
  ui_story_1021_10210501_32_dialog_content = "Embora, julgando pela sua voz, parece ser uma \"ela\".",
  ui_story_1021_10210501_33_dialog_content = "...",
  ui_story_1021_10210501_34_dialog_content = "Por favor, desculpe-os, ancião. Eles não são do Norte, e eu farei com que eles mostrem respeito e saiam imediatamente.",
  ui_story_1021_10210501_35_dialog_content = "Isso não será necessário. Aqueles que realmente respeitavam o ancião da raposa da neve já se foram há muito tempo. Você está aqui apenas para pagar uma dívida, e nada mais.",
  ui_story_1021_10210501_36_dialog_content = "Peço que você mostre mais respeito ao se dirigir à rainha!",
  ui_story_1021_10210501_37_dialog_content = "Silêncio, Carleen!",
  ui_story_1021_10210501_38_dialog_content = "...",
  ui_story_1021_10210501_39_dialog_content = "Não se preocupe, pois minha fúria se acalmou há muito tempo. Tudo o que resta deste ser antigo é a estrutura desgastada que você vê diante de você.",
  ui_story_1021_10210501_40_dialog_content = "Apesar de tudo, nossa tribo já demonstrou respeito pelo seu monarca. O estado miserável desta caverna deve servir como uma resposta adequada para suas perguntas.",
  ui_story_1021_10210501_41_dialog_content = "Ancião, a rainha realmente tem permissão para—",
  ui_story_1021_10210501_42_dialog_content = "Eu só gostaria que você nunca precisasse suportar essas coisas, Tiare.",
  ui_story_1021_10210501_43_dialog_content = "...",
  ui_story_1021_10210501_44_dialog_content = "Ancião, os Eclipsitas que invadiram Northland já avançaram tanto em seu território...",
  ui_story_1021_10210501_45_dialog_content = "O poder da natureza protege este lugar. Por mais fraco que seja, os Eclipsitas não têm como se aproximar do altar. Venha comigo.",
  ui_story_1021_10210501_46_dialog_content = "...",
  ui_story_1021_10210501_47_dialog_content = "<color=#e8d9bb>Awooo...</color>",
  ui_story_1021_10210501_48_dialog_content = "Este é o altar que a tribo de Tiare tem protegido?",
  ui_story_1021_10210501_49_dialog_content = "Nunca esperava ver um lugar assim escondido em uma caverna...",
  ui_story_1021_10210501_50_dialog_content = "Este altar foi construído por nossos ancestrais quando Northland surgiu pela primeira vez.",
  ui_story_1021_10210501_51_dialog_content = "Este lugar... A quem ou ao que ele presta homenagem?",
  ui_story_1021_10210501_52_dialog_content = "O altar está em adoração às Três Árvores de Pinha de Neve e aos nossos antepassados, os protetores da Floresta de Pinha de Neve e de todo o Northland.",
  ui_story_1021_10210501_53_dialog_content = "As Três Árvores de Pinho Cobertas de Neve... Você quer dizer esses três tocos?",
  ui_story_1021_10210501_54_dialog_content = "Carregando a ambição de proteger Northland, eles estavam destinados a serem derrubados, e ainda assim, seu poder nunca se dissipou.",
  ui_story_1021_10210501_55_dialog_content = "Se as Três Árvores de Pinho Nevado escolherem ressurgir, as montanhas se abrirão para elas. O céu, também, nunca esqueceu seu poder, e assim força a luz a passar pelas fendas acima.",
  ui_story_1021_10210501_56_dialog_content = "Este tablet... Ele contém algum tipo de inscrições antigas?",
  ui_story_1021_10210501_57_dialog_content = "O que diz?",
  ui_story_1021_10210501_58_dialog_content = "\"Ele traz vitalidade ao monarca cansado, que por sua vez traz paz ao mundo.\"",
  ui_story_1021_10210501_59_dialog_content = "\"Seu sagrado pacto transforma a escuridão em luz.\"",
  ui_story_1021_10210501_60_dialog_content = "\"Contemplar sua divindade é encontrar felicidade e paz.\"",
  ui_story_1021_10210501_61_dialog_content = "Este poderia ser...",
  ui_story_1021_10210501_62_dialog_content = "O registro mais antigo conhecido da lendária Três Pinheiros...",
  ui_story_1021_10210501_63_dialog_content = "A lenda que é popular em Northland?",
  ui_story_1021_10210501_64_dialog_content = "O primeiro pinheiro testemunha o nascimento da primeira rainha de Northland, o segundo representa a lealdade de seus guardas reais...",
  ui_story_1021_10210501_65_dialog_content = "E o terceiro se torna o próprio cetro da rainha...",
  ui_story_1021_10210501_66_dialog_content = "Hahaha, está simplesmente transbordando com a vaidade dos sucessores reais...",
  ui_story_1021_10210501_67_dialog_content = "Considerem-se sortudos por ela não estar presente para ouvir isso, ou ela daria a todos vocês uma boa surra.",
  ui_story_1021_10210501_68_dialog_content = "Ainda assim, eu conheço muito bem a importância de uma origem gloriosa para qualquer império.",
  ui_story_1021_10210501_69_dialog_content = "<color=#828282>Ding!</color>",
  ui_story_1021_10210501_70_dialog_content = "!",
  ui_story_1021_10210501_71_dialog_content = "Ancião!",
  ui_story_1021_10210501_72_dialog_content = "D-Desculpe pela interrupção... O que há de errado com o seu Spotlight, Tiny One?",
  ui_story_1021_10210501_73_dialog_content = "Eu... Eu também não sei por que fez isso...",
  ui_story_1021_10210501_74_dialog_content = "Vocês dois estiveram escondidos lá esse tempo todo?",
  ui_story_1021_10210501_75_dialog_content = "Urgh... Forasteiros...",
  ui_story_1021_10210501_76_dialog_content = "Diga aos seus amigos para pegar aquilo e sair, PlayerName! O corpo do ancião é muito fraco para lidar com isso!",
  ui_story_1021_10210501_77_dialog_content = "Tiny One!",
  ui_story_1021_10210501_78_dialog_content = "Por quê... Por que não está funcionando?",
  ui_story_1021_10210501_79_dialog_content = "<color=#e8d9bb>Uau, uau—</color>",
  ui_story_1021_10210501_80_dialog_content = "Minha lança parece estar pulsando com poder...",
  ui_story_1021_10210501_81_dialog_content = "Que tipo de coisa é essa no mundo?",
  ui_story_1021_10210501_82_dialog_content = "<color=#e8d9bb>Uau, uau—</color>",
  ui_story_1021_10210501_83_dialog_content = "Meu cajado está ressoando com o altar...",
  ui_story_1021_10210501_84_dialog_content = "...",
  ui_story_1021_10210501_85_dialog_content = "Mas a Força Invernal da rainha parece ser a sua escolha...",
  ui_story_1021_10210501_86_dialog_content = "... O-O quê?",
  ui_story_1021_10210501_87_dialog_content = "Eu ficarei ao lado de um monarca, que por sua vez trará paz a este mundo!",
  ui_story_1021_10210501_88_dialog_content = "(Aquela voz...)",
  ui_story_1021_10210501_89_dialog_content = "Através do meu poder, transformarei a escuridão em luz!",
  ui_story_1021_10210501_90_dialog_content = "Enquanto os outros sentirem felicidade e paz ao me olhar, eu estarei mais do que satisfeito...",
  ui_story_1021_10210501_91_dialog_content = "Hahaha... Vocês dois podem ser tão arrogantes às vezes...",
  ui_story_1021_10210501_92_dialog_content = "Acha que é diferente? Hahaha...",
  ui_story_1021_10210501_93_dialog_content = "O altar ecoa com três vozes distintas...",
  ui_story_1021_10210501_94_dialog_content = "Eu também os ouço...",
  ui_story_1021_10210501_95_dialog_content = "São essas... as vozes do divino?",
  ui_story_1021_10210501_96_dialog_content = "...",
  ui_story_1021_10210501_97_dialog_content = "O divino... reconheceu o seu poder...",
  ui_story_1021_10210501_98_dialog_content = "Inúmeras visões passaram pelos meus olhos agora mesmo...",
  ui_story_1021_10210501_99_dialog_content = "O divino apenas reconhece o poder daqueles que são dignos...",
  ui_story_1021_10210501_100_dialog_content = "Em outras palavras...",
  ui_story_1021_10210501_101_dialog_content = "Sua primeira rainha... Ela realmente obteve a bênção deles...",
  ui_story_1021_10210501_102_dialog_content = "Bom...",
  ui_story_1021_10210501_103_dialog_content = "Isso seria inimaginável para nossos ancestrais falecidos...",
  ui_story_1021_10210501_104_dialog_content = "<color=#e8d9bb>Morrer!</color>",
  ui_story_1021_10210501_105_dialog_content = "Avance e cumpra sua promessa, e você sempre encontrará descanso em Northland.",
  ui_story_1021_10210501_106_dialog_content = "Hesite, e eu pendurarei suas cabeças vergonhosas nos pinheiros de neve para seus descendentes verem!",
  ui_story_1021_10210501_107_dialog_content = "Hã? De quem são esses pensamentos? Eu não estava usando meus poderes agora...",
  ui_story_1021_10210501_108_dialog_content = "Todos ainda estão em pé ao redor do altar como antes...",
  ui_story_1021_10210501_109_dialog_content = "Isso... Isso era a fortaleza outrora inexpugnável na fronteira de Northland...",
  ui_story_1021_10210501_110_dialog_content = "Será que estamos—",
  ui_story_1021_10210501_111_dialog_content = "Sim. Este altar estava localizado dentro do pátio da fortaleza.",
  ui_story_1021_10210501_112_dialog_content = "...",
  ui_story_1021_10210501_113_dialog_content = "Povo do Reino Congelado, desapareçam deste lugar.",
  ui_story_1021_10210501_114_dialog_content = "...",
  ui_story_1021_10210501_115_dialog_content = "Ele está... falando conosco?",
  ui_story_1021_10210501_116_dialog_content = "Nossa roupa... Comparada com a deles, é...",
  ui_story_1021_10210501_117_dialog_content = "Ao roubar o poder dos pinheiros de neve, você nos privou de nossa proteção.",
  ui_story_1021_10210501_118_dialog_content = "Mas marque minhas palavras, nosso povo nunca esquecerá nossa promessa a eles!",
  ui_story_1021_10210501_119_dialog_content = "Mesmo que todos nós pereçamos na floresta que nos deu vida, mesmo que sejamos esmagados pelo peso deste céu opressor...",
  ui_story_1021_10210501_120_dialog_content = "Jamais reconhecerei qualquer monarca que não seja o meu.",
  ui_story_1021_10210501_121_dialog_content = "...",
  ui_story_1021_10210501_122_dialog_content = "Senhor Rode...",
  ui_story_1021_10210501_123_dialog_content = "Hagen! Traga-me a armadura que o rei me concedeu, para que eu possa recompensar os homens que lideram nosso ataque!",
  ui_story_1021_10210501_124_dialog_content = "Senhor Rode... Por favor, use esta armadura com orgulho.",
  ui_story_1021_10210501_125_dialog_content = "Esta não será minha última luta, Hagen! Enquanto eu tiver você ao meu lado, nunca cairei!",
  ui_story_1021_10210501_126_dialog_content = "...",
  ui_story_1021_10210501_127_dialog_content = "Vamos, Hagen.",
  ui_story_1021_10210501_128_dialog_content = "Eu sempre estarei ao seu lado, Senhor Rode...",
  ui_story_1021_10210501_129_dialog_content = "...",
  ui_story_1021_10210501_130_dialog_content = "O Senhor Rode era um homem grande e poderoso que, mesmo assim, se importava profundamente com seus soldados. Estávamos certos de que ele se tornaria o próximo rei de Northland.",
  ui_story_1021_10210501_131_dialog_content = "Irmãos! Pelo rei e todo o Northland, marchamos para a batalha!",
  ui_story_1021_10210501_132_dialog_content = "Para a batalha!",
  ui_story_1021_10210501_133_dialog_content = "Para a batalha!",
  ui_story_1021_10210501_134_dialog_content = "<color=#e8d9bb>Uau, uau—</color>",
  ui_story_1021_10210501_135_dialog_content = "Foi-se... Foi essa a \"força da natureza\" agora há pouco?",
  ui_story_1021_10210501_136_dialog_content = "...",
  ui_story_1021_10210501_137_dialog_content = "Então você serviu como guarda do Senhor Rode, ancião?",
  ui_story_1021_10210501_138_dialog_content = "Sim, Tiare. Ele era seu ancestral e um orgulhoso membro da tribo, o tipo que você idolatra desde que era apenas uma criança.",
  ui_story_1021_10210501_139_dialog_content = "Com a nossa tribo em seu estado atual, não tenho como enfrentá-lo agora.",
  ui_story_1021_10210501_140_dialog_content = "As cicatrizes no seu rosto... Você as conseguiu durante sua batalha com os Eclipsitas naquela época?",
  ui_story_1021_10210501_141_dialog_content = "Não há necessidade de lamentar uma história tão antiga, Tiare.",
  ui_story_1021_10210501_142_dialog_content = "Embora nossas cicatrizes ainda estejam visíveis até hoje, o que você não vê é a nossa vitória sobre os Eclipsitas naquele dia, bem como a nossa celebração com uma fogueira na Floresta Snowpine.",
  ui_story_1021_10210501_143_dialog_content = "Por que você não me contou nada disso?",
  ui_story_1021_10210501_144_dialog_content = "Se você soubesse, teria deixado o Palácio Invernal para proteger este lugar, assim como seus antepassados juraram fazer.",
  ui_story_1021_10210501_145_dialog_content = "Conheço você muito bem, Tiare. Mesmo como guarda da rainha, o sangue do nosso povo corre em suas veias.",
  ui_story_1021_10210501_146_dialog_content = "Chegará o dia em que nossa tribo não existirá mais. Contar essas coisas para você seria sem sentido.",
  ui_story_1021_10210501_147_dialog_content = "Além disso, você já escolheu seu monarca.",
  ui_story_1021_10210501_148_dialog_content = "...",
  ui_story_1021_10210501_149_dialog_content = "E a pessoa a quem você jurou lealdade provou ser digna do poder divino. Você não tem mais motivo para ficar e nos proteger.",
  ui_story_1021_10210501_150_dialog_content = "...",
  ui_story_1021_10210501_151_dialog_content = "Mas... Mas e sobre o \"poder roubado\" que o Senhor Rode estava falando?",
  ui_story_1021_10210501_152_dialog_content = "O Farol...",
  ui_story_1021_10210501_153_dialog_content = "O Farol? Você quer dizer o Farol de Northland?",
  ui_story_1021_10210501_154_dialog_content = "\"Contemplar sua divindade é encontrar felicidade e paz.\"",
  ui_story_1021_10210501_155_dialog_content = "...",
  ui_story_1021_10210501_156_dialog_content = "Para erradicar os Eclipsitas e trazer luz para todo o Northland...",
  ui_story_1021_10210501_157_dialog_content = "Os ancestrais da família real receberam um pinheiro de neve contendo o poder da natureza.",
  ui_story_1021_10210501_158_dialog_content = "O pinheiro de neve se cortou, e sua madeira se tornou combustível para a Fagulha, que serviu como o primeiro Farol de Northland.",
  ui_story_1021_10210501_159_dialog_content = "Desde então, toda a Northland tem sido banhada por sua luz... Como resultado, a Floresta Snowpine tem perdido gradualmente seu poder de repelir os Eclipsitas.",
  ui_story_1021_10210501_160_dialog_content = "...",
  ui_story_1021_10210501_161_dialog_content = "Você viu isso em suas visões?",
  ui_story_1021_10210501_162_dialog_content = "Sim. Os pinheiros de neve reconheceram a família real e escolheram se tornar o Farol de Northland.",
  ui_story_1021_10210501_163_dialog_content = "Somente então eles foram capazes de realizar seu objetivo de proteger nossa terra...",
  ui_story_1021_10210501_164_dialog_content = "Entendo...",
  ui_story_1021_10210501_165_dialog_content = "Em outras palavras, a família real nunca roubou o poder dos snowpines, não é?",
  ui_story_1021_10210501_166_dialog_content = "...",
  ui_story_1021_10210501_167_dialog_content = "...",
  ui_story_1021_10210501_168_dialog_content = "Antes de se tornar o Farol de Northland, o divino usou seu poder para nos proteger aqui. Naquela época, seus poderes ainda não haviam sido privados.",
  ui_story_1021_10210501_169_dialog_content = "Nossos ancestrais construíram este altar em honra a eles, para adorá-los e demonstrar nossa fé e esperança todos os dias.",
  ui_story_1021_10210501_170_dialog_content = "Eles acendiam lamparinas de óleo de pinho até mesmo nos invernos mais frios, tudo para garantir a paz e a prosperidade de nossa tribo.",
  ui_story_1021_10210501_171_dialog_content = "Mas a passagem do tempo trouxe mudanças inesperadas ao longo dos anos. Colheitas falharam, doenças e todo tipo de dificuldades atingiram nossa tribo...",
  ui_story_1021_10210501_172_dialog_content = "Quando os pinheiros de neve foram cortados, o ódio e o desespero rapidamente se abateram sobre nosso povo.",
  ui_story_1021_10210501_173_dialog_content = "Sob o reinado do rei, começamos a rezar no altar dia e noite pela graça do divino.",
  ui_story_1021_10210501_174_dialog_content = "Mas os Eclipsitas vieram mesmo assim, e fui forçado a testemunhar o nascimento e a morte de tantos dos nossos. Apesar de nossas súplicas mais desesperadas, o divino nunca nos respondeu...",
  ui_story_1021_10210501_175_dialog_content = "O silêncio deles era a prova de que nossa tribo estava destinada à extinção como punição pelo nosso ódio.",
  ui_story_1021_10210501_176_dialog_content = "Essa é a história do nosso povo. Antes de você nascer, eu tinha certeza de que encontraria meu fim assim...",
  ui_story_1021_10210501_177_dialog_content = "Ancião...",
  ui_story_1021_10210501_178_dialog_content = "Eu envelheci demais, Tiare. Tudo o que tenho para me sustentar agora são essas memórias.",
  ui_story_1021_10210501_179_dialog_content = "Diga-me, você já fez sua escolha? E está pronto para mantê-la pelo resto da sua vida?",
  ui_story_1021_10210501_180_dialog_content = "Desejo proteger nossa tribo, ancião... mas também desejo ajudar a rainha.",
  ui_story_1021_10210501_181_dialog_content = "Se houver uma divisão entre a família real e nossa tribo, por favor me diga, e eu farei tudo ao meu alcance para superá-la.",
  ui_story_1021_10210501_182_dialog_content = "Para defender Northland dos Eclipsitas, devemos confiar uns nos outros por agora e nos unir?",
  ui_story_1021_10210501_183_dialog_content = "...",
  ui_story_1021_10210501_184_dialog_content = "Ancião, há algo que sempre existiu em minhas memórias, algo que diz respeito ao Primal Haven.",
  ui_story_1021_10210501_185_dialog_content = "Acabei de ter um vislumbre disso nas minhas visões...",
  ui_story_1021_10210501_186_dialog_content = "O pinheiro nevado que serviu como o primeiro Farol de Northland, a árvore que outrora estava enraizada aqui, foi fortalecida pela antiga energia que emanava deste lugar.",
  ui_story_1021_10210501_187_dialog_content = "Estou correto em assumir que o Refúgio Primordial existe em algum lugar perto do altar?",
  ui_story_1021_10210501_188_dialog_content = "Se sim, você conhece uma maneira de invocá-lo e usar seu poder para defender Northland?",
  ui_story_1021_10210501_189_dialog_content = "Uma maneira de invocar o Refúgio Primordial? Heheh...",
  ui_story_1021_10210501_190_dialog_content = "Você teria que extinguir o Farol de Northland e permitir que novas mudas cresçam dessas três árvores caídas.",
  ui_story_1021_10210501_191_dialog_content = "...",
  ui_story_1021_10210501_192_dialog_content = "Além do Farol, existem outros dois pinheiros de neve que devem ser devolvidos ao altar, certo?",
  ui_story_1021_10210501_193_dialog_content = "Correto.",
  ui_story_1021_10210501_194_dialog_content = "Ancião... Isso é verdade?",
  ui_story_1021_10210501_195_dialog_content = "...",
  ui_story_1021_10210501_196_dialog_content = "Mas o Farol de Northland nunca foi extinto... Se a chama se apagar, isso não significa que o Palácio de Inverno e o povo do reino irão—",
  ui_story_1021_10210501_197_dialog_content = "O que aconteceu com o \"guarda de Sua Majestade\"?",
  ui_story_1021_10210501_198_dialog_content = "Sua rainha deseja invocar o Refúgio Primordial e pagar sua dívida com nossa tribo. Você pretende desafiá-la?",
  ui_story_1021_10210501_199_dialog_content = "Claro que não! Eu sempre seguirei a rainha para onde quer que ela vá! Mas...",
  ui_story_1021_10210501_200_dialog_content = "Olhe para mim, Tiare.",
  ui_story_1021_10210501_201_dialog_content = "...",
  ui_story_1021_10210501_202_dialog_content = "Por favor, tenha fé em mim. Eu aceitei esse poder e sei o que devo fazer para retribuir essa bênção.",
  ui_story_1021_10210501_203_dialog_content = "Como meu guarda, desejo que você me ajude a invocar o Refúgio Primordial para defender toda a Northland.",
  ui_story_1021_10210501_204_dialog_content = "Cabe a você trazer de volta os outros dois pinheiros de neve. Você entendeu?",
  ui_story_1021_10210501_205_dialog_content = "Vossa Majestade...",
  ui_story_1021_10210501_206_dialog_content = "Tudo que se encontra sob a neve é Northland, um reino que jurei proteger com minha vida.",
  ui_story_1021_10210501_207_dialog_content = "A luz do Farol não alcança este lugar, então é minha responsabilidade defender sua casa dos Eclipsitas.",
  ui_story_1021_10210501_208_dialog_content = "...",
  ui_story_1021_10210501_209_dialog_content = "Novio, você está familiarizado com a localização dos pinheiros nevados, sim?",
  ui_story_1021_10210501_210_dialog_content = "Sim, Vossa Majestade. Fique tranquilo que nós os recuperaremos enquanto você enfrenta o Eclipsita.",
  ui_story_1021_10210501_211_dialog_content = "...",
  ui_story_1021_10210501_212_dialog_content = "Eu vou agora com o senhor Novio e os outros, ancião...",
  ui_story_1021_10210501_213_dialog_content = "Vá. Siga seu próprio farol e cumpra sua promessa à sua rainha.",
  ui_story_1021_10210501_214_dialog_content = "Pode deixar!",
  ui_story_1021_10210601_1_dialog_content = "Queen Bethlehem está lutando contra os Eclipsitas sozinha... Não há realmente nada que possamos fazer para ajudá-la?",
  ui_story_1021_10210601_2_dialog_content = "A última vez que Sua Majestade me resgatou, ela me concedeu meu poder único. Ela fez tanto por mim, e ainda assim, não posso lutar ao lado dela agora...",
  ui_story_1021_10210601_3_dialog_content = "E com bons motivos. Depois do seu encontro anterior com aquele Eclipsite, você deve saber o quão poderoso ele é.",
  ui_story_1021_10210601_4_dialog_content = "Além disso, você ainda está ajudando a rainha ao recuperar os pinheiros de neve para ela.",
  ui_story_1021_10210601_5_dialog_content = "O Fluxo Escuro que jorra deste gêiser tem erodido as planícies de neve da Terra do Norte todo esse tempo...",
  ui_story_1021_10210601_6_dialog_content = "Sua Majestade veio ao ancião em busca de uma maneira de expurgar este mal de nossa terra. Em outras palavras, para invocar o Refúgio Primordial.",
  ui_story_1021_10210601_7_dialog_content = "Então, onde podemos encontrar os outros dois pinheiros de neve, Senhor Novio?",
  ui_story_1021_10210601_8_dialog_content = "Além da que está no Farol, as outras duas pinhas de neve estão em locais separados, onde continuam a proteger Northland até hoje.",
  ui_story_1021_10210601_9_dialog_content = "Continuar protegendo Northland?",
  ui_story_1021_10210601_10_dialog_content = "De fato. Um é mantido dentro do Palácio Invernal, enquanto o outro está no lugar do seu nascimento.",
  ui_story_1021_10210601_11_dialog_content = "No entanto, a passagem do tempo pode ter tornado todos eles praticamente irreconhecíveis agora. Talvez a lenda dos Três Pinheiros possa esclarecer mais sobre o assunto?",
  ui_story_1021_10210601_12_dialog_content = "Embora o poder da natureza normalmente esteja adormecido, ele deve ressoar com o poder concedido a você pela rainha quando você se aproxima dos pinheiros nevados.",
  ui_story_1021_10210601_13_dialog_content = "Entendido. Obrigado, Senhor Novio!",
  ui_story_1021_10210601_14_dialog_content = "Tanto o Queen Bethlehem quanto a raposa mais velha entendem o que significa proteger com suas vidas.",
  ui_story_1021_10210601_15_dialog_content = "Como guarda de Northland, você também tem um papel a desempenhar, Tiare. Você está em uma missão para proteger.",
  ui_story_1021_10210601_16_dialog_content = "Deixe comigo. Não vou decepcionar todo mundo!",
  ui_story_1021_10210601_17_dialog_content = "Espere, Tiare! Deixe-me ir com você!",
  ui_story_1021_10210601_18_dialog_content = "Você?",
  ui_story_1021_10210601_19_dialog_content = "Eu também posso ajudar!",
  ui_story_1021_10210601_20_dialog_content = "Mas você realmente acha que pode me acompanhar? Ou melhor, você está disposto a me deixar carregar você de novo?",
  ui_story_1021_10210601_21_dialog_content = "Carregar?",
  ui_story_1021_10210601_22_dialog_content = "... Se isso significa que eu vou te ajudar, então eu farei!",
  ui_story_1021_10210601_23_dialog_content = "As habilidades psíquicas de PlayerName podem ajudar.",
  ui_story_1021_10210601_24_dialog_content = "Eu vejo... Então, deixo as coisas aqui para você e os outros, Senhor Novio!",
  ui_story_1021_10210601_25_dialog_content = "PlayerName e eu voltarei logo!",
  ui_story_1021_10210601_26_dialog_content = "H-Huh?",
  ui_story_1021_10210601_27_dialog_content = "E assim mesmo, eles se foram...",
  ui_story_1021_10210601_28_dialog_content = "O fluido carregado de Darkflow está se movendo constantemente em direção ao palácio...",
  ui_story_1021_10210601_29_dialog_content = "Parece que até mesmo a impressionante Lumina de Nikinis é impotente para contê-la agora.",
  ui_story_1021_10210601_30_dialog_content = "Só podemos esperar que Tiare retorne com os pinheiros da neve a tempo. Ainda há esperança para a sobrevivência de sua tribo...",
  ui_story_1021_10210601_31_dialog_content = "Por favor, permita-me servir como um guarda de Northland, Senhor Novio. Eu também desejo fazer minha parte para proteger o reino!",
  ui_story_1021_10210601_32_dialog_content = "<color=#e8d9bb>Do outro lado da floresta</color>",
  ui_story_1021_10210601_33_dialog_content = "Bem, já que não temos como voltar ao Deserto Rediesel agora, nossa melhor escolha é ajudar PlayerName e os outros a salvar o dia.",
  ui_story_1021_10210601_34_dialog_content = "Você está sendo sério?",
  ui_story_1021_10210601_35_dialog_content = "Com certeza! Além disso, é tudo para o benefício do Rediesel.",
  ui_story_1021_10210601_36_dialog_content = "PlayerName ajudou muito Sinsa quando se trata da situação de Eve.",
  ui_story_1021_10210601_37_dialog_content = "Por causa disso, Sinsa está sempre disposto a ajudar sempre que PlayerName está em perigo.",
  ui_story_1021_10210601_38_dialog_content = "Eles são unha e carne, esses dois. Sinsa só gosta de fingir que não sabe.",
  ui_story_1021_10210601_39_dialog_content = "Então, se ajudarmos eles em nome da Rediesel Wrench, ele nos deverá um favor!",
  ui_story_1021_10210601_40_dialog_content = "Você é um gênio, Roy! Não é à toa que o chefe Sinsa sempre diz que podemos aprender uma coisa ou duas com você!",
  ui_story_1021_10210601_41_dialog_content = "Claro, agora vamos nos mover. Vamos eliminar qualquer Eclipsita em nosso caminho enquanto seguimos o fluxo do líquido preto!",
  ui_story_1021_10210601_42_dialog_content = "<color=#e8d9bb>Perto da fronteira de Northland</color>",
  ui_story_1021_10210601_43_dialog_content = "(Em Eclipsiano) Meu senhor... Não podemos ir mais longe...",
  ui_story_1021_10210601_44_dialog_content = "(Eclipsiano) Dizem que a luz daquele farol amaldiçoado vai despedaçar nossos corpos.",
  ui_story_1021_10210601_45_dialog_content = "(Eclipsiano) Gelo e chamas não significam nada para nós, e nem deveria a luz daquele farol maligno.",
  ui_story_1021_10210601_46_dialog_content = "<color=#e8d9bb>Auuuuu!</color>",
  ui_story_1021_10210601_47_dialog_content = "(Eclipsiano) As feras brancas estão uivando para nós.",
  ui_story_1021_10210601_48_dialog_content = "(Eclipsiano) Depois de todos esses anos, quando a fortaleza e seus guardas se transformaram em pó, eles ainda permanecem.",
  ui_story_1021_10210601_49_dialog_content = "(Eclipsian) Northland realmente é um lugar maravilhoso para se estar.",
  ui_story_1021_10210601_50_dialog_content = "Lâmina de Gelo!",
  ui_story_1021_10210601_51_dialog_content = "Todos os invasores de Northland encontrarão seu fim na neve!",
  ui_story_1021_10210601_52_dialog_content = "Mesmo depois de eu ter poupado você, escolheu me perseguir com tanta tenacidade obstinada.",
  ui_story_1021_10210601_53_dialog_content = "Diga-me, você pretende nos selar em uma parede de gelo mais uma vez?",
  ui_story_1021_10210601_54_dialog_content = "... O que você sabe sobre <color=#FFB400>aquela batalha</color>?",
  ui_story_1021_10210601_55_dialog_content = "Parece que você ainda é bastante jovem.",
  ui_story_1021_10210601_56_dialog_content = "(Eclipsiano) Vá. Faça companhia ao nosso amigo.",
  ui_story_1021_10210601_57_dialog_content = "(Eclipsiano) Sim, meu senhor!",
  ui_story_1021_10210700_1_dialog_content = "... A rainha disse que eu tinha que entregar esta mensagem o mais rápido que eu pudesse!",
  ui_story_1021_10210700_2_dialog_content = "É assim, você vê...",
  ui_story_1021_10210700_3_dialog_content = "Então a expedição conjunta já começou mesmo antes de entrar na Zona Cega.",
  ui_story_1021_10210700_4_dialog_content = "Mesmo assim, precisamos defender o posto avançado em Northland. Vamos, Vivian, estamos partindo para Northland imediatamente.",
  ui_story_1021_10210700_5_dialog_content = "Sim, Grande Marechal.",
  ui_story_1021_10210700_6_dialog_content = "Você também me acompanhará, Ms. Blanc.",
  ui_story_1021_10210700_7_dialog_content = "Sim, meu senhor.",
  ui_story_1021_10210700_8_dialog_content = "Nós também vamos, Bethel?",
  ui_story_1021_10210700_9_dialog_content = "Claro. Umbraton não pode se dar ao luxo de perder isso.",
  ui_story_1021_10210700_10_dialog_content = "Mas Northland está situada a uma altitude tão alta...",
  ui_story_1021_10210700_11_dialog_content = "Estamos todos em pé de igualdade aqui, Senhora Bethel. Você está convidada a viajar conosco em nossa aeronave, se quiser.",
  ui_story_1021_10210700_12_dialog_content = "Muito apreciado!",
  ui_story_1021_10210700_13_dialog_content = "T-Tiare... Não posso apenas andar por parte da viagem? Minhas costas parecem que vão partir ao meio...",
  ui_story_1021_10210700_14_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_1021_10210700_15_dialog_content = "Não acredito que você me carregou todo esse caminho... e nos seus ombros, ainda por cima!",
  ui_story_1021_10210700_16_dialog_content = "Você disse que eu poderia te carregar, então eu fiz. Todos os forasteiros são tão propensos a dizer o que não querem dizer?",
  ui_story_1021_10210700_17_dialog_content = "De modo algum... Para ser sincero, eu não achei que você estava falando sério antes...",
  ui_story_1021_10210700_18_dialog_content = "Mas acho que agora sei como o líder das raposas de neve funciona!",
  ui_story_1021_10210700_19_dialog_content = "Ufa! Eu consigo ver o Palácio Invernal daqui...",
  ui_story_1021_10210700_20_dialog_content = "Grr...",
  ui_story_1021_10210700_21_dialog_content = "Uh, o que você está-",
  ui_story_1021_10210700_22_dialog_content = "<color=#e8d9bb>Awoo!</color>",
  ui_story_1021_10210700_23_dialog_content = "Você recebeu uma resposta!",
  ui_story_1021_10210700_24_dialog_content = "Sim. É assim que as raposas e eu nos comunicamos umas com as outras.",
  ui_story_1021_10210700_25_dialog_content = "Então, o que você disse agora?",
  ui_story_1021_10210700_26_dialog_content = "Eu disse a eles que a água negra ainda não havia chegado a este lugar. As raposas disseram que avisariam o Senhor Novio.",
  ui_story_1021_10210700_27_dialog_content = "Você consegue passar tanta informação com um único uivo?",
  ui_story_1021_10210700_28_dialog_content = "Isso mesmo! Você também deveria tentar!",
  ui_story_1021_10210700_29_option_content = "Eu? M-Talvez não...",
  ui_story_1021_10210700_30_dialog_content = "Por quê? Isso é muito embaraçoso para você?",
  ui_story_1021_10210700_31_dialog_content = "N-De jeito nenhum! O que te faz dizer isso?",
  ui_story_1021_10210700_32_dialog_content = "Quando cheguei pela primeira vez ao Palácio de Inverno, alguns dos guardas me imitavam o tempo todo...",
  ui_story_1021_10210700_33_dialog_content = "No início, achei que meu uivo estava muito alto, mas depois percebi que o volume não tinha nada a ver com isso.",
  ui_story_1021_10210700_34_dialog_content = "Ainda assim, nunca me senti envergonhado por isso! Eu fiz o meu melhor para evitar uivar no Palácio Invernal...",
  ui_story_1021_10210700_35_dialog_content = "Mas quando é tarde da noite ou estou em patrulha sozinho, ainda gosto de me comunicar com as raposas assim.",
  ui_story_1021_10210700_36_dialog_content = "Não há nada para se envergonhar! Ouça isso—",
  ui_story_1021_10210700_37_dialog_content = "Aaai!",
  ui_story_1021_10210700_38_option_content = "Uwaaagh!",
  ui_story_1021_10210700_39_dialog_content = "Nós iremos?",
  ui_story_1021_10210700_40_dialog_content = "...",
  ui_story_1021_10210700_41_dialog_content = "Esse olhar no seu rosto... Foi realmente tão ruim assim?",
  ui_story_1021_10210700_42_dialog_content = "Não, eu estou apenas tentando entender o que você disse agora... Você estava pedindo comida, ou dizendo que o tempo está bom?",
  ui_story_1021_10210700_43_dialog_content = "Por que você não tenta de novo?",
  ui_story_1021_10210700_44_dialog_content = "Ah... Talvez mais tarde.",
  ui_story_1021_10210700_45_dialog_content = "Apenas levante a cabeça e endireite o pescoço assim.",
  ui_story_1021_10210700_46_dialog_content = "Levante minha cabeça... e endireite meu pescoço...",
  ui_story_1021_10210700_47_dialog_content = "É isso! Agora apenas abra a boca, encontre as palavras que você quer dizer bem no fundo do seu coração, e grite todas de uma vez!",
  ui_story_1021_10210700_48_dialog_content = "Grr...",
  ui_story_1021_10210700_49_dialog_content = "<color=#e8d9bb>Awoo!</color>",
  ui_story_1021_10210700_50_dialog_content = "Viu? Eu estava certo, não estava?",
  ui_story_1021_10210700_51_dialog_content = "Uau! Não sei se minha mensagem estava clara ou não, mas é ótimo ouvir uma resposta!",
  ui_story_1021_10210700_52_dialog_content = "Ouvir sua alegria também faz as raposas felizes.",
  ui_story_1021_10210700_53_dialog_content = "Tudo bem, acho que descansamos o suficiente. Agora é hora de te levar para o Palácio Invernal de uma vez!",
  ui_story_1021_10210700_54_dialog_content = "E-Ei! Pelo menos me deixe olhar para frente!",
  ui_story_1021_10210700_55_dialog_content = "Olá, Senhorita Zarya! Você coletou muito minério hoje, não coletou?",
  ui_story_1021_10210700_56_dialog_content = "Isso mesmo! É o meu primeiro trabalho para a rainha, então, naturalmente, tenho que dar o meu melhor!",
  ui_story_1021_10210700_57_dialog_content = "Ouvi dizer que seus Luminatics são muito poderosos. Minerar tanto minério deve ter sido fácil para alguém como você!",
  ui_story_1021_10210700_58_dialog_content = "Não exatamente... Eu ainda me congelo acidentalmente de vez em quando...",
  ui_story_1021_10210700_59_dialog_content = "Felizmente, eu só me congelei parcialmente, mas ainda tenho muito a aprender! De qualquer forma, estou indo para o Palácio Invernal para relatar à rainha. Adeus!",
  ui_story_1021_10210700_60_dialog_content = "Ah... Mas pelo que eu ouvi, Sua Majestade não está no Palácio de Inverno agora...",
  ui_story_1021_10210700_61_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_1021_10210700_62_dialog_content = "O que-",
  ui_story_1021_10210700_63_dialog_content = "É PlayerName e Tiare... Mas o que eles estão fazendo aqui?",
  ui_story_1021_10210700_64_dialog_content = "Procuramos em todos os cantos do lugar, mas sua lança não respondeu uma vez sequer...",
  ui_story_1021_10210700_65_dialog_content = "Talvez a energia antiga tenha estado adormecida por muito tempo...",
  ui_story_1021_10210700_66_dialog_content = "Novio disse que deveríamos procurar pistas na lenda. Alguma ideia do que ele quis dizer com isso?",
  ui_story_1021_10210700_67_dialog_content = "O pinheiro de neve no Palácio Invernal deve corresponder à primeira parte da lenda: \"Ele traz vitalidade para o monarca cansado, que por sua vez traz paz ao mundo.\"",
  ui_story_1021_10210700_68_dialog_content = "Então, como a rainha geralmente recupera suas forças quando está cansada?",
  ui_story_1021_10210700_69_dialog_content = "A rainha não passa muito tempo no Palácio Invernal. Na maioria das vezes, ela está ou no quarto dela, na sala de jantar, ou nos jardins atrás do palácio.",
  ui_story_1021_10210700_70_dialog_content = "Parece que a rainha alivia o estresse da mesma maneira que eu - com comida, sono e muito tempo livre.",
  ui_story_1021_10210700_71_dialog_content = "De alguma forma, eu não acho que a rainha se entrega às coisas sobre as quais você está falando...",
  ui_story_1021_10210700_72_dialog_content = "Por que vocês dois estão com tanta pressa para encontrar a rainha? Há algo errado?",
  ui_story_1021_10210700_73_dialog_content = "Este minério...",
  ui_story_1021_10210700_74_dialog_content = "Não se preocupe. O minério não é da região da sua casa, eu prometo!",
  ui_story_1021_10210700_75_dialog_content = "O que você está fazendo aqui, Zarya?",
  ui_story_1021_10210700_76_dialog_content = "Você não me viu agora há pouco? Eu vi vocês dois correndo para o palácio, então pensei que tinham um assunto urgente com a rainha.",
  ui_story_1021_10210700_77_dialog_content = "Mas me disseram que a rainha está ausente do Palácio de Inverno agora, então vim te contar.",
  ui_story_1021_10210700_78_dialog_content = "Nós já sabemos disso.",
  ui_story_1021_10210700_79_dialog_content = "Então o que exatamente você está fazendo aqui?",
  ui_story_1021_10210700_80_dialog_content = "Procurando por algo.",
  ui_story_1021_10210700_81_dialog_content = "É mesmo? Talvez eu possa te dar uma mão?",
  ui_story_1021_10210700_82_dialog_content = "Bem, estamos procurando algo... que alivie o cansaço da rainha.",
  ui_story_1021_10210700_83_dialog_content = "Hmm... Isso quase parece um jogo que as crianças gostam de jogar, um que é baseado em uma lenda...",
  ui_story_1021_10210700_84_dialog_content = "E esse jogo é comum entre as crianças?",
  ui_story_1021_10210700_85_dialog_content = "Claro. As crianças locais costumam ser vistas brincando neste jogo no jardim da rainha.",
  ui_story_1021_10210700_86_dialog_content = "As crianças realmente podem simplesmente entrar no Palácio de Inverno?",
  ui_story_1021_10210700_87_dialog_content = "Queen Bethlehem nunca viu o palácio como algo que pertencia exclusivamente a ela.",
  ui_story_1021_10210700_88_dialog_content = "Ela é tão generosa quanto é diligente. Pensando bem, acho que nunca a vi tirar uma pausa...",
  ui_story_1021_10210700_89_dialog_content = "Há assentos e bancos por todo o palácio, incluindo estas belas cadeiras de balanço no jardim, mas nunca a vi sentar em uma.",
  ui_story_1021_10210700_90_dialog_content = "Então talvez a resposta que estamos procurando... está bem aqui! Venha ver isso, Tiare!",
  ui_story_1021_10210700_91_dialog_content = "...",
  ui_story_1021_10210700_92_dialog_content = "Huh? Sua lança está brilhando!",
  ui_story_1021_10210700_93_dialog_content = "Ah... Eu sabia!",
  ui_story_1021_10210700_94_dialog_content = "O trono da rainha...",
  ui_story_1021_10210700_95_dialog_content = "É isso que você está procurando?",
  ui_story_1021_10210700_96_dialog_content = "Um trono é a coisa perfeita para dissipar a fadiga de um monarca. Também é um símbolo de sua autoridade...",
  ui_story_1021_10210700_97_dialog_content = "Então eles moldaram o trono da rainha a partir do primeiro pinheiro nevado... Mas eu não acho que já a vi sentar nele...",
  ui_story_1021_10210700_98_dialog_content = "Será que ela se recusa a descansar nele porque conhece suas origens?",
  ui_story_1021_10210700_99_dialog_content = "...",
  ui_story_1021_10210700_100_dialog_content = "Parece que o trono está mudando!",
  ui_story_1021_10210700_101_dialog_content = "Vossa Majestade, em nome das tribos que juraram lealdade ao Queen do Norte, permita-me apresentar-lhe isto - um trono digno de sua soberania.",
  ui_story_1021_10210700_102_dialog_content = "A partir deste dia, você pode olhar para seus súditos do topo deste assento de poder.",
  ui_story_1021_10210700_103_dialog_content = "Meu fiel servo, você sabe quanto tempo levaria para percorrer toda a extensão e largura de Northland?",
  ui_story_1021_10210700_104_dialog_content = "E-Eu não tenho certeza, Vossa Majestade... Mas por que pergunta?",
  ui_story_1021_10210700_105_dialog_content = "Não há como eu proteger Northland de cima de um trono frio. Para preservar nossa bela terra, preciso viajar para todos os cantos dela.",
  ui_story_1021_10210700_106_dialog_content = "Mas à medida que a neve cai, os caminhos que você trilha inevitavelmente desaparecerão, e você terá que criar novos.",
  ui_story_1021_10210700_107_dialog_content = "As florestas também mudarão com a chegada de cada nova primavera.",
  ui_story_1021_10210700_108_dialog_content = "Então eu viajarei sem descanso, patrulhando a terra até que cada canto dela esteja sob a luz protetora do Farol.",
  ui_story_1021_10210700_109_dialog_content = "Foi isso...",
  ui_story_1021_10210700_110_dialog_content = "Acabamos de presenciar o momento em que Sua Majestade se tornou pela primeira vez Queen do Norte?",
  ui_story_1021_10210700_111_dialog_content = "Conseguimos ver isso sem o uso dos meus poderes... Deve ter acontecido ainda antes disso...",
  ui_story_1021_10210700_112_dialog_content = "As tribos de Northland criaram um trono para ela como símbolo de sua lealdade, mas ela se recusou a sentar-se nele.",
  ui_story_1021_10210700_113_dialog_content = "E desde que Queen Bethlehem herdou sua vontade, ela tem viajado pela terra sem descanso...",
  ui_story_1021_10210700_114_dialog_content = "Olha!",
  ui_story_1021_10210700_115_dialog_content = "O trono se transformou em um pequeno galho...",
  ui_story_1021_10210700_116_dialog_content = "Parece que este é o pinheiro de neve que estávamos procurando.",
  ui_story_1021_10210700_117_dialog_content = "Que poder incrível!",
  ui_story_1021_10210700_118_dialog_content = "Com isso, poderemos ajudar a rainha...",
  ui_story_1021_10210700_119_dialog_content = "Isso mesmo, e agora estamos a caminho da nossa próxima parada - sua casa!",
  ui_story_1021_10210700_120_dialog_content = "Então vamos!",
  ui_story_1021_10210700_121_dialog_content = "Ei! Da próxima vez que você for em uma caçada lendária, me deixe ir com você!",
  ui_story_1021_10210700_122_dialog_content = "<color=#e8d9bb>A partir daquele momento, a Queen do Norte não tem mais um trono.</color>",
  ui_story_1021_10210801_1_dialog_content = "<color=#e8d9bb>Uau, uau, uau—</color>",
  ui_story_1021_10210801_2_dialog_content = "O clima mudou de repente...",
  ui_story_1021_10210801_3_dialog_content = "O Farol está completamente engolido por uma nevasca. Eu me pergunto como Sua Majestade e os outros estão...",
  ui_story_1021_10210801_4_dialog_content = "Então, você tem alguma ideia de onde encontrar o próximo pinheiro nevado?",
  ui_story_1021_10210801_5_dialog_content = "A próxima parte da lenda diz, \"Sua sagrada aliança transforma a escuridão em luz.\"",
  ui_story_1021_10210801_6_dialog_content = "Lembro-me de minha avó mencionar algo sobre isso...",
  ui_story_1021_10210801_7_dialog_content = "Northland passou por uma era de escuridão em algum momento do passado e só emergiu dela por causa de um antigo pacto com o divino.",
  ui_story_1021_10210801_8_dialog_content = "Um pacto, huh? Soa muito abstrato para mim...",
  ui_story_1021_10210801_9_dialog_content = "Mas um pacto sempre existirá enquanto alguém se lembrar e o cumprir.",
  ui_story_1021_10210801_10_dialog_content = "Pelo menos foi o que minha avó me disse...",
  ui_story_1021_10210801_11_dialog_content = "Acho que tenho uma ideia...",
  ui_story_1021_10210801_12_dialog_content = "Tenho quase certeza de que sua avó era exatamente esse tipo de pessoa, o que significa que eu poderia ser capaz de encontrar uma pista dentro das suas lembranças dela...",
  ui_story_1021_10210801_13_dialog_content = "Sério?",
  ui_story_1021_10210801_14_dialog_content = "Mas minha avó faleceu há tanto tempo... Não sei se minhas memórias são tão úteis quanto você pensa...",
  ui_story_1021_10210801_15_dialog_content = "Por quê?",
  ui_story_1021_10210801_16_dialog_content = "... Você saberá assim que vê-los.",
  ui_story_1021_10210801_17_dialog_content = "Não se preocupe, tenho certeza que vou encontrar algo!",
  ui_story_1021_10210801_18_option_content = "Ligação Telepática—",
  ui_story_1021_10210801_19_dialog_content = "Basta! Eu me recuso a ouvir mais!",
  ui_story_1021_10210801_20_dialog_content = "O quê, não posso dizer mais algumas coisas antes do meu tempo chegar?",
  ui_story_1021_10210801_21_dialog_content = "Vovó... Isso significa que você não vai mais brincar comigo?",
  ui_story_1021_10210801_22_dialog_content = "Temo que não, minha pequena Tiare... Prometa-me que será uma boa menina e crescerá grande e forte, certo?",
  ui_story_1021_10210801_23_dialog_content = "Se você pudesse fazer isso antes, Tiare...",
  ui_story_1021_10210801_24_dialog_content = "Se eu tenho um arrependimento na vida, é que eu não estarei por perto tempo suficiente para ver você crescer...",
  ui_story_1021_10210801_25_dialog_content = "Em poucos anos, estarei me juntando aos meus entes queridos que já partiram...",
  ui_story_1021_10210801_26_dialog_content = "Não se esqueça da sua velha avó, Tiare... ou da sua tribo... Lembre-se sempre...",
  ui_story_1021_10210801_27_dialog_content = "Pare de machucar todos com suas palavras. Logo, nenhum de nós estará vivo para lembrá-las.",
  ui_story_1021_10210801_28_dialog_content = "Vá brincar com as outras raposas lá, Tiare.",
  ui_story_1021_10210801_29_dialog_content = "Uau... Esta é a minha cauda, e...",
  ui_story_1021_10210801_30_dialog_content = "Isto é... Não, espere, deixe-me adivinhar!",
  ui_story_1021_10210801_31_dialog_content = "Você nunca mais deve trazer Tiare aqui.",
  ui_story_1021_10210801_32_dialog_content = "Tiare é uma criança desta tribo. Ela nunca pode esquecer a glória de seu povo, ou as bênçãos de seus antepassados que levaram ao seu nascimento.",
  ui_story_1021_10210801_33_dialog_content = "Ela se tornará a líder desta tribo e uma verdadeira guardiã de Northland. Eu vou garantir isso...",
  ui_story_1021_10210801_34_dialog_content = "E quando esse dia chegar, ela será a única a perceber essa aliança.",
  ui_story_1021_10210801_35_dialog_content = "No passado, as tribos de Northland se mantinham unidas, mas agora apenas as raposas da neve permanecem para proteger nossa terra.",
  ui_story_1021_10210801_36_dialog_content = "Nunca veremos a realização do pacto. Talvez a <color=#FFB400>tábua</color> tenha sido quase que completamente esquecida pelo divino.",
  ui_story_1021_10210801_37_dialog_content = "Não me deixe ouvir você dizer isso para Tiare, seu velho raposo empoeirado.",
  ui_story_1021_10210801_38_dialog_content = "O divino nunca esquecerá, e enquanto Tiare estiver vivo, nós também não esqueceremos.",
  ui_story_1021_10210801_39_dialog_content = "... Então vou destruir o tablet antes que Tiare descubra.",
  ui_story_1021_10210801_40_dialog_content = "Você valoriza esse tablet mais do que qualquer outra pessoa. Você nunca faria uma coisa dessas.",
  ui_story_1021_10210801_41_dialog_content = "Eu não tenho outra escolha.",
  ui_story_1021_10210801_42_dialog_content = "É tão errado esconder essas coisas dela? Apenas olhe para ela, brincando feliz como uma criança normal. Isso não é suficiente?",
  ui_story_1021_10210801_43_dialog_content = "O dever dela é proteger a tribo, não aquele palácio de gelo!",
  ui_story_1021_10210801_44_dialog_content = "A família real roubou o poder do divino sem dar nada em troca. Não só isso, eles também selaram nossos valentes soldados em uma tumba congelada, juntamente com os invasores de Northland...",
  ui_story_1021_10210801_45_dialog_content = "Já se passou mais de um milênio... Mas houve alguma mudança no gelo?",
  ui_story_1021_10210801_46_dialog_content = "Você acha que Tiare continuará tão feliz se souber sobre o nosso passado trágico?",
  ui_story_1021_10210801_47_dialog_content = "Pacto, proteção... Tudo isso parece tão cruel para mim agora.",
  ui_story_1021_10210801_48_dialog_content = "A crueldade que eu vi em você desde o momento em que você nasceu, e até—",
  ui_story_1021_10210801_49_dialog_content = "Isso é suficiente. O coração de Tiare será forte o suficiente para enfrentar essa crueldade, assim como seus grandes ancestrais antes dela.",
  ui_story_1021_10210801_50_dialog_content = "...",
  ui_story_1021_10210801_51_dialog_content = "Vovó—essa raposa te chamou de velha bruxa malvada! Hahaha! Pare com isso, isso faz cócegas!",
  ui_story_1021_10210801_52_dialog_content = "Eu... Eu não vou perder para você!",
  ui_story_1021_10210801_53_dialog_content = "...",
  ui_story_1021_10210801_54_dialog_content = "O que foi?",
  ui_story_1021_10210801_55_dialog_content = "... Você viu eles discutindo, não viu?",
  ui_story_1021_10210801_56_dialog_content = "É. Eles estavam divididos sobre se deveriam ou não deixar você se tornar o líder da sua tribo.",
  ui_story_1021_10210801_57_dialog_content = "Eu não fazia ideia de que o ancião não queria que você liderasse as raposas da neve...",
  ui_story_1021_10210801_58_dialog_content = "Eu sei... A anciã nunca foi de acolher estranhos - ela nem mesmo queria que eu voltasse para a tribo...",
  ui_story_1021_10210801_59_dialog_content = "Talvez seja porque ela sabia que acabaria assim sob a minha liderança.",
  ui_story_1021_10210801_60_dialog_content = "Não é nada disso. O ancião estava preocupado que você nunca mais seria feliz e que passaria a vida em ódio, como sua avó.",
  ui_story_1021_10210801_61_dialog_content = "Feliz?",
  ui_story_1021_10210801_62_dialog_content = "Então é por isso que ela queria que eu cortasse laços com a tribo e servisse como guarda da rainha...",
  ui_story_1021_10210801_63_dialog_content = "Ela manteve este segredo para si mesma todo esse tempo...",
  ui_story_1021_10210801_64_dialog_content = "Nunca me deixando chegar perto do altar...",
  ui_story_1021_10210801_65_dialog_content = "Ou me contando sobre a lenda...",
  ui_story_1021_10210801_66_dialog_content = "Mesmo quando a tribo estava em perigo, ela me afastou...",
  ui_story_1021_10210801_67_dialog_content = "A anciã tem um profundo amor pela sua tribo, mas ela te ama ainda mais, Tiare...",
  ui_story_1021_10210801_68_dialog_content = "...",
  ui_story_1021_10210801_69_dialog_content = "É por isso que não posso abandonar minha promessa como líder das raposas da neve!",
  ui_story_1021_10210801_70_dialog_content = "Eu acredito em Sua Majestade! Se ela diz que invocar o Primal Haven salvará minha tribo, então deve ser verdade!",
  ui_story_1021_10210801_71_dialog_content = "Até então, a anciã nunca me forçará a sair!",
  ui_story_1021_10210801_72_dialog_content = "Eu sei que você consegue, Tiare!",
  ui_story_1021_10210801_73_dialog_content = "Mas mesmo depois de vasculhar minhas memórias, ainda não encontramos nenhuma pista sobre o paradeiro do snowpine, encontramos?",
  ui_story_1021_10210801_74_dialog_content = "Não, eles falaram sobre uma tábua... Aparentemente, ela registrou um pacto entre o divino e a FoxTribo da Neve?",
  ui_story_1021_10210801_75_dialog_content = "Um tablet...",
  ui_story_1021_10210801_76_dialog_content = "Sua avó disse que o mais velho valorizava isso mais do que qualquer um.",
  ui_story_1021_10210801_77_dialog_content = "Mas é possível que ela já tenha destruído...",
  ui_story_1021_10210801_78_dialog_content = "...",
  ui_story_1021_10210801_79_dialog_content = "Pense nisso. Se a anciã realmente valorizava isso, então ela deve ter ido a algum lugar para vê-lo com bastante frequência.",
  ui_story_1021_10210801_80_dialog_content = "Lugares onde o ancião costuma ir... A caverna, o altar, as montanhas, e...",
  ui_story_1021_10210801_81_dialog_content = "Será que...",
  ui_story_1021_10210801_82_dialog_content = "Antes de eu deixar a tribo, havia um lugar onde o ancião passava o dia olhando para o Farol. Não é longe daqui.",
  ui_story_1021_10210801_83_dialog_content = "Não vejo nada além de árvores por aqui...",
  ui_story_1021_10210801_84_dialog_content = "... Quem está aí? Mostrem-se!",
  ui_story_1021_10210801_85_dialog_content = "Uh-oh... Parece que você nos encontrou de novo...",
  ui_story_1021_10210801_86_dialog_content = "Vocês dois de novo!",
  ui_story_1021_10210801_87_dialog_content = "Vamos lá, essa é realmente uma maneira de nos recompensar? Afinal, passamos por todo o trabalho de limpar os Eclipsitas deste lugar.",
  ui_story_1021_10210801_88_dialog_content = "Eu dificilmente acredito que um ladrão de joias como você poderia ser tão bondoso! Agora, o que você roubou desta vez?",
  ui_story_1021_10210801_89_dialog_content = "Nada mesmo, eu te asseguro. Tivemos sorte de escapar daquela caverna apenas com nossas vidas!",
  ui_story_1021_10210801_90_dialog_content = "Uh... Acho que você deveria apenas contar a verdade para eles, Roy.",
  ui_story_1021_10210801_91_dialog_content = "Você disse que, como membro da equipe conjunta de exploração, a Rediesel Wrench nunca desconsideraria as vidas ou a segurança de nossos aliados.",
  ui_story_1021_10210801_92_dialog_content = "Como não conseguimos encontrar nenhum de vocês depois que saímos da caverna, Roy e eu decidimos acabar com os Eclipsitas que apareceram nesta área!",
  ui_story_1021_10210801_93_dialog_content = "É verdade, não vimos um único Eclipsita no nosso caminho até aqui... Nós realmente devemos a vocês!",
  ui_story_1021_10210801_94_dialog_content = "Do que você está falando? Por mais distante que este lugar esteja, ainda está protegido pela luz do Farol!",
  ui_story_1021_10210801_95_dialog_content = "... C-Como deveríamos saber disso? Não há nenhum marcador por aqui ou algo assim! Você está dizendo que não precisávamos lutar contra esses Eclipsitas agora mesmo?",
  ui_story_1021_10210801_96_dialog_content = "Na verdade, tenho quase certeza de que vi um marcador mais cedo, Roy...",
  ui_story_1021_10210801_97_dialog_content = "Tiare! Será que aquele marcador poderia ser—",
  ui_story_1021_10210801_98_dialog_content = "O tablet!",
  ui_story_1021_10210801_99_dialog_content = "Estenda sua lança e veja o que acontece!",
  ui_story_1021_10210801_100_dialog_content = "Todos energizados pela natureza!",
  ui_story_1021_10210801_101_dialog_content = "Não teríamos desperdiçado nossa energia se tivesse brilhado assim mais cedo...",
  ui_story_1021_10210801_102_dialog_content = "Esta inscrição brilhante... Deve ter sido escrita com óleo de pinho da neve.",
  ui_story_1021_10210801_103_dialog_content = "Minha avó uma vez disse que nossas lamparinas de óleo de pinho eram os olhos de todo o Northland.",
  ui_story_1021_10210801_104_dialog_content = "Aposto que brilha muito à noite...",
  ui_story_1021_10210801_105_dialog_content = "Nunca teria pensado que um dos pinheiros de neve estava sendo usado como um marcador para o limite do Farol.",
  ui_story_1021_10210801_106_dialog_content = "Uau! O que está acontecendo?",
  ui_story_1021_10210801_107_dialog_content = "Valentes guardas de Northland! A guerra acabou e a construção do Farol está agora completa.",
  ui_story_1021_10210801_108_dialog_content = "Esta fortaleza congelada permanecerá em comemoração às vidas perdidas na defesa das fronteiras de Northland. Servirá como um lembrete para nosso povo e um aviso para nossos inimigos.",
  ui_story_1021_10210801_109_dialog_content = "Para todos que estão aqui reunidos hoje, eu prometo a vocês:",
  ui_story_1021_10210801_110_dialog_content = "A luz do Farol protegerá este lugar. Não será mais o ponto de encontro entre a escuridão e a luz!",
  ui_story_1021_10210801_111_dialog_content = "Suas famílias compartilharão da paz e prosperidade de Northland.",
  ui_story_1021_10210801_112_dialog_content = "May toda a natureza sirva como minha testemunha, e May o Farol de Northland proteja nosso belo reino.",
  ui_story_1021_10210801_113_dialog_content = "Também peço que você, juntamente com o divino, testemunhe esta aliança, que estendo às suas tribos.",
  ui_story_1021_10210801_114_dialog_content = "Como o primeiro Queen do Norte, eu juro que meus descendentes defenderão nossa terra até o fim!",
  ui_story_1021_10210801_115_dialog_content = "Como líderes tribais de Northland, juramos que nossos descendentes defenderão nossa terra até o fim!",
  ui_story_1021_10210801_116_dialog_content = "A primeira rainha de Northland era realmente algo especial...",
  ui_story_1021_10210801_117_dialog_content = "Então a aliança não era entre sua tribo e o divino...",
  ui_story_1021_10210801_118_dialog_content = "Foi uma promessa entre a primeira rainha e todos os guardas de fronteira...",
  ui_story_1021_10210801_119_dialog_content = "É por isso que meus ancestrais sempre vigiaram este lugar. Mas a rainha não cumpriu sua promessa, e nossa tribo entrou em declínio...",
  ui_story_1021_10210801_120_dialog_content = "É daí que vem a nossa hostilidade em relação à família real...",
  ui_story_1021_10210801_121_dialog_content = "Parece impossível fazer a luz do Farol chegar até este lugar...",
  ui_story_1021_10210801_122_dialog_content = "Eu sei... Mas por anos, a rainha tem patrulhado constantemente as fronteiras da terra.",
  ui_story_1021_10210801_123_dialog_content = "Eu sinceramente acredito que nenhum dos lados falhou em cumprir sua promessa.",
  ui_story_1021_10210801_124_dialog_content = "E agora eles me confiaram a tarefa de invocar o Primal Haven e defender Northland...",
  ui_story_1021_10210801_125_dialog_content = "Isso deve ser o que o senhor Novio queria que eu entendesse!",
  ui_story_1021_10210801_126_dialog_content = "Procurar pelos pinheiros nevados me deu uma compreensão completamente nova de Northland.",
  ui_story_1021_10210801_127_dialog_content = "Parece que está voltando à sua forma original, assim como o trono da rainha...",
  ui_story_1021_10210801_128_dialog_content = "E com isso, encontramos o segundo pinheiro de neve!",
  ui_story_1021_10210801_129_dialog_content = "Quanto ao terceiro, eu me pergunto se Queen Bethlehem realmente pretende extinguir o Farol de Northland por isso...",
  ui_story_1021_10210801_130_dialog_content = "Não tenho mais dúvidas em minha mente! Seja o que for que a rainha decida fazer, estarei lá para ajudá-la a realizar!",
  ui_story_1021_10210801_131_dialog_content = "Vamos levar esses dois pinheiros de neve de volta para eles!",
  ui_story_1021_10210801_132_dialog_content = "Direita!",
  ui_story_1021_10210801_133_dialog_content = "Ah, e... Obrigado, vocês dois!",
  ui_story_1021_10210801_134_dialog_content = "Haha, não mencione isso.",
  ui_story_1021_10210801_135_dialog_content = "Devemos ajudá-los agora que os encontramos, Roy.",
  ui_story_1021_10210801_136_dialog_content = "Ah, eu suponho. Vamos, vamos.",
  ui_story_1021_10210801_137_dialog_content = "<color=#e8d9bb>A partir daquele momento, a tábua que carregava a promessa entre a rainha e as tribos de Northland se foi.</color>",
  ui_story_1021_10210801_138_dialog_content = "Ancião! Senhor Novio! Estamos de volta com o—",
  ui_story_1021_10210801_139_dialog_content = "O que está acontecendo acima do altar?",
  ui_story_1021_10210801_140_dialog_content = "Queen Bethlehem está extraindo o poder da Centelha de dentro de seu corpo e condensando-o na Pavio.",
  ui_story_1021_10210801_141_dialog_content = "A Pavio? Isso significa que o Farol perto do penhasco foi apagado?",
  ui_story_1021_10210801_142_dialog_content = "Não. Na verdade, Sua Majestade tem atuado como o Farol de Northland há muito tempo. O que você vê diante de você é a própria força vital dela.",
  ui_story_1021_10210801_143_dialog_content = "A própria força vital dela... Mas isso não a enfraquece muito?",
  ui_story_1021_10210801_144_dialog_content = "Sim, mas também permite que ela expulse os Eclipsitas das fronteiras de Northland.",
  ui_story_1021_10210801_145_dialog_content = "Vossa Majestade...",
  ui_story_1021_10210801_146_dialog_content = "Embora inúmeros anos tenham passado desde então, o Farol prometido a este lugar finalmente será construído - com a sua ajuda, é claro.",
  ui_story_1021_10210801_147_dialog_content = "Então o que eu deveria fazer agora?",
  ui_story_1021_10210801_148_dialog_content = "Você deve colocar os pinheiros de neve no altar e devolver o poder em sua lança ao divino junto com eles.",
  ui_story_1021_10210801_149_dialog_content = "Venha, vamos rezar ao divino...",
  ui_story_1021_10210801_150_dialog_content = "Eu, Hagen, ancião da Tribo da Neve Fox e guardião do Senhor Rode, deus da guerra de Northland, imploro pela intervenção divina!",
  ui_story_1021_10210801_151_dialog_content = "Eu, Tiare, líder da Tribo da Neve Fox e guardião de Bethlehem, Queen do Norte, imploro pela intervenção divina!",
  ui_story_1021_10210801_152_dialog_content = "A Queen do Norte honrou seu pacto! Seu poder é o seu próprio, assim como o poder dentro desses galhos!",
  ui_story_1021_10210801_153_dialog_content = "Por favor, aceite-os e nutra os Três Pinheiros de Neve com sua força vital, para que eles possam crescer novamente!",
  ui_story_1021_10210801_154_dialog_content = "Abençoe nossas terras antigas e sagradas com sua proteção eterna—",
  ui_story_1021_10210801_155_dialog_content = "Conceda-me poder, Cajado Terra!",
  ui_story_1021_10210801_156_dialog_content = "<color=#e8d9bb>Uau, uau—</color>",
  ui_story_1021_10210801_157_dialog_content = "!",
  ui_story_1021_10210801_158_dialog_content = "Os três tocos... Eles de repente se transformaram em uma única árvore colossal!",
  ui_story_1021_10210801_159_dialog_content = "Este é o poder do Primal Haven?",
  ui_story_1021_10210801_160_dialog_content = "...",
  ui_story_1021_10210801_161_dialog_content = "O poder dentro da minha lança não foi retirado... Se alguma coisa, parece que um poder maior está fluindo para ela!",
  ui_story_1021_10210801_162_dialog_content = "Essa coisa está piscando como um raio... Será que é energia vindo de dentro dos pinheiros de neve?",
  ui_story_1021_10210801_163_dialog_content = "...",
  ui_story_1021_10210801_164_dialog_content = "Aqui no topo do mundo, nossos ancestrais descobriram um riacho quente e suave.",
  ui_story_1021_10210801_165_dialog_content = "Este riacho, como uma bênção dos céus, serpenteava pela paisagem congelada de Northland durante todo o ano e se estendia até os confins de Astra...",
  ui_story_1021_10210801_166_dialog_content = "Esta foi a origem do Primal Haven. O riacho trouxe vida à Floresta Snowpine, que por sua vez deu vida aos nossos primeiros ancestrais.",
  ui_story_1021_10210801_167_dialog_content = "Sob a proteção do Primal Haven, os snowpines e o Wick se uniram para criar este novo Farol.",
  ui_story_1021_10210801_168_dialog_content = "Sua luz atravessará o longo inverno e as montanhas cobertas de neve, dissipando a escuridão e iluminando nossas terras amadas.",
  ui_story_1021_10210801_169_dialog_content = "Além disso, Tiare, você foi escolhido pelo divino para servir como um verdadeiro guardião de Northland.",
  ui_story_1021_10210801_170_dialog_content = "O divino me escolheu... e me abençoou com poder!",
  ui_story_1021_10210801_171_dialog_content = "O poder dentro desta lança congelada se enfurece como fogo. Parece uma tocha em minha mão!",
  ui_story_1021_10210801_172_dialog_content = "Tiare, a partir de hoje, você deve carregar o peso tanto da força divina quanto do dever...",
  ui_story_1021_10210801_173_dialog_content = "Empregue sua coragem e sabedoria na defesa de toda Northland.",
  ui_story_1021_10210802_1_dialog_content = "Um feixe de luz vindo da Floresta Snowpine? Poderia ser um conjunto de ruínas antigas ainda não descoberto?",
  ui_story_1021_10210802_2_dialog_content = "Ou talvez seja algum tipo de sinal?",
  ui_story_1021_10210802_3_dialog_content = "O Farol das lendas oferece orientação e proteção para todo o Northland. Será possível que exista mais de um farol?",
  ui_story_1021_10210802_4_dialog_content = "Se sim, como eles são distribuídos?",
  ui_story_1021_10210802_5_dialog_content = "E qual efeito a luz deles tem sobre a terra?",
  ui_story_1021_10210802_6_dialog_content = "<color=#e8d9bb>Em um canto escondido da terra</color>",
  ui_story_1021_10210802_7_dialog_content = "Então, Northland realmente contém um poder assim afinal.",
  ui_story_1021_10210802_8_dialog_content = "O riacho retomou seu fluxo e rapidamente alcançará o mar.",
  ui_story_1021_10210802_9_dialog_content = "Acho que a Senhora Victoria ficará muito satisfeita com nossas descobertas.",
  ui_story_1021_10210802_10_dialog_content = "Então vamos partir imediatamente.",
  ui_story_1021_10210802_11_dialog_content = "<color=#e8d9bb>A bordo de uma aeronave da Federação Illumina</color>",
  ui_story_1021_10210802_12_dialog_content = "Nunca vi uma luz assim antes... como o sol da manhã surgindo atrás das montanhas nevadas.",
  ui_story_1021_10210802_13_dialog_content = "Defina um curso em direção àquela luz! Velocidade máxima a frente!",
  ui_story_1021_10210802_14_dialog_content = "Sim, Grande Marechal!",
  ui_story_1021_10210901_1_dialog_content = "Parece que... o novo Farol está agora completo.",
  ui_story_1021_10210901_2_dialog_content = "Sua Majestade! Você está ferido? Mal posso suportar vê-lo em um estado tão enfraquecido...",
  ui_story_1021_10210901_3_dialog_content = "Estou bem, Carleen. Todo o Northland está sob uma proteção ainda maior agora, assim como eu.",
  ui_story_1021_10210901_4_dialog_content = "Graah!",
  ui_story_1021_10210901_5_dialog_content = "(Eclipsiano) Meu senhor... Está queimando...",
  ui_story_1021_10210901_6_dialog_content = "(Em Eclipsiano) Queima!",
  ui_story_1021_10210901_7_dialog_content = "(Eclipsiano) Essa sensação... eu me lembro agora...",
  ui_story_1021_10210901_8_dialog_content = "(Eclipsiano) Uma garota cavalgando pela neve nas costas de um alce...",
  ui_story_1021_10210901_9_dialog_content = "(Eclipsian) Eu me lembro de tudo agora.",
  ui_story_1021_10210901_10_dialog_content = "(Eclipsiano) Parece que meus testes provaram ser valiosos.",
  ui_story_1021_10210901_11_dialog_content = "Todos carregados!",
  ui_story_1021_10210901_12_dialog_content = "...",
  ui_story_1021_10210901_13_dialog_content = "Graah!",
  ui_story_1021_10210901_14_dialog_content = "Vossa Majestade! Carleen! Desculpe pelo atraso!",
  ui_story_1021_10210901_15_dialog_content = "O ataque agora há pouco foi inacreditável, Tiare!",
  ui_story_1021_10210901_16_dialog_content = "Tanto a sua lança quanto a sua força parecem ter ficado muito mais fortes!",
  ui_story_1021_10210901_17_dialog_content = "A anciã disse que isso é a prova de que o divino me reconheceu. Agora sou uma guarda digna da rainha!",
  ui_story_1021_10210901_18_dialog_content = "E um guardião de toda a Northland!",
  ui_story_1021_10210901_19_dialog_content = "Isso mesmo!",
  ui_story_1021_10210901_20_dialog_content = "Posso sentir o quanto você cresceu, Tiare. Muito bem.",
  ui_story_1021_10210901_21_dialog_content = "Obrigado por me ajudar a criar este novo Farol.",
  ui_story_1021_10210901_22_dialog_content = "Sua Majestade! Acabei de descobrir sobre a história do trono no Palácio de Inverno, aprendendo o compromisso entre a família real e as tribos... e também...",
  ui_story_1021_10210901_23_dialog_content = "Tenho tanto para te contar! Mas a coisa que eu mais quero dizer é essa—",
  ui_story_1021_10210901_24_dialog_content = "A partir de agora, eu, Tiare, sempre estarei ao seu lado! Você nunca mais terá que enfrentar nenhuma batalha sozinho, Sua Majestade!",
  ui_story_1021_10210901_25_dialog_content = "\"A neve derretida carrega água através das montanhas e riachos, trazendo vida a esta terra abençoada...\"",
  ui_story_1021_10210901_26_dialog_content = "Prepare-se para morrer, Eclipsita!",
  ui_story_1021_10210901_27_dialog_content = "Espere, Tiare!",
  ui_story_1021_10210901_28_dialog_content = "Sua Majestade?",
  ui_story_1021_10210901_29_dialog_content = "Não só você sabe sobre aquela batalha, mas também sabe sobre a bênção de Northland? Como?",
  ui_story_1021_10210901_30_dialog_content = "Naquela época, um silêncio mortal tomou conta dessas terras nevadas.",
  ui_story_1021_10210901_31_dialog_content = "Um sol negro como breu pairava no céu acima, e a chegada do nosso deus estava próxima...",
  ui_story_1021_10210901_32_dialog_content = "Mas então aquela garota apareceu...",
  ui_story_1021_10210901_33_dialog_content = "...",
  ui_story_1021_10210901_34_dialog_content = "Você viu o primeiro Queen de Northland?",
  ui_story_1021_10210901_35_dialog_content = "Com um feixe de luz em sua mão, ela estilhaçou a cúpula e nos separou de nosso deus para sempre.",
  ui_story_1021_10210901_36_dialog_content = "Eu queria desesperadamente olhar para o sol preto uma última vez.",
  ui_story_1021_10210901_37_dialog_content = "Mas com a arma em suas mãos, ela me atacou cegamente.",
  ui_story_1021_10210901_38_dialog_content = "Lembrei-me de tudo depois deste julgamento...",
  ui_story_1021_10210901_39_dialog_content = "A última chama que meus olhos viram não era a minha raiva...",
  ui_story_1021_10210901_40_dialog_content = "Nunca foi raiva, pra começo de conversa!",
  ui_story_1021_10210901_41_dialog_content = "Era um feixe de luz dançante que pintou meu mundo com raiva!",
  ui_story_1021_10210901_42_dialog_content = "(Eclipsiano) Não temo nem o frio nem a chama...",
  ui_story_1021_10210901_43_dialog_content = "(Eclipsiano) Mas aquela luz branca, cintilante... Eu só quero saber o que é...",
  ui_story_1021_10210901_44_dialog_content = "O Farol! É o Farol da rainha!",
  ui_story_1021_10210901_45_dialog_content = "A rainha trouxe a luz do Farol para nos salvar!",
  ui_story_1021_10210901_46_dialog_content = "(Eclipsiano) O Farol...",
  ui_story_1021_10210901_47_dialog_content = "Graah!",
  ui_story_1021_10210901_48_dialog_content = "Eu me lembro de tudo agora.",
  ui_story_1021_10210901_49_dialog_content = "Tudo...",
  ui_story_1021_10210901_50_dialog_content = "Meu julgamento acabou. Vocês podem ir embora com suas vidas intactas.",
  ui_story_1021_10210901_51_dialog_content = "...",
  ui_story_1021_10210901_52_dialog_content = "Não pense que vou deixar você escapar!",
  ui_story_1021_10210901_53_dialog_content = "Vou fazer você pagar pelo que fez às raposas e a toda a nossa tribo!",
  ui_story_1021_10210901_54_dialog_content = "Se você se recusar a sair... então venha e encontre seu fim.",
  ui_story_1021_10210901_55_dialog_content = "Tiare!",
  ui_story_1021_10210901_56_dialog_content = "Todos carregados!",
  ui_story_1021_10210901_57_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1021_10210901_58_dialog_content = "*tosses* M-Maldito Eclipsite... Não vou deixar você escapar...",
  ui_story_1021_10210901_59_dialog_content = "Tiare!",
  ui_story_1021_10210901_60_dialog_content = "Cuidado! Ele está tentando te puxar para a Zona Escura!",
  ui_story_1021_10210901_61_dialog_content = "Agora mesmo... Foi um disparo de canhão?",
  ui_story_1021_10210901_62_dialog_content = "Olhe para o céu, PlayerName—",
  ui_story_1021_10210901_63_dialog_content = "Perdemos nosso alvo, mas parece que PlayerName e os outros estão tentando entrar no domínio dos Eclipsitas.",
  ui_story_1021_10210901_64_dialog_content = "Abaixe a altitude e cubra-os!",
  ui_story_1021_10210901_65_dialog_content = "Sim, Grande Marechal!",
  ui_story_1021_10210901_66_dialog_content = "Eles estão abrindo fogo, Bethel! Isso significa que nós—",
  ui_story_1021_10210901_67_dialog_content = "Illumina e Lumopolis estão fornecendo reforços. Não atrapalhe o caminho deles.",
  ui_story_1021_10210901_68_dialog_content = "Precisamos subir ao convés e levantar a bandeira da expedição conjunta!",
  ui_story_1021_10210901_69_dialog_content = "Todas as forças estão prontas para serem implantadas. Podemos pousar a qualquer momento, senhor!",
  ui_story_1021_10210901_70_dialog_content = "Extermine quaisquer Eclipsitas que encontrar ao longo da fronteira e reforce as posições dos soldados de Northland. Deixe a batalha principal para nossos jovens amigos.",
  ui_story_1021_10210901_71_dialog_content = "Sim, meu senhor!",
  ui_story_1021_10210901_72_dialog_content = "É uma aeronave da Illumina...",
  ui_story_1021_10210901_73_dialog_content = "Assim como um dirigível de Lumopolis... Todos eles estão focando em nossa posição atual.",
  ui_story_1021_10210901_74_dialog_content = "Mas parece que aquele Eclipsite está tentando provocar Tiare e nos atrair para ir em direção a ele...",
  ui_story_1021_10210901_75_dialog_content = "Tiare é rápida! Ela está prestes a ultrapassar a parede à nossa frente!",
  ui_story_1021_10210901_76_dialog_content = "Assim que cruzarmos aquela parede, temo que não haverá como voltar atrás.",
  ui_story_1021_10210901_77_dialog_content = "Mesmo assim, a luz do Farol deve alcançar além disso. Venha comigo.",
  ui_story_1021_10210901_78_dialog_content = "Vou ajudá-lo a chegar ao topo da montanha criando um caminho de gelo. Devemos ajudar Tiare a expulsar esse Eclipsita de Northland de uma vez por todas!",
  ui_story_1021_10210901_79_dialog_content = "Direita!",
  ui_story_1021_10210901_80_dialog_content = "Tiare!",
  ui_story_1021_10210901_81_dialog_content = "Não nos deixe para trás assim! Estamos todos juntos nessa!",
  ui_story_1021_10210901_82_dialog_content = "Vossa Majestade! Meus amigos! E vocês dois também?",
  ui_story_1021_10210901_83_dialog_content = "Não se esqueça, o Rediesel também faz parte da expedição conjunta!",
  ui_story_1021_10210901_84_dialog_content = "Isso mesmo. Afinal, vocês são os que disseram que deveríamos ter uma cerimônia de boas-vindas emocionante antes de começar a expedição.",
  ui_story_1021_10210901_85_dialog_content = "Eu não me lembro de ter dito algo sobre isso...",
  ui_story_1021_10210901_86_dialog_content = "Mas como guarda de Northland, dou-lhe minha palavra de que não descansarei até que esses Eclipsitas sejam expulsos de nossas terras!",
  ui_story_1021_10210901_87_dialog_content = "Sem sequer perceber, a expedição conjunta já chegou tão longe em sua jornada.",
  ui_story_1021_10210901_88_dialog_content = "Logo à frente está o território dos Eclipsitas, mas monstros sanguinários como eles não têm lugar neste mundo!",
  ui_story_1021_10210901_89_dialog_content = "Vamos seguir a luz do Farol e exterminá-los sem piedade!",
  ui_story_1021_10210901_90_dialog_content = "Essas são palavras poderosas vindas da rainha...",
  ui_story_1021_10210901_91_dialog_content = "Com Tiare como minha guarda, não posso deixar de me sentir inspirado por ela.",
  ui_story_1021_10210901_92_dialog_content = "Reúna sua coragem e mantenha um ao outro perto do coração, pois o futuro de Northland e de todos os Aurorianos depende de nós...",
  ui_story_1021_10210901_93_dialog_content = "Ajam como faróis um para o outro, e sua força superará qualquer terror que possamos enfrentar.",
  ui_story_1021_10210901_94_dialog_content = "!",
  ui_story_1021_10210901_95_dialog_content = "Ei, olhe aquela pedra estilhaçada! Parece que o Eclipsita não vai se afastar muito dela!",
  ui_story_1021_10210901_96_dialog_content = "Então vamos destruí-lo juntos! Comigo, todos, marchamos para a Zona Escura!",
  ui_story_1021_10210901_97_dialog_content = "Em frente!",
  ui_story_1021_10210902_1_dialog_content = "Interessante. Isso foi muito além das minhas expectativas...",
  ui_story_1021_10210902_2_dialog_content = "Mas para ascender a maiores alturas, devo exercer autocontrole.",
  ui_story_1021_10210902_3_dialog_content = "Antes de partir, tenho uma última mensagem para todos vocês...",
  ui_story_1021_10210902_4_dialog_content = "Deixe o fedor da escuridão invadir seus sentidos e entre em nosso domínio...",
  ui_story_1021_10210902_5_dialog_content = "Os corpos daqueles que vieram antes de você estão empilhados tão alto quanto montanhas, e suas vozes chamarão seus nomes onde quer que você vá.",
  ui_story_1021_10210902_6_dialog_content = "Eu, Ira, o Protetor do Rei, aguardarei por você na terra da noite eterna.",
  ui_story_1021_10210902_7_dialog_content = "Estou ansioso para o nosso próximo encontro...",
  ui_story_1021_10211001_1_dialog_content = "Os Eclipsitas recuaram de Northland, e a fonte de luz do Farol estabilizou-se novamente.",
  ui_story_1021_10211001_2_dialog_content = "Nossos aliados chamaram de volta seus soldados?",
  ui_story_1021_10211001_3_dialog_content = "Sim, mas o Chefe de Gabinete da Federação Illumina está esperando pelo Caelestite e seu grupo no Vale do Pinheiro Frost.",
  ui_story_1021_10211001_4_dialog_content = "Apesar do posto avançado estar incompleto, parece que nossa expedição à Zona Escura oficialmente começou, e de maneira impressionante.",
  ui_story_1021_10211001_5_dialog_content = "Pelo menos, este novo Farol proporcionará a eles um refúgio temporário antes de se aprofundarem na Zona Escura.",
  ui_story_1021_10211001_6_dialog_content = "Isso significa que eles estarão partindo daqui?",
  ui_story_1021_10211001_7_dialog_content = "Sim, é por isso que devemos redobrar nossos esforços para terminar a construção do posto avançado.",
  ui_story_1021_10211001_8_dialog_content = "Vossa Majestade, os preparativos para nossa partida estão completos. Viemos para nos despedir.",
  ui_story_1021_10211001_9_dialog_content = "Carleen mal pode esperar para voltar e continuar suas aulas de voo. Não é mesmo?",
  ui_story_1021_10211001_10_dialog_content = "Isso não é... Há muitos outros assuntos urgentes para resolver...",
  ui_story_1021_10211001_11_dialog_content = "Então, desejo-lhe uma viagem segura. Obrigado mais uma vez por me ajudar a criar este novo Farol para Northland.",
  ui_story_1021_10211001_12_dialog_content = "Não poderíamos ter feito isso sem a Tiare também! Falando nisso, onde ela está?",
  ui_story_1021_10211001_13_dialog_content = "Ela também tem outros assuntos para tratar.",
  ui_story_1021_10211001_14_dialog_content = "Por favor, assegure aos membros da Equipe de Expedição que o posto avançado será concluído o mais rápido possível.",
  ui_story_1021_10211001_15_dialog_content = "O City Lord diz que enviará os Guardiões da Noite Branca para auxiliar na construção, embora a chegada deles possa ser adiada por dois dias.",
  ui_story_1021_10211001_16_dialog_content = "E eu conheço dois engenheiros especialistas que podem começar a trabalhar hoje!",
  ui_story_1021_10211001_17_dialog_content = "Você está certo! Esses dois têm pensado em joias há muito tempo. Por favor, considere qualquer coisa que eles tenham pego como um adiantamento do pagamento deles.",
  ui_story_1021_10211001_18_dialog_content = "Vocês dois certamente estão animados em nos colocar para trabalhar...",
  ui_story_1021_10211001_19_dialog_content = "Não temos ideia do que aconteceu com aquelas gemas... E se trabalharmos de graça, Honcho Sinsa não vai nos deixar ouvir o fim disso.",
  ui_story_1021_10211001_20_dialog_content = "Além disso, eu prefiro muito mais apoiar a todos do Deserto Rediesel, onde é agradável e quente. Northland é um lugar maravilhoso e tudo mais, mas eu preferiria não voltar nunca mais.",
  ui_story_1021_10211001_21_dialog_content = "E que tal se juntar a nós na expedição?",
  ui_story_1021_10211001_22_dialog_content = "Vamos ter que ver. Sou um homem muito ocupado, sabia?",
  ui_story_1021_10211001_23_dialog_content = "Este dia, que parecia tão distante apesar da minha previsão, está quase ao alcance.",
  ui_story_1021_10211001_24_dialog_content = "No passado, cada facção tinha sua própria posição, e a expedição conjunta não era nada mais do que uma aspiração política elevada.",
  ui_story_1021_10211001_25_dialog_content = "Mas agora, eles cuidam um do outro como verdadeiros camaradas de armas...",
  ui_story_1021_10211001_26_dialog_content = "Rezo para que a camaradagem deles os sustente e preserve enquanto entram na Zona Cega.",
  ui_story_1021_10211001_27_dialog_content = "<color=#e8d9bb>Perto do Vale da Geada de Pinha</color>",
  ui_story_1021_10211001_28_dialog_content = "PlayerName! Espere!",
  ui_story_1021_10211001_29_dialog_content = "E aí, Tiare?",
  ui_story_1021_10211001_30_dialog_content = "Trouxe alguns presentes para todos! Mas no caminho para cá, acidentalmente os deixei cair, junto com a pessoa que estava me ajudando a entregá-los. Desculpe!",
  ui_story_1021_10211001_31_dialog_content = "Você não pode continuar fazendo isso, Tiare. Nesse ritmo, ninguém terá coragem suficiente para andar com você...",
  ui_story_1021_10211001_32_dialog_content = "Então, o que você está planejando fazer agora? Nós adoraríamos ter você como membro da Equipe de Expedição, sabe?",
  ui_story_1021_10211001_33_dialog_content = "Com sua coragem e agilidade, tenho certeza de que você seria capaz de nos ajudar em qualquer situação perigosa!",
  ui_story_1021_10211001_34_dialog_content = "Sou grato pela sua oferta, mas não se esqueça de que tenho algo ainda mais importante para fazer agora.",
  ui_story_1021_10211001_35_dialog_content = "Depois de tudo que passamos juntos, percebo que meus deveres estão longe de terminar.",
  ui_story_1021_10211001_36_dialog_content = "Como um verdadeiro guarda de Northland, eu tenho que continuar dando o meu melhor!",
  ui_story_1021_10211001_37_dialog_content = "É por isso que decidi permanecer em Northland! Vou continuar a história iniciada pelos meus ancestrais raposas da neve e pelas rainhas passadas de Northland!",
  ui_story_1021_10211001_38_dialog_content = "Vou pedir para a anciã compartilhar todas as histórias que minha avó nunca me contou!",
  ui_story_1021_10211001_39_dialog_content = "Parece uma maneira significativa de honrar o legado deles! Não se esqueça, eu também estava lá para testemunhar parte da história!",
  ui_story_1021_10211001_40_dialog_content = "Se você ouvir alguma história nova, lembre-se de me contar tudo em uma carta!",
  ui_story_1021_10211001_41_dialog_content = "Ah! Há uma outra maneira—",
  ui_story_1021_10211001_42_dialog_content = "Grr...",
  ui_story_1021_10211001_43_dialog_content = "Grr...",
  ui_story_1021_10211001_44_dialog_content = "Por que vocês dois estão uivando como um bando de animais enquanto eu arrasto todas essas coisas sozinho?",
  ui_story_1021_10211001_45_dialog_content = "É aquele...",
  ui_story_1021_10211001_46_dialog_content = "Esse é Zarya, outro amigo que fiz em Northland.",
  ui_story_1021_10211001_47_dialog_content = "Então você é quem estava ajudando Tiare a carregar os presentes dela...",
  ui_story_1021_10211001_48_dialog_content = "Ela correu mais rápido que o vento! Eu a perdi completamente de vista antes mesmo de tocar o chão!",
  ui_story_1021_10211001_49_dialog_content = "Bem, isso é algo bastante comum quando você viaja com Tiare.",
  ui_story_1021_10211001_50_dialog_content = "É? Ou foi porque Tiare ainda estava bravo comigo?",
  ui_story_1021_10211001_51_dialog_content = "Humph! Foi sua culpa por atirar um monte de cristais de gelo nas crianças!",
  ui_story_1021_10211001_52_dialog_content = "Você é quem esqueceu de me dizer que ir à sua casa envolvia deixar raposas da neve se revezarem lambendo minhas mãos...",
  ui_story_1021_10211001_53_dialog_content = "Isso não é um costume em nenhum outro lugar em Northland!",
  ui_story_1021_10211001_54_dialog_content = "...",
  ui_story_1021_10211001_55_dialog_content = "Então, essas coisas brilhantes são seus presentes?",
  ui_story_1021_10211001_56_dialog_content = "Isso é um minério de Lúmina?",
  ui_story_1021_10211001_57_dialog_content = "Acertou! Eu me esgotei trazendo todos esses direto da casa de Tiare!",
  ui_story_1021_10211001_58_dialog_content = "Não posso aceitar algo tão valioso como um presente!",
  ui_story_1021_10211001_59_dialog_content = "Por que não? Como líder das raposas da neve, quero retribuir adequadamente a todos vocês por salvarem minha tribo...",
  ui_story_1021_10211001_60_dialog_content = "Este também é o desejo do ancião.",
  ui_story_1021_10211001_61_dialog_content = "A rainha também diz que esse minério pode ser usado para repelir as Eclipsitas e iluminar seu caminho através da Zona Sombria. Você vai precisar deles em sua expedição.",
  ui_story_1021_10211001_62_dialog_content = "Mas a luz deles também está impedindo os Eclipsitas de cruzar as fronteiras de Northland...",
  ui_story_1021_10211001_63_dialog_content = "Este é um presente da nossa tribo! Pegue agora antes que eu me arrependa!",
  ui_story_1021_10211001_64_dialog_content = "Ah... E-eu aceito!",
  ui_story_1021_10211001_65_dialog_content = "(Estou começando a sentir falta de quando ela era apenas a guarda da rainha...)",
  ui_story_1021_10211001_66_dialog_content = "...",
  ui_story_1021_10211001_67_dialog_content = "Parece que você agora está em paz em deixar Tiare fazer o que ela deseja.",
  ui_story_1021_10211001_68_dialog_content = "Mesmo que não seja como minha guarda real, tenho certeza de que ela encontrará seu lugar em Northland em breve.",
  ui_story_1021_10211001_69_dialog_content = "No entanto, você sempre será o farol dela. Desde aquela avalanche, sempre foi assim.",
  ui_story_1021_10211001_70_dialog_content = "<color=#e8d9bb>O dia em que a tribo foi aniquilada...</color>",
  ui_story_1021_10211001_71_dialog_content = "Você acha difícil, servir como guarda da rainha?",
  ui_story_1021_10211001_72_dialog_content = "Sua Majestade é inimaginavelmente poderosa... Sempre que há perigo, a rainha sempre vem ao resgate. Como resultado, meu trabalho raramente é difícil.",
  ui_story_1021_10211001_73_dialog_content = "Ela está sempre me salvando do perigo, vez após vez...",
  ui_story_1021_10211001_74_dialog_content = "A Tribo Fox da Neve sempre paga suas dívidas, é por isso que jurei protegê-la depois que ela me resgatou daquela avalanche.",
  ui_story_1021_10211001_75_dialog_content = "Você realmente acredita que a entende?",
  ui_story_1021_10211001_76_dialog_content = "Claro! Quando Sua Majestade estava patrulhando nossas terras, eu a segui de perto sem que ela soubesse...",
  ui_story_1021_10211001_77_dialog_content = "Os movimentos dela, o aroma, até a maneira como ela respira - eu conheço tudo muito bem.",
  ui_story_1021_10211001_78_dialog_content = "Eu posso sentir a rejeição da tribo por estranhos, mas a rainha é diferente...",
  ui_story_1021_10211001_79_dialog_content = "Quando ela olha para mim, me lembra de um parente distante que só visita uma vez por ano...",
  ui_story_1021_10211001_80_dialog_content = "Quando ela aparece, ela irradia uma certa luz sobre a tribo e o meu mundo também...",
  ui_story_1021_10211001_81_dialog_content = "Então parece que você sabe o que deve ser feito, Tiare. A resposta sempre esteve no seu coração.",
  ui_story_1021_10211001_82_dialog_content = "A pessoa que preenche seu mundo com luz é um farol para sua vida.",
  ui_story_1021_10211001_83_dialog_content = "May você segue a luz do seu farol e se banha em seu brilho quente.",
  ui_story_1021_10211001_84_dialog_content = "Quando você finalmente for capaz de iluminar seu próprio caminho, tenho certeza de que sua luz servirá como um farol para nossa tribo.",
  ui_story_1021_10211001_85_dialog_content = "...",
  ui_story_1021_10211001_86_dialog_content = "Você não vai contar a verdade sobre a avalanche para ela?",
  ui_story_1021_10211001_87_dialog_content = "Contar a ela não faria diferença neste momento.",
  ui_story_1021_10211001_88_dialog_content = "...",
  ui_story_1021_10211001_89_dialog_content = "Mesmo assim, acredito que você também seja um farol para ela.",
  ui_story_1021_10211001_90_dialog_content = "<color=#e8d9bb>Alguns anos atrás...</color>",
  ui_story_1021_10211001_91_dialog_content = "<color=#e8d9bb>Croc, croc, crocante—</color>",
  ui_story_1021_10211001_92_dialog_content = "?",
  ui_story_1021_10211001_93_dialog_content = "(Em um piscar de olhos, a garotinha que uma vez jogou bolas de neve em mim cresceu...)",
  ui_story_1021_10211001_94_dialog_content = "(Viver sozinho na Floresta Nevosa deve ter sido tão solitário às vezes.)",
  ui_story_1021_10211001_95_dialog_content = "<color=#e8d9bb>Farfalhar, farfalhar—</color>",
  ui_story_1021_10211001_96_dialog_content = "...",
  ui_story_1021_10211001_97_dialog_content = "...",
  ui_story_1021_10211001_98_dialog_content = "(E ainda assim ela continua sendo uma criança tão impaciente...)",
  ui_story_1021_10211001_99_dialog_content = "(Ela sempre me seguiu de longe, mas hoje ela escolhe se revelar para mim...)",
  ui_story_1021_10211001_100_dialog_content = "...",
  ui_story_1021_10211001_101_dialog_content = "Todos os anos, por volta da mesma época, você aparece nessas terras.",
  ui_story_1021_10211001_102_dialog_content = "...",
  ui_story_1021_10211001_103_dialog_content = "Mas você ainda não cumpriu sua promessa de trazer a luz do Farol para nós.",
  ui_story_1021_10211001_104_dialog_content = "...",
  ui_story_1021_10211001_105_dialog_content = "Obrigado a todos. Sem vocês, Northland não seria tão pacífica como é hoje.",
  ui_story_1021_10211001_106_dialog_content = "Embora nossos ancestrais tenham escolhido ficar aqui e pereceram na guerra...",
  ui_story_1021_10211001_107_dialog_content = "A escolha de continuar protegendo este lugar é nossa.",
  ui_story_1021_10211001_108_dialog_content = "...",
  ui_story_1021_10211001_109_dialog_content = "Pegue Tiare e saia.",
  ui_story_1021_10211001_110_dialog_content = "?",
  ui_story_1021_10211001_111_dialog_content = "Meus dias estão contados. Quando ela for mais velha, ela aprenderá o preço da proteção e o peso de sua responsabilidade.",
  ui_story_1021_10211001_112_dialog_content = "Não desejo que ela passe a vida teimosamente protegendo a Floresta de Snowpine em solidão, como sua avó fez uma vez.",
  ui_story_1021_10211001_113_dialog_content = "Tiare... é uma criança obstinada.",
  ui_story_1021_10211001_114_dialog_content = "Mas estou bem ciente da curiosidade e esperança que ela sente por você.",
  ui_story_1021_10211001_115_dialog_content = "...",
  ui_story_1021_10211001_116_dialog_content = "<color=#e8d9bb>O ancião salta de volta para a floresta, e uma bola de neve enorme rola em direção a Tiare...</color>",
  ui_story_1021_10211001_117_dialog_content = "Ahhh!",
  ui_story_1021_10211001_118_dialog_content = "Isso acaba quando o gelo derrete—",
  ui_story_1021_10211001_119_dialog_content = "Você me salvou...",
  ui_story_1021_10211001_120_dialog_content = "E não só isso...",
  ui_story_1021_10211001_121_dialog_content = "Sua lança deve estar muito mais durável agora.",
  ui_story_1021_10211001_122_dialog_content = "Está brilhando com uma luz tão intensa!",
  ui_story_1021_10211001_123_dialog_content = "Assim como aquele farol...",
  ui_story_1021_10211001_124_dialog_content = "Espere...",
  ui_story_1021_10211001_125_dialog_content = "...",
  ui_story_1021_10211001_126_dialog_content = "M-Meu nome é Tiare!",
  ui_story_1021_10211001_127_dialog_content = "...",
  ui_story_1021_10211001_128_dialog_content = "E a partir deste dia, não importa para onde você vá, eu sempre estarei lá para protegê-lo! A Tribo da Neve Fox sempre paga suas dívidas!",
  ui_story_1021_10211001_129_dialog_content = "...",
  ui_story_1021_10211001_130_dialog_content = "Obrigado por tudo o que você faz por Northland.",
  ui_story_1021_10211001_131_dialog_content = "Embora meu voto pese muito sobre mim, carrego-o com orgulho a cada passo que dou...",
  ui_story_1021_10211001_132_dialog_content = "Prometo a todos vocês que a luz do Farol de Northland alcançará este lugar...",
  ui_story_1021_10211001_133_dialog_content = "Um dia, iluminará terras ainda mais distantes.",
  ui_story_1022_10220100_1_dialog_content = "(O que... onde estou?)",
  ui_story_1022_10220100_2_dialog_content = "<color=#e8d9bb>O mundo ao redor é frio e completamente desprovido de luz, tornando impossível discernir as direções.</color>",
  ui_story_1022_10220100_3_dialog_content = "(Por que estou em um lugar como este?)",
  ui_story_1022_10220100_4_dialog_content = "(Está ficando mais frio... Eu não posso simplesmente ficar aqui, eu tenho que continuar me movendo!)",
  ui_story_1022_10220100_5_dialog_content = "(Mas para onde eu deveria ir? Está muito escuro para ver qualquer coisa... Huh? O que é isso?)",
  ui_story_1022_10220100_6_dialog_content = "<color=#e8d9bb>Um pequeno ponto de luz, distante, rompe a escuridão esmagadora.</color>",
  ui_story_1022_10220100_7_dialog_content = "<color=#e8d9bb>Imperturbável pela noite fria e opressiva, a luz fica cada vez mais brilhante, até que seu calor e brilho iluminam tudo ao seu redor.</color>",
  ui_story_1022_10220100_8_dialog_content = "<color=#e8d9bb>Como o sol brilhando através de uma noite eterna.</color>",
  ui_story_1022_10220100_9_dialog_content = "(Uma fonte massiva de Lumina... É tão pura, e sinto como se estivesse me observando... Ou até mesmo me guiando.)",
  ui_story_1022_10220100_10_dialog_content = "... você vai esquecer eventualmente. O tempo cura tudo, e se alguém mais especial entrar em sua vida, você vai seguir em frente.",
  ui_story_1022_10220100_11_dialog_content = "Quem está aí? Você está falando comigo?",
  ui_story_1022_10220100_12_dialog_content = "Está tão frio... Meu corpo todo está congelando...",
  ui_story_1022_10220100_13_dialog_content = "... Pegar um resfriado, miau!",
  ui_story_1022_10220100_14_dialog_content = "Está frio... Tão frio...",
  ui_story_1022_10220100_15_dialog_content = "Isso é porque você chutou o cobertor. Eu também não posso colocá-lo sobre você, já que você rolou em cima dele!",
  ui_story_1022_10220100_16_dialog_content = "Então, se você não quer pegar um resfriado, levante-se logo.",
  ui_story_1022_10220100_17_dialog_content = "Huh? Eu estava dormindo agora mesmo? Então foi tudo um sonho...",
  ui_story_1022_10220100_18_dialog_content = "Estava tão frio também! Obrigado por me acordar, Philyshy.",
  ui_story_1022_10220100_19_dialog_content = "De nada! E já que seu lugar está vago agora, é a minha vez de tirar uma soneca...",
  ui_story_1022_10220100_20_dialog_content = "Huh? E-Ei, espere um segundo! Não adormeça assim!",
  ui_story_1022_10220100_21_dialog_content = "Qual é a situação? Onde estamos agora?",
  ui_story_1022_10220100_22_dialog_content = "Olhe pela janela e veja por si mesmo, miau.",
  ui_story_1022_10220100_23_dialog_content = "O que está lá fora... Ah!",
  ui_story_1022_10220100_24_dialog_content = "<color=#e8d9bb>Fora do dirigível, uma escuridão espessa e densa flui pela terra, estendendo-se infinitamente à distância.</color>",
  ui_story_1022_10220100_25_dialog_content = "<color=#e8d9bb>Assim como no pesadelo.</color>",
  ui_story_1022_10220100_26_dialog_content = "A Zona Escura... Já estamos na Zona Escura?",
  ui_story_1022_10220100_27_dialog_content = "Sim! Eu ia te contar, mas vi você encolhido de frio, miau.",
  ui_story_1022_10220100_28_dialog_content = "A-Aham!",
  ui_story_1022_10220100_29_dialog_content = "(Estou me perguntando se a Zona Escura pode ter influenciado o sonho que acabei de ter.)",
  ui_story_1022_10220100_30_dialog_content = "(E aquela bola de Lumina... Ela existe no mundo real também...?)",
  ui_story_1022_10220100_31_option_content = "Alcance Telepático",
  ui_story_1022_10220100_32_dialog_content = "...!",
  ui_story_1022_10220100_33_dialog_content = "(Existe sim! Mas... O que pode ser?)",
  ui_story_1022_10220100_34_dialog_content = "De qualquer forma, a situação deu uma pequena guinada para pior...",
  ui_story_1022_10220100_35_dialog_content = "Consegui acompanhar dois conjuntos diferentes de coordenadas.",
  ui_story_1022_10220100_36_dialog_content = "O primeiro conjunto pertence à equipe de exploração de elite da Lumina. O outro conjunto pertence ao Oficial Charon e Vice.",
  ui_story_1022_10220100_37_dialog_content = "O que aconteceu com Vice?!",
  ui_story_1022_10220100_38_dialog_content = "Acalme-se um pouco... embora eu acho que não posso te culpar por se preocupar. Definitivamente tem algo errado com as coordenadas deles.",
  ui_story_1022_10220100_39_dialog_content = "O sinal da equipe de exploração tem ficado mais fraco com o tempo. É possível que a Dark Zone esteja tendo algum tipo de efeito negativo em nossos dispositivos de comunicação.",
  ui_story_1022_10220100_40_dialog_content = "Mas eu pensei que nossos comunicadores deveriam funcionar dentro da Zona Escura?",
  ui_story_1022_10220100_41_dialog_content = "Isso é verdade, mas há outras coisas a considerar. Geografia, clima, distância e densidade do Darkflow podem afetar seriamente a eficácia de nossos comunicadores.",
  ui_story_1022_10220100_42_dialog_content = "Entendi... E-Então e quanto a Vice e Charon?",
  ui_story_1022_10220100_43_dialog_content = "As coordenadas deles... continuam pulando por todo lugar.",
  ui_story_1022_10220100_44_dialog_content = "Pulando?",
  ui_story_1022_10220100_45_dialog_content = "Sim! Eles estão constantemente em movimento como um ponto de laser, um momento aqui e no próximo lá. Estou ficando tonto; Estou apenas tentando acompanhar. Miau!",
  ui_story_1022_10220100_46_dialog_content = "Pelo que eu sei, o Other End do Charon não é capaz desse tipo de movimento...",
  ui_story_1022_10220100_47_dialog_content = "Mas também não parece que o comunicador deles está quebrado. É estranho, certo?",
  ui_story_1022_10220100_48_dialog_content = "Talvez seja outro efeito da Zona Escura... Ainda estamos incapazes de fazer contato com eles?",
  ui_story_1022_10220100_49_dialog_content = "O Comandante Hiiro tentou, mas ainda nada... Eu nem mesmo sei para onde eles fugiram desta vez.",
  ui_story_1022_10220100_50_dialog_content = "Como isso está acontecendo, miau?! Eu já passei por todos os relatórios de inteligência sobre este lugar, mas ainda não tenho uma resposta! Acho que realmente tenho que arregaçar as mangas para isso!",
  ui_story_1022_10220100_51_dialog_content = "Você não acha que eles... se depararam com um fantasma, acha...?",
  ui_story_1022_10220100_52_dialog_content = "Miau?!",
  ui_story_1022_10220100_53_dialog_content = "Ainda não sabemos nada sobre os poderes deles, certo? Eles podem até ser capazes de algo tão louco quanto a teletransporte!",
  ui_story_1022_10220100_54_dialog_content = "Tenho certeza de que os Fantasmas estariam muito interessados na habilidade de Vice em pilotar um Colossus como Ponta de Lança também...",
  ui_story_1022_10220100_55_dialog_content = "E se um deles conseguir fazer dela refém e causar estragos em todo o mundo?!",
  ui_story_1022_10220100_56_dialog_content = "Miau!!! I-I-Isso seria...",
  ui_story_1022_10220100_57_dialog_content = "Isso seria praticamente impossível, dado que Charon e Other End estão com ela agora.",
  ui_story_1022_10220100_58_dialog_content = "Comandante Hiiro!",
  ui_story_1022_10220100_59_dialog_content = "Hiiro... Tem certeza de que é impossível? Mesmo que haja apenas uma pequena chance, e se—",
  ui_story_1022_10220100_60_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_1022_10220100_61_dialog_content = "Ai—",
  ui_story_1022_10220100_62_dialog_content = "(E-Ela acabou de bater na minha cabeça bem forte...)",
  ui_story_1022_10220100_63_dialog_content = "É impossível descartar completamente uma possibilidade, o que torna igualmente inútil se preocupar com isso.",
  ui_story_1022_10220100_64_dialog_content = "Antes de partirmos para esta expedição, você disse que iria se acalmar e evitar tirar conclusões precipitadas. Você já se esqueceu disso?",
  ui_story_1022_10220100_65_dialog_content = "E-Eu não, mas não posso evitar quando ouço falar que Vice está envolvido em uma situação estranha...",
  ui_story_1022_10220100_66_dialog_content = "(Ugh, minha cabeça... Hiiro me acertou forte!)",
  ui_story_1022_10220100_67_dialog_content = "Entendo, mas a Zona Cega está cheia de perigos inimagináveis. Você precisa permanecer focado.",
  ui_story_1022_10220100_68_dialog_content = "Espero que Vice também tenha isso em mente. Assim como você, ela é a primeira a se preocupar com outras pessoas assim que as coisas ficam perigosas.",
  ui_story_1022_10220100_69_dialog_content = "Ela ainda precisa de mais treinamento como soldado.",
  ui_story_1022_10220100_70_dialog_content = "Hiiro... Você está realmente preocupado com Vice também, não está?",
  ui_story_1022_10220100_71_dialog_content = "Não é óbvio?",
  ui_story_1022_10220100_72_dialog_content = "Vice, Oficial Charon, e até mesmo o Oficial de Tecnologia Gronru... Não faltam gatinhos travessos em nossas fileiras, hein?",
  ui_story_1022_10220100_73_dialog_content = "Gronru? O que aconteceu com ela?",
  ui_story_1022_10220100_74_dialog_content = "... Desde que Ponta de Lança reapareceu, Gronru tem se enterrado em um trabalho de reparo interminável. Ela nem sequer tocou em um videogame todo esse tempo.",
  ui_story_1022_10220100_75_dialog_content = "Como a pessoa que já foi responsável pelos experimentos da Ponta de Lança, ela provavelmente se sente culpada em relação ao Vice e ao Grande Marechal...",
  ui_story_1022_10220100_76_dialog_content = "Não temos tempo para nos preocupar com os sentimentos de outras pessoas agora. Nossa situação já é perigosa o suficiente como está.",
  ui_story_1022_10220100_77_dialog_content = "Nossa aeronave foi projetada para voar em conjunto com as outras duas, para que pudéssemos nos proteger mutuamente.",
  ui_story_1022_10220100_78_dialog_content = "Mas agora que as coordenadas deles se tornaram incertas, precisamos fazer alguns ajustes de emergência em nossa operação.",
  ui_story_1022_10220100_79_dialog_content = "Por mais preocupados que estejamos com Charon e Vice, tenho certeza de que todos concordamos que se reagrupar com eles não é uma opção no momento, certo?",
  ui_story_1022_10220100_80_dialog_content = "(Ela está certa. Mesmo que consigamos alcançar a posição deles, há uma boa chance de eles teleportarem para outro lugar novamente... Droga!)",
  ui_story_1022_10220100_81_dialog_content = "Devido à interferência da Zona Escura, também não recebemos um sinal da equipe de exploração há muito tempo.",
  ui_story_1022_10220100_82_dialog_content = "Neste ponto, estamos apenas perdendo tempo tateando no escuro. Não vamos conseguir nada se isso continuar.",
  ui_story_1022_10220100_83_dialog_content = "... Há uma bola de Lúmina lá fora.",
  ui_story_1022_10220100_84_dialog_content = "O quê?",
  ui_story_1022_10220100_85_dialog_content = "Eu... Eu senti uma enorme concentração de Lumina em algum lugar profundo na Zona Escura. Eu realmente não consigo descrever, mas pode estar perto da fronteira da noite eterna.",
  ui_story_1022_10220100_86_dialog_content = "... Eu não acredito que existe tal coisa, miau!",
  ui_story_1022_10220100_87_dialog_content = "É difícil acreditar que Lumina possa estar na Dark Zone. Mas se as outras equipes notarem algo fora do comum, provavelmente irão verificar.",
  ui_story_1022_10220100_88_dialog_content = "Poderia servir como um ponto de encontro improvisado para todos nós...",
  ui_story_1022_10220100_89_dialog_content = "Comandante Hiiro! Pedido entrante da nossa base traseira!",
  ui_story_1022_10220100_90_dialog_content = "Envie-o.",
  ui_story_1022_10220100_91_dialog_content = "Entendido!",
  ui_story_1022_10220100_92_dialog_content = "... Testando, testando. Alguém me ouve?",
  ui_story_1022_10220100_93_dialog_content = "Reinhardt! Graças a Deus ainda podemos entrar em contato com você!",
  ui_story_1022_10220100_94_dialog_content = "Ouvimos você alto e claro, Grande Marechal. Parece que alguns de nossos canais de comunicação ainda estão intactos.",
  ui_story_1022_10220100_95_dialog_content = "Isso não torna a Zona Escura menos problemática. Ainda não há sinal da equipe de exploração ou suas coordenadas, hein?",
  ui_story_1022_10220100_96_dialog_content = "Você realmente tem um grande desafio pela frente desta vez, Hiiro. Aguente firme.",
  ui_story_1022_10220100_97_dialog_content = "Claro. Minha subordinada ainda está lá fora em algum lugar, e é meu dever trazê-la para casa em segurança.",
  ui_story_1022_10220100_98_dialog_content = "E com o exército de Lumopolis montando acampamento base no terreno, não precisamos nos preocupar em cobrir nossas costas.",
  ui_story_1022_10220100_99_dialog_content = "E você, Grande Marechal? Como estão as coisas com o Comitê? Eles estão dificultando para você?",
  ui_story_1022_10220100_100_dialog_content = "Humph, se eles não me dessem nenhum problema, eu começaria a me perguntar se estava no caminho certo.",
  ui_story_1022_10220100_101_dialog_content = "Em todo caso, as coisas estão indo bem do meu lado. Com o passar do tempo, parece que o Comitê é uma cobra que come o próprio rabo.",
  ui_story_1022_10220100_102_dialog_content = "Eu não entendo muito bem suas palavras.",
  ui_story_1022_10220100_103_dialog_content = "Não importa se é o Belisaria ou os outros atores sem-nome no show... podemos até incluir o Ulysses!",
  ui_story_1022_10220100_104_dialog_content = "Eles não querem nada mais do que usar a ciência e a tecnologia para garantir a sobrevivência de todos os Aurorianos.",
  ui_story_1022_10220100_105_dialog_content = "Isso é inegável, sim.",
  ui_story_1022_10220100_106_dialog_content = "Mas a ciência e a tecnologia também podem ser impiedosas, e a proximidade do Comitê com esses aspectos mais cruéis teve um profundo efeito sobre eles.",
  ui_story_1022_10220100_107_dialog_content = "Mas há um lado frio e duro na tecnologia. O comitê está mais próximo dele e foi o mais afetado.",
  ui_story_1022_10220100_108_dialog_content = "Em troca de racionalidade, eficiência e praticidade, eles abandonaram sua compaixão pelos seus companheiros Aurorianos... E ao fazer isso, eles vão contra seu objetivo original—",
  ui_story_1022_10220100_109_dialog_content = "Para criar um mundo onde os Aurorianos possam viver vidas felizes e pacíficas.",
  ui_story_1022_10220100_110_dialog_content = "(Mesmo Ulysses apenas queria aprimorar os Aurorians para ajudá-los a lutar contra os Eclipsitas...)",
  ui_story_1022_10220100_111_dialog_content = "... Se eles buscam cegamente a eficiência à custa de sua humanidade, o que os torna diferentes dos Eclipsitas seguindo as ordens de um fantasma?",
  ui_story_1022_10220100_112_dialog_content = "Exatamente, é por isso que a última geração de líderes quer encontrar outro caminho, como Yingel e Sean.",
  ui_story_1022_10220100_113_dialog_content = "Eu não quero ficar para trás, terei que fazer mais algumas conquistas sem precedentes, assim como eles.",
  ui_story_1022_10220100_114_dialog_content = "Você não acha que já fez o suficiente desses...?",
  ui_story_1022_10220100_115_dialog_content = "Hahaha! Você faz parecer uma coisa tão ruim!",
  ui_story_1022_10220100_116_dialog_content = "... Mas a verdade é que ainda tenho muito a realizar como o Grande Marechal da Illumina. Ignorei todos os tipos de ameaças ocultas no passado por causa da guerra.",
  ui_story_1022_10220100_117_dialog_content = "Por causa disso, tive que fazer concessões ao Comitê, assim como meu antecessor, enquanto eles assumiam o controle do curso da Federação para o futuro.",
  ui_story_1022_10220100_118_dialog_content = "Já ouvi o suficiente, Grande Marechal! Todos nós sabemos que você não é esse tipo de pessoa, e—",
  ui_story_1022_10220100_119_dialog_content = "Relaxe, Hiiro. Estou apenas expondo os fatos para poder definir novos objetivos para mim mesmo.",
  ui_story_1022_10220100_120_dialog_content = "Não sou mais o mesmo de antes. A revolução que imaginamos naquela época vai se tornar realidade, e eu serei o responsável por isso.",
  ui_story_1022_10220100_121_dialog_content = "O Comitê pode ainda ter seus propósitos, mas eu me recuso a deixá-los desviar o poder da Illumina para o caminho errado.",
  ui_story_1022_10220100_122_dialog_content = "Vou expor os rostos escondidos atrás de suas máscaras de ferro e ver se ainda resta alguma humanidade neles.",
  ui_story_1022_10220100_123_dialog_content = "Não posso dizer muito mais agora, mas prometo que explicarei tudo em breve. Apenas me dê um pouco mais de tempo, todos.",
  ui_story_1022_10220100_124_dialog_content = "<color=#e8d9bb>Enquanto isso, em uma reunião do Comitê Illumina—</color>",
  ui_story_1022_10220100_125_dialog_content = "Reinhardt fez um retorno após sua derrota, os experimentos de Ulysses foram expostos para o mundo ver...",
  ui_story_1022_10220100_126_dialog_content = "E agora temo que as armas preparadas para Azurite sofrerão um destino semelhante.",
  ui_story_1022_10220100_127_dialog_content = "Parece que todo plano que você escolhe apoiar acaba se voltando contra você.",
  ui_story_1022_10220100_128_dialog_content = "Então nos diga, Belisaria, como você pretende assumir a responsabilidade por isso?",
  ui_story_1022_10220100_129_dialog_content = "A reputação do Comitê será completamente arruinada se continuarmos encobrindo esses fracassos vergonhosos!",
  ui_story_1022_10220100_130_dialog_content = "Então por que se dar ao trabalho de escondê-los, especialmente em um momento como este?",
  ui_story_1022_10220100_131_dialog_content = "Se manter as aparências é tão importante para você, então pode muito bem me pedir para renunciar agora mesmo.",
  ui_story_1022_10220100_132_dialog_content = "... E você tem algum problema com isso?",
  ui_story_1022_10220100_133_dialog_content = "Não é sobre mim. Tudo o que importa é se a situação exige isso ou não.",
  ui_story_1022_10220100_134_dialog_content = "Estou preparado para renunciar a qualquer momento, se necessário, para proteger a reputação do Comitê.",
  ui_story_1022_10220100_135_dialog_content = "Essa é a minha razão para estar aqui.",
  ui_story_1022_10220100_136_dialog_content = "... Humf.",
  ui_story_1022_10220100_137_dialog_content = "Mas antes de tomar qualquer medida, peço que leve em consideração Reinhardt, bem como seu poder e apelo.",
  ui_story_1022_10220100_138_dialog_content = "Você já considerou o moral dos soldados servindo sob o Grande Marechal? Como eles veem o Comitê?",
  ui_story_1022_10220100_139_dialog_content = "...",
  ui_story_1022_10220100_140_dialog_content = "A única razão pela qual chegamos tão longe é porque Illumina escolheu dividir seu poder governamental entre o Comitê e o militar.",
  ui_story_1022_10220100_141_dialog_content = "O atual esplendor de Illumina pode ser atribuído ao sistema de equilíbrio e controle entre ambos os lados. Anos de tensão e lutas pelo poder nos levaram a este exato ponto na história.",
  ui_story_1022_10220100_142_dialog_content = "Mas quando o conflito inevitavelmente irrompe, a competência do Grande Marechal determina a precariedade de nossa situação.",
  ui_story_1022_10220100_143_dialog_content = "No passado, fui forçado a subir ao palco e negociar com os militares. Mas, dado nossos atuais desacordos com eles, eu poderia facilmente escolher sair.",
  ui_story_1022_10220100_144_dialog_content = "Mas o que acontece depois disso?",
  ui_story_1022_10220100_145_dialog_content = "Qual de vocês tomaria o meu lugar? Algum de vocês é sequer capaz de assumir o meu papel?",
  ui_story_1022_10220100_146_dialog_content = "<color=#e8d9bb>Um longo silêncio preenche o salão de reuniões.</color>",
  ui_story_1022_10220100_147_dialog_content = "Ainda há um assunto inacabado, então, por favor, tire um tempo para pensar sobre o que eu disse.",
  ui_story_1022_10220100_148_dialog_content = "Na ausência de razão, que tipo de futuro o poder irrestrito criará?",
  ui_story_1022_10220100_149_dialog_content = "Mas podemos muito bem começar uma guerra real se interviermos novamente.",
  ui_story_1022_10220100_150_dialog_content = "O propósito do Comitê sempre foi impor restrições. Por que deveríamos temer o conflito agora, de todas as vezes?",
  ui_story_1022_10220100_151_dialog_content = "Mas como brigas internas sem sentido ajudariam a promover algum de nossos planos?",
  ui_story_1022_10220100_152_dialog_content = "Por enquanto, devemos ceder o controle de Illumina para <color=#FFB400>ela</color>. Deveríamos ter feito isso antes, mas nossa incerteza em relação a <color=#FFB400>ela</color> nos impediu.",
  ui_story_1022_10220100_153_dialog_content = "Parem de discutir. Precisamos agir como um só se quisermos enfrentar essa tempestade.",
  ui_story_1022_10220100_154_dialog_content = "Como um só? Quando cada pessoa em Illumina nos vê como nada mais do que um incômodo? Heheh, não é preciso ser um gênio para saber o que as pessoas pensam do Comitê: um vestígio teimoso e intrometido do passado.",
  ui_story_1022_10220100_155_dialog_content = "Você já tomou sua decisão?",
  ui_story_1022_10220100_156_dialog_content = "Parece que é hora de <color=#FFB400>nós</color> fazermos uma aparição.",
  ui_story_1022_10220100_157_dialog_content = "...!",
  ui_story_1022_10220100_158_dialog_content = "A Illumina nasceu da divisão, mas isso não significa que deva morrer por causa disso.",
  ui_story_1022_10220100_159_dialog_content = "Não importa quem está no poder em qualquer momento. O que importa é que não repetimos nossos erros.",
  ui_story_1022_10220100_160_dialog_content = "A Illumina nunca mais sofrerá traidores.",
  ui_story_1022_10220201_1_dialog_content = "<color=#e8d9bb>Nas profundezas da Zona Escura...</color>",
  ui_story_1022_10220201_2_dialog_content = "Sem sucesso, capitã. Ainda não conseguimos estabelecer contato com os outros.",
  ui_story_1022_10220201_3_dialog_content = "Isso significa que nunca mais os veremos...?",
  ui_story_1022_10220201_4_dialog_content = "Está bem se não conseguirmos entrar em contato com eles. Isso apenas significa que somos livres para fazer o que quisermos.",
  ui_story_1022_10220201_5_dialog_content = "Ter comunicação com eles não é diferente de estar na coleira. Só vai tornar nosso trabalho ainda mais difícil.",
  ui_story_1022_10220201_6_dialog_content = "C-Capitão! Tem certeza de que deveria dizer isso tão alto...?",
  ui_story_1022_10220201_7_dialog_content = "Quem você acha que vai nos ouvir? Aquela pedra ali? Ou talvez aquele gigantesco bloco de gelo?",
  ui_story_1022_10220201_8_dialog_content = "... Aham!",
  ui_story_1022_10220201_9_dialog_content = "Capitão! Eu... Eu acho que ouvi um som de tosse agora mesmo...",
  ui_story_1022_10220201_10_option_content = "O que foi tão estranho nisso?!",
  ui_story_1022_10220201_11_dialog_content = "Ele está certo, você sabe? Foi uma tosse perfeitamente normal.",
  ui_story_1022_10220201_12_option_content = "Não, você definitivamente ouviu isso.",
  ui_story_1022_10220201_13_dialog_content = "Ele está certo, você sabe? Uma tosse deliberada como essa só pode significar que alguém está tentando chamar nossa atenção.",
  ui_story_1022_10220201_14_dialog_content = "Agora, identifique-se! Você está com as forças principais?",
  ui_story_1022_10220201_15_dialog_content = "Eu aplaudo a sua compostura apesar da sua situação atual, Capitão Pepita.",
  ui_story_1022_10220201_16_dialog_content = "Por esse motivo, estou disposto a ignorar suas palavras desta vez. Apenas não deixe isso acontecer novamente.",
  ui_story_1022_10220201_17_dialog_content = "C-C-Comandante Hiiro da 3ª Legião!",
  ui_story_1022_10220201_18_dialog_content = "Ahh, está tão escuro e silencioso aqui! Que lugar perfeito para uma soneca.",
  ui_story_1022_10220201_19_dialog_content = "E-E a Chefe de Inteligência também?!",
  ui_story_1022_10220201_20_dialog_content = "Eu... Eu vou preparar um chá para todos!",
  ui_story_1022_10220201_21_dialog_content = "Não tem chá aqui! Viram o que vocês fizeram? Minha tripulação está assustada por causa de vocês!",
  ui_story_1022_10220201_22_dialog_content = "...",
  ui_story_1022_10220201_23_dialog_content = "E qual é o seu problema, garoto tossindo? Por que você está se escondendo lá atrás? Com medo de que seu rank não possa competir com o deles?",
  ui_story_1022_10220201_24_dialog_content = "E-Eu não sou um soldado, sou apenas um celestita...",
  ui_story_1022_10220201_25_dialog_content = "Isso é ainda pior! O que você está fazendo seguindo eles por aí quando nem mesmo recebeu ordens para fazer isso?!",
  ui_story_1022_10220201_26_dialog_content = "Isso não é verdade. Acontece que estamos trabalhando juntos por um objetivo comum—",
  ui_story_1022_10220201_27_dialog_content = "E qual seria esse objetivo? Fazer de você o pequeno cachorrinho deles?",
  ui_story_1022_10220201_28_dialog_content = "P-Por que, você...!",
  ui_story_1022_10220201_29_dialog_content = "... Chega, vocês duas. Já foi difícil o suficiente para nossas equipes se reagruparem, agora vamos apenas trocar informações e planejar nosso próximo passo.",
  ui_story_1022_10220201_30_dialog_content = "Hmm... Então vocês estavam a caminho de uma enorme bola de Lumina quando nos encontraram?",
  ui_story_1022_10220201_31_dialog_content = "Parece um pouco conveniente demais para mim. Tem certeza de que não está apenas me enganando?",
  ui_story_1022_10220201_32_dialog_content = "Por que mentiríamos sobre isso?",
  ui_story_1022_10220201_33_dialog_content = "Vocês são os únicos que sabem a resposta para isso. Talvez vocês não possam me dizer a verdade agora? Ou talvez vocês realmente gostem muito de piadas...",
  ui_story_1022_10220201_34_dialog_content = "Piadas? Do que diabos você está falando—",
  ui_story_1022_10220201_35_dialog_content = "Leve isso a sério já, você poderia?!",
  ui_story_1022_10220201_36_dialog_content = "PlayerName?",
  ui_story_1022_10220201_37_dialog_content = "Hiiro e eu viemos para a Zona Cega para procurar um amigo muito importante.",
  ui_story_1022_10220201_38_dialog_content = "Estávamos indo para o baile de Lumina na esperança de encontrá-la, mas voltamos de mãos vazias...",
  ui_story_1022_10220201_39_dialog_content = "Por que nós zombaríamos de você?!",
  ui_story_1022_10220201_40_dialog_content = "Seu amigo...?!",
  ui_story_1022_10220201_41_dialog_content = "E não ouse dizer algo como, \"Aposto que você está bem decepcionado por ter encontrado apenas eu\", ou eu vou ficar realmente brava!",
  ui_story_1022_10220201_42_dialog_content = "...",
  ui_story_1022_10220201_43_dialog_content = "...",
  ui_story_1022_10220201_44_dialog_content = "Hahahahaha!",
  ui_story_1022_10220201_45_dialog_content = "O-O que você está rindo...?",
  ui_story_1022_10220201_46_dialog_content = "Então você não está bravo agora? Não vou mentir, estou meio curioso para ver como você é quando está \"realmente bravo\"!",
  ui_story_1022_10220201_47_dialog_content = "Você tem que ser—",
  ui_story_1022_10220201_48_dialog_content = "Mas infelizmente, terá que esperar. Eu não estava planejando dizer algo assim em primeiro lugar.",
  ui_story_1022_10220201_49_dialog_content = "Julguei mal vocês, então peço desculpas por ter me excedido um pouco com meu temperamento. Meu erro!",
  ui_story_1022_10220201_50_dialog_content = "M-Mal interpretado...?",
  ui_story_1022_10220201_51_dialog_content = "Você é de Illumina, então imaginei que todos vocês fossem um bando de lacaios sem cérebro seguindo ordens para mergulhar na Zona Escura.",
  ui_story_1022_10220201_52_dialog_content = "Mas pelo visto... Você está aqui pelo seu amigo! Hahaha!",
  ui_story_1022_10220201_53_dialog_content = "Você é especialmente audacioso! É preciso uma pessoa realmente especial para explodir na frente do comandante da 3ª Legião assim.",
  ui_story_1022_10220201_54_dialog_content = "Eu gosto de você!",
  ui_story_1022_10220201_55_dialog_content = "?!",
  ui_story_1022_10220201_56_dialog_content = "O-O-O que isso deveria significar...?!",
  ui_story_1022_10220201_57_dialog_content = "Eu não piscar quando estou mentindo ou brincando, mas desta vez é diferente.",
  ui_story_1022_10220201_58_dialog_content = "Qualquer um com autodeterminação está bem no meu livro!",
  ui_story_1022_10220201_59_dialog_content = "Tenho quase certeza que todos têm isso...",
  ui_story_1022_10220201_60_dialog_content = "Tudo bem, nós nos desviamos do assunto por tempo suficiente.",
  ui_story_1022_10220201_61_dialog_content = "Pepita, agora que você está falando, vamos ouvir sobre o que você encontrou até agora.",
  ui_story_1022_10220201_62_dialog_content = "Você obteve alguma nova informação desde que entrou na Zona Cega?",
  ui_story_1022_10220201_63_dialog_content = "Nosso progresso, hein... Explorar a Zona Escura não é fácil, mesmo para alguém tão habilidoso quanto eu. Leva muito esforço para fazer qualquer coisa por aqui, você sabe.",
  ui_story_1022_10220201_64_dialog_content = "Como quando tentamos montar um acampamento base. Eu tive que usar esses cartazes de procurado aqui para o papel de parede!",
  ui_story_1022_10220201_65_dialog_content = "<color=#FFB400>MEUS</color> cartazes de procurado.",
  ui_story_1022_10220201_66_dialog_content = "Seus cartazes de procurado? Acho que não entendi muito bem, haha...",
  ui_story_1022_10220201_67_dialog_content = "Hmm... É estranho... Mas tive um sonho com ela há algum tempo...",
  ui_story_1022_10220201_68_dialog_content = "A garota no meu sonho também parecia terrivelmente familiar.",
  ui_story_1022_10220201_69_dialog_content = "Acho que você é a Chefe de Inteligência da Illumina por um motivo, hein?",
  ui_story_1022_10220201_70_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_1022_10220201_71_dialog_content = "Desça, PlayerName!",
  ui_story_1022_10220201_72_dialog_content = "<color=#e8d9bb>Uma poderosa explosão abala a caverna congelada, e incontáveis ​​estalactites caem de cima.</color>",
  ui_story_1022_10220201_73_dialog_content = "<color=#e8d9bb>Apesar da súbita comoção, Pepita dá uma risada vigorosa.</color>",
  ui_story_1022_10220201_74_dialog_content = "Apenas vá procurar pelo seu amigo. Eu não vou ficar no seu caminho, então lembre-se de ficar fora do meu!",
  ui_story_1022_10220201_75_dialog_content = "Miau! Eu sei que já a vi antes, mas onde?!",
  ui_story_1022_10220201_76_dialog_content = "O que está acontecendo? Como a caverna de gelo desabou tão de repente? Onde está Pepita?",
  ui_story_1022_10220201_77_dialog_content = "... Ela fugiu, provavelmente.",
  ui_story_1022_10220201_78_dialog_content = "Fugiu? Mas por quê?!",
  ui_story_1022_10220201_79_dialog_content = "Miau! Eu me lembro agora! Aquela garota é uma fora da lei procurada!",
  ui_story_1022_10220201_80_dialog_content = "Uma fora da lei? Mas então por que a Illumina a colocou no comando da equipe de exploração e a enviou para a Dark Zone?!",
  ui_story_1022_10220201_81_dialog_content = "Porque a capturamos e a jogamos na prisão há um tempo atrás.",
  ui_story_1022_10220201_82_dialog_content = "Então, estamos dizendo que temos algo sobre ela, algo para forçá-la a nos servir? E por que ela, especificamente?",
  ui_story_1022_10220201_83_dialog_content = "O que exatamente fez com que Pepita fosse parar na cadeia, Philyshy?",
  ui_story_1022_10220201_84_dialog_content = "Sem pistas, sinceramente...",
  ui_story_1022_10220201_85_dialog_content = "Nemesis foi responsável por investigar e prender ela. Aparentemente suas ordens vieram diretamente do Comitê.",
  ui_story_1022_10220201_86_dialog_content = "Deve ter sido sério, então.",
  ui_story_1022_10220201_87_dialog_content = "Ah... Posso interromper por apenas um segundo?",
  ui_story_1022_10220201_88_dialog_content = "Faz sentido para Pepita fugir se ela realmente é uma criminosa procurada, mas por que ela escolheria fazer isso aqui de todos os lugares?",
  ui_story_1022_10220201_89_dialog_content = "Antes de nos encontrarmos, ela e sua equipe operavam sem supervisão. Por que ela não fugiu naquela época?",
  ui_story_1022_10220201_90_dialog_content = "Por que ela esperaria até Hiiro estar aqui? Isso só tornaria mais difícil para ela escapar!",
  ui_story_1022_10220201_91_dialog_content = "Bom...",
  ui_story_1022_10220201_92_dialog_content = "O que foi aquela explosão agora? Estamos sob ataque? O capitão acionou uma de nossas armadilhas para os Eclipsitas?",
  ui_story_1022_10220201_93_dialog_content = "Hã? Aonde o capitão foi?!",
  ui_story_1022_10220201_94_dialog_content = "Miau? Você tem armadilhas escondidas por aqui?!",
  ui_story_1022_10220201_95_dialog_content = "A Zona Escura nos desorienta, tornando difícil confiar em nossos sentidos. Para nos proteger, o capitão montou uma série de armadilhas em todo o perímetro.",
  ui_story_1022_10220201_96_dialog_content = "E ela intensificou ainda mais suas contramedidas depois que encontramos aquele lugar.",
  ui_story_1022_10220201_97_dialog_content = "Eu sei que a capitã pode ser um pouco abrasiva às vezes, mas ela realmente se preocupa muito conosco... Heheheh...",
  ui_story_1022_10220201_98_dialog_content = "...",
  ui_story_1022_10220201_99_dialog_content = "Então ela esperou até agora para escapar...",
  ui_story_1022_10220201_100_dialog_content = "... apenas para deixar seus companheiros de equipe aos nossos cuidados? Ah, Pepita!",
  ui_story_1022_10220201_101_dialog_content = "<color=#e8d9bb>Zona Escura, Acampamento Base de Lumópolis—</color>",
  ui_story_1022_10220201_102_dialog_content = "Pepita—esse é o nome do alvo para esta operação.",
  ui_story_1022_10220201_103_dialog_content = "Nosso alvo é muito astuto, e ela faria qualquer coisa para escapar. Todos devem permanecer em alerta máximo.",
  ui_story_1022_10220201_104_dialog_content = "Não podemos nos dar ao luxo de repetir nossos erros.",
  ui_story_1022_10220201_105_dialog_content = "Sim, capitão!",
  ui_story_1022_10220201_106_dialog_content = "Perdoe-me... fui enganado por causa da minha imprudência...",
  ui_story_1022_10220201_107_dialog_content = "Não se culpe por isso, Erica.",
  ui_story_1022_10220201_108_dialog_content = "O Comitê Illumina tem um longo histórico de negociações com ela. Era inevitável que eles fizessem o negócio primeiro.",
  ui_story_1022_10220201_109_dialog_content = "Mas desta vez, temos a iniciativa!",
  ui_story_1022_10220201_110_dialog_content = "Você se importaria de detalhar seus planos?",
  ui_story_1022_10220201_111_dialog_content = "S-Senhora Carleen...!",
  ui_story_1022_10220202_1_dialog_content = "Aqui está o seu Olhar do Abismo. Por favor, aproveite.",
  ui_story_1022_10220202_2_dialog_content = "Tal cor sedutora, aroma pecaminoso e padrões que se misturam por todo lado... Entendo. Isso deve ser realmente a bebida amaldiçoada de um deus perverso.",
  ui_story_1022_10220202_3_dialog_content = "Ahhh...! A doçura permeia meu estômago e penetra minha alma! Que bebida demoniacamente divina...",
  ui_story_1022_10220202_4_dialog_content = "Se eu não sondar as profundezas do inferno, ninguém mais o fará! Traga-me outra, barman!",
  ui_story_1022_10220202_5_dialog_content = "Hahahaha! Toda essa teatralidade por uma pequena bebida, hein? Não posso dizer que não estou entretido!",
  ui_story_1022_10220202_6_dialog_content = "Quem está aí? Que criatura desprezível ousa zombar de mim?",
  ui_story_1022_10220202_7_dialog_content = "Fui eu, mas mal sou uma criatura humilde. Tenho te observado todo esse tempo, vê?",
  ui_story_1022_10220202_8_dialog_content = "Então você gosta desse tipo de bebida, hein? Conheço algumas bebidas semelhantes, se estiver procurando por uma recomendação.",
  ui_story_1022_10220202_9_dialog_content = "Uma recomendação...? Suponho que eu possa seguir seu pequeno estratagema por enquanto...",
  ui_story_1022_10220202_10_dialog_content = "Apenas certifique-se de que não contém álcool. Obrigado.",
  ui_story_1022_10220202_11_dialog_content = "O quê?",
  ui_story_1022_10220202_12_dialog_content = "<size=30>...Por que ela está agindo assim se ela não bebeu nada?</size>",
  ui_story_1022_10220202_13_dialog_content = "Você parece bastante familiarizado com o cardápio... Você costuma vir aqui?",
  ui_story_1022_10220202_14_dialog_content = "Você poderia dizer isso, mas bebidas não são a única coisa que eu conheço. Perigo, emoção, engano e prazer estão todos no topo do meu cardápio!",
  ui_story_1022_10220202_15_dialog_content = "Então você vê este mundo falso apenas como uma seleção de iguarias para agradar seu paladar? Entendo... Talvez você também tenha o potencial para lutar contra o desconhecido...",
  ui_story_1022_10220202_16_dialog_content = "Um brinde à indulgência em nossas naturezas pecaminosas!",
  ui_story_1022_10220202_17_dialog_content = "Ouça, ouça!",
  ui_story_1022_10220202_18_dialog_content = "Ahhh... Outra bebida sumptuosamente estimulante. Sua recomendação não poderia ter sido mais perfeita, estranho.",
  ui_story_1022_10220202_19_dialog_content = "Te disse, não disse?",
  ui_story_1022_10220202_20_dialog_content = "Então, por que você insiste em pedir bebidas assim? Você não me parece nenhum tipo de bonzinho.",
  ui_story_1022_10220202_21_dialog_content = "A verdade é... Estou de serviço ativo agora, o que significa que tenho que permanecer alerta o tempo todo...",
  ui_story_1022_10220202_22_dialog_content = "Uau, seu trabalho deve ser realmente importante, hein?",
  ui_story_1022_10220202_23_dialog_content = "Por que, sim... Como membro da Divisão de Investigação de Hereges de Lumopolis, nosso nobre trabalho não poderia ser mais importante para o mundo...",
  ui_story_1022_10220202_24_dialog_content = "O que a Divisão de Investigação de Hereges está fazendo em Umbraton?!",
  ui_story_1022_10220202_25_dialog_content = "Estamos caçando um alvo altamente perigoso. Umbraton é um antro de maldade sem lei e imoral, o que o torna o lugar perfeito para ela se esconder.",
  ui_story_1022_10220202_26_dialog_content = "O criminoso em questão roubou um valioso tomo de Lumópolis antes de fugir para esta cidade e ocultar seus movimentos...",
  ui_story_1022_10220202_27_dialog_content = "(Ela não pode estar falando de mim, certo...?)",
  ui_story_1022_10220202_28_dialog_content = "Nosso objetivo é capturá-la e recuperar o tomo roubado... Hmm? Espere, amigo, para onde você está indo?",
  ui_story_1022_10220202_29_dialog_content = "Eu... Eu acho que bebi um pouco demais. Só vou me refrescar no banheiro, já volto!",
  ui_story_1022_10220202_30_dialog_content = "... Maldições! Aquela era nossa chance, mas ela ainda conseguiu escapar!",
  ui_story_1022_10220202_31_dialog_content = "Esse estranho gentil e espirituoso... Era Pepita? Mas como isso poderia ser...?",
  ui_story_1022_10220202_32_dialog_content = "Ainda há tempo! Depois dela!",
  ui_story_1022_10220202_33_dialog_content = "Não podemos permitir que Illumina chegue até ela primeiro...",
  ui_story_1022_10220202_34_dialog_content = "(... Este esconderijo deve servir por enquanto.)",
  ui_story_1022_10220202_35_dialog_content = "(Uma árvore é melhor escondida em uma floresta, então para um auroriano como eu, minha melhor escolha é me esconder...)",
  ui_story_1022_10220202_36_dialog_content = "(Em um funeral!)",
  ui_story_1022_10220202_37_dialog_content = "(Ninguém jamais esperaria que eu me escondesse em um caixão e fingisse estar morto! Eles estarão cavando buracos pelo resto de suas vidas procurando por mim! Hahaha—)",
  ui_story_1022_10220202_38_dialog_content = "Já chega. Saia do caixão, Pepita.",
  ui_story_1022_10220202_39_dialog_content = "Então novamente, combina bastante com você.",
  ui_story_1022_10220202_40_dialog_content = "De qualquer forma, você não tem nenhum respeito pelos mortos?",
  ui_story_1022_10220202_41_dialog_content = "!!!",
  ui_story_1022_10220202_42_dialog_content = "(Que me denunciou?! Ah, minhas roupas!)",
  ui_story_1022_10220202_43_dialog_content = "(Fui descuidado. Nem mesmo uma pessoa morta apareceria em seu próprio funeral vestindo trapos assim...)",
  ui_story_1022_10220202_44_dialog_content = "(Quando tudo isso acabar... Vou comprar roupas novas e bonitas para mim!)",
  ui_story_1022_10220202_45_dialog_content = "Você está falando sobre Pepita, o criminoso que roubou um livro valioso de Lumópolis?",
  ui_story_1022_10220202_46_dialog_content = "Sim, minha senhora. No entanto, o tomo roubado não era nada além de uma falsificação, então o próprio roubo não é particularmente nefasto.",
  ui_story_1022_10220202_47_dialog_content = "Nossa preocupação é que ela pegou este falso tomo e se juntou à True Order, a organização mais hedionda e herética que já assolou Astra!",
  ui_story_1022_10220202_48_dialog_content = "... Se o livro roubado é falso, então onde está o verdadeiro?",
  ui_story_1022_10220202_49_dialog_content = "Aí está o problema, minha senhora. O tomo genuíno foi perdido há muitos anos, mas nossa investigação até agora indica—",
  ui_story_1022_10220202_50_dialog_content = "Que também possa ter caído nas mãos da Verdadeira Ordem!",
  ui_story_1022_10220202_51_dialog_content = "Entendo agora. A Verdadeira Ordem sempre foi uma ameaça evasiva, seus membros aparecendo e desaparecendo como sussurros na noite.",
  ui_story_1022_10220202_52_dialog_content = "Então, quando Pepita apareceu e sentou-se para beber com Erica, você viu uma oportunidade no ladrão barulhento e fanfarrão.",
  ui_story_1022_10220202_53_dialog_content = "E assim você tentou usar ela para rastrear a True Order e recuperar o verdadeiro tomo.",
  ui_story_1022_10220202_54_dialog_content = "Sim, Senhora Carleen. Nosso plano na época era exatamente como você descreveu agora.",
  ui_story_1022_10220202_55_dialog_content = "Mas os malditos Carrascos do Comitê Illumina estavam um passo à frente de nós. Depois de encurralar Pepita, eles a levaram de volta para a Federação...",
  ui_story_1022_10220202_56_dialog_content = "Agora que você mencionou, Pepita parece ter sido enviada para a Dark Zone sob as ordens de Illumina. Não será fácil para nós capturá-la neste momento.",
  ui_story_1022_10220202_57_dialog_content = "Talvez, mas fique tranquila, Senhora Carleen.",
  ui_story_1022_10220202_58_dialog_content = "Para esta operação, a Divisão de Investigação de Hereges já obteve permissão do Senhor da Cidade, bem como da própria Grande Marechal.",
  ui_story_1022_10220202_59_dialog_content = "Após se encontrarem, nossos líderes autorizaram nossa contínua perseguição ao criminoso conhecido como Pepita, para que possamos finalmente levá-la à justiça como pretendíamos anteriormente.",
  ui_story_1022_10220202_60_dialog_content = "Não vamos deixá-la escapar desta vez!",
  ui_story_1022_10220202_61_dialog_content = "... Mesmo assim, atualmente estamos trabalhando em colaboração com a equipe de expedição da Zona Cega da Illumina.",
  ui_story_1022_10220202_62_dialog_content = "Eles encontraram Pepita não muito tempo atrás.",
  ui_story_1022_10220301_1_dialog_content = "Aqui, Carleen! Vocês chegaram aqui rapidamente!",
  ui_story_1022_10220301_2_dialog_content = "Claro. Quando um dos tesouros mais valiosos de Lumópolis está em jogo, não há tempo a perder.",
  ui_story_1022_10220301_3_dialog_content = "Qual é o problema? Você está exausto com seu primeiro encontro com aquele ladrão?",
  ui_story_1022_10220301_4_dialog_content = "B-Bem, estaria mentindo se dissesse que não fiquei confuso com isso...",
  ui_story_1022_10220301_5_dialog_content = "Mas não me subestime! Ela não deve ter ido longe, então vou usar meus poderes para localizá-la!",
  ui_story_1022_10220301_6_dialog_content = "...",
  ui_story_1022_10220301_7_dialog_content = "Philyshy está levando os colegas de equipe de Pepita de volta no dirigível, mas Hiiro e eu vamos ficar com você.",
  ui_story_1022_10220301_8_dialog_content = "Como ela foi designada para explorar a Zona Cega sob as ordens da Illumina, tenho a obrigação de localizá-la e obter qualquer informação que ela tenha coletado.",
  ui_story_1022_10220301_9_dialog_content = "Perdoe-me, mas receio que ela voltará conosco em vez disso.",
  ui_story_1022_10220301_10_dialog_content = "E você é?",
  ui_story_1022_10220301_11_dialog_content = "O capitão da Divisão de Investigação de Hereges em Lumópolis. Permita-me explicar nossa situação—",
  ui_story_1022_10220301_12_dialog_content = "...O Grande Marechal autorizou a operação de Lumópolis para capturar Pepita?",
  ui_story_1022_10220301_13_dialog_content = "Entendido. Você está autorizado a levá-la sob sua custódia, mas apenas depois que eu fizer algumas perguntas a ela.",
  ui_story_1022_10220301_14_dialog_content = "O capitão estava tão animada quando descobriu aquele lugar pela primeira vez, mas então ela quase imediatamente nos tirou de lá, como se de repente estivesse extremamente preocupada com nossa segurança.",
  ui_story_1022_10220301_15_dialog_content = "Algo me diz que o que vimos lá não era totalmente desconhecido para ela...",
  ui_story_1022_10220301_16_dialog_content = "Pepita claramente deve ter descoberto algo.",
  ui_story_1022_10220301_17_dialog_content = "Hmph, vocês soldados da Illumina nunca mudam! Você já a levou de nós uma vez antes, e agora está ameaçando fazer isso novamente!",
  ui_story_1022_10220301_18_dialog_content = "Como eu disse, você está livre para levá-la—",
  ui_story_1022_10220301_19_dialog_content = "Não me lembro de ter dado permissão para vocês me passarem pela mesa como um prato de bife!",
  ui_story_1022_10220301_20_dialog_content = "Pepita!",
  ui_story_1022_10220301_21_dialog_content = "Então você finalmente decidiu se entregar!",
  ui_story_1022_10220301_22_dialog_content = "Meu amigo! Não, espere... Eu não posso me deixar ser enganado novamente...",
  ui_story_1022_10220301_23_dialog_content = "Quem disse que eu estava enganando você? A diversão que tivemos bebendo juntos era real, e também eram suas emoções.",
  ui_story_1022_10220301_24_dialog_content = "Então fortaleça sua determinação e enfrente-me em uma luta real, Erica!",
  ui_story_1022_10220301_25_dialog_content = "Minhas emoções... Uma realidade em um mundo falso...",
  ui_story_1022_10220301_26_dialog_content = "Você não vai enganá-la uma segunda vez, Pepita!",
  ui_story_1022_10220301_27_dialog_content = "(Tão rápido!)",
  ui_story_1022_10220301_28_dialog_content = "Você não vai escapar!",
  ui_story_1022_10220301_29_dialog_content = "Pétalas Efêmeras Sobre Cinzas!",
  ui_story_1022_10220301_30_dialog_content = "<color=#e8d9bb>Onda após onda de ataques voam em direção a Pepita, que os contra-ataca brincando ou os desvia com agilidade sem esforço.</color>",
  ui_story_1022_10220301_31_dialog_content = "<color=#e8d9bb>Apesar das probabilidades esmagadoras, ela dificilmente parece estar em desvantagem.</color>",
  ui_story_1022_10220301_32_dialog_content = "Ela não é afetada pela influência da Zona Cega?!",
  ui_story_1022_10220301_33_dialog_content = "Sabia que tinha algo diferente nela...",
  ui_story_1022_10220301_34_dialog_content = "(Aurorianos normais sentem pressão quando se movem na Zona Escura, mas Pepita parece completamente não afetado...)",
  ui_story_1022_10220301_35_dialog_content = "Hahahaha! Parece que você está começando a entender o quão poderoso eu sou!",
  ui_story_1022_10220301_36_dialog_content = "Infelizmente para você, o tutorial acabou! Agora é hora de eu realmente me soltar!",
  ui_story_1022_10220301_37_dialog_content = "Tudo bem, Petey—Mostre a eles o que você tem!",
  ui_story_1022_10220301_38_dialog_content = "Esse poder...!",
  ui_story_1022_10220301_39_dialog_content = "O que está acontecendo?! Está ficando cada vez mais difícil respirar...",
  ui_story_1022_10220301_40_dialog_content = "O Fluxo Escuro está ficando mais espesso...",
  ui_story_1022_10220301_41_dialog_content = "(Não há dúvida... A boneca nas mãos de Pepita está emitindo a mesma energia que um Eclipsite! Mas como?!)",
  ui_story_1022_10220301_42_dialog_content = "Maior, maior! Faça-se tão grande quanto puder!",
  ui_story_1022_10220301_43_dialog_content = "<color=#e8d9bb>Pepita ri loucamente enquanto sua boneca estranha continua a crescer incontrolavelmente. Depois de um tempo, ela começa a lançar uma série de ataques explosivos de seu corpo inchado.</color>",
  ui_story_1022_10220301_44_dialog_content = "<color=#e8d9bb>Até mesmo sua sombra parecia consistir de uma substância desconhecida, espremendo as mentes e corpos de qualquer um que fosse pego em suas fronteiras.</color>",
  ui_story_1022_10220301_45_dialog_content = "Meu povo não vai sobreviver muito mais neste ritmo...!",
  ui_story_1022_10220301_46_dialog_content = "Quando ela colocou as mãos em uma boneca tão estranha?!",
  ui_story_1022_10220301_47_dialog_content = "O nome dele é Petey, para sua informação. Ele é meu <color=#FFB400>familiar</color>, então naturalmente ele tem que ser um pouco mágico!",
  ui_story_1022_10220301_48_dialog_content = "Até vou deixar você brincar com ele, já que sou tão legal! Aproveitem o tempo juntos, todos—",
  ui_story_1022_10220301_49_dialog_content = "Porque não vai durar muito.",
  ui_story_1022_10220301_50_dialog_content = "...!",
  ui_story_1022_10220301_51_dialog_content = "O que... O que é aquilo?",
  ui_story_1022_10220301_52_dialog_content = "Qual o problema, PlayerName? Por que está olhando em volta assim?",
  ui_story_1022_10220301_53_dialog_content = "<color=#e8d9bb>Ela está aqui.</color>",
  ui_story_1022_10220301_54_dialog_content = "Algo está vindo em nossa direção... Algo com uma enorme quantidade de Fluxo Escuro... S-Saia do caminho, pessoal!",
  ui_story_1022_10220301_55_dialog_content = "<color=#e8d9bb>De repente, uma lágrima gigante cai do céu. Enquanto todos correm para se refugiar, sua cor branca leitosa é refletida em seus olhos horrorizados.</color>",
  ui_story_1022_10220301_56_dialog_content = "<color=#e8d9bb>A lágrima cai no chão...</color>",
  ui_story_1022_10220301_57_dialog_content = "<color=#e8d9bb>E uma explosão devastadora sacode todo o campo de batalha.</color>",
  ui_story_1022_10220301_58_dialog_content = "Quem está pegando no pé do meu amigo?",
  ui_story_1022_10220301_59_dialog_content = "<color=#FFB400>Ursura</color>! Eu sabia que você viria!",
  ui_story_1022_10220301_60_dialog_content = "<color=#e8d9bb>À medida que a poeira assenta, uma figura aparece no centro da explosão, sua mera presença sufocando o ar nos pulmões de todos.</color>",
  ui_story_1022_10220301_61_dialog_content = "Este comprimento de onda... É um <color=#FFB400>fantasma</color>!",
  ui_story_1022_10220301_62_dialog_content = "Pepita, seu vilão! Você está conspirando não apenas com a True Order, mas também com os Eclipsitas?!",
  ui_story_1022_10220301_63_dialog_content = "Não consigo discernir sua aparência. É como se ela estivesse em uma névoa espessa...",
  ui_story_1022_10220301_64_dialog_content = "\"Conspirando\"? O que isso significa?! Pepita e eu somos amigos há muito tempo! Se alguém está conspirando, são vocês!",
  ui_story_1022_10220301_65_dialog_content = "?!!",
  ui_story_1022_10220301_66_dialog_content = "Hahahaha, você deveria ver as expressões em seus rostos! Ahh, isso por si só compensa todo o problema que enfrentei desde que reapareci.",
  ui_story_1022_10220301_67_dialog_content = "... Você sabia que eventualmente atrairíamos um Wraith para nós, não sabia?",
  ui_story_1022_10220301_68_dialog_content = "Bem, dã! Você acha que eu sou burro o suficiente para arrumar uma briga com vocês sem alguém como Ursura para me apoiar? Vamos lá, me dê algum crédito!",
  ui_story_1022_10220301_69_dialog_content = "Diga-me, como se sente ao cair em meus truques novamente, Sr. Celestita?",
  ui_story_1022_10220301_70_dialog_content = "Urgh...!",
  ui_story_1022_10220301_71_dialog_content = "Como está o pequeno Petey, Pepita? Senti a presença dele agora mesmo, então vim verificar você. Viu como sou legal?",
  ui_story_1022_10220301_72_dialog_content = "Ele está bem aqui, vê? Espere... Você não vai levá-lo de volta, vai? Nos tornamos realmente bons amigos agora, sabe!",
  ui_story_1022_10220301_73_dialog_content = "(Estou ouvindo isso direito? Por que parece que eles são realmente amigos...?)",
  ui_story_1022_10220301_74_dialog_content = "Não pense que está seguro só porque um fantasma veio ao seu resgate, Pepita.",
  ui_story_1022_10220301_75_dialog_content = "Você ainda precisa ser responsabilizado por roubar um livro sagrado de Lumópolis!",
  ui_story_1022_10220301_76_dialog_content = "Roubar? Aquele livro pertencia à True Order em primeiro lugar, muito obrigado.",
  ui_story_1022_10220301_77_dialog_content = "O quê?!",
  ui_story_1022_10220301_78_dialog_content = "É verdade, o que significa que nunca roubei nada de Lumópolis para começar.",
  ui_story_1022_10220301_79_dialog_content = "E quanto à Illumina, vamos apenas dizer que vocês têm sorte de eu estar disposto a deixar as coisas passarem.",
  ui_story_1022_10220301_80_dialog_content = "Isso não quer dizer que você não me deve nada, embora! Afinal, nada vem de graça!",
  ui_story_1022_10220301_81_dialog_content = "...",
  ui_story_1022_10220301_82_dialog_content = "Aquela velha bruxa Belisaria pensou que poderia usar meu \"coração\" para me controlar, mas ela estava errada. Mortalmente errada.",
  ui_story_1022_10220301_83_dialog_content = "O Grande Pepita não serve a ninguém! Hahahaha!",
  ui_story_1022_10220301_84_dialog_content = "Vamos sair daqui, Ursura.",
  ui_story_1022_10220301_85_dialog_content = "Vamos enlouquecer a noite toda!",
  ui_story_1022_10220301_86_dialog_content = "Pepita...",
  ui_story_1022_10220301_87_dialog_content = "Pare aí mesmo!",
  ui_story_1022_10220301_88_dialog_content = "Argh... Vocês são todos tão irritantes! Apenas morram logo!!!",
  ui_story_1022_10220301_89_dialog_content = "Grahhhh—!!",
  ui_story_1022_10220301_90_dialog_content = "Cuidado!",
  ui_story_1022_10220302_1_dialog_content = "(Vá, Petey. Diga à Senhora Victoria onde estou agora mesmo.)",
  ui_story_1022_10220302_2_dialog_content = "Por que você ainda está parado, Pepita? Eu pensei que você disse que íamos nos divertir!",
  ui_story_1022_10220302_3_dialog_content = "Chegando, chegando!",
  ui_story_1022_10220302_4_dialog_content = "Bwahaha, você viu os rostos deles agora mesmo? Eles estavam tão bravos, mesmo que eu os tenha derrotado tão mal!",
  ui_story_1022_10220302_5_dialog_content = "Sim, você fez! Eu só queria que você estivesse lá para ver como eu explodi todos eles com minhas armadilhas mais cedo. Eles nunca viram isso chegando!",
  ui_story_1022_10220302_6_dialog_content = "Ahh, foi uma vista tão incrível!",
  ui_story_1022_10220302_7_dialog_content = "*Soluçando* E-E você não me convidou? Isso não é justo, Pepita!",
  ui_story_1022_10220302_8_dialog_content = "Você me deve agora! Vamos ficar ainda mais loucos do que nunca antes, você me ouviu?!",
  ui_story_1022_10220302_9_dialog_content = "Eu sei, então pare de chorar. Os bons tempos nunca param quando estamos juntos, lembra?",
  ui_story_1022_10220302_10_dialog_content = "(Eclipsiano) Há um pequeno objeto em movimento longe à distância. Parece estar fugindo.",
  ui_story_1022_10220302_11_dialog_content = "(Falando em Eclipsiano) Ah—É o familiar dado àquele Aurorian pela Senhora Ursura!",
  ui_story_1022_10220302_12_dialog_content = "(Em Eclipsiano) Que problemas ela está causando agora? Aurorianos são muito astutos para serem confiáveis, isso é sabido.",
  ui_story_1022_10220302_13_dialog_content = "(Eclipsiano) Devemos deixá-los ir?",
  ui_story_1022_10220302_14_dialog_content = "(Eclipsiano) Não, seu tolo! Devemos capturar aquele familiar e devolvê-lo à Senhora Ursura!",
  ui_story_1022_10220302_15_dialog_content = "(Eclipsiano) Entendido!",
  ui_story_1022_10220302_16_dialog_content = "Amaldiçoe tudo!!!",
  ui_story_1022_10220302_17_dialog_content = "Nós a tínhamos completamente cercada... E ainda assim ela escorregou por entre nossos dedos novamente!",
  ui_story_1022_10220302_18_dialog_content = "Não seja tão duro consigo mesmo. Nenhum de nós sabia que Pepita pode chamar um fantasma para ajudá-la.",
  ui_story_1022_10220302_19_dialog_content = "Minhas suspeitas, por outro lado, foram totalmente confirmadas.",
  ui_story_1022_10220302_20_dialog_content = "Aquele fantasma tinha algo semelhante a coral crescendo de seu corpo...",
  ui_story_1022_10220302_21_dialog_content = "Assim que ela descobriu \"aquele lugar\", ela sabia que um fantasma estava por perto. Nesse ponto, ela decidiu usar o fantasma como meio de escapar e se entregar a ele.",
  ui_story_1022_10220302_22_dialog_content = "Render-se... A um Wraith? Mas o que um Wraith poderia possivelmente oferecer a ela?",
  ui_story_1022_10220302_23_dialog_content = "Tudo o que prova é que ela caiu além da salvação! Não deixe que ela o influencie com suas palavras nunca mais, Erica!",
  ui_story_1022_10220302_24_dialog_content = "...",
  ui_story_1022_10220302_25_dialog_content = "Ninguém mais acha isso estranho?",
  ui_story_1022_10220302_26_dialog_content = "O que você quer dizer, Carleen?",
  ui_story_1022_10220302_27_dialog_content = "Aquele fantasma, Ursura - Ela é claramente uma inimiga extremamente poderosa, e ainda assim ela não parecia particularmente interessada em lutar contra nós.",
  ui_story_1022_10220302_28_dialog_content = "Nas duas vezes em que ela atacou, foi para proteger Pepita.",
  ui_story_1022_10220302_29_option_content = "C-Poderia ser este o poder da amizade?!",
  ui_story_1022_10220302_30_dialog_content = "... Este não é o momento para piadas.",
  ui_story_1022_10220302_31_dialog_content = "Foi mal!",
  ui_story_1022_10220302_32_option_content = "Mas, brincadeiras à parte, eles pareciam ser amigos um do outro.",
  ui_story_1022_10220302_33_dialog_content = "Pepita tinha certeza de que Ursura viria ao seu resgate, que era o único motivo pelo qual ela se mostrou diante de nós.",
  ui_story_1022_10220302_34_dialog_content = "Amizade entre um fantasma e um Aurorian... Isso é realmente possível?",
  ui_story_1022_10220302_35_dialog_content = "Concordo: o comportamento de Ursura estava longe de ser normal.",
  ui_story_1022_10220302_36_dialog_content = "Ela não tinha inimizade conosco e estava apenas interessada em ajudar Pepita... Mas por quê? Eles poderiam estar planejando algo mais?",
  ui_story_1022_10220302_37_dialog_content = "Talvez esses dois estejam apenas interessados em se divertir juntos?",
  ui_story_1022_10220302_38_dialog_content = "...",
  ui_story_1022_10220302_39_dialog_content = "Não seja absurdo!",
  ui_story_1022_10220302_40_dialog_content = "Agora pegue sua Pedra Lumina e prepare-se para partir, Erica!",
  ui_story_1022_10220302_41_dialog_content = "O quê? Vocês estão realmente indo atrás de Pepita?!",
  ui_story_1022_10220302_42_dialog_content = "Claro que estamos, e nenhum fantasma nos impedirá de cumprir nossa missão! Agora, fique fora do nosso caminho!",
  ui_story_1022_10220302_43_dialog_content = "Não temos escolha. Pepita tem informações que podem nos levar ao tomo roubado de Lumópolis.",
  ui_story_1022_10220302_44_dialog_content = "... Uma vez que a encontrarmos, podemos fazer todas as perguntas que quisermos.",
  ui_story_1022_10220302_45_dialog_content = "(Parece que Carleen está insinuando sobre a Verdadeira Ordem, e a possibilidade do livro roubado realmente pertencer a eles...)",
  ui_story_1022_10220302_46_dialog_content = "(Ela mencionou anteriormente que Pepita era um membro da Verdadeira Ordem.)",
  ui_story_1022_10220302_47_dialog_content = "(Mas se esse é o caso, por que ela foi feita prisioneira pela Illumina? E por que parece que ela tem uma dívida a cobrar deles?)",
  ui_story_1022_10220302_48_dialog_content = "(Há simplesmente muito que não sabemos agora...)",
  ui_story_1022_10220401_1_dialog_content = "Bem-vindo à Tundra de Coral!",
  ui_story_1022_10220401_2_dialog_content = "Lindo, não é? Aposto que você nunca viu nada tão bizarro quanto isso! Vá em frente, grite e berre à vontade do seu coração!",
  ui_story_1022_10220401_3_dialog_content = "É tão bonito de uma maneira distorcida e retorcida. Eu posso ver por que você gosta tanto deste lugar.",
  ui_story_1022_10220401_4_dialog_content = "Qual é o problema? Este lugar não te excita? Vamos lá, mostre alguma emoção!",
  ui_story_1022_10220401_5_dialog_content = "Estou falando sério, Ursura. Este lugar é tão bonito e único que me pegou completamente de surpresa.",
  ui_story_1022_10220401_6_dialog_content = "(Ou pelo menos foi na primeira vez que eu vi.)",
  ui_story_1022_10220401_7_dialog_content = "Bom o suficiente para mim, eu acho. Vamos lá, há muita diversão para ser tida por aqui!",
  ui_story_1022_10220401_8_dialog_content = "É melhor que haja! Você me deixou todo animado sobre este lugar, então não me decepcione!",
  ui_story_1022_10220401_9_dialog_content = "<color=#e8d9bb>O que deveria ter sido um campo pálido e silencioso de gelo era, em vez disso, uma paisagem vibrante cheia de líquens, corais e árvores coloridas, como uma cena tirada diretamente de um conto de fadas sombrio.</color>",
  ui_story_1022_10220401_10_dialog_content = "<color=#e8d9bb>E ali, movendo-se entre os corais—</color>",
  ui_story_1022_10220401_11_dialog_content = "?!",
  ui_story_1022_10220401_12_dialog_content = "(São aqueles... Aurorianos? Não, seus olhos opacos e sem vida são mais parecidos com os dos Eclipsitas, mas eles não se parecem em nada.)",
  ui_story_1022_10220401_13_dialog_content = "<color=#e8d9bb>As criaturas sem alma, semelhantes aos Aurorianos, movem-se mecanicamente entre os recifes de coral, esfregando os líquenes excessivos de suas superfícies.</color>",
  ui_story_1022_10220401_14_dialog_content = "<color=#e8d9bb>Contra o pano de fundo resplandecente de árvores e corais, seus movimentos rígidos parecem ainda mais arrepiantes.</color>",
  ui_story_1022_10220401_15_dialog_content = "Ei Ursura, aqueles são...?",
  ui_story_1022_10220401_16_dialog_content = "Você realmente não sabe o que são esses? São corais, bobo!",
  ui_story_1022_10220401_17_dialog_content = "Não, eu me refiro às pessoas andando ao redor deles... Eles são Aurorianos ou Eclipsitas? Ou talvez algo completamente diferente?",
  ui_story_1022_10220401_18_dialog_content = "Ah... Por que você está perdendo tempo olhando para eles? Não tem sentido, sabe.",
  ui_story_1022_10220401_19_dialog_content = "Vou te dizer agora mesmo, eles definitivamente não herdaram nada do que torna divertido brincar com os Aurorians.",
  ui_story_1022_10220401_20_dialog_content = "(\"Herdar\"? Em outras palavras... Eles estão de alguma forma conectados aos Aurorians.)",
  ui_story_1022_10220401_21_dialog_content = "Depois de passar tanto tempo aqui, esses caras se tornaram muito mais resistentes. É por isso que <color=#FFB400>nós</color> os usamos para tarefas simples como limpeza.",
  ui_story_1022_10220401_22_dialog_content = "Eles ouvem bem quando mandamos fazer coisas, mas caso contrário, são completamente inúteis.",
  ui_story_1022_10220401_23_dialog_content = "Eles são péssimos em conversas, não sabem como se divertir e morrem muito facilmente. Eles simplesmente não se comparam aos Aurorians, sabe!",
  ui_story_1022_10220401_24_dialog_content = "(Eles não têm como se comunicar ou contra-atacar... É isso que ela está tentando dizer?)",
  ui_story_1022_10220401_25_dialog_content = "Ah, mas não se preocupe com eles! Eu sou quem comanda este lugar, agora me siga!",
  ui_story_1022_10220401_26_dialog_content = "...",
  ui_story_1022_10220402_1_dialog_content = "Ufa... Finalmente terminamos os experimentos de hoje.",
  ui_story_1022_10220402_2_dialog_content = "Sou o único que acha que os testes estão ficando mais difíceis ultimamente?",
  ui_story_1022_10220402_3_dialog_content = "Não, você está certo... Para ser honesto, eu não sei quanto mais eu posso aguentar.",
  ui_story_1022_10220402_4_dialog_content = "Meu corpo todo dói como louco, e continuo tendo pesadelos todas as noites...",
  ui_story_1022_10220402_5_dialog_content = "Mesmo aqui...",
  ui_story_1022_10220402_6_dialog_content = "Pepita parece estar aguentando muito bem! Mesmo com um coração fraco e os piores testes de todos nós, nada parece te desacelerar!",
  ui_story_1022_10220402_7_dialog_content = "Ahh, isso não é nada para mim!",
  ui_story_1022_10220402_8_dialog_content = "Comparado ao perigo que meu pai enfrentou, isso é apenas um passeio no parque!",
  ui_story_1022_10220402_9_dialog_content = "Ah sim... Seu pai foi explorar a Zona Escura, não foi Pepita?",
  ui_story_1022_10220402_10_dialog_content = "Sim! Ele faz parte da Equipe de Exploração da Zona Escura da Illumina, então ele faz todo tipo de coisa incrível lá fora!",
  ui_story_1022_10220402_11_dialog_content = "É por isso que eu também quero explorar a Zona Escura. Aposto que ele vai se orgulhar muito de mim! Hahaha!",
  ui_story_1022_10220402_12_dialog_content = "Esse é o espírito, Pepita! Vamos te apoiar o tempo todo!",
  ui_story_1022_10220402_13_dialog_content = "Mas espere, isso não significa que você não vai vê-lo durante nossa próxima visita?",
  ui_story_1022_10220402_14_dialog_content = "... N-Não pode ser evitado. Ele é um cara realmente ocupado, afinal de contas...",
  ui_story_1022_10220402_15_dialog_content = "Tudo bem! Se houver algo que você queira, apenas me diga e eu pedirei para minha mãe trazer para você!",
  ui_story_1022_10220402_16_dialog_content = "T-Tá bem... Valeu.",
  ui_story_1022_10220402_17_dialog_content = "Meu pai virá me ver assim que ele voltar... Tenho certeza disso.",
  ui_story_1022_10220402_18_dialog_content = "<color=#e8d9bb>Alguns anos depois-</color>",
  ui_story_1022_10220402_19_dialog_content = "Como ela tem estado ultimamente?",
  ui_story_1022_10220402_20_dialog_content = "O mesmo de sempre, senhora. Ela joga fora qualquer comida que não gosta e pede porções duplas das coisas que gosta—",
  ui_story_1022_10220402_21_dialog_content = "Ela continua gritando conosco para tocar música, e começa a cantar a plenos pulmões se a ignorarmos...",
  ui_story_1022_10220402_22_dialog_content = "Ela está aqui há tempo suficiente para que todos vocês conheçam suas preferências. Se ela se recusar a comer algo, então não sirva isso para ela.",
  ui_story_1022_10220402_23_dialog_content = "... S-Sim, senhora!",
  ui_story_1022_10220402_24_dialog_content = "Você não acha que está mimando ela demais? Afinal, ela é apenas uma prisioneira.",
  ui_story_1022_10220402_25_dialog_content = "Ela e seu coração são ambos espécimes inestimáveis. Temos mais a perder do que qualquer outro se ela sucumbir à desnutrição.",
  ui_story_1022_10220402_26_dialog_content = "E além disso, desperdiçar comida nunca é uma coisa boa.",
  ui_story_1022_10220402_27_dialog_content = "... Então vamos esperar que ela coopere com você.",
  ui_story_1022_10220402_28_dialog_content = "Ei, qual é o problema lá fora? Você conseguiu o meu disco, ou eu tenho que continuar cantando? Não me diga que você está começando a gostar da minha voz ou algo assim!",
  ui_story_1022_10220402_29_dialog_content = "Suponho que não devo decepcionar meus fãs, então vamos lá! Ahem! Leve-me para caaaaaasa, para aqueles campos de veeeeeeeerde♪",
  ui_story_1022_10220402_30_dialog_content = "Você nunca viu um campo verde em sua vida, Pepita.",
  ui_story_1022_10220402_31_dialog_content = "Ah, não você de novo. Estou cansado de ver essa sua cara velha e feia, suma daqui.",
  ui_story_1022_10220402_32_dialog_content = "É mesmo? Eu me lembro de como você ficava animado sempre que eu te visitava no laboratório.",
  ui_story_1022_10220402_33_dialog_content = "E isso foi porque eu era a única pessoa que sempre vinha te ver.",
  ui_story_1022_10220402_34_dialog_content = "Você não estava lá para me ver. Você apenas veio para ver como seu precioso sujeito de teste estava.",
  ui_story_1022_10220402_35_dialog_content = "O valor de um sujeito de teste é tanto concreto quanto quantificável.",
  ui_story_1022_10220402_36_dialog_content = "Mas coisas como emoções e até laços familiares são muito vagas para serem confiáveis. Na verdade, muitas vezes levam as pessoas a se desviarem.",
  ui_story_1022_10220402_37_dialog_content = "Você, mais do que ninguém, deveria saber disso.",
  ui_story_1022_10220402_38_dialog_content = "...",
  ui_story_1022_10220402_39_dialog_content = "Se você realmente odeia hipocrisia tanto quanto diz, então em vez de soltar todas essas bobagens rebeldes—",
  ui_story_1022_10220402_40_dialog_content = "Você deveria ver minha presença aqui de uma forma mais positiva... Minha preciosa cobaia.",
  ui_story_1022_10220402_41_dialog_content = "Vem cá, Ulysses.",
  ui_story_1022_10220402_42_dialog_content = "...",
  ui_story_1022_10220402_43_dialog_content = "Huh?! É-Esse dispositivo de novo!",
  ui_story_1022_10220402_44_dialog_content = "(Não há dúvida. Naquele ano, quando aqueles cientistas da Illumina substituíram meu coração defeituoso por um artificial...)",
  ui_story_1022_10220402_45_dialog_content = "(Eu vi aquele aparelho ao lado da minha cama quando acordei da cirurgia.)",
  ui_story_1022_10220402_46_dialog_content = "(E dentro dela... Está o meu coração original! Tenho certeza disso!)",
  ui_story_1022_10220402_47_dialog_content = "Parece que você sabe exatamente o que está dentro deste recipiente.",
  ui_story_1022_10220402_48_dialog_content = "... O que você quer de mim?",
  ui_story_1022_10220402_49_dialog_content = "É simples. Precisamos que você use seus poderes únicos para entrar na Dark Zone e recuperar o núcleo do Guardião Um.",
  ui_story_1022_10220402_50_dialog_content = "Se você tiver sucesso, eu mesmo entregarei isso a você.",
  ui_story_1022_10220402_51_dialog_content = "Também posso usar nossa tecnologia atualizada para terminar a construção do seu coração artificial incompleto. A escolha é sua.",
  ui_story_1022_10220402_52_dialog_content = "Você acha que pode me manipular assim?!",
  ui_story_1022_10220402_53_dialog_content = "Eu já te disse para não deixar suas emoções guiarem suas escolhas, Pepita.",
  ui_story_1022_10220402_54_dialog_content = "Pense longa e profundamente sobre o que você realmente quer e o preço que está disposto a pagar por isso.",
  ui_story_1022_10220402_55_dialog_content = "...",
  ui_story_1022_10220402_56_dialog_content = "<color=#e8d9bb>Na Tundra Coral da Zona Escura.</color>",
  ui_story_1022_10220402_57_dialog_content = "<color=#e8d9bb>Com uma voz estridente, Ursura ordena a seus lacaios Eclipsitas que preparem um banquete em honra de seu amigo.</color>",
  ui_story_1022_10220402_58_dialog_content = "<color=#e8d9bb>Quando Pepita volta a si, ela percebe que estava perdida em suas memórias por um bom tempo.</color>",
  ui_story_1022_10220402_59_dialog_content = "<color=#e8d9bb>Ao contemplar as magníficas formações de corais, ela se lembra por que escolheu abandonar seu acordo com Belisaria e vir para cá em vez disso.</color>",
  ui_story_1022_10220402_60_dialog_content = "Ursura.",
  ui_story_1022_10220402_61_dialog_content = "Idiota! Quem te disse para colocar coral vermelho e verde no mesmo prato?! Seu senso estético não é melhor que o de uma formiga!",
  ui_story_1022_10220402_62_dialog_content = "É precisamente por isso que ser de uma linhagem nobre é tão importante... Precisava de algo, Pepita?",
  ui_story_1022_10220402_63_dialog_content = "Você se lembra do que eu te disse quando nos conhecemos pela primeira vez? A história sobre o meu coração?",
  ui_story_1022_10220402_64_dialog_content = "Sobre como aquelas pessoas tiraram meu coração original e—",
  ui_story_1022_10220402_65_dialog_content = "Ah, esses idiotas Aurorianos! Eles arrancaram seu coração e nem tiveram a decência de substituí-lo por um totalmente funcional! É por isso que você está em tanta dor o tempo todo!",
  ui_story_1022_10220402_66_dialog_content = "Eu me lembro de tudo que você me contou sobre isso, Pepita... Então não há necessidade de começar do início.",
  ui_story_1022_10220402_67_dialog_content = "Claro, mas naquela época, você disse algo sobre ser capaz de criar um coração funcional também.",
  ui_story_1022_10220402_68_dialog_content = "<color=#e8d9bb>O olhar de Pepita cai para o centro do peito de Ursura, onde ramos de coral pulsante e ondulante se projetam de maneira espetacular.</color>",
  ui_story_1022_10220402_69_dialog_content = "<color=#e8d9bb>São estes corais que compõem o próprio coração de Ursura.</color>",
  ui_story_1022_10220402_70_dialog_content = "Claro que posso! Afinal, eu tenho o poder mais puro e nobre por aqui!",
  ui_story_1022_10220402_71_dialog_content = "Para alguém tão poderoso quanto eu, criar um coração poderoso de coral é tão simples quanto respirar!",
  ui_story_1022_10220402_72_dialog_content = "... Então, quando você pode começar?",
  ui_story_1022_10220402_73_dialog_content = "Isso significa que você finalmente se decidiu?",
  ui_story_1022_10220402_74_dialog_content = "Hunf! Nesse caso... Você tem que me prometer algo primeiro!",
  ui_story_1022_10220501_1_dialog_content = "Nyaaa! Por que todas as coisas malucas acontecem quando eu não estou por perto?!",
  ui_story_1022_10220501_2_dialog_content = "Mas tudo bem! Como a Chefe de Inteligência favorita de todos, eu trouxe muitas informações valiosas para usarmos!",
  ui_story_1022_10220501_3_dialog_content = "É sobre Pepita?!",
  ui_story_1022_10220501_4_dialog_content = "Você adivinhou! Antes de eu partir, mal sabíamos algo sobre aquela garota, apesar de termos enviado ela para a Zona Escura com sua própria equipe.",
  ui_story_1022_10220501_5_dialog_content = "Então eu consegui falar com Yingel, e ela foi gentil o suficiente para analisar um monte de documentos do Comitê para nós!",
  ui_story_1022_10220501_6_dialog_content = "O Comitê? Eu sabia que havia mais nela do que pensávamos.",
  ui_story_1022_10220501_7_dialog_content = "Pelo que encontramos em seus arquivos, o Comitê enviou uma Equipe de Expedição diferente para a Zona Escura anos atrás...",
  ui_story_1022_10220501_8_dialog_content = "E o pai de Pepita aconteceu de ser um de seus membros.",
  ui_story_1022_10220501_9_dialog_content = "Hã? Você está dizendo que ela foi incluída na equipe de expedição?",
  ui_story_1022_10220501_10_dialog_content = "Não, PlayerName. Pense na aparência de Pepita durante a nossa batalha.",
  ui_story_1022_10220501_11_dialog_content = "Ela não estava usando nenhum tipo de equipamento, e ainda assim seus movimentos não foram afetados pelo Darkflow de forma alguma.",
  ui_story_1022_10220501_12_dialog_content = "Se essa característica é hereditária, então tudo isso faz muito mais sentido.",
  ui_story_1022_10220501_13_dialog_content = "... Você tem razão. Se a habilidade de Pepita de se mover livremente na Zona Cega é herdada, então provavelmente o pai dela também a tinha.",
  ui_story_1022_10220501_14_dialog_content = "A exploração dele deve ter sido realmente bem sucedida então, certo?",
  ui_story_1022_10220501_15_dialog_content = "Pelo contrário, toda a sua equipe foi exterminada...",
  ui_story_1022_10220501_16_dialog_content = "E-Eliminados?!",
  ui_story_1022_10220501_17_dialog_content = "Isso mesmo, e o único sobrevivente foi o pai de Pepita.",
  ui_story_1022_10220501_18_dialog_content = "Mas parece que sua habilidade especial não foi a única coisa que ele usou para voltar. Há uma boa chance de que ele tenha recorrido a meios menos nobres para sobreviver...",
  ui_story_1022_10220501_19_dialog_content = "Porque assim que ele voltou, assinou toda a documentação necessária para colocar Pepita sob a custódia de um laboratório de Illumina.",
  ui_story_1022_10220501_20_dialog_content = "Ele abandonou a própria filha?!",
  ui_story_1022_10220501_21_dialog_content = "Mas isso é basicamente concordar em deixá-la se tornar uma cobaia!",
  ui_story_1022_10220501_22_dialog_content = "Eu sei... É por isso que Yingel acha que deve ter feito algo tão ruim que a única maneira de se salvar era sacrificando sua própria criança...",
  ui_story_1022_10220501_23_dialog_content = "... Inacreditável.",
  ui_story_1022_10220501_24_dialog_content = "Não pensei que alguém na Federação pudesse fazer algo tão covarde.",
  ui_story_1022_10220501_25_dialog_content = "Depois disso, nossas explorações na Zona Escura diminuíram significativamente, mas a pesquisa sobre Pepita continuou sem hesitação.",
  ui_story_1022_10220501_26_dialog_content = "Para maximizar sua força de combate e mobilidade, o Comitê substituiu seu deficiente coração auroriano por um artificial.",
  ui_story_1022_10220501_27_dialog_content = "O quê? Você quer dizer que o coração dela é feito pelo homem?",
  ui_story_1022_10220501_28_dialog_content = "Em outras palavras, o Comitê nunca abandonou seus planos de explorar a Zona Escura. Ao contrário, eles estavam preparando Pepita para ser o próximo líder da Equipe de Expedição.",
  ui_story_1022_10220501_29_dialog_content = "Essa é uma possibilidade distinta com certeza! No entanto...",
  ui_story_1022_10220501_30_dialog_content = "Nossa tecnologia sobre corações artificiais ainda está longe de ser desenvolvida, o que significa que Pepita provavelmente também era uma cobaia valiosa...",
  ui_story_1022_10220501_31_dialog_content = "Pobre Pepita... Como eles poderiam fazê-la passar por tanta dor?",
  ui_story_1022_10220501_32_dialog_content = "Eu sei, mas fica pior. Depois que Pepita descobriu o acordo entre seu pai e o Comitê, ela saiu completamente dos trilhos...",
  ui_story_1022_10220501_33_dialog_content = "Ela fugiu da Illumina na primeira oportunidade que teve e começou a vagar por Astra como uma fugitiva. Pelo que reunimos, parece que ela agora se juntou à True Order.",
  ui_story_1022_10220501_34_dialog_content = "Finalmente entendi... Sem nenhum outro lugar para ir, ela acabou com eles...",
  ui_story_1022_10220501_35_dialog_content = "Mas espere, tem mais! Depois que ela escapou, Pepita na verdade se infiltrou de volta na Federação em um determinado momento.",
  ui_story_1022_10220501_36_dialog_content = "Uma escolha corajosa, mas tola. Qual era o objetivo dela?",
  ui_story_1022_10220501_37_dialog_content = "Acho que o objetivo dela era roubar de volta seu coração original.",
  ui_story_1022_10220501_38_dialog_content = "Mas não demorou muito para encontrá-la, então ela fugiu novamente.",
  ui_story_1022_10220501_39_dialog_content = "Então, ela tinha duas grandes facções a caçando, mas Illumina a capturou no final. Não só isso, mas eles também a enviaram diretamente para a Dark Zone...",
  ui_story_1022_10220501_40_dialog_content = "Não sei como mais descrevê-lo... Mas ela tem uma das histórias mais coloridas que já vi.",
  ui_story_1022_10220501_41_dialog_content = "(Eu realmente não posso culpá-la por odiar autoridade ou ser rebelde...)",
  ui_story_1022_10220501_42_dialog_content = "E agora ela está em aliança com um fantasma.",
  ui_story_1022_10220501_43_dialog_content = "Excelente trabalho, Philyshy. Reportarei tudo ao Grande Marechal o mais rápido possível.",
  ui_story_1022_10220502_1_dialog_content = "... E essa é a nossa situação até agora. A capacidade de Pepita se mover livremente pela Zona Cega é definitivamente valiosa.",
  ui_story_1022_10220502_2_dialog_content = "Como devemos proceder, Grande Marechal?",
  ui_story_1022_10220502_3_dialog_content = "Se encontrarmos ela novamente, realmente se espera que fiquemos parados e deixemos Lumópolis levá-la?",
  ui_story_1022_10220502_4_dialog_content = "É muito provável que Pepita saiba algo sobre o tesouro roubado de Lumópolis.",
  ui_story_1022_10220502_5_dialog_content = "Esta exploração é um esforço conjunto entre a Illumina e a Lumópolis. Se quisermos ter sucesso, não podemos simplesmente ignorar seus interesses.",
  ui_story_1022_10220502_6_dialog_content = "Mas…",
  ui_story_1022_10220502_7_dialog_content = "Isso não significa que não podemos traçar uma linha em algum lugar, embora.",
  ui_story_1022_10220502_8_dialog_content = "Yingel me contou sobre o passado de Pepita há algum tempo. Suspeitei que ela poderia ter um talento para explorar a Zona Escura—",
  ui_story_1022_10220502_9_dialog_content = "Então, compartilhei essa informação com o Senhor da Cidade de Lumopolis.",
  ui_story_1022_10220502_10_dialog_content = "O quê?! Th-Então... Qual foi a reação dele?",
  ui_story_1022_10220502_11_dialog_content = "Qualquer um com olhos pode ver que Pepita é muito mais útil em campo do que em uma cela de prisão.",
  ui_story_1022_10220502_12_dialog_content = "Schwartz não é exceção.",
  ui_story_1022_10220502_13_dialog_content = "Se pudermos usar Pepita e suas habilidades ao máximo, todos se beneficiarão.",
  ui_story_1022_10220502_14_dialog_content = "Não apenas para esta operação, mas também a longo prazo.",
  ui_story_1022_10220502_15_dialog_content = "Você deseja usar ela para coletar mais informações que poderiam nos dar uma vantagem sobre as Eclipsitas em nossas futuras batalhas... É isso?",
  ui_story_1022_10220502_16_dialog_content = "Parece que estamos na mesma página, Senhor Schwartz.",
  ui_story_1022_10220502_17_dialog_content = "Hmph... Na minha opinião, ela não é nada mais do que uma ladra insignificante. Contanto que ela nos diga o que sabe sobre nosso tomo sagrado, Lumópolis não a verá como inimiga.",
  ui_story_1022_10220502_18_dialog_content = "Vejo... Trabalho impressionante, Grande Marechal!",
  ui_story_1022_10220502_19_dialog_content = "Estou feliz que você entenda, então apenas siga os planos deles por enquanto.",
  ui_story_1022_10220502_20_dialog_content = "Além disso, tenho certeza de que Pepita será ainda mais problemático do que toda Lumópolis lá fora! Hahahaha!",
  ui_story_1022_10220502_21_dialog_content = "D-De maneira nenhuma! Sem a sua intervenção oportuna, Lumopolis certamente teria jogado aquela garota na prisão!",
  ui_story_1022_10220502_22_dialog_content = "Afinal... O líder da Divisão de Investigação de Heréticos tem uma obsessão quase maníaca pela True Order.",
  ui_story_1022_10220502_23_dialog_content = "O-O que você quer dizer, Pepita não enfrentará mais punição?!",
  ui_story_1022_10220502_24_dialog_content = "O Lorde da Cidade deve estar plenamente ciente de sua associação com a Verdadeira Ordem!",
  ui_story_1022_10220502_25_dialog_content = "Sim, mas o Senhor da Cidade também está considerando os benefícios de longo prazo que ela pode proporcionar para todos os Aurorians.",
  ui_story_1022_10220502_26_dialog_content = "Ainda temos ordens para interrogá-la sobre o tomo roubado também.",
  ui_story_1022_10220502_27_dialog_content = "Mas como... Como podemos deixar ir tão facilmente...?",
  ui_story_1022_10220502_28_dialog_content = "... Eu sei que você guarda rancor contra a True Order, e sua vingança te tornou um membro exemplar da Divisão de Investigação de Hereges.",
  ui_story_1022_10220502_29_dialog_content = "Mas se os alvos do seu ódio realmente pertencem à Verdadeira Ordem tem sido questionado há anos.",
  ui_story_1022_10220502_30_dialog_content = "Não... Não podemos simplesmente deixá-la ir... Não assim...",
  ui_story_1022_10220502_31_dialog_content = "Já chega, agora componha-se!",
  ui_story_1022_10220502_32_dialog_content = "Estamos na Zona Escura agora. Ao permitir que suas emoções te controlem, você está colocando a vida de seus camaradas em risco!",
  ui_story_1022_10220502_33_dialog_content = "... Você está certa, minha senhora. Por favor, perdoe minha explosão...",
  ui_story_1022_10220502_34_dialog_content = "Eu... Só preciso de um tempo sozinho, só isso.",
  ui_story_1022_10220502_35_dialog_content = "...",
  ui_story_1022_10220601_1_dialog_content = "Não posso deixá-la ir... Não vou! Mesmo que eu tenho que fazer isso sozinho... Vou fazê-la pagar...",
  ui_story_1022_10220601_2_dialog_content = "Ela e todos os membros da Verdadeira Ordem... Devem ser condenados à morte!",
  ui_story_1022_10220601_3_dialog_content = "Vejo que você ainda pretende fazer algo tolo.",
  ui_story_1022_10220601_4_dialog_content = "S-Senhora Carleen...!",
  ui_story_1022_10220601_5_dialog_content = "O que você tem na sua mão?",
  ui_story_1022_10220601_6_dialog_content = "É... É chamado de Ressonador da Noite Branca. É um dos artefatos guardados no Templo de Lumópolis e é capaz de detectar a presença de nossos objetos abençoados.",
  ui_story_1022_10220601_7_dialog_content = "Tem reagido intensamente a algo desde que entramos na Zona Escura.",
  ui_story_1022_10220601_8_dialog_content = "Acredito que um dos artefatos perdidos de Lumópolis possa estar em algum lugar próximo.",
  ui_story_1022_10220601_9_dialog_content = "Está apontando para uma certa direção? Tipo... Qual é a direção em que Pepita e Ursura foram?",
  ui_story_1022_10220601_10_dialog_content = "Eu...",
  ui_story_1022_10220601_11_dialog_content = "Você estava planejando rastreá-los e trazer de volta nossos artefatos perdidos sozinho, não estava?",
  ui_story_1022_10220601_12_dialog_content = "Se for assim, você não está apenas superestimando suas habilidades, mas também está subestimando severamente seus aliados!",
  ui_story_1022_10220601_13_dialog_content = "Se uma única pessoa fosse capaz de realizar algo aqui, teríamos nos unido para criar essa Equipe de Expedição?!",
  ui_story_1022_10220601_14_dialog_content = "Não tenho certeza se devo mencionar isso ou não... Mas eu sinto aquela enorme bola de Lumina na mesma direção também.",
  ui_story_1022_10220601_15_dialog_content = "?!",
  ui_story_1022_10220601_16_dialog_content = "Os fantasmas são nosso inimigo comum. Isso é tudo que tenho a dizer.",
  ui_story_1022_10220601_17_dialog_content = "Você... Hunf.",
  ui_story_1022_10220601_18_dialog_content = "Também quero encontrar Pepita, capitão... Não para puni-la, mas para salvá-la.",
  ui_story_1022_10220601_19_dialog_content = "O propósito da nossa organização é salvar o mundo de forças desconhecidas... E nossos aliados não são exceção. Pelo menos... É assim que eu me sinto.",
  ui_story_1022_10220601_20_dialog_content = "Erica... Você se provou ser mais calmo e sábio do que eu pensava anteriormente. Eu, por outro lado...",
  ui_story_1022_10220601_21_dialog_content = "Perdoe-me, Senhora Carleen... E todos vocês também. Deixei minha vingança nublar minha razão, e por isso devo pedir desculpas.",
  ui_story_1022_10220601_22_dialog_content = "É só que... Sempre que eu penso na True Order, eu—!",
  ui_story_1022_10220601_23_dialog_content = "Ninguém está pedindo para você deixar seu rancor de lado imediatamente. Até mesmo os melhores de nós teriam dificuldade em fazer isso.",
  ui_story_1022_10220601_24_dialog_content = "Mas a vingança não pode custar a sua própria vida... É por isso que decidimos montar essa equipe e cuidar um do outro, certo?",
  ui_story_1022_10220601_25_dialog_content = "Eu...",
  ui_story_1022_10220601_26_dialog_content = "Agora, vamos nos mover. Estamos marchando juntos para a toca de Ursura!",
  ui_story_1022_10220601_27_dialog_content = "<color=#e8d9bb>Seguindo a orientação do Ressonador da Noite Branca, a equipe eventualmente descobre uma vasta extensão de terra preenchida com plantas coloridas e distorcidas.</color>",
  ui_story_1022_10220601_28_dialog_content = "Nossa, esse lugar...",
  ui_story_1022_10220601_29_dialog_content = "É tão bizarro, e ainda assim tão incrivelmente belo... Estou com um mau pressentimento sobre isso...",
  ui_story_1022_10220601_30_dialog_content = "Parece que estamos no caminho certo. Os subordinados de Pepita mencionaram algo sobre descobrir uma terra de corais.",
  ui_story_1022_10220601_31_dialog_content = "A influência de Ursura pode ser a fonte desta paisagem distorcida.",
  ui_story_1022_10220601_32_dialog_content = "... Agora classificando esta área como \"<color=#FFB400>Setor 44 Inexplorado</color>.\"",
  ui_story_1022_10220601_33_dialog_content = "Venha comigo, PlayerName. Há algo que eu gostaria de perguntar a você.",
  ui_story_1022_10220601_34_dialog_content = "O que é isso, Carleen?",
  ui_story_1022_10220601_35_dialog_content = "Você diz que pode sentir uma enorme bola de Lumina em algum lugar por aqui, sim?",
  ui_story_1022_10220601_36_dialog_content = "É possível que um dos nossos artefatos seja a fonte dessa Lumina?",
  ui_story_1022_10220601_37_dialog_content = "Huh? Q-Você quer dizer o que o Ressonador da Noite Branca está detectando?!",
  ui_story_1022_10220601_38_dialog_content = "Acho que não posso descartar completamente, mas algo me diz que não é esse o caso...",
  ui_story_1022_10220601_39_dialog_content = "Realmente não consigo explicar por que me sinto assim. Chame de instinto, mas há algo quente e familiar sobre aquela bola de Lumina...",
  ui_story_1022_10220601_40_dialog_content = "Entendo... Era tudo que eu precisava perguntar. Vamos voltar.",
  ui_story_1022_10220601_41_dialog_content = "Você está bem, Carleen? Parece que... Você está carregando algum tipo de fardo.",
  ui_story_1022_10220601_42_dialog_content = "Com certeza sou, considerando que faço parte da delegação de Lumópolis para a Zona Sombria...",
  ui_story_1022_10220601_43_dialog_content = "... Mas talvez eu esteja sendo muito impaciente. Depois de tudo que aconteceu, talvez eu só queira realizar algo.",
  ui_story_1022_10220601_44_dialog_content = "Em vez de se sentir como uma fera presa na escuridão.",
  ui_story_1022_10220601_45_dialog_content = "Mas você está certo, eu não deveria ter tanta pressa.",
  ui_story_1022_10220601_46_option_content = "Eu não disse nada ainda...",
  ui_story_1022_10220601_47_dialog_content = "Mas você ia, certo?!",
  ui_story_1022_10220601_48_dialog_content = "Er, s-sim! É claro!",
  ui_story_1022_10220601_49_option_content = "Está tudo bem se sentir assim.",
  ui_story_1022_10220601_50_dialog_content = "Eu entendo perfeitamente a sua inquietação... Porque eu sinto exatamente o mesmo.",
  ui_story_1022_10220601_51_dialog_content = "... Obrigado. Isso me conforta mais do que qualquer outra coisa que você poderia ter dito.",
  ui_story_1022_10220601_52_dialog_content = "Hum? Parece que algo está acontecendo ali. Vá!",
  ui_story_1022_10220601_53_dialog_content = "Meu mau pressentimento sobre este lugar só está ficando mais forte... Um deus do mal deve ter descido sobre este lugar...",
  ui_story_1022_10220601_54_dialog_content = "Corpos?! Espere, são esses... Aurorianos?!",
  ui_story_1022_10220601_55_dialog_content = "Eles não se parecem totalmente com eles... Mas também não se parecem com Eclipsitas. O que eles são?",
  ui_story_1022_10220601_56_dialog_content = "... Essas criaturas são semelhantes aos Aurorianos, pois há vestígios tênues de Lumina em seus corpos.",
  ui_story_1022_10220601_57_dialog_content = "No entanto, parece que o Lumina foi completamente drenado deles.",
  ui_story_1022_10220601_58_dialog_content = "Quem ou o que poderia fazer algo tão horrível?! Matá-los assim é...",
  ui_story_1022_10220601_59_dialog_content = "Também pensei assim, mas então dei uma olhada mais de perto.",
  ui_story_1022_10220601_60_dialog_content = "A causa da morte deles não foi ter o Lumina sugado. Na verdade, eles parecem ter vivido por um longo período de tempo neste estado.",
  ui_story_1022_10220601_61_dialog_content = "Mas como... Como os Aurorianos podem sobreviver sem o seu Lumina?",
  ui_story_1022_10220601_62_dialog_content = "Cadáveres aurorianos desprovidos de Lúmina, e um artefato roubado de Lumópolis...",
  ui_story_1022_10220601_63_dialog_content = "... Exploda esses Eclipsitas imundos! Como ousam corromper nossa espécie assim?!",
  ui_story_1022_10220601_64_dialog_content = "Já ocorreu a você que talvez vocês Aurorians sejam os que têm roubado do Eclipse todo esse tempo?",
  ui_story_1022_10220601_65_dialog_content = "Como os lugares que você chama de casa...",
  ui_story_1022_10220601_66_dialog_content = "!!",
  ui_story_1022_10220601_67_dialog_content = "O que foi, PlayerName?",
  ui_story_1022_10220601_68_dialog_content = "... Não é nada.",
  ui_story_1022_10220601_69_dialog_content = "(Estou imaginando coisas, ou ouvi uma voz fraca chamando agora mesmo...?)",
  ui_story_1022_10220701_1_dialog_content = "Todos essas pessoas morreram ao mesmo tempo.",
  ui_story_1022_10220701_2_dialog_content = "Há também estranhos fragmentos de metal espalhados entre os corais... O que exatamente aconteceu aqui?",
  ui_story_1022_10220701_3_dialog_content = "Eu poderia ser capaz de responder isso.",
  ui_story_1022_10220701_4_dialog_content = "... Estamos contando com você.",
  ui_story_1022_10220701_5_dialog_content = "Apenas não se esforce demais, PlayerName.",
  ui_story_1022_10220701_6_option_content = "Varredura Psíquica",
  ui_story_1022_10220701_7_dialog_content = "Huh?! O que... É isso...?",
  ui_story_1022_10220701_8_dialog_content = "<color=#e8d9bb>O rugido ensurdecedor de maquinaria pesada enche o ar.</color>",
  ui_story_1022_10220701_9_dialog_content = "<color=#e8d9bb>A terra treme ao rastro do movimento deles.</color>",
  ui_story_1022_10220701_10_dialog_content = "<color=#e8d9bb>Inúmeras máquinas estranhas voam pelos céus, intercaladas com belos e retorcidos corais e plantas.</color>",
  ui_story_1022_10220701_11_dialog_content = "<color=#e8d9bb>Uma cena muito mais surpreendente comparada ao tranquilo campo de corais visto anteriormente.</color>",
  ui_story_1022_10220701_12_dialog_content = "(Os fragmentos de metal Hiiro encontrados devem ter vindo dessas máquinas.)",
  ui_story_1022_10220701_13_dialog_content = "(Estou olhando para... O campo de corais <color=#FFB400>no passado</color>?)",
  ui_story_1022_10220701_14_dialog_content = "(Ah! Os que estão pilotando essas máquinas são os seres semelhantes aos Aurorianos que vimos antes! Eles estiveram vivendo aqui todo esse tempo?)",
  ui_story_1022_10220701_15_dialog_content = "<color=#e8d9bb>A serenidade dessas terras só pode ser apreciada na presença de criaturas vivas.</color>",
  ui_story_1022_10220701_16_dialog_content = "<color=#e8d9bb>Além do zumbido interminável de suas máquinas, o campo de corais está completamente silencioso.</color>",
  ui_story_1022_10220701_17_dialog_content = "(Não há comunicação entre eles, e suas ações e expressões são tão rígidas. É como se estivessem apenas passando pelas moções de seu trabalho.)",
  ui_story_1022_10220701_18_dialog_content = "(Eles me lembram de Eclipsitas de baixo nível... Então, por que eles se parecem mais com Aurorianos por fora?)",
  ui_story_1022_10220701_19_dialog_content = "Heheh... Depois de todos esses anos, parece que somos os únicos ainda capazes de falar.",
  ui_story_1022_10220701_20_dialog_content = "(Ah! Caramba... Eu não esperava ouvir nenhum deles falar!)",
  ui_story_1022_10220701_21_dialog_content = "Desde que nasci, este lugar não mudou. Além das máquinas, as únicas outras coisas aqui são essas cascas vazias e silenciosas de pessoas...",
  ui_story_1022_10220701_22_dialog_content = "Mal consigo distinguir um do outro agora.",
  ui_story_1022_10220701_23_dialog_content = "Mas por que estamos amaldiçoados a viver assim?",
  ui_story_1022_10220701_24_dialog_content = "Por que não podemos deixar esta terra da morte e ver o mundo exterior?",
  ui_story_1022_10220701_25_dialog_content = "É impossível!",
  ui_story_1022_10220701_26_dialog_content = "Quando eu era jovem, conheci algumas pessoas como nós que tentaram escapar...",
  ui_story_1022_10220701_27_dialog_content = "Então, o que aconteceu? Você já os viu novamente?",
  ui_story_1022_10220701_28_dialog_content = "Não. Eles morreram... Todos eles.",
  ui_story_1022_10220701_29_dialog_content = "?!",
  ui_story_1022_10220701_30_dialog_content = "Há um lugar fora de onde vivemos. É como um forno escaldante, e queimou cada um deles até virarem cinzas.",
  ui_story_1022_10220701_31_dialog_content = "Ninguém nunca tentou sair desde então. Até mesmo aqueles que se afastam um pouco demais deste lugar nunca mais são vistos.",
  ui_story_1022_10220701_32_dialog_content = "Mas por quê...? Realmente não há esperança para nós? Estamos realmente destinados a morrer aqui?",
  ui_story_1022_10220701_33_dialog_content = "Que destino cruel...",
  ui_story_1022_10220701_34_dialog_content = "?!",
  ui_story_1022_10220701_35_dialog_content = "(Ah! Th-Eles estão olhando direto para mim!)",
  ui_story_1022_10220701_36_dialog_content = "O-Olá...?",
  ui_story_1022_10220701_37_dialog_content = "Um forasteiro? Ah, estou tão ciumento.",
  ui_story_1022_10220701_38_dialog_content = "O que te traz a este lugar condenado? Não há nada aqui, exceto máquinas e corais.",
  ui_story_1022_10220701_39_dialog_content = "Ah, e seja lá o que você fizer, não coma o coral. Ele transformará seu sangue em uma cor branca leitosa e desagradável.",
  ui_story_1022_10220701_40_dialog_content = "Assim como as nossas.",
  ui_story_1022_10220701_41_dialog_content = "<color=#e8d9bb>A criatura semelhante a um Auroriano dá um sorriso autodepreciativo.</color>",
  ui_story_1022_10220701_42_dialog_content = "Comer o coral fará meu sangue ficar branco? Entendi... Obrigado pelo aviso.",
  ui_story_1022_10220701_43_dialog_content = "Mas não há mais nada para comer aqui fora?",
  ui_story_1022_10220701_44_dialog_content = "De maneira nenhuma. Apenas coral, coral e mais maldito coral...",
  ui_story_1022_10220701_45_dialog_content = "Este lugar é amaldiçoado, eu te digo. Todos os dias, novos corais e líquens aparecem.",
  ui_story_1022_10220701_46_dialog_content = "As máquinas não podem continuar funcionando corretamente se não as limparmos a tempo.",
  ui_story_1022_10220701_47_dialog_content = "Especialmente essa fornalha. Não importa o que aconteça, não podemos deixá-la parar.",
  ui_story_1022_10220701_48_dialog_content = "Passar nossas vidas trabalhando duro nas ervas daninhas, mantendo uma fornalha viva sem um pingo de dignidade... Nós também devemos estar amaldiçoados.",
  ui_story_1022_10220701_49_dialog_content = "... Além de mim, alguém mais passou por aqui? Tipo... Um Eclipsite?",
  ui_story_1022_10220701_50_dialog_content = "Um fantasma aparece de vez em quando, certo?",
  ui_story_1022_10220701_51_dialog_content = "Isso mesmo. O nome dele é Yodu.",
  ui_story_1022_10220701_52_dialog_content = "Um fantasma?!",
  ui_story_1022_10220701_53_dialog_content = "Ele é o único que vai nos matar.",
  ui_story_1022_10220701_54_dialog_content = "Ele é o único que vai nos matar.",
  ui_story_1022_10220701_55_dialog_content = "Ele é o único que vai nos matar.",
  ui_story_1022_10220701_56_dialog_content = "?!",
  ui_story_1022_10220701_57_dialog_content = "Um dia, quando ele achar que não somos mais úteis para ele, ele vai matar todos nós, um por um.",
  ui_story_1022_10220701_58_dialog_content = "Mas, depois de estarmos presos aqui por toda a nossa vida, podemos muito bem ter morrido há muito tempo.",
  ui_story_1022_10220701_59_dialog_content = "Presos aqui por toda a nossa vida.",
  ui_story_1022_10220701_60_dialog_content = "Presos aqui por toda a nossa vida.",
  ui_story_1022_10220701_61_dialog_content = "...!!!",
  ui_story_1022_10220701_62_dialog_content = "Qual o problema, PlayerName? Você ficou completamente pálido.",
  ui_story_1022_10220701_63_dialog_content = "Eu... Eu acabei de sentir os pensamentos remanescentes das pessoas que morreram aqui.",
  ui_story_1022_10220701_64_dialog_content = "...",
  ui_story_1022_10220701_65_dialog_content = "Mesmo até hoje, suas almas ainda estão presas aqui? May eles encontram a paz algum dia.",
  ui_story_1022_10220701_66_dialog_content = "Então um fantasma chamado Yodu foi responsável por suas mortes? Imperdoável...",
  ui_story_1022_10220701_67_dialog_content = "Isso mesmo, e o poder de Ursura não é nada comparado ao dele.",
  ui_story_1022_10220701_68_dialog_content = "Essa é uma maneira perigosa de pensar. Todos os Wraiths devem ser tratados como ameaças altamente perigosas, você sabe disso.",
  ui_story_1022_10220701_69_dialog_content = "S-Desculpe!",
  ui_story_1022_10220701_70_dialog_content = "Não seja. Eu só quero que você fique alerta quando a situação exigir.",
  ui_story_1022_10220701_71_dialog_content = "Pelo que você viu em suas visões, é seguro assumir que isso era uma base de pesquisa no passado—",
  ui_story_1022_10220701_72_dialog_content = "Os trabalhadores eram essas criaturas semelhantes aos Aurorianos, e seu supervisor era Yodu, o fantasma.",
  ui_story_1022_10220701_73_dialog_content = "Sim... Eu estava pensando na mesma linha.",
  ui_story_1022_10220701_74_dialog_content = "Com exceção de algumas pessoas, os trabalhadores estavam completamente desprovidos de pensamento, emoção e até mesmo de fala.",
  ui_story_1022_10220701_75_dialog_content = "A principal tarefa deles era manter as máquinas funcionando, limpando corais, musgos e outros crescimentos biológicos.",
  ui_story_1022_10220701_76_dialog_content = "E aparentemente, a máquina mais importante era uma espécie de forno.",
  ui_story_1022_10220701_77_dialog_content = "Mas por que coisas como corais e musgos continuam crescendo aqui? Poderia ter algo a ver com Ursura?",
  ui_story_1022_10220701_78_dialog_content = "É possível que essas coisas cresçam onde quer que Ursura vá.",
  ui_story_1022_10220701_79_dialog_content = "Se isso for verdade, então ela deve ter estado perto da base de pesquisa naquela época também. Ela pode até estar conectada ao Yodu de alguma forma.",
  ui_story_1022_10220701_80_dialog_content = "O que é ainda mais motivo para vê-la como uma séria ameaça...",
  ui_story_1022_10220701_81_dialog_content = "E ainda assim, ela e Pepita de alguma forma se tornaram amigos firmes. Certamente ela não a machucaria por causa disso...",
  ui_story_1022_10220701_82_dialog_content = "... Neste ponto, não tenho certeza se Pepita descobrir este lugar foi uma coisa boa ou não.",
  ui_story_1022_10220701_83_dialog_content = "Perdão, mas posso intervir?",
  ui_story_1022_10220701_84_dialog_content = "O que foi?",
  ui_story_1022_10220701_85_dialog_content = "Caso alguém não tenha notado, o Darkflow aqui está incomumente escasso. É como se nem estivéssemos na Dark Zone.",
  ui_story_1022_10220701_86_dialog_content = "Será que o artefato detectado pelo Ressonador da Noite Branca... Está afastando o darkflow circundante muito parecido com nossas <color=#FFB400>Pedras Lumina</color>?",
  ui_story_1022_10220701_87_dialog_content = "Você está certo...! Mas não saberemos a menos que continuemos procurando.",
  ui_story_1022_10220701_88_dialog_content = "Ursura não pode estar muito longe de nós agora. Mantenha a guarda.",
  ui_story_1022_10220800_1_dialog_content = "<color=#e8d9bb>No interior da floresta de corais, Pepita está perdida em pensamentos enquanto observa a paisagem retorcida.</color>",
  ui_story_1022_10220800_2_dialog_content = "Então, você pensou sobre o que eu disse, Pepita?",
  ui_story_1022_10220800_3_dialog_content = "... Ah, você voltou. O que está acontecendo lá fora?",
  ui_story_1022_10220800_4_dialog_content = "Nada para se preocupar, apenas um par de formigas irritantes. A poderosa Ursura tem coisas melhores para fazer do que perder tempo com elas.",
  ui_story_1022_10220800_5_dialog_content = "Você, por outro lado, me deve uma resposta.",
  ui_story_1022_10220800_6_dialog_content = "Apenas acene com a cabeça, e eu usarei o coral para fazer um coração novinho para você.",
  ui_story_1022_10220800_7_dialog_content = "E em troca... Eu tenho que ficar aqui e brincar com você para sempre?",
  ui_story_1022_10220800_8_dialog_content = "Você não estaria jogando \"com\"igo, estaríamos jogando \"juntos\"! Você também quer isso, não quer? Afinal, nos divertimos mais quando estamos juntos!",
  ui_story_1022_10220800_9_dialog_content = "Você está certo. Estar aqui fora é muito divertido, e é raro para mim encontrar alguém tão louco quanto eu.",
  ui_story_1022_10220800_10_dialog_content = "Exatamente! Então é só dizer a palavra, e eu vou começar no seu novo coração!",
  ui_story_1022_10220800_11_dialog_content = "Uma vez que eu faça isso, seu sangue mudará daquele tom vermelho repugnante para um branco puro e nobre como o meu. Então você pode ficar aqui para sempre!",
  ui_story_1022_10220800_12_dialog_content = "... Ursura.",
  ui_story_1022_10220800_13_dialog_content = "Sim?!",
  ui_story_1022_10220800_14_dialog_content = "Você se lembra do que aconteceu quando nos conhecemos pela primeira vez, certo?",
  ui_story_1022_10220800_15_dialog_content = "... Huh? Por que você está revivendo o passado de repente?",
  ui_story_1022_10220800_16_dialog_content = "...",
  ui_story_1022_10220800_17_dialog_content = "(O que... O que está acontecendo? Onde estou...?)",
  ui_story_1022_10220800_18_dialog_content = "Graaaa!!",
  ui_story_1022_10220800_19_dialog_content = "*suspirando* Hahaha... Isso é tudo que consegue? Pode vir!",
  ui_story_1022_10220800_20_dialog_content = "Graaah!",
  ui_story_1022_10220800_21_dialog_content = "Urgh! Meu coração está doendo de novo... Droga... Coração falso e estúpido!",
  ui_story_1022_10220800_22_dialog_content = "(Se ao menos eu tivesse um coração real e saudável... Nada disso estaria acontecendo...)",
  ui_story_1022_10220800_23_dialog_content = "(Lembro-me agora. Eu vim para explorar a Dark Zone com a True Order, mas me afastei por conta própria e fui emboscado por um bando de Eclipsitas.)",
  ui_story_1022_10220800_24_dialog_content = "(E graças ao meu coração estúpido e defeituoso, eu não era forte o suficiente para evitar ser capturado...)",
  ui_story_1022_10220800_25_dialog_content = "(Morrer porque brinquei demais uma vez... Isso é bem a minha cara, né? Heh... Heheh...)",
  ui_story_1022_10220800_26_dialog_content = "... Hahahaha!",
  ui_story_1022_10220800_27_dialog_content = "O que está acontecendo? Acordei do meu longo, longo sono pensando que havia um Aurorian por perto.",
  ui_story_1022_10220800_28_dialog_content = "Mas em vez disso, encontro algum maníaco rindo histericamente no chão.",
  ui_story_1022_10220800_29_dialog_content = "Quem tá aí?!",
  ui_story_1022_10220800_30_dialog_content = "Mas tudo bem, vá tão louco quanto quiser. Afinal, seu coração e sangue—",
  ui_story_1022_10220800_31_dialog_content = "<color=#FFB400>Pertence a mim agora!</color>",
  ui_story_1022_10220800_32_dialog_content = "<color=#e8d9bb>Uma Eclipsita parecida com uma garotinha sorri diabolicamente, revelando seus dentes afiados.</color>",
  ui_story_1022_10220800_33_dialog_content = "<color=#e8d9bb>Um calafrio percorre a espinha de Pepita ao ver o sorriso cruel da garotinha.</color>",
  ui_story_1022_10220800_34_dialog_content = "Haha...",
  ui_story_1022_10220800_35_dialog_content = "Você ainda está rindo?! O que tem de tão engraçado nisso tudo, hein? Você não sabe que está prestes a se tornar a próxima refeição do grande Ursura?!",
  ui_story_1022_10220800_36_dialog_content = "Desculpe, eu apenas acho engraçado que uma garotinha com presas de demônio acha que eu sou o louco aqui.",
  ui_story_1022_10220800_37_dialog_content = "O-O que você saberia?! Meus caninos são um símbolo do meu nascimento nobre, muito obrigado!",
  ui_story_1022_10220800_38_dialog_content = "Nascimento nobre? Parece bem legal, mas isso não te torna apenas um monstro queijo e sugador de sangue?",
  ui_story_1022_10220800_39_dialog_content = "Quando eu terminar de drenar a vida de você, vai parecer couro barato!",
  ui_story_1022_10220800_40_dialog_content = "Hahaha! Cara, isso é simplesmente louco demais!",
  ui_story_1022_10220800_41_dialog_content = "Geralmente as pessoas não conseguem parar de me comprar comida e bebidas onde quer que eu vá. Esse é o tipo de respeito que eu exijo no mundo!",
  ui_story_1022_10220800_42_dialog_content = "Mas essa é a primeira vez que alguém se oferece para sugar meu sangue! Você tem um jeito engraçado de mostrar sua admiração, sabia disso?",
  ui_story_1022_10220800_43_dialog_content = "\"Admiração,\" meu bumbum! A única pessoa que eu admiro é o meu avô, entendeu?!",
  ui_story_1022_10220800_44_dialog_content = "Vou beber até a última gota do seu sangue e transformá-lo em meu eterno escravo! Veremos quem vai rir depois disso, seu idiota!",
  ui_story_1022_10220800_45_dialog_content = "Thrall...?",
  ui_story_1022_10220800_46_dialog_content = "Hmph, finalmente te assustei, hein? Bom! Você vai ter um gosto ainda melhor quando estiver implorando por misericórdia.",
  ui_story_1022_10220800_47_dialog_content = "É... Não, obrigado.",
  ui_story_1022_10220800_48_dialog_content = "O quê?! Q-Quando você pegou isso de mim? Devolva!",
  ui_story_1022_10220800_49_dialog_content = "Mate-me se quiser, mas eu não vou deixar você me transformar em seu escravo.",
  ui_story_1022_10220800_50_dialog_content = "<color=#FFB400>Se eu não sou livre, prefiro estar morto!</color>",
  ui_story_1022_10220800_51_dialog_content = "<color=#e8d9bb>Pepita pega um pedaço de coral afiado e o enfia em seu próprio peito, esguichando sangue vermelho brilhante ao seu redor.</color>",
  ui_story_1022_10220800_52_dialog_content = "...!",
  ui_story_1022_10220800_53_dialog_content = "Urgh... Sangue... Nojento, sangue vermelho... Ahhhhhh—!!!",
  ui_story_1022_10220800_54_dialog_content = "Graaaa!!",
  ui_story_1022_10220800_55_dialog_content = "Salve-nos!",
  ui_story_1022_10220800_56_dialog_content = "Por favor, poupe-nos, Senhora Ursura! Poupe nossas vidas miseráveis!!",
  ui_story_1022_10220800_57_dialog_content = "Eu... Eu odeio ver sangue! Certifique-se de que eles não sangrem quando você estiver matando eles, seus idiotas!",
  ui_story_1022_10220800_58_dialog_content = "(Eclipsiano) Entendido!",
  ui_story_1022_10220800_59_dialog_content = "Aaaaaaahhh!!!",
  ui_story_1022_10220800_60_dialog_content = "Urk! D-Não te disse para não deixá-los sangrar? Vocês são meus novos amigos, então prestem atenção quando eu falar coisas assim!",
  ui_story_1022_10220800_61_dialog_content = "(Eclipsiano) Sim, Senhora Ursura! Faremos o nosso melhor...",
  ui_story_1022_10220800_62_dialog_content = "Tch, vocês são só conversa...",
  ui_story_1022_10220800_63_dialog_content = "Tenho que permanecer forte... Meu novo deus é ainda maior que o chamado Senhor da Verdade...",
  ui_story_1022_10220800_64_dialog_content = "Desça ao nosso mundo e purifique-o, meu senhor!",
  ui_story_1022_10220800_65_dialog_content = "Nngh... Devo ter dormido demais... Quase esqueci...",
  ui_story_1022_10220800_66_dialog_content = "Já fui abençoado com um anel do Eclipse. Não preciso mais beber sangue, é por isso que não suporto nem a visão dele agora!",
  ui_story_1022_10220800_67_dialog_content = "*soluçando* Beber, banhar-se nisso... Nada disso me faz feliz mais! Avô!",
  ui_story_1022_10220800_68_dialog_content = "(Ela começou a chorar histericamente de repente... Ela parece tão triste, chamando pelo avô dela assim.)",
  ui_story_1022_10220800_69_dialog_content = "(Que tipo de cara deixaria ela sozinha aqui? Provavelmente alguém como meu inútil pretexto de pai.)",
  ui_story_1022_10220800_70_dialog_content = "E-Ei, você está bem? Tosse, tosse... Ah certo, eu sou o único com um problema aqui... Heheh.",
  ui_story_1022_10220800_71_dialog_content = "Claro que estou bem! Por que eu não estaria?!",
  ui_story_1022_10220800_72_dialog_content = "Urgh! O-O que você está tentando fazer comigo agora...?",
  ui_story_1022_10220800_73_dialog_content = "D-Não pense que pode me parar sangrando por todo o lugar! E-Eu consigo ver e beber sangue muito bem!",
  ui_story_1022_10220800_74_dialog_content = "Ei! Pare de lamber minha ferida assim, seu monstro...!",
  ui_story_1022_10220800_75_dialog_content = "Ah... Que nojo...",
  ui_story_1022_10220800_76_dialog_content = "<color=#e8d9bb>Uma lágrima branca como leite aparece no canto do olho de Ursura.</color>",
  ui_story_1022_10220800_77_dialog_content = "Se é tão nojento, então simplesmente pare com isso já-",
  ui_story_1022_10220800_78_dialog_content = "Nngh... Arrrgh— Gaaaaahhhh!",
  ui_story_1022_10220800_79_dialog_content = "<color=#e8d9bb>De repente, como se tocada por algum tipo de poder primordial, Ursura começa a gritar e convulsionar enquanto mais lágrimas brancas fluem de seus olhos.</color>",
  ui_story_1022_10220800_80_dialog_content = "I-É tão ruim assim?!",
  ui_story_1022_10220800_81_dialog_content = "Graaaaagh!",
  ui_story_1022_10220800_82_dialog_content = "(E-ela está perdendo o controle! Eu tenho que sair daqui, mas... Droga, eu perdi muito sangue!)",
  ui_story_1022_10220800_83_dialog_content = "P... Petey... Hora de fazer a sua coisa!",
  ui_story_1022_10220800_84_dialog_content = "Uma boneca? Urgh...",
  ui_story_1022_10220800_85_dialog_content = "<color=#e8d9bb>Apesar de seu corpo inteiro tremer violentamente, Ursura consegue invocar uma pequena boneca cinza para arrastá-la para longe.</color>",
  ui_story_1022_10220800_86_dialog_content = "<color=#e8d9bb>Estrondo!! À medida que as lágrimas brancas caem no chão onde Pepita está deitado, elas explodem com uma força destrutiva surpreendente.</color>",
  ui_story_1022_10220800_87_dialog_content = "(Ela está... Me salvando?)",
  ui_story_1022_10220800_88_dialog_content = "(O que está acontecendo com ela de qualquer maneira? Essas explosões não vão machucá-la também? Droga... Não consigo mais abrir meus olhos. Eu definitivamente exagerei comigo mesmo.)",
  ui_story_1022_10220800_89_dialog_content = "(Hoje é... O dia que finalmente morro?)",
  ui_story_1022_10220800_90_dialog_content = "<color=#e8d9bb>Depois de muito tempo...</color>",
  ui_story_1022_10220800_91_dialog_content = "...",
  ui_story_1022_10220800_92_dialog_content = "(Eu ainda estou vivo, hein? Acho que não deveria estar surpreso...)",
  ui_story_1022_10220800_93_dialog_content = "O que há com esse seu coração?",
  ui_story_1022_10220800_94_dialog_content = "Ursura...",
  ui_story_1022_10220800_95_dialog_content = "Não é o seu coração original. É tecnologia da Illumina?",
  ui_story_1022_10220800_96_dialog_content = "... Por que você me salvou?",
  ui_story_1022_10220800_97_dialog_content = "Quando me tornei parte do Eclipse, pensei que finalmente teria amigos que nunca me decepcionariam.",
  ui_story_1022_10220800_98_dialog_content = "Mas todos eles se revelaram um bando de vermes inúteis. Uma nobre senhora como eu merece muito melhor.",
  ui_story_1022_10220800_99_dialog_content = "Mas você... Você está bem.",
  ui_story_1022_10220800_100_dialog_content = "<size=30>Você até se importa comigo.</size>",
  ui_story_1022_10220800_101_dialog_content = "Haha...",
  ui_story_1022_10220800_102_dialog_content = "Para de rir!",
  ui_story_1022_10220800_103_dialog_content = "Então o que, você está me reconhecendo ou algo assim?",
  ui_story_1022_10220800_104_dialog_content = "E qual é o problema com isso? Você deveria se sentir honrado, sabe! A maioria das pessoas estaria dançando e gritando a plenos pulmões por algo assim!",
  ui_story_1022_10220800_105_dialog_content = "Não importa quão bom coração a Illumina faça em você, porque você sempre estará sob o controle deles.",
  ui_story_1022_10220800_106_dialog_content = "Mas eu posso fazer um coração novinho para você, um que você pode chamar de seu próprio!",
  ui_story_1022_10220800_107_dialog_content = "Você se lembra de como eu respondi a você naquela época?",
  ui_story_1022_10220800_108_dialog_content = "Claro! Você disse, \"Não, obrigado, ainda quero aguentar isso um pouco mais.\"",
  ui_story_1022_10220800_109_dialog_content = "E, no entanto, aqui está você ao meu lado mais uma vez! Engraçado como isso funciona, hein?",
  ui_story_1022_10220800_110_dialog_content = "Você nunca conseguirá o que quer confiando neste coração, Pepita.",
  ui_story_1022_10220800_111_dialog_content = "Claro que não! Eu sei em primeira mão o quão ruim é esse coração falso.",
  ui_story_1022_10220800_112_dialog_content = "<color=#e8d9bb>Eu amaldiçoei este coração tantas vezes, e desejei que eu pudesse ter um perfeito em vez disso.</color>",
  ui_story_1022_10220800_113_dialog_content = "<color=#e8d9bb>Um coração forte e saudável que ninguém poderia controlar. Um que me permitiria lutar pelo tempo que eu quisesse sem nunca me cansar. Esse é o tipo de coração que eu sempre quis.</color>",
  ui_story_1022_10220800_114_dialog_content = "<color=#e8d9bb>É por isso que ainda vim aqui, mesmo sabendo que Ursura imporia algum tipo de condição.</color>",
  ui_story_1022_10220800_115_dialog_content = "<color=#e8d9bb>Porque, ao contrário de Belisaria, que sempre me despreza, pelo menos Ursura me trata como igual.</color>",
  ui_story_1022_10220800_116_dialog_content = "<color=#e8d9bb>Quanto à condição dela—</color>",
  ui_story_1022_10220800_117_dialog_content = "<color=#FFB400>\"Ficar aqui para sempre.\"</color>",
  ui_story_1022_10220800_118_dialog_content = "<color=#e8d9bb>Assim que ouvi ela dizer, meu humor mudou completamente. Enquanto olhava para a paisagem congelada e os corais retorcidos que cresciam dela, o mesmo pensamento se repetia na minha cabeça.</color>",
  ui_story_1022_10220800_119_dialog_content = "<color=#e8d9bb>\"Isso é realmente o que será o resto da minha vida?\"</color>",
  ui_story_1022_10220800_120_dialog_content = "<color=#e8d9bb>... Não.</color>",
  ui_story_1022_10220800_121_dialog_content = "<color=#e8d9bb>O mundo é um lugar tão enorme.</color>",
  ui_story_1022_10220800_122_dialog_content = "<color=#e8d9bb>E eu ainda não tive a chance de ver meus campos verdes.</color>",
  ui_story_1022_10220800_123_dialog_content = "A minha resposta é a mesma de antes.",
  ui_story_1022_10220800_124_dialog_content = "Obrigado, mas não obrigado, Ursura.",
  ui_story_1022_10220800_125_dialog_content = "Ainda quero aguentar isso um pouco mais.",
  ui_story_1022_10220901_1_dialog_content = "Você me enganou!",
  ui_story_1022_10220901_2_dialog_content = "Eu sei, e sinto muito mesmo! Mas ainda nos divertimos muito juntos, certo?",
  ui_story_1022_10220901_3_dialog_content = "Mas é melhor se não estivermos juntos todos os dias de nossas vidas, não acha? Afinal, dizem que uma pequena distância torna as amizades ainda mais preciosas!",
  ui_story_1022_10220901_4_dialog_content = "...",
  ui_story_1022_10220901_5_dialog_content = "Busque-o.",
  ui_story_1022_10220901_6_dialog_content = "(Eclipsiano) Entendido!",
  ui_story_1022_10220901_7_dialog_content = "Hã? Buscar quem? Não é como se eu tivesse parentes para você sequestrar, lembra?",
  ui_story_1022_10220901_8_dialog_content = "... Petey?! Ursura... Quando você o levou de volta?",
  ui_story_1022_10220901_9_dialog_content = "Há um tempo atrás, na verdade. Eu só não queria te mostrar porque me importo muito com você.",
  ui_story_1022_10220901_10_dialog_content = "Mas mesmo sendo um bom amigo... Você continua tentando me deixar! Por quê?!?",
  ui_story_1022_10220901_11_dialog_content = "... Eu já te disse o porquê, não disse?",
  ui_story_1022_10220901_12_dialog_content = "<color=#FFB400>Se eu não sou livre... Eu preferiria estar morto!</color>",
  ui_story_1022_10220901_13_dialog_content = "Graaah...",
  ui_story_1022_10220901_14_dialog_content = "Pare ela!",
  ui_story_1022_10220901_15_dialog_content = "(Eclipsiano) Faça como a Senhora Ursura ordena!",
  ui_story_1022_10220901_16_dialog_content = "Graaaa!!",
  ui_story_1022_10220901_17_dialog_content = "Isso é tudo que consegue?",
  ui_story_1022_10220901_18_dialog_content = "Graaah...",
  ui_story_1022_10220901_19_dialog_content = "O-O quê?! O que você pensa que está fazendo?! Você vai morrer nesse ritmo!",
  ui_story_1022_10220901_20_dialog_content = "Então chame seus Eclipsitas para trás e me deixe ir!",
  ui_story_1022_10220901_21_dialog_content = "Graah...",
  ui_story_1022_10220901_22_dialog_content = "Urgh... Heheh, odeio te dizer isso Ursura, mas você vai precisar de lacaios mais fortes se quiser me parar.",
  ui_story_1022_10220901_23_dialog_content = "Desculpe, não posso ficar! Tchau-tchau!",
  ui_story_1022_10220901_24_dialog_content = "Não se atreva!",
  ui_story_1022_10220901_25_dialog_content = "Nngh...",
  ui_story_1022_10220901_26_dialog_content = "Seu coração está te machucando de novo, não está? Esse pedaço de lixo não é forte o suficiente para acompanhar você.",
  ui_story_1022_10220901_27_dialog_content = "Você já deveria conhecer seus limites agora!",
  ui_story_1022_10220901_28_dialog_content = "Sim, certo!",
  ui_story_1022_10220901_29_dialog_content = "Aff...!",
  ui_story_1022_10220901_30_dialog_content = "Peguem ela, todos vocês!",
  ui_story_1022_10220901_31_dialog_content = "... Fique fora do meu caminho!",
  ui_story_1022_10220901_32_dialog_content = "Você enlouqueceu?! Seu coração vai explodir se você continuar lutando assim!",
  ui_story_1022_10220901_33_dialog_content = "Você vai se esgotar antes mesmo de eu começar a levar essa batalha a sério!",
  ui_story_1022_10220901_34_dialog_content = "Isso... Tudo bem para mim!",
  ui_story_1022_10220901_35_dialog_content = "Estou... Estou sangrando?",
  ui_story_1022_10220901_36_dialog_content = "Maldito seja... Como ousa me fazer sangrar! Chega! Se você quer tanto morrer, então deixe-me te ajudar!!!",
  ui_story_1022_10220901_37_dialog_content = "Arrrgh—!",
  ui_story_1022_10220901_38_dialog_content = "<color=#e8d9bb>Tum-tum, tum-tum, tum-tum, tum-tum—</color>",
  ui_story_1022_10220901_39_dialog_content = "<color=#e8d9bb>A batida dentro de seu peito se torna ainda mais selvagem e intensa.</color>",
  ui_story_1022_10220901_40_dialog_content = "<color=#e8d9bb>O coração dela não está apenas batendo, mas também está retumbando furiosamente como um trem à beira de descarrilar.</color>",
  ui_story_1022_10220901_41_dialog_content = "<color=#e8d9bb>Cada onda de dor insuportável é suficiente para despedaçar a mente de qualquer um.</color>",
  ui_story_1022_10220901_42_dialog_content = "<color=#e8d9bb>Mas ela não percebe mais a dor, ou qualquer outra coisa, aliás.</color>",
  ui_story_1022_10220901_43_dialog_content = "<color=#e8d9bb>A clareza de sua mente permite que ela se concentre totalmente em um único pensamento.</color>",
  ui_story_1022_10220901_44_dialog_content = "Enquanto eu queimar o mais brilhantemente possível... Então, qual o problema em morrer?",
  ui_story_1022_10220901_45_dialog_content = "Não sou animal de estimação de ninguém e nunca me renderei a ninguém...",
  ui_story_1022_10220901_46_dialog_content = "<color=#FFB400>Eu... Pertenço a mim mesmo!</color>",
  ui_story_1022_10220902_1_dialog_content = "O Ressonador da Noite Branca está respondendo cada vez mais intensamente. O artefato roubado deve estar por perto.",
  ui_story_1022_10220902_2_dialog_content = "Hã...",
  ui_story_1022_10220902_3_dialog_content = "Está ainda mais forte agora! Nosso alvo pode ser um objeto pequeno, então se espalhem e procurem na área!",
  ui_story_1022_10220902_4_dialog_content = "Às vezes, as respostas que procuramos estão escondidas bem diante de nossos olhos...",
  ui_story_1022_10220902_5_dialog_content = "Agora não é hora para enigmas, Erica. Apenas concentre-se em encontrar o artefato desaparecido.",
  ui_story_1022_10220902_6_dialog_content = "Não era um enigma, minha senhora. Eu estava falando sobre aquela massa de luz sagrada à sua frente...",
  ui_story_1022_10220902_7_dialog_content = "O quê?!",
  ui_story_1022_10220902_8_dialog_content = "Pfft...",
  ui_story_1022_10220902_9_dialog_content = "Pare de rir! Você também não notou, notou?",
  ui_story_1022_10220902_10_dialog_content = "É-É porque eu estava muito ocupado observando o Ressonador... Mas isso não é importante agora! Precisamos confirmar se esse é ou não o artefato perdido de Lumópolis.",
  ui_story_1022_10220902_11_dialog_content = "A Lúmina que está emitindo é tão pura e calmante...",
  ui_story_1022_10220902_12_dialog_content = "Encontramos?!",
  ui_story_1022_10220902_13_dialog_content = "Não há como negar. Este objeto está dissipando o Fluxo Escuro na área ao redor.",
  ui_story_1022_10220902_14_dialog_content = "Em outras palavras, é realmente uma das relíquias sagradas e há muito perdidas da Verdadeira Ordem.",
  ui_story_1022_10220902_15_dialog_content = "Essa voz...",
  ui_story_1022_10220902_16_dialog_content = "Hoje, este objeto sagrado retorna aos seus legítimos proprietários, e todas as coisas voltam aos seus caminhos originais. Tal é o mistério da obra de nosso senhor.",
  ui_story_1022_10220902_17_dialog_content = "Quem você pensa que é?! Solte o tesouro sagrado de Lumópolis imediatamente!",
  ui_story_1022_10220902_18_dialog_content = "Não se precipite, Victoria. Ainda temos muito a discutir, como o paradeiro do nosso texto sagrado!",
  ui_story_1022_10220902_19_dialog_content = "Victoria...? O-O líder da herética Verdadeira Ordem...?!",
  ui_story_1022_10220902_20_dialog_content = "\"Herético\", você diz? Heheheh... Suponho que nossa nobre busca pela Verdade possa ser vista assim pelas mentes ignorantes do mundo.",
  ui_story_1022_10220902_21_dialog_content = "Quanto a este artefato, nunca peguei nada que não me pertencesse primeiro. Este objeto foi roubado da cidade de Varaki pelo mestre deste domínio.",
  ui_story_1022_10220902_22_dialog_content = "As pistas que me levaram a este lugar foram dadas por ninguém menos que Pepita, um membro do nosso ordem.",
  ui_story_1022_10220902_23_dialog_content = "O que há nas minhas ações que você acha tão irracional, Senhora Carleen?",
  ui_story_1022_10220902_24_dialog_content = "... Silêncio, herege!",
  ui_story_1022_10220902_25_dialog_content = "Suas palavras traiçoeiras não mancharão mais os inocentes...",
  ui_story_1022_10220902_26_dialog_content = "Agora morra!!!",
  ui_story_1022_10220902_27_dialog_content = "Huff... Huff...",
  ui_story_1022_10220902_28_dialog_content = "(Há corais ao meu redor... Isso significa que ainda não escapei?)",
  ui_story_1022_10220902_29_dialog_content = "(Ursura segurou seus golpes agora, mas isso não significa que ela não mudará de ideia mais tarde... Se ela me pegar novamente, eu realmente estarei morto.)",
  ui_story_1022_10220902_30_dialog_content = "(Huh? O que é esse barulho?)",
  ui_story_1022_10220902_31_dialog_content = "Gah! Maldições... Um herege vil como você não deveria ser tão poderoso...",
  ui_story_1022_10220902_32_dialog_content = "Tal ódio desenfreado... Diga-me, o que a Verdadeira Ordem fez para despertar sua ira?",
  ui_story_1022_10220902_33_dialog_content = "Esses passos... É ela!",
  ui_story_1022_10220902_34_dialog_content = "Erica? S-Senhora Victoria?! O que está fazendo aqui? Eu pensei que o Petey foi pego antes que ele pudesse enviar minha mensagem...",
  ui_story_1022_10220902_35_dialog_content = "O destino sempre encontra um caminho sob a orientação do nosso senhor.",
  ui_story_1022_10220902_36_dialog_content = "Mas vejo que você está ferido, Pepita. Quem poderia ter feito isso com... Deixa pra lá. Parece que não há mais necessidade de perguntar.",
  ui_story_1022_10220902_37_dialog_content = "Para onde você acha que está indo, Pepita?! Com todo o sangue que você perdeu, já deveria ter morrido dez vezes!",
  ui_story_1022_10220902_38_dialog_content = "Vou ficar realmente bravo se você não parar de correr! Aqui, vou te mostrar exatamente o que vou fazer com você se não ficar quieto!",
  ui_story_1022_10220902_39_dialog_content = "...!",
  ui_story_1022_10220902_40_dialog_content = "Venha até mim, Pepita.",
  ui_story_1022_10220902_41_dialog_content = "Quem você pensa que é, atrapalhando meu caminho?! Espere... É... é você...!",
  ui_story_1022_10220902_42_dialog_content = "Não fiz nada para atrapalhar seu caminho. Tudo o que fiz foi ficar aqui sem me mover.",
  ui_story_1022_10220902_43_dialog_content = "Pepita é quem escolheu te deixar e ficar ao meu lado.",
  ui_story_1022_10220902_44_dialog_content = "E a pessoa que a forçou a tomar essa decisão não é outra senão você.",
  ui_story_1022_10220902_45_dialog_content = "Desde o início, seu maior obstáculo sempre foi você mesmo.",
  ui_story_1022_10220902_46_dialog_content = "...",
  ui_story_1022_10220902_47_dialog_content = "Você... Você está errado! Pepita é meu, não seu...",
  ui_story_1022_10220902_48_dialog_content = "Os mistérios da Verdade são vastos e insondáveis. É natural que você se sinta perdido na confusão.",
  ui_story_1022_10220902_49_dialog_content = "Mas estejam avisados, pois aqueles que rejeitam o conhecimento e abraçam a crueldade e a ignorância—",
  ui_story_1022_10220902_50_dialog_content = "Encontrarão um dia perdidos na noite eterna, um lugar onde até mesmo a luz da Verdade não brilha.",
  ui_story_1022_10220902_51_dialog_content = "Eu... Você... Aaaaaaaaaaa—!!!",
  ui_story_1022_10220902_52_dialog_content = "<color=#e8d9bb>A agressão ameaçadora do fantasma se transforma em um lamento histérico quase instantaneamente. Enquanto ela foge para longe, seus gritos por seu avô ainda podem ser ouvidos.</color>",
  ui_story_1022_10220902_53_dialog_content = "Sh-Ela começou a chorar e fugiu?!",
  ui_story_1022_10220902_54_dialog_content = "Heheh... Me perdoe, mas faz algum tempo desde que coloquei uma criança em seu lugar.",
  ui_story_1022_10220902_55_dialog_content = "Esse fantasma e o Varaki estão ligados pelo destino até certo ponto, mas quando vi o quanto ela havia machucado Pepita, eu não pude me conter.",
  ui_story_1022_10220902_56_dialog_content = "(Outro Varaki?!)",
  ui_story_1022_10220902_57_dialog_content = "Não se mexa, Pepita. Deixe-me cuidar das suas feridas.",
  ui_story_1022_10220902_58_dialog_content = "Esse emblema... Você usou ele para me encontrar, Senhora Victoria?",
  ui_story_1022_10220902_59_dialog_content = "Sim. Este emblema é uma criação minha, uma que está inextricavelmente ligada à sua energia vital. Ele me permite seguir a energia do seu coração artificial.",
  ui_story_1022_10220902_60_dialog_content = "Também me alerta sempre que você está em grave perigo.",
  ui_story_1022_10220902_61_dialog_content = "Então sim, Pepita: vim aqui só por você, e parece que o destino foi gentil o suficiente para reunir a Ordem com uma de suas relíquias perdidas também.",
  ui_story_1022_10221001_1_dialog_content = "Isso me lembra! Você conhece Charon, não é Senhora Victoria?",
  ui_story_1022_10221001_2_dialog_content = "Você sabe onde ele e Vice estão agora? Ou por que as coordenadas do Outro Fim continuam pulando por todo o nosso mapa?",
  ui_story_1022_10221001_3_dialog_content = "Eles não encontraram outro Wraith, encontraram?!",
  ui_story_1022_10221001_4_dialog_content = "Ficaria feliz em te contar sobre—Hmm? De volta de novo, vejo? Me diga, o que você pretende fazer desta vez?",
  ui_story_1022_10221001_5_dialog_content = "Eu... Eu deveria estar perguntando a mesma coisa! Este ladrão roubou um texto sagrado de Lumópolis! Você realmente acha que pode protegê-la do julgamento?!",
  ui_story_1022_10221001_6_dialog_content = "Além disso, nosso texto sagrado encontrou seu caminho até as mãos do seu grupo... O que significa que todos vocês são igualmente culpados!",
  ui_story_1022_10221001_7_dialog_content = "Ei! Quem disse que você poderia falar sobre nós assim?!",
  ui_story_1022_10221001_8_dialog_content = "A tensão entre ambos os lados está se aproximando do seu ponto de ruptura... Mas o que eu posso fazer?",
  ui_story_1022_10221001_9_dialog_content = "Pepita não te contou ainda? Seu chamado \"texto sagrado\" não é diferente do relicário que tenho em minhas mãos agora, já que todos originalmente pertenciam à True Order.",
  ui_story_1022_10221001_10_dialog_content = "Absurdo! Como você pode possivelmente afirmar que tantas coisas pertencem à sua maldita ordem? Diga-me, todo Astra também pertence a você?!",
  ui_story_1022_10221001_11_dialog_content = "Se você não vai ouvir a razão... Então eu vou detê-lo à força.",
  ui_story_1022_10221001_12_dialog_content = "Às armas, Erica!",
  ui_story_1022_10221001_13_dialog_content = "Sim, senhor!",
  ui_story_1022_10221001_14_dialog_content = "Espere!",
  ui_story_1022_10221001_15_dialog_content = "... Não interfira, PlayerName.",
  ui_story_1022_10221001_16_dialog_content = "Independentemente das circunstâncias, temos o dever de investigar o paradeiro do nosso artefato desaparecido.",
  ui_story_1022_10221001_17_dialog_content = "Então, use suas palavras, não suas armas! Ou você já esqueceu dos desejos do Senhor da Cidade?",
  ui_story_1022_10221001_18_dialog_content = "Mas...",
  ui_story_1022_10221001_19_dialog_content = "Se não quisermos atrapalhar nossa exploração conjunta, precisamos tentar resolver as coisas da maneira mais pacífica possível—",
  ui_story_1022_10221001_20_dialog_content = "\"Nossa\" exploração? E de que lado você está, afinal?",
  ui_story_1022_10221001_21_dialog_content = "O quê?!",
  ui_story_1022_10221001_22_dialog_content = "Todo esse tempo eu coloquei minha confiança em você, apenas para você se aliar ao inimigo no pior momento possível.",
  ui_story_1022_10221001_23_dialog_content = "\"Montamos essa equipe para cuidar um do outro!\" Essas foram suas palavras, seu mentiroso sem vergonha!",
  ui_story_1022_10221001_24_dialog_content = "Agora afaste-se antes que eu—",
  ui_story_1022_10221001_25_dialog_content = "Antes você o quê?",
  ui_story_1022_10221001_26_dialog_content = "Você também não?!",
  ui_story_1022_10221001_27_dialog_content = "PlayerName está certo. A exploração da Zona Escura tem prioridade sobre tudo o mais. O Grande Marechal de Illumina e o Senhor da Cidade de Lumópolis concordaram com isso.",
  ui_story_1022_10221001_28_dialog_content = "Então, se você deseja continuar suas \"investigações\", sugiro que abaixe suas armas primeiro.",
  ui_story_1022_10221001_29_dialog_content = "...",
  ui_story_1022_10221001_30_dialog_content = "Capitão...",
  ui_story_1022_10221001_31_dialog_content = "... Hereges... Devem ser postos à morte!!",
  ui_story_1022_10221002_1_dialog_content = "Urgh! Maldição... Você...",
  ui_story_1022_10221002_2_dialog_content = "(Ela é muito poderosa, e a Zona Cega me enfraqueceu severamente...",
  ui_story_1022_10221002_3_dialog_content = "Eu não vou... Deixar você escapar!",
  ui_story_1022_10221002_4_dialog_content = "Nosso senhor me revelou que Pepita está destinado a uma glória ainda maior.",
  ui_story_1022_10221002_5_dialog_content = "Até a próxima vez. May a luz da Verdade guia todos vocês.",
  ui_story_1022_10221002_6_dialog_content = "... Covardes!",
  ui_story_1022_10221002_7_dialog_content = "Espere Senhora Victoria, você ainda não me respondeu! E quanto a Vice e Charon?!",
  ui_story_1022_10221002_8_dialog_content = "Uau! E-Eu estou voando?! O que você está fazendo, Hiiro—",
  ui_story_1022_10221002_9_dialog_content = "Fique parado. Não estamos voando, estou apenas me movendo o mais rápido que posso.",
  ui_story_1022_10221002_10_dialog_content = "É a única maneira de alcançarmos o Victoria.",
  ui_story_1022_10221002_11_dialog_content = "Hum?",
  ui_story_1022_10221002_12_dialog_content = "O que é, Senhora Victoria?",
  ui_story_1022_10221002_13_dialog_content = "Continue sem mim, Pepita. Se você ficar aqui por mais tempo, as coisas só vão se tornar muito mais problemáticas.",
  ui_story_1022_10221002_14_dialog_content = "Rapidamente.",
  ui_story_1022_10221002_15_dialog_content = "... OK!",
  ui_story_1022_10221002_16_dialog_content = "Ela está aqui!",
  ui_story_1022_10221002_17_dialog_content = "Senhora Victoria! Você sabe exatamente onde Vice está, não sabe?!",
  ui_story_1022_10221002_18_dialog_content = "Não seja tão precipitado, meu jovem amigo. Quando chegar a hora das escrituras serem reveladas, você se reunirá com ela.",
  ui_story_1022_10221002_19_dialog_content = "Mas agora simplesmente não é a hora... Adeus.",
  ui_story_1022_10221002_20_dialog_content = "(Então ela sabe sobre o Vice!)",
  ui_story_1022_10221002_21_option_content = "Aumento de Força!",
  ui_story_1022_10221002_22_dialog_content = "Hehehe...",
  ui_story_1022_10221002_23_dialog_content = "O-O que é isso...?",
  ui_story_1022_10221002_24_dialog_content = "<color=#e8d9bb>Monolíticos pilares de gelo ascendem ao céu, flutuando em nítido contraste com a escuridão fluente da noite eterna.</color>",
  ui_story_1022_10221002_25_dialog_content = "<color=#e8d9bb>Encerrado em uma das enormes formações de gelo está nada menos que—</color>",
  ui_story_1022_10221002_26_dialog_content = "... Vice!",
  ui_story_1022_10221002_27_dialog_content = "(Mas como?! O que ela está fazendo em um lugar assim...?)",
  ui_story_1022_10221002_28_option_content = "Digitalizar novamente",
  ui_story_1022_10221002_29_dialog_content = "O som de um piano é arte em sua forma mais pura. Ele pode transcender as próprias fronteiras do tempo e do espaço.",
  ui_story_1022_10221002_30_dialog_content = "O que você está fazendo, Vice?",
  ui_story_1022_10221002_31_dialog_content = "PlayerName está em perigo! Eu tenho que fazer algo antes que ele se perca na escuridão do Engenheiro!",
  ui_story_1022_10221002_32_dialog_content = "Vou usar este piano para avisá-lo...",
  ui_story_1022_10221002_33_dialog_content = "O Engenheiro está observando nosso amigo Caelestite muito de perto. Tão de perto, na verdade, que suas mentes estão agora ligadas.",
  ui_story_1022_10221002_34_dialog_content = "É provável que o Engenheiro perceba você se interferir.",
  ui_story_1022_10221002_35_dialog_content = "Mas—!",
  ui_story_1022_10221002_36_dialog_content = "Honestamente, Senhora Victoria, você não tem senso de romance?",
  ui_story_1022_10221002_37_dialog_content = "Você acha que seu senhor ficaria satisfeito se você interrompesse essa maravilhosa música e abandonasse nosso amigo na escuridão?",
  ui_story_1022_10221002_38_dialog_content = "Oh? Parece que você está disposto a não apenas invocar o nome do nosso senhor, mas também batalhar com o Engenheiro.",
  ui_story_1022_10221002_39_dialog_content = "Você finalmente está pronto para aceitar a Verdade e despertar para o poder da sua linhagem?",
  ui_story_1022_10221002_40_dialog_content = "É uma grande presunção, considerando que eu só pronunciei uma única frase! Permita-me reiterar: Eu não tenho absolutamente nenhum interesse na tal \"Verdade\" que você insiste incessantemente.",
  ui_story_1022_10221002_41_dialog_content = "Então isso é de fato uma tragédia.",
  ui_story_1022_10221002_42_dialog_content = "... Lá! PlayerName conseguiu se libertar!",
  ui_story_1022_10221002_43_dialog_content = "Mas Soroz se foi agora...",
  ui_story_1022_10221002_44_dialog_content = "Não se preocupe, querido Vice. PlayerName nunca abandonaria seu Colossus, e nós nunca o abandonaríamos.",
  ui_story_1022_10221002_45_dialog_content = "Isso realmente torna as coisas um pouco mais complicadas.",
  ui_story_1022_10221002_46_dialog_content = "Estragando o momento mais uma vez, milady?",
  ui_story_1022_10221002_47_dialog_content = "A Verdade protege cada membro da Verdadeira Ordem. Como pessoas de Illumina, no entanto, você ainda não foi escolhido.",
  ui_story_1022_10221002_48_dialog_content = "Se insistem em se colocar em risco... Então, receio que não tenho outra escolha.",
  ui_story_1022_10221002_49_dialog_content = "<color=#e8d9bb>Resumo—</color>",
  ui_story_1022_10221002_50_dialog_content = "Ahhh!",
  ui_story_1022_10221002_51_dialog_content = "O-O que é o significado disso?!",
  ui_story_1022_10221002_52_dialog_content = "<color=#e8d9bb>Com um aceno de mão, Victoria divide o Rio Pristine em dois.</color>",
  ui_story_1022_10221002_53_dialog_content = "<color=#e8d9bb>Charon e Vice caem infinitamente em suas profundezas.</color>",
  ui_story_1022_10221002_54_dialog_content = "<color=#e8d9bb>Enquanto caem, uma voz misteriosa sussurra em seus ouvidos—</color>",
  ui_story_1022_10221002_55_dialog_content = "Contanto que contenha até mesmo uma única gota de água do Rio Prístino, nem mesmo o Darkflow mais poderoso derreterá este gelo.",
  ui_story_1022_10221002_56_dialog_content = "Bwaaaaaa—Hã? N-Nós paramos de cair?",
  ui_story_1022_10221002_57_dialog_content = "... Que lugar é esse?",
  ui_story_1022_10221002_58_dialog_content = "<color=#e8d9bb>Num piscar de olhos, o ambiente ao redor mudou completamente.</color>",
  ui_story_1022_10221002_59_dialog_content = "<color=#e8d9bb>Um céu escurecido os envolve, espesso e retorcido como um pântano vivo. Parece distorcido, como se estivessem vendo através de uma janela de vidro pesado e irregular.</color>",
  ui_story_1022_10221002_60_dialog_content = "<color=#e8d9bb>O vidro, no entanto, é na verdade—</color>",
  ui_story_1022_10221002_61_dialog_content = "Ice? Wh-Why am I trapped in a giant ice pillar?!",
  ui_story_1022_10221002_62_dialog_content = "Huh? Aquele som...",
  ui_story_1022_10221002_63_dialog_content = "<color=#e8d9bb>Tum, tum, tum—</color>",
  ui_story_1022_10221002_64_dialog_content = "Quebre, maldito bloco congelado! Nenhuma tumba de gelo pode aprisionar as chamas das minhas emoções!",
  ui_story_1022_10221002_65_dialog_content = "O-Oficial Charon! Você também está preso aqui?!",
  ui_story_1022_10221002_66_dialog_content = "<color=#e8d9bb>Tum, tum, tum—</color>",
  ui_story_1022_10221002_67_dialog_content = "<color=#e8d9bb>Sob o ataque implacável do Outro Fim, o gelo começa a rachar.</color>",
  ui_story_1022_10221002_68_dialog_content = "Pegue minha mão, Vice!",
  ui_story_1022_10221002_69_dialog_content = "Tô indo!",
  ui_story_1022_10221002_70_dialog_content = "Vício.",
  ui_story_1022_10221002_71_dialog_content = "(Hã? Estou imaginando coisas, ou acabei de ouvir a voz da Senhora Victoria?)",
  ui_story_1022_10221002_72_dialog_content = "Ouça-me, Vice.",
  ui_story_1022_10221002_73_dialog_content = "PlayerName está prestes a enfrentar seu teste mais desafiador ainda. Ele—",
  ui_story_1022_10221002_74_dialog_content = "<color=#e8d9bb>A voz de Victoria aparece nos ouvidos de Vice, clara como o dia.</color>",
  ui_story_1022_10221002_75_dialog_content = "!!",
  ui_story_1022_10221002_76_dialog_content = "O que você está esperando, Vice?! Venha aqui agora mesmo!",
  ui_story_1022_10221002_77_dialog_content = "...",
  ui_story_1022_10221002_78_dialog_content = "Você vá em frente, Oficial Charon.",
  ui_story_1022_10221002_79_dialog_content = "Eu vou ficar aqui.",
  ui_story_1022_10221002_80_dialog_content = "O quê?!",
  ui_story_1022_10221002_81_dialog_content = "PlayerName precisa de mim...",
  ui_story_1022_10221002_82_dialog_content = "E enquanto eu estiver aqui, sei que posso ajudá-lo.",
  ui_story_1022_10221002_83_dialog_content = "<color=#FFB400>Vice</color>—!",
  ui_story_1022_10221002_84_dialog_content = "<color=#e8d9bb>Quero gritar para ela, estender a mão e deixar que ela saiba que estou aqui. Quero estar ao lado dela, ou pelo menos ver seu sorriso novamente...</color>",
  ui_story_1022_10221002_85_dialog_content = "<color=#e8d9bb>Mas minha visão continua escurecendo.</color>",
  ui_story_1022_10221002_86_dialog_content = "<color=#e8d9bb>Mais escuro e mais escuro.</color>",
  ui_story_1022_10221002_87_dialog_content = "<color=#e8d9bb>Como se eu estivesse envolto pela noite eterna.</color>",
  ui_story_1022_10221002_88_dialog_content = "<color=#e8d9bb>Mas a única fonte de luz vem dela.</color>",
  ui_story_1022_10221002_89_dialog_content = "<color=#e8d9bb>Cercado por todos os lados pela fria e opressiva escuridão—</color>",
  ui_story_1022_10221002_90_dialog_content = "<color=#e8d9bb>Sua luz ofuscante brilha em todas as direções.</color>",
  ui_story_1022_10221002_91_dialog_content = "<color=#e8d9bb>Como o sol brilhando através de uma noite eterna.</color>",
  ui_story_1022_10221002_92_dialog_content = "(Essa bola de Lumina que senti antes... Era Vice o tempo todo...)",
  ui_story_1022_10221002_93_dialog_content = "(A luz de sua alma era a única coisa que me impedia de me perder na escuridão.)",
  ui_story_1022_10221002_94_dialog_content = "(Vocês me chamam de Navegador porque contam comigo para guiá-los através de suas batalhas mais difíceis...)",
  ui_story_1022_10221002_95_dialog_content = "(Mas quem tem me guiado o tempo todo é Vice.)",
  ui_story_1022_10221002_96_dialog_content = "(Desde o primeiro dia em que nos conhecemos...)",
  ui_story_1022_10221101_1_dialog_content = "... PlayerName.",
  ui_story_1022_10221101_2_dialog_content = "Acorda, PlayerName!",
  ui_story_1022_10221101_3_dialog_content = "Hiiro...",
  ui_story_1022_10221101_4_dialog_content = "... Eu a vi, Hiiro! Eu sei onde Vice está! Ela é a fonte daquela Lumina que senti antes, mas ela está presa em um gigante pilar de gelo! Nós temos que salvá-la!",
  ui_story_1022_10221101_5_dialog_content = "Estou ouvindo, mas você precisa se acalmar primeiro. Aqui, beba um pouco de água.",
  ui_story_1022_10221101_6_dialog_content = "O-Ok, valeu...",
  ui_story_1022_10221101_7_dialog_content = "Acho que você deveria saber, mas Victoria já se foi. Ela desapareceu de repente há algum tempo.",
  ui_story_1022_10221101_8_dialog_content = "Desapareceu?",
  ui_story_1022_10221101_9_dialog_content = "Sim. Parece que o Victoria com quem falamos não era nada mais do que uma ilusão.",
  ui_story_1022_10221101_10_dialog_content = "*chorando* Avô! Aaaahhhh—",
  ui_story_1022_10221101_11_dialog_content = "Como você pôde morrer e me deixar sozinho assim?! Se você ainda estivesse por perto, aquela <color=#FFB400>mulher nojenta</color> não teria sido tão cruel comigo!",
  ui_story_1022_10221101_12_dialog_content = "Avô...",
  ui_story_1022_10221101_13_dialog_content = "...",
  ui_story_1022_10221101_14_dialog_content = "Acho que não adianta mais chorar sobre isso. Afinal, ele está morto.",
  ui_story_1022_10221101_15_dialog_content = "Mas agora eu tenho Pepita! Ela se preocupa comigo mais do que qualquer outra pessoa!",
  ui_story_1022_10221101_16_dialog_content = "Mas aquela senhora malvada a levou de mim...",
  ui_story_1022_10221101_17_dialog_content = "<size=50>Uauuuuuuuu!</size>",
  ui_story_1022_10221101_18_dialog_content = "Como eu disse antes, foi você quem afastou Pepita.",
  ui_story_1022_10221101_19_dialog_content = "O quê?!",
  ui_story_1022_10221101_20_dialog_content = "É realmente tão difícil para você usar a cabeça de vez em quando? Eu entendo que você nunca precisou, dado o seu direito de nascimento...",
  ui_story_1022_10221101_21_dialog_content = "Mas até mesmo uma mente obtusa é uma coisa terrível de desperdiçar. Não concorda—",
  ui_story_1022_10221101_22_dialog_content = "<color=#FFB400>Filha há muito abandonada do décimo terceiro chefe de família</color>?",
  ui_story_1022_10221101_23_dialog_content = "Como... Como você se atreve a trazer isso à tona!",
  ui_story_1022_10221101_24_dialog_content = "Idiota! Como ousa oferecer esse sangue imundo à minha preciosa neta!",
  ui_story_1022_10221101_25_dialog_content = "Ursura pode distinguir entre o sangue nobre e o sangue de um plebeu tolo! Você está tentando matá-la com sua oferta miserável?!",
  ui_story_1022_10221101_26_dialog_content = "F-Perdoe-me, meu senhor!",
  ui_story_1022_10221101_27_dialog_content = "Aaaaaaaaaaa!",
  ui_story_1022_10221101_28_dialog_content = "Não chore, minha querida. Seu avô vai encontrar para você o melhor sangue do mundo.",
  ui_story_1022_10221101_29_dialog_content = "Apenas o sangue mais doce e delicioso servirá para meu pequeno gênio querido...",
  ui_story_1022_10221101_30_dialog_content = "<color=#e8d9bb>Crash! Com um único movimento, todas as peças de louça caem no chão e se estilhaçam em pedaços.</color>",
  ui_story_1022_10221101_31_dialog_content = "O-O que é, minha senhora?! Fizemos algo mais para ofendê-la?",
  ui_story_1022_10221101_32_dialog_content = "Você realmente não sabe? Você mal me trouxe alguma \"presa\" para brincar hoje! Se meu avô ainda estivesse vivo, você não sonharia em me insultar assim!",
  ui_story_1022_10221101_33_dialog_content = "M-Mas minha senhora... Se reduzirmos o número de plebeus muito rapidamente, a produção diminuirá e nosso povo não terá o suficiente para comer...",
  ui_story_1022_10221101_34_dialog_content = "Então deixe-os comer bolo, se estão tão famintos! Eu realmente preciso explicar tudo para você?!",
  ui_story_1022_10221101_35_dialog_content = "N-Não, minha senhora... Vou providenciar mais presas imediatamente.",
  ui_story_1022_10221101_36_dialog_content = "Fuja...!!!",
  ui_story_1022_10221101_37_dialog_content = "Hahahaha! Agora sim! Jogos de caça são sempre mais divertidos quando há muita presa!",
  ui_story_1022_10221101_38_dialog_content = "Corra o mais longe e rápido que puder, coelhinhos! E não se preocupe...",
  ui_story_1022_10221101_39_dialog_content = "Vou garantir de me divertir muito com cada um de vocês.",
  ui_story_1022_10221101_40_dialog_content = "Todos terão uma vez... Eu prometo.",
  ui_story_1022_10221101_41_dialog_content = "As coisas costumavam ser tão boas. Naquela época, todos me ouviam e brincavam comigo, sem fazer perguntas...",
  ui_story_1022_10221101_42_dialog_content = "Mas não mais. Tudo se foi agora... E é tudo por causa de você, escória Varaki!",
  ui_story_1022_10221101_43_dialog_content = "Graças a você, não tive escolha senão me retirar para o Eclipse, onde tudo que eu podia fazer era dormir, dormir, dormir. Ninguém me ouvia, ou sequer se importava comigo, para dizer a verdade...",
  ui_story_1022_10221101_44_dialog_content = "É toda sua culpa!!",
  ui_story_1022_10221101_45_dialog_content = "Jogando a culpa em outras pessoas novamente, eu vejo?",
  ui_story_1022_10221101_46_dialog_content = "O motivo pelo qual você foi exilado foi por causa de sua tirania e sua traição.",
  ui_story_1022_10221101_47_dialog_content = "Você foi quem liderou um exército de Eclipsitas para a Cidade Varaki, matando inúmeros crentes inocentes e fugindo com a relíquia sagrada da True Order. Esse capítulo manchado de sangue da história de Varaki foi escrito por ninguém menos que você mesmo.",
  ui_story_1022_10221101_48_dialog_content = "Então, quando folheei as páginas empoeiradas da história da nossa família, fiquei chocado ao descobrir a gravidade dos seus pecados...",
  ui_story_1022_10221101_49_dialog_content = "Cale a boca! Apenas cale a boca já! O que há de tão errado em matar alguns Aurorians de qualquer maneira? Não é como se você não tivesse feito o mesmo, certo?!",
  ui_story_1022_10221101_50_dialog_content = "Nada deixava meu avô mais feliz do que me ver feliz... Mas então vocês tiveram que estragar tudo!",
  ui_story_1022_10221101_51_dialog_content = "Não pense que você pode me dar lições só porque você é o chefe da família...",
  ui_story_1022_10221101_52_dialog_content = "Enquanto eu queimar o mais brilhantemente possível... Então, qual o problema em morrer?",
  ui_story_1022_10221101_53_dialog_content = "Não sou animal de estimação de ninguém, e nunca vou me render a ninguém...",
  ui_story_1022_10221101_54_dialog_content = "<color=#FFB400>Eu... Pertenço a mim mesmo!</color>",
  ui_story_1022_10221101_55_dialog_content = "... Eu pertenço a mim mesmo! Eu nunca vou ouvir você ou qualquer outra pessoa!",
  ui_story_1022_10221101_56_dialog_content = "Que uso ridículo do credo de Pepita. Se ela estivesse aqui agora, estaria derramando lágrimas de riso.",
  ui_story_1022_10221101_57_dialog_content = "Não ouse mencioná-la!!!",
  ui_story_1022_10221101_58_dialog_content = "<color=#e8d9bb>Enquanto Ursura grita selvagemente, um denso Fluxo Escuro começa a irromper ao redor dela. </color>",
  ui_story_1022_10221101_59_dialog_content = "<color=#e8d9bb>Envolve-a e borbulha para fora em todas as direções, rastejando de forma ameaçadora sobre o gelo escurecido.</color>",
  ui_story_1022_10221101_60_dialog_content = "<color=#e8d9bb>Incontáveis botões brotam do gelo, crepitando e ramificando-se ao formar enormes aglomerados de coral retorcido.</color>",
  ui_story_1022_10221101_61_dialog_content = "<color=#e8d9bb>Os corais começam a se entrelaçar grotescamente, como as veias de um monstro gigantesco.</color>",
  ui_story_1022_10221101_62_dialog_content = "<color=#e8d9bb>Tum-tum.</color>",
  ui_story_1022_10221101_63_dialog_content = "<color=#e8d9bb>A floresta de corais inteira, uma entidade viva por si só, pulsa em sincronia com o coração que bate no centro da névoa negra turbulenta.</color>",
  ui_story_1022_10221101_64_dialog_content = "<color=#e8d9bb>Com cada batimento cardíaco, mais do viscoso Fluxo Escuro se derrama, corrompendo a vida de todos os Aurorianos nas proximidades.</color>",
  ui_story_1022_10221101_65_dialog_content = "Graaagh—!!!",
  ui_story_1022_10221102_1_dialog_content = "<color=#e8d9bb>Rachadura!</color>",
  ui_story_1022_10221102_2_dialog_content = "<color=#e8d9bb>Victoria finalmente consegue perfurar a densa carapaça de Darkflow de Ursura, embora não sem pagar um preço.</color>",
  ui_story_1022_10221102_3_dialog_content = "Tosse...!",
  ui_story_1022_10221102_4_dialog_content = "Ha... Hahaha! É isso tudo que você consegue reunir, Senhorita Chefe da Casa?!",
  ui_story_1022_10221102_5_dialog_content = "Com um pouco mais de esforço, posso facilmente fazer você se ajoelhar!",
  ui_story_1022_10221102_6_dialog_content = "Suponho que faz sentido. Afinal, despertei para o poder da minha linhagem quando era apenas uma garotinha muito pequena. Até meu avô disse que nunca houve um gênio como eu antes!",
  ui_story_1022_10221102_7_dialog_content = "Mas e você, velha bruxa? Pelo jeito das coisas, você não despertou para seus poderes até que sua vida já estava pela metade! Hahahahaha!",
  ui_story_1022_10221102_8_dialog_content = "... Ei.",
  ui_story_1022_10221102_9_dialog_content = "Qual a graça?",
  ui_story_1022_10221102_10_dialog_content = "Despertei para os meus poderes mais cedo do que qualquer outro na história inteira da nossa família! Isso me torna o mais puro e talentoso da nossa espécie! Você nunca poderia esperar me comparar!",
  ui_story_1022_10221102_11_dialog_content = "Neste ponto, você pode muito bem me fazer o chefe da sua casa! Hahaha—",
  ui_story_1022_10221102_12_dialog_content = "<color=#e8d9bb>A risada maníaca de Ursura chega a um fim abrupto.</color>",
  ui_story_1022_10221102_13_dialog_content = "<color=#e8d9bb>Com um olhar de horror e perplexidade, ela observa enquanto as feridas de Victoria se curam rapidamente uma a uma. Até suas roupas rasgadas retornam ao seu estado original.</color>",
  ui_story_1022_10221102_14_dialog_content = "M-Mas como...?!",
  ui_story_1022_10221102_15_dialog_content = "Você realmente está tão chocado com isso? Eu presumi que um gênio como você já teria percebido minha técnica.",
  ui_story_1022_10221102_16_dialog_content = "Você... Você está guardando a maior parte do seu poder em outro lugar, não está?! O que exatamente você está tramando?!",
  ui_story_1022_10221102_17_dialog_content = "Depois de mergulhar esses dois nas profundezas do Rio Prístino, é natural que eu fique e cuide deles. A Zona Escura é um lugar perigoso, afinal de contas.",
  ui_story_1022_10221102_18_dialog_content = "Se você não tivesse se desviado tanto do caminho da Verdade... Nosso senhor também estaria protegendo você.",
  ui_story_1022_10221102_19_dialog_content = "Impossível... Não tem como você ter força suficiente para lutar contra mim e cuidar de outras pessoas ao mesmo tempo!",
  ui_story_1022_10221102_20_dialog_content = "Sou o mais forte... Despertei para os meus poderes muito antes de qualquer outra pessoa! Minha força é a mais pura, e meu potencial é ilimitado... D-Deve haver algum tipo de truque no seu poder! Tem que haver!",
  ui_story_1022_10221102_21_dialog_content = "Essa é a única explicação que você consegue encontrar? Parece que você despertou para seus poderes <color=#FFB400>muito cedo</color>.",
  ui_story_1022_10221102_22_dialog_content = "O quê?",
  ui_story_1022_10221102_23_dialog_content = "Seu despertar foi prematuro, o que te tornou arrogante e, portanto, terrivelmente ingênuo. Nem uma vez você tentou cultivar seu poder através do pensamento ou treinamento.",
  ui_story_1022_10221102_24_dialog_content = "Não há como negar sua força, Ursura. Você representa os impulsos mais primários e insaciáveis de nossa espécie.",
  ui_story_1022_10221102_25_dialog_content = "Eu, por outro lado, sou exatamente o oposto de você.",
  ui_story_1022_10221102_26_dialog_content = "O-O que isso deveria significar...?",
  ui_story_1022_10221102_27_dialog_content = "Despertei para os meus poderes muito depois de você.",
  ui_story_1022_10221102_28_dialog_content = "Para compreender a Verdade, viajei pela extensão e largura da terra, refletindo sobre tudo que presenciei.",
  ui_story_1022_10221102_29_dialog_content = "Foi uma jornada que você não experimentou e não experimentará novamente.",
  ui_story_1022_10221102_30_dialog_content = "E porque meus métodos são perdidos para você... Só posso pedir que use sua imaginação.",
  ui_story_1022_10221102_31_dialog_content = "Afinal... Você nunca poderia entender.",
  ui_story_1022_10221102_32_dialog_content = "C-Cale-se! Eu sou o mais forte, não você...!",
  ui_story_1022_10221102_33_dialog_content = "<color=#e8d9bb>O grito furioso de Ursura não é suficiente para suprimir o medo em seu coração. Toda a sua vida, disseram-lhe que ela era um gênio entre gênios.</color>",
  ui_story_1022_10221102_34_dialog_content = "<color=#e8d9bb>Mas essa revelação repentina veio como um terrível choque para seu coração, sua mente e seus sentidos—</color>",
  ui_story_1022_10221102_35_dialog_content = "<color=#FFB400>Ordem</color>...",
  ui_story_1022_10221102_36_dialog_content = "<color=#e8d9bb>É o ápice, o reino supremo ao qual todos os Aurorianos que buscam a Verdade aspiram.</color>",
  ui_story_1022_10221102_37_dialog_content = "<color=#e8d9bb>Através de um inquérito sincero, supera todo desejo puro e primitivo. Um hino de adoração dedicado à Verdade.</color>",
  ui_story_1022_10221102_38_dialog_content = "Uma resposta maravilhosa, Ursura. Agora, é hora de colocá-la em prática.",
  ui_story_1022_10221102_39_dialog_content = "Contemple minha técnica secreta. Observe atentamente e não desvie o olhar.",
  ui_story_1022_10221102_40_dialog_content = "Esta peregrinação, eu ofereço ao nosso senhor...",
  ui_story_1022_10221102_41_dialog_content = "Waaaahhhh—!",
  ui_story_1022_10221102_42_dialog_content = "Por quê? Por quê?! A marca do Eclipse foi me dada há muito tempo, então por quê...",
  ui_story_1022_10221102_43_dialog_content = "... Por que eu sou um Auroriano de novo?!",
  ui_story_1022_10221102_44_dialog_content = "Não... Por favor... Eu não quero morrer... Eu não quero desaparecer...",
  ui_story_1022_10221102_45_dialog_content = "Nãooooooo!!!",
  ui_story_1022_10221102_46_dialog_content = "Que técnica aterrorizante... Entendo agora. Então essa é a sua ideia de redenção.",
  ui_story_1022_10221102_47_dialog_content = "Ao negar o imaterial, você pretende oferecer apenas a pura essência ao senhor de todas as consciências?",
  ui_story_1022_10221102_48_dialog_content = "Não... O verdadeiro a ser temido é você, Victoria.",
  ui_story_1022_10221102_49_dialog_content = "O seu poder é algo que até eu anseio controlar mais uma vez. Não existe nada além do seu campo de visão?",
  ui_story_1022_10221102_50_dialog_content = "<color=#e8d9bb>O rio iridescente serpenteia e flui para toda a eternidade. Em suas águas, o tempo não tem significado.</color>",
  ui_story_1022_10221102_51_dialog_content = "<color=#e8d9bb>Ainda agora, inúmeros passados e futuros se organizam igualmente diante do Recluso, incluindo suas realidades paralelas.</color>",
  ui_story_1022_10221102_52_dialog_content = "Mas quase não importa agora... Venha.",
  ui_story_1022_10221102_53_dialog_content = "<color=#e8d9bb>Com uma palma das mãos, o Recluso abre uma fenda no espaço, e um trem movido a vapor surge voando do vazio.</color>",
  ui_story_1022_10221102_54_dialog_content = "Aaaahhhh—",
  ui_story_1022_10221102_55_dialog_content = "Silêncio. Na minha solidão, meus ouvidos se desacostumaram aos gritos dos outros.",
  ui_story_1022_10221102_56_dialog_content = "Não esse maldito rio de novo! E quem você poderia ser?! Espere... Eu já te vi antes.",
  ui_story_1022_10221102_57_dialog_content = "Você é... O primo há muito falecido do meu pai, bem como tio de Victoria... <color=#FFB400>Wilhelm Varaki</color>.",
  ui_story_1022_10221102_58_dialog_content = "Você também pode sempre me chamar de tio, sabe.",
  ui_story_1022_10221102_59_dialog_content = "Sim, bem, me perdoe por não querer discutir laços familiares com um homem morto, especialmente no ambiente estranho em que nos encontramos agora.",
  ui_story_1022_10221102_60_dialog_content = "... Você é tão irritantemente prolixo quanto Victoria.",
  ui_story_1022_10221102_61_dialog_content = "O que foi isso? Quero que saiba que meu discurso eloquente não tem nada a ver com o delírio fanático daquela mulher!",
  ui_story_1022_10221102_62_dialog_content = "Primeiro a filha do meu irmão, agora você... Talvez eu deva mudar o brasão da nossa família para incluir um berço e uma chupeta?",
  ui_story_1022_10221102_63_dialog_content = "Seu nome é Charon, se eu não estou enganado? Me diga, você sabe por que está aqui?",
  ui_story_1022_10221102_64_dialog_content = "Você está dizendo que isso não foi obra sua?",
  ui_story_1022_10221102_65_dialog_content = "Victoria deseja que você aperfeiçoe suas técnicas comigo e aprofunde seu entendimento da verdade. Ela vê um grande potencial oculto em você.",
  ui_story_1022_10221102_66_dialog_content = "O que?! Eu disse àquela bruxa que não quero nada com ela ou com a tal Verdade dela!",
  ui_story_1022_10221102_67_dialog_content = "E você estava inegavelmente desinteressado naquele momento, sim.",
  ui_story_1022_10221102_68_dialog_content = "Mas o tempo passou e você já não é mais a pessoa que era antes. Diga-me, quais são seus pensamentos agora?",
  ui_story_1022_10221102_69_dialog_content = "Eu...",
  ui_story_1022_10221102_70_dialog_content = "<color=#e8d9bb>\"Claro que ainda não estou interessado!\" As palavras quase se formaram na boca de Charon.</color>",
  ui_story_1022_10221102_71_dialog_content = "<color=#e8d9bb>Mas de repente, a imagem de Vice congelado em uma coluna de gelo apareceu em sua mente. Ele se lembrou que seu subordinado ainda estava cercado por Eclipsitas em um lugar de noite eterna.</color>",
  ui_story_1022_10221102_72_dialog_content = "<color=#e8d9bb>Ela escolheu ficar lá pelo bem do Caelestite, o que significa que ele provavelmente está em grave perigo. Por extensão, significa que seus camaradas da Illumina também estão em perigo.</color>",
  ui_story_1022_10221102_73_dialog_content = "<color=#e8d9bb>Nestas circunstâncias...</color>",
  ui_story_1022_10221102_74_dialog_content = "... Talvez seja finalmente a hora de superar minha fase rebelde.",
  ui_story_1022_10221102_75_dialog_content = "Hmph, pelo menos você está ciente de sua própria teimosia, o que significa que ainda há esperança para você... Diferente de algumas pessoas.",
  ui_story_1022_10221102_76_dialog_content = "Mas, felizmente, não terei que colocar minha própria vida inexistente em perigo desta vez. Não é mesmo?",
  ui_story_1022_10221200_1_dialog_content = "...",
  ui_story_1022_10221200_2_dialog_content = "(Uma caverna... Isso mesmo. Consegui recuar até o nosso primeiro local de acampamento antes de desmaiar de exaustão.)",
  ui_story_1022_10221200_3_dialog_content = "(A senhora Victoria provavelmente foi atrás de Ursura. Eu tenho que encontrá-la...)",
  ui_story_1022_10221200_4_dialog_content = "Droga, tudo! Nosso alvo e o tomo roubado estavam bem à nossa frente, e ainda assim perdemos nossa chance!",
  ui_story_1022_10221200_5_dialog_content = "(Uh-oh, o que ela está fazendo aqui? Ainda bem que eu não estava com pressa para sair.)",
  ui_story_1022_10221200_6_dialog_content = "Por favor, não se mova tanto, capitão. Você vai reabrir seus ferimentos.",
  ui_story_1022_10221200_7_dialog_content = "(Erica... Ela parecia tão preocupada quando viu meus ferimentos mais cedo.)",
  ui_story_1022_10221200_8_dialog_content = "Estou bem, Erica! Além disso, estou mais preocupado com o que nosso convidado não convidado está fazendo aqui.",
  ui_story_1022_10221200_9_dialog_content = "Você não recebeu nossa mensagem? Fui enviado para te ajudar.",
  ui_story_1022_10221200_10_dialog_content = "(Alguém mais está aqui? Eu nem mesmo notei...)",
  ui_story_1022_10221200_11_dialog_content = "\"Ajude-nos,\" você diz? Nossa equipe inteira tinha Pepita cercada, e ela ainda conseguiu escapar! Como você poderia nos ajudar agora?!",
  ui_story_1022_10221200_12_dialog_content = "(Estão falando de mim, huh?)",
  ui_story_1022_10221200_13_dialog_content = "Ao usar um método infalível para capturá-la, é claro.",
  ui_story_1022_10221200_14_dialog_content = "Por favor, pegue isso.",
  ui_story_1022_10221200_15_dialog_content = "Um controle remoto? O que você está tentando dizer, que isso pode revelar a localização dela com um apertar de um botão?!",
  ui_story_1022_10221200_16_dialog_content = "Exatamente.",
  ui_story_1022_10221200_17_dialog_content = "... Você está brincando.",
  ui_story_1022_10221200_18_dialog_content = "De maneira nenhuma. O que você está se referindo como um \"controle remoto\" é na verdade uma contramedida colocada em prática por Belisaria anos atrás.",
  ui_story_1022_10221200_19_dialog_content = "Com isso, você pode controlar o batimento do coração artificial no peito de Pepita.",
  ui_story_1022_10221200_20_dialog_content = "!!",
  ui_story_1022_10221200_21_dialog_content = "O coração de Pepita... É artificial?",
  ui_story_1022_10221200_22_dialog_content = "E este botão específico pode ser usado para desligar completamente o coração dela. Eu não deveria precisar explicar o que acontece depois disso... Certo?",
  ui_story_1022_10221200_23_dialog_content = "Usar essa função para localizá-la é praticamente infalível, você não concorda?",
  ui_story_1022_10221200_24_dialog_content = "Você está fora de si?! Isso não seria diferente de assassiná-la!",
  ui_story_1022_10221200_25_dialog_content = "Tirar uma vida só é assassinato quando a vítima é inocente.",
  ui_story_1022_10221200_26_dialog_content = "Mas quando a vítima é um criminoso procurado... Então, isso se torna uma execução.",
  ui_story_1022_10221200_27_dialog_content = "Realmente existe alguma diferença entre os dois...?",
  ui_story_1022_10221200_28_dialog_content = "Quando Pepita traiu a Illumina pela primeira vez, Belisaria segurava este mesmo dispositivo em suas mãos naquele dia.",
  ui_story_1022_10221200_29_dialog_content = "Mas mesmo que ela tenha visto o criminoso escapar com seus próprios olhos, ela não conseguiu se convencer a apertar o botão. Foi... Uma grande decepção.",
  ui_story_1022_10221200_30_dialog_content = "(Belisaria...)",
  ui_story_1022_10221200_31_dialog_content = "Mas acredito que você é diferente da chamada \"Dama de Ferro.\"",
  ui_story_1022_10221200_32_dialog_content = "Sua vindicatividade em relação aos criminosos de Lumópolis é genuína.",
  ui_story_1022_10221200_33_dialog_content = "Eu...",
  ui_story_1022_10221200_34_dialog_content = "Não faça isso, capitã!",
  ui_story_1022_10221200_35_dialog_content = "Isso... Isso não é o caminho certo! Pepita pode ter cometido alguns crimes, mas isso não a torna uma pessoa má!",
  ui_story_1022_10221200_36_dialog_content = "Como um espírito afim, posso ver isso em seus olhos sempre que nos encontramos cara a cara.",
  ui_story_1022_10221200_37_dialog_content = "Todos nós somos culpados de cometer erros ao longo de nossas vidas... Os ensinamentos do Deus da Luz nos dizem isso! Mas até o mais culpado dos pecadores merece uma chance de redenção!",
  ui_story_1022_10221200_38_dialog_content = "Erica...!",
  ui_story_1022_10221200_39_dialog_content = "Quem tá aí?!",
  ui_story_1022_10221200_40_dialog_content = "P-Pepita?! Quando você—",
  ui_story_1022_10221200_41_dialog_content = "Er, desculpe, acho que você está me confundindo com outra pessoa. D-Não se importe comigo, continue com sua conversa!",
  ui_story_1022_10221200_42_dialog_content = "... Depois dela!",
  ui_story_1022_10221200_43_dialog_content = "Espere, Pepita! Não vá!",
  ui_story_1022_10221200_44_dialog_content = "Diga ao seu capitão para entregar esse controle remoto primeiro!",
  ui_story_1022_10221200_45_dialog_content = "Por favor, confie em mim, Pepita! Eu não vou deixar eles te machucarem, então—",
  ui_story_1022_10221200_46_dialog_content = "Isso mesmo! Fale comigo quando você estiver classificado acima desse seu capitão louco!",
  ui_story_1022_10221200_47_dialog_content = "Apenas ouça, Pepita! Você está correndo em direção a—",
  ui_story_1022_10221200_48_dialog_content = "Desista! Eu não vou parar por nada—O-Uau!",
  ui_story_1022_10221200_49_dialog_content = "<color=#e8d9bb>Uma rajada súbita de vento frio quase derruba Pepita no chão.</color>",
  ui_story_1022_10221200_50_dialog_content = "<color=#e8d9bb>Mais alguns passos, e ela teria caído de cabeça em um abismo bocejante e sem fundo.</color>",
  ui_story_1022_10221200_51_dialog_content = "Pepita! Você está bem?!",
  ui_story_1022_10221200_52_dialog_content = "... Não chegue mais perto.",
  ui_story_1022_10221200_53_dialog_content = "Tudo bem, eu não vou, mas por favor, apenas me ouça!",
  ui_story_1022_10221200_54_dialog_content = "O Senhor da Cidade concordou em não te punir, contanto que você nos conte tudo o que sabe sobre nosso tomo desaparecido. Se fizer isso, eu prometo—",
  ui_story_1022_10221200_55_dialog_content = "Você é o que está fazendo a promessa, ou é o Senhor da Cidade?",
  ui_story_1022_10221200_56_dialog_content = "Eu...",
  ui_story_1022_10221200_57_dialog_content = "Você não pode prometer nada, pode? Tudo o que você pode fazer é esperar que seu precioso Senhor da Cidade mantenha sua palavra!",
  ui_story_1022_10221200_58_dialog_content = "Bem, obrigado, mas não obrigado! Não tenho intenção de sobreviver, graças à tão chamada misericórdia do seu mestre.",
  ui_story_1022_10221200_59_dialog_content = "<color=#FFB400>Se eu não sou livre, prefiro estar morto!</color>",
  ui_story_1022_10221200_60_dialog_content = "<color=#e8d9bb>Sem um momento de hesitação, Pepita vira e salta da borda do penhasco.</color>",
  ui_story_1022_10221200_61_dialog_content = "Pepita!!!",
  ui_story_1022_10221200_62_dialog_content = "<color=#e8d9bb>Erica corre para a borda do abismo, mas não vê nenhum sinal de Pepita na névoa rodopiante abaixo.</color>",
  ui_story_1022_10221200_63_dialog_content = "...",
  ui_story_1022_10221200_64_dialog_content = "*Suspira* Mais uma pessoa que foi incapaz de apertar o botão.",
  ui_story_1022_10221200_65_dialog_content = "Essa é a segunda vez que faço a escolha errada. Parece que eu deveria refletir um pouco sobre mim mesmo.",
  ui_story_1022_10221200_66_dialog_content = "... Erica estava certo. Ela era uma criminosa, mas isso não significa que ela merecia morrer. Eu... Eu nunca tiraria a vida de uma pessoa por meus próprios motivos egoístas!",
  ui_story_1022_10221200_67_dialog_content = "Você... Quem diabos é você no mundo?",
  ui_story_1022_10221200_68_dialog_content = "Sua curiosidade supera sua ignorância, capitão. Todos na Divisão de Investigação de Hereges de Lumopolis são assim?",
  ui_story_1022_10221200_69_dialog_content = "Pepita não é mais da sua conta.",
  ui_story_1022_10221200_70_dialog_content = "Este assunto está agora nas mãos dos <color=#FFB400>Executores</color> da Illumina.",
  ui_story_1022_10221200_71_dialog_content = "<color=#e8d9bb>No fundo da Zona Escura, um poderoso raio de luz brilha antes da entrada de uma certa caverna.</color>",
  ui_story_1022_10221200_72_dialog_content = "O que aconteceu...? Quando eu... Espere. Fui enviado de volta?!",
  ui_story_1022_10221200_73_dialog_content = "Céus negros, frio amargo, Darkflow denso... E o Eclipse! Eu realmente voltei! Oh obrigado, muito obrigado...",
  ui_story_1022_10221200_74_dialog_content = "Pelo menos você tem a decência de agradecer ao nosso senhor por trazê-lo de volta, Figerald.",
  ui_story_1022_10221200_75_dialog_content = "...",
  ui_story_1022_10221200_76_dialog_content = "Ah ótimo, vocês também estão aqui.",
  ui_story_1022_10221200_77_dialog_content = "Isso mesmo, e você certamente nos fez esperar. Se você tivesse um pingo de talento, nosso tempo não teria sido tão desnecessariamente desperdiçado.",
  ui_story_1022_10221200_78_dialog_content = "Minhas, essas são algumas palavras dolorosas, Asmodeus. Eu fui o que avançou de cabeça na batalha pelo nosso senhor, mas o que você fez por ele?",
  ui_story_1022_10221200_79_dialog_content = "Porque eu invadiria a Cidade Gannon novamente sem pensar duas vezes, se isso é o que ele queria que eu fizesse.",
  ui_story_1022_10221200_80_dialog_content = "Então considere-se sortudo por ter pelo menos uma qualidade redentora, Figerald.",
  ui_story_1022_10221200_81_dialog_content = "... O que isso quer dizer?",
  ui_story_1022_10221200_82_dialog_content = "E o que ela está fazendo aqui de qualquer maneira? Esta é uma reunião dos Oito Fantasmas, então onde ela se encaixa?",
  ui_story_1022_10221200_83_dialog_content = "...",
  ui_story_1022_10221200_84_dialog_content = "Você quer dizer que não sabe? No Eclipse, existe apenas um único caminho de ascensão.",
  ui_story_1022_10221200_85_dialog_content = "Para alguém ascender, a pessoa acima dela deve primeiro desaparecer.",
  ui_story_1022_10221200_86_dialog_content = "Sempre houve oito Espectros no Eclipse. Não sete, não nove, mas oito.",
  ui_story_1022_10221200_87_dialog_content = "Qu-Que diabos você está falando? Apenas me diga por que Forsakin está aqui!",
  ui_story_1022_10221200_88_dialog_content = "Um general tolo não precisa de soldados astutos. As realizações de Forsakin superam em muito as suas.",
  ui_story_1022_10221200_89_dialog_content = "<color=#FFB400>Ascensão</color> é apenas uma recompensa adequada para seus esforços.",
  ui_story_1022_10221200_90_dialog_content = "!!!",
  ui_story_1022_10221200_91_dialog_content = "Qu-Que é isso?! Qual de vocês me amarrou assim?! Me soltem agora mesmo!!!",
  ui_story_1022_10221200_92_dialog_content = "... Eu não estou com vontade de ver o que acontece a seguir. Estou entrando.",
  ui_story_1022_10221200_93_dialog_content = "Hmph, eu também não tenho motivo para ficar para trás. Acabe logo com isso e entre, Forsakin. A reunião está prestes a começar.",
  ui_story_1022_10221200_94_dialog_content = "...",
  ui_story_1022_10221200_95_dialog_content = "...",
  ui_story_1022_10221200_96_dialog_content = "Ha... Hahahaha! Rasguem ela em pedaços, meus lacaios!",
  ui_story_1022_10221200_97_dialog_content = "Graaah!",
  ui_story_1022_10221200_98_dialog_content = "...",
  ui_story_1022_10221200_99_dialog_content = "Você ficou mais forte... Mas será que é forte o suficiente para isso? Você realmente tem a coragem para seguir em frente?",
  ui_story_1022_10221200_100_dialog_content = "Porque se você me comer agora, só significa que alguém vai te comer no futuro...",
  ui_story_1022_10221200_101_dialog_content = "O dia em que um Eclipsita mais forte e respeitado aparecer... Será o dia em que eles farão uma refeição de você.",
  ui_story_1022_10221200_102_dialog_content = "Você é corajoso o suficiente para ir tão longe? Porque não há volta uma vez que você faça isso.",
  ui_story_1022_10221200_103_dialog_content = "... No fundo do seu coração, você ainda acha que é um auroriano, não é?!",
  ui_story_1022_10221200_104_dialog_content = "...",
  ui_story_1022_10221200_105_dialog_content = "Você já terminou?",
  ui_story_1022_10221200_106_dialog_content = "... Eu não sinto mais os movimentos da Ursura.",
  ui_story_1022_10221200_107_dialog_content = "Eu vejo. Ela ainda provou ser útil no final. Graças a ela, conseguimos ver a técnica secreta daquela pessoa.",
  ui_story_1022_10221200_108_dialog_content = "O ato principal começa agora.",
  ui_story_1022_10221200_109_dialog_content = "... Ela está aqui.",
  ui_story_1022_10221200_110_dialog_content = "Hum?",
  ui_story_1022_10221200_111_dialog_content = "<color=#e8d9bb>Uma figura emerge das sombras, atraindo a atenção de todos.</color>",
  ui_story_1022_10221200_112_dialog_content = "...",
  ui_story_1022_10221200_113_dialog_content = "Heheh, como esperado do nosso talentoso novo membro... Acredito que você será muito mais do que Figerald jamais foi.",
  ui_story_1022_10221200_114_dialog_content = "Não, Asmodeus... É Ursura. Ela está aqui.",
  ui_story_1022_10221200_115_dialog_content = "...",
  ui_story_1022_10221200_116_dialog_content = "A <color=#FFB400>Substância X</color> foi extraída de seu ser, e seu coração e corpo foram praticamente obliterados... No entanto, ela ainda vive. E não só isso, mas ela está se recuperando lentamente.",
  ui_story_1022_10221200_117_dialog_content = "Será por causa de sua linhagem original? Sua essência já havia sido corrompida uma vez em uma impura <color=#FFB400>Substância N</color>.",
  ui_story_1022_10221200_118_dialog_content = "Mesmo que sua natureza imaterial tenha sido tirada, ela ainda sobreviveu.",
  ui_story_1022_10221200_119_dialog_content = "Desde que o ramo de coral que ela criou seja devolvido a ela, sua natureza imaterial... O poder de <color=#FFB400>X</color> também retornará a ela, e seu coração baterá mais uma vez.",
  ui_story_1022_10221200_120_dialog_content = "<color=#e8d9bb>Rangido, rangido, rangido!</color>",
  ui_story_1022_10221200_121_dialog_content = "Abaixe o volume, Petey. Eu só quero dormir um pouco mais...",
  ui_story_1022_10221200_122_dialog_content = "P-Petey?!",
  ui_story_1022_10221200_123_dialog_content = "Você é quem me resgatou? Mas por que fugiu? E a Ursura? Ela está... Ela não está morta, está?!",
  ui_story_1022_10221200_124_dialog_content = "A-Apenas se acalme, Pepita. Se Petey ainda está vivo, então isso significa que Ursura também deve estar. Mas se Petey está aqui agora, também significa que ela está em grandes apuros...",
  ui_story_1022_10221200_125_dialog_content = "... Espere, por que ainda estou preocupado com ela?!",
  ui_story_1022_10221200_126_dialog_content = "Ah, quem eu estou enganando? Encrenqueiros audaciosos como nós... Nós somos praticamente feitos um para o outro.",
  ui_story_1022_10221200_127_dialog_content = "<color=#e8d9bb>Por algum motivo, Petey se enrola na perna de Pepita e começa a guinchar freneticamente.</color>",
  ui_story_1022_10221200_128_dialog_content = "Sim, sim, eu sei que você está preocupado com seu mestre... Espera, você quer dizer que não está? Então o que você—Bwaaaaa!!!",
  ui_story_1022_10221200_129_dialog_content = "<color=#e8d9bb>Uma fenda no espaço se abre acima de Pepita, e um trem surge disparado dela a toda velocidade.</color>",
  ui_story_1022_10221200_130_dialog_content = "Um t-trem?!?",
  ui_story_1022_10221200_131_dialog_content = "A Zona Escura é um lugar frio e desolado. Um nobre condutor como eu nunca poderia abandonar um Auroriano solitário nesta terra congelada da morte.",
  ui_story_1022_10221200_132_dialog_content = "Bem, milady? Gostaria de subir a bordo do trem mais espetacular que existe?"
}
return config
